locales_quest = locales_quest or {}
locales_quest['frFR'] = {
  [1] = {
    'La quête de Kanrethad',
    {'Bon retour du monde des morts.|n|nIl y a bien longtemps, vous étiez $Gdroit et fier, un héros:droite et fière, une héroïne; parmi les vôtres. Aujourd\'hui, vous êtes $Gdéchu et brisé:déchue et brisée;, une relique du passé. Tenez-vous devant moi, pendant que j\'éveille la légende que vous étiez autrefois.|n|nJe vous rendrai les armes et les pouvoirs que vous avez perdus, et vous serez à nouveau $Gcomplet:complète;.', },
    {'Parlez à Kanrethad pour que vos talents, votre arme et votre monture vous soient rendus.', },
  },
  [2] = {
    'Griffe de Serres-tranchantes',
    {'Le grand hippogriffe Serres-tranchantes a été tué, et la griffe arrachée à son cadavre témoigne de votre victoire. Senani Cœur-de-tonnerre, au refuge de Vent-d\'Argent, sera sans doute intéressée de voir ce trophée qui est la preuve de votre exploit.', },
    {'Apportez la Griffe de Serres-tranchantes à Senani Cœur-de-tonnerre, au Refuge de Vent-d\'Argent.', },
  },
  [5] = {
    'L\'estomac qui gargouille',
    {'Je suis resté caché dans cette ville fantôme depuis des semaines.|n|nApportez-moi de quoi festoyer et je vous payerai généreusement.|n|nJ\'ai entendu parler d\'un certain chef Grual qui fait de succulentes tourtes au crabe de la Pénombre, à la taverne du Corbeau écarlate, à Sombre-Comté...', },
    {'Parlez au Chef Grual.', },
  },
  [6] = {
    'La prime pour Garrick Ladétrousse',
    {'Garrick Ladétrousse – un brigand qui harcèle les fermiers et les marchands de la région depuis des semaines – a été vu dans une cabane près des vignes qui se trouvent à l\'est de l\'abbaye, juste après le pont. Rapportez-moi la tête de ce mécréant, et vous empocherez la récompense !|n|nMais soyez $Gprudent:prudente; $N. Garrick a rassemblé une bande de voyous autour de lui. Il ne sera pas aisé de l\'approcher.', },
    {'Tuez Garrick Ladétrousse et rapportez sa tête à l\'Adjoint Willem de l\'Abbaye de Comté-du-Nord.', },
  },
  [7] = {
    nil,
    {'Votre premier travail est de faire un peu de nettoyage, $N. Un clan de kobolds a envahi les bois, au nord. Allez là-bas et attaquez ces vermines. Affaiblissez-les assez, pour qu\'un jour nous puissions les repousser hors de Comté-du-Nord.', },
    nil,
  },
  [8] = {
    'Un marché de voleur',
    {'Hé ! Voudriez-vous faire une faveur à un homme qui a eu plus que sa part de combats contre des zombies et des araignées ?|n|nJ\'ai ici une lettre qui doit être livrée à Brill... à une aubergiste du nom de Renée quelque chose. Enfin c\'est pas important son nom de famille.|n|nBref, c\'est un joli petit coin, plein de personnes victimes de la peste qui essayent de trouver leur voie en ce bas monde. De plus, c\'est un bon endroit pour se reposer. Vous devriez aller voir... D\'autant que je vous payerai bien.', },
    {'Livrez une Lettre à Renée, dans les Clairières de Tirisfal.', },
  },
  [9] = {
    'Les champs de mort',
    {'Regardez ce qu\'il s\'est passé ici ! Ces terres étaient autrefois habitées par de braves fermiers. Mais ces maudits voleurs les ont tous chassés. Pas moi, pour sûr ! Mais il semble que quelques Gardiens des moissons ont pris possession des champs.|n|nSi vous êtes d\'accord, j\'aimerais que vous y alliez et que vous en détruisiez une vingtaine. Revenez quand vous aurez fini pour recevoir votre dû. Une fois que vous aurez débarrassé ceux de mon champ, occupez-vous des champs alentours.', },
    {'Le Fermier Saldean vous a demandé de tuer 20 Gardiens des moissons.', },
  },
  [10] = {
    'La rédemption de Scrimshank',
    {'Oh, c\'est terrible ! J\'ai envoyé mon premier assistant, le géomètre novice Scrimshank, dans le désert au sud-est d\'ici. C\'est un endroit appelé le Gouffre béant. Et il est porté disparu. Dans son dernier rapport, il faisait allusion à ces étranges insectes près de là où il était. Serait-il possible qu\'ils aient maintenant infesté deux grandes régions du désert ?|n|nJ\'ai besoin que vous alliez retrouver Scrimshank dans le Gouffre béant ! Ou, au pire, que vous retrouviez son équipement topographique. Je crains que ce soit tout ce qu\'il reste de lui.', },
    {'Découvrez ce qu\'est devenu le Géomètre Scrimshank, et rapportez son Équipement topographique au Grand géomètre Radiésthéflop, à Gadgetzan.', },
  },
  [11] = {
    'Une prime pour les gnolls rivepatte',
    {'Des gnolls, des animaux brutaux qui n\'ont rien à faire ici, ont été aperçus à la lisière de la forêt d\'Elwynn. C\'est un très grand groupe, bien trop nombreux pour que nous nous en occupions seuls. Ils ont envahi les bois au sud de la tour de garde. Un autre groupe a envahi la région autour du lac du Cairn, à l\'est.|n|nL\'armée de Hurlevent engage quiconque pourrait en tuer. Apportez-moi des brassards peints de gnolls pour me prouver vos actions.', },
    {'Apportez 8 Brassards peints de gnoll à l\'Adjoint Rainer, à la Caserne.', },
  },
  [12] = {
    'Brigade de la marche de l\'Ouest',
    {'La milice du peuple n\'a qu\'un seul objectif : défendre la marche de l\'Ouest et ramener le calme dans les environs. Malheureusement, le prix de la paix est souvent le sang.|n|nUn de mes éclaireurs rapporte qu\'une bande de trappeurs défias sème le trouble dans le coin. Ils auraient été aperçus près de la mine Veine-de-Jango, au nord-ouest, ainsi que dans la ferme des Molsen et la ferme de potirons des Froncebouille. Si vous voulez rejoindre nos rangs, tuez quinze trappeurs défias et quinze contrebandiers défias, puis revenez me voir.', },
    {'Tuez 15 Trappeurs défias et 15 Contrebandiers défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des Sentinelles.', },
  },
  [13] = {
    'Brigade de la marche de l\'Ouest',
    {'Une bande de pilleurs défias a été vue en train de saccager la carrière de la Côte de l\'or ainsi que Ruisselune et la ferme des Alexston. La milice du peuple n\'acceptera pas ce genre de comportement. Déployez-vous immédiatement, $N, et faites en sorte que l\'on sache que la Lumière est présente dans la marche de l\'Ouest.|n|nLa carrière est près de la côte, à l\'ouest de la tour. Comme étape de votre instruction, je veux que vous tuiez quinze pilleurs défias et quinze pillards défias.', },
    {'Tuez 15 Pilleurs défias et 15 Pillards défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des Sentinelles.', },
  },
  [14] = {
    'Brigade de la marche de l\'Ouest',
    {'Quelques défias nous ont échappé. Mon éclaireur le plus fiable fait état de pillages défias dans les campagnes, au sud de la marche de l\'Ouest. Nous pensons qu\'ils se cachent dans les collines de la Dague, fomentant leur prochain coup. Détruisez ces misérables au nom de la milice du peuple.', },
    {'Tuez 15 Malandrins défias, 5 Éclaireurs défias et 5 Truands défias pour Gryan Roidemantel, puis retournez le voir sur la Colline des Sentinelles.', },
  },
  [15] = {
    '[PÉRIMÉ]Enquête sur la crête aux échos',
    {'$N, mes éclaireurs me rapportent que l\'infestation kobold est d\'une plus grande envergure que nous le pensions. Un groupe d\'ouvriers kobolds a établi son campement près de la mine de la Crête aux échos au nord.|n|nAllez à la mine et faites en sorte qu\'il n\'y en ait plus. Nous savons qu\'il y en a au moins huit. Tuez-les, voyez s\'il y en a davantage, et revenez me présenter votre rapport.', },
    {'Tuez 8 Ouvriers kobolds, puis revenez faire votre rapport au Maréchal McBride.', },
  },
  [16] = {
    'Procurer de l\'eau à Gerard',
    nil,
    nil,
  },
  [17] = {
    'Rechercher les composants à Uldaman',
    {'On a découvert récemment une nouvelle plante : les champignons magenta. Ils poussent en grappes au site de fouilles d\'Uldaman ; on les trouve dans les premiers tunnels et loin dans des zones moins explorées. Je veux étudier leur utilité éventuelle en alchimie, et c\'est là que vous entrez en scène.|n|nTrouvez les champignons magenta et rapportez-m\'en une douzaine. Attention, les grappes peuvent projeter des spores vénéneuses quand on les manipule !|n|nRendez-moi ce service et je sortirai pour vous un petit élixir revigorant de derrière les fagots.', },
    {'Apportez 12 Champignons magenta à Ghak Touchesoins, à Thelsamar.', },
  },
  [18] = {
    'La confrérie des voleurs',
    {'Un groupe de voleurs traîne depuis peu autour de Comté-du-Nord. Ils se nomment eux-mêmes la Confrérie défias, et ont été aperçus de l\'autre côté de la rivière à l\'est.|n|nJe ne sais pas ce qu\'ils préparent, mais il est certain que ce n\'est rien de bon ! Apportez-moi les masques qu\'ils portent, et je vous récompenserai d\'une arme.', },
    {'Apportez 8 Masques rouges à l\'Adjoint Willem, à l\'extérieur de l\'Abbaye de Comté-du-Nord.', },
  },
  [19] = {
    nil,
    {'Les renégats et les estafettes Rochenoire tendent des embuscades entre ici et le donjon de Guet-de-pierre. Le chef des estafettes est un orc du nom de Tharil\'zun – nous voulons qu\'il meure. Rapportez-moi la tête de Tharil\'zun !', },
    {'Apportez la Tête de Tharil\'zun au maréchal Marris, dans les Carmines.', },
  },
  [20] = {
    'La menace des Rochenoires',
    {'Les orcs rochenoires ont voyagé depuis les steppes Ardentes et ont pris possession du donjon de Guet-de-pierre, depuis le nord. De cette base, ils patrouillent dans toutes les zones au nord de Comté-du-Lac et forcent les citoyens à rester en ville, parqués comme du bétail.|n|nAidez à libérer Comté-du-Lac de cette oppression. Tuez ces orcs rochenoires et rapportez-moi dix haches détériorées comme preuve de votre réussite.|n|nBien que les orcs rochenoires nous menacent au nord, nous avons des informations disant qu\'il y aurait aussi des orcs au sud-est des Carmines. Si vous en trouvez là-bas, tuez-les.', },
    {'Rapportez 10 Haches détériorées au Maréchal Marris, à Comté-du-Lac.', },
  },
  [21] = {
    '[PÉRIMÉ]Règlement de comptes à Écho-Coron',
    {'Vos dernières investigations ont prouvé que la mine de la Crête aux échos devait être nettoyée. Retournez-y et chassez les kobolds.|n|nNe perdez pas de temps, $N. Plus les kobolds seront tranquilles dans la mine, plus ils renforceront leurs positions à Comté-du-Nord.', },
    {'Tuez 8 Travailleurs kobolds, puis revenez voir le Maréchal McBride, à l\'Abbaye de Comté-du-Nord.', },
  },
  [22] = {
    'Tourte au foie de broche-tripes',
    {'Les oignons sont pelés et l\'ail émincé. Le romarin est pilé. La pâte est cuite et le fenouil haché. La sauce finit de mijoter. Il ne me manque que huit foies de broche-tripes pour réussir ma fameuse tourte à la viande !', },
    {'Salma Saldean a besoin de 8 Foies de broche-tripes pour faire une Tourte au foie de broche-tripes.', },
  },
  [23] = {
    'Patte d\'Ursangous',
    {'Le puissant ours Ursangous n\'est plus !|n|nLe petit emblème en forme de croissant de lune sur sa patte indique que cette bête avait été dressée par les elfes de la nuit pour traquer leurs ennemis dans la forêt. Impossible de dire combien de vos alliés de la Horde ont été tués par cette créature.|n|nVous devriez apporter cette patte à Tarkan au refuge de Vent-d\'Argent. Il sera heureux de voir qu\'une arme pareille a été retirée de l\'arsenal ennemi.', },
    {'Apportez la Patte d\'Ursangous au Capitaine Tarkan au Refuge de Vent-d\'Argent.', },
  },
  [24] = {
    'Tête de Shadumbra',
    {'Shadumbra, autrefois si rapide, gît immobile maintenant que vous l\'avez vaincu.|n|nCette créature légendaire est chère aux elfes de la nuit. Sa tête devrait servir de trophée pour les intimider et représenter la fin de l\'Alliance en Orneval.|n|nLe capitaine Goggath au guet de Hurlenfer sera sans aucun doute ravi de recevoir la tête de ce sabre-de-nuit.', },
    {'Apportez la Tête de Shadumbra au Capitaine Goggath au Guet de Hurlenfer.', },
  },
  [25] = {
    'Y a du gaz dans l\'eau',
    nil,
    nil,
  },
  [26] = {
    'Une leçon à apprendre',
    {'$N, j\'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir $Gun véritable gardien et protecteur:une véritable gardienne et protectrice; de la nature.|n|nLe temps est venu pour vous d\'en apprendre plus à propos de l\'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l\'eau. Pour cela, vous devez voyager jusqu\'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Brasétoile, du Cercle cénarien. Il vous guidera plus avant.', },
    {'Parlez à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune.', },
  },
  [27] = {
    'Une leçon à apprendre',
    {'$N, j\'ai suivi votre progression avec beaucoup de plaisir. Vous êtes assurément en train de devenir $Gun véritable gardien et protecteur:une véritable gardienne et protectrice; de la nature.|n|nLe temps est venu pour vous d\'en apprendre plus à propos de l\'une des nombreuses formes animales que nous pouvons revêtir et dont nous gratifie Cénarius. Un aspect qui vous permettra de maîtriser l\'eau. Pour cela, vous devez voyager jusqu\'au village de Havrenuit, à Reflet-de-Lune, et parler à Dendrite Brasétoile, du Cercle cénarien. Il vous guidera plus avant.', },
    {'Parlez à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune.', },
  },
  [28] = {
    'L\'épreuve du lac',
    {'Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Élune\'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l\'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l\'un des gardiens les plus fiables de Reflet-de-Lune.|n|nVous devez réussir cette quête avant l\'expiration du temps imparti, et vous serez peut-être en concurrence avec d\'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.|n|nBonne chance, $N.', },
    {'Trouvez un Colifichet du sanctuaire dans le Lac Élune\'ara, et apportez-le au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utilisez le Colifichet du sanctuaire.|n|nVous devez parler à Tajarri, au sanctuaire, afin de terminer l\'épreuve.', },
  },
  [29] = {
    'L\'épreuve du lac',
    {'Pour la première épreuve, vous devrez aller fouiller les profondeurs du lac Élune\'ara, et trouver un Colifichet du sanctuaire. Attention, il se corrompt rapidement ; aussi, ne tardez pas à l\'apporter au sanctuaire de Remulos. Utilisez le Colifichet sur le sanctuaire puis parlez à Tajarri ; elle est l\'un des gardiens les plus fiables de Reflet-de-Lune.|n|nVous devez réussir cette quête avant l\'expiration du temps imparti, et vous serez peut-être en concurrence avec d\'autres druides, également à la recherche de colifichets. Il vous faudra user de ruse et de dextérité pour réussir dans cette mission.|n|nBonne chance, $N.', },
    {'Trouvez un Colifichet du sanctuaire dans le Lac Élune\'ara, et apportez-le au sanctuaire de Remulos, au nord-ouest de Reflet-de-Lune. Une fois sur place, utilisez le Colifichet du sanctuaire.|n|nVous devez parler à Tajarri, au sanctuaire, afin de terminer l\'épreuve.', },
  },
  [30] = {
    'L\'épreuve du lion de mer',
    {'Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L\'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L\'autre moitié emprunte à l\'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.|n|nAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Brasétoile.', },
    {'Trouvez le Demi-pendentif d\'agilité aquatique et le Demi-pendentif d\'endurance aquatique. Parlez aux habitants de Reflet-de-Lune pour obtenir des indices quant à l\'endroit où ces objets se trouvent.|n|nReformez le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.|n|nApportez le Pendentif reformé à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune.', },
  },
  [31] = {
    'Forme aquatique (druide elfe de la nuit)',
    {'Vous avez terminé les leçons nécessaires, enseignées à tous les jeunes druides avant qu\'ils ne puissent adopter un aspect aquatique. Retournez voir votre Maître, Turak Totem-runique, aux Pitons-du-Tonnerre. Présentez-lui votre pendentif et montrez-lui que vous êtes en mesure d\'apprendre ce qu\'il est prêt à vous enseigner. Il veillera à parachever votre entraînement, vous permettant de revêtir une forme aquatique.|n|nAu revoir, jeune druide. Nous nous reparlerons plus tard.', },
    {'Retournez aux Pitons-du-Tonnerre et montrez le Pendentif du lion de mer à Turak Totem-Runique.', },
  },
  [32] = {
    'L\'ascension des silithides',
    {'Voici votre rapport. Je vous demande de l\'apporter de toute urgence à quelqu\'un qui a de l\'expérience dans ce domaine.|n|nJe connais un troll érudit du nom de Zilzibin Kongadok. Il a passé beaucoup de temps à étudier les formes de vie exceptionnelles de l\'écologie d\'Azeroth ; de plus, c\'est un historien ! Si vous voulez rencontrer quelqu\'un capable de comprendre la nature de ce danger et comment l\'arrêter, apportez-lui ce rapport. Nous allons avoir besoin de toute l\'aide disponible.|n|nZil réside dans une maison sur le niveau supérieur de la Herse, à Orgrimmar.', },
    {'Apportez le Rapport à Zilzibin Kongadok, à Orgrimmar.', },
  },
  [33] = {
    '[PÉRIMÉ]Les loups derrière la frontière',
    {'Ce qui affecte ces loups n\'est pas prêt de disparaître. Chaque jour, on voit davantage de loups malades. L\'idée de demander à quelqu\'un de tuer des animaux innocents me déplaît profondément, mais nous devons abattre les jeunes loups malades avant que cela ne tourne à l\'épidémie.|n|nTuez des jeunes loups malades dans la vallée, et ramenez-moi leurs peaux comme preuve de vos exploits.', },
    {'Apportez 8 Peaux de loup malade à Eagan Tannepeau, à l\'extérieur de l\'Abbaye de Comté-du-Nord.', },
  },
  [34] = {
    'Un invité indésirable',
    {'Mes jardins ont encore été saccagés. Et je connais le responsable. C\'est ce satané sanglier, celui que le maréchal Marris appelle Fouailleventre.|n|nJe ne vais pas pouvoir replanter mes jonquilles avant la prochaine saison maintenant. Ruinée ! Je suis complètement ruinée à cause de ce sanglier ! Mettez un terme à cette nuisance ! Montrez-moi ses défenses et je serai heureuse de vous récompenser. Il semble qu\'il passe son temps dans les champs au sud-ouest de Comté-du-Lac, mais il vagabonde de temps en temps jusque dans mon jardin.', },
    {'Martie Jainrose de Comté-du-Lac vous a demandé de tuer Fouailleventre. Rapportez-lui ses défenses comme preuve.', },
  },
  [35] = {
    'Inquiétudes supplémentaires',
    {'Si vous voulez savoir si les rumeurs concernant les murlocs sont vraies, allez donc au pont, à l\'est d\'Elwynn, et parlez au garde Thomas. Il y est en poste depuis une semaine, il saura de quoi il retourne.|n|nJ\'ai là un destrier de Hurlevent qui vous conduira jusqu\'au garde Thomas. Vous n\'avez qu\'à me dire si vous êtes $Gprêt:prête; à l\'utiliser.', },
    {'Le Maréchal Dughan vous a demandé de parler au Garde Thomas.', },
  },
  [36] = {
    'Ragoût de la marche de l\'Ouest',
    {'Je n\'avais jamais pensé un jour quitter ma ferme. Mais les champs grouillent de voleurs, et cela devient vraiment trop dangereux pour nous. Dès que la charrette du fermier Froncebouille sera réparée, nous partirons. |n|nVous pourriez peut-être me faire une faveur ? Laissez-moi écrire la recette du ragoût de la marche de l\'Ouest. S\'il vous plaît, apportez-la à Salma Saldean à la ferme de l\'autre côté, là-bas. La ferme des Saldean est un peu plus loin sur la route, juste après l\'embranchement.', },
    {'Verna Froncebouille vous a demandé d\'apporter la Recette du ragoût de la marche de l\'Ouest à Salma Saldean.', },
  },
  [37] = {
    'Trouver les gardes disparus',
    {'Il y a quelques jours, j\'ai envoyé deux gardes, Rolf et Malakai, patrouiller le long de la rivière, et ils ne sont toujours pas revenus. Afin de finaliser mon rapport, je dois absolument savoir ce qu\'il est advenu de ces hommes.|n|nAllez vers le nord, le long de la rivière, et trouvez les gardes... ou ce qu\'il en reste.', },
    {'Le Garde Thomas vous a demandé d\'aller au nord, le long de la rivière, à la recherche de deux gardes disparus, Rolf et Malakai.', },
  },
  [38] = {
    'Ragoût de la marche de l\'Ouest',
    {'Aidez-moi à faire du ragoût de la marche de l\'Ouest. Rapportez-moi les ingrédients suivants : |n|n3 morceaux de viande filandreuse de vautour ;|n3 groins de broche-tripes ;|n3 yeux de murloc ;|n3 okras.', },
    {'Salma Saldean vous a demandé 3 morceaux de Viande filandreuse de vautour, 3 Groins de broche-tripes, 3 Yeux de murloc et 3 Okras.', },
  },
  [39] = {
    'Remettre le rapport de Thomas',
    {'Allez annoncer au maréchal Dughan la mort de Malakai et de Rolf, et prévenez-le que les murlocs à l\'est d\'Elwynn ne pourront pas être contenus par les troupes présentes actuellement.|n|nJe sais que nous n\'avons pas beaucoup de troupes disponibles, mais Dughan trouvera une solution.', },
    {'Avertissez le Maréchal Dughan de Comté-de-l\'Or.', },
  },
  [40] = {
    'Péril en la rivière',
    {'$N, il y a une nouvelle menace dans la forêt d\'Elwynn ! Les murlocs remontent le cours est de l\'Elwynn, effrayant les poissons et attaquant des personnes innocentes !|n|nJ\'ai averti le maréchal Dughan, mais il est plus préoccupé par les gnolls et les bandits. Il n\'est pas convaincu que les murlocs représentent un réel danger.|n|nS\'il vous plaît, $N, parlez à Dughan et persuadez-le d\'envoyer des renforts à l\'est !', },
    {'Remy « Deux fois » veut que vous parliez au Maréchal Dughan à Comté-de-l\'Or.', },
  },
  [45] = {
    'La destinée de Rolf',
    {'En fouillant un peu plus dans la zone, vous tombez sur des traces de pas palmés qui mènent vers l\'est, le long de la rive du lac du Cairn. Légèrement plus loin, vous apercevez un village murloc.|n|nPeut-être que le destin de Rolf s\'est arrêté ici...', },
    {'Fouillez le village des murlocs pour trouver Rolf ou des traces de sa mort.', },
  },
  [46] = {
    'Des primes pour les murlocs',
    {'L\'armée de Hurlevent a mis à prix la tête des rôdeurs et des fourrageurs murlocs qui se trouvent en Elwynn. Tuez-les, découpez leurs ailerons et rapportez-les au garde Thomas, l\'armée de Hurlevent vous récompensera.|n|nLes murlocs ont construit un village au lac du Cairn au nord d\'ici, et un autre au sud, là où la rivière se sépare.', },
    {'Rapportez 8 Ailerons de murloc au Garde Thomas au pont, à l\'est d\'Elwynn.', },
  },
  [47] = {
    'L\'échange de poussière d\'or',
    {'Par ici les kobolds transportent quelquefois de la poussière d\'or sur eux. Cela peut m\'être très utile : rapportez-m\'en beaucoup et je vous en donnerai le meilleur prix de la ville ! Le meilleur prix de la ville !|n|nVous trouverez des kobolds dans la mine de Fondugouffre, au sud, et autour de la mine Veine-de-jaspe au nord-est.', },
    {'Rapportez 10 Poussières d\'or à Remy « Deux fois » à Comté-de-l\'Or. La Poussière d\'or se récupère sur les kobolds dans la Forêt d\'Elwynn.', },
  },
  [48] = {
    'Doux whisky',
    {'Dans la campagne du Sud, là où la vigne pousse, en rampant et se tordant|nSe cache un puits où l\'eau coule profondément|nAussi pure que la Sœur sacrée de la Lumière, elle est|nApportez-moi un peu de cette eau sacrée.', },
    {'Rapportez de l\'Eau de source sacrée à Tristevin Tonnebière.', },
  },
  [49] = {
    'Doux whisky',
    {'Le whisky, de ma vie est le plus ancien amour|nComme les étoiles qui durent pour toujours|nRapportez-moi, pour que mon amour revienne majestueux tel un aigle|nUn sac de chacune de ces céréales : orge, maïs et seigle.', },
    {'Tristevin Tonnebière vous a demandé un Sac d\'orge, un Sac de seigle et un Sac de maïs.', },
  },
  [50] = {
    'Doux whisky',
    {'Je mélangerai et mélangerai, jusqu\'à de la pulpe obtenir|nPour que ce soit notre petit cache sans faiblir|nEn métal solide, il faut que cela soit fait|nPour me permettre de finir cette chanson, du vrai-argent il faut me rapporter.', },
    {'Tristevin Tonnebière vous a demandé du Vrai-argent.', },
  },
  [51] = {
    'Doux whisky',
    {'Pas encore filtré, mais déjà distillé|nComme une terre inconnue attendant d\'être trouvée|nPuis pour faire un tas de charbon il faut être actif|nLivrez-moi une branche de sycomore, ceci est votre objectif.', },
    {'Apportez une Branche de sycomore à Tristevin Tonnebière.', },
  },
  [52] = {
    'Protéger la frontière',
    {'Salutations, $N. Les animaux sauvages deviennent de plus en plus agressifs à mesure que l\'on s\'éloigne de Comté-de-l\'Or, et le camp de bûcherons du Val d\'Est subit de perpétuelles attaques de la part de loups et d\'ours !|n|nNous pourrions avoir besoin de votre aide.', },
    {'Tuez 8 Rôdeurs ou Loups forestiers gris et 5 Jeunes ours des forêts, puis retournez voir le Garde Thomas au pont, à l\'est d\'Elwynn.', },
  },
  [53] = {
    'Doux whisky',
    {'Fluide suave et clair, comme des larmes d\'enfant|nQui une belle teinte ambrée acquiert avec le temps|nAvant que nous puissions te boire à satiété|nUn fût de chêne noirci il nous faut fabriquer.', },
    {'Apportez un Fagot de chêne noirci à Tristevin Tonnebière.', },
  },
  [54] = {
    'Rapport pour Comté-de-l\'Or',
    {'$N, vous êtes $Gun:une:c; $C indubitablement $Gimpliqué:impliquée:c; dans la sûreté de Comté-du-Nord. Vous avez maintenant en charge la protection de la zone entourant la forêt d\'Elwynn.|n|nSi vous acceptez cette responsabilité, j\'ai préparé tous les documents qui doivent être apportés au maréchal Dughan à Comté-de-l\'Or. Comté-de-l\'Or se situe le long de la route sud, au-delà de la frontière.', },
    {'Apportez les Documents du maréchal McBride au Maréchal Dughan à Comté-de-l\'Or, dans la Forêt d\'Elwynn.', },
  },
  [55] = {
    'Morbent Lagangrène',
    {'Morbent Lagangrène se cache dans son repaire, la maison perchée sur la colline, à l\'est. C\'est celle qui domine le cimetière de la Colline-aux-Corbeaux. Son temps sur cette terre touche à sa fin...|n|nUtilisez le Fléau de Morbent contre lui. Il réduira à néant ses magies protectrices.|n|nTuez-le ! Tuez-le et libérez-nous de sa cruauté ! Soyez le bras armé de ma vengeance et $Gle héros:l\'héroïne; du bois de la Pénombre !', },
    {'Utilisez le Fléau de Morbent sur Morbent Lagangrène, tuez-le, puis rapportez le Fléau de Morbent à Sven, dans son camp.', },
  },
  [56] = {
    'Les Veilleurs',
    {'En tant que commandant des Veilleurs, et de par mon serment, il est de mon devoir de protéger les citoyens de Sombre-Comté. Hurlevent a rappelé les gardes qui étaient en faction ici, nous laissant nous débrouiller par nous-mêmes.|n|nCe serait un acte noble de votre part si vous nous aidiez, car nous en avons terriblement besoin ! Aidez les Veilleurs. Aventurez-vous dans les Jardins paisibles, juste au sud de Sombre-Comté, et tuez 8 guerriers squelettes, ainsi que 6 mages squelettes. Les morts-vivants doivent être contrecarrés !', },
    {'Le Commandant Althea Bouclenoire de Sombre-Comté vous a demandé de tuer 8 Guerriers squelettes et 6 Mages squelettes.', },
  },
  [57] = {
    'Les Veilleurs',
    {'$N, on vient juste de me rapporter que la forêt était envahie de morts-vivants ! Si vous êtes d\'accord pour le faire, voyagez jusqu\'au cimetière de Colline-aux-Corbeaux et tuez 15 de ces infâmes démons squelettes et 15 squelettes infernaux. Mes informateurs me disent que des squelettes ont aussi été repérés au sud de Sombre-Comté, autour et dans le cimetière des Jardins paisibles. Les morts-vivants doivent être repoussés hors du bois de la Pénombre !', },
    {'Le commandant de Sombre-Comté, Althea Bouclenoire, vous a demandé de tuer 15 Démons squelettes et 15 Squelettes infernaux.', },
  },
  [58] = {
    'Les Veilleurs',
    {'La situation reste préoccupante à Colline-aux-Corbeaux. La sûreté de Sombre-Comté est entre vos mains, $N. Je n\'ai pas assez de Veilleurs pour protéger la ville. Nous avons encore besoin de vous. Allez à Colline-aux-Corbeaux pour débarrasser le mausolée est de 20 répandeurs de peste !', },
    {'Le Commandant de Sombre-Comté, Althea Bouclenoire, vous a demandé de tuer 20 Répandeurs de peste dans le mausolée est de Colline-aux-Corbeaux.', },
  },
  [59] = {
    'Les armures de cuir et d\'étoffe',
    {'Pour récompenser votre perspicacité et votre bravoure, j\'ai ici un bon pour une pièce d\'armure. Allez trouver Sara Timberlain, au camp de bûcherons du Val d\'Est. Donnez-lui ce bon et elle vous fabriquera une armure. Une fois que vous l\'aurez, $N, utilisez-la pour défendre Elwynn.|n|nLe camp de bûcherons du Val d\'Est est juste à l\'est de ce poste, de l\'autre côté du pont.', },
    {'Donnez le Bon pour une pièce d\'armure de Hurlevent à Sara Timberlain.', },
  },
  [60] = {
    'Les bougies de kobolds',
    {'Bonjour, $Gcher monsieur:ma dame; ! Auriez-vous une seconde ?|n|nMon frère et moi sommes apothicaires à Hurlevent, et je suis ici pour acheter des grandes bougies, afin d\'utiliser leur cire. Pourriez-vous m\'aider ?|n|nLes kobolds produisent ces grandes bougies, et j\'ai entendu dire qu\'ils infesteraient les mines d\'Elwynn... La mine de Fondugouffre au sud et celle de Veine-de-jaspe à l\'est. Je vous suggère d\'aller me chercher ces bougies là où elles se trouvent.', },
    {'Rapportez 8 Grandes bougies à William Pilon de Comté-de-l\'Or.', },
  },
  [61] = {
    'Une cargaison pour Hurlevent',
    {'Mon frère Morgan attend ma cargaison de bougies à Hurlevent. Je n\'ai pas le temps de faire le voyage moi-même, mais si vous livrez la cargaison à ma place, il vous paiera bien.|n|nJ\'ai empaqueté les bougies, et vous pouvez trouver Morgan à notre magasin, les Apothicaires Pilon, dans le quartier commerçant de Hurlevent.', },
    {'Livrez la Cargaison de William à Morgan Pilon dans le Quartier commerçant de Hurlevent.', },
  },
  [62] = {
    'La mine de Fondugouffre',
    {'Comté-du-Nord n\'est pas le seul endroit à avoir des problèmes avec ses mines ! J\'ai des rapports disant que la mine de Fondugouffre à Elwynn est aussi infestée de kobolds.|n|nAllez explorer la mine afin de confirmer ces rapports, puis revenez me voir. Elle se situe au sud de Comté-de-l\'Or, entre les propriétés des Champierreux et des Maclure.', },
    {'Explorez la Mine de Fondugouffre, puis revenez voir le Maréchal Dughan de Comté-de-l\'Or.', },
  },
  [63] = {
    'L\'appel de l\'eau',
    {'Le long de la côte de la forêt des Pins-Argentés, à l\'ouest du Sépulcre, vous trouverez un autel qui a été corrompu. Les esprits n\'y parlent plus aux gens. Vous devez résoudre le problème en purifiant l\'autel.|n|nPrenez ces bracelets élémentaires et la potion de Brine, placez-les sur le brasero de l\'autel. Ce rituel devrait suffire à invoquer un esprit pur à qui vous pourrez parler.|n|nRapportez-moi une preuve de votre réussite, et je vous récompenserai avec un totem.', },
    {'Abattez la Manifestation d\'eau corrompue et placez les Bracelets de manifestation corrompue avec le reste d\'eau pure sur le brasero de la Fontaine éternelle, dans la forêt des Pins-Argentés.', },
  },
  [64] = {
    'Le cadeau oublié',
    {'C\'était horrible ! Verna m\'a réveillé quand elle a entendu du grabuge dans les champs. Ils étaient envahis par des vandales. Nous nous sommes enfuis à toutes jambes, du coup j\'ai oublié ma montre sur place. Le père de Verna me l\'avait offerte pour notre mariage et je suis malade de savoir qu\'elle est entre les mains de ces voleurs. J\'ai laissé ma montre dans la penderie à la ferme. Cherchez le champ de citrouilles à l\'ouest – vous ne pouvez pas le manquer. Si vous me la rapportez, je saurai me montrer reconnaissant !', },
    {'Le Fermier Froncebouille vous a demandé de retrouver sa Montre, qui se trouve dans la penderie de sa ferme près du champ de citrouilles, à l\'ouest.', },
  },
  [65] = {
    'La Confrérie défias',
    {'La bande de misérables, responsable de la fuite des honnêtes gens de la marche de l\'Ouest, se fait appeler la Confrérie défias. J\'ai besoin de vous pour infiltrer ces voyous. Nous devons connaître l\'identité de leur chef et où ils sont basés. À Comté-du-Lac, il y a un voleur nommé Wiley à l\'auberge qui me doit une faveur.|n|nAllez jusqu\'à Comté-du-Lac dans les Carmines, à l\'est d\'Elwynn, et trouvez ce que vous pouvez.', },
    {'Gryan Roidemantel vous a demandé de parler à Wiley à Comté-du-Lac.', },
  },
  [66] = {
    'La légende de Stalvan',
    {'La nuit dernière, j\'ai eu un mauvais pressentiment concernant ma petite-fille Alyssa. Elle serait en grand danger. J\'ai tiré les cartes et la lame de la Faucheuse est sortie.|n|nAprès une longue et sombre transe, j\'ai obtenu un indice. Un nom est apparu : Stalvan.|n|nAllez voir un greffier de la mairie et trouvez plus de détails sur ce personnage. J\'ai peur pour tout le monde…', },
    {'Allez voir le Greffier Daltry, à l\'hôtel de ville de Sombre-Comté.', },
  },
  [67] = {
    '[PÉRIMÉ]La légende de Stalvan',
    {'Stalvan, hein ? Laissez-moi vérifier dans les registres de la ville.|n|nStalvan. Stalvan…Voyons voir. Ah ! Nous y voilà. J\'ai la trace d\'un certain M. Stalvan Mantebrume. Sa dernière adresse connue est l\'école de Ruisselune. Enfin, mon registre date un peu !|n|nFaites-moi une faveur, si vous allez à Ruisselune, renseignez-vous sur cette personne. Que je puisse mettre à jour mon registre.', },
    {'Allez à l\'école de Ruisselune, et rapportez au Greffier Daltry des informations récentes sur Stalvan.', },
  },
  [68] = {
    'La légende de Stalvan',
    {'Vous trouvez une lettre poussiéreuse dans la vieille caisse.', },
    {'Rapportez la Lettre poussiéreuse au greffier Daltry.', },
  },
  [69] = {
    '[PÉRIMÉ]La légende de Stalvan',
    {'Oh non ! J\'ai dû manquer ça la première fois. Dans le registre, juste en dessous de l\'adresse notée pour Stalvan, il y en a une autre partiellement effacée. Il semble qu\'il s\'agisse de l\'auberge de la Fierté du lion à Comté-de-l\'Or. J\'aimerais vérifier cela, $N.', },
    {'Allez à l\'Auberge de la Fierté du lion pour voir si quelqu\'un a entendu parler de Stalvan.', },
  },
  [70] = {
    'La légende de Stalvan',
    {'Oui, effectivement, je me rappelle de Stalvan !|n|nIl y a quelques années, lors d\'une nuit d\'orage, un messager est venu, à la recherche d\'un abri pour la nuit. Vers minuit, l\'homme a dévalé les escaliers en hurlant, le visage terrifié. Il était toujours en pyjama quand il a disparu en courant sous la pluie torrentielle.|n|nDans sa précipitation, il a oublié ses lettres dans le coffre à l\'étage. Il n\'est jamais revenu. Une des lettres était adressée au quartier du Canal à Hurlevent. Prenez-la si vous le voulez.', },
    {'Retrouvez la Vieille lettre de Stalvan dans le coffre, et remettez-la au quartier du Canal, à Hurlevent.', },
  },
  [71] = {
    'Faire son rapport au garde Thomas',
    {'Maintenant que vous avez les deux médaillons, apportez-les au Garde Thomas au Pont est, il saura peut-être comment ces hommes ont été assassinés.', },
    {'Rapporter les Médaillons de Rolf et Malakai au garde Thomas au pont est d\'Elwynn.', },
  },
  [72] = {
    'La légende de Stalvan',
    {'Mon père fut le gardien de cette propriété bien avant que je ne le sois. Il a dû tout nettoyer après le massacre.|n|nLes derniers fonds des Silecrête ont fondu comme neige au soleil. Le reste des affaires de la famille va partir aux enchères. La faute à ces vautours des impôts. J\'imagine que vous êtes $Gimpatient:impatiente; de voir ce qu\'il y a, vous pouvez regarder dans le tas de vieilleries. Si ça se trouve, quelque chose vous intéressera.', },
    {'Recherchez un indice dans le tas d\'affaires.', },
  },
  [74] = {
    'La légende de Stalvan',
    {'Vous trouvez dans la caisse diverses choses : quelques objets moisis, un portrait de famille, des trophées de chasse et de vieux livres. Dans le fond, sous un vase en céramique, vous découvrez une page de journal déchirée.', },
    {'La Page de journal déchirée que vous avez découverte est votre deuxième indice.', },
  },
  [75] = {
    'La légende de Stalvan',
    {'Quand j\'ai emménagé ici, il y avait une liasse de lettres dans le coffre, en haut. Je les ai examinées en arrivant, mais j\'ai abandonné quand mes yeux ont commencé à perdre de leur acuité.|n|nRendez service à un vieil aveugle, et allez voir dans le coffre, à l\'étage. Vous y trouverez peut-être quelque chose qui vous en apprendra plus sur ce Stalvan. Je suis pratiquement sûr qu\'il y a une page de journal décolorée qui peut être très intéressante. Rapportez-la-moi et je vous aiderai de mon mieux.', },
    {'Le Maréchal Haggard vous a demandé d\'aller chercher la Page de journal décolorée dans le coffre, à l\'étage.', },
  },
  [76] = {
    'La mine Veine-de-jaspe',
    {'Merci, nous savons désormais que la mine de Fondugouffre est infestée de kobolds. Nous avons besoin maintenant d\'un éclaireur pour explorer la mine la plus éloignée, celle de Veine-de-jaspe.|n|nExplorez-la et confirmez la présence de kobolds. Pour parvenir à la mine, allez vers l\'est le long de la route, jusqu\'à la tour d\'Azora. De là prenez vers le nord et vous tomberez sur la mine dans les collines.', },
    {'Explorez la Mine Veine-de-jaspe, puis faites votre rapport au Maréchal Dughan de Comté-de-l\'Or.', },
  },
  [77] = {
    'Une situation délicate',
    {'Je possède l\'emballage d\'origine nécessaire pour conditionner la Houle que Dran Droffers recherche. Je vais vous aider à l\'emballer pour le père de Malton, à l\'humeur si caustique… contre deux bouteilles de la susnommée Houle. Les bouteilles se trouvent dans une caisse, dans une base abandonnée de la Horde, près du rocher de l\'Affût.|n|nLa tâche sera ardue : d\'immondes gelées et même des limons infestent les ruines. On dit que ces créatures seraient commandées par une sorte de limon en chef. Quoi qu\'il en soit, procurez-vous la Houle et revenez me voir ici pour la conditionner.', },
    {'Récupérez 10 bouteilles de Houle au miel des Hinterlands dans des caisses se trouvant aux environs de la base abandonnée de la Horde, au rocher de l\'Affût.', },
  },
  [78] = {
    'La légende de Stalvan',
    {'Je connais quelqu\'un qui pourra peut-être vous aider. Quand je commandais les gardes de Hurlevent, nous avions l\'habitude d\'aller boire un coup à la taverne du Corbeau écarlate, à Sombre-Comté. L\'aubergiste, Smitts, connaît nombre d\'histoires sur la région. Montrez-lui cette page, et voyez ce qu\'il vous dira.', },
    {'Prenez la Page de journal décolorée et montrez-la à Smitts l\'aubergiste à Sombre-Comté, au Bois de la Pénombre.', },
  },
  [79] = {
    'La légende de Stalvan',
    {'Je m\'intéresse à l\'histoire de ce personnage, Stalvan, depuis des années. Le jour où ces nobles de passage furent massacrés, il y a quelques années, je suis venu avec Haggard pour enquêter. J\'ai trouvé ces pages boueuses, mais je n\'ai jamais pu faire le lien avec l\'écriture de cet homme fou dans les bois. Ce que vous m\'apportez là, prouve de toute évidence qu\'il est coupable. Portez immédiatement cela au commandant Bouclenoire et racontez-lui ce que vous avez découvert !', },
    {'Portez les pages au Commandant Bouclenoire.', },
  },
  [80] = {
    'La légende de Stalvan',
    {'J\'avais déjà l\'œil sur ce sale type, Stalvan. Mais si les écritures concordent, alors cela prouve sans l\'ombre d\'un doute qu\'il est coupable.|n|nAvec toutes ces journées à tenir le registre de la ville, le Greffier Daltry est devenu un expert dans l\'identification des écritures. Montrez-lui ces pages pour vérifier si les écritures concordent avec la signature présente sur le registre.', },
    {'Montrez au Greffier Daltry la Page de journal maculée de sang.', },
  },
  [81] = {
    'La livraison de Houle',
    {'J\'ai pris la peine de mettre à l\'abri dans le tonneau, en plus de la houle emballée de Dran, les bouteilles supplémentaires qu\'il veut faucher pour son propre compte. Je n\'aime pas beaucoup Dran, mais il n\'y a rien de pire que de la houle éventée. Ne vous donnez pas la peine de me remercier.|n|nAllez maintenant livrer le baril à Dran Droffers, à sa boutique d\'Orgrimmar. Et passez le bonjour à Malton ! Dites-lui que s\'il cherche d\'excellentes boissons et de sympathiques compagnons de beuverie, nous serions honorés de recevoir sa visite.', },
    {'Livrez le tonneau à Dran Droffers, à Orgrimmar.', },
  },
  [82] = {
    'Enquête au Repaire nuisible',
    {'Très bien, maintenant ces rapports à propos des insectes... Ce que nous savons, c\'est qu\'ils drainent l\'eau du réservoir qui se trouvait à l\'emplacement du Repaire nuisible. Ce que nous ne savons PAS... Tout le reste.|n|nEssayons tout d\'abord de savoir qui est notre ennemi ! Je veux que vous alliez au Repaire nuisible et rameniez des bouts de ces bestioles. Récupérez cinq morceaux de ces Centipaars et portez-les à l\'alchimiste Pilonzugg pour qu\'il voie de quoi il retourne. Avec lui sur l\'affaire, nous le saurons vite !', },
    {'Apportez cinq morceaux de Centipaars du Repaire nuisible à l\'Alchimiste Pilonzugg, à Gadgetzan.', },
  },
  [83] = {
    'Articles en lin de qualité',
    nil,
    nil,
  },
  [84] = {
    'Revenir voir Billy',
    {'Voilà. Quand vous donnerez cette tourte à Billy, dites-lui de s\'étouffer avec !', },
    {'Apportez la Tourte de panse de porc à Billy Maclure, aux Vignes des Maclure.', },
  },
  [85] = {
    'Le collier perdu',
    {'J\'ai perdu mon collier, et je pense que c\'est ce garnement de Billy Maclure qui l\'a pris ! Généralement, il vagabonde dans les Vignes des Maclure, à l\'est d\'ici.|n|nRapportez-moi mon collier, et vous réchaufferez le cœur d\'une pauvre veuve.', },
    {'Parlez à Billy Maclure.', },
  },
  [86] = {
    'Une tourte pour Billy',
    {'Si je mangeais une tourte, je pourrais peut-être vous dire qui a ce collier. Vous savez, je pense que cette vieille dame du nom de Bernice, dans l\'autre ferme, fait de formidables tourtes de panse de porc...|n|nSi vous lui apportiez quelques morceaux de viande tendre d\'un des sangliers qui traînent autour de notre ferme, et si vous lui expliquiez toute l\'histoire, alors elle vous préparerait une tourte.', },
    {'Apportez 4 morceaux de Viande de sanglier tendre à Tatie Bernice Champierreux, à la ferme des Champierreux.', },
  },
  [87] = {
    'Dent-d\'or',
    {'Je jouais près de la mine de Fondugouffre, et je pense que j\'ai fait tomb... Euuuuh... Je veux dire que j\'ai vu le collier de la vieille dame. Ne me demandez pas comment il est arrivé là... Ce n\'est pas moi qui l\'ai pris !|n|nQuoi qu\'il en soit, j\'ai vu cet énorme kobold avec une dent en or le prendre et s\'enfuir vers sa tanière au-dessus de la mine. Allez là-bas, trouvez le kobold et vous trouverez le collier, c\'est juré !', },
    {'Rapportez le Collier de Bernice à « Tatie » Bernice Champierreux à la Ferme des Champierreux.', },
  },
  [88] = {
    'Princesse doit mourir !',
    {'Les Saumepuits ont un cochon appelé Princesse qui a gagné des tas de prix. C\'est une ÉNORME truie qui s\'est engraissée sur mon dos en venant chaparder des légumes dans mon potager !|n|nElle y est en ce moment même ! Princesse doit mourir ! Rapportez-moi son collier pour preuve de son exécution, et je vous récompenserai pour votre travail !|n|nVous trouverez Princesse plantée au beau milieu de notre carré de pastèques. Allez l\'égorger !', },
    {'Tuez Princesse, prenez son collier puis rapportez-le à Maman Champierreux, à la Ferme des Champierreux.', },
  },
  [89] = {
    'Le pont sur le lac',
    {'Lors de la dernière invasion des orcs, nous avons été obligés de fondre tout notre fer pour fabriquer des balles, des armures et des épées. Nous avons envoyé une demande de ravitaillement à Hurlevent, mais une bande de gnolls des Carmines a détourné la caravane puis s\'est enfuie dans les collines au-delà de Comté-du-Lac.|n|nNous allons bientôt être à court de matériel pour reconstruire ce pont. Si vous pouviez me rapporter 5 clous en fer et 5 rivets en fer, $N, je ferais en sorte que l\'on vous récompense.|n|nAllez, au travail !', },
    {'Apportez 5 Clous en fer et 5 Rivets en fer au Contremaître Oslow, à Comté-du-Lac.', },
  },
  [90] = {
    'Kébab de loup assaisonné',
    {'La spécialité de la maison est le kébab de loup assaisonné. Bien sûr, je peux vous en faire ! Mais j\'ai besoin de différents ingrédients. Apportez-moi 10 Steaks de loup ainsi qu\'un peu d\'Herbes aromatiques de Hurlevent. Il y a tellement de loups dans la forêt que cela ne devrait pas être un problème pour trouver la viande. Pour ce qui est des herbes, allez donc voir Felicia Gump, la fleuriste du quartier du canal à Hurlevent.', },
    {'Récupérez 10 Steaks de loup et des Herbes aromatiques de Hurlevent, puis retournez voir le chef Grual à Sombre-Comté.', },
  },
  [91] = {
    'La loi de Salomon',
    {'Un ennemi de Hurlevent s\'est installé dans les collines à l\'est des Carmines. D\'infâmes voleurs utilisent les Arcanes pour répandre la terreur et la misère sur notre ville et ses habitants. Derrière cela, il y a une personne, Morganth ; c\'est lui qui dirige cette entreprise maléfique.|n|nMorganth contrôle maintenant le clan des gnolls Sombrepoil, qu\'il utilise pour ses exactions. De par la loi de Comté-du-Lac, aider un ennemi du royaume est passible de la peine de mort.|n|nCes infâmes gnolls doivent être tués !|n|nRapportez-moi 10 pendentifs sombrepoil, et vous serez $Grécompensé:récompensée;.', },
    {'Apportez 10 Pendentifs sombrepoil au Bailli Conacher, à l\'Hôtel de ville de Comté-du-Lac.', },
  },
  [92] = {
    'Goulash des Carmines',
    {'Rien ne me ferait plus plaisir que de vous faire du goulash des Carmines. Mais il y a un petit problème. Lors de la dernière attaque des orcs, j\'ai dû nourrir la totalité des troupes de Hurlevent. Mon garde-manger est complètement vide. Mais si vous me rapportez les ingrédients, je me ferai un plaisir de vous en préparer.|n|nIl me faut seulement 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d\'araignée.', },
    {'Le chef Breanna de Comté-du-Lac vous a demandé 5 morceaux de Viande de condor coriace, 5 Groins de grands Broche-tripes et 5 portions de Chair croustillante d\'araignée.', },
  },
  [93] = {
    'Tourte au crabe de la Pénombre',
    {'Je vais vous confier un petit secret : ma tourte au « crabe » de la Pénombre est en réalité fait de pattes d\'araignée ! C\'est vrai que cela semble un peu répugnant, mais leur goût est merveilleux ! Apportez-moi des pattes d\'araignées fondantes et je vous en préparerai quelques-uns.|n|nVous en trouverez sur les araignées Tisse-venin qui nichent au nord, entre les collines et la rivière.', },
    {'Récupérez 6 Pattes d\'araignée fondantes et apportez-les au chef Grual de Sombre-Comté.', },
  },
  [94] = {
    'L\'œil attentif',
    {'Mon adversaire, Morganth, est un puissant mage vicieux qui vit dans la Tour d\'Ilgalar dans les Carmines. J\'ai élaboré un moyen pour l\'espionner, l\'Œil d\'Azora, et je peux maintenant l\'observer de loin.|n|nMais pour connaître ses pensées, j\'ai besoin d\'assistance.|n|nSi vous le voulez, portez mon Glyphe d\'Azora à la Tour d\'Ilgalar. Placez-le sur la Statue de lion près de la tour.|n|nLorsque cela sera fait, j\'aurai une vision des plans futurs de Morganth.', },
    {'Placez le Glyphe d\'Azora sur la Statue de lion, près de la Tour d\'Ilgalar dans les Carmines.', },
  },
  [95] = {
    'La vengeance de Sven',
    {'Je travaillais dans une ferme, au sud-est... Des cavaliers noirs du défilé de Deuillevent sont venus dans ma ferme et ont massacré toute ma famille alors que j\'étais absent !|n|nQuand je suis rentré, j\'ai vu une silhouette indistincte rôder près de ma grange, en train d\'enterrer quelque chose. Il s\'est enfui avant que j\'aie pu l\'attraper, et je n\'ai pas pu m\'attarder, car je suis parti aussitôt à sa poursuite. Du coup, je n\'ai pas vu ce qu\'il avait caché.|n|nSi vous pouviez découvrir ce qu\'a enterré le cavalier noir, je vous en serais reconnaissant. L\'endroit exact est derrière la vieille souche d\'arbre près de la grange.', },
    {'Allez à la ferme de Sven et trouvez ce qui a été enterré derrière la vieille souche d\'arbre.', },
  },
  [96] = {
    'L\'appel de l\'eau',
    {'Prendre l\'éclat. Prendre l\'éclat et donner la vie.|n|nDonner la vie et comprendre. Comprendre que l\'eau, c\'est la vie... La corruption détruit la vie.|n|nLe pouvoir de l\'eau protège et donne la vie.', },
    {'Apportez l\'Éclat d\'eau à Islen Oeil-des-rivières à l\'Escalier des marées, dans les Tarides.', },
  },
  [97] = {
    '[PÉRIMÉ]La légende de Stalvan',
    {'Prévenez immédiatement le commandant Bouclenoire que les écritures concordent, $N ! Ses soupçons étaient fondés !', },
    {'Prévenez le commandant Bouclenoire.', },
  },
  [98] = {
    'La légende de Stalvan',
    {'Stalvan Mantebrume est un dépravé. De nombreuses victimes ont perdu la vie entre ses mains. Il est sans aucun doute coupable d\'un nombre incalculable de crimes et de méfaits. Et maintenant ce dément menace Sombre-Comté. Seule la Lumière sait quels actes abjects il prépare. Allez jusqu\'à sa chaumière au nord de la ville, $C, et exécutez Stalvan.|n|nLorsque ce sera fait, allez voir Madame Eva et montrez-lui son anneau familial. Après tout, c\'est elle qui a eu la prémonition qui nous a conduits jusqu\'à cette terrible découverte. Mais Sombre-Comté est désormais plus sûre grâce à elle.', },
    {'Tuez Stalvan Mantebrume, et montrez son anneau familial à Madame Eva.', },
  },
  [99] = {
    'La folie d\'Arugal',
    {'Mon mépris pour ce malheureux fou d\'Arugal augmente à mesure que je déchiffre son enchantement. J\'ai presque fini mes recherches pour y parvenir.|n|nMa compréhension sera totale quand j\'aurai compris ce qui cause l\'étrange comportement des habitants de Bois-du-Bûcher. Le jour, les paysans sont des gens normaux. Mais la nuit venue ils se transforment en worgens Ragelune.|n|nJe dois puiser l\'énergie des chaînes qu\'a enchantées Arugal. Rapportez-moi six chaînes enchantées de Bois-du-Bûcher, $N.', },
    {'Rapportez 6 Chaînes enchantées de Bois-du-Bûcher à Dalar Tisselaube, au Sépulcre.', },
  },
  [100] = {
    'L\'appel de l\'eau',
    {'À la fin de votre incantation, une explosion lumineuse se produit. Le grésillement des gouttes dans les flammes s\'est arrêté, et vos sens reviennent à mesure que les esprits corrompus autour de vous sont détruits.', },
    {'Parlez à la Manifestation d\'eau inférieure sur la Côte nord, dans la forêt des Pins-Argentés.', },
  },
  [101] = {
    'Le Totem d\'affliction',
    {'À mesure que la corruption mystique rampe à travers la forêt, la nécessité d\'une protection devient indispensable, $N. Les vents m\'ont murmuré qu\'un grand danger vous guette dans un avenir proche.|n|nSi vous voulez vous garder de ce danger, noble $C, apportez-moi 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d\'araignée. J\'enchanterai alors un Totem d\'affliction qui blessera ceux qui tenteront de vous agresser.', },
    {'Apportez 10 Crocs de goule, 10 Doigts de Squelette et 5 Fioles de venin d\'araignée à Madame Eva, à Sombre-Comté.', },
  },
  [102] = {
    'Une patrouille dans la marche de l\'Ouest',
    {'Hurlevent nous a abandonnés. Un vent de corruption souffle sur la marche de l\'Ouest. C\'est ma terre natale et je n\'abandonnerai pas les gens qui ont choisi de rester ici. Nous, les anciens fermiers, nous résisterons.|n|nVotre mission, si vous l\'acceptez, sera de patrouiller dans les prairies de la marche. Débusquez et tuez les infâmes gnolls qui apparemment sont de connivence avec les voleurs des Mortemines. Apportez-moi 8 Pattes de gnolls et je vous récompenserai pour votre courage.', },
    {'Rapportez 8 Pattes de gnolls au capitaine Danuvin, à la Colline des Sentinelles.', },
  },
  [103] = {
    'Le gardien de la flamme',
    {'Je me souviens de cette terrible nuit, au cours de laquelle la famille du gardien de phare a été tuée. J\'ai contemplé, impuissant, l\'attaque du Vieux Troubloeil. Mais bon, ce qui est fait est fait. Ma préoccupation maintenant est la sécurité des marins et des navires qui croisent sur la Grande mer, car la zone est très dangereuse près des récifs le long de la côte. Vu qu\'il n\'y a plus personne pour s\'occuper du phare, la tâche m\'incombe à présent de surveiller sa flamme.|n|nAidez-moi à garder la flamme allumée, apportez-moi 5 flacons d\'huile provenant des monstres des moissons.', },
    {'Apportez 5 Flacons d\'huile au Capitaine Grayson, au Phare de l\'Ouest.', },
  },
  [104] = {
    'Menace sur la côte',
    {'Quand ma vie a pris fin sur ces rochers, je ne savais pas que je pouvais espérer quelque chose après la mort. Cette nuit-là, le phare était éteint parce que le Vieux Troubloeil avait fait fuir la famille qui s\'en occupait. Mais les gens sont revenus et ont rallumé la flamme. Alors le Vieux Troubloeil a contraint ces faibles d\'esprit de murlocs à attaquer le phare. Cette fois-ci, la famille n\'a pas eu le temps de fuir, et elle a été massacrée par ces ignobles créatures, sans que personne ne puisse intervenir.|n|nTuez le Vieux Troubloeil si vous le rencontrez le long de la plage, et rapportez-moi une de ses écailles, je vous récompenserai.', },
    {'Rapportez une Ecaille du Vieux Troubloeil au Capitaine Grayson, au Phare de l\'Ouest.', },
  },
  [105] = {
    'Hélas, Andorhal',
    {'Hélas, le temps est venu d\'attaquer Andorhal et d\'en finir avec la liche qui la contrôle !|n|nAraj l\'Invocateur, la liche, règne sur les ruines de la cité. Il est gardé par de nombreuses créatures du Fléau qui encerclent les restes du centre de la ville, et sa garde personnelle, qui lui est directement attachée, est redoutable. Vous aurez besoin de plusieurs alliés pour avoir la moindre chance de le vaincre.|n|nExécutez Araj, $N, et apportez-moi un éclat de son phylactère comme preuve !', },
    {'Apportez l\'Éclat phylactère d\'Araj au Grand exécuteur Derrington à la Barricade, dans les Maleterres de l\'Ouest.', },
  },
  [106] = {
    'Jeunes amoureux',
    {'Je suis maudite ! Mon cœur appartient à Tommy Joe Champierreux, mais nos familles sont ennemies. Du coup, je ne peux pas le voir, et pourtant je languis d\'admirer son magnifique visage !|n|nS\'il vous plaît, portez-lui cette lettre de ma part. Généralement, il va à la rivière à l\'ouest de la ferme des Champierreux, qui se trouve à l\'ouest d\'ici.', },
    {'Donnez la Lettre d\'amour de Maybell à Tommy Joe Champierreux.', },
  },
  [107] = {
    'Note pour William',
    {'Je suis sûre que William Pilon a une potion qui permettrait de réunir ces deux amoureux !|n|nTenez, prenez cette note et portez-la à William. Il habite à l\'auberge de la Fierté du lion à Comté-de-l\'Or.', },
    {'Portez la Note de Mamie Champierreux à William Pilon.', },
  },
  [108] = {
    '<TXT> Récompense mystère',
    nil,
    nil,
  },
  [109] = {
    'Aller voir Gryan Roidemantel',
    {'J\'ai l\'impression que vous êtes $Grompu:rompue; au combat, $C. Si vous ne l\'avez pas déjà fait, vous devriez aller voir Gryan Roidemantel. Il dirige la milice du peuple, dont le but est de défendre les fermes de la marche de l\'Ouest. Je suis sûr qu\'il aurait besoin de vous. Il se trouve généralement dans la tour de pierre sur la colline des Sentinelles, près de la route au centre de la marche de l\'Ouest.', },
    {'Parlez à Gryan Roidemantel. Il se trouve dans la tour de pierre sur la Colline des Sentinelles, près de la route au centre de la marche de l\'Ouest.', },
  },
  [110] = {
    'Analyse des morceaux d\'insectes',
    {'Je vais passer un peu de temps à examiner l\'équipement d\'analyse de Scrimshank... et remettre de l\'ordre dans ses effets personnels. J\'ai le sentiment que ces insectes vont nous faire subir bien d\'autres pertes.|n|nPourriez-vous aller voir si l\'alchimiste Pilonzugg a analysé les morceaux d\'insectes que nous lui avons envoyés ? S\'ils sont prêts, rapportez-les-moi.', },
    {'Aller voir à Gadgetzan si l\'Alchimiste Pilonzugg a terminé d\'analyser les morceaux d\'insectes.', },
  },
  [111] = {
    'Discuter avec Mamie',
    {'S\'il vous plaît, $N, allez parler à Mamie. Si quelqu\'un peut trouver une solution à notre problème, c\'est bien elle.|n|nElle habite dans notre ferme à l\'est d\'ici.', },
    {'Parlez à Mamie Champierreux.', },
  },
  [112] = {
    'À la recherche du varech',
    {'Je peux préparer une potion d\'invisibilité pour Maybell, qui lui permettra de s\'échapper du vignoble des Maclure et de rejoindre Tommy Joe. Mais pour préparer cette potion, j\'ai besoin de varech cristallin.|n|nCette plante pousse habituellement dans l\'océan, mais parfois les murlocs en récoltent. Il faut aller voir si les murlocs près du lac de Cristal n\'en auraient pas en ce moment. Le lac de Cristal est à l\'est de Comté-de-l\'Or.', },
    {'Apportez 4 Feuilles de Varech cristallin à William Pilon de Comté-de-l\'Or.', },
  },
  [113] = {
    'Analyse des morceaux d\'insectes',
    {'Le grand géomètre Radiésthéflop doit être informé immédiatement. En fait... toute personne sachant lire doit voir ce rapport. Nous sommes confrontés à une menace très sérieuse et très grave non seulement pour Tanaris et Gadgetzan, mais si on ne s\'en occupe pas, pour tout le Sud de Kalimdor. Oups, et même pour tout Azeroth ; cette menace n\'a donné aucun signe de déclin.|n|nDemandez à Radiésthéflop de faire des copies du rapport pour que vous le distribuiez le plus largement possible. Tout le monde doit être informé de cette menace !', },
    {'Apportez le rapport au Grand géomètre Radiésthéflop à Gadgetzan. Obtenez une copie de ce rapport, comme l\'alchimiste Pilonzugg vous l\'a demandé.', },
  },
  [114] = {
    'La fuite',
    {'Prenez cette potion d\'invisibilité pour la jeune Maybell. Les effets devraient être suffisamment longs pour qu\'elle puisse rendre visite à Tommy Joe.', },
    {'Apportez la Potion d\'invisibilité à Maybell Maclure.', },
  },
  [115] = {
    'Magie des Ténèbres',
    {'Les orcs rochenoires ont engagé des exhalombres pour les aider dans leurs attaques contre les Carmines ; ils ont emporté des orbes de minuit. Ces orbes ont infligé de graves dégâts aux défenses des Carmines et il est impératif que nous ne soyons plus confrontés à leur puissance.|n|nRetrouvez et rapportez-moi les orbes de minuit, après avoir tué les exhalombres rochenoires qui les possèdent. Je détruirai ces orbes ; le monde ne se portera que mieux sans eux !', },
    {'Apportez 3 Orbes de minuit au Maréchal Marris, à Comté-du-Lac.', },
  },
  [116] = {
    'Régime sec',
    {'Je suis dans une situation désespérée, $N. Mes réserves sont presque à sec. La dernière cargaison de boisson aurait dû arriver il y a bien longtemps. L\'invasion des orcs a été un enfer.|n|nPeut-être pouvez-vous travailler pour moi ?|n|nJ\'ai besoin que vous récupériez un tonneau de Tonnebière de chez Tristevin Tonnebière dans les collines de la marche de l\'Ouest, un tonneau de merlot de Hurlevent, une bouteille de tord-boyaux de Sombre-Comté et une outre de rhum doux de Comté-de-l\'Or. Rapportez-les-moi et je ferai en sorte que vous soyez $Grécompensé:récompensée;.', },
    {'Le tavernier Daniels de Comté-du-Lac a besoin d\'un Tonneau de Tonnebière, d\'un Tonneau de merlot, d\'une Bouteille de tord-boyaux et d\'une Outre de rhum doux.', },
  },
  [117] = {
    'Hymne à la Tonnebière',
    {'Allez donc, $Gmon ami:mon amie;, sans tarder hâtez-vous !|nPour que notre breuvage, fidèle à mes dosages,|nTienne plus de la bière que d\'un mauvais ragoût,|nIl me manque du houblon pour en faire le brassage.', },
    {'Apportez 5 Pieds de Houblon à Tristevin Tonnebière pour qu\'il prépare son breuvage spécial.', },
  },
  [118] = {
    'Le prix des fers',
    {'J\'ai utilisé tellement de métal pour équiper les gardes de Hurlevent que je n\'en ai même plus pour ferrer les chevaux !|n|nApportez cette note à Argus le forgeron de Comté-de-l\'Or. Elle explique mon problème et lui demande une livraison de fers à cheval.', },
    {'Apportez la Note de Verner à Argus le forgeron à Comté-de-l\'Or, dans la Forêt d\'Elwynn.', },
  },
  [119] = {
    'Le retour chez Verner',
    {'D\'accord, je lui envoie 50 fers à cheval…|n|nLes voilà, tout empaquetés et prêts à emporter ! Dites à Verner que c\'est un plaisir de faire affaire, et faites en sorte qu\'il trouve la facture accrochée à la caisse !', },
    {'Retournez chez Verner Bongoulot, à Comté-du-Lac, dans les Carmines, et donnez-lui la caisse de Fers à cheval.', },
  },
  [120] = {
    'Un message pour Hurlevent',
    {'Nous vivons un moment crucial, $C. Le bourg est assiégé. Sans renforts, nous allons succomber. Le rapport dont je vous charge est de la plus haute importance. Remettez-le au général Marcus Jonathan de Hurlevent le plus rapidement possible. Dès que vous le lui aurez remis, revenez avec sa réponse, qu\'elle soit bonne ou mauvaise.|n|nMaintenant hâtez-vous !', },
    {'Le magistrat Salomon vous a remis un rapport qui doit être transmis au général Marcus Jonathan de Hurlevent. Il exige que vous reveniez vers lui aussitôt que vous aurez donné le message.', },
  },
  [121] = {
    'Un message pour Hurlevent',
    {'Pendant que j\'attends la réponse du roi, je veux que vous portiez cette lettre au magistrat Salomon.|n|nRompez, $C !', },
    {'Apportez la réponse du Général Marcus Jonathan au Magistrat Salomon, à Comté-du-Lac.', },
  },
  [122] = {
    'Les écailles de dragonnet',
    {'J\'ai besoin d\'écailles ventrales de dragonnet noir pour payer les fers qu\'Argus m\'a envoyés de Comté-de-l\'Or. Si vous pouviez m\'en trouver six, je réglerais ma dette... et il m\'en resterait suffisamment pour vous façonner quelque chose.|n|nLes dragonnets noirs errent souvent au sud de Comté-du-Lac, mais ils aiment aussi se balader. Vous devrez vous embusquer et les chasser quand vous les verrez.', },
    {'Rassemblez 6 Ecailles ventrales de dragonnet noir et apportez-les à Verner Bongoulot, dans les Carmines.', },
  },
  [123] = {
    'Le collecteur',
    {'Cette note est un tableau des heures et des jours auxquels une personne – décrite comme le « Collecteur » – doit recevoir une livraison d\'or en provenance des mines de la forêt d\'Elwynn.|n|nD\'après le tableau, il semblerait que le Collecteur habite près du champ de potirons des Saumepuits, à l\'est d\'Elwynn.|n|nC\'est une information importante. Vous devriez en faire part au maréchal McCree au camp de bûcherons du Val d\'Est.', },
    {'Allez voir le Maréchal McCree, au Camp de bûcherons du Val d\'Est, et donnez-lui le Plan de route du Collecteur.', },
  },
  [124] = {
    'Le hurlement des gnolls',
    {'Comme si les attaques des orcs ne suffisaient pas ! Maintenant j\'ai des brutes et des mystiques gnolls qui rôdent au nord de mon écurie et qui massacrent mes chevaux dès qu\'ils s\'éloignent...|n|nSi vous pouviez nous débarrasser de ces gnolls, mes chevaux et moi vous en serions très reconnaissants.', },
    {'Tuez 10 Brutes des Carmines et 8 Mystiques des Carmines, puis retournez chez Verner Bongoulot.', },
  },
  [125] = {
    'Les outils perdus',
    {'J\'apprécierais vraiment votre aide, $N. La ville est assiégée, l\'approvisionnement devient difficile. On devait me livrer des outils par chariot depuis Comté-de-l\'Or, mais le pont a sauté. Nous avons alors mis les outils dans un bateau, mais les orcs l\'ont touché avec une catapulte. Évidemment, ma boîte d\'outils a coulé tout droit au fond du lac.|n|nRécupérez-la, $N, et je ferai en sorte que vous ne le regrettiez pas.', },
    {'Le contremaître Oslow de Comté-du-Lac veut que vous récupériez sa Boîte d\'outils au fond du Lac Placide.', },
  },
  [126] = {
    'Les collines aux hurlements',
    {'$N, les gnolls sont toujours là. Je peux entendre leurs hurlements quand ils chassent dans les collines de Comté-du-Lac. Et l\'un d\'eux hurle plus fort que les autres : Couineur, leur chef.|n|nTuez Couineur et dispersez sa meute ! Rapportez-moi sa patte comme preuve.|n|nMais faites attention ! Ce gnoll n\'est pas leur chef pour rien ! Ce n\'est pas un bâtard !', },
    {'Apportez la patte de Couineur à Verner Bongoulot, à Comté-du-Lac.', },
  },
  [127] = {
    'Criée aux poissons',
    {'Le lac Placide est connu pour son poisson-lune. C\'est un poisson qui se vend bien et j\'ai justement besoin d\'argent !|n|nRapportez-m\'en 10 ; je paierai bien. Si vous ne savez pas pêcher, peut-être pourrez-vous en voler aux murlocs !', },
    {'Rapportez 10 Poissons-lunes au Chef des docks Baren, à Comté-du-Lac.', },
  },
  [128] = {
    'La prime rochenoire',
    {'Le clan Rochenoire doit être démantelé. L\'ennemi a envahi nos terres. Ces montagnes sont cependant sous le règne souverain du roi de Hurlevent. Nos sources nous indiquent que les chefs de chaque unité du clan sont appelés des champions. Vous les trouverez dans leur campement au nord, juste à l\'ouest de la route menant aux steppes Ardentes.|n|nLe magistrat Salomon veut que ces brutes abjectes soient tuées. Tuez quinze champions rochenoires et revenez me voir.', },
    {'Tuez 15 Champions rochenoires et le garde Howe de Comté-du-Lac vous récompensera.', },
  },
  [129] = {
    'Un repas gratuit',
    {'Vous pouvez me faire une faveur ? J\'ai préparé un déjeuner pour le garde Parker, mais il est en patrouille... C\'est un homme grand et fort, un garde de Hurlevent, qui peut se défendre, mais pour une citadine comme moi, c\'est beaucoup trop dangereux dehors.|n|nSi vous lui apportez ce repas à ma place, revenez me voir, je vous offre un déjeuner gratuit ! Parker patrouille le long de la route qui mène au bois de la Pénombre.', },
    {'Apportez son déjeuner au Garde Parker. Il patrouille sur la route qui mène au Sombre-Comté.', },
  },
  [130] = {
    'Une visite chez l\'herboriste',
    {'Puisque vous retournez voir Darcy, pouvez-vous lui apporter des fleurs de ma part ? Vous en trouverez chez l\'herboriste, quand vous serez de retour à Comté-du-Lac, à l\'extrémité ouest de la ville.|n|nMais quand vous prendrez les fleurs, ne dites pas à l\'herboriste, Martie, qui les achète, ni pour qui elles sont...', },
    {'Parlez à Martie Jainrose, l\'Herboriste des Carmines.', },
  },
  [131] = {
    'Bouquet de jonquilles',
    {'Voilà votre bouquet. J\'ai choisi des jonquilles pour vous. Ce sont mes fleurs préférées !', },
    {'Donnez à Darcy le bouquet de jonquilles.', },
  },
  [132] = {
    'La Confrérie défias',
    {'Ce que je vais vous dire peut me coûter la vie. Le gang défias est en train de préparer un gros coup. Il paraît qu\'ils se sont acoquinés avec des gnolls, des kobolds et même des gobelins.|n|nApportez ce message à Roidemantel. Il donne tous les détails de ce que je sais à ce sujet.', },
    {'Apportez la Note de Wiley à Gryan Roidemantel, dans la marche de l\'Ouest.', },
  },
  [133] = {
    'L\'épouvantail à goules',
    {'Je vis tellement loin de la sûreté de la ville que c\'est un miracle que les morts-vivants ne m\'aient pas dévoré ! En fait, juste hier, un groupe de Mâcheurs est venu rôder près de ma maison !|n|nPour les éloigner, je voudrais faire une sorte d\'« épouvantail » à goules. Il me faut des côtes de goules. On peut se les procurer sur les Dévoreurs, les Mâcheurs, les Mangeurs de cervelle, les Pourris et les Répandeurs de peste.|n|nTrouvez-moi des côtes et je vous donnerais une récompense.', },
    {'Trouvez 7 Côtes de goule. Apportez-les à Abercrombie dans sa cabane.', },
  },
  [134] = {
    'Les ogres voleurs',
    {'Il y a quelques semaines, je cueillais des herbes assez loin de chez moi et j\'ai été attaqué par une bande d\'ogres ! Je me suis enfui, en laissant derrière moi une caisse pleine d\'herbes et de précieux outils.|n|nLes ogres m\'ont pourchassé un moment, puis ils sont retournés à leur tertre, au sud du bois de la Pénombre. Je suis sûr que ma caisse est là-bas, pas très loin du tertre des ogres.|n|nJe vous en prie, $N, récupérez cette caisse pour moi. Elle me fait gravement défaut.', },
    {'Rapporter sa caisse à Abercrombie.', },
  },
  [135] = {
    'La Confrérie défias',
    {'Je me demande de quoi parlait Wiley quand il a mentionné les Maçons. C\'était peut-être un lapsus ? Les Défias pourraient-ils être reliés aux Maçons ? Le seul qui pourrait le savoir à coup sûr, c\'est Mathias Shaw, le chef du SI:7. Montrez-lui la note de Wiley et voyez s\'il a quelque chose à tirer de ce mystère qui s\'épaissit. Si vous avez du mal à trouver Shaw, cherchez du côté de la caserne de la Vieille ville.', },
    {'Apporter la Note de Wiley à Mathias Shaw à Hurlevent.', },
  },
  [136] = {
    'Le trésor caché du capitaine Sanders',
    {'Si vous lisez ceci, c\'est que le vieux capitaine Sanders repose sous six pieds de flotte. Mon trésor est à vous. Il vous suffit de suivre le jeu de piste.|n|nD\'abord, trouvez mon coffre. Il doit être à moitié enterré dans le sable, depuis le temps, sur la côte de la marche de l\'Ouest, à côté de l\'épave. Il y a des tas d\'épaves sur la côte, mais une seule ancre rouillée. Qui trouve cette ancre trouve mon coffre ! Et avec le coffre, l\'indice suivant !', },
    {'Trouvez le Coffre du capitaine Sanders. Fouillez-le pour trouver l\'indice suivant.', },
  },
  [137] = {
    '<NYI> <TXT> Hurlevent Commendation',
    {'Seulement si vous obtenez une recommandation de l\'un des maréchaux et que vous me l\'apportez. Cela sera du meilleur effet sur nos gants frappés d\'un lion.', },
    {'Le général Marcus Jonathan de Hurlevent acceptera une recommandation de la forêt d\'Elwynn. Si vous lui apportez un tel document, vous pourrez choisir une armure.', },
  },
  [138] = {
    'Le trésor caché du capitaine Sanders',
    {'L\'indice que vous trouvez est le suivant : « Bon travail, matelot ! Maintenant il va falloir cingler vers l\'est. À l\'est, vers le haut des falaises, à l\'est vers la route. Cherchez les ruines des vieilles cheminées, au bord de la route. Là, vous trouverez un vieux tonneau qui contient l\'indice suivant. »', },
    {'Trouvez le Tonneau à côté des cheminées en ruine. Fouillez-le pour trouver l\'indice suivant.', },
  },
  [139] = {
    'Le trésor caché du capitaine Sanders',
    {'En fouillant le tonneau, vous découvrez un autre parchemin. Il y est écrit : « À partir de ce tonneau, dirigez-vous vers le nord. Marchez droit comme une bande de cadets qui va au réfectoire, jusqu\'à ce que vous voyiez la cruche vide, à côté de l\'éolienne solitaire, sur les falaises. Si vous farfouillez autour de cette cruche, vous pourrez bien trouver ce que vous cherchez. »', },
    {'Cherchez la Cruche vide à côté de l\'éolienne pour trouver le prochain indice.', },
  },
  [140] = {
    'Le trésor caché du capitaine Sanders',
    {'Bien vu ! Il y a un autre indice au fond de la cruche. L\'encre a coulé par endroits et le papier sent le whisky, mais vous arrivez à reconstituer une partie du texte. « Maintenant que vous avez trouvé la vieille cruche de whisky, vous êtes presque au trésor ! Tournez-vous vers l\'ouest et descendez vers le rivage. Ne vous arrêtez pas au bord de l\'eau, continuez ! Nagez vers l\'ouest jusqu\'à l\'île où se trouve mon coffre au trésor ! »', },
    {'Localisez le Coffre au trésor du capitaine Sanders et ouvrez-le pour prendre votre récompense.', },
  },
  [141] = {
    'La Confrérie défias',
    {'La Guilde des Maçons est dirigée par un homme du nom d\'Edwin VanCleef. C\'est lui qui a rebâti Hurlevent après sa destruction par les orcs au cours de la Première Guerre. Apparemment, VanCleef et ses équipes n\'ont pas apprécié la façon dont ils ont été traités par le roi à la fin de la reconstruction. Ça pourrait expliquer une ou deux petites choses.|n|nJ\'ai rédigé un rapport détaillé pour ton maître, dans la marche de l\'Ouest. Apporte-le-lui tout de suite !', },
    {'Apporter le Rapport de Shaw à Gryan Roidemantel, dans la marche de l\'Ouest.', },
  },
  [142] = {
    'La Confrérie défias',
    {'Nous devons débusquer les Défias de leur cache, $N. Mes éclaireurs ont rendu compte qu\'un Messager Défias a été vu sur les routes entre Ruisselune, la carrière de la côte de l\'Or et la mine Veine-de-Jango. Je veux que vous le capturiez. S\'il résiste, tuez-le, et apportez-moi tout ce que vous trouverez sur lui.', },
    {'Traquer le Messager défias dans la marche de l\'Ouest et apporter les documents qu\'il transporte à Roidemantel.', },
  },
  [143] = {
    'Un message pour la marche de l\'Ouest',
    {'Il y a quelque chose d\'étrange dans le comportement de l\'armée de Hurlevent. Elle devrait se trouver là en force à l\'heure qu\'il est. De toute façon, le temps est un luxe que nous ne pouvons pas nous offrir. Je ne resterai pas là à regarder couler le sang du peuple de Comté-du-Lac sans essayer de trouver de l\'aide. J\'ai entendu dire qu\'une milice populaire s\'était formée dans la marche de l\'Ouest.|n|nApportez cette demande d\'aide à leur chef, Gryan Roidemantel. Ses hommes pourront peut-être nous apporter leur soutien en attendant que le roi envoie ses réserves.', },
    {'Le magistrat Salomon veut que vous portiez sa Demande d\'aide à Gryan Roidemantel dans la marche de l\'Ouest.', },
  },
  [144] = {
    'Un message pour la marche de l\'Ouest',
    {'La demande du magistrat Salomon me peine plus que je ne saurais le dire. Visiblement, il ignore que la guerre a éclaté dans la marche de l\'Ouest, sinon il saurait qu\'aucune aide n\'est à attendre de la Milice. Si Hurlevent ne nous avait pas abandonnés elle aussi, nous n\'aurions pas eu besoin de la Milice.|n|nApportez cette réponse à votre maître dans les Carmines, $C. Et dites-lui que mon cœur est lourd à la pensée de la mort de tant de braves.', },
    {'Retourner voir le Magistrat Salomon avec la réponse de Gryan Roidemantel.', },
  },
  [145] = {
    'Un message pour Sombre-Comté',
    {'Je sollicite votre aide une nouvelle fois. J\'ai écrit au seigneur Bouclenoire pour lui demander de m\'envoyer ses gardes les plus expérimentés, les Veilleurs, afin de renforcer les défenses de Comté-du-Lac. Il est primordial que ce message lui soit remis rapidement. Vous devez faire preuve de la plus grande vigilance. Bouclenoire est le maire de Sombre-Comté, au cœur du bois de la Pénombre. Ne vous écartez pas des chemins.', },
    {'Le magistrat Salomon veut que vous apportiez une lettre au seigneur Bouclenoire de Sombre-Comté.', },
  },
  [146] = {
    'Un message pour Sombre-Comté',
    {'Si je ne connaissais pas personnellement le magistrat Salomon, je penserais qu\'il a perdu la tête ! Envoyer les Veilleurs à Comté-du-Lac simplement parce que Hurlevent lui refuse son aide ? Nous avons dû créer le corps des Veilleurs justement parce que Hurlevent nous avait abandonnés au moment où cette horrible magie a commencé à se répandre. Si j\'envoie mes Veilleurs, notre région sera la proie du Mal avant même que les soldats n\'aient atteint la lisière de la forêt.|n|nPortez cette lettre en réponse à votre maître à Comté-du-Lac.', },
    {'Retourner voir le Magistrat Salomon avec la réponse du Seigneur Bouclenoire.', },
  },
  [147] = {
    'Chasse à l\'homme',
    {'Si le « Collecteur » prend de l\'or dans nos mines, il le vole au royaume ! Traînez-le devant la justice et apportez-moi l\'anneau dont parlait le plan de route que vous m\'avez donné. Cela pourrait bien donner une indication sur l\'employeur du Collecteur...|n|nCe plan de route indique que le Collecteur se cache près du champ de potirons des Saumepuits. Cherchez-le dans ce secteur.', },
    {'Trouvez et tuez le « Collecteur » puis rapportez l\'Anneau du Collecteur au Maréchal McCree.', },
  },
  [148] = {
    'Fournitures en provenance de Sombre-Comté',
    {'Oh ! Comment doit faire un pauvre vieillard ? J\'ai besoin d\'aller chercher des fournitures à Sombre-Comté, mais le village est si loin et je suis si vieux, si faible... Je n\'y arriverai jamais.|n|nPouvez-vous aller à Sombre-Comté et me rapporter des mèches de cheveux fantômes ? Vous les obtiendrez chez Madame Eva, qui habite la place de Sombre-Comté.', },
    {'S\'adresser à Madame Eva.', },
  },
  [149] = {
    'Mèche de cheveux fantômes',
    {'Il y a un pauvre fantôme triste, Marie l\'Aveugle, qui hante une vieille ferme, dans les collines au sud de Sombre-Comté.|n|nPrenez ce Peigne spectral et demandez-lui de peigner ses cheveux. Ensuite, rapportez-moi le peigne et j\'en retirerai les cheveux nécessaires pour fabriquer la mèche.|n|nFaites attention, car des créatures des ténèbres sont terrées autour de la maison...', },
    {'Apportez le Peigne spectral à Marie l\'Aveugle.', },
  },
  [150] = {
    'Les braconniers murlocs',
    {'Les murlocs sont en train de devenir gênants. De plus en plus de pêcheurs jettent l\'ancre au large des rives du lac Placide et remontent un problème dans leurs filets ! Nous devons nous débarrasser d\'eux avant qu\'ils aient dévoré jusqu\'au dernier poisson du lac !|n|nPartez à la chasse aux murlocs ! Rapportez-moi huit ailerons et je vous offrirai quelque chose...', },
    {'Apporter 8 Ailerons de murloc au Chef des docks Baren à Comté-du-Lac.', },
  },
  [151] = {
    'Pauvre Vieille Blanchette !',
    {'Cette pauvre Blanchette ! Après tout ce que nous lui avons fait subir, elle est très fatiguée. Je l\'ai nourrie avant que nous quittions la ferme, mais nous ne nous attendions pas à ce que le chariot nous trahisse. Si vous pouviez lui apporter quelques poignées d\'avoine des champs, vous auriez ma reconnaissance.|n|nJe parie que vous pourriez en trouver un peu près des fermes de la marche de l\'Ouest, si vous parvenez à éviter ces horribles machines qui ont pris possession des lieux. Vous verrez de nombreuses fermes, au sud-ouest.', },
    {'Verna Froncebouille de la marche de l\'Ouest veut que vous lui apportiez 8 Poignées d\'avoine.', },
  },
  [152] = {
    'La côte n\'est pas sûre',
    {'Vous avez probablement remarqué toutes les épaves le long de la côte. La Grande Mer est une maîtresse cruelle, en vérité. La côte de la marche de l\'Ouest doit être nettoyée, afin de permettre aux marins de trouver leur chemin jusqu\'à nos plages en toute sécurité. Les murlocs sont déjà assez dangereux !|n|nTuez 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte et vous recevrez une récompense.', },
    {'Tuez 7 Chasse-marées, 7 Guerriers, 7 Oracles et 7 Cours-la-côte, puis retourner voir le capitaine Grayson au Phare de l\'Ouest.', },
  },
  [153] = {
    'Les masques en cuir rouge',
    {'Les Défias bougent en permanence. Ça fait un moment que je suis leurs mouvements. J\'ai remarqué que nombre des membres du gang portaient un masque en cuir rouge.|n|nApportez-moi 15 de ces masques et vous recevrez une récompense.', },
    {'Apporter 15 Masques en cuir rouge à l\'éclaireur Galiaan à la Colline des Sentinelles.', },
  },
  [154] = {
    'Rendre le peigne',
    {'NON !|n|nPrenez-le, reprenez ce peigne, éloignez-le de moi !|n|nJe suis un monstre et personne ne peut me trouver le moindre charme !', },
    {'Rapporter le Peigne fantôme à Madame Eva à Sombre-Comté.', },
  },
  [155] = {
    'La Confrérie défias',
    {'Alors comme ça Roidemantel envoie $Gun:une:r; $R famélique pour me protéger ? Il faudra bien que ça aille. Tout de même, il vaudrait mieux s\'entourer de quelques alliés...|n|nVous connaissez le plan, n\'est-ce pas ? Vous surveillez mes arrières et je vous mène à la cache des Défias. Vous feriez mieux de ne pas trop vous éloigner. Les Défias veulent ma tête à présent. S\'ils me voient avec vous, ils essaieront de me tuer.|n|nPrévenez-moi quand vous aurez rassemblé quelques amis et que vous serez prêts à partir.', },
    {'Escortez le Traître défias jusqu\'à la cache secrète de la Confrérie défias. Lorsque vous saurez où se cachent VanCleef et ses hommes, rapportez l\'information à Gryan Roidemantel.', },
  },
  [156] = {
    'Cueillette de racines pourries',
    {'Si vous m\'apportez des racines pourries, je pourrai vous préparer une tournée de suc de zombie.|n|nLes racines pourries poussent dans des endroits étranges. J\'ai entendu dire qu\'on pouvait les trouver à l\'intérieur des crânes des démons squelettes et des squelettes infernaux… Cela dit, je ne me suis jamais approché pour vérifier !|n|nLe cimetière de Colline-aux-Corbeaux est plein de ces squelettes. Vous pourriez nous en débarrasser tout en cherchant les racines pourries. Sombre-Comté vous en serait infiniment reconnaissant.', },
    {'Rapporter 8 Racines pourries à Smitts l\'aubergiste de Sombre-Comté.', },
  },
  [157] = {
    'Apporter la mèche',
    {'Voici votre mèche, $N. Elle a des milliers d\'usages. Elle permet d\'attacher les esprits maléfiques, de redonner la vie aux objets inanimés, que sais-je encore ?', },
    {'Apportez la Mèche de cheveux fantômes à Abercrombie, dans sa cabane, au nord du cimetière de Colline-aux-Corbeaux.', },
  },
  [158] = {
    'Le suc de zombie',
    {'J\'ai besoin d\'une bouteille d\'une liqueur peu ordinaire : du Suc de zombie. Smitts, l\'aubergiste de la taverne du Corbeau écarlate à Sombre-Comté, doit pouvoir en fournir.|n|nEt dépêchez-vous, $N. Les nuits commencent à fraîchir et j\'ai besoin de ce breuvage pour réchauffer le sang dans mes veines.', },
    {'S\'adresser à Smitts l\'aubergiste.', },
  },
  [159] = {
    'Livrer le Suc',
    {'Voici votre Suc de zombie…|n|n… Et faites attention avec ce truc. Il est assez fort pour réveiller les morts !', },
    {'Apportez le Suc de zombie à Abercrombie, dans sa cabane.', },
  },
  [160] = {
    'Une lettre pour le Maire',
    {'Apportez cette lettre à Ello Bouclenoire, le maire de Sombre-Comté.|n|nNous sommes de vieux amis… Et quand il lira ça et comprendra ce que vous avez fait pour moi, je suis sûr qu\'il sera tout aussi heureux que moi ! Ha ha !', },
    {'Apporter la Lettre d\'Abercrombie à Ello Bouclenoire, maire de Sombre-Comté.', },
  },
  [161] = {
    'Une sombre menace se dessine',
    {'Si mes soupçons sont justifiés, c\'est une espèce de poudre explosive. Il faut la faire analyser par un artificier pour savoir à quoi nous avons affaire exactement.|n|nUn seul homme en est capable : Ashlan Rictus-de-pierre. Il est chargé de la surveillance des ogres au bastion des Mo\'grosh, à l\'est. Allez dans cette direction et trouvez-le pour qu\'il puisse éclairer notre lanterne.', },
    {'L\'Ingénieur en chef Hinderweir veut que vous apportiez la Poudre à l\'odeur étrange à Ashlan Rictus-de-pierre, l\'expert en explosifs du Camp des Mo\'grosh.', },
  },
  [162] = {
    'L\'ascension des silithides',
    {'Je vous presse d\'apporter ce rapport à quelqu\'un qui a les connaissances nécessaires pour l\'étudier.|n|nJe connais une elfe de la nuit érudite, Gracina Forcesprit. Elle a passé beaucoup de temps à étudier les formes de vie exceptionnelles de l\'écologie d\'Azeroth et elle est historienne de surcroît ! Si vous cherchez quelqu\'un qui pourrait comprendre la nature de cette menace, et surtout qui serait capable de trouver une solution, alors confiez-lui ce rapport. Nous aurons besoin de son aide.|n|nLa dernière fois que j\'ai entendu parler d\'elle, elle vivait au temple de la Lune, à Darnassus.', },
    {'Apporter le Rapport d\'analyse des insectes à Gracina Forcesprit à Darnassus.', },
  },
  [163] = {
    'Colline-aux-Corbeaux',
    {'Il y a quelque chose d\'étrange à Colline-aux-Corbeaux, $N. Calor jure que quelqu\'un (ou quelque chose) hante les bâtiments là-bas. Deux nuits de suite, il a remarqué que les ombres bougeaient et la nuit d\'avant, il dit qu\'il a vu de la lumière à l\'une des fenêtres.|n|nSi, comme vous le prétendez, vous vous intéressez vraiment à la sécurité du bois de la Pénombre, trouvez le monstre qui hante Colline-aux-Corbeaux.', },
    {'Découvrir ce qui hante Colline-aux-Corbeaux.', },
  },
  [164] = {
    'Livraison à Sven',
    {'Connaissez-vous Sven ? Voilà un homme qui accomplit l\'œuvre de la Lumière ! Lui et ses fidèles vivent dans un camp à la lisière nord-ouest du bois de la Pénombre.|n|nMalheureusement, ils sont si peu nombreux qu\'ils ne peuvent même pas dépêcher l\'un des leurs pour aller en ville chercher du ravitaillement. Voudriez-vous lui apporter ceci ?', },
    {'Ravitailler Sven.', },
  },
  [165] = {
    'L\'ermite',
    {'Il y avait un vieil homme qui venait régulièrement en ville faire des courses, mais cela fait un moment que je ne l\'ai pas vu. Il vit dans une cabane, au-dessus du cimetière de Colline-aux-Corbeaux, si je me souviens bien. Vous devriez aller voir ce qui ne va pas.', },
    {'Aller voir le vieil homme dans sa cabane près du cimetière de Colline-aux-Corbeaux.', },
  },
  [166] = {
    'La Confrérie défias',
    {'Il vous reste une dernière mission à accomplir. Il va falloir éliminer Edwin VanCleef. Bien que cela me chagrine de condamner un homme à mort, c\'est pour le bien du peuple de la marche de l\'Ouest que VanCleef doit mourir. Apportez-moi sa tête lorsque l\'acte sera accompli.', },
    {'Tuer Edwin VanCleef et apporter sa Tête à Gryan Roidemantel.', },
  },
  [167] = {
    'Adieu mon frère…',
    {'Nous étions au plus profond d\'une mine dans la marche de l\'Ouest, cachés derrière un baraquement à Ruisselune. Impossible de savoir d\'où viennent ces voleurs puants... Bref, la mine s\'est effondrée sur nous. Je m\'en suis sorti mais les autres... Enfin... On n\'en a plus entendu parler.|n|nVous aurez peut-être plus de chance. Si vous arrivez à avoir des nouvelles de mon frère, je vous en serai reconnaissant. Il portait toujours son insigne de la Ligue des Explorateurs. Si vous ne le trouvez pas, mais que vous me rapportez cet insigne, cela me rendrait un peu de paix.', },
    {'Apporter l\'Insigne de la Ligue des Explorateurs du contremaître Crispechardon à Wilder Crispechardon à Hurlevent.', },
  },
  [168] = {
    'À la recherche de cartes du syndicat des mineurs',
    {'Nombre de mes amis ont péri ce jour terrible de l\'effondrement de la mine. Si vos pas vous conduisent dans cette partie de la mine de Ruisselune, voyez s\'il existe des indices qui permettraient de les identifier. Si vous trouvez leurs cartes du syndicat des mineurs, rapportez-les-moi et je préviendrai leurs familles.', },
    {'Récupérer 4 Cartes du syndicat des mineurs et les apporter à Wilder Crispechardon à Hurlevent.', },
  },
  [169] = {
    'Avis de recherche : Gath\'Ilzogg',
    {'On recherche ! Gath\'Ilzogg, responsable des attaques rochenoires sur le donjon de Guet-de-Pierre et des raids sur la ville de Comté-du-Lac.|n|nGath\'Ilzogg est très dangereux. On dit qu\'il prépare ses prochains crimes contre les humains depuis le donjon récemment conquis. L\'invasion de ces orcs doit être stoppée à tout prix ! Une forte récompense est offerte au cœur vaillant qui apportera la tête de Gath\'Ilzogg au magistrat Salomon.', },
    {'Tuer Gath\'Ilzogg et apporter sa Tête au Magistrat Salomon de Comté-du-Lac pour toucher la récompense.', },
  },
  [170] = {
    'Une nouvelle menace',
    {'J\'espère que vous êtes là pour nous donner un coup de main, $C. Après la dernière attaque des troggs, nous avons besoin de toute l\'aide possible !|n|nJe sais que ces canailles pullulent dans toutes les régions et on dirait que les Frigères ne font pas exception. On les a repérés au sud-est, partout dans les collines et à côté du lac Gelé.|n|nEt ce n\'est pas tout ! Il y a à peine quelques nuits, ils ont attaqué et détruit notre camp, à l\'ouest !|n|nNous sommes un peu à court de personnel, ici, $Gmon gars:jeune fille;, et nous avons besoin de force et de bravoure pour renvoyer les troggs d\'où ils viennent.', },
    {'Balir Martel-de-givre veut que vous tuiez 6 Troggs mâcherocs et 6 Troggs mâcherocs mastocs.', },
  },
  [171] = {
    'Un surveillant de l\'Alliance',
    {'Vous avez été très $Ggentil:gentille; avec moi, $N. Je n\'aurais jamais pensé que je m\'amuserais autant pendant la Semaine des enfants. Merci.|n|nJ\'aimerais que tous les orphelins puissent avoir la chance de faire ce que nous avons fait. Pensez-vous que nous pourrions retourner voir Foltiff Tremblhoupette pour obtenir un râtelier d\'épées en mousse ? Je pense qu\'il est encore en train de pousser ce chariot dans les Canaux à l\'extérieur du quartier commerçant. Comme ça, tout le monde à l\'orphelinat pourra aussi faire quelque chose de marrant !|n|nAprès, il sera temps pour moi de rentrer.', },
    {'Achetez un Râtelier d\'épées en mousse à Foltiff Tremblhoupette. Puis ramenez votre protégé à l\'orphelinat de Hurlevent, en parlant à la directrice de l\'orphelinat, Rossignol, dans le Quartier de la Cathédrale.', },
  },
  [172] = {
    'La Semaine des enfants',
    {'Vous voulez aider l\'orphelinat ? Soyez-en $Gremercié:remerciée; mon $Gami:amie;. Votre aide durant la Semaine des enfants nous sera précieuse.|n|nPrenez ce sifflet. Il ne restera pas disponible très longtemps : en fait, pas plus longtemps que ne dure la Semaine des enfants. Quand vous l\'utiliserez, vous pourrez parler à l\'enfant dont vous avez accepté de vous occuper. Si vous l\'utilisez une seconde fois, il renverra l\'enfant.|n|nJe vous en prie, $N, faites vite la connaissance de votre protégé ! Je suis sûre que l\'enfant est très impatient de vous rencontrer.', },
    {'Utiliser le sifflet d\'orphelin orc pour parler à l\'enfant que vous protégez durant la Semaine des enfants.', },
  },
  [173] = {
    'Worgens dans les bois',
    {'Les ténèbres s\'étendent inexorablement sur le bois de la Pénombre. La quête de maître Carevin est l\'expulsion du mal et de l\'hérésie. Nos efforts protègent le peuple de Sombre-Comté.|n|nVous sentez-vous digne de nous rejoindre ?|n|nJe pensais comme vous, autrefois. Mais la suffisance des Veilleurs était pénible et j\'ai rejoint maître Carevin. Si vous voulez prouver votre valeur, les mots ne suffiront pas.|n|nTestez votre habileté contre les tisseurs d\'ombre Plaie-de-nuit, des worgens qui rôdent dans le verger Pourrissant et dans le bosquet de Clairbois (clair, mon œil !).', },
    {'Tuer 6 worgens Tisseurs d\'ombre Plaie-de-nuit pour Calor de Sombre-Comté.', },
  },
  [174] = {
    '[PÉRIMÉ]Les yeux dans les étoiles',
    {'Mon ami Cog, un gnome, a promis de m\'aider à construire un outil qui permet de voir les étoiles. Il semblerait qu\'il existe une vérité, au-delà de la magie, qui explique les étranges changements survenus dans la forêt.|n|nApportez-moi un tube en bronze fabriqué par un ingénieur habile. C\'est la première étape, si j\'en crois le plan de Cog.', },
    {'Viktori Prism\'Antras de Sombre-Comté veut que vous lui apportiez un Tube en bronze.', },
  },
  [175] = {
    '[PÉRIMÉ]Les yeux dans les étoiles',
    {'Selon le plan de Cog, il faut maintenant que je trouve un moyen de réfléchir la lumière. Je me souviens d\'une femme du nom de Marie, bien connue par ici car elle avait l\'habitude de transporter un miroir. Vous pourriez peut-être chercher Marie et voir si elle nous prêterait une surface réfléchissante pour notre entreprise ? Je crois qu\'elle habitait au sud du bois de la Pénombre...', },
    {'Trouver Marie et la persuader de prêter une surface réfléchissante pour le projet de Viktori.', },
  },
  [176] = {
    'On recherche : « Lardeur »',
    {'On recherche : Lardeur.|n|nCe Lardeur est un énorme gnoll qui rôde dans les bois en quête de proies, dans la partie sud-ouest d\'Elwynn. Il a toujours réussi à dépister ou à vaincre ceux qui voulaient le capturer.|n|nL\'armée de Hurlevent offre une généreuse récompense pour la tête de ce gnoll. Pour avoir une chance de la remporter, les chasseurs de primes devront s\'aventurer dans les bois et régler son compte à la bête !', },
    {'« Réglez son compte » à Lardeur et retournez voir le Maréchal Dughan.', },
  },
  [177] = {
    '[PÉRIMÉ]Les yeux dans les étoiles',
    {'Le miroir était l\'un de mes plus précieux trésors jusqu\'à... l\'accident. Après cela, je l\'ai jeté derrière la grange. Il y avait une goule folle qui traînait souvent par là-bas. Elle l\'a peut-être récupéré. La rumeur dit qu\'elle vit dans le cimetière des Jardins paisibles.', },
    {'Prendre le miroir de Marie l\'Aveugle à la Goule folle et l\'apporter à Viktori de Sombre-Comté.', },
  },
  [178] = {
    'Theocritus récupère son Pendentif',
    {'<Vous entendez une voix désincarnée...>|n|nNe soyez pas $Geffrayé:effrayée;. Je suis Theocritus, grand mage de la tour d\'Azora de la forêt d\'Elwynn. Le pendentif que vous avez en main est un moyen de communication entre les gnolls Sombrepoil et leur maître Morganth.|n|nAprès des mois de recherches, j\'ai cru que moi aussi je pourrais communiquer grâce à ces pendentifs. Si vous pouvez entendre ce message, c\'est que mon sortilège est un succès.|n|nApportez-moi ce pendentif et je vous récompenserai.', },
    {'Apportez le Pendentif sombrepoil décoloré à Theocritus le Mage à la Tour d\'Azora, dans la Forêt d\'Elwynn.', },
  },
  [179] = {
    'Tailleur chez les nains',
    {'Qu\'est-ce que c\'est ? On dirait que vous avez besoin de quelque chose pour tenir chaud aux mains, non ?|n|nJe vais vous dire ce qui vous serait utile : une paire de jolis gants bien chauds. Et comme je suis une âme charitable, je vous les fournirai. À une condition, cependant.|n|nJ\'ai besoin de viande de loup. Arrangement équitable, n\'est-ce pas ? Vous m\'apportez de la viande et je m\'assure qu\'on ne sera pas obligé de vous amputer d\'un ou deux doigts gelés. Qu\'est-ce que vous en dites ?', },
    {'Sten Rudebras voudrait 8 morceaux de Viande de loup coriace.', },
  },
  [180] = {
    'Avis de recherche !',
    {'On recherche : Lieutenant Tripecroc.|n|nConnu comme chef du clan des gnolls Sombrepoil, sous les ordres de Morganth, ennemi de la commune et du royaume. Sur mandat du magistrat Salomon, ce traître doit mourir. Apportez sa patte au magistrat comme preuve de sa mort.', },
    {'Tuer le Lieutenant Tripecroc et rapporter sa patte au Magistrat Salomon de Comté-du-Lac.', },
  },
  [181] = {
    '[PÉRIMÉ]Les yeux dans les étoiles',
    {'Il ne manque plus qu\'un seul objet pour terminer cet appareil. Le plan de Cog mentionne une lentille ou quelque chose comme ça. La seule lentille qui soit assez large pour l\'appareil risque d\'être très difficile à acquérir.|n|nUn ogre du nom de Zzarc\'Vul habite dans la colline au sud du bois de la Pénombre. Si vous le pouvez, rapportez-moi son monocle et je l\'utiliserai comme lentille !', },
    {'Localiser Zzarc\'Vul dans le tertre des ogres au sud du bois de la Pénombre et rapporter son Monocle à Viktori de Sombre-Comté.', },
  },
  [182] = {
    'La menace trolle',
    nil,
    nil,
  },
  [183] = {
    'Chasseur de sangliers',
    {'Rien de tel qu\'une journée de chasse au sanglier, pas vrai ?|n|nOui, eh bien ici, dans la vallée des Frigères, il y en a tellement que ça gâche tout plaisir. Pas besoin de les pousser à attaquer ! Ils sont furieux et prêts à charger sans qu\'on les aide ! En fait, depuis quelque temps, il y a tellement de sangliers dans la vallée des Frigères que chasseur devient un métier à haut risque.|n|nPour faire court, si vous pouviez m\'aider à tuer quelques bêtes, j\'apprécierais le geste.', },
    {'Talin Œil-perçant aimerait que vous tuiez 12 Petits sangliers des rochers.', },
  },
  [184] = {
    'Titre de propriété de Froncebouille',
    {'Voici un vieux titre de propriété concernant une ferme de la marche de l\'Ouest, signé par un certain Théodore Froncebouille et par sa femme, Verna. Au dos, il y a quelques mots hâtivement écrits : |n|n« Nous avons fait pression sur Froncebouille et avons récupéré son titre pensant que ça pourrait nous être utile au cas où nous voudrions nous installer.|n|nIls ne nous embêteront pas. La dernière fois que je les ai vus, ils étaient sur la route de la marche, avec un chariot cassé. »|n|nLes Froncebouille aimeraient sans doute récupérer leur titre...', },
    {'Rapportez le Titre de propriété de Froncebouille à la Ferme des Jansen, dans la Marche de l\'Ouest.', },
  },
  [185] = {
    'Le frisson de la chasse au tigre',
    nil,
    nil,
  },
  [186] = {
    'Petit tigre deviendra grand…',
    nil,
    nil,
  },
  [187] = {
    'Chasseur de grands fauves : les tigres',
    nil,
    nil,
  },
  [188] = {
    'Le frisson de la chasse au tigre',
    {'Les légendes parlent d\'une tigresse insaisissable... Un fauve si puissant qu\'elle dépasse de loin même les vieux mâles. Les chasseurs de l\'expédition de Nesingwary l\'ont poursuivie, sans succès. Plusieurs d\'entre eux sont tombés sous ses griffes acérées, et leurs corps se décompensent maintenant au pied de sa colline, au nord de Grom\'gol. Ils ont surnommé la bête Sin\'Dall.|n|nVous voulez donc accomplir ce $Gqu\'aucun:qu\'aucune:r; $R n\'a réussi avant vous : traquer et tuer Sin\'Dall, et prendre sa patte comme trophée.', },
    {'Tuez Sin\'Dall et rapportez sa Patte.', },
  },
  [189] = {
    'Les oreilles de Scalp-rouge',
    {'Saletés de trolls ! Ils massacrent tous nos agents dès qu\'ils mettent un pied dans la jungle ! J\'ai perdu beaucoup de mes meilleurs hommes dans de simples escarmouches ! Les pertes deviennent insupportables ! Comment vais-je pouvoir expliquer cela au baron Revilgaz ?|n|nIl faut une action décisive... Pense, Kebok, réfléchis... Tu n\'as pas gagné tes galons et ton poste en rêvassant... J\'y suis ! Vous... $N, c\'est ça ? Vous allez m\'aider, n\'est-ce pas ? Il y a de l\'argent à gagner.|n|nVoilà le marché : vous me rapportez les oreilles de quinze trolls scalps-rouges et vous recevrez une récompense.', },
    {'Obtenir 15 Oreilles de trolls scalps-rouges et les apporter à Kebok, à Baie-du-Butin.', },
  },
  [190] = {
    'Si vous voulez vous joindre à la chasse aux côtés des experts placés sous le commandement de Hemet Junior, il va falloir nous prouver que vous êtes $Gun chasseur:une chasseuse; de panthères $Gaguerri:aguerrie;. Vous devrez commencer par les proies les plus faciles, en vous attaquant pour le moment aux plus jeunes fauves. Au fur et à mesure que vous vous améliorerez et que vous acquerrez de l\'expérience, vos chasses deviendront indubitablement de plus en plus dangereuses.|n|nCommencez votre traque en vous dirigeant à l\'est. Revenez me voir quand vous serez devenu un maître chasseur de panthères.',
    {'Si vous voulez vous joindre à la chasse aux côtés des experts placés sous le commandement de Hemet Junior, il va falloir nous prouver que vous êtes $Gun chasseur:une chasseuse; de panthères $Gaguerri:aguerrie;. Vous devrez commencer par les proies les plus faciles, en vous attaquant pour le moment aux plus jeunes fauves. Au fur et à mesure que vous vous améliorerez et que vous acquerrez de l\'expérience, vos chasses deviendront indubitablement de plus en plus dangereuses.|n|nCommencez votre traque en vous dirigeant à l\'est. Revenez me voir quand vous serez devenu un maître chasseur de panthères.', },
    nil,
  },
  [191] = {
    'Petite panthère deviendra grande…',
    nil,
    nil,
  },
  [192] = {
    'Chasseur de grands fauves : les panthères',
    nil,
    nil,
  },
  [193] = {
    'Le frisson de la chasse à la panthère',
    {'Vous êtes presque $Gdevenu:devenue; un maître-chasseur de panthère. Mais il en reste une qui jusqu\'à maintenant vous a échappé.|n|nDes chansons ont été composées sur une puissante panthère nommée Bhag\'thera. Voyons si vous pouvez mettre vos compétences à l\'épreuve en tuant ce fauve.|n|nRapporter le croc de Bhag\'thera à Erlgadin suffira à prouver que vous avez maîtrisé l\'art de la chasse à la panthère.', },
    {'Récupérez le Croc de Bhag\'thera.', },
  },
  [194] = {
    'Le frisson de la chasse au raptor',
    nil,
    nil,
  },
  [195] = {
    'Petit raptor deviendra grand…',
    nil,
    nil,
  },
  [196] = {
    'Chasseur de grands sauriens : les raptors',
    nil,
    nil,
  },
  [197] = {
    'Le frisson de la chasse au raptor',
    {'Avant de retourner au camp de l\'expédition de Nesingwary, vous devez réussir l\'impossible : traquer le raptor qu\'aucun autre chasseur n\'a réussi à capturer. Cette bête est surnommée Téthis, et terrorise la région sud-est de la Strangleronce septentrionale.|n|nSi vous rapportez la serre de Téthis au grand chasseur nain, cela devrait lui prouver que vous êtes $Gun:une:r; $R sortant de l\'ordinaire.', },
    {'Chassez Téthis.', },
  },
  [198] = {
    'Les marchandises du soldat Thorsen',
    {'Hum ! Oui, il y a quelque chose que vous pourriez faire. Le lieutenant Doren et ses partisans, dans le nord, ont besoin d\'être réapprovisionnés.|n|nIls n\'ont encore rien reçu, et avec les attaques des trolls, j\'aurais besoin de quelqu\'un pour le faire. Le campement de Doren se situe au nord-ouest de la route, à l\'entrée de Strangleronce depuis le bois de la Pénombre. Donnez les provisions au soldat Thorsen ; s\'il n\'est pas dans le campement, c\'est qu\'il patrouille plus au sud du camp.|n|nAttention, si vous échouez, vous devrez me rembourser.', },
    {'Remettez les marchandises des gobelins au soldat Thorsen.', },
  },
  [199] = {
    'Une sombre menace se dessine',
    {'Vous devez prendre un échantillon de l\'étrange poudre odorante.', },
    {'Retournez voir l\'ingénieur en chef Hinderweir et montrez-lui l\'indice que vous avez découvert.', },
  },
  [200] = {
    'Hérode la Paperasse',
    {'Si Kurzen connaît le secret de Thorsen, alors cela veut dire qu\'il y a un espion parmi nous. Nous devons trouver comment le secret a été éventé !|n|nLe contact de Thorsen au camp de Kurzen était Hérode la Paperasse. C\'est l\'officier en logistique de Kurzen et il sait tout ce qui se passe dans l\'enceinte. Si vous pouvez mettre la main sur les notes et les registres de Hérode, nous comprendrions peut-être comment Thorsen a été découvert.|n|nLorsque nous étions du côté de Kurzen, le bureau de la Paperasse se trouvait au dernier étage de la seule maison à étage du camp. Ses registres s\'y trouvent probablement encore.', },
    {'Trouver les registres de Hérode la Paperasse.', },
  },
  [201] = {
    'L\'enquête au camp',
    {'On m\'a rapporté qu\'un groupe de chasseurs a établi campement au bord de la rivière, au-dessus de celui de la KapitalRisk, sur le lac Nazfériti. En temps normal, je n\'y prêterais pas attention. Mais, aussi improbable que cela puisse paraître, j\'ai entendu dire que Hemet Nesingwary Jr était l\'un de ces chasseurs. Il semble avoir beaucoup d\'affinités, si vous voyez ce que je veux dire, et l\'on n\'est jamais trop prudent.|n|nPourquoi n\'iriez-vous pas y faire un tour, $N, et voir de quoi il retourne ?', },
    {'Trouver le camp des chasseurs et communiquer sa position à Krazek à Baie-du-Butin.', },
  },
  [202] = {
    'Le colonel Kurzen',
    {'Vous avez montré votre valeur à maintes reprises, et vos ressources semblent même concurrencer celles de ce Kurzen en personne. Il se peut que vous représentiez le salut pour notre bande de rebelles… si vous pouvez vous mesurer à Kurzen et le vaincre !|n|nIl contrôle ses hommes depuis les profondeurs de la Réserve. Vous devez y pénétrer, déborder ses défenseurs, puis combattre Kurzen et ses officiers.|n|nAdieu, $N. Mes espoirs et la destinée de mes hommes sont entre vos mains.', },
    {'Tuer 6 Troupes d\'élite, 4 Lieutenants et rapporter la tête de Kurzen au lieutenant Doren au Camp rebelle.', },
  },
  [203] = {
    'La seconde rébellion',
    {'Nous combattons désespérément le colonel Kurzen. Non seulement c\'est un habile tacticien, mais nous nous battons à 1 contre 10. Pour survivre, nous devons retourner contre lui ses propres tactiques sournoises.|n|nInvestissez son camp, à l\'est, et tuez ses hommes. Le plus possible. Et ressortez avant que les renforts ne vous attrapent.', },
    {'Tuer 15 Guerriers de la jungle.|n|nRetourner voir le sergent Yohwa au Camp rebelle.', },
  },
  [204] = {
    'Mauvaise médecine',
    {'Si nous voulons avoir la moindre chance contre Kurzen, nous devons neutraliser ses services de soins. Il a rassemblé un nombre important de guérisseurs qui soignent ses troupes avec des remèdes tropicaux et empoisonnent les nôtres avec des extraits de fougère vénéneuse.|n|nNous avons besoin de ces remèdes et extraits pour les nôtres. Fouillez la base de Kurzen : ses guérisseurs et guerriers de la jungle auront les remèdes sur eux, et les extraits sont probablement stockés dans une caisse d\'approvisionnement quelconque.', },
    {'Apporter 7 Remèdes tropicaux et 1 Extrait de fougère vénéneuse au sergent Yohwa au Camp rebelle.', },
  },
  [205] = {
    'Sorcellerie trolle',
    {'Tandis que j\'étudie ces légendes que vous avez apportées, rassemblez pour moi des instruments de la magie maléfique des trolls. Entrez dans le territoire des trolls casse-crânes, une tribu mineure du Sud lointain, et obtenez de leurs féticheurs et de leurs mystiques certains fétiches.', },
    {'Apporter 4 Fétiches casse-crânes à frère Nimetz au Camp rebelle.', },
  },
  [206] = {
    nil,
    {'Kurzen est peut-être mort, mais… ce qui l\'a conduit vers le Mal existe toujours ! Mes recherches m\'ont appris ceci : un ogre mage du nom de Mai\'Zoth vit dans les monts orientaux de Strangleronce. On dit qu\'il utilise une magie contrôlant l\'esprit, et je suis sûr qu\'il a perverti Kurzen.|n|nSi l\'on permet à Mai\'Zoth de vivre, alors ses maléfices peuvent en influencer d\'autres, et nous verrons peut-être surgir un deuxième Kurzen.|n|nTuez-le, et apportez-moi sa vue de l\'esprit, l\'artéfact qu\'il utilise pour corrompre les gens.', },
    {'Apportez la Vue de l\'esprit au frère Nimetz au Camp rebelle.', },
  },
  [207] = {
    'Le mystère de Kurzen',
    {'Le colonel Kurzen était jadis un homme grand et noble. Je dois découvrir la cause de sa déchéance ! Il est peut-être sous l\'emprise de la magie des trolls. Pour étayer cette hypothèse, il me faut étudier certaines de leurs légendes.|n|nQuatre tablettes sont cachées dans les ruines des trolls de Strangleronce. Je dois en prendre connaissance ! Recopiez-les et rapportez vos transcriptions.|n|nLa première tablette est dans les Ruines de Bal\'lal, la deuxième dans le Récif infâme, et vous trouverez les troisième et quatrième dans les ruines de Zul\'Kunda.', },
    {'Trouver les 4 tablettes et rapporter ces légendes au frère Nimetz.', },
  },
  [208] = {
    'La chasse au gros gibier',
    {'$N, vous êtes $Gun chasseur:une chasseresse; digne de notre compagnie. Des champs de bataille de Lordaeron aux jungles les plus profondes, j\'ai rarement été témoin de telles prouesses aux armes.|n|nVous avez tué la féroce Sin\'Dall, l\'insaisissable Bag\'thera et le perfide Téthis. Mais le trophée ultime reste la tête du roi Bangalash. Ce tigre blanc est la raison de ma présence ici. Et pourtant, il continue de me narguer depuis son perchoir, vers le sud. Tuez le roi Bangalash et vous serez $Gle plus grand des chasseurs:la plus grande des chasseresses;.', },
    {'Chassez le Roi Bangalash, le grand tigre blanc, et prenez sa tête.', },
  },
  [209] = {
    'Les défenses de Casse-crâne',
    {'Il est difficile et onéreux de tuer assez de tigres pour fournir l\'exportation de leurs crocs vers les îles des mers du Sud. Par chance, nous avons mis au point une technique pour fabriquer des faux indétectables.|n|nÉtonnamment, la matière idéale pour créer ces faux crocs, ce sont des défenses de trolls casse-crânes.|n|nEt avant de vous mettre à râler, sachez que ce que le client ignore ne peut pas le déranger, hein ?|n|nApportez-moi beaucoup de ces défenses, afin que l\'on puisse fournir la livraison mensuelle !', },
    {'Récupérez 18 Défenses de Casse-crâne et apportez-les à Kebok.', },
  },
  [210] = {
    'La cuisine de Krazek',
    {'Presque toute la cuisine se fait au camp. Et c\'était beaucoup de travail, jusqu\'à ce que j\'achète une marmite à un marchand gobelin de Baie-du-Butin. Cette marmite est une pure merveille, le temps qu\'elle m\'a fait gagner est inimaginable… malheureusement elle est cassée ! |n|nPourriez-vous la lui ramener afin qu\'il la répare ? Son nom est Krazek.', },
    {'Apportez la Cocotte ébréchée de Krazek à Krazek le gobelin.', },
  },
  [211] = {
    'Hélas, Andorhal',
    {'Hélas, le temps est venu d\'attaquer Andorhal et d\'en finir avec la liche qui la contrôle !|n|nAraj l\'Invocateur, la liche, règne sur les ruines de la cité. Il est gardé par de nombreuses créatures du Fléau qui encerclent les restes du centre de la ville, et sa garde personnelle, qui lui est directement attachée, est redoutable. Vous aurez besoin de plusieurs alliés pour avoir la moindre chance de le vaincre.|n|nExécutez Araj, $N, et apportez-moi un éclat de son phylactère comme preuve !', },
    {'Apporter l\'Éclat phylactère d\'Araj au commandant Ashlam Vaillepoing, au camp du Noroît, dans les Maleterres de l\'Ouest.', },
  },
  [212] = {
    'Un repas servi froid',
    {'L\'un de mes plats les plus célèbres est le basilic frappé avec sa vinaigrette citronnée. Mais le problème est qu\'il est impossible de garder la viande fraîche, et je dois servir ce plat ce soir à l\'occasion de l\'anniversaire d\'un noble !|n|nAussi si vous pouviez m\'apporter un cuissot provenant d\'un basilic Oeil-de-glace fraîchement occis, et ce dans les plus brefs délais, alors je vous serais redevable d\'un festin de roi.|n|nCes créatures vagabondent souvent dans les dunes au nord-ouest de Strangleronce, vous avez donc un long chemin à parcourir. Et faites vite !', },
    {'Tuer un basilic Œil-de-glace, collecter un Cuissot de basilic glacé, et le rapporter à Angus Stern, au Solitaire bleu.', },
  },
  [213] = {
    'Une ponction musclée',
    {'Cette fois, c\'en est trop ! Ce n\'était pas assez que ce Gelriz vire les nababs invités par les princes marchands, à présent il essaie de s\'immiscer dans les affaires du plus célèbre des pirates !|n|nRevilgaz ne les aura pas, et il m\'a demandé de régler le problème à ma manière.|n|nMa manière ? Le vol ! Les géologues de la KapitalRisk qui campent près du lac Nazfériti sont très intéressés par ces étranges cristaux bleus qu\'ils ont trouvés dans les mines. Rapportez-moi des échantillons de ces cristaux. Peu m\'importe comment vous les obtenez.', },
    {'Retrouver 8 Cristaux réduits et les apporter à Kebok à Baie-du-Butin.', },
  },
  [214] = {
    'Les masques rouges en soie',
    {'Ce n\'est un secret pour personne que le signe de reconnaissance du gang des Défias est un masque rouge. Mais nous avons appris que la qualité du tissu dont est fait le masque détermine le rang de celui qui le porte au sein du gang.|n|nCela étant dit, je veux que vous éliminiez autant de Défias haut placés que possible. Vous en trouverez à coup sûr dans la cachette de VanCleef. Lorsque vous en aurez terminé, rapportez-moi 10 masques rouges en soie pour me prouver leur mort, je vous remettrai alors une récompense. Bonne chance, $N.', },
    {'L\'Eclaireur Riell de la tour de la Colline des sentinelles veut que vous lui rapportiez 10 Masques rouges en soie.', },
  },
  [215] = {
    'Les secrets de la jungle',
    {'Merci de m\'avoir sauvé, $N. Je sais de quoi ça a l\'air, mais… permettez-moi de m\'expliquer.|n|nJ\'ai été chargé par le lieutenant Doren de rejoindre les troupes de Kurzen, pour les espionner et fournir des informations vitales aux renseignements rebelles. Ce que vous venez de voir, c\'est ce que je pensais être ma chance de m\'infiltrer dans la base de Kurzen. Je m\'étais trompé et, encore une fois, merci de m\'avoir sauvé.|n|nIl s\'agissait d\'une mission secrète, aussi n\'en parlez à personne. Mais si vous allez voir Doren, il vous expliquera.', },
    {'Parler au lieutenant Doren au Camp rebelle.', },
  },
  [216] = {
    'Entre un roc et un Crin-de-Chardon',
    {'Les furbolgs crins-de-Chardon sont devenus un danger qui menace notre expansion ! Le village des Crins-de-Chardon, à l\'ouest, nous bloque la route menant au poste de Bois-Brisé. Par ce chemin, nous pourrions contourner le village d\'Astranaar. D\'un autre côté, il offrirait à l\'Alliance une voie d\'accès supplémentaire par où poursuivre son expansion.|n|n$N, nous ne pouvons pas tolérer... que se forme ainsi un chemin facilitant leur campagne d\'expansion !|n|nAllez au village des Crins-de-Chardon et réduisez le nombre des furbolgs. Vous recevrez une récompense en échange de ce travail ; mais surtout, vous ferez votre devoir au service de la Horde !', },
    {'Karang Amakkar, du Guet de Hurlenfer, vous demande de tuer 15 Furbolgs Crins-de-chardon au village des Crins-de-chardon.', },
  },
  [217] = {
    'Une frappe décisive',
    nil,
    nil,
  },
  [218] = {
    'La glace et le feu',
    nil,
    nil,
  },
  [219] = {
    'Porté disparu',
    {'Enfin, des amis de l\'Alliance !|n|nAu secours… Je vous en prie…|n|nLa dernière chose dont je me souviens est que les orcs ont submergé nos forces. La plupart des hommes ont été tués. J\'ai reçu un coup terrible à la tête et tout s\'est assombri. Je suis à présent prisonnier dans cette caverne. Au secours, je suis gravement blessé !|n|nJ\'aurais besoin d\'aide pour revenir jusqu\'à la ville... par pitié... vous êtes mon seul espoir...', },
    {'Protéger le caporal Keeshan sur le chemin des Carmines.', },
  },
  [220] = {
    'L\'appel de l\'eau',
    {'Islen aura une nouvelle tâche à vous confier avant de vous récompenser d\'un totem. La fiole d\'eau que je vous ai donnée est nécessaire à l\'accomplissement de cette tâche.|n|nPartez à présent et trouvez-la. Nous nous reverrons un jour.', },
    {'Apportez la Fiole d\'eau la plus pure à Islen Oeil-des-rivières à l\'Escalier des marées, dans les Tarides.', },
  },
  [221] = {
    'Worgens dans les bois',
    {'Vous avez peut-être remarqué de grands worgens accompagnant les Tisseurs d\'ombre dans les bois ? D\'après ce que nous savons, ces messagers renforcent considérablement les rangs de leurs alliés.|n|nLors de mes expéditions, j\'ai également découvert qu\'ils ont envahi le verger Pourrissant, au sud-ouest de la ville. Ces worgens sont plus résistants que ceux que vous avez combattus précédemment.|n|nRestez donc sur vos gardes.', },
    {'Tuer 12 worgens Messagers Plaie-de-nuit pour Calor de Sombre-Comté.', },
  },
  [222] = {
    'Worgens dans les bois',
    {'Vos victoires passées m\'ont convaincu que vous êtes capable de vous mesurer aux plus forts des worgens infestant les bois.|n|nParmi ceux qui se sont établis en ces contrées, les Crocs noirs et les Contaminés se sont montrés les plus dangereux. On peut les trouver près de certaines cavernes et dans la mine, au sud.|n|nVous pourrez voir de loin la lumière des feux qu\'ils font avec les os de leurs victimes...', },
    {'Tuer 8 Crocs noirs Plaie-de-nuit et 8 Contaminés Plaie-de-nuit pour Calor de Sombre-Comté.', },
  },
  [223] = {
    'Worgens dans les bois',
    {'Voilà, $N. Portez ce message à maître Carevin.|n|n<Il sort promptement un morceau de parchemin décoloré et vous le tend.>|n|nEncore d\'autres comme vous, et nous pourrons vaincre les Veilleurs ! Peut-être alors serions-nous en mesure d\'achever l\'œuvre à laquelle si peu d\'entre nous se sont attelés.', },
    {'Apporter la lettre de Calor à Jonathan Carevin.', },
  },
  [224] = {
    'Une frappe décisive',
    {'Nous devons protéger le Loch, $N ! Avec tant de soldats du roi combattant vaillamment sur des champs de bataille lointains, les forces manquent à l\'intérieur. Les troggs se déversent de la moindre brèche et constituent la menace principale qui pèse sur Forgefer. Ces répugnants mutants doivent être annihilés.|n|nNous avons besoin de vous, $Gbrave aventurier:courageuse aventurière;, pour mener une expédition et semer le chaos dans leurs rangs. Tuez six troggs et six éclaireurs brisepierre, puis revenez me voir. Vous trouverez cette vermine dans les passes entre les montagnes, au sud.', },
    {'Le Montagnard Pave-silex de Thelsamar veut que vous tuiez 6 Troggs et 6 Éclaireurs brisepierre.', },
  },
  [225] = {
    'La tombe effritée',
    {'L\'épitaphe, sur la tombe effritée, annonce simplement :|n|nMORGAN LADIMORE|n|n<Après un examen plus minutieux, vous remarquez que l\'on a touché à la couche de terre sur la tombe, et qu\'une bonne partie semble avoir été déplacée...>', },
    {'Parler à Sirra Von\'Indi à Sombre-Comté.', },
  },
  [226] = {
    'Des loups aux trousses',
    {'Sven et moi avons de difficiles journées qui nous attendent, avec ce Nécromancien à l\'est et tout le reste. Et ici, isolés comme nous le sommes, nous devons chasser pour nous procurer de la nourriture. Il semble que chaque fois que je rentre au campement avec un peu de viande sur moi, des loups sauvages affamés ou enragés me poursuivent en quête d\'un morceau. Cela va sans dire que vivre ici est une tâche ardue !|n|nMais si vous pouviez nous débarrasser de ces loups, vous nous rendriez les choses un peu plus simples. Ils rôdent pour la plupart au nord et à l\'est d\'ici, près de la rivière.', },
    {'Tuer 12 Loups redoutables affamés et 8 Loups redoutables enragés, puis retourner auprès de Lars au camp de Sven à la frontière ouest du bois de la Pénombre.', },
  },
  [227] = {
    nil,
    {'<Il cherche quelques instants sur les étagères puis en sort un livre relié en cuir.>|n|nSi vous voulez en savoir plus, vous devriez parler à Althea, c\'est elle qui s\'est occupée du… problème… avec lui ces derniers temps.', },
    {'Parler au commandant Althea Bouclenoire à Sombre-Comté.', },
  },
  [228] = {
    nil,
    {'D\'après ce que m\'ont rapporté mes Eclaireurs, Mor\'Ladim erre du côté du bois de la Pénombre. On le voit suivre un étrange chemin sinuant à travers le cimetière. Nous l\'avons enseveli après la maison sur la colline, vous voyez où c\'est ?|n|nIl n\'y a rien que je puisse faire pour vous venir en aide, mais je vous souhaite bonne chance.', },
    {'Tuer Mor\'Ladim, puis rapporter son crâne au commandant Althea Bouclenoire à Sombre-Comté.', },
  },
  [229] = {
    'La fille qui survécut',
    {'J\'aurais dû vous le dire plus tôt…|n|nComment puis-je m\'exprimer…|n|nIl se peut que Morgan ait cru que sa famille tout entière était morte, mais en fait sa fille Sarah est Gardien à présent. Elle a toujours été troublée par les… circonstances... entourant la mort de son père. Peut-être pourriez-vous lui donner des nouvelles.', },
    {'Parler au Gardien Sarah Ladimore à Sombre-Comté.', },
  },
  [230] = {
    'Le camp de Sven',
    {'En creusant, vous trouvez un petit livre, plein de terre.|n|nIl ne porte pas de titre, mais il contient des informations que Sven aimerait connaître.', },
    {'Apportez à Sven le Livre de la ferme de Sven.', },
  },
  [231] = {
    'L\'amour d\'une fille',
    {'Voilà, prenez ceci et posez-la sur sa tombe. Peut-être… je ne sais comment… comprendra-t-il que je vais bien, et que personne ne le considère responsable de ce qui est arrivé.|n|n<Les larmes perlent à ses yeux à présent, tandis qu\'elle enlève une bague de sa main droite, et la presse dans votre paume.>|n|nEt... merci, $N.', },
    {'Déposer la bague de Sarah Ladimore sur la tombe de Morgan Ladimore.', },
  },
  [232] = {
    'Course pour l\'apothicaire Zinge',
    {'La Société royale des apothicaires a besoin de vous. Écoutez attentivement et cela sera bénéfique pour nous deux.|n|nL\'apothicaire Keever dans l\'autre salle risque d\'être... vexé. Mais ses recherches porteraient leurs fruits si elles étaient faites par un chercheur plus intelligent. Heureusement, je suis cette chercheuse. Je veux que vous apportiez ce bon de commande à Alessandro Luca, le propriétaire du bazar de la Lune bleue. Il vous donnera une trousse d\'analyse. Quand vous l\'aurez, rapportez-la-moi et je vous expliquerai alors le détail de la quête.', },
    {'Apporter le bon de commande à Alessandro Luca à Fossoyeuse.', },
  },
  [233] = {
    'La distribution du courrier de la Vallée des Frigères',
    {'Hum, je ne pense pas que vous seriez $Gprêt:prête; à me rendre un petit service, si ? Une pile de lettres est arrivée au tri aujourd\'hui, mais je n\'ai pas le temps de les distribuer.|n|nElles ont toutes pour destinataire un dénommé Talin Œil-perçant. Vous pouvez le trouver à l\'ouest, sur la route. Il a établi son camp près du lac Gelé.|n|nQu\'en dites-vous ?', },
    {'Apporter la pile de lettres à Talin Œil-perçant dans la Vallée des Frigères.', },
  },
  [234] = {
    'La distribution du courrier de la Vallée des Frigères',
    {'Si je me souviens bien, le camp de Grelin se trouve plus bas sur la route, vers le sud-est. Il ne fait aucun doute qu\'il serait ravi de recevoir ce courrier.', },
    {'Remettre la lettre à Grelin Blanchebarbe dans la Vallée des Frigères.', },
  },
  [235] = {
    'La Chasse d\'Orneval',
    {'Votre attention ! Les terres sauvages d\'Orneval vous attendent tous !|n|nLa Horde s\'est établie dans les terres au nord des Tarides. Nos deux avant-postes : le Poste de Bois-Brisé et le Poste de la Grève de Zoram s\'efforcent bravement d\'apporter la gloire à la Horde ! Ceux et celles qui veulent faire montre de leur courage devraient y trouver conseil. De plus, Senani Cœur-de-tonnerre, au Poste de Bois-Brisé, directement au nord des Tarides, cherche en ce moment des candidats prêts à prendre part à une grande chasse en Orneval !', },
    {'Parler à Senani Cœur-de-tonnerre, au Poste de Bois-Brisé, en Orneval.', },
  },
  [236] = {
    'Gardien Callahan',
    {'$N ! Il était temps que vous arriviez. Cette bataille est peut-être terminée, mais nous devons nous préparer pour la prochaine. Rendez-vous au Chaudron des flammes, au sud-est de Joug-d\'hiver, et récupérez quelques braises éternelles.|n|nMélangées à du charbon, elles servent à alimenter les démolisseurs et les engins de siège.|n|nOh, et si vous voyez des membres de la Horde dans le Chaudron, n\'hésitez pas à les tuer pour leur prendre leurs braises. Nous ne pouvons pas les laisser prendre l\'avantage lors du prochain combat.', },
    {'Le Maître de siège Rudemanche, à la Forteresse de Joug-d\'hiver, vous a demandé de récupérer 10 Braises éternelles sur des personnages-joueurs de la Horde, au Chaudron des flammes.', },
  },
  [237] = {
    'Une frappe décisive',
    {'Le montagnard Pave-silex n\'a pas tari d\'éloges à votre égard, $R. Aussi, je vais vous confier une mission de la plus haute importance. Nous devons maintenir la pression sur les forces d\'invasion des troggs jusqu\'à ce que les nains, nos frères, reviennent du front de l\'Alliance.|n|nMettez-vous en route pour les collines méridionales et tuez 10 Brise-crâne et 10 Prophètes Brisepierre. Vos attaques nous feront gagner un temps précieux. Revenez me voir une fois votre mission menée à bien.', },
    {'Le Montagnard Gravegalle de la Tour de garde méridionale veut que vous tuiez 10 Brise-crâne et 10 Prophètes Brisepierre, puis que vous retourniez le voir.', },
  },
  [238] = {
    'Course pour l\'apothicaire Zinge',
    {'La trousse est prête, $N. L\'apothicaire Zinge souhaite sûrement l\'avoir le plus vite possible. Apportez-la-lui sans tarder et dites-lui que j\'ai mis cela sur le compte de la Société. Passez-lui également mes plus sincères salutations.|n|nEh bien, ne restez pas là. C\'est pourtant simple d\'être coursier, non ?', },
    {'Apportez une Trousse d\'analyse de terrain à l\'Apothicaire Zinge à Fossoyeuse.', },
  },
  [239] = {
    'Au secours de la garnison du ruisseau de l\'Ouest !',
    {'La garnison basée sur notre frontière à l\'ouest fait état d\'une augmentation de l\'activité des gnolls et des voleurs. Elle demande plus de soldats de Hurlevent, mais nous ne pouvons nous passer d\'aucun !|n|nSi vous le pouvez, votre aide sera la bienvenue. Allez voir l\'Adjoint Rainer à la garnison du ruisseau de l\'Ouest. Il vous dira de quoi il s\'agit.|n|nLa garnison se trouve le long de la route, à l\'ouest. Après avoir traversé le pont au-dessus du ruisseau, ce sera sur la droite.', },
    {'Se rendre à la Garnison du ruisseau de l\'Ouest et parler à l\'Adjoint Rainer.', },
  },
  [240] = {
    'Retour vers la Tremblote',
    {'Et nous y voilà. Des gâteaux au « crabe » façon Grual.', },
    {'Retourner voir la Tremblote avec des Tourtes au crabe de la Pénombre.', },
  },
  [241] = {
    '<TEST> HÉ MONSIEUR WILSON !',
    nil,
    {'Objectif', },
  },
  [242] = {
    nil,
    {'Throm-ka, $C. Il n\'y a pas de temps à perdre. Les orcs du clan Gueule-de-dragon ont fortifié leurs positions dans la vallée au sud d\'ici.|n|nIls n\'ont pas reconnu le mandat du Chef de guerre, ne nous laissant d\'autre solution que de les exterminer, afin qu\'ils ne salissent pas plus longtemps le nom de la Horde.', },
    {'Tuez 8 Écumeurs Gueules-de-dragon, 3 Gardiens Gueules-de-dragon et 1 Maître de guerre Gueule-de-dragon.', },
  },
  [243] = {
    'Sur le terrain',
    {'Vous allez vous rendre dans le désert de Tanaris, pour tester la consistance des tissus des basilics, des scorpides et des hyènes de la région. Récupérez des échantillons de tissus et placez-les dans la trousse d\'analyse ; certains ne conviendront sans doute pas. Il me faut huit échantillons corrects pour chacun des trois types de créatures.|n|nDe plus, les gobelins de Gadgetzan ont une source d\'énergie utilisable avec ce genre de trousse modifiée. Allez parler à l\'ingénieur en chef Vizisanie et récupérez-en pour la trousse.|n|nNe revenez me voir que si vous réussissez.', },
    {'Parler à l\'Ingénieur en chef Vizisanie à Gadgetzan afin d\'obtenir une source d\'énergie pour la trousse d\'analyse.', },
  },
  [244] = {
    'Des gnolls encombrants',
    {'Je vous salue, $C. On m\'a chargé de patrouiller sur ce bout de route. Bien qu\'elle soit sûre pour l\'heure, j\'ai vu des campements de gnolls au nord et à l\'est d\'ici.|n|nComté-du-Lac doit être mise au courant de ce rassemblement de forces ! Allez voir l\'Adjoint Feldon et informez-le. Faites-le, et je suis sûr qu\'il vous offrira la prime d\'un éclaireur.|n|nD\'ordinaire, Feldon inspecte les lieux au sud du pont menant à Comté-du-Lac.', },
    {'Informer l\'Adjoint Feldon au pont au sud de Comté-du-Lac, dans les Carmines.', },
  },
  [245] = {
    '[PÉRIMÉ]Les plaies à huit pattes',
    {'Je vous salue, $C. Peut-être avez-vous vu ces araignées qui ont envahi la frontière ouest ? Nous n\'avons pas les forces nécessaires à une attaque, et le commandant n\'a pas suffisamment d\'hommes pour en envoyer si loin de Sombre-Comté.|n|nCela me gêne de vous le demander, mais il semble que vous êtes de taille à vous en occuper. Je ne peux rien vous promettre de grande valeur, mais je vous récompenserai si vous parvenez à déloger ces horribles bestioles.|n|nOh, un petit conseil : évitez leur venin...', },
    {'Tuer 15 Araignées tisse-venin pygmées, puis rendre compte au Gardien Dodds dans le Bois de la Pénombre.', },
  },
  [246] = {
    'L\'appréciation du danger',
    {'Nous ne pouvons nous passer de personne, la présence de chacun est vitale ici. Pourtant, quelque chose doit être fait à propos de ces gnolls dont vous m\'avez parlé.|n|nPartez à leur recherche, au sud des Carmines. Harcelez-les, tuez tous ceux que vous pouvez et revenez m\'informer de leur nombre et du danger potentiel qu\'ils représentent. Vous trouverez le camp des gnolls le long de la route sud des Carmines.|n|nFaites-le pour l\'armée de Hurlevent, $N, et vous serez $Grécompensé:récompensée;.', },
    {'Tuez 10 Bâtards des Carmines et 6 Braconniers des Carmines, et allez faire un rapport à l\'Adjoint Feldon à Comté-du-Lac.', },
  },
  [247] = {
    'La chasse achevée',
    nil,
    nil,
  },
  [248] = {
    'En regardant plus loin',
    {'J\'ai observé la Tour d\'Ilgalar, et ai découvert que Morganth est entré en conflit avec les orcs au donjon de Guet-de-pierre. Je n\'en connais pas la raison, mais vous pourriez m\'aider à lever le voile sur ce mystère.|n|nPrenez donc le Glyphe d\'Azora, et rendez-vous au sommet de la Tour de garde restée intacte, près du donjon de Guet-de-Pierre.|n|nLà, trouvez un objet dans lequel placer le glyphe. Un coffre, une jarre, qu\'importe, pourvu que le glyphe ne puisse pas être détecté.', },
    {'Monter au sommet de la Tour de garde intacte près du Donjon de Guet-de-pierre, dans les Carmines.|n|nPuis trouver un récipient convenable où placer le Glyphe d\'Azora.', },
  },
  [249] = {
    'Grand magus Doane',
    {'Après une longue surveillance, j\'ai découvert les plans de Morganth.|n|nIl recherche la faux d\'Élune… et il se peut même qu\'il l\'ait déjà trouvée ! S\'il se l\'est appropriée, alors les Carmines et le royaume de Hurlevent tomberont bientôt sous son joug.|n|nJe ne suis pas prêt à l\'affronter, mais j\'ai peur qu\'il faille s\'en occuper dès à présent. Vous devez donc pénétrer dans la tour d\'Ilgalar, et combattre Morganth.|n|nRemportez la victoire, et apportez-moi son pendentif des ombres. Si vous réussissez, le royaume vous sera grandement redevable.', },
    {'Tuer Morganth,|n|npuis rapporter son Pendentif des ombres à Théocritus, à la Tour d\'Azora dans la forêt d\'Elwynn.', },
  },
  [250] = {
    'Une sombre menace se dessine',
    {'Grâce au Ciel, quelqu\'un s\'inquiète pour le barrage ! D\'abord la destruction du viaduc de Thandol, ensuite le pillage de Dun Modr ! Je suis sûr que le barrage est la prochaine cible des Sombrefers. La plus grande partie de mon détachement de sécurité a été dépêché sur le front de l\'Alliance, y compris mon meilleur inspecteur.|n|nC\'est pourquoi j\'ai besoin de vous, $N. J\'ai aperçu quelques sapeurs sombrefers près de la rampe est du barrage. Enquêtez sur place, et rapportez un indice.', },
    {'Enquêtez près de la rampe est du barrage et rapportez à l\'ingénieur en chef Hinderweir un indice qui permettrait de deviner les intentions des nains sombrefers.', },
  },
  [251] = {
    '[PÉRIMÉ]La traduction de la lettre d\'Abercrombie',
    {'Apportez la lettre que vous m\'avez donnée à Sirra Von\'Indi. C\'est un érudit en lettres anciennes. Si quelqu\'un ici peut traduire ce message, c\'est lui !', },
    {'Apportez la Lettre à Ello à Sirra Von\'Indi.', },
  },
  [252] = {
    'La traduction pour Ello',
    {'Bon sang ! Si ce qui est écrit là est vrai, alors ce qu\'a fait Abercrombie est… incroyable.|n|nVous devez la transmettre à Ello.|n|nEt faites vite, car je crains qu\'un sort funeste n\'avance déjà vers notre ville...', },
    {'Apportez la lettre traduite au seigneur Ello Bouclenoire.', },
  },
  [253] = {
    '[PÉRIMÉ]La fiancée de l\'Embaumeur',
    {'Le nom de l\'Embaumeur apparaît dans l\'une des histoires que se racontent les enfants. C\'était un alchimiste bon et généreux, rendu fou par la mort de sa femme, Eliza. Dans le but de la ressusciter, il utilisa la magie noire et plaça son propre cœur dans la poitrine de son épouse décédée.|n|nIl réussit à faire revivre Eliza... mais celle-ci était à présent désormais avide de chair humaine, et l\'Embaumeur dut se résoudre à l\'enterrer.|n|nSon cœur est son pouvoir. Trouvez la tombe d\'Eliza, récupérez son cœur, et rapportez-le-moi pendant qu\'il bat encore. Procédez ainsi et son pouvoir s\'éteindra.', },
    {'Trouvez la tombe d\'Eliza, retrouvez le cœur de l\'Embaumeur, puis retournez voir Ello Bouclenoire.', },
  },
  [254] = {
    'En creusant la terre',
    nil,
    nil,
  },
  [256] = {
    'ON RECHERCHE : Chok\'sul',
    {'Par décret du Magistrat de Thelsamar : Chok\'sul, l\'ogre que l\'on croit être l\'instigateur et le chef des attaques menées sur la ville de Thelsamar, sur le barrage de Formepierre et sur les excavations, est recherché mort, et mort seulement.|n|nLa récompense sera donnée à celui qui apportera la preuve de sa mort au Magistrat.|n|nLa dernière fois que Chok\'sul a été vu, il se trouvait au camp des ogres au nord-est de Loch Modan.', },
    {'Tuer Chok\'sul et rapporter sa tête au Magistrat Courtnez de Thelsamar.', },
  },
  [257] = {
    'La fanfaronnade d\'un chasseur',
    {'Vous voulez jouer $Gau plus malin:à la plus maligne; avec Daryl l\'Intrépide, hein ? Vous avez perdu d\'avance ! Bien sûr, vous êtes libre d\'essayer. Voilà un défi qui devrait être au-dessus de vos capacités, alors ne culpabilisez pas trop si vous n\'êtes pas à la hauteur.|n|nUn groupe de busards s\'est établi ici, au loch Modan. Pourquoi ne pas essayer d\'en désabuser quelques-uns ? Voilà le marché : si vous parvenez à remporter mon défi, je vous donne mon arc ou mon fusil.|n|n<Il vous jauge dédaigneusement.>|n|nVous n\'avez pas grand-chose à perdre, de toute façon...', },
    {'Tuez 8 Busards des montagnes et retournez auprès de Daryl le Jeune au Pavillon des Pérégrins.', },
  },
  [258] = {
    'Le défi d\'un chasseur',
    {'$Naf, c\'est ça ? Vous vous vantez d\'avoir réussi le premier test, pas vrai ? Comme je vous l\'ai dit, ce n\'était pas grand-chose.|n|nVous devriez vous essayer à la chasse au sanglier. Croyez-moi, cela n\'a rien à voir avec la chasse au sanglier de la vallée des Frigères, alors prenez vos précautions.|n|nEt ne soyez pas $Gdéçu:déçue; en cas d\'échec. Je vous donnerai ma chemise si vous réussissez !|n|nÀ propos, je vous ai déjà raconté comment j\'ai reçu ma célèbre cicatrice ? Non ? C\'était il y a deux ans...', },
    {'Tuez 10 Anciens sangliers des montagnes et retournez auprès de Daryl le Jeune au Pavillon des Pérégrins.', },
  },
  [259] = {
    nil,
    {'Salut, $N. J\'ai entendu parler de vos exploits, et je dois admettre que c\'est un honneur pour moi de vous rencontrer. Je ne crois pas que vous connaissiez l\'histoire du vieux Kelt ? Eh bien, fut un temps où le vieux Kelt – Kelt Thomasin, tel est son nom – était considéré comme le meilleur chasseur du royaume. Peu de proies lui échappaient. Mais un jour, il devint totalement obnubilé par une histoire ancienne... un mythe. En fait, selon cette histoire, un énorme battrodon vivrait dans les eaux du lac. Balivernes, si vous voulez mon avis. Mais si cela vous intéresse, vous devriez parler à Kelt.', },
    {'Parler à Kelt Thomasin.', },
  },
  [260] = {
    nil,
    {'Bien, cela vous convaincra sans aucun doute que je suis, comme ils disent – et ne démentez pas, je sais ce qu\'ils disent – un esprit confus, obsédé par une légende improbable. Il s\'agit d\'un vieux conte nain, qui parle d\'un monstre gigantesque vivant dans les profondeurs du loch. J\'ai passé une bonne partie de ma vie à essayer de le traquer, et je n\'en étais pas loin, mais hélas mon âge avance plus vite que moi à présent. Si vous voulez chasser le monstre du loch, apportez-moi des dents et des griffes de battrodon.|n|n<Il sourit mystérieusement.>', },
    {'Rassembler 5 Dents et 5 Griffes de battrodon, puis les apporter à Kelt Thomasin.', },
  },
  [261] = {
    'Sur le chemin écarlate',
    {'Je serai franc. Nous sommes en guerre contre le Fléau. C\'est un mal qui corrompt notre peuple et pollue nos terres. Il faut l\'arrêter avant qu\'il ne nous prenne de vitesse et n\'entraîne notre monde dans l\'obscurité. Nous, la Croisade écarlate, avons juré de combattre le Fléau de toutes nos forces et de toute notre âme.|n|nSi vous êtes de notre bord, faites montre de votre courage et prouvez-nous votre allégeance en détruisant les Ravageurs morts-vivants de Désolace, dans la vallée des Ossements, plus au sud.|n|nFaites cela et la Croisade vous portera en haute estime.', },
    {'Détruire 30 Ravageurs morts-vivants, puis retourner voir Frère Anton, à la Combe de Nijel.', },
  },
  [262] = {
    'La silhouette mystérieuse',
    {'Je dois savoir qui était ce rôdeur que j\'ai vu dans les ombres, la nuit où ma famille a été tuée !|n|nJe vous en prie, $N, vous avez montré que vous êtes $Gplein:pleine; de ressources, trouvez cet individu. Je dois apprendre les secrets qu\'il détient !|n|nJe n\'ai aucun autre indice que vous ne connaissiez déjà, mais tenez, prenez le livre que vous avez trouvé à la ferme. Peut-être quelqu\'un pourra-t-il faire un lien entre ce livre et son propriétaire.', },
    {'Montrer le livre que vous avez trouvé à la ferme de Sven aux habitants de Sombre-Comté.', },
  },
  [263] = {
    'Une frappe décisive',
    {'Les montagnards disent que vous êtes $Gcourageux:courageuse; et $Gcompétent:compétente;, $N. Nous avons besoin de gens tels que vous ici. Le problème avec les troggs ne s\'arrange pas. Les réservistes ont été envoyés au front et nous sommes seuls. Mais à présent que nous avons $Gun:une:c; $C $Gexpérimenté:expérimentée:c; comme vous, nous allons voir de quoi vous êtes capable.|n|nAllez tuer huit chamans et huit briseurs d\'os brisepierre. Vous en trouverez à proximité des cavernes, dans les montagnes du sud. Nous allons voir si votre réputation est fondée, $Gtueur:tueuse; de troggs.', },
    {'Le Montagnard Cognemur de la Tour de garde méridionale veut que vous tuiez 8 Chamans et 8 Briseurs d\'Os brisepierre.', },
  },
  [264] = {
    'Jusqu\'à ce que la mort nous sépare',
    {'Ordure abjecte ! Me laisser pour cette maudite croisade. Parce que « la Lumière est notre bien le plus précieux contre la menace des morts-vivants ».|n|nEt ses enfants alors ? Et MOI ? Nuit après nuit, je l\'ai attendu… à toujours passer après son fichu devoir !|n|nEh bien ! Regardez ce que la « justice » apporte, $N ! Il est mort et je porte sur moi ce qu\'il essayait d\'arrêter !|n|nPortez ce bout de ferraille sur sa tombe au Sépulcre. Je ne veux plus rien avoir à faire avec ça... ni avec lui !', },
    {'Placer le pendentif de Clarice sur la tombe de Yuriv, dans la forêt des Pins-Argentés.', },
  },
  [265] = {
    'La mystérieuse recherche se poursuit',
    {'Je vous rends votre livre, $N, et vous souhaite bonne chance dans vos recherches. Si vous enquêtez auprès d\'autres personnes en ville, elles seront peut-être en mesure de vous fournir d\'autres indices.|n|nEn attendant, en voici un : bien que l\'auteur de ce livre soit étranger à Sombre-Comté, le livre lui-même a été acheté ici.', },
    {'Voir si d\'autres habitants ont des indices concernant la Silhouette mystérieuse.', },
  },
  [266] = {
    '[PÉRIMÉ]Une enquête à l\'auberge',
    {'Voici votre livre, et bonne chance dans votre quête.|n|nVous devriez aller jusqu\'à l\'auberge. Si celui que vous recherchez a passé quelque temps en ville, on l\'a peut-être vu là-bas.', },
    {'Chercher à l\'auberge des indices concernant la Silhouette mystérieuse.', },
  },
  [267] = {
    'La menace trogg',
    {'$C, il se peut que vous ayez entendu parler de la menace que les troggs font peser sur les nains. Les réservistes ayant été appelés pour servir sur le front de l\'Alliance, nous nous retrouvons avec bien peu de forces pour assurer la sécurité de nos terres. Mon régiment a pour mission de garder la porte, ici, et nous ne pouvons quitter notre poste, nous craignons trop une invasion.|n|nMais nous devons attaquer ces maudits troggs, qui se terrent dans les collines. Si vous vous en sentez capable, lancez un assaut contre eux. Rapportez-moi huit dents de pierre de trogg comme preuve de votre réussite.', },
    {'Rapportez 8 Dents de pierre de troggs au Capitaine Rudagite à la Tour de garde méridionale.', },
  },
  [268] = {
    'Retourner voir Sven',
    {'Le livre que vous avez trouvé n\'était écrit qu\'à moitié. J\'ai dû le laisser à l\'exploitation de Sven lorsque je me suis enfui jusqu\'ici…|n|nTenez, prenez la version complète de mon journal et donnez-la à Sven. Il décrit de manière plus exhaustive ce qu\'il s\'y est déroulé.|n|nCe journal a été ma seule compagnie durant ces dernières semaines, mais je vous le donne volontiers si cela m\'épargne d\'affronter Sven et sa colère.', },
    {'Retourner voir Sven avec le journal complété de la Tremblote.', },
  },
  [269] = {
    'À la recherche de la sagesse',
    {'Rendez-vous à la cité de Hurlevent et parlez à l\'évêque Farthing dans la cathédrale de la Lumière. Donnez-lui le journal de la Tremblote et dites-lui que vous voulez combattre Morbent Lagangrène.|n|nBien que Hurlevent ait abandonné Sombre-Comté, Farthing est un homme aimable et empli de sagesse. Il pourrait vous aider dans votre quête pour nous sauver.|n|nVotre mission est périlleuse, mais hâtez-vous, $N. À chaque heure qui s\'écoule, le bois de la Pénombre s\'assombrit encore...', },
    {'Donner le Journal complété de la Tremblote à l\'évêque Farthing à Hurlevent.', },
  },
  [270] = {
    'La Flotte perdue',
    {'Il y a des années, la IIIe flotte de Kul Tiras a coulé le long des côtes des Paluns, une étendue marécageuse située au nord du royaume nain de Forgefer. Un vaisseau avait à son bord un chargement de fer de sancteforge.|n|nLes objets forgés dans ce métal précieux frappent avec la force de la sainte vérité. Si vous devez combattre Morbent Lagangrène, vous aurez besoin d\'une telle arme.|n|nAllez au port de Menethil, et rencontrez mon confrère le nain Glorin Front-d\'acier. S\'il existe une chance de retrouver ce précieux métal, il vous indiquera où le chercher.', },
    {'Aller au port de Menethil, dans les Paluns, et parler à Glorin Front-d\'acier.', },
  },
  [271] = {
    'La vengeance de Vyrin',
    {'Je suppose que vous ne seriez pas contre le fait de rabattre un peu le caquet de Monsieur le Brave ? Daryl a une certaine habileté, il nous le serine assez.|n|nIl y a un an, un grand ours était dans le collimateur du pavillon des Pérégrins, mais pas un chasseur ne réussissait à le tuer. Alors Daryl s\'est dit qu\'il allait s\'en occuper. La seule chose qu\'il y a gagnée, c\'est cette vilaine cicatrice à l\'œil.|n|nTuez cet ours, ça clouera le bec de Daryl, pour une fois.|n|nVous trouverez cet ours, le vieux Noiraud, près de sa tanière dans la caverne, au nord.', },
    {'Tuer le Vieux Noiraud puis montrer le résultat à Daryl le Blanc-bec au pavillon des Pérégrins.', },
  },
  [272] = {
    'L\'épreuve du lion de mer',
    {'Pour la seconde épreuve, vous aurez besoin des deux moitiés qui constitueront le Pendentif du lion de mer. L\'une des moitiés emprunte au lion de mer son agilité à glisser à travers les eaux. L\'autre moitié emprunte à l\'animal son incroyable endurance. Les druides doivent revêtir ces deux aspects pour pouvoir adopter leur forme aquatique.|n|nAllez parler aux résidents de Reflet-de-Lune pour apprendre où les deux parties se trouvent, puis rapportez-les ici, afin de pouvoir les joindre ensemble. Quand vous aurez formé le pendentif, apportez-le à Dendrite Brasétoile.', },
    {'Trouvez le Demi-pendentif d\'agilité aquatique et le Demi-pendentif d\'endurance aquatique. Parlez aux habitants de Reflet-de-Lune pour obtenir des indices quant à l\'endroit où ces objets se trouvent.|n|nReformez le Pendentif du lion de mer à partir des deux moitiés. Vous devez vous trouver à proximité du sanctuaire de Remulos pour faire cela.|n|nApportez le Pendentif reformé à Dendrite Brasétoile, au village de Havrenuit, à Reflet-de-Lune.', },
  },
  [273] = {
    'Approvisionnement du site de fouilles',
    {'Cependant, il n\'est pas trop tard, votre aide est la bienvenue pour prêter main-forte à Huldar. Il ne peut pas être très loin : aussi forts qu\'ils soient, Miran et Saean ne peuvent pas se déplacer très vite avec les barils dont ils sont chargés.|n|nIls ont pris la route habituelle pour aller au site, celle qui suit la courbe du lac au sud de la ville.|n|nÇa ne devrait pas poser de problème de les rattraper à moins qu\'ils ne soient déjà arrivés.', },
    {'Aller voir Huldar.', },
  },
  [274] = {
    'Une sombre menace se dessine',
    {'Maintenant, apportez vite cette mixture à l\'ingé-chef. Les Sombrefers ne vont pas tarder à agir, donc pas question de musarder.', },
    {'Ashlan Rictus-de-pierre vous demande de retourner voir l\'Ingénieur en chef Hinderweir pour lui remettre le Colloïde de désamorçage.', },
  },
  [275] = {
    'Fièvre sur le pays',
    {'Je ne sais pas pourquoi, mais il y a une prolifération maligne dans les Paluns. Les Rampants des tourbières se manifestent. Ils sont malades et répandent leur fièvre partout. Pour circonscrire l\'épidémie, ils doivent être dispersés et renvoyés dans les marécages.|n|nLes Rampants des tourbières divaguent dans les voies navigables des Paluns.', },
    {'Tuer 8 Rampants des tourbières, puis retourner voir Rethiel le Gardien vert, dans les Paluns.', },
  },
  [276] = {
    'Piétinements de pattes',
    {'Les gnolls poils-moussus ont vécu paisiblement dans les Paluns pendant longtemps, mais aujourd\'hui leur nombre augmente. Les buissons et les fleurs du marais ne leur suffisent plus, et pour alimenter leurs feux, leurs haches crasseuses coupent trop de bois.|n|nL\'équilibre naturel n\'est plus respecté. Pour la survie des Paluns, le nombre de gnolls doit être réduit.|n|nTuez quinze gnolls poils-moussus et dix bâtards poils-moussus. Chassez-les au sud, près des nains de la Porte d\'Algaz. Lorsque vous aurez terminé, revenez me voir.', },
    {'Tuez 15 Gnolls poils-moussus et 10 Bâtards poils-moussus puis retournez voir Rethiel le Gardien vert, dans les Paluns.', },
  },
  [277] = {
    'Feu interdit',
    {'Les Poils-moussus coupent les arbres des Paluns et les brûlent pour se chauffer. Je ne le supporte plus !|n|nAllez leur prendre leurs silex bruts, les outils qu\'ils utilisent pour faire du feu. À l\'exception des simples gnolls et des bâtards, tous les Poils-moussus portent des silex.', },
    {'Rapportez à Rethiel le Gardien vert 9 Silex bruts.', },
  },
  [278] = {
    'Une sombre menace se dessine',
    {'Commencez immédiatement à rassembler les matériaux de désamorçage, $N. Le venin de rôdeuse peut être obtenu sur les araignées du loch Modan et vous trouverez les larmes de crocilisque dans les eaux du loch. Par contre, le cristal mo\'grosh sera plus difficile à obtenir. Les ogres au nord-est en extraient dans leurs mines, mais c\'est un minerai très rare.|n|nNous devons être prêts à enrayer une attaque des Sombrefers ! Revenez quand vous aurez collecté les ingrédients requis.', },
    {'Ashlan Rictus-de-pierre, au Camp des Mo\'grosh, veut que vous collectiez du Venin de rôdeuse, du Sang de furie et un Cristal mo\'grosh.', },
  },
  [279] = {
    'Les griffes des profondeurs',
    {'Les murlocs sortent des eaux profondes et construisent leurs villages sur le littoral. Ils harcèlent nos pêcheurs et nos marchands, et il faut les arrêter.|n|nL\'un de ces murlocs, Enfourneur, tend des embuscades aux marchands le long de la route, avec d\'autres Branchies-bleues, et va ensuite se réfugier dans les taudis voisins. Nos marchands sont en danger et nous sommes prêts à payer pour les protéger.|n|nEnfourneur rôde le long du fleuve au nord d\'ici. Trouvez-le, éliminez sa famille et apportez-moi sa tête.', },
    {'Tuer 12 Murlocs Branchies-bleues.|n|nTuer Enfourneur et prendre sa tête.|n|nL\'apporter à Karl Boran au port de Menethil.', },
  },
  [280] = {
    'Une sombre menace se dessine',
    {'Tout à l\'heure, j\'ai découvert quelques insurgés sombrefers qui nageaient vers le barrage avec un tonnelet. Aucun Montagnard n\'était présent pour les arrêter ! J\'ai bien peur qu\'ils n\'aient placé de l\'hydroglycérine à la base du barrage et ça pourrait exploser à tout moment !|n|nMaintenant, j\'ai besoin de vous pour prendre ce produit et le mélanger au contenu du tonnelet avant qu\'il ne soit trop tard ! Vite !', },
    {'L\'Ingénieur en chef Hinderweir vous demande de nager jusqu\'à la base du barrage pour localiser le tonnelet de poudre et d\'y verser la mixture de désamorçage pour empêcher une explosion.', },
  },
  [281] = {
    'Récupération de marchandises',
    {'Il y a peu, un navire marchand, la « Princesse aveugle », a été attaqué par des murlocs. Même si le navire a pu s\'échapper avec son équipage, la majeure partie de la cargaison a été jetée par-dessus bord par les créatures. Une statuette très précieuse à l\'effigie de Terenas Menethil se trouvait dans l\'une des caisses. Nous devons la récupérer.|n|nFouillez les taudis des murlocs le long de la côte et inspectez les caisses, tonneaux et tout ce qui ressemble à de la marchandise volée. Retrouvez la statuette de Menethil et rapportez-la-moi.', },
    {'Rechercher les caisses et les barils dans les camps murlocs le long de la côte.', },
  },
  [282] = {
    'Les observations de Senir',
    {'Je projetais d\'envoyer mon apprenti apporter mon rapport à mon frère Senir, mais je préférerais qu\'il soit placé entre des mains plus... fiables. Enfin, si vous êtes d\'accord, bien sûr !|n|nHum... Vous devrez prendre le tunnel pour arriver à Kharanos.|n|nAllez voir le Montagnard Thalos avant de traverser le tunnel. Il est complètement infesté de troggs maintenant.|n|nRetournez vers Courbenclume, puis continuez en prenant à l\'est vers le tunnel, Thalos n\'est pas loin.', },
    {'Aller voir le Montagnard Thalos.', },
  },
  [283] = {
    'Une sombre menace se dessine',
    {'Le tonnelet pétille légèrement.', },
    {'La Mixture de désamorçage semble avoir fonctionné. Retourner voir l\'Ingénieur en chef Hinderweir pour lui annoncer la bonne nouvelle.', },
  },
  [284] = {
    'La recherche continue',
    {'Vous avez fouillé avec soin les taudis murlocs dans ce secteur et vous n\'avez trouvé aucune trace de la Statuette de Menethil.|n|nIl y a peut-être davantage d\'indices dans les deux taudis qui se trouvent tout près de vous au nord et au nord-est.', },
    {'Rechercher la Statuette de Menethil.', },
  },
  [285] = {
    'À la recherche d\'autres taudis',
    {'L\'inspection minutieuse de ces quelques taudis murlocs n\'a rien donné, mais vous sentez que vous touchez au but.|n|nLa statuette de Menethil doit forcément se trouver dans l\'un des taudis situés au nord !', },
    {'Continuez à fouiller les taudis des murlocs pour retrouver la Statuette de Menethil.', },
  },
  [286] = {
    'Rapporter la statuette',
    {'Une fois le baril sorti de la boue et ouvert, on y trouve une figurine argentée empaquetée avec soin dans la paille. Elle représente un jeune paladin aux cheveux longs, qui brandit un marteau.|n|nCe doit être la Statuette de Menethil ! Vous devez maintenant l\'apporter à Karl Boran au port de Menethil.', },
    {'Apporter la Statuette de Menethil à Karl Boran au Port de Menethil, dans les Paluns.', },
  },
  [287] = {
    'Le repaire des Crins-de-Givre',
    {'Je suis sur mon rapport et j\'ai besoin de votre aide, $N. Je viens juste de trouver où se cachent les trolls, mais ils sont si nombreux que j\'ai peur d\'y aller.|n|nVoici ce que j\'attends de vous... Allez à la grotte, entrez, tuez quelques trolls et revenez ici.|n|nPrenez la route au nord de Kharanos, puis quand vous arriverez au pont, longez la rivière gelée par l\'ouest jusqu\'au Lac glacial. Vous trouverez le village de Brassetout sur la rive ouest. Leur repaire est au sud-ouest du village.', },
    {'Explorer le repaire des Crins-de-Givre et tuer 5 Chasseurs de tête crins-de-givre pour Senir Blanchebarbe à Kharanos.', },
  },
  [288] = {
    'La IIIe flotte',
    {'J\'étais autrefois le second de la « Maîtresse de l\'onde », l\'un des bateaux de la Troisième flotte de Kul Tiras. La Flotte perdue. Perdue parce qu\'à son dernier voyage, elle a été attaquée par des dragons rouges. Des dragons conduits par des orcs !|n|nNous n\'avions aucune chance contre le feu des dragons... Notre flotte a été brûlée et envoyée par le fond. Je suis le seul survivant de ces malheureux navires...|n|n... Oh ça cogne dans ma tête ! Il me faudrait un coup à boire pour supporter cette gueule de bois et continuer mon histoire.', },
    {'Achetez une Cruche d\'hydromel pour le Second Fitzsimmons.', },
  },
  [289] = {
    'L\'équipage maudit',
    {'<Revigoré, Fitzsimmons continue son histoire...>|n|nJe suis le seul survivant de l\'infortunée IIIe flotte de Kul Tiras, détruite au large de la côte, vers le nord. Mais bien que je sois le seul membre d\'équipage qui respire toujours, je ne suis pas le seul qui marche encore ! Car sur l\'un de nos bateaux a été caché un trésor épouvantable, dont le pouvoir énorme maintient prisonnières les âmes de mes frères d\'armes dans les épaves pourries de nos bateaux.|n|nMais si vous parveniez à libérer quelques-uns de mes frères, peut-être pourriez-vous briser la malédiction.', },
    {'Tuez 13 Marins maudits, 5 Soldats de marine maudits et le Second Snellig. Rapportez la Tabatière de Snellig au Second Fitzsimmons, au port de Menethil.', },
  },
  [290] = {
    'Lever la malédiction',
    {'Pour rompre la malédiction et libérer mes frères d\'armes, la... chose... qui se trouve sur mon bateau doit être récupérée et nettoyée ! Je ne sais pas ce que c\'est, mais je sais qu\'elle est en lieu sûr dans le coffre-fort du bateau, dont seul le capitaine Halyndor avait la clé.|n|nMon vieux capitaine rôde toujours dans mes rêves. Je sais qu\'il erre sur « l\'Intrépide », mon bateau perdu. Obtenez de lui sa clé et utilisez-la pour ouvrir le coffre de « l\'Intrépide ».|n|nEnsuite, quand vous aurez cet objet maudit, apportez-le au prêtre Glorin Front-d\'acier en ville.', },
    {'Obtenir du capitaine Halyndor la Clé du coffre-fort de « l\'Intrépide ».|n|nUtiliser la clé pour ouvrir le Coffre verrouillé de l\'Intrépide.', },
  },
  [291] = {
    'Les rapports',
    {'Excellent ! Apportez mon rapport au Sénateur Barin Rougepierre. C\'est un type plutôt aigri, alors ne vous laissez pas impressionner. Il est à Forgefer, dans la salle où se tient la cour du roi Magni.|n|nVous ne connaissez pas la route pour Forgefer ? Prenez la route au nord de Kharanos, traversez le pont, suivez ensuite la route de l\'est – il y a de grandes bannières le long de la route – jusqu\'en haut de la montagne.|n|nCela dit, si vous pouviez éviter de raconter que vous m\'avez aidé... Je ne veux pas qu\'ils pensent que je ne bosse pas assez dur ici, vous comprenez ?', },
    {'Livrer le rapport de Senir au Sénateur Barin Rougepierre à Forgefer.', },
  },
  [292] = {
    'L\'Œil de Paleth',
    {'En ouvrant le coffre, on trouve une sphère noircie, qui irradie une lumière à faire frémir. C\'est le trésor dont Fitzsimmons a parlé : un Oeil maudit de Paleth.|n|nApportez l\'Oeil maudit de Paleth au prêtre Glorin Front-d\'acier, un nain qui se trouve au port de Menethil. Demandez-lui comment lever la malédiction de l\'Oeil.', },
    {'Apportez l\'Oeil maudit de Paleth à Glorin Front-d\'acier au Port de Menethil, dans les Paluns.', },
  },
  [293] = {
    'Purifier l\'Œil',
    {'Je ne peux pas lever la malédiction de l\'Oeil de Paleth. Ces Yeux ont été fabriqués par des prêtres humains, vous devez donc aller à Hurlevent pour trouver quelqu\'un qui pourra vous aider. Allez voir l\'archevêque Benedictus, le maître de la cathédrale de la Lumière de Hurlevent. Il vous aidera.|n|nJe l\'espère pour vous.', },
    {'Apporter l\'Oeil maudit de Paleth à l\'archevêque Benedictus, à la cathédrale de la Lumière de la ville de Hurlevent.', },
  },
  [294] = {
    'La vengeance d\'Ormer',
    {'La situation est grave, c\'est indéniable. Les raptors ont été attirés par les ossements. Ces sales bêtes ont tué mes compagnons et nous ont coincés ici, Merrin, le pauvre Prospecteur et moi.|n|nAidez-nous à nettoyer les Paluns de ces raptors, $N. Il y a des raptors tachetés et des hurleurs tachetés à l\'ouest. Tuez-en 10 de chaque, si vous le pouvez.|n|nCe sera un bon début à la vengeance que je leur réserve.', },
    {'Ormer Tressefer, à l\'Excavation de Whelgar, vous demande de tuer 10 Hurleurs tachetés et 10 Raptors tachetés.', },
  },
  [295] = {
    'La vengeance d\'Ormer',
    {'Il est vraiment temps de faire payer à ces raptors leur soif sanguinaire. Un peu plus bas, il y a d\'innombrables faucheurs tachetés et tranchegueules tachetés. Vengez-moi de ces maudites créatures en en tuant 10 de chaque !', },
    {'Tuez 10 Faucheurs tachetés et 10 Tranchegueules tachetés pour Ormer Tressefer, puis allz le voir à l\'Excavation de Whelgar.', },
  },
  [296] = {
    'La vengeance d\'Ormer',
    {'Lorsque vous étiez là-bas, j\'ai remarqué qu\'un de ces monstres se tenait à l\'écart des autres. Il était plus grand et plus menaçant. Je parie que c\'est lui qui a incité les autres à venir ici interrompre les fouilles.|n|nJ\'ai une dernière chose à vous demander, $N. Faites en sorte que Grondecroc réponde de ses crimes à la justice. Et compte tenu de la gravité de ses crimes, la justice dans ce cas, c\'est la mort ! Apportez-moi une de ses serres pour preuve de sa mort.', },
    {'Ormer Tressefer, de l\'Excavation de Whelgar, vous demande de tuer Grondecroc et de revenir avec l\'une de ses serres une fois la tâche accomplie.', },
  },
  [297] = {
    'Réunir les idoles',
    {'Récemment, juste avant que les troggs ne débarquent sur le site, nous avons découvert un grand nombre d\'étranges idoles taillées. Mais nous n\'avons pas eu le temps de les étudier, car les troggs nous ont chassés des ruines juste après ! Et ces idoles ont un curieux effet sur les troggs : elles les rendent fous furieux !|n|nRapportez-moi huit de ces idoles. Je veux les étudier et il ne faut pas qu\'elles restent aux mains des troggs ! Vous les trouverez sur les troggs qui infestent le site.', },
    {'Apportez 8 Idoles de pierre sculptée à Magmar Tombebranche aux Excavations de Baguefer.', },
  },
  [298] = {
    'Compte rendu d\'avancement des fouilles',
    {'Je dois envoyer un compte rendu d\'avancement à Thelsamar et une nouvelle demande pour avoir plus d\'explosif ! Voici le rapport. Portez-le à Jern Casque-à-cornes. C\'est notre contact local à Thelsamar.|n|nCe n\'est pas une tâche difficile, mais ça doit être fait.', },
    {'Apporter le Compte rendu d\'avancement de Baguefer à Jern Casque-à-cornes à Thelsamar.', },
  },
  [299] = {
    'Découverte du passé',
    {'Avant l\'invasion, j\'ai découvert une tablette appelée la Pierre de Goaz. Elle s\'est brisée en quatre morceaux. Elle parle d\'un « plan divin » et d\'une « prophétie damnée ».|n|nJe crains que nous n\'ayons pas beaucoup de temps. Je suis trop vieux pour aller affronter ces bêtes. Mais vous êtes solide.|n|nExplorez le site de fouilles et cherchez les 4 fragments : Ados, Modr, Golm et Neru. Cherchez dans les artéfacts anciens, ou bien là où le sol est meuble. Apportez-les, que je puisse résoudre le mystère !', },
    {'À la demande du prospecteur Whelgar, parcourir les Excavations à la recherche des 4 fragments de tablette manquants : Ados, Modr, Golm et Neru.', },
  },
  [301] = {
    'Rapport à Forgefer',
    {'Nous aurons besoin d\'une autorisation pour fournir à Baguefer plus d\'explosif. Vous devrez apporter son rapport au quartier général de la Ligue des Explorateurs à Forgefer.|n|nVoici ce rapport. Donnez-le au Prospecteur Foudrepique et mettez-vous à l\'abri juste après ! Foudrepique est impétueux et il ne sera pas ravi d\'apprendre que Baguefer ne progresse que lentement sur le site.|n|nVous trouverez Foudrepique à l\'Assemblée des Explorateurs.', },
    {'Porter le Compte rendu d\'avancement de Baguefer au Prospecteur Foudrepique.', },
  },
  [302] = {
    'De l\'explosif pour Baguefer',
    {'Si Baguefer a encore besoin d\'explosif, par Magni, alors il l\'aura ! J\'ai envoyé un messager à Thelsamar avec une autorisation pour Jern Casque-à-cornes. Il préparera la poudre et du matériel à remettre à Baguefer.|n|nEncore une chose : je veux que vous assuriez personnellement la livraison pour que l\'explosif arrive à bon port. Le dernier chargement n\'y est pas arrivé, alors gardez l\'esprit vif et les yeux ouverts.', },
    {'Parler à Jern Casque-à-cornes à Thelsamar.', },
  },
  [303] = {
    'La guerre contre les Sombrefers',
    {'La guerre fait rage ici autant qu\'à l\'étranger. Tandis que nos valeureux nains donnent leur vie loin de chez eux au nom de l\'Alliance, nos propres terres sont la proie des nains sombrefers. Ils ont eu raison du viaduc de Thandol. Dun Modr est tombé peu après.|n|nNous avons besoin de vous pour reprendre des forces et repousser le front. Si vous pouvez tuer dix nains sombrefers, cinq tunneliers, cinq saboteurs et cinq démolisseurs, nos réservistes pourront être là à temps pour conduire l\'offensive.|n|nFaites vite !', },
    {'Motley Garmaçon de Dun Modr vous demande de tuer 10 Nains sombrefers, 5 Tunneliers sombrefers, 5 Saboteurs sombrefers et 5 Démolisseurs sombrefers.', },
  },
  [304] = {
    'Une tâche sinistre',
    {'Beaucoup de mes soldats sont morts à la bataille de Dun Modr. Mon propre frère a péri lors de la destruction du pont de l\'ouest du viaduc de Thandol. Oui, les nains sombrefers sont une race diabolique. D\'après ce que Roggo a réussi à apprendre, le chef de la bande de nervis qui se trouve dans les Paluns est un démoniste du nom de Balgaras le Crasseux. Et c\'est un véritable lâche. Il envoie ses soldats en première ligne, mais il reste caché dans son camp sur la colline de Morneforge, au sud-est.|n|nSi vous parvenez à trouver cette racaille, exécutez-le et rapportez-moi son oreille, je vous récompenserai, $C.', },
    {'Tuer Balgaras le Crasseux et rapporter son oreille à Tresse-longue le Macabre à Dun Modr.', },
  },
  [305] = {
    'À la recherche de l\'équipe de fouilles',
    {'Oh ça alors ! Vous devez être l\'éclaireur que Tresse-longue a promis d\'envoyer ! Vous ne pouvez pas imaginer mon inquiétude.|n|nMa femme, Merrin, m\'envoie des lettres toutes les semaines depuis le mois dernier. Elle fait partie de l\'équipe de fouilles de Whelgar. Mais il s\'est écoulé presque deux semaines depuis sa dernière lettre. Il y a sûrement quelque chose qui ne va pas !|n|nTresse-longue a dit qu\'il enverrait un éclaireur aux nouvelles si nous n\'avions pas rapidement du nouveau. Je suppose que l\'éclaireur, c\'est vous, $N. Allez voir Merrin à l\'Excavation, à l\'est !', },
    {'À la demande de Tarrel Tisseroche, aller jusqu\'aux Excavations et entrer en contact avec Merrin Tisseroche.', },
  },
  [306] = {
    'À la recherche de l\'équipe de fouilles',
    {'C\'était horrible ! Nous avions découvert quelques artéfacts rares et nous commencions à nous intéresser à ces grands ossements.|n|nAvant d\'avoir compris ce qui se passait, ces raptors marbrés ont déboulé sur le site. Il y a eu beaucoup de morts.|n|nC\'est Ormer – et avec quel courage ! – qui nous a sauvés, le Prospecteur et moi. Il nous a couverts pendant que nous courions nous mettre à l\'abri. Maintenant nous sommes pris au piège. Et nous avons perdu le fruit de notre dur labeur.|n|nTenez, apportez cette lettre à mon cher Tarrel pour lui expliquer la situation.', },
    {'Retourner voir Tarrel Tisseroche avec la lettre de Merrin au Port de Menethil, dans les Paluns.', },
  },
  [307] = {
    'Bas les pattes !',
    {'La mine du Ru d\'argent à l\'est est épuisée depuis longtemps. Elle a été convertie en dépôt de stockage par la Ligue des mineurs, mais aujourd\'hui les kobolds s\'y sont installés, et ils mettent leurs sales pattes sur nos bons vieux outils !|n|nNous chasserons bientôt cette vermine de là, mais avant d\'envoyer des guerriers qui feront forcément un peu de casse, la Ligue veut que quelqu\'un aille chercher son équipement. Ce ne sera pas facile, vous pourriez avoir besoin de l\'aide d\'alliés.|n|nL\'équipement de mineur est stocké dans les caisses de la Ligue des mineurs un peu partout dans la mine. Bonne chance !', },
    {'Allez à la Mine du Ru d\'argent pour prendre 6 lots d\'Équipement de mineur.|n|nRetournez voir le Montagnard Foudrepique.', },
  },
  [308] = {
    'Distraire Jarven',
    nil,
    nil,
  },
  [309] = {
    'Protection de la cargaison',
    {'Nous devons apporter cette poudre à Baguefer, mais ce chariot est immobilisé. La cargaison est trop lourde et trop dangereuse pour que nous la portions nous-mêmes, et qui sait ce que les Sombrefers nous réservent, maintenant que Saean est de leur côté ?|n|nJe me sentirais mieux si vous m\'aidiez à surveiller le chariot, le temps que Miran livre les autres tonnelets de poudre.', },
    {'Protégez Huldar et la Caravane de Baguefer, puis informez le Prospecteur Baguefer de la situation.', },
  },
  [310] = {
    'Bières rivales',
    {'Je dois admettre que ces Tonnebière font quelques bonnes boissons. Mais il faut qu\'ils comprennent qu\'ils ne sont pas les seuls brasseurs ! Vous pouvez peut-être m\'aider à faire passer le message...|n|nTenez, prenez ce tonneau de Brasselorge Scalder. Glissez-vous dans le sous-sol de la distillerie Tonnebière, à Kharanos, et échangez-le avec un de leurs tonneaux de Tonneblonde. Nous verrons bien si leurs clients préfèrent leur recette ou la mienne !|n|nBien sûr, si les tonneaux sont gardés, il faudra peut-être distraire le garde...', },
    {'Aller au sous-sol de la distillerie Tonnebière à Kharanos et remplacer un Tonneau de Tonneblonde par un Tonneau de Brasselorge Scalder.', },
  },
  [311] = {
    'Retour chez Marleth',
    {'Après avoir mis un tonneau de chez Marleth Scalder dans la cave de la Distillerie Tonnebière, vous emportez un Tonneau de Tonneblonde pour prouver que vous l\'avez vraiment fait...', },
    {'Apportez le Tonneau de Tonneblonde à Marleth Brasselorge au Village de Brassetout.', },
  },
  [312] = {
    'La réserve volée de Tundra MacGrann',
    {'J\'avais un mois de réserves de viande séchée et salée que j\'avais stockées pour la saison froide. C\'était hors d\'atteinte des ours, dans une caisse fermée ! Mais pendant que j\'étais à la chasse au daim, cette bête, le Vieux Barbeglace, est venue et repartie avec ma caisse de viande. Il ne sera pas capable de défoncer le thorium de la caisse. Mais je vais mourir de faim si je ne peux pas récupérer mes réserves de viande.|n|nVous semblez plus discret que moi. Peut-être parviendrez-vous à récupérer ma caisse ? Je n\'arriverai jamais à entrer et sortir assez vite de cette caverne avec ma jambe qui se traîne.', },
    {'Récupérer la caisse de viande séchée de Tundra MacGrann dans la Caverne du Vieux Barbeglace.', },
  },
  [313] = {
    'Redéploiement stratégique',
    nil,
    nil,
  },
  [314] = {
    'Protection du troupeau',
    {'Nous avons entendu des cris au milieu de la nuit. Et ce matin, il manquait deux béliers dans le troupeau. C\'est cette sale bête de Vagash qui s\'en est pris à notre gagne-pain. Comme les troupes de Forgefer sont en sous-effectif, il n\'y a personne pour tenir Vagash à distance.|n|nVous avez peut-être assez de courage pour poursuivre la bête et la tuer. Apportez-moi un de ses crocs et je vous récompenserai. Vagash se cache juste au-dessus de la ferme, mais soyez $Gprudent:prudente;, il est très dangereux.', },
    {'Obtenez le Croc de Vagash.', },
  },
  [315] = {
    'La bière brune parfaite',
    {'Je cherche à faire la bière brune parfaite. Je sais que je peux y arriver : le brassage, j\'ai ça dans le sang. Je dois juste trouver la bonne recette...|n|nLes trolls crins-de-givre cultivent une plante, la chatoyante, sur la crête Scintillante, au nord-ouest. Ils l\'utilisent dans leurs rituels tribaux. Nous, les nains, nous ne lui avons pas trouvé d\'usage, mais elle a un goût unique... Et je veux en mettre dans mon brassin !|n|nTrouver de la chatoyante sera dangereux, mais je vous payerai bien pour ce que vous pourrez « emprunter » dans les paniers à chatoyante des trolls.', },
    {'Apportez 7 brins de Chatoyante à Rejold Brasselorge, à Kharanos.', },
  },
  [316] = {
    '<INUTILISÉ 1>',
    nil,
    nil,
  },
  [317] = {
    'Ravitailler le Crache-vapeur',
    {'Je me prépare à entamer une mission pour la brigade des Sapeurs. C\'est une longue mission et j\'ai besoin de ravitailler le Crache-vapeur avec l\'équivalent d\'un mois de provisions. Alors pendant que Grillacier travaille sur mon réservoir, pouvez-vous aller chasser pour moi ?|n|nJ\'ai besoin de fourrure pour nos lits et de viande pour nous nourrir. Vous pouvez rapporter de la viande de sanglier et de la fourrure d\'ours... Vous trouverez l\'un et l\'autre dans les terrains enneigés au sud de l\'antre Gris.', },
    {'Réunir 4 morceaux de Viande de sanglier et 2 Fourrures d\'ours épaisses et les livrer au pilote Claquesoufflet au dépôt de Grillacier.', },
  },
  [318] = {
    'L\'éternol',
    {'Rejold Brasselorge fait des expériences de brassage. Certaines ont bon goût, d\'autres sont mauvaises et certaines... Eh bien, certaines mettraient par terre les plus vaillants des nains !|n|nCe brasseur habite à Brassetout, à l\'ouest de Kharanos, et j\'ai besoin de l\'une de ses boissons : l\'éternol. Ça me tiendra au chaud quand je serai sur les routes glacées.|n|nEt... ce liquide béni brûle si bien que je peux le jeter dans la chaudière du Crache-vapeur pour avoir un peu plus de puissance ! Cette petite tactique m\'a servi plus d\'une fois.', },
    {'Demander un tonneau d\'Eternol à Rejold Brasselorge au village de Brassetout.', },
  },
  [319] = {
    'Une faveur pour un tonneau d\'éternol',
    {'J\'ai un tonneau d\'éternol sous la main, mais... Pouvez-vous me faire une faveur ? Mon village aurait besoin d\'un coup de main pour se débarrasser des animaux sauvages qui errent dans les neiges voisines. Parfois ils rôdent tout près.|n|nNous n\'avons pas peur de ces oursons, de ces chats et de ces cochons – aucun nain digne de ce nom n\'en aurait peur – mais si vous pouviez vous occuper de ces bestioles, nous aurions plus de temps pour travailler.', },
    {'Tuer 6 Ours Griffeglace, 8 Anciens sangliers des rochers et 8 Léopards des neiges, puis retourner voir Rejold Brasselorge à Brassetout.', },
  },
  [320] = {
    'Retour vers Claquesoufflet',
    {'Voici votre tonneau d\'éternol, $N. Et merci encore pour la partie de chasse.', },
    {'Donner le Tonneau d\'éternol au Pilote Claquesoufflet au Dépôt de Grillacier.', },
  },
  [321] = {
    'Le fer de sancteforge',
    {'Les épaves qui se trouvent près du rivage sont les débris de la Flotte perdue de Kul Tiras, brûlée et coulée par les dragons rouges pendant la dernière Grande guerre.|n|nLa flotte venait de Lordaeron, mais il y avait aussi un destroyer elfique, « l\'Albatros ». Il transportait une cargaison de fer de sancteforge et avait rejoint la IIIe flotte pour profiter de sa protection. Ironie du sort, il a été coulé par les mêmes dragons...|n|nMais assez raconté d\'histoires. L\'épave de « l\'Albatros » est au sud du port de Menethil. Si vous trouvez du fer de sancteforge là-bas, apportez-le-moi.', },
    {'Fouiller l\'épave de l\'Albatros, dans les Paluns.', },
  },
  [322] = {
    'Béni soit ce bras',
    {'Il y a un nain, fabricant d\'armes dans le quartier des Nains de Hurlevent, qui sait travailler le fer de sancteforge. Il s\'appelle Grimand Elmore.|n|nJ\'ai emballé le métal que vous avez trouvé dans une caisse. Apportez-le à Grimand et racontez-lui votre histoire. Je suis sûr qu\'il est prêt à aider quiconque mène une quête comme la vôtre et il vous fabriquera une arme – une arme qui donnera du fil à retordre à Morbent Lagangrène lui-même !', },
    {'Apporter la Caisse de lingots de sancteforge à Grimand Elmore, à Hurlevent.', },
  },
  [323] = {
    'Prouver votre valeur',
    {'Morbent Lagangrène est un nécromancien, allié des Cavaliers noirs. Je pourrais vous envoyer le combattre, mais je dois d\'abord tester votre force avant que vous ne luttiez contre un tel adversaire.|n|nVous avez déjà prouvé votre bravoure, mais si vous voulez vraiment affronter le nécromancien, vous devez d\'abord montrer votre valeur contre ses sbires.', },
    {'Tuer 15 Écumeurs squelettes, 3 Soigneurs squelettes et 3 Gardiens squelettes puis retourner voir Sven.', },
  },
  [324] = {
    'Les lingots perdus',
    {'Puisque vous n\'avez trouvé qu\'un seul lingot de sancteforge dans le coffre, il paraît évident que les murlocs ont volé le reste. Pourchassez les écumeurs murlocs près de l\'épave de « l\'Albatros » pour retrouver le fer de sancteforge volé.', },
    {'Collecter 5 Lingots de sancteforge puis retourner voir Glorin Front-d\'acier, dans les Paluns.', },
  },
  [325] = {
    'En armes et prêt au combat',
    {'Voici l\'arme pour combattre le démon dont vous avez parlé. Vous pouvez y aller, $N. Je vous souhaite bonne chance et j\'attends avec impatience d\'entendre le récit vos exploits !', },
    {'Apportez le Fléau de Morbent à Sven, dans le bois de la Pénombre.', },
  },
  [326] = {
    nil,
    {'En toutes choses, un paladin doit réfléchir la Lumière qui amplifie nos forces. Il faut s\'efforcer d\'approcher la divinité. Cela ne veut pas dire qu\'il faut devenir un dieu, juste de faire en sorte que toutes nos actions soient empreintes de bonté.|n|nLes temps sont durs, et vous devez lutter contre le mal, mais souvenez-vous que c\'est en aidant les autres que vous vous distinguerez vraiment de la multitude. La compassion, la patience, la bravoure… toutes ces choses sont aussi importantes pour un paladin que la force au combat.|n|nN\'oubliez jamais cela.', },
    nil,
  },
  [328] = {
    'La clé cachée',
    {'Bien qu\'il ne soit jamais fait mention du soldat Thorsen dans ces rapports, une petite clé en cuivre était cachée dans un des registres d\'Hérode.|n|nEt en poussant plus loin l\'étude de ces notes, on trouve au milieu de divers papiers des références à un « coffre-fort sécurisé ». Il est quelque part dans la Réserve, l\'ensemble de cavernes qui se trouve derrière la base de Kurzen.|n|nSi nous retrouvons ce coffre-fort et que la petite clé peut l\'ouvrir, nous résoudrons peut-être le mystère de Thorsen.', },
    {'Utiliser la Petite Clé en cuivre pour ouvrir le Coffre-fort de Hérode la Paperasse.', },
  },
  [329] = {
    'L\'espion découvert !',
    {'Parmi les objets précieux contenus dans le coffre-fort, il y a une note griffonnée et couverte de boue. Bien qu\'elle soit à peine lisible, on dirait un itinéraire pour le soldat Thorsen. Il y a des détails sur ses itinéraires de patrouille, les gens auxquels il parle, ce qu\'il fait de son temps avec les rebelles. Elle n\'est signée que d\'une lettre : M.|n|nMais celui ou celle qui a écrit cette note doit être proche de Thorsen. Celui ou celle qui a écrit cette note est le traître du camp rebelle.', },
    {'Apporter la Note maculée de boue au lieutenant Doren, au Camp rebelle.', },
  },
  [330] = {
    'Composition des patrouilles',
    {'La note que vous m\'avez donnée est signée d\'un « M »... Je ne sais pas ce que ça signifie.|n|nMais... La note dit aussi que cette personne a partagé les tours de patrouille de Thorsen la semaine dernière. Le traître doit être l\'un de ceux qui ont patrouillé en même temps que Thorsen !|n|nAllez voir le caporal Sethman. C\'est lui qui gère la composition des patrouilles, il vous dira qui était avec Thorsen la semaine dernière.', },
    {'Parler au caporal Sethman.', },
  },
  [331] = {
    'Rapport au lieutenant Doren',
    {'Le lieutenant Doren a-t-il demandé que vous retourniez le voir avec cette information concernant les patrouilles ?', },
    {'Parler au lieutenant Doren.', },
  },
  [332] = {
    'Publicité pour la cave à vins Gallina',
    {'Si vous parlez à qui que ce soit de vin, vous apprendrez que nous, les Gallina, nous vendons le meilleur vin de Hurlevent. Et nous ne sommes pas loin, dans le Quartier commerçant, le long des superbes canaux de la ville.|n|nTenez, prenez ce bon d\'échange. Apportez-le à ma sœur Suzetta dans notre magasin, et elle vous offrira une bouteille de bienvenue de notre célèbre Dalaran noir. Vous ne le regretterez pas !', },
    {'Aller à la Cave à vins des Gallina et apporter à Suzetta Gallina le Bon pour une bouteille de vin gratuite.', },
  },
  [333] = {
    'Harlan a besoin d\'être approvisionné',
    {'Nous avons fait pas mal d\'affaires dernièrement. On dirait que tout le monde achète des armures et des vêtements résistants. Comme s\'ils s\'attendaient à une saison froide et dure...|n|nMais ce sont là des soucis pour plus tard. Mon souci aujourd\'hui, c\'est que je suis à court de vêtements tricotés à vendre. J\'ai besoin d\'un autre lot de mon fournisseur.|n|nSi vous pouviez en prendre livraison auprès de Rema Schneider, chez le tailleur et équipementier du canal, je vous en serais très reconnaissant.', },
    {'Aller à la Boutique de tailleur du canal et donner à Rema Schneider la Demande de tissu, pour Harlan Bagley.', },
  },
  [334] = {
    'Un paquet pour Thurman',
    {'Mon fils Thurman est apprenti chez les Couturiers Larson, dans le Quartier des mages. Il était pressé aujourd\'hui et il a oublié ses ciseaux et ses aiguilles. Je sais qu\'$Gun grand:une grande:c; $C comme vous a des tâches autrement plus importantes à accomplir, mais sans ses outils, Thurman ne peut pas faire son travail d\'apprenti !|n|nS\'il vous plaît, $N, pouvez-vous rapporter à mon fils son matériel de couture ? Les Couturiers Larson tiennent l\'un des deux magasins de prêt-à-porter du Quartier des mages, c\'est le plus éloigné, près de la Tour du mage.', },
    {'Aller chez les Couturiers Larson, dans le Quartier des Mages de Hurlevent, pour donner à Thurman Schneider son Matériel de couture.', },
  },
  [335] = {
    'Une bière noble',
    {'Le seigneur Wishock sème le trouble à la maison des Nobles. Il sait pour notre petit « établissement » et fait pression pour qu\'une enquête soit ouverte. J\'ai un plan pour « occuper » Wishock, mais je vais avoir besoin de votre aide.|n|nIl y a une fleur qui pousse dans le jardin de Stalvan aux environs de Sombre-Comté. On appelle cette petite fleur blanche la larme de Tilloa. J\'aurai aussi besoin d\'une racine de musquash, qu\'on ne trouve qu\'en bas des chutes du barrage de Formepierre, dans les Paluns.', },
    {'Zardeth de la Griffe noire veut que vous lui rapportiez une Larme de Tilloa de Sombre-Comté et une Racine de Musquash des Paluns.', },
  },
  [336] = {
    'Une bière noble',
    {'Le seigneur Wishock est comme tous les hommes, il a ses faiblesses. Il se trouve que la sienne est un penchant prononcé pour la bouteille. Quelle sidérante hypocrisie. Ce pauvre imbécile passe ses journées à essayer de faire fermer notre petite « taverne », et ses nuits à l\'étage à rallonger une ardoise qu\'il ne payera jamais. Eh bien nous allons voir comment Wishock apprécie la cuvée spéciale que je lui ai préparée : la bière brune de la Griffe noire. C\'est du brutal, $N.|n|nApportez-lui et voyez comment il réagit. Probable que ce vieil idiot soit en train de traîner autour de la chambre du Requérant.', },
    {'Apportez la Bière brune de la Griffe noire au Seigneur Wishock, dans la Chambre du requérant.', },
  },
  [337] = {
    'Un vieux livre d\'histoire',
    {'Bien que la couverture de ce livre soit éraflée et couverte de boue, on arrive à lire le titre « L\'Histoire de Hurlevent » sur la tranche. En l\'ouvrant, on voit clairement tamponné sur la première page le sceau de la Bibliothèque de Hurlevent.|n|nOn dirait que quelqu\'un a emprunté ce livre et ne l\'a jamais rendu...', },
    {'Rendre le livre « l\'Histoire de Hurlevent » à la Bibliothèque de Hurlevent.', },
  },
  [338] = {
    'Les vertes collines de Strangleronce',
    {'Maître Nesingwary va être tellement furieux s\'il découvre ça !|n|nIl m\'a fait confiance pour relire le manuscrit de son roman « Les vertes collines de Strangleronce ». Tout allait bien, mais une grande rafale de vent a soufflé sur le camp et a dispersé toutes les pages !|n|nJ\'ai pu en ramasser la plupart, mais certaines sont toujours perdues dans la jungle. Retrouvez les pages qui manquent pour compléter les quatre chapitres.|n|nJe vous aiderai à les remettre dans l\'ordre. Rendez-moi les chapitres une fois que vous les aurez tous les quatre.', },
    {'Rassembler les pages manquantes du manuscrit des « Vertes collines de Strangleronce ». Une fois les quatre chapitres complétés, les rendre à Barnil.', },
  },
  [339] = {
    'Chapitre I',
    {'Le Chapitre I était vraiment fascinant ! Maître Nesingwary plante le décor de l\'histoire et décrit ses compagnons de chasse, moi y compris !|n|nMais c\'est un détail. Laissez-moi voir s\'il manque des pages. On dirait que les pages 1, 4, 6 et 8 sont toujours quelque part dans la jungle !', },
    {'Rapporter les pages 1, 4, 6 et 8 des Vertes collines de Strangleronce de Nesingwary à Barnil Potepierre pour achever le Chapitre I.', },
  },
  [340] = {
    'Chapitre II',
    {'Le Chapitre II regorgeait de passionnants récits de chasse au tigre et à la panthère. Je me donnerais des coups pour avoir laissé les pages s\'envoler !|n|nJ\'ai récupéré toutes les pages à l\'exception des pages 10, 11, 14 et 16.', },
    {'Rapporter les pages 10, 11, 14 et 16 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre II.', },
  },
  [341] = {
    'Chapitre III',
    {'Le Chapitre III est mon préféré. Il parle de la première fois où le sire Erlgadin et dame Rouack ont tué avec un fusil des nains. Et la fin du chapitre, quel suspense !|n|nJe vois qu\'il nous manque encore les pages 18, 20, 21 et 24 pour clore le chapitre. Ces pages sont quelque part par là...', },
    {'Rapporter les pages 18, 20, 21 et 24 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre III.', },
  },
  [342] = {
    'Chapitre IV',
    {'Ah, le Chapitre IV : le grand final ! Et quel final !|n|nIl ne nous manque plus que trois pages, les 25, 26 et 27, pour compléter le Chapitre IV.', },
    {'Rapporter les pages 25, 26 et 27 des « Vertes collines de Strangleronce » de Nesingwary à Barnil Potepierre pour achever le Chapitre IV.', },
  },
  [343] = {
    'En parlant de fermeté',
    {'Je fais un discours sur la fermeté de l\'Esprit et je voudrais citer des passages d\'un livre sur la métallurgie : « Les Tensions du fer ». Un exemplaire de ce livre doit se trouver à la Bibliothèque royale, au Donjon de Hurlevent. Pouvez-vous le récupérer pour moi ? Si vous le faites, que la bénédiction de la Lumière soit sur vous !|n|nLa Bibliothèque royale est très grande, mais le responsable, Milton Sheaf, connaît chaque étagère comme sa poche. Parlez-lui, il cherchera le livre pour vous.', },
    {'Allez à la Bibliothèque royale au Donjon de Hurlevent pour parler à Milton Sheaf. Il trouvera le livre sur la métallurgie dont Frère Kristoff a besoin pour son discours.', },
  },
  [344] = {
    'Frère Paxton',
    {'« Les Tensions du fer » ? Oui, je connais ce livre. Excellent ouvrage, écrit par le mineur nain Margulf Blaggon il y a quelques décennies. Il a passé l\'essentiel de sa vie au cœur des montagnes de Khaz Modan, à creuser pour trouver du minerai. Chic camarade !|n|nMais où en étais-je ? Ah oui ! « Les Tensions du fer » ! J\'ai bien peur que le livre ait été envoyé à l\'abbaye de Comté-du-Nord. Le bibliothécaire de l\'abbaye, le frère Paxton, voulait faire une copie de l\'ouvrage pour sa propre collection.|n|nMais c\'était il y a plusieurs mois. Je me demande pourquoi ça lui prend si longtemps...', },
    {'Parler au frère Paxton, à l\'Abbaye de Comté-du-Nord.', },
  },
  [345] = {
    'Provisions d\'encre',
    {'J\'avais l\'intention de finir ma copie des « Tensions du fer », mais...|n|nEh bien vous voyez, je fabrique ma propre encre pour les livres que je copie. C\'est une recette personnelle : elle ne coule pas, ne tache pas et sèche très rapidement, voire trop rapidement ! Mon dernier lot a séché avant la fin de mon travail de copie et je n\'ai pas eu la possibilité d\'en refaire !|n|nPour en fabriquer davantage, j\'ai besoin de minerai de rethban qui vient des Carmines. Le contremaître Oslow de Comté-du-Lac est mon fournisseur habituel.', },
    {'Aller voir le contremaître Oslow de Comté-du-Lac et lui demander du minerai de rethban.', },
  },
  [346] = {
    'Retourner voir Frère Kristoff',
    {'Maintenant que j\'ai fini ma copie des « Tensions du fer », je vous rends l\'original. Merci pour votre patience et si vous voyez Milton, dites-lui que je suis désolé pour ce long retard.', },
    {'Retourner voir Frère Kristoff sur la Place de la Cathédrale. Lui donner le livre « Les Tensions du fer ».', },
  },
  [347] = {
    'Minerai de rethban',
    {'Le minerai de rethban a été découvert par Bart Rethban. Lorsqu\'il est fondu, ce minerai est moins dur que le fer, mais il possède une essence que certains scribes utilisent comme encre. Il peut être trouvé dans les Cavernes de Rethban, plus au nord.|n|nNous en avons normalement en réserve, mais devant nous préparer aux attaques des orcs, nous n\'avons pas eu le temps d\'en collecter dernièrement. De plus, les gnolls des Carmines occupent maintenant les cavernes de Rethban et leurs manouvriers y exploitent le minerai eux-mêmes.|n|nSi vous voulez en collecter, vous devrez le faire par vos propres moyens.', },
    {'Réunir 5 charges de Minerai de rethban et les apporter à Frère Paxton à la bibliothèque de Comté-du-Nord.', },
  },
  [348] = {
    'La fièvre de Strangleronce',
    {'Malade... Tellement... m-m-malade...|n|n... attrapé la fièvre de Strangleronce... V-v-virus mortel...|n|nSeul remède... est... est... manger le cœur de M-m-m-m-mokk le Sauvage... bête blanche... insaisissable...|n|n... Le féticheur Unbagwa... Lui seul peut invo... invoquer...|n|n... Allez chercher Unbagwa dans la caverne cachée dans le sud du cap...|n|n... vite...mourant... mourant...', },
    {'Chercher le Féticheur Unbagwa pour qu\'il invoque Mokk le Sauvage. Apporter le Cœur de Mokk à Fin Bulboucan.', },
  },
  [349] = {
    'La fièvre de Strangleronce',
    nil,
    {'temp text 02 - log', },
  },
  [350] = {
    'Le point de vue d\'un vieil ami',
    {'Ce Marzon va contacter un Défias et il est lié à Lescovar...|n|nEn ayant tué VanCleef et Thredd, il va être difficile de traîner en justice Lescovar, vu que vos preuves ne valent rien sans leurs témoignages. Sans compter que Lescovar est un noble et qu\'il a de nombreux appuis. Il est ainsi au-dessus des lois.|n|nVous avez besoin d\'une autre aide. Je répugne à le faire, mais voici quelqu\'un que je connais et qui peut nous aider. Vous trouverez Trias dans le Quartier commerçant de la cité.', },
    {'Parler à Elling Trias à Hurlevent.', },
  },
  [351] = {
    'Trouvez OOX-17/TN !',
    {'Vous avez découvert un étrange objet en forme d\'œuf fait de métal. En jouant avec les petits boutons présents sur le dessus, l\'œuf s\'anime, à mesure qu\'il s\'ouvre, il se transforme en une espèce de bidule robot gnome ! Une voix sort du robot en grésillant.|n|n« Je suis Orguignard Odipnoticus, et mon robot guidé a disparu ! Je vous récompenserai si vous le réparez ! Apportez cette balise au robot. Excellent, j\'ai programmé les coordonnées du robot pour vous ! Il s\'est écrasé près du Gouffre béant à Tanaris ! »', },
    {'Apportez la balise de détresse au robot guidé d\'Orguignard.', },
  },
  [352] = {
    nil,
    {'La Grande Mammoda. Énorme, qu\'elle était, avec des griffes et des dents comme des épées. Je n\'étais pas sur mes gardes, mais je ne pense pas qu\'être prêt m\'aurait beaucoup aidé. Un coup à toute volée et pff ! Le noir ! Ils disent que j\'ai de la chance de pouvoir remarcher aujourd\'hui...|n|nBon, pas très gaie comme histoire, hein, $N ? Mais si vous voulez quand même vous mesurer à elle, la Dame du Loch...', },
    nil,
  },
  [353] = {
    'Livraison pour Foudrepique',
    {'Les Foudrepiques sont un clan nain respecté et connu pour ses goûts raffinés et subtils. Ce n\'est donc pas surprenant que Gringer Foudrepique, un montagnard de Forgefer, m\'ait demandé de lui fabriquer une arme.|n|nL\'arme est terminée, mais Gringer vit loin d\'ici, près du Loch Modan. Si vous projetez de voyager vers le nord, pouvez-vous lui livrer ce paquet ?|n|nSon dernier message disait qu\'il se trouvait à la Tour de garde nord du Loch Modan.', },
    {'Livrer le Paquet au montagnard Foudrepique au Loch Modan.', },
  },
  [354] = {
    'Morts dans la Famille',
    {'Les Agamand étaient la famille la plus prospère des Clairières de Tirisfal. Je travaillais dans leurs moulins... avant la Peste.|n|nQuand le Fléau est apparu, les Agamand ont fortifié leur maison et convaincu leurs employés de rester et de les aider à se défendre. Nous étions des imbéciles, mais au moins nous étions des imbéciles loyaux.|n|nLes Agamand, à cause de leur orgueil, nous ont condamnés. Et maintenant le Fléau a fait d\'eux ses favoris !|n|nServez ceux qui ont été abandonnés en vainquant les Agamand qui sont tombés du côté de la Peste. Servez-moi en m\'apportant leurs restes.', },
    {'Rapporter les restes de Gregor, de Nissa et de Thurman à Coleman Farthing, à Brill.', },
  },
  [355] = {
    'Parler à Sevren',
    {'Vous m\'avez ramené les restes des Agamand et satisfait mon désir de vengeance. Mais les Moulins d\'Agamand sont une menace pour tous les Réprouvés, pas seulement moi.|n|nJ\'ai parlé au Magistrat Sevren de vos exploits contre les Agamand et il désire vous parler.', },
    {'Parler au magistrat Sevren à Brill.', },
  },
  [356] = {
    'Patrouille d\'arrière-garde',
    {'Ici à la Barricade, nous devons rester sans cesse en alerte pour protéger Tirisfal des incursions du Fléau. Et malgré tout, il arrive que le Fléau parvienne à se faufiler sous notre nez.|n|nNotre succès à la Barricade dépend d\'un front uni. Nous ne pouvons nous permettre d\'être attaqués par l\'arrière ou de voir les lignes d\'approvisionnement des défenseurs coupées.|n|nRenforcez la Barricade. Patrouillez à l\'ouest et détruisez toutes forces du Fléau que vous rencontrerez. Portez un effort particulier sur la ferme des Balnir. C\'est devenu un havre pour les forces du Fléau qui maraudent dans le secteur.', },
    {'Tuer 8 Horreurs sanguinolentes et 8 Esprits vagabonds.', },
  },
  [357] = {
    'Le nom de la Liche',
    {'Une liche réside dans l\'île au nord du lac Étincelant. Bien qu\'il s\'agisse d\'un Réprouvé disposant de son libre-arbitre, il croit que tous les autres morts-vivants sont des esclaves du Fléau et envoie ses serviteurs attaquer quiconque s\'approche de lui.|n|nMais parce que c\'est un Réprouvé, la Reine le veut. Et s\'il est doué dans les arts de la nécromancie, son savoir serait réellement utile à notre cause.|n|nPour connaître son identité et ses capacités, j\'ai besoin d\'étudier son livre de sorts. Infiltrez-vous dans son camp, prenez le livre et rapportez-le-moi.', },
    {'Apportez le livre de sorts de la Liche et donnez-le à Bethor Glacéclat, à Fossoyeuse.', },
  },
  [358] = {
    'Les profanateurs',
    {'Dans le nord, les fosses communes, au sud-ouest de l\'antre de Garren ont été construites pour accueillir les morts de Tirisfal lorsque la Peste frappa la première fois.|n|nLes corps qui s\'y trouvent ont pu reposer en paix jusqu\'ici mais le Fléau a envoyé des gnolls poil-putride prendre les corps afin de les utiliser pour accroître leurs armées. C\'est intolérable !|n|nVotre mission comporte deux parties : tuer les Poil-putride dans les fosses communes et dans l\'antre de Garren et récupérer sur eux l\'ichor d\'embaumement qui leur donne vie.', },
    {'Tuez des Profanateurs poil-putride et des Bâtards poil-putride.|n|nRapportez 8 Ichors d\'embaumement au magistrat Sevren à Brill.', },
  },
  [359] = {
    'En mission pour les Réprouvés',
    {'J\'ai besoin d\'un rapport récent sur notre base du nécrogarde dans l\'est.|n|nJe dois savoir s\'il y a encore des incursions des forces du Fléau au-delà de la Barricade et dans Tirisfal. Notre vigilance à la frontière des Maleterres doit être maintenue. Nous ne pouvons pas nous permettre que les forces du Fléau s\'établissent ici !|n|nVoyagez vers le sud en suivant la route, puis vers l\'est à l\'embranchement jusqu\'au poste. Demandez le nécrogarde Linnea. Elle a les informations dont j\'ai besoin.', },
    {'Parler au Nécrogarde Linnea.', },
  },
  [360] = {
    'Retourner voir le Magistrat',
    {'Maintenant, rapportez au magistrat Sevren les informations que je vous ai données. Il en a besoin le plus vite possible, soyez rapide.|n|nEt si vous voyez des troupes du Fléau sur votre chemin, abattez-les. Nous ne pouvons leur permettre de parcourir nos contrées sans opposition.', },
    {'Retourner voir le Magistrat Sevren à Brill.', },
  },
  [361] = {
    'Une lettre perdue',
    {'Ceci est une lettre écrite par Thurman, l\'aîné des fils de Gregor Agamand. Elle est adressée à Yvette Farthing, bien qu\'il semble qu\'elle n\'ait pas atteint sa destinataire…', },
    {'Trouver Yvette Farthing. Lui donner la lettre de Thurman Agamand.', },
  },
  [362] = {
    'Les moulins hantés',
    {'Devlin Agamand était le plus jeune des deux fils de la famille Agamand. Jamais frères ne furent aussi différents. Thurman était grand et aimable tandis que son plus jeune frère était faible et acerbe.|n|nLorsque les Moulins d\'Agamand sont tombés suite à la Peste, je n\'ai pas été surpris d\'apprendre que Devlin avait rapidement succombé. Son bavardage maladif peut toujours être entendu près de la route qui mène aux Moulins d\'Agamand.|n|nJe collectionne les restes des Agamand. Je veux ce pauvre Devlin. Trouvez-le, détruisez-le et rapportez-moi ses os.', },
    {'Tuer Devlin Agamand et ramener ses restes à Coleman Farthing à Brill.', },
  },
  [363] = {
    'Réveil brutal',
    nil,
    {'Parler au Prêtre des ombres Sarvis.', },
  },
  [364] = {
    'Les Sans-esprit',
    {'Depuis le jour où le premier Réprouvé a rampé hors de sa tombe, nous sommes en guerre contre le roi-liche et les troupes du Fléau : leurs armées de morts-vivants animés par la nécromancie, des bêtes immondes venues du nord et des spectres tourmentés.|n|nLe roi-liche n\'occupe plus le Trône de glace, mais la partie nord du village est toujours envahie par ses esclaves. Anéantissez-les, n\'ayez aucune pitié, même s\'ils étaient autrefois nos frères et nos sœurs.', },
    {'Tuez 5 Zombies décérébrés et 5 Goules déshéritées.', },
  },
  [365] = {
    'Les champs du Chagrin',
    {'Ça par exemple ! Vous ressemblez à un épouvantail $C. Si vous espérez faire vos preuves au service de la Dame noire, il faudra apprendre les voies des Réprouvés.|n|nÀ l\'ouest, vous trouverez une ferme. Les humains infestent cette terre comme la vermine un cadavre. Et pire, la Croisade écarlate patrouille près de leur tour. Donnez-leur une leçon et volez 10 de leurs précieux potirons.|n|nUne fois que vous les aurez, apportez-les à l\'apothicaire Johann, à Brill.', },
    {'Volez 10 Potirons dans la ferme à l\'ouest, juste au nord du Glas, et apportez-les à l\'Apothicaire Johaan à Brill.', },
  },
  [366] = {
    'Ramener le livre',
    {'Il y a longtemps, Gunther et moi, ainsi que Thule Serres-de-corbeau qui est aujourd\'hui Nécromancien du Fléau, étions amis et étudiants au Kirin Tor - une société de mages de Dalaran.|n|nGunther et moi sommes tombés, tués par la Peste, mais je pensais qu\'il ne s\'était pas relevé ou bien qu\'il avait rejoint les rangs du roi-liche. Il est agréable de le savoir libre.|n|nIl doit être des nôtres. J\'ai mis un sort dans son livre qui, une fois qu\'il le verra, lui montrera que je ne suis pas non plus sous la domination du roi-liche. Une fois qu\'il saura cela, j\'espère qu\'il nous rejoindra.', },
    {'Ramener son livre de sorts à Gunther, dans sa retraite sur son île.', },
  },
  [367] = {
    'Une peste nouvelle',
    {'Dame Sylvanas a fait appel à la Société royale des apothicaires. La Dame noire croit que notre savoir couplé à cette nouvelle magie nous donnera la clé de la défaite d\'Arthas. Elle nous a mis au défi de créer une Peste nouvelle, une Peste plus puissante que celle qui a ravagé Azeroth. Cette nouvelle infection amènera la ruine des forces du Fléau.|n|nMes études montrent que le sang de bêtes en pourrait être la clé. Rapportez-moi 5 fioles de sang de sombredogues, que je puisse tester ma théorie.', },
    {'Récupérez 5 fioles de Sang de sombredogues pour l\'Apothicaire Johaan de la ville de Brill.', },
  },
  [368] = {
    'Une peste nouvelle',
    {'Pendant que vous collectiez mes échantillons, mes expériences m\'ont permis de réaliser que des ingrédients supplémentaires seraient nécessaires pour que cette nouvelle maladie se répande proprement. Empoisonner une victime sans défense est un jeu d\'enfant. Infecter un monde entier est un peu plus compliqué.|n|nJ\'aurais besoin de 5 écailles prélevées sur les murlocs Ailerons noirs des environs. Vous trouverez ces créatures le long de la côte du nord ou de l\'ouest.', },
    {'L\'Apothicaire Johaan de la ville de Brill a besoin de 5 Ecailles d\'Aileron noir prises sur les murlocs des Clairières de Tirisfal.', },
  },
  [369] = {
    'Une peste nouvelle',
    {'Tandis que votre quête vous occupait, j\'ai découvert de vieux textes dans un de mes livres qui indique qu\'une ancienne peste a balayé des milliers de victimes innocentes. Il a été compris plus tard que l\'agent infectieux de l\'épidémie avait été préservé grâce à du venin des araignées Tisse-nuit vicieuses.|n|nRapportez-moi un peu de ce venin pour compléter mes expériences. Je veux voir si le principe conservateur de ce venin agit aussi sur mes décoctions. Les rumeurs disent que les araignées peuvent être trouvées dans l\'est des clairières de Tirisfal.', },
    {'L\'Apothicaire Johaan de la ville de Brill désire que vous lui rameniez 4 échantillons de Venin de Tisse-nuit vicieuse.', },
  },
  [370] = {
    'En guerre avec la Croisade écarlate',
    {'Les documents stratégiques de l\'Exécuteur Arren contiennent tous les détails dont nous avons besoin pour balayer l\'infection humaine de ces terres. Selon nos informations, la Croisade écarlate a assigné le capitaine Perrine et une brigade à la tour en ruine au sud-ouest de Brill.|n|nTuez Perrine ainsi que 3 Zélotes et 3 Missionnaires et revenez me rendre compte.', },
    {'L\'Exécuteur Zygand, à Brill, veut que vous tuiez le Capitaine Perrine, ainsi que 3 Zélotes écarlates et 3 Missionnaires écarlates.', },
  },
  [371] = {
    'En guerre avec la Croisade écarlate',
    {'Nous sommes toujours en guerre et la Croisade écarlate croît en puissance. Le rapport que l\'Exécuteur Arren m\'a envoyé indique que la Croisade lance ses raids depuis la tour en ruine au sud-est de Tirisfal, près de la ferme des Balnir. Elle est sous le commandement du capitaine Vachon.|n|nTuez Vachon et 5 Frères de la Croisade. Cela sera un coup dévastateur pour ces Croisés !', },
    {'L\'Exécuteur Zygand de Brill vous a chargé de liquider le Capitaine Vachon et 5 Frères écarlates.', },
  },
  [372] = {
    'En guerre avec la Croisade écarlate',
    {'La Croisade écarlate lance des raids depuis la tour en ruine au nord-est de Tirisfal, au-delà du Repos de Faol. Selon nos informations, elle est menée par le capitaine Melrache qui a la réputation d\'être un officier impitoyable.|n|nJe vous charge cette mission, dangereuse et spéciale. Abattez Melrache et ses deux gardes du corps au nom de la Dame noire.', },
    {'L\'Exécuteur Zygand de la ville de Brill veut que vous alliez assassiner le Capitaine Melrach et ses deux gardes du corps.', },
  },
  [373] = {
    'La lettre non envoyée',
    {'En fouillant le corps d\'Edwin VanCleef, vous trouvez parmi d\'autres objets une lettre non envoyée. Elle est adressée à Baros Alexston, architecte de la cité de Hurlevent, Hôtel de ville, place de la Cathédrale.|n|nElle a l\'air récemment écrite et scellée.', },
    {'Livrer la lettre pour l\'Architecte de la Cité à Baros Alexston à Hurlevent.', },
  },
  [374] = {
    'Preuves de la mort',
    {'L\'exécuteur Zygand m\'a dit que vous exterminiez des membres de la Croisade écarlate. Les clairières de Tirisfal en sont remplies.|n|nVarimathras, lieutenant de la Dame noire, a pris personnellement en charge la mission d\'exterminer toute la vermine humaine d\'Azeroth. Ici, dans les clairières de Tirisfal, nous affrontons un genre d\'humains particulièrement ennuyeux, la Croisade écarlate.|n|nAllez-y et attaquez la Croisade, $C. Rapportez-moi 10 Anneaux de la Croisade écarlate comme preuve de votre loyauté à Varimathras et à la Dame noire.', },
    {'Apportez 10 Anneaux de la Croisade écarlate au Nécrogarde Burgess, à Brill.', },
  },
  [375] = {
    'Le frisson de la mort',
    {'Il fait si froid maintenant. Le Fléau mort-vivant brûle dans mes veines comme un serpent de glace. Mon âme sera bientôt perdue. Mais aucun destin, aussi irrévocable soit-il, ne m\'empêchera de servir la Dame noire. Lorsque l\'appel est arrivé, j\'ai cousu des sacs pour les morts de la puissante armée de Sylvanas.|n|nMaintenant, mes mains tremblent à cause du froid. Si vous me rapportez cinq peaux de chauve-souris de la pénombre et une bobine de fil grossier, je pourrai me coudre une couverture. Aidez-moi, $N, que je puisse continuer à servir la cause.', },
    {'Rapportez 5 Peaux de chauve-souris de la pénombre et une Bobine de fil grossier à Gretchen Dedmar, à Brill.', },
  },
  [376] = {
    'Les Maudits',
    {'Je soigne nos guerriers blessés, j\'adapte leurs armures et vêtements, et j\'assiste le prêtre des ombres Sarvis.|n|nApparemment, vous allez entrer à son service, vous aussi, pour chasser les Sans-esprit. Si vous voulez rester en un morceau, ce dont je ne doute pas, je peux peut-être vous aider. Je manque de pattes et d\'ailes ; si vous m\'en apportez, je vous fournirai une armure. Vous trouverez de nombreux loups et chauves-souris au sud.', },
    {'Récupérez 4 Pattes de charognard et de 4 Ailes de chauve-souris de la pénombre.', },
  },
  [377] = {
    'Crime et Châtiments',
    {'Non contente de négliger les habitants du bois de la Pénombre, la maison des nobles a décidé d\'humilier le conseil de Sombre-Comté en décidant d\'emprisonner Dextren Ward à Hurlevent, plutôt que de le décapiter ainsi que le seigneur Bouclenoire l\'avait décidé.|n|nWard a été pris en train de vendre des corps du cimetière à Morbent Lagangrène. Ce crime est passible de la peine capitale. Mais Hurlevent exige que Ward soit leur prisonnier.|n|nAssassinez Ward dans la prison de Hurlevent et rapportez-moi sa main. Je vous récompenserai pour cela.', },
    {'Le conseiller Millstipe de Sombre-Comté désire que vous lui rapportiez la main de Dextren Ward.', },
  },
  [378] = {
    'Fureur dans les Profondeurs',
    {'Vous avez prouvé votre loyauté au roi Magni, $C. Et votre haine de la vermine sombrefer est aussi forte que la mienne.|n|nVoici une tâche que j\'aurais voulu accomplir moi-même, mais une dette d\'honneur m\'oblige à rester auprès de Tresse-longue. Roggo a rassemblé un faisceau d\'informations qui prouve que Kam Furie-du-fond était derrière l\'attaque du viaduc de Thandol. C\'est par la volonté de Furie-du-fond que Tresse-longue a perdu son frère.|n|nFurie-du-fond est détenu pour des raisons politiques dans la Prison de Hurlevent. Je veux qu\'il meure, $N. Pour Tresse-longue ! Rapportez-moi sa tête !', },
    {'Rapportez la tête de Kam Furie-du-fond à Motley Garmaçon à Dun Modr.', },
  },
  [379] = {
    'Etancher cette soif',
    {'Vous voulez une source d\'énergie. Je peux vous aider. Savez-vous ce que je veux moi ? Je veux quelque chose à boire ! Rapportez-moi cinq outres de Bat-le-désert, et je vous donnerais le 4711-FTZ.|n|nMaintenant... Devinez où vous pouvez trouver ces outres ? Pourquoi ne pas aller voir un de ces nomades Bat-le-désert, à l\'est d\'ici, pour lui en demander une ? Faites-moi savoir si vous y parvenez.', },
    {'Rapporter 5 Outres de Bat-le-désert à l\'ingénieur en chef Vizisanie à Gadgetzan.', },
  },
  [380] = {
    'Les grottes des Tisse-nuit',
    {'Un de nos plus gros problèmes est d\'obtenir les ressources nécessaires à notre survie. L\'or était déjà rare lorsque l\'Alliance était au sommet de sa puissance.|n|nIl y a une mine d\'or au nord-ouest qui a été envahie par les araignées. Nous avons besoin de cet or, mais nous ne pouvons l\'exploiter à cause de ces créatures. Je n\'ai pas beaucoup de personnels à affecter à cette tâche, alors je vais devoir le faire par étapes.|n|nAllez-y et voyez ce que vous pouvez faire, $N.', },
    {'L\'Exécuteur Arren veut que vous tuiez 8 Jeunes Tisse-nuit et 5 Araignées Tisse-nuit.', },
  },
  [381] = {
    'La Croisade écarlate',
    {'Il vous plaira d\'entendre que nous progressons dans la mine, et cela grâce à vous. Nous pouvons maintenant nous atteler à d\'autres tâches.|n|nMes éclaireurs m\'ont dit qu\'un détachement de la Croisade écarlate avait établi un campement au sud-est. Cette Croisade écarlate est une organisation abjecte qui nous chasse et n\'aura de cesse d\'exterminer jusqu\'au dernier mort-vivant, qu\'il soit du Fléau ou non. Nous devons frapper les premiers !|n|nAttention ce sont des adversaires zélés et dangereux.', },
    {'Apporter à l\'Exécuteur Arren 12 Bracelets écarlates, que vous trouverez sur des Convertis écarlates et des Initiés écarlates.', },
  },
  [382] = {
    'Le messager rouge',
    {'Les rapports de mes supérieurs à Brill indiquent qu\'un agent de la Croisade a été détaché du monastère Écarlate et envoyé ici, au Glas. Toujours selon les rapports, ce messager possède d\'importantes informations sur lui. Je n\'ai pas plus de détails, mais qui que soit ce messager, nous devons l\'avoir !|n|nVous êtes $Gle meilleur:la meilleure; que je peux trouver, $N. Trouvez ce messager et rapportez-moi toutes les informations que vous trouverez sur lui.', },
    {'Tuez Meven Korgal, le messager, au Camp de la Croisade, puis rapportez toutes les informations trouvées à l\'Exécuteur Arren.', },
  },
  [383] = {
    'Informations décisives',
    {'Ceci doit être rapporté à mon supérieur, l\'Exécuteur Zygand à Brill. Avec ces informations, nous serons à même de porter un coup décisif à la Croisade écarlate. Vos services ont été utiles ici au Glas, mais j\'ai besoin de quelqu\'un pour porter ceci à Zygand et je pense qu\'il sera à même de vous trouver une mission plus en relation avec vos capacités.|n|nPrenez la route au nord du Glas. Une fois dans Tirisfal, vous arriverez à un croisement. Prenez la route vers l\'est et continuez. Vous passerez devant le manoir du Foyer froid sur votre route.', },
    {'Livrer les Documents de la Croisade écarlate à l\'Exécuteur Zygand à Brill.', },
  },
  [384] = {
    'Côtes de sanglier à la bière',
    {'Il n\'y a rien que mes clients apprécient plus qu\'une bonne côte de sanglier à la bière ! Le seul problème, c\'est que le trappeur qui nous ravitaille s\'est engagé dans l\'armée du roi pour aller à la guerre sur le front de l\'Alliance.|n|nPeut-être que vous pourriez m\'aider ? Si vous me procurez des côtes de sanglier et une bière au malt Rhapsody de la taverne, je vous donnerai ma recette familiale des côtes de sanglier à la bière accompagnée bien évidemment d\'un échantillon gratuit ! Le secret est dans le malt !', },
    {'Ragnar Tonnebière à Kharanos veut 4 Côtes de sanglier tendres et une chope de Bière au malt Rhapsody.', },
  },
  [385] = {
    'Chasse aux crocilisques',
    {'Beaucoup de chasseurs viennent au Loch Modan pour chasser nos fameux crocilisques. Il y a toujours des marchands qui payent pour avoir ces peaux servant à la confection de vêtements ou d\'armures ; sans parler de ceux qui apprécient leur viande.|n|nLes crocilisques étant féroces et retranchés sur leur île, au milieu du Loch, nous manquons de peaux. Mais ne vous laissez pas effrayer : esquiver les mâchoires de ces bêtes est une expérience enrichissante.|n|nDu moins cette fois...', },
    {'Trouver 5 morceaux de Viande de crocilisque et 6 Peaux de crocilisque pour Marek Cœur-de-fer au pavillon des pérégrins.', },
  },
  [386] = {
    'Ce qui se passait ailleurs…',
    {'Targorr le Terrifiant a servi sous les ordres de Gath\'llzogg en tant qu\'Exécuteur suprême. Sa méthode était impitoyable, même selon les standards orcs. Les hommes qui combattaient vaillamment étaient torturés selon ses désirs. Maintenant il est enfermé dans la Prison de Hurlevent, condamné à mort. Mais quelque chose ne va pas. Un de ces nobles passionnés de procédures bureaucratiques a suspendu l\'exécution. Je suis sûr qu\'il y a des magouilles là-dessous.|n|nMettez fin à la carrière de Targorr le Terrifiant, $N. Allez jusqu\'à la Prison et décapitez-le avant que toutes ces arguties finissent par le libérer.', },
    {'Apportez la tête de Targorr le Terrifiant au Garde Berton à Comté-du-Lac.', },
  },
  [387] = {
    'Écraser la rébellion',
    {'La révolte doit être étouffée ! J\'ai besoin de votre aide. Si l\'on apprend dehors que cette prison est en rébellion, je perds mon poste ! Mais le plus important en ce moment est de forcer les prisonniers à se soumettre, pour la sécurité de Hurlevent.|n|nLa punition en cas d\'émeute est la mort. Tuez quelques-uns de ces déviants ! Cela devrait ramener les choses sous contrôle.', },
    {'Tuez 10 Prisonniers, 8 Détenus et 8 Insurgés dans la Prison pour le Gardien Thelwater de Hurlevent.', },
  },
  [388] = {
    'La couleur du Sang',
    {'L\'amertume coule dans mes veines comme un poison glacé. Mon petit-fils, Mac, était un si bon garçon. À peine 14 ans. Lorsque l\'armée est partie en direction du front, Mac a pris les armes pour défendre la ville. Il était garde à la Prison lorsque les Défias ont été emprisonnés. Mac a réprimandé certains prisonniers qui déchiraient leurs couvertures pour en faire des foulards, symbole de leur gang. Pour cela, ils l\'ont poignardé dans le dos.|n|nJe veux qu\'il soit vengé. Rapportez-moi 10 de leurs précieux foulards de laine. Ils sont de la couleur du sang.', },
    {'Rapporter 10 foulards en laine rouge à Nikova Raskol de Hurlevent.', },
  },
  [389] = {
    nil,
    {'VanCleef et moi étions membres de la Guilde des Maçons. Notre grand projet était de reconstruire Hurlevent après la guerre.|n|nUne fois notre tâche finie, nous avons été escroqués. Les nobles ont refusé de payer. Plusieurs Contremaîtres se virent proposer des emplois dans le gouvernement, mais VanCleef refusa par loyauté envers la guilde. Il mena une émeute et quitta la cité, jurant de se venger.|n|nSon lieutenant, Bazil Thredd, doit en savoir plus sur ses plans. Il est détenu dans la prison de Hurlevent.', },
    {'Parler au Gardien Thelwater à la Prison.', },
  },
  [391] = {
    'Les Emeutes de la Prison',
    {'Qu\'une chose soit bien claire, $N : je n\'ai pas confiance en vous. Mais la situation étant ce qu\'elle est, ça ne change pas grand-chose.|n|nAlors voilà comment on va faire : descendez là-bas et parlez à Thredd. Et si vous êtes vraiment de notre côté, tuez-le et rapportez-moi sa tête. Et s\'il se trouve que vous êtes de son côté, et que vous ne revenez pas... Je vous retrouve et vous périrez comme un rat. Compris ?', },
    {'Tuez Bazil Thredd et rapportez sa tête au Gardien Thelwater, à la Prison.', },
  },
  [392] = {
    'Un curieux visiteur',
    {'Pendant les premières années de son emprisonnement, Thredd n\'a reçu aucun visiteur. Je pensais qu\'il n\'était plus utile à la Confrérie Défias, alors ils l\'ont abandonné.|n|nQuoi qu\'il en soit, il y a quelques mois, tout a changé ; il a commencé à recevoir des visites régulières... Une à deux fois par semaine. C\'était un type étrange, calme. J\'avais des soupçons, mais tous ses papiers étaient en règle.|n|nLe nom sur les papiers était Maelik, voici sa description. Je ne pense pas qu\'il va revenir voir Thredd.', },
    {'Apportez la description du visiteur de Thredd à Baros Alexston à Hurlevent.', },
  },
  [393] = {
    'Les ombres du passé',
    {'Je n\'en ai aucune idée, $N. Il y a quelqu\'un d\'autre qui pourrait vous aider, et il se trouve qu\'il me doit une faveur... bon, pas la peine de parler de ça. Vous trouverez maître Mathias Shaw, du SI:7, dans la caserne de la Vieille ville. Shaw est impliqué dans la plupart des opérations louches de la cité.|n|nSi quelqu\'un a des renseignements, ce sera lui.', },
    {'Apportez la Description scellée du visiteur de Thredd au Maître Mathias Shaw à Hurlevent.', },
  },
  [394] = {
    'La tête de la bête',
    {'Retrouvez Shaw dans la Vieille ville. Faites-lui savoir que la menace Lescovar a été résolue grâce à vous. Je suis sûr qu\'il sera fier d\'avoir un nouveau héros parmi les citoyens de Hurlevent.|n|nJe pense qu\'il vous enverra rencontrer le Prince ou un autre noble. Ne vous laissez pas faire, $N. Les nobles peuvent penser qu\'ils règnent sur la ville autant qu\'ils le veulent, il n\'en reste pas moins que certaines choses échappent à leur contrôle.', },
    {'Parler à Mathias Shaw, à Hurlevent.', },
  },
  [395] = {
    'La fin de la Confrérie',
    {'Ah, j\'avais presque oublié. Alexston est passé pendant que vous n\'étiez pas là, il désirait vous parler. Il est clair qu\'il désirait rendre compte de l\'activité de la Confrérie défias au roi.|n|nUn petit conseil, $N. Si quelqu\'un le demandait, je donnerais tous les détails, mais sans préciser que c\'est votre main qui a tué Lescovar. Croyez-moi. Je suis... habitué... à ce genre de pratiques.|n|nEn ce qui concerne Trias, he bien, ne parlez de lui à personne... jamais... Si vous le pouvez.', },
    {'Parler à Baros Alexston à Hurlevent.', },
  },
  [396] = {
    'Une audience avec le roi',
    {'J\'ai préparé un rapport pour le roi. Je crois que vous devriez le lui remettre, en même temps qu\'une explication de vos découvertes. N\'ayez crainte, il vous récompensera sûrement pour vos actions.|n|nVotre audience est prévue pour bientôt, vous devriez vous hâter, il y a du chemin jusqu\'au donjon de Hurlevent.', },
    {'Apporter le rapport de Baros Alexston sur la Confrérie Défias au Roi Varian Wrynn au Donjon de Hurlevent.', },
  },
  [397] = {
    'Vous nous avez bien servi',
    {'J\'ai entendu dire que le seigneur Wishock avait apprécié ce breuvage.|n|nVous nous avez bien servi, $N. Les démonistes de Hurlevent seront capables de s\'exercer sans être dérangés et ceci grâce à vous. Pour vos efforts, nous vous avons préparé un cadeau. Allez voir mon serviteur, Zggi, et demandez-lui votre récompense.', },
    {'Aller demander votre récompense en parlant à Zggi, le serviteur de Zardeth de la Griffe noire.', },
  },
  [398] = {
    'On recherche : Œil-de-ver',
    {'On recherche : Œil-de-ver !|n|nBête affreuse, même d\'après les critères des gnolls, Œil-de-ver a été condamné à mort pour ses crimes envers les Réprouvés. Ce criminel infâme volait les corps pour que ceux-ci soient utilisés par l\'armée du roi-liche. La dernière apparition d\'Œil-de-ver a eu lieu près de l\'antre de Garren, au nord de Brill, lorsqu\'il pillait les terres.|n|nLa ville de Brill offre une récompense à la personne capable d\'exécuter la sentence. Les griffes de ce brigand doivent être rapportées à l\'Exécuteur Zygand.|n|nLa pitié est pour les faibles.', },
    {'Tuer Œil-de-ver et rapporter ses griffes à l\'Exécuteur Zygand, à Brill, pour toucher la récompense.', },
  },
  [399] = {
    'Débuts modestes',
    {'J\'ai l\'impression qu\'une éternité s\'est écoulée depuis que j\'étais un jeune garçon travaillant à la ferme, dans la marche de l\'Ouest. On dit que l\'on ne peut jamais revenir en arrière et c\'est vrai. C\'est d\'autant plus vrai dans mon cas que la maison de ma famille a été brûlée et détruite par des voleurs.|n|nJ\'ai parlé avec mon père de ce qu\'il était advenu de quelques-uns de mes biens, notamment de ma première boussole. Il n\'a pas pu les sauver. Il m\'a dit qu\'ils devaient être cachés dans la ferme.|n|nLa ferme des Alexston se trouve à l\'ouest de la colline des Sentinelles. Peut-être pourriez-vous y aller et rapporter mes biens ?', },
    {'Aller à la maison de Baros Alexston dans la marche de l\'Ouest pour chercher sa boussole et lui rapporter à la place de la Cathédrale de Hurlevent.', },
  },
  [400] = {
    'Des outils pour Grillacier',
    {'Beldin Grillacier tient un magasin de mécanique. C\'est notre meilleur technicien d\'engins de siège ! Mais il n\'est pas soigneux avec ses outils. Je vous jure qu\'il casse ses clés plates aussi vite que nous les lui fournissons !|n|nNous venons juste de préparer sa dernière commande d\'outils. Si vous la lui livrez, je suis sûr qu\'il vous récompensera.|n|nSon magasin, le dépôt de Grillacier, est juste au nord-est de Kharanos. Et c\'est le repaire de nombreux pilotes d\'engins de siège vétérans. Quand vous y serez, gardez les oreilles ouvertes, il y aura peut-être des occasions à saisir.', },
    {'Rapporter les outils de Grillacier à Beldin Grillacier.', },
  },
  [401] = {
    'Attendre la fin des travaux de Sirra',
    {'J\'ai presque fini de traduire cette note. Si vous revenez dans un moment, j\'aurai fini.', },
    {'Attendre un moment puis parler de nouveau avec Sirra Von\'Indi.', },
  },
  [402] = {
    'Sirra est occupée',
    {'Je suis désolé, mais avec la ville dans cet état, j\'ai d\'autres tâches qui m\'attendent. Peut-être plus tard, si nous survivons, je pourrai finir cette traduction.', },
    {'Vérifier plus tard si Serra est toujours occupé.', },
  },
  [403] = {
    'La garde du tonneau de Tonnebière',
    nil,
    nil,
  },
  [404] = {
    'Une tâche putride',
    {'Le Fléau s\'est infiltré dans les clairières de Tirisfal et a infesté l\'ouest de Brill, près du vieux pont.|n|nAllez là-bas et faites reculer les morts pourrissants et les cadavres décomposés que vous trouverez. Éparpillez leurs ossements et rapportez leurs griffes putrides et les nécrogardes vous récompenseront.', },
    {'Rapporter 7 Griffes putrides au Nécrogarde Dillinger à Brill.', },
  },
  [405] = {
    'La liche prodigue',
    {'Bethor Glacéclat, un puissant mage de Fossoyeuse, dans le sud, m\'a demandé de lui envoyer un agent efficace contre le Fléau. Vous, $N, serez cet agent.|n|nPrésentez ces ordres à Bethor. Il vous instruira du détail de votre mission. Je ne connais pas les détails de celle-ci mais je crois qu\'il s\'agit de recruter une liche. Et cela sera dangereux.|n|nAlors soyez $Gprêt:prête;, $C. Vous ne devez pas échouer.|n|nVous trouverez Bethor dans le quartier des mages de Fossoyeuse.', },
    {'Présenter les ordres de Sevren à Bethor Glacéclat à Fossoyeuse.', },
  },
  [407] = {
    'Les champs du Chagrin',
    {'D\'inoffensifs potirons n\'est-ce pas ? À ce qu\'il semble... Si nous voulons stopper l\'avance d\'Arthas au nord et l\'infestation humaine venant du sud, nous devons commencer à exploiter toute l\'étendue de notre potentiel de morts-vivants.|n|nAvec un peu d\'ingéniosité, un simple potiron va devenir un agent de la Dame noire. Ce potiron, traité avec ma dernière formule, sera une menace sérieuse.|n|nUn autre zélote écarlate a été capturé et est gardé prisonnier dans le cellier de la taverne des Pendus. Prenez ce potiron et donnez-le-lui.', },
    {'Donner le Potiron arrosé au Zélote écarlate capturé qui est gardé dans le cellier de la taverne des Pendus.', },
  },
  [408] = {
    'La crypte familiale',
    {'Les moulins d\'Agamand sont devenus un avant-poste du Fléau. Leur point fort est la crypte de la famille Agamand où leur chef local, un squelette nommé le capitaine Dargol a son quartier général. À l\'aide de la nécromancie, il a ranimé les ancêtres des Agamand et veut les utiliser contre nous.|n|nCela ne doit pas être et c\'est vous qui allez l\'arrêter. Allez jusqu\'à la crypte de la famille Agamand et combattez les ancêtres Agamand.|n|nEt rapportez-moi le crâne du capitaine Dargol.', },
    {'Tuez 8 Spectres ancestraux et 8 Ancêtres pourrissants.|n|nTuez le capitaine Dargol et rapportez son crâne au magistrat Sevren, à Brill.', },
  },
  [409] = {
    'Prouver l\'allégeance',
    {'Vous dites que vous n\'êtes pas $Glié:liée; à la volonté du roi-liche et l\'enchantement que Bethor a mis dans mon livre corrobore ceci. Mais avant que je ne vous croie, je dois avoir des preuves que vous êtes $Gun ennemi:une ennemie; du Fléau.|n|nIl y a un vieil et sanglant autel sur la côte sud de cette île. Il est utilisé par un puissant agent du Fléau, Lillith Nefara.|n|nPrenez une Bougie de signal dans cette boîte là-bas. Allumez-la sur l\'autel et Lillith se réveillera. Détruisez-la et je saurai que vous êtes l\'ennemi du Fléau.', },
    {'Obtenir une Bougie de signal.|n|nInvoquer Lillith Nefara et la tuer.|n|nRetourner voir Gunther sur son île.', },
  },
  [410] = {
    'L\'Ombre dormante',
    nil,
    nil,
  },
  [411] = {
    'Le retour de la liche prodigue',
    {'Portez cette Gemme du néant à mon vieux compagnon Bethor. Cela nous permettra de communiquer… et j\'ai tant de choses à lui dire.', },
    {'Apportez la Gemme du Néant à Bethor Glacéclat à Fossoyeuse.', },
  },
  [412] = {
    'Opération Recombobulation',
    {'Je ferais peut-être mieux de retourner à Gnomeregan pour mettre au point un remède pour les gnomes irradiés, mais Kharanos est la ville où j\'habite, et je ne veux pas qu\'elle tombe aux mains des Crins-de-Givre. Je participe à l\'effort de guerre en réparant et en entretenant des chars à vapeur.|n|nPour une raison nébuleuse, les charognards crins-de-givre se sont mis à collectionner les engrenages gyromécaniques dont j\'ai besoin pour effectuer mes réparations. Ils sont éparpillés le long du front Crins-de-givre, au sud-est de la ville. Vous voulez bien m\'aider à récupérer ces engrenages ?', },
    {'Apportez 8 Engrenages gyromécaniques à Esbrouf Fulgurouage.', },
  },
  [413] = {
    'La Brune scintillante',
    {'J\'aimerais que mon frère Wellart essaye ma nouvelle Brune scintillante. C\'est un montagnard dont la garnison est la tour de garde sud, une des deux tours au bord du Loch Modan.|n|nIl n\'est peut-être pas un brasseur comme le reste des Brasselorge mais il aime boire une bonne bière et je sais qu\'il appréciera celle-ci.|n|nPouvez-vous lui porter ce tonneau de Brune scintillante pour moi ?', },
    {'Amener le Tonneau de Brune scintillante au Montagnard Brasselorge.', },
  },
  [414] = {
    'Une bière brune pour Kadrell',
    {'J\'ai encore bu un peu de cette Brune scintillante faite par mon frère, c\'est vraiment une sacrée bière ! J\'aimerais qu\'un ami montagnard la goûte. Son nom est Kadrell et il patrouille en général sur la route qui passe par Thelsamar au Loch Modan.|n|nPour aller à Thelsamar, partez vers le sud-est en empruntant le tunnel, puis continuez vers le nord-est quand le chemin se sépare. Suivez cette route jusqu\'à Thelsamar.|n|nDonnez au montagnard Kadrell ce fût de Brune scintillante et voyez ce qu\'il en pense !', },
    {'Portez le Fût de Brune scintillante au Montagnard Kadrell.', },
  },
  [415] = {
    'La nouvelle cuvée de Rejold',
    {'Rejold Brasselorge du village de Brassetout vous demande.|n|nIl veut vous parler d\'une nouvelle boisson sur laquelle il travaille… Il parle d\'un coup de main que vous pourriez lui donner. Vous pourriez faire demi-tour et voir ce qu\'il a à dire.|n|nIl pourrait y avoir quelques mousses gratuites pour vous...', },
    {'Parler à Rejold Brasselorge.', },
  },
  [416] = {
    'Chasse au rat',
    {'Nous avons vraiment un problème de vermine à l\'ouest. Les rats des tunnels kobolds sont venus dans les collines, ont creusé leurs terriers et contaminé notre terre avec leur pestilence !|n|nNous voulons les éliminer. Chassez-les et rapportez-moi leurs oreilles pour la récompense.|n|nVous trouverez les tunnels des kobolds et leurs terriers à l\'est, dans la mine du Ru d\'argent.', },
    {'Apportez 8 Oreilles de Rat des tunnels au Montagnard Foudrepique, au Poste d\'Algaz.', },
  },
  [417] = {
    'La revanche du pilote',
    {'Hildelve écrit dans son journal qu\'il a été attaqué par Griffe galeuse, un « gigantesque ours Griffeglace ». Il a repoussé la bête mais pas avant d\'avoir été gravement blessé.|n|nD\'après l\'état du corps de Hildelve, Griffe galeuse a dû revenir et le tuer.|n|nNéanmoins, Hildelve a écrit dans son journal sa dernière volonté :|n|nVengez-moi ! Tuez Griffe galeuse !', },
    {'Tuez Griffe galeuse.|n|nRapportez la griffe à laquelle il doit son nom et le Journal de Hildelve au pilote Martèlepied, à l\'Avant-poste de la Porte sud.', },
  },
  [418] = {
    'Les boudins de Thelsamar',
    {'On n\'a jamais manqué d\'estomacs vides à Thelsamar, avec les gamins qui courent partout et les ouvriers qui reviennent de leur journée de travail après un dur labeur. Nos boudins sont réputés, vous les avez déjà essayés ?|n|nNon ? Eh bien, par ici, il faut travailler pour mériter sa pitance et ce n\'est pas parce que vous êtes bien $Ghabillé:habillée; que l\'on fera une exception pour vous, $C.|n|nTout ce qu\'il me faut, c\'est de la viande d\'ours. La préparation fera le reste. Trouvez-moi cela et laissez la cuisine à Vidra !', },
    {'Apportez 8 morceaux de Viande d\'ours à Vidra Poêlâtre à Thelsamar.', },
  },
  [419] = {
    'Le pilote perdu',
    {'Mon ami et collègue Mori Hildelve, qui est pilote d\'engins de siège, a disparu dans les collines. Nous étions en train de chercher un minerai rare qui est nécessaire pour une poudre explosive de grande qualité. Durant nos recherches, il a essayé de monter une pente avec son engin lorsque le moteur a explosé !|n|nConvaincu qu\'il y avait du minerai dans ces montagnes, Hildelve m\'a confié la garde des engins tandis qu\'il poursuivait la prospection à pied.|n|nCela fait maintenant des jours de cela et j\'ai entendu des grognements de bête venant du nord du lac du Lit d\'Helm, à l\'ouest du tunnel. Mori est un dur-à-cuire mais je suis inquiet.|n|nS\'il vous plaît, $N. Trouvez-le.', },
    {'Le pilote Martèlepied, à l\'Avant-poste de la porte Sud, veut que vous retrouviez le pilote Hildelve.', },
  },
  [420] = {
    'Les observations de Senir',
    {'Les troggs qui infestent le tunnel sont extrêmement hostiles et n\'hésitent pas à attaquer tout intrus. Vous avez l\'air suffisamment solide, vous devriez donc vous en tirer.|n|nLa route à suivre ? Si vous voulez parler à Senir, vous le trouverez à Kharanos.|n|nPassez par le tunnel et une fois dehors à l\'autre extrémité, suivez la route, elle vous conduira à Kharanos.', },
    {'Apporter le rapport de Grelin à Senir Blanchebarbe à Kharanos.', },
  },
  [421] = {
    'Prouver votre valeur',
    {'Dame Sylvanas a chargé Varimathras de la conquête des terres humaines et naines se trouvant vers le sud.|n|nMais Arugal, ci-devant charlatan de Dalaran et aujourd\'hui bête maudite du donjon d\'Ombrecroc, a tristement utilisé sa magie. Il a créé le chaos dans la forêt des Pins-Argentés qui est d\'une grande importance stratégique.|n|nJ\'ai besoin de quelqu\'un de doué dans les arts du combat pour rétablir l\'ordre. Prouvez-moi votre valeur en tuant 5 poils-blancs Ragelune. Ces bêtes dégénérées se trouvent généralement près de la route, en bas de la colline.', },
    {'Tuer 5 Poils-blancs Ragelune pour Dalar Tisselaube au Sépulcre.', },
  },
  [422] = {
    'La folie d\'Arugal',
    {'Comment Arugal a-t-il pu entrer au Kirin Tor ? C\'est au-delà de ma compréhension. Son savoir semblait aussi léger qu\'une bulle de savon.|n|nCe qui importe maintenant, c\'est de savoir quelle magie Arugal a utilisée afin que je puisse la retourner contre lui et rendre la forêt des Pins-Argentés saine pour la Dame noire.|n|nArugal a longtemps habité dans la ferme juste au nord du pont. L\'un des nécrotraqueurs a rapporté avoir vu des livres de sorts, mais il n\'a pas pu les récupérer. Retrouvez-moi le sort appelé le Remède d\'Arugal dans ses livres.', },
    {'Retrouver le Remède d\'Arugal pour Dalar Tisselaube au Sépulcre.', },
  },
  [423] = {
    'La folie d\'Arugal',
    {'Après examen des travaux d\'Arugal, mes pires hypothèses se sont confirmées. Le vieux fou n\'était même pas bon à vider des pots de chambre à Dalaran. Alors, représenter le Kirin Tor dans ses heures les plus sombres...! Les fous !|n|nArugal a utilisé des reliques magiques pour renforcer ses faibles pouvoirs. J\'ai besoin d\'étudier ces objets avant toute chose. Allez au nord et tuez des gloutons Ragelune et des ténébreux Ragelune jusqu\'à ce que vous ayez récolté suffisamment de leurs bracelets enchantés. J\'en ai besoin pour mes recherches. Vous trouverez ces créatures infâmes au nord et à l\'est.', },
    {'Rapportez 6 Bracelets de Gloutons et 3 Bracelets de Ténébreux à Dalar Tisselaube au Sépulcre.', },
  },
  [424] = {
    'La folie d\'Arugal',
    {'Découvrir les sombres secrets des enchantements d\'Arugal va me prendre plus de temps que je ne le pensais.|n|nPendant ce temps, j\'aimerais que vous vous occupiez d\'un problème que nos nécrotraqueurs ont découvert. Il semble qu\'Arugal ait laissé sa magie s\'étendre jusqu\'à la mine du gouffre d\'Elem dans les collines du sud-est.|n|nCette mine serait d\'une aide précieuse pour Varimathras.|n|nJe veux que vous décapitiez le contremaître de cette mine, Grimson le Pâle. Avec sa mort, la mine sera nôtre.', },
    {'Tuer Grimson le Pâle et rapporter sa tête à Dalar Tisselaube au Sépulcre.', },
  },
  [425] = {
    'Ivar l\'Infect',
    {'Mon frère Quinn et moi avions pour mission de reconnaître la forêt des Pins-Argentés et de rendre compte au grand exécuteur Hadrec. Mais nous ne sommes pas allés loin. En passant par cette ferme, nous avons été attaqués par la goule nommée Ivar l\'Infect.|n|nNous avons réussi à nous échapper mais Quinn a été grièvement blessé par Ivar. Il récupère en ce moment grâce à la potion que vous lui avez donnée mais Ivar pourrait revenir avant qu\'il soit guéri.|n|nTuez Ivar de manière à donner le temps à Quinn de récupérer. Ivar se trouve généralement dans la grange, attendant que je baisse ma garde.', },
    {'Tuer Ivar l\'Infect et ramener sa tête à Rane Yorick au lopin d\'Ivar.', },
  },
  [426] = {
    'La chute des moulins',
    {'Les forces du Fléau essayent de construire une base aux moulins d\'Agamand. Si elles réussissent, elles pourront lancer d\'autres attaques sur Tirisfal.|n|nLes ordres sont clairs. Les forces du Fléau positionnées là-bas doivent être détruites.|n|nAllez aux moulins. Collectez des côtes ébréchées sur les soldats et les squelettes Cliquethorax, ainsi que des crânes noircis d\'Ossomanciens Sombroeil.|n|nPour rejoindre les moulins, suivez la route ouest. Après avoir traversé le pont, prenez la route nord au premier croisement. Lorsque vous verrez les moulins, la bataille commencera.', },
    {'Rassemblez 5 Côtes ébréchées et 3 Crânes noircis et rapportez-les au Nécrogarde Dillinger à Brill.', },
  },
  [427] = {
    'En guerre avec la Croisade écarlate',
    {'Les documents que l\'Exécuteur Arren nous a apportés sont juste ce qui nous manquait pour notre bataille contre la Croisade écarlate. Nous savons maintenant où ils se trouvent dans les Clairières de Tirisfal.|n|nMais la Nécrogarde a d\'autres soucis. L\'armée du roi-liche s\'accroît chaque nuit. Nous avons besoin de quelqu\'un capable « d\'initiatives » personnelles tel que vous pour s\'occuper de la Croisade écarlate.|n|nProuvez-moi que vous êtes digne de servir la Dame noire ! Allez vers l\'ouest jusqu\'à la tour après la ferme des Solliden et tuez 10 guerriers écarlates.', },
    {'L\'Exécuteur Zygand, à Brill, veut que vous tuiez 10 Guerriers écarlates.', },
  },
  [428] = {
    'Les nécrotraqueurs égarés',
    {'Il y a quelques semaines, nos nécrotraqueurs, Rane et Quinn Yorick, ont été envoyés en mission de reconnaissance au nord des Pins-Argentés. Nul n\'a plus entendu parler d\'eux.|n|nIls ont peut-être été victimes du Fléau, mais si cela est vrai, j\'aimerais en avoir la confirmation. Trouvez ces nécrotraqueurs.|n|nLeur premier objectif était d\'explorer les fermes au nord de la forêt. Vous devriez commencer par là.', },
    {'Trouver les Nécrotraqueurs Quinn et Rane Yorick.', },
  },
  [429] = {
    'Cœurs sauvages',
    {'Mon frère Quinn a été gravement blessé par la goule Ivar l\'Infect et je doute qu\'il puisse guérir sans l\'aide de la magie. Bien que je ne sois pas spécialiste de ces choses, je sais que nos apothicaires savent concocter des remèdes à partir de cœurs décolorés de worgs.|n|nRecueillez quelques-uns de ces cœurs et portez-les à l\'apothicaire Renferrel au Sépulcre, au sud. Revenez ensuite avec la potion.|n|nVous trouverez des meutes de worgs entre ici et le verger de Malden, plus à l\'est.', },
    {'Recueillir six Cœurs de worg et les apporter à l\'Apothicaire Renferrel au Sépulcre.', },
  },
  [430] = {
    'Retour vers Quinn',
    {'Voici la potion qui guérira Quinn Yorick.|n|nMaintenant, si vous voulez bien m\'excuser, j\'ai un important travail à terminer...', },
    {'Apporter le remède à Quinn Yorick au lopin d\'Ivar, au nord du Sépulcre.', },
  },
  [431] = {
    'Bougies de signal',
    nil,
    nil,
  },
  [432] = {
    'Ces satanés troggs !',
    {'Ces satanés troggs sont en train de démolir mon lieu de travail, que la Lumière les brûle ! Regardez-moi ça : un nouveau baril de poudre qui part en fumée !|n|nOh ! Si seulement je pouvais y aller moi-même et tordre, l\'un après l\'autre, leurs petits cous décharnés ! J\'aimerais les tuer tous !|n|nTout ce stress, cette colère... Cela n\'est pas bon pour ma santé. Et qu\'ont-ils laissé d\'intact ? Rien !|n|nJe les massacrerais volontiers, mais je ne sais plus viser ! Allez donc dans la carrière et tuez quelques-uns de ces salopiauds ! Je vous paierai, mais faites-leur mal, détruisez-les !', },
    {'Tuez 8 Brise-crânes mâcherocs et 8 Briseurs d\'os mâcherocs à la Carrière de Gol\'Bolar et dans sa mine.', },
  },
  [433] = {
    'Le serviteur public',
    {'En tant que membre du Sénat et de la Ligue des Explorateurs, j\'ai décidé d\'inspecter les conditions de travail à la carrière. Elle est infestée de troggs forcenés !|n|nIls ont dévasté la carrière de Gol\'Bolar, sans raison apparente. Ils ont surgi lors de forages en profondeur, détruisant notre équipement et piégeant les mineurs sous la terre.|n|nNous devons rapatrier ces travailleurs vers la surface. Mes mages font des heures supplémentaires pour enchanter des runes de retour. Si vous les apportez aux mineurs ensevelis, ils pourront revenir à la surface en toute sécurité.', },
    {'Distribuez des Runes de retour à 7 Mineurs piégés dans la Mine de la carrière de Gol\'Bolar.', },
  },
  [434] = {
    'L\'attaque !',
    {'Après avoir passé le déguisement à l\'Espion, il entrera pour parler à Lescovar. Les gardes devraient le laisser passer sans problème.|n|nPendant que vous cherchiez le matériel pour moi, j\'ai pris soin d\'informer Marzon qu\'il était temps de rencontrer à nouveau Lescovar. Je lui ai aussi glissé de fausses informations.|n|nLescovar congédiera ses gardes et attendra Marzon dans le jardin. Dès que vous entendrez parler des Défias, agissez. Vous devez les tuer tous les deux. C\'est compris ?|n|nQuand cela sera fait, allez parler à Trias.', },
    {'Rester dans le jardin jusqu\'à ce que le seigneur Gregor Lescovar et Marzon Lame silencieuse aient eu leur conversation. Après, les tuer tous les deux puis retourner voir Elling Trias à Hurlevent.', },
  },
  [435] = {
    'Une escorte pour Erland',
    {'Les loups ne partiront pas, et leurs yeux me fixent avec avidité dès que je fais un pas dehors. Ils doivent avoir une sacrée fringale pour penser que je suis comestible !|n|nJ\'ai un rapport à remettre à mon équipier, le nécrotraqueur Rane Yorick, mais il faudra d\'abord se tailler une route à travers ces loups.|n|nEscortez-moi ! C\'est une véritable meute qui attend dehors ; si vous appeliez des amis en renfort, nous doublerions nos chances de réussite...', },
    {'Escorter Erland jusqu\'à Rane Yorick.', },
  },
  [436] = {
    'Les fouilles de Baguefer',
    {'Le Prospecteur Baguefer dirige l\'exploration de ruines à l\'est du lac. Malgré notre approvisionnement, sa progression s\'est ralentie dernièrement.|n|nBaguefer est un solide et honnête nain qui aime à faire du bon travail, c\'est pourquoi je crains que des forces contraires soient à l\'œuvre pour le ralentir.|n|nAllez aux fouilles de Baguefer et parlez à Magmar Tombebranche. C\'est lui qui gère le site, et il saura sûrement pourquoi le rythme de travail a décru.|n|nPour rejoindre les fouilles, contournez la pointe sud du lac, puis marchez droit vers l\'est.', },
    {'Parler à l\'Explorateur Tombebranche.', },
  },
  [437] = {
    'Le Champ des morts',
    {'Nos premiers rapports de reconnaissance dans la forêt des Pins-Argentés indiquent que les Poil-putride ont une base dans une vieille ferme, le Champ des morts au nord. Nous les avons attaqués à plusieurs reprises, mais à chaque fois ils reçoivent l\'assistance de la banshee Cinglenuit dont la magie désorganise et disperse nos forces.|n|nNous voulons la voir détruite.|n|nAllez dans le Champ des morts et attaquez les Poil-putride. Si vous ne voyez pas la banshee, massacrez les Poil-putride jusqu\'à ce qu\'elle apparaisse, puis tuez-la.|n|nSon essence même deviendra de la poussière. Rapportez-moi cette poussière comme preuve de sa destruction.', },
    {'Tuer des Gnolls poil-putride au Champ des morts.|n|nDétruire Cinglenuit quand elle apparaît.|n|nRapporter son essence au Grand exécuteur Hadrec au Sépulcre.', },
  },
  [438] = {
    'Le bac délabré',
    {'$N, nous avons découvert une nouvelle infestation du Fléau : au Bac délabré. Le bac se trouve à l\'est du Sépulcre, et fourmille de patrouilles de Poil-putride et d\'autres morts-vivants.|n|nLe Fléau a sans doute une bonne raison pour occuper la zone. Allez au Bac délabré et trouvez pourquoi le Fléau se trouve là-bas.', },
    {'Aller au Bac délabré.|n|nChercher la raison de la présence du Fléau.', },
  },
  [439] = {
    'Un indice vers les Poil-putride',
    {'De la pile de corps dépasse une main de femme, marquée par la peste, mais encore relativement fraîche.|n|nUn doigt porte une bague. L\'observation de cette bague révèle une inscription :|n|n« Pour Deliah »', },
    {'Rapporter l\'Anneau de Deliah au Grand exécuteur Hadrec au Sépulcre.', },
  },
  [440] = {
    'La bague ciselée',
    {'Si vous voulez retrouver le mari ou l\'amant qui a donné cette bague à Deliah, parlez au Magistrat Sevren à Brill.|n|nMais je n\'entretiendrais pas d\'espoir à votre place : celui qui a offert la bague est certainement mort à ce jour. Et s\'il est devenu mort-vivant, il a oublié Deliah depuis longtemps.', },
    {'Rapporter l\'Anneau de Deliah au Magistrat Sevren à Brill.', },
  },
  [441] = {
    'Raleigh et Fossoyeuse',
    {'Deliah avait un mari, Raleigh, qui maintenant habite à Fossoyeuse. Si la Deliah qui vivait à Brill est bien celle à qui appartient la bague, alors Raleigh le saura.|n|nRaleigh est dans le quartier des Marchands à Fossoyeuse.', },
    {'Apporter l\'Anneau de Deliah à Raleigh.', },
  },
  [442] = {
    'L\'attaque de l\'île de Fenris',
    {'Il est temps à présent d\'attaquer le bastion du Fléau dans les Pins-Argentés : l\'île de Fenris.|n|nVous devez aller sur l\'île et tuer Thule Serres-de-corbeau. Apportez-moi sa tête !|n|nCette mission est aussi importante qu\'elle est vitale, $N. Vous ne pouvez échouer.', },
    {'Apportez la Tête de Thule au Grand exécuteur Hadrec au Sépulcre.', },
  },
  [443] = {
    'Ichor de Poil-putride',
    {'Avant que nous lancions notre offensive contre l\'île de Fenris, nous devons déterminer qui dirige les gnolls poil-putride. Nos apothicaires pensent que leur origine est liée au fluide étrange qui coule dans leurs corps.|n|nAllez sur l\'île de Fenris, à l\'est du Bac délabré, et collectez de l\'ichor de Poil-putride sur les gnolls. Portez-le à l\'apothicaire Renferrel, qui se trouve à l\'extérieur du Sépulcre.', },
    {'Rapporter 8 bouteilles d\'Ichor de Poil-putride à l\'apothicaire Renferrel.', },
  },
  [444] = {
    'L\'origine des Poil-putride',
    {'J\'ai réduit l\'ichor que vous m\'avez rapporté et en ai séparé les principaux composants. Mes découvertes ne laissent aucun doute sur au moins un point : la magie des démonistes et des nécromanciens a été utilisée dans sa création.|n|nPendant que je pousserai plus avant mes recherches sur ce sujet, je veux que vous en apportiez un échantillon à Bethor Glacéclat à Fossoyeuse. Bethor n\'est pas un apothicaire, mais sa connaissance de la magie pourrait nous aider à comprendre le mystère des Poil-putride.|n|nPartez ! Vous trouverez Bethor dans le quartier de la Magie de Fossoyeuse.', },
    {'Apportez l\'Échantillon d\'ichor à Bethor Glacéclat à Fossoyeuse.', },
  },
  [445] = {
    'Livraison dans la forêt des Pins-Argentés',
    {'Le temps n\'est pas un luxe que peuvent s\'offrir ceux qui travaillent pour dame Sylvanas, mais vous le savez certainement.|n|nEn tant que membre de la Société royale des apothicaires, il est de mon devoir de partager mon savoir avec mes confrères afin que nos efforts conjoints puissent un jour offrir à la Dame noire cette Peste nouvelle qu\'elle désire si ardemment.|n|nPortez ces découvertes à l\'apothicaire Renferrel qui réside au Sépulcre dans la forêt des Pins-Argentés. Prenez la route qui part vers le sud depuis Brill. Quand vous serez devant Fossoyeuse, dirigez-vous vers le sud-ouest.', },
    {'Apporter les découvertes de l\'apothicaire Holland à l\'Apothicaire Renferrel dans la forêt des Pins-Argentés.', },
  },
  [446] = {
    'Thule Serres-de-corbeau',
    {'Cet ichor a été créé par un vieux confrère : Thule Serres-de-corbeau. C\'était un jeune homme prometteur avant la Grande Guerre, mais quand le roi-liche vint au pouvoir, il trahit ses camarades en s\'alliant au Fléau.|n|nJe ne savais pas qu\'il était encore en vie, ni qu\'il menait les Poil-putride contre nous !|n|nJe connais beaucoup de ses sorts, et je peux aider à concocter une potion pour les contrer. Rapportez ce parchemin à l\'apothicaire Renferrel. Il contient les incantations nécessaires à la potion.', },
    {'Porter le parchemin de Bethor à l\'Apothicaire Renferrel au Sépulcre des Pins-Argentés.', },
  },
  [447] = {
    'Une recette mortelle',
    {'Les troupes d\'Arthas sont en nombre, mais avec une Peste nouvelle nous pourrions éradiquer à la fois l\'armée du Fléau et les humains.|n|nMes études ont prouvé que du sang d\'araignée associé à une toxine présente dans le cœur des vieux ours devient un élixir mortel. Collectez ces échantillons sur les araignées du Grouillement, au nord-ouest, et sur les ours qui arpentent la forêt des Pins-Argentés. Livrez ensuite ces ingrédients au maître apothicaire Faranell de la Société royale des apothicaires, à Fossoyeuse.', },
    {'Se rendre au Grouillement et y collecter 6 Cœurs de vieil ours et 6 échantillons de Sang du Grouillement, puis les apporter au maître apothicaire Faranell de la Société royale des apothicaires, à Fossoyeuse.', },
  },
  [448] = {
    'Un rapport pour Hadrec',
    {'Avant que vous n\'attaquiez l\'île de Fenris, faites un rapport au grand exécuteur Hadrec. Il aura sans doute les informations et l\'équipement complémentaires dont vous aurez besoin.', },
    {'Faire un rapport au Grand exécuteur Hadrec au Sépulcre.', },
  },
  [449] = {
    'Le rapport des nécrotraqueurs',
    {'Bien que les blessures de Quinn soient en train de guérir, je veux que notre rapport parvienne au grand exécuteur Hadrec le plus vite possible. Il contient des informations vitales pour maintenir l\'occupation de la forêt des Pins-Argentés par les Réprouvés.', },
    {'Apportez le rapport du Nécrotraqueur au Grand exécuteur Hadrec au Sépulcre.', },
  },
  [450] = {
    'Une recette mortelle',
    {'Vous pouvez encore être utile à la Société royale des apothicaires, $N.|n|nQuand Arugal a jeté sa misérable magie sur la forêt, il a maudit l\'un de nos membres les plus prometteurs, l\'apothicaire Berard. Devenu un serviteur décérébré d\'Arugal, Berard ne nous sert plus à rien, mais ses découvertes pourraient être utiles. Il étudiait une ancienne peste qui a décimé toute la faune aquatique du lac Lordamere, il y a longtemps.|n|nRécupérez le journal de Berard dans son bureau à l\'auberge de Bois-du-Bûcher et rapportez-le à l\'apothicaire Renferrel.', },
    {'Récupérer le Journal de Berard à l\'Auberge de Bois-du-Bûcher et le rapporter à l\'apothicaire Renferrel au Sépulcre.', },
  },
  [451] = {
    'Une recette mortelle',
    {'D\'après le journal de Berard, la mousse de furtifs et de rampants lacustres pourrait intervenir dans la composition d\'une peste nouvelle. Ces bêtes vivent sur les îles du lac Lordamere, à l\'est.|n|nLe journal évoque aussi une rarissime tumeur durcie qu\'il a découverte sur un murloc Aileron noir. Apparemment cette tumeur est tellement rare que Berard n\'a pu en prélever qu\'une.|n|nRecueillez des échantillons de mousse ainsi qu\'une tumeur durcie et rapportez-les au maître apothicaire Faranell à Fossoyeuse.', },
    {'Apporter 6 échantillons de Mousse de Rampant lacustre, 6 échantillons de Mousse de Furtif lacustre et une Tumeur durcie au Maître apothicaire Faranell à Fossoyeuse.', },
  },
  [452] = {
    'Embuscade à Bois-du-Bûcher',
    {'Vous avez fait vite, $N !|n|nLes Conseillers de Bois-du-Bûcher vont revenir dans un instant. Arugal utilise les membres du Conseil comme autant de marionnettes pour garder la mainmise sur le village. Mais je pense que sans le Conseil, les partisans d\'Arugal se retourneraient contre leur maître.|n|nJe ne peux faire cela toute seule, j\'ai besoin de votre aide. Ensemble, nous dévasterons le Conseil au nom de dame Sylvanas.', },
    {'Aider le Nécrotraqueur Faerleia à tuer les membres du Conseil de Bois-du-Bûcher.', },
  },
  [453] = {
    'À la recherche de la silhouette mystérieuse',
    {'Bonne chance, $N. J\'espère que vous retrouverez le bonhomme, et vivant si possible.|n|nS\'il a fui la sécurité de Sombre-Comté, il pourrait être la proie des bêtes sauvages.', },
    {'Retrouver la Silhouette mystérieuse. Indices :|n|nIl n\'est pas né à Sombre-Comté.|n|nC\'est un individu nerveux et craintif.|n|nIl a quitté Sombre-Comté pour faire route vers l\'ouest.', },
  },
  [454] = {
    'Après l\'embuscade',
    {'Avant toute cette...histoire, nous étions en train de convoyer les barils de poudre. Mais maintenant nous devons répartir les tâches, Miran prenant les barils et moi veillant sur les autres.|n|nJe n\'aime pas l\'idée que Miran transporte le reste de la cargaison tout seul. Pourriez-vous l\'escorter quand il sera prêt à partir ?', },
    {'Parler à Miran.', },
  },
  [455] = {
    'Le défi d\'Algaz',
    {'Les orcs du clan Gueule-de-dragon ont un refuge dans les Paluns. Mais voilà : ils se répandent maintenant dans Dun Algaz ! Nous ne pouvons les laisser s\'installer là, sinon le Loch Modan sera coupé du port de Menethil, notre port et bastion dans les Paluns.|n|nTraversez Dun Algaz jusqu\'aux Paluns et tuez quelques orcs pour faire bonne mesure ! Faites un rapport à Valstag Gueule-de-fer au port de Menethil.|n|nPour rejoindre Menethil, passez par Dun Algaz, puis allez au nord en longeant la route, et enfin prenez à l\'ouest à l\'embranchement.|n|nNous comptons sur vous, $N. Vous ne pouvez échouer.', },
    {'Traverser Dun Algaz.|n|nTuer 8 Eclaireurs Gueules-de-dragon et 6 Grunts Gueules-de-dragon.|n|nFaites votre rapport à Valstag Gueule-de-fer au port de Menethil.', },
  },
  [456] = {
    'L\'équilibre de la nature',
    {'Salutations, $N. Je suis le conservateur Ilthalaine. Mon rôle à Sombrevallon est de m\'assurer que l\'équilibre naturel est maintenu.|n|nLes pluies printanières furent particulièrement abondantes cette année, et certains animaux de la forêt en ont profité pour prospérer quand d\'autres ont dépéri.|n|nMalheureusement la population des sabres-de-nuit et des sangliers des chardons s\'est trop accrue. Sombrevallon ne peut produire plus d\'une quantité donnée de nourriture pour les animaux. En route, jeune $C, réduisez la population des sabres-de-nuit et des sangliers des chardons afin de garantir l\'harmonie de la nature.', },
    {'Tuez 3 Jeunes sabres-de-nuit et 3 Jeunes sangliers des chardons.', },
  },
  [457] = {
    'Le dû de la nature',
    nil,
    nil,
  },
  [458] = {
    'La protectrice sylvestre',
    {'Louée soit la Nature, vous êtes là, $C ! D\'étranges rumeurs sont parvenues jusqu\'à moi par l\'entremise des esprits de la forêt.|n|nLa mystérieuse protectrice sylvestre, Tarindrella, est rentrée à Sombrevallon. La dernière fois que l\'on a senti la présence de cette dryade dans ces forêts, c\'était bien avant la bénédiction de Teldrassil. Il y a sûrement quelque chose qui cloche pour motiver son retour sur ces terres.|n|nCherchez Tarindrella et voyez ce qui l\'occupe en ce moment dans notre bosquet. Une des Sentinelles dit l\'avoir vue au sud-ouest d\'Aldrassil.', },
    {'Chercher la dryade connue sous le nom de Tarindrella.', },
  },
  [459] = {
    'Les démons voleurs',
    nil,
    nil,
  },
  [460] = {
    'Reposer en… pièces',
    {'Vous n\'avez pas l\'air d\'un Poil-putride. C\'est déjà ça. J\'avais perdu espoir...|n|nMon nom est Alaric, j\'étais naguère le serviteur et garde du corps de Thule. Il a tenté d\'utiliser sa magie pour me « protéger » du Fléau mort-vivant, mais en fait, son sort m\'a donné une forme de mort-vivant. Après avoir créé les maudits Poil-putride, Thule m\'a décapité et donné ma tête aux gnolls pour qu\'ils jouent avec !|n|nJe vous supplie de me ramener près de mon corps. Je suis sûr que les gnolls l\'ont enterré ici, au donjon de Fenris, près des écuries, dans une tombe anonyme.', },
    {'Apporter la tête d\'Alaric jusqu\'à sa tombe.', },
  },
  [461] = {
    'L\'alcôve secrète',
    {'Je connais une alcôve secrète dans le donjon, qui contient un objet cher à Thule et ses anciens confrères. Il y a également quelque chose qui pourrait vous servir. Amenez-moi sur place !|n|nL\'alcôve se trouve dans la tour la plus au sud-ouest du donjon, derrière une étagère poussiéreuse.|n|nPrenez mon corps, mais laissez mes bottes. De toute façon elles ne m\'allaient pas...', },
    {'Amener Alaric à l\'alcôve secrète.', },
  },
  [462] = {
    nil,
    {'À part vous, nous avons envoyé deux éclaireurs à travers Algaz. Un seul est revenu. Voici ce qu\'il a découvert :|n|nLes Gueules-de-dragon ont envoyé un de leurs lieutenants, Ma\'ruk Wyrmécaille, à Algaz pour y diriger un groupe d\'orcs et couper la route du port de Menethil !|n|nNous devons nous occuper de cela immédiatement. Tuez Ma\'ruk, puis faites un rapport à Valstag Gueule-de-fer au port de Menethil.|n|nMa\'ruk a son quartier général dans une petite grotte, au bord d\'un étang entre le deuxième et le troisième tunnel d\'Algaz. Pour aller à Menethil, prenez à travers Algaz, puis à l\'ouest le long de la route.', },
    {'Tuer Ma\'ruk Wyrmécaille|n|nFaire un rapport à Valstag Gueule-de-fer au port de Menethil.', },
  },
  [463] = {
    'Le Gardien vert',
    {'Avez-vous entendu parler du Gardien vert ? Vous ne le cherchez pas, n\'est-ce pas ? Je dirais que vous êtes $Gfou:folle; si c\'est le cas, mais qui suis-je pour empêcher $Gun illuminé:une illuminée; de courir à sa mort ?|n|nSi vous cherchez le monstre, je crois qu\'il hante les marécages à l\'est de la route où il y a l\'embranchement pour Dun Modr. Il est tapi là-bas, parmi les crocilisques et de choses pires encore !|n|nEt puis, laissez donc votre argent ici ; il ne vous servira à rien où vous allez. Vous ne voulez pas non plus que le Verdâtre s\'ébrèche les dents sur votre or quand il vous coupera en deux ?', },
    {'Trouver le Gardien vert.', },
  },
  [464] = {
    'Bannières de guerre',
    {'Le clan des orcs Gueules-de-dragon fut pratiquement anéanti à la fin de la Deuxième guerre après qu\'ils eurent perdu le contrôle de leurs dragons rouges. Les dragons n\'étaient pas contents de leurs anciens maîtres et ont sauvagement traqué les Gueules-de-dragon. Les quelques survivants ont fui de Grim Batol dans les montagnes jusqu\'à l\'est des Excavations de Whelgar.|n|nMaintenant ils ont repris des forces et campent au nord-est de Menethil.|n|nNous voulons que vous attaquiez leur campement. Vous rassemblerez et me rapporterez leurs bannières de guerre comme preuve de leur destruction.', },
    {'Rapporter 8 Bannières de guerre Gueule-de-dragon au capitaine Rudepoing.', },
  },
  [465] = {
    'La manœuvre de Nek\'rosh',
    {'Pendant que vous combattiez les Gueules-de-dragon, nous avons percé à jour certains de leurs plans.|n|nNek\'rosh a fait construire des catapultes et projette d\'assiéger Menethil ! Et avec les combats à Dun Algaz, nous sommes coupés des renforts !|n|nVous devez détruire ces catapultes. Elles sont au campement des Gueules-de-dragon.|n|nVoici, prenez ce combustible. Taillez-vous une route à coups d\'épée jusqu\'aux catapultes, puis brûlez-les à l\'aide du combustible.|n|nAprès, trouvez et tuez Nek\'rosh. Rien ne nous plairait plus que d\'avoir la tête de cette engeance Gueule-de-dragon au bout d\'une pique...', },
    {'Détruire les Catapultes Gueules-de-dragon.', },
  },
  [466] = {
    'À la recherche de l\'incendicite',
    {'J\'ai appris qu\'il existait un minerai rare, l\'incendicite, dans les Paluns, dans une grotte au nord-ouest de la porte d\'Algaz. C\'est un produit assez volatil, il explose à la moindre mauvaise manipulation ! Mais je suis sûr que correctement extrait, on pourrait l\'utiliser pour donner un sacré punch aux obus de canon !|n|nApportez-moi de l\'incendicite et je trouverai bien quelqu\'un pour l\'expérimenter.|n|nAh ! Et pour extraire ce minerai vous devez savoir miner. Si vous ne l\'avez pas, alors... amenez un ami qui la connaisse !', },
    {'Apportez 6 Chargements d\'Incendicite au Pilote Engrepierre, en Dun Morogh.', },
  },
  [467] = {
    'La quête d\'Engrepierre',
    {'Le pilote Engrepierre adore ses engins de siège, comme il se doit ! Et il est toujours avide d\'informations lui permettant d\'apporter des améliorations techniques à ses chars !|n|nIl a entendu parler d\'un minerai rare et cherche quelqu\'un pour aller en collecter pour lui. Si vous aimez marcher, allez trouver Engrepierre au dépôt de Grillacier en Dun Morogh, et voyez ce dont il a besoin.', },
    {'Parlez au Pilote Engrepierre.', },
  },
  [468] = {
    'Un rapport pour le Montagnard Rochegar',
    {'Le montagnard Rochegar cherche des volontaires pour une mission dans Dun Algaz et les Paluns.|n|nSi vous voulez mouiller vos bottes dans cette terre détrempée au nord, allez parler à Rochegar à Dun Algaz. Dun Algaz est plus au nord sur la route, après la Tour de garde.', },
    {'Parler au Montagnard Rochegar.', },
  },
  [469] = {
    'Livraison quotidienne',
    {'Bonjour, $Gvoyageur:voyageuse; !|n|nVous n\'iriez pas vers Menethil, par hasard ? Sinon, vous pouvez faire halte ici, c\'est un bon endroit pour faire des achats ou prendre une pinte de bière.|n|nMais si vous allez tout de même à Menethil, vous pourriez peut-être apporter ce lot de peaux de crocilisques à James Halloran, le tanneur ?|n|nJe pourrais le faire moi-même, mais ma femme est d\'une méchante humeur en ce moment, et j\'aimerais autant éviter de la contrarier.', },
    {'Apporter le Lot de peaux de crocilisques à James Halloran, le tanneur, au port de Menethil.', },
  },
  [470] = {
    'En creusant dans la vase',
    {'À l\'occasion de ma visite hebdomadaire au Tombeau de Barbe-de-fer, j\'ai été attaquée par de redoutables limons visqueux ! Naturellement, j\'ai paniqué.|n|nJ\'ai jeté mon sac sur l\'un d\'eux, qui l\'a littéralement aspiré, ce qui m\'a laissé le temps de m\'enfuir.|n|nLa mauvaise nouvelle, c\'est que j\'ai absolument besoin du contenu de mon sac !|n|nEt je ne sais pas sur quel Limon je l\'ai jeté : ils se ressemblent tous ! Le Tombeau de Barbe-de-fer est au nord-est, près de Dun Modr. Merci mille fois !', },
    {'L\'un des limons dans le Tombeau de Barbe-de-fer a le sac de Sidonie. Le retrouver et le lui rapporter au port de Menethil.', },
  },
  [471] = {
    'Les devoirs de l\'apprenti',
    {'J\'ai envoyé mon apprenti dans les marécages pour chasser les fameux crocilisques géants des Paluns. Comme il ne revenait pas, je suis parti à sa recherche et l\'ai retrouvé. Tout ce que je peux dire c\'est que ce n\'était pas... plaisant à regarder.|n|nLa rebouteuse dit qu\'il va s\'en sortir, mais entre-temps, j\'ai toujours besoin de mes peaux !|n|n... Si vous tuiez quelques-uns de ces monstres, je n\'y ferais aucune objection ; après ce qu\'ils ont fait... Vous trouverez les crocos au nord de la côte, derrière les taudis des murlocs.', },
    {'Collecter 6 Peaux de crocilisque géant, et les apporter à James Halloran, au port de Menethil.', },
  },
  [472] = {
    'La chute de Dun Modr',
    {'Dun Modr est tombé aux mains des nains sombrefers !|n|nMes blessures sont graves, $C. Mon régiment a été pratiquement décimé ! Ces brutes de Sombrefers nous ont attaqués avant que nous puissions nous regrouper après l\'embuscade du viaduc de Thandol.|n|nNotre chef, Tresse-longue, a sonné la retraite. Comme nous quittions la ville, j\'ai reçu une hache dans le dos. Un voile noir s\'est abattu devant mes yeux.|n|nJe me suis réveillé ici, en sécurité à Menethil, mais j\'ai peur pour mes compagnons. L\'espoir ne m\'a pas encore abandonné. Peut-être Tresse-longue est-il encore vivant ! $R, voyez si vous pouvez le retrouver, pas loin du village de Dun Modr !', },
    {'Rechercher Tresse-longue dans les parages de la ville de Dun Modr.', },
  },
  [473] = {
    'Un rapport au capitaine Rudepoing',
    {'$N. Le clan des orcs Gueules-de-dragon montre sa puissance bien au-delà d\'Algaz. Le capitaine Rudepoing a demandé à parler à tous ceux qui sont prêts à s\'engager contre ces orcs. Il est à l\'intérieur du donjon, dans la salle de guerre.', },
    {'Parler au capitaine Rudepoing.', },
  },
  [474] = {
    'Vaincre Nek\'rosh',
    {'Maintenant que les catapultes ont été détruites, trouvez et exécutez le Chef Nek\'rosh.', },
    {'Tuer le Chef Nek\'rosh.|n|nRapporter la tête de Nek\'rosh au capitaine Rudepoing.', },
  },
  [475] = {
    'Une brise étrange',
    {'Une brise étrange souffle à travers la forêt.|n|nGaerolas Talvethren est le grand gardien des druides de la Serre qui hibernent dans le refuge des saisons de Ban\'ethil. Son devoir en tant que protecteur des Dormants est de veiller à leur sécurité, afin que le pacte avec Ysera ne soit pas rompu.|n|nMais je n\'ai toujours pas de nouvelles de Gaerolas. Allez à l\'est, au village de Brise-Stellaire et revenez avec des nouvelles de Gaerolas, que je puisse calmer mes craintes en apprenant que mon vieux camarade est sain et sauf.', },
    {'Chercher Gaerolas Talvethren à Brise-Stellaire.', },
  },
  [476] = {
    'La corruption des Pins-tordus',
    {'La tribu des Pins-tordus est à nouveau corrompue !|n|nIls m\'ont tendu une embuscade tandis que je partais pour le refuge des saisons de Ban\'ethil, puis ils ont pillé le village de Brise-Stellaire. Dans la forêt, Ursal le Marteleur, leur chef, a été corrompu par quelque chose et il utilise les pouvoirs malfaisants des gangremousses pour les rendre fous.|n|nJe suis trop grièvement blessé pour aller voir Athridas et lui communiquer ces tristes nouvelles. Cette tâche vous incombe à présent, jeune $C. Nous n\'avons plus qu\'à espérer que les Pins-tordus ne soient pas encore arrivés jusqu\'à Ban\'ethil !', },
    {'Retournez auprès d\'Athridas Mantelours à Dolanaar.', },
  },
  [477] = {
    'Frontières',
    {'Comme vous devez le savoir, Moulin-de-l\'Ambre reste un bastion de l\'opposition humaine. La ville est soutenue par les sorciers de Dalaran qui l\'approvisionnent.|n|nJe ne connais pas leurs plans, mais s\'ils portent autant d\'intérêt à ce trou perdu, c\'est qu\'il doit être plus important qu\'on ne pourrait le penser.|n|nIls transportent quantité de caisses depuis Hautebrande. Beaucoup de ces convois ont pour terminus un petit camp au nord du village de Bois-du-Bûcher. Récupérez le contenu de l\'une de ces caisses et apportez-le-moi.', },
    {'Récupérer le contenu de l\'une des caisses des sorciers de Dalaran. Vous trouverez Bois-du-Bûcher au sud.', },
  },
  [478] = {
    'Des cartes et des runes',
    {'<Vous retirez rapidement le pendentif de la caisse et rabattez le couvercle.>', },
    {'Apportez l\'étrange pendentif au prêtre des ombres Allister au Sépulcre.', },
  },
  [479] = {
    'Enquête à Moulin-de-l\'Ambre',
    {'Dalar essaie de localiser la source de la magie des sorciers. Pour l\'heure, nous devons nous efforcer de ralentir leurs progrès...|n|nIl ne fait aucun doute que les conjurateurs, les mages et les protecteurs portent ces pendentifs. Récupérez-en.|n|nSuivez la route principale au sud, puis prenez à l\'est à l\'embranchement qui conduit à Moulin-de-l\'Ambre.', },
    {'Récupérer 8 Pendentifs de Dalaran pour le prêtre des ombres Allister du Sépulcre.', },
  },
  [480] = {
    'Le Tisserand',
    {'Un archimage de grand pouvoir supervise la réactivation du nœud d\'énergie tellurique. Vu les progrès qu\'ils ont faits, notre seule chance de les arrêter est de tuer cet archimage. Ce sera difficile, car il est certainement protégé par d\'autres mages et gardiens.|n|nVous devez partir et le neutraliser au plus vite. Quand il sera mort, récupérez son bâton et apportez-le-moi. En avant !', },
    {'Tuer l\'archimage de Dalaran, puis récupérer son Bâton pour le prêtre des ombres Allister du Sépulcre.', },
  },
  [481] = {
    'L\'analyse de Dalar',
    {'Apportez le pendentif à Dalar Tisselaube. Peut-être pourra-t-il anticiper les plans des Sorciers.', },
    {'Apporter le Pendentif marqué de runes à Dalar Tisselaube au Sépulcre.', },
  },
  [482] = {
    'Les intentions de Dalaran',
    {'Bien sûr ! Comment ai-je pu oublier ?|n|nMoulin-de-l\'Ambre était l\'un des sites sélectionnés par le Kirin Tor en raison des nœuds dormants d\'énergie tellurique qu\'il abrite. Les sorciers projettent sûrement de réactiver les nœuds et d\'utiliser cette énergie pour un projet de grande envergure.|n|nNous ne pouvons les laisser faire…|n|nIl leur faudra beaucoup de puissance pour activer les zones d\'énergie tellurique. Nous pouvons enrayer le processus en volant leurs pendentifs aux sorciers.|n|nRapportez cette information à Allister, il décidera de la suite.', },
    {'Parler au prêtre des ombres Allister au Sépulcre.', },
  },
  [483] = {
    'Les reliques d\'éveil',
    {'Des envahisseurs pins-tordus ont été vus ravageant le refuge des saisons de Ban\'ethil, enclavé dans la colline à l\'ouest.|n|nSi nous n\'intervenons pas, les druides qui y dorment vont être pris dans le Rêve d\'émeraude pour l\'éternité, sans jamais prendre conscience de leur sort. Leur très délicate hibernation ne peut pas être interrompue sans les quatre reliques d\'éveil.|n|nRendez-vous au refuge et récupérez le talisman de la griffe du corbeau, la plume noire, le saphir des cieux et la rune de nidification. Les druides les gardent dans des coffres sacrés. Apportez-les-moi afin que je prépare le rituel d\'éveil.', },
    {'Récupérez les Reliques d\'éveil et rapportez-les à Athridas Mantelours, à Dolanaar.', },
  },
  [484] = {
    'Les peaux de jeune crocilisque',
    {'Je suis James Halloran, le tanneur. Mes peaux de crocilisque traitées sont prisées dans le monde entier.|n|nVous connaissez Einar ? C\'est l\'un des chasseurs qui m\'approvisionne en peaux.|n|nJe suis en ce moment à court de ces peaux soyeuses qui proviennent des jeunes crocilisques.|n|nJe vous paierais grassement si vous pouviez me rapporter quelques-unes de ces peaux. Vous trouverez les jeunes crocilisques dans les marécages, à l\'extérieur de la ville.', },
    {'Collecter 4 Peaux de jeune crocilisque, pour James Halloran, au port de Menethil.', },
  },
  [485] = {
    'Trouvez OOX-09/HL !',
    {'Vous avez découvert un étrange objet métallique en forme d\'œuf. En jouant avec les petits boutons présents sur le dessus, l\'œuf s\'anime. À mesure qu\'il s\'ouvre, il se transforme en une espèce de bidule robot gnomique ! Une voix sort du robot en grésillant :|n|n« Je suis Orguignard Odipnoticus, et mon robot guidé a disparu ! Je vous récompenserai si vous le ramenez ! Rapportez cette balise au robot.|n|nJ\'ai programmé les coordonnées du robot pour vous. Il s\'est écrasé en haut de la rivière près du rocher de l\'Affût ! »', },
    {'Apportez la balise de détresse jusqu\'au robot guidé d\'Orguignard, en haut de la rivière dans les Hinterlands, près du rocher de l\'Affût.', },
  },
  [486] = {
    'Ursal le Marteleur',
    {'Le moment est venu de sauver les druides de la Serre. Si nous échouons maintenant, $N, ils resteront à jamais captifs de leur sommeil.|n|nJe vais préparer les reliques d\'éveil et procéder au rituel, mais pour qu\'il soit efficace, la bête maudite qui est responsable de cette situation tragique doit mourir.|n|nC\'est Ursal le Marteleur qui a perturbé le réveil de nos frères, c\'est Ursal le Marteleur qui doit payer pour qu\'ils puissent être libérés. Suivez la route vers le nord-ouest pour trouver le sentier qui mène au nord, dans la Faille. Ursal y a son repaire.', },
    {'Tuez Ursal le Marteleur.', },
  },
  [487] = {
    'La route de Darnassus',
    {'La route de Darnassus doit rester sûre. En plusieurs occasions, des voyageurs ont été attaqués par des furbolgs de la tribu des Pins-tordus.|n|nDes informations importantes et des convois commerciaux en provenance de Darnassus empruntent cette voie quotidiennement. Nous ne devons pas laisser une bande de païens renégats terroriser les nôtres.|n|nAu nom de la forêt sacrée, prenez les armes, $C. Leur repaire est quelque part le long du sentier qui part vers le nord. Tuez ces embusqués Pins-tordus et revenez me faire votre rapport.', },
    {'Tuez 8 Embusqués pins-tordus.', },
  },
  [488] = {
    'Les commandements de Zenn',
    {'Vous avez envie de travailler, à ce que je vois. Heureusement, il ne se passe pas un jour sans que je n\'aie besoin d\'$Gun jeune:une jeune:c; $C pour répondre à mes demandes.|n|nVoyez-vous, $N, je puis vous rendre $Gheureux:heureuse; et vous offrir ce dont vous n\'osez rêver. Mais en échange vous devez me rapporter certains objets.|n|nMon travail dans la forêt requiert souvent certains... composants. Rapportez-moi des crocs de sabre-de-nuit, des plumes de hibou strigide et des échantillons de soie d\'araignée tissebois.|n|nEt que tout cela reste entre nous, $R.', },
    {'Récupérez 2 Crocs de sabre-de-nuit, 2 Plumes de hibou strigide et 2 échantillons de Soie d\'araignée tissebois.', },
  },
  [489] = {
    'En quête de rédemption !',
    {'Le Conseil de la forêt a eu vent que vous aviez aidé Zenn Vilsabot. Ce satyre est un ennemi de la forêt. $GUn:Une:r; $R devrait avoir mieux à faire que de la fragiliser en tuant ses créatures.|n|nVous devez vous racheter aux yeux du Conseil si vous désirez rester $Gun ami:une amie; de Teldrassil.|n|nDonnez une bonne leçon à Vilsabot et vous serez $Gracheté:rachetée;. Les gangrenoix sont des graines malades qui tombent des arbres. De la fumée verte en sort.|n|nApportez-en à Vilsabot. Il croira qu\'il s\'agit d\'un inoffensif casse-croûte.', },
    {'Collectez 3 Gangrenoix.', },
  },
  [490] = {
    nil,
    {'Selon les ordres stricts du Conseil de Darnassus, j\'ai mis une prime sur la tête des Pins-tordus. Ce ne sont plus des amis de la forêt, mais des êtres corrompus et stupides qui représentent une menace pour toutes les créatures de la clairière.|n|nComme le conseil l\'a ordonné, vous serez récompensé si vous arrivez à éradiquer la menace furbolg de Kalidar. Apportez-moi leurs crocs comme preuve de leur destruction.', },
    {'Rapporter 20 Crocs de Pins-tordus à Shayla Noctebrise, à l\'extérieur de Darnassus.', },
  },
  [491] = {
    'Une Baguette pour Bethor',
    {'Thule m\'a raconté qu\'il y a longtemps, lui et deux de ses confrères créèrent une baguette magique, la fusion des trois baguettes que les mages possédaient alors. Cette baguette devint le symbole de leur amitié, et bien que Thule se mît peu à peu à la mépriser il ne put se résoudre à s\'en séparer ou à la laisser aux deux autres. Alors il vola la baguette et la cacha dans le donjon de Fenris.|n|nVoilà. Apportez la baguette à Bethor Glacéclat, l\'un des anciens amis de Thule. Je suis sûr qu\'il appréciera.', },
    {'Apporter la Baguette tressée à Bethor Glacéclat dans le Quartier de la Magie à Fossoyeuse.', },
  },
  [492] = {
    'Une peste nouvelle',
    {'Selon le nécrogarde, un autre de ces montagnards nains insensés vient juste d\'être capturé. Le nécrogarde aime utiliser la cave de la taverne des Pendus comme cellule, jusqu\'à ce qu\'on puisse « correctement » s\'occuper des prisonniers.|n|nPourquoi n\'iriez-vous pas voir si le captif apprécie la boisson spéciale que j\'ai concoctée pour lui ? Elle contient un soupçon du traitement que la Dame noire réserve au reste d\'Azeroth.', },
    {'Apporter la Boisson spéciale de Johaan au Montagnard captif.', },
  },
  [493] = {
    'Voyage jusqu\'aux contreforts de Hautebrande',
    {'La Société royale des apothicaires est sous la constante pression de la Dame noire pour le développement de la Peste nouvelle. Nous travaillons sans relâche et avons fait de grands progrès. Nous pensons que le succès de notre entreprise serait plus rapide si nous partagions les informations au sein de la Société.|n|nPour cette raison, je veux que vous portiez mes dernières recherches à l\'apothicaire Lydon à Moulin-de-Tarren, une petite ville nichée dans les contreforts de Hautebrande. Le voyage sera long.|n|nAllez au sud sans quitter la route. Suivez de près les panneaux !', },
    {'Livrer les découvertes de l\'Apothicaire Renferrel à l\'Apothicaire Lydon à Moulin-de-Tarren dans les contreforts de Hautebrande.', },
  },
  [494] = {
    '[PÉRIMÉ]Prêts à frapper',
    {'Taisez-vous et écoutez, $C.|n|nJ\'ai été envoyée ici pour surveiller la ville de Hautebrande. C\'est une mission de reconnaissance. Il est impératif que vous envoyiez immédiatement des nouvelles à la grande exécutrice Darthalia à Moulin-de-Tarren. Dites-lui que moi, le nécrotraqueur Lesh, je lui transmets le message suivant :|n|n« Le cri du corbeau retentit à l\'ouest. »|n|nSuivez la route vers l\'est et faites bien attention aux panneaux. Allons, vite, partez pour Moulin-de-Tarren, et en toute hâte !', },
    {'Rendez-vous à Moulin-de-Tarren et délivrez le message du nécrotraqueur Lesh à la Grande exécutrice Darthalia.', },
  },
  [495] = {
    'La couronne de volonté',
    {'Mug\'Thol et sa troupe de guerre ogre ont été envoyés à Alterac afin de récupérer la couronne de volonté pour dame Sylvanas. Malheureusement, au lieu de la rapporter, cet idiot a décidé de l\'essayer... Je suppose que les ogres ne peuvent résister à ce qui brille.|n|nSes actes irresponsables sont de toute façon devenus un problème. La couronne de volonté lui a permis de résister à l\'enchantement qui le liait au service de dame Sylvanas.|n|nLa Dame noire veut faire un exemple : allez à Moulin-de-Tarren, à Hautebrande, et présentez-vous à Melisara, mon lieutenant.', },
    {'Présentez-vous à Melisara, à Moulin-de-Tarren, dans les Contreforts de Hautebrande.', },
  },
  [496] = {
    '[PÉRIMÉ]L\'élixir de souffrance',
    {'Ah ! Un autre jour misérable à Moulin-de-Tarren ! Tout cet air pur me rend fou, $N.|n|nPlus vite nous répandrons l\'épidémie parmi les humains, mieux ce sera. Je fais d\'importantes recherches pour découvrir des agents mortels à utiliser dans mes décoctions, mais je n\'ai pas eu le temps de les collecter tous.|n|nSi vous voulez vous rendre utile, trouvez-moi 10 Langues d\'ours gris et du très rare Ichor de Rampant. Vous trouverez ces ingrédients juste à l\'extérieur de Moulin-de-Tarren.', },
    {'Apporter 10 Langues d\'ours gris et de l\'Ichor de Rampant à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [497] = {
    nil,
    {'Jeune, j\'étais entraîné au métier de gladiateur au donjon de Fort-de-Durn. J\'étais alors ami avec Taretha, la fille de ma nourrice, et maîtresse à l\'époque du maudit bâtard Landenoire.|n|nLe passé est le passé, $N, mais les rumeurs de l\'activité humaine à Hautebrande m\'ont rappelé cette époque. J\'ai dépêché une petite escouade sur place pour enquêter et retrouver, si possible, un...objet...qui me fut donné par Taretha.|n|nEn vain, je le crains, mais peut-être...|n|nMes hommes devraient être déjà rentrés maintenant ; je veux que vous vous rendiez à Moulin-de-Tarren pour juger de la situation.', },
    {'Aller à Moulin-de-Tarren et chercher l\'escouade dépêchée par Thrall.', },
  },
  [498] = {
    '[PÉRIMÉ]Sauvetage',
    {'Moi et d\'autres guerriers avons été envoyés par le Chef de guerre pour récupérer un objet à Fort-de-Durn et enquêter sur ce prétendu Syndicat.|n|nNous sommes allés à Fort-de-Durn pour jeter un coup d\'œil, mais nous avons été surpris par un grand nombre d\'humains. Nous nous sommes bravement battus, mais ils étaient plus nombreux. Ils se sont emparés de nous, mais je suis parvenu à m\'échapper.|n|nFort-de-Durn est au sud-est, de l\'autre côté de la rivière. Drull et Tog\'thar sont retenus là-bas, vous devez aller leur porter secours.', },
    {'Selon les ordres de Krusk à Moulin-de-Tarren, libérer Drull et Tog\'thar du donjon de Fort-de-Durn.', },
  },
  [499] = {
    '[PÉRIMÉ]L\'élixir de souffrance',
    {'Cela va prendre un petit moment d\'associer ces ingrédients pour mettre au point ce qui s\'appellera l\'élixir de souffrance.|n|nNous y voilà ! Ah ! Rien de tel pour égayer une triste journée dans ces mornes contrées que d\'insuffler un peu de souffrance dans le monde.|n|nVoyons voir si notre petite potion produit l\'effet désiré.|n|nDonnez à mon assistant Umpi un avant-goût de ce que la Dame noire a prévu pour les humains et ceux du Fléau.', },
    {'Donner l\'Elixir de souffrance à Umpi.', },
  },
  [500] = {
    '[PÉRIMÉ]La prime Cassecrête',
    {'Les ogres Cassecrête ont installé un repaire dans les montagnes d\'Alterac, près des ruines d\'Alterac. Mes éclaireurs m\'ont appris qu\'ils occupaient également ces ruines.|n|nNous ne pouvons pas les laisser s\'installer tranquillement là-bas. S\'ils commencent à se sentir en sécurité là où ils sont, ils ne tarderont pas à faire mouvement dans les collines. Ils seront alors à nos portes !|n|nPartez au nord dans les montagnes d\'Alterac et chassez des ogres. Rapportez-moi leurs Articulations sales, je vous en donnerai une belle prime.', },
    {'Collecter 9 Articulations sales d\'ogres Cassecrête dans les montagnes d\'Alterac. Les apporter au Maréchal Senterouge à Austrivage.', },
  },
  [501] = {
    '[PÉRIMÉ]L\'élixir de douleur',
    {'Oh ! $N… Les fleurs s\'épanouissent à Hautebrande et l\'air est si pur et vif... Comme cela est triste et regrettable. Je regarde par ma fenêtre crasseuse et je me languis de voir notre Peste nouvelle se répandre et porter la mort à ce monde qui le mérite tant.|n|nBien sûr, je resterais bien à ruminer mes pensées morbides toute la journée, mais mon devoir envers la Dame noire ne peut attendre. Vous m\'aiderez, n\'est-ce pas ? Mes recherches m\'ont permis de conclure que la plus mortelle des préparations s\'obtient à partir du sang d\'un lion des montagnes. Apportez-m\'en et vous verrez ce que je suis capable de faire.', },
    {'Apporter 10 Fioles de sang de lion des montagnes à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [502] = {
    '[PÉRIMÉ]L\'élixir de douleur',
    {'Ah ! Rien de tel que l\'odeur du sang frais dans les collines !|n|nMaintenant, nous allons mélanger tout cela et commencer à nous amuser pour de bon ! Ce que j\'ai créé à partir de ce sang, je l\'appellerai l\'élixir de douleur. Si mes calculs sont exacts, cette mixture pourrait bien être le début de la grande œuvre que je veux offrir à dame Sylvanas. Mais avant tout, nous avons besoin de faire un test.|n|nPrenez cet élixir et allez à la ferme la plus au nord dans les champs de Hautebrande, au sud-ouest. Et voyons comment Stanley, le petit chien du fermier Ray, apprécie cette « douceur ».', },
    {'Donner l\'Elixir de douleur à Stanley.', },
  },
  [503] = {
    '[PÉRIMÉ]Gol\'dir',
    {'D\'après les documents que vous avez rapportés, Gol\'dir est retenu dans une grande base du Syndicat, plus au nord, très certainement dans les montagnes d\'Alterac. Il est captif depuis trop longtemps et doit absolument être libéré.', },
    {'Libérer Gol\'dir et retourner voir Krusk à Moulin-de-Tarren.', },
  },
  [504] = {
    '[PÉRIMÉ]Les combattants cassecrêtes',
    {'Maintenant que vous avez eu un avant-goût des ogres Cassecrête, je veux que vous leur rentriez dedans franchement...|n|nAllez dans les ruines d\'Alterac et débusquez des Combattants Cassecrête. Je veux que vous en fauchiez le plus possible : c\'est la seule façon de faire comprendre à ces brutes qu\'il faut garder leurs distances avec le territoire de l\'Alliance.', },
    {'Tuez 10 Combattants Cassecrête, puis retournez voir le Maréchal Senterouge, à Austrivage.', },
  },
  [505] = {
    '[PÉRIMÉ]Syndicat d\'assassins',
    {'Je suis le nouveau Magistrat d\'Austrivage, assigné ici suite à l\'assassinat du précédent Magistrat. Les tueurs n\'ont jamais été retrouvés, mais nos investigations nous ont permis de conclure qu\'ils avaient été engagés par le Syndicat, un groupe de voleurs commandé par les nobles du royaume déchu d\'Alterac.|n|nLe Syndicat a des camps sur le promontoire de Sofera et la Dague de Corrahn, au nord et à l\'ouest de Moulin-de-Tarren, occupé par la Horde. Exécutez les membres du Syndicat que vous trouverez dans ces camps.', },
    {'Tuer 12 Détrousseurs du Syndicat et 8 Larrons du Syndicat puis retourner voir le magistrat Henry Maleb à Austrivage.', },
  },
  [506] = {
    '[PÉRIMÉ]L\'héritage de Landenoire',
    {'Il y a quelques jours, j\'ai reçu la visite du leader de ce Syndicat. Son nom est Aliden Perenolde et il se prend pour le seigneur de ce pays. Il m\'a confié qu\'il voulait utiliser les orcs qui s\'insurgent contre lui comme esclaves, exactement comme le voulait son père et mentor, le méprisable Landenoire.|n|nPlus important : il est venu en compagnie de sa maîtresse, une petite femme nommée Elysa, qui portait autour du cou le pendentif que le Chef de guerre désire tant.|n|nPartez maintenant, je me débrouillerai pour régler mes affaires.', },
    {'Transmettre l\'information recueillie par Gol\'dir à Krusk à Moulin-de-Tarren.', },
  },
  [507] = {
    '[PÉRIMÉ]Seigneur Aliden Perenolde',
    {'Il est évident que Perenolde doit être tué pour que son influence néfaste disparaisse de la surface de ce monde. Son manoir se trouve au nord, sur les rives du lac Lordamere. Faites votre devoir, $N, et récupérez le pendentif pour le Chef de guerre.', },
    {'Tuer le Seigneur Aliden Perenolde et interroger sa maîtresse, Elysa, au sujet du Pendentif de Taretha.', },
  },
  [508] = {
    '[PÉRIMÉ]Le cadeau de Taretha',
    {'Le Pendentif ? Bien sûr que vous pouvez l\'avoir, prenez-le ! Je ne veux garder de lui aucun souvenir… Laissez-moi tranquille, je ne vous demande rien d\'autre.', },
    {'Rapporter le Pendentif de Taretha à Krusk à Moulin-de-Tarren, aux Contreforts de Hautebrande.', },
  },
  [509] = {
    '[PÉRIMÉ]L\'élixir d\'agonie',
    {'À chaque jour son élixir. Si cela ne tenait qu\'à moi, je laisserais bien ces humains pathétiques et le Fléau se combattre. Ceux-là semblent nés pour s\'entre-tuer.|n|nMais la Dame noire veut accélérer le processus, alors pourquoi ne pas passer ces longues et morbides journées à répandre un peu de peste et de mort à travers le pays ?|n|nVoici le plan, $N : vous irez à la ferme des Nethander, au sud de Moulin-de-Tarren et à l\'est de la rivière et d\'Austrivage. Collectez 6 Fleurs de fangemufle dans les champs et rapportez-les-moi que je puisse achever mon prochain élixir.', },
    {'Apporter 6 Fleurs de fangemufle à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [510] = {
    '[PÉRIMÉ]Documents d\'annonce d\'attaque',
    {'Parmi ces documents se trouve une liste des marchandises commandées. Elle contient des requêtes ordinaires (nourriture, armes, vêtements), mais aussi des demandes moins conventionnelles (masques, huile, poison).|n|nMais ce qu\'il y a de plus remarquable est le caractère urgent de la commande. Ces marchandises étaient nécessaires à l\'exécution de ce qui est décrit dans le document comme une « mission importante contre Austrivage », et l\'on en avait besoin rapidement.', },
    {'Apportez les Documents d\'annonce d\'attaque au Magistrat Maleb à Austrivage.', },
  },
  [511] = {
    '[PÉRIMÉ]Lettre codée',
    {'L\'une des lettres, sur la table, est codée et ne peut être déchiffrée.', },
    {'Apportez la Lettre codée au Maître des traditions Dibbs, à Austrivage.', },
  },
  [512] = {
    '[PÉRIMÉ]Nobles morts',
    {'Je crains que les dirigeants du Syndicat ne veuillent à tout prix la ruine d\'Austrivage. Nous devons porter un coup décisif à ses chefs avant que leurs plans n\'aboutissent.|n|nPartez pour les Ruines de Strahnbrande, dans les montagnes d\'Alterac au nord. Nous pensons que le Syndicat a établi son quartier général dans cette région.|n|nNous savons que ce gang de brigands reçoit ses ordres d\'anciens nobles d\'Alterac. Il se peut qu\'ils se camouflent parmi les agents ordinaires du Syndicat, mais vous saurez que vous avez tué un noble à la chevalière qu\'il porte.|n|nApportez-moi ces chevalières.', },
    {'Apporter 7 Chevalières d\'Alterac au Magistrat Maleb à Austrivage.', },
  },
  [513] = {
    '[PÉRIMÉ]L\'élixir d\'agonie',
    {'Alors que je me résignais à l\'idée qu\'un autre jour allait s\'achever exempt de toute joie, vous m\'apportez ces merveilleuses fleurs de fangemufle.|n|nJe vais d\'abord les réduire en une fine poudre. Nous aurons alors besoin que le maître apothicaire Faranell à Fossoyeuse lui applique son colloïde de virulence. Après, on devrait plutôt s\'amuser, je crois...|n|nTenez, prenez cette Poudre de fangemufle et courez immédiatement voir maître Faranell, $N.', },
    {'Apporter la Poudre de fangemufle au maître apothicaire Faranell à Fossoyeuse.', },
  },
  [514] = {
    '[PÉRIMÉ]Le maître des lettres',
    {'J\'ai un collègue à Forgefer qui pourrait peut-être décoder cette lettre. Rendez-vous à la bibliothèque du Hall des Explorateurs à Forgefer et parlez au Prospecteur Foudrepique. Dites-lui que je vous envoie et montrez-lui la lettre. S\'il y a une personne au nord du pic Rochenoire à pouvoir lire cela, c\'est bien lui.', },
    {'Apporter la Lettre ingénieusement codée au Prospecteur Foudrepique à Forgefer.', },
  },
  [515] = {
    '[PÉRIMÉ]L\'élixir d\'agonie',
    {'Un composé à base de fangemufle ? Absolument merveilleux ! Pourquoi n\'y ai-je pas pensé ? Laissez-moi appliquer de mon colloïde de virulence à cette diabolique mixture.|n|nAfin d\'activer les agents contaminateurs de ce brouet de fangemufle, Lydon aura besoin d\'une potion de sang de troll forte, d\'écailles de Daguéchine et d\'yeux d\'Ailerons déchirés de la côte méridionale. Il saura quoi faire une fois que vous aurez réuni tous les ingrédients. Ah ! j\'ai tellement hâte d\'apprendre ce que l\'expérience va donner.', },
    {'Apportez le Brouet de fangemufle, une Potion de sang de troll forte, 5 Écailles de Daguéchine et 5 Yeux d\'Ailerons déchirés à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [516] = {
    'Le Péril de Beren',
    {'J\'ai reçu des rapports indiquant qu\'un groupe de morts-vivants se cache pour préparer une attaque contre nous. Armés de cette information, nous pouvons retourner la situation en les attaquant les premiers et réduire leur plan minable à un simple souvenir cocasse.|n|nMalheureusement, les informations dont nous disposons sont incomplètes, au mieux. On dit qu\'ils se cachent dans un endroit appelé Péril de Beren. La localisation exacte est inconnue, mais nous savons que c\'est une caverne dans les collines, près d\'une enclave des sorciers de Dalaran.|n|nJ\'ai confiance en vos ressources. Trouvez-les et tuez-les.', },
    {'Localiser le Péril de Beren, tuer 6 Manouvriers Serres-de-corbeau et 6 Gardiens Serres-de-corbeau puis retourner voir le prêtre des ombres Allister au Sépulcre.', },
  },
  [517] = {
    '[PÉRIMÉ]L\'élixir d\'agonie',
    {'Ce nouvel élixir est enfin prêt à être testé. Mais pourquoi gâcher une si bonne et si contagieuse peste sur une pauvre grenouille ou un chien famélique ? Amusons-nous un peu, au nom de dame Sylvanas.|n|nDescendez à Dun Garok. Vous connaissez les casernes où ces sales petits nains s\'agitent partout ? Volez un tonneau de leur Croquejarret brune pour moi. Une fois que j\'aurai ce baril, nous pourrons commencer la fête, vous et moi, $N.', },
    {'Apporter un Tonneau de Croquejarret brune à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [518] = {
    '[PÉRIMÉ]La couronne de volonté',
    {'Mug\'Thol et ses ogres Cassecrête ont envahi les ruines d\'Alterac. Il va être difficile de lui infliger une sérieuse punition sans d\'abord entamer ses troupes.|n|nAprès les avoir réduites à la portion congrue, nous l\'attaquerons.|n|nCompris ? Bien. Allez-y à présent.', },
    {'Tuer 10 Marteleurs Cassecrête pour Melisara à Moulin-de-Tarren.', },
  },
  [519] = {
    '[PÉRIMÉ]La couronne de volonté',
    {'Targ, Fouilleboue et Glommus sont les lieutenants de Mug\'Thol. Ils lui sont loyaux, bien que personne ne sache vraiment ce qui peut pousser un ogre à être loyal.|n|nApportez-moi leurs têtes, $N, et il ne nous restera plus qu\'à nous occuper de celle de Mug\'Thol, de sa couronne, et du reste.', },
    {'Tuer Targ, Fouilleboue et Glommus, puis apporter leurs têtes à Melisara, à Moulin-de-Tarren.', },
  },
  [520] = {
    '[PÉRIMÉ]La couronne de volonté',
    {'À présent que les lieutenants de Mug\'Thol sont morts, tout ce qu\'il nous reste à faire est de tuer Mug\'Thol et de récupérer la couronne de volonté. Je ne crois pas qu\'il veuille la donner gentiment. Et encore moins à vous, si l\'on considère la façon dont ses amis sont... partis.|n|nTrouvez Mug\'Thol, et présentez-moi sa tête et la couronne. Le glas sonnera alors pour la résistance des Cassecrête.', },
    {'Tuer Mug\'Thol et présenter sa tête et la Couronne de volonté à Melisara, à Moulin-de-Tarren.', },
  },
  [521] = {
    '[PÉRIMÉ]La couronne de volonté',
    {'Tout ce qu\'il reste à faire est de donner la couronne de volonté à Sharlindra, à Fossoyeuse. Elle veillera à ce que la couronne soit remise à dame Sylvanas. Je vous déconseille de chercher à l\'utiliser à vos propres fins, $N. Le sort de Mug\'Thol est assez éloquent.', },
    {'Remettre la Couronne de volonté à Sharlindra, à Fossoyeuse.', },
  },
  [522] = {
    '[PÉRIMÉ]Contrat de l\'assassin',
    {'Ceci est un contrat pour l\'assassinat du Magistrat Henry Maleb. L\'ordre a été scellé à la cire rouge, à l\'aide d\'une chevalière caractéristique.', },
    {'Apportez le Contrat de l\'assassin au Magistrat Maleb à Austrivage.', },
  },
  [523] = {
    '[PÉRIMÉ]La mort du baron Vardus',
    {'Le contrat que vous avez trouvé est signé par le baron Vardus, un noble de l\'ancien royaume d\'Alterac, réputé pour son cœur de pierre et ses pratiques barbares. Je ne suis pas surpris que quelqu\'un comme le baron soit derrière tout ça.|n|nTrouvez cet homme. Trouvez-le et faites-le répondre de ses actes. Il doit être avec l\'élite du Syndicat. Peut-être aux Ruines de Strahnbrande, ou dans la vallée qui est au nord.', },
    {'Apportez la tête du baron Vardus au Magistrat Maleb à Austrivage.', },
  },
  [524] = {
    '[PÉRIMÉ]L\'élixir d\'agonie',
    {'À côté, les nécrogardes détiennent quelques fermiers pris en otage. La grande exécutrice Darthalia suspectait qu\'un des stratèges de Hurlevent se cachait parmi eux. Apparemment, le pauvre militaire a été retrouvé mort dans les Maleterres la nuit dernière. Darthalia, toujours aux petits soins pour moi, a décidé de me laisser faire ce que je voulais avec les fermiers.|n|nJe pense qu\'il est temps de leur préparer une petite fête. Comme au bon vieux temps !|n|nPlacez ce baril infecté sur le tapis, dans leur pièce. Tournée générale de bière pestilentielle !', },
    {'Placer le Baril infecté sur le tapis pour les fermiers détenus comme otages.', },
  },
  [525] = {
    'D\'autres mystères',
    {'J\'ai déchiffré la lettre, mais je ne sais pas quoi en faire. Vous l\'avez trouvée chez des voleurs dans les collines d\'Alterac ? C\'est étrange…|n|nVous devriez la montrer au Magistrat d\'Austrivage. Bien que cette lettre soit sibylline, Austrivage est la ville la plus proche d\'Alterac. Si un danger menace, alors il doit savoir.', },
    {'Apportez la Lettre décodée au Magistrat Maleb, à Austrivage.', },
  },
  [526] = {
    'Les lingots de sancteforge',
    {'Vous avez peut-être découvert un lingot de sancteforge dans ce coffre, mais ce n\'est pas suffisant pour forger quoi que ce soit de décent avec !|n|nVous devriez y retourner et en chercher davantage. Les murlocs, près de l\'épave, ont peut-être des lingots sur eux.', },
    {'Collecter 5 Lingots de sancteforge puis retourner voir Glorin Front-d\'acier, dans les Paluns.', },
  },
  [527] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    nil,
    {'Tuer 6 Garçons de ferme, 6 Fermiers, le Fermier Ray et le Fermier Getz, puis retourner voir Darthalia à Moulin-de-Tarren.', },
  },
  [528] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'La nouvelle de l\'attaque sur les fermes situées au nord a semé la panique chez les gens de la ville. Merveilleux !|n|nNos nécrotraqueurs rapportent que les paysans fuient vers les champs au sud de Hautebrande. Ces imbéciles pensent qu\'ils peuvent s\'y cacher et ainsi échapper à leur sort.|n|nMontrez-leur qu\'ils ont tort, $N. Retournez aux Champs de Hautebrande et traquez les paysans qui s\'y tapissent. Apportez-leur le chaos au nom de la Dame noire.|n|nRompez !', },
    {'Tuer 15 Paysans de Hautebrande et faire votre rapport à Darthalia à Moulin-de-Tarren.', },
  },
  [529] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'Les humains de Hautebrande ont fait montre d\'une résistance inattendue. Le problème semble être que les gens de la ville sont équipés par le forgeron local. Nous devons couper cet approvisionnement.|n|nVotre mission consiste à exécuter le forgeron Verringtan. Tuez également ses apprentis. Pendant que vous y serez, rapportez un chargement de fer prélevé dans leur stock. Cela nous sera bien utile lorsque nous aurons achevé la conquête de Hautebrande et que nous entreprendrons de raser Austrivage.', },
    {'Tuez le Forgeron Verringtan et 4 Apprentis Forgerons de Hautebrande.|n|nRécupérez un Chargement de fer, puis retournez voir Darthalia à Moulin-de-Tarren.', },
  },
  [530] = {
    'La vengeance d\'un mari',
    {'Valdred, autrefois un bon ami à moi, est le meurtrier de ma femme. Bien que je sois incapable de ressentir de la peine, j\'aspire à la vengeance. Si vous tuez Valdred et me rapportez ses mains maudites, alors je vous récompenserai.|n|nLa dernière fois que j\'ai entendu parler de lui, il se trouvait au mur de Grisetête, dans le sud des Pins-Argentés, essayant de fuir vers le royaume de Gilnéas.', },
    {'Tuer Valdred Moray.|n|nApporter ses mains à Raleigh Andrean à Fossoyeuse.', },
  },
  [531] = {
    'La vengeance de Vyrin',
    {'Par la Lumière ! N\'apportez pas de choses comme ça dans le pavillon… c\'est insalubre, insupportable, in… in… insalubre !|n|nSortez-moi ça de là, voulez-vous ? Personne ne veut voir votre fichu petit trophée, vraiment !', },
    {'Amener la tête du vieux Noiraud à Vyrin Vent-vif au pavillon des pérégrins.', },
  },
  [532] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'La ville de Hautebrande est en pleine confusion et nous pensons qu\'elle va bientôt tomber. Nous devons cependant persister dans notre barbarie jusqu\'à ce que ces chiens d\'humains soient balayés des collines pour l\'éternité.|n|nMalgré leurs pertes écrasantes, les humains se rassemblent autour de leurs chefs et continuent à se battre. Nous devons éliminer leur chef, le maire Brûle-flanc, de même que le conseil municipal. Détruisez également leur très précieux document politique, la Proclamation de Hautebrande. Et pendant que vous y êtes, volez le Registre municipal.', },
    {'Tuer le Magistrat Brûle-flanc et 4 Conseillers de Hautebrande. Détruire la Proclamation de Hautebrande. Voler le Registre municipal de Hautebrande. Rendre compte à Darthalia à Moulin-de-Tarren.', },
  },
  [533] = {
    '[PÉRIMÉ]L\'épée d\'HumbertInfiltration',
    {'Nous avons enfin des nouvelles et des rumeurs, des indices sur l\'endroit où pourrait être Gol\'dir. Les humains l\'ont emmené à divers endroits, mais nos recherches aboutissent au grand camp du Syndicat, au nord d\'ici.|n|nAllez-y, $N, et rapportez toutes les informations sur lesquelles vous pouvez mettre la main.', },
    {'Rapportez des informations sur l\'emplacement de Gol\'dir pour Krusk, à Moulin-de-Tarren.', },
  },
  [535] = {
    nil,
    {'Eurrgh… Blessé et mourant, me voilà en face de l\'ennemi.|n|nVous me tuerez sans doute de toute façon, mais si vous m\'apportez de la bière brune d\'Austrivage... Les gens de votre race ne boivent pas, non ? Je vous dirai ce que vous voulez savoir.', },
    {'Apporter une Chope de bière brune d\'Austrivage à Valik, au Camp du Syndicat.', },
  },
  [536] = {
    '[PÉRIMÉ]Le long de la côte',
    {'Transféré de la garde de la cité de Hurlevent à Austrivage, une ville visiblement abandonnée… L\'odeur du port jour et nuit.|n|nSans parler du vieux Senterouge… Veut que je m\'occupe des murlocs. Ha !|n|nJ\'ai du mal à m\'imaginer allant jusqu\'à l\'une des enclaves de ces grotesques poissons mutants qui grouillent le long du Rivage occidental. Si vous pouviez y aller et vous occuper d\'eux, j\'apprécierais.', },
    {'Tuez 10 Chasse-marées et 10 Oracles Aileron déchiré pour le lieutenant Farren Orinelle, à Austrivage.', },
  },
  [537] = {
    '[PÉRIMÉ]Le conseil noir',
    {'La lettre que vous m\'avez apportée a été écrite par un être qui se nomme lui-même Nagaz, un membre de la Veille d\'Argus. Je ne sais pas ce qu\'est cette Veille d\'Argus, mais si elle est alliée au Syndicat, alors elle constitue une menace.|n|nJe veux que vous trouviez Nagaz et les Mages de l\'ombre d\'Argus mentionnés dans cette lettre. Je veux que vous les trouviez et que vous les tuiez.|n|nCherchez dans les Hauteurs, là où le Syndicat est le plus fort. C\'est au nord de Strahnbrande.|n|nAvec un peu de chance, vous y trouverez ces représentants de la Veille d\'Argus.', },
    {'Tuer 4 Mages de l\'ombre d\'Argus.|n|nApporter la Tête de Nagaz au Magistrat Maleb à Austrivage.', },
  },
  [538] = {
    'Austrivage',
    {'$N. Si un long voyage ne vous dérange pas, alors j\'ai une tâche à vous confier, pour aider à nouveau Hurlevent à étoffer sa bibliothèque.|n|nL\'ancien royaume d\'Alterac s\'est effondré après la Grande Guerre. C\'est malheureux que la ville soit à présent en ruine, mais il est encore plus tragique que de grands savoirs aient disparu ! Nous devons retrouver ces importantes collections de livres.|n|nAustrivage est la ville la plus proche des Ruines d\'Alterac. Rendez-vous-y et parlez à l\'Erudit Dibbs. Il peut vous guider vers les ruines, et tous les livres que vous pourriez trouver.', },
    {'Parler à l\'Erudit Dibbs à Austrivage.', },
  },
  [539] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'Le registre municipal de Hautebrande indique que la mine de Veine-Azur est sous le contrôle de l\'Alliance. De plus, c\'est une source importante de minerai de fer destinée aux armureries de l\'Alliance.|n|nMême si nous avons porté un coup décisif à la ville de Hautebrande, l\'Alliance soutient et protège toujours la mine de Veine-Azur.|n|nElle se trouve au sud de Hautebrande. Allez-y et tuez le contremaître, un humain du nom de Bonds. Tuez également ses mineurs. Cela devrait envoyer un message fort à l\'Alliance.', },
    {'Tuer le Contremaître Bonds et 10 Mineurs de Hautebrande, puis rendre compte à Darthalia, à Moulin-de-Tarren.', },
  },
  [540] = {
    '[PÉRIMÉ]L\'entretien des connaissances',
    {'Ces ogres répugnants résident à présent dans les ruines d\'Alterac, et je frémis à l\'idée de ce qu\'ils peuvent faire des précieux livres qui s\'y trouvent.|n|nPénétrez dans les ruines d\'Alterac et récupérez des tomes sur les ogres. Prenez tout ce que vous trouverez, mais cherchez également le livre suivant : « Le Bras de Gri\'lek ». C\'est un recueil d\'anciennes légendes trolls que je dois lire. Les ruines d\'Alterac sont le dernier endroit où se trouve une copie intacte de cet ouvrage.', },
    {'Apporter 5 Tomes retrouvés, ainsi que le Livre de cuir usé « Le Bras de Gri\'lek » au Maître des traditions Dibbs, à Austrivage.', },
  },
  [541] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'Des nains aidant des humains ? Que ces affreuses petites bêtes soient maudites.|n|nNous allons tester la force de cette prétendue Alliance. Nous verrons à quel point ces cogneurs de chevilles sont déterminés à aider les humains une fois que nous serons passés. Nous savons précisément où se trouve leur forteresse dans ce territoire.|n|nIls ont établi une caserne dans la partie sud-est de Hautebrande, le long du Mur de Thoradin. La mission est d\'attaquer cette caserne, baptisée Dun Garok, $C. Le capitaine Colline-de-fer, leur chef, doit mourir.', },
    {'Aller à Dun Garok et tuer 8 Montagnards, 4 Fusiliers, 2 Prêtres et le Capitaine Colline-de-fer, puis rendre compte à Darthalia, à Moulin-de-Tarren.', },
  },
  [542] = {
    '[PÉRIMÉ]Les livres de Milton',
    {'J\'ai besoin de temps pour étudier le livre « l\'Arme de Gri\'lek » que vous m\'avez apporté, mais je suis sûr que Milton a hâte d\'enrichir la collection des livres de Hurlevent avec ceux que vous avez retrouvés aux Ruines d\'Alterac.|n|nLes voici, empaquetés et catalogués. Rapportez-les à Milton Sheaf à Hurlevent et je suis certain qu\'il vous en sera reconnaissant.', },
    {'Apportez les Tomes d\'Alterac à Milton Sheaf, à Hurlevent.', },
  },
  [543] = {
    'La tiare de Perenolde',
    {'La Tiare de Perenolde est un ancien héritage des « nobles » de Perenolde, la famille régnante d\'Alterac, avant que ce royaume ne tombe en ruine. On dit qu\'elle a été réalisée par des maîtres bijoutiers à Forgefer, et qu\'elle est ornée des émeraudes les plus pures.|n|nQuand Alterac a été détruite, la Tiare fut perdue. Mais les rumeurs disent qu\'un ogre-mage, Grel\'borg l\'Avare, l\'a trouvée, et qu\'il fouille à présent les Ruines d\'Alterac à la recherche d\'autres trésors.|n|nNous aimerions que vous récupériez la Tiare pour nous.', },
    {'Récupérez la Tiare de Perenolde.', },
  },
  [544] = {
    '[PÉRIMÉ]L\'invasion de la prison',
    {'Je suis venu à Moulin-de-Tarren pour effectuer des recherches, mais je dois à présent résoudre une crise. Voyez-vous, quatre Réprouvés se sont enfuis de Fossoyeuse il y a quelques mois. Ils ont trahi leurs semblables, mais pire encore : ils ont volé la Dame noire.|n|nCes voleurs ont forcé un coffre et se sont emparés de quatre artéfacts, des objets dont nos apothicaires ont besoin pour leurs études. Dame Sylvanas veut les récupérer.|n|nLes voleurs ont fui à Dalaran, et là-bas les sorciers les ont placés en quarantaine dans le camp d\'internement de Lordamere.', },
    {'Trouvez les traîtres et récupérez les artéfacts, puis retournez voir le Magus Toisevide à Moulin-de-Tarren.', },
  },
  [545] = {
    '[PÉRIMÉ]Les patrouilles de Dalaran',
    {'Les sorciers de Dalaran ont construit un vaste dôme magique autour du cœur de leur cité. Certains croient qu\'il s\'agissait de se protéger des violences de cette époque, d\'autres pensent qu\'ils recherchaient simplement la solitude, pour étudier et comploter.|n|nJe ne m\'intéresse pas à leurs raisons. En revanche, ce qui m\'intéresse, c\'est que la périphérie de la ville en ruine puisse abriter des trésors magiques.|n|nMais les sorciers et leurs élémentaires asservis patrouillent dans tout ce secteur.|n|nChassez-les donc, et revenez lorsque leur nombre sera suffisamment réduit.', },
    {'Tuer 6 Invocateurs de Dalaran et 12 Élémentaires asservis, puis retourner voir le Magus Toisevide à Moulin-de-Tarren.', },
  },
  [546] = {
    '[PÉRIMÉ]Souvenirs de morts',
    {'J\'ai entendu dire que vous étiez $Grecruté:recrutée; par Darthalia pour mener l\'offensive contre les humains de Hautebrande. Je vous envie tellement…|n|nTandis que vous vous amuserez – à tuer des humains, à piller, à terroriser les innocents – je resterai coincé ici, à Moulin-de-Tarren, à monter la garde et à me morfondre.|n|nPeut-être prendrez-vous en pitié un vieux nécrogarde comme moi ? Vous remarquez que je fais la collection de crânes. Et vous allez combattre des humains pendant quelque temps, je crois. Au gré de votre longue bataille, vous récolterez bien quelques crânes, apportez-m\'en 30 et je vous rendrai la pareille d\'une belle façon.', },
    {'Le Nécrogarde Samsa du Moulin-de-Tarren veut 30 Crânes d\'humains de Hautebrande.', },
  },
  [547] = {
    '[PÉRIMÉ]L\'épée d\'Humbert',
    {'La grande exécutrice Darthalia m\'a envoyé surveiller Dun Garok de loin. J\'ai établi mon camp juste au-delà de leur champ de vision. Mais ce matin, pour faire bouillir de l\'eau, je suis allé chercher du bois.|n|nQuand je suis revenu au camp, j\'ai découvert que mon équipement avait disparu.|n|nApparemment, des éclaireurs nains de Dun Garok sont passés par là et repartis avec mon matériel. J\'ai besoin de mon épée ! Si vous pouviez la retrouver et me la rendre, je serais tellement reconnaissant. Il y a tellement de nains par ici. Ça va être très difficile de retrouver le sale petit voleur qui l\'a dérobée.', },
    {'Retrouvez l\'Épée du Nécrogarde Humbert à Dun Garok, et la lui rapporter à Moulin-de-Tarren.', },
  },
  [548] = {
    '[PÉRIMÉ]&lt;NYI&gt; &lt;TXT&gt; Bloodstone Pendant',
    {'Ceci démarrera la ligne de quête du Pendentif de Bloodstone… <NYI>', },
    nil,
  },
  [549] = {
    '[PÉRIMÉ]ON RECHERCHE : Personnel du Syndicat',
    {'Au nom de l\'autorité de dame Sylvanas, tous les membres de l\'organisation connue sous le nom du Syndicat sont recherchés. Ceux conduits à la garde ou faits prisonniers seront sommairement exécutés. Nous savons qu\'actuellement ils se rassemblent dans les ruines du donjon de Fort-de-Durn, au sud-est de Moulin-de-Tarren.|n|nUne récompense est offerte à quiconque apporte la preuve de ses actions à la grande exécutrice Darthalia.', },
    {'Tuez 10 Voleurs et 10 Gardiens du Syndicat, puis allez voir la Grande exécutrice Darthalia à Moulin-de-Tarren pour votre récompense.', },
  },
  [550] = {
    '[PÉRIMÉ]La bataille de Hautebrande',
    {'Comme vous avez combattu avec valeur à la bataille de Hautebrande, j\'ai écrit cette recommandation exaltant vos prouesses au combat, pour que le haut commandement les apprécie.|n|nApportez cette recommandation scellée à Bragor Poing-de-sang à Fossoyeuse. Vous pouvez être fier:fière; de ce que vous avez fait, $C.', },
    {'Apporter la Recommandation scellée à Bragor Poing-de-sang, à Fossoyeuse.', },
  },
  [551] = {
    '[PÉRIMÉ]Le Parchemin ensorcelé',
    {'Ce parchemin est sous l\'effet d\'un sort qui le rend indéchiffrable. Mais un mot peut être lu, en haut du papier :|n|nNagaz|n$', },
    {'Apporter le Parchemin ensorcelé à l\'Erudit Dibbs à Austrivage, aux Contreforts de Hautebrande.', },
  },
  [552] = {
    '[PÉRIMÉ]La vengeance d\'Helcular',
    {'Maître Helcular avait presque achevé sa transformation en liche lorsqu\'une bande d\'humains furieux a découvert son repaire dans les collines et l\'a tué. Pour rendre les choses encore pires, ils ont enterré son corps au cimetière d\'Austrivage.|n|nUn tel manque de respect envers un si grand sorcier n\'est pas acceptable. En tant que son apprenti, je veillerai à ce que la pluie de la vengeance tombe drue sur la ville d\'Austrivage.|n|nAvant tout, nous avons besoin du Bâtonnet d\'Helcular. Les yétis ont atteint son repaire. L\'une de ces bêtes l\'a sans doute emporté.', },
    {'Reprendre le Bâtonnet d\'Helcular aux yétis et la ramener au novice Thaivand à Moulin-de-Tarren.', },
  },
  [553] = {
    '[PÉRIMÉ]La vengeance d\'Helcular',
    {'Tenez, prenez le Bâtonnet d\'Helcular. Vous en aurez besoin.|n|nHelcular a fabriqué 3 bûchers cérémoniels comme composants de son sort le plus puissant. La Flamme d\'Azel et la Flamme de Veraz brûlent dans l\'une des cavernes des contreforts. La Flamme d\'Uzel éclaire une cave située plus haut et plus au nord dans les montagnes.|n|nUne fois le Bâtonnet d\'Helcular chargé avec ces trois flammes, il faut l\'enfoncer dans la tombe d\'Helcular située à Austrivage. La vengeance sera nôtre.', },
    {'Charger le Bâtonnet d\'Helcular des pouvoirs de la Flamme d\'Azel, de la Flamme de Veraz et de la Flamme d\'Uzel.|n|nEnfoncez le Bâtonnet chargé dans la tombe d\'Helcular à Austrivage.', },
  },
  [554] = {
    '[PÉRIMÉ]Les Runes gravées',
    {'Le prospecteur Foudrepique est un maître du décodage. Si vous lui apportez le parchemin que vous avez trouvé, alors, avec un peu de chance, il pourra en comprendre la signification. Foudrepique étudie en ce moment aux quartiers généraux des Prospecteurs, à Forgefer.|n|nEt quand vous le verrez, dites-lui que vous m\'avez parlé. Je lui ai envoyé beaucoup de choses dernièrement.', },
    {'Apporter le Parchemin ensorcelé au Prospecteur Foudrepique à Forgefer.', },
  },
  [555] = {
    '[PÉRIMÉ]Bisque de tortue apaisante',
    {'S\'il y a une chose que vous apprendrez à propos d\'Austrivage, c\'est que nous avons l\'une des meilleures cuisines au nord de Hurlevent !|n|nPrenez ma recette secrète de bisque de tortue, par exemple. J\'en ai connu qui ont fait le voyage depuis Sombre-Comté juste pour en déguster une coupe. Mais il y a bien longtemps que je n\'en ai pas fait. Pour me procurer les ingrédients, j\'allais au-delà de Dalaran, jusqu\'au lac Lordamere, mais c\'est trop dangereux à présent. Si vous m\'apportiez de la viande de tortue provenant des gueules d\'acier, au nord d\'ici, je vous mitonnerai un bon petit plat.', },
    {'Apporter 10 morceaux de Viande de tortue au Chef Jessen, à Austrivage.', },
  },
  [556] = {
    '[PÉRIMÉ]Les Runes gravées',
    {'Un sérieux atout des sorciers de Dalaran est leur familiarité avec les élémentaires, ces créatures puissantes venant d\'autres dimensions. Les sorciers utilisent des Runes gravées pour contrôler ces élémentaires. Le magus Toisevide aimerait étudier certaines de ces runes.|n|nPénétrez sur le territoire des sorciers de Dalaran, à l\'ouest de Hautebrande, et trouvez-en.|n|nIl se peut que vous les trouviez sur n\'importe quel citoyen de Dalaran, mais je suggère que vous vous les procuriez au camp d\'internement. C\'est un endroit moins dangereux que Dalaran.', },
    {'Apporter 10 Runes gravées au Conservateur Bel\'varil à Moulin-de-Tarren.', },
  },
  [557] = {
    '[PÉRIMÉ]Les brassards de lien',
    {'Le magus sera très occupé à étudier ces runes gravées que vous avez apportées, mais je sais que tôt ou tard il voudra des échantillons de leurs contreparties : des brassards de lien. Ce sont des brassards qui, passés aux poignets des élémentaires, les lient au service des mages.|n|nChassez des élémentaires dans les ruines de Dalaran et récupérez leurs brassards de lien de terre. Le magus en sera très satisfait.', },
    {'Apporter 4 Brassards de lien de terre au Conservateur Bel\'varil à Moulin-de-Tarren.', },
  },
  [558] = {
    'Autographe de Jaina',
    {'On dit que dame Jaina Portvaillant, à Theramore, est l\'une des plus grandes héroïnes de l\'Alliance de tous les temps. Quand je serai grand, je veux aussi être un héros de l\'Alliance !|n|nVous connaissez Jaina, $N ? Vous pouvez me faire une faveur, s\'il vous plaît ? Vous pouvez m\'avoir un autographe de dame Jaina ? Je sais pas comment lui demander, et c\'est sans doute une personne bien trop occupée pour s\'occuper de quelqu\'un comme moi... Mais pas vous ! Vous êtes $Gun aventurier:une aventurière;, comme elle ! Je parie qu\'elle vous donnerait facilement un autographe !|n|nS\'il vous plaît ?', },
    {'Allez à Theramore pour tenter d\'obtenir un autographe de dame Jaina Portvaillant pour votre protégé.', },
  },
  [559] = {
    '[PÉRIMÉ]La preuve de Farren',
    {'Le croirez-vous, $N ? Senterouge n\'était pas satisfait, en dépit de tous les murlocs que nous avons tués. Ah ! ne soyez pas modeste, vous y avez participé. À présent il veut que je lui apporte la preuve de leur mort, en allant chercher les têtes refroidies de ces misérables murlocs, pour les soumettre à sa validation.', },
    {'Récupérez 10 Têtes de murlocs sur les murlocs du Rivage occidental pour le lieutenant Farren Orinelle à Austrivage.', },
  },
  [560] = {
    '[PÉRIMÉ]La preuve de Farren',
    {'Vous savez, $N, je préférerais ne pas toucher à ces têtes… Puisque vous avez déjà les mains qui sentent le poisson, cela vous dérangerait-il de les livrer à Senterouge pour moi ?', },
    {'Livrer le Sac de têtes de murlocs au maréchal Senterouge à Austrivage.', },
  },
  [561] = {
    '[PÉRIMÉ]La preuve de Farren',
    {'Veuillez informer le lieutenant Orinelle que j\'aimerais qu\'il concentre ses efforts sur les nagas qui infestent le Rivage oriental. Quand il aura obtenu des résultats, dites-lui qu\'il vienne en personne m\'en rendre compte.', },
    {'Parler au Lieutenant Farren Orinelle à Austrivage.', },
  },
  [562] = {
    '[PÉRIMÉ]Hurlevent me voilà',
    {'Mon ancien mentor à la garde de la cité de Hurlevent a envoyé un message me disant que le Haut Commandement de l\'Alliance commence à s\'inquiéter du problème posé par les nagas. D\'après ce qu\'il a entendu, il y a des chances de promotion, ou d\'une bonne affectation, pour quiconque se montrera valeureux dans la résolution de ce problème.|n|nIl y a juste quelque chose qui ne va pas... Je ne peux pas m\'occuper des nagas, $N. Oh bien sûr, je pourrais disperser une querelle d\'ivrognes, ou alpaguer un clochard vindicatif, mais les nagas c\'est trop pour moi. Vous devez m\'aider, $N.', },
    {'Tuez 10 Chasseurs du rivage daguéchines et 10 Sirènes daguéchines pour le Lieutenant Farren, à Austrivage.', },
  },
  [563] = {
    '[PÉRIMÉ]Nouvelle affectation',
    {'Que mon rapport soit lu ne devrait pas poser de problème. Le nouveau capitaine de la Garde, le major Samuelson, était mon mentor lorsque j\'étais posté à Hurlevent. Cela devrait lui donner suffisamment d\'arguments pour que j\'y sois à nouveau transféré. Je vais avoir besoin de vous pour porter mon rapport. Cependant, je n\'aimerais pas que ce cher Senterouge comprenne.', },
    {'Remettre le Rapport de Farren au major Samuelson au Donjon de Hurlevent.', },
  },
  [564] = {
    '[PÉRIMÉ]Un problème très coûteux',
    {'Y\'a rien qui m\'hérisse plus que d\'perdre ces beaux ch\'vaux, là. Et croyez-moi, on en a perdu pas mal, entre ces sales morts-vivants, c\'fichu gang du Syndicat, et toutes les aut\' crapules bonnes à rien qui traînent dans l\'secteur.|n|nMais j\'jure sur la tombe d\'mon vieux grand-père qu\'y a pas d\'danger plus grand pour les ch\'vaux que ces lions d\'montagne, en haut à Alterac.|n|nIls s\'ramènent toujours des collines et m\'rendent la vie difficile !|n|nVous croyez être $Gun héros:une héroïne; ? Allez-y et faites quek\'chose pour y r\'médier !', },
    {'Darren Malvew d\'Austrivage veut que vous tuiez 8 Lions des montagnes et 10 Lions des montagnes massifs.', },
  },
  [565] = {
    '[PÉRIMÉ]La cape en fourrure de yéti de Bartolo',
    {'Moi, le Grand Bartolo, je confectionnerai pour vous ma fameuse cape en fourrure de yéti, célèbre dans le monde entier, et qui fait la renommée de l\'Alliance !|n|nJe vous mets au défi de parcourir le monde pour trouver meilleure cape. Oh ! attendez, qu\'est-ce que vous dites, $Gpetit:petite:r; $R ? « Bartolo, il n\'existe pas de meilleure cape ! » Oui, oui, je sais, j\'ai entendu ça des milliers de fois déjà.|n|nBartolo demande une pelote de laine, une cape d\'homme des collines confectionnée par un habile tanneur, du fil fin et bien sûr de la fourrure de yéti. Apportez-moi tout cela et vous serez $Gun client satisfait:une cliente satisfaite;.', },
    {'Apporter à Bartolo Ginsetti d\'Austrivage une Pelote de laine, une Cape d\'homme des collines, du Fil fin et 10 Touffes de fourrure de yéti.', },
  },
  [566] = {
    '[PÉRIMÉ]ON RECHERCHE : baron Vardus',
    {'Par décret de la grande exécutrice Darthalia, l\'humain connu sous le nom de baron Vardus est recherché pour crime contre les Réprouvés. Nous savons que Vardus est un membre haut placé de l\'organisation dite le Syndicat.|n|nIl a été vu pour la dernière fois dans les Hauteurs des montagnes d\'Alterac, au nord de Moulin-de-Tarren.|n|nIl doit être ramené mort. Apportez une preuve de son trépas à la grande exécutrice Darthalia pour obtenir votre récompense.', },
    {'Tuer le baron Vardus et apporter sa tête à la Grande exécutrice Darthalia, à Moulin-de-Tarren.', },
  },
  [567] = {
    '[PÉRIMÉ]Dangereux !',
    {'Dangereux !|n|nLes humains de Hautebrande dont les noms suivent ont été déclarés dangereux et leurs têtes sont mises à prix par la grande exécutrice Darthalia :|n|nGreffier Horrace Blancheval. Recherché pour le meurtre du nécrogarde Toma.|n|nCitoyen Wilkes. Recherché pour le meurtre de l\'apothicaire Eli.|n|nMineur Hackett. Recherché pour le meurtre du nécrotraqueur Fry.|n|nKalaba la fermière. Recherchée pour détournement de marchandises à Fossoyeuse.|n|nChacun de ces ennemis se cache et sera difficile à débusquer. Une récompense sera remise à la preuve de leur mort.', },
    {'La Grande exécutrice Darthalia de Moulin-de-Tarren offre une prime pour la mort du Greffier Horrace Blancheval, du Citoyen Wilkes, du Mineur Hackett et de Kalaba la fermière.', },
  },
  [568] = {
    'La défense de Grom\'gol',
    {'Throm\'ka, $C !|n|nVotre arrivée à Grom\'gol tombe à point nommé. Je commande ce campement camp ici dans la jungle, au nom du Chef de guerre. Je suis tenu sur l\'honneur d\'assurer la sécurité de tous les membres de la Horde. Notre mission consistant à maintenir une chaîne d\'approvisionnement jusqu\'à Pierrêche est entravée par certaines espèces locales.|n|nJe vous charge de réduire la population des raptors autour de Grom\'gol. Une fois que vous aurez accompli des progrès significatifs, revenez me voir pour que je vous assigne une nouvelle mission.', },
    {'Le commandant Aggro\'gosh du campement Grom\'gol veut que vous tuiez 15 Raptors flagellants.', },
  },
  [569] = {
    'La défense de Grom\'gol',
    {'La première fois que nous sommes arrivés dans cette jungle, nous n\'avions pas l\'intention de déclarer la guerre aux tribus locales. Notre mission d\'approvisionnement de Pierrêche est de la plus haute priorité. Mais des complications ont surgi. Un groupe d\'ogres occupe les Ruines de Mizjah au sud-est de Grom\'gol. Malgré nos avertissements, ils continuent à tendre des embuscades à nos caravanes.|n|nJe vous ordonne de vous occuper de ces ogres peu coopératifs. Allez vers les ruines et délogez-les de la région. Au moins, cela enverra un message fort.', },
    {'Le commandant Aggro\'gosh du campement Grom\'gol veut que vous tuiez 10 Brutes et 5 Sorciers ogres.', },
  },
  [570] = {
    'Enchantement de Mok\'thardin',
    {'Le pouvoir de la magie de la jungle doit être compris et acquis par la Horde. Mes rituels se sont montrés efficaces jusque-là. Je peux lancer des enchantements très puissants. Pour vous, brave $C, je vais réaliser un objet très spécial.|n|nRapportez-moi quelques griffes de panthère ombregueule et un croc de tigresse. Mais pas n\'importe quel croc. Il doit être dans un parfait état.|n|nCes bêtes vivent cachées dans la jungle, mais vous en trouverez pas loin, juste de l\'autre côté de la rivière, depuis les ruines de Mizjah au sud-est.', },
    {'Le Long-voyant Mok\'thardin, du Campement Grom\'gol, veut que vous trouviez 8 Griffes de Panthère ombregueule et 1 Croc de tigresse en parfait état.', },
  },
  [571] = {
    'Enchantement de Mok\'thardin',
    {'Ce dont j\'ai besoin va être très difficile à obtenir. Pour tenir ensemble ces plumes, griffes et ce croc parfait, il me faut une longe magique. Seul un tendon de gorille fera l\'affaire.|n|nVous ne pourrez en trouver un que sur un ancien gorille de Valbrume. On sait que ces animaux fourragent à l\'est de Baie-du-Butin.|n|nLe tendon doit être parfait. Il se peut que vous deviez en tuer plus d\'un pour trouver exactement ce dont j\'ai besoin, mais cela en vaudra la peine.', },
    {'Apporter un Tendon d\'Ancien gorille de Valbrume au Long-voyant Mok\'thardin, à Grom\'gol.', },
  },
  [572] = {
    'Enchantement de Mok\'thardin',
    {'Les matériaux que vous avez collectés sur les félins de la vallée n\'étaient que les premiers ingrédients d\'un puissant objet enchanté. Ces babioles de la jungle combinées à mon rituel chamanique vous fourniront un outil très puissant, au service de la Horde et du chef de guerre.|n|nMais pour l\'heure, vous devez rassembler pour moi quelques plumes de traqueurs de la jungle. Ces créatures portent généralement des plumes sur leurs bras. Vous trouverez un groupe de raptors au sud de Grom\'gol, non loin de la grande arène.', },
    {'Apporter 10 Plumes de Traqueurs de la jungle au Long-voyant Mok\'thardin, au campement Grom\'gol.', },
  },
  [573] = {
    'Enchantement de Mok\'thardin',
    {'Il ne manque plus qu\'un dernier réactif pour compléter l\'enchantement.|n|nAu sud, vers la côte occidentale, loin au-delà des falaises, coule une source sacrée. Elle est à l\'origine d\'un conflit parmi les érudits mystiques et religieux. Chaque race d\'Azeroth proclame que cette source a été rendue divine pour ses propres populations.|n|nLa dernière demande que je vous fais : apportez-moi de l\'Eau de source sacrée. Mais attention. Les nagas ont envoyé des explorateurs qui progressent vers la source. Vous devrez également vous en occuper.', },
    {'Le Long-voyant Mok\'thardin de Grom\'gol a besoin d\'Eau de source sacrée. Il veut que vous tuiez aussi 10 Explorateurs nagas.', },
  },
  [574] = {
    'Forces spéciales',
    {'Maintenant que de nombreux hommes de troupe sont morts, vous devez combattre ses forces hautement entraînées. Lorsqu\'ils ne sont pas dans la nature à massacrer nos soldats rebelles, on peut les trouver au fond de la base de Kurzen, dans un endroit qu\'ils appellent la Réserve.|n|nJe connais personnellement beaucoup des hommes de Kurzen, et sais qu\'ils sont entraînés, loyaux et cruels. Ce n\'est pas une tâche facile que je vous confie là, $N.|n|nAprès les avoir battus, rendez compte au lieutenant Doren, mon officier commandant. Il voudra votre rapport en priorité.', },
    {'Tuez 10 Commandos et 6 Réducteurs de têtes de Kurzen. Rendez compte de votre mission au Lieutenant Doren, au Camp rebelle.', },
  },
  [575] = {
    'L\'offre et la demande',
    {'« Le meilleur travailleur du cuir des mers du Sud et des deux mondes, Ancien et Nouveau ». C\'est comme ça qu\'on m\'appelle. Moi ! Drizzlik ! Le meilleur artisan… Hem. Bon.|n|nMes objets en cuir sont réputés dans le monde entier pour leur perfection – le vrai choix des connaisseurs !|n|nJe viens de recevoir une commande du directeur Riddlevox du Syndicat des Artisans. Il veut une douzaine de ses bottes préférées, le modèle Excelsior (notre meilleure vente, soit dit en passant).|n|nPour mettre en place la forme, j\'ai besoin de peaux de crocilisques. Vous trouverez les meilleurs spécimens le long des rivières, dans le nord de Strangleronce.', },
    {'Apportez 2 Grandes peaux de crocilisque des rivières à Drizzlik, à Baie-du-Butin.', },
  },
  [576] = {
    'Gardez un œil dehors',
    {'Eh, qui va là ?|n|nArgh, je ne vaux rien sans mon œil enchanté spécial. J\'aurais pas dû perdre mes yeux à la guerre pour commencer ! Mais par chance, nous avons débarqué à Menethil et un sorcier de passage a enchanté un œil de verre spécial qui me permet de voir à nouveau.|n|nLa nuit dernière, je me suis retrouvé agressé par des boucaniers de la Voile sanglante alors que je rentrais. Ils ont pris mon œil, oh oui ! On dirait que ces types se sont vite adaptés à Baie-du-Butin.|n|nVous voulez aider un vieux loup de mer à récupérer son œil ?', },
    {'Dizzy le Borgne de Baie-du-Butin veut que vous récupériez son œil chez les boucaniers de la Voile sanglante.', },
  },
  [577] = {
    'La face cachée des bottes',
    {'Bon, la forme des bottes, c\'est fait, et ça se présente bien... Mais les peaux que vous m\'avez fournies ne seront pas suffisantes pour les couches intérieures.|n|n« Qu\'est-ce que nous allons faire, Drizzlik ? » brûlez-vous de me demander. Or, par un merveilleux hasard, c\'est justement à Drizzlik que vous parlez, et il va vous dire ce qu\'on va faire !|n|nL\'intérieur ne sera jamais visible, alors on va se contenter d\'une peau de moindre qualité, plus épaisse, celle des crocilisques du lac Nazfériti.', },
    {'Rapportez 5 Peaux de crocilisque gueule-d\'acier à Drizzlik, à Baie-du-Butin.', },
  },
  [578] = {
    'La pierre des marées',
    {'Si un mage gobelin et des élémentaires d\'eau hantent effectivement l\'île, cela peut vouloir dire que la Pierre des marées peut être mienne !|n|nJe veux que vous localisiez cette île hantée… Découvrez ce qui s\'y passe. Oh ! et si vous voulez en savoir plus sur la Pierre des marées, donnez ce titre à la bibliothèque de Hurlevent, ils devraient être capables de vous trouver une copie du livre dans lequel j\'ai eu vent pour la première fois de cette légende.|n|nSerait-ce possible que ce Gazban ait vraiment découvert la Pierre... ?', },
    {'Localiser l\'Ile hantée pour le baron Revilgaz de Baie-du-Butin.', },
  },
  [579] = {
    'La Bibliothèque de Hurlevent',
    nil,
    nil,
  },
  [580] = {
    'La bibine perdue de Whiskey Slim',
    {'On s\'hum\'ctait l\'gosier féroc\'ment, au large des Hauts-Surplombs, c\' bonnes vieilles Hinterlands dans l\' lointain. Cru qu\'les mers allaient tous nous bouffer.|n|nL\'vieux Slim en c\'nait un bout en bravoure à 40°. L\'cap\'tain\' \'vait une caiss\' de porto Pupellyverbos réquis\'tionnée à un corsair\' s\'rendan\' ta Hurlevent.|n|n\'Lors quand c\'t\' orage prè\' des Hinterlands s\'est pointé, j\'ai fait mon enquête. Une grosse vague a visité l\'endroit et a invité les bouteilles à la gaude. L\'capt\'aine va m\' faire tâter du fouet si vous m\'aidez pas à les ram\'ner.', },
    {'Whiskey Slim de Baie-du-Butin veut que vous lui rameniez les bouteilles de porto Pupellyverbos qu\'il a perdues.', },
  },
  [581] = {
    'La chasse pour Yenniku',
    {'Un sort, c\'est ça. Un sort lancé sur le plus jeune fils de mon chef, Yenniku. Comme la coutume l\'exige chez notre peuple, on l\'a laissé chez les trolls Gurubashi de Zul\'Gurub, mais après que ma tribu, la tribu Sombrelance, a quitté les lieux en compagnie de l\'orc Thrall, nous n\'avons plus revu ce pauvre Yenniku. On m\'a envoyé à Strangleronce depuis la lointaine Orgrimmar, pour rechercher le fils de mon chef.|n|nEt je crois que la tribu des Scalps-rouges le détient.|n|nSi vous vouliez m\'aider, partez à la chasse aux Scalps-rouges. Vous pouvez les trouver au nord. Prenez leurs défenses et revenez me voir.', },
    {'Apporter 9 Défenses de Scalp-rouge à Nimboya au campement Grom\'gol.', },
  },
  [582] = {
    'Les chasseurs de têtes',
    {'Nous devons découvrir si Yenniku est mort.|n|nTuez les Chasseurs de têtes scalps-rouges et prenez leurs Têtes réduites. Vous devez en réunir beaucoup, énormément, pour que je puisse m\'assurer que celle de Yenniku n\'est pas parmi elles.|n|nEt si Yenniku a été tué par les Scalps-rouges, que l\'esprit de leur chef Gan\'zulah soit maudit pour les 600 ans à venir !|n|nPartez, $N. Vous pourrez trouver de nombreux Chasseurs de têtes aux ruines de Zuuldaia et à celles de Zul\'Kunda, le long de la côte au nord.', },
    {'Apporter 20 Têtes réduites à Nimboya au campement Grom\'gol.', },
  },
  [583] = {
    'Bienvenue dans la jungle',
    {'Bienvenue à Strangleronce !|n|nPeut-être n\'êtes-vous pas au courant, mais ce nain, là, n\'est autre que le fils d\'Hemet Nesingwary, le seul et l\'unique, héros de guerre renommé de l\'Alliance, et maître de la chasse au gros gibier. Comme son père, il n\'est pas homme à accueillir facilement les $Gétrangers:étrangères;, mais vous semblez avoir déjà vécu quelques péripéties, $C.|n|nAllez lui parler. C\'est bien le fils de son père, il pourra peut-être vous donner quelques conseils de chasse.', },
    {'Parler à Hemet Nesingwary Jr.', },
  },
  [584] = {
    'Les têtes du clan Scalp-rouge',
    {'La tête de Yenniku n\'était pas parmi celles que vous avez apportées, et je remercie le Grand Serpent pour cela. Mais nous n\'avons pas progressé dans nos recherches pour le retrouver.|n|nNous devons connaître la vérité, et je crains que seuls le Chef du clan Scalp-rouge et son Sorcier la connaissent. Ce sont les ennemis de la tribu Sombrelance et ils n\'avoueront rien d\'eux-mêmes, aussi nous devons extraire la vérité de leurs lèvres mortes.|n|nApportez-moi les têtes de Gan\'zulah et de Nezzliok le Redoutable, et placez-les dans ce chaudron.|n|nIls sont loin à l\'intérieur de Zul\'Kunda. Apportez-moi leurs têtes... nous les ferons alors parler.', },
    {'Apporter la Tête de Gan\'zulah et la Tête de Nezzliok dans le Chaudron bouillonnant au campement Grom\'gol.', },
  },
  [585] = {
    'En parlant avec Nezzliok',
    {'<La tête de Nezzliok parle.>|n|nC\'est vrai. Je sais où l\'enfant Sombrelance a été emmené. Vous m\'avez battu et avez capturé mon esprit, mais je ne dirai rien sans apaisement !|n|nLes Scalps-rouges sont en guerre contre les Casse-crânes. Pour obtenir mes faveurs, volez aux Casse-crânes trois de leurs crânes trophées et apportez-les ici avec nous, pour que mon esprit ait des esclaves dans le Néant. Un crâne doit provenir de la collection de trophées de Balia\'mah, un autre de celle de Ziata\'jai, et le dernier de celle de Zul\'Mamwe.', },
    {'Apporter un Trophée de Balia\'mah, un de Ziata\'jai et un de Zul\'Mamwe dans le Chaudron bouillonnant au campement Grom\'gol.', },
  },
  [586] = {
    'En parlant avec Gan\'zulah',
    {'<La tête de Gan\'zulah parle.>|n|nSoyez $Gmaudit:maudite; ! Et vos ancêtres aussi !|n|nSeuls le sang et la revanche peuvent calmer ma rage, alors si tel est votre souhait… faites ceci :|n|nJetez-vous au cœur des Casse-crânes à l\'est. Massacrez les plus féroces d\'entre eux, et si vous survivez, mesurez-vous à leur chef, Ana\'thek le Cruel. Ha ! Apportez-moi son armure brisée si vous le pouvez !|n|nPuisse-t-il vous démembrer et laisser votre cadavre pourrir sur place.', },
    {'Tuez 8 Chasseurs, 6 Chasseurs de têtes, et 4 Berserkers du clan Casse-crâne.|n|nApportez l\'Armure brisée d\'Ana\'thek au Chaudron bouillonnant, au Campement Grom\'gol.', },
  },
  [587] = {
    'Faire un tabac',
    {'Ah ! La vie en mer. Je ne vais pas dire que c\'est la bonne vie, mais c\'est ma vie.|n|nLorsque j\'arrive au port, j\'aime me trouver une bonne bouteille de tafia et du tabac à priser de qualité. Des habitudes dégoûtantes, mais que serait un pirate sans ses vices, pas vrai ?|n|nAlors vous pouvez imaginer mon dépit lorsque j\'ai découvert que l\'herboriste de la ville était parti et avait vendu sa marchandise. Dire que son chargement a été détourné par ces fichus Écumeurs de la Voile sanglante.|n|nJe parie, $C, que vous pourriez les convaincre de partager, non ?', },
    {'Deeg de Baie-du-Butin veut que vous lui apportiez 15 portions de Tabac à priser.', },
  },
  [588] = {
    'Le sort de Yenniku',
    {'<Nezzliok parle.>|n|nVous avez apaisé le courroux de mon esprit, alors je vais vous révéler ce que vous voulez tant découvrir…|n|nLe jeune Yenniku, il est perdu pour son clan.|n|nIl a été emmené par le féticheur nommé Zanzil le Paria. À présent, Zanzil contrôle son corps et son esprit, et seule la magie la plus puissante, elle pourrait le libérer.|n|nC\'est là une magie que vous n\'avez pas, $C.|n|nPeut-être vos alliés, les Sombrelances de Bambala, à l\'est, ils peuvent vous offrir un espoir de salut pour Yenniku. Mais de cela, je doute.', },
    {'Parler à Kin\'weelay.', },
  },
  [589] = {
    'Les éclats vibrants',
    {'Les légendes parlent d\'un bijou, caché loin au cœur de Strangleronce. Nous l\'appelons la vue de l\'esprit, et il détient de grands pouvoirs. Si vous trouvez ce bijou, alors, peut-être, nous pourrions ramener Yenniku des ténèbres.|n|nJe vais parler aux esprits de la jungle pour localiser la vue de l\'esprit. Tandis que je m\'en occupe, allez dans la Mine aux cristaux, au sud-est d\'ici, et récupérez des éclats vibrants bleus des basilics gueule-de-fer. Ces éclats sont rares, mais nous aurons besoin de leur magie pour faire plier la vue de l\'esprit à notre volonté.', },
    {'Apporter 3 Éclats vibrants bleus à Kin\'weelay au Campement Grom\'gol.', },
  },
  [590] = {
    'Un marché de voleur',
    {'Quoi ?|n|nQuoi ?|n|nVous voulez de l\'argent ? Je ne vous dois pas un sou.|n|nUne lettre ? Quelle lettre ? Oh ! Vous voulez vous battre, alors ? Très bien, $Gmon pote:ma fille;… Allons-y ! Je vous dois de l\'argent…', },
    {'Battre Calvin Montague au Glas.', },
  },
  [591] = {
    'La vue de l\'esprit',
    {'La vue de l\'esprit est gardée par un mage ogre, à l\'est d\'ici et loin au cœur du tertre des ogres mosh\'Ogg. Son nom est Mai\'zoth. Je le connais de l\'époque où les Sombrelances vivaient à Strangleronce. Il est vicieux, et sa magie est puissante.|n|nEt s\'il possède la vue de l\'esprit, alors sa magie le sera encore plus.|n|nVous devez combattre Mai\'Zoth et lui arracher la vue de l\'esprit. C\'est une tâche périlleuse, mais c\'est le seul espoir que nous avons de sauver Yenniku.', },
    {'Apportez la Vue de l\'esprit à Kin\'weelay au Campement Grom\'gol.', },
  },
  [592] = {
    'Il faut sauver Yenniku',
    {'J\'ai façonné la vue de l\'esprit dans une gemme d\'âme. Cette gemme possède deux fonctions : vous devez d\'abord l\'utiliser pour étourdir Yenniku et, une fois qu\'il est inconscient, placer la gemme sur sa tête afin d\'emprisonner son âme.|n|nPuis apportez la gemme à Nimboya.|n|nYenniku demeure en compagnie de Zanzil le Paria le long du rivage de Cristal du lointain cap Strangleronce.', },
    {'Apportez la Gemme d\'âme remplie à Nimboya.', },
  },
  [593] = {
    'Une âme pour la gemme',
    nil,
    nil,
  },
  [594] = {
    'Message dans une bouteille',
    {'La note dit, d\'une écriture plutôt élégante :|n|nÀ quiconque peut m\'aider,|n|nJe vous en prie, j\'ai désespérément besoin d\'aide. Un grand Crin-de-ciel me détient captive sur une île des mers du Sud.|n|nLes étoiles, la nuit, me sont étrangères et sont obscurcies par les arbres de la jungle. Mais les jours les plus clairs, je distingue le Rivage cruel au nord-ouest, et ce qui semble être de grands vaisseaux au sud-ouest.|n|nJe vous en supplie, mon possible sauveur, venez m\'aider.', },
    {'Trouver la main qui a écrit ce message lancé à la mer dans une bouteille.', },
  },
  [595] = {
    'Les boucaniers de la Voile sanglante',
    {'Vous avez l\'air de vouloir travailler, $Gmon pote:ma belle;. J\'ignore pourquoi $Gun:une:c; $C viendrait offrir son aide aux Écumeurs des Flots noirs, mais je ne vais pas la refuser.|n|nNotre bateau vient juste d\'arriver à Baie-du-Butin et on dit que nos rivaux, ces abjects boucaniers de la Voile sanglante, ont été aperçus partout au sud de Strangleronce.|n|nTous les gars sont trop occupés à boire et à courir les jupons ! J\'ai besoin que quelqu\'un aille voir, $N.|n|nAllez à la crique au nord de Baie-du-Butin, le long de la Côte sauvage et voyez ce que vous pouvez trouver.', },
    {'Le Second Crazz veut que vous contrôliez la crique au nord de Baie-du-Butin.', },
  },
  [596] = {
    'Les Colliers d\'os ensanglantés',
    {'J\'ai été envoyé à Grom\'gol pour aider Nimboya dans sa quête, mais j\'ai aussi des raisons personnelles d\'être là.|n|nLa tribu des Scalps-rouges est l\'ennemie de la nôtre. Collecter les trophées de nos ennemis nous donne du pouvoir sur eux. Vous pouvez aider notre tribu en chassant nos ennemis.|n|nIls vivent au nord. Massacrez des trolls scalps-rouges et prenez leurs Colliers d\'os ensanglantés. Trouvez-en beaucoup, et grande sera votre récompense.', },
    {'Apporter 25 Colliers d\'os ensanglantés à Kin\'weelay au Campement Grom\'gol.', },
  },
  [597] = {
    'Les boucaniers de la Voile sanglante',
    {'La carte montre Baie-du-Butin avec un « X » rouge dessiné précisément à l\'endroit où vous vous trouvez.|n|nLe texte gribouillé dit :|n|n« Vous devez préparer un camp à cet endroit et rester tranquilles. Attendez le signal du poste de commandement du sud avant d\'attaquer. Si quiconque approche, tuez-le. »', },
    {'Rendre compte de vos découvertes au Second Crazz à Baie-du-Butin.', },
  },
  [598] = {
    'Collier d\'os brisés',
    {'À présent que vous avez collecté les trophées des Scalps-rouges, j\'ai une autre tâche pour vous. La tribu des trolls casse-crânes vit au sud-est, et nous sommes en guerre contre eux depuis des années. Bien que les Sombrelances ne vivent plus à Strangleronce, nous sommes toujours en conflit avec les Casse-crânes.|n|nAussi, chassez-les. Collectez leurs colliers d\'os brisés et revenez me voir. Aidez-nous dans notre guerre, et vous gagnerez l\'amitié des Sombrelances.', },
    {'Apporter 25 Colliers d\'os brisés à Kin\'weelay au Campement Grom\'gol.', },
  },
  [599] = {
    'Les boucaniers de la Voile sanglante',
    {'Bon sang ! Ainsi les boucaniers de la Voile sanglante préparent une attaque contre Baie-du-Butin ? Eh bien ! Ces crapules ne manquent pas d\'air. Mais Baie-du-Butin restera dirigée par les Écumeurs des Flots noirs !|n|nC\'est plus grave que je ne le croyais. Allez dire ce que vous avez appris à l\'amiral Corne-de-Mer immédiatement ! Ce vieux loup de mer est quelque part en ville...', },
    {'Rendre compte de l\'attaque que prépare la Voile sanglante à l\'amiral Corne-de-Mer.', },
  },
  [600] = {
    'Les mines de la KapitalRisk',
    {'La KapitalRisk possède un réseau d\'opérateurs à travers Strangleronce qui empêche les gobelins durs à la tâche, comme moi, de faire de l\'or honnête ! S\'il vous plaît, vous devez m\'aider !|n|nLa KapitalRisk exploite une mine près de la mine aux cristaux, au nord. Ils ne peuvent pas entrer dans la mine à cause de nombreux basilics, mais ils peuvent toujours extraire des cristaux chantants des collines environnantes.|n|nDérobez leurs cristaux, et montrez-leur que la jungle ne leur appartient pas.|n|nEt... euh... apportez-moi ces cristaux comme preuve !', },
    {'Apporter 10 Cristaux bleus chantants à Grincheux Bullévente, à Baie-du-Butin.', },
  },
  [601] = {
    'Les élémentaires d\'eau',
    {'Les élémentaires d\'eau étaient sans nul doute invoqués par Gazban, le sorcier gobelin. D\'après la rumeur, il aurait découvert la pierre des marées. Comme vous le savez peut-être, cette pierre lance une malédiction sur son porteur, le faisant apparaître et disparaître...|n|nPeut-être pouvons-nous trouver un moyen de neutraliser cette malédiction. Nous pourrions demander à un mage de Dalaran d\'analyser le résidu magique des bracelets de l\'un des élémentaires d\'eau. Il faut que vous retourniez sur l\'île et que vous rapportiez quelques échantillons.', },
    {'Récupérez 6 Bracelets d\'élémentaire d\'eau pour le Baron Revilgaz à Baie-du-Butin.', },
  },
  [602] = {
    'L\'analyse magique',
    {'D\'après ce que j\'ai entendu, les mages de Dalaran ont réussi à reconstruire leur ville magique et à la déplacer en Norfendre, laissant derrière eux un énorme cratère. Mais quelques mages sont tout de même restés, et ils seront ravis de prendre un peu de temps pour examiner les bracelets. S\'il y a une chose que je sais à propos des mages, c\'est qu\'ils ne peuvent résister à une énigme magique.|n|nPrenez le sac de bracelets d\'élémentaires d\'eau et voyez s\'ils peuvent apporter quelque lumière sur la malédiction de la pierre des marées. Cherchez l\'archimage Ansirem Tisserune. J\'ai déjà eu affaire à lui par le passé, et grand est son savoir.', },
    {'Apportez les Bracelets d\'élémentaires d\'eau à l\'Archimage Ansirem Tisserune, au Cratère de Dalaran.', },
  },
  [603] = {
    'La Clé d\'Ansirem',
    {'Le mage qui analyse la Pierre amplifie son pouvoir à travers un point focal… Un autel d\'un certain genre. Vous devriez pouvoir le mettre hors d\'état en le surchargeant.|n|nEt de fait, je sais ce qu\'il vous faut : une dague ancienne, une relique des trolls. Il n\'y a qu\'un... léger problème.|n|nVous voyez, j\'ai trouvé la dague tandis que j\'effectuais des recherches à Strangleronce, mais je l\'ai donnée à ma fille entêtée, Catelyn, qui est partie à Baie-du-Butin pour devenir pirate.', },
    {'Parler à Catelyn à Baie-du-Butin.', },
  },
  [604] = {
    'Les boucaniers de la Voile sanglante',
    {'Crazz parle en termes flatteurs de votre dévouement envers les Écumeurs des Flots noirs. Je vais vous charger d\'une mission très importante pour la flotte.|n|nInfiltrez le prétendu poste de commande méridional que les boucaniers de la Voile sanglante ont établi sur le Rivage cruel. Faites une incursion dans le camp. Apportez-moi leurs cartes et leurs ordres écrits. Nous verrons exactement ce que cette vermine prépare.', },
    {'L\'amiral Corne-de-Mer à Baie-du-Butin veut que vous tuiez 10 Bretteurs de la Voile sanglante et que vous rapportiez les Cartes de la Voile sanglante et les Ordres de la Voile sanglante.', },
  },
  [605] = {
    'Les éclats bleus chantants',
    {'Les cristaux chantants sont uniques à Strangleronce, et très précieux pour certains. Je peux transporter les cristaux, mais cette maudite KapitalRisk fait en sorte qu\'un honnête entrepreneur comme moi ne puisse pas en collecter.|n|nJ\'aimerais vous embaucher.|n|nLes basilics, à Strangleronce, mangent les cristaux. C\'est ce qui durcit leur peau, et parfois, on peut récolter sur eux du cristal de bonne qualité.|n|nVous pouvez en trouver sur n\'importe quel basilic, mais les moins terribles se trouvent le long du rivage, plus au nord.', },
    {'Apportez 10 Éclats de cristal chantant à Grincheux Bullévente.', },
  },
  [606] = {
    'Effrayer Philippe le Chancelant',
    {'S\'il y a bien une chose que je ne supporte pas, ce sont les gens qui ne règlent pas leurs dettes de jeu ! Et il y en a beaucoup dans ce cas. Pourriez m\'aider à récupérer ce qu\'on me doit ? ?|n|nD\'abord, il y a Phillipe « le Trembleur », là-bas, près des quais. Il me doit une grosse somme après notre partie de cartes de la semaine dernière, et je veux récupérer mon argent. Mais pour l\'obtenir, il va falloir lui faire peur.|n|nSortez de la ville et chassez de vieux gorilles de Valbrume. Sortez-leur les tripes et apportez-les au Trembleur. Ne lui dites pas que ça vient d\'un animal, il faut qu\'il s\'imagine le pire.', },
    {'Apportez 5 Abats de Valbrume à Phillippe le Chancelant à Baie-du-Butin.', },
  },
  [607] = {
    'De retour chez MacKinley',
    {'Tenez, prenez cette bourse et donnez-la à Loup des Mers. Et dites-lui que je comptais le rembourser ! Je le jure !|n|nJ\'étais juste un peu saoul et je me suis perdu et… vous savez comment sont les choses. Il comprendra, vous n\'avez pas besoin de devenir $Gbrutal:brutale;.', },
    {'Apportez le Paiement de Philippe le Chancelant à MacKinley « Loup des mers ».', },
  },
  [608] = {
    'Les boucaniers de la Voile sanglante',
    {'Maudit soit le toupet de Firallon ! Il ne pourrait même pas diriger une yole sur le lac de Cristal, et encore moins mener une flotte entière contre nous.|n|nLes boucaniers de la Voile sanglante vont payer leur négligence. À présent que nous connaissons leur plan d\'attaque, nous pouvons les contrer avant même qu\'ils ne sachent ce qui les frappe.|n|nMais pourquoi envoyer la flotte entière faire le travail d\'un courageux groupe d\'aventuriers ? $N, dirigez certains de vos meilleurs camarades au mouillage de Firallon et assassinez les dirigeants de la Voile sanglante. Leur flotte coulera peu après.', },
    {'L\'Amiral Corne-de-Mer de Baie-du-Butin veut que vous tuiez le Capitaine Eau-Plate, le Capitaine Soulaquille et l\'Amiral Firallon.', },
  },
  [609] = {
    'Gages vaudou',
    {'Ma liste se réduit, mais certains me doivent encore de l\'argent.|n|nAprès, il y a Maury « Pied bot » Wilkins, Jon-Jon le Corbeau et Chucky « Dix pouces ».|n|nLes dettes de ces chiens remontent à des mois et je pensais qu\'ils avaient quitté la ville pour éviter de payer ! Plus tard, j\'ai appris qu\'ils étaient maudits et ensorcelés. À présent, ils courent la jungle. Mais je me fiche de leur sort, je veux récupérer ce qui m\'appartient !|n|nIls se trouvent dans les ruines d\'Aboraz et dans les ruines de Jubuwai, au nord-est. Trouvez-les, et rapportez-moi mon dû.', },
    {'Apportez le Pied bot de Maury, la Longue-vue dorée de Jon-Jon, et le Grand anneau de Chucky à MacKinley « Loup des mers » à Baie-du-Butin.', },
  },
  [610] = {
    'Duncan « le Beau garçon »',
    {'Mon PÈRE vous envoie ? J\'aurais cru qu\'il m\'aurait totalement oubliée.|n|nCe n\'est pas vraiment sa faute si je suis partie, il ne pouvait simplement pas imaginer que je ne voudrais pas vivre une vie ennuyeuse, à lire et relire des livres moisis et à devenir un de ces vieux mages livides aux cheveux blancs !|n|nSi ma dague vous intéresse, vous devrez la récupérer chez Duncan « le Beau garçon », l\'un des boucaniers de la Voile sanglante. Plantez quelque chose entre ses épaules et je suis certaine qu\'il y renoncera.', },
    {'Récupérer la Dague de Catelyn auprès de Duncan « le Beau garçon ».', },
  },
  [611] = {
    'La malédiction des marées',
    {'Ainsi vous recherchez un autel d\'un certain genre ? Eh bien ! Je ne suis pas experte en ruines trolles comme peut l\'être mon père, mais j\'ai entendu parler d\'une cité trolle engloutie près de cette île que vous cherchez. Peut-être devriez-vous essayer là-bas ?|n|nVous avez récupéré mon couteau, alors je suppose que vous pouvez l\'emprunter... Mais je veux que vous me le rendiez quand vous aurez fini !', },
    {'Détruire l\'Autel des Marées avec la Lame de Catelyn, tuer Gazban et rapporter la Pierre des Marées et la Lame de Catelyn au baron Revilgaz.', },
  },
  [612] = {
    nil,
    {'J\'ai peu d\'espoir, mais essayez de convaincre Catelyn de se séparer de sa dague ? Le cœur d\'un collectionneur, vous savez ce que c\'est…|n|nPeut-être que si vous dites que c\'est pour moi, elle sera plus disposée à me la vendre ?', },
    {'Rendre sa lame à Catelyn.', },
  },
  [613] = {
    'Le pied-bot de Maury',
    {'Malédiction ! Ce malade de Maury a mis un verrou sur son pied-bot, et je ne peux pas l\'ouvrir ! Son butin est à l\'intérieur, et c\'est ce qu\'il me doit !|n|nNous devons trouver la clé pour ouvrir le verrou. Maury était connu pour jouer avec les ogres mosh\'Ogg, sur leur colline au nord-est. Et il m\'a dit un jour que la dernière fois qu\'il était allé là-bas, il avait été coursé après avoir trop gagné. Peut-être que ces ogres ont sa clé.|n|nMais s\'ils l\'ont, il se peut que vous deviez en tuer beaucoup avant de trouver celui qui la détient...', },
    {'Apportez la Clé de Maury à MacKinley « Loup des mers » à Baie-du-Butin.', },
  },
  [614] = {
    'Le coffre du capitaine',
    {'Dans le passé, je pilotais un navire d\'ici jusqu\'à Cabestan, en Kalimdor. J\'étais un grand capitaine avec une solide réputation.|n|nJusqu\'à ce que…|n|nCes maudits géants des mers m\'apportent la ruine ! Ils ont détruit mon bateau, tué mon équipage, et m\'ont abandonné dans un canot. Et l\'un d\'eux, Gorlash, a volé mon coffre de capitaine. Il a dit qu\'il le voulait pour en faire une tabatière. Quel toupet !|n|nJe sais que Gorlash sillonne la côte à l\'est d\'ici. Trouvez-le et récupérez mon coffre ! Faites-le, et vous gagnerez la gratitude d\'un capitaine.', },
    {'Apportez son Coffre au capitaine Hecklebury Smotts à Baie-du-Butin.', },
  },
  [615] = {
    'Le sabre du capitaine Smotts',
    {'Après que mon premier navire a été détruit par ces géants, j\'en ai acheté un autre. Je l\'ai baptisé le Revanche de Smotts, j\'ai trouvé un nouvel équipage, j\'ai rempli les cales de marchandises, puis j\'ai appareillé pour retrouver ces misérables géants. Je les ai trouvés, et de nouveau ils m\'ont battu. Ils ont détruit le Revanche de Smotts, tué presque tout mon équipage et jeté les rescapés dans un canot.|n|nCette fois, un autre géant, Negolash, m\'a volé mon sabre.|n|nCombattez Negolash et rapportez-moi mon sabre !|n|nParlez à Bizutard. C\'était mon cuistot sur le Revanche de Smotts et il a survécu à la dernière attaque. Il peut vous aider à trouver le géant.', },
    {'Parler à Bizutard.', },
  },
  [616] = {
    'L\'île hantée',
    {'Le baron Revilgaz m\'a chargé de laisser traîner une oreille sur les rumeurs concernant les événements étranges ou surnaturels qui surviennent à Baie-du-Butin et à Strangleronce. Je ne donne généralement pas beaucoup de crédit aux histoires de fantômes, mais j\'ai entendu des marins à la taverne parler d\'une île hantée près de la côte. Des élémentaires d\'eau et un fantôme de gobelin qui divague, qu\'ils disent.|n|nSi vous allez parler à Revilgaz, pourriez-vous lui faire part de cette histoire ?', },
    {'Parler au Baron Revilgaz, à Baie-du-Butin.', },
  },
  [617] = {
    'De derrière les fagots',
    {'Vous cherchez du boulot, $N ? J\'en ai p\'têt\' si vous vous sentez $Gprêt:prête; à relever un p\'tit défi.|n|nJ\'ai un ami, nommé Groy, qui fait un malheur en vendant c\'que les nagas appellent des roseaux akiris : c\'t\'un genre de roseau marin qu\'a d\'la valeur. Je n\'sais pas trop à quoi ça sert, mais on paye cher pour des lots d\'ce truc.|n|nApportez-m\'en dix tiges, et nous ferons des affaires. Les nagas ont été vus dernièrement le long de la plage, au nord.', },
    {'Apporter 10 Roseaux akiris au Corsaire Bloads à Baie-du-Butin.', },
  },
  [618] = {
    'Face à Negolash',
    {'Negolash est un goinfre.|n|nQuand les géants ont détruit notre navire, il est venu directement dans ma cuisine. Il n\'avait pas faim d\'hommes d\'équipage comme les autres géants. Negolash voulait du vin et mes ailes de busard grillées au barbecue. C\'est ma spécialité, et j\'ai dû me rendre jusqu\'aux Terres ingrates pour avoir la recette !|n|nSi vous voulez tendre un piège au géant, trouvez du vin et un monceau d\'ailes de busard. Placez-les dans notre vieux canot, au sud-est, le long de la côte. Quand Negolash sentira cette bonne nourriture, il rappliquera, sans aucun doute !', },
    {'Apporter 10 Ailes de busard grillées et 5 bouteilles de Vin de Junglevigne dans le Canot de sauvetage du capitaine Smotts.|n|nTuer Negolash, et apporter le Sabre d\'abordage de Smotts au capitaine Smotts, à Strangleronce.', },
  },
  [619] = {
    'Allécher Negolash',
    nil,
    nil,
  },
  [620] = {
    'L\'écharpe à monogramme',
    {'On peut lire les lettres "HS" brodées le long de l\'ourlet de la belle écharpe.', },
    {'Rendre l\'Echarpe à monogramme à son propriétaire.', },
  },
  [621] = {
    'Le secret de Zanzil',
    {'Zanzil le Paria demeure avec ses partisans dans les Ruines de Jubuwal et dans celles d\'Aboraz, au nord-est de Baie-du-Butin. Il a été banni de sa tribu. Pourquoi ? Eh bien… |n|nZanzil a le pouvoir de soumettre la volonté des autres, et ses chefs ont peur de lui. Il utilise un mélange de plantes tropicales pour supprimer la volonté et endurcir le corps de ses partisans.|n|nCette préparation intéresse beaucoup ceux qui voudraient contrôler les autres.|n|nApportez-moi des échantillons de ce mélange, et je leur trouverai une utilité.', },
    {'Apporter 12 Échantillons de Mixture de Zanzil à Grincheux Bullévente à Baie-du-Butin.', },
  },
  [622] = {
    'La cocotte du caporal Kaleb',
    {'Pendant que vous étiez $Gparti:partie; j\'ai réparé la cocotte que vous m\'aviez apportée. J\'y ai même ajouté un autre sifflet à vapeur, et regardez : il y a un hachoir au fond pour réduire les os de pattes en bouillie ! Oui ! La Cocotte ébréchée de Krazek ravira tout cuisinier à 100% ! Je suis sûr que son propriétaire en sera satisfait.', },
    {'Apporter la Cocotte réparée de Krazek au caporal Kaleb, au Camp rebelle.', },
  },
  [623] = {
    'De derrière les fagots',
    {'$N, puisque vous êtes là : j\'ai reçu un message de Groy pendant que vous étiez $Gparti:partie;. Il dit être satisfait de la dernière livraison, mais il a un client qui en désire plus, et tout de suite.|n|nJe ne vais pas à Theramore avant une semaine, mais si vous faites le voyage, vous pourriez transporter la marchandise pour moi.|n|nUn peu d\'aventure vous tente ? Vous savez où se trouve Âprefange, n\'est-ce pas ? Je ferais attention quand même, Theramore peut être dangereuse si vous n\'avez pas le bon profil.', },
    {'Apportez un Fagot de roseaux akiris au corsaire Groy à Theramore.', },
  },
  [624] = {
    'Devinette de Cortello',
    {'Il est un pont fleuri, beaucoup emprunté|nÀ l\'est de Deuillevent et au sud des Carmines|nDessous, quelque chose vous attend|n|nCertains l\'appellent allusion, d\'autres indice|n|nIl reposera là pour d\'éternels lendemains|n|nPrenant son temps dans le marais des Chagrins.', },
    {'Résoudre l\'énigme.', },
  },
  [625] = {
    'Devinette de Cortello',
    {'Une terre lointaine en Kalimdor attend|nOù le péril a brisé espoirs et destinées|nÀ l\'est des Tarides le temps est sévère|nTénèbres et dangers criblent le marécage d\'Âprefange|nMais là est un indice pour ceux qui prennent le risque|nAttendant d\'être découvert dans une caverne au sud-ouest.', },
    {'Résoudre l\'énigme.', },
  },
  [626] = {
    'Devinette de Cortello',
    {'À Lordaeron ! La grande terre de bouleversements|nOù le soldat courageux fait de la mort son métier|nTrouvez votre chemin à travers l\'agitation|nVous trouverez le fin mot de la quête|nLe long de la côte des Hinterlands, au pied des grandes chutes|nSous l\'eau, c\'est là que votre trésor vous appelle !', },
    {'Résoudre l\'énigme.', },
  },
  [627] = {
    'Un service pour Krazek',
    {'Il y a une caverne dans la montagne, dans la gorge des Sèches-moustaches, loin au nord dans les hautes-terres Arathies. Cette caverne abrite un minerai rare : la pierre de sang. Celle de cette caverne n\'est pas de la meilleure qualité, mais elle a quand même une certaine valeur...|n|nJ\'en aimerais un peu.|n|nJe vais réparer votre cocotte, mais pendant que j\'y travaille, allez chercher des fragments de pierre de sang. Apportez-m\'en assez, et je vous donnerai un bonus.|n|nEt si vous n\'avez pas la capacité de l\'extraire... trouvez quelqu\'un qui le peut !', },
    {'Apporter 4 chargements de Minerai de pierre de sang inférieur à Krazek à Baie-du-Butin.', },
  },
  [628] = {
    'L\'Excelsior de chez Drizzlik',
    {'Maintenant que l\'intérieur est terminé, tout ce qui reste à faire est la couche extérieure. Pour ça, je n\'utilise que les meilleures peaux de vieux crocis. Elles sont plus souples et solides, avec de belles écailles ; toutes les qualités qui définissent la gamme Excelsior de Drizzlik.|n|nIl est difficile de trouver des peaux parfaites, et celles qui me conviennent le mieux proviennent des vieux crocilisques marins. Les vieux ne sortent que pour défendre les autres crocis marins, alors il faudra en occire quelques-uns avant d\'attirer un vieux.', },
    {'Apporter une Peau d\'ancien crocilisque à Drizzlik, à Baie-du-Butin.', },
  },
  [629] = {
    'Le récif infâme',
    {'Il y a longtemps, un grand tremblement de terre engloutit une ancienne cité trolle sous les eaux de la Côte sauvage au nord-ouest. Nous appelons cet endroit le Récif infâme, car ce sont les murlocs qui à présent résident dans les ruines de la cité, attaquant tous ceux qui s\'en approchent.|n|nUne vieille tablette repose parmi ces ruines, racontant l\'histoire du héros troll Gri\'lek. Cette légende est sacrée pour la tribu Sombrelance, et bien que la tablette soit trop lourde pour qu\'on puisse la bouger, j\'en veux un fragment pour le conserver dans notre nouvelle demeure, à Orgrimmar.', },
    {'Apporter un Fragment de tablette à Kin\'weelay au Campement Grom\'gol.', },
  },
  [630] = {
    'Message dans une bouteille',
    {'$N, je remets mon sort entre vos mains et entre celles de tous ceux que vous pourrez réunir pour me libérer. Le roi Mukla, le grand Crin-de-ciel, est mon ravisseur. Il commande aux bêtes de l\'île et me retient contre ma volonté. Si vous pouviez le combattre et trouver la clé qui ouvre mes chaînes, je vous serais grandement redevable.|n|nJe l\'entends souvent dans la partie sud-est de l\'île, mais je vous en prie, soyez $Gprudent:prudente;, il ne doit pas être abordé à la légère.', },
    {'Tuez le roi Mukla, et revenez auprès de la princesse Poobah avec la clé afin de la libérer.', },
  },
  [631] = {
    'Le viaduc de Thandol',
    {'Une explosion monstrueuse a grondé à travers les collines. C\'tait horrible, j\'vous l\'dis !|n|nDe bons soldats sont morts en défendant le viaduc de Thandol. Tresse-longue dit que nous prendrons notre revanche sur les Sombrefers avant que tout cela ne soit fini.|n|nIci, il n\'y a que des blessés, et je ne vois aucun renfort arriver à l\'horizon. Tresse-longue a envoyé le vieux Bouclerouille en reconnaissance au pont à l\'est, pour voir si nous pouvions le sécuriser.|n|nC\'était il y a plusieurs jours. Avec Dun Modr en état de siège, nous n\'avons pas les ressources d\'aller le chercher.|n|nPeut-être pourriez-vous le trouver...', },
    {'Rhag Garmaçon veut que vous retrouviez le vieux Bouclerouille.', },
  },
  [632] = {
    'Le viaduc de Thandol',
    {'Il semblerait que le pauvre vieux Bouclerouille soit tombé dans une embuscade de Sombrefer. Vous remarquez un parchemin froissé dans son poing serré.|n|nApportez la triste nouvelle à Rhag Garmaçon et montrez-lui ce que vous avez trouvé.', },
    {'Présentez-vous à Rhag Garmaçon à Dun Modir, dans les Paluns et montrez-lui le parchemin que vous avez trouvé sur le corps de Bouclerouille.', },
  },
  [633] = {
    'Le viaduc de Thandol',
    {'Par le Ciel, non ! Pauvre Bouclerouille. C\'est une tragédie !|n|nNous ne devons pas laisser sa mort impunie. Le parchemin qu\'il tenait indique que Kam Furie-du-fond, le cerveau derrière la première attaque, a fait entreposer des explosifs dans une cache, juste de l\'autre côté du viaduc de Thandol, dans les hautes-terres Arathies.|n|nSi ces explosifs atteignent le pont, notre principale ligne d\'approvisionnement vers le nord sera très compromise. La cache doit être détruite, $N. Revenez me voir lorsque votre mission sera accomplie.|n|nVous êtes notre seul espoir.', },
    {'Détruire la cache d\'explosifs.', },
  },
  [634] = {
    'L\'appel à l\'Alliance',
    {'J\'aimerais vous demander un autre petit service, $C. Nous attendons les troupes de réserve de Forgefer. Cependant, Roggo connaît l\'existence d\'un camp de l\'Alliance, au nord sur les hautes-terres Arathies, au Refuge de l\'Ornière.|n|nAllez-y et cherchez le capitaine Nials. Demandez-lui si l\'Alliance peut nous prêter quelques soldats pour nous aider à reprendre Dun Modr et le viaduc de Thandol.', },
    {'Chercher le capitaine Nials au Refuge de l\'Ornière, dans les Hautes-terres Arathies.', },
  },
  [635] = {
    'Le cristal dans les montagnes',
    {'L\'éclat vibre tandis que vous le tenez…|n|nVous ressentez comme un appel, comme si quelqu\'un essayait de communiquer, quelqu\'un qui avait désespérément besoin de votre aide.|n|nUne vision apparaît dans votre esprit. Une vision des monts Arathi, et d\'un cristal brillant saillant de la terre, là-bas.|n|nVous vous sentez $Gattiré:attirée; par cet endroit.', },
    {'Trouver le cristal de votre vision.', },
  },
  [636] = {
    'Légendes de la terre <NYI>',
    {'Ce livre raconte l\'histoire d\'une princesse élémentaire, Myzrael, et de son emprisonnement loin sous les hautes-terres Arathies.|n|nIl évoque également un affleurement secret de cristaux, en surface. Ces cristaux, les Éclats de Myzrael, forment une fenêtre sur la prison de la princesse.|n|nSi une âme courageuse trouve les Éclats de Myzrael, alors peut-être pourra-t-elle lui parler...', },
    {'Trouver les Éclats de Myzrael.', },
  },
  [637] = {
    'Lettre de Sully Balloo',
    {'L\'enveloppe imbibée d\'eau et déchirée se dissout et laisse dans vos mains quelques pages d\'une lettre, écrite avec soin.|n|nLa lettre est adressée à Mme Sara Balloo de Forgefer et commence par les mots : « Ma chère Sara… »', },
    {'Donner la Lettre de Sully Balloo à Sara Balloo.', },
  },
  [638] = {
    'Trollemort',
    {'Thoras Trollemort étant tombé, et Stromgarde en ruine, Vol\'jin a donné pour instructions que nous mettions tout en œuvre pour dérober l\'épée légendaire Trol\'kalar, qui est aux mains des humains, afin de l\'utiliser dans nos futurs combats contre les trolls de Zul\'Gurub.|n|nZengu, l\'un de nos chasseurs aguerris, a été envoyé au Trépas-d\'Orgrim, dans la partie nord-est des hautes-terres Arathies, pour veiller à son obtention.', },
    {'Aller au Trépas-d\'Orgrim dans les Hautes-terres Arathies et parler à Zengu.', },
  },
  [639] = {
    'Cachet de Strom',
    {'Dans des temps anciens, les trolls se battaient contre l\'empire arathorien et notre plus vaillant adversaire était le seigneur Ignaeus de Strom, dit Trollemort. Il se lançait dans la bataille en brandissant Trol\'kalar, ce qui dans leur langue voulait dire « tueuse de trolls ».|n|nMais aujourd\'hui les fils de Trollemort sont affaiblis et leur forteresse est en ruine.|n|nL\'épée est protégée par de nombreux cachets qui ont été répartis entre les survivants de Stromgarde, et nous devons les retrouver.|n|nLe premier a été pris par le Syndicat, l\'un de leurs hommes à Stromgarde devrait l\'avoir.', },
    {'Trouver le Cachet de Strom pour Zengu au Trépas-d\'Orgrim.', },
  },
  [640] = {
    'Le cachet qui fut brisé',
    {'La tombe de Thoras Trollemort est protégée par trois cachets. Vous avez récupéré le premier auprès du Syndicat. Les deux autres seront plus difficiles à obtenir, car ils sont détenus par la milice fortement retranchée de Stromgarde.|n|nLe cachet de Thoradin a été brisé en cinq morceaux par le fils de Thoras, Galen, et dispersé entre les défenseurs de Stromgarde. Retrouvez les morceaux et apportez-les à Tor\'gan, le chaman troll, il les assemblera pour reconstituer le cachet complet.', },
    {'Reprendre les 5 Fragments de cachet aux défenseurs de Stromgarde, puis les apporter à Tor\'gan au Trépas-d\'Orgrim.', },
  },
  [641] = {
    'Cachet de Thoradin',
    {'Le cachet a retrouvé son intégrité et peut désormais permettre d\'ouvrir le sceau sur la tombe de Trollemort. Apportez-le à Zengu, il ne fait pas de doute qu\'il a d\'autres tâches à vous confier.', },
    {'Apportez le Cachet de Thoradin reconstitué à Zengu, au Trépas-d\'Orgrim.', },
  },
  [642] = {
    'La princesse emprisonnée',
    {'Mon nom est Myzrael. Je suis une princesse de la terre et mes ravisseurs, les géants, m\'ont emprisonnée loin sous les hautes-terres Arathies. Ces éclats de cristal sont le seul moyen dont je dispose pour communiquer avec le monde de la surface.|n|nPar pitié, aidez-moi. Les alliés des géants, les kobolds sèches-moustaches, possèdent un de ces éclats à la gorge des Sèches-moustaches, à l\'est. Pour l\'activer, vous devez collecter des poussières de Myzrael sur les kobolds, puis les y appliquer.|n|nJe vous en supplie, $N, venez à mon secours !', },
    {'Collecter 12 Poussières de Myzrael, puis les répandre sur les Éclats iridescents, dans la gorge des Sèches-moustaches.', },
  },
  [643] = {
    'Cachet d\'Arathor',
    {'Bien qu\'on puisse dire qu\'il contrôle tout juste Stromgarde, et certainement pas toutes les hautes-terres Arathies, le prince humain fait courir la campagne aux restes de sa cavalerie. Je ne comprends pas pourquoi, mais qui peut comprendre la façon dont pensent les humains, hein ?|n|nLe plus important, c\'est qu\'il ait donné l\'un des cachets au lieutenant Vaillehuche, commandant sa cavalerie. Trouvez-le et rapportez-moi son cachet.', },
    {'Retrouver le Cachet d\'Arathor et l\'apporter à Zengu, au Trépas-d\'Orgrim.', },
  },
  [644] = {
    'Cachet de Trollemort',
    {'Le dernier cachet dont nous avons besoin pour ouvrir la tombe de Thoras Trollemort est détenu par son fils en personne. Il vit loin à l\'intérieur de Stromgarde, dans une chapelle des quartiers contrôlés par la milice. Le prince Galen est bien protégé et n\'est pas maladroit à la guerre non plus, aussi cette tâche pourrait s\'avérer très ardue.', },
    {'Tuez le Prince Galen Trollemort et apportez le Cachet de Trollemort à Zengu, au Trépas-d\'Orgrim.', },
  },
  [645] = {
    nil,
    {'Qu\'est-ce donc ? Une fois les quatre cachets réunis, ils se sont rassemblés pour n\'en former qu\'un seul. Celui-ci pourra sans aucun doute désactiver la garde placée sur la tombe de Trollemort.|n|nSes restes sont ensevelis dans le sanctuaire derrière la chapelle de Stromgarde. Rapportez Trol\'kalar.', },
    {'Retirer Trol\'kalar de la tombe de Trollemort à Stromgarde.', },
  },
  [646] = {
    nil,
    {'La lumière s\'éteint, doucement, et l\'épée Trol\'kalar, reposant dans un fourreau de pierre, est libérée.', },
    {'Apporter Trol\'kalar à Zengu au Trépas-d\'Orgrim.', },
  },
  [647] = {
    'Tord-boyaux de MacKreel',
    {'J\'ai bu pas mal de mon bon vieux tord-boyaux la nuit dernière ! Tresse-longue aurait ma tête s\'il savait que je me suis endormi pendant mon tour de garde.|n|nL\'alcool a frappé fort. Je me sentais comme si une brigade entière de machines de siège m\'était passée sur le crâne, avec tous ces grondements.|n|nBon sang, regardez l\'heure ! J\'ai promis au brasseur Sentine d\'Austrivage que je lui paierai ma dette en lui envoyant du tord-boyaux.|n|nMais il ne reste que 15 minutes, après je serai en retard ! Apportez-lui ce lot, s\'il vous plaît ! Et dépêchez-vous !', },
    {'Apporter le Tord-boyaux de MacKreel au brasseur Sentine à Austrivage.', },
  },
  [648] = {
    'À la rescousse de OOX-17/TN !',
    {'Le robot émet à nouveau la voix du gnome :|n|n« Je dois déplacer OOX-17/TN dans un endroit dégagé et sûr pour qu\'il puisse entamer sa longue procédure de décollage. Il est équipé d\'un camouflage, mais il me faut du temps pour le rendre opérationnel de mon côté. J\'ai besoin que vous l\'escortiez jusqu\'au... disons jusqu\'aux Grottes du temps ! Ce serait un endroit parfait, et assez long, pour que tout puisse se mettre en route ! »|n|n« Escortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Orguignard Odipnoticus - terminé ! »', },
    {'Escortez OOX-17/TN jusqu\'à ce qu\'il soit en sécurité, puis rendez compte à Orguignard Odipnoticus à Baie-du-Butin.', },
  },
  [649] = {
    'La récupération de Houle',
    {'J\'ai un travail de récupération pour vous, et si vous êtes un amateur de Houle comme moi, vous l\'apprécierez sûrement. La Houle !|n|nMais c\'est une boisson, imbécile.|n|nIl reste une réserve de Houle au miel des Hinterlands dans un avant-poste abandonné de la Horde, qui date de l\'époque où il fonctionnait encore. On ne peut plus trouver d\'aussi bonne Houle, aujourd\'hui. L\'un des hommes de paille de Malton est au courant et connaît la musique. Alors, vous allez vous rendre là-bas et m\'apporter une caisse de Houle emballée, et deux bouteilles pour ma collection. Parlez à Malton, il vous donnera tous les détails nécessaires.', },
    {'Parler à Malton Droffers à Orgrimmar.', },
  },
  [650] = {
    'La récupération de Houle',
    {'L\'elfe que vous devez consulter s\'appelle Gilveradin Courresoleil. Il peut identifier n\'importe quel vin ou cuvée, uniquement à l\'odorat ! Il peut emballer la Houle dont nous avons besoin, et c\'est lui que vous devrez voir. Nous avons besoin de six bouteilles pour la livraison, de deux pour papa, et d\'autant de bouteilles que l\'elfe en voudra... Et il en voudra, croyez-moi ! Lorsque tout sera prêt et que vous aurez deux bouteilles pour papa, revenez me voir.|n|nLe camp de Gilveradin est proche d\'un gîte de hauts-elfes dans les Hinterlands, et ils ne sont pas commodes. Croyez-moi.', },
    {'Parler à Gilveradin Courresoleil. Son camp se situe dans les Hinterlands.', },
  },
  [651] = {
    'Les pierres de lien',
    {'Quatre Pierres de lien sont dispersées à travers tout Arathi. Ces pierres me retiennent prisonnière sous la terre.|n|nPour me libérer vous devez ouvrir la plus puissante : la Pierre de lien intérieure. Et pour cela, vous devez rassembler les clés des trois autres.|n|nCes pierres sont sous la surveillance de gardiens, mais si vous agissez intelligemment, ou si vous avez de la chance, vous pouvez trouver un moyen de les bannir.', },
    {'Collecter la Clé ardente, la Clé armoriée et la Clé de tonnerre aux lieux suivants : la Pierre de lien occidentale, la Pierre de lien orientale et la Pierre de lien extérieure.|n|nLes apporter à la Pierre de lien intérieure.', },
  },
  [652] = {
    'La Pierre cruciale',
    {'Ouvrir les pierres de lien a relâché l\'étreinte de mes fers, mais quelque chose me retient toujours captive. C\'est la pierre cruciale que vous voyez parmi ce cercle de pierres. Et sa clé est détenue par l\'un de mes geôliers, le gardien de pierres Fozruk.|n|nVous devez prendre cette clé, que les gardiens de pierres appellent le bâtonnet de l\'ordre, à Fozruk, et l\'utiliser pour ouvrir la pierre cruciale.|n|n$N, vous avez déjà tellement fait pour me venir en aide. Encore un peu... et ma gratitude fera trembler les fondations même de la terre !', },
    {'Trouver et tuer Fozruk. Apporter le Bâtonnet de l\'ordre à la Pierre cruciale dans les hautes-terres Arathies.', },
  },
  [653] = {
    'Les alliés de Myzrael',
    {'<Myzrael parle.>|n|nLibre ! JE SUIS LIBRE ! Je suis libre de rassembler mes forces, à l\'abri du regard de mes geôliers. Si je les affrontais maintenant ils me domineraient et m\'emprisonneraient de nouveau.|n|nMais au moment voulu, je combattrai les géants, et ils regretteront la tutelle qu\'ils m\'ont imposée !|n|nVous êtes $Gun noble allié:une noble alliée;, $N. J\'aurai encore besoin de votre aide quand le temps sera venu. Bientôt, il vous faudra m\'invoquer à la surface.|n|nParlez à Gerrig Poigne-d\'os. Il se trouve à Forgefer, dans une boutique de la caverne Lugubre. Il sait comment on doit m\'invoquer.', },
    {'Parler à Gerrig Poigne-d\'os, dans la Caverne Lugubre de Forgefer.', },
  },
  [654] = {
    'Les échantillons du désert de Tanaris',
    {'L\'activation de la source d\'énergie fait briller et vibrer la trousse d\'analyse de terrain. Tout semble fonctionner comme prévu.|n|nJe vais l\'envoyer immédiatement.|n|nD\'après l\'ingénieur en chef Vizisanie, vous disposez à présent d\'un peu de temps pour récupérer les données dont vous avez besoin dans le désert de Tanaris.|n|nAllez le voir une fois votre tâche accomplie.', },
    {'Acquérir des Echantillons non testés de 8 basilics, 8 hyènes et 8 scorpions. Rapporter la Trousse d\'analyse de terrain à l\'Ingénieur en chef Vizisanie à Gadgetzan avant que la source d\'énergie ne s\'épuise.', },
  },
  [655] = {
    'Trépas-d\'Orgrim',
    {'Je m\'en souviens très bien, c\'est comme si c\'était hier... Tellement d\'années sans espoir, attaché à cet horrible endroit par du bois et par du fer. Et puis enfin, enfin ! Il y eut le Chef de guerre. Orgrim Marteau-du-destin dans son armure étincelante, son marteau de guerre tournoyant au-dessus de la tête.|n|nCe fut... trop terrible. Que le coup d\'un misérable lâche terrasse notre plus grand héros. Il a chargé, sur son cheval, par derrière, et sa lance l\'a transpercé. Je suis tombé à genoux. Quels espoirs restaient-ils ? Quels espoirs restent-ils ?', },
    {'Parler à Tor\'gan au Trépas-d\'Orgrim.', },
  },
  [656] = {
    'L\'invocation de la Princesse',
    {'Vous devez battre Myzrael avant que sa force n\'augmente. Sinon, une fois qu\'elle aura rassemblé suffisamment de pouvoir, elle défiera ses ravisseurs ! Certains pensent pouvoir la contrôler, mais si elle peut l\'être, alors pourquoi les géants l\'ont-ils enchaînée ??|n|nLogique stupide, pas vrai ?|n|nPour la défier, invoquez-la aux Éclats de Myzrael, où vous lui avez parlé la première fois. Battez-la et prenez ses Chaînes indicibles, puis attachez-les aux Éclats de Myzrael.|n|nAgissez ainsi et elle sera de nouveau prise au piège.', },
    {'Aller aux Éclats de Myzrael, l\'invoquer et la battre.|n|nPrendre ses Chaînes indicibles et les attacher aux Éclats de Myzrael.', },
  },
  [657] = {
    'Les indices d\'une Peste nouvelle ?',
    {'<Quae commence à consulter le dossier.>|n|nC\'est effectivement intéressant. Il semblerait que l\'Apothicaire Jorell ait travaillé sur des expériences mortelles ici à Go\'shek. Je ne suis pas certaine de ce que cela a à voir avec Hautebrande, mais Phin n\'apprécierait pas que nous laissions se poursuivre ces expériences.|n|nNous avons eu une altercation avec des orcs pendant que vous étiez $Gparti:partie;, et je ne suis pas en suffisamment bonne forme pour aider Kinelory. Si vous vous sentez d\'attaque, elle va avoir besoin de protection pour aller à la ferme et voler toutes les recherches que Jorell n\'aurait pas encore envoyées à Moulin-de-Tarren.', },
    {'Parler à Kinelory près de la Ferme de Go\'Shek, dans les Hautes-terres Arathies.', },
  },
  [658] = {
    'Les indices d\'une Peste nouvelle ?',
    {'Ainsi, Phin vous a $Genvoyé:envoyée; prendre de nos nouvelles ? Ça ne m\'étonne pas, il s\'inquiète toujours trop.|n|nNous avons surveillé la ferme pendant plusieurs jours, et Kin prétend qu\'elle a vu une messagère sortir de cette petite maison et se diriger vers le sud il y a peu.|n|nElle parle beaucoup, mais je fais toujours confiance à ses sens lorsque nous sommes dans des endroits dangereux.|n|nVous ne seriez pas $Gun Pisteur compétent:une Pisteuse compétente;, par hasard ? Nous pensons que la messagère se rendait à Moulin-de-Tarren. Si nous pouvions mettre la main sur les documents qu\'elle emportait, cela pourrait nous renseigner sur ce qui se passe à Hautebrande.', },
    {'Trouver la Messagère des Réprouvés et ramener ses documents scellés à Quae près de la Ferme des Go\'shek.', },
  },
  [659] = {
    'Les indices d\'une Peste nouvelle ?',
    {'Salut et bienvenue, $N. Je mène un groupe d\'aventuriers enquêtant sur des faits étranges se produisant dans le coin.|n|nMon cousin à Hautebrande a récemment abattu son chien Stanley parce que l\'animal avait magiquement grossi jusqu\'à une taille immense et attaquait sauvagement quiconque l\'approchait.|n|nJe pense que les morts-vivants sont impliqués, et nous cherchons des indices le prouvant.|n|nDeux de mes compagnes, Quae et Kinelory, sont parties en direction de la ferme des Go\'shek sur les hautes-terres Arathies, et ne sont toujours pas revenues. Vous pourriez les trouver pour moi ? Je commence à m\'inquiéter.', },
    {'Trouver Quae et Kinelory près de la Ferme des Go\'shek dans les hautes-terres Arathies.', },
  },
  [660] = {
    'Les indices d\'une Peste nouvelle ?',
    {'Très bien, $N. Je suis prête si vous l\'êtes.|n|nOn y va ?', },
    {'Protéger Kinelory jusqu\'à ce qu\'elle rejoigne Quae.', },
  },
  [661] = {
    'Les indices d\'une Peste nouvelle ?',
    {'J\'ai déjà vu Kinelory dans un état pire après toute une nuit passée dans une taverne. Vous avez bien fait de la protéger.|n|nCe qu\'elle rapporte de la ferme permettra à Phin de se faire une idée de ce qui se trame à Arathi. Nous allons rester un peu pour être sûr qu\'il n\'y aura pas de représailles suite à votre attaque. Voudriez-vous retourner à Austrivage et parler à Phin ?', },
    {'Retrouver Phin Odelic à Austrivage, aux Contreforts de Hautebrande.', },
  },
  [662] = {
    'Sauvetage en haute mer',
    {'O\'Breen a conduit les bateaux dans la crique. Nous étions certains d\'y trouver le trésor. Le « Noir messager » a accosté sans encombre, mais à mesure que la « Folie de la vierge » et « L\'Esprit des Pins-Argentés » approchaient, le niveau de la mer a commencé à baisser. C\'est la chose la plus étrange que j\'aie jamais vue !|n|nLes deux bateaux se sont échoués sur quelque chose... Une sorte de temple dans les récifs. Puis ils ont coulé à pic ; une vraie tragédie.|n|nNous voulons récupérer leurs cartes maritimes et leurs journaux de bord avant de partir. Nous ne voulons pas que les autres puissent les récupérer !', },
    {'Le lieutenant Nilzlix veut que vous récupériez les Cartes et les Journaux de bord de la « Folie de la vierge » et de « L\'Esprit des Pins-Argentés ».', },
  },
  [663] = {
    'Terre !',
    {'Lolo voit $Gun:une:r; minuscule $R ! Lolo fait toujours le guet !|n|nBienvenue dans la crique de Faldir. Le capitaine O\'Breen a dit qu\'on resterait que quelques heures. Juste le temps de récupérer le trésor et de rentrer à Baie-du-Butin.|n|nMais Lolo pense que ça va durer plus longtemps. Notre groupe a perdu deux navires. Pauvres « Esprit des Pins-Argentés » et « Folie de la vierge ». Au fond de la mer qu\'ils sont maintenant !|n|nLolo vous conseille de parler au capitaine O\'Breen si vous voulez rester ici.', },
    {'Parler au capitaine O\'Breen dans la Crique de Faldir, dans les Hautes-terres Arathies.', },
  },
  [664] = {
    'Chagrin noyé',
    {'Argh, quelle horrible vie ! Je devrais être mort sous l\'eau, et pas assis ici près d\'un feu, respirant de l\'air frais.|n|nL\'équipage a tout fait pour sauver mon merveilleux « Folie de la Vierge ». Loué soit-il !|n|nO\'Breen a réussi à atteindre la rive, nous on n\'a pas été aussi chanceux. La mer s\'est carrément défilée sous nous, je le jure.|n|nÀ un instant on naviguait, l\'instant d\'après on était échoué sur un récif. Et ces créatures ! Elles ont tué tous les survivants. Saleté de nagas ! Je me suis évanoui, puis je me suis réveillé ici.|n|nJe veux que ces créatures meurent !', },
    {'Le capitaine Tripacier de la crique de Faldir veut que vous tuiez 10 Écumeurs daguéchines et 3 Sorcières daguéchines.', },
  },
  [665] = {
    'Le trésor englouti',
    {'Maintenant que nous sommes des Écumeurs des Flots noirs accomplis, il est de notre devoir d\'aider M. O\'Breen à localiser le trésor perdu des elfes.|n|nDans ces eaux sombres, il est presque impossible de trouver les gemmes sans aide. Le docteur a conçu des lunettes spéciales qui pourraient nous être utiles. Il a besoin de les charger avec l\'énergie magique de la pierre enchantée qui se trouve dans la grotte en haut de la colline.|n|nMais cette grotte est maudite ! Quand on s\'en approche, on se fait attaquer. Venez et protégez-moi, alors je pourrai transférer l\'énergie des pierres vers les lunettes.', },
    {'Escorter le professeur Phloppenthrope à la grotte et revenir.', },
  },
  [666] = {
    'Le trésor englouti',
    {'Le trésor repose au fond de la mer depuis si longtemps que les gemmes se sont calcifiées en pierres. Mais le pouvoir contenu dans ces lunettes vous permettra de les localiser facilement.|n|nL\'ingéniosité gnome permet beaucoup !|n|nAussi, empruntez les lunettes de chasse aux gemmes, $N, et voyez si vous pouvez récupérer une partie du trésor perdu pour le capitaine O\'Breen.|n|nJ\'y plongerais bien moi-même mais... euh... des affaires scientifiques importantes nécessitent ma présence sur un sol dur et sec... euh... voilà, c\'est ça.', },
    {'Le docteur Draunessieu, à la crique de Faldir, veut que vous rapportiez 10 Gemmes elfiques et que vous rapportiez ensuite les Lunettes de chasse aux gemmes.', },
  },
  [667] = {
    'La mort venue d\'en bas',
    {'Ça ne se présente pas bien. Il semble que les Daguéchines se regroupent pour une attaque.|n|nLes nagas ont la réputation d\'être impitoyables dans la bataille et ne cesseront d\'attaquer tant que je n\'aurai pas rencontré la mort.|n|nJe ne considère pas ma vie plus précieuse que celles des membres de mon équipage, mais vous devez aider à ma sauvegarde. L\'équipage ne pourra pas revenir à Baie-du-Butin seul et sans la connaissance que je possède des mers.|n|nLes nagas viendront de la mer. Je veux que vous restiez près de moi ici en haut pour parer leur attaque. Servez-vous du canon et repoussez-les.|n|nÊtes-vous $Gprêt:prête;, $N ?', },
    {'Protéger Shakes O\'Breen lors de l\'attaque.', },
  },
  [668] = {
    'Le trésor englouti',
    {'Ne faites pas attendre le capitaine O\'Breen. Il veut voir les gemmes. Après tout, c\'est quand même pour ça qu\'on est là !|n|nAprès ces quelques semaines passées avec les pirates, le professeur et moi-même pensons que la plus mauvaise chose qui pourrait nous arriver serait d\'être surpris à accaparer leur trésor.|n|nVoilà, $N, portez ceci à O\'Breen.', },
    {'Apporter les Gemmes elfiques au Capitaine O\'Breen à la Crique de Faldir, dans les Hautes-terres Arathies.', },
  },
  [669] = {
    'Le trésor englouti',
    {'L\'amiral Corne-de-Mer voudrait voir le plus rapidement possible ce que vous avez trouvé.|n|nMais comme vous pouvez le constater, nous sommes un peu coincés ici. Primo la marée est trop basse, deuzio ces fichues créatures ne nous quittent pas des yeux.|n|nVous rendriez un immense service aux Écumeurs des Flots noirs si vous pouviez prévenir l\'amiral Corne-de-Mer à Baie-du-Butin que nous avons découvert le trésor, et que nous sommes en train de le remonter. Prenez cet échantillon en guise de preuve.', },
    {'Prenez l\'Échantillon de gemme elfique et apportez-le à l\'Amiral Corne-de-Mer à Baie-du-Butin, dans la Vallée de Strangleronce.', },
  },
  [670] = {
    'Le trésor englouti',
    {'Dites, $N, vous semblez aimer l\'aventure. Ma flotte est bloquée à Baie-du-Butin pour cause de ravitaillement.|n|nIl y a des choses qui se trament dans le coin, et j\'ai besoin d\'envoyer une correspondance secrète à Shakes O\'Breen, qui a jeté l\'ancre près des côtes arathies.|n|nPuis-je vous faire confiance pour remettre en toute confidentialité cette missive ?', },
    {'Remettre la Lettre de Corne-de-Mer à Shakes O\'Breen à la Crique de Faldir, dans les Hautes-terres Arathies.', },
  },
  [671] = {
    'Magies immondes',
    {'J\'ai senti quelque chose de bizarre dans l\'air... une chose qui m\'a fait frémir. J\'ai ma petite idée sur ce que c\'est. En essayant de trouver d\'où me venait cette sensation, j\'ai découvert dans l\'ouest, au manoir de Nordclos, des traces résiduelles d\'une invocation démoniaque. À mesure que j\'approchais, mon sang frémissait et la rage montait en moi.|n|nSur le sol, j\'ai trouvé une amulette de pierre de sang, qui est généralement utilisée pour les invocations démoniaques. Celle que j\'ai trouvée était déchargée. Il m\'en faut une autre pour l\'examiner, mais je ne retournerai pas dans le manoir. Pouvez-vous m\'en procurer ?', },
    {'Apporter 10 Amulettes de pierre de sang à Tor\'gan au Trépas-d\'Orgrim.', },
  },
  [672] = {
    'L\'éveil de l\'esprit',
    {'Nous avons essayé de l\'installer confortablement, de le dérider, de lui raconter des histoires sur notre majestueuse cité d\'Orgrimmar en Kalimdor, mais rien ne le fait réagir.|n|nLes histoires de notre jeune chef de guerre Thrall, qui porte l\'armure et le marteau d\'Orgrim mais, peut-être... Peut-être ! Une démonstration de la nouvelle magie chamanique lui donnera de l\'espoir. Ça vaut la peine d\'essayer !|n|nNous pourrions peut-être lui fabriquer un petit quelque chose, oui... Rapportez-moi quelques yeux de raptor, et je vais voir ce que je peux faire.', },
    {'Récupérez 10 Yeux de raptors des hautes-terres sur les Arpenteurs des hautes-terres et les Vandales des hautes-terres pour Tor\'gan, au Trépas-d\'Orgrim.', },
  },
  [673] = {
    'Magies immondes',
    {'Je n\'ai plus aucun doute sur le fait qu\'un puissant démoniste réside dans l\'enceinte de Stromgarde. Régulièrement, en utilisant une relique de magie des arcanes, ce démoniste a invoqué un grand nombre de démons. Nous devons tarir sa source d\'énergie.|n|nTrouvez le démoniste et tuez-le. Rapportez-moi sa source d\'énergie, elle doit être sur lui, et je m\'emploierai à la détruire. Nous verrons alors si le pouvoir de cette chose continue de souiller cette terre...', },
    {'Trouvez l\'Orbe de pierre de sang de Marez Capuche et apportez-la à Tor\'gan, au Trépas-d\'Orgrim.', },
  },
  [674] = {
    'L\'éveil de l\'esprit',
    {'Tenez, donnez cette amulette à Gor\'mul, et regardez si la force des raptors peut ranimer la flamme guerrière qui sommeille en lui.', },
    {'Donner l\'Amulette de griffe de raptor à Gor\'mul à Trépas-d\'Orgrim, dans les Hautes-terres Arathies.', },
  },
  [675] = {
    'L\'éveil de l\'esprit',
    {'<Gor\'mul jette l\'amulette au sol.>|n|nTor\'gan vous envoie, c\'est ça ? Peuh ! Pourquoi est-il si miséricordieux avec moi. Ma propre miséricorde m\'a été enlevée le jour où je n\'ai pas pu mourir avec mon Chef de guerre au combat. Un mauvais coup du sort...', },
    {'Parler à Tor\'gan au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.', },
  },
  [676] = {
    'Menace sur le Trépas-d\'Orgrim',
    {'Mauviettes... Tous autant qu\'ils sont. Vous, $C, qu\'est-ce que vous regardez comme ça ? Vous pensez être quelqu\'un de spécial, hein ? Pourquoi ne le prouvez-vous pas ?|n|nL\'avant-poste de Trépas-d\'Orgrim dans les hautes-terres Arathies est attaqué. À moins qu\'on leur envoie des renforts rapidement, leur défaite est imminente.|n|nMais avant de vous précipiter là-bas, j\'aimerais vous faire passer un test. Au nord-est de Stromgarde, dans les hautes-terres Arathies, il y a une colline habitée par la tribu Rochepoing. Si vous pouvez vous occuper de ces ogres et de leurs massacreurs, allez ensuite faire votre rapport à Drum Lagangrène, à l\'avant-poste du Trépas-d\'Orgrim.', },
    {'Tuer 8 Ogres rochepoings et 10 Massacreurs rochepoings, puis retrouver Drum Lagangrène à l\'avant-poste du Trépas-d\'Orgrim sur les Hautes-terres Arathies.', },
  },
  [677] = {
    'L\'appel du combat',
    {'Les trolls fanécorces et les ogres rochepoings arathis se sont alliés pour nous éradiquer de cette terre, mais nous ne mourrons pas de leurs mains, ni des mains de personne. Nous allons les tuer et leur montrer que nous aussi possédons notre demeure ici.|n|nLes trolls nous ont refusé leur aide et les ogres, si nous les laissions faire, se serviraient de nous comme nourriture et comme literie. Cela ne sera pas !|n|nNous commençons notre attaque sur les trolls fanécorces, au sud. Tuez-les en masse, et ne revenez que lorsque leur camp sera rempli de leur sang.', },
    {'Tuer 10 Lanceurs de haches fanécorces, 10 Chasseurs de tête et 8 Féticheurs, puis retourner voir Drum Lagangrène à l\'avant-poste du Trépas-d\'Orgrim.', },
  },
  [678] = {
    'L\'appel du combat',
    {'Votre force ne fait aucun doute, $N. Voyons ce que vous valez contre un ennemi digne de ce nom.|n|nLes Rochepoings sont basés au sud-ouest d\'ici, vers le pont des nains, et si je ne me trompe pas, les marteleurs et les magi qui s\'y trouvent représenteront pour vous un grand défi.|n|nTuez-en un maximum et revenez me voir quand vous aurez fini. Et même si vous n\'en revenez pas, je ferai l\'éloge de vos exploits sur le champ de bataille.', },
    {'Tuez 10 Brutes rochepoings et 4 Magi rochepoings, puis retournez voir Drum Lagangrène à l\'Avant-poste du Trépas-d\'Orgrim.', },
  },
  [679] = {
    'L\'appel du combat',
    {'La tête de la bête est prête à tomber... avec grand fracas, $N. Vous avez définitivement prouvé votre valeur au cours de cette dernière bataille. Les commanditaires de ces attaques sont installés dans les ruines de Stromgarde, symbole de la faiblesse humaine.|n|nTrouvez et tuez les seigneurs rochepoings et leurs laquais chamans, qui essayent de nous repousser hors de nos terres.', },
    {'Tuer 7 Chamans rochepoings et 3 Seigneurs rochepoings puis revenir voir Drum Lagangrène à l\'avant-poste du Trépas-d\'Orgrim.', },
  },
  [680] = {
    'La réelle menace',
    {'Vous avez bien servi mon mari, $C, mais il ne connaît pas la véritable cause des attaques contre le Trépas-d\'Orgrim.|n|nOr\'Kalar, le valet de Mug\'Thol à Stromgarde, déteste mon mari, et souhaite sa mort depuis qu\'il a été vaincu par lui quelques années auparavant.|n|nJ\'avais le pressentiment qu\'Or\'Kalar tendait un piège à mon mari. Je lui ai donc caché les indices comme quoi il était à l\'origine de ces attaques.|n|nSinon mon mari aurait foncé tête baissée dans le piège… Je voudrais que vous tuiez cette créature et que vous me rameniez sa tête.', },
    {'Tuer Or\'Kalar et apporter sa Tête à Korin Lagangrène à l\'avant-poste du Trépas-d\'Orgrim.', },
  },
  [681] = {
    'Le manoir de Nordclos',
    {'Nous avons combattu pour Stromgarde, et nous avons perdu. Les ogres, le Syndicat et nous, avons divisé notre grande cité et chaque faction s\'est battue contre les autres.|n|nMais nos forces s\'épuisent tandis que celles de nos ennemis se renforcent.|n|nIl nous faut l\'aide de la ville d\'Austrivage, mais l\'approvisionnement reste difficile, car le Syndicat contrôle le territoire entre les deux cités.|n|nAllez au camp du Syndicat situé au manoir de Nordclos et tuez les occupants. Peut-être qu\'ensuite, plus de caravanes de ravitaillement arriveront à destination.', },
    {'Tuer 10 Malandrins du Syndicat et 6 Mercenaires du Syndicat.|n|nRetourner ensuite auprès du capitaine Nials au refuge de l\'Ornière.', },
  },
  [682] = {
    'Les écussons de Stromgarde',
    {'Le Syndicat de Stromgarde est actuellement en guerre contre la milice. Pour inciter la populace à nous affronter aussi, ils ont mis à prix la tête de nos soldats, et donnent de l\'or à tous ceux qui apportent un écusson de Stromgarde pris sur un soldat mort.|n|nNous voulons récupérer ces écussons. Nous ne pouvons tolérer que ces manants prennent les trophées de nos braves soldats tombés sur le champ de bataille !|n|nAllez dans la zone contrôlée par le Syndicat et récupérez les écussons.', },
    {'Rapporter 7 Ecussons de Stromgarde au capitaine Nials au Refuge de l\'Ornière.', },
  },
  [683] = {
    'Requête de Sara Balloo',
    {'$N, j\'ai une petite faveur à vous demander.|n|nPrenez cette lettre et portez-la à notre grand monarque de Forgefer, le roi Magni Barbe-de-bronze. Ce n\'est pas grand-chose pour quelqu\'un comme vous qui a tant fait pour l\'Alliance.|n|nMe présenter devant le roi dans l\'état d\'esprit qui est le mien ne servirait pas notre cause. Vous le comprendrez sûrement.', },
    {'Remettre la lettre de Sara Balloo au roi Magni Barbe-de-bronze à Forgefer.', },
  },
  [684] = {
    'On recherche : Marez Capuche',
    {'La tête de Marez Capuche a été mise à prix. La dernière fois que cette conseillère de haut niveau du Syndicat a été aperçue, c\'était dans la zone de Stromgarde contrôlée par le Syndicat.|n|nLa prime peut être réclamée au capitaine Nials.|n|nAttention: Marez est une démoniste rusée et très adroite, et il est de notoriété publique qu\'elle fricote avec les démons. Débusquez-la avec une extrême prudence.', },
    {'Apporter la tête de Marez au capitaine Nials, au Refuge de l\'Ornière.', },
  },
  [685] = {
    'On recherche : Otto et Lépervier',
    {'La milice de Stromgarde a mis à prix les têtes du seigneur Lépervier et de son garde du corps Otto. Lépervier dirige les forces du Syndicat dans les hautes-terres Arathies, et sa mort sèmerait le chaos dans ces forces.|n|nSon garde du corps Otto, bien qu\'il ne constitue pas une cible stratégique, est un adversaire puissant et il a déjà tué nombre de nos défenseurs.|n|nLes primes pourront être obtenues auprès du capitaine Nials.', },
    {'Apporter les Têtes de Lépervier et d\'Otto au capitaine Nials au Refuge de l\'Ornière.', },
  },
  [686] = {
    'Hommage royal',
    {'Je ne demande pas à ce que les braves naines comme madame Balloo comprennent pourquoi les bouffonneries de la guerre doivent être supportées pour le bien de notre peuple. La perte de son mari comme celle de tous les nains qui combattent au nom de l\'Alliance pèse lourd sur mes épaules.|n|nMais même si je ne peux pas ramener son mari du Néant distordu, je peux lui rendre hommage.|n|nJe vais faire construire un monument en l\'honneur de Sully Balloo, par le maître-maçon Marbresten.|n|nPortez la nouvelle au maître, $C. C\'est vous qui serez en charge de faire respecter cet ordre.', },
    {'Le roi Magni Barbe-de-bronze veut que vous parliez avec le maître-maçon Marbresten.', },
  },
  [687] = {
    'Theldurin l\'Egaré',
    {'Theldurin l\'Egaré était un membre de notre ordre, le Marteau du crépuscule. Il a perdu l\'esprit et a rejeté nos enseignements. Et avant de s\'enfuir il nous a volé le parchemin de Myzrael ! Nous n\'avons pas pu le rattraper, mais des rumeurs font état de sa présence dans les terres Ingrates, complètement fou et baragouinant n\'importe quoi.|n|nPour ramener la dame, vous devez absolument retrouver le parchemin. Et pour cela vous devez retrouver Theldurin.', },
    {'Trouver Theldurin l\'Egaré.', },
  },
  [688] = {
    'Les alliés de Myzrael',
    {'<Myzrael parle.>|n|nLibre ! JE SUIS LIBRE ! Je suis libre de rassembler mes forces, hors de portée de mes ravisseurs. Si je les rencontrais maintenant, ils seraient sûrement plus forts que moi et me captureraient à nouveau.|n|nEn temps voulu, j\'affronterai les géants, et ils regretteront de m\'avoir bannie !|n|nVous êtes d\'une aide précieuse, $N. J\'aurai encore besoin de vous. Quand je serai prête, j\'aurai besoin de vous pour m\'invoquer à la surface.|n|nParlez avec Zaruk au Trépas-d\'Orgrim. Il sait comment m\'invoquer.', },
    {'Parler à Zaruk au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.', },
  },
  [689] = {
    'Hommage royal',
    {'Donc mon bon roi veut construire un monument en l\'honneur du soldat Sully Balloo ? Et vous me dites que le pauvre homme est mort lors de la tragédie du viaduc de Thandol ?|n|nN\'y a-t-il jamais eu la paix en Azeroth ?|n|nQuoi qu\'il en soit, les ordres du roi sont prioritaires. Pour construire un monument grandiose et durable, j\'ai besoin d\'une pierre spéciale, d\'une grande finesse. Allez sur la colline de Darrow à Hautebrande et rapportez-moi du granit d\'Alterac.', },
    {'Le Maître Maçon Marbresten de Forgefer veut 5 morceaux de Granit d\'Alterac.', },
  },
  [690] = {
    'La demande de Malin',
    {'Bonjour, $N. Vous avez l\'air d\'être $Gun aventurier:une aventurière;, et j\'ai un petit travail qui doit être fait.|n|nL\'archimage Trelane, mon ancien maître, a fui depuis peu Stromgarde dans les hautes-terres Arathies, et il m\'a demandé de récupérer quelques objets qu\'il n\'avait pas pu emporter.|n|nLa cité assiégée est tombée, bien qu\'il ait essayé de la défendre. J\'ai déjà des agents sur les Hautes-terres, mais ils ont besoin de renfort. Cela vous intéresse ?', },
    {'Trouver Skuerto au Refuge de l\'Ornière dans les Hautes-terres Arathies.', },
  },
  [691] = {
    'Valoir son poids en or',
    {'L\'archimage Malin nous a envoyés, Skuerto et moi, collecter des ingrédients. Maintenant que vous êtes là, je sais que je n\'aurai pas de problèmes pour trouver ces objets.|n|nJ\'ai besoin des objets suivants : des défenses de Fanécorce, des bourses-médecine fanécorces et un couteau de chasseur des ombres.|n|nPourriez-vous me rapporter ces objets ? Les Fanécorces vivent au sud-est d\'Arathi.', },
    {'Trouvez 10 Défenses de Fanécorce, 4 Bourses-médecine fanécorces et un Couteau de chasseur des ombres pour l\'Apprenti Kryten au Refuge de l\'Ornière.', },
  },
  [692] = {
    'Les fragments perdus',
    {'Le Parchemin de Myzrael... Le Parchemin de Myzrael ? Vous ne voulez tout de même pas ça ! Sa puissance peut faire revenir Myzrael à la surface du monde, et si vous le faites, on sera tous en danger !|n|nOu alors... il est peut-être déjà trop tard. Peut-être qu\'elle est déjà libre. Peut-être ne fait-elle qu\'attendre en rassemblant ses forces avant de les abattre sur nous. Si c\'est le cas, alors vous avez BESOIN du parchemin !|n|n... Quel dommage, il a été détruit. Un élémentaire enragé l\'a volé et déchiré en morceaux.|n|nSi vous pouvez rassembler les fragments, je pourrai, je pense, le reconstituer...', },
    {'Apportez le Fragment de Parchemin déchiré, le Fragment de Parchemin fripé et le Fragment de Parchemin noirci à Theldurin l\'Egaré.', },
  },
  [693] = {
    'La baguette au poing',
    {'Hé $N ! Désolé d\'avoir été un peu bref, la dernière fois j\'étais pris de court... euh, non ce n\'est pas un jeu de mots.|n|nJ\'ai découvert où le premier objet de Trelane a échoué : c\'est Kor\'gresh qui l\'a au hall Rochepoing. Pendant que j\'y suis : il jette des éclairs de glace sur ses troupes pour qu\'elles gardent leur position, ce qui prouve qu\'il n\'est pas loin de maîtriser tous les pouvoirs de l\'objet.|n|nVous trouverez le hall Rochepoing au sud d\'ici, puis à l\'est du viaduc de Thandol. Trouvez cet ogre et rapportez-moi la baguette.|n|nPendant que vous serez en route, je vais voir ce que je peux faire pour Stromgarde.', },
    {'Trouvez la Baguette d\'invocation de Trelane et revenez voir Skuerto, au Refuge de l\'Ornière.', },
  },
  [694] = {
    'Les défenses de Trelane',
    {'Alors vous êtes d\'attaque ?|n|nVoici la prochaine étape : il y a des ogres tout autour de la Tour d\'Arathor à Stromgarde. Nous devons activer les défenses de la tour si nous voulons avoir une chance contre eux et sauvegarder les objets. Pour cela, nous avons besoin de ces gemmes que les chamans rochepoings apprécient particulièrement. Ils les ont récupérées à la tour, mais ils ne vont pas les garder très longtemps.|n|nRécupérez une de ces gemmes, et portez-la à Kryten : il connaît le sort pour l\'enchanter afin qu\'elle serve de clé.', },
    {'Trouver une Agate d\'azur et la porter à l\'Apprenti Kryten au Refuge de l\'Ornière.', },
  },
  [695] = {
    'Enchantement d\'Apprenti',
    {'Et voilà, $N. Il suffit d\'appuyer la gemme sur un des piédestaux près de la base de la tour, et ses défenses s\'activeront. Utilisez-la pour rentrer dans la tour quand vous serez $Gprêt:prête; et allez chercher les autres objets de Trelane.|n|nBonne chance à vous ! Je vous attendrai au camp. Oh ! Parlez à Skuerto avant de partir. Il vous donnera tous les détails nécessaires.', },
    {'Parlez à Skuerto au Refuge de l\'Ornière, dans les Hautes-terres Arathies.', },
  },
  [696] = {
    'Attaque sur la tour',
    {'Voici ce qu\'il faut récupérer : le Phylactère de Trelane, l\'Orbe de Trelane et l\'Agate de braise de Trelane.|n|nLes trois objets doivent se trouver dans un coffre dans la tour, vous ne devriez pas avoir de problème pour l\'ouvrir ; faites juste attention aux ogres.|n|nLes défenses de la tour ne s\'occuperont pas d\'eux ; vous devez avoir vos armes prêtes. Quand les ogres remarqueront que vous êtes là pour les voler, ils risquent de ne pas apprécier.|n|nSoyez $Gprudent:prudente;, et bonne chance.', },
    {'Trouver le Phylactère de Trelane, l\'Orbe de Trelane et l\'Agathe d\'ambre de Trelane. Les rapporter à Skuerto au Refuge de l\'Ornière.', },
  },
  [697] = {
    'La demande de Malin',
    {'Apportez cette lettre à Hurlevent et informez Malin que Kryten sera bientôt de retour. Il vous récompensera pour nous avoir aidés, $N, sans aucun doute.|n|nBon voyage.', },
    {'Porter la Lettre scellée à l\'archimage Malin dans le Quartier des Mages de Hurlevent.', },
  },
  [698] = {
    '[PÉRIMÉ]Petit bonus du soir',
    {'Je rassemble des provisions pour notre avant-poste près de la plage à l\'est. Tok\'Kar fait ce qu\'il peut, mais entre les tours de garde et la cuisine pour ses soldats, ses journées sont déjà bien remplies.|n|nIls aiment cuisiner de la viande de Dents-de-scie quand ils le peuvent, mais je n\'ai pas le temps de leur en trouver une autre cargaison. Cela vous dérangerait de m\'aider ?|n|nLes jeunes Dents-de-scie n\'ont pas autant de goût que ceux plus âgés, alors laissez-les en paix un an ou deux pour qu\'ils atteignent leur taille adulte.', },
    {'Apporter 8 Flancs de Dents-de-scie non préparés à Tok\'Kar dans le marais des Chagrins.', },
  },
  [699] = {
    '[PÉRIMÉ]Petit bonus du soir',
    {'En raison de la menace des murlocs le long des côtes, nous sommes stationnés ici pour repousser, ou au pire alerter s\'ils sont trop nombreux, toutes les menaces sur Pierrêche. Nous n\'avons pas vraiment le temps de respirer, donc si vous le souhaitez, vous pouvez rejoindre nos rangs pour nous aider.|n|nLes Griffes de Mordeurs Dents-de-scie sont un excellent matériau pour fabriquer des armes. Rapportez-m\'en quelques-unes et nous vous donnerons une de nos armes, de la viande fraîche et une bonne compagnie.', },
    {'Apporter 6 Griffes de Mordeurs Dents-de-scie à Tok\'Kar dans le marais des Chagrins.', },
  },
  [700] = {
    'Hommage royal',
    {'Ah, Lordaeron fournit une si belle pierre. Il est si dommage que cette terre connaisse une telle confusion.|n|nMais la construction du Mémorial s\'est très bien déroulée ! Je pense que cette nouvelle ravira le roi.|n|nÀ présent, si vous le voulez bien, veuillez informer Sa Majesté que le Mémorial est prêt, comme il l\'a ordonné.', },
    {'Rendre compte au Roi Magni Barbe-de-bronze.', },
  },
  [701] = {
    'La ruse du raptor',
    {'Avec quelques petites choses en plus, je serai capable de créer un objet qui donnera à Gor\'mul la ruse du raptor ! Avec le pouvoir du raptor en lui, Gor\'mul prendra conscience de notre puissance, et le guerrier qui sommeille en lui se réveillera !|n|nJ\'ai besoin de cœurs de raptors pour créer l\'objet et lancer le sort.', },
    {'Récupérer 12 Cœurs de raptor provenant de Charognards des hautes-terres pour Tor\'gan.', },
  },
  [702] = {
    'La ruse du raptor',
    {'Prenez cet orbe et utilisez sa magie pour insuffler à Gor\'mul l\'essence des raptors. Cela va revigorer son esprit et lui redonner goût à la vie. Lorsqu\'il sera comme avant, nous lui ferons un résumé de l\'activité de la Horde, et il comprendra que pour nos incessantes batailles nous avons besoin d\'un grand guerrier.', },
    {'Donner l\'Orbe de Tor\'gan à Gor\'mul au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.', },
  },
  [703] = {
    'Ailes de busard grillées',
    {'Oh oui ! Mes ailes de busard grillées sont les meilleures ! La sauce est savoureuse et la viande est épicée à souhait. Son odeur attirerait les gens à des kilomètres à la ronde !|n|nJ\'ai tout ce qu\'il faut pour en préparer. Tout... excepté des ailes de busard !|n|nDonc si vous en voulez, apportez-moi des ailes de busard. Apportez-m\'en assez, et je vous donnerai même la recette !', },
    {'Apporter 4 Ailes de busard à Rigglefuzz.', },
  },
  [704] = {
    'Le destin d\'Agmond',
    {'Le dernier rapport que j\'ai reçu d\'Agmond est inquiétant, d\'autant plus qu\'à présent il est mort ! Il dit que son équipe a découvert des « urnes anciennes » au site de fouilles en dehors d\'Uldaman. Je crains que les urnes qu\'il y a découvertes n\'aient poussé les troggs à agir, comme ce fut le cas avec les idoles que j\'ai découvertes ici.|n|nJ\'ai besoin que vous récupériez ces urnes afin que nous les étudiions. Partez pour le site d\'Uldaman, récupérez-les, et revenez me voir.', },
    {'Apporter 4 Urnes de pierre gravées au Prospecteur Baguefer au Loch Modan.', },
  },
  [705] = {
    'Pêche aux perles',
    {'Les Terres ingrates sont inhospitalières. De dangereux prédateurs et de puissants charognards y pullulent. Effrayant, surtout pour un tout petit gobelin. Pour y survivre, il faut être astucieux !|n|nJe sais comment fabriquer des bombes éclairantes. Je les utilise pour éloigner les bêtes sauvages. Mais je commence à manquer d\'un des ingrédients : de la poudre de perles bleues. Apportez-en et je vous récompenserai.|n|nHé ! J\'espère que vous avez de bonnes bottes. Les perles bleues proviennent de palourdes qui vivent au Récif infâme.|n|nOuaip, le Récif infâme de Strangleronce !', },
    {'Apporter 9 Perles bleues à Rigglefuzz dans les Terres ingrates.', },
  },
  [706] = {
    'Enchantements d\'éclats flamboyants',
    {'En tant qu\'apprenti de Feranor Orteil-d\'acier, j\'ai appris à créer des armes dotées d\'enchantements flamboyants. La dernière fois que j\'ai entendu parler de lui, il travaillait dans une forge à Lordaeron.|n|nJe ne peux pas vous donner beaucoup de détails quant au processus, mais je sais qu\'il requiert du sang d\'un cœur de drake noir qui bat encore. Je n\'ai pas grand-chose à faire en attendant les ordres de Forgefer. Si vous me rapportez un tel cœur du ravin de Lethlor, je vous montrerai mes talents !', },
    {'Récupérer un Cœur de drake noir pour Sigrun Taillefer.', },
  },
  [707] = {
    'Baguefer a besoin de vous !',
    {'$N. J\'ai reçu une demande du prospecteur Baguefer, qui se trouve au site de fouilles du Loch Modan : il a besoin de quelqu\'un pour un travail sur un autre de nos sites.|n|nJe n\'ai pas plus de détails, mais si vous allez voir Baguefer, il vous en donnera.', },
    {'Parler au Prospecteur Baguefer, sur le Site de fouilles de Loch Modan.', },
  },
  [708] = {
    'La boîte noire',
    {'La surface de cette boîte noire métallique est fortement grêlée, comme si elle avait été immergée dans de l\'acide. Elle a dû rester longtemps dans l\'estomac du condor géant.|n|nAlors que vous retournez la boîte, vous découvrez un symbole gravé à sa base. Sous le symbole, on peut lire :|n|n« Moteur n°19 - Brigade des sapeurs de Forgefer »', },
    {'Apporter la Boîte noire corrodée à la Salle d\'armes, à Forgefer.', },
  },
  [709] = {
    'La solution à la malédiction',
    {'Oh dieux ! Une malédiction approche. Écoutez-moi ! Une malédiction !|n|nNon, je ne peux pas en parler... je ne peux pas prononcer leur nom, ils pourraient entendre ! Mais si vous voulez savoir, oui si vous voulez en savoir plus sur eux... Alors vous en apprendrez peut-être assez pour les contrecarrer !|n|nPeut-être.|n|nAllez à Uldaman. Non ! Je l\'ai dit ! Vous devez trouver... trouvez la tablette de... Ryun\'eh. Oui, trouvez-la ! Et ne me faites plus prononcer ce nom !|n|nElle est au fond de cet endroit, dans un ancien coffre. C\'est là qu\'elle est cachée... dans un coffre construit bien avant n\'importe quelle construction naine.', },
    {'Apportez la Tablette de Ryun\'eh à Theldurin l\'Egaré.', },
  },
  [710] = {
    'Étude des éléments : la roche',
    {'Je me suis installé ici dans les Terres ingrates pour travailler à mon dernier projet, des entraves de lien élémentaire.|n|nSi j\'aboutis, elles permettront aux mages d\'invoquer des élémentaires très puissants. Pour les finaliser, j\'ai besoin de petits éclats de pierre pour tester certains de mes nouveaux sorts offensifs et quelques bidules que j\'ai assemblés.|n|nCes éclats peuvent facilement être récupérés sur les élémentaires de roche inférieurs, à l\'ouest d\'ici. Pouvez-vous m\'en apporter ?', },
    {'Trouver 10 Petits éclats de pierre et les apporter à Lotwil Veriatus dans les Terres ingrates.', },
  },
  [711] = {
    'Étude des éléments : la roche',
    {'$N, vous vous êtes déjà $Gmontré:montrée; plus capable que tous mes apprentis réunis.|n|nLes prochains éléments dont j\'ai besoin nécessitent un peu plus de force. On trouve de grands blocs de pierre sur des élémentaires de roche, en étant prudent. Leurs corps sont plus forts et plus grands, et ainsi plus enclins à posséder des morceaux de taille suffisante pour mes tests. Ils se trouvent encore un peu plus à l\'ouest d\'ici, ou bien au sud-est le long des bords des montagnes.|n|nPrenez votre temps, je vais d\'abord effectuer des tests avec les plus petits morceaux que vous m\'avez apportés.', },
    {'Apporter 3 Grands blocs de pierre à Lotwil Veriatus dans les Terres ingrates.', },
  },
  [712] = {
    'Étude des éléments : la roche',
    {'$N, il y a une dernière chose dont j\'ai besoin en provenance des élémentaires des Terres ingrates : des brassards de liaison de pierre portés par les élémentaires de roche supérieurs. Selon mes calculs, ces brassards me suffiraient pour calibrer la force de mes propres entraves.|n|nMes divinations pour localiser des élémentaires de roche supérieurs m\'ont permis de trouver un groupe au sud-ouest d\'ici, à côté d\'ogres si je me souviens bien.|n|nRapportez-moi 5 de leurs brassards, comme ça j\'en aurai un peu plus que nécessaire. Servo égare toujours mes réactifs et mes travaux...', },
    {'Apporter 5 Brassards de liaison de pierre à Lotwil Veriatus dans les Terres ingrates.', },
  },
  [713] = {
    'La tête froide l\'emporte toujours',
    {'Laissez-moi vous apprendre quelque chose sur l\'Huile glaciale : elle a la meilleure capacité de refroidissement pour les embrayages et les moteurs.|n|nSes propriétés sont sans égales, et en plus elle lubrifie à merveille et durablement. Et ce n\'est pas tout : elle aide à maintenir les enchantements sur les objets.|n|nJ\'ai besoin d\'une fiole de cette huile pour augmenter la capacité de mes entraves, afin qu\'elles soient assez puissantes pour protéger l\'invocateur de la créature invoquée.|n|nFra\'kas, un de mes amis gobelins, peut vous apprendre à en faire. Il se trouve en Alterac.', },
    {'Trouver de l\'Huile glaciale et la porter à Lotwil Veriatus dans les Terres ingrates.', },
  },
  [714] = {
    'Un gyro... quoi ?',
    {'$N, vous avez brillamment accompli votre travail.|n|n<Lotwil est visiblement obnubilé par son travail.>|n|nSi vous venez à Kharanos, n\'hésitez pas à venir me demander du travail.|n|nOups ! Vite ! Rattrapez-le... oui, ça là. Merci.|n|nMaintenant, j\'ai juste besoin d\'une dernière petite chose. C\'est un petit truc, mais c\'est indispensable, j\'en ai peur : un gyrochronatome.|n|nSi vous pouviez en récupérer un et me l\'apporter, alors je pourrais finir ceci.', },
    {'Apporter un Gyrochronatome à Lotwil Veriatus dans les Terres ingrates.', },
  },
  [715] = {
    'Pierre liquide',
    {'Je pense que les objets que vous avez récupérés pour Lotwil seront le dernier de nos soucis, $N. En revanche, vous avez prouvé que vous étiez $Gun expert:une experte; des sciences que Lotwil considère comme sacrées. Que diriez-vous de m\'aider ?|n|nJ\'ai besoin d\'une potion d\'invisibilité et d\'une potion de soins ; elles pourraient toutes deux être bien utiles très prochainement s\'il mène à bien son projet.|n|nEn échange, je vous donnerai la recette d\'une potion que j\'ai conçue quand j\'étais l\'élève de Lotwil. Elle est basée sur une partie des recherches qu\'il fait ici dans les Terres ingrates.', },
    {'Apporter une Potion d\'invisibilité inférieure et une Potion de soins à Lucien Torsaclef dans les Terres ingrates.', },
  },
  [716] = {
    'Mieux est la pierre que le tissu',
    {'Je sais à quel point Lotwil peut faire preuve de mesquinerie, $N, aussi laissez-moi vous confectionner quelque chose en échange de tous vos efforts. Cela vous protégera peut-être même de l\'atrocité imminente qu\'est la nouvelle invention de Lotwil.|n|nJ\'ai travaillé avec le surplus des pierres que vous avez collectées pour lui, et je peux faire de bons brassards que vous pourriez porter. Des brassards enchantés, bien sûr.|n|nJ\'aurais juste besoin qu\'un forgeron me fasse des brassards guillochés en bronze pour les terminer.', },
    {'Apportez des Brassards guillochés en bronze à Lucien Torsaclef dans les Terres ingrates.', },
  },
  [717] = {
    'Tremblement de terre',
    {'Il est devenu évident que nous ne pouvons plus garantir que Cinglenoir et Hematus resteront prisonniers à Lethlor. Les dragons noirs qui se sont installés là-haut, et les ogres qui projettent de voler le Signe, tout cela nécessite des mesures draconiennes.|n|nLa prison des drakes est scellée grâce à trois pierres runiques qui ne peuvent être retrouvées que par le Signe de la Terre. Ces pierres runiques peuvent être utilisées pour briser le sceau qui les garde enfermés.|n|n$N, faites en sorte qu\'ils ne se réveillent jamais.', },
    {'Utiliser le Signe de la Terre pour activer les Piliers d\'Améthyste, d\'Opale et de Diamant, et obtenir les Pierres runiques.|n|nPlacer les Pierres runiques dans le Sceau de la Terre pour libérer Cinglenoir et Hematus.|n|nLes tuer, puis rapporter les Liens de Cinglenoir, les Entraves de Hematus et le Signe de la Terre à Garek.', },
  },
  [718] = {
    nil,
    {'Dans notre précipitation pour quitter le site de fouilles d\'Uldaman, nous avons été obligés d\'abandonner de nombreux chariots et caisses de fournitures le long du chemin. Les ogres locaux du Camp Kosh se sont précipités sur notre équipement comme des vautours sur une charogne. Ils ne sentent pas meilleur d\'ailleurs. Que la charogne je veux dire !|n|nEnfin bref, ils ont pris une caisse qui contenait toutes nos armes et notre... eh bien, c\'est un peu embarrassant, nous n\'avons pas pris de nourriture avec nous.|n|nNous sommes dans le pétrin maintenant, pourriez-vous nous aider ?', },
    {'Retrouver la Caisse de fournitures pour Sigrun Taillefer.', },
  },
  [719] = {
    'Un nain et ses outils',
    {'Bonjour, $N. Faites attention par ici. Y\'a des nains sombrefers partout : on aurait dit le clan Ombreforge.|n|nIls viennent d\'attaquer le site de fouilles où j\'travaillais... Ils ont tué presque tout le monde, y compris mon chef, Martèlorteil. J\'leur ai échappé de justesse.|n|nLe site se trouve juste au nord d\'ici, et j\'essaie de trouver un moyen d\'récupérer une partie de nos fournitures, mon piolet porte-bonheur surtout.|n|nVous croyez qu\'vous pourriez m\'aider ? L\'un d\'ces maudits Sombrefers a sûrement mon piolet ! Ça peut être n\'importe lequel.', },
    {'Trouver le Piolet porte-bonheur de Ryedol et le rapporter au Prospecteur Ryedol au sud du site de fouilles de Martèlorteil.', },
  },
  [720] = {
    'Un signe d\'espoir',
    {'<Des mots sont grossièrement écrits à la craie sur la carte.>|n|n« Ryedol, |nIls m\'emmènent à Uldaman. Envoie de l\'aide.|n-Martèlorteil »', },
    {'Trouver le Prospecteur Ryedol et lui dire que Martèlorteil Grez est en vie.', },
  },
  [721] = {
    'Un signe d\'espoir',
    {'$N, est-ce que vous pouvez partir à sa recherche ? Est-ce que vous pouvez trouver Martèlorteil à Uldaman ?|n|nSi ces sales Ombreforges le retiennent pour apprendre c\'qu\'il sait du site de fouille des titans, alors tout Forgefer court un grand danger.|n|nDepuis longtemps maintenant, les Sombrefers sont à la r\'cherche de magies pour créer des golems plus puissants. Martèlorteil faisait la même chose, bien sûr, mais seulement pour les contrecarrer.|n|nIls le garderont probablement en vie tant qu\'ils n\'lui auront pas arraché toutes ses connaissances. Vous devez faire vite si vous voulez l\'sauver !', },
    {'Trouver Martèlorteil Grez à Uldaman.', },
  },
  [722] = {
    'L\'amulette des secrets',
    {'Vous avez du courage… <toux>… pour venir jusqu\'à Uldaman pour moi, $C.|n|nSi vous êtes vraiment là pour aider… le vieux Martèlorteil, alors… <toux>… vous devrez me trouver… une amulette.|n|nC\'est Fondombre qui l\'a… Magregan Fondombre. L\'est dans l\'coin... dans les ruines, c\'est sûr. L\'amulette les mènera... <toux>... droit aux parchemins si on n\'l\'arrête pas. Ça dépend de vous, $N. Je vous en prie... récupérez-la.|n|nLes parchemins aideront sans doute les Sombrefers à créer des golems encore plus puissants. Je l\'sais, c\'est tout. Je peux le sentir dans mes os.', },
    {'Trouver l\'Amulette de Martèlorteil et la lui rapporter à Uldaman.', },
  },
  [723] = {
    'Espérance en la foi',
    {'<Martèlorteil tient sa blessure et attend un moment pour reprendre son souffle avant de continuer.>|n|nTrouvez Ryedol, $N. Portez-lui l\'amulette. <toux toux> Il... <toux> saura quoi en faire. Il sait que je recherchais l\'origine de notre peuple, et il... <toux>... sait que c\'était ma mission que d\'arrêter le clan Ombreforge. Ils ne doivent pas s\'emparer de ces parchemins... <toux>', },
    {'Porter l\'Amulette de Martèlorteil au Prospecteur Ryedol dans les Terres ingrates.', },
  },
  [724] = {
    'Espérance en la foi',
    {'Bon, alors... Qui pourrait savoir quoi en faire ?|n|nL\'historien Karnik ! Bien sûr !|n|nIl est à Forgefer. Lui pourra nous aider. Lui et Martèlorteil travaillaient ensemble pour retrouver des artéfacts perdus à Uldaman.|n|nJ\'imagine que le clan Ombreforge a découvert qu\'ils en savaient plus qu\'ils n\'le laissaient croire.|n|nRacontez à Karnik ce qui est arrivé à Martèlorteil et donnez-lui l\'amulette. Il vous dira quoi faire ensuite.', },
    {'Apporter l\'Amulette de Martèlorteil à l\'Historien Karnik à Forgefer.', },
  },
  [725] = {
    'Avertir de la menace',
    {'$N, courez trouver le conseiller Belgrum aussi vite que vous le pourrez. Dites-lui ce que vous savez et demandez-lui ce que nous devons faire. Cette note lui donnera plus d\'explications.|n|nPendant ce temps, je vais essayer d\'entrer en contact avec l\'esprit de Martèlorteil. Peut-être qu\'il sait quelque chose qui pourrait nous aider à mettre un terme aux activités de ces crétins d\'Ombreforge dans les Terres ingrates. Espérons-le.', },
    {'Trouvez le Conseiller Belgrum et donnez-lui la Note.', },
  },
  [726] = {
    'Avertir de la menace',
    {'<Le conseiller Belgrum achève de lire la note, et ses yeux s\'élargissent un moment.>|n|nHoula, très mauvaises nouvelles !|n|n$N, retournez voir l\'historien Karnik et dites-lui qu\'il agit sous l\'autorité du roi pour s\'occuper de cette affaire rapidement et avec fermeté. Il doit mettre un terme aux activités des Ombreforge dans les Terres ingrates.', },
    {'Parler à l\'Historien Karnik.', },
  },
  [727] = {
    'L\'Abrégé de Yagyin à Forgefer',
    {'Les tablettes en disent long. Mais pas assez ! Vraiment pas assez !|n|nIl y a un livre, un abrégé que Yagyin a écrit il y a des années. Les... gens que j\'ai fuis... ils en ont toujours un exemplaire sous la main. Et ils l\'étudient presque tous. Ce livre renferme un immense savoir. Un savoir qui peut nous permettre de nous protéger !|n|nAllez voir Gerrig Poigne-d\'os. Il se trouve dans une boutique à Forgefer, dans la caverne Lugubre. Montrez-lui ce cachet et il pensera que vous êtes un des leurs. Demandez-lui l\'Abrégé de Yagyin... et rapportez-le-moi !', },
    {'Donner le Cachet du Marteau à Gerrig Poigne-d\'os, dans la Caverne Lugubre de Forgefer.', },
  },
  [728] = {
    'L\'Abrégé de Yagyin à Fossoyeuse',
    {'Les tablettes en disent long. Mais pas assez ! Vraiment pas assez !|n|nIl y a un livre, que Yagyin a écrit il y a des années. Les... gens que j\'ai fuis... ils en ont toujours un exemplaire sous la main. Et ils l\'étudient presque tous. Il comprend un immense savoir. Un savoir qui peut nous permettre de nous protéger !|n|nAllez voir le gardien Bel\'dugur à Fossoyeuse, Lordaeron. Montrez-lui ce cachet et il pensera que vous êtes un des leurs. Demandez-lui l\'Abrégé de Yagyin... et rapportez-le-moi !', },
    {'Apportez le Cachet du Marteau au Gardien Bel\'dugur à Fossoyeuse.', },
  },
  [729] = {
    'Les absences du prospecteur',
    {'Quel honneur cela a été quand Maître Grisemoustache m\'a affecté aux ordres du grand Prospecteur Songerrance. À l\'Académie de Forgefer tout le monde connaît les grandes découvertes de Songerrance.|n|nMais le Prospecteur est plutôt... hum... inconscient... de son environnement.|n|nNous avons découvert les traces d\'une grande société. D\'horribles Golems sont sortis du sol et ont envahi le site. Songerrance n\'a pas semblé s\'en apercevoir. J\'ai fui à Auberdine pour demander de l\'aide.|n|nS\'il vous plaît, allez vers le sud pour voir si le prospecteur va bien !', },
    {'Aller vers le sud et vérifier l\'état de santé du Prospecteur Songerrance.', },
  },
  [730] = {
    'Des problèmes à Sombrivage ?',
    {'Il est plaisant de voir qu\'$Gun:une:c; $C s\'intéresse à l\'archéologie et aux grandes merveilles de notre monde.|n|nBien souvent, notre métier est considéré comme un simple passe-temps par nos amis de l\'Alliance. Mais ce que la plupart d\'entre eux ne comprennent pas, c\'est que les récentes découvertes dans Khaz Modan ont prouvé que de grandes et mortelles puissances menacent tout Azeroth, de Lordaeron en Kalimdor.|n|nJe suis vraiment inquiet pour le groupe que j\'ai envoyé à Sombrivage. Je suis sans nouvelles de lui depuis des semaines.|n|nAllez à Auberdine et cherchez des indices sur ce qu\'il lui arrive.', },
    {'Aller à Auberdine et chercher des indices sur les nains de l\'équipe de fouilles.', },
  },
  [731] = {
    'Les absences du prospecteur',
    {'Alors, Hollee... Oh c\'est vrai ! Vous n\'êtes pas Hollee. Où est Hollee ?|n|nBah, ce n\'est pas le problème ! Nous devons trouver ce pinceau à pierre... enfin je veux dire ce mystérieux fossile ! Nous devons le trouver. La Ligue des Explorateurs à Darnassus veut savoir sur quoi je travaille.|n|nDites-moi quand vous serez d\'accord et nous partirons à la recherche de ce pinceau... je veux dire de ce fossile ! Nous trouverons peut-être quelque chose d\'intéressant à écrire à la Ligue.|n|nAlors on y va ?', },
    {'Protéger le Prospecteur Songerrance pendant qu\'il recherche le mystérieux fossile, puis revenir voir l\'Archéologue Hollee à Auberdine.', },
  },
  [732] = {
    'Tremblement de terre',
    {'Sigrun m\'a expliqué que vous l\'aviez beaucoup aidé. Vous pourrez peut-être m\'aider moi aussi. Je suis envoyé par mon maître, Krasus du Kirin Tor, pour mettre fin aux problèmes dans le ravin de Lethlor.|n|nJe ne peux pas divulguer la nature exacte de ma mission, ni la tâche que je dois accomplir, mais elle est de première importance.|n|nUne bande d\'ogres errants, qu\'on a vue parfois près de Camp Boff, a volé un objet appelé le Signe de la Terre, que je dois récupérer. Si vous me le rapportez, je vous en dirai plus.', },
    {'Retrouver le Signe de la Terre pour Garek.', },
  },
  [733] = {
    'Demandes variées',
    {'Cela va devenir difficile de venir ici si je ne peux pas me procurer du matériel pour construire des défenses et d\'autres choses indispensables. J\'ai remarqué que les ogres de la région semblaient bien équipés en ferraille. Peut-être que les légendes à propos d\'engins de siège dans les Terres ingrates ne sont pas si loin de la vérité, finalement...|n|nQuoi qu\'il en soit, le prospecteur s\'inquiète de l\'état de notre petit camp, et j\'aimerais commencer à travailler dès que possible.|n|nLe camp principal des ogres est situé dans la grotte de Crache-poussière, assez loin d\'ici en direction de l\'ouest.', },
    {'Collecter 7 Morceaux de ferraille pour Sigrun.', },
  },
  [734] = {
    'Grandes difficultés',
    {'Merveilleux, merveilleux.|n|n<Lotwil lève les yeux vers vous un instant avant de reprendre son travail.>|n|nAllez parler à Lucien, $N. J\'ai besoin d\'un rouage n° 5. Voulez-vous bien me l\'apporter ?', },
    {'Parler à Lucien Torsaclef dans les Terres ingrates.', },
  },
  [735] = {
    'L\'étoile, la main et le cœur',
    {'L\'Abrégé de Yagyin, hein ? Vous allez établir une nouvelle branche de notre ordre, quelque part ? Laissez tomber, je n\'ai pas à le demander.|n|nJe vais vous aider, j\'en ai une copie en plus. On doit s\'entraider, n\'est-ce pas ? C\'est comme cela que nous prospérons.|n|nJ\'ai besoin de trois objets de puissance. Apportez-les-moi et je vous donnerai le livre.|n|nJe ne vais pas vous donner les noms de vive voix, les murs ont des oreilles, mais je vais vous les écrire.', },
    {'Rapporter les Objets écrits sur le mot de Poigne-d\'os à Gerrig Poigne-d\'os dans Forgefer.', },
  },
  [736] = {
    'L\'étoile, la main et le cœur',
    {'Vous avez besoin de l\'Abrégé de Yagyin ? Vous projetez donc de réunir une nouvelle cellule ? Bien sûr que c\'est le cas... et bien sûr que je vais vous aider, $Gfrère:sœur;.|n|nMais vous devez m\'aider aussi.|n|nJ\'ai besoin de trois objets de puissance. Apportez-les-moi et je vous donnerai le livre.|n|nJe ne peux pas prononcer leurs noms, mais je peux vous les écrire.|n|nApportez-moi les objets de la liste. Si vous pouvez me les obtenir, alors vous méritez de créer une nouvelle branche de notre ordre.', },
    {'Apportez les objets de la liste de Bel\'dugur au Gardien Bel\'dugur à Fossoyeuse.', },
  },
  [737] = {
    'Le savoir perdu',
    {'J\'ai le livre pour vous, $N. Je n\'ai pas besoin de vous demander d\'en prendre le plus grand soin. Et de le garder hors de portée de nos ennemis.|n|nCe livre contient de nombreuses vérités...|n|n... Et la vérité peut vous consumer.', },
    {'Apportez l\'Abrégé de Yagyin à Theldurin.', },
  },
  [738] = {
    'Trouver Agmond',
    {'Le prospecteur Agmond avait la charge de nos sites de fouilles dans les Terres ingrates, au sud-ouest. Je dis « avait » car… en fait, cela fait des semaines que je n\'ai plus eu de ses nouvelles. J\'ai besoin que vous le trouviez pour me ramener son rapport.|n|nAux dernières nouvelles, il se trouverait au site de fouilles le plus au sud des Terres ingrates, un minuscule site au-delà de la Forteresse d\'Angor. Si j\'étais vous, je commencerais mes recherches là-bas.', },
    {'Trouver Agmond.', },
  },
  [739] = {
    nil,
    {'Les traces d\'Agmond partent de l\'ouest. Les traînées de sang sur la pierre et sur le sable vous indiquent que le nain a rampé sur une certaine distance.|n|nEt il est mort ici.|n|nUn examen plus approfondi vous fait remarquer le mot « Murdaloc », tracé sur un tas de sable des Terres ingrates.|n|nTracé près de la main morte d\'Agmond.', },
    {'Tuer l\'assassin d\'Agmond : Murdaloc.|n|nTuer 12 Briseurs d\'os Cavepierre.|n|nEt revenir voir le Prospecteur Baguefer au Loch Modan.', },
  },
  [740] = {
    nil,
    {'Cette quête envoie les joueurs dans la Gorge des Vents brûlants.|n|nRestez sur vos gardes...', },
    nil,
  },
  [741] = {
    'Les absences du prospecteur',
    {'Alors le prospecteur veut envoyer le mystérieux fossile à la Ligue des Explorateurs à Darnassus ? Quitter Sombrivage sans lui… ce n\'est pas bien.|n|nVoilà, $N, apportez le mystérieux fossile au Chef Archéologue Grisemoustache à Darnassus.', },
    {'Apporter le Mystérieux fossile au Chef archéologue Grisemoustache, à Darnassus.', },
  },
  [742] = {
    'La Chasse d\'Orneval',
    {'Votre attention ! Les terres sauvages d\'Orneval vous attendent tous !|n|nLa Horde s\'est établie dans les terres au nord des Tarides. Nos deux avant-postes : le Poste de Bois-Brisé et le Poste de la Grève de Zoram s\'efforcent bravement d\'apporter la gloire à la Horde ! Ceux et celles qui veulent faire montre de leur courage devraient y trouver conseil. De plus, Senani Cœur-de-tonnerre, au Poste de Bois-Brisé, directement au nord des Tarides, cherche en ce moment des candidats prêts à prendre part à une grande chasse en Orneval !', },
    {'Parler à Senani Cœur-de-tonnerre, au Poste de Bois-Brisé, en Orneval.', },
  },
  [743] = {
    'Le danger des Furies-des-vents',
    {'Merci de prendre le temps de me parler, $N. Je suis Ruul, guerrier et professeur.|n|nVous avez atteint l\'âge où il vous faut vous préparer à de dures épreuves si vous comptez vous aventurer hors de Mulgore.|n|nSi vous voulez éprouver votre force, commencez par aller chasser les harpies Furie-des-vents au sud-est. Elles nichent le long des crêtes des montagnes, loin de la route.|n|nElles sont l\'un de nos ennemis naturels, ici en Mulgore. Les affronter éprouvera vos compétences.', },
    {'Apporter 8 Serres de Furie-des-vents à Ruul Serre-d\'Aigle, à Sabot-de-Sang.', },
  },
  [744] = {
    'Préparation à la cérémonie',
    {'$N, mon frère doit bientôt se présenter devant le chef Sabot-de-Sang et il est de mon devoir de lui faire une coiffe digne de ce nom.|n|nJe voudrais vous demander une faveur, pendant que je finis de tanner ces lanières de cuir. Je n\'ai, hélas, pas eu le temps de collecter suffisamment de plumes et je me demandais si vous pouviez en rassembler quelques-unes pour moi ?|n|nVous pouvez trouver des plumes de bonne taille sur les harpies qui vivent loin au nord et au nord-ouest des Pitons-du-Tonnerre. Je n\'ai besoin que de six plumes d\'azur et de six plumes de bronze.', },
    {'Collectez 6 Plumes d\'azur et 6 Plumes de bronze.', },
  },
  [745] = {
    'Partager la terre',
    {'$N, il y a beaucoup de conflits qui ont dévasté cette terre. J\'espère seulement que vous n\'aurez pas à être le témoin du même nombre de batailles que je le fus, moi-même. Il y a pourtant une chose que je voudrais que vous fassiez ; cela vous montrera comment une menace, même minime, peut blesser ce pays, si elle n\'est pas endiguée à temps.|n|nDes crins-pâles gnolls ont colonisé le sud de Sabot-de-Sang et une grotte à l\'ouest. Ils ne répondent pas à nos tentatives de communication et massacrent les animaux sauvages de Mulgore.|n|nAvec cette engeance, la diplomatie n\'est, hélas, plus une solution satisfaisante.', },
    {'Tuez 10 Tanneurs crins-pâles, 8 Ecorcheurs crins-pâles et 5 Braconniers crins-pâles, puis retournez voir Baine Sabot-de-Sang, à Sabot-de-Sang.', },
  },
  [746] = {
    'Les fouilles des nains',
    {'Il y a des nains qui préparent des fouilles au nord-ouest. Ils pensent que la terre abrite des secrets et ils ont raison. Mais creuser et souiller le pays n\'est pas un bon chemin vers la sagesse.|n|nCollectez les outils de forage des nains, fracassez-les et revenez avec les outils brisés.|n|nVous ne pourrez détruire les outils que dans une forge. Vous en trouverez une aux Pitons-du-Tonnerre, bien que n\'importe quelle forge (même une forge dans le camp des nains) suffise à la tâche.', },
    {'Collectez 5 Piolets de prospecteur.|n|nÀ la forge, brisez les Piolets de prospecteur pour obtenir des Outils cassés.|n|nRapportez 5 Outils cassés à Baine Sabot-de-Sang, à Sabot-de-Sang.', },
  },
  [747] = {
    'La chasse commence',
    {'Vous avez un air prometteur, et vous allez avoir l\'occasion de prouver votre valeur au sein de la tribu. Peut-être le jour est-il proche où l\'on vous accueillera dans la grande ville des Pitons-du-Tonnerre. Mais avant, vous devrez démontrer votre valeur à mon père, le Chef Vent-du-faucon.|n|nIci, à la Mesa de Nuage rouge, nous sommes fiers de nos talents de chasseurs. Les taurens chassent par nécessité et par goût du sport. Notre stock de viande a diminué et nous avons besoin de plumes pour nos vêtements. Chassez les trotteurs des plaines du voisinage et faites vos preuves en réapprovisionnant le village.', },
    {'Grull Vent-du-faucon, du Camp Narache, voudrait que vous lui apportiez 7 Plumes de trotteurs des plaines et 7 morceaux de Viande de trotteur des plaines.', },
  },
  [748] = {
    'L\'eau empoisonnée',
    {'Des gobelins et leurs serviteurs ont pollué nos puits sacrés ! Nous ne pouvons tolérer cela.|n|nPour assainir les puits, je dois créer un totem de purification que vous devrez porter au puits, afin de pratiquer le rituel de purification.|n|nD\'abord nous allons fabriquer le totem de purification pour le puits Sabot-d\'hiver. Pour ce faire, le pays doit offrir son aide. Chassez des loups des prairies pour leurs pattes et des trotteurs des plaines adultes pour leurs serres. Vous les trouverez au sud-ouest.|n|nRevenez avec les pattes et les serres, $N.', },
    {'Apporter 6 Pattes de loup des prairies et 4 Serres de trotteur des plaines à Mull Corne-Tonnerre à Sabot-de-Sang.', },
  },
  [749] = {
    'La caravane dévastée',
    {'Il y a quelques jours, nous avons intercepté une caravane de la KapitalRisk qui se déplaçait sous escorte sur les rives du lac Taureau-de-Pierre. Nous avions déjà perdu deux des nôtres dans une bataille antérieure ; aussi avons-nous attaqué sans hésiter. La caravane fut dévastée.|n|nNous avons laissé leurs caisses de provisions sur place, pensant que nos torches détruiraient toute chose de valeur. Mais comme des sauveteurs de la KapitalRisk ont été repérés à côté des caisses brûlées, il se peut que nous nous soyons trompés.|n|nPeut-être pourriez-vous aller sur place et examiner le contenu de ces caisses.', },
    {'Examiner le contenu d\'une caisse de provisions à la caravane dévastée, pour Morin Traqueur-de-nuage.', },
  },
  [750] = {
    'La chasse continue',
    {'Un tauren compétent dans l\'art de la chasse sait que ses proies ne sont pas de simples trophées. Les animaux des plaines nous fournissent ce dont nous avons besoin pour survivre. Vous ferez grosse impression sur les plus âgés si vous réussissez à revenir avec quelques-unes de ces précieuses Peaux de puma des montagnes. Vous pourrez trouver ces bêtes dans les collines plus au sud.|n|nNos enfants ont besoin de vêtements et nos tentes d\'être raccommodées.', },
    {'Grull Vent-du-faucon, du Camp Narache, voudrait que vous lui apportiez 10 Peaux de puma des montagnes.', },
  },
  [751] = {
    'La caravane dévastée',
    {'L\'ouverture de la caisse révèle un assortiment de minerais divers, soigneusement empaquetés. Ceci est une preuve supplémentaire de l\'activité minière de la KapitalRisk dans Mulgore. Sur les minerais, vous récupérez des rouleaux de papier, étroitement ficelés.|n|nLa-haut, dans les collines, vous pouvez presque entendre les bruits des outils de forage qui fendent les roches et voir la fumée des gigantesques feux d\'alimentation.', },
    {'Rapporter les Documents de la KapitalRisk à Morin Traqueur-de-Nuage, à côté de Sabot-de-Sang.', },
  },
  [752] = {
    'Une humble contribution',
    {'Tous les membres de la tribu prennent part à l\'harmonie naturelle de la vie. Nous vivons et travaillons tous ensemble.|n|nNotre engagement les uns pour les autres implique une grande responsabilité envers autrui. Je voudrais vous demander une humble contribution.|n|nMa mère est partie ce matin pour tirer et rapporter de l\'eau d\'un puits qui est au sud-est de Narache. Le temps passe et elle n\'est toujours pas rentrée. Peut-être pourriez-vous aller à sa rencontre ? Je suis, hélas, retenu ici par les affaires de la tribu.', },
    {'Partir chercher la mère du Chef Vent-du-faucon, près du puits, au sud-est de Camp Narache.', },
  },
  [753] = {
    'Une humble contribution',
    {'J\'en ai vu et parcouru du pays, dans ma vie. Ces jambes fatiguées n\'ont plus la vigueur d\'antan, mais je peux encore servir la tribu... en prenant le temps qu\'il faut.|n|nVous avez l\'air d\'être $Gun:une:c; $C enthousiaste. Voici de quoi tester votre jeunesse et votre vitalité : prenez une cruche d\'eau et apportez-la à mon fils, le Chef, au Camp Narache.|n|nRappelez-vous que même la tâche la plus humble peut parfois vous attirer la reconnaissance des aînés.', },
    {'Prendre une Cruche d\'eau du puits.|n|nApporter la cruche au Chef Vent-du-faucon au Camp Narache, qui se trouve au nord-ouest du puits.', },
  },
  [754] = {
    'La purification de Sabot-d\'hiver',
    {'J\'ai réalisé le totem pour purifier le puits Sabot-d\'hiver. Il vous faut maintenant l\'apporter au puits et y pratiquer le Rituel de purification. Vous trouverez le puits dans le sud-est, gardé par d\'infects gobelins !|n|nCe sera tout sauf une mission facile mais vous devez réussir, si nous voulons un jour pouvoir boire de nouveau l\'eau précieuse de ce puits.|n|nBonne chance à vous, $N.', },
    {'Utiliser le Totem de purification de Sabot-d\'hiver au puits Sabot-d\'hiver, puis retourner voir Mull Corne-tonnerre.', },
  },
  [755] = {
    'Les rites de la Terre-mère',
    {'La volonté dont vous avez fait preuve en acceptant cet humble travail pour les taurens de Narache, ainsi que votre goût pour l\'apprentissage révèlent la noblesse de votre caractère, $N. Je suis sûr qu\'un jour vous serez $Gconnu:connue; aux Pitons-du-Tonnerre comme $Gun:une:c; $C des plus $Gvaleureux:valeureuses:c;.|n|nAvant cela, vous serez mis à l\'épreuve des trois Rites de la Terre-mère.|n|nLa première épreuve est le Rite de force. Allez voir le voyant Langue-grise et dites-lui que le Chef Vent-du-faucon vous envoie.|n|nVous trouverez la demeure du Prophète directement au sud de Camp Narache.', },
    {'Aller voir le voyant Langue-grise qui vit dans les collines au sud de Camp Narache.', },
  },
  [756] = {
    'Le totem de Corne-tonnerre',
    {'Pour créer le Totem de purification de Corne-tonnerre, vous devez collecter les griffes des prédateurs qui hantent les plaines de Mulgore. Chassez les traqueurs des prairies et les pumas des basses plaines pour leurs griffes, puis revenez me voir.|n|nVous trouverez les traqueurs des prairies et les pumas des basses plaines à l\'est et à l\'ouest.', },
    {'Rapporter 6 Griffes de Traqueur et 6 Griffes de puma à Mull Corne-tonnerre.', },
  },
  [757] = {
    'Le rite de force',
    {'Les rites de la Terre-mère sont un passage obligé pour tout jeune tauren qui se respecte, aux Pitons-du-Tonnerre.|n|nLa première épreuve est le rite de Force. Vous devrez y démontrer votre bravoure en tuant des ennemis de la tribu.|n|nLes Dos-hirsutes du ravin de Roncelame à l\'est, empiètent sur nos terres tribales. Ils nous tendent des embuscades lors de nos parties de chasse et volent dans les villages, à la nuit tombée.|n|nProuvez votre valeur en massacrant ces vauriens et retournez voir le Chef, au Camp Narache, avec leurs ceintures pour prouver que vous les avez tués.', },
    {'Tuer des Dos-hirsutes dans le Ravin de Roncelame et apporter 12 Ceintures de Dos-hirsute au chef Vent-du-faucon au camp Narache.', },
  },
  [758] = {
    'La purification de Corne-tonnerre',
    {'Le totem est prêt, $N. Il vous faut encore pratiquer le Rituel de purification.|n|nAllez au puits Corne-tonnerre, au nord du village et utilisez le Totem de purification de Corne-tonnerre pour le rituel. Revenez me voir quand cela sera fait.|n|nQue les esprits soient avec vous.', },
    {'Utilisez le Totem de purification de Corne-tonnerre au puits Corne-tonnerre, puis retournez voir Mull.', },
  },
  [759] = {
    'Le totem de Crin-sauvage',
    {'Il ne reste qu\'un puits à purifier, appelé puits Crin-sauvage, d\'après le clan du même nom. Pour nettoyer ce puits, nous aurons besoin des dents d\'un redoutable prédateur : le loup alpha des prairies. Allez chasser ces loups au nord, puis revenez me voir lorsque vous en aurez fini.|n|nLes alphas rôdent souvent autour de notre majestueuse cité des Pitons-du-Tonnerre.', },
    {'Apporter 8 Dents de loup alpha des prairies à Mull Corne-Tonnerre, à Sabot-de-Sang.', },
  },
  [760] = {
    'La purification de Crin-sauvage',
    {'Votre purification des puits Sabot-d\'hiver et Corne-tonnerre est un objet de discussion et de fierté parmi les esprits, jeune $N. Le totem de Crin-sauvage est construit et le devoir vous appelle, encore une fois.|n|nLe puits Crin-sauvage se trouve au nord des Pitons-du-Tonnerre. Pratiquez-y le rituel ! Débarrassez le pays du poison des Totems-sinistres. Que l\'eau claire coule de nouveau !', },
    {'Utiliser le Totem de purification de Crin-sauvage au puits Crin-sauvage.', },
  },
  [761] = {
    'Chasse aux rapaces',
    {'Le rapace est un oiseau rusé, difficile à trouver et à chasser, qui plus est. Une collection de plumes de rapace est signe d\'intelligence et de détermination pour un chasseur.|n|nSi vous êtes $Gprêt:prête; à entreprendre ce travail, pénétrez dans les plaines et chassez les rapaces.|n|nRapportez-moi leurs plumes et faites honneur à votre clan.|n|nVous trouverez les rapaces partout dans Mulgore, mais vos yeux doivent être affûtés pour les localiser et vos jambes, agiles pour les attraper.', },
    {'Apporter 8 Trophées de plumes de Rapace à Harken Totem-de-vent, à Sabot-de-Sang.', },
  },
  [762] = {
    'Un ambassadeur du mal',
    {'L\'ambassadeur Infernus a été envoyé à la Forteresse d\'Angor par Ragnaros lui-même, pour suivre les recherches des artéfacts perdus des Ombreforge à Uldaman.|n|nCela a déjà coûté d\'énormes pertes à notre peuple et la situation empire encore. Je n\'ose imaginer combien d\'artéfacts ils pourraient rassembler et utiliser contre Forgefer.|n|nNotre objectif est simple, $C. Retournez dans les Terres ingrates et tuez l\'ambassadeur Infernus. Une fois la menace éliminée, revenez voir le conseiller Belgrum, avec les preuves de votre victoire.|n|nTout est entre vos mains, à présent.', },
    {'Tuer l\'Ambassadeur Infernus dans la Forteresse d\'Angor et apporter la preuve de sa mort au Conseiller Belgrum à Forgefer.', },
  },
  [763] = {
    'Les rites de la Terre-mère',
    {'Il vous faut encore subir deux épreuves pour achever les Rites de la Terre-mère. Il est temps pour vous d\'élargir votre expérience, $N.|n|nVoyagez jusqu\'au village de Sabot-de-Sang et trouvez le Chef, Baine Sabot-de-Sang, fils de Cairne. Là, vous devrez continuer votre périple et gagner l\'approbation des aînés des Pitons-du-Tonnerre.|n|nPortez ce totem à Baine ; il reconnaîtra mes gravures et vous aidera dans votre quête.|n|nSuivez la route hors de Camp Narache et hâtez-vous. Ne vagabondez pas de-ci de-là, vous vous perdriez.', },
    {'Apporter le Totem de Vent-du-faucon à Baine Sabot-de-Sang à Sabot-de-Sang. Suivre la route hors du camp Narache.', },
  },
  [764] = {
    'La KapitalRisk',
    {'Ceci explique l\'accroissement des effectifs et des équipements de la KapitalRisk en Mulgore. Ces gobelins... leur nombre augmente bien trop vite. Comme on dit : quand on montre quelque chose à un gobelin, les bruits de la monnaie et du profit ne tardent pas à retentir.|n|nLes avides petites créatures... malheureusement pour eux, nous, les taurens, ne permettrons pas à leur entreprise de se développer sur nos terres. Allez à leur mine, au nord-est de la caravane dévastée, et portez leur un message.', },
    {'Tuer 14 Travailleurs de la KapitalRisk et 6 Superviseurs de la KapitalRisk pour Morin Traqueur-de-Nuage de Sabot-de-Sang.', },
  },
  [765] = {
    'Superviseur Vibrouage',
    {'À en croire les documents que vous avez sauvés de la Caravane, la KapitalRisk a conçu plusieurs projets pour nous chasser de nos terres afin de pouvoir les piller et les exploiter en toute liberté.|n|nJe suis épouvanté de voir à quelles extrémités ces odieuses créatures sont prêtes à en venir pour accomplir leurs desseins. Le cerveau qui est à l\'origine de leurs plans doit être tué. Son nom est Superviseur Vibrouage et vous le trouverez à la mine de la KapitalRisk, à l\'est de la Caravane dévastée. Rapportez-moi son écritoire ; peut-être nous apprendra-t-il quelque chose.', },
    {'Tuer le Superviseur Vibrouage et rapporter son Écritoire à Morin Traqueur-de-Nuage, à Sabot-de-Sang.', },
  },
  [766] = {
    nil,
    {'Mon grand-père m\'a conté sa bataille avec la créature nommée Mazzranache. Il m\'a parlé de ses yeux rouges, démoniaques, de ses serres aiguisées comme des rasoirs et de sa morsure venimeuse.|n|nJ\'ai eu la malchance de rencontrer la bête tandis que je cheminais à travers les plaines. Elle était exactement comme mon grand-père me l\'avait décrite ; elle m\'a attaqué et m\'a profondément mordu à l\'épaule. Son poison coule à présent dans mes veines et j\'aurais besoin d\'ingrédients rares pour réaliser un antidote : un cœur de loup, un fémur de puma, une écaille de trotteur des plaines et un gésier de rapace.|n|nHâtez-vous, le temps m\'est compté.', },
    {'Apporter un Cœur de loup des plaines, un Fémur de puma des basses plaines, une Ecaille de trotteur des plaines et un Gésier de rapace à Maur Mande-Pluie, à Sabot-de-Sang.', },
  },
  [767] = {
    'Le rite de vision',
    {'Réussir le Rite de vision, un des rites de la Terre-mère, vous attirera le respect des aînés des Pitons-du-Tonnerre.|n|nNotre peuple a compris que la terre était pourvoyeuse de ressources. Pour faire l\'expérience de la vision rituelle, vous devez parler au chef spirituel du village, Zarlman Deux-Lunes.', },
    {'Parler à Zarlman Deux-Lunes, à Sabot-de-Sang.', },
  },
  [768] = {
    'La chasse aux peaux',
    {'Salut, $Gmon:ma; jeune $Gami:amie; ! Votre œil brille d\'une flamme farouche et je vois que vous avez hâte de retourner dans les plaines pour chasser. Puissiez-vous faire l\'honneur de votre clan !|n|nJe travaille les peaux de bêtes ; j\'en fais des vêtements et des armures pour les gens des Pitons-du-Tonnerre.|n|nSi vous alliez chasser des bêtes et m\'en rapportiez les peaux, je pourrais vous confectionner quelque chose.', },
    {'Apporter 12 pièces de Cuir léger à Veren Haut-Trotteur, aux Pitons-du-Tonnerre.', },
  },
  [769] = {
    'Sac en cuir de kodo',
    {'Les kodos de Mulgore sont puissants et robustes, qualités que nous respectons beaucoup. Si vous savez travailler le cuir et souhaitez apprendre à confectionner un sac en cuir de kodo, apportez-moi les fournitures nécessaires.|n|nFaites cela et je partagerai mes connaissances avec vous.', },
    {'Apportez 4 pièces de Cuir léger et 4 Bobines de fil grossier à Veren Haut-trotteur, aux Pitons-du-Tonnerre.', },
  },
  [770] = {
    'La cape de démon balafrée',
    {'Cette peau déchiquetée de hurleur fantomatique porte toujours la terrible blessure reçue lors de la bataille des loups contre la Légion ardente.|n|nPeut-être que quelqu\'un au camp Frôle-Soleil saura quelque chose sur la malédiction du hurleur fantomatique...', },
    {'Trouver quelqu\'un qui puisse vous en apprendre davantage au sujet du Hurleur fantomatique.', },
  },
  [771] = {
    'Le rite de vision',
    {'Pour passer le Rite de vision, vous devez collecter les ingrédients nécessaires à la réalisation de l\'Eau des Prophètes.|n|nJ\'aurai besoin de Pierres de puits, qui se trouvent autour des puits, en Mulgore. Je les combinerai aux pommes de pin, qui tombent des arbres majestueux de notre pays.|n|nCes ingrédients sont porteurs de grands principes magiques ; quand vous en consommerez les décoctions devant le feu tribal, leurs essences vous donneront une vision. Suivez-la et vous accéderez à l\'étape suivante de votre quête sacrée.', },
    {'Collecter 2 Pierres de puits et 2 Pommes de pin et les rapporter à Zarlman Deux-Lunes, à Sabot-de-Sang.', },
  },
  [772] = {
    'Le rite de vision',
    {'Vous allez maintenant être $Gconfronté:confrontée; à l\'Eau des Prophètes.|n|nQuand vous vous sentirez $Gprêt:prête;, consommez-la en face du feu tribal. Une fois bue l\'eau sacrée, la vision se matérialisera rapidement devant le feu.|n|nA ce moment-là, vous serez $Gseul:seule; avec votre destin...', },
    {'Consommer l\'Eau des Prophètes devant le feu tribal à Sabot-de-Sang et suivre la vision quand elle apparaîtra.', },
  },
  [773] = {
    'Le rite de sagesse',
    {'Pour gagner l\'approbation des aînés des Pitons-du-Tonnerre, vous devez désormais réussir le Rite de sagesse.|n|nMaintenant que vous avez achevé le Rite de vision, les esprits ancestraux des Rochers rouges vous donneront la bénédiction des ancêtres. Seuls ceux qui ont bu l\'Eau des Prophètes accèdent à cette bénédiction.|n|nVoyagez à l\'est des Pitons-du-Tonnerre, jusqu\'aux Rochers rouges et cherchez l\'Esprit ancestral, $N.', },
    {'Voyager aux Rochers rouges, à l\'est des Pitons-du-Tonnerre et parler à l\'Esprit ancestral.', },
  },
  [775] = {
    'Un voyage aux Pitons-du-Tonnerre',
    {'Vous allez maintenant être $Grévéré:révérée; dans notre grande ville. Chaque $R qui passe avec succès les Rites de la Terre-mère a droit à cet honneur.|n|nPour votre quête finale, trouvez notre noble chef, Cairne Sabot-de-Sang, qui demeure au sommet de la plus haute mesa des Pitons-du-Tonnerre.', },
    {'Parler à Cairne Sabot-de-Sang aux Pitons-du-Tonnerre.', },
  },
  [776] = {
    'Les rites de la Terre-mère',
    {'Vous avez passé les rites de la Terre-mère et avez désormais votre place parmi nous, aux Pitons-du-Tonnerre.|n|nMais pour maintenir un prestige si durement gagné, vous devez continuer à prouver votre valeur auprès de votre peuple.|n|nNous sommes des chasseurs, $N. Plus bas, en Mulgore, vit une formidable bête kodo nommée Arra\'chea. Prouvez votre habileté à la chasse ; traquez la bête et rapportez-moi la Corne d\'Arra\'chea.', },
    {'Apporter la Corne d\'Arra\'chea à Cairne Sabot-de-Sang, aux Pitons-du-Tonnerre.', },
  },
  [777] = {
    'Grandes difficultés',
    {'Bon.|n|nJe serai là-bas... à l\'abri.|n|nRejoignez-moi, si vous le souhaitez.', },
    {'Apporter le Rouage N°5 à Lotwil Veriatus.', },
  },
  [778] = {
    'Grandes difficultés',
    {'Haha ! C\'est fait ! Les entraves sont finies !|n|nC\'est le moment, Lucien. C\'est le moment, Servo !|n|nÊtes-vous $Gprêt:prête; à assister à la fusion parfaite de la science alchimique et des arcanes, $N ?|n|nJe vais maintenant invoquer un puissant élémentaire. C\'est un grand jour pour nous !', },
    {'Vaincre le Gardien Fam\'retor et rapporter les Entraves de lien élémentaire de Lotwil à Lotwil Veriatus.', },
  },
  [779] = {
    'Sceau de la Terre',
    nil,
    nil,
  },
  [780] = {
    'Les sangliers de guerre apprivoisés',
    {'Les sangliers de guerre apprivoisés du ravin de Roncelame se répandent sur nos terrains de chasse. Ils sont entraînés au combat et rendus agressifs par les hurans dos-hirsutes contre lesquels nous sommes en guerre.|n|nPartez, massacrez ces infâmes créatures et revenez avec leurs groins et leurs flancs, que nous puissions en faire un bon ragoût pour les jeunes.', },
    {'Grull Vent-du-faucon, du Camp Narache, voudrait que vous tuiez des sangliers de guerre, et que vous rapportiez 8 Groins de sanglier de guerre et 8 Flanchets de sanglier de guerre.', },
  },
  [781] = {
    'L\'attaque du camp Narache',
    {'Après une analyse attentive de la carte, vous comprenez que vous avez découvert les plans du chef de guerre dos-hirsute pour assiéger le camp Narache.|n|nLe chef Vent-du-faucon pourrait certainement tirer profit de ces informations !', },
    {'Apportez les Plans d\'attaque des Dos-hirsutes au chef Vent-du-faucon, au camp Narache.', },
  },
  [782] = {
    'Alliances rompues',
    {'Durant l\'alliance de la Deuxième guerre entre la Horde et le dragon Aile de mort, nous avons appris que deux de ses lieutenants, Cinglenoir et Hematus, ont été emprisonnés dans le ravin de Lethlor, loin à l\'est. Nous devons réduire au silence nos anciens alliés pervertis afin de restaurer l\'honneur de la Horde !|n|nNous avons engagé Tho\'grun et sa bande de mercenaires ogres pour obtenir le Signe de la Terre, une clé nécessaire à l\'ouverture de la prison des drakes. Mais Tho\'grun nous a trahis, il nous a terrassés et s\'en est emparé. Allez au Camp Boff et récupérez-le !', },
    {'Tuer Boss Tho\'grun et rapporter le Signe de la Terre à Gorn, à Kargath.', },
  },
  [783] = {
    '[PÉRIMÉ]Menace intérieure',
    nil,
    {'Parlez au Maréchal McBride.', },
  },
  [784] = {
    'Vaincre les traîtres',
    {'Guidés par l\'amiral Portvaillant, les humains de Kul Tiras prirent pied en Durotar, en violation du pacte signé des années auparavant entre le Chef de guerre et Jaina Portvaillant pour vaincre Archimonde.|n|nL\'attaque humaine fut repoussée et le donjon de Tiragarde tomba. Mais, récemment, les troupes de réserves de l\'amiral, menées par le lieutenant Benedict, ont repris le donjon et menacent nos terres, une fois de plus. Ces humains ne montrent décidément aucun respect pour la diplomatie.|n|nDémontrez votre bravoure et voyagez vers le sud, jusqu\'au donjon de Tiragarde, pour éliminer ses envahisseurs humains.', },
    {'Tuer 10 Marins de Kul Tiras, 8 Soldats de marine de Kul Tiras et le Lieutenant Benedict, puis retourner voir Gar\'Thok à Tranchecolline.', },
  },
  [785] = {
    'Alliance stratégique',
    {'Thrall est un chef noble et sage dont la ténacité sur le champ de bataille n\'a d\'égale que son habileté pour la diplomatie.|n|nLes trolls sombrelances ont prouvé qu\'ils étaient d\'inestimables alliés pour les orcs. Liés par la loyauté et l\'honneur, nous avons signé un pacte de protection avec eux.|n|nLe Chef de guerre a donné des ordres pour s\'assurer que nos amis sombrelances du village de Sen\'jin ne soient pas sous le joug d\'une menace directe. L\'un de leurs éclaireurs les plus sûrs, Lar Fouinebroche, surveille de près leur flanc ouest.|n|nCherchez Lar et assistez-le dans sa tâche.', },
    {'Chercher Lar Fouinebroche sur le flanc ouest du village de Sen\'jin.', },
  },
  [786] = {
    'Déjouer l\'agression des Kolkar',
    {'Parlez plus doucement, $C. Les centaures kolkars sont juste derrière la crête, à l\'ouest, dans la combe des Kolkars.|n|nLa nuit dernière, alors qu\'ils étaient en manœuvres, je me suis glissé dans leur village et j\'ai découvert que ces tristes créatures envisageaient une attaque massive contre les trolls et les orcs de Durotar.|n|nNous ne pouvons leur permettre de mener leurs desseins à terme. Peut-être avez-vous les capacités requises pour vous infiltrer dans la combe des Kolkars et y détruire leurs plans d\'attaque ?|n|nAux dernières nouvelles, ces plans ont été répartis entre trois de leurs chefs.', },
    {'Détruire 3 Jeux de Plans d\'attaque dans la combe des Kolkar, pour Lar Fouinebroche à l\'extérieur du village de Sen\'jin.', },
  },
  [787] = {
    'La nouvelle Horde',
    {'Throm\'ka, $C. Je suis Eitrigg, chargé par Thrall de superviser l\'entraînement des recrues.|n|nLa Horde n\'est plus ce qu\'elle était. Jadis, je la quittai, écœuré par l\'influence toujours croissante des sbires avides de la Légion ardente. Durant mon exil, je fus pris par un groupe d\'humains, mais secouru ensuite par le Chef de guerre. Lorsqu\'il me fit part de sa vision de la Horde, libre de toute influence démoniaque et guidée par les chamans, je réintégrai ses rangs.|n|nGornek aura d\'autres instructions pour vous.', },
    {'Faites un rapport à Gornek, dans l\'Antre.', },
  },
  [788] = {
    'La dent tranchante',
    {'La première chose à faire sera de tremper un peu ce corps trop tendre. Je pourrais vous envoyer dans les Tarides pour y chasser des kodos ; mais en toute honnêteté, vous nous êtes plus utile $Gvivant que mort:vivante que morte;.|n|nEn revanche, je pense que les sangliers tachetés seront des adversaires à votre hauteur. Vous les trouverez plus au nord.', },
    {'Tuez 8 Sangliers tachetés, puis retournez voir Gornek, dans l\'Antre.', },
  },
  [789] = {
    'L\'aiguillon du scorpide',
    {'De piètres novices comme de grands guerriers ont succombé au dard venimeux des scorpides. Vous trouverez un grand nombre de ces créatures au nord-ouest. Apportez-moi huit de leurs queues comme preuve que vous les avez affrontées.|n|nL\'antidote à leur venin est préparé à partir de leur aiguillon. Nous conservons de grandes quantités de ce remède pour sauver de jeunes vies comme la vôtre...|n|nMais vous n\'aurez certainement aucun besoin de ce contrepoison, n\'est-ce pas ?', },
    {'Apporter 8 Queues de scorpides ouvriers à Gornek, dans l\'Antre.', },
  },
  [790] = {
    nil,
    {'$C ! Je me voyais déjà mort ici, ignoré de tous. Alors que je chassais les scorpides de la vallée, je fus soudain confronté à un spécimen particulièrement puissant. Je parvins à lui porter un grand coup avant qu\'il ne referme ses pinces autour de ma jambe.|n|nJe fus, hélas, distrait par cette attaque et en oubliai le redoutable aiguillon, qui se ficha dans ma poitrine. Je vous en prie, tuez ce scorpide pour moi ! Mon honneur doit être lavé. J\'ai combattu la créature sur le plateau, plus au sud.', },
    {'Tuez Sarkoth et rapportez sa pince à Hana\'zua.', },
  },
  [791] = {
    'Assumer ses responsabilités',
    {'Mon âge me rend inapte au maniement des armes, mais j\'ai appris à me rendre utile par d\'autres moyens.|n|nDe ce poste d\'observation, je guette les envahisseurs. Nos forces s\'accroissant de jour en jour, je me trouve de moins en moins souvent à devoir donner l\'alarme en soufflant dans le cor.|n|nAussi, pour passer le temps, je confectionne du matériel et aide de plus jeunes guerriers que moi à défendre leur pays.|n|nJe peux fabriquer un sac pour vos affaires. Si cela vous intéresse, apportez-moi du canevas, un matériau qu\'on trouve communément chez les humains et les centaures.', },
    {'Apporter 8 Morceaux de canevas à Furl Morguefront, dans la tour de guet de Tranchecolline.', },
  },
  [792] = {
    'Les vils quasits',
    {'Je suis sûre que la vallée des Épreuves vous enseignera beaucoup, jeune $C.|n|nJ\'ai été envoyée dans la vallée pour vous guider, mais j\'y ai découvert une menace croissante.|n|nUn groupe qui se fait appeler la Lame ardente a un convent, ici, dans la vallée des Épreuves. Ils se cachent dans une grotte, au nord-est, d\'où leurs vils quasits partent se répandre sur les terres pour les ravager.|n|nComme première action contre la Lame ardente, je vous demande de vaincre ces quasits. Massacrez-les en nombre et, si vous y avez survécu, revenez me voir.', },
    {'Tuez 8 Vils quasits.|n|nRetournez voir Zureetha Mireloin, à l\'extérieur de l\'Antre.', },
  },
  [793] = {
    'Alliances rompues',
    {'Le Sceau de la Terre est retenu par trois Pierres runiques, placées dans les Piliers de diamant, d\'onyx, et d\'améthyste dans le Ravin de Lethlor. Avec le Signe de la Terre, vous serez capable d\'enlever les Pierres runiques et de déverrouiller le Sceau de la Terre.|n|nPrudence, $N, les drakes noirs Cinglenoir et Hematus sont des ennemis à prendre au sérieux. Tuez-les et apportez-moi leurs liens.|n|nPour atteindre le ravin, allez dans la partie la plus à l\'est des Terres ingrates. Faites bien attention, car le ravin abrite de nombreux drakes.', },
    {'Utiliser le Signe de la Terre pour activer les Piliers de diamant, d\'opale et d\'améthyste, et obtenir les Pierres runiques.|n|nPlacer les Pierres runiques dans le Sceau de la Terre pour libérer Cinglenoir et Hematus.|n|nLes exécuter et rapporter les Liens de Cinglenoir, les Entraves d\'Hematus et le Signe de la Terre à Gorn.', },
  },
  [794] = {
    'Médaillon de la Lame ardente',
    {'Mes divinations me font voir qu\'un objet de puissance se trouve loin à l\'intérieur du convent de la Lame ardente, et qu\'il est gardé par des bêtes et de la magie noire.|n|nVous devez trouver cet objet, le Médaillon de la Lame ardente et le prendre au convent.|n|nAttention, il sera probablement entre les mains d\'un agent de la Lame ardente autrement plus puissant que les quasits.|n|nPartez, $N. Vous trouverez le Convent dans une caverne, au nord puis à l\'ouest.', },
    {'Apportez le Médaillon de la Lame ardente à Zureetha Mireloin, à l\'extérieur de l\'Antre.', },
  },
  [795] = {
    'Sceau de la Terre',
    nil,
    nil,
  },
  [804] = {
    nil,
    {'Ce que vous avez fait pour moi remplit mon cœur de courage. Je ne peux pas me laisser mourir comme ça, je dois me battre !|n|nJe ne puis, cependant, regagner l\'Antre sans assistance. S\'il vous plaît, $N, retournez à l\'Antre et informez Gornek de ma situation. Peut-être saura-t-il m\'aider.', },
    {'Informer Gornek, à l\'Antre, de la situation critique dans laquelle se trouve Hana\'zua.', },
  },
  [805] = {
    'Faire un rapport au Village de Sen\'jin',
    {'Vos aventures contre la Lame ardente sont finies… ici dans la vallée. Mais je veux que vous rendiez compte de vos découvertes.|n|nAllez au village troll de Sen\'jin et cherchez maître Gadrin. Le village est à l\'est de la vallée, puis à droite à l\'embranchement.|n|nParlez-lui de la Lame ardente, dites-lui que ses membres ont atteint la vallée des Épreuves. Demandez-lui s\'ils ont déjà atteint Sen\'jin.|n|nAllez, $N, et faites vite. J\'ai peur que le mal découvert au convent de la Lame ardente ne présage un plus grand danger.', },
    {'Parler à Maître Gadrin au village de Sen\'jin.', },
  },
  [806] = {
    'De sombres orages',
    {'Nous ne pouvons permettre à la Lame ardente de prendre pied en Durotar ! Nous devons les détruire avant que ce mal ne suppure !|n|nJ\'ai mené mes propres enquêtes et j\'ai découvert qu\'un démoniste de la Lame ardente, le gobelin Féplouf Sombrorage, s\'est établi dans les falaises du Tonnerre au nord-ouest. Là-bas, lui et ses sectateurs répandent le chaos.|n|nTrouvez Féplouf et éliminez-le. Apportez-moi alors sa griffe !', },
    {'Apporter la Griffe de Féplouf à Orgnil Marque-l\'âme à Tranchecolline.', },
  },
  [807] = {
    nil,
    {'Mes éclaireurs m\'ont averti qu\'en Durotar, une corruption démoniaque avait infecté la nature et la vie sauvage. Les bêtes infectées ont été vues au nord et à l\'ouest.|n|nElles rôdent au milieu de leurs semblables, comme des animaux normaux, mais des forces maléfiques les habitent ; la magie noire dévore leur cœur de flammes hideuses.|n|nCes animaux doivent malheureusement être détruits !|n|nSi vous rencontrez ces bêtes en explorant Durotar, tuez-les, arrachez et rapportez-moi leurs cœurs brûlés, que je puisse les étudier avant de les détruire.', },
    {'Apporter 5 Cœurs brûlés à Orgnil Marque-l\'âme à Tranchecolline.', },
  },
  [808] = {
    'Crâne de Minshina',
    {'J\'entends la voix de mon frère Minshina qui m\'appelle dans mes rêves.|n|nIl a été enlevé par Zalazane, le démoniste des îles de l\'Écho, à l\'est. Et il est mort.|n|nMais la mort ne l\'a pas libéré. Car Zalazane a emprisonné son esprit dans son propre crâne. Dans mes rêves, je peux le voir parmi d\'autres crânes, dans un cercle de puissance situé sur la plus grande des îles de l\'Écho. Tant qu\'il y reste, son esprit est condamné.|n|nJe vous en prie, $N. Trouvez le cercle et le Crâne de Minshina. Rapportez-le.|n|nLibérez-le !', },
    {'Récupérer le Crâne de Minshina dans le Cercle de puissance, sur les îles de l\'Écho.|n|nLe rapporter à Maître Gadrin, au village de Sen\'jin.', },
  },
  [809] = {
    nil,
    {'Depuis la dernière grande guerre où la Légion ardente fut défaite, j\'ai recherché les sources de corruption démoniaque dans la société des orcs. Le collier que vous m\'avez apporté confirme mes craintes.|n|nIl appartient à la Lame ardente, un culte en possession d\'un objet de grand pouvoir maléfique qu\'on appelle la « graine démoniaque ». Vous pouvez la trouver dans les Tarides, au sommet du pic de Brume-funeste. La graine doit absolument être détruite !|n|nAllez au poste de Guet-Lointain, à l\'ouest, sur la frontière des Tarides, et parlez avec mon assistant, Ak\'Zeloth. Il vous donnera les prochaines directives.', },
    {'Parlez à Ak\'Zeloth, dans les Tarides.', },
  },
  [810] = {
    nil,
    {'Vous feriez bien de ne pas mésestimer la dangerosité de ce pays, $C.|n|nLa vie sauvage, ici, peut nous apprendre beaucoup... à condition d\'être sage et de savoir observer.|n|nLes scorpides, par exemple, sont des créatures qui ont su parfaitement survivre en Durotar. Si vous voulez rester vivant dans ce pays violent, vous feriez bien de prendre à votre compte certains de leurs attributs. Leur carapace renforcée, par exemple, peut vous protéger tout à la fois de la morsure du soleil et de celle de l\'épée.|n|nApportez-moi six carapaces de petits scorpides, que vous trouverez sur le cadavre des scorpides cliquetants que vous pourrez tuer, $N. Je vous en récompenserai largement.', },
    {'Apporter 6 Carapaces de petits scorpides à Kor\'ghan, au village de Sen\'jin.', },
  },
  [811] = {
    nil,
    {'Une autre caractéristique des scorpides est leur loyauté farouche les uns pour les autres. Ils protègeront infailliblement celui des leurs qui se trouve en danger - mais vous avez sûrement déjà « goûté » à cet aspect de leur comportement social, lors de votre première chasse.|n|nVous feriez bien d\'adopter cette stratégie : nous sommes plus forts ensembles et solidaires que divisés.|n|nApportez-moi huit carapaces de grand scorpide que vous trouverez sur le cadavre des scorpides blindés que vous pourrez tuer. Vous apprendrez beaucoup de ce travail, et je vous en récompenserai.', },
    {'Apporter 8 Carapaces de grand scorpide à Kor\'ghan, au village de Sen\'jin.', },
  },
  [812] = {
    'Besoin d\'un remède',
    {'$N... votre minutage est parfait. J\'espère que je pourrai en dire autant de votre célérité.|n|nJ\'ai manqué d\'attention en combattant des Queues-venin aux alentours, et j\'ai été piqué par l\'un d\'entre eux. Le poison m\'affaiblit au moment même où je parle. A ce rythme, il me reste peut-être une heure à vivre. Mais je vais avoir besoin de vous...|n|nKor\'ghan, à Orgrimmar, sait comment confectionner l\'antidote. Trouvez-le... et faites vite, $N. Je ne vais pas pouvoir tenir beaucoup plus longtemps. Il devrait se trouver dans la Faille de l\'Ombre.', },
    {'Trouver Kor\'ghan à Orgrimmar et obtenir l\'Antidote du Queue-venin. L\'apporter ensuite à Rhinag près de la frontière nord-ouest de Durotar.', },
  },
  [813] = {
    'La recherche de l\'antidote',
    {'Les scorpides Queue-venin sont parmi les plus dangereux en Durotar. Rhinag a manqué de sagesse lorsqu\'il a les a chassés sans emporter d\'antidote, mais à présent, une remontrance est vraiment la dernière chose dont il a besoin.|n|nApportez-moi des Glandes à venin de n\'importe quel Queue-venin, et je lui préparerai un antidote. Vous en trouverez près de l\'entrée d\'Orgrimmar.|n|nDépêchez-vous, $N. L\'un d\'entre nous a besoin de votre aide.', },
    {'Apporter 4 Glandes à venin de Queue-venin à Kor\'ghan à Orgrimmar.', },
  },
  [814] = {
    nil,
    {'Cuisiner et nettoyer, voilà toutes mes activités !|n|nSi vous voulez manger, fournissez la viande ! Je n\'ai pas le temps de chasser puis de préparer à manger à tous ces salopiauds. Vous devrez apprendre à mettre la main à la pâte si vous voulez être correctement traité.|n|nTrouvez-moi quelques Morceaux de viande de sanglier, si vous voulez vous rendre utile... ou, tout simplement, ne pas mourir de faim.', },
    {'Apporter 10 Morceaux de viande de sanglier au Cuisinier Torka, à Tranchecolline.', },
  },
  [815] = {
    'Des œufs pour l\'omelette',
    {'Bah ! J\'allais presque oublier... faut qu\'je ficelle le p\'tit déjeuner|n|n$N, bougez- vous l\'train et allez m\'trouver quelques œufs de fouette-queue. M\'en faut au moins trois si j\'veux en avoir aussi pour le déjeuner de demain.|n|nLe fouette-queue Griffesang peut être farouche et protège ses œufs jusqu\'à la mort, ça oui. Ils les enfouissent parfois bien trop profondément pour pouvoir les déterrer ; mais, bon, si vous fouinez un peu du côté des îles de l\'Écho, au sud-est du village de Sen\'jin, vous en trouverez d\'accessibles à foison, partout sur ces îles.', },
    {'Rapporter 3 Œufs de fouette-queue au cuisinier Torka, à Tranchecolline.', },
  },
  [816] = {
    'L\'égaré',
    {'$N, pouvez-vous m\'aider ? Mon fils, Kron, est parti chasser il y a quelques jours et il n\'est toujours pas revenu. Il est allé à l\'ouest, vers les Tarides, pour traquer des crocilisques, le long du fleuve Furie-du-Sud. Je crains le pire.|n|nAussi fort soit-il, sa fierté mal placée l\'a toujours conduit dans les pires situations. Lorsque je lui ai dit que les crocilisques étaient puissants et brutaux, il s\'est emporté et est parti.|n|nSi vous ne le ramenez pas, découvrez au moins ce qu\'il est devenu...Même si vous devez pour cela ouvrir le ventre de chaque crocilisque, le long des bancs de sable de la Furie-du-Sud.', },
    {'Trouvez un indice du sort de Kron et en informez Misha Tor\'kren, à la ferme, au nord-ouest de Tranchecolline.', },
  },
  [817] = {
    'Proie nécessaire',
    {'La plupart des peaux que nous utilisons proviennent des tigres de Durotar, $N. Couvertures, armures, tentes, nous avons beaucoup de raisons de chasser ces bêtes, et autant de les laisser prospérer.|n|nLe temps est venu de cueillir la récolte, pour ainsi dire. Nos rangs grandissent et les besoins de mon peuple sont supérieurs à nos provisions. Il me faut plus de peaux pour subvenir à ces besoins.|n|nApportez-moi 4 Fourrures de tigres de Durotar, et je vous récompenserai. Vous pourrez les trouver sur les îles au sud d\'ici.', },
    {'Apporter 4 Peaux de tigres de Durotar à Vel\'rin Croc, au village de Sen\'jin.', },
  },
  [818] = {
    'Un esprit parfaitement éduqué',
    {'Même si mes yeux sont faibles, j\'y vois encore suffisamment clair. Je me repose souvent sur mes compétences en alchimie pour les magies qui autrefois m\'étaient aisées. Mais je refuse de prendre $Gun apprenti:une apprentie;. Aucun orc ou troll assez digne ne s\'est jamais présenté.|n|nEt vous, en êtes-vous digne ? Bien sûr que vous en êtes digne... que vous croyez l\'être.|n|nJ\'ai besoin de certaines choses. Pouvez-vous les obtenir ?|n|nIl me faut des yeux de makruras intacts, et des fioles de mucosités de clampants. De n\'importe quels makruras ou clampants en Durotar. Nous nous reparlerons bientôt.', },
    {'Apporter 4 Yeux de makrura intacts et 8 Fioles de mucus de clampant à maître Vornal, au village de Sen\'jin.', },
  },
  [819] = {
    'Tonneau vide de Chen',
    {'Une petite pancarte, placée à l\'extrémité du tonneau, dit :|n|n« Chen Orage-de-brune -|n|nQue la dive bouteille vous apporte la paix spiritueuse. »', },
    {'Trouver quelqu\'un qui en sache davantage au sujet du Tonneau vide de Chen.', },
  },
  [820] = {
    nil,
    {'Vraiment, un esprit de force doit demeurer en vous, ou peut-être n\'était-ce que de la chance, pas vrai ?|n|nC\'est sur quoi les jeunes comptent le plus de nos jours : la chance… et la générosité de ceux qui sont plus puissants qu\'eux. Assez peu prennent le temps de trouver leur propre voie. Ils implorent toujours de l\'aide... ou une récompense, mais jamais la quête. Il est sûr qu\'il en sera de même avec vous.|n|nMais il y a de l\'espoir. J\'ai besoin de quelque chose d\'autre pour ma potion, $N. Il me faut 8 brins de chatoyante. On peut en trouver dans les falaises du Tonnerre au nord-ouest de Tranchecolline.', },
    {'Apporter 8 Brins de chatoyante à maître Vornal au village de Sen\'jin.', },
  },
  [821] = {
    'Tonneau vide de Chen',
    {'Voudriez-vous goûter à la boisson qui porte le nom de Chen ? Ahhh ! La Brune d\'Orage est un bien puissant breuvage. Chen en a appris la recette à mon mentor, et mon mentor me l\'a apprise. J\'aurais besoin que vous me trouviez certaines choses, mais je vous assure : le choc en vaut la peine.|n|nApportez-moi cinq canines de lion des savanes, de n\'importe lesquels ; cinq rognons de trotteur des plaines, et une corne de lézard-tonnerre. Ça devrait parfaitement faire l\'affaire.|n|nVous trouverez ces ingrédients dans les Tarides.', },
    {'Apporter 5 Canines de lion des savanes, 5 Rognons de trotteur des plaines, et 1 Corne de lézard-tonnerre au brasseur Drohn à Cabestan.', },
  },
  [822] = {
    'Tonneau vide de Chen',
    {'De la bonne, cette Brune d\'Orage, hein ?|n|nJ\'ai une autre recette que j\'ai apprise de Chen. Ça vous intéresse ? Ça ne sera pas long, et ça peut même vous être utile si vous comptez poursuivre vos aventures.|n|nApportez-moi cinq glandes d\'éclair trouvées sur des orageux, une glande salivaire de faucon-tonnerre et un foie de kodo des Tarides.|n|nComme je l\'ai dit, ce truc décoiffe. C\'est la bière trogg dont je vous ai parlé.', },
    {'Apporter 5 Glandes d\'éclair, 1 Glande salivaire de faucon-tonnerre et 1 Foie de kodo au brasseur Drohn à Cabestan.', },
  },
  [823] = {
    'Un rapport à Orgnil',
    {'Nous autres au village de Sen\'jin avons nos problèmes, et nous vous remercions pour votre aide. Mais les nouvelles que vous apportez à propos de la Lame ardente pourraient annoncer des ennuis pour tout le monde.|n|nUn orc nommé Orgnil Marque-l\'âme est posté à Tranchecolline. Il protège Durotar de maux tels que la Lame ardente. Allez lui parler et informez-le de notre demande. Donnez-lui également des nouvelles de la vallée des Épreuves. Il voudra savoir ces choses.|n|nTranchecolline est au nord.', },
    {'Parler à Orgnil Marque-l\'âme à Tranchecolline.', },
  },
  [824] = {
    'Je\'neu du Cercle terrestre',
    {'Le Cercle terrestre est un groupe de chamans dédié à l\'étude et à la préservation des éléments. Ils en savent plus sur les dieux anciens fous, les vieilles légendes et les savoirs antiques que la plupart des savants de ce monde.|n|nHeureusement pour vous, je connais quelqu\'un du Cercle terrestre, ici, en Orneval. Allez à l\'avant-poste de Zoram\'gar, sur la côte de la grève de Zoram. Montrez à Je\'neu Sancrea ce que nous avons trouvé. Si quelqu\'un peut découvrir quelle est la signification de ce globe, c\'est bien lui.', },
    {'Apportez le Globe d\'eau souillée à Je\'neu Sancrea, dans les Profondeurs de Brassenoire.', },
  },
  [825] = {
    'Des épaves',
    {'L\'un de mes éclaireurs les plus observateurs me rapporte que les épaves de la flotte de Portvaillant sont toujours près de la côte de Durotar, juste à l\'est du donjon de Tiragarde.|n|nCe n\'est un secret pour personne que les humains, alliés à ces petites bêtes idiotes que sont les gnomes, possèdent des connaissances avancées en mécanique. Nous devons apprendre précisément les savoirs de tous nos ennemis potentiels. Et notre peuple bénéficiera de ces nouveaux savoirs, également.|n|nNagez à travers les épaves, $N, et trouvez pour moi les outils de l\'Alliance.', },
    {'Gar\'Thok de Tranchecolline veut que vous retrouviez 3 Outils gnomes parmi les épaves près de la côte.', },
  },
  [826] = {
    nil,
    {'Le féticheur Zalazane demeure sur les îles de l\'Écho, à l\'est. Ce sont les îles que nous appelions autrefois « maison ».|n|nDe là, il envoie ses trolls sur le continent et déchaîne ses maléfices sur notre peuple pour placer davantage des nôtres sous son emprise.|n|nIl faut l\'arrêter.|n|nBattez Zalazane et ses serviteurs, d\'anciens trolls sombrelances perdus pour notre cause. Apportez-moi sa tête, et je saurai que son règne maléfique est terminé.', },
    {'Battre Zalazane.|n|nTuer 8 Trolls vaudou et 8 Trolls maléficiés.|n|nApporter la Tête de Zalazane à Gadrin.', },
  },
  [827] = {
    'Le rocher du Crâne',
    {'$N. La Lame ardente a infesté la caverne appelée le rocher du Crâne, à l\'est d\'Orgrimmar. Ils y accomplissent des rituels abominables, et brûlent leur propre chair avec des colliers brûlants.|n|nEn portant ces colliers, je pense que les sectateurs s\'harmonisent avec la puissance démoniaque. Mais pour le confirmer, je dois en posséder une collection afin de les étudier.|n|nPartez pour le rocher du Crâne et prenez les colliers brûlants que vous trouverez sur les membres du culte. Apportez-les-moi, et je dévoilerai leurs mystères.', },
    {'Prendre les Colliers brûlants des sectateurs au Rocher du Crâne.|n|nLes apporter à Margoz à son camp.', },
  },
  [828] = {
    nil,
    {'L\'un de nos chamans, Margoz, en sait plus sur la corruption de la Lame ardente. Il parle d\'une caverne appelée rocher du Crâne dans les montagnes, juste à l\'extérieur d\'Orgrimmar, qui abrite un important groupe de sectateurs.|n|nAvant que vous ne partiez pour le rocher du Crâne, parlez à Margoz. C\'est un sage et son conseil est précieux.|n|nIl campe au nord-est, entre la côte et le ravin Asséché.|n|nSuivez son avis, mais quoi qu\'il dise, $N, je veux que vous écrasiez ce culte !', },
    {'Parler à Margoz.', },
  },
  [829] = {
    'Neeru Lamefeu',
    {'Les colliers brûlants que vous m\'avez apportés sont des instruments puissants et démoniaques. Deviner leur origine est cependant, je le crains, au-delà de mes capacités de chaman. Nous aurons besoin qu\'un démoniste les étudie.|n|nApportez un collier brûlant à Neeru Lamefeu. Bien qu\'il soit un redoutable démoniste, il professe qu\'il utilise ses pouvoirs pour contrecarrer les démons, et proclame que ses recherches sur l\'occulte sont bénignes. Que cela soit vrai ou pas, nous pouvons avoir besoin de son aide contre le culte démoniaque en Durotar. Vous trouverez Neeru à Orgrimmar, dans la Faille de l\'Ombre.', },
    {'Apporter un Spécimen de collier à Neeru Lamefeu à Orgrimmar.', },
  },
  [830] = {
    'Les ordres de l\'amiral',
    {'Vous ouvrez la vieille enveloppe décolorée et découvrez un document d\'apparence officielle. Vous reconnaissez le sceau de l\'amiral Portvaillant.|n|nÇa a l\'air important. Peut-être que Gar\'Thok, le commandant de Tranchecolline, serait intéressé par cette information.', },
    {'Apporter les Ordres de l\'amiral Portvaillant à Gar\'Thok de Tranchecolline.', },
  },
  [831] = {
    'Les ordres de l\'amiral',
    {'On ne peut pas faire confiance aux humains. Nous avons combattu à leurs côtés le cœur empli de lassitude, sachant qu\'ils nous trahiraient un jour.|n|nLa mort de l\'amiral Portvaillant n\'a pas été suffisante pour clore cette longue tradition de tromperie. Cette vermine avait bien préparé ses plans avant qu\'il ne rencontre la mort.|n|nSon influence ne s\'éteindra pas non plus avec Benedict. Qui sait combien de temps il reste avant que la prochaine vague d\'hommes de Portvaillant ne déferle sur nos rivages ?|n|nNous devons apporter ces ordres à Vol\'jin à Orgrimmar immédiatement ! On peut le trouver dans les logements de Thrall.', },
    {'Porter les Ordres de l\'amiral Portvaillant à Vol\'jin, dans les appartements de Thrall à Orgrimmar.', },
  },
  [832] = {
    'Ombres ardentes',
    {'<Des mots émanent du pendentif et dans votre esprit.>|n|nGazz\'uz ?|n|nGazz\'uz… au rapport !|n|nOn raconte que vous avez été découvert au rocher du Crâne. Vous devez vous préparer à une attaque !|n|nGazz\'uz, je vous ordonne de parler ! Parlez ou je m\'assurerai que Neeru Lamefeu apprenne votre présence, et il vous tombera dessus comme la misère sur le monde.|n|nNe testez pas vos capacités contre Neeru...|n|n... Gazz\'uz, vous êtes là ?', },
    {'Apporter cet Oeil à Neeru Lamefeu à Orgrimmar.', },
  },
  [833] = {
    'Le cimetière sacré',
    {'Seuls les plus vaillants taurens sont enterrés aux Rochers rouges, notre terre funéraire sacrée. C\'est un honneur accordé aux grands guerriers qui ont aidé à construire et à défendre les Pitons-du-Tonnerre et à ceux qui ont donné leur vie pour le bien de leur tribu et de leurs chefs.|n|nMais il apparaît qu\'un infâme danger menace notre terre sacrée. Un groupe d\'intrus dos-hirsutes ravage le cimetière et je suis trop vieux et trop faible pour les repousser.|n|nIls doivent pourtant être chassés sans pitié, $N.', },
    {'Tuez 8 Intrus dos-hirsutes à Rochers rouges.', },
  },
  [834] = {
    'Des vents dans le désert',
    {'Je suis Rezlak, l\'un des gars de Gazleu. Le patron m\'a envoyé pour donner un coup de main aux orcs, ici en Durotar. Les choses se sont bien passées, à part pour les caravanes. Je n\'arrive pas à assurer leur sécurité ! Ça rend mon boulot un peu plus difficile, vous savez ?|n|nLa dernière livraison – ils avaient PROMIS de passer ! – a été chipée par les harpies Terrevent au... c\'était où déjà... au canyon de Tranchevent ?|n|nFaut que je récupère ces marchandises ! Suivez le grand canyon vers le sud. Le ravin le traverse d\'est en ouest.', },
    {'Retrouvez 5 Sacs de ravitaillement.', },
  },
  [835] = {
    'Des lignes sécurisées',
    {'Gazleu m\'a dit une fois « Rezlak, il y a une chose que tu dois savoir dans la vie : si tu veux qu\'une chose soit faite correctement, fais-la toi-même. »|n|nJe ne peux supporter la perte de nos caravanes, alors je vais m\'occuper des choses en personne. Les harpies coupent nos lignes d\'approvisionnement. Si nous les tuons toutes, les routes seront sûres.|n|nBien sûr, il y a autre chose que Gazleu m\'a enseigné, et c\'est « En payant bien, tout est possible. » Alors, vous allez m\'aider, $N ? Bien... je vous conseille de commencer par le canyon, à l\'est.', },
    {'Tuez 12 harpies de Durotar. N\'importe quel type de harpie fera l\'affaire.', },
  },
  [836] = {
    'À la rescousse de OOX-09/HL !',
    {'Le robot émet à nouveau la voix du gnome :|n|n« Je dois déplacer OOX-09/HL dans un endroit dégagé et sûr pour qu\'il puisse entamer sa longue procédure de décollage. Il est équipé d\'un camouflage, mais il me faut du temps pour le rendre opérationnel de mon côté. Il faut que vous l\'escortiez jusqu\'au... disons de gros rochers qui cachent la vue ! Ce serait un endroit parfait, et assez long, pour que tout puisse se mettre en route ! »|n|n« Escortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Orguignard Odipnoticus, terminé. »', },
    {'Escortez OOX-09/HL jusqu\'à ce qu\'il soit en sécurité, puis rendez compte à Orguignard Odipnoticus, à Baie-du-Butin.', },
  },
  [837] = {
    'Empiètement',
    {'Quand nous sommes arrivés, les hurans tranchecrins possédaient la majeure partie de la terre, et étaient comme une épine dans notre flanc. Par des efforts constants, nous sommes parvenus à en chasser une grande partie, mais ils restent toujours bien fortifiés dans certains secteurs.|n|nCela a suffisamment duré, cependant. Pour notre propre sécurité, nous ne pouvons tolérer la présence des Tranchecrins sur notre territoire. On peut trouver leurs camps à l\'ouest d\'ici. Cherchez les roncières et vous les trouverez. Aujourd\'hui, nous les chassons de Durotar, et demain, peut-être, de tout Kalimdor.', },
    {'Tuer 4 Hurans tranchecrins, 4 Eclaireurs tranchecrins, 4 Lève-poussière tranchecrins et 4 Gardes de guerre tranchecrins pour Gar\'Thok de Tranchecolline.', },
  },
  [838] = {
    nil,
    {'Sur l\'île de Caer Darrow se trouve la Scholomance - une école servant de forteresse au Fléau. Nos ennemis y résident, à l\'abri, et libres de poursuivre des recherches qui ne font qu\'accroître leur pouvoir. Une porte se dresse sur le chemin, et malgré tous nos efforts, elle ne peut être franchie sans que la bonne clé ne lui soit présentée.|n|nL\'apothicaire Dithers sait beaucoup de choses au sujet de la Scholomance, et a une idée quant à la façon d\'obtenir cette clé. Vous m\'avez prouvé que vous êtes capable d\'atteindre des objectifs, aussi je vous confie cette tâche. Allez lui parler et entretenez-le à ce propos.', },
    {'Parler à l\'Apothicaire Dithers à la Barricade, dans les Maleterres de l\'Ouest.', },
  },
  [840] = {
    'Sous les drapeaux de la Horde',
    {'Hum ! Vous avez l\'air plutôt $Gfort:forte;.|n|nÉcoutez, mon bon ami Kargal a besoin de nouvelles recrues pour servir dans les Tarides. Je sais que vous voulez faire ce qui est bon pour la Horde. Eh bien, voici votre chance !|n|nApportez cette lettre de recrutement à Kargal et voyez s\'il la signe...', },
    {'Donner votre Lettre de recrutement à Kargal Balafre-glorieuse, à l\'Avant-poste des Tarides.', },
  },
  [841] = {
    'Une autre Source d\'énergie ?',
    {'Laissez-moi deviner… vous n\'avez pas accompli l\'un de vos horribles exploits à temps. Non, attendez, encore mieux, vous l\'avez laissée tomber dans le sable ! Bien, qu\'importe la raison, j\'ai d\'autres sources d\'énergie que je peux vous vendre. Cette fois, cependant, ça vous coûtera dix, OUI DIX Outres de Bat-le-désert !|n|nLes temps sont durs par ici vous savez, $N, et les sources d\'énergie ne poussent pas sur les arbres ! Hmm, mais si c\'était le cas... peut-être que nous pourrions FABRIQUER un arbre à sources d\'énergie...', },
    {'Apporter 10 Outres de Bat-le-désert à l\'ingénieur en chef Vizisanie à Gadgetzan pour qu\'il les échange contre une autre source d\'énergie.', },
  },
  [842] = {
    'Conscription à la Croisée',
    {'<Kargal sort une lettre de recrutement toute froissée de sa veste et y griffonne une signature, avant de vous la tendre, l\'air solennel.>|n|nEh bien, moustique, on peut dire que vous avez fait vos preuves ici. Considérez-vous comme $Grengagé:engagée;. On a besoin de gens comme vous à la croisée… si vous y arrivez $Gvivant:vivante;. Prenez la route à l\'ouest. Quand vous arriverez au croisement, prenez vers le sud. Si vous voulez aider votre nouvelle Horde, parlez à Halga et faites la route avec la prochaine caravane. À votre arrivée, remettez cette lettre à Sergra Sombreronce.', },
    {'Remettez votre lettre de recrutement signee à Sergra Sombreronce à la Croisée. Si vous ne l\'avez pas déjà fait, vous pouvez faire la route avec la prochaine caravane en parlant à Halga Œil-sanglant au poste de Guet-Lointain.', },
  },
  [843] = {
    'La reconquête de Gann',
    {'Je foule ces chemins dans la solitude.|n|nLes nains de Bael Modan n\'ont aucun respect pour ma terre. D\'horribles explosions creusent profondément le sol tandis que des machines éventrent les collines. La terre qui autrefois était le foyer et la nourrice de ma tribu est aujourd\'hui grouillante de ces nains destructeurs.|n|nLes tentatives diplomatiques pour arriver à un accord ont échoué. À présent l\'heure de l\'action radicale a sonné.|n|nRepoussez par la force les nains de Bael Modan et apportez-moi le journal de leur chef, le prospecteur Khazgorm.', },
    {'Gann Cime-de-pierre veut que vous tuiez 15 Excavateurs de Bael\'dun et 5 Surveillants de Bael\'dun.|n|nApporter le Journal de Khazgorm à Gann Cime-de-pierre.', },
  },
  [844] = {
    'La menace des trotteurs des plaines',
    {'Vous connaissez les trotteurs des plaines ? Elles sont bonnes à rien, ces bêtes-là. Elles savent pas voler. Des grosses poules avec une cervelle de la taille de l\'articulation de mon petit doigt. Trop gourdes pour éviter un chariot qui arrive sur elles. J\'ai cassé plus d\'un essieu sur leurs crânes épais... Parfois j\'ai l\'impression que les hurans font exprès d\'effrayer un troupeau pour l\'envoyer devant nos caravanes juste avant de nous prendre en embuscade.|n|nFaites-moi plaisir, $C. Décimez ces sales volatiles pour nettoyer les routes et apportez-moi leurs becs en guise de preuve.', },
    {'Collectez 7 Becs de trotteur des plaines.', },
  },
  [845] = {
    'Les zhévras',
    {'Si vous souhaitez servir ma chère Horde, vous allez devoir me prouver votre force, mon petit. Vous pouvez vous faire les dents en chassant les zhévras. Ils ne sont peut-être pas les animaux les plus forts des Tarides, mais évitez leurs ruades ou vous le regretterez.|n|nChassez les zhévras au nord et au sud et ramassez leurs sabots. Apportez-les-moi, et peut-être qu\'on vous enverra ensuite vous battre contre quelque chose de plus costaud.', },
    {'Tuez des Messagers zhévras pour obtenir 4 Sabots de zhévra.', },
  },
  [846] = {
    'La revanche de Gann',
    {'Il est évident que le prospecteur dépendait des explosifs et des véhicules bruyants pour déchirer le sol. Nous pouvons nous attendre à ce qu\'un nouveau contremaître le remplace bientôt.|n|nJ\'aimerais faire goûter aux nains leur propre médecine. D\'après ces plans, si nous combinons de la nitroglycérine avec de la pulpe de bois et du nitrate de sodium, nous pouvons créer une charge explosive. Les fusiliers, les soldats et les officiers du donjon possèdent ces ingrédients.|n|nRécupérez ces objets et apportez-les-moi. Je confectionnerai une charge que les nains ne sont pas près d\'oublier.', },
    {'Gann Cime-de-pierre veut que vous lui apportiez 6 Fioles de Nitroglycérine, 6 Paquets de Pulpe de bois et 6 échantillons de Nitrate de sodium.', },
  },
  [847] = {
    'La ruse du raptor',
    {'Ce… Ce pouvoir… Est-ce le pouvoir des chamans que Tor\'gan a essayé de me montrer ? Je dois admettre que c\'est intéressant. Dites à Tor\'gan qu\'il a réussi à me convaincre… pour l\'instant. Je vais écouter ce qu\'il a à dire.', },
    {'Parler à Tor\'gan au Trépas-d\'Orgrim, dans les Hautes-terres Arathies.', },
  },
  [848] = {
    'Spores fongiques',
    {'Les oasis des Tarides renferment un mystère. Une énergie vitale parcourt leurs eaux, vivifiant les plantes et les animaux qui s\'y abreuvent.|n|nElle les vivifie… et les transforme.|n|nIl existe un champignon qui pousse près des bassins Oubliés, au nord-ouest. Ses spores ont des propriétés que nous, les apothicaires de Lordaeron, trouvons utiles.|n|nRapportez-moi ces spores et vous aurez toute notre gratitude.', },
    {'Récoltez 5 Spores fongiques sur des champignons dans les Bassins Oubliés.', },
  },
  [849] = {
    'La revanche de Gann',
    {'En suivant les plans de Khazgorm, la fabrication d\'une charge explosive ne devrait pas poser de problème.|n|nAh ! Nous y voilà.|n|nÀ présent, $N, je vais vous confier une tâche spéciale. Prenez ce bâton explosif et utilisez-le pour faire sauter la machine volante à Bael Modan.|n|nNon seulement cette machine est une partie cruciale de l\'infrastructure du site, mais elle sert également de machine de guerre. Plus important encore, c\'est un symbole de pouvoir et une insulte portée à la mémoire de ma tribu.|n|nFaites ma fierté en concluant cette quête héroïque et vous serez $Grécompensé:récompensée;.', },
    {'Détruire la Machine volante à Bael Modan et retourner voir Gann Cime-de-pierre.', },
  },
  [850] = {
    'Les chefs des Kolkars',
    {'Les centaures nuisent aux taurens depuis des années. Et récemment, les centaures kolkars des Tarides sont devenus un danger réel. D\'habitude, ils étaient désorganisés, mais de nouveaux chefs ont émergé. Et les ont unis.|n|nAfin de préserver nos possessions ici, ces chefs centaures doivent être éliminés.|n|nApportez-moi la tête de Barak Plaie-des-kodos. Il campe à l\'ouest des bassins Oubliés.|n|nVainquez-le, puis revenez me voir.', },
    {'Tuez Barak Plaie-des-kodos et prenez sa tête.', },
  },
  [851] = {
    'Verog le Derviche',
    {'Verog se cache bien, mais d\'après les renseignements que vous avez obtenus, sa femelle Wyneth se trouve toujours dans sa tente de commandement, juste à l\'ouest. Si nous la tuons, Verog arrivera ventre à terre.|n|nRegthar nous a envoyés ici en éclaireurs, mais il a aussi donné l\'ordre de désorganiser la chaîne de commandement des centaures à chaque fois que nous en aurions l\'occasion. Faites sortir Verog de sa cachette et tuez-le !', },
    {'Tuez Wyneth afin d\'attirer Verog le Derviche, puis tuez-le et prenez sa tête.', },
  },
  [852] = {
    'Hezrul Marque-de-sang',
    {'Hezrul Marque-de-sang dirige les centaures des Tarides. Il est féroce, brutal et rusé. Le faire disparaître bouleverserait les Kolkars et les diviserait, ce qui réduirait fortement la menace qu\'ils représentent pour nous.|n|nVous devez tuer Hezrul. Rapportez-moi sa tête et je l\'accrocherai aux murs de ce poste de garde pour que les centaures sachent ce qu\'est la peur.|n|nHezrul dirige son peuple depuis l\'oasis Luxuriante, au sud.', },
    {'Tuez Hezrul Marque-de-sang et prenez sa tête.', },
  },
  [853] = {
    '[PÉRIMÉ]L\'apothicaire Zamah',
    {'J\'ai fait une émulsion avec les spores que vous m\'avez apportées. Je dois à présent l\'envoyer à mon associée, l\'Apothicaire Zamah. Si vous pouviez la lui apporter, elle pourra vous offrir quelque chose de nos magasins d\'alchimie.|n|nElle est aux Bassins de la vision, une caverne qui se trouve sous les chamans des Pitons-du-Tonnerre. Le chemin menant à cette caverne est bien caché, mais vous pourrez le trouver sur la cime des Esprits.|n|nDépêchez-vous ! Cette émulsion ne restera pas puissante longtemps. Elle doit être livrée et utilisée au plus vite.', },
    {'Apportez les Spores fondues à l\'Apothicaire Zamah aux Pitons-du-Tonnerre, avant que la limite de temps ne soit dépassée.', },
  },
  [854] = {
    'Un voyage à la Croisée',
    {'J\'avais prédit votre arrivée, jeune $C. Bien que peut-être vous ne soyez plus si jeune.|n|nJe crois qu\'il est temps de vous aventurer plus profondément dans ces terres. Je sens que vous êtes $Gdestiné:destinée; à de grandes choses.|n|nC\'est la Croisée que vous devez chercher à présent, dans la mesure où nos vies se sont mêlées à celles des orcs et qu\'ils ont besoin de notre aide. Descendez cette route vers l\'est et suivez-la vers le nord en direction de la Croisée. Trouvez Thork dans ses murs, il est béni par la Terre-mère.', },
    {'Parler à Thork, à la Croisée des Tarides.', },
  },
  [855] = {
    'Bracelets de centaure',
    {'La structure de commandement des centaures repose sur un noyau de guerriers dévoués et disciplinés qui maintiennent les autres dans le rang. Si nous réduisons l\'effectif de ces vétérans, les simples centaures seront désorganisés. J\'ai donc une mission pour vous, avec une récompense à la clé.|n|nAutour de l\'oasis Luxuriante, au sud, vous trouverez des maraudeurs et des prophètes-tempête kolkars. Tuez-les et récupérez leurs bracelets. Revenez quand vous aurez amassé une bonne quantité de ces trophées et la Horde vous récompensera généreusement.', },
    {'Récupérez 10 Bracelets de centaure sur des Maraudeurs et des Prophètes-tempête kolkars.', },
  },
  [856] = {
    nil,
    {'Bien que vous ayez atteint les Tarides, votre voyage n\'est pas terminé. Vous devez le poursuivre jusqu\'à la Croisée, où l\'on a beaucoup besoin de vous.|n|nSuivez la route sur laquelle vous étiez, et tournez à gauche lorsque le chemin vous laisse le choix. Continuez vers le nord jusqu\'à voir les murs de la Croisée.|n|nJuste avant d\'entrer, rencontrez le Sage Ancestral, il vous dispensera quelques mots de sagesse.', },
    {'Descendre la route à partir du Camp Taurajo.|n|nTourner à gauche à l\'intersection en T et continuer vers le nord.|n|nSuivre le chemin jusqu\'au Sage Ancestral à l\'extérieur de la Croisée.', },
  },
  [857] = {
    'La larme des lunes',
    {'La puissance était mienne ! Dans mes propres mains ! Et je veux la retrouver ! La retrouver, je vous dis !|n|nCes fichus excavateurs l\'ont découverte… Elle était tellement belle. Avoir trouvé la Larme des lunes, c\'était la première grande découverte qu\'on avait faite à Bael Modan.|n|nElle aurait dû être mienne ! Mienne je vous dis !|n|nMais le général Doublenattes devint jaloux de la puissance qu\'elle me donnait. Il l\'a enfermée à clé dans le donjon. L\'a traitée de maudite, il l\'a fait ! L\'imbécile !|n|nD\'autres la voulaient et ils devaient être arrêtés ! Ce bâtard de Doublenattes m\'a chassé.|n|nMaintenant, je la veux à nouveau ! Je la veux je vous dis !', },
    {'Feegly l\'Exilé veut que vous retrouviez pour lui la Larme des lunes.', },
  },
  [858] = {
    'Contact',
    {'Ce n\'est sûrement pas Krachevalve qui vous a $Genvoyé:envoyée; ? Je suis coincé ici. Je suis entré sans réaliser que j\'avais besoin d\'une clé pour déverrouiller la colonne de déplacement du déchiqueteur. L\'un des autres opérateurs m\'a demandé si tout allait bien, et j\'ai paniqué ! Au lieu de lui dire que je n\'avais pas la clé, je lui ai dit qu\'il y avait un genre de problème mécanique.|n|nNous devons sortir d\'ici au plus vite ! Montez à la salle de contrôle au sommet du derrick, le superviseur devrait avoir une clé pour ce déchiqueteur.|n|nSortez-moi de là !', },
    {'Allez chercher la Clé de contact auprès du Superviseur Trimballast.', },
  },
  [860] = {
    'Sergra Sombreronce',
    {'Si vous souhaitez suivre la voie du chasseur, alors votre voyage vous mène jusqu\'aux Tarides. Ses créatures sont robustes et féroces. Vous y apprendrez beaucoup en les traquant, et votre volonté grandira.|n|nParlez à Sergra Sombreronce. Elle sera votre premier guide dans les Tarides.|n|nElle se trouve à la Croisée. Pour l\'atteindre, allez à l\'est en partant de Sabot-de-Sang et en vous rendant dans les Tarides, puis allez au nord lorsque le chemin se sépare. Et attention tandis que vous voyagez. Les Tarides réservent de grands dangers pour ceux qui manquent de préparation ou de prudence.', },
    {'Parler à Sergra Sombreronce, à la Croisée.', },
  },
  [861] = {
    'Le chemin du chasseur',
    {'Vous êtes avide d\'explorations, ça se voit. J\'avais aussi le désir d\'explorer, autrefois…|n|nD\'explorer, et de chasser. Car chasser est le plus grand honneur d\'un tauren.|n|nSi vous désirez vraiment suivre la voie du chasseur, apportez-moi les griffes de Rôdeurs des basses plaines de Mulgore. Ils sont robustes et astucieux, une proie parfaite pour $Gun:une:c; jeune $C qui suit la voie de la chasse.', },
    {'Récupérez 4 Griffes de Rôdeurs des basses plaines.', },
  },
  [862] = {
    'Brouet de rat',
    {'$GUn:Une:c; $C comme vous doit plutôt avoir faim ici dans les Tarides. Moi, je crève la dalle tout au long de la journée.|n|nJe vais vous mitonner un chouette brouet. J\'ai juste besoin de quelques rats fouisseurs.|n|nIl semble que ces sales nains de Bael Modan soient submergés par le festin favori de tout un chacun. À présent descendez vers le sud, à Bael Modan, et apportez-moi quelques rats fouisseurs.|n|nVous ne pouvez pas vous prétendre $Gaventurier chevronné:aventurière chevronnée; si vous n\'avez pas passé du temps à tuer des rats ! Ha !', },
    {'Apporter 8 Rats fouisseurs à Boustiff\' à l\'est de la Croisée.', },
  },
  [863] = {
    'La fuite',
    {'Je suppose que j\'apprendrai en le faisant… Ça ne devrait pas être trop difficile. Juste quelques boutons par-ci par-là, et un levier ou deux… Alors, êtes-vous $Gprêt:prête; à y aller ?', },
    {'Protégez Crackelevier et le Déchiqueteur gobelin pendant la fuite hors de la Videfange.', },
  },
  [864] = {
    'De retour vers l\'apothicaire Zinge',
    {'« Et voilà, la source d\'énergie est enlevée et les données sont préservées. Bien, faites attention sur la route et tout ça. J\'espère que cette horrible expérience s\'est bien déroulée pour vous, et tous les autres… »|n|nLe gobelin se détourne pour s\'occuper des demandes de la Compagnie des eaux de Gadgetzan. « Vous mettez la trousse d\'analyse verrouillée à l\'abri en vue du voyage de retour vers Fossoyeuse. Là-bas, l\'apothicaire Zinge vous attend, vous et la trousse d\'analyse de terrain verrouillée. »', },
    {'Apportez la Trousse d\'analyse de terrain verrouillée à l\'apothicaire Zinge à Fossoyeuse.', },
  },
  [865] = {
    'La corne, c\'est le pied',
    nil,
    nil,
  },
  [866] = {
    'Les échantillons de racines',
    {'Les herbes qui poussent dans les Tarides ne sont pas tout à fait pareilles à celles des autres contrées. Leurs propriétés sont à peu près semblables, mais l\'eau des oasis les transforme légèrement. Elles sont juste un peu différentes.|n|nJ\'aimerais étudier ces différences... pour voir si nous pouvons les exploiter !|n|nSi vous êtes $Gun herboriste compétent:une herboriste compétente;, cueillez les herbes que vous trouvez dans les Tarides. Apportez-moi ces échantillons que je puisse les comparer aux herbes des autres régions.', },
    {'Récoltez 8 Échantillons de Racines sur des herbes des Tarides du Nord.', },
  },
  [867] = {
    'Les harpies pillardes',
    {'Tant que vous êtes là, $C, peut-être que vous pouvez m\'aider. Ces maudites harpies massacrent nos caravanes d\'approvisionnement depuis trop longtemps déjà. Il est temps que nous tranchions quelques-unes de leurs gorges et que nous réduisions leur nombre.|n|nL\'attaque la plus dévastatrice devra détruire une bonne partie de leur chaîne inférieure de commandement, pour que nous puissions ensuite remonter jusqu\'au sommet.|n|nNous allons commencer en douceur. Tuez des harpies ensorçaile de n\'importe quel type au nord-ouest, et apportez-moi 6 griffes d\'Ensorçaile. Ce sera un bon début…', },
    {'Prélevez 6 Griffes d\'Ensorçaile sur des Harpies et des Volplumes ensorçaile.', },
  },
  [868] = {
    'La chasse aux œufs',
    {'Hé $N ! On m\'a fait venir à la Croisée pour surveiller la zone et noter ce qui s\'y déroule, pour mes maîtres à Orgrimmar.|n|nL\'un de mes sujets d\'étude est cette créature, ressemblant à un insecte, et que nous avons découverte au sud dans le Champ des géants. Nous savons peu de choses sur ces bêtes, alors je me fais un point d\'honneur d\'en découvrir plus. Elles semblent posséder quelque intelligence, plus que la plupart des simples animaux.|n|nPrenez cette griffe d\'excavation et récupérez quelques œufs dans les tertres où vivent ces bêtes. Mais attention, si elles sont alertées par quoi que ce soit, elles vous attaqueront.', },
    {'Apporter 12 Œufs de silithide et la Griffe d\'excavation à Korran, à la Croisée.', },
  },
  [869] = {
    'Sur la piste du voleur',
    nil,
    nil,
  },
  [870] = {
    'Les bassins Oubliés',
    {'Vous avez senti les secousses, $C ? Quelque chose a déchiré cette contrée en deux. Cependant, nous, les druides, pouvons sentir des secousses d\'un autre ordre.|n|nLa vie bouillonne désormais dans des terres autrefois desséchées et stériles. Les oasis autour de la Croisée se mettent soudain à reverdir. Je sens qu\'une force se fraye un chemin vers la surface, mais d\'où vient-elle ? Est-elle liée au désastre qui a frappé les Tarides ?|n|nNous devons en trouver l\'origine. Allez aux bassins Oubliés, au nord-ouest de la Croisée et explorez-en les fonds à la recherche d\'une source de pouvoir. Quand vous l\'aurez trouvée, revenez ici.', },
    {'Fouillez le fond des Bassins Oubliés au nord-ouest de la Croisée.', },
  },
  [871] = {
    'La défense du poste de Guet-Lointain',
    nil,
    nil,
  },
  [872] = {
    'L\'offensive du poste de Guet-Lointain',
    nil,
    nil,
  },
  [873] = {
    nil,
    {'Le grand Isha Awak est le seigneur de ces eaux. Grande est sa force et solennelle est sa fierté. Les humains de la côte le craignent, car il en a occis beaucoup parmi eux.|n|nMais il ne me fait pas peur. Je suis reconnaissante de son existence. Il est un digne défi et une proie honorable.|n|nSi vous êtes $Gprêt:prête; alors partez nager et cherchez Isha Awak, le Destin des profondeurs.|n|nSon esprit demeure dans son cœur, et l\'entendre battre, c\'est voir votre destinée.', },
    {'Apportez le Cœur d\'Isha Awak à Mahren Oeil-des-cieux.', },
  },
  [874] = {
    'Mahren Oeil-des-Cieux',
    {'Vous avez chassé les bêtes des Tarides. Votre esprit est fort. Mais un chasseur doit toujours être prêt. Un véritable chasseur doit être capable de traquer une proie sur n\'importe quelle piste. Des montagnes ou des marais ne sauraient le rebuter.|n|nEt pas même la mer.|n|nAllez trouver ma sœur, Mahren. Elle chasse les grandes bêtes maritimes le long de la côte. Ce sera votre professeur.|n|nMais soyez $Gprudent:prudente; tandis que vous la recherchez, car la côte des Tarides est détenue par des humains.', },
    {'Parler à Mahren Oeil-des-cieux.', },
  },
  [875] = {
    'Lieutenants harpies',
    {'La seule manière d\'éliminer les Ensorçailes, c\'est de briser leur chaîne de commandement. Les harpies sont commandées par d\'intrépides lieutenants, les tueuses ensorçaile. Si vous tuez les tueuses, le reste suivra.|n|nRendez-vous dans les collines Arides et massacrez-les. Faites en sorte qu\'elles meurent dans la douleur, $N. Nous voulons montrer à ces femelles qu\'il n\'est pas sage de choisir la Horde comme adversaire.', },
    {'Tuez 6 Tueuses ensorçaile dans les Collines Arides, dans les Tarides du Nord.', },
  },
  [876] = {
    'Serena Plumesang',
    {'Avant de mourir, les harpies que vous avez tuées ont mentionné le nom de leur matriarche, Serena Plumesang. À en juger par la haine farouche dont les harpies font preuve envers la Horde, leur matriarche doit nourrir une sorte de profonde rancune. Vous décidez de traquer Serena Plumesang et de mettre un terme à son problème une bonne fois pour toutes.', },
    {'Tuez Serena Plumesang et prenez sa tête.', },
  },
  [877] = {
    'L\'oasis Stagnante',
    {'Est-il possible que ce qui arrive dans le sud se reproduise ici ? À en juger par ce que vous avez trouvé aux bassins Oubliés, la réponse passe peut-être par les oasis. Tentons une expérience, voulez-vous ?|n|nTenez, prenez ces graines récoltées au sommet de cette montagne. Elles sont mortes et stériles. Apportez-les à l\'oasis Stagnante, juste en contrebas et si vous y trouvez une fissure, déposez-y les graines… et observez ce qui se passe. Rendez compte du résultat à Tonga, à la Croisée.', },
    {'Utilisez les graines séchées pour enquêter sur les fissures, à l\'Oasis Stagnante.', },
  },
  [878] = {
    'Tribus en guerre',
    {'Vous devez frapper mes ennemis <grogne>. Vous devez aider Mutiledent et les Tranchecrins en affaiblissant les Dos-hirsutes. Les deux tribus accordent beaucoup d\'importance à la spiritualité et sont très liées à la terre et à ses pouvoirs <grogne>. Cela nous apporte de la force en tout, et pour la guerre en particulier.|n|nSi vous voulez découvrir qui a causé à Thork <grogne> et à la Horde un tel supplice, alors aidez Mutiledent ! Attaquez les chefs spirituels des Dos-hirsutes au nord. Affaiblissez-les afin que les Tranchecrins puissent les vaincre et régner sur les Tarides.', },
    {'Tuer 6 Sourciers dos-hirsutes, 12 Tisseurs d\'épines dos-hirsutes et 12 Géomanciennes dos-hirsutes puis retourner auprès de Mutiledent au camp Taurajo dans les Tarides.', },
  },
  [879] = {
    'Une trahison de l\'intérieur',
    {'Trois membres de ma tribu sont venus du kraal pour diriger les raids contre la Horde, $R. <grogne> Ils sont brutaux et malins, et si vous parvenez à les vaincre, alors votre Croisée et même la plus grande partie des Tarides seront en paix... <grogne>|n|nNak, Kuz et Lok Plaie-des-orcs sont ceux que vous recherchez. Ils se trouvent loin au sud des Tarides. L\'un lance des sorts, l\'autre est un pisteur, et leur chef, celui qu\'on nomme Plaie-des-orcs <grogne> est un guerrier. Tuez-les, $R, tout comme ils m\'ont tué.', },
    {'Tuer Nak, Kuz et Lok Plaie-des-orcs et apporter leurs crânes à Mutiledent au Camp Taurajo dans les Tarides.', },
  },
  [880] = {
    'Source de vie',
    {'Il sera important d\'étudier l\'incidence que les oasis et l\'énergie bizarre que vous y avez découverte ont sur la faune et la flore. L\'oasis Stagnante, en contrebas, abrite une espèce de tortue gueule d\'acier dont la population a récemment explosé. En outre, ces animaux jadis pacifiques sont devenus agressifs. J\'en ai fait personnellement l\'expérience avant de monter jusqu\'ici.|n|n<Jerrik vous montre un doigt pansé.>|n|nJe soupçonne les oasis d\'avoir modifié leur comportement. Récoltez leurs carapaces et donnez-les à analyser à Tonga, à la Croisée.', },
    {'Prélevez 6 Carapaces de Gueules d\'acier altérées sur des Gueules d\'acier de l\'Oasis Stagnante.', },
  },
  [881] = {
    nil,
    {'Blanchebrume, ou « Echeyakee » dans la langue des taurens, est le roi des lions des savanes. Il chasse si furtivement qu\'il est comme une brume légère et blanche sur la terre. Il tue si vite que ses proies n\'ont pas le temps d\'avoir peur ni de souffrir.|n|nLes taurens disent qu\'il est à la fois la miséricorde et la mort.|n|n$N, je vous lance à la poursuite d\'Echeyakee. Son antre est juste au nord-ouest, sur la face nord d\'une petite montagne, au milieu des ossements de kodo géant.|n|nSonnez de cette corne dans les parages de son antre et il se montrera.', },
    {'Soufflez dans votre cor devant le repaire d\'Echekayee pour le faire apparaître. Tuez-le ou dominez-le.', },
  },
  [882] = {
    nil,
    {'Ishamuhale, Lancecroc, est le plus redoutable des raptors solécailles. Il ne chasse pas pour se divertir, ni pour se nourrir. Il chasse par passion. Il tue car sa nature est de tuer.|n|nEt vous allez apprendre de cette nature, $N, car votre voie suit à présent les traces griffues d\'Ishamuhale.|n|nCommencez la chasse. Tuez sa proie favorite, un zhévra, puis emmenez sa carcasse à l\'arbre mort au nord-ouest de Cabestan. Ishamuhale sera attiré par l\'odeur.|n|nSoyez $Gprêt:prête; lorsqu\'il arrivera.', },
    {'Apporter le Croc d\'Ishamuhale à Jorn au Camp Taurajo.', },
  },
  [883] = {
    nil,
    {'Le Sabot de Lakota\'mani est un symbole de la force du grand kodo.', },
    {'Apportez le Sabot de Lakota\'mani à Jorn au Camp Taurajo.', },
  },
  [884] = {
    nil,
    {'Lorsqu\'on le touche, des étincelles jaillissent de l\'épine caudale d\'Owatanka.', },
    {'Apporter l\'Epine caudale d\'Owatanka à Jorn au Camp Taurajo.', },
  },
  [885] = {
    nil,
    {'La plume de Washte Pawne est douloureuse au toucher.', },
    {'Apportez la Plume de Washte Pawne à Jorn Oeil-des-cieux au Camp Taurajo.', },
  },
  [886] = {
    'Les oasis des Tarides',
    {'Les druides des Pitons-du-Tonnerre sentent une étrange puissance qui fuit dans les Tarides, à l\'est de Mulgore.|n|nNous avons envoyé Tonga Totem-runique pour enquêter sur la source de cette puissance, mais nous craignons qu\'il ait besoin d\'aide.|n|nVoyagez jusqu\'aux Tarides et parlez à Tonga. Il sera à la Croisée. Pour atteindre cet endroit, prenez la route à l\'est en sortant de Sabot-de-Sang. Entrez dans les Tarides, puis tournez vers le nord lorsque la route se divise. Continuez dans cette direction et vous trouverez la Croisée.|n|nEt ne quittez pas la route, $N, car les Tarides sont hostiles.', },
    {'Parler à Tonga Totem-runique à la Croisée.', },
  },
  [887] = {
    'Flibustiers des mers du Sud',
    {'Gazleu m\'a promis une promotion si je l\'aidais à régler les soucis de piraterie à Cabestan. Le problème, ce sont ces nouveaux boucaniers qui se sont fixés sur l\'île de la Dispute, au sud. Ils n\'en ont pas seulement après nos marchandises, ils ont aussi des comptes à régler ! L\'autre nuit, ils s\'en sont même pris à l\'un de nos galions de guerre.|n|nJe suis en train d\'élaborer un plan pour traiter cette situation en profondeur, mais Gazleu veut des résultats immédiats. Allez donc sur l\'île de la Dispute pour faire sauter quelques têtes, d\'accord ?', },
    {'Tuez 8 Coupe-gorge ou Corsaires des mers du Sud sur l\'Île de la Dispute.', },
  },
  [888] = {
    '[PÉRIMÉ]Course à la lentille',
    {'J\'aimerais récupérer toutes mes marchandises. Hélas, je suis sûr que ce n\'est pas possible. Mais il y a des choses que je dois absolument récupérer !|n|nComme vous pouvez le constater, mon observatoire est prêt à fonctionner, mais il manque la plus petite des deux lentilles. La première est arrivée de Durotar par caravane, mais la deuxième a été envoyée par bateau, et elle ne m\'est jamais parvenue ! Je n\'ai pas non plus reçu mes bottes de chez Drizzlik à Baie-du-Butin !|n|nPartez pour le camp des pirates, et voyez si vous les trouvez.', },
    {'Retrouver la Cargaison de bottes et la Lentille de télescope pour Gazleu de Cabestan.', },
  },
  [889] = {
    'L\'esprit du vent',
    nil,
    nil,
  },
  [890] = {
    '[PÉRIMÉ]La livraison perdue',
    {'J\'ai attendu durant une éternité l\'arrivée de mon dernier chargement de marchandises de Baie-du-Butin ! Je suis à peu près sûr qu\'il a dû être volé par les Flibustiers, mais pour que je le sois complètement, pourriez-vous descendre du côté des docks et demander à Tournoupette si mes marchandises ont déjà été livrées à mon entrepôt sans que je le sache ?|n|nTenez, descendez mon Grand livre à Tournoupette et demandez-lui de vérifier à nouveau mes inventaires par rapport à ses registres.', },
    {'Apporter le Grand Livre de Gazleu au Maître des quais Tournoupette.', },
  },
  [891] = {
    'La vengeance d\'un capitaine',
    nil,
    nil,
  },
  [892] = {
    '[PÉRIMÉ]La livraison perdue',
    {'Tout a l\'air correct selon mes registres, $N. Retournez-y et dites à Gazleu que sa chance a tourné. Je ne serais pas surpris que les pirates aient pris ses marchandises.|n|nJe ne peux rien faire d\'autre pour lui. Oh !… Vous pourriez lui dire quand même que j\'ai quelque chose venant de Terremine à son nom, s\'il peut faire un saut pour le chercher.', },
    {'Rapporter le Grand Livre de Gazleu à Gazleu à Cabestan.', },
  },
  [893] = {
    'Des armes de choix',
    {'Les hurans tranchecrins, au sud, au-delà du Champ des géants, n\'ont pas de forgerons compétents, que je sache. Mais ils ont apparemment commencé à construire des armes plus solides. J\'aimerais mettre la main sur différents types de ces armes pour acquérir leurs techniques, si possible.|n|nSi vous souhaitez œuvrer pour l\'honneur de la Horde, apportez-moi des exemples de leurs armes. Obtenez une dague de leurs traqueurs, une baguette de leurs prophètes, et un bouclier de leurs frénétiques. Cela devrait parfaitement faire l\'affaire.', },
    {'Apporter un Eustache tranchecrin, une Baguette tranchecrin carbonisée et un Bouclier tranchecrin à Tatternack Forgacier au camp Taurajo dans les Tarides.', },
  },
  [894] = {
    nil,
    {'La KapitalRisk dispose d\'un petit centre de recherches à l\'ouest d\'ici, juste après la Videfange. Je ne sais pas vraiment ce qu\'ils y font, mais j\'ai pu découvrir qu\'ils y menaient des expériences sur un appareil appelé « samophlange ».|n|nMais qu\'est-ce que ça peut bien être, un samophlange ? Enfin, quoi qu\'il en soit, je veux examiner cette machine, il faut donc que quelqu\'un aille la récupérer pour moi.|n|nJ\'ai pu me procurer un exemplaire de leur mode d\'emploi du système de contrôle, vous devriez pouvoir trouver comment désengager le samophlange.', },
    {'Accéder à la Console de contrôle au Centre de recherches de la KapitalRisk.', },
  },
  [895] = {
    'ON RECHERCHE : cap\'taine Garvey',
    nil,
    nil,
  },
  [896] = {
    'La bonne fortune d\'un mineur pauvre',
    {'Hé, $R, ça vous intéresse, les pierres précieuses ? Je savais que ça piquerait votre curiosité.|n|nÀ ce qu\'on dit sur les docks de la rivière, l\'un des mineurs de la KapitalRisk qui exploite la mine des Pierriers juste au nord-est a trouvé une émeraude de la taille de votre poing.|n|nJe connais quelques acheteurs qui seraient intéressés par un tel caillou, et je suis prêt à faire cinquante-cinquante sur sa vente. Ça vous tente ?', },
    {'Récupérez l\'Émeraude œil-de-chat sur l\'un des Surveillants ou l\'un des Massacreurs de la KapitalRisk.', },
  },
  [897] = {
    'Le Moissonneur',
    {'Cette étrange créature, qui ressemble à un insecte, n\'a pas l\'air de faire partie de l\'ordre naturel, comme si elle n\'appartenait simplement pas aux Tarides.', },
    {'Apportez la Tête du Moissonneur à Jorn Oeil-des-cieux.', },
  },
  [898] = {
    'Hors du fort',
    {'Enfin ! Quelqu\'un est venu me sauver !|n|nIl est incroyable que vous ayez passé les gardes. Ces fanatiques de Theramore sont devenus fous. Ils ont coulé notre navire et m\'ont emprisonné. Je suis le seul survivant. Ils ont dit que j\'étais leur ennemi et un danger pour l\'Alliance.|n|nMoi ! Un danger pour leur parodie d\'Alliance ? J\'étais matelot sur un transport de gnôle entre Cabestan et Baie-du-Butin.|n|nMais assez parlé. Aidez-moi à retourner à Cabestan, voulez-vous ? Dites-moi lorsque vous serez $Gprêt:prête; et nous prendrons la fuite.', },
    {'Escorter en toute sécurité Gilthares Ramefeu jusqu\'au capitaine Brillesoleil à Cabestan.', },
  },
  [899] = {
    'Consumé par la haine',
    {'Ils ont assassiné ma femme. Ils ont brûlé ma ferme. Depuis cette funeste nuit, je parcours ces terres, de l\'aube au coucher du soleil, et je scrute l\'horizon à la recherche de ces monstres. J\'ai tué chaque homme-sanglier que j\'ai rencontré depuis, mais ma soif de sang est loin d\'être étanchée.|n|nVous, $C, vous pourriez m\'aider.|n|nTuez-les. Tuez-en autant que vous pouvez. Apportez-moi leurs défenses et nous boirons ensemble à leur destruction.', },
    {'Obtenez 30 Défenses de huran.', },
  },
  [900] = {
    nil,
    {'Les trois valves de contrôle sont actuellement ouvertes. Les indications sur le panneau de contrôle vous amènent à penser qu\'elles doivent être fermées pour que l\'appareil puisse être arrêté.', },
    {'Fermez la Valve de contrôle du carburant, la Valve de réglage et la Valve de contrôle principale, puis utilisez à nouveau la console de contrôle.', },
  },
  [901] = {
    nil,
    {'Comme l\'appareil est désactivé, le panneau de contrôle peut s\'ouvrir et on peut sortir le samophlange de la console. À présent que tout est en place, il reste à trouver la clé qui déverrouillera la console.', },
    {'Récupérez la Clé de la console du Bricoleur Brokarde.', },
  },
  [902] = {
    nil,
    {'Ouvrir la console de contrôle révèle des entrelacs de fils, de tubes et d\'autres objets mécaniques étranges, dont la plupart ne semblent avoir aucune utilité. En les écartant et en fouillant au fond de la console, vous découvrez le samophlange. Vous le retirez d\'un coup sec de son réceptacle.', },
    {'Rapportez le Samophlange à Krachevalve, à l\'Avant-poste de Potuyère, dans les Tarides du Nord.', },
  },
  [903] = {
    'La chasse aux chasseresses',
    nil,
    nil,
  },
  [905] = {
    'Dans l\'antre du raptor',
    nil,
    nil,
  },
  [906] = {
    'Une trahison de l\'intérieur',
    {'Apportez la tête de Lok à Thork à la Croisée, $R. <grogne> Il devrait savoir ce qu\'il est advenu de ma tribu sans le moindre mot — ha, mais je ne m\'attends pas à ce qu\'il croie que Mutiledent y a <grogne> contribué. Mais il est certain qu\'il vous récompensera pour vous être $Goccupé:occupée; de tels actes <grogne>.|n|nJe vais continuer à vous bénir du pouvoir d\'Agammagan aussi longtemps que je resterai dans cette cage, $R. Jusque-là, adieu.', },
    {'Apporter le Crâne de Lok à Thork à la Croisée des Tarides.', },
  },
  [907] = {
    'Les lézards-tonnerre enragés',
    {'À présent, $N, vous devez combattre les grands lézards-tonnerre. Ces bêtes sont si imposantes que le sol tremble lorsqu\'ils parcourent les plaines. Prenez garde lorsque vous les combattez, car un faux pas peut vous jeter directement sous leurs pattes.|n|nVous trouverez les lézards-tonnerre au sud des Tarides. Ils sont connus sous les noms de Groin-tempête, Orageux et Tête-tonnerre. Revenez me voir lorsque vous les aurez vaincus.', },
    {'Apporter 3 doses de Sang de lézard-tonnerre à Jorn Oeil-des-cieux, au Camp Taurajo.', },
  },
  [908] = {
    'Parmi les ruines',
    {'Le Marteau du crépuscule s\'est déplacé dans les ruines d\'Écrin-de-Lune des profondeurs de Brassenoire. Leur présence forcera les élémentaires à travailler contre nous. Si nous ne nous occupons pas de cette région, ils en prendront complètement le contrôle.|n|n$N, allez à Brassenoire et trouvez la pierre de la Brasse. Elle devrait se trouver quelque part, à proximité, dans l\'eau. À l\'intérieur, se trouve un noyau de la Brasse, un objet qui, s\'il est utilisé correctement, offrira un historique de toute l\'activité des élémentaires. Si je l\'avais, je pourrais, avec l\'aide du Cercle terrestre, faire quelque chose pour les arrêter !', },
    {'Apportez le Noyau de la Brasse à Je\'neu Sancrea, à l\'Avant-poste de Zoram\'gar, en Orneval.', },
  },
  [909] = {
    nil,
    {'Sur l\'élémentaire d\'eau vaincu, vous trouvez un étrange globe d\'eau. Vous avez la nette impression que l\'objet a absorbé l\'énergie de la créature. À l\'intérieur du globe, vous discernez une eau aux reflets malsains. Le globe lui-même semble insensible à toute forme d\'action physique.|n|nS\'il y a une personne qui puisse comprendre ce qu\'est cet objet, cela ne peut être que Je\'neu Sancrea du Cercle terrestre.', },
    {'Apportez le Globe d\'eau étrange à Je\'neu Sancrea, dans les Profondeurs de Brassenoire.', },
  },
  [910] = {
    'Un tour sur les quais',
    {'J\'ai entendu parler des grands bateaux qui naviguent entre Cabestan et Baie-du-Butin ! C\'est génial de voyager sur l\'océan et de faire de grandes batailles navales. Peut-être que je serai un puissant marin de la Horde quand je serai grand ! Ouais !|n|nVous voulez bien m\'emmener voir les quais de Cabestan, s\'il vous plaît ? Je vous promets que je sauterai pas dans l\'eau et que je ne ferai pas de bêtise. Je veux juste voir les grands bateaux et sentir l\'eau salée de la mer ! Ouais !', },
    {'Emmenez votre protégé sur les quais de Cabestan, dans les Tarides.', },
  },
  [911] = {
    'L\'accès vers la frontière',
    {'Ils disent qu\'Orneval est la nouvelle frontière, et que le Rempart de Mor\'shan dans les Tarides est à sa porte. Ça doit être génial d\'être un pionnier, de trouver tout ce dont on a besoin dans la nature sauvage ! Ils disent que c\'est là que la Horde et l\'Alliance se battront le plus dans l\'avenir, et je veux y être, $N !|n|nVous voulez bien m\'emmener au Rempart de Mor\'shan pour que je puisse voir à quoi ressemble la frontière, s\'il vous plaît ? Je veux voir l\'endroit où la Horde chasse ces sales elfes de la nuit puants !', },
    {'Emmenez votre protégé au Rempart de Mor\'shan dans la région nord des Tarides, juste à l\'entrée d\'Orneval.', },
  },
  [912] = {
    'Le costume de trogg Brisepierre',
    nil,
    nil,
  },
  [913] = {
    'Le cri du faucon-tonnerre',
    {'Le faucon-tonnerre, $N, est une bête féroce. Il est temps pour vous d\'en affronter. Vous devez trouver où il rôde, puis m\'apporter ses ailes comme preuve de votre chasse fructueuse.|n|nParvenez-y, et l\'heure de notre séparation sonnera bientôt.', },
    {'Trouver et tuer un faucon-tonnerre, et rapporter ses ailes à Jorn Oeil-des-cieux, au Camp Taurajo.', },
  },
  [914] = {
    'Les druides du Croc',
    {'Les druides des cavernes des Lamentations, les druides du Croc, sont une aberration. Ils appartenaient à un ordre de druides nobles voulant soigner les Tarides, mais ils tentent maintenant de plier cette terre à leurs fantasmes.|n|nIls ont quatre chefs, et chacun possède une gemme de rêve. Même à présent, leurs visages me hantent ! Vous devez les tuer et m\'apporter les gemmes. Ces terres pourront peut-être ainsi connaître à nouveau la paix.|n|nAllez, $N. Vous les trouverez, tapis, au fond des cavernes des Lamentations.', },
    {'Apportez les Gemmes de Cobrahn, d\'Anacondra, de Pythas et de Serpentis à Nara Crin-Sauvage aux Pitons-du-Tonnerre.', },
  },
  [915] = {
    'Je veux une glaaaaace !',
    {'DE LA GLACE ! Oh, s\'il vous plaaaaîîîîîît, je peux avoir de la glace ?! La glace à la fraise est ma glace préférée, et la meilleure glace à la fraise du monde, c\'est celle d\'Aguilor & Dagharn ! C\'est ma glace préférée dans le monde entier !|n|nJ\'en ai mangé il y a longtemps aux courses des Salines, mais il paraît qu\'ils en vendent en ville ! S\'il vous plaît ? S\'il vous plaaaaîîîîîît ? Avec une deuxième boule sur le dessus ??!?!', },
    {'Allez chercher de la glace à la fraise pour votre protégé. Le gamin semble préférer la marque de glace Aguilor & Dagharn.', },
  },
  [916] = {
    'La corruption des Tissebois',
    nil,
    {'Tuez 12 Araignées tissebois.', },
  },
  [917] = {
    'Oeuf d\'araignée Tissebois',
    {'En fait, maintenant que j\'y pense, vous pouvez peut-être m\'aider davantage. Je voulais récupérer un œuf de Tissebois à l\'intérieur de la caverne, mais les araignées ne m\'ont pas laissé approcher. Si vous pouviez en trouver un et l\'apporter à Dirania, nous vous en serions très reconnaissants.', },
    {'Apportez un Œuf d\'araignée Tissebois à Dirania Brillargent, près d\'Aldrassil.', },
  },
  [918] = {
    'Les graines de sylvain',
    {'Les sylvains de Teldrassil sont des élémentaires de la Nature. D\'une certaine manière, ils reflètent l\'ordre naturel des plantes et des animaux sur notre grand arbre.|n|nAussi est-ce inquiétant de voir les sylvains devenir furieux, d\'autant plus que les choses sont censées s\'améliorer.|n|nJe veux vous aider à trouver la source de ce mal. J\'ai élaboré différentes méthodes pour alimenter les plantes et j\'aimerais les essayer sur des graines de sylvain. S\'il vous plaît, pouvez-vous en collecter sur les sylvains autour du lac Al\'Ameth et me les apporter ?', },
    {'Récoltez 6 Graines de sylvain.', },
  },
  [919] = {
    'Les pousses de sylvain',
    {'De petits sylvains poussent près des eaux du lac Al\'Ameth. J\'ai bien peur que nous ne puissions plus rien faire pour ces jeunes sujets. Nous devons les arracher avant qu\'ils ne grandissent trop et causent des problèmes.|n|nLorsque vous serez près du lac, arrachez les pousses de sylvains que vous verrez. Aidez-nous à garder une terre propre !', },
    {'Collectez 10 Pousses de sylvain.', },
  },
  [920] = {
    'Les appels de Tenaron',
    {'$N, n\'est-ce pas ? J\'ai entendu dire que Tenaron vous cherchait. Vous le trouverez à l\'endroit le plus haut d\'Aldrassil.|n|nIl se peut que nous vivions longtemps encore, mais ce serait mieux de ne pas le faire attendre trop longtemps.', },
    {'Parler à Tenaron Poignorage au sommet d\'Aldrassil à Sombrevallon.', },
  },
  [921] = {
    'Teldrassil : la couronne d\'Azeroth',
    nil,
    nil,
  },
  [922] = {
    'Rellian Vertecime',
    {'$N, pouvez-vous apporter l\'une des graines que vous avez trouvées à mon ami, Rellian Vertecime ? Il est druide au taudis d\'Aigue-vive, et la dernière fois que nous avons parlé, il m\'a révélé son intérêt concernant mes travaux sur les sylvains. Il avait quelques idées de son côté et il appréciera d\'avoir un spécimen de graine à étudier.|n|nMerci, $N. J\'espère qu\'un jour, vous verrez les fruits de mon labeur.|n|nVous trouverez le taudis d\'Aigue-vive le long de la route qui part de Dolanaar vers l\'ouest, sur le chemin de Darnassus.', },
    {'Apporter une Graine de sylvain à Rellian Vertecime au Taudis d\'Aigue-vive.', },
  },
  [923] = {
    'Les tumeurs moussues',
    nil,
    nil,
  },
  [924] = {
    'La Graine démoniaque',
    {'La Graine démoniaque est un outil puissant au service de la Légion ardente. Elle repose dans une caverne du pic de Brume-funeste, au-dessus d\'un diabolique autel de feu.|n|nJ\'ai préparé des Pierres de puissance qui, lorsqu\'elles seront placées près de la graine, couperont sa connexion avec la Légion.|n|nPrenez une pierre sur la table et portez-la à l\'autel de feu au sommet du pic de Brume-funeste. Voyagez à l\'ouest, puis au nord lorsque la route se divise. Le pic sera sur votre gauche. L\'escalade la plus sûre s\'effectue par la face nord.|n|nEt faites vite, le pouvoir de la pierre faiblit avec le temps.', },
    {'Prendre une Pierre de puissance imparfaite. L\'apporter à l\'autel de feu avant que le pouvoir de la pierre n\'expire, puis revenir à Ak\'Zeloth.', },
  },
  [925] = {
    'Empreinte de sabot de Cairne',
    {'On dit que Cairne Sabot-de-Sang est l\'un des plus grands héros de la Horde de tous les temps. Quand je serai grand, je veux être un héros de la Horde, moi aussi !|n|nVous connaissez Cairne, $N ? Vous pouvez me faire une faveur, s\'il vous plaît ? Vous pouvez avoir son empreinte de sabot pour moi ? Je sais pas comment lui demander, et c\'est sans doute une personne bien trop occupée pour s\'occuper de quelqu\'un comme moi... Mais pas vous ! Vous êtes $Gun aventurier:une aventurière;, comme lui ! Je parie qu\'il vous donnerait facilement son empreinte de sabot !|n|nS\'il vous plaît ?', },
    {'Allez aux Pitons-du-Tonnerre pour tenter d\'obtenir l\'empreinte de sabot de Cairne pour votre protégé.', },
  },
  [926] = {
    'Pierre de puissance imparfaite',
    nil,
    nil,
  },
  [927] = {
    'Le cœur moussu',
    {'Le cœur de Noiremousse le Fétide est couvert d\'une mousse sombre et huileuse. En fait, ce qui permet d\'identifier ce cœur, c\'est sa pulsation, lente et rythmée.|n|nPeut-être que Denalan voudra voir ce cœur ?', },
    {'Apportez le Cœur moussu à Denalan au lac Al\'Ameth.', },
  },
  [928] = {
    'Teldrassil : transmettre la conscience',
    {'Bien que je puisse vous entretenir encore longtemps des puits de lune et de Teldrassil, je dois vous demander de partir. Corithras Ragelune vous attendra. J\'ai versé l\'eau de la flasque que vous m\'avez apportée dans ce récipient que vous devez lui remettre.|n|nCherchez Corithras. Vous le trouverez au puits de lune à Dolanaar. Suivez la route vers le sud à partir d\'Aldrassil en sortant de Sombrevallon, et continuez à suivre les pavés ronds lorsque la route se dirige vers l\'ouest.|n|nAttention, restez toujours sur la route, $N. Il y a de dangereuses bêtes dans les forêts ces derniers temps.', },
    {'Apportez le Récipient à moitié rempli à Corithras Ragelune à Dolanaar.', },
  },
  [929] = {
    'Teldrassil : le rejet des Aspects',
    nil,
    nil,
  },
  [930] = {
    'Le fruit luminescent',
    {'Au beau milieu des frondaisons de cette plante luminescente se balance un gros fruit rond.|n|nVous avez la certitude que Denalan voudra l\'étudier.', },
    {'Apportez le Fruit luminescent à Denalan au Lac Al\'Ameth.', },
  },
  [931] = {
    'Les racines chatoyantes',
    {'Les feuilles de la plante flamboient dans la lumière de la forêt, lui donnant une aura pulsante et sinueuse.|n|nVous pensez que Denalan en souhaiterait un spécimen.', },
    {'Apporter les Racines chatoyantes à Denalan. Il se trouve généralement au Lac Al\'Ameth, mais il se rend parfois au Taudis d\'Aigue-vive.', },
  },
  [932] = {
    'Haine folle',
    {'Je vous avertis, $N, cette affaire doit rester entre nous. Les satyres nous embarrassent déjà suffisamment, et celui-ci dépasse franchement les bornes.|n|nOn l\'appelle seigneur Melenas. Il réside dans la caverne de Gangreroche, juste au nord, où il a rassemblé de nombreux guerriers grells. Son cœur est aussi noir que la nuit, et il prépare quelque chose d\'abominable.|n|nVous devez le trouver à l\'intérieur de sa caverne et m\'apporter sa tête.', },
    {'Récupérez la Tête du Seigneur Melenas.', },
  },
  [933] = {
    'Teldrassil : l\'aube se lève',
    nil,
    nil,
  },
  [934] = {
    'Teldrassil : la couronne d\'Azeroth',
    {'Cependant, tout n\'était pas parfait sur Teldrassil. Les plans soigneusement conçus de Forteramure pour le nouvel Arbre-Monde s\'étaient déroulés comme il l\'avait espéré. Mais il y eut un petit problème, un problème sans doute à l\'origine des nombreuses difficultés rencontrées sur Teldrassil.|n|n. Mais je ne vais pas m\'étendre maintenant sur ce sujet. Vous devez vous rendre au dernier puits de lune, au nord-ouest, dans la clairière de l\'Oracle. Sous les branches de l\'arbre-oracle se trouve le premier et le plus puissant de nos puits. Remplissez une flasque de son eau et revenez me voir.', },
    {'Remplir la Flasque d\'améthyste et la rapporter à Corithras Ragelune à Dolanaar.', },
  },
  [935] = {
    'Les eaux de Teldrassil',
    nil,
    nil,
  },
  [936] = {
    'L\'aide à l\'archidruide Totem-runique',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps, si cela est possible.|n|nLe Cercle cénarien des Pitons-du-Tonnerre est très intéressé par des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans un projet crucial. Bien que je n\'en connaisse pas les détails, je peux vous dire que Hamuul Totem-runique lui-même mène ce projet.|n|nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la cime des Anciens aux Pitons-du-Tonnerre.', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique aux Pitons-du-Tonnerre.', },
  },
  [937] = {
    'La clairière enchantée',
    {'On m\'a envoyée ici avec un petit groupe de Sentinelles pour protéger l\'arbre-oracle des harpies qui ont construit leurs nids tout autour de la clairière. Nous essayons de les repousser petit à petit.|n|nLorsque l\'arbre-oracle a tenté d\'envoyer un messager à Darnassus avec un rapport, celui-ci a été attaqué par un groupe de harpies et tué.|n|nSi vous vous sentez suffisamment $Gpréparé:préparée; pour cette tâche, allez à leurs nids, tuez-les et rapportez-moi leurs ceintures en guise de preuve de vos exploits.', },
    {'Récupérez 6 Ceintures plumesang.', },
  },
  [938] = {
    'Brume',
    {'La fourrure de la tigresse à dents de sabre est d\'un gris particulier, tranchant avec les couleurs de la forêt environnante. Tandis qu\'elle repose là, vous remarquez qu\'elle est gravement blessée : de profondes lacérations déchirent son dos et son ventre.|n|nElle lève la tête et vous regarde, ses yeux bleus brillants d\'intelligence. Elle a l\'air de vouloir vous suivre.', },
    {'Escorter Brume vers la Sentinelle Arynia Eclairciel au puits de lune, près de l\'arbre-oracle.', },
  },
  [939] = {
    '[PÉRIMÉ]La flûte de Xavaric',
    {'Vous étudiez la simple flûte de bois que vous avez récupérée après avoir vaincu Xavaric.|n|nLe bois noueux semble solide mais les spirales et les motifs à sa surface semblent se mouvoir quand vous tournez l\'instrument entre vos mains. Soudain, vous êtes $Gpris:prise; d\'un sentiment d\'appréhension…|n|nVous vous ébrouez, $Gcertain:certaine; que votre esprit vous joue des tours.|n|nIl se pourrait que d\'autres satyres détiennent des indices relatifs à ce que vous avez trouvé. Apportez vos découvertes au druide Eridan Ventebleu qui vit dans la partie sud de Gangrebois.', },
    {'Apportez la Flûte de Xavaric et 5 échantillons de Lien maudit Jadefeu à Eridan Ventebleu, dans le sud de Gangrebois.', },
  },
  [940] = {
    nil,
    {'On entend murmurer la forêt qui loue vos grandes prouesses, $N. Les harpies une fois délogées de leurs nids, un grand calme s\'est répandu sur la forêt, et ses créatures se sentent à nouveau en sécurité. Je craignais d\'envoyer un autre messager à l\'archidruide, mais je sais que vous, vous parviendrez à lui remettre un message.|n|nApportez-lui ceci et sachez que la forêt veillera à votre sécurité le long du chemin menant à la forêt de pierre.', },
    {'Remettre le rapport de l\'arbre-oracle à l\'archidruide Fandral Forteramure à Darnassus.', },
  },
  [941] = {
    'Une belle plante',
    {'J\'ai débarrassé le cœur de cette ignoble mousse, mais il reste contaminé…|n|nEssayez de placer le cœur dans ce pot. Il est rempli d\'un terreau spécial qui pourrait le nettoyer et le guérir.', },
    {'Planter le Cœur corrompu dans le Pot de Denalan.', },
  },
  [942] = {
    'Les absences du prospecteur',
    {'Le fossile ressemble de manière frappante à un autre que j\'ai vu une fois à Forgefer. Un archéologue du nom de Outrepanse l\'avait apporté à notre conférence annuelle de la Ligue des explorateurs. Il croyait que le fossile détenait un pouvoir que l\'on aurait pu réveiller d\'une certaine façon.|n|nLa dernière fois que j\'ai entendu parler de lui, Outrepanse s\'était installé à la taverne de l\'Eau-profonde, au port de Menethil, attendant une escorte pour le mener à l\'Excavation de Whelgar. Recherchez-le et montrez-lui le fossile de Songerrance. Peut-être pourra-t-il révéler les secrets du passé.|n|nLe bateau pour le port de Menethil part de Hurlevent.', },
    {'Apporter le mystérieux Fossile à l\'Archéologue Outrepanse au port de Menethil.', },
  },
  [943] = {
    'Les absences du prospecteur',
    {'Le prospecteur Whelgar détient à présent le fossile original, en son site des Paluns. Quand j\'ai découvert la Pierre de Relu, j\'ai cru y voir la solution à l\'énigme du fossile.|n|nAlors que je taillais la route pour aller à la rencontre de Whelgar, j\'ai subi une attaque de raptors et la relique fut perdue. J\'ignore laquelle de ces créatures chamarrées a bien pu l\'avaler, mais si vous pouvez la retrouver, je peux libérer le pouvoir de ces artéfacts.|n|nApportez-moi donc la Pierre de Relu, et le fossile original que Whelgar possède.', },
    {'L\'archéologue Outrepanse au port de Menethil veut que vous lui apportiez la Pierre de Relu et le Fossile d\'Outrepanse.', },
  },
  [944] = {
    'Le Glaive du Maître',
    {'C\'est étrange que des nagas soient là, à Sombrivage. Mais... la présence du Marteau du crépuscule l\'est encore plus. Ce culte vénère de très anciens seigneurs de la terre. Des seigneurs vaincus il y a longtemps de cela.|n|nLe Glaive du maître, au sud, est un endroit où est tombé l\'un de ces anciens seigneurs.|n|nAllez-y et cherchez d\'autres sectateurs du Marteau du crépuscule.|n|nPrenez cette flasque de divination. Utilisez-la pour créer une coupe de divination après avoir enquêté au Glaive du maître. Puis parlez-moi par l\'intermédiaire de cette coupe.', },
    {'Trouvez des informations, puis utilisez la Flasque de divination pour créer une Coupe de divination. Utilisez la coupe pour parler à Onu.', },
  },
  [945] = {
    'L\'évasion de Therylune',
    {'Au secours !|n|nJe me promenais autour du Glaive du Maître, et ces infâmes sectateurs m\'ont entourée. Encore heureux que je sois douée pour me cacher !|n|nPouvez-vous m\'aider à m\'échapper ? Et j\'aurais aussi besoin de dire à ma sœur Therysil que je vais bien. Elle est en Orneval au sud, au sanctuaire d\'Aessina.', },
    {'Aider Therylune à s\'échapper, puis dire à Therysil au Sanctuaire d\'Aessina que sa sœur est saine et sauve.', },
  },
  [947] = {
    'La caverne aux champignons',
    {'Je prépare une potion qui nécessite des champignons rares, des champignons qui ne poussent que dans une certaine caverne. La caverne en question se trouve au-delà des Chutes de la Bondissante, à l\'est et légèrement au nord le long des montagnes.|n|nJ\'irais bien moi-même, mais le Bosquet des Anciens m\'a conseillé de me tenir à l\'écart de cet endroit. Nos vénérables alliés pressentent que cette caverne est l\'antre d\'une nouvelle créature maléfique, ici à Sombrivage.|n|nS\'il vous plaît, $N, ramassez ces champignons pour moi. Et pendant que vous y êtes, explorez la caverne pour confirmer le pressentiment des Anciens.', },
    {'Apporter 5 Pédoncules d\'Amanite et 1 Amanite phalloïde à Barithras Lunombrage à Auberdine.', },
  },
  [948] = {
    nil,
    {'Onu, un Ancien du savoir au Bosquet des Anciens, est au courant de votre voyage vers les Chutes de la Bondissante et souhaite vous parler. Le bosquet se trouve au sud, blotti près des montagnes.|n|nLes Anciens sont patients et sages, $N. Mais si Onu souhaite votre conseil à propos de ce que vous avez vu aux chutes, alors j\'ai peur que ce soit urgent.', },
    {'Parler à Onu au Bosquet des Anciens.', },
  },
  [949] = {
    'Le camp du Marteau du crépuscule',
    {'Nous ne connaissons pas le but du Marteau du crépuscule au Glaive du maître.|n|nFouillez leur camp au Glaive… Essayez de trouver quelque chose qui puisse nous indiquer leurs intentions.|n|nCar nous devons les connaître avant d\'établir un plan.', },
    {'Trouver un indice au Camp du Marteau du crépuscule au Glaive du maître.', },
  },
  [950] = {
    'Retourner voir Onu',
    {'Consulter le tome du Crépuscule rend fou. Au premier regard, le texte commence à flotter et danser ; images et enluminures s\'entremêlent pour créer des formes grotesques.|n|nVous arrivez tout juste à déchirer une page de ces gribouillages déments avant qu\'un vertige ne vous submerge.', },
    {'Apportez les Gribouillages déments à Onu.', },
  },
  [951] = {
    'Les Reliques de Mathystra',
    {'Le parchemin que vous avez découvert au Glaive du maître est une page provenant d\'un texte ancien… écrit par des elfes ! Il est souillé de la corruption du Marteau du crépuscule. Ainsi, le culte utilise l\'ancienne magie des elfes pour ramener ses vieux maîtres dans notre monde.|n|nVoyagez jusqu\'aux ruines de Mathystra au nord-est, et cherchez d\'anciennes reliques, dans l\'herbe et parmi les pierres brisées. En les étudiant, il se peut que nous comprenions comment le Marteau du crépuscule compte exploiter la magie des elfes.', },
    {'Apportez 6 Reliques de Mathystra à Onu, au Bosquet des Anciens.', },
  },
  [952] = {
    'Bosquet des Anciens',
    {'Si vous avez suffisamment de temps pour servir de $Gmessager:messagère; pour l\'arbre-oracle, je pourrais vous demander de remettre un message au bosquet des Anciens, à Sombrivage, au sud d\'Auberdine.|n|nVous aurez probablement à effectuer le voyage en hippogriffe, mais j\'ai foi en vos compétences. Apportez ceci à Onu, l\'Ancien du savoir. Il attend un mot de ma part, tout comme j\'attendais un mot de la clairière de l\'Oracle.', },
    {'Livrer le message de Fandral à Onu au Bosquet des Anciens, à Sombrivage, au sud d\'Auberdine.', },
  },
  [953] = {
    'La chute d\'Ameth\'Aran',
    {'Vous trouverez à l\'est les ruines d\'Ameth\'Aran. Elles sont habitées par les esprits sans repos des Bien-nés qui vivaient autrefois dans ces murs, quand les serviteurs d\'Azshara y pratiquaient librement leur puissante magie.|n|nOn m\'a envoyée pour explorer les ruines et trouver deux grandes tablettes, sur lesquels sont racontées les histoires d\'Ameth\'Aran et de sa chute. Alors que je lisais les runes, j\'ai été surprise par les esprits, et je me suis enfuie.|n|nS\'il vous plaît, si vous le pouvez, aventurez-vous dans les ruines et déchiffrez les tablettes pour moi.', },
    {'Étudier les tablettes qui parlent d\'Ameth\'Aran et de sa chute, puis retourner voir la Sentinelle Tysha Lamelune à Sombrivage.', },
  },
  [954] = {
    nil,
    {'Les ruines de Bashal\'Aran à l\'est sont infestées de serviteurs démoniaques. Les fées et les satyres qui ont élu domicile dans la région se nourrissent des énergies magiques du secteur, et leurs pouvoirs augmentent avec le temps passé sur place.|n|nMais malgré cela, j\'ai remarqué un sanctuaire dont ils ne s\'approchent jamais. A l\'ouest des ruines, au sommet d\'un petit promontoire, filtre une étrange aura bleue... Il doit y avoir une explication à la répugnance des démons.|n|nJ\'aimerais que vous enquêtiez à ce propos.', },
    {'Trouver la source de l\'aura bleue dans les Ruines de Bashal\'Aran.', },
  },
  [955] = {
    nil,
    {'Si j\'avais à raconter l\'histoire de ma vie, il ne fait pas de doute qu\'elle dépasserait les limites de votre patience. Disons que ma vie a été longue et douloureuse, et cette forme spectrale qui est la mienne à présent est peut-être le pire de tous ces tourments.|n|nJe suis retenu ici par les pouvoirs de la magie. Bien que mes mots puissent sonner faux, je vous assure que je vous serais reconnaissant au-delà de tout si vous pouviez m\'aider à identifier ce qui me retient prisonnier. Un sceau fait partie de ce dispositif, et en examinant les boucles d\'oreilles des fées et des grells, je pourrais en trouver la trace.', },
    {'Acquérir 8 Boucles d\'oreilles de grell pour Asterion à Bashal\'Aran.', },
  },
  [956] = {
    nil,
    {'Si les grells sont entrés en contact avec le sceau qui verrouille ma prison éternelle, je crois en connaître la cause. Il ne fait pas de doute que le sceau est en la possession du satyre qui les dirige.|n|nJe ressens fortement que cela doit être vrai, $N. L\'un des satyres le possède à présent. Si vous pouvez l\'obtenir, je serais si proche de pouvoir passer les barreaux de ma prison que les larmes me monteraient aux yeux.', },
    {'Obtenir l\'Ancien sceau de pierre de lune et l\'apporter à Asterion à Bashal\'Aran.', },
  },
  [957] = {
    nil,
    {'C\'est le savoir de l\'un des plus puissants Bien-nés qui a créé le sceau fermant ma prison. À Ameth\'Aran, dans les ruines au sud, jumelles de celles-ci, brûle une flamme antique, de couleur bleue. Dans cette flamme, ce sceau pourrait être détruit.|n|nSoyez $Gprudent:prudente; dans les ruines, $N.', },
    {'Détruire l\'Ancien sceau de pierre de lune à la flamme antique qui se trouve dans Ameth\'Aran, puis retourner voir Asterion à Bashal\'Aran.', },
  },
  [958] = {
    'Les outils des Bien-nés',
    {'$C. J\'aurais quelque chose à vous demander.|n|nConnaissez-vous les ruines d\'Ameth\'Aran ? Si ce n\'est pas le cas, vous les trouverez à l\'est de la route principale, à quelque distance au sud. Alors qu\'elles abritaient de nombreux Bien-nés puissants, elles ne sont plus à présent que l\'image de la destruction à laquelle leurs expériences ont abouti.|n|nLes Sentinelles disent que les esprits des Bien-nés sont toujours là, et qu\'ils manient toujours leurs instruments magiques. Nous devons nous emparer de ces reliques, afin de les détruire.', },
    {'Retrouver 7 Reliques de Bien-né pour Thundris Tissevent à Auberdine.', },
  },
  [959] = {
    'Fuite de porto aux docks',
    {'Oups !|n|nJ\'ai eu une petite mésaventure, comme vous pouvez le voir ! La cargaison du matin venant de Baie-du-Butin était énorme. Énorme je dirais ! J\'ai jamais vu autant de caisses. Bien, j\'essayais d\'expédier rapidement les choses alors j\'ai commencé à décharger un peu plus que je ne pouvais soutenir. C\'est à ce moment-là que tout s\'est cassé la gueule.|n|nAvant que je sache ce qu\'il se passait, j\'ai vu cette peste de Magglish le Dingue filer avec une bouteille de porto de quatre-vingt-dix-neuf ans d\'âge. Je l\'ai poursuivi jusqu\'aux cavernes des Lamentations. Pas question d\'y rentrer, quand même.|n|nPeut-être êtes-vous suffisamment $Gcourageux:courageuse; pour aller le retrouver ?', },
    {'Le grutier Bigglefuzz de Cabestan veut que vous repreniez la bouteille de Porto de 99 ans d\'âge à Magglish le Dingue, qui se cache dans les Cavernes des Lamentations.', },
  },
  [960] = {
    'Onu réfléchit',
    nil,
    nil,
  },
  [961] = {
    'Onu réfléchit',
    nil,
    nil,
  },
  [962] = {
    'Fleur de serpent',
    {'La Société royale des apothicaires, basée dans la grande ville de Fossoyeuse de Lordaeron, m\'a envoyée ici pour une mission très particulière, $N. Peut-être souhaitez-vous m\'aider, et ainsi aider la Dame noire, dans nos efforts pour faire progresser les Réprouvés.|n|nJ\'ai récemment étudié un spécimen rare de flore appelé fleur de serpent. Je crois qu\'en grande quantité, cette herbe a un bon potentiel.|n|nMalheureusement, elle ne pousse qu\'au plus profond des cavernes des Lamentations, un réseau de cavernes situé dans les Tarides.', },
    {'L\'Apothicaire Zamah des Pitons-du-Tonnerre veut que vous récoltiez 10 Fleurs de serpent.', },
  },
  [963] = {
    'Un amour éternel',
    {'À la suite des batailles au Puits d\'éternité, j\'ai appris qu\'Ameth\'Aran avait été détruit, et son peuple tué, y compris mon bel amour Anaya.|n|nJe n\'aurais jamais cru, des milliers d\'années plus tard, que des souvenirs d\'Anaya hanteraient toujours mes rêves. Frappé de stupeur, j\'ai erré dans les bois de Sombrivage, et j\'ai retrouvé les ruines d\'Ameth\'Aran... Là j\'ai vu l\'esprit hanté de ma bien-aimée.|n|nElle doit être libérée, mais je n\'ai pas le cœur de faire cela. Son esprit doit être détruit.', },
    {'Libérer l\'esprit d\'Anaya Coursaurore et rapporter son pendentif à Cerellean Blanchegriffe à Auberdine.', },
  },
  [964] = {
    'Fragments de squelette',
    {'La clé pour accéder à la Scholomance s\'appelle une Clé squelette. Elle doit être forgée à partir des restes d\'un squelette - de plusieurs en fait - et doit être renforcée des métaux les plus robustes dans un moule particulier. Enfin, un sceau de pouvoir provenant d\'une créature naturellement capable d\'ouvrir le portail de la Scholomance permettra à la clé d\'avoir la fonction désirée.|n|nMais commençons par le commencement, $N. Nous allons avoir besoin de fragments de squelette pour forger la clé. Les squelettes d\'Andorhal devraient nous les fournir, mais ceux en dehors des murs de la ville devraient pouvoir faire l\'affaire également.', },
    {'Apporter 15 Fragments de squelette à l\'Apothicaire Dithers à la Barricade, dans les Maleterres de l\'Ouest.', },
  },
  [965] = {
    'La Tour d\'Althalaxx',
    {'Salutations, jeune $R. Je m\'appelle Elissa Brise-Stellaire, et il est de mon devoir de protéger Auberdine de tout mal.|n|nÀ cette fin, j\'ai envoyé Balthule Frappelombre observer les événements étranges qui se produisent près de la Tour d\'Althalaxx au nord-est.|n|nIl aurait déjà dû revenir. J\'ai peur qu\'il ait rencontré un danger imprévu dans la forêt. J\'apprécierais beaucoup si vous pouviez le trouver et vous assurer qu\'il va bien.', },
    {'Trouver Balthule Frappelombre près de la Tour d\'Althalaxx à Sombrivage.', },
  },
  [966] = {
    'La Tour d\'Althalaxx',
    {'Un groupe de démonistes s\'est établi autour et à l\'intérieur de la tour. Je serais retourné à Auberdine pour rendre compte à Elissa plus tôt, mais j\'avais peur de rater quelque chose une fois parti.|n|nDelgren suspectait qu\'une telle compagnie puisse se rassembler à la tour, mais il n\'en savait pas la cause.|n|nQuelques morceaux de parchemins appartenant à ces démonistes ont atterri entre mes mains, mais j\'en ai besoin d\'autres pour compléter le puzzle. Je vous avertis cependant de ne pas vous aventurer dans la tour, les démonistes qui s\'y trouvent sont beaucoup trop puissants !', },
    {'Collecter 4 Parchemins passés pour Balthule Frappelombre près de la Tour d\'Althalaxx.', },
  },
  [967] = {
    'La Tour d\'Althalaxx',
    {'Mon maître, Delgren le Purificateur, est un paladin qui a gracieusement offert son assistance pour défendre nos forêts contre les démons et les morts-vivants. Il m\'a beaucoup appris sur la Lumière sacrée et sur l\'art de la bataille.|n|nDelgren doit être mis au courant des opérations du culte immédiatement.|n|nVous le trouverez loin au sud, au poste de Maestra dans la forêt d\'Orneval. Faites vite, j\'ai peur que la menace que représente la Rive noire n\'augmente d\'heure en heure.', },
    {'Remettre la Lettre de Balthule à Delgren le Purificateur dans la forêt d\'Orneval.', },
  },
  [968] = {
    'Les puissances d\'en bas',
    {'Bien qu\'affreusement usé et égratigné, le titre est encore lisible sur la couverture :|n|nLes puissances d\'en bas.|n|nÀ l\'intérieur du livre écorné se trouve une liste de noms imprononçables affublés d\'horribles titres, des méthodes de culte, des sacrifices conseillés... dont beaucoup incluent des créatures humanoïdes, vivantes.|n|nAu verso de la couverture, sont inscrits les mots suivants : « Runes et malédictions de Poigne-d\'os, la caverne Lugubre, Forgefer. Propriétaire : Gerrig Poigne-d\'os. »|n|nSi Poigne-d\'os vend de tels livres, peut-être qu\'il rachètera celui-ci.', },
    {'Apportez le Livre : Les puissances d\'en bas à Gerrig Poigne-d\'os, dans la Caverne Lugubre de Forgefer.', },
  },
  [969] = {
    '[PÉRIMÉ]Que la chance soit avec vous',
    {'Rien qu\'à vous regarder, je vois que vous voulez un charme de chance. Mau\'ari sait tout !|n|nLà-bas, dans le sud du Berceau, vous trouverez un canyon où les géants collectent des éclats de glace. Vous pouvez toujours prélever vous-mêmes des éclats sur le canyon. Ils ont une puissante qualité de réflexion.|n|nRapportez-moi des éclats cognegivre, et mon charme de chance sera à vous.', },
    {'Collecter 4 Éclats cognegivre pour la féticheuse Mau\'ari à Long-Guet.', },
  },
  [970] = {
    'La Tour d\'Althalaxx',
    {'La lettre de Balthule est désespérée. Ce culte de la Rive noire m\'irrite au plus haut point et doit être éradiqué. J\'ai eu affaire à quelques vermines de la Rive noire au nord-est d\'ici à Ordil\'Aran. L\'un d\'entre eux possède une gemme d\'âme, qui je crois détient le secret de la puissance de ce culte.|n|nApportez-la-moi, et je serai capable de déchiffrer les secrets qu\'elle contient.', },
    {'Trouver une Gemme d\'âme luminescente et la rapporter à Delgren le Purificateur au poste de Maestra.', },
  },
  [971] = {
    'La connaissance des profondeurs',
    {'J\'ai pour devoir de recueillir le savoir. Le savoir ancien. Le savoir puissant. Le savoir qui ouvre des portes et le savoir qui pourrait réveiller Ceux qui dorment, s\'il est utilisé à mauvais escient.|n|nIl court des rumeurs sur un livre ancien, le manuscrit de Lorgalis, dissimulé dans les profondeurs de Brassenoire, à l\'ouest. Cet endroit est l\'ancienne demeure de nos ancêtres, depuis longtemps disparus. Ils avaient réuni de grandes connaissances avant que leur cité ne tombe en ruine.|n|nFouillez les profondeurs de Brassenoire à la recherche du manuscrit. Faites-le, et je ne l\'oublierai pas. Pas même en ces temps apocalyptiques.', },
    {'Apportez le Manuscrit de Lorgalis à l\'Apprentie sentinelle Issara, au Camp de Brassenoire.', },
  },
  [972] = {
    'Sapta d\'eau',
    nil,
    nil,
  },
  [973] = {
    'La Tour d\'Althalaxx',
    {'Ilkrud Magthrull ? Oui, je le connais. Il s\'agit d\'un puissant démoniste orc qui s\'est établi au Sanctuaire de Scarfeu, un endroit très maléfique dans le sud-ouest d\'Orneval.|n|nIl n\'a pas été plus qu\'un simple désagrément jusqu\'à présent, et je n\'ai pas eu affaire à lui, mais il semble que le temps soit venu.', },
    {'Apporter le Tome d\'Ilkrud Magthrull à Delgren le Purificateur au Poste de Maestra.', },
  },
  [974] = {
    'À la recherche de la source',
    {'Les sources chaudes ne cesseront de m\'étonner ; d\'où vient cette chaleur ?|n|nVu à quel point les sources sont proches de la crête de la Fournaise, je me demande si le volcan n\'y serait pas pour quelque chose. J\'ai créé un thermomètre pour lire et enregistrer la température de différentes parties du volcan et trouver la plus chaude. La chaleur est exprimée en degrés Kraklenheit !|n|nVoici, prenez-le et faites des mesures de température sur la crête, dès que vous voyez un point chaud !', },
    {'Krakle, au cratère d\'Un\'Goro, vous demande de découvrir la zone la plus chaude de la crête de la Fournaise.|n|nQuand vous trouvez une zone de chaleur, cliquez avec le bouton droit de la souris sur le thermomètre afin de prendre la température. Continuez vos recherches jusqu\'à avoir trouvé la zone la plus chaude.', },
  },
  [975] = {
    '[PÉRIMÉ]Cache de Mau\'ari',
    {'Avant de vous donner ce charme, je vous expliquerai comment l\'utiliser.|n|nSi vous le portez sur vous, vous trouverez certains objets spéciaux sur les créatures que vous combattrez. Sans le charme, pas d\'objets spéciaux, vous voyez ?|n|nCes objets s\'appellent des E\'ko. Si vous trouvez n\'importe lequel de ces objets, apportez-le à la vieille Mau\'ari, qui saura vous aider.|n|nAttendez ici pendant que je prépare votre charme.', },
    {'Attendre un instant, puis reparler à la Féticheuse Mau\'ari pour recevoir le Charme de chance.', },
  },
  [976] = {
    'De l\'approvisionnement pour Auberdine',
    {'Delgren m\'a demandé d\'apporter un message et du ravitaillement à la Sentinelle Brise-Stellaire à Auberdine, mais je déteste partir seul. La forêt regorge de dangereux adversaires et je ne veux pas prendre le risque que le ravitaillement ou des informations capitales tombent entre de mauvaises mains.|n|nSi vous et quelques autres pouvez m\'accompagner en tant que gardes, je partirai tout de suite. Si vous nous protégez, aucun doute que ces marchandises arriveront à bon port.', },
    {'Parler à Delgren le Purificateur, au Poste de Maestra, après avoir escorté Feero à travers la Forêt d\'Orneval.', },
  },
  [977] = {
    '[PÉRIMÉ]Yéti ? Y es-tu ?',
    {'Maintenant que j\'ai ce dont j\'ai besoin pour construire les parties mécaniques mobiles, il ne me manque qu\'une seule chose. Deux choses, en fait. Deux cornes !|n|nLes patriarches et matriarches Chardon de glace sont ceux qui ont les plus grandes cornes. Ces yétis se trouvent dans les grottes, au sud-est. Il y en a un grand nombre là-bas, vous n\'aurez pas de problèmes à les trouver.|n|nRappelez-vous que je ne veux que les plus belles cornes, sans la moindre éraflure !', },
    {'Collecter 2 Cornes de yéti en parfait état pour Umi Sarcafroisse, à Long-Guet.', },
  },
  [978] = {
    'Les Indomptables lunaires',
    {'Les plumes d\'indomptables des Hinterlands contiennent des traces de magie. Toutefois, ces créatures ne semblent pas avoir de pouvoirs particuliers. La magie semble faire partie de leur essence.|n|nPendant mes études, j\'ai entendu qu\'une importante population d\'Indomptables résidait dans les terres enneigées du Berceau-de-l\'Hiver. Ces créatures auraient-elles les mêmes pouvoirs ? Aidez-moi à trouver les réponses à ces questions, $N. Allez au Berceau-de-l\'Hiver et collectez des plumes qui traînent au sol, puis revenez me voir.', },
    {'Récupérez 10 Plumes de Chouettard lunaire au Berceau-de-l\'Hiver, puis retournez voir Erelas Ambreciel, à Rut\'theran.', },
  },
  [979] = {
    'Trouver Ranshalla',
    {'Oui, oui, ces plumes semblent contenir le même enchantement que j\'ai remarqué précédemment… Bien que je ne sache pas vraiment ce que nous pourrions découvrir, je vous conjure de continuer à chercher des réponses, $N.|n|nL\'une de mes collègues a voyagé récemment au Berceau-de-l\'Hiver afin d\'y observer les indomptables, dans leur habitat naturel. Pourquoi ne pas essayer de la retrouver et voir ce qu\'elle a pu découvrir...', },
    {'Trouver Ranshalla dans l\'est du Berceau-de-l\'Hiver.', },
  },
  [980] = {
    'Les nouvelles sources',
    {'Il y a d\'autres sources chaudes dans un endroit appelé le Berceau-de-l\'Hiver, très loin au nord. Ce qui est étrange, c\'est qu\'il n\'y a pas de volcan à proximité ; intéressant n\'est-ce pas ?|n|nSi vous voulez en apprendre plus, vous devriez aller au Berceau-de-l\'Hiver et parler à une de mes amies. Son nom est Donova Antreneige, et elle réside aux environs de ces sources.|n|nEncore merci de m\'avoir aidé avec mon thermomètre et à plus tard !', },
    {'Voyager jusqu\'au Berceau-de-l\'Hiver et parler à Donova Antreneige.', },
  },
  [981] = {
    'La Tour d\'Althalaxx',
    {'Vous méritez bien une récompense pour tout ce que vous avez accompli. Retournez voir Delgren et dites-lui qu\'Athrikus Narassin gît à terre par vos soins et que le Culte de la Rive noire est vaincu et démantelé.', },
    {'Aller voir Delgren le Purificateur au Poste de Maestra.', },
  },
  [982] = {
    'Océan profond, mer immense',
    {'Au large de Sombrivage, plus au nord, il y a deux épaves de bateau : l\'Aube argentée et le Voile de brume. Il y a quelque temps, ces deux bateaux sont tombés sur ces maudits murlocs, alors qu\'ils faisaient voile à travers la vaste mer jusqu\'à Auberdine. Ils reposent maintenant au fond des eaux, comme autant de trophées au crédit de ces démons.|n|nLes deux capitaines n\'ont pas survécu et leurs journaux de bord et effets personnels sont toujours dans leurs coffrets. Je voudrais que vous les récupériez ; cela serait symboliquement très important pour tous les équipages de cette contrée.', },
    {'Récupérer le Coffret de l\'Aube argentée et le Coffret du Voile de brume, pour Gorbold Main-d\'acier, à Auberdine. Ces deux objets se trouvent à bord des épaves des navires respectifs, au nord du village.', },
  },
  [983] = {
    'Bigobox 827',
    {'Hé ! J\'ai besoin d\'aide pour ma dernière invention, la bigobox. Elle permet de parler aux gens à distance !|n|nVous en avez peut-être déjà vu, ce sont des boîtes avec un levier dessus. Le seul problème, c\'est qu\'il faut une maintenance permanente.|n|nElles ont toutes un problème différent, mais j\'ai eu une idée géniale. J\'ai placé chacune d\'elle près de la créature qui possède les éléments appropriés pour la réparer. En ce moment, la bigobox 827 est en panne. C\'est juste au sud d\'Auberdine, vraiment tout près. Il faut 6 pattes de clampants pour la réparer. Je vous payerai pour ça...', },
    {'Réunir 6 Pattes de clampants et les mettre dans la Bigobox 827.', },
  },
  [984] = {
    'Quelle est l\'ampleur de la menace ?',
    {'Certains de mes frères ont été sauvés de justesse d\'un furbolg corrompu à Teldrassil, et je me suis juré d\'arrêter ces atrocités avant que d\'autres ne soient blessés... ou pire.|n|nJ\'ai déjà vu des prémices de corruption à Sombrivage, mais il faut que je cherche d\'autres signes ailleurs. Je pense qu\'il serait logique de poursuivre les investigations auprès des furbolgs. Pourriez-vous trouver un de leurs camps et me dire s\'il y a des signes de corruption ?', },
    {'Trouver un camp de furbolgs corrompus à Sombrivage et retourner voir Terenthis dans Auberdine.', },
  },
  [985] = {
    'Quelle est l\'ampleur de la menace ?',
    {'Vous avez déjà prouvé vos qualités dans le domaine de la reconnaissance, $N. Avez-vous aussi les qualités nécessaires pour affronter l\'adversaire ?|n|nLes aventuriers ne préfèrent pas tous le combat direct à l\'art de la ruse et de l\'évasion.|n|nSi vous pensez être à la hauteur de la tâche, sachez que la plus grande menace pour notre peuple est aujourd\'hui le camp furbolg au sud d\'Auberdine. Vous y trouverez des furbolgs de la tribu Noirbois. Tuez 8 Guides et 5 Messagers du vent et revenez me voir.', },
    {'Tuer 8 Guides et 5 Messagers du vent Noirbois puis retourner voir Terenthis à Auberdine.', },
  },
  [986] = {
    'Un maître perdu',
    {'$N, votre habileté m\'a déjà été utile. Puis-je à nouveau vous demander d\'aider Griffe-sinistre et son maître Volcor ? Je vais vous fabriquer une cape magique qui vous permettra de vous déplacer librement au milieu des créatures de Sombrivage pendant que vous le chercherez.|n|nPour faire cette cape, j\'ai besoin de cinq belles peaux de géniteur ou de matriarche traquelune. Vous trouverez ces tigres au sud de la Sinueuse ou beaucoup plus au sud, non loin d\'Orneval.', },
    {'Trouver 5 Belles peaux de traquelune et les apporter à Terenthis, à Auberdine.', },
  },
  [988] = {
    nil,
    {'J\'ai remarqué la cape que vous portez, $N. Si vous acceptez de la sacrifier, je peux utiliser sa magie pour m\'échapper. Le problème, c\'est que vous, vous resterez ici dans la caverne.|n|nPourrez-vous vous débrouiller pour sortir si nous choisissons cette solution ?|n|nJe peux vous assurer que Terenthis vous récompensera si vous faites le choix de m\'aider.|n|nC\'est à vous de trancher, mais j\'ai vraiment besoin de votre aide.', },
    {'Parlez à Volcor.', },
  },
  [989] = {
    nil,
    {'Si nous décidons de nous battre pour sortir, le plan est simple : nous tracerons notre route en tuant tous les furbolgs qui seront sur notre chemin... Ou tout ce qui voudrait essayer de nous arrêter.|n|nJ\'espère qu\'il y a un autre moyen, mais tôt ou tard il faudra affronter les furbolgs. Autant le faire nous-mêmes, nous serons sûrs que le travail a été fait.|n|nPrenez le temps de préparer vos armes ou vos enchantements, puis revenez me voir.', },
    {'Parlez à Volcor.', },
  },
  [990] = {
    'Voyage vers Orneval',
    {'$N, ma maîtresse, Raene Mène-loup, vous attend à la cité d\'Astranaar dans Orneval. Peut-être que grâce à vous, nous pourrons réduire la corruption qui y règne.|n|nEn partant d\'ici, vous devez prendre plein sud en restant près de la route ; vous trouverez sans problème votre chemin en suivant cette direction.', },
    {'Trouvez Raene Mène-loup dans Orneval.', },
  },
  [991] = {
    'Recherche Teronis désespérément',
    {'L\'une de mes amies d\'Astranaar, Raene Mène-loup, m\'a demandé d\'envoyer un éclaireur à l\'ouest du lac Falathim. Il y a des jours maintenant que Teronis est parti, juste avant que la Horde n\'attaque.|n|nIl cherchait un objet qui pourrait retarder les attaques des furbolgs contre notre peuple : un bâtonnet créé par un sorcier diabolique, aujourd\'hui mort.|n|nAvant de partir, il a dit qu\'il cherchait pour ce bâtonnet une gemme qu\'il savait cachée dans un sanctuaire, sur une île du lac.|n|nMalheureusement, une force maléfique s\'est emparée des lieux. Je vous en prie, $N, retrouvez mon ami.', },
    {'Retrouvez Teronis au lac Falathim, en Orneval.', },
  },
  [992] = {
    'Étude des eaux de Gadgetzan',
    {'Nous avons un poste temporaire vacant de géomètre novice à la Compagnie des Eaux de Gadgetzan, si ça vous intéresse !|n|nComme les nomades s\'emparent de tous nos puits, nous devons exploiter tous les points d\'eau libres ! Il y en a dans le désert, mais seulement pour ceux qui les étudient en premier.|n|nPrenez cette fiole de sourcier et récoltez un échantillon d\'eau de la mare près du Guet de Tristesable. Juste sous le nez des trolls. Rapportez-moi la fiole pleine quand vous aurez fini !', },
    {'Utiliser la Fiole de sourcier vide à la mare près du Guet de Tristesable. Une fois l\'échantillon récolté, remettre la Fiole de sourcier pleine au grand géomètre Radiésthéflop à Gadgetzan.', },
  },
  [993] = {
    'Un maître perdu',
    {'La cape est terminée, $N. Nous devons trouver Volcor à présent. J\'espère seulement que nous sommes encore dans les temps.|n|nLa magie de la cape, une fois invoquée, ne durera pas longtemps. Cinq minutes, peut-être. Ce sera à vous de choisir quand l\'utiliser. Je suggérerais d\'attendre de trouver Griffe-sinistre.|n|nSi ce qu\'il m\'a dit est vrai, vous trouverez son maître dans une caverne au sud d\'ici. Griffe-sinistre vous attendra le long de la route. Faites-lui un signe de la main lorsque vous le verrez et il vous indiquera la direction de son maître.', },
    {'Trouver Volcor, à Sombrivage, et lui donner la Cape enchantée de traquelune.', },
  },
  [994] = {
    'Évasion par la force',
    {'Ça va, $N. Sortons de là. Nous nous fraierons un passage jusqu\'à la route ; Griffe-sinistre devrait encore y être. Une fois là-bas, nous pourrons nous séparer.|n|nTerenthis va vouloir que vous lui racontiez immédiatement ce qui s\'est passé, vous irez donc à Auberdine dès que nous serons sortis vivants d\'ici.', },
    {'Protéger Volcor jusqu\'à la route puis aller voir Terenthis à Auberdine.', },
  },
  [995] = {
    'Évasion par la ruse',
    {'D\'accord... si vous le voulez, nous nous échapperons d\'ici.|n|nRappelez vous, une fois que vous aurez quitté ce lieu, allez à Auberdine et rencontrez Terenthis. C\'est là que je vais me rendre aussi, et j\'y serai probablement avant vous.', },
    {'S\'échapper de la grotte des furbolgs et aller voir Terenthis à Auberdine.', },
  },
  [996] = {
    'Fleur-de-vent corrompue',
    nil,
    nil,
  },
  [997] = {
    'La terre de Denalan',
    {'Vous allez vers le sud ? Au lac Al\'Ameth ? Si c\'est le cas, j\'ai une tâche à vous confier...|n|nMon collègue Denalan campe le long du rivage oriental du lac, où il étudie la flore de Teldrassil. Il a demandé qu\'on lui envoie un paquet de terre rare de Darnassus, mais il y a eu du retard et le paquet vient seulement d\'arriver à Dolanaar.|n|nPouvez-vous le lui apporter ?', },
    {'Apportez le paquet de Terre rare à Denalan au lac Al\'Ameth.', },
  },
  [998] = {
    'Fleur-de-vent corrompue',
    nil,
    nil,
  },
  [999] = {
    'Quand les rêves tournent au cauchemar',
    nil,
    nil,
  },
  [1000] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Hamuul Totem-runique, sur la cime des Anciens des Pitons-du-Tonnerre, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1001] = {
    'Bigobox 411',
    {'Une petite voix crépite à l\'intérieur de la machine.|n|n« C\'est Crackboum ! La prochaine bigobox se trouve au nord d\'Auberdine, sur la plage !|n|nCette bigobox porte le numéro 411 et a besoin de 3 Yeux de batteur pour être réparée. Ils sont un peu au large de la côte ! Les Frappeurs de Sombrivage... *Hic*... Pardon...|n|nTout comme pour la dernière fois, quand vous donnerez les objets à la bigobox, elle vous crachera votre récompense. *Hic*... Quoi ? Non, je vais bien ! »', },
    {'Rassembler 3 Yeux de batteur de Sombrivage au fond de la mer, près de la Bigobox 411.', },
  },
  [1002] = {
    'Bigobox 323',
    {'La bigobox se tait un instant puis vous entendez Crackboum commencer à parler.|n|n« La-la bigobox suivante est la numéro 323. L\'est au nord d\'Auberdine mais... Où est la bière ? Hein ? Oh ! C\'est sur-sur la route alo-lors ça ne devrait pas-pas être dif-difficile de la trou-trouver près du pont. »|n|nCrackboum marmonne quelque chose d\'incohérent puis vous entendez un bruit de déglutition sonore.|n|n« Il f-f-faut des crocs de traquelune... 6 cro-crocs. »', },
    {'Trouver 6 Crocs de traquelune et les mettre dans la Bigobox 323.', },
  },
  [1003] = {
    'Bigobox 525',
    {'En plus du bruit de fond et des sons écœurants qui viennent de la machine, vous entendez la voix hésitante de Crackboum appeler.|n|n« Au-autre au s-sud en bas de l-la route. Ne devrait pa-pas trop dur à trouver... juste au b-bord... près d\'une clôture. Je p-pense que je l\'ai ca-cachée dans un beu-beu... buisson. Hé hé hé !... Ouais, la bigobox 525 a be-besoin de s-scalps vieillis de vieux ou-ours des chardons. Garçon, une autre ! Vi-vieillis... Hé hé hé !... »|n|nVous entendez déglutir tandis que la machine s\'arrête. Puis soudain, elle éructe.|n|n« 4 ! »', },
    {'Se procurer 4 Scalps vieillis sur de Vieux ours des chardons au sud d\'Auberdine et les placer dans la Bigobox 525.', },
  },
  [1004] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Hamuul Totem-runique, sur la cime des Anciens des Pitons-du-Tonnerre, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1005] = {
    'Ce qui se cache au-delà',
    nil,
    nil,
  },
  [1006] = {
    'Ce qui est au-delà',
    nil,
    nil,
  },
  [1007] = {
    'Les statuettes antiques',
    nil,
    {'Récupérez 10 Statuettes antiques.', },
  },
  [1008] = {
    'La grève de Zoram',
    {'Le mal se cache sur notre côte nord-ouest, à l\'endroit appelé grève de Zoram.|n|nC\'est là que se trouve la cité perdue de Zoram, détruite pendant la Fracture et submergée par les eaux. Cela fait une éternité que les elfes de la nuit l\'ont perdue. Perdue et presque oubliée.|n|nAujourd\'hui, les nagas y sont retournés et nous ne savons pas pourquoi. Mais la raison importe peu : nous devons tuer ces démons et les rejeter dans les profondeurs !|n|nRevenez me voir quand votre mission sera achevée.', },
    {'Apportez 20 Têtes d\'Irequeue à Shindrell Prestefeu, à Astranaar.', },
  },
  [1009] = {
    nil,
    {'J\'ai bien peur que les mystères que renferment les statuettes antiques ne restent une énigme tant que vous n\'en aurez pas trouvé la clé.|n|nCette clé est un anneau, l\'anneau de Zoram. Il appartenait autrefois aux dirigeants de cette cité, avant que les vagues de la Fracture ne l\'eussent submergée.|n|nPendant des années, l\'anneau fut introuvable, mais les nagas viennent de remettre la main dessus.|n|nLeur chef, Ruuzel, se trouve sur une île sur la côte nord de la grève de Zoram. Je vous en prie, $N, trouvez-moi cet anneau !', },
    {'Trouvez l\'Anneau de Zoram.', },
  },
  [1010] = {
    'Cheveu de Bathran',
    {'Une plante pousse dans les vieilles ruines du repaire de Bathran, par-delà la route de l\'est. On l\'appelle les cheveux de Bathran et elle est réputée guérir les maux de l\'esprit.|n|nÀ présent, la Horde la récolte pour servir ses desseins maléfiques.|n|nIl y a une enfant malade à Astranaar, et nous pensons qu\'il ne s\'agit pas simplement d\'une maladie physique. J\'ai promis à mon maître de trouver un remède, mais je n\'ai pas l\'âme d\'un guerrier.|n|nAccepteriez-vous d\'aller au repaire de Bathran et d\'y cueillir cette plante ?', },
    {'Cueillez 8 Cheveux de Bathran.', },
  },
  [1011] = {
    'Les maladies des Réprouvés',
    {'Les Réprouvés, le bras mort-vivant de la Horde, ont rampé jusqu\'en Orneval, et rôdent près de nos ruines et de nos refuges des saisons. Nous pensons que leur objectif est de répandre la maladie sur les terres des elfes de la nuit. Nous devons nous en assurer !|n|nLes Réprouvés ont un camp au sud d\'ici, près du refuge des saisons de Dor\'danil. Ils y conçoivent poisons et maladies et les placent dans des bouteilles. Frayez-vous un passage jusqu\'à ce camp et volez une de ces bouteilles pleines. Revenez alors me voir. J\'expérimenterai cette maladie et découvrirai à quelles fins elle a été conçue.', },
    {'Apporter une Bouteille des maladies à Kayneth Mortebrise au Chant des Forêts.', },
  },
  [1012] = {
    'Les druides fous',
    {'Les druides sont morts. Ils ont été tués par leurs chefs, que la Horde a rendus fous ! Cette maudite Horde qui empoisonne le cœur de la forêt ! Même d\'ici, je peux sentir la corruption, et je n\'ose m\'aventurer plus loin.|n|nLe lien qui m\'unit à Orneval et au cœur de la forêt est trop fort, mais vous… vous pourriez vous rendre au refuge des saisons, et faire le nécessaire. J\'y ai laissé quelques points de repère à votre intention.|n|nCela me fend le cœur, mais je dois vous demander de tuer les anciens grands chefs des druides, Taneel Sombrebois, Uthil Huchelune et Mavoris Éclairciel.', },
    {'Tuez les druides devenus fous : Taneel Sombrebois, Uthil Huchelune et Mavoris Éclairciel.', },
  },
  [1013] = {
    'Le Livre d\'Ur',
    {'$N, il y a un livre dans le donjon d\'Ombrecroc, le « Livre d\'Ur », qui ferait très bon effet dans ma collection. Ur était un grand mage de Dalaran avant l\'arrivée du Fléau, les études qu\'il a faites dans certains domaines ont beaucoup de valeur aux yeux de certains... parmi les Réprouvés.|n|nPénétrez dans le donjon d\'Ombrecroc et trouvez ce livre. Apportez-le-moi et je ferai part de votre action à notre Dame noire.', },
    {'Apportez le Livre d\'Ur au Gardien Bel\'dugur à l\'Apothicarium, à Fossoyeuse.', },
  },
  [1014] = {
    'Arugal doit mourir',
    {'Arugal se trouve toujours dans le donjon d\'Ombrecroc. Nous ne pouvons pas faire des Pins-Argentés une forteresse stratégique pour la Dame noire tant qu\'Arugal est vivant.|n|nJe vais me débrouiller pour que sa magie soit annihilée, $N. Mais je vous laisse le soin de faire en sorte qu\'Arugal rencontre la mort qu\'il sert si bien.|n|nAllez au donjon d\'Ombrecroc pour mettre fin une fois pour toutes aux charmes crasseux d\'Arugal. Apportez-moi la tête de ce vil sorcier !', },
    {'Tuer Arugal et apporter sa Tête à Dalar Tisselaube au Sépulcre.', },
  },
  [1015] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Fandral Forteramure,à Darnassus, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Fandral Forteramure, dans l\'Enclave cénarienne, à Darnassus. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1016] = {
    'Mystral gagnant',
    nil,
    {'Tuez 12 Élémentaires d\'eau souillés et Maréen.', },
  },
  [1017] = {
    'Mage invocateur',
    {'Il n\'y a qu\'un seul mage mort-vivant dans les Tarides capable de souiller autant d\'élémentaires d\'eau. C\'est aussi le seul suffisamment idiot pour le faire. Sarilus Souillemporte est probablement assis au sommet du pic de Brume-funeste, en train de se moquer de moi.|n|n$N, vous devez pénétrer en territoire ennemi et éliminer ce scélérat. J\'en ai assez de sa stupidité et nous devons lui montrer ce qui arrive à ceux qui s\'en prennent aux Sentinelles.|n|nTuez-le et apportez-moi sa tête. Mais soyez $Gprudent:prudente;, il se peut que la Horde vous surveille.', },
    {'Tuer Sarilus Souillemporte et apporter sa Tête à la Sentinelle Vélène Heurtétoile au Refuge de Vent-d\'Argent.', },
  },
  [1018] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Hamuul Totem-runique, sur la cime des Anciens des Pitons-du-Tonnerre, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1019] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Fandral Forteramure,à Darnassus, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Fandral Forteramure, dans l\'Enclave cénarienne, à Darnassus. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1020] = {
    'Jouvence d\'Orendil',
    {'$N, maintenant que la lumière bénie d\'Élune a imprégné cette décoction, je pense qu\'elle devrait guérir cette pauvre enfant. Je vous en prie, apportez-la à Astranaar, et donnez-la à son père, Pelturas Blanchelune.|n|nPour atteindre Astranaar, suivez la route qui mène au sud, puis à l\'est. Mais si vous souhaitez vous y rendre plus rapidement, adressez-vous à la sentinelle Avana.', },
    {'Apportez la Jouvence d\'Orendil à Pelturas Blanchelune à Astranaar, en Orneval.', },
  },
  [1021] = {
    'Vil satyre ! Dryades en danger !',
    {'Écoutez, je ne sais pas qui vous êtes, mais j\'ai besoin de votre aide. Mes sœurs sont allées reprendre la branche de Cénarius aux satyres. Elles ont dit qu\'elles seraient vite de retour, mais cela fait deux jours entiers qu\'elles sont parties !|n|n$N, vous devez les retrouver ! Elles cherchaient les ruines d\'un temple des elfes de la nuit à Xavian, au nord-ouest. Je ne sais que penser. Trouvez Anilia, c\'est elle qui menait les recherches.', },
    {'Trouvez Anialia à Xavian, en Orneval.', },
  },
  [1022] = {
    'Le val Hurlant',
    {'Bien que nous ayons dépensé beaucoup d\'énergie pour repousser les démons encore présents de Gangrebois jusqu\'au nord, nous n\'avons pas eu beaucoup de succès. Nous avons pu éviter toute présence démoniaque en Orneval.|n|nAu nord, près de la frontière de Gangrebois, de mystérieux hommes-loups ont investi le sanctuaire en ruine de Mel\'Thandris. Leurs cris sont si terrifiants qu\'on a surnommé ce secteur le val Hurlant. Le « Tome de Mel\'Thandris » qui est gardé dans le sanctuaire peut faire la lumière sur la raison de la venue de ces hommes-loups.', },
    {'Allez au Val Hurlant et étudiez le Tome de Mel\'Thandris, puis retournez voir la Sentinelle Melyria Ombregivre au Chant des forêts.', },
  },
  [1023] = {
    'L\'aventurier de la gemme perdue',
    nil,
    {'Trouvez la Gemme luminescente.', },
  },
  [1024] = {
    'La nymphe de ces bois',
    {'Ah, vous voilà, $N. J\'ai lu avec attention les notes de Teronis, et il semble que la prochaine étape de votre mission soit de trouver les autres morceaux du bâtonnet de Dartol.|n|nSi j\'étais vous, je commencerais par suivre le chemin à l\'est qui mène à la tour de Raynebois.|n|nLà se trouve une dryade nommée Shael\'dryn qui saura vous guider.|n|nPrenez la gemme avec vous : Shael\'dryn en aura besoin si elle doit vous aider à réparer le bâtonnet.', },
    nil,
  },
  [1025] = {
    'Une défense agressive',
    {'Avant que vous n\'alliez au Puits de lune, j\'ai une autre tâche à vous confier pour aider les habitants d\'Orneval, si ça vous dit de tester vos compétences.|n|nLe long de la route qui commence à l\'est, avant le fleuve Falfarren, les furbolgs ont attaqué des voyageurs. Leurs esprits tordus se nourrissent de la peur qu\'ils causent et seul le sang des innocents les rassasie.|n|nAidez les Sentinelles à protéger nos terres en rendant à ces monstres la monnaie de leur pièce.|n|nJe crois que leurs camps sont au sud de la route... Faites preuve de prudence.', },
    {'Tuez 1 Protecteur, 2 Ursas, 10 Totémiques et 12 Guerriers de la tribu Vile-sylve, puis retournez voir Raene Mène-loup, à Astranaar.', },
  },
  [1026] = {
    'Ô, ma chère cassette !',
    {'Je regrette que vous n\'ayez pas de meilleures nouvelles.|n|nRaene a raison, je sais ce qu\'avait créé Dartol et je connais les tréants de la région. Du moins, je les connaissais. Désormais, ils sont corrompus et leur nature a changé.|n|nVotre mission est de rapporter le morceau suivant du bâtonnet, mais vous devez d\'abord trouver la clé qui ouvre le coffre le contenant.|n|nLa clé en bois est sur l\'un des tréants au nord-est, près de Gangrebois. Une fois que vous l\'aurez, cherchez une petite clairière en passant par le passage couvert, dans la vallée. Le coffre devrait être caché par-là.', },
    {'Trouvez la Clé en bois et utilisez-la pour obtenir la Hampe en fer du Bâtonnet de Dartol.', },
  },
  [1027] = {
    'Faire le mort',
    {'Les druides de la Griffe possèdent le dernier morceau du bâtonnet. J\'ai demandé à leur chef, Oso Roncepatte, de me le donner, mais ses gardiens et lui m\'ont presque tuée ! Apparemment, ils ont aussi été infectés par la corruption de la Horde qui empoisonne le cœur de la forêt.|n|nMais je sais comment vous pourriez vous introduire dans la grotte d\'Oso et prendre le pommeau.|n|nDepuis toujours, je suis douée pour faire la morte. C\'est très efficace contre les ours ! Je peux vous montrer ! Allez à l\'est jusqu\'au creux Ombragé, et s\'ils essaient de vous attraper, utilisez ma technique.', },
    {'Trouvez le dernier morceau du Bâtonnet de Dartol, le Pommeau en fer.', },
  },
  [1028] = {
    'Recherche Teronis désespérément',
    {'Le bâtonnet est terminé, $N. Le réparer, c\'était facile... Ce qui va nous donner plus de mal, c\'est d\'atteindre l\'Autel qui a le pouvoir de le recharger.|n|nAvec de la concentration et des efforts, cela ne devrait pas être trop dur pour quelqu\'un comme vous, qui a déjà tant accompli.|n|nPartez vers le sud-est, il y a très peu de chemins, et ne perdez pas le nord de vue – et faites preuve de prudence. L\'autel est caché dans les montagnes qui entourent cette prairie.|n|nUne fois arrivé, placez le bâtonnet sur l\'autel... Le reste relève de la magie.', },
    {'Trouver l\'Autel caché et recharger le Bâtonnet de Dartol.', },
  },
  [1029] = {
    'Retourner voir Raene',
    {'Je vous suggère d\'aller trouver Raene pour lui dire que le bâtonnet est réparé. Je suis certaine qu\'elle saura vous dire quelle est la prochaine étape de votre mission.|n|nSoyez $Gprudent:prudente;… Il émane de ce bâtonnet un pouvoir à la fois maléfique et bénéfique. J\'espère que vous savez ce que vous faites, Raene et vous.|n|nBonne chance, $N.', },
    {'Apportez le Bâtonnet de Dartol à Raene Mèneloup, à Astranaar.', },
  },
  [1030] = {
    'Le bâtonnet de Dartol',
    {'Je ne sais pas exactement ce que Teronis comptait faire ensuite, mais s\'il disait vrai au sujet du pouvoir du bâtonnet, alors il devrait vous permettre de prendre une autre forme, probablement celle d\'un furbolg.|n|nPeut-être qu\'il voulait utiliser ces pouvoirs pour les approcher, mais même les créatures non corrompues l\'auraient abattu s\'il avait manqué de prudence. Transformé par le bâtonnet, Dartol aurait pu parler à un furbolg non corrompu.|n|nVous devriez commencer par trouver Krolg. Sa hutte se trouve au sud-est du lac Mystral.', },
    nil,
  },
  [1031] = {
    'La branche de Cénarius',
    {'<Anilia pose ses mains sur vos épaules et vous attire vers elle. Haletante, elle indique l\'arche au nord, avant de fermer les yeux pour toujours.>|n|nIl l\'a prise... Geltharis...|n|n<Au fond de votre cœur, vous comprenez que le dernier souhait d\'Anilia est de voir la branche de Cénarius à nouveau entre les mains des dryades.>', },
    {'Récupérez la Branche de Cénarius.', },
  },
  [1032] = {
    'Mort aux satyres !',
    {'Je n\'arrive pas à croire qu\'Anilia ne soit plus là… Nous avions l\'habitude de jouer ensemble dans la forêt. Je me sens presque... triste.|n|nJe sais ce qui pourrait me remonter le moral. Massacrez les satyres qui m\'ont pris Anilia ! Rapportez-moi leurs cornes comme preuve de leur mort. En faisant cela, vous gagnerez mon éternelle gratitude.', },
    {'Rassembler 16 Cornes de satyre.', },
  },
  [1033] = {
    'Larme d\'Élune',
    {'J\'espérais que le remède d\'Orendil sauverait Relara, mais je crains qu\'il ne puisse que ralentir la progression de la maladie qui la terrasse. Nous devons trouver un traitement plus efficace ! Heureusement, Orendil m\'a parlé d\'un autre remède, au cas où le premier échouerait.|n|nLa larme d\'Élune est une variété de pierre qu\'on ne trouve qu\'en un seul endroit : les vestiges du lac Iris, détruit par l\'éruption du Pic-Tonnerre, au nord-est d\'Astranaar. Orendil a dit que cette pierre dissiperait toute corruption.|n|nJe vous en prie, $N, apportez-moi la larme d\'Élune et priez pour qu\'elle guérisse mon enfant !', },
    {'Trouvez une Larme d\'Élune.', },
  },
  [1034] = {
    'Les ruines de Chimétoile',
    {'La larme d\'Élune a un peu amélioré l\'état de ma fille. Ses cauchemars ont diminué et je remercie la déesse pour sa bénédiction. Mais... la fièvre n\'a pas baissé.|n|nOrendil m\'a parlé d\'une poussière dépolie que l\'on trouve dans les ruines de Chimétoile. Peut-être qu\'elle diminuerait la fièvre de Relara. Trouvez un peu de cette poussière, et rapportez-la-moi, je vous en prie.|n|nLes ruines de Chimétoile se trouvent au sud, $N. Puisse Élune vous faire revenir rapidement !', },
    {'Rapporter 5 Poignées de Poussière d\'étoile à Pelturas Blanchelune à Astranaar.', },
  },
  [1035] = {
    'Le lac Tombeciel',
    {'La fièvre de Relara est tombée, mais elle est toujours très faible. Je ne crois pas que sa force reviendra avec le temps. Il va falloir le pouvoir d\'une pierre de lune.|n|nNous avions l\'habitude d\'en ramasser au lac Tombeciel au sud-est... jusqu\'à ce que les Sombretaillis s\'y installent.|n|nLeur chef, un oracle, a ramassé toutes les pierres tombées de la lune et les conserve. Vous devez maintenant lui reprendre une pierre de lune.|n|nMais pour ça, je crains que vous ne soyez dans l\'obligation de le tuer.', },
    {'Reprendre une Pierre de lune tombée à l\'Oracle Sombretaillis puis l\'apporter à Pelturas Blanchelune à Astranaar.', },
  },
  [1036] = {
    'En avant toutes, jeune mariole !',
    {'$N... Oui, j\'ai entendu parler de vous ; vous n\'êtes pas l\'$Gami:amie; de Baie-du-Butin, exactement comme nous, les boucaniers de la Voile sanglante. L\'amiral Firallon recherche des volontaires vigoureux et enthousiastes comme vous pour une mission spéciale.|n|nSi cela vous intéresse, trouvez la Voile cramoisie et parlez avec l\'amiral, sous le pont. Le navire est ancré plus à l\'est, au large de la côte Sauvage, à proximité du Courant et de La Chance de la demoiselle.', },
    {'Parlez à l\'amiral Firallon, à bord de la Voile cramoisie, au large de la côte de la vallée de Strangleronce.', },
  },
  [1037] = {
    'Velinde Chantétoile',
    {'Velinde Chantétoile m\'a précédée dans la forêt d\'Orneval. Au début, elle semblait contrôler la situation dans Gangrebois, mais peu à peu ses résultats ont faibli. Un beau jour, elle a tout simplement disparu.|n|nOn m\'a envoyée ici pour continuer sa mission. Cependant, j\'ai bien peur de ne rien savoir d\'elle. Peut-être que Thyn\'tel Tisselame, l\'un des commandants des Sentinelles, a du nouveau sur sa disparition, des détails que j\'ignorerais.|n|nElle comprendra certainement l\'importance de ce genre d\'informations.', },
    {'Parler à Thyn\'tel Tisselame à la Terrasse des guerriers de Darnassus.', },
  },
  [1038] = {
    'Les effets personnels de Velinde',
    {'Le « Tome de Mel\'Thandris » vous a montré cela ? Je suppose qu\'il n\'y a pas grand mal à vous permettre d\'examiner ses affaires. Cette clé ouvrira le coffre dans lequel nous avons stocké ses effets, dans le baraquement des Sentinelles. Elle a tenu un journal de sa mission, s\'il y a quoi que ce soit à apprendre, ce sera là-dedans.|n|nJe dois ajouter que les Sentinelles croient qu\'elle avait des raisons personnelles de partir et s\'attendent à ce qu\'elle revienne à tout moment. La prêtresse a fait beaucoup dans le passé pour gagner notre confiance.', },
    {'Fouiller le coffre de Velinde pour trouver son Journal et le rendre ensuite avec la clé à Thyn\'tel Tisselame à Darnassus.', },
  },
  [1039] = {
    'Le port des Tarides',
    {'Cabestan est le seul port des Tarides. L\'hypothèse la plus probable est que Velinde a trouvé à Cabestan un navire de commerce pour la conduire à la crique des Flots noirs, en Azeroth. Nous avons des relations limitées avec les gobelins qui gèrent le port, mais le maître des docks devrait avoir des informations sur les arrivées et les départs des passagers des bateaux.|n|nSuivez la route au sud-est d\'Orneval et vous arriverez dans les Tarides. Faites preuve de prudence, $N, les guerriers de la Horde patrouillent dans le secteur. Mais au port, vous serez en sûreté.', },
    {'Aller voir le Maître des docks Tournoupette à Cabestan.', },
  },
  [1040] = {
    'Passage à Baie-du-Butin',
    {'Oh oui ! Enfin trouvé. Z\'auriez dû me dire qu\'elle était passée il y a longtemps. Voyons.|n|nVelinde Chantétoile. Passage réservé à Baie-du-Butin sur le « Balbuzard noir ». Je n\'ai rien d\'autre là-dedans, donc je suppose qu\'elle est arrivée à bon port.|n|nJe ne peux pas faire grand-chose de plus pour vous. Elle a cependant demandé comment voyager par voie de terre de l\'autre côté et je lui ai indiqué Ruzzgot, un chef de caravane basé à Baie-du-Butin. Peut-être que cette Velinde a voyagé avec lui.|n|nMaintenant dégagez. Je n\'ai pas toute la journée à vous consacrer.', },
    {'Prendre un bateau pour Baie-du-Butin et aller voir le Caravanier Ruzzgot.', },
  },
  [1041] = {
    'La route de la caravane',
    {'S\'avère que j\'ai eu tort à propos de vous et que ça n\'arrive pas tous les jours.|n|nJe viens juste de me rappeler de cette Velinde que vous cherchez. Pas tous les jours qu\'une prêtresse des elfes de la nuit veut voyager dans une vieille et sale – mais parfaitement adaptée à vos transports de marchandises ! – caravane comme la mienne.|n|nNous avons pris ensemble le chemin vers le nord, elle se dirigeait vers Sombre-Comté. L\'employé là-bas tient à jour toutes sortes d\'informations. Pourrait savoir quelque chose d\'utile.|n|nFaites preuve de prudence dans la jungle, c\'est un endroit mortel même dans les bons jours.', },
    {'Aller voir le greffier Daltry à Sombre-Comté.', },
  },
  [1042] = {
    'La famille Carevin',
    {'Non, je n\'ai reçu aucun rapport concernant une Velinde Chantétoile résidant à Sombre-Comté... Quoique, si vous voulez mon avis, j\'aie du mal à imaginer une prêtresse elfe de la nuit prenant une chambre à l\'auberge, si vous voyez ce que je veux dire.|n|nPour ce qui est des hommes-loups que vous mentionnez, j\'en ai entendu parler. Justement l\'autre jour, Calor est rentré en ville avec une guirlande de leurs têtes. Il travaille avec la famille Carevin. Des chasseurs de démons, de morts-vivants et autres monstres. Allez voir Jonathan, c\'est le chef de famille.', },
    {'Aller voir Jonathan Carevin à Sombre-Comté.', },
  },
  [1043] = {
    'La faux d\'Élune',
    {'Votre histoire sonne juste... Je ne comprends pas bien vos motifs, mais si vous venez dans le bois de la Pénombre pour le débarrasser de quelques worgens, je ne vais plus chercher à comprendre.|n|nIl y a une mine au sud, que les worgens ont envahie... Ils sont apparus de nulle part, mais d\'après ce que nous savons, c\'est là qu\'on les a vus pour la première fois.|n|nFaites votre boulot, mais si vous découvrez quoi que ce soit d\'important, je vous demande de m\'en faire part. Nous acceptons l\'aide de tout le monde dans notre guerre contre le Mal.', },
    {'Cherchez les signes de la Faux d\'Élune puis retourner voir Jonathan Carevin à Sombre-Comté.', },
  },
  [1044] = {
    'Réponses aux questions',
    {'Nous maîtriserons le problème des worgens, n\'ayez aucune crainte là-dessus. Ce mal que votre amie a introduit dans nos bois sera contenu et je ne lui en veux pas pour ses actions. Des événements étranges surviennent en ce moment, $N et l\'obscurité ne connaît aucun répit.|n|nJe ne vous retiendrai pas plus longtemps. Je soupçonne que d\'autres ont entendu parler de ce que vous avez trouvé dans les mines du bois de la Pénombre.', },
    {'Retournez vers Thyn\'tel Tisselame à Darnassus.', },
  },
  [1045] = {
    'Un nouvel accessoire',
    {'Je suis certain que le sorcier Dartol, depuis longtemps disparu, avait l\'intention d\'utiliser son bâtonnet pour nous asservir et nous détruire, tout comme les Elfes de la nuit et les Orcs. Mais je pense que nous allons à présent détourner l\'utilisation de cet objet.|n|nRan Dent-rouge est le roi de tous les furbolgs d\'Orneval. Sa tribu, les Dent-rouge, est la plus puissante et vit recluse dans un camp juste à l\'est.|n|nTuez-les tous et ramenez-moi le crâne du chef. Nous verrons comment l\'utiliser au mieux.', },
    {'Obtenir le Crâne de Ran Dent-rouge et le Bâtonnet de Dartol.', },
  },
  [1046] = {
    'Par le pouvoir du bâtonnet ancestral',
    {'Prenez le bâtonnet, à présent, et servez-vous de son pouvoir pour parler à mon frère, Ota Wen.|n|nLes orcs l\'ont capturé et emprisonné avec d\'autres furbolgs, dans la grande cage située au nord du refuge de Vent-d\'Argent. Le bâtonnet vous permettra de persuader Ota et les autres furbolgs de se rebeller et d\'attaquer la Horde.|n|nVous serez ensuite libre d\'aller où bon vous semblera. Sachez simplement que vous vous êtes $Gmontré:montrée; digne de recevoir mon amitié.', },
    nil,
  },
  [1047] = {
    'La nouvelle frontière',
    {'Votre attention !|n|nLe Cercle cénarien cherche à recruter ceux qui se sentent capables pour une mission d\'exploration sur les nouveaux territoires de Kalimdor ! Des terres désolées, interdites, regorgeant de dangers, se trouvent à l\'ouest de Tanaris et de Gadgetzan, et le Cercle a besoin d\'honorables représentants pour agir en son nom.|n|nTous ceux et celles qui seraient intéressés devraient solliciter une audience auprès du Cercle cénarien. Parlez avec l\'archidruide Fandral Forteramure,à Darnassus, pour plus d\'informations !', },
    {'Parler à l\'Archidruide Fandral Forteramure, dans l\'Enclave cénarienne, à Darnassus. Évoquer l\'appel du Cercle cénarien concernant l\'exploration des frontières de Kalimdor.', },
  },
  [1048] = {
    'Au monastère Écarlate',
    {'Pendant que la Dame noire s\'occupe du problème urgent posé par l\'avance du roi-liche au nord, je me préoccupe de ce qui se passe par ici.|n|nAucun doute, les parasites humains qui se nomment la Croisade écarlate sont l\'épine à l\'intérieur même de nos terres. Les Clairières de Tirisfal grouillent littéralement de ces petites fourmis rouges.|n|nAllez au Monastère, $C, et faites disparaître la grande inquisitrice Blanchetête et ses lieutenants les plus importants.', },
    {'Tuer la grande inquisitrice Blanchetête, le commandant Mograine de la Croisade, le champion Hérode et le maître-chien Loksey, et retourner faire son rapport à Varimathras à Fossoyeuse.', },
  },
  [1049] = {
    'Compendium des Déchus',
    {'Le Cercle terrestre avait des intentions pures envers nos frères tourmentés. Mais qui connaît les motivations de ceux qui chuchotent aux oreilles du Conseil des Anciens ?|n|nLes Réprouvés auxquels nous nous sommes alliés ont un lourd passé de duperie. Notre pacte a été trop hâtif. Peut-être Cairne aurait-il été sage de tenir compte des avertissements d\'Orgrimmar.|n|nLe cœur du monastère Écarlate abrite le « Compendium des Déchus », gardé par des humains fanatiques et fous furieux. Ils tirent leur méthode de leur folie, mais leurs recherches pourraient s\'avérer utiles.', },
    {'Trouver le « Compendium des Déchus » au Monastère dans les Clairières de Tirisfal et retourner voir le Sage Recherche-la-Vérité aux Pitons-du-Tonnerre.', },
  },
  [1050] = {
    'Mythologie des titans',
    {'L\'avenir est inévitable ! Nous nous lançons vers lui comme les gouttes de pluie tombent dans la Grande mer.|n|nMais peut-être qu\'en étudiant le passé, nous pourrons savoir à quoi nous attendre pour mieux nous préparer.|n|nAvant que Lordaeron ne connaisse ces événements sinistres, il y avait un bastion de connaissance caché dans les Clairières de Tirisfal. La rumeur disait qu\'un livre appelé « la Mythologie des titans » avait été placé dans la bibliothèque du vieux Monastère.|n|nRetrouvez-le et peut-être qu\'ensemble nous pourrons découvrir les secrets du passé !', },
    {'Reprendre « la Mythologie des titans » au Monastère et le rapporter à la Bibliothécaire Mae Blêmepoussière à Forgefer.', },
  },
  [1051] = {
    'La vengeance de Vorrel',
    {'Bien que ma volonté soit intacte, je ne peux plus servir la Dame noire. Je sens que mes jours sur Azeroth vont prendre fin. Ma force de vie vole en éclats.|n|nC\'est l\'œuvre de l\'Interrogateur Vislar ! Il m\'a torturé pendant des semaines ! Il a pris mon anneau de mariage et l\'a donné à sa femme. Le monstre !|n|nVengeance… Je veux ma vengeance !|n|nCe pompeux imbécile s\'est vanté de sa précieuse femme, Nancy, qui vit le long du lac Lordamere. Traquez cette femme, assassinez-la et rendez mon anneau de mariage à ma femme, Monika, à Moulin-de-Tarren.|n|nExaucez mes dernières volontés…', },
    {'Rapporter l\'anneau de mariage de Vorrel Sengutz à Monica Sengutz à Moulin-de-Tarren.', },
  },
  [1052] = {
    'Sur le chemin écarlate',
    {'Nous, les membres de la Croisade écarlate, nous revendiquons des forteresses d\'Âtreval dans les Clairières de Tirisfal. Nous sommes assez fiers des bastions de nettoyage que nous avons installés partout dans Lordaeron.|n|nVous avez fait vos preuves contre les morts-vivants de Désolace. Mais la vraie menace de cette peste se trouve à Lordaeron.|n|nFaites route jusqu\'à la ville d\'Austrivage, dans les royaumes de l\'Est. Cherchez-y un croisé nommé Raleigh le Dévot. Remettez-lui cette lettre de recommandation portant mon sceau et il vous donnera une place d\'honneur dans notre monastère.', },
    {'Apporter la Lettre de recommandation du Frère Anton à Raleigh le Dévot à Austrivage.', },
  },
  [1053] = {
    'Au nom de la Lumière',
    {'J\'ai servi autrefois la Croisade écarlate avec honneur, fidélité et fierté. J\'ai cru que sa cause était noble : débarrasser Azeroth des morts-vivants.|n|nMais lorsque je suis allé au Monastère, dans les Clairières de Tirisfal, je me suis rendu compte combien les frères perdaient le sens des réalités. Aujourd\'hui, ils sont persuadés que tous ceux qui ne portent pas leur tabard sont des êtres tourmentés. Des hommes et des femmes innocents ont été torturés sous prétexte qu\'ils étaient tourmentés.|n|nLa Croisade écarlate doit être écrasée au nom de la Lumière. C\'est vous, $N, qui devez renverser ce régime fourvoyé.', },
    {'Tuer la Grande inquisitrice Blanchetête, Mograine le Commandant de la Croisade, Hérode le Champion de la Croisade et le Maître-chien Loksey, et retourner faire un rapport à Raleigh le Dévot à Austrivage.', },
  },
  [1054] = {
    'Diminution de la menace',
    {'Les furbolgs crins-de-chardon sont au nord d\'Astranaar. Mes éclaireurs m\'ont appris que leur nombre a très fortement augmenté ces derniers mois. S\'ils deviennent trop nombreux, ils pourraient bien trouver le courage d\'attaquer Astranaar...|n|nTuez-en autant que possible, mais surtout apportez-moi le crâne de leur chef pour me prouver que vous les avez arrêtés... au moins pour l\'instant.|n|nJe vais rester à Astranaar pour attendre de vos nouvelles. Qu\'Élune soit avec vous !', },
    {'Apporter le Crâne de Dal Griffe-de-sang à Raene Mène-loup à Astranaar.', },
  },
  [1055] = {
    'Recherche Teronis désespérément',
    {'Le Bâtonnet, maintenant achevé, repose entre vos mains. Shael\'dryn va vouloir apprendre votre réussite.', },
    {'Retourner voir Shael\'dryn au puits de lune.', },
  },
  [1056] = {
    'Voyage au pic des Serres-Rocheuses',
    {'Les esprits de la forêt m\'ont dit que vous aviez du courage et que vous étiez $Gprêt:prête; à voyager.|n|nAu sud, près du lac Mystral, il y a un tunnel nommé la Perce des Serres. Par ce tunnel, vous arriverez dans un secteur connu sous le nom de la Combe des Cisailles, dans les Serres-Rocheuses. Une fois là-bas, faites route vers le sud-ouest, devant le lac de la Combe et ensuite vers le nord, en prenant la montée jusqu\'au pic des Serres-Rocheuses.|n|nLe gardien Albagorm vous y attend. Faites ce qu\'il vous demande, $R.|n|nLe voyage sera périlleux.', },
    {'Voyager pour aller voir le Gardien Albagorm au pic des Serres-Rocheuses.', },
  },
  [1057] = {
    'À la reconquête du Val calciné',
    {'En tant que protecteur des esprits de la forêt, vous pouvez sans aucun doute deviner pourquoi je suis alarmé.|n|nVous avez voyagé à travers ces montagnes pour atteindre ce pic, et avez sûrement vu les changements terrifiants qu\'a subis la terre. La cupidité a mené à la destruction de ces collines sacrées.|n|nLe Val calciné, au sud, a été consumée par une avide armée mécanique. Pire encore, les Rougefuries qui ont empiété sur ce territoire nous en interdisent l\'accès et nous empêchent d\'y prospérer à nouveau.|n|nChassez ces affreuses harpies, $N !', },
    {'Le Gardien Albagorm du pic des Serres-Rocheuses veut que vous tuiez 7 Harpies, 7 Embusqués, 7 Tueuses et 7 Volplumes Rougefuries.', },
  },
  [1058] = {
    'Magie de la forêt de Jin\'Zil',
    {'Je suis surexcité !|n|nTrois petites cages pour trois petits elfes ! Mais qu\'allons-nous faire de nos trois calinouilleurs d\'arbre ? Eh bien ! Faisons-leur goûter à… comment appellent-ils cela ?… La magie de la forêt !|n|nJ\'aurais besoin de pas mal de Sève des Serres-Rocheuses. Prenez également des Moustaches crépusculaires à ces affreux félins. Cela nous amène aux Yeux de coursier : on ne peut jamais en avoir trop sous la main. Et surtout n\'oublions pas : une précieuse Ecaille de dragon-faë !|n|nHâtez-vous de rejoindre le pic des Serres-Rocheuses $N, que je puisse concocter une recette magique de la forêt.', },
    {'Le Féticheur Jin\'Zil à Malaka\'jin veut 5 doses de Sève des Serres-Rocheuses, 5 Moustaches crépusculaires, 30 Yeux de coursier et une Ecaille de dragon-faë.', },
  },
  [1059] = {
    'À la reconquête du Val calciné',
    {'Les Rougefuries ont été maîtrisées. Mais elles se regrouperont bientôt si nous n\'agissons pas.|n|nLoin au sud des Tarides se trouve une terre connue sous le nom de Mille pointes. Si vous voyagez à l\'ouest des Mille pointes jusqu\'à la lisière de la luxuriante forêt de Féralas, vous trouverez un druide nommé Falfindel Gardevoie.|n|nCe grand et sage druide est capable d\'invoquer de puissants esprits de la forêt qui pourraient aider à la reconquête du Val calciné.|n|nFaites-lui connaître notre requête ! Partez à sa recherche. Maintenant !', },
    {'Trouver Falfindel Gardevoie à la frontière entre les Mille pointes et Féralas.', },
  },
  [1060] = {
    '[PÉRIMÉ]Lettre à Jin\'Zil',
    {'Vous avez tellement fait pour moi, $N. Vous me portez vraiment chance et j\'aimerais que vous voyiez quelque chose.|n|nLes harpies ne viennent pas des environs des Tarides. Elles viennent d\'un endroit appelé les Serres-Rocheuses, loin au nord-ouest d\'ici. Bien qu\'il s\'agisse probablement d\'un endroit dangereux pour vous, j\'ai besoin que cette lettre soit remise à l\'un de mes vieux amis qui y réside, un féticheur du nom de Jin\'Zil.|n|nIl sera content d\'apprendre que Serena Plumesang est morte, et je crois que vous trouverez les Serres-Rocheuses intéressantes.', },
    {'Remettez la lettre de Darsok à Jin\'Zil dans sa caverne de Malaka\'Jin, dans les Serres-Rocheuses.', },
  },
  [1061] = {
    'Les esprits des Serres-Rocheuses',
    {'Les esprits des Serres-Rocheuses sont courroucés, car les gobelins et leurs serviteurs pillent et brûlent cette région. Ainsi la Terre a appelé à grands cris, et ceux qui sont à son écoute ont entendu.|n|nSeereth Bris-de-pierre, une prometteuse chamane de la Horde, a été envoyée dans les Serres-Rocheuses. Elle témoigne d\'une large déforestation perpétrée par les gobelins, et elle demande de l\'aide.|n|nRencontrez Seereth dans les Serres-Rocheuses. Pour la trouver, suivez la route à l\'ouest de la Croisée des Tarides. Elle s\'est établie près du val de Grandbois.', },
    {'Parler à Seereth Bris-de-pierre à la frontière des Serres-Rocheuses et des Tarides.', },
  },
  [1062] = {
    'Les invasions gobelines',
    {'La KapitalRisk, dirigée par des gobelins, s\'est installée dans les Serres-Rocheuses, où ils coupent les arbres et brûlent des secteurs entiers de la forêt. Les esprits de cette terre sont quasiment aveuglés par la douleur et par la haine. Nous devons l\'arrêter !|n|nPartez pour le nord-ouest, au-delà du Val de Grandbois et dans la combe des Cisailles. Vous trouverez les gobelins et leurs serviteurs à l\'œuvre. Montrez-leur que la Horde ne permettra pas l\'exploitation des Serres-Rocheuses. Prouvez-le avec les arguments qu\'ils comprennent le mieux...|n|nLa violence.', },
    {'Tuer 15 Déboiseurs de la KapitalRisk, puis retourner auprès de Seereth Bris-de-pierre à la frontière des Serres-Rocheuses et des Tarides.', },
  },
  [1063] = {
    '[PÉRIMÉ] L\'Ancienne',
    {'Pour vraiment soigner les esprits des Serres-Rocheuses, nous devons consulter les anciens esprits des taurens.|n|nLe seul chef dont j\'ai entendu parler est Magatha. Elle est très vieille et ses connaissances sont grandes. Si quelqu\'un peut canaliser une aide spirituelle des taurens, c\'est bien elle.|n|nMagatha réside aux Pitons-du-Tonnerre, la capitale des taurens, sur la cime des Anciens, la cité au nord-est du promontoire. Parlez à Magatha, et racontez-lui les périls encourus par les Serres-Rocheuses.', },
    {'Parler à Magatha aux Pitons-du-Tonnerre.', },
  },
  [1064] = {
    '[PÉRIMÉ]L\'aide des Réprouvés',
    {'Les taurens ont un lien avec cette terre, et apprendre la mauvaise santé des Serres-Rocheuses me peine. Mais j\'ai peur que pour soigner cette terre, nous devions d\'abord éradiquer la maladie qui l\'envahit.|n|nN\'est-ce pas heureux, alors, que les Réprouvés soient nos alliés ? Ils en savent beaucoup à propos des maladies. Je pense qu\'ils peuvent nous aider, et en nous aidant ils consolideront la confiance qui existe entre nos deux peuples.|n|nParlez à l\'Apothicaire Zamah. C\'est une érudite et un émissaire des Réprouvés. Vous la trouverez aux Bassins de la vision sous la cime des Esprits.', },
    {'Parler à l\'Apothicaire Zamah aux Bassins de la vision.', },
  },
  [1065] = {
    '[PÉRIMÉ] Un voyage vers Moulin-de-Tarren',
    {'Pour débarrasser les Serres-Rocheuses de la KapitalRisk, nous devons employer des mesures extrêmes. Extrêmes, mais sans effusion de sang.|n|nIl se peut que l\'un de mes confrères ait exactement l\'outil dont nous avons besoin. Il se nomme Lydon, et réside dans la ville de Moulin-de-Tarren, dans les contreforts de Hautebrande, dans la terre lointaine de Lordaeron.|n|nPour atteindre Hautebrande, voyagez par zeppelin vers notre capitale, Fossoyeuse. Puis allez au nord vers les Clairières de Tirisfal, au sud-ouest vers les Pins-Argentés, et enfin au sud vers Hautebrande.|n|nCherchez Lydon et donnez-lui cette note. Elle explique ce que nous attendons de lui.', },
    {'Apportez la Note de Zamah à l\'Apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [1066] = {
    '[PÉRIMÉ]Le sang des innocents',
    {'Je vais créer une toxine pour annihiler la violence de la KapitalRisk, et la rendre faible et docile. Cela devrait régler le problème de la Horde dans les Serres-Rocheuses, pas vrai ?|n|nMais pour créer la toxine, je vais avoir besoin de sang d\'innocent, un ingrédient difficile à trouver.|n|nHeureusement le Syndicat, un groupe de brigands humains, emploie des mages de l\'ombre... Et ces mages stockent du sang d\'innocent pour leurs propres desseins, peu recommandables.|n|nVous trouverez les mages de l\'ombre du Syndicat au donjon de Fort-de-Durn, au sud-est.', },
    {'Apporter 5 Fioles de Sang d\'innocent à l\'apothicaire Lydon à Moulin-de-Tarren.', },
  },
  [1067] = {
    '[PÉRIMÉ]Le retour aux Pitons-du-Tonnerre',
    {'Voici la toxine. Si vous l\'utilisez contre la KapitalRisk, cela devrait produire des effets intéressants, et peut-être même contagieux. Je dois dire que c\'est très excitant de voir mon travail appliqué sur le terrain !|n|nMais avant de l\'utiliser, apportez-la à l\'apothicaire Zamah. Elle doit mettre au point une méthode de diffusion particulière pour optimiser les effets de la toxine.', },
    {'Apporter la Toxine de Lydon à l\'Apothicaire Zamah aux Pitons-du-Tonnerre.', },
  },
  [1068] = {
    'Les machines à déchiqueter',
    {'Il existe une relation entre la magie spirituelle des chamans et la magie naturelle des druides. C\'est pourquoi nous, les chamans, nous pouvons entendre la complainte des esprits des Serres-Rocheuses. Beaucoup de leurs murmures m\'échappent, mais un message – une vision – est clair...|n|nJ\'ai eu la vision de deux machines à forme humaine, dans la Combe des cisailles, au nord-ouest du val de Grandbois, coupant les arbres à une vitesse incroyable. Ces bêtes de métal doivent être stoppées !|n|nDans ma vision, il y avait d\'étranges symboles gravés sur les machines :|n|nXT4 et XT9.', },
    {'Détruire les Déchiqueteurs XT4 et XT9, puis retourner voir Seereth Bris-de-pierre à la frontière entre les Serres-Rocheuses et les Tarides.', },
  },
  [1069] = {
    '[PÉRIMÉ]Omelette de mousses-profondes',
    {'L\'omelette aux œufs d\'araignée est la nouvelle mode culinaire à Baie-du-Butin ! Le problème c\'est qu\'il n\'y a pas le moindre œuf dans toute la ville.|n|nUne possibilité se profile !|n|nÀ la combe des Cisailles et dans le canyon de Sishir, dans les Serres-Rocheuses, au nord-ouest, vit l\'araignée des mousses profondes. Apportez-moi ses œufs et je vous payerai un sacré paquet !|n|nÀ la combe des Cisailles, vous trouverez les œufs groupés sous les arbres qui restent.|n|nEn ce qui concerne le canyon de Sishir... eh bien, si vous avez un estomac fragile, vous feriez bien de vous en tenir à la combe des Cisailles pour collecter les œufs...', },
    {'Apporter 15 Œufs de mousse-profonde à Mebok Mizzyrix à Cabestan.', },
  },
  [1070] = {
    'De garde dans les Serres-Rocheuses',
    {'Salutations, $N.|n|nVotre apparence semble indiquer que vous avez envie de parcourir le monde. Êtes-vous $Gallé:allée; dans les Serres-Rocheuses ? C\'est une région tourmentée par la KapitalRisk et par d\'autres ennemis des elfes de la nuit.|n|nRécemment, la sentinelle Mène-loup y a envoyé mon amie Kaela Ombrelance enquêter sur place, et je n\'ai toujours pas reçu de ses nouvelles. L\'inquiétude me ronge, d\'autant que l\'Alliance a envoyé un mage gnome avec elle... Mauvais présage, pour sûr.|n|nPourriez-vous la retrouver et revenir m\'informer ?', },
    {'Retrouver Kaela Ombrelance qui surveille la vallée à l\'entrée de la combe des Cisailles dans les Serres-Rocheuses.', },
  },
  [1071] = {
    'Du répit pour un gnome',
    {'Vous voyez, $N, je suis un membre de l\'Assemblée illuminée d\'arcanologie, d\'alchimie et de sciences d\'ingénierie, et c\'est mon but… non, il est de mon DEVOIR de montrer aux elfes de la nuit que l\'association de magie, de mixtures et de mécanique peut aider à sauver leurs forêts.|n|nMais c\'est un combat acharné, et les gobelins semblent se reproduire comme des lapins. Je n\'ai même pas eu le temps de construire mes dernières inventions !|n|nJ\'ai besoin de temps pour planifier et organiser. Mais vous pouvez m\'aider à retenir les gobelins à quai à la combe des Cisailles, à l\'est.', },
    {'Tuez 10 Déboiseurs de la KapitalRisk et 10 Défricheurs de la KapitalRisk, puis retournez voir Gaxim Larguerouille dans les Serres-Rocheuses.', },
  },
  [1072] = {
    'Un vieux collègue',
    {'L\'appareil auquel je pense est à ce jour ma version la plus avancée. Mais nous aurons besoin d\'une potion spéciale si nous voulons que ça marche. Je pense que nous pourrons avoir la bonne dose également puisque cette mission sera votre dernière.|n|nEt pour ça, il nous faut un puissant explosif : le Nitromirglyceronium.|n|nLa seule personne qui puisse faire du NG-5 est un de mes vieux amis : Lomac Rubangrenage. Cherchez-le à Brikabrok.|n|nDemandez-lui de nous faire du NG-5, je vais travailler au placement de mes appareils en attendant.', },
    {'Parler à Lomac Rubangrenage à Forgefer.', },
  },
  [1073] = {
    'Inaptitude + Produits chimiques = Rigolo',
    {'Ha ha ha ! Vous avez besoin de nitromirglyceronium pour empêcher les gobelins de détruire une forêt ?|n|nSavoir si vous connaissez Gaxim ou non ne m\'intéresse pas… Je vais vous donner le matos juste histoire de vous voir ou de les voir exploser en petits confettis.|n|nIl y a un problème quand même : je n\'en ai plus.|n|nMais je vais vous dire, vous m\'apportez les bonnes potions, et je vous en fais tout de suite.|n|nLe moins que vous puissiez faire c\'est de me montrer que vous avez des talents d\'alchimiste avant que je vous donne un échantillon de ma grande œuvre.', },
    {'Apporter 4 Potions de mana mineures et 2 Elixirs de Robustesse mineure à Lomac Rubangrenage à Forgefer.', },
  },
  [1074] = {
    'Inaptitude + Produits chimiques = Rigolo',
    {'Voilà, $Gétranger:étrangère;. Mais faites attention avec ça quand même… C\'est volatil.|n|nSi vous êtes vraiment $Gun ami:une amie; de Gaxim, alors transmettez-lui mes salutations. Si vous ne l\'êtes pas, alors amusez-vous bien à vous faire sauter la tronche.', },
    {'Apportez le Nitromirglyceronium à Gaxim Larguerouille, dans les Serres-Rocheuses.', },
  },
  [1075] = {
    'Un parchemin de Collin Mauren',
    {'OK, maintenant à propos de l\'explosion à distance… Oh ! Je n\'ai pas encore expliqué cette partie de mon plan ?|n|nBien, alors voici la version courte : avec un peu de magie, on peut déclencher l\'explosion sans avoir besoin de vous dans les parages. Je suis en train de peaufiner un système qui vous permettra d\'appuyer simplement sur un bouton pour que le NG-5 explose, à votre commandement.|n|nMais j\'ai besoin du sort d\'un ami à Hurlevent. Il s\'appelle Collin Mauren. Vous le trouverez dans le quartier des Mages, là-bas. C\'est un humain, alors ça sera difficile de le rater.', },
    {'Trouver Collin Mauren à Hurlevent.', },
  },
  [1076] = {
    'Des diables dans la marche de l\'Ouest',
    {'Ah ! Je crois que j\'ai compris. Un sort de contact… Je pense que c\'est l\'effet qu\'il recherche.|n|nJe vais devoir créer un parchemin pour y inscrire le sort. Pour cela, j\'ai besoin de débris de Diable de poussière.|n|nTandis que je rassemble le reste des ingrédients, pourquoi n\'iriez-vous pas dans la marche de l\'Ouest me trouver une de ces ignobles créatures ? Elles sont dangereuses, mais je suis sûr que vous n\'êtes plus à ça près si vous êtes volontaire pour participer à une expérience de Gaxim.|n|nJe serai là quand vous reviendrez.', },
    {'Apporter des Débris de diable de poussière à Collin Mauren à Hurlevent.', },
  },
  [1077] = {
    'Livraison spéciale pour Gaxim',
    {'Voilà, $N. Ça devrait faire l\'affaire.|n|nAssurez Gaxim de ma considération la prochaine fois que vous le verrez. J\'ai hâte d\'entendre la suite de cette aventure.|n|nAdieu.', },
    {'Apportez le Parchemin de contact à Gaxim Larguerouille dans les Serres-Rocheuses.', },
  },
  [1078] = {
    'Des retrouvailles pour Mauren',
    {'Les voyageurs m\'interrogent toujours au sujet des Serres-Rocheuses. C\'est une région populaire pour qui cherche l\'aventure, qu\'il s\'agisse de traquer des wyvernes, des élémentaires, ou du personnel de la KapitalRisk.|n|nDans le Val calciné, loin à l\'intérieur des montagnes, vivait autrefois une espèce de basilic dont les écailles, une fois plantées dans la poussière, produisaient un merveilleux réactif pour certains des sorts que j\'ai créés.|n|nSi ces basilics vivent toujours, j\'aimerais avoir quelques-unes de leurs écailles.|n|nPrenez votre temps, ce n\'est pas urgent, mais je paye bien.', },
    {'Apporter 8 Ecailles de cristal à Collin Mauren à Hurlevent.', },
  },
  [1079] = {
    'Opérations spéciales – Plan A',
    {'Ça y est, $N. Faites très attention ! Les dispositifs sont montés et prêts à fonctionner.|n|nPrenez ces explicatifs. Ils résument tout ce qu\'il faut savoir sur les détonateurs et les explosifs, et indiquent également où vous devez les placer.|n|nRappelez-vous, le succès de votre mission ne dépend pas de la somme de destruction que vous provoquerez. Le succès du plan A dépend du fait que vous rapportiez les plans d\'ingénierie de la KapitalRisk de l\'intérieur de la scierie au sud du lac de la Combe.', },
    {'Récupérer les Plans d\'ingénierie de la KapitalRisk dans la scierie de la Combe des Cisailles.', },
  },
  [1080] = {
    'Opérations spéciales – Plan B',
    {'Le plan B est identique au plan A, $N.|n|nNous faisons diversion et nous volons leurs précieuses notes.|n|nLe plus important est d\'obtenir leurs notes… Rappelez-vous de ça.|n|nLes explicatifs que je vous ai déjà fournis indiquent où placer les explosifs. Revenez simplement ici en vie et avec ces notes...', },
    {'Récupérer les Notes de la KapitalRisk dans la mine des Cisailles à l\'extrémité est de la Combe des Cisailles.', },
  },
  [1081] = {
    'Réception par Tyrande',
    {'$N, il est sûr que Tyrande Murmevent en personne voudrait vous remercier de prendre part à cette mission.|n|nIl n\'y paraît peut-être pas, mais votre aide pourrait renforcer notre position dans les Serres-Rocheuses.|n|nSi vous vous considérez comme notre $Gallié:alliée; face à ces atrocités, allez voir Tyrande au temple de la Lune de Darnassus.', },
    {'Trouver Tyrande Murmevent à Darnassus.', },
  },
  [1082] = {
    'Une mise à jour pour la Sentinelle Thenysil',
    {'$N, vous avez accompli un noble geste en nous offrant votre aide.|n|nLes Sentinelles d\'Orneval vous récompenseront si vous leur donnez des nouvelles de Gaxim et de moi. Dites-leur que nous sommes bien partis pour stopper la KapitalRisk et soigner la terre.|n|nTrouvez Tara Thenysil à Astranaar ; elle sera ravie de vous voir revenir avec de bonnes nouvelles.', },
    {'Retourner voir la Sentinelle Tara Thenysil en Orneval.', },
  },
  [1083] = {
    'Esprits enragés',
    {'Je ne sais pas exactement comment la KapitalRisk s\'est comportée vis-à-vis de la vallée, mais une chose est sûre : elle a été submergée par des créatures locales.|n|nSes gens ont mis le feu à la forêt et utilisé leurs engins de destruction pour ravager la vallée.|n|nMais dans leur ignorance ils ont libéré des esprits ardents et des élémentaires de flamme, de roche et de rage.|n|nLa Terre n\'a aucune chance de voir le sourire d\'Élune tant que ces créatures la fouleront librement.|n|nApportez-moi leurs Braises fumantes pour me montrer que vous avez réduit leur nombre.', },
    {'Apporter 8 Braises fumantes provenant de n\'importe quel élémentaire de feu du Val calciné à Kaela Ombrelance, dans les Serres-Rocheuses.', },
  },
  [1084] = {
    'Les Anciens blessés',
    {'Il me semble évident que les protecteurs de la vallée, les tréants, ont quelque chose à voir avec le retrait de la KapitalRisk. Malheureusement, même ceux qui étaient autrefois de grands gardiens sont aujourd\'hui corrompus.|n|nGaxim pense que leur corruption est d\'une certaine manière liée aux armes utilisées par les gobelins pendant le combat.|n|nJe lui ai dit que je collecterais un résidu sur un tréant blessé pour qu\'il l\'étudie et découvre l\'origine du mal.|n|nApportez-moi un morceau de shrapnel pour que le gnome puisse m\'en dire plus...', },
    {'Apporter un morceau de Shrapnel corrodé à Kaela Ombrelance, dans les Serres-Rocheuses.', },
  },
  [1085] = {
    'De garde dans les Serres-Rocheuses',
    {'La situation ici dans les Serres-Rocheuses est suffisamment grave pour qu\'une elfe de la nuit et un gnome travaillent ensemble.|n|nLa KapitalRisk a dévasté cette région et j\'ai passé la majeure partie de mon temps à mettre un terme à cette destruction.|n|nNe jugez pas Gaxim trop vite, il comprend la nécessité de notre travail commun.|n|nSi vous souhaitez nous aider, alors commencez par parler à Gaxim.|n|nJe suis désolée de ne pas encore pouvoir vous renvoyer à Tara avec de bonnes nouvelles. Bientôt peut-être…', },
    {'Parler à Gaxim dans les Serres-Rocheuses.', },
  },
  [1086] = {
    '[PÉRIMÉ]L\'aéroport de la machine volante',
    {'La toxine est prête. Tout ce qu\'il reste à faire est de la livrer. Vous devez vous en occuper, $N.|n|nLa KapitalRisk doit avoir un moyen d\'envoyer des messages et de petites cargaisons entre ses quartiers généraux et ses sites d\'opérations dans les Serres-Rocheuses. Il s\'agit probablement d\'un petit aéroport, pas suffisamment important pour un zeppelin, mais assez pour une machine volante. Cherchez dans les Serres-Rocheuses les secteurs sous contrôle de la KapitalRisk et trouvez cet aéroport, s\'il existe. Placez-y alors la toxine.|n|nPlacez-la, et courez !', },
    {'Apportez le Brouillard toxique à l\'aéroport de la KapitalRisk, puis retourner voir l\'Apothicaire Zamah.', },
  },
  [1087] = {
    'L\'héritage de Cénarius',
    {'Vous ne pouvez pas imaginer la haine que je ressens pour cette terre misérable. Au pic, les semblables de Cénarius et les druides kaldorei emploient leurs pouvoirs minables pour étouffer le flot de magie, même jusqu\'au sud de leurs possessions pathétiques... leurs forêts bien-aimées.|n|nJe voudrais retourner à Jaedenar et exulter dans le flot de magie, mais mon maître ne le permettra pas tant que mon travail ici ne sera pas achevé.|n|nIl ne fait aucun doute que vous aimez les elfes de la nuit et leurs alliés aussi peu que je les aime. Aidez-moi, et notre but commun pourra être atteint.', },
    {'Tuer 4 Fils de Cénarius, 4 Filles de Cénarius et 4 Botanistes cénariens pour Braelyn Brasemain, près de la Retraite de Roche-Soleil.', },
  },
  [1088] = {
    nil,
    {'Ils ont cru qu\'ils pourraient arrêter le flot de magie. Ils se sont trompés. Ils ont cru pouvoir cacher Ordanus, mais j\'aurai sa tête !|n|nLa magie m\'accorde la vision véritable. Oui… il est là. Un croisement… Au sommet d\'un grand arbre dans la forêt d\'Orneval. Un nom... Raynebois. L\'un des fils aînés du dieu de la Forêt. Ils l\'ont fait disparaître du pic avant que je puisse le trouver, mais son temps est compté.|n|nApportez-le-moi et je vous offrirai un puissant cadeau.', },
    {'Apporter la Tête d\'Ordanus à Braelyn Brasemain, près de la Retraite de Roche-Soleil.', },
  },
  [1089] = {
    'L\'Antre',
    {'Les druides ont construit l\'Antre des Serres dans le pic des Serres-Rocheuses. Ils y conservent de nombreux objets puissants.|n|nIls ont conçu un plan compliqué pour que ces derniers ne tombent pas entre de mauvaises mains.|n|nPar chance, j\'ai réussi à… extraire quelques informations de l\'un d\'entre eux.|n|nCachée dans une petite lanterne, à l\'entrée de l\'Antre, vous trouverez la Clé du gardien ; elle vous permettra d\'ouvrir des cachettes autour de l\'Antre. Les objets extraits de ces cachettes donnent accès au trésor, situé dans l\'un des secteurs centraux.', },
    {'Aller dans l\'Antre, sur le Pic des Serres-Rocheuses. En utilisant la Clé du gardien, obtenir les objets cachés des druides. Utiliser ces objets pour ouvrir le Trésor de l\'Antre des Serres.', },
  },
  [1090] = {
    'Les ordres de Gerenzo',
    {'Vous savez, avant j\'étais la seconde personne la plus importante ici sur ce site. Tout a changé quand Gerenzo est arrivé. Il a viré mon patron, Ziz Fizzik, et m\'a envoyé bosser dans les mines. Ziz m\'a dit de rester ici et de rassembler des renseignements. Son nouveau patron nous paiera bien si nous pouvons découvrir les plans de Gerenzo.|n|nMais bon, ce que je sais c\'est que Gerenzo a ordonné que des quantités importantes de ce minerai or-vert soient extraites. Je peux vous trouver un échantillon pour que vous l\'apportiez à Ziz, mais faites attention aux patrouilles le temps que j\'aille en chercher.', },
    {'Obtenir le minerai mystérieux de Piznik après qu\'il l\'aura extrait.', },
  },
  [1091] = {
    'Des nouvelles pour Kaela',
    {'$N, apportez ces notes à Kaela. Il est certain qu\'elle voudra en savoir plus à ce propos. Ou du moins ce sera le cas des Sentinelles.|n|nDites-lui à quel point notre victoire a été éclatante, et à quel point nous n\'aurions pu y parvenir sans l\'aide d\'un peu de magie.', },
    {'Apportez les Notes de la KapitalRisk à Kaela Ombrelance aux Serres-Rocheuses.', },
  },
  [1092] = {
    'Les ordres de Gerenzo',
    {'Je pense que je ferais mieux d\'envisager de ficher le camp d\'ici, aussi. Ça ne va pas prendre beaucoup de temps avant que la nouvelle de ce qui s\'est passé ici se répande au-dessus, et je suis sûr qu\'ils ne seraient pas ravis de me revoir.|n|nJe vais dégager d\'ici et aller voir Ziz. J\'espère qu\'il pourra me trouver du boulot !|n|nJe vais essayer de nettoyer ce bordel, mais vous devez apporter l\'échantillon de minerai à Ziz tout de suite. Il m\'a dit qu\'il établirait un camp quelque part du côté ouest de la Combe des Cisailles. Bonne chance.', },
    {'Remettre le Minerai non identifié à Ziz Fizzik dans les Serres-Rocheuses.', },
  },
  [1093] = {
    'Super-Découpeur 6000',
    {'C\'est terrible ce que la KapitalRisk a fait ici, hein ? Mais à quoi donc pensaient-ils ? Une compagnie de gobelins qui embauche un gnome !|n|nHeureusement pour moi, Krachevalve reconnaît un génie lorsqu\'il en voit un. M\'a embauché juste après que je me suis fait virer !|n|nIl me dit qu\'ils construisent une énorme machine pour découper le bois, et Sputt veut que je vole les plans pour lui. Malheureusement, Gerenzo – maudit gnome – veut ma peau... Peut-être que vous pourriez voler les plans pour moi ? Vous devriez les trouver sur l\'un de leurs opérateurs.', },
    {'Trouver le Plan du Super-Découpeur 6000 pour Ziz Fizzik dans les Serres-Rocheuses.', },
  },
  [1094] = {
    'D\'autres instructions',
    {'Cette enveloppe contient toutes les informations que j\'ai pu rassembler avant qu\'ils me flanquent à la porte : des documents internes de la KapitalRisk, quelques manuels, des trucs techniques… Et bien entendu, le plan du Super-Découpeur 6000.|n|nKrachevalve a élu résidence à Cabestan dans les Tarides. Vous ne devriez pas avoir trop de mal à le trouver, c\'est un type un peu vert.', },
    {'Remettre l\'Enveloppe scellée à Krachevalve à Cabestan, dans les Tarides.', },
  },
  [1095] = {
    '[PÉRIMÉ]D\'autres instructions',
    {'L\'embauche de ce gnome par la KapitalRisk a créé quelques remous à Terremine. Les princes marchands n\'approuvent pas que Razdunk fasse des affaires avec ce Gerenzo.|n|nRiddlevox m\'a demandé de m\'occuper du problème, et il est certain qu\'il a reçu, d\'un ou de plusieurs des princes marchands, les mêmes instructions. Bien sûr, le directeur ne me l\'a pas dit. Disons que j\'ai simplement une intuition.|n|nQuoi qu\'il en soit, nous devons faire en sorte de supprimer Gerenzo, et ce serait le test parfait de voir Fizzik s\'en occuper.', },
    {'Apportez les nouveaux ordres à Ziz Fizzik dans les Serres-Rocheuses.', },
  },
  [1096] = {
    'Gerenzo Siffleclef',
    {'J\'ai rencontré Gerenzo une fois, mais laissez-moi vous dire qu\'il n\'est pas très beau à voir. On dirait que sa chair est en train de pourrir, et il s\'est fait greffer du métal et des accessoires sur le corps. Il a remplacé certains membres naturels par des membres mécaniques.|n|nAu nord-est d\'ici, loin au-dessus du lac de la Combe, près de la roue hydraulique, Gerenzo surveille le site entier.|n|nJe ne pourrais pas monter là-haut, je ne survivrais pas aux combats. Sans parler de me charger de Gerenzo... Mais vous semblez être capable de réussir.|n|nSi vous le tuez pour moi, je ferai en sorte que ça en vaille le coup !', },
    {'Apporter le Bras mécanique de Gerenzo Siffleclef à Ziz Fizzik dans les Serres-Rocheuses.', },
  },
  [1097] = {
    'La quête d\'Elmore',
    {'Il y a un fabricant d\'armes à Hurlevent, un nain du nom de Grimand Elmore, qui nous a envoyé un mot disant qu\'il avait besoin d\'aide avec une livraison. Je crois qu\'il veut qu\'un paquet soit envoyé dans son pays d\'origine, dans le nord.|n|nVous avez des jambes robustes ! Si vous êtes $Gintéressé:intéressée; par un peu de marche à pied, alors parlez à Grimand. Nous pourrions vous utiliser ici, mais nous devons également entretenir nos bonnes relations avec les nains.|n|nVous trouverez Grimand Elmore au magasin d\'armes dans le quartier des Nains de Hurlevent, dans la partie nord-est de la ville.', },
    {'Parler à Grimand Elmore à Hurlevent.', },
  },
  [1098] = {
    'Des nécrotraqueurs à Ombrecroc',
    {'En préparation d\'un assaut sur Ombrecroc, deux nécrotraqueurs ont été envoyés au donjon pour réunir des renseignements. Plusieurs jours ont passé, et ils ne sont toujours pas revenus. Nous devons cependant prendre connaissance de leur rapport si nous voulons que notre attaque ait la moindre chance de réussir !|n|nAussi voici votre tâche, $N. Partez pour le donjon d\'Ombrecroc au sud et trouvez les nécrotraqueurs Adamant et Vincent. Trouvez-les, et s\'ils ont besoin d\'aide, aidez-les !|n|nCette mission est aussi dangereuse qu\'elle est critique, $N. N\'échouez pas.', },
    {'Trouvez les Nécrotraqueurs Adamant et Vincent.', },
  },
  [1099] = {
    'Les gobelins gagnent !',
    nil,
    nil,
  },
  [1100] = {
    'Journal de Lonebrow',
    {'Vous ouvrez lentement le journal décoloré de Henrig Lonebrow…', },
    {'Lire le Journal de Henrig Lonebrow.', },
  },
  [1101] = {
    'La mégère du Kraal',
    {'Pauvre Heralath ! Et ce nain... Lonebrow. Quel esprit courageux il avait.|n|nNous ne devons pas laisser leur vaillance périr pour rien. Cette mégère… Charlga Trancheflanc… doit être arrêtée.|n|nIl ne fait pas de doute qu\'infiltrer le kraal sera périlleux. Nous n\'avons pas le temps d\'envoyer un mot à Darnassus. $N, rassemblez un groupe et tuez la mégère.|n|nApportez-moi le médaillon de Trancheflanc comme preuve de son décès.', },
    {'Apporter le Médaillon de Trancheflanc à Falfindel Gardevoie à Thalanaar.', },
  },
  [1102] = {
    'Un destin funeste',
    {'Cairne est un noble chef qui a unifié notre peuple, ici, aux Pitons-du-Tonnerre.|n|nMais je ne peux pas pardonner aussi facilement à ceux qui nous ont éloignés de nos terres ancestrales. Mon peuple a habité les Tarides du Sud pendant des décennies. Cette terre est sacrée pour nous. Mais nous en avons été chassés par de nombreux ennemis.|n|nUn destin funeste attend la sinistre mégère, Charlga Trancheflanc, qui rameute une ignoble armée depuis le kraal de Tranchebauge.|n|nApportez-moi le cœur de Trancheflanc et je pourrai mourir en paix, $N.', },
    {'Apporter le Cœur de Trancheflanc à Cime-de-Pierre le Vieil, aux Pitons-du-Tonnerre.', },
  },
  [1103] = {
    'L\'appel de l\'eau',
    {'Bienvenue, $Gmon pote:m\'dame; ! Vous êtes ici pour purifier l\'eau et prouver votre compréhension de cet élément à Islen ? J\'viens juste de vaincre l\'esprit corrompu de l\'eau, ouais, moi-même, et j\'m\'apprêtais à placer les bracelets et les gouttes d\'eau restantes dans le brasero.|n|nQu\'est-ce que c\'est que ce machin ? Ahhh. Tiev comprend très bien quand quelque chose tourne mal. Eh bien, Tiev peut beaucoup vous aider si vous voulez voir de nouveau l\'esprit pur de l\'eau.|n|nApportez-moi un sapta d\'eau d\'Islen comme preuve de votre bonne préparation, et j\'vous attendrai pour faire ma part du travail.', },
    {'Apporter un sapta d\'eau à Tiev Mordune dans la forêt des Pins-Argentés, si vous n\'arrivez pas à parler à la Manifestation d\'eau mineure.', },
  },
  [1104] = {
    'Le venin acide des salines',
    {'J\'ai tellement de modèles pour notre chariot explosif ! Tellement ! Et je dois tous les essayer !|n|nJe travaille à un nouveau type de carburant. Un qui met vraiment vraiment vraiment le feu ! Je n\'ai pas encore trouvé le mélange exact, mais je pense savoir ce dont j\'ai besoin... Les scorpides qui vadrouillent dans les Salines ont un venin qui contient des tas et des tas d\'acides. C\'est tout à fait unique ! Et c\'est exactement ce qu\'il me faut !|n|nApportez-moi de ce venin et croyez-moi, notre chariot va voler !', },
    {'Apportez 6 doses de Venin de scorpide acide à Féplouf Zéboulon, dans les Salines.', },
  },
  [1105] = {
    'Les carapaces durcies',
    {'Mon frère travaille sur un nouveau carburant pour son chariot explosif. Il est brillant, vraiment. Tellement brillant que… Je pense que ce nouveau carburant va être tellement corrosif qu\'il risque de dissoudre le châssis.|n|nJe veux renforcer ses réservoirs avant que ça n\'arrive.|n|nLes tortues des Salines ont une carapace très résistante. J\'avais l\'idée de les utiliser pour créer de nouveaux réservoirs sur notre chariot explosif. Des réservoirs capables de contenir le nouveau carburant de mon frère.|n|nVous avez l\'air suffisamment responsable. Vous pourriez m\'obtenir ces carapaces ?', },
    {'Apporter 9 Carapaces de tortue durcies à Lachnouf Zéboulon dans les Salines.', },
  },
  [1106] = {
    'Martek l\'Exilé',
    {'Je suis en train de développer un nouveau moteur. Il rendra le chariot si rapide ! Suffisamment rapide pour voler, je le sais ! J\'ai juste besoin de faire des pistons qui peuvent supporter de très très grandes pressions. Tous mes essais ont échoué, car je n\'arrive pas à faire des pistons suffisamment forts !|n|nMais il y a quelqu\'un qui pourrait m\'aider.|n|nSon nom est Martek l\'Exilé. C\'est un grand forgeron et il en connaît plus sur les métaux que n\'importe qui d\'autre. Apportez-lui cette lettre, je sais qu\'il peut m\'aider !|n|nMais il est très très loin. En Azeroth, dans les Terres ingrates, dans un camp, avec un gobelin !|n|nTrouvez-le !', },
    {'Apporter la Lettre de Féplouf à Martek l\'Exilé dans les Terres ingrates.', },
  },
  [1107] = {
    'Les nageoires incrustées',
    {'Notre chariot explosif est ce qu\'il y a de plus rapide dans les Salines. Tellement rapide que… j\'ai peur que les frottements ne le détruisent complètement.|n|nPour empêcher cela, je dois créer un composite pour enduire les parties mobiles du chariot. Il doit être dur, mais pas friable, et pouvoir résister à la corrosion du sel, ou le temps passé dans les Salines le grignotera petit à petit.|n|nAvez-vous entendu parler du Récif infâme, $N ? C\'est près de la côte de la vallée de Strangleronce. Des murlocs Selécaille y vivent, et leurs nageoires sont un élément crucial de mon composite.', },
    {'Apporter 10 Nageoires incrustées à Lachnouf Zéboulon dans les Salines.', },
  },
  [1108] = {
    nil,
    {'Je ne suis pas là simplement pour rester à l\'écart des gens. Il y a une fortune en métal dans les Terres ingrates, $N, si vous avez les tripes pour aller la chercher.|n|nLe métal s\'appelle l\'indurium, et une de ses qualités est sa très haute résistance à la chaleur et à la pression.|n|nÇa pourrait faire l\'affaire pour le chariot de Féplouf.|n|nMais nous devons nous en assurer. Trouvez-moi des échantillons d\'indurium et je testerai ses propriétés.|n|nLe véritable indurium se trouve dans les profondeurs d\'Uldaman, mais les troggs Cavepierre des Terres ingrates en ont parfois des paillettes sur eux. Apportez-moi ces paillettes.', },
    {'Apporter 10 Paillettes d\'indurium à Martek l\'Exilé dans les Terres ingrates.', },
  },
  [1109] = {
    'Corvée de guano',
    {'Comme vous pouvez le constater, $N, nous préparons de très… intéressantes expérimentations à la Société royale des apothicaires.|n|nEn tant que Maître, mon travail est de superviser les plus ambitieuses de nos tentatives alchimiques. Tellement de travail et si peu de temps !|n|nVous avez l\'air d\'avoir beaucoup voyagé, $C. Peut-être pourriez-vous m\'aider.|n|nJ\'ai besoin d\'une substance rare. C\'est un matériau infect, qui provient d\'une espèce rare de chauves-souris que l\'on trouve dans la fosse connue sous le nom de kraal de Tranchebauge. Apportez-moi du guano de chauve-souris du kraal afin que nous puissions nous mettre au travail...', },
    {'Apporter 1 tas de Guano du kraal au maître apothicaire Faranell à Fossoyeuse.', },
  },
  [1110] = {
    '[PÉRIMÉ pour 4.x] Pièces de chariot explosif',
    {'Eh ! Avec toutes les courses qui ont lieu ici, il n\'est pas surprenant que quelques incidents surviennent le long du chemin.|n|nSi vous regardez tout autour des Salines, vous verrez des traces d\'accidents. On trouve des pièces de chariots explosifs partout !|n|nEt ces pièces valent de l\'argent. Elles intéressent les gnomes et les gobelins. Ils cherchent toujours des pièces à monter sur leurs chariots.|n|nAlors allez-y et trouvez-moi des pièces. Apportez-m\'en un tas et je vous paierai bien.', },
    {'Apporter 30 Pièces de Chariot explosif à Kravel Koalbarbe des Salines.', },
  },
  [1111] = {
    'Maître des quais Tournoupette',
    {'Mon boulot, c\'est que les gens obtiennent ce dont ils ont besoin, et les gnomes par-là ont besoin qu\'une commande soit passée. Leurs pièces sont arrivées à Cabestan il y a une semaine, mais je n\'ai pas pu faire le voyage.|n|nAlors, êtes-vous $Gprêt:prête; à marcher un peu ? Allez à Cabestan, et donnez cette commande de pièces au Maître des quais Tournoupette. Il se trouvera probablement sur les docks.|n|nFaites cela pour moi, et j\'aurai plus de boulots à vous confier.|n|nDes boulots, mon $Gami:amie; avec de sérieux bénéfices à la clé...', },
    {'Apporter la Commande de Kravel au Maître des quais Tournoupette à Cabestan, dans les Tarides.', },
  },
  [1112] = {
    'Les pièces détachées de Kravel',
    {'Voici le paquet de Kravel, $N. Et lorsque vous lui remettrez, dites-lui que s\'il veut plus de commandes spéciales, alors il doit payer l\'addition !', },
    {'Apporter les Pièces détachées de Kravel à Kravel Koalbarbe dans les Salines, aux Mille pointes.', },
  },
  [1113] = {
    'Des cœurs zélés',
    {'Vous pourriez vous demander pourquoi j\'ai besoin d\'un type rare de guano. Eh bien, pour cette expérience, je veux voir quels effets deux substances chimiques diamétralement opposées peuvent avoir l\'une sur l\'autre, et spécialement lorsqu\'elles sont combinées à un agent extrêmement toxique pour assurer les résultats les plus... effrayants.|n|nDans les pics au nord-est des Clairières de Tirisfal, vous trouverez le monastère Écarlate. Les disciples fanatiques de la Croisade s\'y réunissent, à l\'intérieur et à l\'extérieur des salles. Peu importe lesquels vous tuez, ils peuvent tous avoir le type de cœur dont j\'ai besoin.', },
    {'Le maître apothicaire Faranell, à Fossoyeuse, veut 20 Cœurs zélés.', },
  },
  [1114] = {
    'Une livraison pour les gnomes',
    {'À présent que j\'ai ce dont j\'ai besoin, apportez ces pièces à Féplouf Zéboulon. Cela fait longtemps qu\'il les attend. Je suis sûr que la pièce que j\'ai prélevée sur sa commande ne lui manquera pas…|n|nEt ça ne vaut même pas le coup de lui dire. C\'est une toute petite pièce complètement inutile, de rien du tout. Minuscule...|n|nFaites-moi confiance.', },
    {'Apportez les Pièces de chariot fragiles à Féplouf Zéboulon dans les Salines.', },
  },
  [1115] = {
    'Le marchand de rumeurs',
    {'Maintenant que nous avons rendu un service aux gnomes, il est temps de faire une faveur aux gobelins !|n|nJe crois savoir que le pilote de course gobelin, Nazz Toutevapeur, n\'a pas toujours porté ce nom. Je me demande pourquoi il en a changé. Je me demande s\'il s\'agit d\'un secret, et je me demande s\'il accorde de la valeur à ce secret.|n|nSi quelqu\'un connaît la vérité, alors c\'est Krazek à Baie-du-Butin, sur la pointe sud de Strangleronce. Parlez à Krazek et interrogez-le sur notre pilote gobelin.|n|nSi vous parvenez à en tirer une information utile, alors nous pourrions peut-être en tirer profit...', },
    {'Parler à Krazek à Baie-du-Butin, dans la Vallée de Strangleronce.', },
  },
  [1116] = {
    'De la poussière de rêve dans les marécages',
    {'Vous obtenir des informations sur Nazz est une grande faveur que je vous fais, $N. Oui, une grande faveur ! Mais vous avez fait tout le chemin depuis les Salines pour en avoir… Voulez-vous voyager encore un peu ?|n|nPendant que je contacte mes sources, pourquoi ne chercheriez-vous pas quelque chose pour moi, hein ?|n|nHmm... Qu\'est-ce que ce sera ?... Et que diriez-vous de poussière de rêve ? On en trouve sur les dragonnets du marais des Chagrins... Oui, j\'aimerais de la poussière de rêve pour ma blague à tabac !|n|nTrouvez-m\'en, $N, et je vous fournirai l\'information que vous recherchez.', },
    {'Apporter 10 Grains de poussière de rêve à Krazek à Baie-du-Butin. La Poussière de rêve se récupère sur les dragonnets du marais des Chagrins.', },
  },
  [1117] = {
    'Des rumeurs pour Kravel',
    {'J\'ai dû utiliser une faveur qu\'on me devait et abandonner une bouteille de vin elfique rare. J\'ai même dû faire des déductions difficiles moi-même. Mais j\'ai trouvé l\'information que vous cherchez.|n|nTenez, j\'ai écrit une lettre avec des passages très croustillants au sujet de notre ami, Nazz Toutevapeur. Faites-en ce que vous voulez, c\'est trop dangereux pour que moi je l\'utilise.|n|nMais ne dites à personne qui vous a informé !', },
    {'Apportez les Rumeurs gobelines à Kravel Koalbarbe dans les Salines, aux Mille pointes.', },
  },
  [1118] = {
    'Retour à Baie-du-Butin',
    {'$N, vous êtes quelqu\'un en qui je peux avoir confiance, pour faire le boulot, mais aussi pour la fermer tout en le faisant.|n|nJ\'ai échafaudé un nouveau plan, $C. C\'est risqué, mais si ça marche, on peut tous les deux se faire un paquet ! Et je pense que vous êtes la bonne personne pour ne pas se laisser abuser.|n|nPour commencer, vous devez retourner à Baie-du-Butin. Désolé, $Gcher:chère; $N. Je sais que ma dernière quête vous y a $Gamené:amenée;. Mais cette fois-ci, parlez à Grincheux Bullévente.|n|nDonnez-lui cette lettre. Et s\'il demande de l\'aide, faites de votre mieux pour lui apporter. Cela en vaudra la peine.', },
    {'Apporter le Plan de Kravel à Grincheux Bullévente à Baie-du-Butin, dans la Vallée de Strangleronce.', },
  },
  [1119] = {
    'La mixture de Zanzil et la bière brune du Sot',
    {'J\'ai trouvé comment mélanger la mixture de Zanzil avec de la bière brune pour créer une boisson qui décape. Une bière brune du Sot. Je pense que c\'est exactement ce dont Kravel a besoin, mais essayez-la et dites-moi comment ça se passe.|n|nEt $N, ne gardez pas trop longtemps ce truc sans l\'utiliser. La mixture de Zanzil a un effet bizarre sur les levures de la bière, elle les booste un max. Mais elle ne va pas rester fraîche éternellement.', },
    {'Apportez la Bière brune du Sot à Kravel, aux Salines, aux Mille pointes.', },
  },
  [1120] = {
    'Saoulez les gnomes',
    {'Nous devons essayer cette bière brune du Sot sur l\'une des équipes de mécanos. Si vous voulez l\'essayer sur l\'équipe des gnomes, alors tenez, prenez la bière et donnez-la au chef des mécaniciens gnomes.|n|nEt n\'attendez pas trop. Cette bière va se gâter après un temps.', },
    {'Apportez la Bière brune du Sot au Chef-mécanicien gnome, à la Piste des mirages, aux Mille pointes.', },
  },
  [1121] = {
    'Saoulez les gobelins',
    {'Nous devons essayer cette bière brune du Sot sur l\'une des équipes de mécanos. Si vous voulez l\'essayer sur l\'équipe des gobelins, alors tenez, prenez la bière et donnez-la au chef des mécaniciens gobelins.|n|nEt n\'attendez pas trop. Cette bière va se gâter après un temps.', },
    {'Apportez la Bière brune du Sot au Chef-mécanicien gobelin, à la Piste des mirages, aux Mille pointes.', },
  },
  [1122] = {
    'Retourner voir Bullévente',
    {'Cette bière brune du Sot a marché à merveille ! J\'ai parié sur la course suivante… Vous pensez bien que l\'équipe que vous avez éméchée a fait son numéro sur le chariot !|n|nIl n\'y a plus qu\'une chose à faire : apportez cette note à Grincheux Bullévente à Baie-du-Butin. Il voudra connaître les résultats du test.|n|nEt avec un peu de chance, nous aurons plus de cette bière brune du Sot pour les prochaines courses !', },
    {'Apportez le Rapport sur la bière brune du Sot à Grincheux Bullévente, à Baie-du-Butin, dans la Vallée de Strangleronce.', },
  },
  [1123] = {
    nil,
    {'Pour cette tâche, vous devrez assister et aider le majordome du Gardien Remulos, Rabine Saturna, à Reflet-de-Lune. Il vous faudra explorer les terres désolées qui se trouvent loin à l\'ouest de Tanaris et d\'Un\'Goro. Il habite à Havrenuit, le plus grand village de Reflet-de-Lune.|n|nJe voudrais que vous compreniez à quel point votre présence y est importante. En effet, les tensions ne cessent de croître entre les elfes de la nuit de Darnassus et le Cercle cénarien de Reflet-de-Lune. Essayez de vous départir de tout préjugé racial et appelez-en à la sagesse de vos ancêtres qui savaient comment traiter avec le Cercle cénarien, $N. Bonne chance.', },
    {'Parler à Rabine Saturna, au village de Havrenuit, à Reflet-de-Lune. Reflet-de-Lune se trouve entre Gangrebois et le Berceau-de-l\'Hiver. Le chemin qui y mène traverse le Repaire des Grumegueules.', },
  },
  [1124] = {
    'La dévastation',
    {'À l\'ouest du cratère d\'Un\'Goro, par la crête du nord-ouest, se trouvent d\'arides terres désolées du nom de Silithus. Peu nombreux sont ceux qui savent qu\'une guerre y eut lieu, opposant les elfes de la nuit à une force extérieure maléfique. Le mal put être contenu, mais maintenant nous pensons que des forces sont à l\'ouvrage pour réanimer cette inimaginable... horreur.|n|nAllez voir Layo Heurtétoile, l\'un de nos agents dans Silithus ; vous le trouverez au cimetière du Repos des vaillants, là où reposent tous ceux qui sont tombés. Donnez-lui cette lettre, afin qu\'il vous accorde sa confiance.', },
    {'Parler à Layo Heurtétoile, à proximité du Repos des vaillants de Silithus, et lui montrer la Lettre de Rabine.', },
  },
  [1125] = {
    'Les esprits de Sudevent',
    {'Au sud-ouest se trouve un endroit terrible : les ruines du village de Sudevent. C\'est là que nous devons commencer à travailler, $N.|n|nD\'après ce que j\'ai appris, ce village fut jadis une base des elfes de la nuit en Silithus. Il est maintenant envahi par des ruches de silithides. Je ne peux penser sans la plus grande horreur comment le village fut jadis emporté et submergé...|n|nLes esprits torturés des druides et des Sentinelles hantent les ruines, sans but. Explorez cet endroit et libérez les âmes de ces malheureux.', },
    {'Libérer l\'esprit de 8 Druides torturés et de 8 Sentinelles torturées, dans le village de Sudevent, puis revenir voir Layo Heurtétoile, au cimetière du Repos des Vaillants de Silithus.', },
  },
  [1126] = {
    'Une ruche dans la tour',
    {'La ruche doit être traitée au village de Sudevent, et je pense que je sais comment les atteindre. Mon expérience m\'a appris que les ruches des silithides étaient extrêmement sensibles à leur environnement. Ce qui explique leurs attaques dès qu\'ils entendent les gémissements des esprits.|n|nLes silithides sont plus nombreux dans la tour ; celle qui est entourée d\'un nuage de guêpes. Escaladez la tour et forcez la ruche à entrer en activité. Revenez faire votre rapport sur ce que vous avez appris, mais faites attention ! Si vous découvrez quoi que ce soit qui vous semble utile, rapportez-le-moi.', },
    {'Escalader la tour du village de Sudevent, et trouver un moyen de mettre la ruche des silithides en activité. Toute chose inhabituelle doit être rapportée à Layo Heurtétoile, au cimetière du Repos des vaillants de Silithus.', },
  },
  [1127] = {
    'Bière brune du Sot',
    {'Ainsi, vous voulez de la bière brune du Sot, hein ? Vous pensez retourner aux courses ?|n|nTrès bien, apportez-moi de la mixture de Zanzil et je vous préparerai davantage de bière.', },
    {'Apporter 12 Mixtures de Zanzil à Grincheux Bullévente, à Baie-du-Butin.', },
  },
  [1128] = {
    '<NYI> Les mécanos gnomes ont soif',
    nil,
    nil,
  },
  [1129] = {
    '<NYI> Les mécanos gobelins ont soif',
    nil,
    nil,
  },
  [1130] = {
    'Melor envoie un message',
    {'$N, Melor Sabot-de-pierre a entendu parler de vos exploits, et vous a préparé une voie à suivre.|n|nSi vous souhaitez l\'emprunter, alors partez pour les Pitons-du-Tonnerre et parlez à Melor. Vous le trouverez sur la cime des Chasseurs.', },
    {'Parler à Melor Sabot-de-Pierre aux Pitons-du-Tonnerre.', },
  },
  [1131] = {
    'Broie-l\'acier',
    {'Parfois, nous chassons pour vivre. Parfois, nous chassons pour l\'honneur. Et parfois, nous chassons pour mériter le savoir de la Terre-mère. |n|nMais la chasse qui vous attend n\'est pas de celles-là. Il s\'agit de détruire une créature qui refuse les bénédictions de la Terre-mère. |n|nLes Mille pointes, au sud des Tarides, sont le terrain de chasse de l\'hyène Broie-l\'acier. C\'est un tyran, qui attire à lui les autres hyènes, répand la terreur et massacre les bêtes plus paisibles. |n|nTrouvez Broie-l\'acier, $N. Trouvez-le et tuez-le.', },
    {'Apportez 1 Côte de Broie-l\'acier à Melor Sabot-de-pierre aux Pitons-du-Tonnerre.', },
  },
  [1132] = {
    'Fiora Grandes-oreilles',
    {'Ah ! Pouvoir prendre la mer une fois encore ! Sentir le baiser du vent, être bercé par les vagues comme un enfant par sa mère !|n|nJ\'aimerais avoir votre chance, $Gcher:chère:c; $C, car je vois la mer dans votre avenir proche !|n|nIl est de mon devoir de raconter aux âmes vaillantes la terre de Kalimdor, la terre de toutes les possibilités ! Si vous voulez chercher fortune sur la mer, prenez ici un bateau qui vous mènera au joli port d\'Auberdine. Adressez-vous alors à mon amie, l\'elfe Fiora Grandes-oreilles.|n|nElle vous aidera à commencer l\'aventure de Kalimdor !', },
    {'S\'adresser à Fiora Grandes-oreilles sur les docks d\'Auberdine, à Sombrivage.', },
  },
  [1133] = {
    'Le voyage vers Astranaar',
    {'$N, allez à Astranaar. Je suis sûr $Gqu\'un:qu\'une; fidèle membre de l\'Alliance comme vous peut faire beaucoup de bien là-bas. Allez offrir vos services à Shindrell Prestefeu.|n|nInutile de dire qui vous envoie, car Shindrell ne me connaît pas...', },
    {'Parlez à Shindrell Prestefeu à Astranaar.', },
  },
  [1134] = {
    'Les Ailes-fières des Serres-Rocheuses',
    {'Nous ne sommes pas en guerre ouverte avec la Horde, mais la paix est fragile. Leurs agents agissent clandestinement contre nous. |n|nLeurs incursions nous ont été révélées par des sources secrètes à Theramore : il semble que des orcs collectent du venin des wyvernes Ailes-fières du lac Mirkfallon, dans le sud des Serres-Rocheuses. Un venin utilisé ensuite par leurs assassins lors de raids secrets contre l\'Alliance ! |n|nS\'il s\'agit de la vérité, nous devons les stopper, $N ! Nous devons anéantir leur source d\'approvisionnement en venin.', },
    {'Apporter 12 Glandes de venin d\'aile-fière à Shindrell Prestefeu à Astranaar.', },
  },
  [1135] = {
    'Le venin de Haut-Perchoir',
    {'Comme vous le savez, les wyvernes sont souvent domestiquées par les orcs, qui les utilisent comme montures. Ce que l\'on sait moins, c\'est que, dans certains cercles, le venin de wyverne est plus recherché que la bête elle-même. Si vous n\'avez pas peur de chasser la wyverne, j\'ai un travail pour vous.|n|nIl existe dans la région des Mille pointes, à l\'ouest, un lieu nommé Haut-Perchoir. Les wyvernes qui y nichent produisent un puissant venin. Très puissant et largement monnayable.', },
    {'Apporter 10 Glandes à venin de Haut-Perchoir à Fiora Grandes-oreilles à Theramore.', },
  },
  [1136] = {
    '[PÉRIMÉ]Gueule-glacée',
    {'$N, il est temps pour vous de voyager vers de lointaines contrées. Le moment est venu. |n|nVous devez partir à la poursuite de Gueule-glacée, un yéti des montagnes d\'Alterac. Il est très difficile à trouver, car sa fourrure blanche se confond avec la neige de ses montagnes maternelles. |n|nJe vais vous montrer comment attirer une telle créature à découvert. Prenez ce parchemin. Il vous indiquera la manière de débusquer Gueule-glacée. |n|nAllez, maintenant, $N. Votre voyage sera long et plein d\'embûches. Votre quête sera accomplie lorsque vous rapporterez la crinière de Gueule-glacée.', },
    {'Rapporter la Crinière de Gueule-glacée à Melor Sabot-de-Pierre aux Pitons-du-Tonnerre.', },
  },
  [1137] = {
    'Des nouvelles pour Féplouf',
    {'L\'indurium est étonnamment résistant à la chaleur. Je suis certain que ce métal serait idéal pour les pistons de Féplouf. Mais il lui faudra du minerai d\'indurium naturel, pas seulement quelques paillettes.|n|nOn ne trouve ce minerai que très profondément enfoui dans les terres d\'Uldaman, en bordure septentrionale des Terres ingrates. C\'est là que se trouve le véritable indurium.|n|nEnvoyez mes amitiés à Féplouf Zéboulon et répétez-lui ce que je viens de vous dire.|n|nQue votre voyage soit paisible, $N. Je ne serais pas étonné que nous soyons appelés à nous rencontrer de nouveau... Dès que Féplouf recevra mon message au sujet de l\'indurium, il vous enverra certainement à Uldaman pour en chercher !', },
    {'Parler à Féplouf Zéboulon dans les Salines, aux Mille pointes.', },
  },
  [1138] = {
    'Fruit de la mer',
    {'J\'adore le crabe, ce fruit de mer par excellence ! Vous pouvez le faire griller, l\'ébouillanter, le braiser, en faire des beignets frits, des acras, le déguster en salade ou le consommer en soupe ; voilà tout ce qu\'on peut faire avec.|n|nJe suis ici en train de pêcher en ce moment, et je ne peux donc pas me procurer les morceaux de chair de crabe raffinée dont j\'ai besoin. Vous pouvez en trouver sur les clampants des récifs et sur les clampants des marées incrustés. Vous pouvez en faire plein de choses. Vous pouvez le faire griller, l\'ébouillanter, le braiser...', },
    {'Collecter 6 morceaux de Chair de crabe raffinée pour Gubber Blump, à Auberdine.', },
  },
  [1139] = {
    'La tablette de volonté',
    {'Nous avons ralenti le clan Ombreforge en le coupant du pic Rochenoire, mais la quête de Martèlorteil n\'est toujours pas accomplie. Sa mort ne doit pas rester vaine. Il voulait trouver la Tablette de Volonté : un morceau de pierre que les titans avaient gravé de caractères magiques pour les aider à donner la vie à leurs créations, leur communiquer une volonté propre. C\'est ce que dit la légende en tout cas.|n|nIl nous faut retrouver cette tablette avant ceux du clan Ombreforge !|n|nRepartez pour Uldaman, trouvez la tablette et revenez ici immédiatement.', },
    {'Trouver la Tablette de Volonté et la rapporter au Conseiller Belgrum à Forgefer.', },
  },
  [1140] = {
    'La Tour d\'Althalaxx',
    {'L\'écriture des orcs est à peine plus lisible que le gribouillage d\'un enfant. J\'ai essuyé bien des moqueries lorsque j\'ai décidé d\'apprendre leur langue, mais il est toujours utile de connaître l\'ennemi. |n|nSi j\'en crois les griffonnages d\'Ilkrud, il semble qu\'Athrikus possède toujours deux gemmes d\'âme captives, au défilé de la Nuit et à Satyrnaar, des régions tenues par les satyres au nord-est d\'Orneval. |n|nFaites attention, $N, les temples baignés de sang des satyres peuvent être effrayants, même pour $Gun:une:c; $C aussi $Gaguerri:aguerrie:c; que vous !', },
    {'Libérer les Âmes de Bien-nés captives au défilé de la Nuit et à Satyrnaar, puis retourner voir Delgren le Purificateur au poste de Maestra.', },
  },
  [1141] = {
    'La famille à la canne à pêche',
    {'J\'adore pêcher. La famille Blump est connue comme une grande famille de pêcheurs. Je m\'appelle Gubber Blump ; je pêche.|n|nIl y a un poisson que j\'aime attraper dans le coin, le mérou de Sombrivage. J\'avais l\'habitude d\'aller en bateau pour pêcher Ie mérou, mais les bateaux ne sortent plus depuis que ces maudits murlocs sont arrivés. Je suppose qu\'ils ont aussi dévoré tous les mérous.|n|nVoulez-vous m\'aider à attraper des mérous de Sombrivage ? Si vous m\'aidez, je vous donnerai une authentique canne à pêche de la famille Blump ! C\'est une excellente canne pour attraper le poisson.', },
    {'Attraper 6 Mérous de Sombrivage pour Gubber Blump, à Auberdine.', },
  },
  [1142] = {
    'Le déclin et la mort',
    {'Il ne me reste plus beaucoup de temps... Tellement... Tellement faible...|n|nLe brave Lonebrow a été envoyé pour avertir Falfindel...|n|nMais avant que je ne m-m-meure...|n|n... Ma femme, Treshala... Son pendentif de mariage avec moi... V-v-volé... par un de ces sauv-v-vages agresseurs...|n|nTrouvez-le, j-j-je vous en prie... Et rapportez-le à Treshala, à Darnassus...|n|n... Et racontez-lui ma mort... solitaire.', },
    {'Trouver et rapporter le Pendentif de Treshala à Treshala Ruissefriche à Darnassus.', },
  },
  [1143] = {
    'La Tour d\'Althalaxx',
    {'Je vois. Si ce que vous affirmez est vrai, alors c\'est le moment de frapper. Je sais qu\'Athrikus réside en haut de la tour. Faites attention, car il est entouré de nombreux démonistes, bien plus dangereux que ceux que vous avez déjà combattus.', },
    {'Tuer Athrikus Narassin et apporter sa Tête à Balthule Frappelombre près de la Tour d\'Althalaxx.', },
  },
  [1144] = {
    'Willix l\'Importateur',
    {'Enfin de l\'aide !|n|nVous n\'avez pas idée du temps que j\'ai passé prisonnier ici ! Je n\'arrive plus à me rappeler quand j\'ai vu le monde extérieur pour la dernière fois.|n|nVous voyez, je suis un entrepreneur. Prêt à tout en échange d\'un sou, si vous voyez ce que je veux dire. J\'avais entendu dire que Mebok Mizzyrix payait bien pour les racines de feuillebleues de cette espèce de porcherie ! Je pensais que ce serait de l\'argent facile. Je me trompais comme qui dirait d\'un poil.|n|nBref... Si vous voulez bien me sortir de là, je vous le revaudrai...', },
    {'Escorter Willix l\'Importateur jusqu\'à la sortie du Kraal de Tranchebauge.', },
  },
  [1145] = {
    'L\'essaim s\'agrandit',
    {'Bien des voyageurs qui sont passés par la Croisée m\'ont aidé à ramasser des œufs dans le Champ des géants, et nombreux sont ceux qui ont rapporté des récits effrayants sur les créatures. J\'en ai assez entendu pour considérer ces insectes comme plus dangereux que ne l\'avaient cru mes maîtres de prime abord.|n|nJ\'ai besoin d\'un courrier pour aller à Orgrimmar trouver Belgrom Cogneroche. Cela ne sera pas simple et celui qui ira devra prendre cette tâche au sérieux.|n|nOn trouve généralement Belgrom devant la maison des guerriers.', },
    {'Remettre la Note scellée de Korran à Belgrom Cogneroche à Orgrimmar.', },
  },
  [1146] = {
    'L\'essaim s\'agrandit',
    {'Ainsi, Korran est arrivé aux mêmes conclusions que nous sur ces insectes... On dirait qu\'il s\'agit d\'une menace plus grande que nous ne le pensions au départ.|n|nIl y a quelques jours, un chasseur est rentré à moitié mort des Mille pointes. Il accompagnait un groupe chargé de déloger une équipe de fouille naine hors des Salines. Une nuée de ces insectes a jailli d\'une grotte pendant l\'attaque et les a presque anéantis.|n|nIls étaient sous les ordres de Moktar Krin et ils se sont réfugiés à la lisière des Salines. Apportez-lui cette note.', },
    {'Apporter la Note scellée de Belgrom à Moktar Krin aux Mille pointes.', },
  },
  [1147] = {
    'L\'essaim s\'agrandit',
    {'Hum... On dirait que Belgrom pense que ces monstres sont une menace. Il veut que nous les repoussions jusque dans les profondeurs abjectes d\'où ils sont sortis.|n|nOn dirait que tuer les nains de la Ligue des Explorateurs ne leur a pas suffi... Et maintenant il va falloir que j\'envoie une section à moitié anéantie mener une nouvelle bataille. Nous ne pourrons pas réaliser cette mission par nous-mêmes. Pas tant que nous serons dans cet état. Le site de fouilles est là-bas vers le sud. Envie de manier l\'épée et de nous donner un coup de main ?', },
    {'Tuer 5 Chercheurs silithides, 5 Bourdons silithides et 5 Envahisseurs silithides, puis retourner voir Moktar Krin aux Mille pointes.', },
  },
  [1148] = {
    'Des parties de l\'essaim',
    {'Vous inspectez la carapace avec soin. Comme vous la tournez, vous comprenez que le placage est entrecroisé de telle manière qu\'elle lui donne une dureté incroyable. Cela ne ressemble à rien que vous connaissiez. Vous inspectez le reste du corps et vous réalisez que ces créatures sont très puissantes et très évoluées. |n|nEn regardant de nouveau la carapace, vous vous dites que Korran apprécierait sûrement d\'étudier ces créatures d\'un peu plus près. Cela l\'aiderait à découvrir ce qu\'elles sont et d\'où elles viennent.', },
    {'Apporter 1 Cœur de silithide, 5 Serres de silithide et 3 Carapaces de silithide intactes à Korran, à la Croisée.', },
  },
  [1149] = {
    'L\'épreuve de la Foi',
    {'Vous me cherchiez, ou peut-être est-ce le destin qui vous mène à moi ? Aucune importance. Vous voilà et un nouveau voyage commence pour vous.|n|nIl y a différents aspects dans un être : l\'esprit, le corps, l\'âme. Certains peuvent être améliorés par les traditions d\'une culture. Pour d\'autres... Nous pouvons simplement espérer qu\'elles existent en nous. Si vous êtes d\'accord, je vais mettre à l\'épreuve quelques-unes de vos qualités.|n|nSi vous réussissez, vous y gagnerez en force. Si vous échouez, vous comprendrez l\'immensité du Néant.|n|nLa première épreuve est l\'Epreuve de la Foi.', },
    {'Si vous avez la Foi, sautez des planches qui dominent les Mille pointes.', },
  },
  [1150] = {
    'L\'épreuve de l\'Endurance',
    {'Il me plaît de constater que votre courage reste entier à la lumière de ce que vous avez déjà réalisé. Puisque votre foi est intacte, il est temps de mettre les capacités de votre corps à l\'épreuve.|n|nCommençons par une épreuve d\'endurance. Allez jusqu\'à la tanière des Volplumes, à l\'ouest du poste de Librevent. Plongez au cœur de leur tanière et détruisez leurs réserves de nourriture. Cela devrait provoquer leur colère, et si vous êtes capable de survivre assez longtemps à leur furie, Grenka Hurlesang elle-même s\'attaquera à vous... Tuez-la et apportez-moi sa griffe en accomplissement de votre épreuve.', },
    {'Apporter la Griffe de Grenka à Dorn Traqueur-des-plaines, aux Mille pointes.', },
  },
  [1151] = {
    'L\'épreuve de la Force',
    {'Au temps des Dieux très anciens, les élémentaires peuplaient ce monde. Ils adoraient les Dieux très anciens, et le pouvoir de ces derniers maintenait les élémentaires attachés à ce monde. Lorsque les Dieux très anciens furent bannis, les élémentaires disparurent de notre monde et ils n\'y reviennent que s\'ils sont appelés par de puissants mages.|n|nIl y a pourtant des exceptions. Certains élémentaires étaient suffisamment puissants pour rester. L\'un d\'eux est Rok\'Alim.|n|nPour mettre votre force à l\'épreuve, trouvez Rok\'Alim dans les Mille pointes et tuez-le.', },
    {'Apporter des Fragments de Rok\'Alim à Dorn Traqueur-des-plaines dans les Mille pointes.', },
  },
  [1152] = {
    'L\'épreuve de la Connaissance',
    {'Vous avez presque terminé votre apprentissage avec moi, mais l\'Épreuve de la Connaissance n\'est pas de mon ressort. Il y a des leçons que l\'on apprend et des lieux que l\'on visite pour lesquels il faut un autre guide que moi-même.|n|nSi vous vous sentez apte, cherchez Braug Esprit-troublé... C\'est un chaman d\'une grande sagesse. Il vous mettra à l\'épreuve, alors prêtez attention à ses paroles, $N. |n|nLorsque vous vous estimerez apte, trouvez le tunnel qui relie les Serres-Rocheuses et Orneval : Braug habite près de là. Mais soyez $Gprudent:prudente;, $N. Les elfes de la nuit pourraient vouloir vous empêcher d\'accomplir votre épreuve.', },
    {'Trouver Braug Esprit-troublé près de l\'entrée de la Perce des Serres dans les Serres-Rocheuses.', },
  },
  [1153] = {
    'Un nouveau minerai',
    {'Vous m\'avez apporté une aide précieuse par le passé, $C. Le Chef de guerre apprécie, au moins jusque-là, ce que j\'ai accompli, et me demande de continuer avec une nouvelle détermination. Mon honneur me commande de vous envoyer au Chef de guerre avec une recommandation pour tout ce que vous avez fait, mais avant je voudrais vous demander votre aide une nouvelle fois.|n|nDes voyageurs, récemment revenus d\'un endroit appelé les Mille pointes, ont tué un kobold porteur d\'un échantillon d\'un minerai inhabituel. Ils n\'ont pas voulu le vendre. Je voudrais que vous me rapportiez un échantillon de ce minerai.', },
    {'Trouver un échantillon de minerai brut sur un Mineur ou un Géomètre Mufle-de-gravier et l\'apporter à Tatternack Forgacier, au Camp Taurajo dans les Tarides.', },
  },
  [1154] = {
    'L\'épreuve de la Connaissance',
    {'Vous avez réussi les épreuves de Dorn et vous cherchez à présent le défi suivant. Ce que vous avez réussi, un enfant aurait pu le réussir. Il est facile de mettre son corps à l\'épreuve. Pour l\'esprit, c\'est tout autre chose.|n|nJe vais m\'expliquer simplement : trouvez le livre dont je vais vous parler, étudiez-le et répondez à mes questions sur son contenu.|n|nQuel livre ? « L\'Héritage des aspects ». On peut le trouver au pied de Dor\'danil au sud d\'Orneval, protégé par les druides morts et leurs assassins.', },
    {'Trouver l\'Héritage des Aspects et l\'apporter à Braug Esprit-troublé, à côté de l\'entrée de la Perce des Serres, dans les Serres-Rocheuses.', },
  },
  [1156] = {
    nil,
    {'<INUTILISÉ 1>', },
    nil,
  },
  [1158] = {
    nil,
    {'<INUTILISÉ 1>', },
    nil,
  },
  [1159] = {
    'L\'épreuve de la Connaissance',
    {'Bien joué, $N. Vous avez passé la première partie de l\'Épreuve de la Connaissance, mais il reste une question à laquelle vous devez répondre. Cette question, je ne puis la poser.|n|nCherchez Parqual Fintallas dans la cité de Lordaeron. C\'était un grand historien parmi les humains, avant d\'être emporté par la Peste. Il continue sa quête du savoir, mais un savoir d\'une nature différente.|n|nIl exigera de vous une certaine tâche avant d\'accepter de vous tester, mais vous avez superbement mené à bien les épreuves jusqu\'ici... Je suis sûr que vous surmonterez cet obstacle.', },
    {'Trouver Parqual Fintallas à Fossoyeuse.', },
  },
  [1160] = {
    'L\'épreuve de la Connaissance',
    {'Je vous dirai ce que vous devrez chercher, et je vous poserai même ma question, mais certainement pas parce que vous cherchez à vous prouver quelque chose à vous-même. La Connaissance est bien plus importante que la force. Même si d\'autres vous surpassent en habileté, votre connaissance du monde vous sera précieuse. |n|nRendez-vous au Monastère au nord des Clairières de Tirisfal. Dans la bibliothèque, vous trouverez un livre intitulé « Les commencements de la menace des morts-vivants ». Il était utilisé par les paladins, désormais corrompus, pour leur entraînement contre ceux de ma race. |n|nApportez-le-moi.', },
    {'Trouver « Les commencements de la menace des morts-vivants » et le rapporter à Parqual Fintallas à Fossoyeuse.', },
  },
  [1161] = {
    nil,
    {'<INUTILISÉ 1>', },
    nil,
  },
  [1162] = {
    nil,
    {'<INUTILISÉ 1>', },
    nil,
  },
  [1163] = {
    nil,
    {'<INUTILISÉ 1>', },
    nil,
  },
  [1164] = {
    'Le voleur volé',
    {'La traînée ! La truie ! Kenata vit toujours ; sa famille est riche et prospère tandis que je souffre, comme une Réprouvée que je suis !|n|nMa famille a disparu, emportée par la peste. Notre domaine a disparu, lui aussi, détruit et brûlé pendant la guerre. Et malgré cela, aidée de ses misérables enfants, elle a l\'audace de voler le seul bien qui me reste.|n|nJe n\'attache plus d\'importance aux choses qui m\'ont été volées. Ce que je veux à présent c\'est leurs têtes !|n|nTuez-les pour moi ! Rendez-vous à la ferme des Dabyrie en Arathi, au nord-est du Refuge de l\'Ornière.', },
    {'Apporter la Tête de Kenata, Fardel et Marcel Dabyrie à Genavie Callow à Fossoyeuse.', },
  },
  [1166] = {
    '[PÉRIMÉ]Les soucis du Seigneur Mok\'Morokk',
    {'Vous incliner devant le seigneur Mok\'Morokk !|n|nRexxar faire de moi le puissant chef du clan Cognepierre !|n|nMoi bon chef. Moi garder clan en sûreté.|n|nGrands dragons venir et faire du feu avec anciennes maisons. Mais moi ogre malin. Moi trouver nouveau foyer pour clan ici.|n|nNous quitter ancienne maison trop vite. Moi oublier des trucs. Minuscule $R, aller trouver mes trucs. Vous aller au sud et trouver mon tafia délicieux, mon tabac à priser et mon coffre. Moi apprécier vous après ça. Vous chercher dans l\'Antre des flammes et dans les ruines Cognepierres... Mes trucs être là-bas, moi sûr !', },
    {'Le seigneur Mok\'Morokk de Mur-de-Fougères veut que vous retrouviez son tafia, son tabac à priser et son coffre dans le marécage d\'Âprefange.', },
  },
  [1167] = {
    'La Tour d\'Althalaxx',
    {'Il serait sage de vous entretenir avec Balthule avant d\'affronter Athrikus. Il a certainement observé la Tour avec une grande vigilance et il pourrait avoir des renseignements intéressants.', },
    {'S\'entretenir avec Balthule Frappelombre près de la Tour d\'Althalaxx.', },
  },
  [1168] = {
    'L\'armée des dragons noirs',
    {'Rexxar faire Mok\'Morokk seigneur. Lui mieux aimer pouvoir que ogres.|n|nDragons noirs tuer beaucoup ogres. Tuer femme de Tharg. Mok\'Morokk dire à nous de fuir. Nous venir alors ici.|n|nOgres devoir combattre. Ogres pas bons pour fuite. Mok\'Morokk s\'intéresser seulement à Mok\'Morokk.|n|nMoi appeler ma maison « ruines Cognepierres ». Moi mieux au sud. Ici pas maison.|n|nVous aider ogres à combattre armée des dragons noirs. Moi vouloir vengeance. Moi vouloir rentrer maison.', },
    {'Tharg de Mur-de-Fougères veut que vous tuiez 10 Eclaireurs Crins-de-feu, 10 Queues-cendrées Crins-de-feu et 5 Plaiedécailles Crins-de-feu.', },
  },
  [1169] = {
    '[PÉRIMÉ]L\'identification de la portée',
    {'Voyez ce vieux fou de Mok\'Morokk, qui se complaît dans son pouvoir et Tharg, qui combat les démons du désespoir et de la vengeance tout en espérant prendre la direction du clan. On dirait que je suis le seul qui cherche à connaître la source de l\'agression qui a détruit notre ancien foyer.|n|nPourquoi ce regard ahuri, $N ? Vous vous attendiez à m\'entendre parler comme un forban mal dégrossi parce que je suis un ogre ?|n|nBon ! Au travail, maintenant ! Apportez-moi des cœurs et des langues de dragonnets incendiaires et de jeunes incendiaires. Je pourrai alors chercher la source du mal.', },
    {'Draz\'Zilb de Mur-de-Fougères souhaite que vous lui apportiez 7 Langues d\'incendiaire et 7 Cœurs d\'incendiaire.', },
  },
  [1170] = {
    '[PÉRIMÉ]La portée d\'Onyxia',
    {'Le village des Cognepierres a été envahi par la portée d\'Onyxia. Mais pourquoi la fille d\'Aile de mort, le seigneur du vol noir, est-elle descendue sur nos champs ?|n|nC\'est très troublant. Onyxia a sûrement un autre but que de faire le siège d\'un petit village ogre.|n|nRendez immédiatement compte à Mok\'Morokk ! Il faut agir !', },
    {'Parler au seigneur Mok\'Morokk au village de Mur-de-Fougères.', },
  },
  [1171] = {
    '[PÉRIMÉ]La portée d\'Onyxia',
    {'Vous laisser moi maintenant. Aller dire à Draz\'Zilb nous rester ici. Pas de dragon noir ici.', },
    {'Parler à Draz\'Zilb à Mur-de-Fougères.', },
  },
  [1172] = {
    '[PÉRIMÉ]La portée d\'Onyxia',
    {'L\'engeance d\'Onyxia s\'est répandue dans tout le Cloaque aux dragons. Il est impératif d\'empêcher les dragonnets d\'éclore.|n|nHâtez-vous de rejoindre la tourbière du Ver, au sud du marécage d\'Âprefange. Il est sûr qu\'elle a laissé ses œufs là-bas. Trouvez-les tous et détruisez-les.|n|nNous ne pourrons jamais rebâtir le village des Cognepierres si les environs servent de nid aux dragons !|n|nQuant à Mok\'Morokk, j\'ai d\'autres projets pour lui…', },
    {'Draz\'Zilb, de Mur-de-Fougères, veut que vous détruisiez 5 des Œufs d\'Onyxia.', },
  },
  [1173] = {
    '[PÉRIMÉ]Défier le Seigneur Mok\'Morokk',
    {'Vous oser défier seigneur Mok\'Morokk ?|n|nMorbleu !|n|nMoi écraser $R comme un insecte !|n|nVous me dire quand vouloir bonne raclée.', },
    {'Défaire Mok\'Morokk en combat singulier et rapporter la nouvelle à Draz\'Zilb au village de Mur-de-Fougères.', },
  },
  [1174] = {
    'Et ce sont les gnomes qui gagnent !',
    nil,
    nil,
  },
  [1175] = {
    'Les cahots de la piste',
    {'Après le gros accrochage entre le Tonnerre rouge gobelin et un basilic, Kronkenfourche m\'a embauché pour surveiller la piste. Je ne sais pas ce que mangent les animaux d\'ici pour grossir comme ça, mais il faut réduire leur nombre si nous voulons éviter qu\'ils ne se baladent sur la piste pendant une course.|n|nJe vais vous dire : si vous voulez gagner un peu d\'argent sortez d\'ici et faites dégager les basilics de la zone.', },
    {'Tuez 10 Basilics du sel gemme, 10 Peau-de-cristal du sel gemme et 6 Contemplateurs du sel gemme pour le maître pisteur Zherin des Salines.', },
  },
  [1176] = {
    'Allégement de la structure',
    {'Quand on veut vraiment courir, chaque détail compte. Il faut tout prendre en compte depuis la plus petite chute de puissance jusqu\'au plus léger défaut dans la tension des fils des bobines, en passant par un trop grand allégement du châssis… |n|nNous utilisons des os de vautour pour fabriquer une grande partie des structures mineures de nos voitures, qui sont des modèles d\'équilibre entre légèreté et solidité. Cela pourrait être encore amélioré si nous avions plus de ces os ! Ils sont faciles à obtenir : les plateaux salés sont littéralement infestés de vautours. |n|nRapportez-moi des os de vautour et vous recevrez une récompense en échange.', },
    {'Se procurer 10 Os creux de vautour pour Pozzik dans les Salines.', },
  },
  [1177] = {
    'Faim !',
    {'Pil\'bou grand ogre.|n|nMoi faim.|n|nVous aller taper poisson. Apporter manger pour Pil\'bou.|n|nVous nourrir Pil\'bou sinon Pil\'bou manger vous.', },
    {'Pilebou Piessale, dans le nord d\'Âprefange, veut 8 Têtes d\'Aileron boueux.', },
  },
  [1178] = {
    'Mécénat gobelin',
    {'Notre équipe de course est la fierté de tous les gobelins ! Vous seriez surpris si je vous disais les noms de tous ceux qui y participent, d\'une manière ou d\'une autre !|n|nVous connaissez Gazleu ? Il voyage dans le monde entier pour nous rapporter nos pièces détachées. Il a même participé une fois à la construction d\'un des engins !|n|nIl y a quelques semaines, il a dit qu\'il nous enverrait un nouveau prototype de régulateur de carburant, mais il n\'est pas encore arrivé. D\'habitude, il est plus rapide que ça... Peut-être accepteriez-vous d\'aller à Cabestan pour le lui demander ? Je sais que j\'exagère un peu en vous le demandant, mais les gnomes sont en train de nous prendre de vitesse !', },
    {'Parler à Gazleu à Cabestan, dans les Tarides.', },
  },
  [1179] = {
    'Les frères Zéboulon',
    {'Vous avez déjà entendu parler des Salines ? C\'est une étendue plate et salée au-delà de Kalimdor, juste au sud du canyon des Mille pointes. C\'est un endroit fabuleux pour les courses ; forcément, c\'est complètement plat !|n|nUne paire de gnomes, des frères, des amis à moi, sont là-bas pour essayer leur nouvelle voiture à réaction. D\'après ce qu\'on m\'a dit, elle dépote ! Elle dépote tellement que les pilotes se crashent tous l\'un après l\'autre. Et finissent avec le crâne en miettes.|n|nAlors, évidemment, ils m\'ont demandé de fabriquer des casques, mais j\'ai des contraintes ici ! Je ne peux pas faire le voyage !|n|nVous pouvez ?', },
    {'Apportez la Caisse de casques anti-accidents à Lachnouf Zéboulon, à la Piste des mirages, dans les Salines.', },
  },
  [1180] = {
    'Mécénat gobelin',
    {'Bon, revenons à la raison de votre voyage. Je sais que j\'ai promis à Pozzik un nouveau régulateur de carburant, mais je ne l\'ai pas encore reçu. Revilgaz, à Baie-du-Butin, dit qu\'il l\'a envoyé par bateau, mais il s\'est peut-être perdu en route.|n|nSi c\'est le cas, nous ne pouvons pas faire grand-chose. Mais nous pouvons tout de même vérifier qu\'il est bien parti de Baie-du-Butin.|n|nVérifiez avec Maître Lozouïe, sur les quais, là-bas, il devrait être en mesure de vérifier les registres de chargement.', },
    {'S\'adresser au Maître des quais Lozouïe à Baie-du-Butin.', },
  },
  [1181] = {
    'Mécénat gobelin',
    {'Désolé, je ne vais pas être d\'un grand secours, $N ! Si vous voulez d\'autres informations, je vous suggère d\'aller trouver le baron lui-même. S\'il y a quelqu\'un qui est en mesure de vous renseigner sur les affaires de Revilgaz, c\'est Revilgaz lui-même. |n|nVous le trouverez à l\'étage de la Taverne, de l\'autre côté du port.', },
    {'Parler au Baron Revilgaz, à Baie-du-Butin.', },
  },
  [1182] = {
    'Mécénat gobelin',
    {'Vous voyez, les déchiqueteurs de la KapitalRisk du lac Nazfériti (au nord de Strangleronce) sont équipés d\'un nouveau régulateur de carburant. Je pensais que Pozzik serait en mesure de l\'adapter s\'il avait quelques détails précis à son sujet. Malheureusement, j\'ai sous-estimé l\'intelligence de Cozzle, le Surveillant du chantier.|n|nPeut-être aurez-vous plus de chance dans la recherche des plans. Je sais qu\'il les garde chez lui, mais ils sont certainement sous clé.', },
    {'Apportez les Plans du régulateur de carburant au baron Revilgaz à Baie-du-Butin.', },
  },
  [1183] = {
    'Mécénat gobelin',
    {'Vous devriez être sur le départ. Transmettez mes salutations à Pozzik et dites-lui que s\'il a besoin de quoi que ce soit, qu\'il n\'hésite pas à demander. J\'attends les nouvelles de sa victoire avec impatience !', },
    {'Apporter les Plans du Régulateur de carburant à Pozzik dans les Salines.', },
  },
  [1184] = {
    'Des parties de l\'essaim',
    {'Retournez voir Belgrom à Orgrimmar pour lui dire que Moktar fait tout ce qu\'il peut aux Mille pointes. Dites-lui aussi que mes études progressent et que je pourrai lui donner des détails assez vite. Cela devrait le satisfaire pleinement.', },
    {'Retour à Orgrimmar pour voir Belgrom Cogneroche.', },
  },
  [1185] = {
    'Sous la chitine...',
    nil,
    nil,
  },
  [1186] = {
    'Le dix-huitième pilote',
    {'Je vais être très occupé avec l\'intégration de ce nouveau Régulateur de carburant sur la structure de nos voitures de course, mais si vous voulez apporter une aide supplémentaire à l\'équipe, adressez-vous à Razzeric. C\'est notre pilote. En fait, c\'est notre dix-huitième pilote... Et il aime bien apporter ses petites modifications personnelles à sa voiture.|n|nJe vous préviens, il est un peu à côté de ses pompes alors tâchez de ne pas manifester de surprise quand vous lui parlerez !', },
    {'S\'adresser à Razzeric, dans les Salines, aux Mille pointes.', },
  },
  [1187] = {
    'Les trucs de Razzeric',
    {'Pozzik est un grand mécanicien, je le sais, mais il tergiverse trop lorsqu\'il s\'agit de puissance et de se lancer dans l\'action. Ce n\'est pas mon cas.|n|nLorsque Pozzik en a fini avec une machine, je prends quelques instants pour apporter mes petites modifications. Vous savez ce que c\'est, je rends la direction un peu plus souple, j\'enlève des morceaux de carrosserie inutiles, et j\'y mets un peu plus de patate...|n|nJ\'ai commandé un lance-hydroglycérine à Shreev au Bidulium de Gadgetzan, mais apparemment le zeppelin qui le transportait s\'est écrasé dans le marécage d\'Âprefange ! Il faut que je le récupère, $N !', },
    {'Récupérer le Lance-hydroglycérine pour Razzeric dans les Salines.', },
  },
  [1188] = {
    'La sécurité d\'abord',
    {'Mais qu\'est-ce que c\'est que ça ? Shreev a laissé la sûreté enclenchée. Ça limite l\'énergie que je peux en tirer à chaque fois. Je lui avais dit de l\'enlever ! Ça ne va pas ! |n|nVous devez rapporter ça au Bidulium de Gadgetzan dans le désert de Tanaris, et faire enlever ce truc par Shreev.', },
    {'Apportez le Lance-hydroglycérine à Shreev à Gadgetzan, en Tanaris.', },
  },
  [1189] = {
    'La sécurité d\'abord',
    {'Voilà ! J\'ai fait selon les recommandations de Razzeric. Dites-lui simplement d\'être prudent quand il installera ce truc. À la moindre erreur, il n\'avancera pas : il explosera sur place.|n|nCe serait dommage, non ? Qui sait ce que vaudra notre dix-neuvième pilote !', },
    {'Rapporter le Lance-hydroglycérine modifié à Razzeric, dans les Salines, aux Mille pointes.', },
  },
  [1190] = {
    'Rester dans la course',
    {'Les frères Zéboulon ont utilisé un nouveau matériau de construction, c\'est la seule explication plausible. Leurs voitures avancent plus rapidement qu\'avant, mais leur aspect et toutes les données que nous avons recueillies sur leurs courses restent identiques.|n|nCe que nous savons, c\'est que Tropp Zéboulon est branché à temps plein sur les plans de sa nouvelle découverte.|n|nZamek peut créer une diversion pour vous, ainsi vous pourrez dérober ces plans.', },
    {'Utiliser Zamek pour faire diversion, dérober les plans de Tropp et les apporter à Pozzik dans les Salines, aux Mille pointes.', },
  },
  [1191] = {
    'La diversion de Zamek',
    nil,
    nil,
  },
  [1192] = {
    'Minerai d\'indurium',
    nil,
    nil,
  },
  [1193] = {
    'Un piège cassé',
    nil,
    nil,
  },
  [1194] = {
    'Les schémas de Tropp',
    {'Les schémas de Tropp montrent le processus de raffinage de l\'indurium. D\'après ses gribouillages, il apparaît que le minerai provient de la mine des nains d\'Uldaman dans les Terres ingrates.|n|nLa plupart des autres notes évoquent ses propriétés de résistance à la chaleur.|n|nCe qui sert de presse-papiers pour les plans est vraisemblablement un gros morceau d\'indurium non raffiné.', },
    {'Apportez l\'Échantillon de minerai d\'indurium à Pozzik dans les Salines, aux Mille pointes.', },
  },
  [1195] = {
    'La flamme sacrée',
    {'Les centaures du clan Galak, dans les Mille pointes, protègent un artéfact du temps de la création de leur espèce.|n|nNous aimerions le voir de plus près, mais il nous faut d\'abord une flasque d\'eau provenant d\'un des puits de lune des elfes de la nuit.|n|nPour puiser l\'eau, vous aurez besoin d\'une des fioles que transportent les dryades près de la retraite de Raynebois, au cœur de la forêt d\'Orneval. Il existe un puits de lune près de la rive ouest de la Falfarren, au sud de la route principale. Vous pourrez y remplir la fiole.', },
    {'Rapporter une Fiole d\'Eau forte remplie à Zangen Sabot-de-Pierre aux Pitons-du-Tonnerre.', },
  },
  [1196] = {
    'La flamme sacrée',
    {'Apportez la Flasque remplie à Rau Cours-les-falaises au Poste de Librevent dans le sud-est des Mille pointes. Vous pouvez atteindre les Mille pointes en empruntant la Grande élévation à la limite sud des Tarides.|n|nJe ne serais pas surpris que vous puissiez nous aider davantage.', },
    {'Remettre la Flasque d\'eau forte remplie à Rau Cours-les-falaises au Poste de Librevent.', },
  },
  [1197] = {
    'La flamme sacrée',
    {'En l\'aspergeant avec l\'eau que vous avez apportée, vous pourrez temporairement éteindre la flamme qui protège la relique des centaures. L\'effet sera provisoire, vous devrez faire vite.|n|nVous trouverez la combe du Sabot fendu, la ville fortifiée des centaures, plus au nord. La flamme est gardée dans le bastion du Sabot fendu, une zone très solidement gardée.|n|nFaites attention, les centaures du clan Galak sont très nombreux à cet endroit et ils combattront férocement pour protéger une chose aussi importante à leurs yeux.', },
    {'Récupérer le Sabot fendu pour Rau Cours-les-falaises du Poste de Librevent.', },
  },
  [1198] = {
    'À la recherche de Thaelrid',
    {'De nombreuses rumeurs courent ces jours-ci sur l\'union entre le Marteau du crépuscule et les nagas, dans les profondeurs de Brassenoire, à l\'ouest. |n|nMon rôle ici est de collecter autant d\'informations que possible, afin que nous sachions où et quand un besoin d\'aide se fait sentir.|n|nCela fait des jours à présent que j\'ai envoyé un éclaireur espionner les activités menées dans les profondeurs de Brassenoire. Thaelrid n\'est toujours pas revenu au rapport.|n|nMes autres éclaireurs sont occupés à régler des affaires urgentes.|n|nPartez à la recherche de Thaelrid pour moi, $N.', },
    {'Partez à la recherche de l\'Éclaireur Thaelrid, dans les Profondeurs de Brassenoire.', },
  },
  [1199] = {
    'Le crépuscule descend',
    {'Le Marteau du crépuscule a gagné en puissance grâce aux rites ancestraux des chaotiques Dieux très anciens, qu\'il s\'emploie désormais à ramener en ce monde pour y répandre la mort et la terreur.|n|nNous pensons que le Marteau du crépuscule s\'est allié aux nagas et, qu\'ensemble, ils se regroupent en masse dans les profondeurs de Brassenoire, à l\'ouest.|n|nQuels que soient les plans maléfiques qu\'ils préparent dans les profondeurs du temple ancien, il faut les déjouer !|n|nLancez un assaut sur le Marteau et rapportez la preuve de vos actes. Vos efforts seront grassement récompensés.', },
    {'Apportez 10 Pendentifs du Crépuscule à la Sentinelle Aluwyn, au Camp de Brassenoire.', },
  },
  [1200] = {
    'L\'infamie de Brassenoire',
    {'Mes forces me quittent. J\'ai besoin de votre aide !|n|nIl y a longtemps, ce site était un grand temple d\'Élune. Mais la malchance l\'a conduit à sa ruine, quand un Dieu très ancien, en contaminant ces lieux depuis les profondeurs de la terre, a corrompu le puits de lune sacré.|n|nAku\'Mai, serviteur du Dieu très ancien, est sorti des eaux.|n|nLes sectateurs du Marteau du crépuscule se sont alliés aux nagas pour occuper ces terres. Les sectateurs, conduits par Kelris, sacrifient des innocents à Aku\'Mai pour augmenter son pouvoir.|n|nTuez Kelris et apportez sa tête à Ashelan au camp de Brassenoire, je vous en prie, $N.', },
    {'Apportez la Tête du Seigneur du Crépuscule Kelris à Ashelan Bois-du-nord, au Camp de Brassenoire.', },
  },
  [1201] = {
    'Les espions de Theramore',
    {'La trêve entre la Horde et l\'Alliance n\'est pas toujours respectée. Des escarmouches et des actions secrètes sont menées par chacun des deux camps, et il est de notre devoir de nous assurer que la Horde garde l\'avantage ! |n|nNous avons maintenant l\'occasion de démasquer les infiltrateurs de l\'Alliance. |n|nIls sont en position à l\'est du village de Mur-de-Fougères. Ils nous espionnent et rapportent nos mouvements à Theramore, ce que nous ne pouvons permettre. |n|nTraquez-les et tuez-les. Envoyons un message clair à leurs chefs : nous ne supporterons pas leur présence sur notre sol !', },
    {'Tuer 9 Infiltrateurs de Theramore, puis rendre compte à Nazeer Pique-sanglante à Mur-de-Fougères.', },
  },
  [1202] = {
    'Les docks de Theramore',
    {'$N, deux de nos espions ont été envoyés pour dérober des documents sur un bateau dans les docks de Theramore. Ils ont trouvé les papiers, mais ont été découverts et ils ont dû jeter les documents à la mer. |n|nL\'un des deux a réussi à s\'échapper par la suite, mais il n\'a pas pu récupérer le paquet. Il a rendu compte de son échec et maintenant je vous confie cette mission. |n|nLes documents sont dans un coffret, quelque part dans les eaux des docks de Theramore. Trouvez ces documents, $N, et apportez-les-moi.', },
    {'Apportez les Documents du capitaine à Nazeer Pique-sanglante au village de Mur-de-Fougères.', },
  },
  [1203] = {
    'Jarl a besoin d\'une épée',
    {'Je dois découper quelque chose. Je ne peux pas vous dire quel type de découpage je vais faire, mais... j\'ai besoin d\'une lame. Pas n\'importe quelle lame !|n|nIl y en a qui disent que c\'est une épée. Moi je dis lame.|n|nVous allez m\'aider ? Ces hommes-poissons, les murlocs, ou un truc comme ça... Il y en a un qu\'ils appellent Tranchéchine, il porte une grande épée, et il vit au nord d\'ici près de la plage. Voilà l\'épée qu\'il me faut !|n|nMais ne traînez pas. Ce que je dois découper n\'attendra pas des années.', },
    {'Apportez l\'Épée de Tranchéchine à Jarl « Œil-des-marais », au Manoir des Flammeroles.', },
  },
  [1204] = {
    'Soupe de Rochefange aux insectes',
    {'Je prépare un plat que je nomme « Soupe et insectes rochefange ». Il me manque encore les ingrédients principaux… Eh bien, je pense que je ne ferais pas long feu à patauger tout seul dans le marécage d\'Âprefange !|n|nAussi, $N, cela vous dérangerait-il de faire une petite partie de chasse pour moi ? D\'abord, il me faut des langues de tortues Rochefange. Vous pouvez en trouver le long de la côte, près de la baie.|n|nMais il ne me faut pas n\'importe quelles langues ! J\'entends par là que certaines tortues ont la langue fourchue...|n|nIl paraît que ces langues fourchues ont un goût particulier, et je veux cet ingrédient-là dans ma recette...', },
    {'Apporter 8 Langues fourchues de Rochefange à Morgan Stern, à Theramore.', },
  },
  [1205] = {
    'Mortebourbe',
    {'Mortebourbe est un ancien crocilisque du marécage d\'Âprefange. Son heure est arrivée. |n|nSes vieux os grincent quand il extrait son énorme corps du marais, et pourtant il évolue avec la force et la vitesse de ses jeunes années. Son corps fatigué torture le grand esprit qui l\'habite, un esprit dont la flamme ne faiblit pas. |n|nPourtant, il vit maintenant marqué par une douleur cruelle et permanente. Vous devez mettre fin à la vie de cette noble créature, $N. Vous devez conduire Mortebourbe à la paix.', },
    {'Apportez la Dent de Mortebourbe à Melor, aux Pitons-du-Tonnerre.', },
  },
  [1206] = {
    'Jarl a besoin d\'yeux',
    {'Le jus d\'œil est bon à boire. Malheureusement la plupart des monstres n\'ont que deux yeux.|n|nMais les araignées, elles, ont beaucoup d\'yeux. Plus que beaucoup. Et le jus d\'œil de Sombrebrume est fameux. Doux et salé ! Des yeux d\'araignée entiers... J\'ai l\'impression de les savourer.|n|nLes araignées Sombrebrume se trouvent à l\'ouest d\'ici, dans la caverne de Sombrebrume. À votre avis, c\'est cette grotte qui a donné son nom aux araignées, ou l\'inverse ?', },
    {'Apportez 20 Yeux de Sombrebrume à Jarl « Œil-des-marais », au Manoir des Flammeroles.', },
  },
  [1218] = {
    'Les cuisses de grenouille des marais',
    {'J\'aime la cuisine. La bonne cuisine du marais. Les cuisses de grenouilles vertes grillées, par exemple.|n|nHélas, je n\'ai plus du tout de cuisses de grenouilles. Cela dit, le manoir grouille de grenouilles. Des grenouilles géantes des marais. Vous croyez que vous pourriez me procurer des cuisses ? Rien de plus facile. Un bon coup sur la tête, et vous me rapportez les cuisses.|n|nAprès, je ferai un ragoût qui mijotera et je le mangerai et je vous en donnerai un peu aussi.|n|nVous aimez le ragoût ?', },
    {'Apportez 10 Cuisses de grenouilles des marais à Jarl « Œil-des-marais », dans le marécage d\'Âprefange.', },
  },
  [1219] = {
    '[PÉRIMÉ]Le rapport orc',
    {'En remuant la poussière, on trouve la main coupée d\'un orc. Une main qui agrippe encore un tube en os gravé. Le tube contient un parchemin taché.|n|nLe parchemin est écrit en orc... Et ça semble important.', },
    {'Apportez le Rapport de l\'Espion au Lieutenant Aden de Theramore.', },
  },
  [1220] = {
    '[PÉRIMÉ]Le capitaine Vimaire',
    {'Le capitaine Vimaire désire voir le rapport orc que vous avez trouvé, $N. C\'est lui qui connaît le mieux la langue des orcs. Et il doit savoir qu\'il y a des espions de la Horde près de Theramore !|n|nLe capitaine est dans la Caserne, au nord-est de Theramore.', },
    {'Apportez le Rapport orc au capitaine Garran Vimaire.', },
  },
  [1221] = {
    'Racines de feuillebleue',
    {'Les racines de feuillebleue sont une friandise universellement appréciée ! Mais elles sont rares, très rares. On ne peut les trouver qu\'ici, dans les Tarides, profondément enterrées au kraal de Tranchebauge.|n|nEt même ici, vous ne pourriez pas les trouver à moins de savoir comment les chercher ! C\'est pourquoi j\'ai entraîné ces écureuils Sniffetarin à les trouver. Ils ont un grand nez et peuvent sentir une racine à cinquante pas.|n|nCela ne sera pas facile, mais si vous me rapportez quelques racines, je vous paierai grassement.', },
    {'Prenez une Caisse percée.|nPrenez un Bâton de commandement de Sniffetarin.|nLisez le Manuel d\'utilisateur de Sniffetarin.|n|nAu Kraal de Tranchebauge, utilisez la Caisse pour invoquer un Ecureuil Sniffetarin et le Bâton de commandement pour lui ordonner de chercher les racines.|n|nRapportez 6 Racines de feuillebleue, le Bâton de commandement de Sniffetarin et la Caisse percée à Mebok Mizzyrix, à Cabestan.', },
  },
  [1222] = {
    'Sauvetage du Puant',
    {'Génial, enfin quelque chose qui ne veut pas me dévorer !|n|nJ\'ai besoin d\'aide pour occuper ces bestioles autour de moi et vous me semblez de taille.|n|nLe chef cuisinier Morgan Stern travaille sur une nouvelle recette et il m\'a envoyé ici pour cueillir des feuilles de trèfle des marais. Il doit les trouver bons à manger.|n|nQuoi qu\'il en soit, pendant que je cherchais du trèfle, je me suis retrouvé cerné ! Pouvez-vous m\'aider à sortir de là et surveiller les alentours pendant que je cherche les trèfles ?', },
    {'Escortez Ignatz « Puant » puis parlez à Morgan Stern à Theramore.', },
  },
  [1238] = {
    'Le rapport perdu',
    {'Au milieu de la poussière, une main d\'orc, seule. Et dans cette main, un tube creusé dans de l\'os. Et dans le tube, un parchemin sale.|n|nCe parchemin est un rapport établi par un orc qui a passé des semaines à espionner la ville de Theramore.|n|nAprès examen du rapport, il est clair qu\'il doit être apporté au maître-espion orc au village de Mur-de-Fougères.', },
    {'Apportez le Rapport de l\'espion à Nazeer Pique-sanglante à Mur-de-Fougères.', },
  },
  [1239] = {
    'La tête coupée',
    {'Une fouille approfondie permet de découvrir une tête d\'orc mâle. Les lèvres sont figées dans un rictus et les yeux noirs semblent vous fixer avec défi.', },
    {'Apportez la Tête d\'orc défiant à Nazeer Pique-sanglante à Mur-de-Fougères.', },
  },
  [1240] = {
    'Le féticheur troll',
    {'Nous devons connaître les faits concernant la mort de Marg ! Et il n\'y a qu\'une seule manière de savoir, $N. C\'est d\'utiliser la sorcellerie des trolls.|n|nApportez la tête de Marg à Kin\'weelay dans la vallée de Strangleronce, au Campement Grom\'gol.|n|nKin\'weelay est le plus puissant des féticheurs des trolls sombrelances. Si quelqu\'un peut parler à l\'esprit de Marg Œillenuit, c\'est lui.', },
    {'Apporter la Tête d\'orc défiant à Kin\'weelay au Campement Grom\'gol dans la vallée de Strangleronce.', },
  },
  [1241] = {
    'Un diplomate a disparu',
    {'Récemment, un diplomate a été envoyé à Theramore pour rencontrer Jaina Portvaillant. Ce diplomate n\'est jamais arrivé.|n|nJe pense que les Défias sont impliqués dans ce complot, mais je ne vois pas de quelle manière. La disparition du diplomate n\'a pas encore attiré l\'attention du public, mais cette situation ne durera pas.|n|nDes agents du roi sont déjà en train de fouiller la ville à la recherche d\'indices, mais j\'aimerais consulter mes propres contacts.|n|nDans la vallée des Héros vit un vieil ami à moi qui s\'appelle Jorgen. Trouvez-le, donnez-lui cette note et suivez ses instructions.', },
    {'Trouver Jorgen dans la cité de Hurlevent.', },
  },
  [1242] = {
    'Un diplomate a disparu',
    {'Portez cette note à Elling Trias. Ne lui dites rien d\'autre. Contentez-vous d\'être $Gpoli:polie; et attendez la réponse. Et ne vous inquiétez pas, il répondra.|n|nQue ce soit bien clair, $N : c\'est une affaire sérieuse, alors gardez votre clapet fermé.|n|nVous trouverez Trias dans son magasin de fromages, « Aux Fromages de Trias », dans le Quartier commerçant. Bonne chance !', },
    {'Apporter la Note scellée de Jorgen à Elling Trias dans la cité de Hurlevent.', },
  },
  [1243] = {
    'Un diplomate a disparu',
    {'Jorgen, vieux fils de… Alors c\'est comme ça que ça va se passer, hein ?|n|nTrès bien, je peux m\'en accommoder. J\'espère qu\'il trouvera le Néant distordu au plus tôt !|n|nVoilà comment nous allons procéder, $N. Je commence à utiliser mes contacts ici, mais comme c\'est vous qui faites le plus gros du travail de terrain, je vous prête un peu d\'argent.|n|nAllez à Sombre-Comté, dans le bois de la Pénombre, et trouvez le gardien Backus. Il patrouille généralement sur la route nord juste en dehors de la ville. Dites-lui simplement que vous êtes là pour surveiller, pour moi, l\'activité des Défias, et il vous aidera en vous donnant toutes les informations qu\'il possède.', },
    {'Donner la Note scellée au Gardien Backus, dans le bois de la Pénombre.', },
  },
  [1244] = {
    'Un diplomate a disparu',
    {'Les activités des Défias ? Il y a toujours de l\'activité, même s\'ils ne se vantent pas que nous les considérions comme une menace.|n|nMais pendant que j\'y pense, il y a eu récemment quelque chose de bizarre. Cela s\'est passé il y a environ deux semaines : certains de leurs agents se sont réunis près de la ferme des Addle. D\'après le rapport, j\'en ai déduit que quelque chose d\'important était en préparation.|n|nPourquoi ne commenceriez-vous pas par vérifier cela et me rapporter tout ce que vous trouverez ?|n|nLa ferme est au sud de la route qui vient de la marche de l\'Ouest, juste à l\'endroit où vous rentrez dans le bois de la Pénombre.', },
    {'Trouvez le Registre des Défias et rapportez-le au Gardien Backus, dans le Bois de la Pénombre.', },
  },
  [1245] = {
    'Un diplomate a disparu',
    {'Ouais ! Cela semble bien trop compliqué pour quelque chose qui serait juste destiné à vous induire en erreur. Je ne devrais même pas être en train de regarder tout ça. Portez-le à Trias. Il sera capable de comprendre tout cela. Et ne laissez PERSONNE se mettre en travers de votre chemin. Ceci est trop gros pour moi. C\'est peut-être même trop gros pour lui, mais il verra.|n|nEt faites-moi une faveur, $N, ne dites à personne que je vous ai fourni de l\'aide. Si mes supérieurs apprennent que je savais quelque chose sur cette affaire et que je ne les ai pas prévenus, ils me pendront.', },
    {'Apportez le Registre des Défias à Elling Trias à Hurlevent.', },
  },
  [1246] = {
    'Un diplomate a disparu',
    {'Ouais, maintenant que j\'y pense… Dashel… Dashel… quelque chose… Son nom c\'était quoi déjà ? POING ! Dashel Poing-de-pierre. Ils l\'appelaient Poing dans certains milieux, probablement parce qu\'il aimait se battre.|n|nVous le trouverez habituellement dans la Vieille ville, pile au centre. Allez donc lui parler. Et n\'hésitez pas à utiliser une épée ou quelque chose de bien lourd et contondant pour l\'engager à discuter. N\'y allez pas de main morte, s\'il est aussi impliqué que ces papiers le laissent à penser, il n\'est pas prêt à parler de son plein gré.', },
    {'Parler à Dashel Poing-de-pierre à Hurlevent.', },
  },
  [1247] = {
    'Un diplomate a disparu',
    {'Alors ouais… Hum !… Il se pourrait que je sache quelque chose à propos de cette rencontre à la ferme des Addle. Ça s\'est passé il y a quelques semaines je crois. Je n\'y ai pas participé. J\'avais terminé ma part du travail lorsque le plan A a échoué… Maudits aventuriers !|n|nLa taupe que nous avions pour le plan B venait de Menethil, un type appelé le Mince. C\'est tout ce que je sais sur leur plan de rechange.', },
    {'Parler à Elling Trias à Hurlevent.', },
  },
  [1248] = {
    'Un diplomate a disparu',
    {'Un de mes contacts a pris sa retraite dans les Paluns, dans le port de la cité de Menethil pour être précis. Il sera d\'accord pour vous aider si vous lui dites que vous travaillez pour moi. Son nom est Mikhail. Avant de quitter Hurlevent, il y a quelques années, il disait qu\'il voulait s\'occuper d\'un bar.|n|nParlez-lui, trouvez ce « Mince » et trouvez tout ce qui est possible sur ce diplomate disparu. Nous avons besoin de savoir où ils l\'ont emmené ou au moins qui il est. Le registre ne dit rien concernant leurs projets après sa capture.', },
    {'Parler à Mikhail dans les Paluns.', },
  },
  [1249] = {
    'Un diplomate a disparu',
    {'Vous dites que c\'est Elling qui vous envoie ? Eh bien l\'hospitalité que je vous dois est encore plus grande. Quels que soient vos besoins, demandez. Je ferai de mon mieux pour vous aider.|n|nHmm, le Mince, vous dites ? Ça ne me dit rien, mais je garderai un œil ouvert au cas où.|n|nNe vous retournez pas maintenant, $N, mais le gentilhomme là-bas près de la sortie regarde par ici. Il écoute notre conversation un peu trop attentivement, si vous voyez ce que je veux dire. Si j\'étais vous, je l\'intercepterais avant qu\'il ne puisse atteindre la porte et disparaître.', },
    {'Soumettre Tapoke Jahn avant qu\'il ne s\'échappe et ensuite retourner voir Mikhail à Menethil.', },
  },
  [1250] = {
    'Un diplomate a disparu',
    {'Les Défias ne me payent pas suffisamment pour que je meure pour leur cause. Ils ont pris le roi. Ouais, le roi de Hurlevent, pas un petit diplomate de rien du tout. Il était en route pour rencontrer Jaina Portvaillant. C\'était un gros coup apparemment et un grand secret. Mais il n\'y avait pas que les Défias qui y participaient. Ils travaillaient pour quelqu\'un. Je pense qu\'ils savaient que c\'était quelque chose de trop gros pour eux.|n|nMon travail consistait à introduire l\'un de leurs hommes sur le bateau du roi lorsqu\'il était à quai. Le nom de ce type est Hendel. C\'est tout ce que je sais. Je le jure !', },
    {'Parler à Mikhail dans les Paluns.', },
  },
  [1251] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Un bouclier en fer, noirci par le feu qui a fait rage, est fixé à la cheminée branlante, une des rares structures encore debout de ce qui a été l\'auberge du Repos ombragé.|n|nLe bouclier peut être détaché du mur en brique de la cheminée.', },
    {'Rapportez le Bouclier en fer noirci à Krog, à Mur-de-Fougères.', },
  },
  [1252] = {
    '[PÉRIMÉ]Le lieutenant Paval Reethe',
    {'Un éclat de lumière attire votre attention sur les gravats. Écartant les débris et la poussière, vous trouvez un insigne émaillé représentant une ancre dorée sur fond blanc : le symbole de Theramore.|n|nSous l\'ancre est gravé : « Lieutenant Paval Reethe ».', },
    {'Rapporter le badge de Reethe au capitaine Garran Vimaire à Theramore.', },
  },
  [1253] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Un bouclier en fer, noirci par le feu qui a fait rage, est fixé à la cheminée branlante, une des rares structures encore debout de ce qui a été l\'auberge du Repos ombragé.|n|nLe bouclier peut être détaché du mur en brique de la cheminée.', },
    {'Rapportez le Bouclier en fer noirci au capitaine Garran Vimaire à Theramore.', },
  },
  [1258] = {
    '... Et des bestioles',
    {'Un autre ingrédient de ma nouvelle recette est la patte de crabe géant. Et les crabes qu\'ils ont à Âprefange, ceux qu\'on appelle les Bourbecoques, sont délicieux !|n|nLa carapace des pattes de crabe est un des éléments clés de la présentation de ce plat. Cela veut dire que j\'ai besoin de pattes parfaites, sans trace ni éraflure. Un crabe adulte n\'a généralement qu\'une ou deux pattes de cette qualité, et il m\'en faut beaucoup pour mettre ce plat au point.|n|nPromenez-vous dans les rochers qui entourent Theramore et trouvez-moi de belles pattes !', },
    {'Apporter 12 Pattes de Clampant en parfait état à Morgan Stern à Theramore.', },
  },
  [1259] = {
    '[PÉRIMÉ]Le lieutenant Paval Reethe',
    {'Le nom du lieutenant Paval Reethe ne me dit rien. Votre meilleure chance est de vérifier auprès de l\'adjudant Tesoran. Il conserve tous les dossiers de la garde de Theramore, du personnel jusqu\'à l\'équipement.|n|nIl devrait être capable de vous dire qui est ce Reethe après un rapide coup d\'œil dans ses registres.', },
    {'Trouver plus de renseignements sur Paval Reethe auprès de l\'adjudant Tesoran à Theramore.', },
  },
  [1260] = {
    '[PÉRIMÉ]Morgan Stern',
    {'Je suis en train de créer une nouvelle carte pour le restaurant. Elle sera composée de plats typiques sur un thème « bayou ». Je pense que ma clientèle au Solitaire Bleu va l\'adorer !|n|nJ\'ai envoyé mon neveu Morgan à Theramore, une ville au bord du marécage d\'Âprefange. Il collecte des recettes locales et j\'ai besoin de savoir ce qu\'il a déjà trouvé.|n|nLe voyage pour Theramore est long. Trop long pour moi. Mais je parie que quelqu\'un d\'aussi jeune que vous, $C, sauterait sur une occasion de voyager, non ?', },
    {'Parler à Morgan Stern à Theramore.', },
  },
  [1261] = {
    'Marg parle',
    {'Maudit Bourbecoque ! Tu ne peux pas tuer Marg ! Ah, mais je suis mort. Alors il doit m\'avoir tué...|n|nMais ma mission ! Ma mission ! Vous, $N, devez achever ma mission.|n|nAlors que j\'étais près de Theramore, j\'ai espionné un groupe de soldats de l\'Alliance qui campaient sur la plage. Un de ces soldats portait un pendentif... Un pendentif avec plus de pierres précieuses que dans les rêves d\'un soldat !|n|nCette nuit-là, je me suis glissé dans leur camp et j\'ai volé le pendentif, mais au retour à la base, un homme-crabe Bourbecoque m\'a tué !|n|n$N, vous devez le retrouver et récupérer le pendentif !', },
    {'Apportez le Pendentif orné à Nazeer à Mur-de-Fougères.', },
  },
  [1262] = {
    'Rapport à Zor',
    {'Il est étrange que le pendentif que Marg a volé était en possession de simples soldats. Peut-être que son propriétaire était déguisé, ou que les soldats l\'avaient eux-mêmes volé !|n|nQuoi qu\'il en soit, il s\'agit d\'un pendentif de noble et nous devons découvrir son véritable propriétaire si nous voulons percer ce mystère.|n|nApportez-le à Zor Arbre-solitaire à Orgrimmar. Il en connaît beaucoup sur les personnages politiques de l\'Alliance et saura dire si ce pendentif est connu parmi les nobles de Hurlevent.', },
    {'Apportez le Pendentif orné à Zor Arbre-solitaire à Orgrimmar.', },
  },
  [1263] = {
    'L\'auberge en feu <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1264] = {
    'Un diplomate a disparu',
    {'Au début de chaque mois, les soldats de marine de Kul Tiras reçoivent leur paye et quittent généralement Theramore pour un autre endroit. Un grand nombre d\'entre eux viennent ici pour les femmes, faire la bringue et passer un bon moment. L\'un de ces groupes vient régulièrement à cette taverne et je crois que ce Hendel en fait partie.|n|nLe commandant Samaul à Theramore devrait vous aider à le trouver si Hendel est toujours par ici. Il est loyal à Portvaillant, mais si vous citez négligemment le nom de Elling, il devrait vous aider... discrètement.', },
    {'Trouver le commandant Samaul, dans le marécage d\'Âprefange.', },
  },
  [1265] = {
    'Un diplomate a disparu',
    {'Hendel ? Oui, je le connais. Mais pourquoi avez-vous besoin d\'un de mes soldats ?|n|nElling vous a demandé de le trouver ? Je n\'aime pas cela. Elling ne vous aurait pas $Genvoyé:envoyée; directement à moi si cela n\'était pas pour des problèmes. Je comprends que vous ne puissiez pas me dire de quoi il s\'agit, mais sachez ceci : j\'ai pour mission de protéger ce pays. Si vous pensez créer des problèmes, alors je vous suggère de m\'en informer.|n|nJe crois que Hendel est cantonné à la première tour en dehors de Theramore.', },
    {'Chercher le soldat Hendel à la halte de la Vigie.', },
  },
  [1266] = {
    'Un diplomate a disparu',
    {'Le soldat Hendel se trouve à l\'ouest d\'ici. Il est en ce moment de garde et protège des infiltrateurs de Theramore tandis qu\'ils se reposent. Ils ont tenu à l\'œil la base de la Horde, Mur-de-Fougères, et tout ce qui pourrait menacer nos frontières.|n|nVous ne devriez rencontrer aucune difficulté pour le trouver. Cherchez simplement des tentes le long de la route.|n|nUne autre affaire nécessite mon attention, mais je vous rejoindrai bientôt. Vous pourrez toujours me rencontrer dans la tour de dame Portvaillant si vous avez le moindre problème.', },
    {'Trouver le soldat Hendel dans le marécage d\'Âprefange.', },
  },
  [1267] = {
    'Un diplomate a disparu',
    nil,
    {'Parler à Jaina Portvaillant au marécage d\'Âprefange.', },
  },
  [1268] = {
    '[PÉRIMÉ]Des empreintes de sabots suspectes',
    {'Des lignes d\'empreintes de sabots partent des ruines encore fumantes de l\'auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d\'autres empreintes peu marquées dans la boue du marais.', },
    {'Faire votre rapport sur les empreintes suspectes de l\'auberge du repos ombragé à Krog, au village de Mur-de-Fougères.', },
  },
  [1269] = {
    'Le lieutenant Paval Reethe',
    {'Un éclat de lumière attire votre attention sur les gravats. Écartant les débris et la poussière, vous trouvez un insigne émaillé représentant une ancre dorée sur fond blanc : le symbole de Theramore.|n|nSous l\'ancre est gravé : « Lieutenant Paval Reethe ».', },
    {'Rapporter le Badge de Reethe à Krog à Mur-de-Fougères.', },
  },
  [1270] = {
    'Sauvetage du Puant',
    {'Enfin quelque chose qui ne semble pas vouloir me manger !|n|nJ\'ai besoin d\'aide pour repousser ces monstres et vous me semblez convenir.|n|nUn gobelin de Cabestan, du nom de Mebok Mizzyrix, a besoin de feuilles de trèfle des marais pour une potion ou je ne sais quoi... J\'avoue que je me fiche complètement de la raison, son argent est bienvenu et je connais ce marais, donc me voilà.|n|nDommage que je me sois fait encercler avant d\'avoir trouvé les trèfles ! Pourriez-vous m\'aider à sortir de là et surveiller mes arrières pendant que je cherche les plantes pour Mebok ?', },
    {'Escortez Ignatz « Puant » puis parlez à Mebok Mizzyrix à Cabestan.', },
  },
  [1271] = {
    'Fête au Solitaire Bleu',
    nil,
    nil,
  },
  [1272] = {
    'Trouver Reethe <CHANGE INTO GOSSIP>',
    nil,
    nil,
  },
  [1273] = {
    '[PÉRIMÉ]Questionner Reethe',
    {'Cela a pris du temps, mais j\'ai trouvé Reethe. Il se cache bien pour un humain.|n|nOgron se demande s\'il n\'est pas devenu fou après tout ce temps passé dans le marais. Vous venez avec moi pour lui tirer les vers du nez.', },
    {'Aller avec Ogron pour parler à Reethe puis retourner voir Krog à Mur-de-Fougères.', },
  },
  [1274] = {
    'Un diplomate a disparu',
    {'Excusez-moi, $Gmonsieur:madame;, l\'évêque DeLavey m\'a demandé de prendre contact avec des $Gaventuriers:aventurières; qui pourraient être capables de l\'aider avec un problème délicat.|n|nSi vous pouviez vous rendre discrètement au Donjon de Hurlevent pour lui parler dès que cela vous est possible, il est certain qu\'il apprécierait grandement votre secours. À nouveau, soyez $Gdiscret:discrète;. Il s\'agit d\'une affaire d\'une certaine importance.', },
    {'Trouver l\'évêque DeLavey au Donjon de Hurlevent.', },
  },
  [1275] = {
    'Recherches sur la corruption',
    {'Ces imbéciles d\'elfes de sang peinent avec la magie démoniaque. N\'ont-ils pas vu ce qui est arrivé aux nagas et aux satyres de Kalimdor ?|n|nJe crains que les elfes de sang ne subissent pareille transformation. Azeroth ne supporterait pas la naissance d\'une autre race de monstres abjects.|n|nJe souhaite étudier les troncs cérébraux des satyres et des nagas afin de découvrir ce qui attend les Sin\'dorei. Vous trouverez des satyres et des nagas dans les profondeurs de Brassenoire, juste à l\'ouest.', },
    {'Relwyn Sombrétoile, du Camp de Brassenoire, vous a demandé de récupérer 8 Troncs cérébraux corrompus.', },
  },
  [1276] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Je me souviens ! Mosarn est un forgeron respecté des Pitons-du-Tonnerre. Je savais que j\'avais entendu son nom quelque part !|n|nEn remerciement, le Cercle terrestre m\'a offert un équipement complet forgé par Mosarn. Du très beau travail !|n|nPeut-être pourrait-il vous en dire plus sur ce bouclier qu\'il a forgé.|n|nCe n\'est pas une grosse piste, mais comme nous n\'avons rien obtenu d\'utile de Reethe, c\'est tout ce que nous avons.', },
    {'Montrer le Bouclier en fer noirci à Mosarn aux Pitons-du-Tonnerre.', },
  },
  [1277] = {
    nil,
    {'Kagoro a trouvé les propriétaires des empreintes de centaures. Il s\'agit d\'une bande de crétins de Mauradon.', },
    {'Occupez-vous-en.', },
  },
  [1279] = {
    nil,
    {'Finir l\'un des trois.', },
    nil,
  },
  [1281] = {
    'La chanson de Jim <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1282] = {
    '[PÉRIMÉ]Ils l\'appellent Jim le Souriant',
    {'Je ne peux pas m\'empêcher d\'être désolé pour le vieux Jim là-bas. Il n\'a pas toujours été comme ça. Il a tenu une auberge dans les marais pendant un moment, un endroit superbe.|n|nÉcoutez, je ne veux pas vraiment en parler. Allez voir le capitaine Vimaire si vous ne pouvez pas faire autrement. Il se trouve en haut de la Citadelle de Theramore, la grande caserne à l\'est de la tour de dame Jaina.', },
    {'Parler au Capitaine Garran Vimaire au dernier étage de la citadelle de Theramore.', },
  },
  [1283] = {
    'L\'incendie de l\'auberge du Repos ombragé <CHANGE TO GOSSIP>',
    nil,
    nil,
  },
  [1284] = {
    '[PÉRIMÉ]Des empreintes de sabots suspectes',
    {'Des lignes d\'empreintes de sabots partent des ruines encore fumantes de l\'auberge du Repos ombragé. Il y a au moins quelques traces visibles avec d\'autres empreintes peu marquées dans la boue du marais.', },
    {'Rapporter la présence des empreintes suspectes à l\'auberge du Repos ombragé au capitaine Vimaire à Theramore.', },
  },
  [1285] = {
    '[PÉRIMÉ]Les hommes de Daelin',
    {'Reddon… Mmm Senterouge non, je suis allé trop loin… Ah voilà ! Lieutenant Paval Reethe.|n|nA rejoint la garde de Theramore en même temps que la plupart des recrues ayant fait la traversée avec dame Portvaillant. Engagé dans les soldats de marine de Kul Tiras à seize ans. États de service brillants, promu... |n|nPorté disparu.', },
    {'Ramener l\'information concernant Reethe au capitaine Vimaire à Theramore.', },
  },
  [1286] = {
    '[PÉRIMÉ]Les déserteurs',
    {'Nous avons lutté pour maintenir notre présence dans les marais, et grâce à notre détermination, nous avons pu conserver plusieurs tours de garde défensives dans le secteur.|n|nLes dernières informations et rapports d\'éclaireurs que j\'ai reçus indiquent qu\'un groupe de déserteurs squatte une tour abandonnée à la Halte perdue, au sud-est de l\'auberge.|n|nLe lieutenant local est apparemment Balos Jacken. Voyez si vous pouvez lui soutirer des informations.|n|nSoyez sur vos gardes, $N. Il risque d\'être réticent à collaborer.', },
    {'Obtenir des informations sur Reethe de Balos Jacken et des déserteurs dans le marécage d\'Âprefange.', },
  },
  [1287] = {
    '[PÉRIMÉ]Les déserteurs',
    {'Reethe ? Ce lâche ?|n|nNous l\'avons éjecté du camp, car il insistait pour aller piller le ravitaillement des ogres de Mur-de-Fougères. Nous ne sommes pas suffisamment nombreux pour faire face à ces brutes sans cervelle.|n|nIl a franchi trop de fois les limites, alors nous l\'avons envoyé paître.|n|nBon, je vous ai $Gaidé:aidée;... Alors aidez-moi à votre tour en oubliant que vous nous avez trouvés !', },
    {'Parler au Capitaine Garran Vimaire à Theramore à propos de Reethe.', },
  },
  [1288] = {
    'Rapport de Vimaire',
    {'Vous avez fait du bon travail, $N, le meilleur que j\'ai vu de la part de quelqu\'un qui n\'est pas de chez nous.|n|nDame Portvaillant a demandé que je la tienne informée de cette situation délicate et je ne lui ai pas parlé depuis longtemps.|n|nJe m\'apprêtais à lui envoyer mon rapport, mais il me semble plus approprié que cela soit vous qui lui parliez. Vous répondrez mieux à ses questions que moi.', },
    {'Donnez le Rapport de Vimaire à Dame Jaina Portvaillant à Theramore.', },
  },
  [1289] = {
    '<nyi> Rapport de Vimaire',
    {'Bien, d\'après ce que je déduis du rapport du capitaine Vimaire, vous avez été d\'une aide capitale dans ces investigations, et de cela je vous remercie.|n|nJe peux avoir l\'esprit en paix sachant que vous vous occupez de ce problème. Si vous acceptez, je vous suggère de retourner voir le capitaine Vimaire et de l\'aider à résoudre l\'affaire.', },
    {'Retourner voir le capitaine Garran Vimaire à Theramore.', },
  },
  [1290] = {
    '<nyi> Enquête sur Mosarn',
    {'Parler au Garde Komak. Poser des questions est mauvais pour votre santé.', },
    {'On parle.', },
  },
  [1301] = {
    '[PÉRIMÉ]James Hyal',
    {'Avant de travailler ici, au Solitaire bleu, j\'ai été formé par l\'un des meilleurs chefs cuisiniers et aubergistes que je connaisse. Il s\'appelait James Hyal. Tout ce que j\'ai et tout ce que j\'ai appris, je le lui dois.|n|nJe me demande ce qu\'il devient. Son frère Vincent et lui sont allés travailler dans une auberge du port de Menethil, mais je suis sans nouvelles depuis longtemps.|n|nSi vous passez dans le coin, donnez-lui le bonjour de ma part, d\'accord ?', },
    {'Allez voir Vincent Hyal au Port de Menethil.', },
  },
  [1302] = {
    '[PÉRIMÉ]James Hyal',
    {'Mon frère James a accompagné dame Portvaillant lorsqu\'elle a traversé les océans. Les dernières nouvelles disaient que le calme était revenu là-bas et que James avait monté une auberge quelque part sur le continent. Où qu\'il soit, je suis sûr que ses affaires sont florissantes. C\'est un excellent chef cuisinier !|n|nJe suis sans nouvelles de lui depuis un bon moment. Trop de travail avec son auberge, je suppose. Mais le greffier à Theramore a peut-être plus de renseignements. Cherchez-le en haut de ce donjon près du centre de la ville. Comment s\'appelle-t-il déjà... Ah oui, la Citadelle de Theramore.', },
    {'Parler au greffier Lendry à la citadelle de Theramore.', },
  },
  [1318] = {
    'Affaires inachevées chez les Gordok',
    {'Maintenant qu\'z\'êtes le roi, p\'têt\' qu\'vous pourrez récupérer l\'objet précieux des Gordok que le sale elfe qui se dit prince nous a pris. L\'roi avant vous a pas réussi, et celui d\'avant non plus, et aucun roi depuis que Tortheldrin – c\'est le sale elfe – l\'a volé à un vieux roi gordok d\'il y a longtemps !|n|nC\'est le gantelet de puissance gordok. Les vieux, ils disent que seul le vrai roi des Gordok pourra le ramener. Et puis, les vieux, ils disent aussi que le sale elfe est toujours là – si vous le trouvez, vous pourrez porter le gantelet de puissance pour toujours ! Ouais ! Je vais vous montrer !', },
    {'Trouvez le Gantelet de puissance gordok et rendez-le au Capitaine Kromcrabouille à Hache-Tripes.|n|nSelon Kromcrabouille, les histoires des « vieux » racontent que Tortheldrin – un « vilain » elfe qui se fait appeler prince – l\'a volé à l\'un des rois gordok.', },
  },
  [1319] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Je suis désolé de ne pouvoir vous en dire plus, $N, mais je sais qui peut vous aider. Caz Bi-Douille, un de nos meilleurs forgerons. Portez-lui le bouclier et voyez ce qu\'il peut vous dire.', },
    {'Montrer le Bouclier en fer noirci à Caz Bi-Douille à Theramore.', },
  },
  [1320] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Ah ! J\'ai failli manquer ceci… La lanière de cuir au dos a dû brûler, mais on dirait qu\'elle avait été faite pour un grand gabarit. Je dirais même un tauren.|n|nC\'est tout ce que je peux dire. Dites au capitaine Vimaire que je suis désolé de n\'avoir pas pu l\'aider davantage.', },
    {'Discuter avec le capitaine Garran Vimaire à Theramore.', },
  },
  [1321] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Hmmm… Je ne vois rien qui sorte de l\'ordinaire à propos de ce bouclier. Demandons à Do\'gol, le forgeron, de l\'examiner, puis écoutons ce qu\'il peut nous dire, mais n\'espérons pas trop…', },
    {'Montrer le Bouclier en fer noirci à Do\'gol au village de Mur-de-Fougères.', },
  },
  [1322] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Hmmm ! Il y a quelque chose d\'écrit sur le bord du bouclier, c\'est dur à lire avec toutes ces traces de suie.|n|nJ\'ai besoin d\'acide pour le faire apparaître. Du venin d\'araignée de Sombrebrume, ça ira. Les araignées ont envahi une vieille mine, la Caverne de Sombrebrume, au nord-ouest du village. Rapportez-moi quelques glandes et je vous nettoie ça.', },
    {'Trouver 5 Sacs de Venin acide pour Do\'gol de Mur-de-Fougères.', },
  },
  [1323] = {
    '[PÉRIMÉ]Le Bouclier noir',
    {'Oh ! Je crois que j\'ai mis trop d\'acide sur le bouclier. Frottons un peu pour voir…|n|nHmm, difficile à lire, mais je crois que c\'est un nom : Mosarn. Jamais entendu parler de lui. Peut-être Krog le saura. Krog connaît tellement de monde.', },
    {'Parler à Krog au village de Mur-de-Fougères.', },
  },
  [1324] = {
    'Un diplomate a disparu',
    {'Quoi ? Vous venez m\'accuser d\'être allié aux Défias et vous pensez que je vais rester là tranquillement alors que vous êtes en train de m\'insulter ? Quelque chose me dit que vous pensez à cela depuis longtemps.', },
    {'Battre le soldat Hendel dans le marécage d\'Âprefange.', },
  },
  [1338] = {
    'La mission de Foudrepique',
    {'Il y a un forgeron nain dont j\'admire beaucoup le travail. Il s\'appelle Furen Barbe-longue et ses compétences sont inégalables. J\'ai besoin d\'un nouveau bouclier et je veux l\'un des siens !|n|nLe problème… Furen est loin dans le sud, dans le quartier des Nains de Hurlevent. Chez les humains ! Je ne comprends pas pourquoi il vit là-bas, si loin de Forgefer. Les humains doivent lui faire un pont d\'or pour qu\'il accepte de rester !|n|nSi vous avez envie de voyager, et ne pensez pas à demander une récompense, alors pourquoi ne porteriez-vous pas ma commande de bouclier à Furen ?', },
    {'Portez la commande de Foudrepique à Furen Barbe-longue à Hurlevent.', },
  },
  [1339] = {
    'La mission du Montagnard Foudrepique',
    {'J\'ai entendu dire que le montagnard Foudrepique a besoin d\'un coursier. Quelqu\'un pour voyager à sa place. Qu\'en pensez-vous, $R ? Êtes-vous capable de ce travail ?|n|nSi c\'est le cas, vous trouverez Foudrepique au sommet de la tour de garde la plus au nord.', },
    {'Parler au Montagnard Foudrepique.', },
  },
  [1358] = {
    'Un échantillon pour Helbrim',
    {'Un collègue de Kalimdor, l\'apothicaire Helbrim, étudie les effets des toxines de Lordaeron sur les animaux de Kalimdor. Il serait très intéressé par un échantillon de cœurs de loups que Renferrel m\'a envoyés.|n|nHelbrim se trouve dans les Tarides, dans un village connu sous le nom de la Croisée. Pour le rejoindre, vous voyagerez par zeppelin jusqu\'à Orgrimmar, la capitale des orcs, puis à pied vers le sud en Durotar. Allez à l\'ouest, dans les Tarides, et vous trouverez rapidement la Croisée.', },
    {'Apportez l\'échantillon de cœur de loup à l\'Apothicaire Helbrim dans les Tarides.', },
  },
  [1359] = {
    'Une livraison pour Zinge',
    {'Les cœurs de loups que vous avez là possèdent une qualité inouïe pour ces spécimens. Ils possèdent une toxicité telle qu\'elle tuerait net les loups vivants !|n|nC\'est fascinant, il faut approfondir l\'étude. J\'ai gardé quelques échantillons de ces cœurs. Apportez-les à ma collègue, l\'Apothicaire Zinge. Vous la trouverez dans notre quartier général à Fossoyeuse.', },
    {'Apportez les Échantillons de cœurs de loups à l\'Apothicaire Zinge à Fossoyeuse.', },
  },
  [1360] = {
    'Des Trésors à recouvrer',
    {'J\'avais un bon travail de terrassier à l\'excavation d\'Uldaman dans les Terres ingrates… jusqu\'à ce que ces sacrés troggs arrivent. J\'ai à peine réussi à sauver ma peau, rien d\'autre. Dans la panique, j\'ai laissé mon plus précieux bien. Il se trouve dans mon coffre, donc à l\'abri des troggs, mais au beau milieu d\'eux.|n|nVous auriez toute ma gratitude, en honneur et en or, si vous pouviez me le rapporter. Il y a un coffre portant mon nom au bout du hall commun nord. C\'est là qu\'il faut aller.', },
    {'Récupérer les biens de Krom Rudebras dans son coffre dans le hall commun nord d\'Uldaman et les lui rapporter à Forgefer.', },
  },
  [1361] = {
    'Regthar Seuil-de-mort',
    {'Un guerrier de la Horde, Regthar Seuil-de-mort, recrute des agents pour une mission dans les terres de Désolace. Allez lui parler si vous souhaitez vous porter volontaire. Il se trouve dans les Tarides, dans une série de fortins situés à l\'ouest de la Croisée.|n|nEt aiguisez vos armes. Désolace est ravagée par la guerre.', },
    {'Discuter avec Regthar Seuil-de-mort.', },
  },
  [1362] = {
    'Les Kolkars de Désolace',
    {'Les centaures kolkars vivent en Désolace et leurs forces sont disséminées dans toutes les Tarides. Il est de notoriété publique que des agents de la Horde s\'occupent d\'eux.|n|nMais tant que les centaures seront puissants en Désolace, ils resteront une menace. Il est temps de nous en débarrasser.|n|nParlez à Felgur Doublecoupe au poste de Rôdeur-fantôme en Désolace. Il y a été envoyé pour réunir des informations sur les centaures. Il saura comment faire au mieux avec les Kolkars de Désolace.', },
    {'Discuter avec Felgur Doublecoupe au poste de Rôdeur-fantôme en Désolace.', },
  },
  [1363] = {
    'Les ordres de Mazen',
    {'En tant que conservateur de la bibliothèque de l\'Académie des arts et sciences des arcanes, il est de ma responsabilité de m\'assurer que tous les livres magiques et les parchemins sont bien présents. Qui sait quelle folie pourrait survenir si l\'un de ces textes enchantés tombait entre de mauvaises mains ?|n|nCela me fait penser : mon assistant, Dellis, a fait une terrible erreur la semaine dernière. Il est parfaitement à l\'aise dans la bibliothèque, mais parfaitement incompétent dès qu\'il franchit les portes de Hurlevent. Soyez un exemple de ce temps et allez aider le vieux Dellis, voulez-vous ?', },
    {'Parler à l\'acolyte Dellis à Hurlevent.', },
  },
  [1364] = {
    'Les ordres de Mazen',
    {'Les ordres de maître Mazen sont très clairs : porter d\'importants essais au gardien Mahar Ba au Rempart-du-Néant.|n|nMais je n\'ai jamais été dans les terres Foudroyées avant ! C\'est terrifiant !|n|nDans le marais des Chagrins, j\'ai pris un mauvais chemin et j\'ai fini cerné par d\'horribles créatures à moitié végétales. Elles bougeaient comme si elles voulaient m\'attaquer, alors j\'ai fui. Mais dans ma hâte, j\'ai laissé tomber les papiers. Un des monstres les a pris, j\'en suis sûr.|n|nPourriez-vous les retrouver s\'il vous plaît et les porter à Mahar Ba ?', },
    {'Retrouver les Essais de Khadgar sur la convergence dimensionnelle et les porter au Gardien Mahar Ba au Rempart-du-Néant.', },
  },
  [1365] = {
    nil,
    {'Les Kolkars ne sont pas les seuls centaures de Désolace. De nombreux clans parcourent ces plaines sèches, combattant et mourant. Il est heureux qu\'ils se battent entre eux, car ils sont forts et brutaux. Si les centaures s\'unissaient contre nous, ils seraient un adversaire redoutable.|n|nNous devons nous occuper d\'eux avant qu\'ils ne s\'allient.|n|nVotre première mission est de désorganiser le clan Kolkar. Vous y parviendrez en tuant son chef, le khan Dez\'hepah.|n|nLe village des Kolkars est au nord-est. Allez, et puisse la fortune vous sourir !', },
    {'Rapporter la Tête du khan Dez\'hepah à Felgur Doublecoupe en Désolace.', },
  },
  [1366] = {
    'La prime aux centaures',
    {'Maintenant que vous avez terrifié les clans centaures, il est temps de les saigner. Lorsque vous voyagerez à travers Désolace, chassez-les. Je me moque de savoir à quel clan ils appartiennent. Vous devez juste collectionner les oreilles. Je veux un monceau d\'oreilles !|n|nEn diminuant leur nombre vous porterez un coup à leur résolution et sonnerez le glas de leurs envies d\'expansion.|n|nBonne chasse, $N.', },
    {'Apporter 15 Oreilles de centaure à Felgur Doublecoupe, en Désolace.', },
  },
  [1367] = {
    'L\'alliance avec les Magram',
    {'Pour battre les centaures, nous allons utiliser leur haine contre eux. Nous allons nous allier à l\'un des clans, et par ce biais nous apprendrons comment battre les autres clans.|n|nSi vous décidez de vous allier aux Magram, alors tuez leurs ennemis, les Gelkis. Vous gagnerez ainsi le respect des Magram. Lorsque cela sera fait, alors allez rencontrer Warug, le porte-parole des Magram, dans les faubourgs du village des Magram au sud-est de Désolace.', },
    {'Faire en sorte que les Magram soient Amicaux envers vous, puis aller parler à Warug.', },
  },
  [1368] = {
    'L\'alliance avec les Gelkis',
    {'Pour battre les centaures, nous allons utiliser contre eux leur haine fratricide. Nous allons nous allier à l\'un des clans, et par ce biais, nous apprendrons comment vaincre les autres clans.|n|nSi vous décidez de vous allier aux Gelkis, alors tuez leurs pires ennemis, les Magram. Après avoir gagné le respect des Gelkis, allez rencontrer le chaman Uthek la Sage dans les environs du village des Gelkis, au sud-ouest de Désolace.', },
    {'Faire en sorte que les Gelkis deviennent Amicaux envers vous, puis aller parler à Uthek la Sage.', },
  },
  [1369] = {
    'Larmes brisées',
    {'Les Gelkis pensent que Theradras, la mère des centaures, nous protège. Ils sont idiots. Personne ne protège les centaures. Les centaures n\'ont pas besoin de protection ! Les Magram n\'ont pas besoin de protection ! Nous sommes les plus forts !|n|nMontrez aux Gelkis qu\'ils sont stupides. Allez dans la caverne de leur village. Ils y possèdent des cristaux, les Larmes de Theradras. Détruisez ces cristaux et rapportez-moi les morceaux.', },
    {'Maintenir votre réputation auprès des Magram et ramener 3 Larmes brisées à Warug au village des Magram.', },
  },
  [1370] = {
    'Voleur de viande',
    {'Lorsque nous ne sommes pas en guerre, nous chassons pour trouver de la viande. La viande nous donne la force et des ventres remplis se battent mieux que des ventres vides.|n|nC\'est la même chose chez les Magram. Ils gardent la viande en trop afin de se battre plus longtemps entre leurs chasses. Si vous attaquez leur village à l\'est et prenez leurs réserves de viande, leur force va diminuer.', },
    {'Rapporter 6 Sacs de viande grossièrement séchée à Uthek la Sage au village des Gelkis.', },
  },
  [1371] = {
    'Un bidule pour Warug',
    {'Il y a longtemps, un petit gnome est venu en Désolace. Il avait des chevaux et une carriole qui contenait des choses étranges. De drôles de choses. Des choses qui brûlaient de différentes couleurs. Des choses qui bougeaient, mais n\'étaient pas vivantes. J\'ai tué le petit gnome mais avant cela... Il m\'a fait rire.|n|nJ\'ai gardé ma chose préférée de sa carriole. C\'était un humain en bois qui me faisait signe jusqu\'à ce que je le tape et que je le casse.|n|nJ\'en veux un nouveau !', },
    {'Maintenir votre réputation auprès des Magram et rapporter un Leurre perfectionné à Warug au village des Magram en Désolace.', },
  },
  [1372] = {
    'La vérité, rien que la vérité',
    {'Notre force expéditionnaire a été envoyée sur les ordres de Varimathras pour surveiller le bas-Azeroth.|n|nPendant une reconnaissance, j\'ai remarqué un infiltrateur humain qui espionnait le repaire des Mendiants. Avant que je ne puisse l\'attraper, certains de nos... frères orcs l\'ont capturé et emmené à Pierrêche, leur forteresse dans le marais des Chagrins.|n|nJe veux… aider… nos alliés, les orcs. Ils n\'ont pas vu notre camp, mais malgré cela, je veux les aider.|n|nTravaillez avec Faustin pour développer… un sérum de vérité pour notre ami, à Pierrêche.', },
    {'Parler à l\'Apothicaire Faustin, au Repaire des Mendiants.', },
  },
  [1373] = {
    nil,
    {'Vous avez encore à prouver des choses et votre prochaine mission vous emmènera loin, car maintenant les Gelkis vont combattre les Magram sans vous.|n|nLa terre chuchote bien des secrets à ceux qui savent écouter. Un des secrets que j\'ai appris est qu\'il existe un cristal rouge appelé draenéthyste, nouvellement arrivé sur notre terre. Il vient d\'un endroit où les montagnes volent et où les démons règnent.|n|nApportez-moi un éclat de draenéthyste et ma magie grandira ! Le cristal se cache dans un endroit appelé le marais des Chagrins, et appartient à un Perdu, Ongeku.', },
    {'Maintenez votre réputation auprès des Gelkis et rapportez un Éclat de draenéthyste à Uthek la Sage au Village des Gelkis, en Désolace.', },
  },
  [1374] = {
    nil,
    {'La terre me parle et me dit que les Magram sont de plus en plus faibles. Il est maintenant temps de tuer leur khan !|n|nRapportez-moi la tête de Jehn, le khan des Magram !', },
    {'Apportez la Tête du khan Jehn à Uthek la Sage au village des Gelkis, en Désolace.', },
  },
  [1375] = {
    nil,
    {'Vous avez aidé les Magram et je vous apprécie. Maintenant tuez le khan des Gelkis ! Il s\'appelle Shaka et je veux sa tête ! Je veux la regarder et me moquer de lui !', },
    {'Maintenez votre réputation parmi les Magram et rapportez la Tête du khan Shaka à Warug au village des Magram, en Désolace.', },
  },
  [1380] = {
    nil,
    {'Vous nous avez aidés contre les Magram, $N. À présent, aidez-nous à battre le clan des Maraudine ! Tuez leur chef, le khan Hratha !|n|nPour le combattre, soufflez dans la corne de guerre maraudine. Elle se trouve au sommet d\'un grand promontoire, dans la vallée des Lances.|n|nMais pour souffler dans la corne, vous devez d\'abord obtenir une embouchure de corne de guerre. Elles sont rares, et portées uniquement par des Maraudine de confiance.|n|nQuand vous aurez soufflé dans la corne, des centaures arriveront. Tuez-en jusqu\'à ce que Hratha apparaisse.|n|nLe khan Hratha porte un fragment de... clé. Apportez-le-moi...', },
    {'Maintenez votre réputation auprès des Gelkis, et apportez le Fragment de clé des Maraudine à Uthek la Sage, au Village des Gelkis.', },
  },
  [1381] = {
    nil,
    {'Le khan des Gelkis est mort, et à présent le clan Maraudine va tomber ! Tuez le khan des Maraudine, Hratha.|n|nPour le combattre, soufflez dans la Corne sur le grand promontoire de la Vallée des lances. Mais pour y souffler, vous aurez besoin d\'une embouchure. Pour l\'obtenir, tuez des centaures Maraudine. Tuez jusqu\'à ce que vous la trouviez. Puis soufflez dans la corne.|n|nAgissez ainsi et les centaures Maraudine viendront à la tour. Tuez-en jusqu\'à ce que le khan Hratha apparaisse. Il détient un fragment de clé. Apportez-moi ce fragment...', },
    {'Maintenez votre réputation auprès des Magram, et apportez le Fragment de clé des Maraudine à Warug au village des Magram, en Désolace.', },
  },
  [1382] = {
    'Une étrange alliance',
    {'Nous avons de la chance que les clans de centaures se battent entre eux, car s\'ils unissaient leurs forces, rien ne pourrait les arrêter. Oui, nous sommes chanceux, et nous devrions mettre à profit cet avantage.|n|nL\'un des clans de centaures, le clan Gelkis, mène une guerre acharnée au clan Magram. Si nous attaquons ce second clan, alors nous pourrions peut-être conclure une alliance avec les Gelkis.|n|nAllez parler à Uthek la Sage, aux approches des campements gelkis, au sud-ouest de Désolace. Grâce à elle, vous pourrez peut-être conclure une alliance avec le clan Gelkis.', },
    {'Faire en sorte que les Gelkis deviennent Amicaux envers vous, puis aller parler à Uthek la Sage.', },
  },
  [1383] = {
    'La vérité, rien que la vérité',
    {'Je pense avoir trouvé la composition du sérum qu\'il nous faut. Il s\'occupera de la vérité exactement comme il convient. Pour cette préparation, je vais avoir besoin de beaucoup de cœurs de panthères des ombres, en provenance du marais. J\'aurai également besoin d\'un champignon de boueux enchanté, de la réserve personnelle du seigneur du bourbier local. Il est certain que quelqu\'un d\'aussi talentueux que vous, $N, peut le persuader de s\'en séparer.|n|nLa dernière chose dont j\'aurai besoin pour le sérum, c\'est du sang d\'un dragonnet rêveur, comme ceux qui vivent à côté de la caverne d\'Itharius dans le marécage.|n|nAllez-y à présent !', },
    {'L\'apothicaire Faustin, du Repaire des Mendiants, a besoin de 5 Cœurs de panthère des ombres, d\'un Champignon de Boueux et de Sang de dragonnet vert.', },
  },
  [1384] = {
    'Raid sur les Kolkars',
    {'Les Kolkars estiment que leur magie est puissante. Ils ne connaissent rien à la magie ! Ils ne reconnaîtraient même pas la magie si elle les frappait !|n|nVous allez leur montrer que leur magie est faible. Allez chez les centaures kolkars au nord-est, et tuez-les. Détruisez leurs camps. Apportez-moi leurs charmes, que je les jette au feu et que je rie !', },
    {'Maintenir votre réputation auprès des Gelkis, et apporter 10 Charmes bruts à Uthek la Sage dans le village des Gelkis, en Désolace.', },
  },
  [1385] = {
    'Une violente politique',
    {'Désolace est une terre en guerre. Les centaures se font la guerre les uns les autres. Nous pensons que les vainqueurs vont surgir et menacer nos forteresses, ce que nous ne pouvons permettre.|n|nNous devons apprendre comment battre les centaures, et pour cela nous devons nous allier à l\'un des clans. Les centaures Magram sont en guerre contre les Gelkis. Si vous combattez les centaures Gelkis, alors les Magram pourraient envisager une alliance.|n|nGagnez les faveurs des Magram, puis parlez à Warug, au village des Magram, au sud-est de Désolace.', },
    {'Faire en sorte que les Magram soient Amicaux envers vous, puis aller parler à Warug.', },
  },
  [1386] = {
    'Assaut sur les Kolkars',
    {'Les centaures kolkars pensent qu\'ils sont forts, mais nous rions de leur force ! Nous rions d\'eux et nous les tuons ! Vous les tuez aussi. Montrez-moi que vous pouvez tuer des centaures kolkars comme nous les tuons. Allez vers le nord et massacrez-les tous !', },
    {'Maintenir votre réputation auprès des Magram, tuer 12 Centaures kolkars, 12 Éclaireurs kolkars, 6 Marteleurs kolkars, puis retourner voir Warug, dans le village des Magram, en Désolace.', },
  },
  [1387] = {
    'La prime aux centaures',
    {'Le peuple des centaures est divisé en nombreux clans. Chaque clan a son chef et ses propres buts, mais ils ont tous une « qualité » en commun : la cruauté.|n|nSi nous voulons avoir une chance de construire la paix, alors les centaures doivent être éradiqués. C\'est exactement la tâche que je vous confie.|n|nPendant que vous serez en Désolace, chassez des centaures et prenez leurs oreilles. Apportez-moi de nombreuses, très nombreuses oreilles.|n|nŒuvrez au service de l\'Alliance, $N, et nous nous rapprocherons de la fin de la guerre.', },
    {'Apporter 15 Oreilles de centaures au caporal Melkins, à la combe de Nijel, en Désolace.', },
  },
  [1388] = {
    'La vérité, rien que la vérité',
    {'Tout se déroule selon le plan, $N. Je veux que vous remettiez ce sérum de vérité au nécrotraqueur Zraedus et il vous montrera comment l\'administrer… proprement.|n|nHa ! Ha !', },
    {'Remettre le Sérum de vérité de Faustin au Nécrotraqueur Zraedus au Repaire des Mendiants.', },
  },
  [1389] = {
    '[PÉRIMÉ]Les cristaux de draenéthyste',
    {'Les Perdus qui vivent dans le Sanctuaire des friches nous ressemblent physiquement, mais ce sont des monstres… rendus fous par les rigueurs de notre voyage vers Azeroth. Nos anciens frères attrapent et tuent quiconque s\'approche du Sanctuaire des friches, à l\'est.|n|nEt ils nous ont volé quelque chose de sacré à nos yeux : des cristaux de draenéthyste.|n|nNous n\'avons pas la force suffisante pour pénétrer dans le Sanctuaire des friches et reprendre nos draenéthystes volées dans leurs huttes et près des feux de camp. Mais sans ces cristaux... nous pourrions également perdre la voie, tout comme eux.', },
    {'Apporter 6 Cristaux de draenéthyste à Magtoor au Havre boueux du marais des Chagrins.', },
  },
  [1390] = {
    '<nyi> Oups, on les a encore tués !',
    nil,
    nil,
  },
  [1391] = {
    'La vérité, rien que la vérité',
    {'Nous devons procéder avec une certaine discrétion. Après tout, ce n\'est pas comme si vous alliez danser la valse là-bas et convaincre un imbécile de boire la préparation de Faustin, pas vrai ?|n|nMais il y a une chose à laquelle les humains ne savent pas dire non, c\'est l\'alcool. Je prendrai le sérum de Faustin et le verserai dans de la bière. Je peux garantir que le pauvre type n\'hésitera pas à la siffler d\'un trait.|n|nHâtez-vous vers Pierrêche, dans le marais des Chagrins, $N.|n|nEt faites en sorte que notre petite mission reste secrète et sans accroc...', },
    {'Apporter la Bière de Zraedus à l\'Infiltrateur Marksen à Pierrêche.', },
  },
  [1392] = {
    'Noboru le Gourdin',
    {'Noboru a harcelé les draeneï du Havre boueux pendant des mois, et son gourdin est le symbole de la brutalité qu\'ils ont subi de la part de ceux qu\'ils ont perdus.', },
    {'Apporter le Casse-tête de Noboru au Chef du Havre boueux dans le marais des Chagrins.', },
  },
  [1393] = {
    'L\'évasion de Galen',
    {'Au secours ! Ces créatures vont me manger !|n|nSortez-moi de là, et je vous donnerai un grand trésor ! Il est dans mon camp, dans le marais au nord de Pierrêche, mais il est enfermé dans un coffre qui ne peut être ouvert que grâce à un truc que moi seul connais.|n|nSi vous m\'aidez à m\'en sortir, alors je vous l\'enseignerai.', },
    {'Escorter Galen jusqu\'à ce qu\'il soit hors de danger, puis trouver son camp dans le marais des Chagrins et ouvrir son coffre.', },
  },
  [1394] = {
    'Le dernier voyage',
    {'Vous avez bien œuvré, $N. Vous avez réussi mon test, et les tests d\'avant. Retournez voir Dorn aux Mille pointes. Il ressentira le changement qui s\'est opéré en vous, et constatera que votre cerveau, votre corps et votre esprit sont suffisamment forts pour que vous soyez $Grécompensé:récompensée; de vos efforts.|n|nRestez fidèle à l\'équilibre que vous avez montré durant ces épreuves, $N. Dorn vous testera à nouveau dans l\'avenir si vous le faites.', },
    {'Parler à Dorn Traqueur-des-plaines aux Mille pointes.', },
  },
  [1395] = {
    'Fournitures pour Rempart-du-Néant',
    {'Cette caisse de pierres de puissance doit être livrée au Rempart-du-Néant, dans les terres Foudroyées. Elles ne vont pas conserver leur pouvoir longtemps, aussi nous ne pouvons pas les envoyer par la prochaine caravane.|n|nVous devez les emporter, et vous devez les emporter rapidement.|n|nApportez-les à l\'intendant Lungertz au Rempart-du-Néant. Pour atteindre le donjon, vous devez voyager vers l\'est, à travers le défilé de Deuillevent, puis à l\'est à travers le marais des Chagrins, et enfin vers le sud à travers les terres Foudroyées.|n|nFaites attention, $N. Vous allez traverser des endroits dangereux, mais vous n\'avez pas le droit d\'échouer.', },
    {'Apportez la Caisse de Pierres de puissance à l\'Intendant Lungertz, avant que le pouvoir des pierres n\'expire.', },
  },
  [1396] = {
    '[PÉRIMÉ]Des créatures sauvages rôdent',
    {'Ma caravane avait pour destination la côte est. Mais nous ne l\'avons pas atteinte. Les Perdus nous ont attaqués, tuant les gardes et volant des marchandises.|n|nMoi seul ai survécu à l\'assaut. J\'ai juré de protéger les marchandises restantes, mais des créatures sauvages rôdent dans les alentours. Je vous en prie, aidez-moi à défendre mon campement contre ces bêtes !', },
    {'Tuer 8 Jeunes crocilisques dents-de-scie, 10 Tisseuses des pleurs et 10 Jaguars du marécage, puis retourner voir le Gardien Biggs, dans le marais des Chagrins.', },
  },
  [1397] = {
    '<nyi> Sauvé !',
    nil,
    nil,
  },
  [1398] = {
    nil,
    {'Je vous dois beaucoup, $N. Un cœur noble bat en vous. J\'ai à présent une autre tâche pour laquelle je demanderai humblement votre aide.|n|nSi je veux avoir la moindre chance d\'atteindre Rempart-du-Néant, alors je dois réparer mon chariot. Et pour cela, j\'ai besoin de bois. Du bois fort, du bois sec, pas de ce bois spongieux et noueux des arbres du marais.|n|n$N, partez à l\'est pour la côte et cherchez du bois qui a séché au soleil. Et apportez-le-moi.', },
    {'Apporter 8 Morceaux de Bois séché au soleil au Gardien Biggs dans le marais des Chagrins.', },
  },
  [1418] = {
    'Neeka Balafre-sanglante',
    {'Les Terres ingrates sont une région difficile, en bordure du Loch Modan, un territoire aux mains de l\'Alliance. Aussi, la liaison entre Pierrêche et Kargath, l\'avant-poste des Terres ingrates, est-elle souvent interrompue.|n|nMontrez votre valeur, $N. Partez pour les Terres ingrates et parlez à Neeka Balafre-sanglante, éclaireur principal de l\'avant-poste de Kargath. Parlez-lui, puis envoyez-moi son rapport.', },
    {'Parler à Neeka Balafre-sanglante.', },
  },
  [1419] = {
    'Les coyotes voleurs',
    {'Avez-vous passé beaucoup de temps dans les Terres ingrates, $C ? Avez-vous ressenti la chaleur ? Avez-vous affronté les bêtes qui rôdent dans les plaines poussiéreuses ? Il est temps que vous le fassiez.|n|nLes coyotes des rochers sont une espèce robuste. Robuste, et suffisamment intrépide pour s\'aventurer jusqu\'à Kargath et chaparder de la nourriture. Aidez-nous à débarrasser l\'avant-poste de ces pique-assiettes !|n|nChassez les coyotes des rochers, $N. Chassez-les et apportez-moi leurs mâchoires. Apportez-en assez, et peut-être que je vous croirai lorsque vous dites que vous connaissez les Terres ingrates.', },
    {'Apporter 30 Mâchoires de coyotes à Neeka Balafre-sanglante à Kargath.', },
  },
  [1420] = {
    'Le rapport à Helgrum',
    {'J\'ai écrit un rapport tout frais pour Helgrum à Pierrêche. Remettez-le-lui.|n|nEt si vous vous considérez comme une bonne estafette, alors ne vous perdez pas. Et ne tombez pas aux mains de l\'ennemi.', },
    {'Apporter le Rapport de Neeka à Helgrum l\'Agile à Pierrêche.', },
  },
  [1421] = {
    '[PÉRIMÉ]Le chariot perdu',
    {'J\'ai perdu connaissance durant l\'attaque des Perdus, mais avant que tout ne s\'obscurcisse, j\'ai vu l\'un de nos chariots en train d\'être traîné vers le sanctuaire des Friches, le village des Perdus, au nord.|n|nUn coffre plein d\'ingrédients de valeur se trouvait dans ce chariot. Ces ingrédients sont d\'un intérêt scientifique vital pour les sorciers de Rempart-du-Néant. Retrouvez ce coffre et mettez la main sur ces ingrédients, $N. Une fois que vous les aurez en votre possession, rapportez-les-moi.', },
    {'Trouver le Coffre de la Caravane, dans le Sanctuaire des Friches, obtenir les Composants pour les sorciers, et les apporter au Gardien Biggs.', },
  },
  [1422] = {
    '[PÉRIMÉ]Le danger venu des flots',
    {'Pendant que je commence à travailler sur votre arme, pourquoi n\'iriez-vous pas parler à Katar ? Il a mentionné qu\'il aurait besoin d\'aide pour patrouiller le long de la plage, et je vous imagine mieux gardant vos esprits et vos armes en alerte que vous saoulant en compagnie des autres poux avec qui je partage ce camp.', },
    {'Parler à Katar, dans le marais des Chagrin.', },
  },
  [1423] = {
    'Les marchandises perdues',
    {'Ce tonneau, bien que petit, est robuste. Il est scellé avec une cire jaune à l\'odeur âcre. On peut lire, tamponné au cul du tonneau :|n|nINTENDANT LUNGERTZ|n|nREMPART-DU-NEANT.', },
    {'Apportez les Marchandises perdues à l\'Intendant Lungertz.', },
  },
  [1424] = {
    '[PÉRIMÉ]Le bassin des larmes',
    {'Le chef de guerre nous a envoyés enquêter sur des événements étranges survenus au temple d\'Atal\'Hakkar.|n|nLes trolls Atal\'ai sont une tribu d\'ensorceleurs noirs connus pour utiliser des magies interdites. Vous pouvez imaginer notre étonnement lorsque nous sommes arrivés pour découvrir que le temple avait été englouti.|n|nÀ présent, les dragons verts gardent le site, et ils se disent protecteurs d\'Azeroth.|n|nNous devons découvrir ce qui s\'est passé. Explorez les lieux autour du Bassin des larmes et rassemblez des artéfacts atal\'ai. Ils me permettront de reconstituer une partie du puzzle.', },
    {'Fel\'zerul à Pierrêche veut que vous rassembliez 5 Artéfacts atal\'ai.', },
  },
  [1425] = {
    '[PÉRIMÉ]La remise du chargement',
    {'Pendant que je répare ce chariot, $N, j\'ai une dernière tâche à vous confier.|n|nJ\'ai empaqueté les marchandises les plus importantes rescapées des attaques des ogres. Apportez-les au Rempart-du-Néant. Le donjon est blotti dans les collines au nord des terres Foudroyées, pour surveiller la Porte des ténèbres.|n|nPour atteindre Rempart-du-Néant, suivez la route est. À l\'embranchement, allez vers le sud dans les terres Foudroyées, puis tournez à gauche au second. Continuez à suivre la route, $N, et soyez $Gprudent:prudente;.', },
    {'Apportez la Cargaison pour Rempart-du-Néant à l\'Intendant Lungertz au Rempart-du-Néant.', },
  },
  [1426] = {
    '[PÉRIMÉ]Le danger venu des flots',
    {'Je n\'ai aucun amour pour la mer, ni pour aucune des créatures que j\'ai vu sortir de ses profondeurs. C\'est une maîtresse puissante, mais aveugle. Insensible et brutale. Cela m\'apporterait un grand plaisir de massacrer les hommes-poissons par centaines si c\'était en mon pouvoir. Mais je ressens également du plaisir à les regarder mourir de la main de quiconque obéit à la volonté de la Horde.|n|nCe qui nous amène à vous, $C. Combien pouvez-vous en massacrer ? Voudriez-vous vous mesurer à leur plus puissante espèce ?', },
    {'Tuer 10 Murlocs des marais, 10 Cracheurs des marais, 10 Dévoreurs des marais, puis retourner voir Katar dans le marais des Chagrins.', },
  },
  [1427] = {
    '[PÉRIMÉ]Le danger venu des flots',
    {'Avant que vous ne vous reposiez, parlez à nouveau à Tok\'Kar. Pendant que vous étiez $Gparti:partie;, il a terminé quelques armes. Pour récompenser l\'aide que vous nous avez apportée, il devrait vous en offrir une. Vous devriez tester sa force contre les hommes-poissons quand vous vous sentirez $Gprêt:prête;... mais seulement pour me faire plaisir.', },
    {'Parler à Tok\'Kar dans le marais des Chagrins.', },
  },
  [1428] = {
    '[PÉRIMÉ]Le danger permanent',
    {'Il me plaît de voir que votre haine pour les hommes-poissons grandit en même temps que la mienne.|n|nTrouvez-en d\'autres, le long de la plage, et lorsque vous serez $Gfatigué:fatiguée; de vous battre, revenez me voir. Nous parlerons alors d\'une récompense pour vos efforts assidus.', },
    {'Tuez 10 Cracheurs des marais, 10 Dévoreurs des marais, 10 Oracles des marais, puis retournez voir Katar dans le marais des Chagrins.', },
  },
  [1429] = {
    '[PÉRIMÉ]L\'Exilé atal\'ai',
    {'Tandis que vous braviez les dangers du Bassin des larmes, l\'un de mes éclaireurs a trouvé un vélin en peau séché, avec un texte écrit avec du sang. Cela semble être une sentence prononcée à l\'encontre d\'un prêtre de la tribu Atal\'ai.|n|nLe prêtre a été condamné à un sort pire que la mort, pour un Atal\'ai.|n|nIl a été exilé, obligé de vivre loin au nord, dans les Hinterlands, avec les trolls fanécorces.|n|nJe vais faire un paquet de ces artéfacts. Vous allez trouver l\'exilé et lui demander d\'identifier ces objets. Revenez me voir lorsque vous aurez achevé votre voyage.', },
    {'Apportez les Artéfacts atal\'ai à l\'Exilé atal\'ai dans les Hinterlands.', },
  },
  [1430] = {
    '[PÉRIMÉ]Viande fraîche',
    {'Le goût succulent de la chair de clampant est très prisé parmi mes clients. Et particulièrement celui des clampants monstrueux.|n|nSi vous comptez vous rendre sur la côte prochainement, je peux rentabiliser votre voyage : rapportez-moi quelques-unes de leurs pattes et je les expédierai à Orgrimmar.|n|nLa côte se trouve à l\'est, et vous y trouverez facilement ces créatures, détalant de-ci de-là le long des plages et dans la mer.', },
    {'Apporter 10 Pattes de clampants monstrueux à Dar dans le marais des Chagrins.', },
  },
  [1431] = {
    'Les relations de l\'Alliance',
    {'Tenez-vous tranquille, $C, et permettez-moi de partager avec vous quelque chose d\'important pour notre peuple, mais loin d\'être évident.|n|nNous sommes une race fière, et la guerre contre les humains a mis à rude épreuve même la grande patience de Thrall. Vous voyez, notre Chef de guerre est sage et prudent, et il continue à placer son peuple en premier. Il est, en fin de compte, un diplomate, et le temps qu\'il a passé avec les humains lui a appris leur façon d\'être.|n|nSi l\'histoire que je viens de commencer éveille votre intérêt, alors trouvez Keldran près de la sortie ouest de la ville. Sa masure s\'y trouve.', },
    {'Parler à Keldran à Orgrimmar.', },
  },
  [1432] = {
    'Les relations de l\'Alliance',
    {'Tandis que l\'Alliance progresse plus profondément en Kalimdor, des conclusions hâtives pourraient être tirées à propos d\'hypothétiques accords entre la Horde et la Légion ardente. Le Chef de guerre ne peut le permettre. Avec sa bénédiction, je prends le contrôle pour superviser leur anéantissement.|n|nJ\'ai des agents dans le secteur de Désolace, au Poste de Rôdeur-fantôme, au nord du grand Cimetière des kodos. Allez au sud du Val Calciné, dans les Serres-Rocheuses, vous devriez tomber dessus. Une fois sur place, allez trouver Takata Lamacier.', },
    {'Parlez à Takata Lamacier en Désolace.', },
  },
  [1433] = {
    'Les relations de l\'Alliance',
    {'Les sectateurs de la Lame ardente élaborent de nombreux plans, mais sachez qu\'ils sont foncièrement maléfiques, que leur esprit est corrompu, et que la destruction est le seul moyen de mettre un terme à leurs objectifs.|n|nKeldran a envoyé Maurin avec moi car il connaît la Lame et les méthodes des démonistes.|n|nIl supervise nos actions contre la Lame, tandis que je m\'occupe des autres dangers démoniaques ici en Désolace.|n|nParlez-lui, et il vous expliquera ses projets.', },
    {'Parler à Maurin Craquossement en Désolace.', },
  },
  [1434] = {
    'Souillé par les satyres',
    {'Une infestation démoniaque n\'arrive pas sans une aide extérieure. Quelque chose permet au Mal de prendre pied.|n|nCela peut être un esprit affaibli, tenaillé par un désir vain de pouvoir. Peut-être est-ce une soif de vengeance, ou l\'appel de la justice finale. Lorsque nous sommes assaillis par la douleur, le démon devient plus fort que nous. Un démon tel que les satyres.|n|nDes liens ont été établis entre les satyres et la Lame ardente, et Thrall souhaiterait les voir massacrés. Cherchez-les au nord-est d\'ici, et revenez me voir lorsque vous les aurez vaincus.', },
    {'Massacrer 7 Voleurs Fielfurie, 7 Gangreliges Fielfurie, 7 Traîtres Fielfurie et 7 Implorateurs de l\'enfer Fielfurie, puis retourner voir Takata Lamacier en Désolace.', },
  },
  [1435] = {
    'Esprits consumés',
    {'La mort est très désirable pour ces dégoûtantes créatures qui quittent les ordres de leur seigneur pour des raisons si égoïstes. Mais la mort n\'est pas suffisante quand on a affaire à ceux qui se sont donnés aux ténèbres.|n|nPrenez cette gemme. Lorsqu\'un membre de la Lame ardente approchera de la mort, activez sa magie. Le sort attirera l\'esprit corrompu de sa victime, laissant une gemme ardente infusée.|n|nApportez-moi ces gemmes ardentes, que je m\'en occupe comme il convient.|n|nPartez à présent, et puissiez-vous échapper à la mort.', },
    {'Apporter une Gemme ardente et 15 Gemmes ardentes infusées à Maurin Craquossement en Désolace.', },
  },
  [1436] = {
    'Les relations de l\'Alliance',
    {'La lutte se déroule bien, $N. Peut-être que le Chef de guerre nous permettra de rentrer dans nos foyers avant la fin de la saison si nous continuons à frapper de si grands coups dans notre bataille contre les démons et leurs servants.|n|nRetournez voir Keldran et faites-lui savoir ce que nous avons accompli. Il est certain qu\'il récompensera vos efforts ici. Sa cause est importante à ses yeux, et il sera fier de savoir que le Chef de guerre la respecte.', },
    {'Parler à Keldran à Orgrimmar.', },
  },
  [1437] = {
    'La recherche de Vahlarriel',
    {'Je me nomme Vahlarriel, $N. Je suis ici pour retrouver deux nobles disparus, issus d\'une famille marchande de Darnassus : la famille Malem. Le père craint le pire, et je dois tout tenter pour retrouver ses enfants disparus. J\'ai commencé mes recherches pour retrouver Tyranis ou Dalinda, mais j\'ai bon espoir que je ne serai pas ici longtemps.|n|nAux dernières nouvelles, ils passaient par les Serres-Rocheuses il y a quelques semaines.|n|nSi vous trouvez leur chariot, s\'il vous plaît, veuillez revenir ici pour m\'en informer.', },
    {'Rechercher le chariot de Tyranis et de Dalinda Malem en Désolace.', },
  },
  [1438] = {
    'La recherche de Vahlarriel',
    {'Trouvez Dalinda et Tyranis si vous le pouvez, et revenez m\'informer de vos progrès. Commencez vos recherches dans cette forteresse. Je vais immédiatement contacter mes supérieurs à Darnassus et les informer de la situation.|n|n$N, il y a quelque chose que je souhaite vous dire. Mes supérieurs ont montré quelque inquiétude à propos de Tyranis Malem et de ses raisons de venir ici. Le plus important pour eux est que Dalinda Malem soit retrouvée et ramenée en bonne santé. Nous devons... jauger Tyranis avant qu\'il ne rentre chez lui.', },
    {'Trouver Dalinda Malem en Désolace.', },
  },
  [1439] = {
    'À la recherche de Tyranis',
    {'Nous avons été emmenés ici après le massacre de nos gardes et de nos serviteurs par les orcs. Oh ! Ils leur ont fait des choses si horribles ! J\'ai cru qu\'ils allaient également nous tuer, sur place, mais ils avaient visiblement d\'autres plans.|n|nTyranis a essayé de leur parler. Je pense qu\'il voulait les impressionner par sa connaissance des arcanes... Je ne suis pas sûre de savoir pourquoi.|n|nJe vous en prie, je ne peux pas quitter les lieux tant que j\'ignore ce qu\'il est advenu de mon frère. Retrouvez-le, et venez me dire quel a été son sort.', },
    {'Trouver Tyranis Malem en Désolace.', },
  },
  [1440] = {
    'Le retour vers Vahlarriel',
    {'Ainsi, le temps est venu ? J\'apprécie vos efforts, et si la situation ne se résout pas, alors permettez-moi de vous remercier dès à présent pour tout ce que vous avez fait pour moi et ma famille. Si vous êtes $Gprêt:prête;, rien ne me retient ici. Nous pouvons partir quand vous estimerez le bon moment arrivé.', },
    {'Escorter Dalinda Malem depuis la forteresse de Hache-Tonnerre et retourner voir Vahlarriel Tueur-de-démons, en Désolace.', },
  },
  [1442] = {
    'À la recherche de la gemme de Kor',
    {'Salutations, $N. Que puis-je faire pour quelqu\'un qui suit la voie sacrée ?|n|nAh oui ! Morpuits, le forgeron… d\'il y a longtemps. Je me souviens bien de lui, mais cela fait quelque temps que je n\'ai pas entendu parler de lui.|n|nIl ne m\'a jamais paru impudent, aussi je ne peux que supposer que son désir d\'une gemme de Kor est noble.|n|nSi vous souhaitez réellement l\'une de ces gemmes, alors vous devez vous diriger vers le nord-ouest d\'Orneval. Vous y trouverez les Profondeurs de Brassenoire à l\'intérieur de ruines anciennes. Les nagas qui utilisent toujours ces gemmes se trouvent en bas. Ne partez pas $Gseul:seule;, $C.', },
    {'Apporter une Gemme de Kor à Thundris Tissevent à Sombrivage.', },
  },
  [1443] = {
    '<nyi> L\'extorsion',
    nil,
    nil,
  },
  [1444] = {
    'De retour vers Fel\'Zerul',
    {'Jammal\'an le Prophète m\'a condamné à être exilé du temple d\'Atal\'Hakkar. Je considérais autrefois que le grand prêtre était un chef digne.|n|nSa foi inflexible dans sa prophétie apportera la destruction aux Atal\'ai. Si ce n\'est pas déjà fait.|n|nLorsque j\'ai exprimé des réserves, j\'ai été traité d\'infidèle et évincé du temple.|n|nLes artéfacts que vous avez apportés sont inoffensifs. Mais si Jammal\'an a découvert le bon fétiche d\'enchantement pour le rituel d\'invocation, alors le monde court un grand péril...', },
    {'Retourner voir Fel\'Zerul à Pierrêche.', },
  },
  [1445] = {
    '[PÉRIMÉ]Le temple d\'Atal\'Hakkar',
    {'Ainsi il a parlé de la prophétie de Jammal\'an ?|n|nLe chef spirituel des Atal\'ai croit qu\'une fois Hakkar revenu du Néant pour Azeroth, le dieu accordera l\'immortalité à sa tribu.|n|nUne excuse idiote pour provoquer une fin du monde prématurée, si vous voulez mon avis.|n|nMais vous dites que l\'Exilé a parlé de fétiches enchantés ? Cela m\'inquiète profondément. S\'ils constituent la clé du rituel atal\'ai et qu\'ils sont à l\'origine de ce chaos, nous devons comprendre leurs pouvoirs intrinsèques.|n|nAventurez-vous dans le temple, et emparez-vous des fétiches.', },
    {'Rassembler 20 Fétiches d\'Hakkar et les apporter à Fel\'Zerul à Pierrêche.', },
  },
  [1446] = {
    'Jammal\'an le Prophète',
    {'Mes compagnons fanécorces n\'apprécient pas beaucoup les étrangers qui rôdent près de chez eux.|n|nMoi ? Je n\'ai plus de maison. J\'ai été exilé par mon peuple, la grande tribu des Atal\'ai du marais des Chagrins.|n|nNotre chef spirituel, Jammal\'an, avait ce qu\'il appelait une prophétie. Il pense que l\'invocation du dieu Hakkar apportera l\'immortalité à la tribu des Atal\'ai.|n|nMais j\'ai prôné la prudence. Et si cette prophétie n\'était rien d\'autre que de la manipulation ?|n|nJe veux une revanche pour mon exil. Apportez-moi la tête de Jammal\'an. Peut-être qu\'ensuite mon peuple retrouvera son libre arbitre.', },
    {'L\'Exilé atal\'ai des Hinterlands veut la Tête de Jammal\'an.', },
  },
  [1447] = {
    'Un diplomate a disparu',
    {'Ouais ! De toute évidence, vous n\'êtes pas $Gle:la:c; $C $Gle plus futé:la plus futée:c; à être $Garrivé:arrivée:c; à Hurlevent, mais vous êtes sur le point de devenir l\'$Gun:une:c; des plus stupides à n\'en jamais repartir.|n|nJe vous ai présenté mes amis ?', },
    {'Battre Dashel Poing-de-pierre à Hurlevent.', },
  },
  [1448] = {
    'À la recherche du temple',
    {'Fut un temps, j\'étais jeune et plein de vigueur comme vous, $C.|n|nMais à présent je suis vieux et incapable d\'explorer le monde comme je le faisais autrefois. Ah, les choses que j\'ai vues !|n|nMais il reste un mystère qui m\'a toujours échappé. Pour ma dernière quête, la Ligue des Explorateurs m\'a envoyé chercher le temple d\'Atal\'Hakkar. La rumeur veut qu\'il se trouve dans le marais des Chagrins.|n|nEn raison de mon état fragile, j\'ai parcouru les cieux à dos de griffon, mais je ne l\'ai jamais trouvé.|n|nPourriez-vous venir en aide à un vieux nain ? Peut-être aurez-vous plus de chance à pied.', },
    {'Brohann Ventrabière à Hurlevent veut que vous recherchiez le temple d\'Atal\'Hakkar.', },
  },
  [1449] = {
    'Vers les Hinterlands',
    {'Comme j\'en ai déjà parlé plus tôt, j\'ai moi-même tenté une reconnaissance du temple depuis les airs. Mais en fait, je n\'étais pas exactement seul.|n|nJ\'ai voyagé sur un griffon de la fameuse volière de Nid-de-l\'Aigle dans les Hinterlands. Là, j\'avais acheté les services d\'un de leurs meilleurs pilotes. Mais il est tombé de sa monture, et directement dans le marais...|n|nMon vieil âge m\'empêche de me souvenir du nom de ce pauvre type. Le maître de la volière devrait s\'en souvenir, très certainement.|n|nPartez-y et cherchez Falstad Marteau-hardi.|n|nNous devons découvrir ce qui est arrivé à ce pilote.', },
    {'Parler au haut-thane Falstad Marteau-hardi, au Nid-de-l\'Aigle des Hinterlands.', },
  },
  [1450] = {
    'Maître des griffons Hachegriffe',
    {'Ainsi, vous êtes un des fameux coursiers au service des vieux schnocks de la Ligue des Explorateurs, hein ?|n|nBien, écoutez-moi, $C. Je ne sais pas avec qui votre vieux pote faisait des ronds dans le ciel d\'Azeroth. Est-ce que j\'ai la tête du Maître des griffons Hachegriffe ? Hein ?|n|nSi vous êtes tellement $Gintéressé:intéressée; par les aléas du trafic aérien pourquoi n\'allez-vous pas lui parler directement ? Si je vous prends à glandouiller dans le coin un peu plus longtemps, je vais vraiment vous faire transpirer.|n|nÀ présent, bougez de là !', },
    {'Parlez au Maître des griffons Hachegriffe dans la Volière de Nid-de-l\'Aigle.', },
  },
  [1451] = {
    'Rhapsody Croquejarret',
    {'Rhapsody commençait vraiment à apprécier le goulot. Mais ne vous méprenez pas : tous les nains ici à la volière savent apprécier une bonne bière quand le bon moment arrive.|n|nMais le vieux Croquejarret s\'est habitué à la boisson comme le jour s\'est habitué à la nuit. Quel dommage ! Personne ne savait voler comme lui.|n|nLes premiers signes du problème sont apparus quand il est revenu en titubant de cette mission avec votre pote, Brohann. Tout s\'est écroulé peu de temps après. Nous avons dû le laisser partir.|n|nLa dernière fois que j\'ai entendu parler de lui, il avait monté un camp de brassage à l\'est d\'ici...', },
    {'Chercher Rhapsody Croquejarret dans les Hinterlands.', },
  },
  [1452] = {
    'Le Kocktail Kalimdor de Rhapsody',
    {'Hic !|n|nAlors c\'est ce vieux fou de Brohann qui vous envoie ? Bon sang ! On a eu une de ces aventures… Hic !|n|nSi vous voulez que je vous raconte ce qui s\'est passé au marais, je vais avoir besoin de quelque chose de costaud à boire. C\'était pas beau à voir, vous comprenez ? Hic !|n|nJe vais vous dire... Apportez-moi de quoi concocter un Kocktail Kalimdor et je vous en parlerai.|n|nJe vais avoir besoin de gésiers de Roc de Tanaris... et voyons... de foies de Groddoc et de Ferpoil de Féralas...|n|nUn bon Kocktail Kalimdor bien costaud... ça m\'f\'ra causer !', },
    {'Rhapsody Croquejarret dans les Hinterlands veut que vous lui rameniez 3 Gésiers de roc, 3 Foies de Groddoc et 3 Foies de Ferpoil.', },
  },
  [1453] = {
    'Les affaires de Récupérateurs en Désolace',
    {'Il y a beaucoup de travail à faire en Désolace, $N. C\'est un endroit atroce, souillé par les centaures et autres monstruosités. Mais si vous voulez un bon petit travail honnête à la semaine, alors allez-y, parlez à Kreldig Ungor, et dites-lui que je vous envoie.|n|nVous le trouverez planqué à la Combe de Nijel, un petit camp plutôt douillet niché dans les montagnes dans la partie nord de Désolace. Allez simplement à l\'est si vous venez des Serres-Rocheuses. C\'est facile à rater, alors faites attention.', },
    {'Parler à Kreldig Ungor en Désolace.', },
  },
  [1454] = {
    'L\'épave de Karnitol',
    {'Salutations, l\'$Gami:amie;. Asseyez-vous donc…|n|nMa première commande concerne le mage Karnitol, une sorte de noble de Hurlevent. Je crois que son bateau a été attaqué par des géants des mers au large de la côte, dans le nord-ouest de Désolace. Ses serviteurs ont essayé de sauver l\'un de ses précieux coffres, mais quand les géants ont attaqué en masse, il a préféré l\'abandonner et se téléporter, avec ses serviteurs, en lieu sûr.|n|nIl nous a demandé de retrouver ce coffre et son contenu, et de les lui rapporter à Hurlevent.', },
    {'Retrouver le Coffre de Karnitol en Désolace.', },
  },
  [1455] = {
    'L\'épave de Karnitol',
    {'Vous prenez un moment pour comprendre comment le coffre a été ouvert, et vous remarquez, sur les côtés et le dessus du coffre, de longues et profondes entailles. Elles révèlent que quelque chose d\'autre qu\'un humain ou qu\'un géant s\'y est intéressé. Les marques ne ressemblent pas à celles d\'une épée ou d\'une dague.|n|nAprès avoir fouillé le coffre, vous constatez qu\'il est complètement vide.|n|nN\'ayant plus rien d\'autre à faire, vous refermez le coffre et vous préparez à partir. Kreldig va être déçu.', },
    {'Retourner voir Kreldig Ungor en Désolace.', },
  },
  [1456] = {
    'L\'épave de Karnitol',
    {'Intrigant.|n|nBien, il se peut que tout espoir ne soit pas perdu.|n|nLe long de cette même côte, mais plus au nord, près de l\'île de Ranazjar, se trouvent des ruines sous-marines datant des elfes de la nuit. Une tribu de nagas, les Ondulames, s\'y est établie ! Je pense que c\'est notre meilleure chance.|n|nSi un groupe de leurs éclaireurs a été envoyé aussi loin au sud, alors cette tribu doit être puissante. Pour retrouver les possessions de Karnitol, je m\'attaquerais en priorité aux nagas les plus forts : les chasse-marées et les sorcières des mers.', },
    {'Retrouver la Sacoche de Karnitol et la rapporter à Kreldig Ungor en Désolace.', },
  },
  [1457] = {
    'L\'épave de Karnitol',
    {'Rapportez les biens de Karnitol à Roetten à Forgefer, et il vous paiera pour ce travail bien accompli.|n|nHa ! Ha ! Si vous ne faites pas attention, il sera tellement satisfait de vous qu\'il vous demandera de nous rejoindre à plein temps.|n|nMais à nouveau, bon travail, $N.|n|nSoyez $Gprudent:prudente; sur le chemin du retour, et ne prenez pas tout votre temps ; Karnitol n\'est pas le plus patient des hommes, mais il reste très généreux néanmoins.', },
    {'Apporter la Sacoche de Karnitol à Roetten Martel-de-pierre à Forgefer.', },
  },
  [1458] = {
    'Des réactifs pour les Récupérateurs',
    {'L\'une de mes tâches ici consiste à collecter des réactifs pour Leftwitch, un mage gnome de Kharanos. Roetten semble penser que c\'est de l\'argent facilement gagné puisque nous sommes déjà sur place. Il se soucie peu du fait que nous sommes si démunis.|n|nLes premiers objets de sa liste devraient être assez faciles à trouver, et ce sera de l\'argent gagné pour quiconque m\'aidera.|n|nJ\'ai besoin de cornes et de griffes des satyres Fielfurie qui vivent à l\'est d\'ici. Rapportez-m\'en et nous poursuivrons la liste.', },
    {'Apporter 10 Griffes de Fielfurie et 10 Cornes de Fielfurie à Kreldig Ungor en Désolace.', },
  },
  [1459] = {
    'Des réactifs pour les Récupérateurs',
    {'Ensuite, sur la liste de Leftwitch, on trouve… on trouve… Oh !|n|nRelativement facile, mais il faut décrypter ses directives. Il a besoin de venin de scorpashi et de peau de kodo. Mais il est précisé que le venin doit provenir de n\'importe quel scorpashi, et que la peau doit être celle d\'un vieux kodo, pas d\'un kodo mourant ou d\'un ancien kodo.|n|nLes mages, je vous dis pas, les trucs qu\'ils veulent parfois... c\'est tout simplement bizarre.', },
    {'Apporter 7 Fioles de venin de scorpashi et 3 Cuirs de vieux kodo à Kreldig Ungor, en Désolace.', },
  },
  [1462] = {
    'Sapta de terre',
    nil,
    {'Parler à la Prophétesse Plume-de-corbeau pour obtenir un autre Sapta de terre.', },
  },
  [1463] = {
    'Sapta de terre',
    nil,
    {'Parler à Canaga Hucheterre pour obtenir un autre Sapta de terre.', },
  },
  [1464] = {
    'Sapta de feu',
    nil,
    {'Parlez à Telf Joolam pour obtenir un autre Sapta de feu.', },
  },
  [1465] = {
    'La recherche de Vahlarriel',
    {'Tandis que vous continuez à fouiller le chariot, vous découvrez non seulement un pendentif mais également des traces de pas qui se dirigent vers le sud. Au loin, vous distinguez de la fumée s\'élevant d\'une grande forteresse. La fumée provient d\'un feu entretenu, il ne s\'agit pas de bâtiments qui brûlent, et votre instinct vous dit que les Malem, si tant est qu\'ils soient toujours en vie, ont été emmenés dans cette direction.|n|nVous estimez que Vahlarriel, à la Combe de Nijel, devrait voir le pendentif et savoir qu\'il se trouve des signes de vie au sud.', },
    {'Rapporter le Pendentif de Malem à Vahlarriel Tueur-de-démons en Désolace.', },
  },
  [1466] = {
    'Des réactifs pour les Récupérateurs',
    {'Ce sont les derniers objets à rassembler. Cela vous prendra aussi un peu plus de temps que pour les précédents.|n|nBien, assez parlé, commençons. Leftwitch dit qu\'il a besoin de : dix cervelles de mange-mana, de chasseur de mage ou de chasseur ley ; dix ailes du néant prélevées sur une vierge du Néant, une sœur du Néant ou une ensorceleuse du Néant. Et... dix fioles de sang de garde funeste provenant d\'un capitaine ou seigneur de la garde funeste.|n|nC\'est assez simple, non ? Non, sérieusement, si vous laissez tomber cette quête, je comprendrai.', },
    {'Apporter 10 Cervelles de gangrechiens, 10 Ailes du Néant et 10 Fioles de Sang de garde funeste à Kreldig Ungor, en Désolace.', },
  },
  [1467] = {
    'Des réactifs pour les Récupérateurs',
    {'Pour être $Gpayé:payée;, vous devez retourner à Forgefer et parler à Roetten en personne. Il aimera être débarrassé de la caisse de Leftwitch, de toute façon. Remettez-lui simplement ceci et ça devrait suffire pour avoir votre récompense.|n|nEt ne vous en faites pas, je ferai passer un mot positif à votre sujet lorsque je reviendrai. Je ne devrais plus rester longtemps en Désolace.', },
    {'Rapporter la Caisse de Leftwitch à Roetten Martel-de-pierre à Forgefer.', },
  },
  [1468] = {
    'La Semaine des enfants',
    {'Vous voulez aider l\'orphelinat ? Soyez-en $Gremercié:remerciée; mon $Gami:amie;. Votre aide durant la Semaine des enfants nous sera précieuse.|n|nPrenez ce sifflet. Il ne restera pas disponible très longtemps : en fait, pas plus longtemps que ne dure la Semaine des enfants. Quand vous l\'utiliserez, vous pourrez parler à l\'enfant dont vous avez accepté de vous occuper. Si vous l\'utilisez une seconde fois, il renverra l\'enfant.|n|nJe vous en prie, $N, faites vite la connaissance de votre protégé ! Je suis sûre que l\'enfant est très impatient de vous rencontrer.', },
    {'Utilisez le Sifflet d\'orphelin humain pour parler à l\'enfant que vous protégerez pendant la Semaine des enfants.', },
  },
  [1469] = {
    'L\'histoire de Rhapsody',
    {'Avant le vol, je me suis bu un plein tonneau de bière brune. Hic !|n|nEt ça a été un de ces vols ! Volé de-ci de-là avec Brohann qui me suivait. Mais pas vu de temple en tout cas. Hic !|n|nJe veux dire, j\'ai pas vu de temple, jusqu\'à ce que je sois trop parti et que je tombe de ma monture. J\'ai plongé directement dans la flotte et j\'ai été aspiré. Me suis trouvé entouré par un tas de trolls à la mine patibulaire. Vous pensez bien que j\'ai nagé très vite pour partir ! J\'ai quand même ramassé un souvenir troll. Tenez, apportez ça à Brohann et dites-lui que son temple est là-bas, en bas, de fait. Hic !', },
    {'Apportez le Fragment de tablette atal\'ai à Brohann Ventrabière à Hurlevent.', },
  },
  [1470] = {
    'Lever le voile',
    {'Salutations, enfant. Je peux voir que vous êtes encore novice dans les arts du démoniste, le pouvoir échappant toujours à votre contrôle. Je peux aussi sentir votre désir d\'apprendre.|n|nEt vous apprendrez.|n|nLa force ne réside pas dans l\'ignorance. La connaissance est notre pouvoir le plus puissant. Par l\'application du savoir, nous pouvons contrôler les magies et les êtres chaotiques du vide, et les soumettre à notre volonté.|n|nJe peux vous montrer comment soumettre un servant, mais d\'abord vous devez m\'apporter trois crânes pris sur les squelettes Cliquethorax qui rôdent près de la forge abandonnée.', },
    {'Apportez 3 Crânes de Cliquethorax à Venya Marthand.', },
  },
  [1471] = {
    'Le lien',
    {'Vous avez sûrement vu le cercle d\'invocation en dessous. C\'est le seul endroit d\'où vous pourrez tirer un marcheur du Vide libre.|n|nEn utilisant ces runes, vous pourrez l\'attirer ici. Vous devrez alors le dominer par la force des armes et de la magie. Lorsqu\'il sera assujetti, il sera lié à vous. Venez alors me voir, et je vous expliquerai le sort d\'invocation, pour que vous puissiez vous en servir, pour quelque objectif que ce soit.', },
    {'Utiliser les Runes d\'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Runes d\'invocation à Carendin Halgar, au Temple des Damnés.', },
  },
  [1472] = {
    'La dévoreuse d\'âmes',
    {'Une succube est une dévoreuse d\'âmes, une destructrice de cœurs et une tentatrice d\'hommes. Une créature machiavélique à l\'esprit très singulier.|n|nElle ne peut pas être amenée dans notre monde sans une impulsion.|n|nAussi nous utilisons sa propre force contre elle. Face à des cœurs d\'hommes bons, d\'hommes purs, d\'hommes aimants, la succube est incapable de résister, et elle viendra jusqu\'à notre monde. Alors vous pourrez la dominer, et l\'utiliser.|n|nParlez à mon assistant, Godrick Farsan, à l\'intérieur du temple. Il vous aidera à trouver un appât.', },
    {'Parler à Godrick Farsan au Temple des damnés.', },
  },
  [1473] = {
    'La créature du Vide',
    {'Il semble acquis que vous êtes $Gprêt:prête; à apprendre à invoquer un marcheur du Vide.|n|nUn être créé par le chaos qui l\'entoure. Si vous en invoquez un, mais que vous ne pouvez pas le contrôler, vous serez $Gannihilé:annihilée;.|n|nLe premier marcheur du Vide a été invoqué par Egalin, et le procédé est expliqué dans son grimoire.|n|nMalheureusement, il nous a été volé par un agent de la Croisade écarlate, qui l\'a caché dans sa base, dans une tour de l\'ouest. Rapportez-le-moi, et je vous transmettrai cette connaissance.', },
    {'Retrouver le Grimoire d\'Egalin et l\'apporter à Carendin Halgar au Temple des damnés.', },
  },
  [1474] = {
    'Le lien',
    {'Lancez un sort avec ces cœurs au cercle d\'invocation. Vous ouvrirez ainsi le chemin à une succube. Vous avez de grands pouvoirs à présent, et vous en aurez besoin pour la soumettre.|n|nAttention à ses charmes, $N, beaucoup d\'esprits forts ont cédé devant eux. Une fois qu\'elle sera battue, la succube retournera au Néant, et je vous apprendrai le sort pour l\'invoquer à volonté.', },
    {'Utiliser les Cœurs purs pour invoquer et soumettre une succube, puis rapporter les Cœurs purs à Carendin Halgar, au Temple des Damnés.', },
  },
  [1475] = {
    'Dans le temple d\'Atal\'Hakkar',
    {'D\'après la légende, le temple d\'Atal\'Hakkar est un lieu saint dédié au dieu ancien, Hakkar l\'Écorcheur d\'âmes. Habité par une ignoble tribu de trolls, les Atal\'ai, on dit qu\'il est impossible d\'y entrer.|n|nCe temple est à présent sous les eaux du Bassin des larmes, et récupérer les artéfacts sera d\'autant plus difficile. Mais c\'est pourtant ce que j\'ai besoin que vous fassiez, $N.|n|nAidez-moi, en récupérant les Tablettes atal\'ai intactes. Apportez-les-moi, et je deviendrai un héros aux yeux de la Ligue des Explorateurs. Nous partagerons ensemble cette gloire.', },
    {'Rassembler 10 Tablettes atal\'ai pour Brohann Ventrabière à Hurlevent.', },
  },
  [1476] = {
    'Des cœurs purs',
    {'Des hommes d\'honneur et de bien ? Est-ce qu\'un tel homme existe seulement ?|n|nCela a nécessité une recherche assez longue, mais grâce à quelques fragments d\'histoires entendues par-ci par-là, je suis parvenu à trouver deux hommes qui devraient faire l\'affaire.|n|nLe premier se nomme Dalin Forgebusier. Il a consacré sa vie aux réfugiés de Lordaeron, ceux qui sont rejetés par leurs pairs au mur de Grisetête.|n|nL\'autre s\'appelle Comar Villard, un homme qui reste fidèle à son premier amour, et qui court les Paluns à la recherche de sa femme.|n|nRemettez leurs cœurs à Carendin. Mais auparavant, laissez-moi vous montrer votre gibier.', },
    {'Apportez les Cœurs de Dalin Forgebusier et de Comar Villard à Carendin Halgar dans le Temple des Damnés.', },
  },
  [1477] = {
    'Fournitures vitales',
    {'Les mages conduisent des recherches au Rempart-du-Néant dans les terres Foudroyées, des recherches vitales à notre compréhension des Portes des ténèbres. Ils ont besoin presque constamment de marchandises, mais notre ligne d\'approvisionnement vers Rempart-du-Néant est fragile.|n|nVous devez vous assurer que les provisions parviennent bien au Rempart-du-Néant. Allez voir le maître de guet Sorigal à Sombre-Comté, et faites ce qu\'il demande. Cette quête vous conduira dans des terres hostiles, $N. Soyez $Gprêt:prête;.', },
    {'Parler au Maître de guet Sorigal à Sombre-Comté, dans le Bois de la Pénombre.', },
  },
  [1478] = {
    'Les invocations de Halgar',
    {'Ah, $N ! Je viens juste de recevoir un mot de Carendin Halgar disant qu\'il voulait vous voir pour continuer l\'entraînement.|n|nVous devriez être $Gfier:fière; de vous, $N. Ce n\'est pas tous les jours que Maître Halgar daigne instruire personnellement un jeune démoniste.|n|nVous le trouverez dans le quartier de la Magie à Fossoyeuse, près du temple des Damnés.', },
    {'Parler à Carendin Halgar à Fossoyeuse.', },
  },
  [1479] = {
    'Le Rameau des Éternels',
    {'J\'ai entendu parler d\'histoire sur les elfes de la nuit, qui ont leur banque dans un arbre, mais qui ressemble à un ours ! C\'est génial ! C\'est chouette, il paraît que les elfes de la nuit aiment la nature et ce genre de choses. Et les ours, c\'est trop terrible !|n|nVous voulez bien m\'emmener voir l\'arbre-ours à Darnassus, s\'il vous plaît ? Y\'a un bateau qui peut nous amener juste à côté, ça ne devrait pas prendre trop de temps. S\'il vous plaaaaaaaaaaaît !', },
    {'Conduire l\'orphelin à la banque de Darnassus. La banque est creusée dans le tronc d\'un arbre connu sous le nom du Rameau des Éternels.', },
  },
  [1480] = {
    'Le corrupteur',
    {'La peau déchirée sent le pourri. Malgré son aspect sec et fragile, elle est remarquablement souple.|n|nEn la déroulant, vous voyez clairement une sorte de langage écrit en rouge sur l\'un des côtés. Un symbole est apposé en évidence en bas de la peau ; vous supposez qu\'il s\'agit d\'une signature.|n|nPeut-être Maurin pourrait-il vous en dire plus ?', },
    {'Apportez une Peau de démon écorché à Maurin Craquossement en Désolace.', },
  },
  [1481] = {
    'Le corrupteur',
    {'Je pense pouvoir trouver ce démon si j\'ai les réactifs adéquats.|n|nS\'il est effectivement aussi puissant que je le suspecte, je vais avoir besoin de certains objets disponibles sur des créatures mortelles. Mais vous agissez au nom du Chef de guerre, aussi je suis certain que vous accepterez ma quête.|n|nD\'abord, je vais devoir briser toutes les protections qu\'il aurait contre les visions. Pour cela, j\'aurais besoin d\'un scalp de satyre. Mais pas de n\'importe quel satyre. Il doit provenir d\'un traqueur des ombres Fielfurie.|n|nCherchez cette tribu dans les ruines anciennes au nord-est de Désolace.', },
    {'Apporter un Scalp de traqueur des ombres à Maurin Craquossement en Désolace.', },
  },
  [1482] = {
    'Le corrupteur',
    {'Un cristal d\'oracle ferait parfaitement l\'affaire. Ils sont conçus par les nagas et utilisés par leurs oracles.|n|nAu nord-ouest d\'ici, le long de la côte, se trouve un vaste récif de corail que les nagas considèrent comme leur demeure, lorsqu\'ils viennent près du rivage. Vous trouverez leurs oracles là-bas. Les Ondulames sont dangereux et ne réagiront pas amicalement à votre intrusion : soyez $Gprudent:prudente; et hâtez-vous.|n|nQuand vous reviendrez, nous verrons à localiser le seigneur-démon Azrethoc.', },
    {'Apporter un Cristal d\'oracle à Maurin Craquossement, en Désolace.', },
  },
  [1483] = {
    '[PÉRIMÉ]Ziz Fizzik',
    {'La KapitalRisk a détourné un grand nombre de savants gobelins, mais de temps en temps, nous avons l\'occasion de les leur reprendre.|n|nIl y a quelque temps, l\'équipe de la KapitalRisk des Serres-Rocheuses a embauché Gerenzo Siffleclef. Un gnome ! Leur autre ingénieur, Ziz Fizzik, en a été tellement dégoûté qu\'il a essayé de trouver un nouveau travail auprès du Syndicat des Artisans. Je lui ai confié quelques travaux à faire, mais il a peut-être besoin de renfort.|n|nPeut-être que vous pourriez voir ça pour moi ? On peut le trouver à la lisière ouest de la combe des Cisailles.', },
    {'Parler à Ziz Fizzik dans la Combe des Cisailles.', },
  },
  [1484] = {
    'Le corrupteur',
    {'Cette créature est beaucoup plus dangereuse que je ne l\'avais cru. Il est certain que Takata doute de mes capacités à battre une telle créature, et ce serait insulter son honneur que de ne pas l\'informer de ce qui vient juste de se passer.|n|nParlez à l\'homme d\'épée, dites-lui que vous voulez tuer le démon s\'il l\'autorise, mais n\'insistez pas trop. Ce serait mieux qu\'il croie que c\'est son idée.', },
    {'Parlez à Takata Lamacier en Désolace.', },
  },
  [1485] = {
    'Les vils quasits',
    {'Ces démonistes qui sont passés avant nous ont engendré la méfiance parmi la Horde, et bien que nous soyons tolérés, nous ne sommes pas aimés.|n|nCela n\'a pas poussé les démonistes à s\'unir pour autant, et beaucoup choisissent de vivre reclus, marinant seuls dans leur magie. Je ne vais pas tenter de vous faire choisir un chemin ou l\'autre, mais seulement vous aider pendant votre progression.|n|nAvant que je vous apprenne l\'art de l\'Invocation, apportez-moi six têtes de vils quasits. Vous en trouverez dans la grotte au nord-est.', },
    {'Apporter 6 Têtes de vils quasits à Ruzan.', },
  },
  [1486] = {
    'Les peaux de déviants',
    {'Tandis que Naralex s\'enfonçait toujours plus profondément dans son cauchemar, des bêtes étranges émergèrent de sous les Tarides, jusqu\'aux cavernes des Lamentations.|n|nCes créatures déviantes possèdent des propriétés étranges, comme si elles venaient d\'un autre monde. Bien qu\'elles soient maléfiques de nature, je pense qu\'il y a des avantages à tirer de leur présence ici en Kalimdor. Leur peau peut certainement être travaillée par les travailleurs du cuir.|n|nSi vous vous considérez à la hauteur, partez dans les cavernes ici-bas et trouvez des peaux de déviants.', },
    {'Nalpak, dans les Cavernes des Lamentations, veut 20 Peaux de déviants.', },
  },
  [1487] = {
    'L\'éradication des déviants',
    {'Naralex poursuivait un noble but.|n|nNotre grand chef aspirait à entrer dans le Rêve d\'émeraude pour faire reverdir ces terres arides, qui étaient autrefois une forêt luxuriante. Mais quelque chose s\'est mal passé.|n|nLe rêve de Naralex s\'est transformé en cauchemar et des créatures corrompues ont commencé à envahir les cavernes.|n|nDes Disciples de Naralex tentent de le réveiller, mais mon souci est de débarrasser les cavernes de ces bêtes maléfiques.|n|nBravez les cavernes, $N, et éradiquez cette vermine déviante.', },
    {'Ebru, dans les Cavernes des Lamentations, veut que vous tuiez 7 Ravageurs déviants, 7 Vipères déviantes, 7 Traînards déviants et 7 Crocs-d\'effroi déviants.', },
  },
  [1488] = {
    'Le corrupteur',
    {'Bien que je ne sache rien de ce seigneur Azrethoc, je suis d\'accord avec Maurin. Il faut l\'arrêter, surtout s\'il tente de gagner du pouvoir au sein de la Lame ardente pour faire avancer ses objectifs.|n|nVous nous avez déjà exprimé votre souhait d\'aider le Chef de guerre, et j\'aimerais vous charger de réunir un groupe pour aller tuer ce seigneur-démon et son serviteur démoniste.|n|nLorsque vous serez $Gprêt:prête;, partez pour le sud, et revenez me voir lorsque ce danger sera éliminé.', },
    {'Tuer le seigneur Azrethoc et Jugkar Grim\'rod puis retourner voir Takata Lamacier en Désolace.', },
  },
  [1489] = {
    'Hamuul Totem-runique',
    {'Les carapaces que vous m\'avez apportées portent une souillure que je n\'ai jamais vue auparavant. Je pense que l\'eau des oasis en est la cause, et je peux ressentir le désordre qu\'ils causent à cette terre. C\'est comme si la terre rêvait et ne pouvait s\'éveiller.|n|nLes cavernes des Lamentations doivent être à l\'origine de cette souillure. Mais avant de vous y rendre, allez parler à Hamuul Totem-runique, le druide ancien. Je lui ai envoyé un message décrivant les événements dans les Tarides. C\'est un sage, et il peut vous donner de bons conseils.|n|nVous le trouverez aux Pitons-du-Tonnerre, sur la cime des Anciens.', },
    {'Parler à Hamuul Totem-runique.', },
  },
  [1490] = {
    'Nara Crin-Sauvage',
    {'J\'ai pénétré sur la terre des rêves et j\'ai vu un groupe de druides dans les cavernes des Lamentations. J\'ai vu qu\'autrefois leurs buts étaient nobles, mais qu\'ils ont perdu le chemin depuis. Ils sont à présent serviteurs de la souillure qui sourd dans les Tarides.|n|nJe ne suis plus jeune et les forces me manquent. Je ne pourrai pas rester plus longtemps sur cette terre des rêves pour en apprendre davantage sur ces druides souillés. Mais Nara est jeune et son esprit est féroce. Elle est restée à rêver tandis que je me retirais.|n|nParlez-lui. Elle est dans la tente, là-bas.', },
    {'Parler à Nara Crin-sauvage.', },
  },
  [1491] = {
    'Les potions d\'intelligence',
    {'D\'accord, les cornes de raptors ne marchent pas si bien que cela. Mais ce n\'est pas grave, personne ne devient riche au premier essai ! Et de plus, je pense avoir trouvé encore mieux pour mes potions d\'intelligence !|n|nIl existe une substance appelée essence de lamentation, qui est sûrement à l\'oigine des plantes et bêtes étranges des Tarides. Trouvez-en, et je l\'essaierai dans mes boissons !|n|nJ\'ai entendu dire que cette essence apparaît sur des créatures à l\'état d\'ectoplasme vivant dans les cavernes des Lamentations, à l\'ouest. Chassez ces créatures et récupérez l\'essence.', },
    {'Récupérez 6 doses d\'Essence de lamentation.', },
  },
  [1492] = {
    '[PÉRIMÉ]Maître des quais Tournoupette',
    {'J\'ai besoin d\'envoyer une caisse de potions, de réactifs et d\'objets divers à mes associés dans l\'Ancien Monde. J\'ai en fait assez peu de temps et je ne peux pas vérifier moi-même qu\'elle est bien embarquée aux docks de Cabestan. De plus, la dernière caravane est déjà partie.|n|nSi vous pouvez, apportez-la au Maître des quais Tournoupette. Il veillera à ce qu\'elle soit chargée sur le prochain bateau en partance pour la crique des Flots noirs.', },
    {'Apportez la Caisse sûre au Maître des quais Tournoupette à Cabestan.', },
  },
  [1498] = {
    'La voie de la défense',
    {'En tant que guerrier, l\'une de nos tâches les plus cruciales est… la protection. Nous sommes le bouclier de la Horde, et nous gardons nos semblables les plus faibles à l\'arrière. Si vous voulez rejoindre nos rangs, alors vous devez me prouver votre ardeur.|n|nPartez pour les falaises du Tonnerre en Durotar, où vivent les foudroyants et les lézards-tonnerre. Chassez ces bêtes ! Montrez-moi que vous êtes plus $Gfort:forte; qu\'eux ! Affrontez leurs assauts et apportez-moi un tas d\'écailles roussies comme preuve.|n|nFaites cela, et alors je deviendrai votre maître.', },
    {'Apporter 5 Ecailles roussies à Uzzek au Poste de Guet-Lointain dans les Tarides.', },
  },
  [1499] = {
    'Les vils quasits',
    {'Zureetha envoie des novices comme vous réduire le nombre des créatures de la caverne près de laquelle vous avez combattu les vils quasits.|n|nJe pense qu\'il serait bon pour vous de l\'aider et ainsi de gagner de l\'expérience. Dites-lui également que vous avez participé à la résolution du problème posé par ces diablotins, elle aura probablement une récompense pour vous.', },
    {'Parler à Zureetha Mireloin.', },
  },
  [1500] = {
    'Le réveil de Naralex',
    nil,
    nil,
  },
  [1501] = {
    'La créature du Vide',
    {'Il reste si peu de démonistes… Nous risquons beaucoup, mais cela en vaut la peine. Vous devez rapidement atteindre la pleine possession de vos capacités pour être utile à la Horde et au Chef de guerre.|n|nIl est temps pour vous d\'apprendre un nouveau sort d\'invocation.|n|nD\'abord, vous devez récupérer la tablette de Verga, qui a été volée par des démonistes de la Lame ardente et qui est à présent détenue dans leur antre du rocher du Crâne à l\'est de la ville. Une fois que j\'aurai la tablette, je vous montrerai les runes nécessaires à l\'invocation d\'un marcheur du Vide.', },
    {'Récupérer la Tablette de Verga pour Gan\'rul Oeil-sanglant à Orgrimmar.', },
  },
  [1502] = {
    'Thun\'grim Mirefeu',
    {'Il est vital que l\'arme d\'un guerrier soit de qualité. Et s\'il y a bien un orc capable de concevoir des armes de qualité, c\'est Thun\'grim Mirefeu. C\'est un ermite qui vit au sommet des collines à l\'est de la Croisée.|n|nSi vous cherchez une arme, $Gguerrier:guerrière;, alors cherchez Thun\'grim. Pour le trouver, voyagez d\'abord vers la Croisée, vers l\'ouest. Puis tirez droit à l\'est, dans les collines. Son camp est au sommet d\'une d\'entre elles.', },
    {'Parler à Thun\'grim Mirefeu dans les Tarides.', },
  },
  [1503] = {
    'Acier forgé',
    {'Je vais vous donner une arme, $N, mais d\'abord vous devez me venir en aide. Les Tranchecrins du nord-ouest sont venus dans mon camp il y a plusieurs nuits. Ils ne venaient pas m\'affronter, mais ils savaient que ma vue est mauvaise. Quelques-uns m\'ont distrait, en grognant, tandis que les autres me dévalisaient ! Les lâches !|n|nIls ont emporté un coffre de fer contenant des barres d\'acier forgé. Si vous pouvez les récupérer, alors je vous donnerai l\'arme idéale.|n|nTrouvez le coffre en fer dans le camp des hurans et rapportez-moi les barres d\'acier forgé.', },
    {'Apportez les Barres d\'Acier forgé à Thun\'grim Mirefeu dans les Tarides.', },
  },
  [1504] = {
    'Le lien',
    {'À présent, observez la Tablette de Verga, car elle contient les glyphes nécessaires à l\'invocation. Apportez-les au cercle sous la tente de Neeru Lamefeu de l\'autre côté de la grotte. Vous serez alors capable d\'invoquer un marcheur du Vide.|n|nVous devez le battre en utilisant tous les moyens physiques et magiques que vous avez à votre disposition. Une fois qu\'il sera battu, revenez me voir avec les glyphes d\'invocation et je vous apprendrai comment soumettre la créature.', },
    {'Utiliser les Glyphes d\'invocation pour invoquer et soumettre un marcheur du Vide, puis rapporter les Glyphes d\'invocation à Gan\'rul Oeil-sanglant, à Orgrimmar.', },
  },
  [1505] = {
    'Le vétéran Uzzek',
    {'La Horde honore ses guerriers, car leur force n\'est pas remise en question. Mais les grands guerriers sont également de grands étudiants.|n|nCherchez Uzzek. C\'est le vétéran de maintes batailles et il enseigne à présent l\'art du combat à de jeunes guerriers. Vous le trouverez au sud du poste de Guet-Lointain, la garnison orque à la frontière entre les Tarides et Durotar.', },
    {'Parlez à Uzzek au Poste de Guet-Lointain.', },
  },
  [1506] = {
    'Les invocations de Gan\'rul',
    {'Vous là ! $N, c\'est ça ?|n|nJ\'espère que votre programme n\'est pas trop chargé, car Gan\'rul veut vous voir tout de suite. Vous le trouverez avec les démonistes seniors à la Faille de l\'Ombre.|n|nD\'après mes souvenirs de Gan\'rul, le fait qu\'il vous appelle est soit une très bonne chose, soit une très mauvaise.', },
    {'Parler à Gan\'rul Oeil-sanglant à Orgrimmar.', },
  },
  [1507] = {
    'La dévoreuse d\'âmes',
    {'Il est temps pour vous d\'en apprendre plus sur les magies d\'invocation. Vous allez apprendre à invoquer une succube, une créature dotée de pouvoirs mentaux incroyables. Elle peut apaiser les esprits faibles jusqu\'à ce qu\'ils tombent en son pouvoir. Mais ne craignez rien ! Je sais que vous êtes capable de relever le défi.|n|nUne succube peut être invoquée que si elle est appâtée avec un objet qui représente une grande dévotion et un grand amour.|n|nUne suggestion ? Parlez à Cazul... Il semble qu\'il n\'y ait pas grand-chose que le vieux démoniste ignore.', },
    {'Parlez à Cazul à la Faille de l\'Ombre.', },
  },
  [1508] = {
    'Cazul l\'aveugle',
    {'Hmm… mais bien sûr, ce n\'est pas la raison pour laquelle vous êtes $Gvenu:venue; me parler.|n|nSi Gan\'rul vous envoie, ce doit être parce que vous devez invoquer une succube, et que vous avez besoin d\'un objet pour la séduire.|n|nHmm… si vous pouvez faire confiance à un homme aveugle pour vous diriger, $N, alors écoutez. Zankaja vit à l\'ouest de la tour des coursiers du vent, dans les hauteurs d\'Orgrimmar. Elle attend le retour de son compagnon.|n|nAllez la voir.', },
    {'Parler à Zankaja à Orgrimmar.', },
  },
  [1509] = {
    'Des nouvelles de Dogran',
    {'Mon compagnon, Dogran, a été récemment envoyé à la Croisée pour y accomplir son devoir. Il avait obtenu une promotion, et il était très fier.|n|nMoi, j\'étais triste, mais je n\'en ai rien laissé paraître. Et j\'étais inquiète, aussi. Les Tarides sont une région bien plus dangereuse qu\'Orgrimmar, et je craignais le pire.|n|nÀ présent, cela fait une semaine qu\'il aurait dû rentrer, et je n\'ai toujours reçu aucune nouvelle...|n|nPeut-être pourriez-vous vous rendre à la Croisée et voir s\'ils ont des nouvelles de lui ? Il travaillait avec Gazrog, qui devrait toujours y être assigné.', },
    {'Parler à Gazrog à la Croisée.', },
  },
  [1510] = {
    'Des nouvelles de Dogran',
    {'Il était en poste au Camp Taurajo, où nous essayions de nous débarrasser des hurans. Il a dirigé quelques grunts sur l\'un de leurs campements, mais il a été alors grièvement blessé. Les autres sont revenus et ont essayé de lui porter secours. Mais il allait très mal, ses blessures saignaient et ils hésitaient à le déplacer avant de le panser correctement.|n|nIls ont envoyé un message ici, demandant un breuvage de soin des trolls de Malaka\'jin, au pied des Serres-Rocheuses. Nous avons envoyé quelqu\'un pour le chercher, mais personne n\'est encore revenu.', },
    {'Parler à Ken\'zigla, au village de Malaka\'jin.', },
  },
  [1511] = {
    'Breuvage de Ken\'zigla',
    {'Je pensais bien que quelqu\'un d\'autre viendrait prendre le breuvage, alors je l\'ai préparé à toutes fins utiles.|n|nTenez, prenez, $N. N\'oubliez pas : ne lui donnez que la moitié ! Cela lui donnera suffisamment de force pour qu\'il puisse bouger sans perdre tout son sang. Laissez passer une nuit, puis donnez-lui l\'autre moitié.|n|nVoilà, vous feriez bien de l\'apporter à Logmar au Camp Taurajo. D\'après ce que m\'a dit l\'autre qui est passé avant, il devrait avoir une idée de l\'endroit où Dogran se trouve.', },
    {'Apporter le Breuvage de Ken\'zigla au grunt Logmar, au Camp Taurajo.', },
  },
  [1512] = {
    'Le cadeau de l\'amour',
    {'Zankaja est jeune et belle. Être enchaînée à un invalide… Je ne permettrai pas qu\'elle souffre de cette injustice.|n|nLaissez-moi, $N. Et merci. Je peux ainsi terminer ma vie dans une glorieuse bataille, et non comme un légume.|n|nEt je vous en prie, je souhaiterais que vous ne disiez rien à ma compagne... Je ne veux pas qu\'elle se sente coupable.', },
    {'Apportez le Pendentif de poussière à Gan\'rul Oeil-sanglant à Orgrimmar.', },
  },
  [1513] = {
    'Le lien',
    {'Apportez cela au cercle d\'invocation dans la tente de Neeru, $N. Invoquez une ignoble succube, et dominez-la. Comme toujours cependant, soyez $Gprudent:prudente;, car la fierté et une trop grande confiance en soi ont terrassé de nombreux démonistes prometteurs.|n|nUne fois que vous l\'aurez vaincue, venez me rendre le pendentif, pour que je puisse donner des nouvelles à Zankaja.', },
    {'Utiliser le Pendentif de Dogran pour invoquer et soumettre une succube, puis rapporter le Pendentif de Dogran à Gan\'rul Oeil-sanglant, à Orgrimmar.', },
  },
  [1514] = {
    'Fleur-de-vent corrompue',
    nil,
    nil,
  },
  [1515] = {
    'La captivité de Dogran',
    {'Vous êtes $Garrivé:arrivée; jusque-là, alors si vous voulez voir la fin, je ne vais pas vous arrêter. Cependant, je ne peux pas vous fournir de forces supplémentaires, vous êtes $Gseul:seule;.|n|nDogran est prisonnier dans un camp de hurans au nord d\'ici. Cherchez une paire de huttes. Il sera surveillé de près... À condition qu\'ils ne l\'aient pas encore tué et qu\'il n\'ait pas succombé à ses blessures.|n|nBonne chance.', },
    {'Apporter le Breuvage de Ken\'zigla à Dogran dans les Tarides.', },
  },
  [1516] = {
    'L\'appel de la terre',
    {'Le temps est venu, jeune $C. Vous êtes $Gdevenu plus fort:devenue plus forte; et votre esprit est aussi endurant que la terre. Votre choix de suivre la voie du chaman montre votre sagesse, avant même de devoir faire vos preuves.|n|nL\'élément de la terre guidera votre destinée, et fera partie intégrante de votre être, si vous y êtes $Gprêt:prête;. Mais vous devez vous présenter devant la terre elle-même. Si vous êtes $Gprêt:prête;, vous verrez des choses dont seuls les chamans ont connaissance.|n|nCherchez les traqueurs gangrenés au nord, et prenez-leur deux de leurs sabots. Revenez alors me voir, et nous parlerons de votre avenir.', },
    {'Apporter 2 Sabots de traqueur gangrené à Canaga Hucheterre dans la Vallée des Épreuves.', },
  },
  [1517] = {
    'L\'appel de la terre',
    {'Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits forts de percevoir les éléments comme nul autre ne le peut. Votre esprit contactera l\'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.|n|nIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs, ne l\'oubliez pas.|n|nCherchez le rocher des esprits au sud-ouest d\'ici, au bout du chemin secret. Buvez-y votre sapta et... et vous verrez.', },
    {'Trouver le Rocher des esprits et boire le Sapta de terre.', },
  },
  [1518] = {
    'L\'appel de la terre',
    {'Prenez ce quartz brut et apportez-le à Canaga Hucheterre. Il attestera de notre rencontre. Il créera un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu\'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre à bien d\'autres.|n|nSoyez $Gpatient:patiente;, $N. Restez $Gfort:forte;. Et recherchez la sagesse. C\'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu\'un avec elle. Respectez-la comme elle vous respecte.', },
    {'Apportez le Quartz brut à Canaga Hucheterre dans la Vallée des Épreuves.', },
  },
  [1519] = {
    'L\'appel de la terre',
    {'Il est temps à présent, jeune $C. Votre corps s\'est aguerri et votre esprit est aussi endurant que la terre. Je le vois, vous possédez déjà la sagesse.|n|nLa terre guide notre peuple, et nous parle, de la même manière qu\'elle vous parlera lorsque le temps sera venu. Mais vous devez être $Gmis à l\'épreuve:mise à l\'épreuve;. Si vous êtes $Gprêt:prête;, alors vous verrez des choses que nous seuls connaissons.|n|nPartez à la recherche des chamans dos-hirsutes dans leur ravin à l\'est, et procurez-vous le baume qu\'ils utilisent lors de leurs rituels. Ne revenez me voir que lorsque vous en aurez suffisamment pour votre propre potion.', },
    {'Apporter 2 Applications de Baume rituel au Prophète Plume-de-corbeau au Camp Narache.', },
  },
  [1520] = {
    'L\'appel de la terre',
    {'Un sapta est une boisson qui lie notre esprit aux éléments. Imprégnée de magie, cette potion permet aux esprits ouverts de voir les éléments comme personne d\'autre ne peut les voir. Votre esprit sera lié à jamais à l\'élément pour lequel le sapta a été créé, que seuls de rares chamans peuvent confectionner.|n|nIl faut toujours boire le sapta dans un endroit sacré, jamais ailleurs.|n|nCherchez l\'autel du chaman à l\'est d\'ici et buvez-y le sapta.', },
    {'Trouver le Rocher des kodos et boire le Sapta de terre.', },
  },
  [1521] = {
    'L\'appel de la terre',
    {'Prenez ce quartz brut et apportez-le à la prophétesse Plume-de-corbeau. Il attestera de notre rencontre. Elle concevra un totem pour vous, et ce caillou en sera le cœur. Aussi petit qu\'il puisse paraître, vous comprendrez avec le temps que la taille importe peu, et que même la plus petite des choses peut survivre aux montagnes.|n|nSoyez $Gpatient:patiente;, $N. Restez $Gfort: forte;. Et recherchez la sagesse. C\'est ce que la terre attend de vous. À la fin, vous ne ferez plus qu\'un avec elle. Respectez-la comme elle vous respecte.', },
    {'Apportez le Quartz brut à la prophétesse Plume-de-corbeau au Camp Narache.', },
  },
  [1522] = {
    'L\'appel du feu',
    {'Qu\'le feu soit avec vous, $Gm\'sieur:m\'dame;. Je vois que vous êtes balèze déjà dans les arts de la terre, et j\'pense que vous êtes $Gprêt:prête; à parler à Kranal.|n|nIl vit au nord de la Croisée des Tarides. Il s\'y connaît dans les éléments et peut vous apprendre les méthodes du feu... si vous pensez être $Gprêt:prête;.|n|nL\'est facile à trouver, n\'allez pas trop loin, c\'est tout, sinon vous vous retrouvez direct chez les elfes de la nuit.', },
    {'Trouver Kranal Fiss dans les Tarides.', },
  },
  [1523] = {
    'L\'appel du feu',
    {'Cela fait longtemps que vous n\'avez pas été $Gmis à l\'épreuve:mise à l\'épreuve;, $N. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu d\'apprendre la destruction et le chaos. L\'élément du feu peut vous appartenir, si vous êtes $Gprêt:prête; à en payer le prix.|n|nRecherchez Kranal Fiss dans les Tarides. Il vit dans une petite demeure au nord de la Croisée, mais prenez garde. Si vous atteignez les terres des elfes de la nuit, c\'est que vous êtes $Gallé:allée; trop loin.', },
    {'Trouver Kranal Fiss dans les Tarides.', },
  },
  [1524] = {
    'L\'appel du feu',
    {'Vous êtes suffisamment $Gpuissant:puissante; pour manier le totem de feu, mais cela ne signifie pas que vous êtes $Gprêt:prête;.|n|nLe long de la Furie-du-Sud en Durotar, avant la Grande Mer, se trouve un sentier caché menant aux hauteurs les plus élevées de cette terre. Trouvez le chemin menant au sommet et vous découvrirez l\'un de nos autels sacrés, surveillé par Telf Joolam : l\'Autel de la flamme dormante.|n|nApportez-lui cette torche, cela voudra dire que vous tentez d\'apprivoiser le feu. Rapportez-la-moi lorsqu\'elle sera enflammée au brasero de l\'autel et je veillerai à ce que le totem de feu vous soit remis.', },
    {'Apportez la Torche de la flamme dormante à Telf Joolam en Durotar.', },
  },
  [1525] = {
    'L\'appel du feu',
    {'Mais vous n\'êtes pas là pour recevoir un cours d\'histoire, n\'est-ce pas ? Vous êtes $Gvenu:venue; pour la flamme éternelle et le totem de feu.|n|nLa première étape consiste à créer un sapta et à vous lier à la flamme.|n|nJe peux m\'en occuper si vous m\'apportez deux choses. La première est du goudron de feu, un objet simple à se procurer et généralement porté par les lanceurs de sorts Tranchecrin dans les Tarides de l\'est.|n|nIl sera plus dangereux de se procurer la seconde : une bourse de réactifs que vous trouverez sur l\'un des sectateurs de la Lame ardente. Ils sont dans une caverne au-dessus des ravins, au nord-est de Tranchecolline.', },
    {'Apporter 1 Goudron de feu et 1 Bourse de réactifs à Telf Joolam en Durotar.', },
  },
  [1526] = {
    'L\'appel du feu',
    {'Le sapta de feu est terminé. Il est temps pour vous de vous confronter à la flamme. Utilisez le sapta à l\'autel et rendez-vous au sommet de la montagne pour affronter la manifestation. Elle n\'attaquera pas tant que vous ne serez pas $Gprêt:prête;, mais elle sait que vous pouvez la voir.|n|nFrappez bien, et frappez vite, $N, car sa puissance grandira si vous tardez à la tuer. Quand vous l\'aurez vaincue, placez ses braises dans le brasero et allumez la torche.', },
    {'Vaincre la Manifestation de feu mineure, et placer sa Braise rougeoyante dans le brasero, en haut de l\'Autel de la flamme éternelle.', },
  },
  [1527] = {
    'L\'appel du feu',
    {'Tenant fermement la torche, vous vous détournez du brasero et embrassez Durotar du regard. Vous sentez la fièvre battre dans votre esprit tandis que le vent avive les flammes qui dansent furieusement.|n|nVous prenez le chemin du retour vers les Tarides, pour trouver Kranal Fiss.', },
    {'Apportez la Torche de la flamme éternelle à Kranal Fiss dans les Tarides.', },
  },
  [1528] = {
    'L\'appel de l\'eau',
    {'L\'eau est dans votre avenir, $Gmon pote:m\'dame;. Je vois qu\'vous vous en sortez déjà bien avec les arts du feu, et je pense que vous êtes $Gprêt:prête; à parler à Islen.|n|nElle vit le long de la côte des Tarides. Si vous suivez le fleuve Furie-du-Sud en direction du sud, vous pouvez pas la rater – cherchez l\'grand requin ! Elle maîtrise les arts des éléments et peut vous apprendre ceux de l\'eau... si vous pensez être $Gprêt:prête;.|n|nElle est facile à trouver, n\'allez pas trop loin, c\'est tout. Elle se trouve juste après Cabestan.', },
    {'Trouver Islen Oeil-des-rivières dans les Tarides.', },
  },
  [1529] = {
    'L\'appel de l\'eau',
    {'Cela fait longtemps que vous n\'avez pas été $Gmis à l\'épreuve:mise à l\'épreuve;, $N. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu pour vous d\'apprendre la pureté de l\'eau.|n|nCherchez Islen Oeil-des-rivières dans les Tarides. Elle se trouve le long de la côte est, au sud du fleuve Furie-du-Sud et de Cabestan. Vous la trouverez dans une hutte de pêcheur. Bonne chance à vous, $N.', },
    {'Trouver Islen Oeil-des-rivières dans les Tarides.', },
  },
  [1530] = {
    'L\'appel de l\'eau',
    {'S\'il y a une leçon à apprendre de l\'eau, la voici : l\'eau est la renaissance.|n|nSon pouvoir coule, érode et rend propre toute chose. Ses propriétés de guérison et de ressourcement sont incomparables, mais seulement lorsqu\'elle est pure.|n|nLorsque vous comprendrez que l\'eau, quand elle est polluée, peut dévaster tout ce qu\'elle touche, vous apprécierez à quel point cette ressource est vitale.|n|nSi vous souhaitez le sapta de l\'eau, trouvez Brine loin dans les Tarides du Sud. Sa maison est constamment la cible des hurans.', },
    {'Trouver Brine à la Crête de Noirépine, dans les Tarides du Sud.', },
  },
  [1531] = {
    'L\'appel de l\'air',
    {'Y faut que vous y alliez, là. Préparez-vous à montrer qu\'vous êtes digne de r\'cevoir vot\' totem d\'air. Mais déjà, vous d\'vez trouver Prate Oeil-des-nuages aux Mille pointes. Elle vous dira comment obtenir vot\' totem d\'air.|n|nPassez au sud par les Tarides, puis aux Mille pointes, à l\'est. Vous la trouverez cachée dans un trou, avec son p\'tit copain. Haha, ne lui dites pas qu\'je la salue pas, elle aimerait pas trop.', },
    {'Trouver Prate Oeil-des-nuages aux Mille pointes.', },
  },
  [1532] = {
    'L\'appel de l\'air',
    {'Les vents de Kalimdor se hâtent pour vous rencontrer et vous serez bientôt $Gcompté:comptée; parmi nos plus puissants frères et sœurs. La fierté m\'emplit de vous voir arriver à ce stade, et de savoir votre avenir si prometteur.|n|nL\'air est difficile à contrôler, mais j\'ai foi en vos capacités à surmonter tous les obstacles.|n|nPartez pour l\'extrême sud des Tarides et entrez aux Mille pointes. C\'est là, loin à l\'est, que vous trouverez Prate Œil-des-nuages. Elle vous enseignera.', },
    {'Trouver Prate Oeil-des-nuages aux Mille pointes.', },
  },
  [1533] = {
    '<NYI>L\'appel de l\'air',
    nil,
    nil,
  },
  [1534] = {
    'L\'appel de l\'eau',
    {'Prenez cette outre et enfoncez-vous au cœur de la forêt luxuriante que les elfes de la nuit appellent Orneval. C\'est à l\'extrême nord des Tarides.|n|nUne fois dans la forêt, allez à l\'ouest. Le long des montagnes qui séparent les Serres-Rocheuses d\'Orneval, au-delà du lac Mystral, vous trouverez un lieu sacré : les ruines de Chimétoile. Une petite fontaine jaillit au centre du lac.|n|nApportez-moi un échantillon de l\'eau de cette fontaine. Ce sera le dernier ingrédient que vous devez obtenir avant que je ne vous renvoie à Islen.', },
    {'Remplir l\'Outre bleue vide aux Ruines de Chimétoile en Orneval et la rapporter à Brine dans les Tarides.', },
  },
  [1535] = {
    'L\'appel de l\'eau',
    {'Pour trouver la compréhension et obtenir le sapta, vous devez trouver les eaux les plus pures. Tandis que vous rassemblerez les échantillons pour moi, observez les lieux qui vous entourent. Soyez $Gattentif:attentive; aux créatures qui ont besoin d\'eau, et qui la protègent. Voyez comment elle affecte les forêts et les déserts. Soyez témoin de la manière dont la substance même qui maintient la vie force les créatures à ôter la vie.|n|nNous commencerons par une tâche simple : en bas de ma hutte, vous trouverez un bassin de ce précieux liquide. Remplissez-en cette outre et revenez me voir.', },
    {'Remplir l\'Outre marron vide au trou d\'eau, derrière la hutte de Brine, puis rapportez-lui la, dans les Tarides.', },
  },
  [1536] = {
    'L\'appel de l\'eau',
    {'Il y a longtemps, j\'ai suivi quelques compagnons jusqu\'aux contreforts de Hautebrande. Nous nous sommes défendus contre des humains tenaces qui s\'y sont établis et nous nous sommes retrouvés dans une petite ville occupée par les Réprouvés : Moulin-de-Tarren.|n|nC\'est là que j\'ai découvert une chose des plus étranges : en pleine ville, un petit puits offrait une belle eau fraîche. Je ne crois même pas que ces pestiférés comprennent sa valeur. C\'est une goutte de pureté au cœur d\'une mer de malédiction.|n|nRemplissez cette outre avec cette eau et rapportez-la-moi.', },
    {'Remplir l\'Outre rouge vide au puits de Moulin-de-Tarren et retourner voir Brine dans les Tarides.', },
  },
  [1537] = {
    '<NYI>L\'appel de l\'air',
    nil,
    nil,
  },
  [1538] = {
    '<NYI>L\'appel de l\'air',
    nil,
    nil,
  },
  [1558] = {
    'Le barrage de Formepierre',
    {'Forgefer, c\'est là où vivent tous les nains et les gnomes. Pas loin, il y a un endroit qui s\'appelle le Loch Modan. Les nains y ont construit un ÉNORME barrage. Ils disent que c\'est l\'une des choses les plus grandes jamais construites. Ouah !|n|nVous pouvez m\'emmener au Loch Modan pour voir le barrage, s\'il vous plaît ? Je crois que c\'est le barrage de Forme... de Formepierre. Il est énorme, c\'est sûr. J\'aimerais bien regarder par-dessus la grande chute d\'eau. Je promets que je ne me pencherai pas trop au-dessus de la rambarde !', },
    {'Conduire l\'orphelin au barrage de Formepierre au Loch Modan. Vous devez le conduire au milieu du barrage pour qu\'il puisse voir par-dessus l\'immense chute d\'eau.', },
  },
  [1559] = {
    'La recette de la bombe éclairante',
    nil,
    nil,
  },
  [1560] = {
    'La quête de Tooga',
    {'Je suis complètement perdu !|n|nMa femme, Torta, m\'a envoyé chercher le dîner et j\'ai dû prendre le mauvais chemin quelque part.|n|nAuriez-vous l\'amabilité de me guider vers Torta ? Elle m\'attend au sud de Port Gentepression.', },
    {'Montrer à Tooga le chemin du retour vers sa femme, Torta.', },
  },
  [1578] = {
    'Rééquiper le front',
    {'Les montagnards de Loch Modan combattent les troggs, et cela les occupe beaucoup. Ils ont constamment besoin d\'être approvisionnés en armures et en nouvelles armes.|n|nC\'est pourquoi mon collègue Thorvald est ici, pour maintenir l\'équipement des montagnards en bon état. Aussi, si vous pouviez fabriquer des haches en cuivre et des ceintures en anneaux de cuivre, puis les apporter à Thorvald, il vous en serait reconnaissant. Il se peut même qu\'il partage une partie de son savoir avec vous.|n|nThorvald est basé dans la tour de garde méridionale de Loch Modan.', },
    {'Apportez 6 Haches en cuivre et 6 Ceintures en anneaux de cuivre à Thorvald dans la Tour de garde méridionale du Loch Modan.', },
  },
  [1579] = {
    'Rouages électriques',
    {'Je suis venu à Auberdine parce que c\'est calme. Je veux créer dans le calme. Forgefer est décidément trop bruyante après une nuit passée à boire !|n|nAlors j\'ai pris un bateau pour Auberdine et j\'ai bu un petit peu trop pendant le voyage. J\'ai laissé tomber ma boîte de rouages électriques par-dessus bord ! J\'en ai besoin !|n|nJe ne sais pas exactement où je l\'ai laissée tomber, mais si vous pêchez quelque part dans l\'océan, il se peut que vous ayez de la chance...', },
    {'Apporter 8 Rouages électriques à Crackboum Tournelevier à Auberdine.', },
  },
  [1580] = {
    'Pêche aux Electropellers',
    {'Nous savons que vous êtes $Gchanceux:chanceuse;, mais à quel point l\'êtes-vous vraiment, $N ?|n|nUne nuit, je marchais sur les routes de Sombrivage. J\'essayais de trouver une bonne rivière ou un bon lac pour tester mon nouvel appeau à canard explosif et à propulsion automatique, et je pense que j\'étais un peu... parti. Je me suis endormi et je me suis réveillé des heures plus tard à Auberdine. Mes cheveux étaient roussis et je ne trouvais plus mon sac d\'Electropellers ! J\'avais dû le laisser tomber dans l\'eau !|n|nIl me faut ces Electropellers ! Peut-être pourriez-vous les pêcher quelque part dans un lac ou dans un cours d\'eau quelconque à Sombrivage...', },
    {'Apporter 12 Electropellers à Crackboum Tournelevier à Auberdine.', },
  },
  [1581] = {
    'Les élixirs pour les Feuillelame',
    {'Notre magasin d\'herbes et d\'alchimie est florissant, mais mon mari passe tellement de temps à préparer ses potions qu\'il ne nous en reste plus pour nous deux.|n|nPouvez-vous nous aider ?|n|nSi vous m\'apportiez une provision d\'élixirs déjà faits, alors je serais heureuse de commercer avec vous. J\'ai ici quelques herbes rares qui pourraient vous intéresser.', },
    {'Apporter 6 Elixirs de force du lion et 2 Elixirs de défense mineure à Syral Feuillelame à Dolanaar.', },
  },
  [1582] = {
    'Gilet lueur-de-lune',
    {'Nous autres à Darnassus sommes très occupés, et tout particulièrement les artisans. Les jeunes aventuriers souhaitant affronter les dangers de la nature ont constamment besoin d\'équipement.|n|nSi vous pouviez m\'aider à honorer mes commandes de cuir, alors je pourrais peut-être vous apprendre une technique avancée d\'artisanat du cuir.', },
    {'Apporter 1 paire de Gants en cuir estampé, 5 paires de Bottes en cuir estampé et 5 Capes en cuir estampé à Lotherias à Darnassus.', },
  },
  [1598] = {
    'Le Tome dérobé',
    {'Vous ici ! $N, c\'est ça ?|n|nÊtes-vous $Gsûr:sûre; de votre vocation de démoniste, car si vous ne pouvez pas maîtriser ce que vous invoquez, vous finirez $Gaspiré:aspirée; dans le Néant.|n|nJe dois vous enseigner les arts du démoniste, mais je dois d\'abord m\'assurer que vous êtes suffisamment $Gfort:forte;.|n|nUn novice qui étudiait à l\'abbaye s\'est enfui pour rejoindre la Confrérie défias. Pourquoi est-ce que cela m\'intéresse ? Eh bien, il a volé certains livres importants.|n|nL\'un d\'entre eux se trouve être un livre que je voulais pour mon usage personnel : « la Puissance du Vide ». Volez-le pour moi, il est caché dans sa tente dans les vignes.', },
    {'Retrouvez la Puissance du Vide pour Drusilla La Salle.', },
  },
  [1599] = {
    'Les débuts',
    {'Vous devez être $Gle nouveau:la nouvelle; démoniste dont tout le monde parle. Quelqu\'un doit vous apprécier pour qu\'on m\'arrache à mes recherches et me demande de vous enseigner.|n|nNe vous inquiétez pas, je vais vous consacrer du temps.|n|nLe plus simple des sorts d\'invocation est celui du diablotin. Mais avant que je vous le livre, vous devez prouver que vous avez les capacités physiques et mentales nécessaires.|n|nApportez-moi trois charmes de plume que portent les novices crins-de-givre de la caverne au sud-ouest.', },
    {'Apporter 3 Charmes de plume à Alamar Grimm à Courbenclume.', },
  },
  [1618] = {
    'Le rééquipement des Carmines',
    {'Nous les nains ne sommes pas les seuls à nous battre. Nos alliés humains sont très occupés également.|n|nLes Carmines subissent régulièrement des attaques des orcs rochenoires, et leur réserve d\'équipement est constamment très basse. Si vous vouliez leur venir en aide, je suis sûr que leur forgeron permanent, Verner Bongoulot, vous apprendrait un ou deux trucs.', },
    {'Tormus Forge-profonde veut que vous apportiez 4 Ceintures runiques en cuivre et 4 Maillets lourds en cuivre à Verner Bongoulot, dans les Carmines.', },
  },
  [1638] = {
    'L\'entraînement du guerrier',
    {'Vous avez montré que vous êtes $Gun guerrier:une guerrière; capable, $N. Mais vous êtes encore jeune et avez beaucoup à apprendre.|n|nParlez à Harry Burlguard, il est généralement à la taverne du Cochon siffleur, dans la Vieille ville de Hurlevent. Harry est un vétéran et un excellent maître. Il pourrait vous montrer quelques passes d\'armes qui vous aideraient à vivre plus vieux.', },
    {'Parler à Harry Burlguard à Hurlevent.', },
  },
  [1639] = {
    'Bartleby le poivrot',
    {'Ouais, je peux vous enseigner ! Mais d\'abord je veux voir ce que vous savez déjà.|n|nVous voyez ce poivrot là-bas au bout du bar ? Bartleby ? Je veux que vous lui preniez sa chope.|n|nHa ! Et si vous connaissez Bartleby, alors vous savez qu\'il ne vous la donnera pas gentiment.', },
    {'Parler à Bartleby.', },
  },
  [1640] = {
    'Battre Bartleby',
    {'Vous voulez quoi ? Vous êtes $Gfou:folle; !|n|nLa seule façon pour vous d\'obtenir cette chope serait de la prendre entre mes doigts froids et morts…', },
    {'Battre Bartleby, puis lui parler.', },
  },
  [1641] = {
    'Le Tome de divinité',
    nil,
    nil,
  },
  [1642] = {
    'Le Tome de divinité',
    {'En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l\'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.|n|nBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c\'est en aidant les autres que vous vous démarquerez véritablement des citoyens d\'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.|n|nPrenez-en conscience, et ne l\'oubliez pas.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1643] = {
    'Le Tome de divinité',
    {'Votre tâche, à présent, $N, est de trouver quelqu\'un ici, à Hurlevent, qui a besoin de votre aide. Quelqu\'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu\'un ayant besoin d\'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.|n|nAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière.', },
    {'Chercher Stephanie Turner dans le Quartier commerçant de Hurlevent.', },
  },
  [1644] = {
    'Le Tome de divinité',
    {'Qu\'ils soient bénis. La plupart ont perdu leur famille dans les attaques du Fléau, ces dernières années.|n|nMon mari, John, collecte des matériaux qui me servent à confectionner des chemises et des pantalons pour les enfants, ce que je n\'ai malheureusement pas eu le temps de faire dernièrement.|n|nMais peut-être voudriez-vous m\'aider ? Oh, merci mille fois, $N.|n|nSi vous pouviez m\'apporter de l\'étoffe de lin pour que je puisse en faire des vêtements pour les enfants, je vous en serais reconnaissante.', },
    {'Apporter 10 morceaux d\'étoffe de lin à Stephanie Turner à Hurlevent.', },
  },
  [1645] = {
    'Le Tome de divinité',
    nil,
    nil,
  },
  [1646] = {
    'Le Tome de divinité',
    {'En toutes choses, un paladin doit réfléchir la Lumière qui nourrit notre force. Tendre vers la pureté, se battre pour l\'un des nôtres, ne veut pas dire que nous nous battons pour une déité. Nous nous battons pour être bons dans toutes nos actions.|n|nBien que nous soyons appelés pour frapper le Mal en ces temps difficiles, vous ne devez jamais oublier que c\'est en aidant les autres que vous vous démarquerez véritablement des citoyens d\'Azeroth. La compassion, la patience, la bravoure, ces valeurs sont aussi importantes pour un paladin que la force dans la bataille.|n|nPrenez-en conscience, et ne l\'oubliez pas.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [1647] = {
    'Le Tome de divinité',
    {'Votre tâche, $N, consiste à trouver quelqu\'un ici à Forgefer qui ait besoin d\'aide. Quelqu\'un ayant un cœur et des motivations purs. Peut-être une personne dévouée aux autres. Peut-être quelqu\'un ayant besoin d\'un guide. En tout cas, cette personne doit être pétrie de bonnes intentions et doit vouloir compter sur votre gentillesse.|n|nAgissez au mieux et revenez me voir après. Alors, nous discuterons de la voie du paladin et de la Lumière. Je resterai ici, au temple, dans l\'attente de votre retour. D\'autres paladins auront besoin que je les guide, également.', },
    {'Chercher John Turner à la périphérie de Forgefer.', },
  },
  [1648] = {
    'Le Tome de divinité',
    {'Ma femme et moi nous nous occupons d\'un orphelinat à Hurlevent, principalement pour des enfants qui ont perdu leurs parents au cours des attaques du Fléau cette dernière décennie. Je passe à Forgefer à peu près tous les mois afin de collecter des vivres offerts par des citoyens d\'ici, et j\'essaie de convaincre certaines associations de soutenir notre action vis-à-vis des enfants.|n|nCe voyage a été horriblement lent, et pas très productif.|n|nSi je pouvais simplement trouver des pièces de lin pour que ma femme puisse coudre quelques vêtements, je pourrais enfin envoyer quelque chose à la maison.', },
    {'Apporter 10 morceaux d\'étoffe de lin à John Turner à Forgefer.', },
  },
  [1649] = {
    'Le Tome de la bravoure',
    {'La bravoure et toutes les vertus qui vont avec sont comme les minerais rares : pour leur valeur vous devez les chérir, mais vous devez aussi prendre le temps de les entretenir, de les polir. Quand vous les associez judicieusement, vous obtenez un alliage résistant, qui peut résister même aux coups les plus violents.|n|nCette force, votre foi, votre bravoure doivent être éprouvées. Vous devez apprendre à ne jamais perdre la foi et comprendre qu\'avec le pouvoir de la Lumière à vos côtés, vous pourrez surmonter plus d\'obstacles que la plupart des gens.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1650] = {
    'Le Tome de la bravoure',
    {'Bien ! Votre engouement est le signe que vous êtes $Gprêt:prête; et montre votre enthousiasme à commencer le test. Ainsi soit-il !|n|nA l\'extrémité de Longrivage, dans la marche de l\'Ouest, une petite maison donne sur l\'océan. C\'est la demeure du couple Morpuits. Jordan, un très bon forgeron, est parti à Forgefer voir les nains. Mais il a laissé Daphne, sa femme, seule et sans protection.|n|nDes rapports disent que les Défias ont envahi cette zone : Daphne aura peut-être besoin de protection. Allez là-bas.', },
    {'Trouver Daphne Morpuits dans la marche de l\'Ouest.', },
  },
  [1651] = {
    'Le Tome de la bravoure',
    {'Je suis sûre qu\'ils seront là dans peu de temps maintenant, préparez-vous.|n|nJ\'ai une arme à la maison. Je vais la chercher et je reviens vous donner un coup de main, mais vous allez devoir faire le plus gros du travail j\'en ai peur.|n|nJe n\'ai aucune idée de leur nombre, mais pour sûr ils seront plus nombreux que la dernière fois.|n|nPriez la Lumière de vous accorder ses faveurs parce que... Vous avez entendu ça ? Je pense qu\'ils arrivent.|n|nNous allons nous replier près de la maison !', },
    {'Défendez Daphne Morpuits contre les attaques des Défias.|n|nAucun de vous deux ne doit mourir, si vous voulez réussir la quête.|n|nQuand vous aurez réussi, reparlez à Daphne Morpuits.', },
  },
  [1652] = {
    'Le Tome de la bravoure',
    {'S\'il vous plaît, retournez voir Duthorian et dites-lui que je suis saine et sauve. Et c\'est grâce à vous et à l\'Église.|n|nJe vais envoyer un mot à Jordan à Forgefer pour lui dire de ne pas s\'inquiéter. Oh qu\'il me manque ! J\'ai hâte qu\'il revienne.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1653] = {
    'Le test de droiture',
    {'Je pense que Jordan voudra vous remercier lui-même, et comme j\'ai besoin d\'un messager pour lui dire que sa femme est en sécurité, je pense que vous êtes $Gle candidat idéal:la candidate idéale;.|n|nJordan a été un paladin de la Lumière avant que son dévouement au métier de son père le fasse changer de voie. Il connaît nos coutumes et il est considéré parmi nos meilleurs fidèles.|n|nIl doit être encore à Forgefer. Dans la journée, il aime travailler hors de l\'enceinte de la ville, sans doute pour profiter du grand air de la montagne.', },
    {'Parler à Jordan Morpuits à Forgefer.', },
  },
  [1654] = {
    'Le test de droiture',
    {'J\'aimerais vous récompenser, si vous voulez bien l\'accepter ? Ne vous y trompez pas, ma générosité sera tributaire de votre contribution, mais je sens que cette association sera bénéfique pour nous deux.|n|nJe vous fabriquerai une arme à la hauteur de vos actions, un symbole des paladins et de la Lumière, mais vous devez me procurer les composants dont j\'ai besoin pour la forger. J\'ai déjà fait la liste de ce qui est nécessaire, il manquait juste une personne de qualité comme vous pour me les procurer. Qu\'en pensez-vous, $C ?', },
    {'Utiliser les Notes sur les armes de Jordan, trouver du Bois de chêne de blanchepierre, la Cargaison de Minerai raffiné de Bailor, le Marteau de forge de Jordan et une Gemme de Kor, puis revenir voir Jordan Morpuits à Forgefer.', },
  },
  [1655] = {
    'Cargaison de minerai de Bailor',
    {'Ach, vous m\'avez fait peur, $Ghomme:femme; ! Vous ne pouviez pas remarquer que j\'étais perdu dans mes pensées ?|n|nQu\'est-ce que c\'est ? La cargaison de Jordan... pour Forgefer. Ahhh, ouais, j\'vois de quoi vous parlez ! Les ogres Mo\'grosh... z\'ont volé la cargaison de minerai d\'mon vieil ami. La caravane venant des Paluns a été attaquée. Le garde qui avait survécu est mort il y a quelques jours : le soigneur est pas arrivé à temps.|n|nSi vous voulez la cargaison, faut que vous alliez au nord-est à travers le Loch. Elle est quelque part par là.', },
    {'Apporter la Cargaison de minerai de Jordan à Bailor Main-de-pierre au Loch Modan.', },
  },
  [1656] = {
    'Une tâche inachevée',
    {'$N, s\'il vous plaît, je vous en supplie, pouvez-vous m\'aider ? Je n\'ai pas fini ce que j\'ai à faire ici sur le Plateau – je suis au milieu de mon rite de force – et mon père veut que je livre ces fourrures à l\'auberge de Sabot-de-Sang.|n|nJe ne suis pas suffisamment reposée pour finir mon rite et faire ce que mon père m\'a demandé. Cela vous embêterait-il d\'y aller pour moi ?|n|nL\'auberge est agréable et c\'est l\'endroit parfait pour se reposer après un long voyage. Vous en conviendrez lorsque vous l\'aurez vue.', },
    {'Livrez le Ballot de fourrures à l\'aubergiste Kauth à Sabot-de-Sang.', },
  },
  [1657] = {
    'Empuantir Austrivage',
    {'Nous allons célébrer la Sanssaint en grande pompe… en en faisant voir de toutes les couleurs à nos ennemis d\'Austrivage !|n|nPrenez l\'une de ces boules puantes conçues spécialement pour l\'occasion. Elle est remplie d\'une substance nauséabonde dont aucun humain - ou aucune bête à l\'esprit simple, d\'ailleurs - ne peut supporter l\'odeur. Il faut la jeter au beau milieu d\'Austrivage pour qu\'elle agisse correctement, donc attendez-vous à combattre l\'Alliance !|n|nQuand vous aurez accompli cette tâche… cet hommage à notre libération, revenez me voir !', },
    {'Lancer trois Boules puantes des Réprouvés au milieu d\'Austrivage en Hautebrande, puis revenez voir la sombre imploratrice Yanka à la Fête de l\'homme d\'osier, dans les Clairières de Tirisfal.', },
  },
  [1658] = {
    'Un intrus à la Fête de l\'homme d\'osier',
    {'J\'ai besoin de personnes courageuses pour se rendre dans les clairières de Tirisfal, et voir comment se déroule la fête de l\'Homme d\'osier. Je ne vais pas vous mentir, aller là-bas sera dangereux : les gardes de faction lors de la fête seront exceptionnellement brutaux. Cependant, nous devons absolument connaître l\'ampleur des festivités, et la gravité des problèmes que les Réprouvés nous causeront durant la Sanssaint.|n|nSi vous vous sentez d\'attaque, dirigez-vous vers Tirisfal et observez la fête. Revenez me voir avec des informations, et je m\'assurerai que vous recevrez une compensation convenable.', },
    {'Allez voir la Fête de l\'homme d\'osier des Réprouvés dans les clairières de Tirisfal. Revenez voir le Sergent Hartman à Austrivage quand ce sera fait.', },
  },
  [1661] = {
    'Le Tome de noblesse',
    {'Encore bonjour, $N. Je suis encore plus fier de vous appeler $Gfrère:sœur; qu\'avant ; votre dévouement est une bénédiction pour nous tous.|n|nLe temps est venu de vous accorder une grande récompense. Sachez que je vous donne cela gratuitement, mais que plus tard, les défis qu\'auront à accomplir les paladins qui voudront réaliser mes quêtes seront autrement plus exigeants.|n|nReparlez-moi plus tard et je vous accorderai une grande faveur.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1665] = {
    'Tasse de Bartleby',
    {'OK, voilà ma tasse. Attendez ! Laissez-moi finir avant... OK, allez-y !', },
    {'Apporter la Tasse de Bartleby à Burlguard.', },
  },
  [1666] = {
    'Maréchal Haggard',
    {'Vous avez appris quelques passes d\'armes, mais il faudrait utiliser une arme décente. Je parie que si vous parliez au maréchal Haggard il pourrait vous aider.|n|nLe maréchal Haggard habite dans un manoir dans la forêt d\'Elwynn, au Camp de bûcherons du Val d\'Est. Il est à la retraite, mais il a accumulé beaucoup d\'équipements quand il était en activité.|n|nDites-lui que vous venez de ma part, et avec un peu de chance il aura une arme en trop à vous offrir.', },
    {'Parler au maréchal Haggard.', },
  },
  [1667] = {
    'Jack Dent-Morte',
    {'Burlguard vous a dit de passer ? Oui, j\'ai des armes en trop ici, mais avant vous devez faire quelque chose pour moi...|n|nIl y a quelque temps un scélérat défias appelé Jack Dent-Morte m\'a escroqué. Il faisait sombre et il portait un tabard de Hurlevent, j\'ai cru que c\'était le maréchal Dughan. Il m\'a dit qu\'il avait besoin de mon ancienne plaque de Maréchal de Hurlevent et je lui ai donnée... Alors il a éclaté de rire et s\'est enfui avant que je puisse l\'attraper !|n|nRapportez-moi ma plaque ! Jack Dent-Morte a probablement un camp secret dans le sud.', },
    {'Retrouver la Plaque du maréchal Haggard au Camp de Jack Dent-Morte, et la rapporter au maréchal Haggard.', },
  },
  [1678] = {
    nil,
    {'Si vous voulez monter dans les rangs des guerriers, vous avez intérêt à être robuste. Je peux vous apprendre de nouvelles passes d\'armes, mais avant, prouvez-moi que vous pouvez vous débrouiller $Gseul:seule; contre des adversaires réels.|n|nVejrek est le plus coriace des trolls du coin ; c\'est lui que vous devez affronter. Il a une hutte dans les contreforts au sud du repaire des Crins-de-givre.|n|nRapportez-moi sa tête et je saurai que vous avez du courage.', },
    {'Apportez la Tête de Vejrek à Muren Foudrepique à Forgefer.', },
  },
  [1679] = {
    'Muren Foudrepique',
    {'Bonjour guerrier ! Vous êtes $Gvoué:vouée; à un grand avenir, mais il vous reste quelques petits trucs à apprendre et Muren Foudrepique est le nain qu\'il vous faut pour vous les enseigner.|n|nVous trouverez Muren dans la Salle d\'armes à la Garde militaire de Forgefer. Parlez-lui quand vous serez $Gprêt:prête; à apprendre ce qu\'est un vrai guerrier.', },
    {'Parler à Muren Foudrepique.', },
  },
  [1680] = {
    'Tormus Forge-profonde',
    {'Maintenant que vous avez appris de nouvelles passes, il est temps pour vous d\'avoir une arme digne de ce nom. Parlez à Tormus Forge-profonde. Il peut vous fabriquer une arme dont vous me donnerez des nouvelles.|n|nVous trouverez Tormus ici, à Forgefer, à la Grande Forge.', },
    {'Parler à Tormus Forge-profonde.', },
  },
  [1681] = {
    'Base de Baguefer',
    {'Mon mentor, Sturgy Baguefer, a une base au sud du lac du Lit d\'Helm, à l\'est de Dun Morogh. Il est maître forgeron, et c\'est le meilleur.|n|nMais un jour, un de ses apprentis lui a apporté un étrange minerai. Le maître Baguefer l\'a baptisé « minerai ombreux » et s\'est empressé de le travailler. Mais au moment où il était sur le point d\'aboutir, une bande de nains sombrefers a attaqué sa base. Ils ont tué tout le monde !|n|nAllez à la base de Baguefer, $N, vengez la mort du maître, et rapportez-moi une cargaison de minerai ombreux.', },
    {'Rapporter du Minerai ombreux à Tormus Forge-profonde à Forgefer.', },
  },
  [1682] = {
    'Armes en fer gris',
    nil,
    nil,
  },
  [1683] = {
    'Vorlus Vilsabot',
    {'Avant de vous apprendre quoi que ce soit, vous devez me prouver votre résolution.|n|nLe satyre Vorlus Vilsabot a découvert un de nos lointains puits de lune, au sud-est du refuge des saisons de Ban\'ethil. Il est en train d\'y barboter, souillant l\'eau pure avec sa crasse.|n|nTrouvez Vorlus au puits de lune et détruisez-le. Rapportez-moi sa corne comme preuve, et je vous entraînerai.|n|nLe chemin vers le puits de lune est bien caché, $N, restez $Gconcentré:concentrée; et alerte, et vous le trouverez.', },
    {'Apportez la Corne de Vorlus Vilsabot à Elanaria, à Darnassus.', },
  },
  [1684] = {
    nil,
    {'Bonjour, $Gguerrier:guerrière; ! Vos compétences progressent, mais il y a plus à savoir sur votre métier que vous ne le pensez. Pour continuer à progresser il vous faudra bientôt trouver un Maître.|n|nLa guerrière Elanaria réside à Darnassus, à la Terrasse des guerriers. Elle peut vous former.', },
    {'Parler à Elanaria.', },
  },
  [1685] = {
    'Convocation de Gakin',
    {'N\'est-ce pas toujours ainsi ? Je vous ai $Gcherché:cherchée; partout aujourd\'hui et je n\'ai pas pu vous trouver, et maintenant que je n\'ai plus besoin de vous, vous venez me voir. !|n|nJ\'ai perdu assez de temps à vous chercher, je ne vais donc pas vous faire attendre plus longtemps. Maître Gakin vous convoque pour une autre leçon. Il me semble que vous devriez y aller immédiatement.|n|nVous le trouverez au sous-sol de « l\'Agneau assassiné ». Au fait, pas un mot : je préférerai que l\'endroit reste tranquille.', },
    {'Aller voir Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.', },
  },
  [1686] = {
    'L\'Ombre d\'Elura',
    {'Vous avez appris beaucoup, $N. Maintenant nous allons vous fabriquer une arme. Une arme de $Gguerrier:guerrière;.|n|nPour cela, vous devez aller à Sombrivage.|n|nIl y a bien longtemps, un bateau s\'est brisé sur les rochers près du phare d\'Auberdine, éparpillant ses caisses de minerai d\'élunite au fond de l\'océan.|n|nTout d\'abord, vous devez vaincre la gardienne de l\'élunite : l\'Ombre d\'Elura. C\'était le capitaine du bateau, elle s\'est condamnée elle-même à errer au fond de l\'océan pour protéger la cargaison à jamais. Combattez-la, récupérez son médaillon, et remontez toutes les caisses de minerai.', },
    {'Apporter 8 Caisses de minerai d\'élunite et le Médaillon d\'Elura à Elanaria à Darnassus.', },
  },
  [1687] = {
    'Le phare hanté',
    {'Des fois, tard le soir, les gouvernantes de l\'orphelinat nous racontent des histoires qui font peur. C\'est GÉNIAL ! Il y en a une à propos d\'un fantôme qui hante un phare dans la marche de l\'Ouest. C\'était un pirate à qui d\'autres pirates ont pris son bateau. Waou !|n|nVous pourriez m\'emmener au phare de la marche de l\'Ouest ? Je veux voir le fantôme du capitaine ! Je resterai près de vous, c\'est promis, je ne m\'enfuirai pas ni rien...', },
    {'Emmenez l\'orphelin voir le phare sur la côte de la marche de l\'Ouest.', },
  },
  [1688] = {
    nil,
    {'J\'ai eu une étudiante du nom de Surena Caledon. Elle était là où vous êtes en ce moment, enthousiaste à apprendre la magie des démonistes, et talentueuse. En plus, elle était jeune et belle. Quand j\'y repense, quelle traînée !|n|nCette voleuse s\'est enfuie avec un truand, Erlan Trimelande. Sa perte est négligeable, mais je lui avais offert une écharpe de pierre de sang que je veux absolument récupérer.|n|nSa vie m\'importe peu maintenant. Vous la trouverez au champ de potirons des Saumepuits. Rapportez-moi ce qui m\'appartient.', },
    {'Retrouver l\'Écharpe de Surena pour Gakin le Tisse-noir à Hurlevent.', },
  },
  [1689] = {
    'Le lien',
    {'En retrouvant mon écharpe et en éliminant Surena, vous avez prouvé que vous étiez au moins aussi $Gtalentueux:talentueuse; qu\'elle.|n|nCela dit, vous avez terriblement besoin d\'entraînement. Vous pouvez manier les flux magiques, bien sûr, mais être démoniste, c\'est bien plus que cela.|n|nJe vais vous montrer comment contrôler un marcheur du Vide, mais avant, vous devez en invoquer un dans le cercle d\'invocation et le maîtriser avec les armes – physiques et magiques – dont vous disposez. Utilisez la magie que contient l\'écharpe sur le cercle d\'invocation en bas.', },
    {'Utilisez l\'Écharpe de pierre de sang pour invoquer et soumettre un marcheur du Vide, puis rapportez-la à Gakin le Tisse-noir, à Hurlevent.', },
  },
  [1690] = {
    'Châtier les Bat-le-désert',
    {'Vous là-bas ! Il est temps d\'aider la Compagnie des Eaux de Gadgetzan.|n|nLes nomades Bat-le-désert de Tanaris se sont emparés de presque tous les puits ! Si nous ne pouvons pas y avoir accès, notre réserve d\'eau va s\'assécher en un clin d\'œil. Si vous voulez vous faire bien voir, aidez-nous à faire la loi contre ces nomades !|n|nAllez à l\'est d\'ici et abattez dix bandits et dix larrons Bat-le-désert, puis revenez immédiatement me faire votre rapport. La justice n\'attend pour aucun homme... gobelin... bon, enfin bref, allez-y !', },
    {'Abattez 10 Bandits et Larrons Bat-le-désert à l\'est de Gadgetzan, puis revenez faire votre rapport à l\'ingénieur en chef Vizisanie.', },
  },
  [1691] = {
    'Continuer à châtier les Bat-le-désert',
    {'Nous avons maintenant besoin que vous vous attaquiez aux nomades Bat-le-désert les plus puissants. Vous avez fait du bon travail jusque-là, mais pour reprendre ces puits, il vaut mieux avoir à affronter le moins possible de ces pillards !|n|nCette fois, il faut que vous éliminiez des voleurs, des assassins et des mages de l\'ombre. Ils se trouvent à l\'est et au sud-est d\'ici.|n|nJe ne vais pas vous mentir, ils sont coriaces. Faites cela pour nous, et nous pourrons bientôt reprendre ce qui est nôtre.', },
    {'Tuez 10 Mages de l\'ombre Bat-le-désert, 8 Voleurs Bat-le-désert et 6 Assassins Bat-le-désert pour l\'ingénieur en chef Vizisanie à Gadgetzan.', },
  },
  [1692] = {
    'Forgeron Mathiel',
    {'J\'ai mis l\'élunite que vous avez récupérée dans une caisse. Portez-la au forgeron Mathiel, il s\'en servira pour fabriquer votre arme.|n|nMathiel est au sud, de l\'autre côté de ce bâtiment.', },
    {'Apportez la Caisse d\'élunite au Forgeron Mathiel.', },
  },
  [1693] = {
    'Armes en élunite',
    nil,
    nil,
  },
  [1698] = {
    'Yorus Brasselorge',
    {'Yorus Brasselorge a lancé un défi à tous les guerriers de l\'Alliance. Il attend à l\'Auberge de Comté-du-Lac, dans les Carmines, et promet une grande récompense à celui qui passera l\'épreuve.', },
    {'Parler à Yorus Brasselorge.', },
  },
  [1699] = {
    'Le défi de Rethban',
    {'J\'ai appelé cette épreuve le « défi de Rethban ». Pour passer l\'épreuve, tout ce que vous avez à faire c\'est d\'entrer dans les cavernes de Rethban, jusqu\'à la première fourche. Facile ! Sauf qu\'il y a certaines conditions...|n|nVous devez être de retour dans moins d\'une heure.|n|nEt il y a un tas de gnolls des Carmines sur le chemin.|n|nAvant de commencer, il faut que vous preniez une lampée de ma boisson personnelle : du Brasselorge Scalder !|n|nAlors qu\'en dites-vous ? Les cavernes de Rethban sont dans les collines, au nord de Comté-du-Lac. Êtes-vous $Gprêt:prête; à relever le défi de Rethban ?', },
    {'Entrer dans les Cavernes de Rethban jusqu\'à la première fourche, et revenir voir Brasselorge dans le temps imparti.|n|nVous ne devez pas mourir et libérer votre esprit.', },
  },
  [1700] = {
    nil,
    {'J\'ai pris des notes sur les techniques que j\'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie à Grimand Elmore. Il est ici dans le quartier des Nains, au magasin d\'armes.|n|nEt attention quand vous lui donnerez mes notes. Il est extrêmement fier de ses compétences, et il n\'aimera pas l\'idée que je puisse lui apprendre quelque chose...', },
    {'Porter les Notes de Furen à Grimand Elmore.', },
  },
  [1701] = {
    'Une cotte de mailles en acier trempé',
    {'Alors je vous ai donné un bon bouclier, mais on ne va pas s\'arrêter là. Je connais le secret pour fabriquer une Cotte de mailles extrêmement résistante. C\'est difficile à faire et demande des matériaux très rares, mais si vous voulez faire le travail sur le terrain, alors je vous en fabriquerai une.|n|nQu\'en dites-vous, $N ? Vous relevez le défi ? Je vais donc vous donner la liste des éléments dont j\'ai besoin et où les trouver.', },
    {'Réunir les matériaux dont Furen Barbe-longue a besoin et lui apporter à Hurlevent.', },
  },
  [1702] = {
    'Fabricant de bouclier',
    {'Vous avez montré vos talents en relevant le défi de Rethban, $N. Et je respecterai ma parole. Je vais vous donner votre récompense...|n|nSauf qu\'elle est à Hurlevent.|n|nParlez à mon ami, Furen Barbe-longue, dans le quartier des Nains de Hurlevent. C\'est le meilleur fabricant de boucliers que vous rencontrerez, et il me doit une faveur.|n|nTenez, apportez-lui ce tonneau de Brasselorge Scalder et demandez-lui un bouclier. Il vous en donnera un bon.', },
    {'Apportez le Tonneau de Scalder à Furen Barbe-longue.', },
  },
  [1703] = {
    nil,
    {'J\'ai pris des notes sur les techniques que j\'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie au Forgeron Mathiel. Il vit à Darnassus, assez loin d\'ici, mais je suis sûr qu\'il sera reconnaissant de pouvoir apprendre ce que j\'ai appris.', },
    {'Apporter les Notes de Furen à Mathiel.', },
  },
  [1704] = {
    'Pléthorloge Cléventail',
    {'J\'ai pris des notes sur les techniques que j\'ai mises au point en faisant votre armure, et je dois en faire parvenir une copie à Pléthorloge Cléventail. C\'est un forgeron gnome de Forgefer et quand il lira mes découvertes, je parie qu\'il s\'arrachera la barbe.', },
    {'Apporter les Notes de Furen à Pléthorloge Cléventail.', },
  },
  [1705] = {
    'Sang ardent',
    {'Je déteste l\'admettre, mais Furen a fait une découverte impressionnante. Mais pour être sûr je dois l\'essayer moi-même sur une armure. Si vous me procurez le matériel, $N, alors vous pourrez en avoir une.|n|nPour faire cette armure, il me faut des échantillons de sang ardent et du roc ardent.|n|nLe seul endroit où je sais en trouver est le bois de la Pénombre. Les worgens Plaie-de-nuit basés dans la mine du Destin de Roland ont du sang ardent, et leur chef, Videssac, devrait avoir le Roc.|n|nQue la chance soit avec vous, $N !', },
    {'Rapporter 20 Fioles de sang ardent et 1 Roc ardent à Grimand Elmore à Hurlevent.', },
  },
  [1706] = {
    'L\'armure de Grimand',
    nil,
    nil,
  },
  [1707] = {
    'Une prime pour les outres',
    {'Salutations, $N. Je m\'appelle Trimballot, et nous avons un travail important à vous confier, si vous vous sentez d\'attaque ! Hourra !|n|nIl n\'y a rien qui me ferait plus plaisir, en tant qu\'opérateur du robinet expérimenté, que de récupérer les outres de Bat-le-désert que vous trouverez dans le désert. C\'est notre eau de toute façon : les nomades l\'ont juste volée ! La Compagnie des Eaux de Gadgetzan vous offre un paquet pour cinq outres que vous rapporterez. Et ce qui est encore plus important, vous aidez Gadgetzan à s\'aider elle-même !', },
    {'Apportez 5 Outres de Bat-le-désert à l\'Opérateur de robinet Trimballot, à Gadgetzan.', },
  },
  [1708] = {
    'Corail de fer',
    {'Je veux essayer la nouvelle technique de Furen Barbe-longue sur une de mes pièces d\'armure. Et parce que vous avez aidé Furen et qu\'il m\'a aidé, je vous offrirai l\'armure que j\'aurai fabriquée !|n|nPour faire la pièce, j\'ai besoin d\'un corail spécial, du corail torride. Il pousse à un seul endroit : le long des côtes au sud du port de Menethil dans les Paluns.|n|nApportez-moi suffisamment de corail torride et je pourrai fabriquer l\'armure. Et dépêchez-vous, $N. Je suis impatient de commencer !', },
    {'Apportez 20 Coraux torrides à Pléthorloge Cléventail, à Forgefer.', },
  },
  [1709] = {
    'La création de Pléthorloge',
    nil,
    nil,
  },
  [1710] = {
    'Coquilles desséchées au soleil',
    {'Mon collègue, Furen Barbe-longue, a fait une découverte que je suis impatient d\'essayer. Je veux la tester sur une de mes nouvelles armures, car je pense que ses techniques me permettraient d\'améliorer la qualité de mes produits.|n|nVoulez-vous m\'aider ? Si vous me rapportez de quoi fabriquer l\'armure, alors j\'en ferai une pour vous.|n|nJ\'ai besoin de coquilles d\'œuf desséchées au soleil des wyvernes ailes-fières qui résident à Haut-Perchoir, dans les Mille pointes. Cherchez les coquilles au pied de leurs nids, et revenez quand vous en aurez assez.', },
    {'Apportez 20 Coquilles desséchées au soleil à Mathiel, à Darnassus.', },
  },
  [1711] = {
    'L\'armure de Mathiel',
    nil,
    nil,
  },
  [1712] = {
    'Cyclonien',
    {'J\'ai passé un temps considérable à observer ce site. J\'observe… Je verrai peut-être tomber le Grand Cyclonien ! Mais je n\'ai toujours pas trouvé un champion pour combattre le seigneur des Vents.|n|nPeut-être est-ce vous ?|n|nProuvez-le-moi. Rassemblez les éléments dont j\'ai besoin pour invoquer un Cyclonien, et je saurai que vous êtes $Gun grand guerrier:une grande guerrière;. Peut-être pouvez-vous le battre et récupérer son cœur de tourbillon.|n|nSi c\'est le cas, alors je transmettrai le pouvoir du cœur dans une arme que je vous donnerai.|n|nVoilà le parchemin qui liste les objets dont j\'ai besoin.', },
    {'Apportez les objets du Parchemin de Bath\'rah à Bath\'rah la Vigie des vents à Alterac.', },
  },
  [1713] = {
    'L\'invocation',
    {'Je suis prêt à faire mon rituel pour invoquer un Cyclonien. Quand il apparaîtra, vous devez l\'abattre et lui prendre son Cœur de tourbillon. Je l\'utiliserai pour faire une arme qui possédera les pouvoirs du Cyclonien.|n|n$N, êtes-vous $Gprêt:prête; à affronter le Maître des vents ?', },
    {'Apportez le Cœur de tourbillon à Bath\'rah la Vigie des vents.', },
  },
  [1714] = {
    'Essence d\'exil',
    nil,
    nil,
  },
  [1715] = {
    'L\'Agneau assassiné',
    {'Hum ! Dans le temps, tous les démonistes de Khaz Modan étaient entraînés par les maîtres de Gnomeregan, mais maintenant que nous avons été forcés de nous réfugier dans ce trou à rats qu\'est Forgefer, et que Magni a décidé de nous surveiller, nous sommes forcés d\'envoyer les novices étudier à Hurlevent.|n|nHeureusement, Gakin n\'est pas un empoté, vous pourrez donc continuer à recevoir un enseignement, mais cela m\'exaspère !|n|nEnfin, vous trouverez Gakin au sous-sol de « l\'Agneau assassiné » à Hurlevent.', },
    {'Aller voir Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.', },
  },
  [1716] = {
    'La dévoreuse d\'âmes',
    {'Une succube est une dévoreuse d\'âmes, une destructrice de cœurs et une dominatrice d\'esprits. Elle ne connaît rien d\'autre que le Mal.|n|nC\'est cette créature que vous allez apprendre à invoquer et à contrôler, mais on ne peut pas l\'amener dans notre monde sans un appât.|n|nAvec un symbole d\'amour comme appât, elle répondra sûrement à votre appel. Alors vous pourrez la maîtriser, et en faire votre esclave.|n|nIl va cependant être difficile de trouver quelque chose de cette nature. Vous devriez parler à Takar le Prophète. Vous le trouverez dans les Tarides de Kalimdor près du Camp Taurajo.', },
    {'Parler à Takar le Prophète dans les Tarides.', },
  },
  [1717] = {
    'Convocation de Gakin',
    {'$N ! Je ne pensais pas vous trouver ici, mais on m\'a demandé de vous chercher.|n|nIl est temps pour vous de reprendre l\'entraînement, vous devez aller voir Gakin la prochaine fois que vous passerez à Hurlevent. Il vous attend.', },
    {'Aller voir Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.', },
  },
  [1718] = {
    'de l\'île mortelle',
    {'Votre renommée en tant que $Gguerrier:guerrière; s\'accroît, $N. Il est temps de vous mesurer à l\'un de vos pairs.|n|nIl existe une île près des côtes des Tarides, au sud de Cabestan : l\'île de la Dispute. Les guerriers s\'y retrouvent.|n|nS\'y retrouvent et s\'affrontent.|n|nParlez au chef des guerriers de l\'île, Klannoc Macleod. S\'il pense que vous le méritez, alors il vous guidera plus avant sur la voie du guerrier.|n|nPour atteindre l\'île de la Dispute, cherchez des bancs de sable à faible profondeur le long de la côte des Marchands.', },
    {'Parler à Klannoc Macleod.', },
  },
  [1719] = {
    'La Dispute',
    {'Si vous voulez que je sois votre Maître, vous devez d\'abord passer la Dispute. C\'est une épreuve que nous, sur l\'île de la Dispute, aimons faire passer aux guerriers qui pensent être forts, et si vous réussissez ce test alors nous saurons que vous l\'êtes.|n|nPour commencer, marchez à travers cette foule là-bas, et allez jusqu\'à l\'âtre. Dites à Twiggy Tête-plate que vous êtes $Gprêt:prête;, il vous enverra des partenaires de combat.|n|nBattez-les tous, et il appellera le Grand Will. Tuez le Grand Will, et revenez me voir.', },
    {'Tuer le Grand Will et parler à Klannoc Macleod sur l\'île de la Dispute.', },
  },
  [1738] = {
    'Cœur du bois',
    {'En prévision de votre arrivée, j\'ai utilisé ma vision pour regarder à travers le monde et à travers le temps. J\'ai trouvé ce que vous cherchez.|n|nLors de la guerre des Anciens, deux amoureux sont tombés ensemble lors d\'une bataille. Là où ils sont morts, un arbre connu sous le nom de cœur du bois poussa, symbole de leur amour éternel.|n|nCe sera assez pour attirer une succube. Vous le trouverez dans les ruines d\'Ordil\'Aran, dans la partie nord-ouest de la forêt d\'Orneval.', },
    {'Trouver le Cœur du bois en Orneval et le porter à Gakin le Tisse-noir dans le Quartier des Mages de Hurlevent.', },
  },
  [1739] = {
    'Le lien',
    {'En utilisant le noyau du cœur du bois, vous serez en mesure de jeter le sort dans le cercle d\'invocation qui se trouve dans la crypte en bas afin d\'ouvrir un portail d\'où la succube arrivera.|n|nAttention, $N, les succubes arrivent à contrôler les esprits les plus forts.|n|nUne fois que vous l\'aurez vaincue et renvoyée dans le néant, revenez me voir pour que je vous apprenne comment l\'appeler et la contrôler.', },
    {'Utiliser le Noyau du cœur du bois pour invoquer et soumettre une succube, puis rapporter le Noyau de cœur du bois à Gakin le Tisse-noir, à l\'Agneau assassiné.', },
  },
  [1740] = {
    'L\'Orbe de Soran\'ruk',
    {'Quand les démons de la Légion sont tombés, leurs esprits furent emprisonnés dans des orbes et distribués à leurs mages et leurs démonistes.|n|nBeaucoup furent apportés en Azeroth par leurs serviteurs. Même fragmentés, ils gardent les pouvoirs du démon emprisonné à l\'intérieur.|n|nL\'orbe de Soran\'ruk a été brisé en deux morceaux, l\'un a été fragmenté pour être utilisé par les acolytes du Marteau du crépuscule dans les profondeurs de Brassenoire. L\'autre, le plus gros morceau, est en possession d\'un sorcier dans le donjon d\'Ombrecroc. Retrouvez les fragments et je pourrai réparer l\'orbe.', },
    {'Trouvez 3 Fragments de Soran\'ruk et 1 Grand fragment de Soran\'ruk et rapportez-les à Doan Karhan, dans les Tarides.', },
  },
  [1758] = {
    'Tome de la Cabale',
    {'Il faudra plus qu\'un simple cercle d\'invocation pour attirer un chasseur corrompu et le défier.|n|nMes trois acolytes et moi-même allons vous aider à créer les cercles magiques. Vous aurez besoin d\'un exemplaire du Tome de la Cabale, qui a été perdu depuis bien des années. L\'ouvrage a été écrit par le premier groupe de démonistes pour invoquer seul un chasseur corrompu.|n|nKrom Rudebras peut peut-être vous aider. Ce démoniste nomade passe son temps à accumuler des textes anciens et traîne parfois dans la bibliothèque à Forgefer.', },
    {'Parler à Krom Rudebras à Forgefer.', },
  },
  [1778] = {
    'Le Tome de divinité',
    {'Je vais devoir rentrer chez moi le plus rapidement possible. Heureusement, Stephanie fait de même pour rentrer à Hurlevent. J\'ai hâte de la revoir. A bientôt, $C.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [1779] = {
    'Le Tome de divinité',
    {'Je veux que vous preniez ceci, $N. Cela s\'appelle le Symbole de vie.|n|nVous avez montré que vous étiez charitable et $Gpatient:patiente;, maintenant je veux que vous me montriez votre pouvoir et vos talents au combat en tant qu\'adepte.|n|nMuiredon, mon mari, a rencontré récemment des nains sombrefers, et il s\'en est sorti de justesse. Il est à Forgefer, aux bons soins d\'un de nos prêtres.|n|nPrenez le Symbole et parlez-lui. Si vous pouvez l\'aider, alors nous nous reparlerons bientôt. Que la Lumière soit avec vous !', },
    {'Prendre le Symbole de vie et parler à Muiredon Forgeguerre à Forgefer.', },
  },
  [1780] = {
    'Le Tome de divinité',
    {'J\'amènerai ça aux enfants dès aujourd\'hui. Merci beaucoup, $C. Il est rare de nos jours qu\'$Gun homme:une femme; de votre trempe se montre dans cette ville, mais vous avez prouvé que les paladins à Hurlevent ne tourneront jamais le dos à ceux qui sont dans le besoin.|n|nAdieu.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1781] = {
    'Le Tome de divinité',
    {'Je veux que vous preniez ceci, $N. Cela s\'appelle un Symbole de vie.|n|nVous avez montré que vous étiez charitable et $Gpatient:patiente;, et maintenant il est temps de savoir si vous avez la puissance nécessaire pour contrôler un des plus grands dons de la Lumière.|n|nMon ami Gazin a croisé récemment des Défias à Elwynn près de la Veillée des héros – il s\'en est sorti de justesse. Il est près de l\'autel en train de se faire soigner par un de nos prêtres.|n|nPrenez le Symbole et parlez-lui. Si vous pouvez l\'aider, alors nous nous reparlerons bientôt. Que votre chemin soit éclairé par la Lumière !', },
    {'Porter le Symbole de vie à Gazin Tenorm à Hurlevent.', },
  },
  [1782] = {
    'L\'armure de Furen',
    nil,
    nil,
  },
  [1783] = {
    'Le Tome de divinité',
    {'J\'espionnais des nains sombrefers qui se terrent au sud du lac du Lit d\'Helm. Nous savions qu\'ils n\'étaient pas là pour rien, alors Narm et moi nous nous sommes rapprochés – assez près pour voir leur chef donner des ordres à ses hommes.|n|nNarm et moi nous avons tenté d\'en tuer quelques-uns, mais ils se sont révélés plus résistants que nous le pensions, et beaucoup plus nombreux. Narm m\'a dit de partir et de ramener du renfort, donc voilà pourquoi je suis là.|n|nNarm a besoin d\'aide, et je ne me reposerai pas tant qu\'il n\'en n\'aura pas trouvé.|n|nAllez-vous m\'aider, $N ?', },
    {'Prendre le Symbole de vie et ressusciter Narm Faulk dans Dun Morogh.', },
  },
  [1784] = {
    'Le Tome de divinité',
    {'Avant de tomber, Muiredon et moi avions presque vaincu un des espions sombrefers près de cette petite maison. Nous avons vu le capitaine leur passer des ordres, et nous avons cherché à le tuer pour récupérer ces ordres.|n|nCertaines personnes au conseil de Forgefer ne croient pas à la présence des Sombrefers en Dun Morogh. En récupérant un de ces scripts, nous aurions non seulement la preuve de leur présence ici, mais nous aurions aussi une idée de ce qu\'ils trament.|n|nRécupérez un de ces scripts et rapportez-le à Muiredon, $N.', },
    {'Récupérez un Document sombrefer près du lac du Lit d\'Helm, et rapportez-le à Muiredon Forgeguerre, à Forgefer.', },
  },
  [1785] = {
    'Le Tome de divinité',
    {'J\'peux déjà voir l\'visage d\'ma femme s\'illuminer de fierté. Vous devriez bouger vot\'postérieur tout de suite et aller la voir. J\'pense qu\'elle aura des choses à vous dire.|n|nLa Lumière soit avec vous, $C ! Je vous reverrai sur l\'champ de bataille contre le Fléau et ces damnés Sombrefers quand le temps viendra.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [1786] = {
    'Le Tome de divinité',
    {'Henze et moi sommes allés à la Veillée des héros, une île au milieu du lac du Cairn au nord-est d\'Elwynn. Nous avions entendu dire que des Défias avaient infiltré nos frontières et nous voulions le prouver aux conseillers du roi.|n|nNous en avons surpris en possession de documents, et nous les avons attaqués. Malheureusement, nous avons été rapidement submergés par des mages.|n|nHenze les a retenus pendant que je m\'enfuyais... C\'était cinglé de sa part, mais il était brave.|n|nIl est mort à présent. Pourriez-vous nous aider, $N ?', },
    {'Apporter le Symbole de vie et ressusciter Henze Faulk à Elwynn.', },
  },
  [1787] = {
    'Le Tome de divinité',
    {'Nous aurons le temps de parler du Symbole plus tard. Ce qui importe c\'est de récupérer les papiers que les Défias avaient sur eux. Si nous pouvons mettre la main dessus, nous serons en mesure de prouver que la Confrérie a infiltré Elwynn et nous aurons une idée de ce qu\'elle trame.|n|nJe ne suis pas assez remis pour combattre maintenant, $N. Pensez-vous pouvoir récupérer $Gseul:seule; ces papiers dans l\'île ?|n|nSi vous pouvez les récupérer, apportez-les à Gazin et dites-lui que je vais bien.', },
    {'Retrouver un Script Défias sur les Sorciers-voleurs défias d\'Elwynn et le rapporter à Gazin Tenorm à Hurlevent.', },
  },
  [1788] = {
    'Le Tome de divinité',
    {'Je vais porter le Script aux conseillers du roi après que Duthorian y aura jeté un coup d\'œil, ensuite allez parler à Duthorian. Il voudra sûrement vous féliciter !|n|nMerci encore, $N. J\'espère que l\'on se reverra. Je suis fier de vous avoir comme $Gallié:alliée;... et comme $Gami:amie;.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [1789] = {
    'Le Symbole de vie',
    nil,
    nil,
  },
  [1790] = {
    'Le Symbole de vie',
    nil,
    nil,
  },
  [1791] = {
    'La Vigie des vents',
    {'À présent que vous avez appris la posture berserker, vous aurez besoin d\'une belle arme avec laquelle l\'utiliser.|n|nAllez parler à Bath\'rah la Vigie des vents, un troll ermite qui vit entre les montagnes d\'Alterac et les Maleterres de l\'Est. C\'est un fabricant d\'armes très versé dans son métier et un puissant chaman.|n|nPour le trouver, allez à la rivière qui coule le long du côté est de Moulin-de-Tarren. Remontez-la vers le nord. Bath\'rah campe près des ruines jonchant la rive est de la rivière.', },
    {'Parler à Bath\'rah la Vigie des vents.', },
  },
  [1792] = {
    'Arme Tourbillon',
    nil,
    nil,
  },
  [1793] = {
    'Le Tome de la bravoure',
    nil,
    nil,
  },
  [1794] = {
    'Le Tome de la bravoure',
    nil,
    nil,
  },
  [1795] = {
    'Le lien',
    {'Si vous êtes suffisamment $Gpréparé:préparée;, alors nous pouvons commencer. Laissez-moi vous expliquer la procédure.|n|nJe vais commencer par créer un simple cercle d\'invocation. Quand j\'aurai fini, mes acolytes vont utiliser leurs bâtonnets de canalisation pour créer un cercle majeur.|n|nLisez alors l\'incantation du Tome de la Cabale, et le chasseur corrompu apparaîtra. Faites attention, $N. Un chasseur corrompu est un ennemi puissant, et j\'aimerais que vous gardiez la tête sur les épaules.', },
    {'Utiliser le Tome de la Cabale pour invoquer et soumettre un Chasseur corrompu, puis rapporter le Tome de la Cabale à Strahad Farsan, à Cabestan.', },
  },
  [1796] = {
    'Les composants de la robe sanglante dorée enchantée',
    {'Le premier objet que je vais vous aider à confectionner est une robe. Vous rassemblerez ses composants pour moi, et nous les assemblerons ensemble. Après quoi, si tant est que vous aurez réussi, vous aurez les premiers des nombreux objets qui vous aideront dans vos luttes.|n|nMais pour commencer, vous devez confectionner une robe d\'Arcana. Un tailleur peut vous les faire, ou peut-être que vous pourriez en acheter à quelqu\'un d\'autre, mais cela m\'impressionnerait que vous la confectionniez vous-même. Quelle que soit la manière dont vous vous la procurerez, apportez-moi la robe, et nous commencerons.', },
    {'Apportez une Robe d\'Arcana à Menara Taillevide, dans les Tarides.', },
  },
  [1798] = {
    'À la recherche de Strahad',
    {'Il est temps pour vous d\'apprendre à invoquer un chasseur corrompu, $N. Je n\'ai pas ni composants ni les objets nécessaires ici pour vous l\'enseigner, donc adressez-vous à Strahad Farsan, un membre de notre communauté.|n|nIl réside dans le port gobelin de Cabestan. Je vais lui envoyer un message pour lui annoncer votre venue.', },
    {'Parler à Strahad Farsan dans les Tarides.', },
  },
  [1799] = {
    'Fragments de l\'Orbe d\'Orahil',
    {'Bien, alors commençons.|n|nAllez d\'abord parler à mes acolytes à l\'intérieur et choisissez l\'une des voies qu\'ils vous proposeront de suivre... Ils vous en diront davantage eux-mêmes.|n|nEnsuite, vous devrez voyager en Désolace et prendre un Orbe infernal sur l\'un des démonistes du convent de Mannoroc. C\'est cet orbe que vous purifierez avec l\'aide d\'un mage du nom de Tabetha, au sud du marécage d\'Âprefange. Elle vous aidera en souvenir de notre histoire commune.|n|nNe revenez pas avant d\'avoir accompli les deux tâches que j\'ai requises auprès de vous.', },
    {'Parler aux acolytes de Menara dans la tour qui domine Cabestan et choisir de suivre l\'une de leurs voies.|n|nEnsuite, apporter un Orbe infernal à Tabetha, dans le marécage d\'Âprefange.', },
  },
  [1800] = {
    'La salle du trône de Lordaeron',
    {'La gouvernante de l\'orphelinat, à la maison, nous raconte de grandes histoires de bataille et de sagesse, si nous sommes gentils et que nous avons fait nos corvées. Une histoire raconte la chute de Lordaeron, et comment le maléfique Arthas a assassiné son père pour devenir le chef.|n|nIl n\'avait pas d\'honneur, $N ! Quand je serai grand, je serai un puissant guerrier de la Horde, et ma lame sera guidée par l\'honneur - jamais par le mal !|n|nVous voulez bien m\'emmener voir la salle du trône, s\'il vous plaît ? C\'est juste avant l\'endroit où il faut descendre pour aller à Fossoyeuse.', },
    {'Emmenez votre protégé à la vieille salle du trône de Lordaeron, qui se trouve juste avant l\'endroit où il faut descendre pour aller à Fossoyeuse.', },
  },
  [1801] = {
    'Tome de la Cabale',
    {'Il va falloir plus qu\'un simple cercle d\'invocation pour appeler le chasseur corrompu que vous allez affronter.|n|nMes trois acolytes et moi allons vous assister pour créer les cercles magiques. Vous avez besoin d\'un exemplaire du Tome de la Cabale, qui a été perdu depuis bien des années. Il a été écrit par le premier groupe de démonistes pour invoquer seul un chasseur corrompu.|n|nPeut-être que Jorah Annison peut vous aider. En ce moment, il est employé comme cartographe à Fossoyeuse, mais il en connaît plus que quiconque sur les textes anciens.', },
    {'Parler à Jorah Annison à Fossoyeuse.', },
  },
  [1802] = {
    'Tome de la Cabale',
    {'Il a été perdu, mais j\'ai une petite idée d\'où il se trouve.|n|nIl n\'en existe qu\'un seul exemplaire, en très mauvais état : déchiré à plusieurs endroits et en grande partie arraché de la reliure. La rumeur dit que cette partie serait entre les mains des centaures des Mille pointes.|n|nL\'autre partie a été perdue sur la côte ouest d\'Austrivage, alors qu\'elle était envoyée par bateau au port de Menethil. Elle n\'est jamais arrivée à destination.|n|nEn échange de ces informations, tout ce que je demande c\'est que vous le trouviez, et que vous me l\'apportiez afin que je puisse le voir.', },
    {'Retrouver le Tome moisi et le Manuscrit en lambeaux pour Krom Rudebras à Forgefer.', },
  },
  [1803] = {
    'Tome de la Cabale',
    {'Ah ! Je vois que vous avez les mêmes goûts de démoniste que moi. Vraiment, vouloir récupérer le Tome de la Cabale est une noble intention. Saviez-vous qu\'il était autrefois à Lordaeron ? Mais il a été abîmé, presque la moitié des pages ont été arrachées. Qui a pu faire une chose pareille ?|n|nUne rumeur circule à propos de cette moitié perdue : on dit qu\'elle serait entre les mains des centaures des Mille pointes.|n|nLe reste a été envoyé à Forgefer, mais a été perdu lors de son transport sur la côte ouest d\'Austrivage.', },
    {'Retrouver le Tome moisi et le Manuscrit en lambeaux pour Jorah Annison à Fossoyeuse.', },
  },
  [1804] = {
    'Tome de la Cabale',
    {'Ah ! C\'est difficile de le laisser partir. Mais vous l\'avez trouvé et vous avez des choses importantes à faire avec. S\'il vous plaît, dites bien à Strahad que j\'en veux une copie !|n|nPendant que vous étiez $Gparti:partie;, il vous a envoyé un message. Les acolytes qui vont participer à l\'invocation ont besoin de trois bâtonnets de canalisation, vous devez les trouver.|n|nIl ne sait peut-être pas où les chercher, mais moi si ! Les derniers à en avoir utilisé étaient des orcs du clan Gueule-de-dragon dans les Paluns, leurs magiciens doivent en posséder…', },
    {'Apportez le Tome reconstitué et 3 Bâtonnet de canalisation à Strahad Farsan, à Cabestan.', },
  },
  [1805] = {
    'Tome de la Cabale',
    {'C\'est l\'un des textes les plus intéressants que j\'ai parcouru au cours de ces dernières années. Ici, il n\'y a pas grand-chose, à part des livres de géographie, que j\'ai déjà tous lus... Strahad m\'en enverra peut-être une copie, quand il le pourra...|n|nÀ propos, il vous fait dire que pour remplir votre mission, il vous faudra trois bâtonnets de canalisation.|n|nPour vous remercier de m\'avoir laissé regarder ce texte, laissez-moi vous confier un secret : vous trouverez ces bâtonnets sur les orcs du clan Gueule-de-dragon dans les Paluns.', },
    {'Apportez le Tome reconstitué et 3 Bâtonnet de canalisation à Strahad Farsan, à Cabestan.', },
  },
  [1806] = {
    'Le test de droiture',
    {'Pourquoi n\'irions-nous pas à la forge pour commencer ? J\'ai préparé votre arrivée depuis quelque temps déjà et tout devrait être prêt.|n|nAprès cela, vous serez mieux $Gpréparé:préparée; que jamais pour défendre la Lumière, je vous le promets.|n|nJe dois vous avouer, $N, que je suis un peu envieux de votre réussite. Mais sachez que de pouvoir participer à ma manière à cette réussite me remplit d\'aise.', },
    {'Attendre que Jordan Morpuits finisse de forger votre arme.', },
  },
  [1818] = {
    'Parler à Dillinger',
    {'J\'ai entendu dire que le nécrogarde Dillinger avait un travail pour quelqu\'un comme vous. Si vous voulez prouver votre valeur aux forces de la Dame noire, alors présentez-vous devant Dillinger immédiatement.|n|nLe poste du nécrogarde Dillinger est à la frontière ouest de Brill, près du cimetière.', },
    {'Parler au Nécrogarde Dillinger à Brill.', },
  },
  [1819] = {
    'Ulag le Fendeur',
    {'Lorsque le Fléau s\'est abattu sur les Clairières de Tirisfal, nous avons capturé l\'un de ses serviteurs pour l\'étudier. C\'était un esprit libre, qui se nommait Ulag le Fendeur. Pourtant, malgré sa libre conscience, le roi-liche avait gardé son emprise sur lui.|n|nNous espérions trouver un moyen de le délivrer de cette influence, mais nous avons échoué. Il est temps de le libérer, maintenant...|n|nLibérez-le et tuez-le.|n|nEn actionnant le déclencheur de la Pierre du Crâne devant le Mausolée qui se trouve au nord, vous briserez le sceau magique qui le lie.|n|nAprès... Il faudra frapper vite et fort, $N !', },
    {'Tuer Ulag le Fendeur, puis parler au Nécrogarde Dillinger.', },
  },
  [1820] = {
    'Parler à Coleman',
    {'Vous avez prouvé votre valeur à la Dame noire, à présent vous pourrez peut-être la prouver à l\'un de ses sujets.|n|nColeman Farthing cherche un guerrier pour être son bras vengeur contre les ennemis des Réprouvés.|n|nVous le trouverez à « la Taverne des Pendus » dans l\'est de Brill.', },
    {'Parler à Coleman Farthing.', },
  },
  [1821] = {
    'L\'héritage des Agamand',
    {'J\'ai servi la famille Agamand tout le long de ma vie et ils ont été la cause de ma mort ! S\'ils sont maintenant les esclaves du roi-liche, ce n\'est que justice !|n|nÀ présent, je dois m\'approprier les derniers vestiges de leur honneur perdu. Dans leur crypte, je veux que vous voliez leur héritage familial : une épée, une hache, une dague et une masse, et que vous me les apportiez.|n|nLa crypte de la famille Agamand se trouve à la lisière nord des moulins d\'Agamand, sous la protection de créatures du Fléau errantes et des Agamands morts.', },
    {'Rapporter à Coleman Farthing la Hache de la famille Agamand, l\'Épée de la famille Agamand, la Masse de la famille Agamand et la Dague de la famille Agamand.', },
  },
  [1822] = {
    'Une arme en héritage',
    nil,
    nil,
  },
  [1823] = {
    'Parler à Ruga',
    {'Vous êtes un guerrier compétent à la renommée croissante. Peut-être êtes-vous $Gprêt:prête; pour l\'épreuve de Ruga Totem-de-rage ? Si c\'est le cas, alors allez trouver Ruga au Camp Taurajo dans les Tarides.|n|nIl cherche des guerriers qui accepteraient de passer son épreuve.', },
    {'Parler à Ruga Totem-de-rage.', },
  },
  [1824] = {
    'L\'épreuve du Champ des géants',
    {'Pour passer l\'épreuve, vous devez voyager vers le sud jusqu\'au Champ des géants. Là-bas, vous trouverez un grand nombre d\'insectes rampants. Ils sont récemment arrivés dans les Tarides et je pense que cela ne présage rien de bon.|n|nApportez-moi leurs antennes mobiles, et ne perdez pas de temps, $N. Ces antennes ne remuent pas longtemps. Apportez-les-moi dans le temps alloué, et vous aurez réussi l\'épreuve.', },
    {'Apporter 5 Antennes mobiles à Ruga Totem-de-rage au Camp Taurajo.', },
  },
  [1825] = {
    'Parler à Thun\'grim',
    {'Thun\'grim Mirefeu, un forgeron orc de grande renommée, a entendu parler de vos exploits au service de la Horde. Il voudrait vous confectionner un équipement d\'armure et vous propose d\'aller en discuter immédiatement avec lui.|n|nThun\'grim campe à l\'est de la Croisée dans les Tarides.', },
    {'Parler à Thun\'grim Mirefeu dans les Tarides.', },
  },
  [1838] = {
    'Armure de brutalité',
    {'J\'ai entendu parler de votre force et de votre courage, et je voudrais faire pour vous une armure complète qui vous aidera à mesure que vos exploits passeront à la postérité.|n|nMais faire une armure est une véritable quête en soi $N, et je vais avoir besoin de votre aide et de celle d\'autres forgerons de la Horde.|n|nTenez, prenez ce parchemin. J\'ai passé de nombreuses nuits à lutter avec mes yeux presque aveugles pour écrire tout ce dont j\'ai besoin pour l\'armure. Apportez-moi ce qui est noté sur ce parchemin et je créerai pour vous la première pièce de l\'ensemble.', },
    {'Apportez à Thun\'grim Mirefeu 15 Lingots de Fer cendré, 10 Azurites en poudre, 10 Barres de Fer et une Fiole de Phlogiston.', },
  },
  [1839] = {
    'Ula\'elek et les Gantelets de brutalité',
    {'Ula\'elek, le forgeron troll, va façonner pour vous les gantelets de brutalité. Il demeure en Durotar, au Village de Sen\'jin, avec ses frères Sombrelances, et il attend votre arrivée.', },
    {'Parler à Ula\'elek en Durotar.', },
  },
  [1840] = {
    'Orm Sabot-de-pierre et le Camail de brutalité',
    {'Orm Sabot-de-pierre est très respecté pour son habileté. Il va fabriquer pour vous le Camail de brutalité.|n|nCherchez-le aux Pitons-du-Tonnerre, près du bassin du grand totem central de la cité.', },
    {'Parler à Orm Sabot-de-pierre aux Pitons-du-Tonnerre.', },
  },
  [1841] = {
    'Velora Nitely et les garde-jambes de brutalité',
    {'On dit qu\'avant de mourir, Velora Nitely était l\'un des plus grands forgerons d\'armures de Lordaeron. La mort, semble-t-il, n\'a pas affecté ses talents. Allez voir Velora : elle fabriquera vos garde-jambes de brutalité.|n|nVelora officie à Fossoyeuse de Lordaeron, dans le quartier des Marchands.', },
    {'Parler à Velora Nitely à Fossoyeuse.', },
  },
  [1842] = {
    'Les sabots de satyre',
    {'Je peux vous faire une paire de gantelets de brutalité, et ils seront porteurs d\'une grande magie, mais pour cela, vous devez d\'abord m\'apporter cette magie.|n|nLes satyres parcourent le nord-est d\'Orneval à cause du pouvoir de la forêt. Ils se nourrissent de sa pureté, ils aspirent son innocence comme des sangsues et la corrompent. Ceux d\'entre eux ont des sabots fendus et abîmés. Ils ont volé plus de magie à la forêt que les autres. |n|nCes sabots détiennent un grand pouvoir. J\'en aurai besoin pour façonner vos gantelets.', },
    {'Rapporter 7 Sabots fendus de satyre à Ula\'elek au village de Sen\'jin en Durotar.', },
  },
  [1843] = {
    'Gantelets de brutalité',
    nil,
    nil,
  },
  [1844] = {
    'La corne de chimère',
    {'Je veux bien vous faire un casque, mais vous devez d\'abord me montrer que vous en êtes digne.|n|nBlottie sur les flancs sud-ouest des Serres-Rocheuses se trouve le Val calciné. C\'était autrefois un endroit verdoyant, mais il est désormais souillé et étouffé sous la cendre. Les créatures qui y vivent encore en sont folles de douleur et de désespoir.|n|nC\'est là que je vous envoie, $N.|n|nVous devez aller au Val calciné et trouver une matriarche chimère. Tuez-la, libérez-la de sa misère. Apportez-moi sa corne galvanisée comme preuve et je vous ferai votre casque.', },
    {'Apporter une Corne galvanisée à Orm Sabot-de-Pierre aux Pitons-du-Tonnerre.', },
  },
  [1845] = {
    'Camail de brutalité',
    nil,
    nil,
  },
  [1846] = {
    'Les tibias de Gueule-de-dragon',
    {'Pour faire les Jambières de brutalité, j\'ai besoin de quelques solides tibias. Les orcs Gueules-de-dragon des Paluns ont de jolis tibias bien épais. Je vais en avoir besoin.|n|nMais ils doivent être vraiment solides. Prenez soin de tester les tibias que vous ramasserez. Si vous pouvez les casser à mains nues, c\'est qu\'ils ne sont pas assez solides pour que je puisse travailler avec.', },
    {'Apporter 8 Solides tibias de Gueule-de-dragon à Velora Nitely, à Fossoyeuse.', },
  },
  [1847] = {
    'Garde-jambes de brutalité',
    nil,
    nil,
  },
  [1848] = {
    'Haubert de brutalité',
    nil,
    nil,
  },
  [1858] = {
    'La Main brisée',
    {'Je vous le laisse pour ouvrir la sacoche de Tazan et me rapporter son contenu. Le mécanisme de verrouillage est complexe, ce serait sans doute plus facile si vous trouviez la clé.|n|nComme elle n\'était pas sur le corps de Tazan, je ne peux que supposer qu\'il a confié la clé à quelqu\'un... Oh oui ! C\'est ça ! Il avait un aide nommé Gamon. Un ivrogne, vous le trouverez probablement à la taverne. Peut-être que vous pourrez lui prendre la clé en douceur.', },
    {'Voler la Clé de Tazan puis l\'utiliser pour ouvrir sa Sacoche et livrer son contenu à Therzok dans la Faille de l\'Ombre à Orgrimmar.', },
  },
  [1859] = {
    nil,
    {'Parlez moins fort, $N ! Ouais, je sais qui vous êtes ! On m\'a fait un topo.|n|nD\'après ce qu\'on entend dire de vous, vous vous débrouillez au combat et vous employez la ruse à l\'occasion.|n|nJ\'ai raison ?|n|nDe toute façon, vous devriez aller voir Therzok à Orgrimmar. Il a quelque chose à vous proposer.', },
    {'Aller voir Therzok dans la Faille de l\'Ombre à Orgrimmar.', },
  },
  [1860] = {
    'Parler à Jennea',
    {'Nous, les mages, avons une tâche à accomplir. Une tâche essentielle pour la sécurité de Hurlevent et de la forêt.|n|nJennea Cannon vous donnera plus de détails. Elle étudie dans le sanctuaire du Sorcier, dans le quartier des Mages de Hurlevent. Hâtez-vous d\'aller la voir.', },
    {'Parler à Jennea Cannon à Hurlevent.', },
  },
  [1861] = {
    'Le lac Miroir',
    {'Les importantes luttes mystiques que le monde a vécues ont fait déborder les courants magiques de leurs canaux autrefois stables. Nous essayons de déterminer quels effets ces changements ont provoqué et certains d\'entre nous craignent le pire !|n|nMais je vous en dirai davantage plus tard. Pour l\'instant, nous avons besoin de vous pour recueillir des informations.|n|nTenez, prenez ce flacon. Allez au bas de la chute d\'eau du lac Miroir, au sud-ouest des portes de Hurlevent, et prélevez un échantillon de cette eau. Apportez-le-moi pour que je puisse vérifier si l\'eau est contaminée par la magie.', },
    {'Apporter un échantillon d\'Eau du lac Miroir à Jennea Cannon à Hurlevent.', },
  },
  [1878] = {
    'Une prime pour les outres',
    nil,
    nil,
  },
  [1879] = {
    'Parler à Bink',
    {'$N ! Bink, ma collègue de Forgefer, vous salue. Elle a une mission qu\'elle ne veut confier qu\'à un mage ! Avez-vous cette qualification, $N ?|n|nDans ce cas, adressez-vous à elle. Elle passe son temps dans le Hall des Mystères de la Garde mystique de Forgefer.', },
    {'Parler à Bink à Forgefer.', },
  },
  [1880] = {
    'Bidulotron de youplala',
    {'Nous, les mages, nous faisons plus qu\'agiter les doigts et faire quelques jolies étincelles ! Nous contrôlons la magie, le tissu de base de notre monde ! Et cela nécessite beaucoup de soin et de résolution. Et de connaissances... tant de connaissances !|n|nL\'une de mes inventions, le Bidulotron de Youplala, permet de rassembler et de stocker d\'énormes quantités d\'informations. Mais je l\'ai perdu ! Quand nous nous sommes enfuis de notre maison de Gnomeregan, je l\'ai oublié dans un coffre d\'une de nos huttes, à l\'extérieur de la ville, et maintenant, la place est envahie par des gnomes lépreux !|n|nJe vous en prie, $N, récupérez mon Bidulotron !', },
    {'Rapporter à Bink son Bidulotron de Youplala.', },
  },
  [1881] = {
    'Parler à Anastasia',
    {'$N, Anastasia Hartwell a une tâche à proposer à quelqu\'un de votre valeur. Allez la voir dans le quartier de la Magie de Fossoyeuse et préparez-vous à accomplir votre première tâche pour les mages des Réprouvés.', },
    {'Allez voir Anastasia Hartwell.', },
  },
  [1882] = {
    'La ferme des Balnir',
    {'Les Maleterres de l\'Est sont une aberration. Engendrées par le roi-liche, elles étendent leur magie dans le sol, corrompant et tuant tout ce qui vit. Bien que les forces destructrices de la corruption aient un certain charme, nous, les mages des Réprouvés, pensons que cette façon de faire est chaotique et doit être arrêtée.|n|nMais d\'abord, nous devons mesurer leur étendue dans Tirisfal. Allez à la ferme des Balnir, à l\'est de Tirisfal. Il y a des fleurs qui poussent dans le jardin, des gueules-de-loup. Cueillez-les et revenez me voir.', },
    {'Apporter des Gueules-de-loup du jardin des Balnir à Anastasia Hartwell dans le Quartier de la Magie de Fossoyeuse.', },
  },
  [1883] = {
    'Parler à Un\'thuwa',
    {'Un\'thuwa, le mage tribal du village de Sen\'jin, a détecté une perturbation dans les courants magiques de Durotar et demande de l\'aide. Allez voir Un\'thuwa et faites ce que vous pouvez pour l\'aider.|n|nEn retour, de nouveaux secrets vous seront révélés.', },
    {'Aller voir Un\'thuwa.', },
  },
  [1884] = {
    'Les Tas de Ju-Ju',
    {'Le démoniste Zalazane des îles de l\'Écho a perturbé le flux magique en Durotar. Il l\'a fait par l\'intermédiaire de fétiches infectés, des tas de Ju-ju, qu\'il a placés dans ses huttes sur l\'île principale d\'Écho.|n|nCes tas perturbent la faune et la flore et accroissent le pouvoir des sorciers et des créatures infernales qui se cachent dans les coins sombres du pays.|n|nVous devez détruire les tas de Ju-ju, $N, avant que le flux de magie ne soit altéré pour toujours.', },
    {'Détruire 4 Tas de Ju-Ju, puis retourner voir Un\'thuwa au village de Sen\'jin.', },
  },
  [1885] = {
    nil,
    {'$N ? Pas vraiment ce à quoi je m\'attendais, compte tenu de l\'intérêt que Carkad lui-même manifeste pour vous ! Comme quoi les apparences sont parfois trompeuses, non ?|n|nPeu importe, vous devez aller le voir dès que possible. Autant que vous ne sachiez pas ce qui est arrivé au dernier qui a ignoré ses sommations.', },
    {'Aller voir Mennet Carkad dans le Quartier des Voleurs de Fossoyeuse.', },
  },
  [1886] = {
    'Les nécrotraqueurs',
    {'Si vous voulez rejoindre les nécrotraqueurs, la garde d\'élite du seigneur Varimathras, vous devez prouver votre valeur.|n|nJe ne vais pas vous mentir, $N, cette tâche pourrait bien signifier votre mort.|n|nIl y a certaines choses auxquelles il faut prêter attention. J\'ai besoin des effets personnels d\'Astor Hadren, un messager qui voyage entre les Pins-Argentés et Fossoyeuse. Je vous laisse le choix de la méthode.|n|nMoins vous en saurez, mieux ça vaudra pour vous. Réussissez et je vous en dirai plus.', },
    {'Trouver la Lettre de recommandation d\'Astor et l\'apporter à Mennet Carkad dans le Quartier des Voleurs.', },
  },
  [1898] = {
    'Les nécrotraqueurs',
    {'La lettre de recommandation devrait être suffisante pour convaincre Andron que vous êtes $Gle messager:la messagère; qu\'il attendait. J\'ai déjà rencontré Andron, il n\'est pas assez intelligent pour être soupçonneux.|n|nLe seigneur Varimathras suspecte Andron d\'avoir fourni de l\'aide à un autre groupe. Il exige de savoir lequel et en veut la preuve.|n|nJe veux que vous alliez voir Andron pour obtenir cette information. Vous le trouverez à son magasin près de l\'Apothicarium.', },
    {'Aller voir Andron Gant à Fossoyeuse.', },
  },
  [1899] = {
    'Les nécrotraqueurs',
    {'Vous trouverez les informations qui intéressent vos employeurs dans le grand livre sur l\'étagère derrière moi. Apportez-leur avec mes respects et dites-leur que je préférerais que ce soit vous qu\'ils envoient, si ce qu\'ils trouvent leur semble avoir assez de valeur, pour continuer notre petit accord.', },
    {'Apporter le Grand Livre d\'Andron à Mennet Carkad dans le Quartier des Voleurs de Fossoyeuse.', },
  },
  [1918] = {
    'Les éléments souillés',
    {'Sur l\'élémentaire vaincu, vous trouvez un globe d\'eau, extrêmement lumineux, dont le contenu semble vraiment répugnant. Apparemment, l\'essence qui a souillé les eaux du lac Mystral est également présente dans les eaux du globe.|n|nCe genre de découverte n\'est pas en mesure d\'intéresser le commun des mortels. Mastok Torvesiffle, au poste de Bois-brisé, pourrait bien avoir une idée plus précise à ce sujet.', },
    {'Apportez le Globe d\'eau souillée à Mastok Torvesiffle, au Poste de Bois-Brisé, en Orneval.', },
  },
  [1919] = {
    'Rendre compte à Jennea',
    {'Vous connaissez de mieux en mieux le métier, jeune $N. Vous vous sentez d\'attaque pour commencer vos vraies leçons maintenant ? Pour prendre part à la guerre secrète que nous menons ?|n|nSi oui, allez voir Jennea Cannon au sanctuaire du Sorcier, dans le quartier des Mages de Hurlevent. Elle vous confiera une tâche qui sera votre première fenêtre sur le monde invisible.', },
    {'Parler à Jennea Cannon à Hurlevent.', },
  },
  [1920] = {
    'Trouver le Solitaire bleu',
    {'On nous a rapporté un incident qui est survenu à la taverne du « Solitaire bleu » dans le quartier des Mages. Des créatures étranges et invisibles rôdent dans la taverne et je crains qu\'une faille de mana ne se soit formée là-bas.|n|nIl faut que vous y alliez pour neutraliser ces créatures. Sur place, utilisez l\'incantation de manifestation pour les rendre visibles, puis capturez-les avec un coffre de retenue. Quand vous en aurez suffisamment, revenez me voir avec les coffres remplis, les coffres vides et l\'incantation.', },
    {'Obtenir une Incantation de manifestation et une Caisse de coffres de retenue placée derrière Jennea Cannon. Apporter 3 Coffres de retenue remplis à Jennea Cannon au Sanctuaire du sorcier.', },
  },
  [1921] = {
    'Rassembler les matériaux',
    {'Vous avez bien servi les mages, et il est temps de vous attribuer votre robe de sorcier. Wynne Larson peut la réaliser pour vous, mais il faudra lui fournir les matériaux nécessaires. |n|nLa robe sera faite de lin, ce qui ne sera pas difficile à trouver, mais vous devrez aussi fournir des gemmes chargées de la faille. On ne peut les trouver que dans la mine du Ru d\'argent à Loch Modan, dans les caisses laissées par la Ligue des mineurs nains. |n|nRassemblez le lin et les gemmes et apportez-les à Wynne Larson, chez les couturiers Larson, dans le quartier des Mages.', },
    {'Apporter 10 morceaux d\'Etoffe de lin et 6 Gemmes chargées de la faille à Wynne Larson à Hurlevent.', },
  },
  [1938] = {
    'Traité d\'Ur sur la Magie des Ombres',
    {'Autrefois, trois mages étudiaient dans cette tour, jusqu\'à ce que l\'un d\'entre eux tombe dans les travers de la magie noire. On l\'a pressé de se détacher de ses travaux maléfiques, mais il n\'a pas pu résister. Il fut alors banni. |n|nLe mage renégat a élu domicile dans la tour d\'Ilgalar, dans les Carmines, et il a emporté avec lui un livre très puissant : le « Traité d\'Ur sur la Magie des Ombres ». |n|nNous, mages de Hurlevent, voulons récupérer ce livre. Volez-le dans la tour d\'Ilgalar et rapportez-le.', },
    {'Apportez le « Traité d\'Ur sur la magie des Ombres » au Grand Sorcier Andromath à Hurlevent.', },
  },
  [1939] = {
    'Grand sorcier Andromath',
    {'Le grand sorcier Andromath souhaite vous parler, $N. Il est en haut du sanctuaire du Sorcier, dans le quartier des Mages de Hurlevent.|n|nIl serait sage d\'aller le voir, car Andromath est l\'un des mages les plus puissants de Dalaran. Avec lui, le Conseil est en effet un Haut Conseil.', },
    {'Aller voir le Grand Sorcier Andromath.', },
  },
  [1940] = {
    'Soie d\'araignée en parfait état',
    {'Vous avez servi sans faille, $N. Je pense qu\'il est temps pour vous de revêtir un vêtement plus adapté à votre statut. Si vous allez chercher les matériaux nécessaires, nous ferons faire la robe qui convient.|n|nVous devez pénétrer dans le bois de la Pénombre et chasser les araignées solitaires putrides qui s\'y cachent. Prélevez leur soie, mais uniquement la plus fine et la plus pure. Quand vous en aurez suffisamment, apportez-la à Wynne Larson, des Couturiers Larson, dans le quartier des Mages. Elle confectionnera votre robe.', },
    {'Apporter 8 Soies d\'araignée en parfait état à Wynne Larson à Hurlevent.', },
  },
  [1941] = {
    'Robe en tisse-mana',
    nil,
    nil,
  },
  [1942] = {
    'L\'Habit du noeud astral',
    nil,
    nil,
  },
  [1943] = {
    'Parler à Deino',
    {'La mage trolle Deino a besoin de votre aide, $N. Elle réside à Orgrimmar, au pavillon de Buissombre.', },
    {'Aller voir Deino.', },
  },
  [1944] = {
    'Les Eaux de Xavian',
    {'La ville légendaire de Xavian est enfouie au plus profond des terres orientales d\'Orneval et les initiés connaissent bien son histoire. Il est dit que les eaux de Xavian ont des pouvoirs magiques énormes.|n|nJe voudrais un échantillon de ces eaux, pris à la source.|n|nPrenez ce flacon et allez à Xavian. Recueillez de l\'eau en bas de la chute la plus haute et rapportez-la-moi. Et prenez garde en vous déplaçant dans la cité ancienne : les satyres se sont installés dans les ruines et ils n\'aiment pas que les mages viennent fourrer leur nez dans leurs affaires.', },
    {'Apportez l\'Échantillon d\'Eau de Xavian à Deino à Orgrimmar.', },
  },
  [1945] = {
    'Les sœurs rieuses',
    {'En remerciement de vos services, j\'ai pris des dispositions pour vous faire confectionner de nouvelles robes, à condition que vous alliez chercher les matériaux nécessaires... |n|nPour ces robes, vous devez vous rendre en Orneval et prélever des boucles de cheveux sur les sœurs rieuses, les dryades qui se réunissent près de la retraite de Raynebois.|n|nUne fois en possession de leurs cheveux, apportez-les à Kil\'hala, un tailleur troll qui se trouve à la Croisée, dans les Tarides. Il vous attend et coudra vos robes.', },
    {'Apporter 12 Cheveux de sœurs rieuses à Kil\'hala à la Croisée.', },
  },
  [1946] = {
    'L\'Habit du néant',
    nil,
    nil,
  },
  [1947] = {
    'Voyager vers le Marais',
    {'Il est à présent temps pour vous d\'obtenir votre baguette de mage. Tout d\'abord, allez voir Tabetha, l\'ermite humaine du marécage d\'Âprefange. Sa cabane se trouve au fin fond du marais, à l\'ouest de Theramore.|n|nAdressez-vous à elle, car son savoir est immense. Vous trouverez sa cabane à l\'ouest de Theramore, et juste au nord des ruines Cognepierres.', },
    {'Aller voir Tabetha.', },
  },
  [1948] = {
    'Les Objets de Puissance',
    {'La fabrication d\'une baguette de mage n\'est pas aisée. Il faut des substances rares et il faut fabriquer un récipient pour recueillir de grandes quantités d\'énergie magique. Vous devez me rapporter tout ça.|n|nJ\'ai écrit sur ce parchemin ce dont vous aurez besoin et des instructions sur la façon de les obtenir. Apportez-moi exactement ce qui est sur cette liste et suivez mes instructions à la lettre, car sinon les choses pourraient... mal tourner au moment de la fabrication de votre baguette magique.', },
    {'Apporter 1 Jade et le Roncier de foudre à Tabetha, dans le marécage d\'Âprefange.', },
  },
  [1949] = {
    'Des secrets cachés',
    {'Pour faire votre baguette magique, je dois lire des passages d\'un certain livre. Ce livre, intitulé « Rituels du pouvoir », a été écrit par le magus Tirth.|n|nJe n\'ai pas d\'exemplaire de ce livre et aucune des grandes bibliothèques de ce monde n\'en possède un. Vous devez donc aller voir Tirth et l\'obtenir de lui.|n|nBonne chance ! Tirth était un grand mage et un grand savant, mais maintenant il passe tout son temps aux courses des gnomes et des gobelins des Salines, à boire et à parier.', },
    {'Parler au magus Tirth dans les Salines.', },
  },
  [1950] = {
    'Trouver le Scoop',
    {'Je peux vous aider pour le livre, mais d\'abord, vous devez m\'aider !|n|nL\'ouvrage que vous cherchez est dans mon coffre-fort, fermé magiquement. Pour l\'ouvrir, il faut prononcer une incantation spéciale et je ne me souviens plus de l\'incantation ! D\'habitude, mon assistant m\'aide à me rappeler de ces choses, mais je ne le trouve nulle part.|n|nSi vous voulez mon livre, trouvez d\'abord mon apprenti ! Demandez aux gens le long de la piste. Avec un peu de chance, quelqu\'un l\'aura vu. Ramenez-le ici, ou au moins qu\'il vous donne l\'incantation pour ouvrir le coffre !', },
    {'Trouvez l\'Incantation pour ouvrir le coffre-fort de Tirth, puis retournez voir Tirth.', },
  },
  [1951] = {
    'Rituels du Pouvoir',
    {'Hum... Maintenant que j\'y pense, je n\'ai plus ce livre ! Vous voyez, j\'avais quelques dettes de jeu et pour les régler, j\'ai vendu ma dernière copie des « Rituels du pouvoir » à un membre du clergé...|n|nUn membre de la Croisade écarlate. Il a dû le mettre dans la bibliothèque du monastère Écarlate dans les clairières de Tirisfal !|n|nSi vous voulez ce livre, il va falloir que vous alliez le chercher au monastère. Et désolé pour tout ce tracas. Je ne suis plus moi-même ces derniers temps...', },
    {'Apportez le livre des « Rituels du pouvoir » à Tabetha dans le marécage d\'Âprefange.', },
  },
  [1952] = {
    'La baguette du mage',
    {'Je vais fabriquer les baguettes magiques maintenant.', },
    {'Parler à Tabetha après son rituel.', },
  },
  [1953] = {
    'Retourner dans le Marais',
    {'Il est temps pour vous de parler à l\'ermite Tabetha, $N. Elle vous donnera des indications sur la fabrication de l\'un des objets les plus importants pour les mages.|n|nLa cabane de Tabetha est loin dans le marécage d\'Âprefange, à l\'ouest de Theramore.', },
    {'Aller voir Tabetha.', },
  },
  [1954] = {
    'L\'orbe infernal',
    {'D\'abord, il faut acquérir un orbe puissant. Les démonistes de la Lame ardente ont des orbes splendides, de qualité... Dommage qu\'ils soient liés à des démons ! Mais ça peut s\'arranger. |n|nRendez-vous en Désolace et prenez un orbe infernal à un Invocateur démoniste. Ils se retrouvent au convent de Mannoroc. |n|nLorsque vous aurez cet orbe, rapportez-le.', },
    {'Apporter un Orbe infernal à Tabetha dans le marécage d\'Âprefange.', },
  },
  [1955] = {
    'L\'Exorcisme',
    {'Maintenant que nous avons l\'orbe de l\'Invocateur, nous devons exorciser le démon qu\'elle contient. Je peux y arriver. C\'est même la partie facile.|n|nVous, vous allez avoir à faire le plus dur : tuer le démon quand il va sortir.|n|nEt il va falloir faire vite, sans ça, il se réfugiera dans l\'orbe et il faudra tout recommencer !|n|nPréparez-vous. Apportez vos sorts les plus puissants et gardez vos potions à portée de la main. Et amenez un ami, si vous en avez un. Parce que ça ne va pas être joli...', },
    {'Tuez le démon de l\'Orbe, puis parlez à Tabetha.', },
  },
  [1956] = {
    'L\'énergie d\'Uldaman',
    {'Le démon a été enlevé, et maintenant il nous faut une source d\'énergie. Malheureusement, les plus puissantes sont les plus anciennes et les plus difficiles à acquérir ! Le destin n\'est pas tendre avec nous, hein ? |n|nIl va falloir que vous alliez à Uldaman pour y vaincre la sentinelle d\'obsidienne. Il est grand, il est fort, et sa source d\'énergie est pleine... d\'énergie ! |n|nJe vous souhaite beaucoup de chance, $N. Et si vous n\'avez pas cette chance, eh bien... C\'était un plaisir d\'avoir pu faire votre connaissance.', },
    {'Récupérer une Source d\'énergie en obsidienne et la rapporter à Tabetha dans le marécage d\'Âprefange.', },
  },
  [1957] = {
    'Les éruptions de mana',
    {'Nous avons presque fini, mais la dernière étape est la plus périlleuse, $N.|n|nJ\'ai l\'orbe d\'invocateur vide, prêt à être ensorcelé. Nous le ferons en canalisant l\'énergie d\'une faille de mana. Je jetterai un sort qui va en ouvrir une pour un court moment. Des créatures issues du mana en surgiront. Vous devrez combattre ces éruptions de mana pour extraire leur puissance, dont je m\'emparerai.|n|nTuez suffisamment d\'éruptions de mana avant que la faille ne se referme et je canaliserai toute leur énergie dans votre orbe.', },
    {'Tuer 12 Eruptions de mana dans la limite de temps imposée.', },
  },
  [1958] = {
    'L\'énergie céleste',
    nil,
    nil,
  },
  [1959] = {
    'Rendre compte à Anastasia',
    {'Les mages de Fossoyeuse ont noté une perturbation magique dans la ville et ont demandé à tous les mages de la Horde d\'enquêter.|n|nAnastasia Hartwell vous en dira plus. Allez la voir dans le quartier de la Magie de Fossoyeuse.', },
    {'Allez voir Anastasia Hartwell.', },
  },
  [1960] = {
    'Enquêter dans le magasin de l\'Alchimiste',
    {'L\'échoppe d\'alchimiste d\'Algernon, à l\'Apothicarium, est l\'objet de curieux troubles. Des créatures magiques, faites seulement de magie, la parcourent. Il doit bien y avoir une raison, et nous devons la découvrir !|n|nEnquêtez à ce propos et capturez ces créatures. Prenez des coffres de stockage et un parchemin, derrière moi. Utilisez-le à l\'échoppe pour rendre les créatures visibles, assujettissez-les à l\'aide de vos sorts, puis capturez-les dans les coffres. Rapportez les coffres pleins, ceux qui sont vides et l\'incantation.', },
    {'Obtenir une Incantation de Manifestation et une Caisse de Coffres de retenue placée derrière Anastasia Hartwell. Apporter 3 Coffres de retenue remplis, la Caisse de Coffres de retenue et l\'Incantation de Manifestation à Anastasia Hartwell à Fossoyeuse.', },
  },
  [1961] = {
    'Rassembler les matériaux',
    {'Il est temps pour vous de porter vos premières robes de mage, $N. Elles sont le signe de votre statut et un témoignage de votre valeur.|n|nPour gagner ces robes, il vous faudra aller dans la forêt des Pins-Argentés et prendre des gemmes de mana aux mages de Dalaran. Leurs croyances sont semblables aux nôtres, il est donc assez désagréable de les assassiner, mais s\'ils ne sont pas assez forts pour résister, alors ils ne méritent pas de vivre.|n|nApportez les gemmes et une longueur de lin à Josef Gregorian, à sa boutique de tailleur, dans le quartier de la Magie.', },
    {'Apporter 10 morceaux d\'Etoffe de lin et 6 Gemmes de mana de Dalaran à Josef Gregorian.', },
  },
  [1962] = {
    'Robe du feu-sorcier',
    nil,
    nil,
  },
  [1963] = {
    'La Main brisée',
    {'Le Chef de guerre utilise des méthodes trop subtiles. Par prudence, il veut éviter de déchaîner le pouvoir de la Horde. Pourtant, nous avons été plus forts, nous avons été de fiers conquérants ! Nous devons retrouver notre gloire passée et la Main brisée va la reconquérir.|n|nNous tirons notre force de l\'ombre et frappons nos ennemis en secret. Une tâche que vous devez accomplir pour prouver votre valeur.|n|nLe troll Tazan est en affaires avec les pirates près de Cabestan. Il détient des informations dont j\'ai besoin. Tuez-le et apportez-moi sa sacoche.', },
    {'Tuer Tazan et apporter sa Sacoche à Therzok, à la Faille de l\'Ombre à Orgrimmar.', },
  },
  [1978] = {
    'Les nécrotraqueurs',
    {'Le Syndicat ? Je ne m\'en serais jamais douté. Il semble que ces messieurs d\'Alterac soient tombés bien bas depuis leur trahison.|n|nLe seigneur Varimathras aura plaisir à apprendre ça et comme vous avez contribué à cette découverte, il convient que ce soit vous qui la lui annonciez.|n|nAh comment pouvais-je oublier !|n|nBienvenue chez les nécrotraqueurs…', },
    {'Livrer le Grand Livre d\'Andron à Varimathras au Hall de la Dame noire à Fossoyeuse.', },
  },
  [1998] = {
    nil,
    {'Le seigneur Varimathras vient juste de m\'envoyer une missive au sujet d\'une menace concernant les Réprouvés, menace qui doit être immédiatement supprimée. Son nom est Fenwick Thatros, et le seigneur Varimathras pense que c\'est l\'un des chefs morts-vivants qui ont pris pied dans la forêt des Pins-Argentés.|n|nJ\'ai immédiatement pensé à vous, $N. J\'ai assez confiance dans vos capacités pour penser que vous réussirez cette mission.|n|nLes derniers rapports des nécrotraqueurs dans la forêt indiquent que Thatros doit se trouver près du vieux port abandonné sur Lordamere.', },
    {'Tuer Fenwick Thatros et rapporter sa Tête à Mennet Carkad dans le Quartier des Voleurs de Fossoyeuse.', },
  },
  [1999] = {
    'Les outils du métier',
    {'Les magiciens du Kirin Tor à Moulin-de-l\'Ambre ont stocké d\'importants documents se rapportant à l\'état actuel de Dalaran. Nous tenons cela d\'un de nos prisonniers. Le seigneur Varimathras a ordonné de remettre ces documents aux nécrotraqueurs.|n|nCette tâche vous incombe, $N. Cependant, vous aurez besoin de certains équipements, et de la maîtrise de la technique du crochetage. Allez voir Estelle Gendry, notre spécialiste, et demandez-lui un jeu d\'outils avant de partir.', },
    {'Trouver le Rapport de situation de Dalaran et le remettre à Mennet Carkad dans le Quartier des Voleurs de Fossoyeuse.', },
  },
  [2000] = {
    'Rokar Ombrelame',
    {'Trop de temp mort pour vous, $N. C\'est le moment d\'en apprendre plus sur notre petit commerce. Hier soir, cinq des nôtres ont été trouvés morts avec quelques plombs dans la peau, dans l\'une des failles d\'Orgrimmar. Il y en a qui s\'opposent à nous, en utilisant nos propres méthodes contre nous.|n|nAlors j\'ai décidé de vous apprendre l\'art du Crochetage.|n|nMalheureusement, c\'est une compétence pour laquelle mes mains ne conviennent pas bien. Vous devrez chercher Rokar, qui vit dans les collines près de Durotar. Même s\'il est âgé, je gage qu\'il a toujours la même habileté.', },
    {'Aller voir Rokar Ombrelame en Durotar.', },
  },
  [2018] = {
    'L\'épreuve de Rokar',
    {'Ah ! Maintenant Therzok m\'envoie ses étudiants boutonneux ! Eh bien, je suppose que je peux vous apprendre une ou deux choses. Ce n\'est pas que je me soucie beaucoup de vos affaires, mais je ne voudrais pas avoir votre mort sur la conscience.|n|nMais vous devez d\'abord me prouver que vous êtes digne de mon enseignement.|n|nJe vais vous dire, $N. Je n\'aime pas beaucoup cette KapitalRisk. Cette région me rappelle Draenor et ça me dérange de voir les gobelins la dévaster. Peut-être qu\'ils cesseraient leur travail si le surveillant de leur Videfange disparaissait...', },
    {'Tuer le Surveillant Glibby et apporter son Sifflet à Rokar Ombrelame en Durotar.', },
  },
  [2019] = {
    'Les outils du métier',
    {'Vous voilà, $N. Ceci devrait bien vous servir. Fabrication personnelle, je vous jure que vous ne trouverez pas mieux.|n|nNe prenez pas la peine de m\'expliquer ce que vous voulez en faire, cependant. Je ne m\'intéresse pas aux arrangements de Therzok, je veux seulement vivre tranquillement ma retraite.|n|nSi jamais vous aviez besoin d\'un autre jeu d\'outils, revenez me voir et je vous en fournirai un. Mais prenez-en soin !', },
    {'Retourner voir Therzok à la Faille de l\'Ombre à Orgrimmar.', },
  },
  [2020] = {
    nil,
    {'Maintenant voilà la serrure fermée.', },
    nil,
  },
  [2038] = {
    'Les fournitures perdues de Bingles',
    {'Comme si le crash dans le Loch n\'avait pas suffi, des troggs de l\'île voisine m\'ont attaqué et ont volé mes outils et mes capsuleurs soufflants Explonheimer spéciaux ! Sans gyrocoptère et sans explosifs, le mouvement n\'a aucune chance ! |n|nRapportez-moi mes outils et mes capsuleurs soufflants, $N. Pour Gnomeregan !', },
    {'Trouver et rapporter à Bingles son matériel :|n|nLa Clé de Bingles, le Tournevis de Bingles, le Marteau de Bingles et le Capsuleur soufflant de Bingles.', },
  },
  [2039] = {
    'Trouvez Bingles',
    {'Nous avons perdu contact avec Bingles ! On l\'a envoyé en mission de reconnaissance sur Gnomeregan et ça fait une semaine qu\'il n\'a pas envoyé de rapport. Je sais juste qu\'il est parti et s\'est envolé.|n|nLa dernière fois qu\'on a vu son gyrocoptère, c\'était au-dessus du Loch. Peut-être que vous pourriez enquêter, $N.', },
    {'Trouver Bingles Explonheimer, au Loch Modan.', },
  },
  [2040] = {
    'Assaut souterrain',
    {'Gnomeregan est tombé sous le contrôle de ces troggs maudits ! La situation est grave, mais vous pouvez peut-être nous aider, $N. |n|nAu plus profond des mortemines, il y a un déchiqueteur gobelin en état de fonctionnement. Trouvez-le et rapportez sa source d\'énergie intacte. Elle permettra à nos excavateurs gyrodrilmatiques de percer les murailles de Gnomeregan pour l\'assaut !', },
    {'Récupérez l\'Indicateur Gnoam dans les mortemines et rapportez-le à Shoni la Silencieuse, à Hurlevent.', },
  },
  [2041] = {
    'Allez voir Shoni',
    {'Peut-être... Peut-être que vous pouvez nous aider dans la bataille de Gnomeregan.|n|nVous trouverez à Hurlevent le commandant de notre équipe d\'assaut souterraine, Shoni la Silencieuse. Shoni a besoin d\'aide pour ses excavateurs gyrodrilmatiques.|n|nVous la trouverez probablement parmi les nains de Hurlevent.|n|nBonne chance, $N.', },
    {'Aller voir Shoni la Shilencieuse au Quartier des Nains, à Hurlevent.', },
  },
  [2058] = {
    nil,
    {'Vous allez tuer un type, un membre de la Ligue des assassins. Il a tué le vieux chef des nécrotraqueurs.', },
    nil,
  },
  [2059] = {
    nil,
    {'Bien supposé, vous nous intéressez.', },
    nil,
  },
  [2078] = {
    'La vengeance de Gyromast',
    {'Bouseux de terrien ! Tu dois me dégoter mon second.|n|nPrends c\'te clé, mets-y dans le bon trou, et ramèn\' le ici pour servir le cap\'taine.|n|nCes murlocs et leur chef vont pas beaucoup aimer quand mon second va leur mettre l\'grappin dessus !', },
    {'Trouvez le Second de Gelkak, le Destructomembreur 4100, et ramenez-le à Gelkak.', },
  },
  [2098] = {
    'La recherche de Gyromast',
    {'La vie d\'un pirate n\'est pas facile, bouseux de terrien. C\'est pas pillage et tafia à volonté ! Hélas ! Mon navire est à la baille, tout près du bord, à cause de ces saletés de battrodons.|n|nJ\'ai b\'soin que mon second rapplique en ordre de marche !|n|nQuand j\'me suis ramassé sur le rivage, la clé de contact de mon second est tombée sur les rochers et a été chapardée par des bestioles du cru. Du coin de l\'œil, j\'ai vu des clampants déchaînés, des trotteurs des forêts géants et des murlocs fouiller l\'épave...', },
    {'Trouver et rapporter les 3 Morceaux de la clé de Gelkak à Gelkak Gyromast.', },
  },
  [2118] = {
    'Terres malades',
    {'Il y a une maladie qui s\'étend à travers tout Sombrivage, contaminant les esprits et les organismes qu\'elle touche.|n|nCe sont les ours des chardons qui ont été les plus touchés. Ces animaux, autrefois si nobles, sont devenus des instruments de destruction, enragés et frénétiques. J\'ai peut-être trouvé un remède contre ce mal.|n|nApportez ce piège dans la forêt et placez-le au sol. N\'importe quel ours des chardons enragé qui traversera cette lumière deviendra docile pour un court moment. Une fois que l\'ours sera docile, il vous suivra. Ramenez-le ici, $N.', },
    {'Capturer vivant un Ours des chardons enragé, puis le ramener à Tharnariun.', },
  },
  [2138] = {
    'Nettoyage de l\'infection',
    {'Comme je le craignais, le remède ne marche pas.|n|nCela m\'attriste énormément de devoir ordonner la mort de certaines créatures de la nature, mais les ours des chardons malades et infectés doivent être éliminés.|n|nRetournez dans la forêt et détruisez 20 ours des chardons enragés, $N. Cela ne suffira sans doute pas à éradiquer la contamination, mais ça permettra de limiter pendant quelque temps les dégâts que ces animaux causent à notre forêt et à ses habitants.', },
    {'Débarrasser la forêt de 20 Ours des chardons enragés et retourner voir Tharnariun Soigneflore, à Sombrivage.', },
  },
  [2139] = {
    'Espoir de Tharnariun',
    {'La survie de notre peuple et de nos terres a exigé des sacrifices, $N.|n|nHélas, vous avez dû verser le sang des serviteurs de la nature et bien des animaux sont tombés sous vos coups. Le peuple d\'Auberdine vous doit beaucoup, et la souffrance de la forêt est apaisée, au moins pour le moment.|n|nJ\'ai une dernière tâche à vous confier mais sachez qu\'il vous faudra tuer de nouveau. J\'espère de tout cœur que ce sera la dernière fois, $N.|n|nÀ côté de Bashal\'Aran, dans une caverne au nord-est d\'ici, habite la Mère de la tanière. Faites-la disparaître.', },
    {'Trouver et tuer la Mère de la tanière.', },
  },
  [2158] = {
    'Repos et détente',
    {'Tous les aventuriers doivent prendre du repos s\'ils veulent éviter l\'épuisement... Et pour cela, le meilleur endroit, c\'est bien l\'Auberge de la Fierté du lion ! |n|nMon meilleur ami, l\'aubergiste Farley, tient cette auberge. Si vous venez de ma part, il vous fera sûrement des réductions sur le prix de la nourriture et de la boisson ! |n|nSuivez cette route vers le sud, vous ne pouvez pas la rater !', },
    {'Parler à l\'aubergiste Farley, à l\'auberge de la Fierté du lion.', },
  },
  [2159] = {
    'Livraison de Dolanaar',
    {'Salutations, jeune $C. Pouvez-vous m\'aider ? Je dois livrer ce paquet d\'herbes dans la ville de Dolanaar, mais ne puis partir d\'ici car j\'ai une tâche à terminer avec les druides de Sombrevallon.|n|nPouvez-vous livrer ce paquet pour moi ? Il doit être remis à l\'aubergiste Keldamyr, à l\'auberge de Dolanaar. Elle se trouve sur cette route, au sud.', },
    {'Apportez la Livraison pour Dolanaar à l\'Aubergiste Keldamyr.', },
  },
  [2160] = {
    'Des provisions pour Tannok',
    {'Hé ! Vous avez l\'air d\'être un cœur généreux. Si vous projetez de prendre le Passage, pourriez-vous apporter un paquet à l\'auberge de Kharanos ?|n|nVous vouliez vous arrêter à l\'auberge, non ? Si vous prenez le Passage, vous aurez certainement envie de vous y reposer.|n|nQuoi qu\'il en soit, apportez ceci à Tannok Martel-de-givre, l\'assistant de l\'aubergiste. Je ne peux pas passer le Passage moi-même et il faudra des jours avant qu\'une escorte de Montagnards ne passe par ici !', },
    {'Livrer la Caisse de ravitaillement à l\'auberge de Tannok Martel-de-givre à Kharanos.', },
  },
  [2161] = {
    'Un fardeau de péon',
    {'Excusez-moi... Pouvez-vous m\'aider ?|n|nVous voyez ce chargement ? J\'ai suivi la route, j\'ai bravé les scorpides, les araignées, que sais-je encore, tout ça pour apporter ces vivres dans la vallée des Épreuves. Je pensais qu\'ils en auraient besoin... Mais non, ils n\'en ont pas voulu ! Maintenant, il ne me reste plus qu\'à rapporter tout ça à Tranchecolline et ça me terrorise, à cause des bêtes...|n|nVous pourriez vous en charger pour moi ? Je ne suis qu\'un malheureux péon mais vous... Vous n\'avez peur de rien, vous avez l\'habitude d\'être héroïque ! |n|nRapportez ce paquet à l\'aubergiste Grosk à l\'auberge de Tranchecolline. Merci !', },
    {'Apportez le Fardeau d\'Ukor à l\'aubergiste Grosk à Tranchecolline.', },
  },
  [2178] = {
    'Brouet de trotteur',
    {'Sentez-vous cet arôme délicieux ? C\'est ma recette secrète, $N : le brouet de trotteur frais. Délicieux !|n|nLa recette vous intéresse peut-être ?|n|nAvant de vous l\'apprendre, je veux voir comment vous vous débrouillez avec les bêtes.|n|nJe ne m\'attends pas à ce que vous sortiez en dompter un, mais si vous pouvez en abattre quelques-uns et rapporter leur succulente viande, ça suffira à me convaincre que je peux vous montrer comment cuisiner mon brouet de trotteur.', },
    {'Apporter 5 morceaux de Viande de trotteur à Alanndarian Chantenuit, à Auberdine.', },
  },
  [2198] = {
    'Le collier brisé',
    {'Vous avez trouvé un Collier terni mais sur lequel on devine encore des entrelacs compliqués et des signes magiques. Il a été brisé et on voit qu\'il manque trois gemmes. Sous le collier, on peut reconnaître le sceau de la ville de Forgefer et, sous le sceau, trois toutes petites lettres : "TdK".|n|nS\'il y a quelque chose à tirer de ce Collier, il va falloir revenir à ses origines. Le sceau et les initiales sont déjà un début...', },
    {'Chercher celui qui a fabriqué le Collier brisé pour découvrir sa valeur potentielle.', },
  },
  [2199] = {
    'Le Prix de la Connaissance',
    {'Je suis un joaillier de renom, ici, à Forgefer. Enfin, je l\'étais... Je suis la victime d\'un concurrent déloyal ! Dans ce métier, c\'est la réputation qui fait tout... Et résultat, je me retrouve sans un sou, uniquement propriétaire d\'un nom traîné dans la boue ! |n|nJe veux que vous me rapportiez cinq barres d\'argent pour terminer une commande qui m\'a été faite - la première commande depuis des lustres ! |n|nVous me rapportez ces barres d\'argent et je répondrai à vos questions au sujet du collier.', },
    {'Apporter 5 Barres d\'Argent à Talvash del Kissel, à Forgefer.', },
  },
  [2200] = {
    'Retour à Uldaman',
    {'Un de mes concurrents a fait courir la rumeur que le collier avait maudit le paladin. Inutile de dire que personne ne vient acheter des bijoux maudits à un joaillier !|n|n$N, je vous propose un marché : trouvez les gemmes et je réparerai le collier, à condition que vous affirmiez partout que je ne fabrique PAS de bijoux maudits !|n|nCherchez des indices à Uldaman ; voyez si le corps du paladin est là-bas ; après tout c\'est lui qui en était le dernier propriétaire ! Quand vous aurez les gemmes, utilisez ceci pour me contacter, ici à Forgefer.', },
    {'Chercher des indices sur le Collier de Talvash à Uldaman. Le paladin dont il a parlé est la dernière personne à l\'avoir porté.', },
  },
  [2201] = {
    'Trouver les gemmes',
    {'Le journal du paladin est sans doute le seul indice dans Uldaman qui puisse vous conduire aux gemmes. Si ce qu\'il prétend est vrai, il va falloir traiter avec les nains ombreforge et les troggs qui s\'affrontent pour le contrôle du site de fouilles.|n|nLa traque des gemmes doit commencer immédiatement. Lorsqu\'elles seront récupérées, il faudra prendre les instructions de Talvash à Forgefer en utilisant la flasque de divination.', },
    {'Trouvez le rubis, le saphir et la topaze qui sont éparpillés à travers Uldaman. Une fois que vous les aurez, contactez Talvash del Kissel en utilisant la Flasque de divination qu\'il vous a donnée précédemment.|n|nC\'est dans le journal, vous savez...|n* Le rubis a été caché dans une zone barricadée des Ombreforge.|n* La topaze a été dissimulée dans une urne, dans l\'une des zones trogg, pas très loin de nains de l\'Alliance.|n* Le saphir est en la possession du chef trogg, Grimelok.', },
  },
  [2202] = {
    'Rechercher les composants à Uldaman',
    {'On a découvert récemment une nouvelle plante : les champignons magenta. Ils poussent en grappes au site de fouilles d\'Uldaman ; on les trouve dans les premiers tunnels et loin dans des zones moins explorées. Je veux étudier leur utilité éventuelle en alchimie, et c\'est là que vous entrez en scène.|n|nTrouvez les champignons magenta et rapportez-m\'en une douzaine. Attention, les grappes peuvent projeter des spores vénéneuses quand on les manipule !|n|nRendez-moi ce service et je sortirai pour vous un petit élixir revigorant de derrière les fagots.', },
    {'Apporter 12 Champignons magenta à Jarkal Fondemousse à Kargath.', },
  },
  [2203] = {
    'Les réactifs des Terres ingrates II',
    {'Votre aide m\'a été précieuse, merci, $C. Je vous récompenserai en vous donnant la recette du breuvage que vous avez testé un peu plus tôt... mais je vais d\'abord vous confier une mission dangereuse. Écoutez bien. |n|nCe coffret contient trois récipients thaumaturgiques vides. Ils sont entourés d\'une aura d\'harmonie qui attire le sang de dragon gardien des terres brûlées. Attention ! Si vous n\'en utilisez qu\'un, la bête deviendra enragée. Lorsque vous aurez rempli les trois, rapportez-les-moi. |n|nVous aurez la recette de mon élixir en échange.', },
    {'Utiliser les 3 Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Jarkal Fondemousse à Kargath.', },
  },
  [2204] = {
    'Réparer le collier',
    {'Vous allez avoir besoin de "pep\'s" pour le collier, et l\'endroit idéal pour en trouver, c\'est Uldaman... Je suppose qu\'il y a des tas de constructions qui se baladent par là-bas, non ? Il suffit de choisir la plus vile et la plus grande et de lui piquer sa source d\'énergie. Je suis presque sûr de pouvoir m\'en servir pour le collier !|n|nSans source d\'énergie, de toute façon, la réparation est impossible. Revenez me voir à Forgefer quand vous l\'aurez, et on verra ce qu\'on peut faire !', },
    {'Obtenir une Source d\'énergie de la construction la plus puissante que vous pouvez trouver à Uldaman, puis la remettre à Talvash del Kissel à Forgefer.', },
  },
  [2205] = {
    'Chercher le SI:7',
    {'L\'insigne ? Rien... Rien qui soit pour vous... Si j\'en juge par votre apparence, j\'ai peur que Mathias vous prenne pour le livreur de fromage, mon enfant, au lieu du malandrin attendu. Enfin, on m\'a donné un travail et j\'ai promis de livrer ce travail. |n|nTiens, à propos, vous apporterez ce paquet à Mathias, et peut-être qu\'il vous donnera un ou deux petits boulots à accomplir. |n|nAllez, du vent.', },
    {'Remettre le colis de Keryn Sylvius à maître Mathias Shaw à la Caserne de Hurlevent.', },
  },
  [2206] = {
    'Effraction',
    {'Nos espions sur le terrain rapportent que les bandits sont très actifs dans le sud de Comté-de-l\'Or. Il semble qu\'ils aient pris le débarcadère de Jerod et qu\'ils l\'utilisent pour passer en contrebande de grandes quantités de produits entre les Carmines et la marche de l\'Ouest.|n|nIl faut que vous vous introduisiez dans la petite maison à côté du quai et que vous me rapportiez le programme d\'embarquement des navires, $N. Vous le trouverez probablement au profond des poches de l\'intendant des docks.|n|n... Et $N, si vous étiez $Gdécouvert:découverte;, sachez que le SI:7 nierait vous avoir jamais $Gconnu:connue;.', },
    {'Trouver l\'Intendant des docks et récupérer le Programme d\'embarquement, pour le compte de maître Mathias Shaw.', },
  },
  [2218] = {
    'La voie du salut',
    {'Une autre âme perdue en quête de conseil, hein ? Je suppose que vous cherchez une voie, votre voie. J\'ai déjà vu ça mille fois, encore $Gun héros désœuvré:une héroïne désœuvrée; qui cherche du travail.|n|nEh bien, c\'est aujourd\'hui votre jour de chance, mon $Gami:amie;. Hogral connaît la solution à votre tourment.|n|nVoici ce qu\'il vous faut faire : prenez cette route jusqu\'à Forgefer et cherchez-y la caverne Lugubre. Une fois sur place, localisez la guilde des voleurs et demandez entretien à Hulfdan Barbe-noire. Il vous guidera vers votre salut.', },
    {'Parler à Hulfdan Barbe-noire à Forgefer.', },
  },
  [2238] = {
    'Simple subterfuge',
    {'Vous voyez, le roi a épuisé les carrières en extrayant le minerai de fer et les gemmes. Cela fait plus de richesses que n\'en devrait voir un nain en vivant dix vies.|n|nLe Cercle secret a des valeurs, $N. Nous accordons de la valeur à ce qui a de la valeur. Vous comprenez ?|n|nNous pensons que le roi doit partager ce butin, mais nous ne voulons pas que « Barbe-puante » sache qu\'il est en train de partager, pigé ?|n|nAdressez-vous à Onin MacHammar à Gnomeregan et tenez-moi au courant. Il est habile, il se cache parmi les lépreux. Faites attention.', },
    {'Trouver Onin MacHammar à Gnomeregan.', },
  },
  [2239] = {
    'Rapport d\'Onin',
    {'La carrière ? Ouaip, je vois ces monstrueux chars à vapeur qui passent près de là, presque tous les jours.|n|nMes contacts, à l\'est, me disent que le char quitte Forgefer, charge sa cargaison à la carrière de Gol\'Bolar, se ravitaille à Kharanos et après, pour une raison bizarre, emprunte le long chemin qui contourne Gnomeregan avant d\'atteindre Forgefer où il décharge.|n|nTout est dans le rapport, $R. Portez-le à Hulfdan, qu\'il puisse réfléchir à la suite du plan.', },
    {'Porter le rapport d\'Onin à Hulfdan à Forgefer.', },
  },
  [2240] = {
    'La chambre secrète',
    {'Bon... Pour la tâche en cours...|n|nIl va falloir explorer une chambre secrète, la Chambre de Khaz\'mul. Le problème, c\'est qu\'elle se trouve derrière une lourde porte fermée ! Il est heureux que je sache comment l\'ouvrir ! |n|nJ\'ai tout écrit dans ce journal, là, sur la table. Pour l\'instant nous sommes coincés ici. Trouvez la Chambre de Khaz\'mul pour nous, $N !|n|nLisez mon journal, explorez la Chambre, puis rendez compte au Prospecteur Foudrepique de la Ligue des Explorateurs à Forgefer.', },
    {'Lire le journal de Baelog, explorer la Chambre secrète, puis rendre compte au Prospecteur Foudrepique.', },
  },
  [2241] = {
    'Pomme d\'amour',
    {'Ils disent que je suis fleur bleue... quoi que cela puisse vouloir dire.|n|nC\'est vrai qu\'à tout instant je pense à Syurna. C\'est vrai, ma maison est tapissée de peintures et de dessins de Syurna. C\'est vrai, je peux passer des jours sans manger, boire ou dormir en me languissant de l\'amour que nous aurions pu connaître. Mais est-ce mal ?|n|nEt maintenant elle refuse de me voir ! MOI ! J\'ai essayé de lui envoyer des messages, mais elle ne veut parler à personne à moins que ce ne soit un voleur.|n|nPourriez-vous lui porter cette fleur ? Et n\'oubliez pas de dire que c\'est de la part de Jannok.', },
    {'Porter la Rose de Jannok à Syurna à Darnassus.', },
  },
  [2242] = {
    'L\'appel du destin',
    {'Nous pensons qu\'il existe un être qui pourrait nous aider à comprendre ce qui arrive aux forêts de Teldrassil. Malheureusement, toutes les tentatives pour amener la créature à coopérer se sont soldées par un désastre.|n|nIl se cache sur une branche, sur le rebord de la clairière de l\'Oracle. À ce jour, tous ceux qui ont approché le satyre, par la force ou la diplomatie, ont été anéantis. Le camouflage est peut-être la solution, $N.|n|nTrouvez ce que Sethir l\'Ancien cache dans ses poches et faites-moi un rapport.', },
    {'Trouver Sethir l\'Ancien et rapporter tout indice découvert à Syurna.', },
  },
  [2258] = {
    'Les réactifs des Terres ingrates',
    {'$N, je pourrais avoir l\'usage de vos capacités. Je suis un alchimiste de quelque renom et j\'ai besoin de votre aide pour acquérir des composants que l\'on ne peut trouver que dans les Terres ingrates. |n|nJ\'ai besoin des objets suivants pour réapprovisionner mon stock : cinq gésiers de busards, dix crocs de coyote des rochers et cinq fragments d\'élémentaire de roche. À prendre sur les bêtes elles-mêmes, bien entendu... Si vous n\'êtes pas du genre batailleur, trouvez quelqu\'un qui le soit ! |n|nTrouvez-moi ces objets, et vous aurez quelques pièces en échange, ça vous va ?', },
    {'Apporter 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d\'élémentaire de roche à Jarkal Fondemousse, à Kargath, dans les Terres ingrates.', },
  },
  [2259] = {
    'Erion Murmombre',
    {'Ne vous inquiétez pas, $N, je ne vous envoie pas voir Syurna. Erion veut que vous le rejoigniez dans l\'Enclave de Cenarion. Faites vite !', },
    {'Contacter Erion Murmombre à Darnassus.', },
  },
  [2260] = {
    'L\'ordre d\'Erion',
    {'Le Service de Renseignement de Hurlevent a entendu parler de vos exploits, $N, et il veut vous recruter. |n|nLe voyage est coûteux et périlleux, mais on ne rejette pas l\'opportunité de s\'entraîner pour le SI:7 !|n|nUn nouveau monde s\'ouvre à vous, $N. Rendez-vous dans la Vieille ville de Hurlevent et adressez-vous à Renzik "le Kriss" " au QG du SI:7.', },
    {'Voyager vers Hurlevent pour y demander conseil à Renzik « le Kriss ».', },
  },
  [2278] = {
    'Les disques de platine',
    {'Les pièces centrales de cette chambre au trésor sont quatre larges disques de platine ornés de cachets d\'origine inconnue. Lorsque vous les touchez, vous sentez un frémissement. Le visage d\'un grand gardien des pierres apparaît alors.|n|n« Salut à vous. Je suis le gardien du savoir. La synthèse des terrestres par les Faiseurs a été gravée et conservée dans les disques de Norgannon. »|n|nVous avez découvert un immense savoir, inconnu du monde entier !', },
    {'Parlez au Gardien des pierres pour connaître le Savoir qu\'il défend. Une fois découvert ce qu\'ils peuvent offrir, activez les Disques de Norgannon.', },
  },
  [2279] = {
    'Les disques de platine',
    {'Votre main vibre de nouveau au contact des disques de Norgannon. Cette fois, pourtant, c\'est un étrange grincement qui se fait entendre. |n|nSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des disques ! |n|nVoilà qui sera utile à tous ceux qui s\'intéressent à l\'histoire ancienne d\'Azeroth. La Ligue des explorateurs de Forgefer est connue dans toute l\'Alliance pour ses recherches sur le sujet ; ils devraient pouvoir faire bon usage de tout ceci.', },
    {'Apporter la version miniature des Disques de Norgannon à la Ligue des Explorateurs à Forgefer.', },
  },
  [2280] = {
    'Les disques de platine',
    {'Votre main vibre de nouveau au contact des disques de Norgannon. Cette fois, pourtant, c\'est un étrange grincement qui émane des disques. |n|nSoudain, votre sac paraît plus lourd. Vous y trouvez une version miniature des disques ! |n|nIl ne fait aucun doute qu\'un objet de ce genre serait d\'une valeur inestimable pour quiconque s\'intéresse à l\'histoire ancienne d\'Azeroth. Il y a certainement quelqu\'un qui voudrait l\'avoir !', },
    {'Apporter la version miniature des Disques de Norgannon à une personne qui serait très intéressée par cet objet.', },
  },
  [2281] = {
    'Le Rendez-vous des Carmines',
    {'Vous jeter maintenant sur le champ de bataille serait pur suicide. Renzik ne veut pas d\'un autre cadavre de voleur dans son équipe. Mais pas d\'inquiétude, $N : Renzik vous mettra à niveau.|n|nDirigez-vous vers les Carmines et discutez avec Lucius, un associé du SI:7. Vous le trouverez facilement, il traîne généralement autour des docks de Comté-du-Lac avec d\'autres bons à rien.', },
    {'S\'aventurer vers Comté-du-Lac dans les Carmines et parler à Lucius.', },
  },
  [2282] = {
    'La scierie d\'Alther',
    {'J\'entraîne des voleurs depuis des années ! Après tout, c\'est pas n\'importe quel vaurien qu\'est né avec la grâce et la finesse du vieux Lucius.|n|nUn peu plus loin, z\'allez trouver la scierie d\'Alther. J\'y ai un coffre fermé qui contient que\'q\' chose d\'important. Allez le récupérer pour moi. Rapportez-moi ce qui s\'y trouve, et vous recevrez vot\' certificat de voleur !', },
    {'Ouvrez le Coffret de Lucius, récupérez le Gage de voleur et rapportez-le à Lucius, à Comté-du-Lac.', },
  },
  [2283] = {
    'Réparer le Collier',
    {'Nous avons du travail pour vous, si vous avez du cran...|n|nAu plus profond de l\'excavation d\'Uldaman, dans les Terres ingrates, il paraît qu\'il y a les restes d\'un crétin de paladin qui est mort par là il y a pas longtemps. Ça nous intéresse pas, sauf qu\'il avait un collier de prix avec lui. On dit qu\'il y avait trois Gemmes dessus : un Rubis, un Saphir et une Topaze.|n|nBon alors voilà : on le paiera très cher. Il est peut-être abîmé mais on s\'en moque. On le réparera.', },
    {'Rechercher dans l\'excavation d\'Uldaman un Collier de prix et le rapporter à Dran Droffers à Orgrimmar. Ce Collier peut être endommagé.', },
  },
  [2284] = {
    'Réparer le Collier, deuxième prise',
    {'Aussi vrai que Malton est un crétin, ces gemmes sont encore que\'que part dans Uldaman. Va falloir y r\'tourner. |n|nComme j\'l\'ai d\'jà dit, si les informations que nous avons sont justes, il y a un rubis, un saphir et une topaze. |n|nOù elles sont, comment je l\'saurais ? Si vous avez du bol et qu\'vous trouvez l\'corps du paladin, et qu\'il a pas encore été nettoyé, elles s\'ront p\'têt encore là.', },
    {'Trouver, dans les profondeurs d\'Uldaman, des indices sur la localisation des Gemmes.', },
  },
  [2298] = {
    'Extorsion royale',
    {'Alors on était là, en train de comploter pour la phase III quand soudain, deux crétins de Magni se pointent en parlant de je ne sais quel coup, et d\'arrêter ceux du Cercle secret.|n|nPersonne ne porte la main sur le vieux Barbe-Noire ! La discussion s\'envenime, blabla, paf, et soudain on prononce vot\' nom !|n|nV\'voulez un conseil ? Prenez le premier griffon pour Hurlevent. Une fois là-bas, allez voir Renzik «le Kriss » dans la Vieille ville. C\'est un vieil ami à moi.', },
    {'Allez à Hurlevent et cherchez Renzik « le Kriss ».', },
  },
  [2299] = {
    'Cap sur Hulfdan !',
    {'Où donc étiez-vous, $N ? Hulfdan vous cherche partout. On craignait que le roi ne vous ait fait mettre aux fers.|n|nAllez à Forgefer dès que possible et parlez à Hulfdan !', },
    {'Se rendre à Forgefer et parler à Hulfdan Barbe-noire.', },
  },
  [2300] = {
    nil,
    {'Renzik vous cherchait, l\'$Gami:amie;.|n|nJe ne ferais pas attendre le bras droit de Mathias à votre place.', },
    {'Allez à Hurlevent et cherchez Renzik « le Kriss ».', },
  },
  [2318] = {
    'La traduction du Journal',
    {'Vous êtes dans l\'impasse si vous n\'arrivez pas à faire traduire le journal dans une langue que vous comprenez. Il doit bien y avoir des gens qui en sont capables, non ? L\'endroit le plus proche où vous pourriez trouver un traducteur, c\'est l\'avant-poste de Kargath dans les terres Ingrates. C\'est le mieux pour commencer !', },
    {'Trouver quelqu\'un qui puisse traduire le journal du paladin. L\'endroit le plus proche est Kargath, dans les Terres ingrates.', },
  },
  [2338] = {
    'La traduction du Journal',
    {'Chez Droffers et fils, ils sont trop bêtes pour restaurer la magie du collier. Moi, je peux le faire. Je veux l\'étudier pour apprendre à le confectionner moi-même. Pour ce faire, j\'aurai besoin de votre collier. Laissez-le-moi et en échange je vous traduirai le journal. Le temps que vous trouviez les gemmes, j\'aurai le loisir d\'apprendre ce qui m\'intéresse.|n|nUn marché simple et sans duperie... Alors, qu\'en pensez-vous ?', },
    {'Laisser Jarkal emprunter le Collier en échange de la traduction du Journal.', },
  },
  [2339] = {
    'Trouver les gemmes et la source d\'énergie',
    {'Voici la traduction du journal, pour que vous puissiez le lire de votre côté. En gros, il dit que ce sont les nains qui ont caché le rubis, les troggs la topaze et que c\'est un trogg nommé Grimelok qui a le saphir.|n|nBon. Ensuite, vous aurez besoin d\'une source d\'énergie pour que le collier fonctionne de nouveau. Et ça, Dran Droffers ne le sait pas. Pour en trouver une, moi, j\'irais au plus profond d\'Uldaman et je détruirais les machines les plus puissantes. Elles disposent sûrement d\'une source d\'énergie !|n|nQuand vous aurez tout ça, revenez me voir.', },
    {'Récupérer, dans Uldaman, les trois gemmes et une source d\'énergie pour le collier, puis les rapporter à Jarkal Fondemousse, à Kargath. Jarkal pense que vous pouvez trouver une source d\'énergie sur la machine la plus puissante d\'Uldaman.|n|nC\'est dans le journal, vous savez...|n* Le rubis a été caché dans une zone barricadée des Ombreforge.|n* La topaze a été dissimulée dans une urne, dans l\'une des zones trogg, pas très loin de nains de l\'Alliance.|n* Le saphir est en possession du chef trogg, Grimelok.', },
  },
  [2340] = {
    'Livrer les Gemmes',
    {'Un collier et des gemmes ordinaires marcheront aussi bien, du moment qu\'ils sont faits du même matériau. Cette source d\'énergie, en revanche, c\'est elle qui va donner sa magie au Collier... Enfin j\'espère ! |n|nJe fournirai volontiers les gemmes nécessaires pour la confection de votre version du collier, si toutefois cette source d\'énergie fonctionne. |n|nRetournez à Orgrimmar, et terminez votre marché avec Droffers et Fils. Ne leur dites rien de notre rencontre et lorsque vous reviendrez, je pourrais bien avoir un cadeau pour vous.', },
    {'Apporter les Gemmes et le Collier récupérés à Dran Droffers, à Orgrimmar.', },
  },
  [2341] = {
    'Réparer le collier, troisième prise',
    {'Pendant que Dran et Malton Droffers se disputent la prise, la moitié de l\'affaire est maintenant close. Il vous reste à retourner dans les Terres ingrates pour finir tout ça. Jarkal Fondemousse, à Kargath, pourrait avoir une récompense spéciale à vous donner.', },
    {'Rendre visite à Jarkal Fondemousse à Kargath pour constater (ou non) son succès.', },
  },
  [2342] = {
    'Des Trésors à recouvrer',
    {'Balayer les enclos à chauves-souris avec ce balai, ce n\'est pas digne d\'un Garrett ! J\'ai fait quelques économies avec ce boulot maudit, et je suis prêt à les dépenser pour améliorer mes conditions de travail.|n|nL\'arme familiale des Garrett est restée enfermée dans notre Coffre, dans le Hall commun sud d\'Uldaman, où nous avons trimé comme mineurs. Sans elle, je suis coincé ici pour toujours, à balayer derrière ces immondes chauves-souris !|n|nRapportez-moi ce trésor de famille ! Aidez-moi à retrouver ma dignité !', },
    {'Rapporter à Patrick Garrett, à Fossoyeuse, son Trésor de famille, qui se trouve dans le Coffre de famille dans le Hall commun sud d\'Uldaman.', },
  },
  [2358] = {
    'Cornes de Nez\'ra',
    {'Il y a bien des lustres, les Cornes de Nez\'ra ont été volées au manoir de Ravenholdt. Je les ai cherchées par le monde entier, sur terre comme sur mer. Et tout ce temps, c\'étaient ces bêtes immondes qui les avaient !|n|nExterminez tous les orcs rochenoires que vous croiserez jusqu\'à ce que vous retrouviez les Cornes de Nez\'ra.|n|nFaites ceci pour moi, $N, et votre renommée atteindra Ravenholdt.', },
    {'Rapporter les Cornes de Nez\'ra à Arantir, à Comté-du-Lac.', },
  },
  [2359] = {
    'La tour de Klaven',
    {'Je suis là, à surveiller cette tour depuis des semaines, $N. Récemment, un chargement important est arrivé du bois de la Pénombre, protégé par ces gardes.|n|nQue sont-ils ? Aucune idée. La seule chose que je puisse affirmer, c\'est qu\'ils ne sont pas humains.|n|nQuoi qu\'il en soit, dans cette cargaison repose un coffre, et je suppose que ces abominations sont commises à sa garde. Le gros avec les piques, là, possède une clé dont nous aurons besoin.|n|nRécupérez cette clé, entrez dans la tour et découvrez ce que contient ce coffre. Rapportez à Mathias le produit de votre recherche.', },
    {'Volez la Clé de la Tour défias, pénétrez dans la Tour et trouvez ce que contient le Coffre du bois de la Pénombre. Rapportez les informations à Mathias Shaw à Hurlevent. Lisez le journal de Kearnen pour savoir ce qui se passe dans la tour.', },
  },
  [2360] = {
    'Mathias et les Défias',
    {'Pas trop tôt, $N. Les éléments de reconnaissance du SI:7 nous apprennent que les Défias sont inhabituellement actifs dans la marche de l\'Ouest.|n|nOn dirait qu\'ils ont pris une ancienne tour de guet de l\'Alliance abandonnée au sud-est de la colline des Sentinelles, et qu\'ils s\'en servent comme base d\'opérations pour leurs trafics à partir de la route d\'approvisionnement des Carmines.|n|nAllez dans la marche et contactez l\'agent Kearnen. Elle est cachée à proximité de la tour.|n|n... Oh, $N, si vous veniez à être $Gcapturé:capturée;, le SI:7 nierait avoir eu connaissance, etc.', },
    {'Se rendre dans la marche de l\'Ouest et trouver l\'Agent Kearnen pour un débriefing.', },
  },
  [2361] = {
    'Réparer le collier',
    nil,
    nil,
  },
  [2378] = {
    'Trouver la Main brisée',
    {'Vous avez bien servi les nécrotraqueurs, $N, mais il est temps d\'étendre votre expérience. Vous avez montré vos capacités en matière de ruse et de traîtrise, mais votre entraînement n\'est pas terminé. |n|nLes nécrotraqueurs ont des alliés au sein de la Main brisée. Cherchez ceux qui viennent à notre aide : trouvez Shenthul à Orgrimmar.', },
    {'Voyager vers Orgrimmar pour y parler à Shenthul, dans la Faille de l\'Ombre.', },
  },
  [2379] = {
    nil,
    {'Votre seule détermination ne suffira pas pour affronter les obstacles qui nous attendent.|n|nAdressez-vous à Zando\'zan pour commencer votre entraînement comme opérationnel de la Main brisée.|n|nLorsque vous maîtriserez le noble art du vol et de la tricherie vous pourrez faire un pas de plus vers votre destinée.', },
    {'Parler à Zando\'zan à la Faille de l\'Ombre.', },
  },
  [2380] = {
    'Cap sur Orgrimmar !',
    {'Spécialiste de la forfaiture et de la tricherie, vous ne l\'êtes pas, mais ça peut changer. Il semble que vous ayez impressionné les chefs avec vos maigres talents, puisque le grand Shenthul lui-même vous réclame.|n|nPrenez la route vers le nord jusqu\'à Orgrimmar et adressez-vous à Shenthul à la Faille de l\'Ombre.', },
    {'S\'adresser à Shenthul à la Faille de l\'Ombre à Orgrimmar.', },
  },
  [2381] = {
    'Piller les pilleurs',
    {'Sans vouloir vous effrayer, $N, les cinq derniers qui ont essayé de voler le trésor des mers du Sud ont été mis en pièces.|n|nLe long de la côte, au sud, vous trouverez le « Tranche-les-vagues », le navire des Flibustiers des mers du Sud. Le trésor se trouve dans la cale. Au deuxième niveau se trouve la salle des pirates, une salle d\'entraînement pour leurs voleurs.|n|nMontez à bord, volez le trésor, et rapportez-le-moi. Utilisez la salle des pirates si vous voulez vous entraîner, mais soyez $Gprudent:prudente; !', },
    {'Apportez le Trésor des mers du Sud à Wrenix le Misérable à Cabestan. Ne pas oublier d\'obtenir un B.G.A.C. et des Outils de voleur de l\'Appareil bidulotronique de Wreni. Ces deux éléments sont nécessaires pour accomplir la mission.|n|nEn cas d\'attaque par des perroquets particulièrement hostiles, utiliser le B.G.A.C. !', },
  },
  [2382] = {
    'Wrenix de Cabestan',
    {'Zando\'zan l\'a vu ! Oui, le jour vient ! La mort de l\'esclave... Le poignard dans le dos, le poison suintant de chaque veine... Zando\'zan en a trop dit.|n|n$N ! Zando\'zan a une tâche pour $N ! $N doit aller à Cabestan, à l\'est de la Croisée, pour rencontrer Wrenix le Misérable. Allez !', },
    {'Aller jusqu\'à Cabestan dans les Tarides pour parler à Wrenix le Misérable.', },
  },
  [2383] = {
    'Parchemin simple',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l\'extérieur de l\'Antre, dissimulé dans l\'ombre.', },
    {'Lire le Parchemin simple, et parler à Frang, dans la Vallée des Épreuves.', },
  },
  [2398] = {
    'Les nains perdus',
    {'Le site de fouilles d\'Uldaman n\'a pas toujours été mal fréquenté. Nous, les nains de Forgefer, contrôlions le secteur... jusqu\'à la venue des troggs. Ils sont arrivés si vite et si nombreux que même des nains n\'ont pas pu les arrêter !|n|nLeur attaque a été si soudaine que je crains que certains des nôtres soient pris au piège derrière les lignes ennemies.|n|nMon ami Baelog a conduit une petite troupe assez loin dans le site avant d\'être repéré. S\'ils sont vivants, je veux que vous les trouviez.', },
    {'Trouver Baelog dans Uldaman.', },
  },
  [2399] = {
    'Les racines ont poussé',
    nil,
    nil,
  },
  [2418] = {
    'Les pierres de puissance',
    {'Il y a quelque temps, j\'ai eu un problème avec les nains Ombreforge. Ils m\'ont emmené à la forteresse d\'Angor pour étudier deux sortes de pierres étranges venant d\'Uldaman. J\'ai découvert que ces pierres, à condition d\'être bien utilisées, étaient des sources d\'énergie stables. C\'est étonnant tout ce qu\'on peut trouver sur ce vieux site !|n|nBref, après leur avoir appris le secret des pierres, ils m\'ont chassé de la forteresse et ont commencé les fouilles.|n|nJe veux ces pierres ! Apportez-m\'en des deux sortes et je vous paierai bien !', },
    {'Apporter 8 Pierres de puissance Dentrium et 8 Pierres de puissance An\'Alleum à Rigglefuzz dans les Terres ingrates.', },
  },
  [2438] = {
    'Le Capturêve d\'émeraude',
    {'Un jour, Gaerolas Talvethren, le gardien des druides du refuge des saisons de Ban\'ethil, m\'a donné un capturêve d\'émeraude. Cette puissante amulette est capable d\'aspirer l\'énergie du Rêve d\'émeraude pour apporter la chance à ceux qui la portent.|n|nHélas, je n\'ai pas pu la récupérer dans ma commode au village de Brise-Stellaire... Autrefois, Brise-Stellaire était un endroit tranquille, mais il a succombé à la corruption des furbolgs qui y résident.|n|nVoudriez-vous récupérer mon capturêve, $C ?', },
    {'Récupérez le Capturêve d\'émeraude.', },
  },
  [2439] = {
    'Les disques de platine',
    {'Cet objet est incroyable. Si ce qu\'il dit est vrai, les anciens titans, ou les Créateurs comme ces disques les nomment, sont le lien avec notre création enchantée ! Nous devons investir autant de temps que possible dans cette recherche.|n|nPour vous, héroïque $C, apportez ce bon à Dinita Mantepierre à la Banque. Il vous donnera une récompense à la hauteur de cette magnifique trouvaille !|n|nRevenez directement me voir quand vous serez $Gprêt:prête;, il y a encore beaucoup à faire pour la Ligue !', },
    {'Apporter le Bon de récompense à Dinita Mantepierre à la Chambre forte de Forgefer.', },
  },
  [2440] = {
    'Les disques de platine',
    {'Je vais concentrer mes travaux sur ces disques ; ils me révéleront bientôt leur raison d\'être.|n|n$N, je vais vous récompenser pour la diligence avec laquelle vous m\'avez apporté ceci. Portez ce bon à Bena Sabot-d\'Hiver, le maître des alchimistes des Pitons-du-Tonnerre. Elle vous offrira un objet spécial que vous apprécierez sûrement et elle vous proposera un choix de breuvages magiques de ma réserve personnelle.|n|nRevenez vite me voir, car je sens qu\'il y a du pain sur la planche pour étudier cette trouvaille.', },
    {'Apporter le Bon de récompense à Bena Sabot-d\'Hiver aux Pitons-du-Tonnerre.', },
  },
  [2458] = {
    'Sous le couvert de la nuit',
    {'La KapitalRisk... Vous avez entendu parler d\'eux ?|n|nDepuis un an, nous essayons d\'y introduire un de nos agents. Nous avons travaillé dur, mais prudemment, et nous avons réussi.|n|nNous venons d\'apprendre que la KapitalRisk projette une opération de grande envergure. Allez au nord de la Videfange, à la tour de la KapitalRisk, et contactez notre agent, le sous-chef Fizzule.|n|nUne fois sur place, utilisez ce lance-fusées, approchez Fizzule et faites-lui le salut de la Main brisée.', },
    {'Aller à la tour de la KapitalRisk, au nord de la Videfange, et contacter l\'agent secret de la Main brisée, le sous-chef Fizzule.|n|nUne fois la tour en vue, utiliser le lance-fusées pour se signaler au sous-chef Fizzule. Tirer DEUX fusées, puis s\'approcher du sous-chef Fizzule et faire le Salut brisé (/salut).|n|nRespecter l\'ordre de ces actions, car Fizzule attaque et tue toute personne qu\'il ne peut pas identifier.', },
  },
  [2459] = {
    'Ferocitas le Mangeur de rêves',
    {'L\'émeraude... Elle a disparu ! Mon capturêve a été endommagé !|n|nUne bande de mystiques Pins-tordus rôde au nord de Brise-Stellaire. J\'ai entendu dire que leur chef, Ferocitas le Mangeur de rêves, porte un collier qui émet des lueurs vertes dans l\'obscurité. Vu l\'état de mon capturêve, il est certain qu\'il a volé mon émeraude... Il ne comprendra jamais que sa puissance lui est inutile.|n|nTrouvez mon bijou disparu, $N. Et tant que vous y êtes, profitez-en pour nous débarrasser de quelques mystiques corrompus.', },
    {'Tuez 7 Mystiques pins-tordus et retrouvez le Bijou disparu.', },
  },
  [2460] = {
    'Le Salut brisé',
    {'En tant que voleur de la Main brisée, il est impératif que vous appreniez le Salut brisé. C\'est la seule façon d\'identifier un autre membre de la Main.|n|nRegardez, apprenez, répétez.', },
    {'Faire le Salut brisé à Shenthul.', },
  },
  [2478] = {
    'Mission : Possible mais non probable',
    {'Vous devez voler la clé de la tour au contremaître Silixiz, $N. Une fois la clé en votre possession, gardez-la soigneusement, je pourrais en avoir besoin plus tard.|n|nProfitez de l\'état d\'affaiblissement des habitants empoisonnés, et laissez donc votre tendance au chaos et à la destruction s\'exprimer librement. Tuez-les tous ! Ne montrez aucune pitié !|n|nLorsque tous baigneront dans leur sang, ouvrez le coffre de Bisbiwix et volez la mixture de Zanzil. Apportez la tête de Bisbiwix ainsi que la mixture à Shenthul à Orgrimmar.', },
    {'Voler la Clé de la tour de Silixiz au Contremaître Silixiz, puis tuer deux Pantins mutants de la KapitalRisk, deux Patrouilleurs de la KapitalRisk, et deux Sentinelles de la KapitalRisk.|n|nAssassiner le Grand contremaître Bisbiwix et prendre sa tête. Ouvrir le coffre de Bisbiwix et y voler la Mixture altérée de Zanzil. Apporter la Mixture et la tête de Bisbiwix à Shenthul à Orgrimmar, et attendre de nouvelles instructions.', },
  },
  [2479] = {
    'L\'aide d\'Hinott',
    {'Apportez un échantillon du mélange à Serge Hinott à Moulin-de-Tarren.|n|nSi quelqu\'un peut vous guérir, c\'est bien Serge. Si vous vivez suffisamment longtemps, il vous montrera comment créer un poison et comment l\'utiliser.', },
    {'Aller à Moulin-de-Tarren dans les contreforts de Hautebrande et livrer l\'Échantillon de la mixture de Zanzil à Serge Hinott.|n|nPour rejoindre Moulin-de-Tarren, prenez le zeppelin à Fossoyeuse et suivez la route du sud, à travers les Pins-Argentés et vers Hautebrande. Suivez les panneaux !', },
  },
  [2480] = {
    'L\'aide d\'Hinott',
    {'Je n\'ai jamais vu d\'aussi merveilleux résultats pour un poison ! Zanzil, vous dites ? Jamais entendu parler de lui, mais je m\'incline devant le mélange qu\'il a créé.|n|nBon, vous voulez que je vous guérisse et que je vous apprenne ensuite à utiliser le poison ?|n|nLaissez-moi un peu de temps pour examiner la toxine, $N.', },
    {'Attendre Serge Hinott pour achever le remède.', },
  },
  [2498] = {
    'Retour vers Denalan',
    {'Je viens de recevoir un mot de Denalan au lac Al\'Ameth, disant qu\'il a peut-être découvert la cause les tumeurs chez les sylvains. Allez le voir et dites-lui que je vous envoie.|n|nFaites vite, $N, il a besoin de nous.', },
    {'Rellian Vertecime vous demande d\'aller parler à Denalan au lac Al\'Ameth.', },
  },
  [2499] = {
    'Froncechêne',
    {'J\'ai compris ! J\'ai couru vous prévenir ! C\'est tout simple, en fait… La corruption se propage de sylvain en sylvain, mais elle prend sa source dans un seul individu.|n|nFroncechêne a été parasité par la plus grande tumeur que j\'aie jamais vue… On pourrait même dire qu\'elle est gargantuesque.|n|nFroncechêne a longtemps vécu dans une caverne près de mon lac, mais depuis, il s\'est installé dans un creux, au nord-est d\'ici, $N. Traquez Froncechêne et récupérez la tumeur, éliminez cette source de contamination de chez moi.', },
    {'Ôtez la Tumeur gargantuesque de Froncechêne.', },
  },
  [2500] = {
    'Les réactifs des Terres ingrates',
    {'$C, vos services vont m\'être utiles. Je suis alchimiste et j\'ai besoin de votre aide pour trouver certains réactifs dans les Terres ingrates.|n|nJ\'ai besoin de ceci pour ma réserve : 5 Gésiers de busard, 10 Crocs de coyote des rochers et 5 Fragments d\'élémentaire de roche. Évidemment, vous pouvez trouver les réactifs sur les créatures elles-mêmes. Si vous n\'êtes pas du genre battant, trouvez donc des amis qui le soient.|n|nApportez-moi tout ça et je vous récompenserai.|n|nQu\'en dites-vous ?', },
    {'Aller chercher les réactifs dont Ghak Touchesoins a besoin dans les Terres ingrates, puis les lui rapporter à Thelsamar.', },
  },
  [2501] = {
    'Les réactifs des Terres ingrates II',
    {'Vous m\'avez été des plus utiles, $N. Votre récompense sera la recette de la boisson que vous avez goûtée tout à l\'heure... Mais j\'ai une tâche très dangereuse pour vous.|n|nCette boîte fermée contient trois récipients thaumaturgiques vides ; ils sont imprégnés d\'un fluide magique qui drainera le sang d\'un dragon gardien des terres brûlées. Je vous préviens : les bêtes deviennent très agressives quand on les utilise sur elles. Une fois que vous aurez rempli les trois, apportez-les-moi.|n|nFaites cela, et la recette sera à vous !', },
    {'Utiliser les Récipients thaumaturgiques vides sur des dragons gardiens des terres brûlées dans les Terres ingrates. Une fois remplis, les rapporter à Ghak Touchesoins à Thelsamar.', },
  },
  [2518] = {
    'Les larmes de la Lune',
    {'Autrefois, dame Sathrah était aimée d\'Élune. Gracieuse et pure, l\'araignée tissait ses toiles d\'argent au clair de lune pour recueillir la brume du soir. La rosée argentée avait de grands pouvoirs de guérison et on la conservait au temple.|n|nMais récemment, dame Sathrah a sombré dans la folie. Sa descendance à venir est également menacée.|n|nTrouvez dame Sathrah, $N, et mettez fin à ses souffrances. Elle demeure au nord-est, près du fleuve. Prenez ses filières d\'argent et apportez-les-moi.', },
    {'Récupérez les Filières d\'argent de Dame Sathrah.', },
  },
  [2519] = {
    'Le temple de la Lune',
    {'Une créature de la forêt, autrefois l\'une des plus grandes, a besoin de votre aide, $R.|n|nC\'est une tâche difficile, mais qui doit être accomplie.|n|nS\'il vous plaît, allez voir la prêtresse A\'moora, elle vous expliquera de quoi il s\'agit. Elle se trouve au sud-est d\'ici, dans le temple de la Lune.', },
    {'Sœur Aquinne veut que vous parliez à la prêtresse A\'moora, au Temple de la Lune.', },
  },
  [2520] = {
    'Sacrifice de Sathrah',
    {'Maintenant vous devez finir la tâche qui vous a été confiée. Prenez les filières et offrez le sacrifice de dame Sathrah à Élune. Permettez à la grande araignée de trouver le repos.|n|nÀ l\'intérieur du temple, trouvez la fontaine centrale. C\'est là que vous déposerez le sacrifice. Les eaux saintes vont nettoyer et purifier la corruption qui a conduit Sathrah à la folie.|n|nQuand vous aurez fini, revenez me voir.', },
    {'La prêtresse A\'moora vous demande de placer les Filières d\'argent de dame Sathrah dans la fontaine à l\'intérieur du temple, puis de retourner la voir.', },
  },
  [2521] = {
    'Au service de Kum\'isha',
    {'$R, votre cerveau étriqué peut-il comprendre la rareté d\'une sphère de draenéthyste sans défaut ? Les draeneï ont consacré des vies entières à chercher un seul de ces cristaux et ils n\'ont rencontré que des destins horribles.|n|nEt vous voilà devant Kum\'isha, sachant ce qu\'il veut et souhaitant toujours l\'aider ? Très bien, $R... Si en parcourant ces terres, vous trouvez une sphère de draenéthyste sans défaut, apportez-la-moi et je vous récompenserai au-delà de vos rêves les plus fous.', },
    {'Si vous trouvez une sphère de draenéthyste sans défaut au hasard des voyages dans les terres Foudroyées, apportez-la à Kum\'isha le Collecteur.|n|nCette gemme, l\'une des plus rares de tout Azeroth, peut être détenue par n\'importe qui dans le pays.|n|nUne récompense sera donnée pour chaque sphère de draenéthyste sans défaut trouvée et rapportée.', },
  },
  [2522] = {
    'Les efforts de Kum\'isha',
    {'Bien que l\'invocation de portail ait échoué, j\'ai bon espoir que la prochaine tentative sera la bonne.|n|nL\'espoir des draeneï est aussi fort que votre soif de bibelots, $R. Retournez dans ces terres maudites et trouvez une autre sphère de draenéthyste sans défaut.|n|nBien sûr, vous êtes libre d\'accepter ou non cette tâche... *grand sourire*.', },
    {'Trouvez une Sphère de draenéthyste sans défaut, et apportez-la à Kum\'isha le Collecteur.', },
  },
  [2523] = {
    'Fleur-de-chant corrompue',
    nil,
    nil,
  },
  [2541] = {
    'Le druide dormant',
    {'Les chamans Pins-tordus qui habitent cet endroit ont découvert comment séparer l\'esprit d\'un druide dormant de son corps physique. Les furbolgs ont ranimé ma forme physique et l\'utilisent pour attaquer ceux qui essaient d\'explorer le refuge des saisons de Ban\'ethil. Je suis impuissant, pris au piège dans le Rêve d\'émeraude.|n|nVous devez m\'aider. Les chamans Pins-tordus portent un charme étrange qu\'ils utilisent pour exécuter ce rituel et je voudrais l\'examiner. Je vous en prie, $N, il m\'en faut un.', },
    {'Rapporter un Charme vaudou de chaman à Oben Grifferage dans le Refuge des saisons de Ban\'ethil.', },
  },
  [2561] = {
    'Druide de la Griffe',
    {'J\'ai examiné ce charme, $N, et je vois maintenant ce qu\'il faut faire. Prenez-le et suivez mes instructions.|n|nVous devez franchir la porte qui mène à la salle suivante. Vous y trouverez mon corps sans âme. Je regrette de devoir en arriver là, mais je ne vois pas d\'autre moyen de me libérer de l\'emprise des Pins-tordus.|n|nPour me permettre de leur échapper, vous devez tuer ma forme physique. Ensuite, utilisez le charme vaudou sur mon cadavre. Lorsque vous aurez accompli cette tâche, revenez me voir.', },
    {'Tuez le corps privé d\'âme d\'Oben Grifferage, puis utilisez le Charme vaudou.', },
  },
  [2581] = {
    'Joues de Raillecroc',
    {'Tout le monde sait que la mâchoire des hyènes possède une force énorme, mais jusqu\'à quel point ? Au point de mordre dans trois pouces d\'acier au thorium ? Impossible ! Improbable ! Et pourtant je l\'ai vu de mes propres yeux.|n|nAllez dans les terres Foudroyées et apportez-moi trois joues de Raillecroc. En cherchant les Raillecroc, trouvez aussi les sangliers et les scorpoks : la préparation initiale exige deux poumons de sanglier éclatés et une pince de scorpok.', },
    {'Apportez 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial.', },
  },
  [2582] = {
    'La rage des âges',
    {'Oh, $N ! Bienvenue. On dirait que vous avez apprécié l\'effet de ce mélange tiré des Raillecroc. Prenez garde, si l\'effet immédiat est un fantastique regain de force, à long terme les effets pourraient être dangereux pour votre esprit et votre intelligence.|n|nSachant cela, en voulez-vous encore ? Dans ce cas, apportez-moi trois autres joues de Raillecroc, deux poumons de sanglier éclatés et une pince de scorpok.', },
    {'Apportez 3 Joues de Raillecroc, 2 Poumons de sanglier éclatés et 1 Pince de scorpok au Mage de sang Drazial.', },
  },
  [2583] = {
    'La vitalité du sanglier',
    {'Sur ces terres désolées vivent deux espèces de sanglier : le sanglier cendré et le sanglier infernal.|n|nL\'endurance de ces bêtes les rend presque invulnérables, et même les autres prédateurs les évitent.|n|nNous devons faire de nouvelles analyses, $N. Si vous m\'apportez trois Poumons de sanglier éclatés, deux Pinces de scorpok et un Cerveau de basilic, je créerai un élixir divin. Vous serez mon premier cobaye !', },
    {'Apportez 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial.', },
  },
  [2584] = {
    'L\'esprit du sanglier',
    {'Quand je vous ai administré l\'élixir, $N, je savais qu\'une ou deux applications ne rassasieraient pas votre appétit. Et maintenant, je peux voir la faim dans vos yeux. Le mélange provoque une dépendance, à laquelle même les plus forts ne résistent pas.|n|nQu\'il en soit ainsi ! Si vous voulez plus de cocktail de jus de poumon, retournez dans le désert et trouvez-moi trois poumons de sanglier éclatés, deux pinces de scorpok et un cerveau de basilic.', },
    {'Apportez 3 Poumons de sanglier éclatés, 2 Pinces de scorpok et 1 Cerveau de basilic au Mage de sang Drazial.', },
  },
  [2585] = {
    'Le coup décisif',
    {'Avez-vous observé les scorpoks au combat, $N ? Avez-vous vu la grâce et l\'agilité avec lesquelles ils se déplacent ?|n|nSi seulement nous pouvions isoler cette agilité et l\'encapsuler, nous serions riches au-delà de... je veux dire... ce serait bien pour la communauté scientifique.|n|nAidez-moi, $N et je vous permettrai d\'essayer le résultat.|n|nPour faire un échantillon stable, j\'ai besoin de trois Pinces de scorpok, de deux Gésiers de vautour et d\'un Poumon de sanglier éclaté.', },
    {'Apportez 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial.', },
  },
  [2586] = {
    'Le sel de scorpok',
    {'Vous êtes en vie ! C\'est une bonne nouvelle, vraiment. Je suppose que vous revenez pour avoir plus de préparation de scorpok ?|n|nTrès bien, $N, retournez dans le désert et ne revenez pas avant d\'avoir prélevé trois pinces de scorpok, deux gésiers de vautour et un poumon de sanglier éclaté.', },
    {'Apportez 3 Pinces de scorpok, 2 Gésiers de vautour et 1 Poumon de sanglier éclaté au mage de sang Drazial.', },
  },
  [2601] = {
    'La morsure du basilic',
    {'Ces terres désolées sont envahies par les basilics Rougepierre, $N. Ils se sont adaptés et multipliés plus que n\'importe quelle autre espèce.|n|nJ\'ai observé leur technique de chasse et leur comportement : leur processus de pensée est plus complexe que celui de certains humanoïdes.|n|nJe veux étudier leur intelligence !|n|nRapportez-moi dix cerveaux, $N. Cependant, le composé ne sera pas complet sans deux gésiers de vautour pour former la base de la solution.', },
    {'Apportez 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore.', },
  },
  [2602] = {
    'Un esprit infaillible',
    {'Votre concentration est déjà retombée ? Il faut faire d\'autres recherches !|n|nOh oui ! Le prix est le même, $N. Retournez dans les terres Foudroyées et revenez me voir avec dix cerveaux de basilic rougepierre et deux gésiers de vautour.', },
    {'Apportez 10 Cerveaux de basilic et 2 Gésiers de vautour au Mage de sang Lynnore.', },
  },
  [2603] = {
    'La vigueur du vautour',
    {'La mort a réellement des ailes dans les terres Foudroyées, $R. J\'ai vu les pourfendeurs noirs et les racleurs-d\'os festoyer sur de nombreux cadavres d\'explorateurs et déchiqueter même les carcasses les plus atteintes par la maladie. Je me demande comment leur système neutralise la peste qui sévit sur ces terres.|n|nAidez-moi dans mes études, $N ! J\'ai besoin de gésiers ! Egalement de deux joues de Raillecroc pour la base du mélange.|n|nLa récompense de vos efforts sera double.', },
    {'Apportez 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore.', },
  },
  [2604] = {
    'Domination spirituelle',
    {'Je vois que votre feu intérieur a diminué. Cela voudrait-il dire que l\'euphorie n\'a duré qu\'une heure ?|n|nSi vous voulez plus de gomme de gésier, alors j\'ai besoin de plus de gésiers. Retournez dans le désert, $N. Et ne revenez pas avant d\'avoir récupéré dix gésiers et deux joues.', },
    {'Apportez 10 Gésiers de vautour et 2 Joues de Raillecroc au Mage de sang Lynnore.', },
  },
  [2605] = {
    'Le gobelin assoiffé',
    {'J\'ai une idée… J\'ai entendu parler de créatures étranges appelées collecteurs de rosée, vivant au sud-ouest... Elles sont capables de stocker de l\'eau dans des glandes spéciales.|n|nJe pense que si je pouvais me procurer l\'une de ces glandes, je pourrais mettre au point une boisson qui étancherait ma terrible soif ! Pensez-vous que vous pourriez m\'aider, $N ?|n|nAllez au jardin des cactus, $N, c\'est là que vous trouverez les collecteurs de rosée.', },
    {'Trouver une Glande à rosée remplie et l\'apporter à Marin Brouillecaboche à Gadgetzan.', },
  },
  [2606] = {
    'De bon goût',
    {'Beurk ! Cette substance a un goût épouvantable ! Je peux oublier tout de suite mon idée...|n|nAttendez, qu\'est-ce que c\'est que ça ? Oh, je sais ! Vous pensez que je dois continuer de croire en cette substance. Très bien alors...|n|nOh, j\'ai une idée brillante ! Apportez cette rosée à mon amie Saupoudr, c\'est un excellent chef. Racontez-lui ce que nous avons fait, et dites-lui que nous voudrions que ça descende un peu plus facilement.|n|nSi déjà ça a mauvais goût, il faut au moins que ça ait quelque chose de spécial... Et bien moi, je ne le sens pas...', },
    {'Marin Brouillecaboche vous demande d\'aller voir Saupoudr à Gadgetzan.', },
  },
  [2607] = {
    'Le toucher de Zanzil',
    {'On dirait que vous avez rapporté plus d\'informations que je n\'en attendais. Les événements prennent une tournure étrange, $N.|n|nUn remède ? Hum... Rendez-vous à la Cave et allez voir le docteur Mixilpixil, il pourra peut-être vous aider.', },
    {'Aller voir le docteur Mixilpixil dans la Cave de la caserne.', },
  },
  [2608] = {
    'Le toucher de Zanzil',
    {'Oh Ciel ! Vous ressemblez à la mort. Je corrige : j\'ai vu la mort, vous semblez en pire état. Vous ressemblez à ce que serait la mort à son dernier instant.|n|nAh ! Vous entendez ce Noarm ? Notez-le !|n|n*soupir* Hum ! Oui, pour vous aider, je dois prendre un peu de votre sang. Ne vous inquiétez pas, ça ne fait mal que les… cinquante premières fois. Allongez-vous (/coucher) quand vous serez $Gprêt:prête; pour le traitement, $N.', },
    {'S\'allonger (/coucher) pour être $Gexaminé:examinée; par le Docteur Mixilpixil. Comment peut-il trouver le remède s\'il ne peut pas trouver la cause ?', },
  },
  [2609] = {
    'Le toucher de Zanzil',
    {'Le diagnostic est unanime, $N. Vous êtes $Gatteint:atteinte; de « itis ».|n|nHeureusement, j\'ai un remède.|n|nVoilà ce dont j\'ai besoin : une brassée de fleurs sauvages simples, une fiole plombée, un tube en bronze et une bobine de fil de soie chartreuse. La vieille Emma en a laissé pour moi au « Fil le plus fin ». Le magasin se trouve le long des canaux.|n|nDépêchez-vous $N, et ne touchez personne jusqu\'à votre guérison. Oh ! Montgomery dit que vous devriez prendre une douche – c\'est lui qui le dit, pas moi.', },
    {'Apporter au docteur Mixilpixil une Brassée de Fleurs sauvages simples, une Fiole plombée, un Tube en Bronze et une Bobine de Fil de soie chartreuse. Le itis ne guérit pas tout seul.', },
  },
  [2621] = {
    'Le déshonoré',
    {'Des regrets. C\'est tout ce que j\'ai pour l\'instant. Une mauvaise décision aux conséquences horribles. Si seulement j\'avais attendu ces ordres. Peut-être détaillaient-ils les horreurs qui nous attendaient ! Peut-être devaient-ils nous guider autrement ? En fin de compte, c\'est ma faute. Tout cela est ma faute.|n|nJe suis là et j\'attends les ordres. Je dois savoir. Je dois avoir ces ordres.|n|nLe commandant d\'ordonnance Ruag réside à Pierrêche. Trouvez-le et découvrez ce qui est arrivé aux ordres.', },
    {'Aller voir le commandant d\'ordonnance Ruag dans Pierrêche, au Marais des Chagrins.', },
  },
  [2622] = {
    'Les ordres disparus',
    {'Les ordres ? Que voulez-vous faire avec ?|n|nQu\'est-ce que vous insinuez, $N ? Bien sûr que j\'ai relayé ces ordres ! Les soldats auxquels j\'ai envoyé ces ordres ont été pris en embuscade par les murlocs. Un seul s\'en est sorti, si on peut dire. Il peut à peine parler, ne peut pas marcher et on l\'alimente par un tube. Si vous voulez savoir où sont ces ordres, allez voir Bengor. Il est quelque part par là... et, $N, méfiez-vous des endroits où vous fourrez votre nez : il pourrait bien être arraché.', },
    {'Aller voir Bengor dans Pierrêche, au Marais des Chagrins.', },
  },
  [2623] = {
    'Le Parleur des marécages',
    {'Le commandant d\'ordonnance a donné des ordres. Nous avons pris... pris des ordres. Sur le chemin des terres Foudroyées, pris en embuscade.|n|nLes murlocs... Beaucoup de murlocs... Un qui s\'appelle le Parleur des marécages. A pris les ordres de mes mains avant de me frapper le crâne avec sa lance. À l\'est... la caverne...|n|n<Bengor perd connaissance.>', },
    {'Retrouver les Ordres du Chef de guerre et les rendre au Héros de la Horde tombé au combat.', },
  },
  [2641] = {
    'L\'ingrédient secret de Saupoudr',
    {'Quand j\'étais gamine, ma sœur faisait à manger. C\'était horrible ! Mon estomac ne supportait pas sa cuisine, jusqu\'à ce que je trouve ce que j\'aime à appeler mon ingrédient "secret" ! Ajoutez-le à n\'importe quoi et... ouah ! le goût devient génial !|n|nDe quoi je parle ? D\'un champignon, le tragan pourpre. Si vous voulez que je vous aide à rendre buvable ce breuvage écœurant, allez aux Hinterlands et cherchez un petit lac.|n|nLe tragan pourpre ne vit que sous l\'eau.', },
    {'Saupoudr, de Gadgetzan, vous demande de cueillir un Tragan pourpre et de le lui apporter.', },
  },
  [2661] = {
    'Livraison pour Marin',
    {'Voilà la Poudre violette, $N. Portez-la à Marin et dites-lui qu\'il me doit une faveur !', },
    {'Saupoudr vous demande d\'apporter la Poudre violette à Marin Brouillecaboche à Gadgetzan.', },
  },
  [2662] = {
    'Elixir Brouillecaboche',
    {'Maintenant, il faut mélanger cette poudre avec la rosée.|n|nPartez et revenez me voir un peu plus tard... Quand j\'aurai mis au point le fabuleux Élixir Brouillecaboche !', },
    {'Retourner voir Marin Brouillecaboche une fois qu\'il aura créé son élixir.', },
  },
  [2681] = {
    'Les pierres qui nous lient',
    {'Vous ne pourrez pas à vous $Gseul:seule; affronter les forces de Razelikh et de ses subordonnés.|n|nRassemblez un groupe d\'aventuriers pour libérer mes hommes de leur torture éternelle ! Vous devez briser dix-huit pierres.|n|nBattez-vous durement et mourez avec honneur, $N.', },
    {'Libérer 9 Serviteurs de Razelikh, 3 Serviteurs de Sevine, 3 Serviteurs d\'Allistarj et 3 Serviteurs de Grol. Retourner voir le Héros de la Horde tombé au combat une fois la tâche terminée. Il faut rester à proximité des pierres ou le processus échouera.', },
  },
  [2701] = {
    'Les héros des Anciens',
    {'Je vous en prie, prenez cette Relique des Anciens. Nous n\'en avons plus besoin.|n|nPuisse-t-elle bien vous servir dans votre combat contre la Légion.', },
    {'Ouvrir le coffre et prendre la récompense.', },
  },
  [2702] = {
    'Les héros des Anciens',
    {'Votre noblesse et votre héroïsme m\'ont honoré, $N.|n|nVous les avez honorés aussi…', },
    {'Aller voir le caporal Thund Sabot-fendu.', },
  },
  [2721] = {
    nil,
    {'Un chapitre de vos aventures se termine, un autre commence, $N.|n|nL\'un de mes hommes manque toujours à l\'appel, il est perdu quelque part dans ces terres. Je parle du lieutenant Kirith, bien sûr.|n|nComme je l\'ai déjà dit, nous avons été tous deux capturés et torturés par Allistarj mais, pauvre Kirith, sa force a vacillé. Depuis ma cage, je pouvais entendre ce qu\'il subissait, ses cris résonnaient dans toute la caverne. Je ne l\'ai plus vu depuis.', },
    {'Découvrir ce qui est arrivé au Lieutenant Kirith.', },
  },
  [2741] = {
    'Le Super-Oeuf-O-Matic',
    nil,
    nil,
  },
  [2742] = {
    'Rin\'ji est pris au piège !',
    {'Hé $R !|n|nS\'il plaît à vous, aidez Rin\'ji à s\'évader. Moi sais que $R pas aimer race de Rin\'ji, mais Rin\'ji demande pitié ! Rin\'ji doit sortir ici !|n|nCadeau agréable pour $R si $Gil:elle; aider Rin\'ji à sortir...|n|nRin\'ji cache quelque chose de secret sur les Hauts-Surplombs.', },
    {'Escorter Rin\'ji hors du Gîte de Quel\'Danil, puis découvrir son secret caché sur les Hauts-Surplombs, à l\'est.', },
  },
  [2743] = {
    'Le couvert de l\'obscurité',
    {'Faisons vite, $R, mon temps ici est compté.|n|nIl faut détruire la triade de pouvoir qui protège le seigneur-démon Razelikh. Ce ne sera pas aussi facile que de libérer une âme damnée.|n|n<Kirith sourit.>|n|nVous voyez, chacun des trois subalternes de Razelikh porte autour du cou le tiers d\'une amulette créée par Razelikh. L\'amulette dont vous aurez besoin pour appeler le démon.|n|nRetournez voir Trebor et dites-lui comment appeler Razelikh. Il pourra vous aider à aller plus loin.', },
    {'Retourner voir le Héros de la Horde tombé au combat avec ces découvertes.', },
  },
  [2744] = {
    'Le chasseur de démons',
    {'La triade est protégée par Razelikh.|n|nEn échange de leur servitude, Razelikh a accordé à chacun d\'eux un pouvoir presque illimité dans les terres Foudroyées, ainsi qu\'une amulette leur conférant l\'immortalité. Tant qu\'ils restent dans leurs terres, ils ne peuvent pas être tués.|n|nQuelqu\'un peut vous aider à poursuivre, $N. Allez en Azshara et trouvez le chasseur de démons, Loramus Thalipedes. Cherchez-le dans les îles.', },
    {'Aller voir Loramus Thalipedes en Azshara.', },
  },
  [2745] = {
    'En infiltrant le château',
    {'Hum ! Une histoire intéressante à ne pas prendre à la légère. Ouais, je peux vous aider, mais ce que vous devez faire n\'est pas vraiment une justice... légale, si vous allez jusqu\'au bout.|n|nOn doit d\'abord s\'occuper de Lescovar et de Marzon, et vite. Pensez-vous en être capable ?|n|nÀ vous de décider. Si oui, rendez-vous rapidement au château pour y rencontrer un vieil ami à moi, un gnome nommé Tyrion. Il observe Lescovar depuis maintenant quelques semaines. Il devrait pouvoir vous aider à en finir.', },
    {'Allez voir Tyrion au Château de Hurlevent.', },
  },
  [2746] = {
    'Des objets d\'une certaine importance',
    {'Trias veut accélérer les choses, hein ? Bien, nous pouvons le faire, mais je ne suis pas prêt. Je vais faire la partie difficile du boulot, mais c\'est vous qui allez vous salir les mains, d\'accord ? Bon.|n|nIl faut que vous m\'obteniez certaines choses pour mettre mon plan à exécution. J\'ai le déguisement parfait pour que l\'Espion passe ces gardes.|n|nApportez-moi de la soie et deux pommes. Pour la soie, débrouillez-vous, mais vous trouverez des pommes parfaites à la petite ferme de Clara à l\'extérieur de la ville.', },
    {'Apporter 3 Etoffes de soie et 2 Pommes fraîches de Clara à Tyrion à Hurlevent.', },
  },
  [2747] = {
    'Un œuf extraordinaire',
    nil,
    nil,
  },
  [2748] = {
    'Un œuf de premier choix',
    nil,
    nil,
  },
  [2749] = {
    'Un œuf ordinaire',
    nil,
    nil,
  },
  [2750] = {
    'Un mauvais œuf',
    nil,
    nil,
  },
  [2751] = {
    'Remparts barbares',
    {'Vingt générations d\'Omosh ont tenu ce marteau, $N. Nous avons façonné cent mille tonnes de métal. Tragiquement, tout prend fin avec Orokk, l\'échec des Omosh : sans famille et sans héritier.|n|nJe ne peux pas laisser les savoir-faire secrets des Omosh mourir avec moi ! Quelqu\'un doit recueillir cet héritage, qu\'il soit ou non un Omosh !|n|nProuvez à Orokk que vous êtes celui-là, $N. Apportez deux brassards guillochés en bronze, deux glaives en bronze et deux griffes aiguisées. Apportez-les à Orokk et nous pourrons continuer.', },
    {'Apportez 2 Brassards guillochés en bronze, 2 Glaives en bronze et 2 Griffes aiguisées à Orokk Omosh à Orgrimmar.', },
  },
  [2752] = {
    'Épaulettes en fer',
    {'Orokk voit l\'ardeur dans vos yeux, $N. Comme une éponge, vous absorbez la sagesse des leçons des Omosh.|n|nTrois leçons encore !|n|nRetournez à l\'enclume, absorbez-vous dans la chaleur de la forge, créez pour Orokk quatre marteaux de guerre en bronze et quatre haches de guerre en bronze. Ensuite seulement vous apprendrez le secret des Epaulettes en fer.', },
    {'Apporter 4 Haches de guerre en bronze et 4 Marteaux de guerre en bronze à Orokk Omosh à Orgrimmar.', },
  },
  [2753] = {
    'Piétinés',
    {'Deux leçons encore vous enseignera Orokk, $N. Vos muscles font mal, je sais, mais continuez pour les Omosh !|n|nApportez à Orokk quatre heaumes en fer émeraude, quatre brassards en fer émeraude et deux jambières en fer émeraude – pour votre apprentissage et la souffrance de vos ennemis !', },
    {'Apporter 4 Heaumes en fer émeraude, 4 Brassards en fer émeraude et 2 Jambières en fer émeraude à Orokk Omosh à Orgrimmar.', },
  },
  [2754] = {
    'Les cornes de Frénésie',
    {'Voici la dernière leçon d\'Orokk, $N. A l\'enclume sacrée et à la forge, vous devez retourner ! Apportez à Orokk deux maillets en fer massif, deux bottes en bronze argenté et deux gantelets en bronze argenté.|n|nRegardez la crainte grandir dans leurs yeux à votre approche !', },
    {'Apportez 2 Maillets en fer massif, 2 Bottes en bronze argenté et 2 Gantelets en bronze argenté à Orokk Omosh à Orgrimmar.', },
  },
  [2755] = {
    'Les joies des Omosh',
    {'Orokk ne pleure pas, $N. Il a une poussière dans l\'œil.|n|n<Orokk essuie une larme.>|n|nIl y a un dernier secret de famille Omosh qu\'Orokk va transmettre. Orokk mourra heureux, grâce à $N.|n|nApprenez la danse de joie des Omosh et vous apprendrez ensuite le secret des Poings de fer !', },
    {'Regarder et apprendre la Danse de joie des Omosh.', },
  },
  [2756] = {
    'Les vieilles voies',
    {'Aux temps légendaires, Aturk aurait écrasé les crânes de ses ennemis et réduit leurs os en poudre comme combustible de lampe. Ces jours sont loin, $R. Le chef de guerre appelle à la paix parmi les clans. Les vieux ennemis ne sont plus observés que par des yeux fatigués ! |n|nC\'est incroyable, je sais, mais telle est la volonté de Thrall.|n|nAssez ! Vous êtes ici pour apprendre et vous allez apprendre ! Apportez-moi quatre cuirasses en acier et quatre heaumes en plaques d\'acier et vous aurez un avant-goût de la guerre !', },
    {'Apporter 4 Cuirasses en acier et 4 Heaumes en plaques d\'acier à Aturk l\'Enclume à Orgrimmar.', },
  },
  [2757] = {
    'Baie-du-Butin ou la mort !',
    {'Écoutez, $Ggamin:gamine; : vous n\'apprendrez plus rien ici.|n|nJe connais un type qui connaît un autre type. Il tourne autour de la forge à Baie-du-Butin. Montrez-lui cet insigne, il vous dira tout du mithril.|n|nAlors, qu\'en dites-vous ? Laissez cette matière aux bébés dans leurs langes, $N. Il est temps de progresser.|n|nSi ça vous intéresse, ce gars s\'appelle McGavan. Montrez-lui ce bibelot et il reconnaîtra votre engagement.', },
    {'Aller voir McGavan à Baie-du-Butin.', },
  },
  [2758] = {
    'Les origines de la forge',
    {'Quand j\'avais votre âge, un nain du nom de Galvan m\'a pris sous son aile et m\'a tout appris du métier de Forgeron d\'armures. Avant de partir pour Baie-du-Butin, il m\'a fait promettre de former tous ceux qui auraient le désir et la détermination de devenir forgerons.|n|nBien, il est temps pour vous d\'apprendre quelque chose. Faites-moi six brassards en écailles dorées et vous comprendrez comment on devient forgeron, $N.', },
    {'Apportez 6 Brassards en écailles dorées à Hank le Marteau à Hurlevent.', },
  },
  [2759] = {
    'À la recherche de Galvan',
    {'Galvan a quitté Baie-du-Butin depuis longtemps, mais les membres de l\'ordre sont restés en ville, espérant trouver un jour une autre personne digne de la tutelle de Galvan.|n|nPortez cet insigne à McGavan à Baie-du-Butin.|n|nSi vous avez réussi à aller aussi loin, il saura que vous êtes digne de lui. J\'ai foi en vous, $N !', },
    {'Aller voir McGavan à Baie-du-Butin.', },
  },
  [2760] = {
    'L\'ordre du Mithril',
    {'La plupart de nos recrues ne vont jamais jusqu\'à Baie-du-Butin, $N. L\'éclat de l\'insigne est suffisant pour déclencher la convoitise, même chez le plus loyal des forgerons. Les imbéciles ! Cet insigne est une goutte d\'eau en comparaison de l\'océan des richesses que vous verrez !|n|nAllez trouver Galvan l\'Ancien et montrez-lui cette épingle. Il habite loin au nord, entre Zul Gurub et le tertre des ogres mosh\'Ogg.', },
    {'Aller voir Galvan l\'Ancien dans la vallée de Strangleronce.', },
  },
  [2761] = {
    'Ça fond, ça ne fond pas',
    {'Beaucoup de forgerons pensent qu\'extraire le minerai et le travailler sont des tâches distinctes, indépendantes, mais qui peut être forgeron sans être mineur ? C\'est impossible ! Un forgeron accompli doit aussi être un mineur accompli.|n|nMontrez donc à Galvan ce dont vous êtes capable, $N. Apportez-moi quarante barres de fer et quarante barres de mithril. En échange, Galvan vous apprendra comment réaliser un pantalon orné en mithril !', },
    {'Apporter 40 Barres de mithril et 40 Barres de fer à Galvan l\'Ancien à Strangleronce.', },
  },
  [2762] = {
    'Le vif-argent n\'est pas de l\'argent',
    {'On dit que le vrai-argent est plus solide et plus résistant que le mithril. Galvan n\'est pas contre les comparaisons, mais contrairement à ce que son nom laisse croire, le vrai-argent n\'est pas de l\'argent ! Le mithril est un minerai beaucoup plus noble ! Il faut comprendre cela par soi-même, $N.|n|nApportez-moi quarante barres de mithril et cinq barres de vrai-argent. En échange, vous apprendrez le secret des gants ornés en mithril, et mieux, vous comprendrez que le vrai-argent ne tient pas ses promesses !', },
    {'Apporter 40 Barres de mithril et 5 Barres de vrai-argent à Galvan l\'Ancien à Strangleronce.', },
  },
  [2763] = {
    'L\'art de l\'imprégnation',
    {'Les pierres précieuses sont de la plus grande importance pour notre art, $N. Peu de gemmes sont plus précieuses que la citrine. Elle amplifie les propriétés magiques que nous insufflons à nos produits.|n|nPour cette leçon, nous allons renforcer quarante barres de mithril avec quatre citrines. Cela vous permettra de mieux comprendre la gemmologie magique et comment créer des épaulières ornées en mithril.', },
    {'Apporter 40 Barres de mithril et 4 Citrines à Galvan l\'Ancien à Strangleronce.', },
  },
  [2764] = {
    'Le meilleur disciple de Galvan',
    {'Si vous êtes sur le point de terminer votre formation avec Galvan, vous devez aller à Gadgetzan.|n|nLà, vous trouverez mon meilleur élève : Trenton Martelume. Il a beaucoup à vous apprendre sur le mithril orné. Sinon restez ici et apprenez !|n|nOh bien sûr, Gadgetzan est à Tanaris !', },
    {'Parler à Trenton Martelume à Gadgetzan.', },
  },
  [2765] = {
    'Maître Forgeron !',
    {'J\'ai su, dès que je vous ai $Gvu:vue;, que vous deviendriez $Gl\'un:l\'une; de mes meilleurs disciples ! Vous n\'avez pas hésité à donner une relique à McGavan,dans le seul but de me rencontrer. Une telle foi et une telle dévotion pour l\'art doivent être récompensées.|n|nVous avez atteint l\'expertise dans l\'art de la forge, $N. Cueillez le fruit de vos efforts !', },
    {'Réclamez votre récompense à Galvan l\'Ancien !', },
  },
  [2766] = {
    'Trouvez OOX-22/FE !',
    {'Vous découvrez une sorte d\'engin métallique en forme d\'œuf, qui revient à la vie lorsque vous tripotez l\'un de ses boutons. Il semblerait que ce soit un machin robotique gnome ! Une voix grésille :|n|n« Mon nom est Orguignard Odipnoticus, et mon robot guidé s\'est perdu ! Je vous récompenserai si vous le retrouvez. S\'il vous plaît, allez placer cette balise dans le robot.|n|nJ\'ai calculé la position de mon robot égaré : il est dans une caverne près du val des Griffes farouches ! ».', },
    {'Placez la balise de détresse dans le robot d\'Orguignard qui se trouve dans une caverne près du val des Griffes farouches.', },
  },
  [2767] = {
    'À la rescousse de OOX-22/FE !',
    {'Le robot émet à nouveau la voix du gnome :|n|n« Je dois déplacer OOX-22/FE dans un endroit dégagé et sûr pour qu\'il puisse entamer sa longue procédure de décollage. Il est équipé d\'un camouflage, mais il me faut du temps pour le rendre opérationnel. J\'ai besoin que vous escortiez le robot jusqu\'à... disons la route principale ! Ce serait un endroit parfait et assez vaste pour que tout puisse se mettre en route ! »|n|n« Escortez-le jusque là-bas, et venez me parler à Baie-du-Butin ! Orguignard Odipnoticus - terminé ! »', },
    {'Escortez OOX-22/FE jusqu\'à ce qu\'il soit en sécurité, puis rendez compte à Orguignard Odipnoticus à Baie-du-Butin.', },
  },
  [2768] = {
    'Bâtonnet divino-matic',
    {'Le sergent Bly m\'a volé ! Il a dit qu\'il ne faisait que l\'emprunter, mais il a volé mon précieux bâtonnet divino-matic ! Sans lui, comment savoir où creuser de nouveaux puits ?|n|nTrouvez Bly et reprenez mon bâtonnet ! J\'ai entendu qu\'il emmenait une bande d\'aventuriers mal famés chasser les trésors à l\'ouest, à Zul\'Farrak. Je parie que vous le trouverez là-bas.|n|nEspérons que les trolls se seront déjà occupés de lui, car si vous devez l\'affronter pour reprendre le bâtonnet, le combat sera difficile.', },
    {'Apportez le Bâtonnet divino-matic à l\'Ingénieur en chef Vizisanie, à Gadgetzan.', },
  },
  [2769] = {
    'Les frères Zéboulon',
    {'Avez-vous rencontré les frères Zéboulon ? Ils sont dans les Salines en Kalimdor. Ils font des courses de voitures à fusée contre les gobelins. Ils gagnent régulièrement. Il faut dire que les voitures des gobelins explosent si souvent qu\'elles passent rarement la ligne d\'arrivée !|n|nMalgré cela, les frères Zéboulon cherchent toujours à avoir une voiture plus rapide. Lachnouf m\'a dit qu\'il cherchait un composant très rare pour sa nouvelle expérience.|n|nIl a besoin d\'aide pour trouver ce composant. Allez l\'aider.', },
    {'Parler à Lachnouf Zéboulon dans les Salines.', },
  },
  [2770] = {
    nil,
    {'Au cœur de Zul\'Farrak, la cité des trolls des sables à Tanaris, il y a un bassin sacré. De ce bassin, les trolls invoquent une bête énorme ! Gahz\'rilla ! Elle est tellement puissante que même ses écailles crépitent d\'énergie. C\'est cette énergie que je convoite pour ma voiture !|n|nRapportez-moi une écaille électrifiée de Gahz\'rilla !|n|nMais l\'invocation de Gahz\'rilla est l\'un des secrets les mieux gardés des trolls. Avant d\'affronter le monstre, vous devez apprendre le secret des trolls.', },
    {'Rapporter l\'Ecaille électrifiée de Gahz\'rilla à Lachnouf Zéboulon dans les Salines.', },
  },
  [2771] = {
    'Une tête bien faite sur les épaules',
    {'Il semble que le maître ait planifié tout cela depuis le début. Je n\'ai pas appris à créer le genre d\'objet que vous savez créer, de même que vous ne savez pas créer ce que je sais faire.|n|nLe maître est sage, $N. Chacun de nous doit apprendre de l\'autre !|n|nMontrez-moi comment faire un camail en mithril et des épaulières ornées en mithril et je vous montrerai comment faire un heaume orné en mithril.', },
    {'Apportez deux Camails en mithril et une paire d\'Epaulières ornées en mithril à Trenton Martelume.', },
  },
  [2772] = {
    'Le monde à vos pieds',
    {'Au dernier championnat intervallée des forgerons, tous les spectateurs ont vu un de ces chiens de la mine de la KapitalRisk m\'attaquer la jambe. Mais ils ne savent pas ce qui m\'a permis de continuer et de gagner ce championnat. Eh oui ! Des bottes ornées en mithril !|n|nJe vais avoir besoin d\'apprendre à faire un pantalon orné en mithril cette année, car la KapitalRisk participe encore au championnat ! Apprenez-moi comment faire le pantalon et je vous apprendrai à faire les bottes !', },
    {'Apportez deux paires de Bottes en mithril lourd et un Pantalon orné en mithril à Trenton Martelume.', },
  },
  [2773] = {
    'Le gars du mithril',
    {'Dans cette région, on m\'appelle le gars du mithril. Je fournis des équipements ornés en mithril aux aventuriers du monde entier.|n|n<Trenton chuchote.>|n|nPeu savent que je ne connais pas la technique des gants ornés en mithril. Mais chut ! Cela sera notre petit secret.|n|nEnseignez-moi cette technique, $N, et en échange je vous montre le point culminant de mon apprentissage chez Galvan : la cuirasse ornée en mithril.', },
    {'Apportez deux Cuirasses lourdes en mithril et une paire de Gants ornés en mithril à Trenton Martelume.', },
  },
  [2781] = {
    'ON RECHERCHE : Caliph Dard-de-Scorpide',
    {'ON RECHERCHE : Caliph Dard-de-Scorpide !|n|nLa Compagnie des Eaux de Gadgetzan de Tanaris paiera une forte récompense pour la tête de Caliph Dard-de-Scorpide, chef des hors-la-loi Bat-le-Désert. Ses crimes sont :|n|n1) Assassinat d\'employés de la Compagnie des Eaux de Gadgetzan ;|n2) Vol des ressources de la Compagnie des Eaux de Gadgetzan ;|n3) Vol des biens de la Compagnie des Eaux de Gadgetzan.|nRapportez les preuves de la mort de Caliph Dard-de-Scorpide à l\'ingénieur en chef Vizisanie pour toucher immédiatement votre récompense.', },
    {'Apportez la tête de Caliph Dard-de-Scorpide à l\'Ingénieur en chef Vizisanie à Gadgetzan.', },
  },
  [2782] = {
    'Secret de Rin\'ji',
    {'La tablette est couverte de lettres gravées par des trolls fanécorces. Le secret de Rin\'ji est réellement un mystère…|n|nIl est possible que vous ayez quelque chose de réellement précieux entre les mains. Mais l\'inverse est également possible. Un troll fanécorce en détresse ferait probablement n\'importe quoi pour s\'en sortir...', },
    {'Oran Serpenroule, une érudite réputée pour sa connaissance des us et coutumes des trolls fanécorces, pourrait peut-être déchiffrer la tablette. Elle habite le Quartier de la Magie à Fossoyeuse.', },
  },
  [2783] = {
    'Querelles mesquines',
    {'Nous avons combattu le mauvais ennemi, $N.|n|nLa vraie puissance de cette région continue de croître alors que nous nous chamaillons avec les orcs sur cette terre aride.|n|nDevons-nous continuer à nous battre contre la Horde, pour finir écrasés un jour par les armées de la Légion ardente ? C\'est futile.|n|nMettez vos différences de côté, $N, parlez au Héros de la Horde tombé au combat. Il sait ce qui se passe dans les terres Foudroyées.', },
    {'Parlez au Héros de la Horde tombé au combat à la frontière des Terres Foudroyées et du marais.', },
  },
  [2784] = {
    'Perte d\'honneur',
    {'Écoutez mon histoire, $R.', },
    {'Écouter le Héros de la Horde tombé au combat raconter son histoire.', },
  },
  [2801] = {
    'Une histoire de chagrin',
    {'Avant que nous ne continuions, vous devez écouter mon histoire.', },
    {'Écouter le Héros de la Horde tombé au combat raconter son histoire.', },
  },
  [2821] = {
    'La marque de la qualité',
    {'Ma philosophie, concernant le travail du cuir, c\'est que mon travail doit être le meilleur possible : pas de compromis. Quelqu\'un disant que la qualité ne compte pas essaye de vous escroquer !|n|nDans ma recherche de matières premières de qualité, rien ne vaut la peau de yéti épaisse. Elle provient des yétis de Féralas, et il y en a beaucoup au val des Griffes farouches. J\'en ai besoin et j\'échangerai l\'un de mes objets en cuir contre un ballot de dix peaux. Si cela vous semble équitable, le marché est conclu.', },
    {'Rapporter 10 Peaux de yéti épaisses à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2822] = {
    'La marque de la qualité',
    {'Je suis fier de mon travail et je sais que cela se voit : la qualité ne doit jamais être dévalorisée. Quiconque dit que la qualité n\'est pas primordiale ferait également croire que les abysses sont lumineux.|n|nDans ma recherche de matières premières de qualité, rien ne vaut la peau de yéti épaisse. Elle provient des yétis de Féralas, et il y en a beaucoup au val des Griffes farouches, à l\'ouest d\'ici. Je vous laisserai choisir un objet parmi mes créations contre un ballot de dix peaux. Si cela vous convient, nous faisons affaire !', },
    {'Apporter 10 Peaux de yéti épaisses à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2841] = {
    'Guerre des plates-formes',
    {'Technologie gnome… Ce terme était autrefois brandi comme un slogan. Les temps ont changé. Ils ont désormais une nouvelle plateforme, supérieure à tous nos modèles de déchiqueteurs combinés. J\'ai besoin des plans de cette plateforme, $N !|n|nMalheureusement ceux-ci sont enfermés dans le coffre du mekgénieur Thermojoncteur. Et pour compliquer les choses, la combinaison du coffre n\'est connue que de lui seul.|n|nFaites ce qu\'il faut pour obtenir cette combinaison, $N. Puis ouvrez le coffre et rapportez-moi ces plans !', },
    {'Obtenez la Combinaison du coffre de Thermojoncteur, prenez les Plans de la plateforme à Gnomeregan et apportez-les à Nogg, à Orgrimmar.', },
  },
  [2842] = {
    'L\'ingénieur en chef Scooty',
    {'Dès que nous aurons des nouvelles de Kernobee à propos de la nouvelle plateforme des gnomes, Scooty et moi commencerons à travailler sur le Transpolyporteur 6000 : le moyen le plus rapide et le plus sûr d\'aller à Gnomeregan.|n|nIl est enfin prêt à recevoir des passagers, $N. Si vous désirez l\'essayer, allez à Baie-du-Butin et parlez avec Scooty au perchoir des coursiers du vent. Pour aller à Baie-du-Butin, prenez le bateau depuis Cabestan.|n|nVous pouvez aussi traverser les montagnes de Dun Morogh, mais elles sont infestées de nains…', },
    {'Parler à Scooty à Baie-du-Butin.', },
  },
  [2843] = {
    'Gnomer-paaarti !',
    {'Aussi longtemps que vous êtes en possession du transpondeur gobelin, tout ce que vous avez à faire est de traverser le portail et vous vous retrouverez à Gnomeregan.|n|nIl y aura peut-être des effets secondaires bizarres, mais aucun ne devrait être permanent... plus maintenant.|n|nJ\'oubliais de parler du plus important : le retour. Lorsque vous serez $Gprêt:prête; à revenir, allez au portail de multitéléportation de Gnomeregan !|n|nBon, il faut maintenant régler le transpondeur selon votre poids et votre taille.', },
    {'Attendre que Scooty calibre le Transpondeur gobelin.', },
  },
  [2844] = {
    'Le garde géant',
    {'Je suis vraiment bon à rien, $N. J\'étais supposé surveiller mon amie Shay, et je l\'ai perdue. Je ne suis pas sûr de ce qui s\'est passé, mais la dernière fois que je l\'ai vue, nous étions en train de marcher dans les ruines au nord d\'ici.|n|nTout allait bien, mais lorsque je me suis retourné vers elle... elle avait disparu.|n|nMaintenant je ne sais plus quoi faire. Vous avez une idée, $N ? Je suis affreusement inquiet.|n|nEt si vous alliez la chercher ? Vos jambes vous permettent d\'aller plus vite que moi.', },
    {'Retrouver la jeune elfe de la nuit perdue.', },
  },
  [2845] = {
    'Shay l\'égarée',
    {'Pouvez-vous m\'aider à retrouver mon chemin jusqu\'à mon ami, Croque-roc ? Il était supposé me surveiller… Mais j\'ai tendance à folâtrer de-ci de-là. Il y a tant de choses à voir et je me laisse facilement distraire.|n|nIl y a toutefois une chose qui me ramène toujours.|n|nDans ce coffre, vous trouverez une cloche qui m\'est précieuse. J\'adore sa sonorité. Si je m\'égare, vous n\'avez qu\'à la faire sonner, je reviendrai immédiatement.', },
    {'Prendre la Cloche de Shay dans le coffre.|n|nEscorter Shay Coursefeuille au Camp de Croque-roc.', },
  },
  [2846] = {
    'Tiare des abysses',
    {'Il y a longtemps, je possédais une splendide pièce de joaillerie, la tiare des abysses. Elle n\'était pas seulement belle, elle détenait un grand pouvoir, pour ceux qui savaient l\'utiliser.|n|nQuand l\'hydromancienne Velratha a appris son existence, elle l\'a convoitée. Elle a envoyé des agents chez moi pour la voler pendant mon absence. Voleurs !|n|nJe veux ma tiare ! Allez à Zul\'Farrak, la cité des trolls à Tanaris, trouvez Velratha et reprenez-lui la tiare. Rapportez-la et vous gagnerez mes faveurs.', },
    {'Apportez la Tiare des abysses à Tabetha au marécage d\'Âprefange.', },
  },
  [2847] = {
    'L\'armure en cuir fauve',
    {'$N, vous avez acquis une bonne connaissance du travail du cuir ! Mais je sais des choses qui pourraient vous intéresser… L\'armure en cuir fauve ! L\'intérêt du cuir fauve tient aux propriétés chaotiques des sauvageonnes et de quelques autres créatures d\'ici. L\'armure que vous réaliserez sera ce qu\'un artisan de votre compétence peut fabriquer de mieux.|n|nJe vous apprendrai à la réaliser si vous acceptez de travailler pour moi pendant un moment. Le coût initial est juste de dix pièces de cuir épais. Après nous parlerons technique.', },
    {'Rapporter 10 Cuirs épais à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2848] = {
    'Epaulières en cuir fauve',
    {'Les épaulières en cuir fauve protègent efficacement le haut des bras et les épaules. Comme l\'ensemble des pièces d\'armure en cuir fauve, elles bénéficient d\'une qualité supplémentaire, mais aléatoire, en raison de l\'utilisation des sauvageonnes.|n|nPour ce patron, j\'ai besoin de six renforts d\'armure épais et d\'une sauvageonne. Cela ne devrait pas vous poser de problèmes.', },
    {'Apporter 6 Renforts d\'armure épais et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2849] = {
    'Gilet en cuir fauve',
    {'Le gilet est la pièce maîtresse de toute armure en cuir fauve. Il procure une protection maximale du torse tout en permettant à la puissante magie des sauvageonnes de se diffuser dans l\'armure.|n|nPour ce modèle, je demande deux paires de gants en écailles de tortue, deux cuirasses en écailles de tortue et une sauvageonne. C\'est une grosse commande, mais vous ne devriez pas avoir de problème à me la fournir.', },
    {'Rapporter 2 Cuirasses en écailles de tortue, 2 paires de Gants en écailles de tortue et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2850] = {
    'Casque en cuir fauve',
    {'Un casque en cuir fauve offre une protection optimale sans sacrifier au confort. Comme pour l\'armure en cuir fauve, les sauvageonnes lui apportent une amélioration puissante, mais aléatoire. Les porteurs d\'armures de cuir raffolent de cet article !|n|nPour ce modèle, j\'ai besoin de deux tuniques de la nuit, deux bandeaux de la nuit et d\'une sauvageonne. Complétez cette commande et le patron est à vous !', },
    {'Rapporter 2 Tuniques de la nuit, 2 Bandeaux de la nuit et 1 Sauvageonne à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2851] = {
    'Bottes en cuir fauve',
    {'Vous avez déjà beaucoup appris, $N. Mais ce n\'est pas fini. Après viennent les bottes en cuir fauve, la pierre angulaire de tout l\'équipement.|n|nCes bottes protègent bien les pieds tout en étant très confortables. Les semelles souples sont une bénédiction pour ceux qui se déplacent discrètement.|n|nPour ces bottes, j\'ai besoin de deux pantalons de la nuit, de deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, faites-le-moi savoir.', },
    {'Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2852] = {
    'Jambières en cuir fauve',
    {'Vous pouvez maintenant apprendre des techniques plus complexes, $N. Les jambières en cuir fauve sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l\'utiliseront apprécieront grandement cette protection combinant l\'amélioration apportée par la sauvageonne.|n|nPour ce modèle, j\'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.', },
    {'Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Pratt McGrubben au bastion de Pennelune.', },
  },
  [2853] = {
    'Maître du cuir fauve',
    {'Eh bien, $N ! Vous êtes un modèle de rapidité. Vous connaissez tous les patrons de l\'armure en cuir fauve, sauf un. Je ne vous demanderai rien pour celui-là, vous le méritez… mais je ne peux pas vous l\'apprendre moi-même. Mon maître est le seul qui puisse vous transmettre ce savoir.|n|nPortez cette lettre à Telonis, il enseigne le travail du cuir à Darnassus. Montrez-lui la lettre et laissez-le vous reconnaître comme son égal, ainsi que je l\'ai fait.', },
    {'Donner la Lettre de Pratt à Telonis, le Maître tanneur de Darnassus.', },
  },
  [2854] = {
    'L\'armure en cuir fauve',
    {'$N, la renommée de vos talents vous précède. Je connais quelque chose qui pourrait vous intéresser... l\'armure en cuir fauve ! Le cuir fauve tire ses propriétés des sauvageonnes que l\'on trouve dans la végétation luxuriante et sur quelques créatures. Cela ne devrait pas être compliqué pour quelqu\'un de votre niveau.|n|nJe vous enseignerai, mais en échange vous travaillerez pour moi pendant un moment. La première chose consiste à me rapporter dix pièces de cuir épais. Après nous discuterons technique.', },
    {'Rapporter 10 Cuirs épais à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2855] = {
    'Epaulières en cuir fauve',
    {'Les épaulières en cuir fauve protègent efficacement le haut des bras et les épaules. Comme toutes les pièces d\'armure en cuir fauve, elles bénéficient d\'une amélioration puissante, mais aléatoire, grâce aux sauvageonnes.|n|nPour ce modèle, je demande six renforts d\'armure épais et une sauvageonne. Cela ne devrait pas vous poser trop de problèmes.', },
    {'Apporter 6 Renforts d\'armure épais et 1 Sauvageonne à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2856] = {
    'Gilet en cuir fauve',
    {'Le gilet est la pièce maîtresse de toute armure en cuir fauve. Il procure une protection maximale du torse tout en permettant à la puissante magie des sauvageonnes de se diffuser dans l\'armure.|n|nPour ce patron, il me faut deux cuirasses et deux paires de gants en écailles de tortue, et aussi une sauvageonne. Ce n\'est pas une leçon facile, mais vous disposez clairement des talents pour la mener à bien.', },
    {'Rapporter 2 Cuirasses en écailles de tortue, 2 paires de Gants en écailles de tortue et une Sauvageonne à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2857] = {
    'Casque en cuir fauve',
    {'Un casque en cuir fauve offre au porteur une protection optimale sur les parties vitales sans sacrifier au confort. Comme pour l\'armure en cuir fauve, les sauvageonnes lui confèrent une amélioration puissante et aléatoire. Les porteurs d\'armure en cuir fauve souhaiteront avoir cette pièce d\'équipement !|n|nPour ce modèle, j\'ai besoin de deux tuniques de la nuit, deux bandeaux de la nuit et d\'une sauvageonne. Rapportez-les et le patron est à vous !', },
    {'Rapporter 2 Tuniques de la nuit, 2 Bandeaux de la nuit et 1 Sauvageonne à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2858] = {
    'Bottes en cuir fauve',
    {'Vous avez déjà beaucoup appris, $N. Mais ce n\'est pas tout. L\'étape suivante concerne les bottes en cuir fauve.|n|nElles protègent bien les pieds tout en restant confortables. Les semelles souples sont une bénédiction pour ceux qui aiment se déplacer discrètement.|n|nPour ces bottes, j\'ai besoin de deux pantalons de la nuit et deux paires de bottes de la nuit, ainsi que de deux sauvageonnes. Lorsque vous aurez tout cela, nous continuerons.', },
    {'Rapporter 2 Pantalons de la nuit, 2 paires de Bottes de la nuit et 2 Sauvageonnes à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2859] = {
    'Jambières en cuir fauve',
    {'Vous pouvez maintenant apprendre des techniques plus complexes, $N. Les jambières en cuir fauve sont un des équipements en cuir les plus résistants et les plus puissants. La taille, les hanches et les parties vitales sont particulièrement bien protégées. Les aventuriers qui l\'utiliseront apprécieront grandement cette protection combinant l\'amélioration apportée par la sauvageonne.|n|nPour ce modèle, j\'ai besoin de deux casques en écailles de tortue, de deux brassards en écailles de tortue et de deux sauvageonnes.', },
    {'Rapporter 2 Casques en écailles de tortue, 2 Brassards en écailles de tortue et 2 Sauvageonnes à Jangdor Rôdeur-agile au Camp Mojache.', },
  },
  [2860] = {
    'Maître du cuir fauve',
    {'$N, vous avez appris tout ce que je pouvais vous enseigner. Il reste néanmoins un dernier élément de l\'armure en cuir fauve à apprendre. Je ne vous demanderai rien pour celui-là, vous l\'avez mérité. Mais je ne peux vous le donner.|n|nMon maître est la seule personne à pouvoir vous l\'enseigner. Remettez cette lettre à Una, qui enseigne le travail du cuir aux Pitons-du-Tonnerre. Montrez-lui la lettre et laissez-la vous reconnaître comme son égal, ainsi que je l\'ai fait.', },
    {'Donner la Lettre de Jangdor à Una, le Maître tanneur des Pitons-du-Tonnerre.', },
  },
  [2861] = {
    'La mission de Tabetha',
    {'La rumeur dit que Tabetha, une collègue mage qui vit loin dans le marécage d\'Âprefange, a un compte à régler avec une certaine trolle des sables à Zul\'Farrak. Si vous parlez à Tabetha, elle pourra vous en dire davantage.|n|nEt invitez quelques amis, $N. Si Tabetha vous envoie à Zul\'Farrak, il ne faut pas y aller $Gtout seul:toute seule;.|n|nVous trouverez le cottage de Tabetha à l\'ouest de Theramore, juste au nord des ruines Cognepierres.', },
    {'Parler à Tabetha dans le marécage d\'Âprefange.', },
  },
  [2862] = {
    'La guerre avec les Griffebois',
    {'Les gnolls… Ils sont plus qu\'une nuisance. Ils représentent une menace constante pour ce campement ! Qu\'ils soient natifs de Féralas ou non n\'a aucune importance. Si nous ne prenons pas rapidement des mesures appropriées, nous serons balayés de la région.|n|nLes attaques contre le camp sont de pire en pire. Nous avons besoin de votre aide pour réduire leur nombre. Rapportez-moi dix crinières et je vous récompenserai de vos efforts.|n|nAllez !', },
    {'Rapportez 10 Crinières de gnolls griffebois à Hadoken Rôdeur-agile, au Camp Mojache.', },
  },
  [2863] = {
    'Frappe sur les Alphas',
    {'Le plan concerne divers chefs gnolls - les Alphas pour reprendre leur propre appellation - et leur élimination successive en un minimum de temps. Si nous pouvions exécuter ce genre d\'éradication rapide et précise contre eux, cela amènerait le chaos dans leurs rangs. Et peut-être que le message passerait même à l\'intérieur de leurs têtes épaisses et infestées de puces que nous pouvons et allons les détruire !|n|nJe veux que vous soyez $Gle messager:la messagère; de ma volonté. Éliminez cinq de leurs Alphas en une heure pour cette mission, $N, ou nous resterons dans l\'impasse.', },
    {'Tuez 5 Alphas griffebois et retournez voir Hadoken Rôdeur-agile en moins d\'une heure.', },
  },
  [2864] = {
    nil,
    {'Mon cousin Tran\'rek me pose un problème. Il m\'a promis une cargaison de carapaces de scarabées il y a quelques semaines, et je n\'ai toujours rien reçu. C\'est mon cousin, je n\'aimerais donc pas le rappeler méchamment à l\'ordre.|n|nPouvez-vous lui parler avant que je ne commette un acte regrettable ? Dites-lui que j\'ai vraiment besoin de cette cargaison.|n|nGadgetzan est dans le nord de Tanaris, en Kalimdor.', },
    {'Parler à Tran\'rek à Gadgetzan.', },
  },
  [2865] = {
    'Les carapaces de scarabées',
    {'Les scarabées de Tanaris ont une carapace très dure ! Si dure qu\'elle est utilisée dans de nombreux domaines.|n|nEn fait ces carapaces sont si utiles que les scarabées ont presque disparu !|n|nJe sais où trouver des scarabées, mais vous devez me promettre de ramener leurs carapaces. Promis ?|n|nOK, les scarabées ont une colonie à Zul\'Farrak. Je pense que les trolls ne les chassent pas pour leurs carapaces.|n|nMais vous si ! Allez à Zul\'Farrak et trouvez-moi ces carapaces intactes !', },
    {'Rapporter 5 Carapaces de scarabée intactes à Tran\'rek à Gadgetzan.', },
  },
  [2866] = {
    'Les ruines de Solarsal',
    {'Au sud se trouvent les ruines de Solarsal, un site bien antérieur à l\'ère moderne. Nous avons exploré ces ruines et rien trouvé, aussi les avons-nous délaissées.|n|nTrès récemment, les nagas hainecrêtes se sont installés en nombre dans les ruines. Au début, nous pensions à une attaque. Bien que cela soit toujours possible, nous croyons qu\'il s\'agit d\'autre chose.|n|nAllez là-bas, explorez les ruines et rendez compte de tout ce qui vous paraîtra inhabituel. Bonne chance, $N.', },
    {'Explorer les ruines de Solarsal et enquêter sur la présence des nagas dans le secteur.', },
  },
  [2867] = {
    'Retourner au bastion de Pennelune',
    {'Après la découverte du belvédère étrange au cœur des ruines de Solarsal, il est temps de retourner au bastion de Pennelune et faire votre rapport au général Shandris Pennelune.', },
    {'Retourner voir Shandris Pennelune au bastion de Pennelune et lui rendre compte de vos découvertes.', },
  },
  [2868] = {
    nil,
    {'Faites de ce mauvais garçon une tombe trolle dans le Temple englouti et récupérez quelque chose de sympathique !', },
    nil,
  },
  [2869] = {
    'Contre les Hainecrêtes',
    {'La meilleure approche est de penser, indépendamment du projet réel des nagas, qu\'ils tentent de prendre possession de l\'île. Nous devons réagir énergiquement avant qu\'il ne soit trop tard.|n|nRapportez-moi dix écailles de Hainecrête en bon état ; pas besoin de vous expliquer comment vous les procurer. Vous diminuerez leur puissance et affaiblirez leur présence sur l\'île de Sardor, ce qui joue en notre faveur.', },
    {'Rapporter 10 Écailles de naga hainecrête à Latronicus Lancelune au bastion de Pennelune.', },
  },
  [2870] = {
    'Contre le seigneur Shalzaru',
    {'$N, de nouveaux rapports nous donnent une bonne idée de la chaîne de commandement des nagas. Parmi le tout-venant se trouvent des individus de sang royal, et ce sont eux qui prennent toutes les décisions.|n|nNous avons identifié l\'un de ces nobles, le seigneur Shalzaru. Nos agents disent qu\'il a découvert une relique étrange au cours de fouilles récentes qu\'il a menées dans une caverne au sud des ruines principales, sur l\'île de l\'Effroi.|n|nArrêtez les autres en neutralisant Shalzaru et rapportez-moi sa relique afin que nous puissions l\'étudier.', },
    {'Éliminez le seigneur Shalzaru et rapportez la Mystérieuse relique qu\'il a découverte à Latronicus Lancelune, au bastion de Pennelune.', },
  },
  [2871] = {
    'Livraison de la relique',
    {'Si vous aviez l\'amabilité de porter la relique à ma femme Vestia, je vous en serais très reconnaissant. Elle n\'est pas seulement une excellente prêtresse, elle fait également partie des meilleurs érudits que vous puissiez trouver. Je n\'arrive pas à comprendre l\'usage de cet objet. Si quelqu\'un peut le savoir, c\'est ma femme... et nous avons besoin de savoir de quoi il s\'agit !|n|nElle est juste derrière le virage, sûrement en train d\'étudier. Merci, $N.', },
    {'Porter la Relique mystérieuse à Vestia Lancelune au bastion de Pennelune.', },
  },
  [2872] = {
    'Les dettes de Stoley',
    {'Mon vieux copain Stoley me doit une bouteille d\'un rhum très spécial. Il tient un bar à Port Gentepression en Tanaris. C\'est en Kalimdor. Il soutient que ce rhum est plus fort que tout ce que l\'on peut trouver à Baie-du-Butin. Il y croit dur comme fer. À tel point que si je ne suis pas de son avis après avoir goûté cet alcool, je double ce qu\'il me doit !|n|nJe pense que depuis la dernière fois, il a perdu confiance, car il ne m\'a toujours pas envoyé son fameux rhum à goûter. Un pari est un pari, je ne reviendrai pas dessus. Pourquoi n\'iriez-vous pas lui parler un peu ?', },
    {'Parler à Stoley, à Port Gentepression.', },
  },
  [2873] = {
    'Cargaison de Stoley',
    {'Je dois du rhum à MacKinley "Loup des mers" pour payer une dette de jeu, mais je n\'en ai plus ! Le capitaine Cuergo a volé ma dernière caisse et il l\'a entreposée dans cette ville de pirates fortifiée, au sud.|n|nSi vous pouviez rapatrier ma cargaison de rhum, alors je pourrais prouver à MacKinley que la gnôle de Kalimdor est autrement plus musclée que le petit-lait qu\'ils boivent à Baie-du-Butin.', },
    {'Apportez la Cargaison de Stoley à Port Gentepression et remettez-la à Stoley.', },
  },
  [2874] = {
    'Livraison à MacKinley',
    {'Merci encore pour votre aide, $N. Voici une bouteille de rhum de cale Gentepression. Portez-la à MacKinley et il pourra remballer ses préjugés à propos des alcools de Baie-du-Butin.', },
    {'Apportez la Bouteille de Stoley à MacKinley « Loup des mers » à Baie-du-Butin.', },
  },
  [2875] = {
    'ON RECHERCHE : André Barbe-en-feu',
    {'L\'ignoble pirate André Barbe-en-feu est recherché pour crimes contre Gentepression et Gadgetzan.|n|nPar décret du conseil gouvernemental, toute personne lisant ce texte est autorisée à utiliser la force, et à tuer si nécessaire, pour procéder à l\'arrestation d\'André et de ses complices.|n|nSi André était décédé ou indisposé pendant son interrogatoire, un autre décret précise que sa tête servira de preuve. La présentation de ladite tête au Chef de la sécurité Vizisanie constitue un contrat valable et inaliénable.', },
    {'Rapportez la tête d\'André au Chef de la sécurité Vizisanie, à Port Gentepression.', },
  },
  [2876] = {
    'Horaires des bateaux',
    {'Ce parchemin détaille le calendrier des livraisons entre Port Gentepression et Baie-du-Butin. La liste contient le nom des navires et des dates, passées ou à venir. Certaines lignes sont cochées d\'un grand X. D\'autres sont annotées avec "Bon butin" ou "Dur combat".|n|nQuelqu\'un à Port Gentepression apprécierait certainement de voir ce document.', },
    {'Présenter les Horaires des bateaux aux autorités de Port Gentepression.', },
  },
  [2877] = {
    'Nettoyer le rocher de l\'Affût',
    {'Nous, les Marteaux-Hardis, nous souvenons du passé, mieux que nos frères de Forgefer. Si vous désirez vous faire des amis, alors travaillez pour nous !|n|nLa Horde a abandonné ses positions dans les Hinterlands, autour du rocher de l\'Affût qui est maintenant envahi par des vases et des limons. Nous avons des plans pour ce secteur, mais nous avons besoin de quelqu\'un pour faire du nettoyage.|n|nC\'est là que vous intervenez ! Allez là-bas et liquidez dix vases vertes et dix limons de jade puis revenez me faire votre rapport ici. Exécution !', },
    {'Tuer 10 Vases vertes et 10 Limons de jade puis faire votre rapport à Fraggar Tonnemante au Nid-de-l\'Aigle.', },
  },
  [2878] = {
    'Fleur-de-chant corrompue',
    nil,
    nil,
  },
  [2879] = {
    'Le Bâton d\'Equinex',
    {'Il semble que ce bâton soit le Bâton d\'Equinex. C\'est en fait une clé qui permet d\'ouvrir le Monolithe d\'Equinex érigé dans les ruines de Vent-du-Corbeau, sur le continent, à l\'ouest du Bosquet du rêve.|n|nLocalisez les quatre flammes qui brûlent toujours dans les ruines: Samha, Imbel, Byltan et Lahassa. Là, retrouvez leur essence, et tout en vous tenant près du Monolithe, utilisez les essences pour dynamiser le bâton. S\'il s\'agit bien du Bâton d\'Equinex, vous pourrez alors ouvrir le Monolithe et prendre l\'artéfact sacré qui s\'y trouve.', },
    {'Dynamiser le Bâton de Troyas et trouver le Monolithe d\'Equinex.', },
  },
  [2880] = {
    'Chasse au collier troll',
    {'Comprenez bien ceci, $R. Nous ne faisons PAS partie de l\'Alliance ! Les Marteaux-hardis sont indépendants, ils prouvent leur valeur par l\'action et leurs actes et non en bavardant, contrairement à ceux qui parlent afin de camoufler leur passivité !|n|nSi vous cherchez des amis par ici, commencez par prouver votre valeur ! Ces idiots de trolls qui remplissent les Hinterlands portent parfois des colliers tribaux. Rapportez-en cinq et nous considérerons que vous avez fait un pas dans la bonne direction.', },
    {'Rapporter 5 Colliers tribaux trolls à Fraggar Tonnemante au Nid-de-l\'Aigle.', },
  },
  [2881] = {
    'Chasse au collier troll',
    nil,
    nil,
  },
  [2882] = {
    'Or de Cuergo',
    {'Cette carte montre une plage orientée au sud. Sous la carte, des mots élégamment tracés…|n|nAu sud de Gentepression, avec raison|n|nAu sud de la maison|nTrouvez un drapeau, un mât et des os|nCreusez ici, si vous l\'osez|nCreusez et gagnez l\'or de Cuergo !|nUne clé il faut et une clé vous verrez|nLes hommes d\'en face il faudra tuer.', },
    {'Trouvez l\'or de Cuergo !', },
  },
  [2902] = {
    'Enquête chez les Griffebois',
    {'Les gnolls ne sont pas des lumières, mais ils ont certainement des documents concernant leurs récents agissements. Si nous trouvions des plans, alors nous aurions une meilleure idée de ce qui les motive.|n|nJe veux que vous retourniez chez les Griffebois et que vous rapportiez tout ce qui ressemble à un plan de bataille. Ils doivent avoir quelque chose, leurs attaques sont trop coordonnées. Trouvez les plans de bataille et rapportez-les-moi.', },
    {'Trouver les Plans de bataille des gnolls dans les camps gnolls du sud du Camp Mojache.', },
  },
  [2903] = {
    'Les plans de bataille',
    {'Une fois trouvés les plans des gnolls, il reste à les porter à Hadoken Rôdeur-agile au Camp Mojache. Peut-être comprendra-t-il les projets des gnolls…', },
    {'Apportez les Plans de bataille des Griffebois à Hadoken Rôdeur-agile au Camp Mojache.', },
  },
  [2904] = {
    'Une jolie pagaille',
    {'<Kernobee grogne.>Qu… Que s\'est-il passé ?|n|nLa dernière chose dont je me souviens est d\'avoir été capturé par un groupe de nains sombrefers, d\'avoir été battu comme plâtre et jeté ici avec ces troggs crasseux.|n|nSortez-moi de là, $N !|n|nVoici le plan : vous me conduisez à la sortie, si nous survivons, vous allez à Baie-du-Butin prévenir Scooty que je suis allé à Cabestan pour informer Brikol\'as de l\'implication des Sombrefers dans la conception de cette super plateforme.|n|nAllons-y !', },
    {'Escorter Kernobee jusqu\'à la sortie de la Fuite du temps, puis faire un rapport à Scooty, à Baie-du-Butin.', },
  },
  [2922] = {
    'Sauver le cerveau de Techbot !',
    {'Lorsque notre cité bien-aimée de Gnomeregan est tombée, une étincelle a fait disjoncter ma pauvre création, le Techbot. Il nous aidait bien, moi et mes associés, avec ses nombreux gadgets et ses banques d\'informations illimitées, mais son cerveau positronique a été polarisé. Techbot est maintenant négatronique et son comportement s\'est inversé. Il erre, enragé, dans Gnomeregan !|n|nMais peut-être peut-il être sauvé. Si vous retrouviez sa mémoire principale et me la rapportiez, je pourrais découvrir la cause de la polarisation et réparer mon pauvre Techbot.|n|n', },
    {'Rapportez la Mémoire principale de Techbot au maître-artisan Suprétincelle à Forgefer.', },
  },
  [2923] = {
    'Maître-bricoleur Suprétincelle',
    {'Le maître-artisan Suprétincelle est très contrarié par la perte de sa création mécanique, le Techbot. Je me souviens du Techbot comme d\'une machine gentille et serviable, très utile aux gnomes, mais Suprétincelle dit qu\'il a eu des problèmes de fonctionnement.|n|nVraiment dommage, mais avec de la chance, cela pourrait être réparé !|n|nParlez avec maître Suprétincelle, à Brikabrok, le quartier gnome de Forgefer. Votre aide sera la bienvenue.', },
    {'Parler au maître-artisan Suprétincelle à Forgefer.', },
  },
  [2924] = {
    'Les cerveaux mécaniques',
    {'Un composant pratiquement universel, le cerveau mécanique, est d\'une grande utilité pour les artisans et les forgerons de Gnomeregan. Mais durant notre exode, personne n\'a pensé à en emporter ! Et j\'en ai besoin d\'un grand nombre pour le travail que je vais bientôt accomplir.|n|nS\'il vous plaît, allez à Gnomeregan et rapportez-en. Vous les trouverez dans les profondeurs de notre cité, dans des conteneurs appelés des extrapolateurs artificiels.|n|nMerci, $N et dépêchez-vous !', },
    {'Rapporter 12 Cerveaux mécaniques à Pléthorloge Cléventail à Forgefer.', },
  },
  [2925] = {
    'Les cerveaux mécaniques de Pléthorloge',
    {'Un ami gnome, Pléthorloge Cléventail, m\'a écrit depuis Forgefer. Il me dit qu\'il a besoin d\'aide pour une mission dangereuse, mais vitale à Gnomeregan, l\'ancienne et puissante cité gnome, aujourd\'hui contaminée et envahie de gnomes fous et de leurs inventions.|n|nJe dois rester ici, mais je dois aider mon ami. Si vous pouviez y aller à ma place, je serais votre débiteur.|n|nVous pouvez trouver Pléthorloge à Brikabrok, le quartier gnome de Forgefer.', },
    {'Parler à Pléthorloge Cléventail à Forgefer.', },
  },
  [2926] = {
    nil,
    {'Depuis l\'accident, Gnoarn discute et palabre sur le fait de nettoyer Gnomeregan de l\'infestation des troggs et de trouver un remède à la maladie, $N.|n|nPar chance, Esbrouf et moi sommes près de trouver quelque chose, un remède ou une recette de rhum particulièrement corsée, nous ne sommes pas sûrs… Nous le saurons après les tests ! Nous avons bien évidemment besoin de quelques ingrédients pour tester notre produit, notamment des retombées radioactives collectées sur des troggs irradiés de Gnomeregan. Remplissez cette flasque avec la Lueur verte et rapportez-la.', },
    {'Utiliser la Flasque de collecte plombée vide sur les Envahisseurs ou les Pilleurs irradiés pour recueillir des retombées radioactives. Une fois pleine, rapportez-la à Ozzie Virevolt à Kharanos.', },
  },
  [2927] = {
    'Le jour d\'après',
    {'Vous ne pensiez quand même pas que j\'ai toujours été chauve ? Non $Gm\'sieur:m\'dame; ! C\'est la fuite radioactive à Gnomeregan qui a causé cette tragique perte de cheveux. Avant cela, j\'avais la seule coiffure afrognome de tout Azeroth.|n|n<Gnoarn brandit le poing vers le ciel.>|n|nMaudits soient ces troggs crasseux, qu\'ils soient tous maudits !|n|nPeut-être qu\'il n\'est pas trop tard, $N. Nous pouvons peut-être encore la sauver, je parle de la ville ! Allez voir Ozzie Virevolt à Kharanos. Lui et Esbrouf, son partenaire, travaillent à résoudre ce problème.', },
    {'Parler à Ozzie Virevolt à Kharanos, en Dun Morogh.', },
  },
  [2928] = {
    'Excavateurs gyrodrilmatiques',
    {'C\'est affreux, $N. Nous n\'avons pas suffisamment de pièces détachées pour envoyer notre flotte d\'excavateurs gyrodrilmatiques en Dun Morogh.|n|nNous avons besoin de ces pièces, $N. Le meilleur endroit pour en trouver est Gnomeregan, et j\'ai entendu dire que les bots et les mechs grouillaient là-bas comme les puces sur le dos d\'un chien.|n|nVous devez aller à Gnomeregan et mettre en pièces quelques robots. Rapportez-moi des entrailles mécaniques. Deux douzaines devraient suffire.', },
    {'Apportez 24 Entrailles mécaniques de robot à Shoni, à Hurlevent.', },
  },
  [2929] = {
    'La grande trahison',
    {'J\'avais confiance en Thermojoncteur, $R. Je ne pensais pas qu\'il me trahirait, moi et tout le peuple gnome. Et pourquoi ? La puissance ? L\'argent ? Il les aurait eus de toute façon. Maintenant nous avons été jetés hors de notre pays et ce malade est à sa tête. Le roi du vide...|n|nNous reprendrons Gnomeregan, $N. Nous n\'arrêterons pas tant que la ville ne sera pas nôtre à nouveau. Si vous désirez vous joindre à nous, j\'ai une mission simple à vous confier : tuer le traître. Détruisez le mekgénieur Thermojoncteur.', },
    {'Aller à Gnomeregan et tuer le mekgénieur Thermojoncteur. Puis retourner voir le Grand Bricoleur Mekkanivelle.', },
  },
  [2930] = {
    'Sauvetage de données',
    {'Quand nous avons fui Gnomeregan, nous avons dû abandonner tant de données importantes !|n|nJ\'ai besoin des données de la carte perforée prismatique d\'une Matrice d\'encodage 3005-D, dans Gnomeregan. C\'est votre destination ; mais pour cela, vous devez d\'abord accéder aux terminaux de modèles -A, -B et -C. Et ceci n\'est possible qu\'avec les cartes prismatiques, en commençant par les blanches... Et nous avons laissé toutes nos cartes dans la ville.|n|nPouvez-vous nous aider ?', },
    {'Apporter une Carte perforée prismatique au Maître mécanicien Fontuyau, à Forgefer.', },
  },
  [2931] = {
    'Du travail pour Fontuyau',
    {'Le maître-mécanicien Fontuyau à Forgefer a besoin d\'aventuriers ! Il organise des groupes pour pénétrer à nouveau dans Gnomeregan afin d\'effectuer une mission de récupération de première importance.|n|nIl se peut que Fontuyau ne soit pas membre des grandes Assemblées d\'arcanologie, d\'alchimie ou de sciences d\'ingénieries comme je le suis, mais il reste un gnome intelligent. S\'il considère que c\'est important, alors mes calculs indiquent qu\'il y a quatre-vingts pour cent de chances que ce soit véritablement important !|n|nIl s\'agit là des probabilités les plus optimistes en ce qui nous concerne !', },
    {'Parler au Maître mécanicien Fontuyau, à Forgefer.', },
  },
  [2932] = {
    'Sinistre message',
    {'Les trolls fanécorces étaient jadis des alliés de la Horde, mais ils ont trahi Thrall... ce qui ne peut être toléré !|n|nVoici, prenez ma pique et allez dans les Hinterlands, loin au nord. Vous trouverez l\'endroit en question au nord-est du Moulin-de-Tarren, un village tenu par nos alliés, les Réprouvés.|n|nQuand vous entrerez sur les terres des Hinterlands, chassez les trolls fanécorces. Collectez leurs crânes, puis plantez ma pique dans le sol de l\'un de leurs petits villages, Hiri\'watha ou Zun\'watha.|n|nMontrez-leur que tout se paie en ce bas monde !', },
    {'Collectez des Crânes de Fanécorce et placez-les sur la Pique de Nimboya. Posez la Pique de Nimboya préparée dans l\'un des villages des Fanécorces, dans les Hinterlands, puis retournez voir Nimboya, à Strangleronce.', },
  },
  [2933] = {
    'Bouteilles de venin',
    {'Ces bouteilles contiennent un terrible venin.|n|nVu le nombre de bouteilles dans ce village, les Fanécorces doivent projeter quelque chose d\'important avec elles ; peut-être qu\'un apothicaire de la ville toute proche de Moulin-de-Tarren serait intéressé par l\'étude d\'un échantillon.', },
    {'Apporter une Bouteille de venin à un apothicaire, à Moulin-de-Tarren.', },
  },
  [2934] = {
    'Glande à venin intacte',
    {'Il me faut un échantillon frais du venin que vous m\'avez apporté. Les araignées dont il provient hantent les Hinterlands. Chassez-les jusqu\'à ce que vous trouviez une glande à venin intacte, puis rapportez-la-moi. Vous trouverez beaucoup d\'araignées près de la ville trolle de Shadra\'Alor.|n|nNe tardez pas, $N, la glande à venin doit être fraîche lorsque vous l\'apporterez.', },
    {'Rapporter une Glande à venin intacte à l\'Apothicaire Lydon, à Moulin-de-Tarren.', },
  },
  [2935] = {
    'Consulter Maître Gadrin',
    {'Le venin des gardes du clan n\'était pas le même que celui que vous m\'avez rapporté. Ils proviennent sans doute d\'une araignée différente.|n|nJe veux un échantillon de venin frais. Pour savoir où en trouver, vous devez consulter un troll qui connaît bien les Fanécorces : maître Gadrin, au village de Sen\'jin. Allez en Durotar et parlez à Gadrin. Avec un peu de chance, il saura de quelle araignée les Fanécorces tirent leur venin.', },
    {'Parler à Maître Gadrin au village de Sen\'jin.', },
  },
  [2936] = {
    'Le dieu-araignée',
    {'Les Fanécorces adorent un dieu-araignée dont ils obtiennent ce venin extrêmement toxique. Ainsi, si vous voulez en collecter un peu, il vous faudra invoquer leur dieu !|n|nPour réussir l\'invocation, vous devez connaître le vrai nom de cette divinité. Il est écrit sur une tablette, enterrée à Tanaris, dans la cité trolle de Zul\'Farrak. Dans une tombe gardée par Theka le Martyr, pour être plus exact.|n|nTuez Theka, trouvez et lisez la tablette pour connaître le véritable nom du dieu-araignée, puis revenez me voir.', },
    {'Lire la Tablette de Theka pour connaître le véritable nom du dieu-araignée des Fanécorces, puis retourner voir Maître Gadrin.', },
  },
  [2937] = {
    'L\'invocation de Shadra',
    {'Prenez ce parchemin et lisez-le devant l\'autel de Shadra\'Alor, loin à l\'intérieur des terres des Fanécorces, dans les Hinterlands. Shadra, le dieu-araignée, sera invoqué et paraîtra.', },
    {'Terrasser Shadra, à l\'autel de Shadra\'Alor, puis rapporter son venin à l\'Apothicaire Lydon, à Moulin-de-Tarren.', },
  },
  [2938] = {
    'Du venin pour Fossoyeuse',
    {'Le venin que vous avez récupéré sur le dieu araignée des Fanécorces est une grande découverte ! J\'ai pu tuer près de deux douzaines de lapins avec une seule goutte. Il est juste que certains de ces lapins étaient très jeunes et suffisamment petits pour tenir dans la paume de la main. Leur résistance aux toxines devait être très basse. Néanmoins, il s\'agit là d\'un puissant poison !|n|nJ\'aimerais en envoyer un échantillon à mon supérieur, l\'apothicaire Faranell à l\'Apothicarium de Fossoyeuse. Il ne fait aucun doute qu\'il aimerait conduire ses propres expériences.', },
    {'Apporter le Colis de Faranell au maître apothicaire Faranell, à Fossoyeuse.', },
  },
  [2939] = {
    'En savoir plus',
    {'Bien que les ruines de Féralas puissent être très dangereuses, elles ont beaucoup à raconter sur ce qui s\'est passé ici.|n|nIl y a quelques jours, tandis que je fouillais les décombres, j\'ai découvert ce qui semble être une douve classique. Je ne peux cependant pas me défaire de l\'idée que cela cache quelque chose... Angelas et moi avons fait des recherches dans nos livres, mais nous n\'avons rien découvert la concernant.|n|nJe connais une collègue à Darnassus qui pourrait peut-être nous dire de quoi il s\'agit, $N. Pourquoi n\'iriez-vous pas lui parler et voir si elle peut nous aider ?', },
    {'Parler à Daryn Calmevent, au village de Rut\'theran.', },
  },
  [2940] = {
    'Féralas : une histoire',
    {'Ce livre a l\'air de ne pas avoir été ouvert depuis des années. Sa couverture est passée et ses pages jaunies ; mais en l\'examinant de plus près, vous remarquez que c\'est exactement ce que Troyas devait rechercher.|n|nVous le prenez, puis réalisez que vous devriez d\'abord demander la permission avant de l\'emprunter.', },
    {'Demander à Daryn Calmevent si vous pouvez emprunter son livre.', },
  },
  [2941] = {
    'Le prêt',
    {'J\'ai étudié beaucoup de thèmes et de sujets, et ma dernière étude porte sur les gueules d\'acier qui vivent sur les plages, dans les Hinterlands. Il y a un spécimen en particulier que j\'aimerais voir, une gueule d\'acier géante nommée Gammerita. Mes recherches me retiennent ici, hélas. Je pense qu\'une image de la bête suffirait à son étude.|n|nPortez cette lettre à Gruzouille Sautelevier, à Tanaris. Elle a inventé une machine qui prend des images. Elle appelle cela : "photographie", je crois...', },
    {'Apporter la lettre à Gruzouille Sautelevier, à Tanaris.', },
  },
  [2942] = {
    'La Pierre du matin',
    {'Lorsque vous retirez l\'artéfact du Monolithe, vous sentez que l\'énergie du Bâton d\'Equinex commence à décliner.', },
    {'Rapporter la Pierre étincelante et le Bâton d\'Equinex à Troyas Lunebise, dans le bastion de Pennelune.', },
  },
  [2943] = {
    'Retourner voir Troyas',
    {'Voilà, $N. Je vous en prie, prenez soin de mon livre.|n|nPartez, à présent. Je suis sûre que Troyas attend votre retour avec impatience.', },
    {'Apporter le livre à Troyas Lunebise, dans le bastion de Pennelune.', },
  },
  [2944] = {
    'Le Preneur d\'images FX',
    {'Regardez ma dernière invention, $N. Tout ce que vous avez à faire, c\'est viser ce dont vous voulez une image puis d\'appuyer sur ce bouton.|n|nQuelle était la créature des Hinterlands que vous avez mentionnée ? Gammerita ? Eh bien, bonne chance pour la trouver. Je suis sûre que Daryn sera contente du cliché que vous lui en ferez.|n|nVoici le Preneur d\'images FX, faites-en bon usage et amusez-vous bien !', },
    {'Utiliser le Preneur d\'images FX pour prendre un cliché de Gammerita, puis retourner voir Daryn Calmevent à Rut\'theran.', },
  },
  [2945] = {
    'Anneau sali',
    {'Vous avez découvert, sur le corps d\'un des nains sombrefers, ce qui semble être un anneau. La crasse le recouvre entièrement, rendant difficile son identification et impossible son port. Il vous semble pouvoir discerner, sous les résidus, comme le chatoiement d\'un métal précieux et l\'éclat d\'une gemme.|n|nSi vous voulez utiliser cet anneau, il vous faudra trouver un moyen de nettoyer la saleté qui le souille.', },
    {'Trouver un moyen de nettoyer l\'Anneau sali.', },
  },
  [2946] = {
    'Questions sans réponses',
    {'Nous voulons que vous portiez les disques que vous avez trouvés, aux portes scellées d\'Uldum. Nous... ne sommes pas sûrs de ce qui va se passer quand vous ferez cela.|n|nCela pourrait être risqué, aussi bien que parfaitement inefficace. Vous devrez utiliser les disques, d\'une manière ou d\'une autre... Peut-être les portes s\'ouvriront-elles toutes seules à l\'approche des disques... allez savoir. Essayez ce qui vous semblera bon et attendez-vous à tout.|n|nRevenez ensuite à Forgefer. Du travail nous attend !', },
    {'Apportez les Disques de platine miniatures aux Portes d\'Uldum, à Tanaris, et cherchez les indices de la connexion qui existe entre eux.', },
  },
  [2947] = {
    'Le retour de l\'anneau',
    {'En ouvrant la boîte, vous trouvez ce à quoi vous vous attendiez : un anneau scintillant, comme flambant neuf ! Dès que vous l\'enfilez, vous sentez une vague de puissance magique traverser votre corps.|n|nDans la face intérieure de l\'anneau, vous voyez le poinçon de Forgefer, accompagné de trois petites initiales gravées : "TdK". Ce peuvent être celles du précédent propriétaire de l\'anneau ou celles de son artisan. Garder l\'anneau... ou le rendre à cette personne. Difficile décision, en vérité...', },
    {'Vous pouvez soit garder l\'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l\'intérieur.', },
  },
  [2948] = {
    'Amélioration gnomique',
    {'Écoutez, $N, cet anneau vous appartient... mais je peux l\'améliorer ! Comme je vous l\'ai déjà dit, sa forme est très simple, et j\'ai beaucoup progressé depuis. Pour la modique somme de trente pièces d\'argent, je lui donnerai de nouveaux atours... bon, un peu plus de trente pièces, car je suis un peu gêné financièrement, en ce moment.|n|nTous mes stocks de matériaux sont épuisés ; si vous m\'apportez une barre d\'argent et une agate mousse, je pourrai ajouter un treillis d\'argent et d\'agate qui donnera à cet anneau un sacré coup de fouet !|n|nFaites-moi confiance !', },
    {'Apportez l\'Anneau d\'or brillant, une Barre d\'argent, une Agate mousse et 30 pièces d\'argent à Talvash del Kissel, à Forgefer.', },
  },
  [2949] = {
    'Le retour de l\'anneau',
    {'En ouvrant la boîte produite par le Brille-o-Matic 5200, vous découvrez un anneau scintillant. Quand vous le passez à votre doigt, vous sentez une incroyable vague de puissance magique traverser votre corps.|n|nDans la face intérieure de l\'anneau, vous pouvez voir le petit poinçon d\'Orgrimmar à côté duquel les trois premières lettres gravées d\'un mot sont visibles : « NOG... »|n|nCe sont peut-être les initiales de l\'ancien propriétaire de l\'anneau ou de son fabricant. Garder l\'anneau... ou retrouver « NOG » - difficile décision, en vérité...', },
    {'Vous pouvez soit garder l\'anneau, soit retrouver la personne désignée par les lettres qui sont gravées à l\'intérieur.', },
  },
  [2950] = {
    'Nogg améliore l\'anneau',
    {'Non, non, non, je ne suis pas en train de dire que cet anneau est à moi. Cependant, votre information sur les Sombrefers fut très utile. J\'améliorerai cet anneau pour vous, bien mieux que ne le pourrait celui qui a forgé cette pauvre petite chose... sans doute un gnome, d\'ailleurs...|n|nSi vous m\'apportez une barre d\'argent, une agate mousse et trente pièces d\'argent, je pourrai ajouter un treillis d\'argent et d\'agate qui donnera une ampleur toute nouvelle à la magie contenue dans cet anneau. Cela vous intéresse ?', },
    {'Apportez l\'Anneau d\'or brillant, une Barre d\'argent, une Agate mousse et 30 pièces d\'argent à Nogg, à Orgrimmar.', },
  },
  [2951] = {
    'Le Brille-o-Matic 5200 !',
    {'L\'étrange objet est là, au milieu des gnomes. Une petite plaque sur la machine indique : « Brille-o-Matic 5200 », suivi d\'un texte :|n|n« La crasse et les résidus ruinent vos objets ? Le Brille-o-Matic 5200 est l\'outil qu\'il vous faut pour restaurer toute la brillance et l\'éclat qu\'ils méritent. Veuillez placer l\'objet à décaper dans la machine, ainsi que trois pièces d\'argent dans la fente prévue à cet effet et attendez un petit moment : vos objets de valeur en sortiront comme neufs ! »', },
    {'Insérer un Objet sali dans le Brille-o-Matic 5200, sans oublier de jeter trois pièces d\'argent dans la fente, pour démarrer la machine.', },
  },
  [2952] = {
    'Le Brille-o-Matic 5200 !',
    nil,
    nil,
  },
  [2953] = {
    'Le Brille-o-Matic décape encore',
    nil,
    nil,
  },
  [2954] = {
    'Le Gardien des pierres',
    {'« Bonjour, je garde l\'entrée. Si vous n\'avez pas les Plaques d\'Uldum intégrées à votre jeu de disques je ne vous laisserai pas entrer dans le complexe d\'Uldum. »|n|nL\'apparition du Gardien des pierres de Norgannon est la réaction qui était espérée en vous envoyant dans le Désert de Tanaris avec les disques de platine. Vous devez maintenant découvrir l\'histoire du Gardien des pierres avant de continuer.', },
    {'Apprendre le but du Gardien des pierres de Norgannon, puis interagir avec le Piédestal d\'Uldum, dans le désert de Tanaris.', },
  },
  [2962] = {
    'Encore plus de Lueur verte !',
    {'Votre échantillon n\'était pas seulement insuffisant, mais impur.|n|nNous avons besoin de plus de Lueur verte. Les troggs ne sont apparemment pas encore assez irradiés. Vous devrez aller à Gnomeregan et rapporter de la matière radioactive, prélevée à la source. Je parle bien sûr de toutes ces gelées, rôdeurs et autres horreurs irradiées qui errent là-bas. Attention, la collecte et le conditionnement de telles matières est difficile ; il vous faudra faire plusieurs tentatives avant qu\'un échantillon valable soit prélevé.', },
    {'Voyager à Gnomeregan et rapporter de la Matière radioactive à haut potentiel. Attention, la matière radioactive est instable et se désactive rapidement.|n|nUne fois la tâche achevée, conserver la Flasque plombée lourde, pour Ozzie.', },
  },
  [2963] = {
    'Prodiges d\'Uldum',
    {'Ah, $N ! La nouvelle de votre découverte dans Uldaman a mis en joie la Ligue des explorateurs. La Ligue a beaucoup travaillé pour découvrir le secret des petits disques de platine que vous avez trouvés. Je puis vous dire que nous sommes au seuil de quelque chose d\'important !|n|nL\'historien Karnik a quelques hypothèses très intéressantes sur l\'origine de la vallée des Guetteurs dans le désert de Tanaris. Il voudrait vous parler dès que possible.', },
    {'Parler à l\'Historien Karnik dans le Hall des explorateurs, à Forgefer.', },
  },
  [2964] = {
    'Travail imminent',
    {'Bien, $N... Il semblerait que nous soyons dans l\'impasse. Nous avons besoin des Plaques d\'Uldum, mais nous ne savons pas où elles se trouvent. Nous devons réfléchir avant d\'avoir un plan pertinent. J\'ai bien quelques petites idées et j\'espère que nous vous enverrons bientôt pour les récupérer.|n|nLe Grand Explorateur doit être informé de tout cela, $N ; il est à parier qu\'il veut aussi vous remercier pour l\'aide que vous avez apportée à la Ligue.', },
    {'Parler au Grand Explorateur Magellas, à Forgefer.', },
  },
  [2965] = {
    'Prodiges d\'Uldum',
    {'Ah, $N, vous voilà de nouveau. Vos révélations quant au site de fouilles d\'Uldaman ont motivé bien des discussions parmi nous. J\'en parlais justement avec mon ami, le druide Nara Crin-sauvage et il m\'apparut que son expérience passée pouvait orienter la suite de notre action.|n|nAllez la voir et écoutez l\'histoire de ses voyages dans la vallée des Guetteurs du désert de Tanaris. Elle vous attend à la cime des Anciens.', },
    {'Aller à la Cime des Anciens, aux Pitons-du-Tonnerre et parler à Nara Crin-Sauvage.', },
  },
  [2966] = {
    'Questions sans réponses',
    {'Le Sage Recherche-la-Vérité et moi-même voulons que vous portiez les disques que vous avez découverts jusqu\'aux portes scellées d\'Uldum. Nous... ne sommes pas sûrs de ce qui va arriver quand vous serez là-bas.|n|nCela pourrait être risqué, aussi bien que parfaitement inefficace. Vous devrez utiliser les disques, d\'une manière ou d\'une autre... peut-être les portes s\'ouvriront-elles toutes seules à l\'approche des disques... allez savoir. Essayez ce qui vous semblera bon et attendez-vous à tout.|n|nApprenez ce que vous pourrez, puis revenez me voir ; nous aurons beaucoup à nous dire.', },
    {'Apportez les Disques de platine miniatures aux Portes d\'Uldum, à Tanaris, et cherchez les indices de la connexion qui existe entre eux.', },
  },
  [2967] = {
    'Le retour aux Pitons-du-Tonnerre',
    {'Vous accédez au socle, à nouveau ; les disques de platine réapparaissent une nouvelle fois dans votre sac à dos.|n|nAvec ce que vous avez appris du Gardien des pierres et les disques en votre possession, vous pouvez à présent retourner aux Pitons-du-Tonnerre et informer Nara Crin-sauvage de votre découverte.', },
    {'Parler à Nara Crin-Sauvage, aux Pitons-du-Tonnerre.', },
  },
  [2968] = {
    'Travail imminent',
    {'Bien, $N... Il semble que nous soyons dans l\'impasse. Nous avons besoin des Plaques d\'Uldum, mais nous ne savons pas où elles se trouvent. Nous devons faire des recherches à ce sujet. J\'ai bien quelques petites idées et j\'espère que vous irez bientôt les récupérer. Nous vous demanderons bientôt de vous joindre à nous pour découvrir la vérité.|n|nLe sage Recherche-la-Vérité doit être informé de cela, $N ; il voudra aussi vous remercier d\'avoir, une fois de plus, répondu à l\'appel.', },
    {'Parler au Sage Recherche-la-Vérité, aux Pitons-du-Tonnerre.', },
  },
  [2969] = {
    'Liberté pour toutes les créatures',
    {'L\'odieux clan du Totem-sinistre capture des dragons féeriques, $N. Jer\'kai et moi ne savons pas quels desseins ils poursuivent en faisant cela, mais ce n\'est certainement rien de bon.|n|nNous ne sommes pas assez puissantes pour combattre le Totem-sinistre dans son camp et libérer les dragons, mais peut-être qu\'avec votre aide...|n|nSi vous êtes d\'accord et avez quelques amis robustes qui voudraient se joindre à vous, allez libérer les créatures de leurs cages grâce à cette clé et assurez-vous qu\'elles restent en vie. Je serai à vos côtés tout le temps ; Jer\'kai, pour sa part, restera ici, au cas où...', },
    {'À l\'aide de la Clé de la cage en bambou, libérer les Fées fléchetteuses de l\'enclos dans le Camp du Totem-sinistre. Au moins 6 Fées fléchetteuses et Kindal Tisselune doivent survivre.|n|nVous avez 6 minutes avant que Kindal décide qu\'il est temps de battre en retraite et que vous échouiez dans votre quête.', },
  },
  [2970] = {
    'Justice de châtiment',
    {'Comme vous l\'a déjà dit Kindal, nous allons désormais combattre le clan du Totem-sinistre. Ensemble, nous devrions pouvoir affronter quelques taurens, mais nous apprécierions votre aide, si vous êtes d\'accord.|n|nVous avez vu l\'un des camps, en aval ; il y en a encore d\'autres à l\'est. Faites selon vos compétences et techniques mais infligez autant de dégâts possibles aux taurens. Quand ils auront goûté à la piqûre des flèches de Kindal et à vos propres armes, nous nous retrouverons $Gtous:toutes; ici, pour faire le point.', },
    {'Tuer 12 Naturalistes du Totem-sinistre, 10 Écumeurs du Totem-sinistre et 6 Chamans du Totem-sinistre avant de retourner voir Jer\'kai Tisselune, en Féralas.', },
  },
  [2972] = {
    'Justice de châtiment',
    {'Ici, dans les terres sauvages, Kindal et moi n\'avons pas grand-chose à vous offrir, mais nous voulons récompenser votre aide. Prenez ma chevalière. Si un jour vous êtes dans les environs de Teldrassil, allez au temple de la Lune au cœur de Darnassus. Là, vous trouverez ma Grande prêtresse Tyrande Murmevent. L\'anneau lui dira que nous allons bien et que votre histoire est vraie.|n|nNous vous remercions toutes les deux, $N.', },
    {'Apporter la Chevalière de Jer\'kai à la Grande prêtresse Tyrande Murmevent, à Darnassus.', },
  },
  [2973] = {
    'Une nouvelle cape',
    {'Ah, vous voici, $C. Lors d\'une mission pour nos maîtres d\'Orgrimmar, j\'ai voyagé loin en direction de Féralas.|n|nMon amie Korrin adore les vêtements, j\'ai donc l\'intention de lui confectionner une nouvelle cape ornée des ailes légères des créatures féeriques. M\'aiderez-vous ? Les Fées fléchetteuses aux ailes sublimes se trouvent à l\'ouest de Camp Mojache.', },
    {'Rapporter 10 Ailes iridescentes de Fées fléchetteuses à Krueg Casse-crâne au Camp Mojache.', },
  },
  [2974] = {
    'Une découverte sinistre',
    {'Quoi ! Vous avez rencontré des taurens dans le secteur ? Vous plaisantez ! À quoi ressemblaient-ils !?|n|nLe clan du Totem-sinistre ! Vous en avez vus ? Belgrom, l\'un de nos maîtres, s\'intéresse à eux… Il offre même une prime sur leur tête.|n|nVous devez repartir, $C. Retournez-y et apportez-moi leurs cornes. Des montagnes si vous pouvez. Ils ne doivent pas être traités à la légère ou sous-estimés. Retournez-y et massacrez-les. Que les rivières de Féralas rougissent de leur sombre sang.', },
    {'Apporter 20 Cornes de Totem-sinistre à Krueg Casse-crâne au Camp Mojache.', },
  },
  [2975] = {
    'Les ogres de Féralas',
    {'La tribu des ogres gordunni ne peut pas passer inaperçue, dans cette région. Regardez autour de vous : le pays est comme blessé par leur simple présence, $N. Nous devons les repousser avant qu\'ils ne se répandent plus avant en Féralas.|n|nSuivez la rivière au nord, vous tomberez sur leur avant-poste. Portez la mort et la désolation parmi eux, $N. Nous devons leur montrer à quel point nous les trouvons indésirables.', },
    {'Tuer 10 Ogres gordunni, 10 Ogre-magi gordunni et 5 Brutes gordunni pour Rok Orhan, du Camp Mojache.', },
  },
  [2976] = {
    'Une découverte sinistre',
    {'Comment ?|n|nAh, j\'ai parlé d\'une récompense, n\'est-ce pas ? Bon... ça m\'apprendra à ouvrir la bouche !|n|nVous avez fait le travail et je suppose que je vous dois ce que je vous avais promis. Prenez les cornes, je les ai mises dans une caisse pour vous. Portez-les à Belgrom Cogneroche, dans la Vallée de l\'Honneur. Il souhaite entendre votre rapport et vous récompenser.|n|nQue les vents vous portent, $C, et merci encore pour tout.', },
    {'Apportez la Caisse de Cornes de Totem-sinistre à Belgrom Cogneroche, Orgrimmar.', },
  },
  [2977] = {
    'Retour à Forgefer',
    {'Comme vous accédez de nouveau au socle, les disques de platine apparaissent une fois de plus dans votre sac à dos.|n|nAvec ce que vous avez appris du Gardien des pierres et les disques de nouveau en votre possession, vous pouvez maintenant retourner à Forgefer et informer la Ligue des explorateurs de votre découverte.', },
    {'Parler à l\'Historien Karnik, à Forgefer.', },
  },
  [2978] = {
    'Le parchemin gordunni',
    {'En ramassant le parchemin sali, vous remarquez qu\'ils représentent quelque cérémonie ou rassemblement. Rok Orhan aimerait sûrement jeter un œil sur ce parchemin et savoir quel est son rapport avec les Gordunni.', },
    {'Apportez le Parchemin gordunni à Rok Orhan, au Camp Mojache.', },
  },
  [2979] = {
    'Sombre cérémonie',
    {'On dirait bien des plans pour quelque sombre cérémonie, $N. D\'après ce que je vois, cette assemblée est tenue par les seigneurs-mages gordunni.|n|nTrouvez l\'un de ces seigneurs-mages et prenez-lui un orbe.|n|nL\'orbe d\'un mage contient une grande puissance et nous aidera à en savoir plus sur cette cérémonie secrète des Gordunni.', },
    {'Rok Orhan, du Camp Mojache, veut que vous trouviez un Orbe gordunni.', },
  },
  [2980] = {
    'Les ogres de Féralas',
    {'Vous avez prouvé que vous saviez vous battre et je sais que vous avez le courage de continuer la mission.|n|nAllez dans les plateaux Sauvages, au sud-ouest. Vous y verrez des structures détruites et abandonnées sur les terres qui, jadis, appartenaient aux elfes de la nuit. Dirigez-vous sur ces ruines, et quand vous traverserez des terres profanées aux arbres flétris, vous trouverez les Gordunni. Repoussez-les.|n|nCes ogres sont beaucoup plus forts et dangereux que ceux que vous avez précédemment combattus, $N. Soyez $Gprudent:prudente;.', },
    {'Tuez 10 Chamans gordunni, 10 Démonistes gordunni et 5 Marteleurs gordunni pour Rok Orhan, du Camp Mojache.', },
  },
  [2981] = {
    'Menace sur Féralas',
    {'Féralas est un lieu parfait pour faire ses preuves, $C. Une tribu d\'ogres appelée les Gordunni domine militairement l\'endroit et leur nombre, sans cesse, s\'accroît. Ils doivent être arrêtés avant de devenir une véritable menace pour Féralas.|n|nJe connais une certaine Rok Orhan qui habite au Camp Mojache, en Féralas ; allez la trouver, elle vous en dira plus sur la situation.', },
    {'Comme le veut Belgrom Cogneroche, aller parler à Rok Orhan, au Camp Mojache.', },
  },
  [2982] = {
    'Les plateaux Sauvages',
    {'Bien que ce soit risqué, Troyas et moi avons visité les ruines dans les forêts de Féralas.|n|nCes derniers temps, Troyas a pris l\'habitude de se rendre seul sur les plateaux Sauvages, et je m\'inquiète pour lui. Les ogres gordunni contrôlent la zone et ils ne traitent pas avec douceur ceux qui s\'aventurent dans leur domaine.|n|nAccepteriez-vous d\'aller dans les ruines, au sud-est, et de tuer quelques ogres afin de rendre la zone un peu plus sûre pour Troyas ? Je vous en remercie par avance.', },
    {'Tuer 8 Démonistes Gordunni, 8 Chamans Gordunni et 8 Brutes Gordunni pour Angelas Lunebise.', },
  },
  [2983] = {
    'L\'appel du feu',
    {'Cela fait quelque temps que vous n\'avez pas été $Gmis à l\'épreuve:mise à l\'épreuve;, $N. Vous avez fait preuve de patience dans vos études jusque-là, mais il est temps pour vous d\'apprendre de plus grands pouvoirs… il est temps d\'apprendre le réel pouvoir. L\'élément de feu vous appartient si vous êtes $Gprêt:prête; à payer pour cela.|n|nRecherchez Kranal Fiss dans les Tarides. Il réside dans une petite demeure au nord de la Croisée, mais faites attention ; si vous atteignez les terres de ces maudits elfes, c\'est que vous êtes $Gallé:allée; trop loin.', },
    {'Trouver Kranal Fiss dans les Tarides.', },
  },
  [2984] = {
    'L\'appel du feu',
    {'Cela fait longtemps que vous n\'avez pas été $Gmis à l\'épreuve:mise à l\'épreuve;, $N. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu d\'apprendre la destruction et le chaos. L\'élément du feu peut vous appartenir, si vous êtes $Gprêt:prête; à en payer le prix.|n|nRecherchez Kranal Fiss dans les Tarides. Il vit dans une petite demeure au nord de la Croisée, mais prenez garde. Si vous atteignez les terres des elfes de la nuit, c\'est que vous êtes $Gallé:allée; trop loin.', },
    {'Trouver Kranal Fiss dans les Tarides.', },
  },
  [2985] = {
    'L\'appel de l\'eau',
    {'Vous êtes capable d\'affronter la prochaine épreuve, $N. Vous avez su monter de la patience et avez progressé dans vos études, mais il est maintenant temps d\'apprendre plus encore et de connaître la pureté de l\'eau.|n|nCherchez Islen Oeil-des-rivières, dans les Tarides. Elle vit le long de la côte est, au sud du fleuve Furie-du-Sud et de Cabestan. Vous la trouverez dans sa cabane de pêcheur. Bonne chance, $N.', },
    {'Trouver Islen Oeil-des-rivières dans les Tarides.', },
  },
  [2986] = {
    'L\'appel de l\'eau',
    {'Cela fait longtemps que vous n\'avez pas été $Gmis à l\'épreuve:mise à l\'épreuve;, $N. Vous avez montré de la patience jusque-là dans vos études, mais le temps est à présent venu pour vous d\'apprendre la pureté de l\'eau.|n|nCherchez Islen Oeil-des-rivières dans les Tarides. Elle se trouve le long de la côte est, au sud du fleuve Furie-du-Sud et de Cabestan. Vous la trouverez dans une hutte de pêcheur. Bonne chance à vous, $N.', },
    {'Trouver Islen Oeil-des-rivières dans les Tarides.', },
  },
  [2987] = {
    'Cobalt gordunni',
    {'Je viens juste d\'arriver en Féralas et j\'ai appris que les ogres Gordunni qui y résident gardent d\'intéressants minéraux. Impossible de savoir ce qu\'ils projettent, mais ils protègent leurs stocks farouchement et les enterrent pour empêcher qu\'un fou comme moi ne mette la main dessus.|n|nSi vous êtes d\'accord, voici ma pelle : allez dans l\'avant-poste des Gordunni, plus au nord, et extrayez-moi un peu de cobalt gordunni. Cherchez la lueur bleue, puis commencez à creuser !', },
    {'Collecter 12 échantillons de Cobalt gordunni pour Orwin Azztuche, du Camp Mojache.', },
  },
  [2988] = {
    'Les cages des Fanécorces',
    {'Le fils de notre plus puissant griffon est parti ! L\'héritier d\'Aile-vive, Bec-tranchant, a été perdu tandis qu\'il chassait avec ses parents il y a quelques jours, et nous pensons que ce sont les trolls qui l\'ont enlevé.|n|nVous devez nous aider. Passez en revue les cages dans les deux villages de trolls fanécorces pour savoir si Bec-tranchant s\'y trouve.', },
    {'Inspectez les cages dans les deux villages des Fanécorces, puis retournez auprès du Maître des griffons Hachegriffe.', },
  },
  [2989] = {
    'L\'autel de Zul',
    {'Bec-tranchant ne se trouvait pas avec les trolls fanécorces. Peut-être les trolls du clan Vilebranche l\'ont-ils enlevé ? Partez pour l\'autel de Zul sur le bord ouest du territoire vilebranche et cherchez le jeune griffon.', },
    {'Regarder sur le dessus de l\'autel de Zul, puis retourner auprès du Maître des griffons Hachegriffe.', },
  },
  [2990] = {
    'Thadius Sinissombre',
    {'Apportez cette plume à Thadius Sinissombre, le devin. Il a quitté Nid-de-l\'Aigle il y a des années pour engranger un savoir plus sombre, mais dans son cœur il reste un Marteau-hardi !|n|nPeut-être que ses talents peuvent nous aider à retrouver Bec-tranchant.|n|nCette plume provient du nid où dormait le jeune griffon. Donnez-la à Thadius qui, avec un peu de chance, pourra utiliser ses talents divinatoires pour localiser Bec-tranchant.|n|nBonne chance, $N. Vous trouverez Thadius dans les terres Foudroyées, dans la tour des mages de Rempart-du-Néant.', },
    {'Apportez la Plume de Bec-tranchant à Thadius Sinissombre, dans les Terres Foudroyées.', },
  },
  [2991] = {
    'Médaillon de Nekrum',
    {'Si vous voulez que je localise votre griffon, vous devrez faire quelque chose pour moi. Il y a un troll dans Zul\'Farrak, Nekrum Mâchentrailles, qui possède un médaillon que j\'aimerais beaucoup étudier. Apportez-le-moi et j\'utiliserai mes pouvoirs pour retrouver Bec-tranchant.|n|nZul\'Farrak est de l\'autre côté de l\'océan, à l\'est, dans le désert de Tanaris.', },
    {'Apportez le Médaillon de Nekrum à Thadius Sinissombre, dans les Terres Foudroyées.', },
  },
  [2992] = {
    'La Divination',
    {'Laissez-moi un peu de place pour me permettre de pratiquer le rituel de divination. Je vais connecter la plume à son propriétaire, ce qui me donnera accès à Bec-tranchant lui-même.|n|nSi tout se déroule comme prévu, évidemment... Sinon, eh bien, vous feriez mieux de ne pas regarder.', },
    {'Attendre que Sinissombre ait fini de pratiquer son rituel de divination.', },
  },
  [2993] = {
    'Retour dans les Hinterlands',
    {'Bec-tranchant est enfermé dans une cage, placée haute sur une falaise au sommet de Jintha\'Alor dans les Hinterlands. La clé de cette cage est en possession de la grande prêtresse des trolls du clan Vilebranche, la vile prêtresse Maléficia.|n|nVoilà, j\'ai fait ma part. Je vous souhaite bonne chance dans votre quête, $N.', },
    {'Parler au Maître des griffons Hachegriffe.', },
  },
  [2994] = {
    'Sauver Bec-tranchant',
    {'Bec-tranchant doit être secouru !|n|nFrayez-vous un chemin, à coups d\'épée s\'il le faut, jusqu\'au sommet de Jintha\'Alor, au cœur du territoire des Vilebranches et arrachez la clé de la cage à la vile prêtresse Maléficia. Enfin, retrouvez et libérez Bec-tranchant !', },
    {'Combattre jusqu\'au sommet de Jintha\'Alor, tuer la vile prêtresse Maléficia pour obtenir la clé de la cage de Bec-tranchant, et sauver Bec-tranchant.', },
  },
  [2995] = {
    'Lignes de communication',
    {'Le gîte de Quel\'Danil est un centre de communication pour les elfes des Hinterlands. Leurs ambassadeurs essaient d\'entrer en contact avec les races partageant leur connaissance des trolls fanécorces, qui habitent dans le sud des Hinterlands. Tous les documents concernant les communications sont gardés dans le gîte.|n|nNous ne voulons pas que les gens du Haut-val tissent des alliances, $N.|n|nDétruisez les documents du Haut-val. Nous devons brûler leurs lignes de communication... au sens propre comme au sens figuré.', },
    {'Brûlez les Archives du Haut-val, le Rapport du Haut-val et les Notes du Haut-val.', },
  },
  [2996] = {
    'À la recherche de Strahad',
    {'Je vous ai beaucoup appris et maintenant je dois passer la main à un autre professeur. Il s\'appelle Strahad et habite à Cabestan. C\'est un humain, mais que cela ne vous incline pas à croire qu\'il est faible. Il est de petite taille, c\'est vrai, mais très puissant et pourra vous apprendre des invocations beaucoup plus importantes. Allez le voir maintenant. Vous le trouverez à Cabestan... à côté de la tour qui surplombe le port.', },
    {'Parlez à Strahad Farsan, à Cabestan.', },
  },
  [2997] = {
    'Tome de divinité',
    {'Bonjour, $N. Je sais que vous êtes très $Goccupé:occupée; à aider les gens de Dun Morogh, mais si vous avez le temps, allez jusqu\'à Forgefer pour parler à la vénérable Tiza Forgeguerre. Les plus jeunes de nos paladins vont la voir lorsqu\'ils veulent en apprendre plus sur la Lumière et sur ce que l\'on attend d\'eux.|n|nVous la trouverez à l\'étage du Hall des Mystères qui se trouve dans la Garde mystique. Bonne chance, $N.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [2998] = {
    'Tome de divinité',
    {'Salutations ! Duthorian Rall, l\'un de nos paladins les plus influents, parlait de vous récemment. Je l\'ai entendu dire qu\'il était temps que vous soyez $Gmis:mise; à l\'épreuve... Ainsi que des compliments vous concernant.|n|nJe vous conseille de vous rendre à Hurlevent et de lui parler. Je pense que vous le trouverez dans la cathédrale de la Lumière, où il passe le plus clair de son temps.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [2999] = {
    'Tome de divinité',
    {'Bonjour, $N. Je sais que vous êtes très $Goccupé:occupée; à aider les gens de Dun Morogh, mais si vous avez le temps, allez jusqu\'à Forgefer pour parler à la vénérable Tiza Forgeguerre. Les plus jeunes de nos paladins vont la voir lorsqu\'ils veulent en apprendre plus sur la Lumière et sur leurs obligations.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [3000] = {
    'Tome de divinité',
    {'Bonjour, $N. Je sais que vous êtes très $Goccupé:occupée; à aider les gens d\'Azeroth, mais si vous avez le temps, retournez à Forgefer et parlez à l\'une de nos paladins les plus respectés, Tiza Forgeguerre. Nos jeunes paladins nains vont la consulter quand ils veulent en apprendre plus au sujet de la Lumière et sur ce que l\'on attend d\'eux.|n|nVous la trouverez à l\'étage du Hall des Mystères qui se trouve dans la Garde mystique.', },
    {'Parlez à Tiza Forgeguerre, à Forgefer.', },
  },
  [3001] = {
    'À la recherche de Strahad',
    {'Je vous ai appris des sorts, mais l\'heure est venue pour d\'autres leçons que je ne puis plus prodiguer. Votre nouveau professeur habite à Cabestan ; il s\'appelle Strahad. C\'est un humain, mais ne vous fiez pas à cela : il n\'est ni faible ni hostile et ses pouvoirs sont grands. Il pourra vous enseigner les grandes invocations que vous avez maintenant les moyens d\'apprendre.|n|nVous le trouverez à Cabestan... à côté de la tour qui surplombe le port.', },
    {'Trouver Strahad Farsan, à Cabestan.', },
  },
  [3002] = {
    'L\'Orbe Gordunni',
    {'Je connais bien mon ennemi, $N, mais je ne suis qu\'un guerrier. Je ne peux pas vous dire à quoi peut servir cet orbe.|n|nMais je connais un mage à Orgrimmar qui saura nous en dire plus à ce sujet. Montrez-lui l\'objet.', },
    {'Apportez l\'Orbe Gordunni à Uthel\'nay, au pavillon de Buissombre, à Orgrimmar.', },
  },
  [3022] = {
    'À manipuler avec soin',
    {'$N, je vois que vous aspirez à embrasser ma louable cause. Bien entendu, vous pouvez faire quelque chose pour moi !|n|nApportez cette caisse d\'œufs à Erelas Ambreciel. Ce druide les met en couveuse puis entraîne les jeunes hippogriffes. Vous le trouverez dans Teldrassil, dans un petit village appelé Rut\'theran.', },
    {'Apportez la Caisse soigneusement empaquetée à Erelas Ambreciel, au village de Rut\'theran.', },
  },
  [3042] = {
    'Agent durcissant troll',
    {'Les trolls Furie-des-sables de Zul\'Farrak fabriquent un agent durcissant à partir du grès, que j\'utilise aussi pour tremper mes créations. Cette matière est très prisée, et si vous m\'en rapportez une bonne quantité, vous serez largement $Grétribué:rétribuée;.|n|nZul\'Farrak est au nord-ouest de Gadgetzan. Bonne chance.', },
    {'Apporter 20 Fioles d\'agent durcissant troll à Trenton Martelume, à Gadgetzan.', },
  },
  [3062] = {
    'Cœur noir',
    {'Edana Serrehaine est la reine des harpies ruissenord qui vivent dans les ruines à l\'ouest. Cette créature est le mal à l\'état brut ; il paraît que son cœur est de cristal froid, vide de toute émotion sauf de haine pure. Vous devez affronter Edana et me rapporter son cœur noir.|n|nJ\'ai entendu dire que les harpies portaient un cor ; s\'il est utilisé près des pierres de Serrehaine, dans la partie nord des ruines, la reine est invoquée.|n|nImaginez sa surprise quand elle se rendra compte que ce n\'est pas sa chère famille, mais la mort qui l\'a appelée.', },
    {'Rapporter le Cœur noir d\'Edana Serrehaine à Talo Sabot-de-ronce, au Camp Mojache.', },
  },
  [3063] = {
    'Se venger des Ruissenord',
    {'Jadis, j\'étais un chasseur de renom et ne craignais aucune espèce de créature. Jusqu\'à ce que...|n|nUn jour que j\'aiguisais mon épée dans la forêt, après une rude bataille, des harpies m\'ont encerclé et attaqué. Je ne sais comment je réussis à en sortir vivant.|n|nEncore maintenant, je peux entendre leurs affreux cris de crécelle...|n|nDepuis cette embuscade, je ne suis plus le même tauren ; j\'ai peur et mon âme est emplie de haine.|n|nLes harpies ruissenord vivent à l\'ouest. $N, soyez le bras armé de ma colère, vengez-moi !', },
    {'Tuer 4 Harpies ruissenord, 4 Volplumes ruissenord, 4 Imploratrices célestes ruissenord et 4 Pourfendeuses ruissenord pour Talo Sabot-de-ronce.', },
  },
  [3064] = {
    nil,
    {'J\'ai besoin de chapeaux de pirate ; rapportez-m\'en beaucoup !', },
    {'Apporter 20 Chapeaux de pirate à Yorba Fermevanne.', },
  },
  [3065] = {
    'Tablette simple',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des guerriers Frang. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu. Vous le trouverez à l\'extérieur de l\'Antre, dissimulé dans l\'ombre.', },
    {'Lire la Tablette simple, et parler à Frang, dans la Vallée des Épreuves.', },
  },
  [3082] = {
    'Tablette gravée',
    {'Ah, pendant votre absence, on a apporté une tablette pour vous, $N.|n|nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chasseurs, Jen\'shan. Elle souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Parler à Jen\'shan dans la Vallée des Épreuves.', },
  },
  [3083] = {
    'Tablette codée',
    {'Ah, pendant votre absence, on a apporté une tablette pour vous, $N.|n|nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des voleurs, Rwag. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lire la Tablette codée, et parler à Rwag, dans la Vallée des Épreuves.', },
  },
  [3084] = {
    'Tablette runique',
    {'Ah, pendant votre absence, on a apporté une tablette pour vous, $N.|n|nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des chamans, Shikrik. Elle souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Parlez à Shikrik dans la Vallée des Épreuves.', },
  },
  [3085] = {
    'Tablette bénie',
    {'Ah, pendant votre absence, on a apporté une tablette pour vous, $N.|n|nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des prêtres, Ken\'jai. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lire la Tablette bénie, et parler à Ken\'jai, à l\'extérieur de l\'Antre, dans la Vallée des Épreuves.', },
  },
  [3086] = {
    'Tablette glyphée',
    {'Ah, pendant votre absence, on a apporté une tablette pour vous, $N.|n|nLisez-la, dès que vous aurez un moment. Si je ne me trompe pas, elle provient du Maître des mages, Mai\'ah. Elle souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lire la Tablette glyphée, et parler à Mai\'ah, près de l\'entrée de l\'Antre, dans la Vallée des Épreuves.', },
  },
  [3087] = {
    'Parchemin gravé',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chasseurs, Karranisha. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lisez le Parchemin gravé et parlez à Karranisha, dans la Vallée des Épreuves.', },
  },
  [3088] = {
    'Parchemin codé',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des voleurs, Rwag. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lire le Parchemin codé, et parler à Rwag, dans la Vallée des Épreuves.', },
  },
  [3089] = {
    'Parchemin runique',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nLisez-le quand vous en aurez le temps. Si je ne me trompe pas, il provient du Maître des chamans, Shikrik. Elle souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lire le Parchemin runique, et parler à Shikrik, dans la Vallée des Épreuves.', },
  },
  [3090] = {
    'Parchemin contaminé',
    {'Ah, pendant que vous n\'étiez pas là un parchemin est arrivé pour vous, $N.|n|nJ\'évite normalement de traiter avec des démonistes, si c\'est possible, mais je pense que vous devriez le lire, quand vous en aurez le temps. Si je ne me trompe pas, il provient du maître qui vous a été récemment assigné, Nartok. Il souhaiterait s\'entretenir avec vous, quand vous jugerez le moment venu.', },
    {'Lisez le Parchemin contaminé, et parlez à Nartok dans la Vallée des Épreuves.', },
  },
  [3091] = {
    'Note simple',
    {'Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu\'elle était envoyée par le Maître des guerriers, Harutt. Si ce message est bien de Harutt, je ne tarderais pas à le lire, à votre place.', },
    {'Lire la Note simple, et parler à Harutt Corne-tonnerre, au Camp Narache.', },
  },
  [3092] = {
    'Note gravée',
    {'Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu\'elle était envoyée par le maître des chasseurs, Lanka. Si ce message est bien de Lanka, je ne tarderais pas à le lire, à votre place.', },
    {'Lire la Note gravée, et parler à Lanka Vise-loin, au Camp Narache.', },
  },
  [3093] = {
    'Note runique',
    {'Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu\'elle était envoyée par le Maître des chamans, Meela. Si ce message est bien de Meela, je ne tarderais pas à le lire, à votre place.', },
    {'Lire la Note runique, et parler à Meela Aube-glorieuse, au Camp Narache.', },
  },
  [3094] = {
    'Note verdoyante',
    {'Il y a quelques instants, une messagère était à votre recherche, $N. Je crois qu\'elle était envoyée par le Maître des druides, Gart. Si ce message est bien de Gart, je ne tarderais pas à le lire, à votre place.', },
    {'Lire la Note verdoyante, et parler à Gart Cours-la-Brume, au Camp Narache.', },
  },
  [3095] = {
    'Parchemin simple',
    {'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu\'il est de quelque importance, car il porte le sceau du Maître des guerriers, Dannal. À votre place, je prendrais le temps de le lire avant de repartir.', },
    {'Lire le Parchemin simple, et parler à Dannal Stern, au Glas.', },
  },
  [3096] = {
    'Parchemin codé',
    {'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu\'il est de quelque importance, car il porte le sceau du Maître des voleurs, David Trias. À votre place, je prendrais le temps de le lire avant de repartir.', },
    {'Lire le Parchemin codé, et parler à David Trias, au Glas.', },
  },
  [3097] = {
    'Parchemin béni',
    {'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu\'il est de quelque importance, car il porte le sceau du Maître des prêtres, Duesten. À votre place, je prendrais le temps de le lire avant de repartir.', },
    {'Lire le Parchemin béni, et parler au sombre clerc Duesten, dans l\'église du Glas.', },
  },
  [3098] = {
    'Rouleau glyphé',
    {'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu\'il est de quelque importance, car il porte le sceau du Maître des mages, Isabella. À votre place, je prendrais le temps de le lire avant de repartir.', },
    {'Lire le Rouleau glyphé, et parler à Isabella, dans l\'église du Glas.', },
  },
  [3099] = {
    'Rouleau contaminé',
    {'Ah, pendant que vous vous occupiez du Fléau, ce parchemin est arrivé pour vous. Je suppose qu\'il est de quelque importance, car il porte le sceau du Maître des démonistes, Maximillion. À votre place, je prendrais le temps de le lire avant de repartir.', },
    {'Lire le Rouleau contaminé, et parler à Maximillion, au Glas.', },
  },
  [3100] = {
    'Lettre simple',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de Llane, notre maître des guerriers. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre simple et parler à Llane Beshere, à l\'Abbaye de Comté-du-Nord.', },
  },
  [3101] = {
    'Lettre consacrée',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de frère Sammuel, notre maître des paladins. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre consacrée, et parler à Frère Sammuel, à l\'Abbaye de Comté-du-Nord.', },
  },
  [3102] = {
    'Lettre codée',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de Jorik, l\'un de nos maîtres. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre codée, et parler à Jorik Kerridan, dans l\'écurie, derrière l\'Abbaye de Comté-du-Nord.', },
  },
  [3103] = {
    'Lettre bénie',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de la prêtresse Anetta, notre maître des prêtres. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre bénie, et parler à la prêtresse Anetta, à l\'abbaye de Comté-du-Nord.', },
  },
  [3104] = {
    'Lettre glyphée',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de Khelden, notre maître des mages. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre glyphée, et parler à Kheldon Bremen, à l\'intérieur de l\'Abbaye de Comté-du-Nord.', },
  },
  [3105] = {
    'Lettre contaminée',
    {'$N, vous vous êtes $Gchargé:chargée; des espions rochenoires ? On m\'a demandé de vous apporter ceci dès votre retour. Il semble que ce soit une lettre scellée aux armes de Drusilla, l\'un de nos maîtres. À votre place, je la lirais avant d\'entreprendre quoi que ce soit d\'autre, ici, à l\'abbaye.', },
    {'Lire la Lettre contaminée, et parler à Drusilla La Salle, à proximité de l\'Abbaye de Comté-du-Nord.', },
  },
  [3106] = {
    'Rune simple',
    {'Pendant que vous m\'aidiez, on m\'a donné cette rune pour vous, $N. Prenez le temps de la lire. Je pense qu\'elle provient du maître des guerriers, Thran. Jetez-y un coup d\'œil et allez le retrouver à l\'intérieur de Courbenclume.', },
    {'Lisez la Rune simple, et parlez à Thran Khorman, dans la Vallée des Frigères.', },
  },
  [3107] = {
    'Rune consacrée',
    {'Pendant que vous m\'aidiez, on m\'a donné cette rune pour vous, $N. Prenez le temps de la lire. Je pense qu\'elle provient du maître des paladins, Bromos. Jetez-y un coup d\'œil et allez le retrouver à l\'intérieur de Courbenclume.', },
    {'Lisez la Rune consacrée, et parlez à Bromos Grummneur, à Courbenclume.', },
  },
  [3108] = {
    'Rune gravée',
    {'$N, on m\'a donné cette rune pour vous. Prenez le temps de la lire pendant que vous le pouvez. Je pense qu\'elle provient du maître des chasseurs, Thorgas. Jetez-y un coup d\'œil et allez le retrouver, à l\'intérieur de Courbenclume.', },
    {'Lisez la Rune gravée et parlez à Thorgas Grimson, à Courbenclume.', },
  },
  [3109] = {
    'Rune codée',
    {'Pendant que vous m\'aidiez, on m\'a donné cette rune pour vous, $N. Prenez le temps de la lire. Je pense qu\'elle provient du maître des voleurs, Solm. Jetez-y un coup d\'œil et allez le retrouver à l\'intérieur de Courbenclume.', },
    {'Lisez la Rune codée, et parlez à Solm Hargrin, à Courbenclume.', },
  },
  [3110] = {
    'Rune bénie',
    {'Pendant que vous m\'aidiez, on m\'a donné cette rune pour vous, $N. Prenez le temps de la lire. Je pense qu\'elle provient du maître des prêtres, Branstock. Jetez-y un coup d\'œil et allez le retrouver à l\'intérieur de Courbenclume.', },
    {'Lisez la Rune bénie, et parlez à Branstock Khalder, à Courbenclume.', },
  },
  [3111] = {
    nil,
    {'Il y a bien longtemps, les hauts-elfes nous ont appris les secrets de la magie ainsi qu\'à nos alliés humains. Ils nous ont mis en garde sur les règles à suivre et contre la folie qu\'elle peut provoquer ! Mais n\'y croyez pas. Nous sommes différents des elfes ; nous n\'avons pas les mêmes faiblesses. Restez sur le droit chemin et vous verrez que la magie est aussi puissante en tant qu\'outil qu\'en tant qu\'arme.|n|nVenez me chercher à Courbenclume. Je vous y attendrai !|n|n- Marrek Stromnur, Maître des mages', },
    {'Parler à Marrek Stromnur à Courbenclume.', },
  },
  [3112] = {
    'Note de service simple',
    {'Pendant que vous m\'aidiez, on m\'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu\'elle provient du Maître des guerriers, Thran. Jetez-y un coup d\'œil et allez le retrouver, à l\'intérieur de Courbenclume, quand vous en aurez le temps.', },
    {'Lire la Note de service simple, et parler à Thran Khorman, dans la Vallée des Frigères.', },
  },
  [3113] = {
    'Note de service codée',
    {'Pendant que vous m\'aidiez, on m\'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu\'elle provient du Maître des voleurs, Solm. Jetez-y un coup d\'œil et allez le retrouver, à l\'intérieur de Courbenclume, quand vous en aurez le temps.', },
    {'Lire la Note de service codée, et parler à Solm Hargrin, dans la Vallée des Frigères.', },
  },
  [3114] = {
    'Note de service glyphée',
    {'Pendant que vous m\'aidiez, on m\'a donné cette note de service pour vous. Prenez le temps de la lire. Je pense qu\'elle provient du Maître des mages, Marryk. Jetez-y un coup d\'œil et allez le retrouver, à l\'intérieur de Courbenclume, quand vous en aurez le temps.', },
    {'Lire la Note de service glyphée, et parler à Marryk Nurribit, dans Courbenclume, au-dessus de la Vallée des Frigères.', },
  },
  [3115] = {
    'Rune contaminée',
    nil,
    nil,
  },
  [3116] = {
    'Cachet simple',
    {'Ce cachet m\'a été donné par un messager de notre maître des guerriers, Alyissia. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez ce message et rapportez-le-lui.', },
    {'Allez voir Alyissia, à l\'intérieur d\'Aldrassil, au Sombrevallon.', },
  },
  [3117] = {
    'Cachet gravé',
    {'Ce cachet m\'a été donné par un messager de notre maître des chasseurs, Ayanna. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez ce message et rapportez-le-lui.', },
    {'Allez voir Ayanna Vassanfin, à l\'intérieur d\'Aldrassil, au Sombrevallon.', },
  },
  [3118] = {
    'Cachet codé',
    {'Ce cachet m\'a été donné par un messager de notre maître des voleurs, Frahun. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez le message et rapportez-le-lui.', },
    {'Lisiez le Cachet codé et allez parler à Frahun Murmombre, à l\'intérieur d\'Aldrassil, au Sombrevallon.', },
  },
  [3119] = {
    'Cachet béni',
    {'Ce cachet m\'a été donné par un messager de notre maître des prêtres, Shanda. Elle souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez le message et rapportez-le-lui.', },
    {'Allez voir Shanda, à l\'intérieur d\'Aldrassil, au Sombrevallon.', },
  },
  [3120] = {
    'Cachet verdoyant',
    {'Ce cachet m\'a été donné par un messager de notre maître des druides, Mardant. Il souhaiterait vous parler, dès que vous aurez un moment à lui accorder. Lisez le message et rapportez-le-lui.', },
    {'Lisez le Cachet verdoyant et allez parler à Mardant Chênefort, à l\'intérieur d\'Aldrassil, au Sombrevallon.', },
  },
  [3121] = {
    'Une Requête étrange',
    {'Xerash Lamefeu, au pavillon de Lariss, au nord du Camp Mojache, a ce qu\'il me faut pour travailler ici ! Il a préparé un mélange dont j\'ai besoin pour... enfin vous verrez.|n|nMettez-vous en chemin pour voir Xerash. Tenez, prenez ceci. C\'est une tête réduite que j\'ai promise à Xerash en échange des herbes. C\'est la tête d\'un pauvre nain qui a croisé ma route dans la forêt. Je suis certain qu\'il appréciera.', },
    {'Porter la Tête réduite à Xerash Lamefeu, au Pavillon de Lariss, en Féralas.', },
  },
  [3122] = {
    'Retourner voir le féticheur Uzer\'i',
    {'Voici les herbes, $N. Portez-les au féticheur Uzer\'i.|n|nDites-lui que je suis très content de la tête réduite.', },
    {'Livrer une Poche d\'herbes de Xerash au Féticheur Uzer\'i, en Féralas.', },
  },
  [3123] = {
    'Test du récipient',
    {'Il va s\'agir d\'un test, qui mettra à l\'épreuve le rituel que j\'ai accompli comme vos capacités. Prenez ce récipient, $N. Avec cela, vous pourrez réduire la taille des créatures et les y capturer.|n|nPartez pour les étendues Sauvages de l\'est et cherchez des bêtes. Vos cibles sont les vicieux ours Ferpoil et coureurs Longues-dents, $N. Tuez-les, puis utilisez le récipient à muisek pour les faire rétrécir et les capturer avant que leurs esprits ne s\'échappent.', },
    {'Tuez 10 Ours Ferpoil ou Coureurs Longues-dents, puis utilisez le Récipient à muisek de bête pour faire rétrécir et capturer les bêtes vaincues.|n|nRamenez 10 Muiseks de bêtes et le Récipient à muisek de bête au Féticheur Uzer\'i, en Féralas.', },
  },
  [3124] = {
    'Muisek d\'hippogriffe',
    {'Puisque vous avez montré que vous êtes à la fois digne de confiance et $Gdoué:douée; pour utiliser le récipient à muisek, je souhaite à présent que vous capturiez une autre créature.|n|nLes hippogriffes ont été les compagnons loyaux des elfes de la nuit durant plusieurs années. Leur esprit est résolu et ferme.|n|nVotre tâche consiste à tuer 10 hippogriffes Aigreplume et de rapidement les faire rétrécir et les capturer avec le récipient, afin que leur muisek soit préservé. Vous trouverez les hippogriffes dans les plateaux Sauvages au sud d\'ici.', },
    {'Tuer 10 Hippogriffes Aigreplume de n\'importe quel type, puis utiliser le Récipient à muisek pour les faire rétrécir et les capturer.', },
  },
  [3125] = {
    'Muisek de dragon féerique',
    {'À présent, $N, je souhaite que vous capturiez une créature fragile en apparence, mais dont l\'esprit puissant nous intéresse. Je veux parler des dragons féeriques. Ils ont été les alliés des elfes de la nuit. Nous devons en capturer afin que la Horde puisse également bénéficier de cette force spirituelle.|n|nVoici le récipient, $N. Tuez 8 Fées fléchetteuses ou Petits dragons féeriques, et capturez leur muisek. On peut en trouver à l\'ouest d\'ici.', },
    {'Tuez 8 Fées fléchetteuses ou Petits dragons féeriques. Utiliser le Récipient à muisek pour rétrécir et capturer les dragons féeriques vaincus.', },
  },
  [3126] = {
    'Muisek de tréant',
    {'Les marcheurs des bois errants qu\'on voit louvoyer dans la forêt sont notre prochaine cible, $N. Les elfes de la nuit ont gagné les tréants à leur cause dans leur combat contre la Horde. Leur vitesse de déplacement est faible, mais leur rôle en tant que protecteurs est indéniable.|n|nBientôt, nous pourrons utiliser leur pouvoir à notre propre compte.|n|nTrouvez trois marcheurs des bois errants, tuez-les et utilisez le récipient à muisek pour les miniaturiser et les capturer.', },
    {'Tuez 3 Marcheurs des bois errants. Utilisez le Récipient à muisek pour miniaturiser et capturer les tréants vaincus.', },
  },
  [3127] = {
    'Muisek de géant des montagnes',
    {'La dernière chose que je vous demande est de partir vers le nord-ouest pour trouver l\'ennemi final.|n|nLes géants des montagnes ont quitté leurs montagnes pour aider les elfes de la nuit quand la Légion ardente est apparue. Vous les reconnaîtrez à leur stature massive ainsi qu\'aux vibrations du sol à mesure que vous avancerez dans leur contrée rocailleuse.|n|nJ\'ai à cœur de maîtriser une puissance d\'une telle taille. Tuez 7 géants des montagnes puis utilisez le Récipient pour capturer leur puissant muisek.', },
    {'Tuer 7 Marcheurs des terres ou Géants des falaises. Utiliser le Récipient à muisek pour faire rétrécir et pour capturer les Géants des montagnes.', },
  },
  [3128] = {
    'Matériaux naturels',
    {'Je vais avoir besoin de matériaux pour finir ce que j\'ai commencé... Vous pouvez les rechercher tout en accomplissant les autres tâches que je vais vous confier.|n|nJ\'aurai besoin de bûches fendues de tréant de Féralas. De minerai incrusté, que l\'on peut trouver sur les géants des montagnes ou les dragons féeriques, à l\'ouest. Et aussi, trouvez-moi des tendons résistants des chouettards des Hinterlands ou des hippogriffes de Féralas. Enfin, il me faudrait une grande quantité de fragments métalliques de chacune des créatures mentionnées.', },
    {'Apporter 2 Bûches fendues, 6 Minerais incrustés, 20 Morceaux de tendons résistants et 40 Fragments métalliques au Féticheur Uzer\'i au Camp Mojache.', },
  },
  [3129] = {
    'Armes de l\'Esprit',
    {'Imprégner les armes de muisek est un processus difficile. Maintenant que nous avons les matériaux nécessaires et le muisek des créatures que vous avez capturées, je peux commencer. Attendez s\'il vous plaît ; je reviens dans un moment.', },
    {'Le Féticheur Uzer\'i veut que vous patientez pendant qu\'il prépare les armes.', },
  },
  [3130] = {
    'Contre les Hainecrêtes',
    {'À présent, je vais vous diriger vers mon second, Latronicus. Il a gardé un œil attentif sur les forces des nagas jusqu\'alors. J\'estimerai la situation générale ici selon les nagas. Non pas que je veuille envoyer une force compacte les combattre, laissant ainsi la forteresse ouverte à une attaque directe de la Horde, ou pire...|n|nMais passons, Latronicus attend. Vous avez fait du bon travail jusque-là, $N. Continuez comme ça.|n|nVous pouvez disposer.', },
    {'Se présenter devant Latronicus Lancelune au bastion de Pennelune.', },
  },
  [3141] = {
    nil,
    {'Donc vous souhaitez vous battre contre des démons ? Vous feriez bien d\'écouter mon histoire.', },
    {'Écoutez l\'histoire de Loramus Thalipedes.', },
  },
  [3161] = {
    'Gahz\'ridienne',
    {'$N, je suis un scientifique mais au fond de moi, je suis aussi un chasseur de trésor !|n|nIl y a longtemps, quand les trolls occupaient ces terres, ils ont créé de nombreux ornements à l\'image de Gahz\'rilla, une hydre qu\'ils adorent comme divinité. Ces ornements sont sculptés à partir d\'une matière que j\'appelle la « gahz\'ridienne », d\'après le nom du dieu hydre.|n|nJ\'en ai déjà trouvé un peu moi-même, mais j\'aimerais en avoir plus à étudier ; peut-être pourrez-vous m\'en trouver ?|n|nJ\'ai même inventé un détecteur qui fait de la recherche de gahz\'ridienne un jeu d\'enfant ! Vous n\'avez qu\'à le porter et la recherche peut commencer !', },
    {'Marvon Chercherivet, à Tanaris, vous a demandé de ramasser 30 Ornements en gahz\'ridienne.', },
  },
  [3181] = {
    'La corne de la bête',
    {'La corne gigantesque est couverte d\'égratignures et de fissures. Un objet de métal inhabituel s\'est logé sous la surface dure.|n|nAprès de plus amples observations, vous remarquez qu\'il s\'agit d\'une lame de hache brisée. Sur le métal sont gravés les mots suivants :|n|nPropriété de la montagnarde Minigravillon.|n|nQuand vous essayez de déloger la lame, elle s\'effrite en mille morceaux.|n|nOups !', },
    {'Porter la Corne Gigantesque de Margol à la Montagnarde Minigravillon.', },
  },
  [3182] = {
    'Titre de propriété',
    {'Et vous pensez que je vais avaler une histoire pareille ? Le fer de ma hache se serait brisé et serait coincé dans la véritable corne, s\'il s\'agissait bien d\'elle.|n|nÉcoutez, apportez ce faux grossier au conservateur en chef Thorius à Forgefer. S\'il est capable de valider vos dires, vous recevrez un certificat de haut fait. Rapportez-moi cette preuve et je vous remettrai la clé de la gorge des Vents brûlants.|n|nAllez-y !', },
    {'Porter la Corne gigantesque de Margol au conservateur en chef Thorius à Forgefer.', },
  },
  [3201] = {
    'Enfin !',
    {'Je n\'arrive pas à croire que Minigravillon ait pu douter de l\'authenticité de la corne. Entre vous et moi, je pense qu\'elle est seulement jalouse. Je sais qu\'elle tenait vraiment à tuer elle-même cette bête, à cause de « l\'incident » et tout.|n|nDonc vous avez besoin d\'un document comme preuve ? Après la contribution que vous venez de faire au musée, ce ne sera pas un problème.|n|n<Le conservateur en chef Thorius commence à remplir un grand document>|n|nEt voilà ! Vous pouvez présenter ceci à Minigravillon.', },
    {'Apporter le document de preuve à la Montagnarde Minigravillon.', },
  },
  [3221] = {
    'Parler à Renferrel',
    {'Tandis que vous étiez en train d\'aider nos nécrotraqueurs, l\'apothicaire Renferrel vous a fait appeler. Il n\'a rien précisé mais a dit qu\'il voulait vous parler à propos des cœurs de loup que vous lui aviez donnés.', },
    {'Parler à l\'apothicaire Renferrel au Sépulcre.', },
  },
  [3241] = {
    nil,
    {'Récupérez les totems du Pic de Brume-funeste, car il est plutôt poisseux en ce moment et ce n\'est pas un endroit convenable pour des totems tout propres.', },
    {'Apportez-les à Tonga Totem-runique.', },
  },
  [3261] = {
    '[PÉRIMÉ 4].xJorn Œil-des-cieux',
    {'Nos routes se séparent, $N. Pour en apprendre plus, vous devrez aller au Camp Taurajo, vers le sud et parler à Jorn Oeil-des-cieux. Il continuera de vous guider.', },
    {'Parler à Jorn Oeil-des-cieux, au Camp Taurajo.', },
  },
  [3281] = {
    '[PÉRIMÉ]Argent volé',
    {'Vous avez peut-être tué les raptors, mais l\'argent qu\'ils ont volé doit être récupéré ! Des rapports indiquent que les raptors ont un important site de nidification au sud de Cabestan. Cet endroit est connu sous le nom de Terres des raptors. Il est probable qu\'ils y aient apporté notre argent volé.|n|nAllez dans ce repaire de raptors et cherchez-le. Quand vous l\'aurez trouvé, rapportez-le-moi.', },
    {'Rapportez l\'Argent volé à Gazrog à la Croisée.', },
  },
  [3301] = {
    'Mura Totem-Runique',
    {'Ma camarade de clan, Mura Totem-runique, est partie pour les Pins-Argentés afin d\'aider nos alliés morts-vivants. C\'est une forêt qui dépérit doucement, et elle avait l\'espoir d\'y insuffler la vie à nouveau. Peut-être que la vie insolite que nous trouvons ici dans les Tarides l\'aiderait à réaliser ses souhaits pour les Pins-Argentés ?|n|nPrenez avec vous une des carapaces que vous avez apportées, et donnez-la à Mura Totem-runique aux Pins-Argentés. Elle séjourne au Sépulcre. Avec un peu de chance, l\'étude de cette carapace l\'aidera à trouver une solution pour guérir cette forêt à l\'agonie.', },
    {'Allez voir Mura Totem-runique au Sépulcre, dans la Forêt des Pins-Argentés.', },
  },
  [3321] = {
    'Est-ce que ceci est à vous ?',
    {'Vous avez beaucoup fait pour l\'Ordre, $N. Le total dévouement nécessaire pour parvenir jusqu\'ici aurait rebuté toute personne ordinaire. Il ne fait aucun doute dans mon esprit, ni dans celui de Galvan, que vous faites partie des nôtres.|n|nC\'est la raison pour laquelle j\'estime que vous méritez une petite récompense. Ce n\'est pas grand-chose en fait, un simple colifichet. Il se peut que vous connaissiez déjà ses propriétés, car je crois que c\'est ce qui vous a $Gamené:amenée; à nous en premier lieu.', },
    {'Attendre que Trenton ait terminé son travail.', },
  },
  [3341] = {
    'L\'anéantissement',
    {'Il se trouve dans les Tarides un horrible fouillis de ronces entremêlées, les Souilles de Tranchebauge. Bien que nos premières observations à cet endroit n\'aient révélé que peu de dangers, nos découvertes récentes sont beaucoup plus alarmantes…|n|nLes hurans des Souilles de Tranchebauge se sont alliés au Fléau. Une liche du nom de Amnennar, dite le Porte-froid, les contrôle à présent et utilise le pouvoir de son imposante connaissance pour diriger chacun de leurs mouvements.|n|nAmnennar est liée à Ner\'zhul par la télépathie ; nous devons trancher ce lien, $N. Il faut éliminer le Porte-froid.', },
    {'Andrew Brownell veut que vous tuiez Amnennar le Porte-froid et que vous lui rameniez son crâne.', },
  },
  [3361] = {
    'Les malheurs d\'un réfugié',
    {'J\'étais en route pour Gnomeregan, où j\'allais rejoindre mes semblables, quand subitement, tout a été horriblement de travers !|n|nJ\'ai quitté Courbenclume avec armes et bagages, et de la neige jusqu\'à la taille. C\'est alors qu\'il y a eu cet incroyable tremblement de terre, et tout a basculé. J\'ai échoué ici, mais ce qui est plus grave, c\'est que les trolls ont volé toutes mes affaires !|n|n$N, j\'ai déjà fait suffisamment étalage de mon incompétence depuis un jour et demi. Vous voulez bien vous glisser dans le camp des trolls au sud-ouest, et me rapporter mes affaires ?', },
    {'Récupérer la Boîte de Felix, le Coffre de Felix et le Seau de boulons de Felix.', },
  },
  [3362] = {
    'La vallée des Chardonniers',
    {'Avez-vous déjà vu la vallée des Chardonniers ? C\'est un endroit dangereux, $N.|n|nIl y a d\'étranges bêtes là-bas, imprévisibles ! Je crois qu\'on les appelle les chardonniers noueux et les chardonniers taille-racine...|n|nJe veux accéder à la vallée, mais avec tous ces chardonniers dans les parages c\'est bien trop risqué. Si vous vouliez bien aller en tuer quelques-uns, je pourrais envisager d\'y retourner. Qu\'en pensez-vous, $N ? M\'aiderez-vous ?', },
    {'Tran\'rek, à Gadgetzan, voudrait que vous tuiez 8 Chardonniers noueux et 8 Chardonniers taille-racines.', },
  },
  [3363] = {
    'Fleur-de-chant corrompue',
    nil,
    nil,
  },
  [3364] = {
    'Une livraison de thé brûlant',
    {'Ah ! Je devais apporter un Thé brûlant à Durnan Coupefourrure, à Courbenclume, mais je dois d\'abord en porter un à Grelin. Je n\'arriverai jamais à Courbenclume avant qu\'il ne refroidisse !|n|nVous m\'avez l\'air rapide. Vous pouvez le faire. Cette boisson ne restera chaude que 5 minutes et Durnan n\'a pas commandé un Thé "glacé", alors partez tout de suite. Courbenclume est un village dans la montagne, au nord-est.|n|nMerci, $N, et n\'oubliez pas de me rapporter ma tasse !', },
    {'Apporter un Thé brûlant à Durnan Coupefourrure, dans Courbenclume, dans les cinq minutes imparties avant qu\'il ne refroidisse !', },
  },
  [3365] = {
    'Rapporter la Tasse',
    {'Ah ! Vous êtes $Garrivé:arrivée; à point nommé ! Rien de tel qu\'un bon thé chaud, non, BRÛLANT, par une froide journée d\'hiver pour réchauffer les méandres de votre esprit.|n|nTenez, $N, soyez assez aimable pour rapporter cette tasse vide à Nori pour moi, voulez-vous ?', },
    {'Apporter la Chope de Nori à Nori Fièroblique dans la Vallée des Frigères.', },
  },
  [3366] = {
    'L\'Éclat luminescent',
    {'L\'éclat est d\'un vert brillant, et bien que compact, ce qui ressemble à de la fumée tourbillonne juste au-dessous de sa surface. Vous ne pouvez vous empêcher de contempler les profondeurs du cristal, bien qu\'en même temps, vous sentiez qu\'il y réside quelque chose de très inquiétant.|n|nPeut-être devriez-vous voir si quelqu\'un à Cabestan pourrait vous en apprendre plus à propos de cet étrange éclat...', },
    {'Aller à Cabestan pour trouver la raison d\'être de l\'Éclat de cauchemar.', },
  },
  [3367] = {
    'Les pierres de Suntara',
    {'<Dorius gémit.>|n|nJe suis grièvement blessé, $R. Je me sens… la tête toute légère… tout… tournoie… je saigne… à l\'intérieur.|n|nJe dois retourner à Forgefer. Aidez-moi, $N.', },
    {'Aider Dorius à retourner à Forgefer.', },
  },
  [3368] = {
    'Les pierres de Suntara',
    {'Mon frère,|n|nSi vous lisez cette lettre, c\'est que je n\'existe plus. Comment vous est-elle parvenue, je l\'ignore. Mais remerciez et récompensez ceux qui ont fait en sorte que vous l\'ayez reçue.|n|nÀ propos des pierres : elles existent, les Sombrefers les ont en leur possession. Leur chef, Lathoric le Noir, utilise le pouvoir de ces pierres pour asservir mon équipe d\'archéologues. Ils ont été emmenés au Chaudron. Leurs esprits sont à présent asservis et ils travaillent nuit et jour pour achever une chose qui répond au nom d\'Obsidion.|n|nSecourez-les. Il s\'agit là de la dernière volonté d\'un homme mort.|n|n-Dorius', },
    {'Apporter la Lettre roussie à Thorius à Forgefer. Il se trouve dans le Hall des Explorateurs.', },
  },
  [3369] = {
    'Au cœur des cauchemars',
    {'Cet éclat détient de grands secrets. Il s\'agit de l\'essence pure du Rêve d\'émeraude. Ce que je vois dans cet éclat n\'a rien d\'un rêve cependant. On pourrait même appeler cela une vision de cauchemar.|n|nMon but n\'est pas de vous alarmer, $N, mais je crois qu\'il serait mieux pour vous de remettre cet éclat à un grand druide, et ce le plus tôt possible.|n|nLa personne que vous devriez rencontrer à la cime des Anciens se nomme Hamuul Totem-runique. Partez pour les Pitons-du-Tonnerre. Je ne peux pas vous en dire plus.', },
    {'Apportez l\'Éclat de cauchemar à Hamuul Totem-runique à la Cime des Anciens.', },
  },
  [3370] = {
    'Au cœur des cauchemars',
    {'Cet éclat détient de grands secrets. Il s\'agit de l\'essence pure du Rêve d\'émeraude. Ce que je vois dans cet éclat n\'a rien d\'un rêve cependant. On pourrait même appeler ce genre de vision un cauchemar.|n|nMon souhait n\'est pas de vous alarmer, $N, mais je crois qu\'il serait mieux pour vous de remettre cet éclat aux mains d\'un grand druide, et ce dès que vous le pouvez.|n|nLa personne que vous devez trouver au Cercle cénarien se nomme Mathrengyl Pasdelours. Partez pour Darnassus. Je ne peux vous en dire plus.', },
    {'Apportez l\'Éclat de cauchemar à Mathrengyl Pasdelours à Darnassus.', },
  },
  [3371] = {
    'La justice des nains',
    {'Il y a, à présent, un creux vide de sens, là où se trouvait autrefois mon cœur, $N. Je ne me remettrai pas de la perte de Dorius. Je dois faire en sorte que sa dernière volonté soit accomplie. Justice doit être rendue contre ceux qui ont commis ce meurtre de sang-froid.|n|nRetournez à la Gorge des Vents brûlants et respectez sa dernière volonté : libérez ses hommes. Les nains sombrefers forcent leurs esclaves à travailler dans une mine étouffante appelée la Fosse aux scories. Allez chercher les hommes de Dorius là-bas.', },
    {'Retourner à la Gorge des Vents brûlants et trouver l\'Equipe d\'archéologues de Dorius.', },
  },
  [3372] = {
    'La libération',
    {'Libérez-les, $R. Leurs corps sont morts, mais la puissance de Suntara les oblige à achever leur travail.|n|nL\'autel de Suntara est la clé pour les libérer. Allez au nord-ouest, dans les collines au-dessus de la caverne… Le Marteau du crépuscule y garde une relique. Emparez-vous-en et placez-la sur l\'autel de Suntara.|n|n<L\'archéologue mourant s\'effondre.>', },
    {'Trouvez l\'Artéfact mystérieux gardé par les Idolâtres du Marteau du crépuscule dans le quart nord-ouest de la Gorge des Vents brûlants, et rapportez-le à l\'Autel de Suntara, dans la Fosse aux scories.', },
  },
  [3373] = {
    'L\'Essence d\'Eranikus',
    {'Alors que vous touchez la gemme, une voix grave résonne dans votre esprit.|n|n« $GMortel:Mortelle;, considérez ma requête. Je suis Eranikus des dragons verts, gardien de ce temple maudit. J\'avais pour charge de m\'assurer que les trolls n\'amènent plus en ces lieux leurs dieux abominables. Mais j\'ai échoué. Alors que j\'imprègne cette gemme d\'une partie de mon essence, je sens que mon étreinte sur le Rêve s\'évanouit vers le néant. Je vous en prie, placez cette gemme dans le Réceptacle d\'essence de mon antre, et que notre magie en ces lieux purge l\'infection de mon esprit et me permette de reposer. »', },
    {'Placer l\'Essence d\'Eranikus dans le Réceptacle d\'essence situé dans son antre dans le Temple englouti.', },
  },
  [3374] = {
    'L\'Essence d\'Eranikus',
    {'Vous activez la Pierre de vœu et Itharius parle directement à votre esprit à travers elle.|n|n« En acceptant la charge contenue dans cette Pierre de vœu, vous vous engagez à soutenir ma cause et celle des dragons d\'Ysera, qui est de racheter l\'esprit corrompu d\'Eranikus. Le premier sacrifice, parmi les nombreux que vous et moi ferons sans aucun doute, va être de m\'abandonner la gemme qui a enchaîné ce qu\'il reste de volonté dans l\'esprit d\'Eranikus.|n|nFaites-le, $N, et nous œuvrerons de concert au rachat d\'une âme digne de rédemption. »', },
    {'Apportez la Pierre de voeu des dragons d\'Ysera et l\'Essence d\'Eranikus enchaînée à Itharius au marais des Chagrins. C\'est là que vous choisirez d\'aider ou non les dragons d\'Ysera.', },
  },
  [3375] = {
    'La flasque de remplacement',
    {'Hum, vous avez besoin d\'une autre flasque de divination ? C\'est une plaisanterie, n\'est ce pas ? Qu\'avez-vous fait de la première ?! Nous avons du pain sur la planche, $R. Ces flasques ne poussent pas sur les arbres ! En fait, j\'aimerais bien que ce soit le cas, car je m\'y rendrais tout simplement et en cueillerais une, puisqu\'il ne m\'en reste plus !!|n|nPour que je puisse vous la préparer, j\'ai besoin des choses suivantes : une potion de mana, un morceau de charbon et du nectar sucré. Ne me demandez pas pourquoi, rapportez-moi simplement tout ceci et je vous en ferai une autre.', },
    {'Apportez une Potion de mana, du Charbon, et du Nectar sucré à Talvash del Kissel, à Forgefer, pour remplacer la Flasque de divination de Talvash.', },
  },
  [3376] = {
    'La fin de Brochaigu !',
    {'$N, j\'ai entendu parler de vous. Peut-être saurez-vous nous venir en aide là où d\'autres ont échoué.|n|nNous, taurens, avons fait de cette terre notre foyer. Mais cela n\'a pas été sans pertes. Les hurans dos-hirsutes, du ravin de Roncelame, menés par leur chef Brochaigu Mantépine, nous accablent sans cesse. Je vous demande de me rapporter la tête de leur chef !|n|nVous pourrez le trouver dans le ravin, à l\'est, dans leur village de fortune.', },
    {'Apportez la Tête du chef Brochaigu Mantépine à Brave Plume-des-vents à la Mesa de Nuage rouge.', },
  },
  [3377] = {
    'Prière à Élune',
    {'Me viendrez-vous en aide, $Gmortel:mortelle; ? Écoutez mon récit.', },
    {'Écouter le récit de Zamael.', },
  },
  [3378] = {
    'Prière à Élune',
    {'Me viendrez-vous en aide, $Gmortel:mortelle; ? Trouverez-vous la prière à Élune ?|n|nComme je l\'ai dit, cette prière a été gravée sur une tablette en or. Elle doit se trouver sur l\'une de ces crapules vénérant des idoles.|n|nSi vous parvenez à retrouver ma prière, apportez-la à Astarii Cherchétoile à Darnassus. Il importe peu que ma foi ait été ravivée après les innombrables actions malveillantes que j\'ai infligées à ce monde et à ses habitants, mais ma prière doit être entendue. La dernière chose que je demande est l\'absolution.', },
    {'Trouver la Prière à Élune et l\'apporter à Astarii Cherchétoile à Darnassus.', },
  },
  [3379] = {
    'Les tisseuses d\'ombre',
    {'Les araignées de la gorge des Vents brûlants sont une source inestimable de Soie des ténèbres. Comme vous le savez, la Soie des ténèbres est très recherchée par les artisans de notre métier.|n|nMalheureusement, un groupe de braconniers a récemment empiété sur ces terres, et massacre en masse les araignées sans se soucier des effets à long terme de leurs actions. Aussi, la première chose que je vous demanderai sera assez simple : trouvez-les, et... tuez-les.|n|nCommencez vos recherches au nord.|n|nSi vous avez besoin d\'assistance, parlez avec Raze.', },
    {'Tuer le groupe de braconniers Ombresoie qui rôde dans la gorge des Vents brûlants. Nilith a de bonnes raisons de croire qu\'ils doivent être exterminés tous les cinq. Retourner voir Nilith dans la gorge des Vents brûlants lorsque vous aurez terminé.', },
  },
  [3380] = {
    'Le Temple englouti',
    {'Il existe en ce monde des esprits qui ne connaissent pas le repos, $N. Il existe des esprits viciés par leur solitude, liés à un mal antique…|n|nJ\'ai entendu parler d\'un endroit se trouvant profondément sous la surface de la terre, banni en ce lieu par des puissances plus grandes que je n\'aie jamais rencontrées.|n|nSi vous souhaitez en apprendre davantage sur cet endroit, le Temple englouti, partez à la recherche d\'un gobelin nommé Marvon Chercherivet. Il a étudié de nombreuses parties du monde, et aux dernières nouvelles, il a quitté sa demeure à Cabestan pour étudier les ruines des trolls à Tanaris.', },
    {'Trouver Marvon Chercherivet à Tanaris.', },
  },
  [3381] = {
    'Une rencontre avec le maître',
    {'Ah ! $GUn:Une; jeune vient parler à Sanath. Quelle journée merveilleuse ! Quel plaisir que vous m\'honoriez de la grâce de votre présence. Merci, $R !|n|nS\'il vous plaît, n\'ayez pas l\'arrogance de considérer mon sarcasme comme un compliment. Que les choses soient claires : je ne vous apprécie pas ! Mais cette petite conversation n\'a strictement rien à voir avec nous. Elle a à voir avec mon maître.|n|nApportez-moi une paire de plumes d\'hippogriffe pour mes flèches et je vous octroierai l\'autorisation d\'aller le voir. Il a expressément demandé que je ne lui envoie $Gd\'aventuriers que s\'ils:d\'aventurières que si elles; s\'en montrent suffisamment dignes.', },
    {'Apporter 2 Plumes d\'hippogriffe sans défaut à Sanath Lim-Yo, en Azshara, si vous souhaitez parler à son maître.', },
  },
  [3382] = {
    'Doux whisky',
    {'Nous étions près de la côte et cherchions un endroit sûr où jeter l\'ancre. Le soleil ne s\'était pas couché depuis plus d\'une heure lorsqu\'ils ont attaqué… Ces maudits nagas !|n|nJe ne sais pas ce qu\'ils cherchaient, mais il est clair qu\'ils ne l\'ont pas trouvé. Ils sont déjà revenus une fois. Deux de mes éclaireurs sont de garde à l\'entrée de la vallée pour nous avertir lorsque la prochaine attaque aura lieu.|n|nCela me désole que vous arriviez à ce moment, $N, mais je n\'y peux rien.|n|nÊtes-vous $Gprêt:prête; pour le combat de votre vie ?', },
    {'Défendre le capitaine Vanessa Beltis, son équipage et les passagers de “l\'Horizon” contre l\'attaque des nagas. Le capitaine Vanessa Beltis doit survivre.', },
  },
  [3385] = {
    'Le Sous-marché',
    {'Ils se sont donnés le nom de Sous-marché : des commerçants sans vergogne qui vendront, intimideront, commerceront, ou feront à peu près n\'importe quoi contre la bonne somme d\'argent.|n|nMais les choses empirent, $N. Ils ont établi une base d\'opérations ici dans la gorge des Vents brûlants. Kovic dirige les opérations et entretient des liens étroits avec les nains sombrefers dans la région.|n|nNous devons frapper fort et envoyer un message clair à leurs dirigeants. Tuez Kovic, ainsi que son agent Clonk. Apportez-moi sa sacoche du marchand lorsque vous en aurez terminé.|n|nPartez pour le Chaudron à présent !', },
    {'Tuer le Maître d\'artisanat Kovic et son agent Clonk. Récupérer sur son corps la Sacoche du marchand et l\'apporter à Nilith.', },
  },
  [3402] = {
    'Le Sous-marché',
    {'Je veux que vous informiez personnellement Vizzklick à Gadgetzan de la défaite de Kovic. Il sera si heureux d\'apprendre sa mort qu\'il vous remettra sûrement une récompense.', },
    {'Parler à Vizzklick à Gadgetzan.', },
  },
  [3421] = {
    'Le voyage de retour',
    nil,
    nil,
  },
  [3441] = {
    'Châtiment divin',
    {'Écoutez mon récit, $Gaventurier:aventurière;.', },
    {'Écouter le récit de Kalaran Lamevent.', },
  },
  [3442] = {
    'La flamme parfaite',
    {'Vous avez pris la bonne décision, $N.|n|nNous devons frapper à l\'endroit où nous ferons le plus de mal : aux quatre tours de garde.|n|nLorsque les quatre tours seront en feu, nous pourrons lancer notre offensive avant même qu\'ils aient le temps de réagir.|n|nVous allez avoir besoin du bon outil pour incendier les tours. Et pour cet outil, nous devons trouver quelques ingrédients.|n|nApportez-moi quatre Cœurs des flammes, et quatre globes d\'Huile de golem, et je ferai naître la torche de flamme parfaite.|n|nVous devriez prendre tout d\'abord pour cibles les golems et les élémentaires de ces terres.', },
    {'Réunir 4 Cœurs des flammes et 4 globes d\'Huile de golem puis rapporter ces objets à Kalaran Lamevent.', },
  },
  [3443] = {
    'Forger le manche',
    {'Pour porter la flamme parfaite, nous aurons besoin d\'un manche et d\'une enveloppe. Vous devez tout d\'abord trouver un manche convenable.|n|nLes sous-chefs et les esclavagistes Sombrefer du Chaudron se servent d\'armes en thorium enchanté, un alliage extrêmement solide. Si vous m\'apportez huit dagues plaquées en thorium, je pourrai les fondre et utiliser le métal pour fabriquer le manche.', },
    {'Apporter 8 Dagues plaquées en thorium à Kalaran Lamevent.', },
  },
  [3444] = {
    'Le Cercle de pierres',
    {'J\'ai pénétré une fois dans les premières salles du Temple englouti. Le mal de ces lieux oppresse quiconque y entre. Je n\'ai réussi à trouver la sortie qu\'à grand-peine, ne progressant que difficilement à travers le limon qui recouvre à présent le sol. Je ne me souviens que d\'avoir trébuché dans une grande pièce circulaire, remplie de statues de serpents...|n|nJ\'ai récemment découvert une pierre ronde qui portait le même symbole de serpent gravé sur sa face. Je l\'ai fait envelopper et envoyer à mon atelier à Cabestan. Récupérez-la, et il se peut que je puisse vous en dire davantage.', },
    {'Récupérer le Cercle de pierres à l\'Atelier de Marvon Chercherivet à Cabestan.', },
  },
  [3445] = {
    'Le Temple englouti',
    {'J\'ai entendu parler d\'un endroit se trouvant profondément sous la surface de la terre, banni en ce lieu par de plus grandes puissances que je n\'aie jamais rencontrées.|n|nSi vous souhaitez en apprendre davantage sur cet endroit, le Temple englouti, partez à la recherche d\'un gobelin nommé Marvon Chercherivet. Il a étudié de nombreuses régions du monde, et aux dernières nouvelles, a quitté sa demeure à Cabestan pour étudier les ruines des trolls à Tanaris.|n|nJe vous souhaite bonne chance dans vos recherches, cela fait longtemps que personne ne l\'a vu.', },
    {'Trouver Marvon Chercherivet à Tanaris.', },
  },
  [3446] = {
    'Dans les profondeurs',
    {'J\'ai trouvé à l\'intérieur du temple une pièce circulaire avec six stèles, chacune étant une statue de serpent. La curiosité m\'amena à pousser l\'une d\'entre elles, simplement pour voir ce qui allait se passer. C\'était un piège, et l\'explosion m\'a presque emmené jusqu\'aux portes de la mort. Alors que je reposais là, sur le bord, je regardais en bas pour m\'apercevoir qu\'il y avait une autre statue dans la partie inférieure de la pièce : un autel si l\'on peut dire... Hakkar, je crois qu\'il s\'appelait comme ça.|n|nJe pense que cet autel est la clé du mystère : vous devez apporter ce symbole à cet autel du Temple englouti.', },
    {'Trouver l\'Autel d\'Hakkar dans le Temple englouti du marais des Chagrins.', },
  },
  [3447] = {
    'Le secret du cercle',
    {'Ma mémoire est brumeuse, mais je vais vous raconter ce dont je me souviens. Je crois que le cercle de statues situé dans le Temple englouti détient, malgré les dangers qui s\'y cachent, un secret permettant de découvrir un trésor encore plus important.|n|nJe pouvais activer une série de lumières depuis l\'autel principal. Il est possible que si vous parveniez à comprendre la signification de ces lumières, vous puissiez découvrir les mystères de cette pièce.|n|nJe vous mets quand même en garde, $N. De puissants maléfices protègent ces lieux. Il est probable que quoi que ce soit qui ait de la valeur soit gardé avec ferveur.', },
    {'Voyager jusqu\'au Temple englouti et découvrir le secret du cercle de statues.', },
  },
  [3448] = {
    'La transmission du fardeau',
    {'On m\'a récemment donné la responsabilité d\'étudier Azshara, un endroit autrefois magnifique que les elfes considéraient comme leur demeure. C\'était à l\'époque où ils pratiquaient la magie. Cet endroit est à présent plus dangereux que beau, mais cela ne nous empêche pas de retourner chaque pierre qui s\'y trouve pour découvrir des réponses sur notre passé.|n|nUn de mes compagnons du nom de Tymor m\'a proposé son aide pour étudier ce lieu, car il s\'intéresse particulièrement à de tels sujets.|n|nIl possède une petite demeure en ville, à droite du Hall des mystères.', },
    {'Parlez au mage Tymor à Forgefer.', },
  },
  [3449] = {
    'Les runes des Arcanes',
    {'Certains elfes vénéraient autrefois la magie tout autant qu\'Élune. Des mages, parmi les plus puissants, conçurent des runes et des tablettes citant les règles des arcanes et des aperçus de leurs découvertes. Ils les laissèrent dans des lieux publics pour que chacun puisse les méditer.|n|nJ\'aimerais beaucoup obtenir des reproductions de ces runes des ruines d\'Eldarath. J\'ai ici pour vous une trousse qui vous permettra d\'effectuer ces reproductions, mais il vous appartiendra de trouver ces runes. Faites attention quand même, la Ligue des Explorateurs n\'est pas la seule à s\'intéresser à Eldarath.', },
    {'À l\'aide de la Trousse de dessin, effectuer des reproductions de la Rune de Beth\'Amara, de la Rune de Jin\'yael, de la Rune de Markri, de la Rune de Sael\'hai, puis se diriger vers la petite île près de la Péninsule méridionale d\'Azshara et signaler au Pilote Xiggs Allumèche de venir les prendre.', },
  },
  [3450] = {
    'Une collecte facile',
    {'Je veux que les reproductions soient apportées à ma tour, mais il n\'est pas nécessaire que vous fassiez tout le chemin jusque là-bas. Je vais simplement les faire transporter par les airs depuis Azshara.|n|nXiggs Allumèche me doit un service ou deux et il sera bientôt dans le coin. On l\'a embauché pour surveiller la côte. Allez lui parler avant de partir. Il pourra vous donner un lance-fusée pour que vous puissiez lui envoyer un signal. Lorsque vous serez en possession des reproductions, dirigez-vous vers l\'endroit qu\'il vous indiquera et donnez-les-lui pour qu\'il puisse les emporter en toute sécurité jusqu\'à ma tour. Il devrait être au hangar du Quartier militaire.', },
    {'Parlez à Xiggs Allumèche à Forgefer.', },
  },
  [3451] = {
    'Signal de la récupération',
    {'Ah, ainsi Tymor vous envoie, hein ? Oui, je lui dois un service ou deux. Qu\'est-ce que c\'est ? Eh bien, quel diable est-ce là... Oui, je peux lui donner un coup de main avec ça. Vous aurez besoin d\'un lance-fusée et d\'un lieu de rendez-vous… c\'est simple.|n|nNous avons construit un site d\'atterrissage sur une petite île au large de la péninsule au sud d\'Azshara. Prenez ce lance-fusée, et utilisez-le là-bas. Je verrai votre signal et viendrai récupérer la marchandise... quoi que ce soit.', },
    {'Parlez à Xiggs Allumèche à Forgefer pour obtenir un Lance-fusée standard.', },
  },
  [3452] = {
    'L\'enveloppe de la flamme',
    {'Nous avons besoin d\'une dernière pièce pour former la torche.|n|nVous trouverez un grand campement du Marteau du crépuscule dans les montagnes au nord-ouest. La rumeur dit qu\'ils portent des symboles et des idoles afin de rendre hommage à leur dieu. Il se peut que ces symboles et ces idoles portent en eux suffisamment d\'enchantement pour former une enveloppe magique. Apportez un seul symbole de Ragnaros et je tenterai d\'en extraire la magie pour créer l\'enveloppe de la flamme.', },
    {'Trouver et apporter un Symbole de Ragnaros à Kalaran Lamevent.', },
  },
  [3453] = {
    'La Torche de vindicte',
    {'Laissez-moi un moment afin que je combine les différentes parties et que j\'y applique les enchantements nécessaires.', },
    {'Attendre que Kalaran Lamevent termine la Torche de vindicte.', },
  },
  [3454] = {
    'La Torche de vindicte',
    {'La torche doit à présent être liée à $Gson:sa; propriétaire. Prenez-la, $N !', },
    {'Prendre la Torche de vindicte.', },
  },
  [3461] = {
    'Le retour auprès de Tymor',
    {'Tymor ne m\'a rien donné avec lequel je puisse vous payer, aussi je suggère que vous abordiez le sujet directement avec lui lorsque vous retournerez à Forgefer. Il est certain qu\'il occupe toujours la même place dans la Garde mystique. Frappez simplement à sa porte et assurez-vous qu\'il vous rétribue correctement. Cela n\'aura rien d\'un pique-nique... c\'est sûr...|n|nMerci encore pour l\'aide que vous lui avez apportée cependant, et bonne chance.|n|nÀ propos, je n\'ai plus besoin de la trousse de dessin. Pourquoi ne la rapporteriez-vous pas à Tymor lorsque vous irez le voir ?', },
    {'Rapporter la Trousse de dessin du mage Tymor au mage Tymor, à Forgefer.', },
  },
  [3462] = {
    'Ecuyer Maltrake',
    {'Adressez-vous à mon représentant, l\'écuyer Maltrake. Il vous en apprendra davantage sur l\'utilisation de la Torche de vindicte.', },
    {'Parler à l\'écuyer Maltrake.', },
  },
  [3463] = {
    'Allumer le feu !',
    {'Écoutez bien, $N. Bien que les quatre tours ne puissent jamais être détruites, vous pouvez vous servir de la torche de châtiment afin d\'y mettre le feu pour une longue période. Un incendie qu\'aucun élément ou qu\'aucune force ne pourra éteindre.|n|nTant qu\'elles seront en flammes, aucun garde ou aucune sentinelle ne pourra y résider. Ainsi, leur première ligne de défense n\'existera simplement plus.|n|nVous devez pénétrer dans chaque tour et utiliser la Torche de vindicte à l\'intérieur des fortifications. Méfiez-vous des guetteurs des Sombrefers, $N.', },
    {'Mettre le feu aux Tours de garde nord, sud, est et ouest en utilisant la Torche de vindicte à l\'intérieur de chaque tour.', },
  },
  [3481] = {
    'Bibelots...',
    {'Le coffre a l\'air fermé.', },
    {'Ouvrir le coffre.', },
  },
  [3482] = {
    nil,
    {'C\'est la version de la quête de la Boîte noire pour la Horde.', },
    {'Porter la boîte à Kravel.', },
  },
  [3483] = {
    'Signal de la récupération',
    nil,
    nil,
  },
  [3501] = {
    'Tout se compte en grandes quantités',
    {'Même si vous ne pourrez jamais trouver une sphère de draenéthyste sans défaut, vous découvrirez sans doute divers fragments imparfaits de draenéthyste en explorant ces terres.|n|nJe doute que Kum\'isha puisse les utiliser pour rentrer à la maison mais ils peuvent avoir une autre utilité pour les draeneï.|n|nApportez tous les fragments imparfaits de draenéthyste que vous pourrez et je vous récompenserai.', },
    {'Apporter des Fragments imparfaits de draenéthyste à Kum\'isha et toucher une récompense pour chaque fragment rapporté.', },
  },
  [3502] = {
    'Au rebut pour les draeneï…',
    {'Eh bien, après cette démonstration d\'avidité vorace, j\'ai la nausée.|n|nCela dit, je ne vais pas m\'étendre trop longtemps sur votre penchant.|n|nPour chaque fragment imparfait de draenéthyste que vous m\'apporterez, je vous récompenserai avec le même genre d\'affaires bonnes pour le rebut. Mon tas d\'affaires va diminuer tandis que le vôtre va devenir de plus en plus lourd. Sur Draenor, nous appelons cela une situation « gagnant-gagnant ».', },
    {'Apportez des Fragments imparfaits de draenéthyste à Kum\'isha. N\'importe quel monstre des Terres Foudroyées peut détenir un fragment.', },
  },
  [3503] = {
    'Réunion avec le Maître',
    nil,
    nil,
  },
  [3504] = {
    'Trahison',
    {'Une traîtresse, une voleuse ! C\'est ce qu\'elle sera toujours !|n|nJ\'ai fait une grave erreur, $N. J\'ai fait confiance à un elfe de sang. Pire, à UNE elfe de sang !|n|nElle prétendait qu\'Azshara renfermait de grandes richesses... de puissants objets. Je n\'avais qu\'à envoyer quelques guerriers avec elle pour la protéger et j\'en serais récompensé. Que j\'ai été bête... Elle les a tous tués.|n|nJe réclame vengeance, $N, mais je ne peux pas envoyer quelqu\'un d\'autre. Allez voir Ag\'tor à Valormok, au nord du campement des Haldarr. Il vous en dira plus.', },
    {'Apporter la Lettre scellée à Ag\'tor Poing-de-sang en Azshara.', },
  },
  [3505] = {
    '[PÉRIMÉ 4.x]Trahison',
    {'J\'ai réfléchi.|n|nNous commençons notre croisade contre ses ouvriers au sud des falaises de la péninsule du nord d\'Azshara. Tuez-les avec une colère sanglante, qu\'ils sachent le prix de la trahison.|n|nNe vous occupez pas d\'elle pour l\'instant : elle passe son temps en Azshara avec ses gardes du corps. Une fois ses ouvriers morts, il faudra trouver son campement personnel et faire une reconnaissance du terrain avant de l\'attaquer. Nous trouverons peut-être quelque chose à utiliser pour la provoquer.', },
    {'Tuer 10 Vengeurs elfes de sang et 10 Géomètres elfes de sang avant de rechercher le campement du magus Rimtori. Une fois le camp trouvé, chercher quelque chose d\'important pour elle et qui peut être utilisé pour l\'obliger à se battre.', },
  },
  [3506] = {
    'Trahison',
    {'Quelques instants de réflexion vous donnent des idées, dont une vous fait sourire : la destruction des cristaux suffira peut-être à provoquer l\'elfe de sang responsable du meurtre de tant d\'orcs et de la trahison dont a été victime Belgrom ?|n|nVous continuez à déchiffrer le texte et les images du livre et vous rendez compte que l\'un des cristaux est lié au créateur du cercle ; les autres sont liés à quelque chose de beaucoup plus sinistre.|n|nVous fermez le livre et commencez à chercher quel cristal détruire.', },
    {'Détruire le Cristal de focalisation des arcanes lié au magus Rimtori et l\'assassiner ensuite. Puis apporter la tête du magus Rimtori à Ag\'tor Poing-de-sang en Azshara.', },
  },
  [3507] = {
    '[PÉRIMÉ 4.x]Trahison',
    {'Retournez voir Belgrom à Orgrimmar. Il voudra voir sa tête de ses yeux ! Nous reviendrons bientôt.|n|nAh, c\'est en effet une bonne journée. Merci pour votre aide, $N.', },
    {'Aller voir Belgrom Cogneroche à Orgrimmar.', },
  },
  [3508] = {
    'Briser l\'Amulette',
    {'Vous êtes téméraire, $N. C\'est une qualité admirable de votre espèce, le fait de foncer aveuglément dans la bataille alors qu\'il n\'y a aucune chance de succès, ou si peu. Je vous aiderai, ne serait-ce que pour voir tomber un seul des sbires de Razelikh.|n|nBriser la tutelle de Razelikh sur ses subalternes va prendre du temps et nécessitera l\'utilisation d\'artéfacts rares.|n|nNe bougez plus, je dois commencer le rituel de Lumière. L\'information que j\'en tirerai m\'aidera à façonner des armes de grand pouvoir.', },
    {'Attendre que Loramus ait achevé le rituel de Lumière.', },
  },
  [3509] = {
    'Le nom de la bête',
    {'Il n\'y a qu\'une façon de nuire au seigneur démon et à ses sbires. Il faut forger une arme qui portera son véritable nom.|n|nSi nous parvenons à forger une telle arme, le démon et toute sa clique seront vulnérables.|n|nUn autre seigneur se trouve en Azshara, le seigneur Arkkoroc. Vous devez aller le trouver, mais attention, ses sbires n\'hésiteront pas à vous éliminer s\'ils vous découvrent.|n|nVous aurez certainement un prix à payer pour cette information.', },
    {'Aller voir le seigneur Arkkoroc en Azshara. Commencer la recherche au bord de l\'eau pour trouver le temple d\'Arkkoran.', },
  },
  [3510] = {
    'Le nom de la bête',
    {'Elle tue mes enfants, $Gmortel:mortelle;. Celle qui se proclame souveraine de ces océans. Une fausse déesse, rien de plus. Écrasez-la et apportez-moi chacune de ses têtes.|n|nEn échange, vous obtiendrez le nom que vous cherchez et autre chose, d\'importance égale.|n|nElle rôde sur la couvée... Elle se nomme Hetaera.|n|n<Le seigneur Arkkoroc désigne le sud-ouest.>|n|nAllez-y !', },
    {'Assassiner Hetaera et apporter la Tête ensanglantée d\'Hetaera, la Tête battue d\'Hetaera et la Tête meurtrie d\'Hetaera au seigneur Arkkoroc.', },
  },
  [3511] = {
    'Le nom de la bête',
    {'Comme promis, je vais vous révéler le nom du seigneur-démon : Razelikh le Souilleur. Mais tout d\'abord, je dois préparer quelque chose de la plus grande importance pour votre voyage.|n|nL\'arme que vous cherchez à confectionner nécessite une trempe particulière. Laissez-moi quelques instants pour vider le sang de ces têtes.|n|n<Le seigneur Arkkoroc presse les têtes entre ses gigantesques poings, exprimant ainsi tout le sang.>|n|nApportez la trempe à Loramus, ainsi que le nom de la bête : Rakh\'likh.', },
    {'Rapporter le durcisseur à Loramus Thalipedes.', },
  },
  [3512] = {
    'Par les mots d\'Eranikus',
    {'$N, nous devons d\'abord inventer une méthode pour parler à Eranikus par l\'intermédiaire de la gemme. Il se trouve entre le sommeil et la mort, dans un enfer de cauchemars. Même si l\'essence que vous m\'avez donnée est infectée, nous avons une chance de l\'atteindre.|n|nVous devez aller jusqu\'aux terres glacées de l\'est du Berceau-de-l\'Hiver et chercher un de nos alliés mortels, l\'implorateur d\'esprits Umbranse. Il parle aux morts. Quoiqu\'Eranikus ne soit pas vraiment mort, il pourra peut-être nous aider.', },
    {'Rendez-vous dans la partie orientale du Berceau-de-l\'Hiver et allez voir Umbranse l\'implorateur d\'esprit.', },
  },
  [3513] = {
    'Le Parchemin runique',
    {'Ce parchemin à l\'air très officiel est fermement entouré d\'un ruban argenté. Vous pensez que ça intéresserait sûrement quelqu\'un de le voir, mais qui ?|n|nIl y a un avant-poste au nord de la frontière d\'Orneval et si l\'information sur ce rouleau concerne les elfes de la nuit, c\'est le bon endroit pour l\'apporter.', },
    {'Apporter le Parchemin runique à la tour de garde Nord dans les Tarides.', },
  },
  [3514] = {
    'Présence de la Horde',
    {'Ce parchemin vient de la dryade rusée nommée Rynthariel, Maître des clés de l\'antre des Serres, au pic des Serres-Rocheuses.|n|nElle ne pourra plus contacter la personne sur qui vous l\'avez pris, hein ? Mais nous devons renforcer notre position. La Horde ne tolérera pas qu\'on lui dispute ces lieux.|n|n$N, partez pour l\'antre des Serres. Tuez Rynthariel, et placez un symbole que tous pourront voir et comprendre. Prenez le drapeau de la Horde, $N. Hissez-le dans l\'antre des Serres, qu\'ils n\'aient pas la témérité d\'envoyer un autre messager.', },
    {'Tuer le chef de l\'Antre des Serres, Rynthariel le Maître des clés.', },
  },
  [3517] = {
    'L\'art du vol',
    {'J\'admets avoir profité de ma situation en Azshara, $N. La punition de Belgrom a eu de bons côtés.|n|nJ\'y ai fait des recherches et vous seriez $Gétonné:étonnée; de voir combien il y a d\'objets de valeur ici.|n|nJe vous en dirai plus sur mes affaires et vous ferai participer aux profits, si vous m\'aidez à les récupérer.|n|nJ\'ai besoin de tablettes disposées partout dans les ruines d\'Eldarath, à l\'est d\'ici. Les quatre portent le nom de sorciers bien-nés. Trouvez-les pour moi et nous discuterons.', },
    {'Trouver la Tablette de Beth\'Amara, la Tablette de Jin\'yael, la Tablette de Markri et la Tablette de Sael\'hai puis retourner voir Jediga en Azshara.', },
  },
  [3518] = {
    'Livraison à Magatha',
    {'La première tablette va à une taurène... Elle s\'appelle Magatha. Elle se trouve parmi les anciens aux Pitons-du-Tonnerre et elle est l\'un des partisans de l\'alliance entre les taurens et les Réprouvés. Plus que n\'importe lequel des anciens, elle sent que les taurens et leurs connaissances peuvent aider les Réprouvés à redevenir des hommes.|n|nApportez-lui la Tablette de Beth\'Amara. La tablette est peut-être le lien dont elle a besoin pour aider les Réprouvés... ou du moins c\'est ce qu\'elle dit.', },
    {'Apportez la Tablette de Beth\'Amara à Magatha aux Pitons-du-Tonnerre.', },
  },
  [3519] = {
    'Un ami dans le besoin',
    {'Ahhh... J\'ai été mordu par une araignée nommée Githyiss la Vile en explorant sa caverne, tout près d\'ici. Une grande quantité de poison m\'a été injectée ; vous devez m\'aider.|n|nPrévenez Dirania Brillargent. Elle sera capable de me secourir.|n|nVite... J\'ai des vertiges de plus en plus alarmants...', },
    {'Allez Dirania Brillargent, au Sombrevallon.', },
  },
  [3520] = {
    'Esprits de Hurleurs',
    {'Je cherche les esprits des hurleurs des vallées de Féralas. Ils sont cousins d\'un dieu fort ancien et leurs esprits lui sont liés.|n|nPrenez ce roncier magique et allez en Féralas pour y trouver les hurleurs des vallées, au sud et au centre. Tuez-les, puis agitez ma baguette au-dessus d\'eux. Cela exhortera leur esprit à se révéler. Touchez les esprits et prenez leur essence.|n|nRevenez me voir avec ma baguette et les esprits et je vous en dirai plus de ce dieu ancien dont je vous ai parlé.', },
    {'Capturer l\'Esprit de 3 Hurleurs en Féralas, puis retourner voir Yeh\'kinya à Port Gentepression.', },
  },
  [3521] = {
    'Antidote d\'Iverron',
    {'Je m\'inquiète beaucoup pour mon ami Iverron. Il est parti depuis près d\'une journée, et j\'ai peur qu\'il ait été empoisonné… ou pire.|n|nJe veux que vous récupériez les composants nécessaires à la fabrication d\'un antidote, juste au cas où.|n|nCueillez des champignons jacinthe à la base des arbres, les lys pétales de lune près de l\'eau, et de l\'ichor d\'araignée Tissebois sur l\'une de ces créatures, au nord.|n|nMême s\'il a été empoisonné, les mélanger pour préparer l\'antidote ne devrait pas vous poser de problèmes. Il est parti vers le nord, en direction de la grotte de Sombrefil. Avec un peu de chance, vous pourrez l\'y trouver.', },
    {'Collectez 7 Champignons jacinthe, 4 Lys pétales de lune et 1 Ichor d\'araignée Tissebois.', },
  },
  [3522] = {
    'Antidote d\'Iverron',
    {'L\'antidote est prêt, $N. Faites en sorte qu\'Iverron le boive.|n|nVous devez savoir une chose : l\'antidote ne reste efficace que pendant 5 minutes. Vous devez le lui apporter à temps.|n|nQue la vitesse soit avec vous, $N.', },
    {'Apporter l\'Antidote d\'Iverron à Iverron avant que la limite de temps ne soit atteinte. Iverron se trouve près de la grotte, au nord.', },
  },
  [3523] = {
    'Le Fléau des Souilles',
    {'Remarquable ! Mon nom est Belnistrasz et je vous remercie de m\'avoir secouru. Je me voyais déjà mort... ou pire, transformé en repas pour cette vermine infestée par le Fléau. Oui, j\'ai dit le Fléau à dessein : ici, ils ont négocié une sorte d\'accord avec les hurans et ce cauchemar en est le résultat.|n|nÉcoutez, plutôt que de fuir, voulez-vous m\'aider à en finir ? C\'est probablement dangereux, mais vous semblez être du genre à ne pas vous inquiéter pour si peu.', },
    {'Pour aider Belnistrasz, lui parler de nouveau et lui rendre la Pierre de voeu qu\'il vous avait donnée.', },
  },
  [3524] = {
    'Échouage',
    {'De majestueuses créatures marines se jettent sur le littoral de Sombrivage, où elles restent échouées jusqu\'à leur mort. Dernièrement, le nombre de ces bêtes n\'a cessé d\'augmenter. C\'est le temple de la Lune qui m\'envoie pour enquêter, mais la présence des murlocs, sur le littoral, a freiné mes recherches.|n|nIl y a une créature géante échouée au sud d\'Auberdine, et beaucoup de ces maudits murlocs grisebrumes aux alentours. Pourriez-vous aller récupérer des os sur la carcasse de cette créature ? Ils nous serviront pour nos études.', },
    {'Récupérer des Os de créature marine sur la créature échouée, au sud d\'Auberdine, puis les apporter à Gwennyth Bly\'Leggonde, à Auberdine.', },
  },
  [3525] = {
    'L\'extinction de l\'idole',
    {'Près de l\'entrée, il y a une idole qui sert de four aux hurans, ces bêtes... ils consument ceux qu\'ils enlèvent dans les Tarides. Je peux faire en sorte qu\'ils ne puissent plus jamais s\'en servir, mais j\'ai besoin de votre aide. Voici mon plan : escortez-moi jusqu\'à l\'idole, quand nous arriverons, je commencerai le rituel. Pendant ce temps, je ne pourrai pas communiquer avec vous et encore moins me défendre. Protégez-moi pendant que je détruis l\'idole. S\'ils parviennent à m\'abattre, tout est fini.|n|nÊtes-vous avec moi ?', },
    {'Escorter Belnistrasz jusqu\'à l\'Idole des hurans dans les Souilles de Tranchebauge.|n|nProtéger Belnistrasz tandis qu\'il exécute le rituel pour arrêter l\'idole.', },
  },
  [3526] = {
    'Ingénierie des gobelins',
    {'La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. L\'Ingénierie des gobelins est clairement le choix de tous les ingénieurs brillants. Apprendre à vaincre le monde par l\'utilisation judicieuse d\'explosifs et d\'incroyables mécanismes !|n|n$N, lisez ce manuel. Si vous voulez en apprendre plus, apportez-le à Nixx Elastirouage à Gadgetzan. Mais attention : l\'adhésion à cette discipline est définitive et exclusive, alors soyez $Gsûr:sûre; de faire le bon choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gobeline, apporter le Manuel d\'Ingénierie à Nixx Elastirouage dans Gadgetzan.', },
  },
  [3527] = {
    'La prophétie de Mosh\'aru',
    {'La prophétie ancienne de Mosh\'aru explique comment contenir l\'essence du dieu Hakkar. Elle a été écrite sur deux tablettes, apportées à la cité trolle de Zul\'Farrak, à l\'ouest de Gadgetzan.|n|nApportez-moi les tablettes Mosh\'aru !|n|nLa première tablette est détenue par le troll Theka le Martyr, mort depuis longtemps. On raconte que ses bourreaux ont été changés en scarabées et qu\'ils parcourent à présent son autel.|n|nLa seconde tablette est détenue par l\'hydromancienne Velratha, près du bassin sacré de Gahz\'rilla.|n|nUne fois que vous aurez les tablettes, apportez-les-moi.', },
    {'Apportez les Première et Deuxième tablettes Mosh\'Aru à Yeh\'kinya, à Tanaris.', },
  },
  [3528] = {
    'Le dieu Hakkar',
    {'Maintenant il faut capturer l\'essence de l\'avatar d\'Hakkar.|n|nApportez l\'Œuf d\'Hakkar au Sanctuaire du dieu déchu dans le Temple englouti d\'Azeroth. Invoquez le pouvoir de l\'œuf pour réveiller le dieu mort.|n|nIl enverra ses sbires contre vous. Combattez-les et prenez leur sang hakkari, puis versez-le sur les flammes éternelles qui retiennent l\'esprit d\'Hakkar. Une fois les flammes éteintes, l\'avatar d\'Hakkar entrera dans notre monde.|n|nCombattez-le et placez son essence dans l\'œuf d\'Hakkar.', },
    {'Apportez l\'Œuf d\'Hakkar rempli à Yeh\'kinya dans Tanaris.', },
  },
  [3541] = {
    'Livraison pour Jes\'rimon',
    {'J\'ai un copain à Orgrimmar. Il réside dans la rue principale. Il est difficile à trouver si vous ne savez pas où regarder, mais allez voir dans les bâtiments les plus hauts et vous devriez sans peine tomber sur lui.|n|nFaites-moi une faveur, n\'allez pas répéter à tout Kalimdor qu\'il est là : ce serait mauvais pour lui comme pour moi.|n|nIl nous donnera un prix plus qu\'honnête pour la Tablette de Jin\'yael. Je ne sais pas pourquoi, mais vous auriez dû voir comme il était excité quand je lui en ai parlé.', },
    {'Apportez la Tablette de Jin\'yael à Jes\'rimon à Orgrimmar.', },
  },
  [3542] = {
    'Livraison à Andron Gant',
    {'Andron Gant est mon contact suivant. Il se terre habituellement à Fossoyeuse, tout près de l\'Apothicarium.|n|nQuand il est venu me voir, il était plus loquace qu\'à l\'ordinaire et il m\'a dit pourquoi il voulait la Tablette. Apparemment, des mages de Fossoyeuse veulent étudier certains des charmes mystérieux que les Bien-nés utilisaient. Ils pensent que cette tablette les y aidera. Markri était expert en invocation de créatures, surtout des élémentaires.|n|nApportez la Tablette de Markri et revenez me voir pour votre récompense.', },
    {'Apportez la Tablette de Markri à Andron Gant à Fossoyeuse.', },
  },
  [3561] = {
    'Livraison à l\'archimage Xylem',
    {'Cette dernière tablette est destinée à quelqu\'un de très dangereux, $N. Croyez-moi, je lui fais encore moins confiance qu\'aux autres.|n|nL\'archimage Xylem habite une tour en haut des collines qui entourent Azshara. Il est humain, mais il agit comme aucun autre humain que j\'aie jamais rencontré... ou tué. La puissance se dégage de tout son être et je n\'ose lui demander ce qu\'il veut faire de la tablette.|n|nIl est venu me voir, mais il m\'a dit que son garde du corps Sanath m\'aiderait à parvenir à la tour lorsque je serais prête à le rencontrer. Partez au nord à la recherche de Sanath.', },
    {'Apportez la Tablette de Sael\'hai à l\'archimage Xylem en Azshara.', },
  },
  [3562] = {
    '[PÉRIMÉ]Le paiement de Magatha à Jediga',
    {'Portez cette note à Jediga. Dites-lui que son paiement l\'attendra à son retour. Et dites-lui que son travail est satisfaisant.|n|nFaites vite, $N. Dites à votre maîtresse que je l\'attendrai ici.', },
    {'Apporter la Note de Magatha à Jediga en Azshara.', },
  },
  [3563] = {
    'Le paiement de Jes\'rimon à Jediga',
    {'Portez cette lettre à Jediga. Faites-lui savoir qu\'notre accord a été rentable et qu\'son travail me satisfait.|n|nDites-lui d\'rev\'nir vite à Orgrimmar et qu\'Jes\'rimon y prendra bien soin d\'elle.|n|nDites-lui tout cela et j\'aurai p\'t-êt\' à nouveau b\'soin d\'vos services plus tard, $N.', },
    {'Apporter la Note de Jes\'rimon à Jediga en Azshara.', },
  },
  [3564] = {
    'Le paiement d\'Andron à Jediga',
    {'Ici... Portez... <hic> cela à Jediga. Bonne chance !', },
    {'Apporter la Note d\'Andron à Jediga en Azshara.', },
  },
  [3565] = {
    'Le paiement de Xylem à Jediga',
    {'Qu\'y a-t-il ? Oh oui, votre paiement. Bien sûr.|n|nPrenez ceci et partez. Je suis sûr que Jediga attend avec une grande, grande patience votre retour.', },
    {'Apporter la Note de Xylem à Jediga en Azshara.', },
  },
  [3566] = {
    'Debout, Obsidion !',
    {'C\'était... C\'était... C\'était un piège.|n|nPardonnez... moi.|n|nTuez ce traître… Tuez-le pour nous… pour Thorius.', },
    {'Assassiner Lathoric le Noir et Obsidion, puis retourner voir Thorius, à Forgefer, avec la Tête de Lathoric le Noir et le Cœur d\'Obsidion.', },
  },
  [3567] = {
    'Au sommet',
    nil,
    nil,
  },
  [3568] = {
    'Corruption suintante',
    {'Regardez cette taurène derrière moi, celle qui a l\'air de se trouver mal. Elle était en Azshara récemment. Elle affirme avoir été blessée par des nagas en traversant les ruines d\'Eldarath.|n|nAprès les avoir repoussés, elle s\'est reposée sur la plage et a bu dans l\'une des cuvettes de marée. Maintenant elle est malade.|n|nJe veux découvrir ce qu\'elle a bu. Prenez cette boîte, avec quelques fioles vides que j\'ai étiquetées. Remplissez chacune d\'elle dans une cuvette différente et revenez me voir.', },
    {'Avant de retourner voir le Chimiste Cuely, remplir les 4 Fioles vides dans les cuvettes de marées le long de la côte des Ruines d\'Eldarath, en Azshara.', },
  },
  [3569] = {
    'Corruption suintante',
    {'Donnez-le à Thersa. Peut-être que ça va guérir sa... Ou peut-être pas. Nous ne le saurons que lorsqu\'elle aura bu.', },
    {'Donner l\'élixir de Cuely à Thersa Chant-du-vent, à Fossoyeuse.', },
  },
  [3570] = {
    'Corruption suintante',
    nil,
    nil,
  },
  [3581] = {
    nil,
    {'Imaginez-vous en train de courir dans les plaines, les forêts et les montagnes, le visage dans le vent... De voyager en terres inconnues ; l\'étonnement de la découverte de la route, votre destin lié au seul horizon.|n|nDites-vous que sur un sabot, on peut réaliser beaucoup de choses ; en tant que tauren, vous bénéficierez de la rapidité de la Course dans les plaines. Il n\'y a aucune limite aux distances que vous pourrez parcourir.', },
    {'Retourner voir Saern Cours-avec-fierté pour apprendre la compétence de Course dans les plaines.', },
  },
  [3601] = {
    'Kim\'jael évidemment !',
    {'Kim\'jael, effectivement ! Savez-vous ce que Kim\'jael signifie chez les elfes de sang, $N ? Petit rat... ou quelque chose comme ça. Quels imbéciles !|n|nIls m\'ont embauché pour aider à reconnaître le secteur et pour chercher des genres de trésors perdus. Je me suis évidemment précipité lorsque j\'ai entendu le mot "trésor" et le montant qu\'ils allaient me payer, mais ils m\'ont bien entendu trahi et ont essayé de me tuer... MOI !|n|nC\'est pour vous dire, on ne peut jamais faire confiance à un elfe de sang.|n|nMaintenant, le problème, c\'est qu\'ils sont en possession de mon équipement et que je ne peux pas le récupérer. Vous voulez m\'aider ?', },
    {'Fouiller le Camp de base thalassien pour trouver la Boussole, la Lunette, le Poulet farci et le Wizzlegoober de Kim\'Jael, puis les lui rapporter en Azshara.', },
  },
  [3602] = {
    nil,
    {'Les anciens géants des falaises de la région du sud d\'Azshara se nourrissent de la roche et des constructions locales. Leurs excréments forment un cristal très malléable et extrêmement solide appelé azsharite.|n|nOn le trouve dans le Cercle du sud, mais on en récupère peu en raison du tempérament extrêmement violent des géants.|n|nVous devez aller au sud et récupérer suffisamment d\'azsharite pour créer le corps de l\'arme. Mes gangrechiens vous aideront à trouver le cristal.', },
    {'Trouvez 20 Azsharites cristallisées au sud d\'Azshara. Utilisez éventuellement le gangrechien pour « renifler » l\'emplacement où sont intelligemment cachés les dépôts.|n|nRetournez voir Loramus une fois votre tâche accomplie.', },
  },
  [3621] = {
    'La formation du gangreplaie',
    {'Les armes sont prêtes à être forgées. Vous devez apporter l\'azsharite trempée à quelqu\'un qui saura en exploiter l\'énergie.|n|nUn tel forgeron se trouve dans la vallée de Strangleronce. Galvan l\'Ancien, le chef de l\'ordre du Mithril, pourra fabriquer ces armes. Vous trouverez son campement entre Zul\'Gurub et le tertre des ogres mosh\'Ogg.|n|nPuissent votre détermination et votre foi vous porter dans cette épreuve. Si vous échouez, sachez que votre dieu vous regarde en souriant, $Gmortel:mortelle;.', },
    {'Apporter la cargaison à Galvan l\'Ancien dans la vallée de Strangleronce.', },
  },
  [3625] = {
    'Armes gangrenées en azsharite enchantée',
    {'$N, la création de chaque arme va prendre un peu de temps.|n|nDe plus, vous ne pourrez utiliser le pouvoir de la Malédiction gangreneuse qu\'une fois toutes les trois minutes. Ses propriétés d\'affaiblissement contre Razelikh le Souilleur et ses sbires peuvent varier dans la durée. C\'est pourquoi vous devez prendre garde d\'utiliser la Malédiction gangreneuse au bon moment !|n|nÀ présent, donnez-moi une minute pour terminer votre arme, $N.', },
    {'Attendre que Galvan ait fini de forger les armes.', },
  },
  [3626] = {
    'Retour dans les terres Foudroyées',
    {'L\'heure de la rédemption est proche, $N. Vous devez retourner dans les terres Foudroyées avec votre nouvel équipement et parler au Héros de la Horde tombé au combat pour recevoir votre objectif final.', },
    {'Retourner voir le Héros de la Horde tombé au combat, au Croisement de Lance-brisée, au Marais des Chagrins.', },
  },
  [3627] = {
    'Réunir les morceaux de l\'amulette brisée',
    {'Pour atteindre le Souilleur, vous devez d\'abord détruire la triade de pouvoir et récupérer les morceaux d\'amulette. Quand vous aurez récupéré les trois morceaux, revenez me voir et je vous donnerai de nouvelles instructions.|n|nAllez, $N ! Partez dans les terres Foudroyées ! Sevine, Allistarj et Grol doivent mourir !', },
    {'Assassiner Grol le Destructeur, dame Sevine et l\'archimage Allistarj. Prendre sur leurs cadavres l\'Amulette de Grol, l\'Amulette de Sevine et l\'Amulette d\'Allistarj.|n|nN\'oubliez pas d\'UTILISER vos armes gangrenées en azsharite enchantée pour affaiblir la triade (ils ne peuvent pas être tués autrement), mais faites-le sagement...', },
  },
  [3628] = {
    'Son nom est Rakh\'likh',
    {'Razelikh se terre sur la plus haute montagne des terres Foudroyées. Le seul moyen d\'y accéder est d\'utiliser les runes de téléportation près de la montagne. Tant que vous tenez l\'amulette, vous pouvez vous y transporter. Une fois là-bas, vous devez neutraliser la bête. L\'amulette est votre atout, $N. Utilisez-la sur l\'Autel du Souilleur.|n|nSi vous arrivez à le vaincre, prenez sa corne. Elle sera signe d\'espoir pour ceux qui la verront, la preuve que les héros existent dans ce monde déchiré par la guerre.', },
    {'Détruire Razelikh le Souilleur et apporter la Corne brisée du Souilleur au Héros de la Horde tombé au combat. Rendre aussi l\'Amulette du Souilleur au Héros pour qu\'il puisse la détruire, afin de l\'empêcher de tomber entre de mauvaises mains.', },
  },
  [3629] = {
    'Ingénierie des gobelins',
    {'L\'ingénierie pratiquée au niveau d\'expert connaît deux disciplines : celle des gnomes et celle des gobelins. Je ne mentionne l\'Ingénierie des gobelins que parce que je suis un Maître juste. Ils aiment faire des choses qui explosent et se soucient rarement des conséquences.|n|n$N, lisez ce manuel. Si vous voulez apprendre comment vous faire sauter, apportez-le à Nixx Elastirouage dans Gadgetzan. Mais le choix de cette discipline est définitif et exclut l\'autre, alors soyez $Gsûr:sûre; de votre choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gobeline, apporter le Manuel d\'Ingénierie à Nixx Elastirouage dans Gadgetzan.', },
  },
  [3630] = {
    'Ingénierie des gnomes',
    {'L\'ingénierie pratiquée à un niveau d\'expert connaît deux disciplines : celle des gnomes et celle des gobelins. L\'ingénierie gnome est de loin supérieure ! Elle consiste à construire de merveilleux dispositifs qui rendent la vie meilleure !|n|n$N, lisez ce manuel. Si vous voulez en apprendre plus sur l\'ingénierie gnome, apportez ce manuel au maître-artisan Suprétincelle dans Forgefer. Mais le choix de cette discipline est définitif et exclut l\'autre, alors soyez $Gsûr:sûre; de votre choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gnome, apporter le Manuel d\'Ingénierie au maître-artisan Suprétincelle, à Forgefer.', },
  },
  [3631] = {
    'Invoquer un Palefroi corrompu',
    {'Hum. À mon avis, vous n\'avez ni la force ni les compétences requises, mais cela ne me regarde pas puisque Strahad pense autrement, et que c\'est lui qui décide... cette fois.|n|nIl voudrait vous parler le plus vite possible. Vous le trouverez, avec ses acolytes, dans la petite tour qui domine Cabestan, dans les Tarides.|n|nNe traînez pas.', },
    {'Parlez à Strahad Farsan, dans les Tarides.', },
  },
  [3632] = {
    'Ingénierie des gnomes',
    {'L\'ingénierie pratiquée à un niveau d\'expert connaît deux disciplines : celle des gnomes et celle des gobelins. L\'ingénierie gnome est de loin supérieure ! Elle consiste à construire de merveilleux dispositifs qui rendent la vie meilleure !|n|n$N, lisez ce manuel. Si vous voulez en apprendre plus sur l\'ingénierie gnome, apportez ce manuel au maître-artisan Suprétincelle dans Forgefer. Mais le choix de cette discipline est définitif et exclut l\'autre, alors soyez $Gsûr:sûre; de votre choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gnome, apporter le Manuel d\'Ingénierie au maître-artisan Suprétincelle, à Forgefer.', },
  },
  [3633] = {
    'Ingénierie des gobelins',
    {'La meilleure ingénierie est représentée par deux disciplines : celle des gnomes et celle des gobelins. L\'Ingénierie des gobelins est clairement le choix de tous les ingénieurs brillants. Apprendre à vaincre le monde par l\'utilisation judicieuse d\'explosifs et d\'incroyables mécanismes !|n|n$N, lisez ce manuel. Si vous voulez en apprendre plus, apportez-le à Nixx Elastirouage à Gadgetzan. Mais attention : l\'adhésion à cette discipline est définitive et exclusive, alors soyez $Gsûr:sûre; de faire le bon choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gobeline, apporter le Manuel d\'Ingénierie à Nixx Elastirouage dans Gadgetzan.', },
  },
  [3634] = {
    'Ingénierie des gnomes',
    {'L\'ingénierie au niveau d\'expert connaît deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez vous spécialiser dans celle des gnomes. Ils fabriquent des objets et des gadgets qui se prétendent révolutionnaires, mais qui fonctionnent rarement.|n|n$N, lisez ce manuel. Si ça vous intéresse, apportez-le au maître-artisan Suprétincelle dans Forgefer. Mais le choix de cette discipline est définitif et exclut l\'autre, alors soyez $Gsûr:sûre; de votre choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gnome, apporter le Manuel d\'Ingénierie au maître-artisan Suprétincelle, à Forgefer.', },
  },
  [3635] = {
    'Ingénierie des gnomes',
    {'L\'ingénierie au niveau d\'expert enseigne deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez connaître celle des gnomes. Ils fabriquent des objets et des gadgets pour prétendument changer le monde, mais ils fonctionnent rarement.|n|n$N, lisez ce manuel. Si ça vous intéresse, apportez-le à Orguignard Odipnoticus à Baie-du-Butin. Mais attention : l\'adhésion à cette discipline est définitive et exclusive, alors soyez $Gsûr:sûre; de faire le bon choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gnome, apporter le Manuel d\'Ingénierie à Orguignard Odipnoticus à Baie-du-Butin.', },
  },
  [3636] = {
    'Apportez la Lumière',
    {'Le Fléau est une menace persistante pour l\'Alliance, vous le savez fort bien. Récemment, nous avons découvert quelque chose, $N.|n|nDans les Tarides, il y a un amas de ronces, les Souilles de Tranchebauge. C\'était autrefois la demeure de hurans normaux, mais maintenant un pacte y a été fait avec le Fléau, pour créer des créatures beaucoup plus mauvaises... Elles sont gouvernées par la liche Amnennar, dite le Porte-froid.|n|nSoyez le porte-parole de la Lumière, $N ; mettez fin à cette mauvaise union.', },
    {'Tuer Amnennar le Porte-froid, aux Souilles de Tranchebauge, pour l\'Archevêque Benedictus.', },
  },
  [3637] = {
    'Ingénierie des gnomes',
    {'L\'ingénierie au niveau d\'expert enseigne deux disciplines : celle des gnomes et celle des gobelins. Bien que ce soit du gâchis à mon sens, vous devriez connaître celle des gnomes. Ils fabriquent des objets et des gadgets pour prétendument changer le monde, mais ils fonctionnent rarement.|n|n$N, lisez ce manuel. Si ça vous intéresse, apportez-le à Orguignard Odipnoticus à Baie-du-Butin. Mais attention : l\'adhésion à cette discipline est définitive et exclusive, alors soyez $Gsûr:sûre; de faire le bon choix !', },
    {'Pour en apprendre davantage sur l\'ingénierie gnome, apporter le Manuel d\'Ingénierie à Orguignard Odipnoticus à Baie-du-Butin.', },
  },
  [3638] = {
    'Le Vœu du secret',
    {'L\'ingénierie des gobelins traite de l\'utilisation pratique des explosifs ! Nos schémas nous permettent de faire des bombes et des armes puissantes ; c\'est le thème du manuel que vous lisez.|n|nDepuis toujours, ce manuel est lié par un Vœu du secret couvrant tous nos schémas. Une fois que vous serez Ingénieur gobelin, vous ne pourrez plus accéder à l\'Ingénierie des gnomes. Si vous voulez toujours devenir Ingénieur gobelin, signez ce document vous engageant au secret et revenez me voir. Réfléchissez soigneusement, $N.', },
    {'Pour devenir un Ingénieur gobelin, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Nixx Elastirouage dans Gadgetzan.', },
  },
  [3639] = {
    'Montrez votre travail',
    {'Cette lueur dans vos yeux me dit tout ce que j\'ai besoin de savoir : vous voulez faire sauter des trucs. Vous êtes un ingénieur habile, $N, mais la question n\'est pas là. Je veux analyser votre travail pour orienter vos efforts futurs dans une direction plus… gobeline. J\'ai besoin des échantillons suivants : 20 grandes bombes en fer, 20 bâtons de dynamite solide et 5 moutons explosifs – avec leurs crans de sûreté armés, merci.|n|nSoumettez-moi vos réalisations et je ferai de vous un ingénieur gobelin officiel !', },
    {'Apporter 20 Grandes bombes en fer, 20 Dynamites solides et 5 Moutons explosifs à Nixx Elastirouage dans Gadgetzan.', },
  },
  [3640] = {
    'Le Vœu du secret',
    {'L\'ingénierie des gnomes consiste à mettre en forme la théorie de l\'ingénierie pour servir nos besoins ! Nos schémas nous permettent de construire des appareils contrôlant le monde qui nous entoure. Le manuel que vous avez lu traite de ce sujet.|n|nIl traite également du Vœu du secret qui recouvre nos schémas. Lorsque vous adhérez à l\'Ingénierie des gnomes, vous ne pouvez plus revenir en arrière. Vous ne pourrez jamais plus accéder à l\'Ingénierie des gobelins.|n|nSi vous souhaitez toujours devenir Ingénieur gnome, signez ce document qui vous engage à garder le secret à vie et revenez me parler. Prenez votre décision après mûre réflexion, $N.', },
    {'Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore le maître-artisan Suprétincelle, à Forgefer.', },
  },
  [3641] = {
    'Montrez votre travail',
    {'Si vous vous sentez $Gprêt:prête; à fabriquer des objets vraiment faramineux, vous êtes au bon endroit. Je vois bien que vous êtes déjà un ingénieur compétent. Cependant, je souhaite analyser votre travail pour savoir comment introduire les techniques gnomes dans vos travaux futurs. J\'ai besoin des échantillons suivants : six tubes en mithril, une lunette de précision et deux leurres perfectionnés.|n|nSoumettez-moi ces objets et je ferai de vous un ingénieur gnome officiel, ayant accès à tous les schémas !', },
    {'Apportez 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés au Maître-bricoleur Suprétincelle, à Forgefer.', },
  },
  [3642] = {
    'Le Vœu du secret',
    {'L\'ingénierie des gnomes consiste à mettre en forme la théorie de l\'ingénierie pour servir nos besoins ! Nos schémas nous permettent de construire des appareils contrôlant le monde qui nous entoure. Le manuel que vous avez lu traite de ce sujet.|n|nIl traite également du Vœu du secret qui recouvre nos schémas. Lorsque vous adhérez à l\'Ingénierie des gnomes, vous ne pouvez plus revenir en arrière. Vous ne pourrez jamais plus accéder à l\'Ingénierie des gobelins.|n|nSi vous souhaitez toujours devenir Ingénieur gnome, signez ce document qui vous engage à garder le secret à vie et revenez me parler. Prenez votre décision après mûre réflexion, $N.', },
    {'Pour devenir un Ingénieur gnome, cliquer avec le bouton droit sur le Vœu de secret et retourner voir une fois encore Oglethrope Odipnoticus à Baie-du-Butin.', },
  },
  [3643] = {
    'Montrez votre travail',
    {'Si vous vous sentez $Gprêt:prête; à fabriquer des objets vraiment faramineux, vous êtes au bon endroit. Je vois bien que vous êtes déjà un ingénieur compétent. Cependant, je souhaite analyser votre travail pour savoir comment introduire les techniques gnomes dans vos travaux futurs. J\'ai besoin des échantillons suivants : six tubes en mithril, une lunette de précision et deux leurres perfectionnés.|n|nSoumettez-moi ces objets et je ferai de vous un ingénieur gnome officiel, ayant accès à tous les schémas !', },
    {'Apportez 6 Tubes en mithril, 1 Lunette de précision et 2 Leurres perfectionnés à Orguignard Odipnoticus à Baie-du-Butin.', },
  },
  [3644] = {
    'Le renouvellement de la Carte de membre',
    nil,
    nil,
  },
  [3645] = {
    'Le renouvellement de la Carte de membre',
    nil,
    nil,
  },
  [3646] = {
    'Le renouvellement de la Carte de membre',
    nil,
    nil,
  },
  [3647] = {
    'Le renouvellement de la Carte de membre',
    nil,
    nil,
  },
  [3661] = {
    'Dans les faveurs d\'Élune ?',
    {'Les indomptables sont des créatures tout à fait imprévisibles, $N. Capables d\'une douceur incroyable, elles sont féroces si on menace ce qui est important à leurs yeux.|n|nOn dit que ces bêtes auraient été créées par Élune, et j\'aimerais savoir si c\'est vraiment le cas.|n|nJ\'ai récemment entendu parler d\'une population d\'indomptables vivant dans les Hinterlands ; des chouettards vicieux, des chouettards primitifs et des chouettards sauvages. Ils hantent les terres sauvages, là-bas. Pourriez-vous aller collecter quelques-unes de leurs plumes pour moi ?', },
    {'Collecter 15 Plumes d\'Indomptable dans les Hinterlands, pour Erelas Ambreciel au village de Rut\'theran.', },
  },
  [3681] = {
    'Tome de divinité',
    {'Il me navre d\'interrompre vos voyages, $R, mais je pense que vous serez $Gintéressé:intéressée; d\'apprendre que Hurlevent a récemment envoyé un message disant que tous les paladins devaient s\'y rendre pour y être entraînés.|n|nSi je n\'en savais pas plus, je dirais que vous êtes sur le point d\'atteindre un certain stade et qu\'il est temps pour vous de commencer l\'étude des Tomes.|n|nCherchez Duthorian Rall à Hurlevent. D\'habitude, il enseigne aux paladins dans la cathédrale de la Lumière.', },
    {'Parler à Duthorian Rall à Hurlevent.', },
  },
  [3701] = {
    'Les ruines fumantes de Thaurissan',
    {'Rendez-vous dans les ruines fumantes de Thaurissan, dans les steppes Ardentes, et réunissez autant de renseignements que possible.|n|nOn raconte que de mystérieuses reliques jonchent les ruines. Peut-être devriez-vous commencer vos recherches par elles, $N. Attention aux gardiens de Thaurissan. Ces assassins veillent à ce que les secrets qui y sont enfouis ne s\'échappent pas.', },
    {'Allez dans les ruines de Thaurissan, dans les Steppes Ardentes. Récupérez des informations sur les Reliques de Thaurissan, puis retournez auprès de l\'Historienne royale Archesonus.', },
  },
  [3702] = {
    'Les ruines fumantes de Thaurissan',
    {'Est-ce que vous aimeriez entendre une petite histoire sur les nains sombrefers ?', },
    {'Écouter l\'historienne royale Archesonus raconter l\'histoire de Thaurissan.', },
  },
  [3721] = {
    'Un OOX rien que pour vous',
    nil,
    nil,
  },
  [3741] = {
    'Collier de Nida',
    {'Mon amie Hilary a perdu son collier, et nous ne parvenons pas à le retrouver. Nous avons pêché toute la journée ici, et nous avons déjà cherché aux alentours. Je crois qu\'il est tombé dans le lac. Nos parents ne veulent pas que nous y nagions... Ma maman dit qu\'il y a des choses méchantes sous l\'eau. Mais vous n\'avez pas l\'air d\'avoir peur des choses méchantes.|n|nVous pouvez retrouver son collier, s\'il vous plaît ?', },
    {'Trouver le Collier d\'Hilary et le rapporter à Hilary à Comté-du-Lac.', },
  },
  [3761] = {
    'Humus d\'Un\'Goro',
    {'Il paraît que la terre du Cratère d\'Un\'Goro est naturellement riche en propriétés magiques puissantes. Le Cercle cénarien souhaite étudier cette terre. Rendez-vous au Cratère d\'Un\'Goro et prélevez suffisamment de terre pour que nous puissions travailler un bon moment.|n|nCette terre riche s\'agglomère parfois, et certaines bêtes peuvent en porter sur elles des fragments utilisables. Apportez-les tous à Ghede. Cherchez simplement des monticules de terre et des taurens en train de beugler des ordres et vous le trouverez. C\'est un bon gars, mais ne l\'énervez pas.', },
    {'Apporter 20 Échantillons d\'humus d\'Un\'Goro à Ghede, aux Pitons-du-Tonnerre.', },
  },
  [3762] = {
    'L\'aide à l\'archidruide Totem-runique',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps, si cela est possible.|n|nLe Cercle cénarien des Pitons-du-Tonnerre est très intéressé par des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans un projet crucial. Bien que je n\'en connaisse pas les détails, je peux vous dire que Hamuul Totem-runique lui-même mène ce projet.|n|nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la cime des Anciens aux Pitons-du-Tonnerre.', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique aux Pitons-du-Tonnerre.', },
  },
  [3763] = {
    'L\'aide à l\'archidruide Forteramure',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps si la chose est possible.|n|nLe Cercle cénarien à Darnassus recherche des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l\'archidruide Fandral Forteramure en personne mène ces recherches.|n|nSi cela vous intéresse, allez directement lui parler à l\'Enclave cénarienne à Darnassus.', },
    {'Parler à l\'Archidruide Fandral Forteramure à Darnassus.', },
  },
  [3764] = {
    'Humus d\'Un\'Goro',
    {'On raconte que l\'humus du Cratère d\'Un\'Goro est enrichi de propriétés magiques puissantes. Je veux séparer le vrai de la rumeur ; partez pour les terres sauvages du Cratère d\'Un\'Goro et récupérez suffisamment d\'échantillons de qualité de son sol afin que nous puissions l\'étudier sans discontinuer.|n|nVous pourriez considérer que cette simple tâche de récupération est indigne de vous, mais ce genre de considération ne vous ferait apprécier ni de moi ni du Cercle cénarien. Apportez les échantillons à Jenal, qui doit sans aucun doute perdre son temps dehors derrière cet arbre. Cherchez simplement le tas de terre. C\'est lui qui s\'occupera de la logistique, pas moi.', },
    {'Apporter 20 Échantillons d\'humus d\'Un\'Goro à Jenal dans l\'Enclave cénarienne à Darnassus.', },
  },
  [3765] = {
    'La dépravation au loin',
    {'Hurlevent. Tellement bouillonnant d\'activité !|n|nJe viens de loin pour chercher de l\'aide. On dit que de courageux aventuriers foulent les rues de cette cité.|n|nMon frère, Gershala, a besoin d\'aide à Sombrivage. Il demeure dans la ville côtière d\'Auberdine.|n|nLe voyage est long et périlleux. C\'est pourquoi je demande l\'aide d\'$Gun:une:c; $C $Gexpérimenté:expérimentée:c; comme vous.', },
    {'Aller voir Gershala Murmenuit à Auberdine.', },
  },
  [3781] = {
    'Recherches sur la fibre d\'aurore',
    {'Nous avons planté des graines de Tharlendris dans de la terre du Cratère d\'Un\'Goro, avec ce que nous appelons une Sacoche de printemps. Ces graines ont germé et donné un grand nombre d\'herbes fortes et variées. Parmi elles, il y a la Fibre d\'aurore, une herbe dont on sait peu de chose. J\'ai l\'intention de percer ses mystères.|n|nApportez ceci à Mathrengyl, en bas, et il vous remettra quelques graines afin que vous puissiez commencer. Si vous veniez à en manquer, vous devrez lui en acheter.', },
    {'Apporter le Bon pour des graines de l\'archidruide à Mathrengyl Pasdelours dans l\'Enclave cénarienne à Darnassus.', },
  },
  [3782] = {
    'Recherches sur la fibre d\'aurore',
    {'Nous avons planté des graines de Tharlendris dans de la terre du Cratère d\'Un\'Goro, avec ce que nous appelons une Sacoche de printemps. Ces graines ont germé et donné un grand nombre d\'herbes fortes et variées. Parmi elles, il y a de la Fibre d\'aurore, une herbe dont on sait peu de chose. J\'espère pouvoir percer ses mystères, pour le Cercle.|n|nApportez ce bon à ma sœur Bashana et elle vous remettra quelques graines afin que vous puissiez nous aider. Si vous veniez à en manquer, vous devrez lui en acheter.', },
    {'Apporter le Bon pour des graines à Bashana Totem-Runique aux Pitons-du-Tonnerre.', },
  },
  [3783] = {
    '[PÉRIMÉ]Yéti ? Y es-tu ?',
    {'Mes amis ne cessent d\'avoir de grandes idées. Et je n\'aurais jamais cru être capable de les concurrencer… jusqu\'à ce jour ! Je viens juste de dessiner les plans de quelque chose de vraiment merveilleux ! Si vous me promettez de ne pas le répéter, je vais vous dire mon secret...|n|nJe vais construire un yéti mécanique ! Non seulement mes amis ne vont pas le croire quand ils le verront, mais une fois qu\'ils se seront remis de leur surprise, je sais qu\'ils seront vraiment impressionnés !|n|nPour commencer, j\'aurais besoin de plusieurs fourrures épaisses de yétis, prélevées sur des yétis Chardon de glace. Voudriez-vous m\'aider ? Vous en trouverez au sud-est.', },
    {'Récupérez 10 Fourrures épaisses de yéti pour Umi Sarcafroisse, à Long-Guet.', },
  },
  [3784] = {
    'L\'aide à l\'archidruide Totem-runique',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps, si cela est possible.|n|nLe Cercle cénarien des Pitons-du-Tonnerre est très intéressé par des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans un projet crucial. Bien que je n\'en connaisse pas les détails, je peux vous dire que Hamuul Totem-runique lui-même mène ce projet.|n|nJe vous en prie, si cela vous intéresse, allez lui parler en personne à la cime des Anciens aux Pitons-du-Tonnerre.', },
    {'Parler à l\'Archidruide Hamuul Totem-Runique aux Pitons-du-Tonnerre.', },
  },
  [3785] = {
    'Recherches sur la fibre d\'aurore',
    {'Voici la Sacoche de printemps dont vous aurez besoin pour utiliser les graines de Tharlendris. Vous devrez avoir également des échantillons d\'humus d\'Un\'Goro sous la main comme fertiliseur pour les graines. Servez-vous juste de la sacoche lorsque vous serez en possession de tout ce qui est nécessaire. Elle s\'occupera du reste.|n|nLorsque vous aurez suffisamment de fibre d\'aurore, apportez-les-moi ici à l\'Enclave. Veuillez ne pas déranger l\'archidruide. C\'est un homme très occupé, et il ne s\'agit pas de le déranger à chaque fois que quelqu\'un arrive avec un nouveau sac de fibre d\'aurore !', },
    {'Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendris et deux Échantillons d\'humus d\'Un\'Goro pour essayer de cultiver des Fibres d\'aurore.|n|nApporter 10 Fibres d\'aurore à Mathrengyl Pasdelours à Darnassus.', },
  },
  [3786] = {
    'Recherches sur la fibre d\'aurore',
    {'Voici la Sacoche de printemps dont vous aurez besoin pour utiliser les graines de Tharlendris. Vous devrez avoir également des échantillons d\'humus d\'Un\'Goro sous la main comme fertilisant pour les graines. Servez-vous juste de la sacoche lorsque vous serez en possession de tout ce qui est nécessaire. Elle s\'occupera du reste.|n|nLorsque vous aurez suffisamment de fibres d\'aurore, apportez-le-moi ici sur la cime des Anciens. Veuillez ne pas déranger l\'archidruide. Ses recherches l\'occuperont beaucoup, de même que ses nombreux soucis le préoccuperont bien assez.', },
    {'Utiliser une Sacoche de printemps avec une pochette de graines de Tharlendris et deux Échantillons d\'humus d\'Un\'Goro pour essayer de cultiver des Fibres d\'aurore.|n|nApporter 10 Fibres d\'aurore à Bashana Totem-runique aux Pitons-du-Tonnerre.', },
  },
  [3787] = {
    'La requête de Gentecime',
    {'Excusez-moi, mon $Gami:amie;…|n|nL\'un de mes collègues voudrait vous entretenir à propos des recherches que vous effectuez conjointement avec le Cercle cénarien. Il est druide et se nomme Quintis Gentecime. Il demeure au bastion de Pennelune, en Féralas, et voudrait vous parler de la Fibre d\'aurore. Il insiste pour que notre conversation n\'atteigne en aucun cas les oreilles de l\'archidruide…|n|nSi cela vous intéresse, allez lui parler. Il ne fait aucun doute que tout vous sera révélé si vous allez le voir.', },
    {'Parler à Quintis Gentecime dans le bastion de Pennelune.', },
  },
  [3788] = {
    'La requête de Gentecime',
    {'Excusez-moi, mon $Gami:amie;…|n|nL\'un de mes collègues voudrait vous entretenir à propos des recherches que vous effectuez conjointement avec le Cercle cénarien. Il est druide et se nomme Quintis Gentecime. Il demeure ici au bastion de Pennelune et voudrait vous parler de la Fibre d\'aurore. Il insiste pour que notre conversation n\'atteigne en aucun cas les oreilles de l\'archidruide.|n|nSi cela vous intéresse, allez lui parler. Il ne fait aucun doute que tout vous sera révélé si vous allez le voir.', },
    {'Parler à Quintis Gentecime dans le bastion de Pennelune.', },
  },
  [3789] = {
    'L\'aide à l\'archidruide Forteramure',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps si la chose est possible.|n|nLe Cercle cénarien à Darnassus recherche des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l\'archidruide Fandral Forteramure en personne mène ces recherches.|n|nSi cela vous intéresse, allez directement lui parler à l\'Enclave cénarienne à Darnassus.', },
    {'Parler à l\'Archidruide Fandral Forteramure à Darnassus.', },
  },
  [3790] = {
    'L\'aide à l\'archidruide Forteramure',
    {'Pardonnez-moi, $C, mais j\'aimerais prendre quelques instants de votre temps si la chose est possible.|n|nLe Cercle cénarien à Darnassus recherche des $Gaventuriers aguerris tels:aventurières aguerries telles; que vous pour lui prêter main-forte dans des recherches capitales. Bien que je ne connaisse pas les détails, je peux vous dire que l\'archidruide Fandral Forteramure en personne mène ces recherches.|n|nSi cela vous intéresse, allez directement lui parler à l\'Enclave cénarienne à Darnassus.', },
    {'Parler à l\'Archidruide Fandral Forteramure à Darnassus.', },
  },
  [3791] = {
    'Le Mystère des Fibres d\'aurore',
    {'Je vais être franc avec vous, $N. Cela m\'intéresse – non, cela m\'inquiète ! – de savoir pourquoi l\'archidruide de Darnassus utilise le couvert du Cercle cénarien, tout autant que ses ressources, pour se procurer d\'aussi grandes quantités de Fibre d\'aurore. Je suis chercheur et mon domaine concerne les malédictions. J\'ai entendu dire que la Fibre d\'aurore, placée dans certaines conditions, développe des propriétés similaires à celles d\'autres herbes utilisées dans des malédictions primitives.|n|nJe veux en savoir davantage, et je sollicite votre aide. Apportez-moi dix Fibres d\'aurore et je m\'occuperai de vous.', },
    {'Apporter 10 Fibres d\'aurore à Quintis Gentecime au bastion de Pennelune.', },
  },
  [3792] = {
    'De la Fibre d\'aurore au bastion de Pennelune',
    nil,
    nil,
  },
  [3801] = {
    'Héritage Sombrefer',
    {'Salutations, $N. Je me nomme Franclorn Le Forgebusier. Oui, le Franclorn Le Forgebusier, inventeur des méthodes d\'approche architectonique de la roche. Vous êtes sans aucun doute déjà $Gpassé:passée; près de l\'une de mes créations lors de vos aventures dans notre monde ravagé par la guerre. Vous y êtes peut-être même $Gentré:entrée;.|n|nVous vous demandez probablement ce que je fais ici et ce que j\'attends de vous. Deux excellentes questions.|n|nJ\'ai besoin de votre aide, bien sûr. En échange, je vous remettrai la clé des profondeurs de ma cité maudite.', },
    {'Parler à Franclorn Le Forgebusier à la Tombe du Forgebusier, au Mont Rochenoire, si obtenir une clé de la Cité majeure vous intéresse.', },
  },
  [3802] = {
    'Héritage Sombrefer',
    {'Vous trouverez Fineous Sombrevire au-delà du Cercle de la loi, dans la Chambre de l\'artisanat. Tuez ce misérable chien et récupérez Souillefer.|n|nApportez Souillefer au sanctuaire de Thaurissan et placez le marteau à la place qui est la sienne : dans les mains de la statue érigée en mon honneur.|n|nAlors le compartiment dans lequel j\'ai placé la clé maîtresse s\'ouvrira. Plus important encore, Souillefer restera entre mes mains pour l\'éternité. S\'ils tentent de l\'enlever, la statue et le marteau se briseront, à jamais perdus.', },
    {'Tuer Fineous Sombrevire et récupérer le grand marteau, Souillefer. Apporter Souillefer au sanctuaire de Thaurissan et le placer sur la statue de Franclorn Le Forgebusier.', },
  },
  [3803] = {
    'De la fibre d\'aurore pour Darnassus',
    nil,
    nil,
  },
  [3804] = {
    'Des Fibres d\'aurore pour les Pitons-du-Tonnerre',
    nil,
    nil,
  },
  [3821] = {
    'Le Rocher des Cognepeurs',
    {'Sha\'ni a été envoyée dans les steppes Ardentes pour enquêter sur les rites étranges des ogres brûlentrailles. C\'était il y a plus de trois semaines.|n|nSangredent dit qu\'il n\'a plus de nouvelle de son régiment et que je ferais mieux de l\'oublier et de me concentrer sur ce que j\'ai à faire. Incroyable, non ? C\'est ma femme !|n|nJe suis dans l\'impossibilité de quitter mon poste, $N, mais je dois savoir ce qui lui est arrivé. Partez à sa recherche dans les steppes Ardentes, je vous en prie.', },
    {'Aventurez-vous dans les Steppes Ardentes et découvrez ce qu\'il est advenu de Sha\'ni Fière-défense.', },
  },
  [3822] = {
    nil,
    {'Tout mon régiment a été capturé, $N. Tous ont été tués, sauf moi.|n|nLeur chef, Krom\'Grul, voulait me réserver pour un genre de rituel.|n|nJ\'ai été enchaînée à cet autel et battue à mort par ce monstre. J\'ai rendu l\'âme après une heure de cette torture. Alors, il a arraché mon anneau de nez de mariage et l\'a passé à son doigt. Je n\'ai jamais vu une telle sauvagerie !|n|nTrouvez Krom\'Grul et tuez-le ! Rapportez mon anneau à Thal\'trak.|n|n$N, dites-lui que nous nous rencontrerons à nouveau... dans une autre vie.', },
    {'Récupérez l\'Anneau de nez de Sha\'ni sur Krom\'Grul, et rapportez-le à Thal\'trak, à Kargath. Fouillez les différentes grottes et mines du Rocher des Cognepeurs.', },
  },
  [3823] = {
    'Exterminer les Brûlentrailles',
    {'Nous devons frapper nos ennemis avant qu\'ils ne nous frappent !|n|nJe serai bref, soldat.|n|nLes ogres brûlentrailles des steppes Ardentes sont les alliés des orcs rochenoires. Ils collaborent étroitement avec ces maudits orcs en gardant le rocher des Cognepeurs, riche en minerais et en veillant à la sécurité des lignes d\'approvisionnement.|n|nLaissez votre signature, $N. Bousculez leurs rangs et revenez me voir quand vous aurez accompli votre travail.|n|n<Oralius serre ses poings sur du vide, comme s\'il étranglait quelqu\'un.>|n|nJE VAIS TE TUER, WINKY !', },
    {'Tuer 15 Ogres-mages brûlentrailles, 7 Ogres brûlentrailles et 7 Brutes brûlentrailles.', },
  },
  [3824] = {
    'Le seigneur-brute Gor\'tesh',
    {'Ils faiblissent, je vous assure ! Nous devons à présent porter un coup décisif.|n|nLe seigneur-brute Gor\'tesh doit être tué. Plus important encore, vous devez me rapporter sa tête afin que je puisse préparer la troisième partie de notre attaque sur les ogres brûlentrailles.|n|nAttention, soldat : Gor\'tesh n\'est pas établi au rocher des Cognepeurs lui-même, mais dans un bâtiment des orcs rochenoires, à l\'ouest du rocher des Cognepeurs.|n|nVos ordres sont simples : trouvez Gor\'tesh et décapitez-le. Revenez me voir une fois votre travail accompli.|n|nFERME-LA, WINKY !', },
    {'Trouver la Tête coupée de Gor\'tesh.', },
  },
  [3825] = {
    'Une tête d\'ogre au bout d\'une pique = une fête',
    {'Il vous reste une dernière chose à faire, soldat.|n|nJ\'ai pris la liberté de planter la tête de Gor\'tesh sur une pique. À présent, tout ce que vous avez à faire, c\'est d\'apporter cette pique au sommet du rocher des Cognepeurs et de la ficher dans le sol. Après cela, vous pourrez admirer ces lâches d\'ogres courir pour sauver leur vie ! Après vous être $Gamusé:amusée; un peu, revenez et je vous récompenserai pour votre dur labeur.|n|n<Oralius semble perdre contact avec la réalité.>', },
    {'Prendre la Tête coupée de Gor\'tesh et la placer au sommet du Rocher des Cognepeurs. Chercher un monticule de terre meuble pour planter la pique.', },
  },
  [3841] = {
    'Un orphelin à la recherche d\'un foyer',
    {'Oh, salut $N ! Cela me fait plaisir de vous revoir. Comment s\'est passé votre voyage à Darnassus ?|n|nJe crois que vous serez $Gheureux:heureuse; d\'apprendre que nous avons fait pas mal de progrès pendant que vous étiez $Gparti:partie;. Nous avons même sauvé un nid plein d\'œufs. Malheureusement, la mère est morte avant que nous puissions l\'atteindre.|n|nDites-moi, en voudriez-vous un pour en faire un animal de compagnie ? Ils semblent bientôt prêts à éclore et ont besoin $Gd\'un père attentif:d\'une mère attentive;. Qu\'en dites-vous ?|n|nSi cela vous intéresse, apportez l\'un de ces œufs à Quentin. Il se trouve à la piste de course des Salines. Il pourra vous en apprendre davantage.', },
    {'Parler à Quentin aux Mille pointes.', },
  },
  [3842] = {
    'Une courte incubation',
    {'Les Tisselune, hein ? Fascinant. J\'aimerais que les Fées fléchetteuses comprennent ce que cela veut dire d\'avoir ces deux-là veillant sur elles.|n|nLes Tisselune sont tout à fait compétentes.|n|nAinsi, ce sont elles qui vous ont offert l\'œuf. Dans ce cas, vous allez en être responsable aussi longtemps que vous le souhaitez. Il semble qu\'il sera bientôt prêt à éclore, mais nous devons nous assurer qu\'il va bien et qu\'il n\'a subi aucun dommage.|n|nJ\'ai simplement besoin de deux élixirs de robustesse pour lancer un petit sort afin de renforcer sa santé. J\'ai ici le reste des ingrédients.', },
    {'Apporter 2 Elixirs de Robustesse à Quentin, aux Mille pointes.', },
  },
  [3843] = {
    'Un tout nouveau membre dans la famille',
    {'Un spécimen magnifique, $N. Si cette créature arrive à terme, ce sera un animal plein de santé !|n|nSi vous avez l\'intention de garder cette créature, permettez-moi de vous suggérer une dernière chose. Rendez-vous au Nid-de-l\'Aigle dans les Hinterlands. Allez parler au nain Agnar Domptebêtes, c\'est un dresseur d\'animaux renommé et il vous conseillera pour mener à bien les dernières étapes de la gestation.|n|nMais dépêchez-vous, $N, cet œuf est fragile et nécessite des soins appropriés.', },
    {'Emmenez votre Œuf fragile de Fée fléchetteuse dans les Hinterlands et parlez à Agnar Domptebêtes. Dépêchez-vous, vous n\'avez qu\'une heure pour le trouver avant que le petit ne meure dans l\'œuf.', },
  },
  [3844] = {
    'C\'est un secret pour tout le monde',
    {'Un radeau brisé repose le long du rivage. Vu qu\'il ne s\'agit que d\'un petit étang, on peut se demander comment ce radeau a échoué ici. Les traces sur les arbres aux alentours indiquent cependant que le niveau de l\'eau pourrait varier.|n|nExplorer ce secteur pourrait révéler des indices supplémentaires...', },
    {'Rechercher dans l\'étang un indice sur l\'identité du propriétaire du radeau brisé.', },
  },
  [3845] = {
    'C\'est un secret pour tout le monde',
    {'Après vous être $Gemparé:emparée; du paquet, vous l\'apportez jusqu\'au rivage. Peut-être que si vous examinez les objets qui l\'emplissent, vous pourrez en découvrir davantage sur l\'identité de son propriétaire.|n|nQuelques voyageurs égarés se trouvent au refuge des Marshal. Il se peut que vous en appreniez plus en ces lieux.', },
    {'Examiner les objets du paquet et les apporter à leur propriétaire.', },
  },
  [3861] = {
    'COT-COT-CODEC !',
    {'« Cot... cot... cot... CODEEEC !|n|nCot... cot... cot. »|n|nLa poule vous regarde puis commence à griffer la terre. On dirait qu\'elle est en train d\'écrire un mot sur le sol. Est-ce que cela pourrait être... S-A-L-D-E-A-N ? Avant que vous ne puissiez demander quoi que ce soit, la poule s\'ébroue et retourne vaquer à ses occupations.', },
    {'Trouver de la Nourriture spéciale pour poulet et l\'apporter à la poule que vous voulez aider. Lorsque vous l\'aurez trouvée, encouragez-la (/acclame) avant d\'essayer de lui donner la Nourriture spéciale pour poulet.', },
  },
  [3881] = {
    'Le sauvetage de l\'expédition',
    {'Je ne sais pas comment vous êtes $Gparvenu:parvenue; jusqu\'ici, mais votre arrivée me réjouit ! Je me nomme Williden Marshal et je mène une expédition neutre. Notre dernière tentative s\'est soldée par d\'innombrables désastres. Nous avons sous-estimé le danger représenté par le Cratère d\'Un\'Goro.|n|nAlors que nous fuyions nos campements, dans le sud-ouest et le nord-est du cratère, nous avons laissé derrière nous des fournitures d\'une importance vitale. Vous avez l\'air valeureux, pouvez-vous nous aider à les récupérer ?', },
    {'Apporter une Caisse de nourriture et de l\'Équipement de recherche à Williden Marshal dans le Cratère d\'Un\'Goro.', },
  },
  [3882] = {
    'Faites rouler les os',
    {'On pourrait penser qu\'être chef terrassier pour les Expéditions Marshal signifie que j\'aime creuser. Il y a des choses bien plus désagréables à faire en ce monde… mais aucune ne me vient à l\'esprit.|n|nNous étions supposés creuser dans les Coteaux de la terreur - quel nom FANTASTIQUE, soit dit en passant - à la recherche de stégodons et de dimeurtrodons morts ! Eh bien, figurez-vous qu\'il en reste aussi beaucoup de vivants ! Wil et Hol insistent encore pour étudier ce piège mortel, alors nous devons ramener ces os de dinosaures. Entre vous et moi, s\'ils proviennent de créatures vivantes, ils feront tout aussi bien l\'affaire.', },
    {'Apporter 8 Os de dinosaure à Étincelle Minerien, au cratère d\'Un\'Goro.', },
  },
  [3883] = {
    'Écologie étrangère',
    {'On ne va pas arrêter les recherches à cause d\'un échec ! Avant d\'arriver ici, nous faisions des études sur les insectes Gorishi dans la partie sud du cratère. Leur présence est une nouveauté dans l\'écologie d\'Un\'Goro et nous voulons savoir pourquoi.|n|nDans leur ruche, il doit exister une écloserie pour les larves. Vous pouvez identifier ces lieux parce que des larves sont suspendues. Utilisez cette fiole pour prélever un échantillon de la paroi de la ruche près de l\'une des écloseries. Rapportez-la-moi pour que je l\'étudie !', },
    {'Utiliser la Fiole de raclement pour récolter un Échantillon de paroi de la ruche dans une des nurseries de la ruche Gorishi, à l\'intérieur du cratère d\'Un\'Goro. Chercher les chambres qui contiennent des larves suspendues.|n|nApporter l\'Échantillon de paroi de la ruche à Hol\'anyee Marshal dans le cratère d\'Un\'Goro.', },
  },
  [3884] = {
    'Le journal de Williden',
    {'Vous avez découvert un journal en piteux état. On peut encore en déchiffrer certaines parties, cependant. Notamment le nom de son propriétaire, inscrit à l\'intérieur : Williden Marshal. Si le journal dit vrai, alors Williden devrait se trouver quelque part dans la partie nord du cratère. D\'après ce que raconte le journal, lui et ses hommes sont partis pour des terres plus élevées et à l\'abri des bêtes sauvages lorsque leurs camps de base se sont vus submergés.', },
    {'Rapporter le Journal à Williden Marshal quelque part dans le Cratère d\'Un\'Goro.', },
  },
  [3885] = {
    nil,
    {'Escortez-moi ainsi que Dadanga !', },
    {'Escorter Petra et Dadanga !', },
  },
  [3901] = {
    'Faites cliqueter les thorax !',
    {'Vous avez prouvé votre valeur aux Réprouvés dans des conditions normales, $N. À présent, voyons ce que vous pouvez faire lorsque vous êtes sous pression.|n|nLes squelettes cliquethorax, des sbires décérébrés extrêmement dangereux, sont plus résistants que les zombies auxquels vous avez eu affaire jusqu\'à présent. Réduisez leur nombre et démontrez à nouveau votre appartenance aux Réprouvés. Quand vous aurez fini, ne vous attardez pas, revenez me voir.', },
    {'Tuez 8 Squelettes cliquethorax.', },
  },
  [3902] = {
    'La chasse aux trésors',
    {'Vous, là ! Si vous cherchez à vous rendre utile, écoutez bien !|n|nNous avons besoin de recrues fraîchement déterrées pour se rendre au Glas et rechercher tout équipement utile. Il est sûrement remisé dans des piles de boîtes. Nous attendons de nouvelles recrues mais, à moins que nous ne voulions les voir déambuler tout nus, nous ferions mieux de commencer à faire de la récupération !|n|nAllez-y, au travail, misérable sac d\'os ! Et je ne récompenserai pas ceux qui n\'y mettent pas d\'ardeur.', },
    {'Fouiller Le Glas et ses alentours pour trouver 6 caisses de Fournitures de récupération, et les ramener au Nécrogarde Saltain.', },
  },
  [3903] = {
    nil,
    {'Votre fiabilité est démontrée, $C. Vous n\'avez pas peur de vous salir les mains, hein ?|n|nJ\'ai une amie du nom de Milly Osworth, elle a un gros problème. Elle et son chariot se trouvent de l\'autre côté de l\'abbaye, près de l\'étable. Je suis sûr que vos deux bras devraient lui être utiles, $N.', },
    {'Parler à Milly Osworth.', },
  },
  [3904] = {
    'Récolte de Milly',
    {'Une bande de brigands, les Défias, s\'est introduite dans le vignoble de Comté-du-Nord alors que je faisais les récoltes ! Je l\'ai signalé aux gardes de Comté-du-Nord et ils m\'ont assuré qu\'ils faisaient le nécessaire, mais je crains le pire pour ma récolte de raisin ! Si les Défias ne la volent pas, les gardes pourraient l\'écraser en poursuivant ces voyous.|n|nAidez-moi, je vous en prie ! J\'ai ramassé pratiquement tout mon raisin dans des seaux mais je les ai laissés dans les vignes, au sud-est.|n|nRapportez-moi ces seaux ! Sauvez ma récolte !', },
    {'Apportez 8 seaux de la Récolte de Milly à Milly Osworth, à l\'Abbaye de Comté-du-Nord.', },
  },
  [3905] = {
    'Manifeste des vendanges',
    {'À présent que mes vendanges sont sauvées, apportez ce Manifeste des vendanges à Frère Neals. Il s\'occupe du magasin de nourriture et de boisson de Comté-du-Nord, et il est certain qu\'il sera ravi d\'apprendre que nous avons du raisin frais.|n|nVous trouverez Frère Neals dans la tour de l\'abbaye. C\'est là qu\'il aime déguster son vin.', },
    {'Apportez le Manifeste des vendanges à Frère Neals dans l\'Abbaye de Comté-du-Nord.', },
  },
  [3906] = {
    'Discordance des flammes',
    {'Les anciens ont ressenti une perturbation parmi les éléments. Les nains sombrefers ont invoqué en notre monde un esprit vil qui menace de recouvrir nos terres d\'un froid éternel. Nous devons enquêter sur cette dissonance de la flamme.|n|nPartez pour le mont Rochenoire. Passez par l\'Abîme de flamme et rendez-vous dans la carrière. C\'est là que vous trouverez le seigneur du Feu : le Grand maître Pyron.|n|nRétablissez l\'harmonie et revenez me voir.', },
    {'Partir pour la carrière dans le mont Rochenoire et tuer le Grand maître Pyron. Retourner voir Cœur-de-tonnerre une fois votre mission accomplie.', },
  },
  [3907] = {
    'Discordance des flammes',
    {'Je peux sentir la souillure de l\'air qui vous entoure, $N. Il y en a un autre, caché dans les profondeurs de Rochenoire. C\'est lui qui contrôle cette souillure.|n|nLe vent et la terre pleurent son nom : Seigneur Incendius… mais quelqu\'un… quelque chose… commande cet être. Il n\'est qu\'un émissaire.|n|nTrouvez-le et découvrez où se cache son maître. Revenez me voir lorsque vous aurez obtenu cette information.', },
    {'Pénétrez dans les Profondeurs de Rochenoire et traquez le Seigneur Incendius. Tuez-le puis donner tous les renseignements que vous pourrez trouver à Cœur-de-tonnerre.', },
  },
  [3908] = {
    'C\'est un secret pour tout le monde',
    {'Vous comprenez, j\'ignore comment j\'ai échoué ici. Et personne ne peut me le dire. C\'est un mystère pour tout le monde ! Il semble que je ne puisse me souvenir de rien…|n|nCes objets que vous m\'avez apportés… ils me rappellent quelque chose, quand même.|n|nMon épée... j\'étais supposé la renforcer de quelque manière, mais je ne sais pas vraiment pourquoi. Cela me navre de ne pas pouvoir m\'en souvenir et d\'être incapable de vous en dire plus, je suis désolé !|n|nMais ce que je peux vous dire, c\'est à qui l\'apporter : Donova Antreneige, au Berceau-de-l\'Hiver. Vous la trouverez près des sources chaudes. Elle peut y tremper l\'épée.', },
    {'Apporter l\'Épée de Linken à Donova Antreneige au Berceau-de-l\'Hiver.', },
  },
  [3909] = {
    'L\'élixir de Videre',
    {'Non, ce n\'est pas vrai ! Linken ? Il a OUBLIÉ ?|n|nAh, je vois… il a perdu la mémoire…|n|nBien, voici son épée. Elle n\'est pas terminée, cependant. Je connais celui qui pourrait l\'achever, mais… parvenir à lui parler pourrait s\'avérer difficile.|n|nÉcoutez, je sais qui peut vous aider. Ce serait trop long à expliquer en détail, mais vous devez obtenir de l\'élixir de Videre. La seule personne qui peut vous aider à le trouver se nomme Gregan Gerbebière. Il est difficile de le localiser, mais aux dernières nouvelles, il campait dans les terres sauvages de Féralas.', },
    {'Rechercher Gregan Gerbebière au nord de Féralas. Apprendre de lui comment vous pouvez acquérir l\'élixir de Videre, puis retourner voir Donova Antreneige, au Berceau-de-l\'Hiver.', },
  },
  [3910] = {
    nil,
    {'Bienvenue à Gadgetzan ! Ramenez-nous à la maison...', },
    {'Escorter Petra et Dadanga jusqu\'à Un\'Goro.', },
  },
  [3911] = {
    'Le dernier élément',
    {'Il y a du travail pour ceux qui s\'aventurent dans les Profondeurs, $N.|n|nLes Sombrefers peuvent créer des golems extrêmement puissants.|n|nLes premiers rapports de nos espions indiquent que les nains se servent d\'une source d\'énergie unique pour donner à leurs créations une puissance de destruction incomparable.|n|nImaginez simplement ce que nous pourrions faire de nos abominations si nous mettions la main sur cette essence des éléments ! Fouillez les moindres recoins de cette cité s\'il le faut, mais ne revenez pas tant que vous n\'aurez pas découvert cette essence ! Votre récompense sera à la mesure du risque encouru.', },
    {'Partir pour les Profondeurs de Rochenoire et trouver 10 Essences des éléments. Commencer vos recherches par les golems et par les créateurs de golems. Vivian Lagrave a aussi marmonné quelque chose à propos d\'élémentaires.', },
  },
  [3912] = {
    'Rendez-vous à la tombe',
    {'Cet élixir va vous permettre de vous entretenir avec quelqu\'un que vous ne pourriez même pas voir en temps normal…|n|nApportez l\'élixir de Videre et l\'épée de Linken jusqu\'au cimetière au-dehors de Gadgetzan, à Tanaris. Une fois $Garrivé:arrivée;, buvez la potion. Les conséquences pourraient vous surprendre, mais en aucun cas n\'ayez crainte.|n|nUne fois que vous aurez votre "nouvelle" forme, dirigez-vous vers le nord jusqu\'à ce que vous atteigniez les montagnes. Vous trouverez la personne à qui vous devez parler dans l\'une des lézardes rocheuses. Il se nomme Gaeriyan.|n|nSouvenez-vous ! Il ne vous parlera que si vous avez adopté cette forme...', },
    {'Se rendre au cimetière au-dehors de Gadgetzan et boire l\'élixir de Videre. Suivre le reste des instructions de Donova pour trouver Gaeriyan.', },
  },
  [3913] = {
    'Une situation grave',
    {'Si vous retournez au cimetière dont vous venez, $N, vous y trouverez une pierre tombale particulière. Celle-ci se démarquera des autres. Elle renferme des secrets.|n|nPoussez la pierre, et vous les apprendrez…', },
    {'Ressusciter, puis rechercher la pierre tombale que Gaeriyan vous a demandé de trouver.', },
  },
  [3914] = {
    'L\'épée de Linken',
    {'Après un grand flash, vous pouvez à nouveau vous saisir de l\'épée. Elle s\'est transformée !', },
    {'Remettre l\'Épée excellente de Linken à Linken dans le cratère d\'Un\'Goro.', },
  },
  [3921] = {
    'Wenikee Bakaboulon',
    {'C\'est moi qui ai fait ça ? On dirait que j\'ai embouti l\'un des fluidifiants à portance dans les rayons de l\'engrenage dérégulateur. On peut réparer ça facilement. Je connais une experte en pistons radiaux à expansion triple qui adorerait travailler sur un samophlange. Apportez-le à Wenikee Bakaboulon, juste au sud du rempart de Mor\'shan. Elle se fera une joie de le réparer.|n|nHé, on n\'a même pas besoin de marcher. C\'est l\'occasion rêvée de tester mon porteur de personnes personnel !', },
    {'Apportez le Samophlange cassé à Wenikee Bakaboulon. Adressez-vous à Brak pour être directement $Gtéléporté:téléportée; auprès d\'elle.', },
  },
  [3922] = {
    'Les petites pièces',
    {'Je veux réparer ce samophlange, mais pour ce faire je vais avoir besoin de certaines choses. Je n\'ai plus de rondelles de dix-sept cinq et il va m\'en falloir un sacré paquet pour le travail qui nous attend.|n|nLes endroits les plus proches où l\'on peut en trouver sont la station de recherche non loin d\'ici et la Videfange, à l\'est. La KapitalRisk en conserve généralement dans ses seaux d\'outils. Regardez dans les seaux à l\'un ou l\'autre endroit, et revenez me voir lorsque vous aurez récupéré suffisamment de rondelles de métal.', },
    {'Trouvez 10 Rondelles de métal dans des seaux autour de la Videfange.', },
  },
  [3923] = {
    '[PÉRIMÉ]Rilli Grassougob',
    {'Hmm, ça n\'a pas marché. J\'ai placé des jauges supplémentaires sur le samophlange pour en mesurer l\'intégrité structurelle, et elles donnent comme résultat une intégrité constante proche de zéro. Je pourrais ajouter d\'autres cadrans et peut-être un ou deux leviers pour essayer de le réparer, mais... je crains que ça ne fasse qu\'empirer les choses.|n|nVous devriez apporter le samophlange à Rilli Grassougob. Il travaillait autrefois pour la KapitalRisk. Si quelqu\'un est capable de le réparer, c\'est bien Rilli.|n|nVous pourrez le trouver à l\'Atelier de Nogg à Orgrimmar, dans la Vallée de l\'Honneur.', },
    {'Apportez le Samophlange cassé à Rilli Grassougob à Orgrimmar.', },
  },
  [3924] = {
    '[PÉRIMÉ]Manuel du Samophlange',
    {'Je pense pouvoir réparer le samophlange, mais je vais avoir besoin du manuel d\'utilisation tout d\'abord. Lorsque je travaillais pour la KapitalRisk, j\'avais un rival du nom de Chef Cuivroncteur, qui connaissait des tas de secrets sur le samophlange, et qui donnait quelques rares informations sur l\'appareil à ceux envers qui il avait confiance. Je ne faisais pas partie des rares élus...|n|nLe Chef Cuivroncteur était généralement à la mine des Pierriers dans la partie nord-est des Tarides. Parvenez à en obtenir le manuel, et s\'il en a distribué des pages à quiconque, vous devrez également les récupérer.', },
    {'Apportez le Manuel du samophlange à Rilli Grassougob à Orgrimmar.', },
  },
  [3941] = {
    'Un gnome dans le besoin',
    {'Réfléchir… réfléchir… je sais que je suis venu ici pour quelque chose d\'important…|n|nJ\'ai une idée, $N. Dans la caverne proche se trouve une gnome du nom de J.D. Elle a été très aimable envers moi lorsque je suis arrivé ici. Peut-être que désorienté comme je l\'étais, je lui ai dit quelque chose dont elle pourrait se souvenir ?|n|nPourquoi n\'iriez-vous pas la voir et lui demander ? Oh, mais attention ! Elle joue toujours avec ces cristaux brillants que j\'ai vus dans le cratère. Je ne sais pas vraiment ce qu\'elle prépare là-bas !', },
    {'Trouver J.D. Collie dans la caverne du refuge des Marshal.', },
  },
  [3942] = {
    'Les souvenirs de Linken',
    {'Oh… Linken ? Oui, c\'est un drôle de type. La première fois qu\'il est venu ici, il marmonnait des propos incohérents. Il a dû recevoir un sacré coup sur la tête, si vous voulez mon avis.|n|nMais je ne peux pas m\'empêcher de me souvenir de quelque chose qu\'il disait, tout de même. Comme quoi il construisait un genre de totem. Il disait qu\'il devait parler à quelqu\'un du nom d\'Eridan Ventebleu... dans un endroit appelé Gangrebois... je crois ?|n|nJe ne pense pas qu\'il puisse lui-même vous en dire plus. Si vous voulez en apprendre davantage, peut-être devriez-vous chercher en personne Eridan ?', },
    {'Trouver Eridan Ventebleu dans le sud de Gangrebois.', },
  },
  [3961] = {
    'L\'aventure de Linken',
    {'Et dire que pendant tout ce temps la raison pour laquelle Linken est venu ici était de nous débarrasser de Coursembrase… Il semble être une personne ordinaire, mais j\'ai remarqué qu\'il ne s\'intéressait pas le moins du monde à mes expériences et à mes gadgets, qui passionnent d\'ordinaire les gnomes. Il doit être un grand guerrier.|n|nApportez-lui le totem. Voyez si cela l\'aide à se remémorer la raison pour laquelle il est venu ici.', },
    {'Apporter le Totem d\'argent d\'Aquementas à Linken au refuge des Marshal.', },
  },
  [3962] = {
    'C\'est dangereux d\'y aller seul',
    {'$N, je m\'en souviens enfin… Je suis venu ici pour combattre Coursembrase. J\'ai fait un long voyage, et il s\'agissait de la dernière étape.|n|nMais ce n\'est plus moi le héros… c\'est vous. Avec tout ce que vous avez déjà accompli, c\'est à vous d\'en finir, pas à moi.|n|nConfrontez-vous à Coursembrase, et battez-le. Il garde un artéfact appelé la Flamme dorée. Il procure une puissance plus vaste que tout ce que j\'ai pu connaître, et il est plus que dangereux entre les mains de quelqu\'un au cœur maléfique.|n|nNe partez pas $Gseul:seule;, ce serait trop dangereux.', },
    {'Partir pour la crête de la Fournaise, au sud du refuge des Marshal.|n|nTrouver Coursembrase et utiliser le Totem pour dissiper son aura protectrice. Une fois Coursembrase vaincu, se procurer la Flamme dorée.', },
  },
  [3981] = {
    'Commandant Gor\'shak',
    {'Pauvre Gargal… il ne l\'a même pas vue venir. SCHLACK ! La flèche est entrée exactement au centre du sommet de sa tête. Déjà que ce n\'était pas une lumière avant, alors maintenant…|n|n<Galamav grimace.>|n|nLorsque nous avons délogé la flèche, nous avons trouvé un message enroulé autour.|n|nSur ce message, il y avait un orc maladroitement dessiné derrière des barreaux et la signature du commandant Gor\'shak.|n|nS\'il est toujours en vie dans les Profondeurs, il faut que vous le retrouviez.|n|nUn piège, vous dites ? Sans blague ! C\'est bien pour ça que c\'est VOUS qui y allez !', },
    {'Trouver le commandant Gor\'shak dans les Profondeurs de Rochenoire.|n|nVous vous souvenez que le dessin maladroit représentait également des barreaux au-dessus du portrait. Peut-être devriez-vous rechercher un genre de prison.', },
  },
  [3982] = {
    'Que se passe-t-il ?',
    {'Je suis venu sous les auspices de Thrall. Pensiez-vous réellement que ces bouffons auraient pu me capturer ? Je me suis arrangé pour être fait prisonnier et pour pouvoir trouver des informations.|n|n<Gor\'shak chuchote.>|n|nLa princesse de Forgefer a été enlevée par l\'Empereur Thaurissan. La Princesse Barbe-de-bronze est dans cette cité même ! Je parie que le cœur du vieux Magni s\'est presque arrêté de battre lorsqu\'il a appris la nouvelle.|n|n<Gor\'shak rit.>|n|nChuuut ! Vous entendez ? Des gardes arrivent ! DÉFENDEZ-VOUS !', },
    {'Défendre Gor\'shak.', },
  },
  [4001] = {
    'Que se passe-t-il ?',
    {'Jusqu\'à présent, mes entretiens avec le nain, Kharan, dans la cellule de l\'autre côté du mur, ont été plus que limités. J\'ai tout de même réussi à le convaincre que je (ou plutôt que nous) ne lui voulions aucun mal.|n|nAllez lui parler et obtenez autant d\'informations que possible sur la princesse et sur ses ravisseurs. Puis allez raconter au Chef de guerre ce que vous avez appris.|n|nThrall ne veut pas qu\'il soit fait le moindre mal à la princesse. Bien au contraire, il a prévu un plan pour qu\'elle retourne en toute sécurité à Forgefer. Kharan sait déjà tout cela... Allez-y !', },
    {'Parler à Kharan Force-martel et obtenir autant de renseignements que possible sur l\'enlèvement de la princesse Moira Barbe-de-bronze. Apporter ces renseignements à Thrall à Orgrimmar.|n|nGor\'shak a dit que Kharan était détenu dans une cellule proche.', },
  },
  [4002] = {
    'Les royaumes de l\'Est',
    {'Vous apportez d\'excellents renseignements, $N.|n|nEn tant que Chef de guerre, il est de mon devoir d\'accomplir ce qu\'il y a de mieux pour la Horde. De m\'assurer que les générations qui nous suivent ne soient pas astreintes à une existence sans espoir.|n|nLa possibilité de construire nos alliances futures nous échoit à tous. Un geste d\'aide envers les nains pourrait fortement renforcer nos liens avec les royaumes de l\'Est. Voici la raison pour laquelle vous ne devez pas échouer !|n|nÊtes-vous $Gprêt:prête; ?', },
    {'Parler à Thrall si vous êtes $Gprêt:prête; à vous charger de la mission qu\'il a prévue.', },
  },
  [4003] = {
    'Un sauvetage royal',
    {'Ce coup porté aux nains sombrefers pourrait créer une onde de choc perceptible dans tout leur royaume.|n|nLa princesse Barbe-de-bronze est sous le contrôle de l\'Empereur Thaurissan. Vous devez tuer l\'Empereur afin de la libérer. Mais attention, votre quête est dangereuse à plus d\'un titre, car la princesse elle-même vous attaquera sans retenue tant qu\'elle sera sous le contrôle de l\'Empereur. NE LUI FAITES PAS DE MAL !', },
    {'Tuer l\'Empereur Thaurissan et libérer la Princesse Moira Barbe-de-bronze de son sort maléfique.', },
  },
  [4004] = {
    'La Princesse sauvée ?',
    {'Vous avez assassiné mon mari, $R ! Mon enfant naîtra et grandira dans ce monde sans avoir de père.|n|n<La princesse Moira vous montre du doigt.>|n|nJe vous jure pourtant que cet enfant sera le prochain souverain du royaume de Forgefer. Vous et ceux de votre espèce seront chassés et abattus comme des chiens, sans répit et sans merci.|n|n<Vous pensez que la princesse Moira souffre peut-être des effets résiduels du sort de Thaurissan.>|n|nLaissez-moi, $R. Je pense que votre chef de guerre est avide de connaître le résultat de son ingérence.', },
    {'Retourner voir Thrall à Fort Grommash, à Orgrimmar.', },
  },
  [4005] = {
    nil,
    {'Apportez le sac de fournitures à Tanaris. Rendez-vous à la crique des Gréements, et cherchez un cercle de pierres.|n|nLa péninsule la plus à l\'est, là est le secret…|n|nLisez le Livre d\'Aquor une fois que vous serez dans ce cercle. Invoquez la seule créature qui soit capable de transformer vos objets en un Totem pour combattre Coursembrase.|n|nAquementas n\'aimera pas être ainsi éveillé, mais souvenez-vous que vous devez rester dans le cercle pour qu\'il transforme les objets.', },
    {'Apporter le Livre d\'Aquor, les Griffes argentées et le Cœur d\'Arbrefer à Tanaris.|n|nUtiliser le Livre d\'Aquor pour invoquer Aquementas.|n|nAprès avoir terminé le totem, l\'apporter à J.D. Collie au refuge des Marshal.', },
  },
  [4021] = {
    'La contre-attaque !',
    {'La Horde loue vos victoires contre les Kolkars, mais ils sont à présent fous furieux. On me rapporte qu\'un contingent, épris de vengeance, a quitté leur patrie en Désolace pour arriver dans les Tarides. Aux dernières nouvelles, ils prennent d\'assaut les fortins depuis l\'ouest !|n|nCombattez les envahisseurs, et mettez un terme à la menace qu\'ils représentent pour les Tarides. Tuez-en jusqu\'à ce que leur chef de guerre, Krom\'zar, apparaisse. Battez-le et apportez-moi un morceau de sa bannière comme preuve de votre exploit.|n|nNous comptons sur vous, $N.', },
    {'Tuez des centaures kolkars jusqu\'à ce que Krom\'zar apparaisse, puis tuez-le et arrachez un Morceau de sa bannière.', },
  },
  [4022] = {
    'Un goût de flammes',
    {'Les dragons sont au courant de vos œuvres dans la gorge des Vents brûlants.|n|nMontrez-la-moi, $R. L\'écaille, imbécile.', },
    {'Montrer à Cyrus Lerepenti l\'Ecaille des dragons noirs que vous avez reçue de Kalaran Lamevent.', },
  },
  [4023] = {
    'Un goût de flammes',
    {'Vous recherchez les dragons ? Présentez-moi la preuve de votre valeur, $Gmortel:mortelle;.', },
    {'Montrer à Cyrus Lerepenti une preuve de votre valeur.|n|nVous avez le sentiment que Cyrus sait déjà que vous êtes indigne.', },
  },
  [4024] = {
    'Un goût de flammes',
    {'Je souhaite goûter aux flammes ardentes de la montagne de feu. Laisser la lave fondue cascader tout le long de mon être. Cette essence, cette chaleur fulgurante, c\'est cela dont j\'ai soif.|n|nBael\'Gar demeure dans les Profondeurs de Rochenoire : un être fait de flammes pures, né des feux de Ragnaros. Tuez Bael\'Gar et extrayez de ses restes brûlants son feu intérieur.|n|nServez-vous de l\'écaille pour arracher sans danger le feu intérieur à sa dépouille.|n|nSi vous réussissez à me le rapporter, vous serez $Grécompensé:récompensée;.', },
    {'Partez pour les Profondeurs de Rochenoire et tuez Bael\'Gar.|n|nVous savez seulement que le géant demeure à l\'intérieur des Profondeurs de Rochenoire. N\'oublier pas d\'utiliser l\'Ecaille des dragons noirs altérée pour capturer l\'Essence ardente.|n|nApporter l\'Essence ardente recouverte à Cyrus Lerepenti.', },
  },
  [4041] = {
    'L\'élixir de Videre',
    nil,
    nil,
  },
  [4061] = {
    'La révolte des machines',
    {'Nous avons découvert les machines lors de nos premières incursions dans la gorge des Vents brûlants. Après une enquête plus minutieuse, nous avons découvert qu\'elles étaient importées des steppes Ardentes, et peut-être des profondeurs de Rochenoire. C\'est pour cela que nous avons besoin de vous, $N.|n|nVotre première mission sera de pénétrer dans les steppes Ardentes et de récupérer des fragments d\'élémentaires sur des automates de roc et sur des réalisations en roc moindres de la région. Lorsque vous en aurez suffisamment, revenez me voir et je déterminerai leur origine.', },
    {'Aventurez-vous dans les Steppes Ardentes et récupérez 10 Fragments d\'élémentaires cassés pour la Hiérophante Theodora Mulvadania.|n|nTheodora vous a indiqué que les golems et les élémentaires étaient la source de ces fragments.', },
  },
  [4062] = {
    'La révolte des machines',
    {'S.G.A.|n|nVoici les « initiales » gravées sur les fragments d\'élémentaires. Au-dessous, on peut lire un genre de rang. Les machines que vous avez détruites dans les steppes Ardentes étaient de « Rang IV ». Je présume qu\'il s\'agit d\'un rang peu élevé.|n|nApportez cet échantillon de fragment à Lotwil Veriatus dans le camp à l\'est. C\'est un érudit qui a un certain renom dans les sciences sur les élémentaires. Il se peut qu\'il puisse nous venir en aide dans notre quête.', },
    {'Apporter l\'Échantillon de fragment d\'élémentaire à Lotwil Veriatus.|n|nTheodora vous a dit qu\'il se trouvait dans un camp à l\'est.', },
  },
  [4063] = {
    'La révolte des machines',
    {'Argelmach ? Impossible ! Argelmach a été tué il y a dix ans. Je le sais, c\'est moi qui l\'ai tué.|n|nIl s\'agissait d\'un nain abject, obsédé par l\'idée de ruiner le travail de ma vie afin d\'atteindre ses diaboliques desseins. On dirait que les méchants parviennent toujours à échapper à la justice.|n|nS\'il s\'agit de l\'œuvre d\'Argelmach, il faut le détruire. Je vais avoir besoin de spécimens de ses dernières créations. Si l\'on me donne les bons, il se peut que je parvienne à mettre un terme à ce soulèvement. Les créations gardent Argelmach dans les Profondeurs de Rochenoire.', },
    {'Trouver et tuer le Seigneur des golems Argelmach. Rapporter sa tête à Lotwil. Collecter également 10 Noyaux d\'élémentaire intacts sur les Golems ravarage et les Assemblages porteguerre qui protègent Argelmach. Vous savez cela car vous êtes médium.', },
  },
  [4081] = {
    'TUER À VUE : nains sombrefers',
    {'Par ordre du chef de guerre Sangredent, commandant du Corps Expéditionnaire de Kargath :|n|nTous les membres des forces du général Forgehargne présents dans les Profondeurs de Rochenoire doivent être annihilés.|n|nLes hommes de Forgehargne sont des tueurs de sang-froid, responsables du massacre de masse de la 109e division du corps expéditionnaire de Kargath. Les héros doivent exercer avec une prudence extrême lorsqu\'ils combattent ces brutes.|n|nQuiconque détruira la première ligne des forces du général Forgehargne dans les Profondeurs de Rochenoire recevra un tribut.', },
    {'Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !|n|nLe chef de guerre Sangredent veut que vous tuiez 15 Gardes ragenclumes, 10 Gardiens ragenclumes et 5 Fantassins ragenclumes. Retourner le voir une fois votre mission accomplie.', },
  },
  [4082] = {
    'TUER À VUE : Officiers de haut rang sombrefers',
    {'Par ordre du chef de guerre Sangredent, commandant du Corps Expéditionnaire de Kargath :|n|nLe chef du service de renseignement du C.E.K., le grand maître Lexlort, et revenu avec des informations concernant l\'endroit approximatif où se trouveraient les officiels de haut rang sombrefers. Derrière une porte verrouillée et près du cœur de la cité, ils entraînent leurs forces pour faire périr nos hommes. Partez pour les profondeurs de Rochenoire et tuez-les !|n|nLa réussite de cette mission vous vaudra un tribut.', },
    {'Pénétrez dans les Profondeurs de Rochenoire et tuez les vils agresseurs !|n|nLe Chef de guerre Sangredent veut que vous tuiez 10 Médecins ragenclumes, 10 Soldats ragenclumes et 10 Officiers ragenclumes. Retourner le voir une fois votre mission accomplie.', },
  },
  [4083] = {
    'Le Calice spectral',
    nil,
    nil,
  },
  [4084] = {
    'Cœur d\'argent',
    {'Je ne connais pas la personne dont vous parlez, $N.|n|nMais ne vous inquiétez pas ; si votre ami était en voyage pour venir me trouver, je sais ce qu\'il recherchait.|n|nAu cœur du cratère d\'Un\'Goro demeure un mal sous sa forme la plus pure. Ce mal prend la forme d\'un élémentaire du nom de Coursembrase... Il est protégé par une aura que personne ne peut dissiper.|n|nPersonne... à part ceux qui ont suffisamment de pouvoir pour y parvenir. Je peux vous apprendre ce pouvoir, $N.|n|nD\'abord, faites ce que je vous demande. Trouvez 11 Griffes d\'argent et 1 Cœur d\'Arbrefer sur les créatures de Gangrebois, puis revenez.', },
    {'Trouver 11 Griffes d\'argent et 1 Cœur d\'Arbrefer pour Eridan Ventebleu à Gangrebois.', },
  },
  [4101] = {
    '[PÉRIMÉ]Purifiez Gangrebois',
    {'Les plantes procurent de la vie à Gangrebois, mais elles-mêmes souffrent des souillures de la corruption. Je connais les moyens de les en débarrasser, mais je ne peux enseigner une telle connaissance qu\'à ceux en qui j\'ai une entière confiance. Prouvez-moi que vous soutiendrez véritablement la cause du Cercle cénarien !|n|nVous trouverez les cavernes d\'Arbrefer, au nord. Les élémentaires de Crochebois qui s\'y trouvent ne peuvent plus être purifiés, à présent. Je vous demande de m\'apporter leur essence, appelée l\'ambre de sang, afin que je l\'étudie dans l\'espoir de sauver les autres formes de vie ici.', },
    {'Apportez 15 Ambres de sang à Arathandris Argeciel, à Gangrebois.', },
  },
  [4102] = {
    '[PÉRIMÉ]Purifiez Gangrebois',
    {'Les plantes procurent de la vie à Gangrebois, mais elles-mêmes souffrent des souillures de la corruption. Je connais les moyens de les en débarrasser, mais je ne peux enseigner une telle connaissance qu\'à ceux en qui j\'ai une entière confiance. Prouvez-moi que vous soutiendrez véritablement la cause du Cercle cénarien !|n|nVous trouverez les cavernes d\'Arbrefer, au nord. Les élémentaires de Crochebois qui s\'y trouvent ne peuvent plus être purifiés, à présent. Je vous demande de m\'apporter leur essence, appelée l\'ambre de sang, afin que je l\'étudie dans l\'espoir de sauver les autres formes de vie ici.', },
    {'Apportez 15 Ambres de sang à Maybess Brise-des-rivières, à Gangrebois.', },
  },
