  [5892] = {
    'Fournitures de Gouffrefer',
    {'Avant que les combats ne commencent, nous avons stocké du matériel pour Dun Baldar dans la mine de Gouffrefer. Les troggs qui ont débarqué ne représentaient pas un grand problème tant que nous disposions de troupes pour surveiller la mine, mais maintenant que nous nous battons contre la Horde, nous ne pouvons plus en garder le contrôle.|n|nNous avons besoin du matériel qui se trouve à Gouffrefer, $N. Entrez dans la mine et rapportez-m\'en un chargement.', },
    {'Apporter 10 Fournitures de Gouffrefer à l\'Intendant de l\'Alliance de Dun Baldar.', },
  },
  [5893] = {
    'Fournitures de Froide-dent',
    {'La mine de Froide-dent au nord était autrefois l\'endroit idéal pour stocker des réserves de matériel, mais maintenant que les combats contre les Foudrepiques deviennent de plus en plus violents, nous n\'avons pas toujours assez de guerriers pour en stationner à la mine pour la protéger. Le contrôle de la mine passe donc souvent à l\'Alliance ou à ses habitants souterrains...|n|nMais nous avons grand besoin de nos fournitures, $N ! Allez à la mine de Froide-dent et rapportez-m\'en un chargement. Et prenez garde aux ennemis en chemin. L\'équilibre des forces en présence peut changer très vite là-bas...', },
    {'Apportez 10 Fournitures de Froide-dent à l\'intendant de la Horde, au Donjon Loup-de-givre.', },
  },
  [5901] = {
    'Une Plaie sur la Croisade',
    {'Ainsi, afin que la Croisade écarlate connaisse la douleur et la lutte, je veux lui prendre sa précieuse scierie. Je suis sûre que la perte d\'une telle ressource va rendre beaucoup plus difficiles la défense et la reconstruction de la ville. Allez-vous m\'aider, $N ? |n|nCommencez par vous rendre à Pestebois dans les Maleterres de l\'Est. Remplissez cette fiole avec les termites que vous trouverez dans leurs monticules disséminés dans les bois. Revenez quand vous en aurez assez.', },
    {'Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l\'Est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Mickey Levine, à la Barricade, dans les Clairières de Tirisfal.', },
  },
  [5902] = {
    'Une Plaie sur la Croisade',
    {'Maintenant que nous avons suffisamment de termites, portez ce tonneau cerclé d\'acier à la scierie de la Crête du nord, au sud d\'Âtreval. Vous la trouverez à l\'ouest de la route qui mène jusqu\'en ville.|n|nQuand vous y serez, placez le tonneau au cœur de la scierie, en hauteur, sur une caisse par exemple, et ouvrez-le.|n|nLe reste se fera tout seul. Revenez me voir et je vous récompenserai pour votre aide.', },
    {'Trouver un endroit judicieux au centre de la scierie de la Crête du nord, dans les Maleterres de l\'Ouest, pour placer le Tonneau de Termites des Maleterres.', },
  },
  [5903] = {
    'Une Plaie sur la Croisade',
    {'J\'ai plusieurs fois essayé d\'employer la force pour barrer la route à la Croisade écarlate, mais en vain. Alors j\'ai décidé de lui pourrir la vie.|n|nSi vous voulez m\'aider, nous allons introduire dans cette scierie les plus terribles des termites.|n|nDans Pestebois, près de Stratholme, autrefois si grande, prospère une espèce de termites qui a survécu à la fois à la peste et au Fléau. Trouvez leurs termitières et remplissez cette fiole. Nous allons les lâcher sur la Croisade...', },
    {'Utiliser le Pot de Termites vide sur la Termitière, dans les Maleterres de l\'est. Après avoir récupéré 100 Termites des Maleterres, retourner voir Nathaniel Dumah, au camp du Noroît, dans les Maleterres de l\'Ouest.', },
  },
  [5904] = {
    'Une Plaie sur la Croisade',
    {'Maintenant que nous avons les termites, prenez ce tonneau renforcé, et apportez-le à la scierie de la Crête du nord, au sud d\'Âtreval. Vous la trouverez à l\'ouest de la route qui mène à la ville.|n|nUne fois sur place, placez le tonneau au centre de la scierie. Trouvez un endroit approprié, comme une caisse, posez-le dessus, puis ouvrez-le. Les termites feront leur travail, rongeront le bois des poutres, et rendront la scierie inutilisable pour la Croisade.', },
    {'Trouver un endroit judicieux au centre de la scierie de la Crête du nord, dans les Maleterres de l\'Ouest, pour placer le Tonneau de Termites des Maleterres.', },
  },
  [5921] = {
    'Reflet-de-Lune',
    {'Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, indépendamment des relations actuelles tendues entre l\'archidruide Forteramure et le gardien Remulos – le gardien de Reflet-de-Lune. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.|n|nPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Brasétoile, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.', },
    {'Utiliser le sort « Téléportation : Reflet-de-Lune » pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Brasétoile, au village de Havrenuit.', },
  },
  [5922] = {
    'Reflet-de-Lune',
    {'Tous les druides sont les bienvenus sur les terres sacrées de Reflet-de-Lune, taurens ou elfes de la nuit. Le gardien Remulos – le gardien de Reflet-de-Lune – surveille de près tous les druides qui hivernent ici. Maintenant que vous apprenez la voie de la Griffe, je vous enseignerai le charme qui pourra vous transporter là-bas. Utilisez-le chaque fois que vous chercherez la connaissance ou la consolation de Reflet-de-Lune.|n|nPour votre première leçon, allez à Reflet-de-Lune et parlez à Dendrite Brasétoile, à Havrenuit, du chemin sur lequel vous vous engagez maintenant. Bonne chance, jeune druide.', },
    {'Utiliser le sort « Téléportation : Reflet-de-Lune » pour aller à Reflet-de-Lune. Une fois sur place, parler à Dendrite Brasétoile, au village de Havrenuit.', },
  },
  [5923] = {
    'Écouter l\'appel',
    {'Excusez-moi, vous...|n|nJ\'ai cru comprendre que Mathrengyl Pasdelours souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu\'il veuille vous former personnellement. Mathrengyl est l\'assistant direct de l\'archidruide lui-même et l\'un des druides les plus sages et les plus reconnus de Teldrassil.|n|nIl se trouve dans l\'Enclave cénarienne à Darnassus, au deuxième étage de l\'arbre de Fandral Forteramure.', },
    {'Parler à Mathrengyl Pasdelours, dans l\'Enclave cénarienne, à Darnassus.', },
  },
  [5924] = {
    'Écouter l\'appel',
    {'Excusez-moi, vous...|n|nJ\'ai cru comprendre que Mathrengyl Pasdelours souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu\'il veuille vous former personnellement. Mathrengyl est l\'assistant direct de l\'archidruide lui-même et l\'un des druides les plus sages et les plus reconnus de Teldrassil.|n|nIl se trouve dans l\'Enclave cénarienne à Darnassus, au deuxième étage de l\'arbre de Fandral Forteramure.', },
    {'Parler à Mathrengyl Pasdelours, dans l\'Enclave cénarienne, à Darnassus.', },
  },
  [5925] = {
    'Écouter l\'appel',
    {'Excusez-moi, vous...|n|nJ\'ai cru comprendre que Mathrengyl Pasdelours souhaitait vous parler. Il semble que votre formation de druide soit sur le point de prendre un nouveau tournant et qu\'il veuille vous former personnellement. Mathrengyl est l\'assistant direct de l\'archidruide lui-même et l\'un des druides les plus sages et les plus reconnus de Teldrassil.|n|nIl se trouve dans l\'Enclave cénarienne à Darnassus, au deuxième étage de l\'arbre de Fandral Forteramure.', },
    {'Parler à Mathrengyl Pasdelours, dans l\'Enclave cénarienne, à Darnassus.', },
  },
  [5926] = {
    'Écouter l\'appel',
    {'Excusez-moi...|n|nJ\'ai entendu dire que Turak Totem-runique voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu\'il veuille vous former personnellement. Turak est l\'un des assistants des archidruides ; il a la réputation d\'être sage et patient et il devrait bien vous former.|n|nIl est aux Pitons-du-Tonnerre, dans la tente principale du Cercle cénarien sur la cime des Anciens.', },
    {'Parler à Turak Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre.', },
  },
  [5927] = {
    'Écouter l\'appel',
    {'Excusez-moi...|n|nJ\'ai entendu dire que Turak Totem-runique voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu\'il veuille vous former personnellement. Turak est l\'un des assistants des archidruides ; il a la réputation d\'être sage et patient et il devrait bien vous former.|n|nIl est aux Pitons-du-Tonnerre, dans la tente principale du Cercle cénarien sur la cime des Anciens.', },
    {'Parler à Turak Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre.', },
  },
  [5928] = {
    'Écouter l\'appel',
    {'Excusez-moi...|n|nJ\'ai entendu dire que Turak Totem-runique voulait vous parler. Il semble que votre formation soit sur le point de prendre une nouvelle voie et qu\'il veuille vous former personnellement. Turak est l\'un des assistants des archidruides ; il a la réputation d\'être sage et patient et il devrait bien vous former.|n|nIl est aux Pitons-du-Tonnerre, dans la tente principale du Cercle cénarien sur la cime des Anciens.', },
    {'Parler à Turak Totem-Runique, sur la Cime des Anciens des Pitons-du-Tonnerre.', },
  },
  [5929] = {
    'Esprit du Grand ours',
    {'Au nord-ouest de Reflet-de-Lune se trouve la demeure d\'un être sage et noble que nous appelons l\'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l\'ours. A un moment, tous les druides cherchent la sagesse de l\'esprit et vous ne ferez pas exception.|n|nAllez voir l\'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.', },
    {'Aller voir l\'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu\'il peut vous enseigner sur la nature de l\'ours. Quand cela est fait, retourner voir Dendrite Brasétoile, à Havrenuit, dans Reflet-de-Lune.', },
  },
  [5930] = {
    'Esprit du Grand ours',
    {'Au nord-ouest de Reflet-de-Lune se trouve la demeure d\'un être sage et noble que nous appelons l\'esprit du Grand ours. Il a été le professeur particulier de tous les druides et leur mentor pour leur première approche de la compréhension naturelle de l\'ours. A un moment, tous les druides cherchent la sagesse de l\'esprit et vous ne ferez pas exception.|n|nAllez voir l\'esprit du Grand ours maintenant et prenez son enseignement. Quand il sera satisfait de vous, revenez me voir à Havrenuit. Nous verrons alors si vous avez vraiment profité de ses leçons.', },
    {'Aller voir l\'esprit du Grand ours, au nord-ouest de Reflet-de-Lune et apprendre ce qu\'il peut vous enseigner sur la nature de l\'ours. Quand cela est fait, retourner voir Dendrite Brasétoile, à Havrenuit, dans Reflet-de-Lune.', },
  },
  [5931] = {
    'Retour à Darnassus',
    {'Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Mathrengyl Pasdelours vit en complète harmonie avec l\'équilibre naturel, bien que résidant à proximité de l\'endroit où cet équilibre a vacillé. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l\'équilibre naturel.|n|nPartez maintenant. Nous nous reverrons bientôt.', },
    {'Retourner à Darnassus et parler à Mathrengyl Pasdelours, dans l\'Enclave cénarienne.', },
  },
  [5932] = {
    'Retour vers les Pitons-du-Tonnerre',
    {'Le temps est venu pour nous de nous séparer. La mise en pratique des leçons que vous avez apprises vous ramènera vers la personne qui vous a demandé de venir me voir. Bien que les taurens passent pour novices dans les voies de Cénarius, Turak Totem-runique est en totale harmonie avec la nature. Écoutez attentivement ses instructions et vous aurez achevé vos premières leçons en tant que protecteur de l\'équilibre naturel.|n|nPartez maintenant. Nous nous reverrons bientôt.', },
    {'Retourner aux Pitons-du-Tonnerre, et parler à Turak Totem-Runique, sur la Cime des Anciens.', },
  },
  [5941] = {
    'Retourner voir Chromie',
    {'Vous avez collecté maintes reliques de la bataille de Comté-de-Darrow. À chaque fois que vous en avez rapporté davantage, mon cœur se languissait un peu plus de mon village, et je brûlais de le protéger de son destin.|n|nJe sais que cela ne se peut, mais Chromie, cette étrange gnome à Andorhal, m\'a dit que c\'était possible. Elle dit que vous avez le pouvoir de sauver Comté-de-Darrow !|n|nElle m\'a demandé de rassembler les reliques et de vous les donner pour que vous les lui apportiez. Elle a dit qu\'elle vous attendait dans l\'auberge en ruine d\'Andorhal.', },
    {'Apporter l\'Ensemble de reliques à Chromie, à Andorhal.', },
  },
  [5942] = {
    'Trésors cachés',
    {'Papa m\'a demandé de vous donner cette clé. Il dit qu\'elle ouvre un coffre, derrière la maison.|n|nIl voulait aussi que je vous remercie. Vous l\'avez aidé ? Vous lui avez dit que vous aviez retrouvé ma poupée ?|n|nEnfin, voici la clé. Et merci, $N. Merci ! Vous êtes $Gun très gentil monsieur:une très gentille dame; !', },
    {'Utiliser la Clé de Joseph sur le Coffre de Joseph.', },
  },
  [5943] = {
    'La caravane de Gizelton',
    {'Vous semblez compétent, $R. Peut-être voudriez-vous gagner un peu d\'argent ? Cork et moi avons monté cette caravane pour faire fortune, mais nous ignorions les dangers que recélait cette entreprise !|n|nDevant nous se trouve le convent de Mannoroc… En temps normal, les démons nous ignorent mais quelque chose a effrayé les kodos, ce coup-ci. Je vous paierai pour protéger la caravane lorsque nous passons près du convent de Mannoroc. Quand nous aurons traversé ce coin, vous pourrez aller chercher votre récompense auprès de notre associé, Smeed, au camp de Fouillevis.', },
    {'Escorter la caravane de Gizelton à travers le convent de Mannoroc. Parler à Smeed, au camp de Fouillevis, pour toucher la récompense.', },
  },
  [5944] = {
    'En rêve',
    {'Depuis longtemps, je ne suis qu\'une marionnette du Grand croisé. Quelle raison y avait-il de lutter contre ce que la Croisade écarlate était devenue ? Après toutes ces années, c\'est seulement grâce à la mémoire de mon père que je dois d\'être encore en vie, aujourd\'hui.|n|nJe fais des rêves, et mon père y est à mes côtés. Il se tient fièrement à ma droite, tandis que l\'on m\'intronise dans l\'ordre. Ensemble, nous abattons des légions entières de soldats du Fléau, et faisons étinceler l\'honneur de l\'Alliance et de Lordaeron.|n|nJ\'en ai assez de ces rêves.|n|nAmenez-moi auprès de lui.', },
    {'Escortez Taelan Fordring jusqu\'à la sortie d\'Âtreval.', },
  },
  [5961] = {
    'Le champion de la reine banshee',
    {'Ça me fait plaisir de voir les plus valeureux se joindre à nous. Nos effectifs enflent et se renforcent de jour en jour. Peut-être êtes-vous en mesure de tester votre courage et votre force, $C ?|n|nNathanos figurait parmi les premiers de mes champions ; il est connu maintenant sous le nom de Flétrisseur. Très peu ont autant d\'engagement et de vigueur que lui, dans nos rangs.|n|nAllez à sa rencontre, dans les Maleterres de l\'est. Il vit dans la ferme des Marris. De temps en temps, il parcourt les terres et massacre tous les membres du Fléau et de l\'Alliance qu\'il croise sur sa route.', },
    {'Parler à Nathanos le Flétrisseur, dans les Maleterres de l\'Est. Il se trouve actuellement à la ferme des Marris.', },
  },
  [5981] = {
    'Géants déchaînés',
    {'Il y a environ quatre mille ans, Tyrande Murmevent a sauvé la reine des sabres-de-givre, aux prises avec des géants déchaînés. Depuis, les sabres-de-givre sont les alliés des elfes de la nuit.|n|nCes géants, qui étaient autrefois un danger pour les sabres-de-givre, existent toujours. Ce sont les géants Cognegivre et ils sont installés dans la grande vallée au sud, pas très loin d\'ici.|n|nProuvez votre fidélité aux sabres-de-givre : tuez-en au nom de leur reine, Shy-Rotam !', },
    {'Rivern Givrevent voudrait que vous tuiez 4 Géants Cognegivre et 4 Protecteurs Cognegivre.', },
  },
  [6001] = {
    'Corps et cœur',
    {'A l\'est d\'Auberdine se trouvent plusieurs grottes de séléniens. Celle qui est la plus proche d\'Auberdine contient une pierre des séléniens. Lunegriffe, le défenseur de la pierre, ne vous affrontera que si la poussière de lune cénarienne est appliquée sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme doivent le faire tous les druides de la Griffe.|n|nVous avez gagné le droit d\'utiliser cette poussière de lune cénarienne, $N... Maintenant, montrez-moi que vous avez aussi gagné celui d\'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !', },
    {'Utiliser la Poussière de lune cénarienne sur la Pierre des séléniens d\'Auberdine pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu\'il possède.|n|nQuand cela est fait, parler à Mathrengyl Pasdelours, à Darnassus.', },
  },
  [6002] = {
    'Corps et cœur',
    {'À l\'ouest de Taurajo, dans les Tarides, juste avant Mulgore, se trouve une pierre des séléniens. Les séléniens sont des créatures spéciales qui ne sont pas originaires de ce pays. Lunegriffe, le défenseur de la pierre, vous affrontera lorsque vous appliquerez la poussière lunaire cénarienne sur la pierre. Lunegriffe possède une force que vous devez vous approprier, comme tous les druides de la Griffe.|n|nVous avez gagné le droit d\'utiliser cette poussière lunaire cénarienne, $N... Maintenant montrez-moi que vous avez aussi gagné celui d\'acquérir la force physique et spirituelle que tout druide digne de ce nom se doit de posséder !', },
    {'Utiliser la Poussière lunaire cénarienne sur la Pierre des séléniens, entre Mulgore et les Tarides, pour invoquer Lunegriffe. Affronter Lunegriffe, et gagner la force physique et spirituelle qu\'il possède.|n|nQuand cela est fait, parler à Turak Totem-Runique, aux Pitons-du-Tonnerre.', },
  },
  [6004] = {
    'Un travail inachevé',
    {'On m\'a envoyée en reconnaissance, pour affaiblir et juger les défenses d\'Âtreval. Certaines personnes, dans l\'Alliance, pensent que l\'importance de la petite ville n\'est pas seulement d\'ordre historique. Je ne suis pas là pour poser des questions quant à ce qui fait l\'importance de cette ville ; je suis de toute façon bien trop épuisée pour l\'instant pour pouvoir continuer. Je dois me reposer.|n|nSi vous le voulez, je vous paierai largement en échange de votre aide. Commencez au sud, par l\'un de leurs camps, près de petit rempart qu\'ils ont érigé. Si vous faites vos preuves, je vous emploierai pour m\'aider dans ma mission principale.', },
    {'Tuer deux Médecins écarlates, deux Chasseurs écarlates, deux Magi écarlates et deux Chevaliers écarlates avant de revenir vers Krista Fondombre dans les Maleterres de l\'Ouest.', },
  },
  [6021] = {
    'Zaeldarr le Banni',
    {'Pouvez-vous croire qu\'après tous les ennuis que nous avons dans les Maleterres, il faille maintenant se préoccuper également des voleurs ? Et pas des voleurs normaux, des voleurs trolls.|n|nEt pas seulement des voleurs trolls normaux, des voleurs trolls morts-vivants !|n|nIls sont dirigés par un troll mort-vivant qui répond au nom de Zaeldarr le Banni, et ils viennent ici la nuit pour voler des corps dans la fosse, plus bas, puis ils les ramènent dans leur cache de trolls morts-vivants : le caveau de Zaeldarr, à l\'ouest.|n|nAllez là-bas et tuez Zaeldarr, $N. Je ne peux plus supporter sa méchanceté !', },
    {'Apportez la Tête de Zaeldarr au Conservateur Alen, à la chapelle de l\'Espoir de Lumière.', },
  },
  [6022] = {
    'Tuer utile',
    {'Tant que vous travaillerez pour moi, vous tuerez sur commande.|n|nVotre première tâche consiste à nourrir mes chiens.|n|nPrenez ce mortier et ce pilon, et allez à la Croisée de Corin. Une fois sur place, vous trouverez une belle brochette de membres du Fléau à tuer. Sur leurs carcasses encore tièdes, collectez de la Pourriture vivante ; vous la pulvériserez ensuite dans le mortier, puis laisserez le tout coaguler. Rapportez-moi la pourriture coagulée.|n|nEt puis, imbécile, rappelez-vous que la pourriture vivante, prélevée sur des morts-vivants, ne reste pas vivante bien longtemps ; aussi, faites vite !', },
    {'Allez à l\'est à la Croisée de Corin et détruisez les membres du Fléau qui habitent la ville. Rassemblez 7 morceaux de Pourriture vivante en moins de 10 minutes. Utilisez le Mortier et le Pilon pour réduire la Pourriture vivante en Pourriture coagulée.', },
  },
  [6023] = {
    'Un travail inachevé',
    {'Ma véritable mission était d\'affaiblir les forces extérieures de la Croisade écarlate, puis d\'infiltrer Âtreval pour faire une estimation de leur nombre. Je ne suis toujours pas en mesure de le faire moi-même, aussi pourriez-vous peut-être m\'aider, une fois encore, $N ? D\'après les informations que j\'ai collectées avant d\'être découverte, la Croisade comprend deux membres, lesquels constituent l\'épine dorsale de leurs forces à l\'extérieur de la ville : le veneur Radley et le cavalier Durgen. Les tuer représentera déjà un progrès. Ils devraient se trouver le long de la Passe d\'Âtreval, à l\'extérieur de la ville.', },
    {'Tuer le veneur Radley et le cavalier Durgen, avant de retourner voir Kirsta Fondombre, dans les Maleterres de l\'Ouest.', },
  },
  [6024] = {
    'L\'appel d\'Hameya',
    {'Tuez-moi. Avant qu\'il ne soit trop tard.|n|nJe suis Hameya. Tandis que je voyageais vers Zul\'Mashar, mes frères et moi avons mangé de la viande corrompue... et nous avons changé. Nous sommes infectés.|n|nJ\'entends les mots de la liche, maintenant, qui me pressent de me rendre à Zul\'Mashar pour y infecter encore plus de monde. Je ne peux y résister ; ainsi, j\'ai écrit ce parchemin, avant que toutes mes forces et ma volonté ne me quittent définitivement.|n|nJ\'ai enterré un coffre dans la terre, à proximité d\'un chariot, derrière cette crypte. Seule ma clé pourra l\'ouvrir, et cette clé est en ma possession. Si vous voulez mon trésor, vous devrez me trouver.|n|nTuez-moi, avant qu\'il ne soit trop tard.', },
    {'Tuer l\'Infiltrateur Hameya. Utiliser sa clé sur le Monticule de poussière, derrière le caveau de Zaeldarr.', },
  },
  [6025] = {
    'Un travail inachevé',
    {'Quoi ? Vraiment ? Vous voulez en savoir plus ? Mais vous avez déjà fait tant pour moi, $N. Je ne peux quand même pas vous demander d\'entrer à Âtreval pour me défendre.|n|nC\'est sûr, $N ? Âtreval est beaucoup plus dangereux que le Passage, et je ne peux vous fournir ni protection ni même d\'informations sur les risques que vous prenez.|n|nEh bien ! Si vous désirez vraiment m\'aider, pénétrez dans la ville et cherchez un endroit en hauteur, pour dominer toute la ville. De là vous pourrez voir combien ils sont et revenir me l\'annoncer. Mais faites preuve de prudence...', },
    {'Aller à Âtreval, et trouver un poste d\'observation élevé d\'où voir la ville et jauger les forces de la Croisade écarlate, puis retourner voir Kirsta Fondombre, dans les Maleterres de l\'Ouest.', },
  },
  [6026] = {
    'Voilà qui est beaucoup demander',
    {'Ces agents de l\'Aube d\'argent ont chargé le vieux Smokey de réaliser un petit travail de démolition. La maman du vieux Smokey n\'a pas élevé un simplet : dès que des écus tintent, Smokey est disponible et prêt à rendre service. C\'est mon mot d\'ordre !|n|nJe serais maintenant disposé à partager la commission avec vous, si vous étiez d\'accord pour exécuter un petit travail sur le terrain. Voici l\'idée : je vais me diriger vers Pestebois et marquer tous les bâtiments qui sont destinés à être détruits. Pendant ce temps, vous collecterez les composants qui sont nécessaires à la confection des bombes. Qu\'en dites-vous ?', },
    {'Smokey LaRue veut que vous lui apportiez 2 Barres de thorium, 1 Bâtonnet doré, 8 Bombes explosives et 8 Déclencheurs instables.|n|nVous devrez trouver un forgeron et un ingénieur pour obtenir ces objets.', },
  },
  [6027] = {
    'Livre des Anciens',
    {'$N, je vous confie la Gemme du serpent. Placez cette gemme dans la main de la Statue du serpent qui se trouve sur l\'île de Ranazjar, une petite île au nord-ouest d\'ici. En même temps, vous appellerez celui qui protège le livre des Anciens. Ce livre contient les secrets des nagas, des secrets qui ont été gardés pendant des siècles. Apportez-moi ce livre et nous en apprendrons beaucoup sur nos adversaires !', },
    {'Obtenez le Livre des Anciens, puis rapportez-le à Azore Aldamort, dans la tour d\'Ethel Rethor.', },
  },
  [6028] = {
    'Le rapport de Long-Guet',
    {'Je suis à la recherche d\'une personne sérieuse qui voudrait m\'aider pour une petite affaire qui n\'est pas sans importance. Je suis ici en tant que représentant de l\'Aube d\'argent, auprès des dirigeants de Long-Guet. J\'ai besoin d\'obtenir un rapport et de le transmettre à l\'officier de l\'Aube d\'argent, Purecarde, au camp du Noroît. L\'endroit se trouve le long de la lisière sud des Maleterres de l\'ouest.|n|nL\'occasion serait trop belle de vous présenter à ma supérieure, et peut-être d\'en obtenir du travail !', },
    {'Apportez le Rapport de Long-Guet à l\'officier de l\'Aube d\'argent Purecarde au Camp du Noroît, dans les Maleterres de l\'Ouest.', },
  },
  [6029] = {
    'Le rapport de Long-Guet',
    {'Je cherche une personne sérieuse pour m\'aider dans une petite affaire, qui n\'en est pas moins importante. Je représente les intérêts de l\'Aube d\'argent devant l\'autorité locale de Long-Guet. J\'ai besoin de fournir un rapport à l\'officier de l\'Aube d\'argent, Garush, à la Barricade ; cela se trouve à quelque distance d\'ici, le long de la lisière ouest des Maleterres de l\'Ouest, à l\'est des clairières de Tirisfal.|n|nCela serait l\'occasion de vous présenter à mon supérieur, et peut-être d\'obtenir du travail, sous son commandement !', },
    {'Livrer le Rapport de Long-Guet à l\'officier Garush de l\'Aube d\'argent, à la Barricade, dans les Maleterres de l\'Ouest.', },
  },
  [6030] = {
    'Duc Nicholas Zverenhoff',
    {'Umbranse, un médium qui vit en reclus dans la région, a offert à l\'Aube d\'argent un chef-d\'œuvre de littérature... un de ceux qui comprennent une quantité indécente de blabla en prose.|n|nL\'un des chefs les plus respectés de l\'Aube, le duc Nicholas Zverenhoff, est aussi un brillant linguiste. Pourriez-vous lui apporter cela de ma part, contre une récompense ? La chapelle de l\'Espoir de Lumière, c\'est là qu\'il réside en ce moment. L\'endroit se trouve loin à l\'est, à l\'intérieur des Maleterres de l\'est.', },
    {'Apportez le livre « Études sur la langue des Esprits » au duc Nicholas Zverenhoff, à la chapelle de l\'Espoir de Lumière, dans les Maleterres de l\'Est.', },
  },
  [6031] = {
    'Etoffe runique',
    {'À Grumegueules, nous sommes satisfaits d\'être entre nous. Nous n\'aimons pas les étrangers, ce qui n\'arrange malheureusement pas le commerce.|n|nIl n\'y a pas longtemps, une de nos rares amis elfe de la nuit est arrivée à Grumegueules, portant une cape en étoffe runique. L\'étoffe runique est un textile que l\'on ne voit pas souvent par ici, et mes frères ont été séduits par sa perfection. Ils désirent que je leur procure des vêtements taillés dans cette étoffe.|n|nVoudriez-vous m\'apporter de l\'étoffe runique ? Si vous m\'en apportez suffisamment, je vous donnerai quelque chose en échange.', },
    {'Apportez 30 pièces d\'étoffe runique à Meilosh au Repaire des Grumegueules.', },
  },
  [6032] = {
    'Le vêtement sacré',
    {'Bien que le peuple des Grumegueules sache enchanter les étoffes runiques, elles ne sont pas sacrées pour nous. Mais l\'étoffe lunaire, elle, est sacrée.|n|nApportez-m\'en un petit morceau et je vous apprendrai un secret de fabrication.', },
    {'Apporter 2 pièces d\'Etoffe lunaire à Meilosh, au Repaire des Grumegueules.', },
  },
  [6041] = {
    'Quand Smokey chante, je deviens violent',
    {'Pendant que vous collectiez les provisions, quelques-uns de mes agents ont pu marquer les bâtiments du Fléau que nous devons démolir.|n|nVoici le plan : je m\'en vais vous donner dix bâtons de mon mélange spécial. Vous les porterez à Pestebois et les placerez dans les bâtiments du Fléau qui ont été marqués et sont destinés à sauter.|n|n<Smokey claque des doigts.>|n|nBing ! C\'est pas plus compliqué que ça.', },
    {'Aller à Pestebois, au nord-ouest de la chapelle de l\'Espoir de Lumière. Détruire 8 Bâtiments du Fléau en utilisant le Mélange spécial de Smokey sur les Marques de détonation que portent les bâtiments destinés à être détruits. Smokey a fait marquer les ziggourats et les abattoirs.|n|nUne fois la bombe placée, quitter le bâtiment et contempler le résultat de votre opération.|n|nGarder en tête que le Mélange spécial de Smokey est très... instable.', },
  },
  [6042] = {
    'Les petits soucis de la non-vie',
    {'On ne peut pas faire deux pas hors de cette ferme sans se heurter à une de ces chauves-souris si désagréables. Je veux pouvoir poursuivre ces canailles et combattre le Fléau sans me faire agresser sans arrêt par ces damnées chauves-souris. Mais bon, j\'ai mieux à faire que de passer mon temps à tuer stupidement des chauves-souris, jour après jour. Par contre, vous non !|n|nQuoi ? Votre formation ? Mais la voilà, votre formation ! Maintenant sortez de ma vue et ne revenez pas avant d\'avoir tué un nombre respectable de ces démons ailés. Ne me décevez pas.', },
    {'Tuer 20 Chauves-souris pestiférées nuisibles et 10 Chauves-souris pestiférées monstrueuses. Retourner voir Nathanos le Flétrisseur quand ce sera fait.', },
  },
  [6061] = {
    'Dompter la bête',
    {'En tant que taurens, il est important que nous suivions les traditions de nos ancêtres en affrontant des créatures puissantes. En battant ces créatures, nous pouvons nous nourrir de leur esprit, ce qui nous rapproche de mère Nature.|n|nDe même, apprivoiser une bête pour qu\'elle combatte à nos côtés nous aide à ne faire qu\'un avec la nature qui nous entoure. Vous finirez par apprendre à apprivoiser une bête. Mais tout art demande de la pratique et vous avez beaucoup à apprendre. Commencez en prenant ce Bâtonnet de domptage et allez apprivoiser un trotteur des plaines adulte.', },
    {'Utiliser le Bâtonnet de domptage pour dompter un trotteur des plaines adulte. S\'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Yaw Crin-Tranchant, à Sabot-de-Sang.', },
  },
  [6062] = {
    'Dompter la bête',
    {'C\'est une excellente compétence que de savoir commander à la nature. En tant que chasseur, vous devez vous efforcer d\'utiliser la force et le pouvoir de n\'importe quelle créature.|n|nPrendre le contrôle d\'un animal n\'est pas facile, c\'est une tâche que vous devez entreprendre avec beaucoup de détermination.|n|nPour commencer, prenez ce bâtonnet de domptage et utilisez-le pour apprivoiser un sanglier tacheté redoutable. Vous en trouverez près de Tranchecolline. Entraînez-vous à combattre avec le sanglier à vos côtés, puis revenez me voir.', },
    {'Utiliser le Bâtonnet de domptage pour dompter un sanglier tacheté redoutable. S\'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Thotar de Tranchecolline.', },
  },
  [6063] = {
    'Dompter la bête',
    {'En tant que chasseur, vous devez prendre conscience de vos responsabilités. On ne peut pas plier la nature à ses désirs, elle doit être respectée et reconnue comme bien plus forte que votre propre existence.|n|n$N, vous devez prouver que vous avez compris cela avant de gagner la capacité d\'apprivoiser un animal pour en faire votre compagnon.|n|nVotre première tâche est de prendre ce bâtonnet de domptage. Il vous permettra d\'apprivoiser une rôdeuse Tissebois. Apprivoisez-la et entraînez-vous à chasser ensemble.', },
    {'Utiliser le Bâtonnet de domptage pour dompter une Rôdeuse Tissebois. S\'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Dazalar, à Dolanaar.', },
  },
  [6064] = {
    'Dompter la bête',
    {'Hé là ! Vous voulez savoir comment obtenir un animal de compagnie ?|n|nEh bien commençons ! Il n\'y a rien de plus important qu\'un bon équipement pour aller à la chasse, mais nous discuterons de ma nouvelle pétoire à mitraille une autre fois. Pour le moment, concentrons-nous sur quelque chose qui vous intéresse, j\'en suis sûr : un animal de compagnie !|n|nLa meilleure façon d\'apprendre est d\'essayer avec plusieurs créatures différentes pour voir ce que ça donne. Commencez par trouver un grand sanglier des rochers, utilisez ensuite le bâtonnet de domptage pour l\'apprivoiser.', },
    {'Utiliser le Bâtonnet de domptage pour dompter un Grand sanglier des rochers. S\'entraîner à combattre à ses côtés, puis rapporter le Bâtonnet de domptage à Grif Cœur-sauvage, à Kharanos.', },
  },
  [6065] = {
    'La voie du chasseur',
    {'Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.|n|nVous devez aller voir Yaw Crin-Tranchant dans le Village Sabot-de-Sang. Il vous guidera pour que vous trouviez votre animal de compagnie.', },
    {'Parler à Yaw Crin-Tranchant, à Sabot-de-Sang, en Mulgore.', },
  },
  [6066] = {
    'La voie du chasseur',
    {'Salut, jeune adepte de la chasse. Vous me semblez assez habile pour apprivoiser une bête et en faire votre compagnon.|n|nVous devez aller voir Yaw Crin-Tranchant dans le Village Sabot-de-Sang. Il vous guidera pour que vous trouviez votre animal de compagnie.', },
    {'Parler à Yaw Crin-Tranchant, à Sabot-de-Sang, en Mulgore.', },
  },
  [6067] = {
