  [7667] = {
    'Assistance matérielle',
    {'$N, j\'espère que vous pourrez m\'aider dans une affaire urgente… à la fois matériellement et spirituellement. Laissez-moi vous expliquer.|n|nDans les profondeurs de la Scholomance, en Lordaeron, se trouve une chambre appelée le Grand ossuaire. Je suis en train de terminer un objet qui permettra de percer les ombres de cet horrible endroit. Pour le terminer, j\'ai besoin de deux diamants : un diamant d\'Azeroth et un diamant noir en parfait état. Je sais que cela ne se trouve pas facilement, et je n\'ai pas les moyens de les acheter.|n|nPourriez-vous me les procurer ?', },
    {'Si vous voulez aider Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse d\'Orgrimmar, apportez-lui un Diamant d\'Azeroth et un Diamant noir en parfait état.', },
  },
  [7668] = {
    'La menace de Ravassombre',
    {'Le chevalier de la mort Ravassombre règne sur le Grand ossuaire de la Scholomance. Il se prépare à altérer le monde des esprits pour accomplir ses ténébreuses volontés. Il faut l\'arrêter ! Ce sera le rôle du Clairvoyant que vous m\'avez aidé à préparer.|n|nUtilisez-le au centre du sous-sol du Grand ossuaire pour appeler les esprits qui servent Ravassombre. Lorsque vous les aurez vaincus, le chevalier de la mort apparaîtra en personne. Ramenez-moi sa tête, $N ! Sa mort est la seule chose qui puisse annuler les ravages qu\'il a commis dans le monde des esprits !', },
    {'Servez-vous du Clairvoyant au centre du sous-sol du Grand ossuaire de la Scholomance. Cela attirera des esprits que vous devrez combattre. Les vaincre fera apparaître le Chevalier de la mort Ravassombre. Tuez-le.|n|nRapportez la Tête de Ravassombre à Sagorne Rôdeur-des-crêtes de la Vallée de la Sagesse, à Orgrimmar.', },
  },
  [7669] = {
    'Retour au Grand ossuaire',
    nil,
    nil,
  },
  [7670] = {
    'Seigneur Grayson Brisombre',
    {'$N, le temps est venu d\'apprendre ce que vous devrez faire pour vous procurer quelque chose que vous attendez sans doute depuis longtemps… votre destrier !|n|nAllez parler au seigneur Grayson Brisombre, dans le Quartier de la Cathédrale, à Hurlevent. Il vous apprendra à maîtriser la monture favorite des paladins. Et auparavant, il vous chargera de toutes les tâches que vous devrez accomplir pour vous en procurer un.|n|nJ\'espère que votre épreuve se passera bien. Pour la Lumière, noble $Gfrère:sœur; !', },
    {'Parler au seigneur Grayson Brisombre dans le Quartier de la Cathédrale de Hurlevent.', },
  },
