  [7905] = {
    'La foire de Sombrelune',
    {'La foire de Sombrelune approche ! Participez à nos jeux palpitants, remportez des prix fabuleux, faites-vous dire la bonne aventure !|n|nSi vous agissez maintenant, vous pourrez échanger ce coupon contre des bons gratuits, ainsi qu\'un exemplaire du mondialement célèbre Guide pratique de Sombrelune, qui vous aidera à identifier certains trésors lors de vos voyages !|n|nIl vous suffira de donner ce coupon à Gelvas Crasseporte, à la foire.|n|nActuellement, l\'entrée de la foire se trouve juste à côté de Comté-de-l\'Or, dans la forêt d\'Elwynn.', },
    {'Donnez le Coupon pour des bons gratuits à Gelvas Crasseporte, qui se trouve à la foire de Sombrelune.', },
  },
  [7906] = {
    'Cartes de Sombrelune - Fauves',
    nil,
    nil,
  },
  [7907] = {
    'Suite de Fauves de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Fauves, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Fauves à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [7908] = {
    'Maître de l\'arène',
    {'Être le maître d\'une arène, ça ne doit pas se limiter à ça ! Le pirate qui anime celle des Gurubashi aura peut-être des conseils à me donner.', },
    {'Parler à Court John Mithril dans l\'arène de Strangleronce.', },
  },
  [7926] = {
    'La foire de Sombrelune',
    {'La foire de Sombrelune approche ! Participez à nos jeux palpitants, remportez des prix fabuleux, faites-vous dire la bonne aventure !|n|nSi vous agissez maintenant, vous pourrez échanger ce coupon contre des bons gratuits, ainsi qu\'un exemplaire du mondialement célèbre Guide pratique de Sombrelune, qui vous aidera à identifier certains trésors lors de vos voyages !|n|nIl vous suffira de donner ce coupon à Gelvas Crasseporte, à la foire.|n|nActuellement, l\'entrée de la foire se trouve juste à côté des Pitons-du-Tonnerre, en Mulgore !', },
    {'Donnez le Coupon pour des bons gratuits à Gelvas Crasseporte, qui se trouve à la foire de Sombrelune.', },
  },
  [7927] = {
    'Suite de Portails de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Portails, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Portails à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [7928] = {
    'Suite de Seigneurs de guerre de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Seigneurs de guerre, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
