  [7937] = {
    'Une surprise vous attend...',
    {'Une surprise vous attend au val d\'Est.|n|nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher. Alors que vous la serrez dans votre main, vous avez une vision du camp de bûcherons du Val d\'Est dans la Forêt d\'Elwynn. En vous concentrant sur cette image, vous voyez une meule de foin à côté d\'une écurie.', },
    {'Allez dans le Camp de bûcherons du Val d\'Est dans la Forêt d\'Elwynn pour trouver la surprise qui vous attend.', },
  },
  [7938] = {
    'Une surprise vous attend...',
    {'Une surprise vous attend à l\'intérieur des Mortemines.|n|nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher. Alors que vous la serrez dans votre main, vous avez une vision des Mortemines, situées dans le hameau en ruine de Ruisselune, dans la marche de l\'Ouest. En vous concentrant sur cette image, vous vous voyez emprunter des passages tortueux jusqu\'à ce que vous atteigniez un portail étincelant... qui conduit au cœur même des mines. Lorsque vous le traversez, un étrange coffre apparaît de nulle part.', },
    {'Allez dans les Mortemines dans la marche de l\'Ouest pour trouver la surprise qui vous attend.', },
  },
