  [7944] = {
    'Une surprise vous attend...',
    {'Une surprise vous attend dans les cavernes des Lamentations.|n|nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher. Alors que vous la serrez dans votre main, vous avez une vision d\'une caverne située au sud-ouest de la Croisée, dans les Tarides. En vous concentrant sur cette image, vous vous voyez emprunter des passages tortueux jusqu\'à ce que vous atteigniez un portail étincelant... qui conduit au cœur même de la caverne. Lorsque vous le traversez, un étrange coffre apparaît de nulle part.', },
    {'Allez dans les Cavernes des Lamentations dans les Tarides pour trouver la surprise qui vous attend.', },
  },
  [7945] = {
    'Une surprise vous attend...',
    {'Une surprise vous attend devant le Rocher des crins-pâles.|n|nLa prédiction que Sayge vous a donnée vous semble un peu chaude au toucher. Alors que vous la serrez dans votre main, vous avez une vision du Rocher des crins-pâles en Mulgore. En vous concentrant sur cette image, vous voyez une souche juste à côté de l\'entrée de la caverne.', },
    {'Allez au Rocher des Crins-pâles, en Mulgore, pour trouver la surprise qui vous attend.', },
  },
