  [8171] = {
    'La bataille pour le bassin Arathi !',
    {'Comme vous l\'avez sûrement entendu, la Ligue d\'Arathor envoie un grand nombre de troupes dans le bassin Arathi. Avides de nourriture et de matières premières, ces fous de l\'Alliance ont l\'intention de prendre et de contrôler les riches ressources de cette région. Nous devons leur montrer qu\'Arathor ne sera plus jamais le foyer de pitoyables humains !|n|nAllez dans le bassin Arathi et attaquez la mine, la scierie, la forge et l\'écurie. Mettez à bas la bannière de l\'ennemi, et emparez-vous de ces territoires pour la Horde.|n|nAllez, $N. Revenez me voir quand vous aurez accompli votre tâche.', },
    {'Attaquez la mine, la scierie, la forge et l\'écurie du bassin Arathi, puis revenez voir le Maître de la mort Dwire, au Trépas-d\'Orgrim.', },
  },
  [8181] = {
    'La confrontation avec Yeh\'kinya',
    {'Les tablettes Mosh\'aru contiennent de mauvaises nouvelles, $N. La véritable forme d\'Hakkar, le dieu lui-même, peut renaître par l\'intermédiaire de l\'œuf dans lequel vous l\'avez enfermé. Yeh\'kinya vous avait dit que c\'était pour contenir sa malfaisance, mais c\'était pour la recréer ! Le troll s\'est trompé – ou nous a trompés !|n|nRetournez voir Yeh\'kinya et demandez-lui l\'œuf. Espérons qu\'il n\'est pas trop tard pour empêcher Hakkar de revenir !', },
    {'Parlez à Yeh\'kinya.', },
  },
  [8182] = {
    'La Main de Rastakhan',
    {'$N, nos pires craintes se réalisent. Les légendes racontent que l\'Écorcheur d\'âmes régnait naguère sur les trolls par le mal et la terreur, et il exerçait un pouvoir sans partage. Si nous ne l\'arrêtons pas maintenant, son royaume risque de s\'étendre à tout Azeroth !|n|nLes envoyés des trolls zandalariens nous aideront peut-être à interrompre la montée des ténèbres. Ils se sont installés sur l\'île de Yojamba, sur la côte de Strangleronce, à l\'ouest des ruines de Zul\'Kunda. Parlez à leur chef, Molthor, et prions pour qu\'il sache comment vaincre Hakkar.', },
    {'Parlez à Molthor à Strangleronce.', },
  },
  [8183] = {
    'Le cœur d\'Hakkar',
    {'Le cœur d\'Hakkar brûle de l\'intérieur. En dépit de la défaite de l\'Écorcheur d\'âmes, l\'essence de sa puissance repose encore dans cet organe maudit.', },
    {'Donnez le Cœur d\'Hakkar à Molthor sur l\'île de Yojamba.', },
  },
