  [8227] = {
    'Mètre ruban de Nat',
    {'Au milieu d\'un tas de lignes et de moulinets se trouve un mètre ruban en soie, auquel est attachée une étiquette :|n|n« Nat Pagle, marécage d\'Âprefange ».', },
    {'Rendez le Mètre ruban de Nat à Nat Pagle, au marécage d\'Âprefange.', },
  },
  [8228] = {
