  [8687] = {
    'Objectif : les tunnelières de la Ruche\'Zora',
    {'Nous avons demandé à ce que des renforts rejoignent l\'assaut sur la Ruche\'Zora. Vous avez été $Gchoisi:choisie; pour affronter les tunnelières de la Ruche\'Zora. À la fin de la mission, présentez-vous au rapport devant le commandant Mar\'alith.', },
    {'Tuez 30 Tunnelières de la Ruche\'Zora puis présentez-vous au rapport devant le commandant Mar\'alith au Fort cénarien en Silithus. Pour terminer cette quête, vous devez aussi apporter le Briefing de combat VII.', },
  },
  [8688] = {
    'L\'Ancien Tracevent',
    nil,
    nil,
  },
  [8689] = {
    'Voile de sagesse infinie',
    {'Je suis content de voir que vous allez nous aider pour notre offensive en Ahn\'Qiraj, $N. J\'aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, $C.|n|nJ\'ai besoin pour cela d\'un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J\'ai aussi besoin d\'idoles et de scarabées dont je me servirai pour fabriquer le fermoir.|n|nJe vous promets que vous ne serez pas $Gdéçu:déçue;.', },
    {'Apporter 1 Drapé martial qiraji, 2 Idoles de jaspe, 5 Scarabées d\'or et 5 Scarabées d\'argile à Keyl Vivegriffe, en Silithus. Vous devrez aussi être $GRévéré:Révérée; par le Cercle cénarien pour terminer cette quête.', },
  },
  [8690] = {
    'Cape de la tempête imminente',
    {'Je suis content de voir que vous allez nous aider pour notre offensive en Ahn\'Qiraj, $N. J\'aimerais vous offrir un objet de protection, qui pourra vous servir contre notre ennemi, $C.|n|nJ\'ai besoin pour cela d\'un drapé qiraji, que je retaillerai à vos mesures, bien sûr. J\'ai aussi besoin d\'idoles et de scarabées dont je me servirai pour fabriquer le fermoir.|n|nJe vous promets que vous ne serez pas $Gdéçu:déçue;.', },
    {'Apportez 1 Drapé royal qiraji, 2 Idoles d\'obsidienne, 5 Scarabées d\'or et 5 Scarabées d\'argile à Keyl Vivegriffe, en Silithus. Vous devrez aussi être $GRévéré:Révérée; par le Cercle cénarien pour terminer cette quête.', },
  },
