  [8856] = {
    'Survivre dans le désert',
    {'L\'afflux de nouvelles recrues au Fort cénarien nous pose un problème. Comment les garder en vie dans le désert ? Les volontaires inexpérimentés risquent la déshydratation et l\'empoisonnement – le sable grouille de créatures venimeuses. Rassemblez les matériaux nécessaires à la constitution de paquetages de survie dans le désert, et remettez-les à Calandrath au Fort cénarien.', },
    {'Ramener 4 Globes d\'eau, 4 Anti-venins puissants et 4 Pains de saumon à Calandrath, à l\'auberge du Fort cénarien en Silithus.', },
  },
  [8857] = {
    'Les secrets du Colosse - Ashi',
    {'Je suis à la recherche d\'aventuriers endurcis, désireux de remettre un échantillon prélevé sur le Colosse d\'Ahsi à Orguignard, qui vit à Baie-du-Butin. Non non, pas question de vous approcher du cadavre de cette chose. Prenez l\'un de mes échantillons et surtout, faites vite. Une fois pourri, ce truc ne lui servira plus à rien.', },
    {'Remettre la Carcasse du colosse d\'Ashi à Orguignard Odipnoticus, à Baie-du-Butin.', },
  },
  [8858] = {
    'Les secrets du Colosse - Regal',
    {'Franchement, j\'aimerais mieux balancer cette carcasse de cafard dans la sale gueule d\'Huilepoing… Sauf que j\'suis coincé là à ramasser des bouts du bestiau. Vu sa taille, j\'suis là jusqu\'aux p\'tites heures du matin.|n|nPrenez cet échantillon et portez-le à Huilepoing de ma part. Et vite, $C. Il paye BIEN !|n|nOuais, l\'est à la halte du Thorium, dans la gorge des Vents brûlants.', },
    {'Apporter la Carcasse du colosse de Regal au surveillant Huilepoing, dans la gorge des Vents brûlants.', },
  },
  [8859] = {
    'Les secrets du Colosse - Zora',
    {'Mes serviteurs ont failli se faire tuer en récupérant ce prélèvement. Vous devez absolument vous dépêcher ! Le seigneur Maxwell Tyrosus attend impatiemment un échantillon frais de la carcasse. Il estime que les secrets de ce colosse pourraient nous aidera dans notre lutte contre le Fléau !|n|nComment, vous êtes encore là ?Allez, en route pour l\'Espoir de lumière ! Oui, oui, vous serez généreusement $Grécompensé:récompensée; pour vos efforts…', },
    {'Apporter la Carcasse du colosse de Zora au seigneur Maxwell Tyrosus, à la chapelle de l\'Espoir de lumière, dans les Maleterres de l\'Est.', },
  },
  [8860] = {
    'Les fêtes du Nouvel an !',
    {'Hurlevent organise une fête pour le nouvel an ! De l\'alcool sera distribué gratuitement toute la journée, et la nuit, il y aura des feux d\'artifice ! Ce sera sans doute une jolie fête ! Mais Baie-du-Butin ne sera pas en reste et aura sa propre fête ; et je parie qu\'elle sera bien plus belle !|n|nSinon, l\'aubergiste Allison, à Hurlevent, a besoin de marchandises des Gourmandises Fumebois pour nourrir tous les fêtards. Vous pouvez me faire une faveur, et les livrer à ma place ?|n|nMerci, $N ! C\'est pour l\'aubergiste Allison de la Rose dorée, qui se trouve dans le quartier commerçant de Hurlevent.', },
    {'Apportez les Marchandises des Gourmandises Fumebois à l\'Aubergiste Allison, à Hurlevent.', },
  },
  [8861] = {
    'Les fêtes du Nouvel an !',
    {'Les Pitons-du-Tonnerre organisent une fête pour le nouvel an ! De l\'alcool sera distribué gratuitement toute la journée, et la nuit, il y aura des feux d\'artifice ! Ce sera sans doute une jolie fête ! Mais Baie-du-Butin ne sera pas en reste et aura sa propre fête ; et je parie qu\'elle sera bien plus belle !|n|nSinon, l\'aubergiste Pala, aux Pitons-du-Tonnerre, a besoin de marchandises des Gourmandises Fumebois pour nourrir tous les fêtards. Vous pouvez me faire une faveur, et les livrer à ma place ?|n|nMerci, $N ! C\'est pour l\'aubergiste Pala, dont l\'établissement est situé près du pont qui mène à la cime des Chasseurs.', },
    {'Apportez les Marchandises des Gourmandises Fumebois à l\'Aubergiste Pala, aux Pitons-du-Tonnerre.', },
  },
  [8862] = {
    'Chandelle d\'Élune',
    nil,
    nil,
  },
  [8863] = {
    'Raviolis de fête',
    nil,
    nil,
  },
  [8864] = {
    'Les robes de la fête lunaire',
    nil,
    nil,
  },
  [8865] = {
    'Les habits de la fête lunaire',
    nil,
    nil,
  },
  [8866] = {
    'L\'Ancien Barbe-de-bronze',
    nil,
    nil,
  },
  [8867] = {
    'Le feu d\'artifice lunaire',
    {'Tous les ans, les druides de Reflet-de-Lune organisent une fête pour célébrer le grand triomphe de notre ville sur un mal ancien.|n|nNous honorons la sagesse de nos ancêtres, partageons d\'excellents festins et, bien sûr, nous tirons des feux d\'artifice !|n|nEn échange d\'une petite donation, vous pourrez vous procurer des fusées colorées auprès de notre vendeur. Essayez d\'utiliser les lanceurs que vous trouverez à proximité, $N.', },
    {'Lancez 8 Feux d\'artifice lunaires et 2 Chapelets de feux d\'artifice lunaires et retournez voir une Messagère de la Fête lunaire dans l\'une des capitales.', },
  },
  [8868] = {
    'La bénédiction d\'Élune',
    {'La bête Présage était autrefois un héros de ce monde, un loup d\'une grande force et d\'une grande valeur. Présage combattit aux côtés des héros de la guerre des Anciens, jusqu\'à ce qu\'il succombe à des magies démoniaques. Se retournant contre ses alliés, il dévasta Azeroth, répandant mort et terreur sur son passage.|n|nIl fut finalement vaincu ici, à Reflet-de-Lune. Présage dort maintenant sous les eaux du lac Élune\'ara. Mais à chaque nouvel an, durant la fête, il s\'agite…|n|nRassemblez des compagnons, $N, pour invoquer et vaincre Présage. Il vous faut mériter la bénédiction d\'Élune !', },
    {'Invoquez Présage, et vainquez-le pour gagner la Bénédiction d\'Élune. Retournez ensuite voir Valadar Chantétoile à Havrenuit.', },
  },
  [8869] = {
    'Douce sérénité',
    {'Aller jusqu\'à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le rapporter à Lilith.', },
    {'Aller jusqu\'à Stratholme et tuer le Forgeur de marteaux cramoisi. Récupérer son Tablier et le rapporter à Lilith.', },
  },
  [8870] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parler à la Messagère de la Fête lunaire à la Garde mystique de Forgefer. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.', },
  },
  [8871] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parlez à la Messagère de la Fête lunaire à Hurlevent.', },
  },
  [8872] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parler à la Messagère de la Fête lunaire à l\'Enclave cénarienne de Darnassus. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.', },
  },
  [8873] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parler à la Messagère de la Fête lunaire dans la Vallée de la Sagesse à Orgrimmar. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.', },
  },
  [8874] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parler à la Messagère de la Fête lunaire à l\'entrée de Fossoyeuse. Vous pouvez aussi parler aux messagères de la Fête lunaire des autres capitales.', },
  },
  [8875] = {
    'La fête lunaire',
    {'C\'est l\'époque des réjouissances, $N ! Le Cercle cénarien invite tous les habitants d\'Azeroth à célébrer avec lui la Fête lunaire. Vous trouverez la messagère de la Fête lunaire dans cette ville, à un endroit marqué par un cercle béni de lumière lunaire. Elle pourra vous en dire plus sur la fête.', },
    {'Parler à la Messagère de la Fête lunaire à la Cime des Anciens des Pitons-du-Tonnerre. Vous pouvez aussi parler aux messagers de la Fête lunaire des autres capitales.', },
  },
  [8876] = {
    'Les petites comètes',
    nil,
    nil,
  },
  [8877] = {
    'Lanceur de feux d\'artifice',
    nil,
    nil,
  },
  [8878] = {
    'Des recettes de fête',
    nil,
    nil,
  },
  [8879] = {
    'Les grandes comètes',
    nil,
    nil,
  },
  [8880] = {
    'Les chapelets de comètes',
    nil,
    nil,
  },
  [8881] = {
    'Les chapelets de grandes comètes',
    nil,
    nil,
  },
  [8882] = {
    'Lanceur de chapelets',
    nil,
    nil,
  },
  [8883] = {
    'Valadar Chantétoile',
    {'Maintenant que vous avez reçu votre invitation pour la Fête lunaire, vous pouvez vous rendre à Reflet-de-Lune. Vous y trouverez de nombreux célébrants. Valadar Chantétoile et sa sœur Fariel attendent ceux qui veulent participer à la célébration au village de Havrenuit.|n|nRendez-vous à Reflet-de-Lune via la lumière lunaire supérieure et parlez à Valadar Chantétoile. Voyons quels cadeaux vous pourrez gagner pendant la fête !', },
    {'Utilisez votre Invitation à la fête lunaire dans la lumière lunaire pour vous rendre à Reflet-de-Lune. À votre arrivée, parlez à Valadar Chantétoile.', },
  },
  [8884] = {
    'Des têtes de poisson à la pelle',
    {'Salutations, $C. Regardez vers la côte ; que voyez-vous ? En effet, notre plage... notre Rivage paisible, est infestée de cette nuisance connue sous le nom de murlocs.|n|nNous devons la libérer de cette plaie !|n|nJ\'ai une tâche à vous confier. Si vous pensez être à la hauteur, je souhaite avoir leurs têtes ! Voyons si nous parvenons à suffisamment réduire leur nombre pour qu\'ils retournent dans les profondeurs troubles d\'où ils sont venus, s\'ils sont un tant soit peu raisonnables !', },
    {'Collecter 8 Têtes de murloc Sinistrécaille et retourner voir Hathvelion Miresoleil dans le bois des Chants éternels sur le piton qui domine le Rivage paisible.', },
  },
  [8885] = {
    'L\'anneau de Mmmrrrggglll',
    {'Les murlocs Sinistrécaille n\'ont pas été effrayés par vos efforts. Mais je crois savoir ce qui leur ferait plier bagage, et me donnerait l\'occasion de me venger par la même occasion.|n|nIls ont un chef murloc qui se donne le nom de Mmmrrrggglll. Il parcourt la Grève dorée au sud du fleuve. Cette bête a un jour tué l\'un de mes compatriotes et porte maintenant son anneau pour nous défier et se moquer de nous.|n|nExécutez Mmmrrrggglll et rapportez-moi l\'anneau de mon ami. Voilà qui devrait suffisamment intimider ces monstres !', },
    {'Récupérez l\'Anneau de Mmmrrrggglll sur la patte sans vie du chef des Sinistrécaille. Rapportez-le à Hathvelion Miresoleil dans le bois des Chants éternels sur le piton surplombant le Rivage paisible.', },
  },
  [8886] = {
    'Les pirates Sinistrécaille !',
    {'Heureusement que vous êtes là, $C ! Ces répugnants murlocs Sinistrécaille ont volé ma cargaison ! Comme si ça ne suffisait pas que les Déshérités aient pris le peu de marchandises magiques que j\'avais, les murlocs ont pris le reste ! Qu\'est donc devenu cet endroit ?|n|nPourriez-vous récupérer ma cargaison ? Je ne m\'attends pas à ce que vous puissiez tout rapporter, mais au point où j\'en suis, je vous serais reconnaissante pour la moindre part. C\'était ce groupe de murlocs Sinistrécaille dans les huttes juste à l\'ouest et au sud du mouillage de la Grève dorée, j\'en suis certaine !', },
    {'Récupérez 6 caisses de la Cargaison du capitaine Kelisendra et rapportez-les à cette dernière au camp protégé juste à l\'est du mouillage des Voiles du soleil dans le bois des Chants éternels.', },
  },
  [8887] = {
    'Les portulans perdus du capitaine Kelisendra',
    {'Intéressant… vous avez trouvé un tube de cuir étanche contenant un certain nombre de feuilles de parchemin. Il s\'agit de toute évidence de cartes marines, et elles portent toutes la signature d\'un certain capitaine Kelisendra.|n|nVous avez entendu parler d\'un petit camp fortifié, juste à l\'est du mouillage des Voiles du soleil. Le capitaine y est peut-être ?', },
    {'Rendez les Portulans perdus du capitaine Kelisendra à cette dernière au camp protégé, juste à l\'est du mouillage des Voiles du soleil dans le bois des Chants éternels.', },
  },
  [8888] = {
    'L\'apprentie du magistère',
    {'$C, écoutez ma requête. Pour des raisons que je ne peux donner pour l\'instant, j\'ai décidé de fermer mon école, qui se trouve près d\'ici. Il y a quelques jours, j\'ai envoyé là-bas l\'une de mes élèves, l\'apprentie Loralthalis. Je n\'ai cependant pas eu de ses nouvelles depuis.|n|nPourriez-vous s\'il vous plaît vous rendre à la Flèche de Ternesoir et vous assurer qu\'elle va bien ? Pour cela, dirigez-vous vers le nord à la sortie de la retraite des Pérégrins, puis allez à droite à l\'embranchement.|n|nMerci.', },
    {'Parler à l\'apprentie Loralthalis près de la Flèche de Ternesoir dans le bois des Chants éternels.', },
  },
  [8889] = {
    'Désactiver la flèche',
    {'Comme vous le savez peut-être déjà, le magistère Ternesoir m\'a envoyée pour désactiver les sources d\'énergie qui alimentent la Flèche. Il y en a trois, chacune à un endroit différent à l\'intérieur.|n|nMalheureusement, comme vous pouvez le constater, on dirait que je suis arrivée trop tard, et la flèche de Ternesoir est envahie d\'étranges créatures magiques. Je n\'ai pas les compétences pour mener à bien cette tâche, mais $Gun:une:c; $C comme vous pourrait sûrement le faire facilement, non ?', },
    {'Désactiver les 3 Sources d\'énergie de la Flèche de Ternesoir à l\'intérieur de la flèche de Ternesoir. Puis rapporter le Joyau de désactivation à l\'apprentie Loralthalis dans le bois des Chants éternels.', },
  },
  [8890] = {
    'Une communication de la flèche',
    {'$N, j\'ai une dernière faveur à vous demander. Voudriez-vous tenir au courant de ce qui s\'est passé ici le magistère Ternesoir à la retraite des Pérégrins ? Dites-lui que je vais bien, mais surtout faites en sorte qu\'il sache que certains apprentis sont devenus des Déshérités.|n|nMerci pour votre aide !', },
    {'Retourner voir le magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.', },
  },
  [8891] = {
    'Des recherches abandonnées',
    {'Vous avez découvert ce qui semble être un journal de recherches, laissé là par le magistère Ternesoir. Un bref examen de son contenu vous révèle de choquantes tentatives de filtration de flux magiques corrompus, ce qui pourrait expliquer ce qui s\'est passé ici à la flèche de Ternesoir. Il est certain que le magistère voudrait qu\'on le lui rapporte.', },
    {'Rapporter le Journal du magistère Ternesoir au magistère Ternesoir à la retraite des Pérégrins dans le bois des Chants éternels.', },
  },
  [8892] = {
    'La situation au mouillage des Voiles du soleil',
    {'Le mouillage des Voiles du soleil a été conquis par des vermines de Déshérités. Dès que nous aurons des renforts, nous montrerons à ces brutes qui est le patron, $N.|n|nDans l\'intervalle, ralentissez-les donc un peu tout en leur apprenant un peu de discipline. Allez-y, et montrez-leur qu\'on ne se moque pas de nous impunément. Vous trouverez le mouillage des Voiles du soleil juste à l\'ouest du village de Brise-clémente.', },
    {'Tuez 5 Nervis déshérités et 5 Voyous déshérités, puis allez faire votre rapport au forestier Degolien au bois des Chants éternels.', },
  },
  [8893] = {
    'Le Super-Oeuf-O-Matic',
    nil,
    nil,
  },
  [8894] = {
    'Corvée de nettoyage',
    {'C\'est affreux ! Affreux ! Il se passe des choses étranges à la flèche, le magistère et ses apprentis s\'enfuient, et juste après, voilà que tout le domaine est infesté de bestioles magiques ! Et qui s\'est donné la peine de prévenir ce pauvre Wyllithen ? Personne, voilà qui !|n|nIl va falloir que vous m\'aidiez à faire disparaître ces monstres, $C… Je ne peux pas entretenir le domaine avec ces « anomalies » qui galopent dans tous les coins !', },
    {'Tuez 6 Serpents de mana et 6 Fieléthers, puis retournez voir le paysagiste Wyllithen, sur les Terres de Ternesoir, dans le bois des Chants éternels.', },
  },
  [8895] = {
    'Une livraison au sanctum septentrional',
    {'Il est bon de découvrir que vous êtes au moins modérément $Gcompétent:compétente;, $N. Et comme vous semblez très $Gdésireux:désireuse; de faire vos preuves, je vais vous confier une autre tâche.|n|nVoici une lettre pour le telluriste Caidanis, l\'arcaniste qui veille à ce que le sanctum septentrional continue à fonctionner. Lorsque vous quittez la place de l\'Épervier, allez au sud-ouest et vous le trouverez. C\'est une personne très importante. J\'espère que vous ne l\'importunerez pas trop avec des bavardages inutiles.', },
    {'Remettre la Lettre sans marque au telluriste Caidanis, au Sanctum septentrional du bois des Chants éternels.', },
  },
  [8896] = {
    'L\'espion des nains',
    {'Vous êtes $Gsûr:sûre; que vous avez trouvé ces notes sur un elfe de la nuit ? Elles sont presque entièrement rédigées dans la langue des nains…|n|nLe prospecteur Garde-enclume ! Il nous est arrivé de Forgefer en mission diplomatique. J\'aurais dû me douter qu\'il s\'intéressait d\'un peu trop près à nos sanctum arcaniques. $N, il se trouve au sanctum septentrional. Trouvez-le et occupez-vous de lui. Discrètement.', },
    {'Trouvez et tuez le prospecteur Garde-enclume au Sanctum septentrional, puis faites votre rapport à Aeldon Signesol, dans le bois des Chants éternels.', },
  },
  [8897] = {
    'Très chère Colara,',
    {'Je suis forcé de rester ici à monter la garde devant la porte, mais je m\'inquiète pour Colara, ma bien-aimée. Je ne la vois que quelques heures, quand j\'ai de la chance, et bon, regardez-moi… J\'ai une paye d\'officier subalterne et on peut m\'expédier au front d\'un moment à l\'autre.|n|nEt si elle m\'oubliait ? Les hommes ne manquent pas en ville. Y compris des hommes riches.|n|nBref, j\'ai essayé de lui écrire. Ce n\'est pas grand-chose, mais si vous pouviez lui apporter ma lettre, ce serait merveilleux.', },
    {'Apporter la Note soigneusement calligraphiée du lieutenant Heldric à Colara Dean, devant la banque de Hurlevent.', },
  },
  [8898] = {
    'Très chère Colara,',
    {'La dernière fois que je suis passé à Hurlevent pour les affaires de la banque, j\'ai rencontré une fille et elle m\'a volé mon cœur. Je n\'arrête pas de penser à elle ! Je lui ai écrit une lettre – je m\'y suis repris à douze fois !|n|nJe n\'ai pas confiance dans la poste, et je veux être sûr qu\'elle l\'aura. Si vous allez dans cette direction, pourriez-vous me rendre service ?', },
    {'Apporter la Lettre froissée à Colara Dean, devant la banque de Hurlevent.', },
  },
  [8899] = {
    'Très chère Colara,',
    {'Comment décrire sa beauté ? Des milliers d\'années à manier les mots, et me voilà à court.|n|nCes mortelles perturbent notre esprit et font de nous des fous balbutiants.|n|nJ\'ai contemplé ces mots pendant trop longtemps. Je ne peux rien en tirer de plus éloquent. Non, elle doit avoir ma lettre maintenant, sans quoi un autre soupirant finira par attirer son attention.', },
    {'Apporter la Lettre immaculée à Colara Dean, devant la banque à Hurlevent.', },
  },
  [8900] = {
    'Très chère Elenia,',
    {'Elle était si triste. Je le voyais bien, en regardant au-delà de son état. Je veux dire, elle semblait triste. Ne l\'auriez-vous pas été ?|n|nMais lorsque je lui ai parlé, nous avons créé un lien. Je n\'aurais jamais cru que quelqu\'un pourrait comprendre ce que je pensais, mais elle y était parvenue.|n|nQuand j\'en ai parlé aux autres, ils se sont moqués de moi, alors je ne lui ai jamais reparlé. Mais elle me manque. Pouvez-vous lui apporter cette lettre de ma part ? Je veux être sûr qu\'elle lui sera remise en mains propres.', },
    {'Apporter la Note légèrement froissée à Elenia Haydon, près de la banque de Fossoyeuse.', },
  },
  [8901] = {
    'Très chère Elenia,',
    {'Avez-vous déjà connu l\'amour, jeune $Ghomme:femme; ? Ce sentiment m\'était totalement étranger, jusqu\'à ce que je rencontre dernièrement une fille de Fossoyeuse, Elenia. Il est déjà rare pour les gens comme nous de chercher ailleurs que dans notre peuple, alors ne parlons même pas des Réprouvés.|n|nMais aujourd\'hui, elle hante mon esprit jour et nuit.|n|nSi cela vous est possible, pouvez-vous lui remettre cette lettre ? Je voudrais qu\'elle vienne ici, en Mulgore. J\'espère qu\'elle dira oui.', },
    {'Apporter la Lettre écrite avec soin à Elenia Haydon, près de la banque de Fossoyeuse.', },
  },
  [8902] = {
    'Très chère Elenia,',
    {'C\'était dans une autre vie, mais j\'ai été promis à Elenia, mon amour d\'enfance. Je l\'avais oubliée depuis des années mais depuis peu, je pense de plus en plus à elle.|n|nMalgré tout ce qui s\'est passé, il reste peut-être un peu de place pour l\'amour dans nos existences.|n|nJe suis sûr qu\'elle a changé, elle aussi. Pouvez-vous lui remettre cette lettre de ma part ? Je suis trop nerveux pour la lui donner en personne.', },
    {'Apporter la Lettre pleine d\'amour à Elenia Haydon, près de la banque de Fossoyeuse.', },
  },
  [8903] = {
    'Les périls de l\'amour',
    {'Il y a quelque chose de pas naturel dans cette épidémie amoureuse. Ce n\'est ni esthétique, ni convenable. Et pire, cela pourrait poser une menace pour la sécurité de l\'Alliance tout entière.|n|nQue se passerait-il si les gardes étaient atteints par cette étrange maladie ? Il faut faire quelque chose.|n|nExaminez donc les gardes de Hurlevent et voyez s\'ils sont devenus aussi déraisonnables que les autres.', },
    {'Obtenez une Carte de garde de Hurlevent et rapportez-la à Aristan Mottar, à Hurlevent.', },
  },
  [8904] = {
    'Les périls de l\'amour',
    {'Il y a quelque chose de pas naturel dans cette épidémie amoureuse. Elle est écœurante, elle affaiblit nos défenses, et elle pourrait nous mettre tous en danger.|n|nQue la plupart d\'entre nous soient en train de se rendre ridicule est déjà déplaisant. Mais j\'ai peur que même nos gardes, qui devraient être immunisés à ce genre de chose, ne soient touchés.|n|nExaminez donc les gardes et voyez s\'ils sont devenus aussi déraisonnables que les autres.', },
    {'Obtenez une Carte de garde moisie et rapportez-la à Fenstad Argyle, à Fossoyeuse.', },
  },
  [8905] = {
    'Une proposition sérieuse',
    {'Voilà une heureuse rencontre, $C, car j\'ai quelque chose qui pourrait vous intéresser.|n|nJ\'ai en ma possession un ensemble d\'armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d\'une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d\'une pièce d\'armure plus ordinaire… et d\'une petite faveur.|n|nEn ce moment, je m\'intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l\'Hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d\'or. Vous verrez, le jeu en vaut la chandelle !', },
    {'Procurez-vous 15 Échantillons de sang du Berceau-de-l\'Hiver et 20 pièces d\'or, et apportez-les avec une paire de Brassards du Cœur-sauvage à Deliana à Forgefer.', },
  },
  [8906] = {
    'Une proposition sérieuse',
    {'Voilà une heureuse rencontre, $C, car j\'ai quelque chose qui pourrait vous intéresser.|n|nJ\'ai en ma possession un ensemble d\'armure qui ressemble beaucoup à ce que portent les membres de votre profession, mais d\'une qualité bien supérieure à la moyenne. Je veux bien me séparer des bracelets en échange d\'une pièce d\'armure plus ordinaire… et d\'une petite faveur.|n|nEn ce moment, je m\'intéresse aux propriétés du sang des sabres-de-givre et des ours du Berceau-de-l\'Hiver. Rapportez-moi une quantité assez importante de ce sang, une paire de bracelets ordinaires et un peu d\'or. Vous verrez, le jeu en vaut la chandelle !', },
    {'Procurez-vous 15 Échantillons de sang du Berceau-de-l\'hiver et 20 pièces d\'or, et apportez-les avec une paire de Manchettes de bestiaire à Deliana à Forgefer.', },
  },
