  },
  [8913] = {
    'Une proposition sérieuse',
    {'Salut, $C ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n\'avez jamais vu une pièce d\'armure comme celle-ci.|n|nSi vous m\'accordez une petite faveur, je suis prêt à vous l\'échanger contre une paire de brassards ordinaires.|n|nJ\'ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d\'or en plus, et nous ferons l\'échange.', },
    {'Procurez-vous 15 Echantillons de venin de Silithus et 20 pièces d\'or, et apportez-les avec une paire de Brassards du Cœur-sauvage à Mokvar, à Orgrimmar.', },
  },
  [8914] = {
    'Une proposition sérieuse',
    {'Salut, $C ! Je vois bien à votre allure que vous avez vu et accompli de grandes choses dans ce monde. Mais je suis prêt à parier que vous n\'avez jamais vu une pièce d\'armure comme celle-ci.|n|nSi vous m\'accordez une petite faveur, je suis prêt à vous l\'échanger contre une paire de brassards ordinaires.|n|nJ\'ai besoin de quelques bons échantillons du venin des araignées et des scorpions qui infestent Silithus. Apportez-moi ça et quelques pièces d\'or en plus, et nous ferons l\'échange.', },
