  [8940] = {
    'Une juste compensation',
    {'Vous avez fait la preuve de votre fiabilité, $N. Je suis sûr que vous m\'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.|n|nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.', },
    {'Apportez une Ceinture de dévot et une paire de Gants de dévot à Mokvar à Orgrimmar.', },
  },
  [8941] = {
    'Une juste compensation',
    {'Vous avez fait la preuve de votre fiabilité, $N. Je suis sûr que vous m\'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.|n|nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.', },
    {'Apportez une Ceinture Sombreruse et une paire de Gants Sombreruse à Mokvar à Orgrimmar.', },
  },
  [8942] = {
    'Une juste compensation',
    {'Vous avez fait la preuve de votre fiabilité, $N. Je suis sûr que vous m\'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.|n|nPour le moment, je me contenterai de remplacer votre ceinture et vos gantelets. Si nous survivons tous les deux, je vous remettrai les autres pièces.', },
    {'Apportez une Corde des éléments et une paire de Gantelets des éléments à Mokvar à Orgrimmar.', },
  },
  [8943] = {
    'Une juste compensation',
    {'Vous avez fait la preuve de votre fiabilité, $N. Je suis sûr que vous m\'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.|n|nPour le moment, je me contenterai de remplacer votre ceinture et vos gants. Si nous survivons tous les deux, je vous remettrai les autres pièces.', },
    {'Apportez une Ceinture de Brume-funeste et des Gants de Brume-funeste à Mokvar à Orgrimmar.', },
  },
  [8944] = {
    'Une juste compensation',
    {'Vous avez fait la preuve de votre fiabilité, $N. Je suis sûr que vous m\'aiderez à me sortir de ce mauvais pas, mais par prudence, je vais doser les récompenses en fonction de vos performances.|n|nPour le moment, je me contenterai de remplacer votre ceinture et vos gantelets. Si nous survivons tous les deux, je vous remettrai les autres pièces.', },
    {'Apportez une Ceinture de vaillance et une paire de Gantelets de vaillance à Mokvar à Orgrimmar.', },
  },
  [8945] = {
    'La supplique du mort',
    {'Vous aurez vos informations, $N, mais il y a plus important.|n|nMon épouse bien-aimée a été capturée par la vermine morte-vivante du baron Vaillefendre.|n|nJe ne voulais pas qu\'elle rejoigne l\'absurde croisade de l\'Aube d\'argent, mais cela n\'a plus d\'importance. Vous devez achever ce que j\'ai commencé, vous devez arracher Ysida aux griffes du baron !', },
    {'Entrez à Stratholme et sauvez Ysida Harmon du baron Vaillefendre.', },
  },
  [8946] = {
    'Une preuve de vie',
    {'Un destin cruel a voulu que mon bien-aimé périsse en tentant de me sauver. Pourtant, vous me dites que vous pouvez lui parler.|n|nRemettez-lui ce médaillon pour lui prouver que je suis en bonne santé. Il ne doit pas s\'attarder dans ce monde, cela me briserait le cœur.|n|nAdieu, $N. Je serai toujours votre débitrice.', },
    {'Remettez le Médaillon d\'Ysida à Anthion Harmon, dans les Maleterres de l\'Est.', },
  },
  [8947] = {
    'L\'étonnante requête d\'Anthion',
    {'Nous n\'avons pas réalisé l\'importance du médaillon de Valthalak. Nous l\'avons donc partagé comme le reste des dépouilles. Le premier morceau a été pris par un nain, un certain Theldren. Lorsque j\'ai essayé de le lui reprendre, il bien failli me tuer. Vous devrez récupérer ce fragment par la force.|n|nAux dernières nouvelles, Theldren s\'était fait gladiateur chez les nains Sombrefer. Vous risquez d\'avoir un peu de mal à le pousser à vous affronter.|n|nJe vais avoir besoin des matériaux suivants… En fait, non, vous allez en avoir besoin.', },
    {'Remettre 3 Barres de sombrefer, 20 Cuirs enchantés, 3 Etoffes lunaires et 4 Peaux robustes traitées à Anthion Harmon dans les Maleterres de l\'Est.', },
  },
  [8948] = {
    'Le vieil ami d\'Anthion',
    {'Theldren n\'est pas du genre à participer de son plein gré à un combat honnête. J\'ai donc fabriqué cette bannière aux couleurs de sa famille.|n|nMoyennant une petite touche de magie supplémentaire, il sera incapable de résister à cette provocation.|n|nFalrin, l\'une de mes vieilles connaissances, connaît la marche à suivre. Vous le trouverez dans la bibliothèque de Hache-Tripes.', },
    {'Apportez la Bannière de défi incomplète à Farlin Sculpteflore, dans la bibliothèque de Hache-Tripes.', },
  },
  [8949] = {
    'La vendetta de Falrin',
    {'En effet, je connais l\'enchantement dont vous avez besoin, $C. Mais je ne suis pas de ceux qui distribuent des faveurs gratuitement, même si vous m\'avez été $Genvoyé:envoyée; par un vieil ami.|n|nJe hais mes voisins ogres, ces brutes méprisables. J\'exècre les séides d\'Omokk autant que les sujets du roi Gordok.|n|nTuez-les ! Tuez-en beaucoup ! Ramenez-moi les perles qu\'ils portent autour du cou comme preuve de vos actions. Lorsque vous m\'en aurez rapporté assez, nous reparlerons de votre requête.', },
    {'Collecter 25 Perles de guerre ogres à l\'intérieur de Hache-Tripes ou du Pic Rochenoire, puis revenir voir Falrin Sculpteflore, à l\'intérieur de l\'Athenaeum à Hache-Tripes.', },
  },
  [8950] = {
    'L\'enchantement du provocateur',
    {'Enchanter la bannière ne sera pas bien compliqué, $N. Malheureusement, je n\'ai pas les matériaux nécessaires. Entre nous, les gens demandent rarement des charmes de ce genre.|n|nIl va me falloir l\'essence de l\'un des fantômes d\'Eldreth qui hantent ces salles, une poignée de runes ténébreuses de la Scholomance et quelques grands éclats brillants. Ramenez-moi ces composants, je m\'occuperai du reste.', },
    {'Apportez les choses suivantes à Falrin Sculpteflore dans Hache-Tripes : 1 Essence de spectre railleur, 4 Runes ténébreuses et 8 Grands éclats brillants.', },
  },
  [8951] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.', },
  },
  [8952] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.', },
  },
  [8953] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.', },
  },
  [8954] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Bottes de Sancteforge, des Cuissards de Sancteforge et des Spallières de Sancteforge.', },
  },
  [8955] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Sandales de dévot, une Jupe de dévot et un Mantelet de dévot.', },
  },
  [8956] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.', },
  },
  [8957] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Bottes des éléments, un Kilt des éléments et des Espauliers des éléments.', },
  },
  [8958] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.', },
  },
  [8959] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Deliana et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec elle pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Deliana à Forgefer avec des Bottes de vaillance, des Cuissards de vaillance et des Spallières de vaillance.', },
  },
  [8960] = {
    'Le triste destin de Bodley',
    {'Alors il faut que nous récupérions le reste du médaillon ? Trouver Bodley risque d\'être un tantinet compliqué. Il est retourné au mont Rochenoire dans l\'espoir de pénétrer à nouveau dans le pic Rochenoire, et il n\'est jamais revenu.|n|nJe vous conseille de prendre la machine gobeline à faire apparaître les fantômes avec vous, car je crains le pire.', },
    {'Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.', },
  },
  [8961] = {
    'Les trois rois des flammes',
    {'Avant d\'invoquer le seigneur Valthalak au pic Rochenoire et de mettre un terme à ce problème, nous devons retrouver les deux autres tiers de l\'amulette. Pour cela, il nous faut un brasero et des charbons peu ordinaires…|n|nTrois puissants nobles élémentaires ont ce qu\'il nous faut. Ce sont le seigneur Incendius dans les profondeurs de Rochenoire, le pyrogarde Prophète ardent au pic Rochenoire et le duc des Cendres en Silithus. Récupérez un morceau de leurs restes, puis revenez me voir avec un Brasero béni, que vous pourrez acheter auprès de l\'Aube d\'argent si vous êtes $Ghonoré:honorée; auprès d\'eux.', },
    {'Récupérez l\'Incendicite d\'Incendius, la Braise du prophète ardent sur le pyrogarde Prophète ardent et les Cendres de Cendres, ainsi qu\'un Brasero béni, puis retournez voir Bodley au mont Rochenoire.', },
  },
  [8962] = {
    'Des composants importants',
    {'Écoutez-moi attentivement, $C. Maintenant que nous avons le brasero et le moyen de l\'allumer, il ne nous manque plus qu\'un composant pour l\'alimenter ; quelque chose qui soit assez puissant pour attirer l\'esprit de mon ancien camarade décédé.|n|nMor Sabot-gris, notre meilleur druide, avait d\'excellents amis au sein du Cercle cénarien, dont certains sont tombés sous les coups des silithides. J\'ai besoin que vous récupériez des restes druidiques auprès des silithides qui vivent dans les environs de la Ruche\'Regal, au sud-est de Silithus.', },
    {'Procurez-vous des Restes druidiques et rapportez-les à Bodley, à l\'intérieur du mont Rochenoire.', },
  },
  [8963] = {
    'Des composants importants',
    {'Écoutez-moi attentivement, $C. Maintenant que nous avons le brasero et le moyen de l\'allumer, il ne nous manque plus qu\'un composant pour l\'alimenter ; quelque chose qui soit assez puissant pour attirer l\'esprit de mon ancienne camarade décédée.|n|nIsalien, notre prêtresse, a grandi au Berceau-de-l\'Hiver, à Brise-Stellaire. J\'ai besoin que vous alliez chercher une relique de Brise-Stellaire auprès des géants Cognegivre de la gorge du Blanc murmure, au sud de Berceau-de-l\'Hiver. Ils sont célèbres pour les raids qu\'ils lancent de temps en temps dans le nord.', },
    {'Procurez-vous une Relique de Brise-Stellaire et rapportez-la à Bodley, à l\'intérieur du Mont Rochenoire.', },
  },
  [8964] = {
    'Des composants importants',
    {'Écoutez-moi attentivement, $C. Maintenant que nous avons le brasero et le moyen de l\'allumer, il ne nous manque plus qu\'un composant pour l\'alimenter ; quelque chose qui nous fournisse un point focal assez puissant pour attirer l\'esprit de mes anciens camarades décédés.|n|nJarien et Sothos croyaient aux idéaux de la Croisade écarlate. Ils souhaitaient devenir chevaliers au sein de cette vile organisation. Rendez-vous à la Main de Tyr, dans les Maleterres de l\'est, et récupérez une épée brillante de fanatisme sur les prétoriens qui y sont cantonnés.', },
    {'Procurez-vous une Épée brillante de fanatisme, puis rapportez-la à Bodley, à l\'intérieur du mont Rochenoire.', },
  },
  [8965] = {
    'Des composants importants',
    {'Écoutez-moi attentivement, $C. Maintenant que nous avons le brasero et le moyen de l\'allumer, il ne nous manque plus qu\'un composant pour l\'alimenter ; quelque chose qui soit assez puissant pour attirer l\'esprit de mon ancien camarade décédé.|n|nUn nécromancien ogre qui voyageait avec nous, Kormok, adorait invoquer les âmes des morts bannis sur l\'Île de la purification, près de la côte méridionale des contreforts de Hautebrande. Rendez-vous là-bas et récupérez un peu de cendres d\'âme de banni sur leurs restes…', },
    {'Prélevez des Cendres d\'âme de banni, puis retournez voir Bodley à l\'intérieur du mont Rochenoire.', },
  },
  [8966] = {
    'Le morceau gauche de l\'amulette du seigneur Valthalak',
    {'Mon ami, Mor Sabot-gris, a été le premier à être possédé par un morceau de l\'amulette du seigneur Valthalak, la première victime du fragment d\'esprit corrupteur qu\'elle renferme. Après avoir dérobé l\'amulette et le livre de sorts du seigneur Valthalak, nous avons fui le sommet du pic Rochenoire pour sauver nos vies. Mor s\'est égaré et est tombé dans les profondeurs du pic.|n|nPar la suite, nous avons découvert qu\'il avait survécu à sa chute, mais qu\'il avait été capturé et torturé par le maître de guerre Voone. Quelques assassins spectraux se sont faufilés dans les profondeurs et l\'ont tué sous les yeux de Voone.', },
    {'Utilisez le Brasero de signal pour invoquer l\'esprit de Mor Sabot-gris, puis tuez-le. Ensuite, retournez voir Bodley à l\'intérieur du mont Rochenoire avec le Morceau gauche de l\'amulette du seigneur Valthalak et le Brasero de signal.', },
  },
  [8967] = {
    'Le morceau gauche de l\'amulette du seigneur Valthalak',
    {'Sur la fin, alors que nous faisions notre possible pour rester en vie, nous avons appris que la prêtresse elfe de la nuit de notre compagnie, Isalien, s\'était rendue dans une antique cité de son peuple, la ville que nous connaissons sous le nom de « Hache-Tripes ». D\'après ce que nous avons compris, elle avait des raisons personnelles pour s\'y installer, mais elle voulait aussi découvrir les secrets du morceau d\'amulette qu\'elle détenait.|n|nElle n\'y est pas parvenue. Nous avons entendu dire qu\'elle avait été victime d\'une embuscade tendue par Alzzin le Modeleur et ses forces au sanctuaire d\'Eldretharr.', },
    {'Utilisez le Brasero de signal pour invoquer l\'esprit d\'Isalien, puis tuez-le. Retournez voir Bodley, à l\'intérieur du mont Rochenoire, avec le Morceau gauche de l\'amulette du seigneur Valthalak et le Brasero de signal.', },
  },
  [8968] = {
    'Le morceau gauche de l\'amulette du seigneur Valthalak',
    {'Lorsque notre compagnie de mercenaires a éclaté, Sothos et Jarien, un frère et une sœur, ont decidé de rejoindre la Croisade écarlate. Ils ont emmené le morceau gauche de l\'amulette du seigneur Valthalak avec eux. C\'était plutôt un bon débarras… sauf qu\'il nous faut ce morceau.|n|nÀ ce que j\'ai compris, ils ont échoué lors de leur initiation, et ont été tués par le Grand croisé Dathrohan en personne dans ses appartements du Bastion écarlate.|n|nQue ce soit vrai ou non, nous devons… je veux dire, vous devez, récupérer ce morceau d\'amulette.', },
    {'Utilisez le Brasero de signal pour invoquer Jarien et Sothos et les tuer. Retournez voir Bodley, à l\'intérieur du mont Rochenoire, avec le Morceau gauche de l\'amulette du seigneur Valthalak et le Brasero de signal.', },
  },
  [8969] = {
    'Le morceau gauche de l\'amulette du seigneur Valthalak',
    {'Maintenant que nous avons tout ce qu\'il nous faut, il est temps que nous parlions de notre prochaine invocation.|n|nPour un ogre, Kormok n\'était pas désagréable, jusqu\'à ce qu\'il se mette à la nécromancie. Après… après, il donnait la chair de poule à tous les membres de la compagnie. Personne n\'a été étonné qu\'il emmène son morceau d\'amulette dans son nouveau foyer, la Scholomance. Même là, ou peut-être « surtout là », il n\'était pas à l\'abri des assassins spectraux. Ils l\'ont tué devant son maître, Ras Murmegivre.', },
    {'Utilisez le Brasero de signal pour invoquer l\'esprit de Kormok, puis tuez-le. Retournez voir Bodley, à l\'intérieur du mont Rochenoire, avec le Morceau gauche de l\'amulette du seigneur Valthalak et le Brasero de signal.', },
  },
  [8970] = {
    'Votre avenir passe par l\'île d\'Alcaz',
    {'Comme je vous le disais, $C, de mon vivant, j\'avais envisagé la possibilité de devenir devin. Mais comme vous le savez peut-être, ça n\'est pas un métier très rentable. Non seulement c\'est dangereux, mais en plus les composants sont à la fois rares et coûteux. Toutefois, j\'en ai appris assez pour localiser le dernier morceau de l\'amulette, ainsi que l\'esprit de mon ancien camarade.|n|nC\'est là que vous intervenez, $N. J\'ai besoin que vous alliez sur l\'île d\'Alcaz, au large du marécage d\'Âprefange, et que vous récupériez du varech de sang sur les nagas Strashaz qui y vivent.', },
    {'Récupérez 20 Varechs de sang sur les nagas Strashaz, puis retournez voir Bodley au mont Rochenoire.', },
  },
  [8971] = {
    'RÉUTILISER',
    nil,
    nil,
  },
  [8972] = {
