  [9014] = {
    'Garder le meilleur pour la fin',
    {'Une histoire extraordinaire, $N ! Je vous remercie, et tous ceux qui ont été impliqués dans cette affaire vous expriment leur gratitude. Grâce à vos efforts, nous sommes libérés de nos erreurs passées.|n|nQuant à votre récompense, j\'ai quelques trucs ici. Ils devraient vous plaire, et vous les avez bien mérités.', },
    {'Donnez votre Collerette de magistère et votre Robe de magistère à Mokvar.', },
  },
  [9015] = {
    'Le défi',
    {'Écoutez-moi bien, $N. Si vous voulez que la bannière fonctionne comme vous le désirez, vous devez pénétrer dans le Cercle de la loi, dans les profondeurs de Rochenoire. Laissez-vous condamner par le Juge supérieur Mornepierre et plantez la bannière dans le sol de l\'arène, en signe de défi.|n|nVotre victime sera incapable de se maîtriser, elle sera consumée par le désir de vous affronter. Lorsque vous aurez ce que vous voulez, retournez voir Anthion.', },
    {'Rendez-vous dans le Cercle de la loi, dans les profondeurs de Rochenoire, et placez la Bannière de provocation en son centre lorsque vous serez $Gcondamné:condamnée; par le Juge supérieur Mornepierre. Tuez Theldren et ses gladiateurs, puis retournez voir Anthion Harmon dans les Maleterres de l\'Est avec le premier morceau de l\'amulette du seigneur Valthalak.', },
  },
  [9016] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des bottes du Cœur-sauvage, un Kilt du Cœur-sauvage et des Spallières du Cœur-sauvage.', },
  },
  [9017] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Bottes de bestiaire, un Pantalon de bestiaire et un Mantelet de bestiaire.', },
  },
  [9018] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Bottes de magistère, des Jambières de magistère et un Mantelet de magistère.', },
  },
  [9019] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Sandales de dévot, une Jupe de dévot et un Mantelet de dévot.', },
  },
  [9020] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Bottes Sombreruse, un Pantalon Sombreruse et des Spallières Sombreruse.', },
  },
  [9021] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Sandales de Brume-funeste, des Jambières de Brume-funeste et un Mantelet de Brume-funeste.', },
  },
  [9022] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Retournez voir Mokvar à Orgrimmar avec des Bottes de vaillance, des Cuissards de vaillance et des Spallières de vaillance.', },
  },
  [9023] = {
    'Le poison parfait',
    {'Mon frère et moi nous occupons de tout ce qui concerne les poisons en dehors du manoir de Ravenholdt.|n|nLe seigneur Ravenholdt m\'a chargé de mettre la main sur un nouveau poison composite qui peut être préparé à partir des glandes à venin des habitants de Zul\'Gurub et des ruines d\'Ahn\'Qiraj.|n|nDeux des créatures qui hantent ces ruines maudites ont exactement ce qu\'il nous faut, $C. Ramenez-moi les Glandes à venin de Kurinnaxx et de Venoxis, et ma reconnaissance éternelle vous sera acquise.', },
    {'Dirk Tonnebois, du Fort cénarien en Silithus, veut que vous lui rameniez la Glande à venin de Venoxis et la Glande à venin de Kurinaxx.', },
  },
  [9024] = {
    'L\'intuition d\'Aristan',
    {'Vous sentez cette odeur ? C\'est celle des parfums et de l\'eau de Cologne qui sont à la mode ces temps-ci. Nos gardes ne négligeraient pas leur devoir aussi facilement.|n|nSauf si leur jugement a été obscurci par le biais d\'une quelconque alchimie...|n|nIl n\'y a qu\'un moyen de s\'en assurer : remettez un flacon de parfum et une bouteille d\'eau de Cologne à Morgan Pilon, et faites-lui part de mes soupçons. Je vous rembourserai vos achats lorsque vous reviendrez me voir.', },
    {'Remettez 1 bouteille d\'Eau de Cologne et 1 Flacon de parfum à Morgan Pilon, dans le Quartier commerçant de Hurlevent.', },
  },
  [9025] = {
    'La découverte de Morgan',
    {'Eh bien, cela m\'étonne aussi, mais on dirait qu\'Aristan a mis le doigt sur quelque chose. J\'ai trouvé des traces de certaines substances utilisées dans les philtres d\'amour, et d\'une décoction subtile qui altère le jugement.|n|nCe n\'est pas totalement inhabituel pour des parfums, mais certains de ces ingrédients… ne sentent pas bon, si vous voyez ce que je veux dire.', },
    {'Retourner voir Aristan Mottar, à côté de la banque, dans le Quartier commerçant de Hurlevent.', },
  },
  [9026] = {
    'Remonter à la source',
    {'Nous devons remonter à la source. Il y a beaucoup plus de gens qui entrent et sortent de la Rose dorée que d\'habitude… y compris des gardes. Parlez à Allison. Si elle vend ces parfums, elle pourra vous dire d\'où ils viennent.', },
    {'Parler à l\'aubergiste Allison à la Rose dorée, dans le Quartier commerçant de Hurlevent.', },
  },
  [9027] = {
    'Remonter à la source',
    {'Quelque chose d\'anormal dans l\'eau de Cologne ? C\'est possible. Je n\'ai jamais vu autant de gens se ruer sur un produit.|n|nÉcoutez, s\'il y a un problème, je veux le savoir. J\'ai acheté ma réserve à un marchand nommé Evert Sorisam. Il est arrivé en ville il n\'y a pas longtemps.|n|nIl m\'a parlé d\'une livraison à faire au Fil le plus fin.', },
    {'Parler à Evert Sorisam, au Fil le plus fin, au bord des canaux de Hurlevent.', },
  },
  [9028] = {
    'La source est découverte !',
    {'Comment ça, une trahison ? Non, je vous assure que mes intentions sont complètement innocentes.|n|nQuel mal y a-t-il à aider ceux qui souhaitent simplifier les rites complexes de la séduction ? Cela n\'a rien d\'un crime !|n|nTenez, pour vous prouver que je ne voulais de mal à personne, je vais même vous indiquer ma source.|n|nTous ces produits venaient d\'un certain Staffron Lerent, un apothicaire ou quelque chose de ce genre. Je ne l\'ai jamais vu.|n|nL\'intermédiaire, un gobelin, m\'a dit qu\'il travaillait dans les contreforts de Hautebrande, derrière le mystérieux manoir de Ravenholdt. Si vous voulez aller le voir, je vous souhaite bonne chance !', },
    {'Trouver l\'apothicaire Staffron Lerent dans les contreforts de Hautebrande, derrière le manoir de Ravenholdt.', },
  },
  [9029] = {
    'Un chaudron bouillonnant',
    nil,
    nil,
  },
  [9030] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Allez voir Deliana à Forgefer.', },
  },
  [9031] = {
    'Les adieux d\'Anthion',
    {'L\'âme de Valthalak était conservée dans cette amulette.|n|nAveuglés par la cupidité, nous l\'avons brisée en trois, sans savoir que nous allions être maudits pour cela.|n|nLe seul moyen d\'arrêter le sort lancé par Valthalak est de réunir le médaillon. Retournez voir Mokvar et dites-lui que Bodley est sa seule chance de retrouver les morceaux manquants. Voyez avec lui pour les récompenses.|n|nQuant à moi, pour une fois, je vais reposer en paix. Je vous souhaite bonne chance, vous en aurez bien besoin !', },
    {'Allez voir Mokvar à Orgrimmar.', },
  },
  [9032] = {
    'Le triste destin de Bodley',
    {'Ce médaillon contenait l\'âme du seigneur Valthalak ? Je comprends mieux qu\'il ait été gardé par une puissante malédiction.|n|nLocaliser Bodley risque d\'être difficile. Aux dernières nouvelles, il se préparait à retourner au pic Rochenoire. On n\'a plus jamais entendu parler de lui.|n|nVous devriez le chercher au mont Rochenoire, même s\'il est probablement déjà mort. Je vous suggère de prendre la machine du gobelin avec vous, $Gmon ami:mon amie;.', },
    {'Rendez-vous au mont Rochenoire, près du pic Rochenoire, et utilisez le Révélateur de fantômes extradimensionnel pour trouver Bodley.', },
  },
  [9033] = {
    'Les échos de la guerre',
    {'Cinq ans se sont écoulés depuis la dernière guerre…|n|nDes dizaines de milliers de morts, et pour quoi ? La menace n\'a jamais été éradiquée.|n|nLe roi-liche s\'agite à nouveau. Son lèche-bottes, Kel\'Thuzad, ourdit une nouvelle attaque contre nos terres.|n|nNous ne le laisserons pas faire ! Prouvez votre volonté de servir ! Prouvez que vous êtes $Gprêt:prête; à risquer votre vie et votre âme pour mettre un terme à cette folie ! Si vous y parvenez, la puissance combinée de l\'Aube et de la Croisade seront à votre service.|n|nPénétrez dans Naxxramas et anéantissez le Fléau qui y rôde…', },
    {'Le commandant Eligor Portelaube, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, veut que vous tuiez 5 Monstruosités vivantes, 5 Gargouilles peau de pierre, 8 Capitaines des chevaliers de la mort et 3 Traque-venin.', },
  },
  [9034] = {
    'Cuirasse de cuirassier',
    {'Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d\'armures désacralisées et des débris d\'armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.', },
    {'Korfax, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera une cuirasse de cuirassier si vous lui apportez les choses suivantes : 1 Cuirasse désacralisée, 25 Débris d\'armure en plaques, 4 Barres d\'arcanite et 2 Cristaux de nexus.', },
  },
  [9035] = {
    'Une embuscade au bord de la route',
    {'Vous, là ! Aidez-moi, s\'il vous plaît !|n|nNous avons été attaqués par les Déshérités ! Dans leur faim démente de magie, ils ont emporté tout ce qu\'ils ont pu : cristaux de mana, baguettes, livres de sorts… tout !|n|nMeledor, l\'autre apprenti, les pourchasse. J\'ai dû rester en arrière pour protéger ce qu\'ils n\'ont pas pris. Continuez sur la route et voyez si vous pouvez lui prêter main-forte.', },
    {'Parlez à l\'apprenti Meledor dans le bois des Chants éternels, le long de la route qui part au sud depuis Lune-d\'Argent.', },
  },
  [9036] = {
    'Cuissards de cuirassier',
    {'Durant vos batailles contre le Fléau à Naxxramas, si vous tombez sur des pièces d\'armures désacralisées et des débris d\'armures, ramenez-les-moi et je vous forgerai une pièce de cette armure de héros.', },
    {'Korfax, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des cuissards de cuirassier si vous lui apportez les choses suivantes : 1 paire de Cuissars désacralisés, 20 Débris d\'armure en plaques, 4 Barres d\'arcanite et 3 Peaux robustes traitées.', },
  },
  [9037] = {
