  [9111] = {
    'Robe de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera une Robe de foi si vous lui ramenez 1 Robe désacralisée, 25 Débris d\'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus.', },
  },
  [9112] = {
    'Jambières de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des Jambières de foi si vous lui ramenez 1 paire de Jambières désacralisées, 20 Débris d\'armure en tissu, 4 Etoffes lunaires et 2 Cristaux de nexus.', },
  },
  [9113] = {
    'Diadème de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est, vous fabriquera un Diadème de foi si vous lui ramenez 1 Diadème désacralisé, 15 Débris d\'armure en tissu, 3 Etoffes lunaires et 3 Cristaux de nexus.', },
  },
  [9114] = {
    'Protège-épaules de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des Protège-épaules de foi si vous lui ramenez 1 paire de Protège-épaules désacralisés, 12 Débris d\'armure en tissu, 2 Etoffes lunaires et 3 Peaux robustes traitées.', },
  },
  [9115] = {
    'Sandales de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des Sandales de foi si vous lui ramenez 1 paire de Sandales désacralisées, 12 Débris d\'armure en étoffe, 2 Etoffes lunaires et 3 Peaux robustes traitées.', },
  },
  [9116] = {
    'Gants de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des Gants de foi si vous lui ramenez 1 paire de Gants désacralisés, 8 Débris d\'armure en tissu et 4 Etoffes lunaires.', },
  },
  [9117] = {
    'Ceinture de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera une Ceinture de foi si vous lui ramenez 1 Ceinture désacralisée, 8 Débris d\'armure en tissu, 2 Cristaux des arcanes et 2 Etoffes lunaires.', },
  },
  [9118] = {
    'Manchettes de foi',
    {'<Le père Montoy fait quelques gestes étranges dans l\'air, devant vous.>|n|nSoyez $Gbéni mon fils:bénie ma fille; ! Avez-vous trouvé les habits des défunts ? Les pauvres âmes qui ont rendu leur dernier souffle sur le champ de bataille ont tout perdu, sauf leur dignité.|n|nRamenez-moi les restes désacralisés des trépassés avec des composants de purification et vous connaîtrez la foi.', },
    {'Le père Inigo Montoy, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, vous fabriquera des Manchettes de foi si vous lui ramenez 1 paire de Manchettes désacralisées, 6 Débris d\'armure en tissu, 1 Cristal arcanique et 1 Cristal de nexus.', },
  },
  [9119] = {
    'Panne au sanctum occidental',
    {'Puisque vous êtes là, $N, j\'ai une faveur à vous demander. L\'apprenti de la telluriste Velania est passé tout à l\'heure pour nous demander de l\'aide. Il semble y avoir une sorte de panne au sanctum occidental. Malheureusement, notre… très sympathique… invité nain m\'occupe à plein temps. Voyez si vous pouvez lui donner un coup de main. Le sanctum occidental se trouve au sud-ouest.', },
    {'Parler à la telluriste Velania, au Sanctum occidental du bois des Chants éternels.', },
  },
  [9120] = {
    'La chute de Kel\'Thuzad',
    {'Le phylactère est tout ce qui reste du maître de Naxxramas. Votre bon sens vous souffle de le détruire, afin que la liche ne puisse plus jamais se reformer. Heureusement, vous avez appris à faire taire la petite voix de la raison.|n|nIl y aura bien quelqu\'un, à la chapelle de l\'Espoir de Lumière, qui sera disposé à vous payer grassement pour cet objet.', },
    {'Apportez le Phylactère de Kel\'Thuzad à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9121] = {
    'Naxxramas, la citadelle de l\'effroi',
    {'Dans les profondeurs de Pestebois se trouve l\'entrée de la citadelle de l\'effroi, Naxxramas. Toutes les tentatives pour y pénétrer ont échoué en raison des balises magiques placées sur le portail runique - jusqu\'à présent.|n|nNous avons mis au point un moyen d\'entrer grâce à l\'occultation arcanique - un vieux sortilège du Kirin Tor avec quelques modifications personnelles. Comme votre dévouement à la cause de l\'Aube laisse encore un peu à désirer, $N, le prix en sera élevé. Peut-être préférerez-vous renoncer pour l\'instant et revenir lorsque vous serez $Grévéré:révérée; ou $Gexalté:exaltée; afin de bénéficier d\'une remise.', },
    {'L\'archimage Angela Dosantos à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est veut 5 Cristaux des arcanes, 2 Cristaux de nexus, 1 Orbe de piété et 60 pièces d\'or. Vous devez aussi être $GHonoré:Honorée; auprès de l\'Aube d\'argent.', },
  },
  [9122] = {
    'Naxxramas, la citadelle de l\'effroi',
    {'Dans les profondeurs de Pestebois se trouve l\'entrée de la citadelle de l\'effroi, Naxxramas. Toutes les tentatives pour y pénétrer ont échoué en raison des balises magiques placées sur le portail runique - jusqu\'à présent.|n|nNous avons mis au point un moyen d\'entrer grâce à une sorte d\'occultation arcanique permanente, un vieux sortilège du Kirin Tor avec quelques modifications personnelles. Cela étant dit, l\'occultation est coûteuse. Mais puisque votre dévouement à la cause de l\'Aube est admirable, nous sommes prêts à prendre en charge une partie des dépenses.', },
    {'L\'archimage Angela Dosantos à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est veut 2 Cristaux des arcanes, 1 Cristal de nexus et 30 pièces d\'or. Vous devez aussi être $GRévéré:Révérée; auprès de l\'Aube d\'argent.', },
  },
  [9123] = {
    'Naxxramas, la citadelle de l\'effroi',
    {'Dans les profondeurs de Pestebois se trouve l\'entrée de la citadelle de l\'effroi, Naxxramas. Toutes les tentatives pour y pénétrer ont échoué en raison des balises magiques placées sur le portail runique - jusqu\'à présent.|n|nNous avons mis au point un moyen d\'entrer grâce à une sorte d\'occultation arcanique permanente, un vieux sortilège du Kirin Tor avec quelques modifications personnelles. Cela étant dit, l\'occultation est coûteuse. Cependant, votre dévouement à la cause de l\'Aube est indéfectible ! Nous prendrons en charge toutes les dépenses.', },
    {'L\'archimage Angela Dosantos à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est vous accordera gratuitement l\'Occultation arcanique. Vous devez être $GExalté:Exaltée; auprès de l\'Aube d\'argent.', },
  },
  [9124] = {
    'L\'armure de traqueur des cryptes ne se fabrique pas toute seule',
    {'Ça vous dirait de gagner une de ces jolies pièces ?|n|n<Leopold vous montre un insigne de la Croisade.>|n|nJ\'ai un petit souci et vous pourriez peut-être m\'aider à le résoudre, $N. Je fabrique des armures de traqueur des cryptes pour ceux qui sont assez fous pour s\'aventurer dans Naxxramas. Bien qu\'ils me fournissent l\'essentiel du matériau de base pour réaliser ces armures, je manque continuellement de morceaux de démon des cryptes. Apportez-moi un bon paquet de ces morceaux et je vous les paierai avec un insigne, utilisable auprès des intendants.', },
    {'Le veneur Leopold, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, veut que vous lui apportiez 30 Morceaux de démon des cryptes.', },
  },
  [9125] = {
    'Morceaux de démon des cryptes',
    nil,
    nil,
  },
  [9126] = {
    'Des morceaux pour la faucheuse d\'os',
    {'D\'après les indications de don Julio, il faut des fragments d\'os pour fabriquer l\'armure de la faucheuse d\'os. Beaucoup de fragments. Même si ceux qui sont assez cinglés pour s\'aventurer dans Naxxramas me fournissent suffisamment de matériau de base pour réaliser l\'armure, je n\'ai jamais assez de fragments d\'os du Fléau.|n|nAlors, qu\'est-ce que vous en pensez ? Ça vous dirait de vous salir les mains et de détruire quelques bestioles du Fléau en même temps ? C\'est du gagnant-gagnant.', },
    {'Rohan l\'assassin, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, veut 30 Fragments d\'os.', },
  },
  [9127] = {
    'Fragments d\'os',
    nil,
    nil,
  },
  [9128] = {
    'L\'équation élémentaire',
    {'Salutations, $Gaventurier:aventurière; ! Cherchez-vous du travail ? Je paye mes employés par le moyen d\'insignes. Ces insignes peuvent être utilisés auprès de l\'Intendant pour acheter des objets de puissance.|n|nIl vous suffit de m\'apporter autant de noyaux des éléments que vous pouvez en porter. Le plus sera le mieux !|n|nVous les trouverez sur les élémentaires de formes et de tailles variées qui existent de par le monde.', },
    {'L\'archimage Angela Dosantos à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est veut 30 Noyaux des éléments.', },
  },
  [9129] = {
    'Noyau des éléments',
    nil,
    nil,
  },
  [9130] = {
    'Des marchandises de Lune-d\'Argent',
    {'Bienvenue, volontaire ! Nous manquons un peu de matériel ici, mais Lune-d\'Argent a promis de nous aider à nous approvisionner. C\'est là que vous intervenez.|n|nApportez cette liste au maître du ciel Brillaube. Il vous expliquera la meilleure façon de vous rendre à Lune-d\'Argent.', },
    {'Remettez la Demande de Sathiel au maître du ciel Brillaube, à Brise-Clémente.', },
  },
  [9131] = {
    'Armer un cuirassier',
    {'Avez-vous déjà vu une armure de cuirassier, $C ? Non, bien sûr que non, vous n\'êtes encore $Gqu\'un gamin:qu\'une gamine;, un vulgaire moutard. Alors, laissez-moi vous dire une chose : c\'est magnifique.|n|nVous vous demandez ce que cela a à voir avec vous, hein ? Je vais vous le dire, $Gle:la; môme. J\'ai besoin de très nombreux morceaux de sombrefer, et je suis prêt à les payer.|n|nIls me serviront à créer des ensembles d\'armures de cuirassier pour nos champions. Alors, ramenez-moi des morceaux et passez à la caisse.', },
    {'Korfax, de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est, veut 30 Morceaux de sombrefer.', },
  },
  [9132] = {
    'Morceaux de sombrefer',
    nil,
    nil,
  },
  [9133] = {
    'Un vol jusqu\'à Lune-d\'Argent',
    {'Eh bien $C, sachez qu\'en échange d\'une somme modique, je peux vous faire traverser les cieux sur le dos de l\'une de ces magnifiques créatures. Dans la région, je vous garantis que c\'est plus sûr que la marche !|n|nLorsque vous arriverez à Lune-d\'Argent, cherchez Sathren Aube-azur dans le bazar.|n|nLorsque vous aurez décidé de braver la pesanteur, venez me voir.', },
    {'Achetez un vol pour Lune-d\'Argent et remettez la Demande de Sathiel à Sathren Aube-azur, à Lune-d\'Argent.', },
  },
  [9134] = {
    'La maîtresse du ciel Tombejour',
    {'Bon, comme vous n\'avez pas l\'air d\'avoir prévu de chariots ou d\'animaux de bât, je vais vous renvoyer d\'où vous venez avec ce que vous pourrez porter, et rien de plus. Si vous avez déjà parlé au maître du ciel Brillaube à Brise-Clémente, vous devriez pouvoir rejoindre Sathiel très rapidement par la voie des airs.|n|nTenez, emportez ces fournitures à la maîtresse du ciel Tombejour pour une ultime inspection, devant les murs de Lune-d\'Argent à la porte du Berger.', },
    {'Apporter les Marchandises de Sathiel à la maîtresse du ciel Tombejour, juste devant la Porte du Berger, à Lune-d\'Argent.', },
  },
  [9135] = {
    'Le retour vers Sathiel',
    nil,
    nil,
  },
  [9136] = {
    'La flore sauvage',
    {'Je fabrique un type d\'armure spéciale, appelée marcherêve, pour les héros courageux qui entrent dans Naxxramas. Ils parviennent à me fournir la plupart des matériaux nécessaires, mais je suis toujours à l\'affût de personnes capables de dénicher des palmes sauvages dans la flore de notre monde.|n|nVous penserez peut-être que ce travail est indigne de vous, mais sans ces palmes, il m\'est impossible de fabriquer l\'armure.|n|nJe suis aussi en mesure de vous rétribuer en vous remettant l\'insigne de votre choix, car l\'Aube et la Croisade me subventionnent.', },
    {'Rayne de la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est veut 30 Palmes sauvages.', },
  },
  [9137] = {
    'La flore sauvage',
    nil,
    nil,
  },
  [9138] = {
    'Solcouronne',
    {'Nous sommes encerclés, $C. Les villages des alentours ont été conquis par le Fléau !|n|nVous devez vous rendre immédiatement au village de Solcouronne, au nord-est, et y affronter la menace nérubienne du Fléau.|n|nCes créatures ressemblent à des araignées, vous ne pouvez pas les rater. Il n\'y a pas de temps à perdre, nous devons reconquérir Quel\'Thalas !', },
    {'Tuez 10 Gardes nérubis, puis retournez voir l\'arcaniste Vandril à Tranquillien dans les Terres fantômes.', },
  },
  [9139] = {
    'Brume-d\'or',
    {'Nous avons remporté un premier succès, mais il faut encore reprendre deux autres villages !|n|nNotre prochaine cible est Brume-d\'or. Ce village se trouve au nord-ouest. Il a été conquis par les fantômes des hauts-elfes qui y vivaient autrefois. C\'est horrible, je sais, mais c\'est le genre de tactique qu\'affectionne le Fléau.|n|nAllez-y et triomphez de ces fantômes et de ces âmes en peine, $C. Pour vous y rendre, prenez la route à l\'ouest de Tranquillien.', },
    {'Vaincre 6 Fantômes quel\'dorei et 4 Âmes en peine quel\'dorei au village de Brume-d\'or, puis retourner voir l\'arcaniste Vandril à Tranquillien, dans les Terres fantômes.', },
  },
  [9140] = {
    'Coursevent',
    {'$N, la dernière bataille de notre campagne contre les villages des Terres fantômes commence. Coursevent, au sud-ouest, a été envahi par une force importante, composée de troupes de choc du Fléau, des ombres et des gargouilles. Vous interviendrez à l\'avant-garde pour diminuer leur nombre.|n|nLes magistères du sanctum du Soleil, qui est tout proche, nous ont présenté une requête. Ils souhaitent étudier les restes de ces créatures du Fléau, car ils espèrent découvrir des moyens créatifs de les combattre.|n|nBonne chasse !', },
    {'Collectez 6 Substances fantasmatiques et 4 Fragments de gargouille. Rapportez-les à l\'arcaniste Vandril à Tranquillien dans les Terres fantômes.', },
  },
  [9141] = {
    'On m\'appelle « Le Coq »',
    {'Vous voulez une commission d\'artisan ? Quoi ? Vous vous imaginez que je vais vous donner une de ces commissions si vivement recherchées juste parce que vous vous êtes $Gmontré:montrée; ici ? Sûrement pas, feignasse. Des artisans du monde entier cherchent du travail ici sur le front.|n|nSi vous voulez une commission, vous allez devoir me montrer que vous êtes $Gprêt:prête; à verser du sang pour la cause. Apportez-moi une marque de valeur et nous reparlerons.|n|nEt pour mettre vos petites mains poisseuses de $Gbon à rien:bonne à rien; sur une de ces marques, vous n\'avez qu\'une chose à faire - commencez le carnage.', },
    {'Le commandant d\'ordonnance Metz, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est, veut une Marque de valeur de l\'Aube d\'argent.', },
  },
  [9142] = {
    'Commission d\'artisan',
    nil,
    nil,
  },
  [9143] = {
    'S\'occuper de Zeb\'Sora',
    {'Le lieutenant s\'est dépêché de nous envoyer nous battre avec les trolls qui vivent de l\'autre côté du lac. Il n\'a pas pensé à déployer des éclaireurs. Nous avons payé sa sottise très cher ! Vous m\'entendez, Tomathren ? Vous êtes un crétin !|n|nVoulez-vous m\'aider, $C ? Il faut toujours que nous nous occupions de ces trolls. Je vais rester là et lui servir de nourrice – j\'ai l\'impression qu\'il a perdu l\'esprit.|n|nPartez vers l\'est, traversez le lac et entrez dans Zeb\'Sora. Je veux me venger ! Amenez-moi leurs oreilles, que je me fabrique un collier !', },
    {'Collecter 6 Oreilles de trolls de Zeb\'Sora et les remettre au Forestier Valanna dans les Terres fantômes.', },
  },
  [9144] = {
    'Disparu dans les Terres fantômes',
    {'Il y a quelques jours, mon neveu a été envoyé dans les Terres fantômes. Il ne m\'a rien dit de sa mission, sinon qu\'elle était extrêmement confidentielle.|n|nIl n\'est pas revenu. Je crains le pire, $C. Un messager disparu n\'a peut-être pas grande importance pour les impitoyables magistères de Lune-d\'Argent, mais pour moi il est comme un fils. Pourriez-vous partir à sa recherche, $N ? S\'il vous plaît ?', },
    {'Suivez la route qui part du village de Brise-Clémente vers le sud. Lorsque vous approcherez les Terres fantômes, cherchez le Courrier Aube-glorieuse.', },
  },
  [9145] = {
    'Il faut aider le forestier Valanna !',
    {'Je ne peux pas rester là sans rien faire en attendant une audience avec le grand exécuteur Mavren ou dame Auriférias, $C ! Mon affaire ne peut pas attendre !|n|nNous avions commencé à nous occuper des trolls Ombrepins qui vivent au nord-est, de l\'autre côté du lac Elrendar, mais le lieutenant a mal géré l\'attaque. Nous avons perdu de nombreux pérégrins. Et après, il a craqué. Le forestier Valanna m\'envoie demander de l\'aide. Elle a aussi dépêché le forestier Salissa à l\'enclave des Pérégrins.|n|nRetrouvez-les, $C. Valanna a été grièvement blessée et le lieutenant n\'est bon à rien.', },
    {'Trouver le forestier Valanna et le lieutenant Tomathren sur la rive du lac Elrendar, dans les Terres fantômes, près du village de Solcouronne.', },
  },
  [9146] = {
    'Un rapport pour le capitaine Hélios',
    {'Puis-je vous demander une dernière faveur, $C ? Je ne sais pas si Salissa a rejoint l\'enclave des Pérégrins, sur la rive sud du lac. Accepteriez-vous d\'y aller chercher de l\'aide ?|n|nPrésentez-vous au capitaine Hélios et expliquez-lui ce qui nous est arrivé. Il nous enverra du secours dès que possible.', },
    {'Parler au capitaine Hélios à l\'enclave des Pérégrins, sur la rive sud du lac Elrendar, dans les Terres fantômes.', },
  },
  [9147] = {
    'Le courrier blessé',
    {'Ne restez pas là les bras ballants ! Vous ne voyez pas que ce garçon a besoin de soins immédiats ? La peste commence à s\'étendre dans son organisme. Encore quelques minutes et même un maître apothicaire comme moi ne pourra plus le sauver.|n|nLes animaux au sud de la rivière portent tous des germes de peste dans leur sang. Allez de l\'autre côté du pont et chassez les bêtes pestiférées qui se trouvent là-bas. Apportez-moi suffisamment d\'échantillons de sang pestiféré et je concocterai un sérum capable de sauver cet elfe de sang. Dépêchez-vous !', },
    {'L\'apothicaire Thedra du bois des Chants éternels veut que vous lui apportiez 4 Échantillons de sang pestiféré pris sur les bêtes des Terres fantômes.', },
  },
  [9148] = {
    'Livraison à Tranquillien',
    {'Je... je suis trop faible pour continuer. Je porte un terrible avertissement du seigneur régent Theron, sous la forme d\'une lettre. Vous allez devoir la livrer à ma place.|n|nApportez-la à l\'arcaniste Vandril à Tranquillien. C\'est une ville que vous trouverez plus au sud, sur cette route. Allez-y et... trouvez Vandril...', },
    {'Apportez la Lettre de Lune-d\'Argent à l\'arcaniste Vandril à Tranquillien, dans les Terres fantômes.', },
  },
  [9149] = {
    'La côte pestiférée',
    {'Pour découvrir un remède à la peste, nous devons comprendre comment elle affecte chaque type de créature, des formes de vie complexes aux espèces les moins favorisées.|n|nJe suis ici pour étudier les murlocs car, comme nous, ils ont conservé leur libre arbitre par-delà la mort. Il faut que je découvre ce qui rend ces misérables bâtards si exceptionnels, $N !|n|nPartez vers le nord-ouest et ramenez-moi leurs épines dorsales, que je puisse étudier la concentration de la peste dans leur moelle. Qui sait ce que nous découvrirons dans ces petits os ?', },
    {'Apportez 6 Épines dorsales de murlocs pestiférés à l\'apothicaire Renzithen, à Tranquillien dans les Terres fantômes.', },
  },
  [9150] = {
    'Les dépouilles du passé',
    {'Qui l\'eût cru ? Nous avons un sanctum des arcanes en état de marche au sud-est d\'ici, le sanctum du Soleil. De très nombreux magistères importants s\'y sont rendus pour participer à son fonctionnement.|n|nBien sûr, ils ont tous oublié le sanctum de la Lune, plus à l\'ouest. Il n\'en reste pas grand-chose et les énergies qu\'il dégage ont donné naissance à des créatures assez bizarres.|n|nD\'un autre côté, je ne suis pas du genre à laisser perdre des ressources. Rendez-vous au sanctum de la Lune et voyez si vous pouvez récupérer les essences cristallisées des créatures qui s\'y trouvent.', },
    {'Le magistère Darenis veut que vous vous rendiez au sanctum de la Lune, à l\'ouest de Tranquillien, et que vous récupériez 8 Essences de mana cristallisées sur les Dévoreurs arcaniques et les Changemana qui occupent les lieux.', },
  },
  [9151] = {
    'Le sanctum du Soleil',
    {'Vous avez prouvé votre loyauté envers Tranquillien, et vous nous avez aidés à la défendre contre la menace du Fléau. Certains de nos plus puissants magistères sont venus de Lune-d\'Argent pour nous aider à conduire la bataille jusqu\'à la porte de l\'ennemi.|n|nIls ont reconstruit le sanctum des arcanes au sud, et repoussé le Fléau de la région environnante. Ils ont l\'intention de lancer une offensive sur Mortholme, la forteresse de Dar\'Khan. Vous feriez bien de les rejoindre, $N. Je suis sûr qu\'ils sauront faire bon usage d\'$Gun:une:c; $C comme vous.', },
    {'Parlez au magistère Idonis au sanctum du Soleil dans les Terres fantômes.', },
  },
  [9152] = {
    'Les marchandises de Tombal',
    {'Comment puis-je approvisionner l\'effort de guerre si je ne peux même pas apporter mes marchandises jusqu\'ici ? On m\'a promis une escorte qui n\'est jamais venue. Et ensuite j\'ai dû abandonner un de mes chariots plus à l\'ouest lorsque j\'ai été attaqué par un groupe de goules !|n|nVous me rendriez un service pour me permettre d\'ouvrir boutique ? Descendez la route de l\'ouest vers l\'extérieur de la ville, au-delà du cimetière. Vous trouverez un embranchement de l\'autre côté de la Malebrèche. La colline sur laquelle se trouve mon chariot est juste derrière.', },
    {'Retrouver la Marchandise de Rathis Tombal et la lui rapporter à Tranquillien dans les Terres fantômes.', },
  },
  [9153] = {
    'Sous les ombres',
    {'Les nécropoles volantes du Fléau hantent les territoires de la Horde comme de l\'Alliance. Les terres Foudroyées, Berceau-de-l\'Hiver, les Steppes ardentes et Tanaris sont sillonnés par les ombres de ces forteresses aériennes.|n|nSeuls nos efforts coordonnés nous permettront de les repousser.|n|nLes nécropoles sont soutenues par des cercles magiques à proximité et dans chaque cercle, grouille une multitude de créatures mortes-vivantes. Nous avons découvert que nous pouvons détruire leurs défenses en abattant les hordes de créatures décérébrées qui entourent ces cercles.', },
    {'Surveillez votre carte pour trouver une région subissant une attaque du Fléau. Allez-y et endommagez une nécropole en exterminant les créatures du Fléau aux alentours. Rapportez ensuite 10 de leurs Runes nécrotiques au commandant Thomas Helleran, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9154] = {
    'La chapelle de l\'Espoir de Lumière',
    {'Le Fléau est revenu, et ses serviteurs sont plus nombreux que jamais. Ça doit être du fait du roi-liche ! L\'Aube d\'argent recrute tous les hommes et femmes ayant l\'envie et les moyens de défendre nos contrées.|n|nSi vous souhaitez partager notre cause, apportez ce document au gardien des registres, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est.', },
    {'Apportez l\'Annonce de l\'appel aux armes au gardien des registres, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9155] = {
    'Dans la Malebrèche',
    {'Si vous êtes $Garrivé:arrivée; si loin, vous devez avoir entendu parler de la Malebrèche et des créatures décérébrées du Fléau qui parcourent encore le chemin dévasté autrefois tracé par Arthas lorsqu\'il se dirigeait vers Lune-d\'Argent.|n|nRendez-vous utile en éclaircissant un peu les rangs des créatures du Fléau dans la brèche. Si vous vous en montrez digne, je toucherai un mot en votre faveur.', },
    {'Tuez 10 Affameurs ressuscités et 10 Cannibales dégingandés dans la Malebrèche. Retournez voir le nécrotraqueur Rathiel à Tranquillien dans les Terres fantômes pour obtenir une récompense.', },
  },
  [9156] = {
    'On recherche : Putrepoing et Luzran',
    {'Nous déclarons par la présente la mise à prix des abominations connues sous les noms de Putrepoing et Luzran. Ces effroyables créations de Dar\'Khan, extrêmement dangereuses, ont été aperçues patrouillant aux alentours des deux ziggourats, la sanguinolente et la hurlante. Pour toucher la récompense, présentez-vous au nécrotraqueur Rathiel avec la tête des abominations comme preuve de votre exploit.', },
    {'Recherchez Putrepoing et Luzran dans les Terres fantômes et tuez-les. Rapportez leurs têtes au nécrotraqueur Rathiel à Tranquillien pour empocher une prime.', },
  },
  [9157] = {
    'Rituels oubliés',
    {'Chaque année, les habitants du village de Solcouronne prenaient part à un rituel pour garder le contrôle des différents aspects de la nature. Notre maîtrise de l\'élément aquatique était symbolisée par l\'invocation et l\'asservissement d\'un élémentaire appelé Aquantion. Mais en pervertissant notre magie, Aquantion est parvenu à briser ses chaînes et à faire de nous ses esclaves !|n|nAu cours du rituel, nous portions des médaillons en forme de vagues. Cherchez-les au fond du lac ; nous allons en avoir besoin pour libérer les esprits de nos compatriotes.', },
    {'Apportez 8 Médaillons du front de mer à Geranis Blancmatin, dans les Terres fantômes.', },
  },
  [9158] = {
    'Les porteurs de la peste',
    {'Vous faites preuve de courage en venant dans les Terres fantômes, $N. Il y a beaucoup à faire ici et pas assez d\'âmes courageuses pour tout faire.|n|nJ\'ai une tâche assez ingrate à vous proposer, si vous avez vraiment l\'intention de soutenir notre cause. Sur ces territoires, la peste a atteint même la vie animale, et nous devons absolument l\'empêcher de s\'étendre. Chassez les lynx griffes-fantômes qui rôdent à l\'est et au sud d\'ici, et revenez me voir quand vous en aurez tué suffisamment.', },
    {'Le pérégrin Sedina, à l\'enclave des pérégrins des Terres fantômes, veut que vous tuiez 10 Lynx Griffes-fantômes.', },
  },
  [9159] = {
    'Circonscrire l\'épidémie',
    {'Vous nous avez prouvé que vous étiez $Gun allié:une alliée; de valeur, $N. J\'ai besoin de vous pour poursuivre la tâche et localiser d\'autres animaux pestiférés. Cette fois, essayez de trouver des bêtes plus dangereuses. Chassez les rôdeuses filetoiles à l\'ouest de la Malebrèche et les brumoptères vampiriques, juste au sud, puis revenez me voir.', },
    {'Le pérégrin Sedina à l\'enclave des Pérégrins dans les Terres fantômes veut que vous tuiez 8 Rôdeuses filetoiles et 10 Brumoptères vampiriques.', },
  },
  [9160] = {
    'Enquêter à An\'daroth',
    {'$C, nous avons des problèmes avec un groupe d\'elfes de la nuit. Il y a peu, ils se sont emparés d\'une île située non loin d\'ici. Ils ont installé un petit campement sur l\'ancien nexus tellurique des hauts elfes, An\'daroth, au nord-ouest. Un chemin de terre y mène, juste au-delà de la Malebrèche.|n|nJe vous invite à nous aider en vous rendant là-bas, en enquêtant pour savoir ce qu\'ils manigancent, et en tuant autant de ces prétentieux elfes de la nuit que vous le pourrez.', },
    {'Enquêtez dans la région d\'An\'daroth, tuez 12 Espions des Sentinelles et retournez voir dame Auriférias à Tranquillien dans les Terres fantômes.', },
  },
  [9161] = {
    'L\'ombre du traître',
    {'On dit que Dar\'Khan Drathir est revenu d\'entre les morts pour diriger les armées du Fléau dans les Terres fantômes. Dar\'Khan s\'est rallié au Fléau il y a bien longtemps... pourtant à l\'origine c\'était un elfe bien vivant. Il passait le plus clair de son temps dans la flèche d\'Aubétoile, au nord-est d\'ici. Il s\'y est caché pendant d\'innombrables nuits, à comploter contre les siens.|n|nFouillez la tour pour y trouver des informations, $N. Peut-être tenait-il un journal ou prenait-il des notes. On ne peut jamais savoir à l\'avance où se trouvent les informations utiles.', },
    {'Allez à la Flèche d\'Aubétoile dans les Terres fantômes et cherchez des indices sur le passé de Dar\'Khan.', },
  },
  [9162] = {
    'Vestiges du passé',
    {'Alors que vous parcourez les pages du journal, vous avez l\'irritante sensation d\'être $Gobservé:observée;.|n|nLe contenu est troublant. L\'âme de Dar\'Khan était visiblement noircie par la haine et le mépris qu\'il éprouvait pour son propre peuple. Toutes ses intrigues et ses machinations sont rapportées avec une profusion de détails.|n|nIl y a sans doute quelque chose que Vynna trouvera utile.', },
    {'Retournez voir le forestier Vynna à l\'Enclave des pérégrins avec le Journal de Dar\'Khan.', },
  },
  [9163] = {
    'En territoire occupé',
    {'Nous allons adopter des méthodes plus directes pour comprendre ce que manigancent ces elfes de la nuit. Allez là-bas et emparez-vous de toutes les informations sur lesquelles vous pourrez mettre la main. Je veux que vous preniez la route de l\'ouest et que vous vous dirigiez vers l\'île de Shalandis. Elle est toute proche de la côte. Récupérez tous les plans qui pourraient se trouver sur l\'île ou sur leur bateau.', },
    {'Volez les Plans des elfes de la nuit : An\'daroth, les Plans des elfes de la nuit : An\'owyn, et les Plans des elfes de la nuit : Divination contre les sin\'dorei, puis retournez voir Dame Auriférias à Tranquillien dans les Terres fantômes.', },
  },
  [9164] = {
    'Prisonniers de Mortholme',
    {'Ah, oui. L\'une de mes plus belles créations. Ce breuvage rompt la plupart des formes de stupeur d\'origine alchimique.|n|nLes effets secondaires comprennent un état de confusion, des nausées et - dans de rares cas - une cécité temporaire. Tout cela est bien préférable à ce que le Fléau prévoit de faire aux prisonniers de Mortholme, si vous voulez mon avis.|n|nBonne chance, brave $C. Vous allez en avoir besoin.', },
    {'Apportez le Breuvage de restauration de Renzithen à Mortholme et venez au secours de l\'apprenti Varnis, de l\'apothicaire Enith et du forestier Vedoran. Puis retournez voir l\'arcaniste Janeda au sanctum du Soleil pour recevoir une récompense.', },
  },
  [9165] = {
    'Sauf-conduit',
    {'Sans l\'aide des aventuriers, ma caravane y serait restée, et moi avec ! Des créatures du Fléau surgissaient de toutes parts pour essayer de nous empêcher d\'arriver jusqu\'ici.|n|n<Le garde Didier s\'éponge le front.>|n|nMaintenant il faut qu\'on attende ici le grand maréchal Chambers. Il signera votre sauf-conduit à rapporter au commandant d\'ordonnance Metz à la chapelle de l\'Espoir de Lumière.|n|nAu fait $N, surveillez vos propos en présence de Chambers. C\'est le genre d\'officier qui vous arrache la tête pour mieux vous souffler dans les bronches, sauf qu\'avec lui c\'est pas une image...', },
    {'Apportez le Sauf-conduit signé au commandant d\'ordonnance Metz à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9166] = {
    'Livrer les plans à An\'telas',
    {'Vous devez porter les plans récupérés chez les elfes de la nuit à An\'telas de ma part. C\'est à l\'est, sur le versant sud du pic de Frôle-soleil, au nord-est du sanctum du Soleil.|n|nLe magistère Sylastor y poursuit des recherches sur l\'énergie des lignes et des nexus telluriques, et son utilisation possible dans notre combat contre le Fléau. Demandez-lui de déchiffrer ces plans pour nous éclairer un peu sur les machinations des elfes de la nuit.', },
    {'Livrez les Plans des elfes de la nuit au magistère Sylastor à An\'telas, dans les Terres fantômes.', },
  },
  [9167] = {
    'La destruction du Traître',
    {'Tout ce que nous avons accompli dans les Terres fantômes a été fait avec pour objectif la récupération de ce qui nous appartient de droit. Cela fait bien trop longtemps que le Fléau maintient son emprise étouffante sur la région.|n|nL\'heure est venue de lui rendre la monnaie de sa pièce, $N. Grâce à votre aide et à celle de nos nouveaux alliés les Réprouvés, la vengeance sera bientôt à notre portée.|n|nCelui qui a cherché à voler la puissance du puits de soleil doit mourir. Apportez-moi la tête de Dar\'Khan et vos prouesses resteront dans l\'Histoire !', },
    {'Abattez Dar\'Khan Drathir à Mortholme et rapportez sa tête au magistère Kaendris, au sanctum du Soleil dans les Terres fantômes.', },
  },
  [9168] = {
    'Au cœur de Mortholme',
    {'Dans les profondeurs de Mortholme, nos ennemis s\'acharnent à créer des soldats spectraux plus forts et plus dangereux. Ces créatures répugnantes sont de parfaites machines à tuer, mises au point par Dar\'khan en personne et endurcies par la magie de Mortholme.|n|nAllez jusqu\'à la tour des Damnés à l\'intérieur de Mortholme et détruisez-les, $N. Nous ne pouvons pas nous permettre de laisser les rangs de l\'armée ennemie se renforcer alors que nous luttons pour maintenir notre avant-poste dans les Terres fantômes.', },
    {'Détruisez 8 Yeux de Dar\'Khan et rendez compte au magistère Idonis, au Sanctum du Soleil dans les Terres fantômes.', },
  },
  [9169] = {
    'Désactiver An\'owyn',
    {'Leurs cristaux de lune sont des appareils de surveillance - Ils vont nous espionner ! Je sais que l\'énergie disponible à An\'dorath ne leur suffira pas. En revanche, ils trouveront tout ce dont ils ont besoin à An\'owyn, juste au sud !|n|nCes plans m\'ont permis de comprendre à peu près comment fonctionnent ces cristaux de lune ; suffisamment pour les neutraliser. Ils sont conçus de façon à pouvoir être allumés ou éteints. Vous devez aller à An\'owyn, récupérer l\'orbe de contrôle sur l\'un des elfes de la nuit, et l\'utiliser sur le cristal de lune pour empêcher la réalisation de leur plan !|n|nFaites vite, $C !', },
    {'Récupérez l\'Orbe de contrôle du cristal et utilisez-la pour désactiver le Cristal de lune des elfes de la nuit à An\'owyn. Retournez ensuite auprès du magistère Sylastor à An\'telas, dans les Terres fantômes.', },
  },
  [9170] = {
    'Les lieutenants de Dar\'Khan',
    {'Dar\'Khan, ce traître immonde, occupe désormais une position très importante dans les rangs du Fléau. Ses lieutenants commandent des armées de morts-vivants toujours plus nombreuses, face à nos forces qui ne cessent de décroître.|n|nMasophet le Noir, Jurion le Menteur, Borgoth le Saigneur et Mirdoran le Déchu. Retenez bien leur nom, car ils ne le cèdent qu\'à Dar\'Khan. Tuez-les, et ses armées seront décapitées.', },
    {'Le magistère Idonis veut que vous alliez à Mortholme pour tuer Masophet le Noir, Jurion le Menteur, Borgoth le Saigneur et Mirdoran le Déchu. Allez ensuite lui rendre compte du succès de votre mission au sanctum du Soleil, dans les Terres fantômes.', },
  },
  [9171] = {
    'Il faut que ça croustille !',
    {'C\'est in-to-lé-ra-ble ! Je n\'ai rien, absolument rien pour travailler ! Dame Auriférias m\'a demandé de venir de Lune-d\'Argent ; il convient qu\'elle soit servie comme une dame de haut rang, n\'est-ce pas ? Mais j\'arrive ici, et il n\'y a rien à manger. Rien ! Vous devez sortir et nous ramener des proies fraîchement tuées, $C, pour que j\'aie quelque chose à préparer.|n|nFigurez-vous que dame Auriférias a un penchant pour les nourritures croustillantes. Il y a des quantités de rôdeuses Filetoile au sud-ouest, de l\'autre côté de la Malebrèche. Je sais, c\'est dégoûtant, mais il faudra bien faire avec.', },
    {'Collectez 5 Pattes d\'araignée croustillantes et ramenez-les au maître cuisinier Mouldier à Tranquillien dans les Terres fantômes.', },
  },
  [9172] = {
    'Un rapport pour le magistère Kaendris',
    {'Avec l\'aide des Réprouvés, les magistères du sanctum du Soleil ont beaucoup progressé dans l\'analyse des faiblesses du Fléau. Le magistère Kaendris saura quoi faire de cette information.|n|nVous le trouverez au sanctum du Soleil, au sud-ouest. Faites vite, $N. Dar\'Khan est rusé, et il observe nos moindres mouvements !', },
    {'Remettre le Journal de Dar\'Khan au magistère Kaendris au sanctum du Soleil, dans les Terres fantômes.', },
  },
  [9173] = {
    'Reprendre la flèche de Coursevent',
    {'$C, je veux que vous repreniez la flèche de Coursevent !|n|nEn vérité, c\'est un honneur que je vous fais, car c\'est le lieu de naissance de dame Sylvanas, reine des Réprouvés et anciennement général des forestiers elfes. Pour l\'heure, la flèche est occupée par les monstres imbéciles du Fléau.|n|nPour y aller, prenez la route du sud jusqu\'à l\'embranchement et tournez à droite. Lorsque vous aurez traversé la Malebrèche, continuez vers le sud-ouest. Vous ne pouvez pas la rater.', },
    {'Tuez 8 Acolytes de Mortholme et 10 Forestiers déchus, puis retournez voir le Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes.', },
  },
  [9174] = {
    'Vaincre Aquantion',
    {'Cet élémentaire opiniâtre a soufflé nombre de vies au jour maudit de sa révolte. En faisant appel aux misérables murlocs pour saboter nos rituels, il a détourné notre magie et l\'a retournée contre nous.|n|nMontrez-lui que notre soif de vengeance n\'a pas faibli ! Prenez ces médaillons et allez les déposer sur l\'autel de la maîtrise des flots, au fond du lac. Aquantion devrait répondre immédiatement à votre invocation !|n|nPrenez garde, $R ! Sans notre magie pour la contrôler, sa colère sera sans borne. Détruisez Aquantion pour que nous retrouvions la paix !', },
    {'Geranis Blancmatin veut que vous nagiez au fond du lac à l\'est de Solcouronne et que vous utilisiez le Paquet de médaillons sur l\'Autel de la maîtrise des flots. Invoquez et détruisez l\'élémentaire appelé Aquantion, puis retournez voir Geranis.', },
  },
  [9175] = {
    'Le collier de la dame',
    {'Le collier scintille. C\'est une pièce de joaillerie remarquable qui semble résister à la mélancolie qui emplit les Terres fantômes. Étant donné l\'inscription et le lieu où vous l\'avez trouvé, il a dû être perdu par dame Sylvanas Coursevent elle-même !|n|nLa meilleure solution serait peut-être de l\'apporter au grand exécuteur Mavren à Tranquillien. Il semble être le Réprouvé de plus haut rang de la région et il saura sûrement quoi en faire.', },
    {'Apportez le Collier de la dame au Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes.', },
  },
  [9176] = {
    'Les ziggourats jumelles',
    {'Selon ce journal, Dar\'Khan a promis au Fléau deux puissants artéfacts elfiques : la pierre de lumière et la pierre de flammes. Elles ont été imprégnées des énergies magiques du puits de soleil et possèdent des pouvoirs de protection contre le Fléau.|n|nLes cristaux devaient être transportés là où se trouvent maintenant la Ziggourat hurlante et la Ziggourat sanguinolente, au milieu de la Malebrèche. S\'ils sont toujours là, il faut que nous les retrouvions. Leur puissance nous sera extrêmement utile dans notre lutte contre l\'ennemi.', },
    {'Rendez-vous à la Ziggourat sanguinolente et à la Ziggourat hurlante et retrouvez la Pierre de lumière et la Pierre de flammes. Retournez voir le magistère Kaendris au Sanctum du Soleil après avoir récupéré les objets.', },
  },
  [9177] = {
    'En route pour Fossoyeuse',
    {'Voilà qui est extraordinaire ! Il semble qu\'il s\'agisse d\'un cadeau fait à dame Sylvanas par sa sœur en personne, Alleria !|n|nVous devez immédiatement le lui apporter à Fossoyeuse ! La Dame tient sa cour dans le Quartier royal.|n|nPour vous rendre à Fossoyeuse, utilisez l\'orbe de transposition au sanctum intérieur de la Flèche de Solfurie à Lune-d\'Argent. Une fois là-bas, prenez l\'ascenseur pour descendre jusqu\'à la ville proprement dite. Utilisez vos cartes si vous avez du mal à trouver le Quartier royal.', },
    {'Apportez le Collier de la Dame à dame Sylvanas Coursevent dans le Quartier royal de Fossoyeuse.', },
  },
  [9178] = {
    'Commission d\'artisan - Pierre de lest denses',
    {'Le porteur de la présente commission est en droit de recevoir comme paiement l\'insigne de son choix à la livraison des articles ci-dessous.|n|nBon de commande FG-091 :|n|n120 pierres de lest denses.|n|nToute commission honorée doit être livrée au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est.|n|nLe présent contrat est nul et non avenu s\'il est modifié ou endommagé.|n|n-Commandant d\'ordonnance Metz, Aube d\'argent', },
    {'Livrer 120 Pierres de lest denses et la Commission d\'artisan - Pierres denses au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9179] = {
    'Commission d\'artisan - Pansières impériales',
    {'Le porteur de la présente commission est en droit de recevoir comme paiement l\'insigne de son choix à la livraison des articles ci-dessous.|n|nBon de commande FG-428 :|n|n3 pansières impériales.|n|nToute commission honorée doit être livrée au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est.|n|nLe présent contrat est nul et non avenu s\'il est modifié ou endommagé.|n|n-Commandant d\'ordonnance Metz, Aube d\'argent', },
    {'Livrer 3 Pansières impériales et la Commission d\'artisan - Pansières impériales au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9180] = {
    'En route pour Fossoyeuse',
    {'Voilà qui est extraordinaire ! Il semble qu\'il s\'agisse d\'un cadeau fait à dame Sylvanas par sa sœur en personne, Alleria !|n|nVous devez immédiatement le lui apporter à Fossoyeuse ! La Dame tient sa cour dans le Quartier royal.|n|nPour vous rendre à Fossoyeuse, utilisez l\'orbe de transposition au sanctum intérieur de la Flèche de Solfurie à Lune-d\'Argent. Une fois là-bas, prenez l\'ascenseur pour descendre jusqu\'à la ville proprement dite. Utilisez vos cartes si vous avez du mal à trouver le Quartier royal.', },
    {'Apportez le Collier de la Dame à dame Sylvanas Coursevent dans le Quartier royal de Fossoyeuse.', },
  },
  [9181] = {
    'Commission d\'artisan - Marteaux volcaniques',
    {'Le porteur de la présente commission est en droit de recevoir comme paiement l\'insigne de son choix à la livraison des articles ci-dessous.|n|nBon de commande FG-697 :|n|n3 marteaux volcaniques.|n|nToute commission honorée doit être livrée au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'est.|n|nLe présent contrat est nul et non avenu s\'il est modifié ou endommagé.|n|n-Commandant d\'ordonnance Metz, Aube d\'argent', },
    {'Livrer 3 Marteaux volcaniques et la Commission d\'artisan - Marteaux volcaniques au maître-fourrier Navrepierre, à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9182] = {
    'Commission d\'artisan - Hache d\'armes énorme en thorium',
