  [9299] = {
    'Une note du front',
    {'Vous avez trouvé cette lettre sur l\'un des nombreux serviteurs du Fléau que vous avez tués. À en juger par son apparence et son odeur, elle a longtemps été en la possession de morts-vivants. Peut-être que quelqu\'un à la chapelle de l\'Espoir de Lumière souhaiterait l\'examiner plus attentivement...', },
    {'Apportez la Note détériorée au gardien des registres à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9300] = {
    'Une page du front',
    {'Vous avez trouvé cette lettre sur l\'un des nombreux serviteurs du Fléau que vous avez tués. À en juger par son apparence et son odeur, elle a longtemps été en la possession de morts-vivants. Peut-être que quelqu\'un à la chapelle de l\'Espoir de Lumière souhaiterait l\'examiner plus attentivement...', },
    {'Apportez la Page abîmée au gardien des registres à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9301] = {
    'Une enveloppe du front',
    {'Vous avez trouvé cette lettre sur l\'un des nombreux serviteurs du Fléau que vous avez tués. À en juger par son apparence et son odeur, elle a longtemps été en la possession de morts-vivants. Peut-être que quelqu\'un à la chapelle de l\'Espoir de Lumière souhaiterait l\'examiner plus attentivement...', },
    {'Apportez l\'Enveloppe tachée de sang au gardien des registres à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9302] = {
    'Une missive du front',
    {'Vous avez trouvé cette lettre sur l\'un des nombreux serviteurs du Fléau que vous avez tués. À en juger par son apparence et son odeur, elle a longtemps été en la possession de morts-vivants. Peut-être que quelqu\'un à la chapelle de l\'Espoir de Lumière souhaiterait l\'examiner plus attentivement...', },
    {'Apportez la Missive froissée au gardien des registres à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9303] = {
    nil,
    {'Zhanaa a besoin de notre aide pour récupérer des pièces de l\'Exodar. Taerix a préparé une solution qui doit être injectée aux chouettides Nidebois qui vivent dans la zone où se trouvent beaucoup de débris.|n|nIl vous suffira de vous approcher des chouettides encore sains et d\'utiliser le cristal sur eux. Malheureusement, vous devrez tuer les autres. Vous les trouverez au bosquet des Nidebois et dans les collines des Nidebois, au sud-est.', },
    {'Utilisez le Cristal d\'inoculation sur 6 Chouettides nidebois. Retournez ensuite auprès du redresseur de torts Aldar au Point d\'impact du val d\'Ammen.', },
  },
  [9304] = {
    'Un document du front',
    {'Vous avez trouvé cette lettre sur l\'un des nombreux serviteurs du Fléau que vous avez tués. À en juger par son apparence et son odeur, elle a longtemps été en la possession de morts-vivants. Peut-être que quelqu\'un à la chapelle de l\'Espoir de Lumière souhaiterait l\'examiner plus attentivement...', },
    {'Apportez le Document taché au gardien des registres à la chapelle de l\'Espoir de Lumière dans les Maleterres de l\'Est.', },
  },
  [9305] = {
    'Pièces de rechange',
    {'Nous avons réussi à récupérer un émetteur holographique, mais l\'accident l\'a endommagé. Si nous pouvions le réparer, il nous aiderait à trouver d\'autres survivants à l\'extérieur du val d\'Ammen.|n|nLe vaisseau contenait des appareils qui auraient pu nous servir de source de pièces de rechange, mais les chouettides du coin s\'en sont emparés avant que nous ne les récupérions nous-mêmes.|n|n$N, vous devez aller vers le sud, au fourré et dans les collines des Nidebois pour retrouver les pièces de rechange.', },
    {'Récupérez 4 Pièces de rechange pour l\'émetteur puis rapportez-les à la technicienne Zhanaa au Point d\'impact du val d\'Ammen.', },
  },
  [9306] = {
    'Discuter avec le redresseur de torts Aldar',
    {'$N, le redresseur de torts Aldar cherche quelqu\'un capable de s\'occuper du problème que nous avons avec les chouettides mutants du fourré des Nidebois. Nous devons nous occuper d\'une conséquence malheureuse de notre arrivée imprévue ici.|n|nVous le trouverez à l\'extérieur, plus au sud, au point d\'impact. Je vous en prie, allez lui parler dès que vous le pourrez.', },
    {'Allez parler au redresseur de torts Aldar, au Point d\'impact du val d\'Ammen.', },
  },
  [9307] = {
    'Compassion',
    {'Le lac Rivargent tout proche a été irradié lorsque l\'un des fragments du vaisseau s\'y est englouti. Cela a engendré des mutations chez de nombreuses créatures, et certaines sont devenues hostiles, au premier rang desquelles les chouettides mutés.|n|nAllez dans le fourré des Nidebois, au sud, et achevez autant de ces malheureuses créatures que possible. Soyez $Gun:une:c; $C miséricordieux, essayez d\'opérer proprement et sans douleur.', },
    {'Tuez 14 Chouettides mutés, puis retournez voir le redresseur de torts Aldar au Point d\'impact du val d\'Ammen.', },
  },
  [9308] = {
    'Des restes d\'elfe de sang ?',
    {'Vous êtes $Gsûr:sûre; que les restes mutilés qui gisent sur le sol sont ceux d\'un sin\'dorei : un elfe de sang. À en juger par ses blessures, il semble qu\'il soit tombé sous les griffes des chouettides mutants qui vivent dans le fourré.|n|nEn fouillant le corps, vous découvrez qu\'il porte une amulette autour du cou. Elle intéresserait peut-être le redresseur de torts Aldar.', },
    {'Remettez l\'Amulette d\'elfe de sang au redresseur de torts Aldar, au Point d\'impact du val d\'Ammen.', },
  },
  [9309] = {
    'L\'éclaireur disparu',
    {'Plusieurs sources distinctes nous ont fait savoir qu\'il se passerait des choses étranges sur l\'Ombrecrête.|n|nC\'est troublant. Nous pensions que nos précédentes reconnaissances avaient été complètes. Un de mes éclaireurs n\'a pas encore fait son rapport.|n|n$C, je compte sur vous pour partir vers le sud-ouest, de l\'autre côté du lac Rivargent, à la recherche de Tolaan, et déterminer ce qui l\'a retardé.', },
    {'Trouvez Tolaan sur l\'Ombrecrête du val d\'Ammen et parlez-lui.', },
  },
  [9310] = {
    'Cristal nécrotique voilé',
    {'Sur le cadavre de la créature nécrophage, vous découvrez un cristal qui émet faiblement de l\'énergie nécrotique.', },
    {'Apportez le Cristal nécrotique voilé au lieutenant Rukag dans la cour de Fossoyeuse.', },
  },
  [9311] = {
    'L\'espionne elfe de sang',
    {'J\'ai un plan. Nous devons tuer leur chef. Sans leur maître, peut-être qu\'ils vont battre en retraite pour se regrouper. Nous avons seulement besoin de gagner du temps jusqu\'à ce que les réparations soient achevées.|n|nPuis le redresseur de torts Aldar devra être mis au courant. Tuez la géomètre, puis revenez et dites-lui ce que nous avons trouvé.', },
    {'Tuez la Géomètre Candress, puis allez rendre compte au redresseur de torts Aldar, au Point d\'impact du val d\'Ammen.', },
  },
  [9312] = {
    'L\'émetteur',
    {'$N, pendant que vous étiez $Gparti:partie; enquêter sur l\'Ombrecrête, Zhanaa ici présente a travaillé sur l\'émetteur holographique. Vous devriez aller lui parler.', },
    {'Allez voir la technicienne Zhanaa, au Point d\'impact du val d\'Ammen.', },
  },
  [9313] = {
    'En route pour le Guet d\'azur',
    {'Par tout ce qui est bon, $N, vous devez immédiatement vous rendre à ce Guet d\'azur pour y rencontrer Dyvuun !|n|nIl y a un chemin qui mène à l\'ouest, hors de cette île minuscule. Suivez-le, traversez la Cristalline, et vous arriverez sur la partie principale de l\'île. Poursuivez votre route le long de ce chemin et vous devriez trouver le Guet d\'azur.|n|nVoyez si vous pouvez les convaincre de nous envoyer de l\'aide et du ravitaillement. Nous vous rejoindrons là-bas dès que nous le pourrons.|n|nMerci, sans vous nous n\'y serions pas arrivés !', },
    {'Allez voir le technicien Dyvuun au Guet d\'azur, sur l\'Île de Brume-azur.', },
  },
  [9314] = {
    'Une demande du Guet d\'azur',
    {'$C ! Deux de ces bêtes mutantes se sont jetées sur moi et je suis blessé à la jambe.|n|nJ\'avais été envoyé en tant qu\'éclaireur par le Guet d\'azur suite aux indications que nous avons reçues de Zhanaa. S\'il vous plaît, ça ne vous dérangerait pas trop d\'aller parler à l\'hôtesse Chellan à ma place ? Il faut qu\'elle sache combien de personnes arriveront au Guet d\'azur. Vous n\'avez qu\'à traverser la Cristalline ici et à suivre la route jusqu\'au Guet d\'azur.|n|nN\'oubliez pas de lui demander de vous loger pendant que vous serez là-bas.', },
    {'Allez voir l\'hôtesse Chellan au Guet d\'azur, sur l\'Île de Brume-azur.', },
  },
  [9315] = {
    nil,
    {'Approchez. Je vais... mourir.|n|nOn m\'a envoyé ici... pour tuer ces nérubiens, mais Vandril ne... savait pas qu\'ils avaient un chef.|n|n<L\'elfe de sang moribond est pris d\'une quinte de toux et crache une grande quantité de sang.>|n|nVous devez trouver et... tuer Anok\'suten. Elle erre autour... du village de Solcouronne. N\'y allez pas $Gseul:seule;.', },
    {'Tuez Anok\'suten et retournez voir l\'arcaniste Vandril, à Tranquillien dans les Terres fantômes.', },
  },
  [9316] = {
    '[TXT] Sauvages gobelins',
    {'<Brianna vous observe attentivement.>|n|nAlors comme ça vous voulez tuer des gobelins ? Bon, si vous y tenez, vous pouvez commencer avec les sauvages des alentours. Apportez-moi leurs dents pour preuves de vos exploits.', },
    {'Brianna Schneider sur l\'île des concepteurs veut 10 Dents de gobelins.', },
  },
  [9317] = {
    'Pierre à aiguiser consacrée',
    nil,
    nil,
  },
  [9318] = {
    'Huile de sorcier bénie',
    nil,
    nil,
  },
  [9319] = {
    'Une lumière au sein des ombres',
    {'Nous ne sommes pas les seuls à célébrer cette fête, $N. Toutes les créatures, toutes les cultures, sont touchées par les flammes. Même dans les lieux les plus sombres, des feux sont allumés.|n|nSi vous souhaitez le vérifier par vous-même, voyagez dans les profondeurs. Cherchez les feux de joie qui brûlent dans Stratholme, dans la Scholomance, parmi les ogres de Hache-Tripes et dans les salles du pic Rochenoire lui-même ; j\'attendrai votre retour.', },
    {'Trouvez et touchez les feux de joie situés au pic Rochenoire, à Hache-Tripes, dans la Scholomance et à Stratholme. Puis retournez voir le gardien des flammes de la fête.', },
  },
  [9320] = {
    'Potion de super-mana',
    nil,
    nil,
  },
  [9321] = {
    'Potion de super-soins',
    nil,
    nil,
  },
  [9322] = {
    'Feux sauvages en Kalimdor',
    {'La fête du Feu du solstice d\'été est célébrée partout en Azeroth, et les terres contrastées de Kalimdor ne font guère exception. À vous voir, un voyage ne vous ferait pas de mal.|n|nLe solstice d\'été ne peut être pleinement apprécié que si vous voyez les grands feux bleutés de par le monde. Les célébrants ont allumé des feux dans l\'ouest de la froide région de Berceau-de-l\'hiver, dans le nord-est d\'Azshara, près du Repos des Vaillants dans les terres désolées de Silithus, et près de l\'entrée de la luxuriante contrée d\'Un\'Goro. Revenez quand vous aurez achevé votre voyage.', },
    {'Visitez les campements du solstice d\'été en Azshara, en Silithus, au cratère d\'Un\'Goro et à Berceau-de-l\'Hiver, puis revenez voir le Gardien des flammes.', },
  },
  [9323] = {
    'Feux sauvages dans les royaumes de l\'Est',
    {'Notre célébration de la flamme se répand à travers les territoires, $C. Aucun lieu n\'est assez éloigné pour ne pas ressentir la chaleur de notre fête, et les plus grands feux brillent de flammes d\'un bleu intense. Allez les voir.|n|nVous en trouverez un juste au nord du pic Rochenoire. Les autres sont près d\'une ville en ruine au cœur des Maleterres de l\'est, le long de la route des falaises dans les montagneuses Hinterlands, et sur la voie de la Porte des ténèbres dans les terres Foudroyées.|n|nRevenez une fois que votre voyage sera terminé.', },
    {'Rendez visite aux campements de la fête du Feu situés dans les Terres Foudroyées, les Maleterres de l\'Est, les Hinterlands, et la gorge des Vents brûlants, puis allez parler au gardien des flammes de la fête.', },
  },
  [9324] = {
    'Voler la flamme d\'Orgrimmar',
    {'Cette flamme, dérobée au cœur même d\'Orgrimmar, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...', },
    {'Rapportez la Flamme d\'Orgrimmar au Maître des traditions.', },
  },
  [9325] = {
    'Voler la flamme des Pitons-du-Tonnerre',
    {'Cette flamme, dérobée aux chamans des Pitons-du-Tonnerre, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...', },
    {'Rapportez la flamme des Pitons-du-Tonnerre au Maître des traditions.', },
  },
  [9326] = {
    'Voler la flamme de Fossoyeuse',
    {'Cette flamme, dérobée dans les ruines au-dessus de Fossoyeuse, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Maître des traditions saura sûrement vous en dire plus...', },
    {'Rapportez la flamme de Fossoyeuse au Maître des traditions.', },
  },
  [9327] = {
    'Les Réprouvés',
    {'Je sais que ça peut paraître bizarre, mais ces Réprouvés sont là pour nous aider. Vous devriez parler avec leur chef, le grand exécuteur Mavren. Il se trouve dans la tour à l\'ouest de la ville.|n|nQuand vous en aurez fini avec lui, $C, revenez me voir. J\'ai un problème grave qui doit être résolu au plus vite !', },
    {'Allez parler au Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes.', },
  },
  [9328] = {
    'Un héros parmi les Sin\'dorei',
    {'C\'est le début d\'un nouveau chapitre dans l\'histoire de notre peuple, $N. Nous allons reprendre nos terres, et renforcer nos liens avec Sylvanas et ses alliés.|n|nApportez la tête du traître au seigneur régent Lor\'themar Theron, à Lune-d\'Argent. Cette nouvelle le ravira.', },
    {'Apportez la Tête de Dar\'Khan à Lor\'themar Theron, à Lune-d\'Argent.', },
  },
  [9329] = {
    'Les Réprouvés',
    {'Je sais que ça peut paraître bizarre, mais les Réprouvés sont là pour nous aider. Vous devriez parler avec leur chef, le grand exécuteur Mavren. Il se trouve dans la tour à l\'ouest de la ville.|n|nQuand vous en aurez fini avec lui, $C, revenez me voir. J\'ai un problème grave qui doit être résolu au plus vite !', },
    {'Allez parler au Grand exécuteur Mavren à Tranquillien, dans les Terres fantômes.', },
  },
  [9330] = {
    'Voler la flamme de Hurlevent',
    {'Cette flamme, dérobée au cœur même de Hurlevent, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Conteur de la fête saura sûrement vous en dire plus...', },
    {'Rapportez la flamme de Hurlevent au Conteur de la fête.', },
  },
  [9331] = {
    'Voler la flamme de Forgefer',
    {'Cette flamme, dérobée au cœur même de Forgefer, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Conteur de la fête saura sûrement vous en dire plus...', },
    {'Rapportez la flamme de Forgefer au Conteur de la fête.', },
  },
  [9332] = {
    'Voler la flamme de Darnassus',
    {'Cette flamme, dérobée sur les côtes de Teldrassil, vous inonde de chaleur. Ce pouvoir brut vous est étranger, mais le Conteur de la fête saura sûrement vous en dire plus...', },
    {'Rapportez la flamme de Darnassus au Conteur de la fête.', },
  },
