  [10733] = {
    'Sur la voie pourpre',
    {'Vous avez choisi votre voie, $C. Il vous échoit maintenant de la suivre, quel que soit l\'endroit où elle vous conduira.|n|nVous verrez qu\'avoir des amis parmi les archimages de Dalaran procure certains avantages. Servez-nous bien, et vos actions seront récompensées.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Honoré:devenue Honorée; auprès de l\'Œil pourpre.', },
  },
  [10734] = {
    'Sur la voie pourpre',
    {'Vous avez choisi votre voie, $C. Il vous échoit maintenant de la suivre, quel que soit l\'endroit où elle vous conduira.|n|nVous verrez qu\'avoir des amis parmi les archimages de Dalaran procure certains avantages. Servez-nous bien, et vos actions seront récompensées.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Honoré:devenue Honorée; auprès de l\'Œil pourpre.', },
  },
  [10735] = {
    'Sur la voie pourpre',
    {'Vous avez choisi votre voie, $C. Il vous échoit maintenant de la suivre, quel que soit l\'endroit où elle vous conduira.|n|nVous verrez qu\'avoir des amis parmi les archimages de Dalaran procure certains avantages. Servez-nous bien, et vos actions seront récompensées.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Honoré:devenue Honorée; auprès de l\'Œil pourpre.', },
  },
  [10736] = {
    'Sur la voie pourpre',
    {'Vous avez choisi votre voie, $C. Il vous échoit maintenant de la suivre, quel que soit l\'endroit où elle vous conduira.|n|nVous verrez qu\'avoir des amis parmi les archimages de Dalaran procure certains avantages. Servez-nous bien, et vos actions seront récompensées.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Honoré:devenue Honorée; auprès de l\'Œil pourpre.', },
  },
  [10737] = {
    'Le toucher du maître',
    {'J\'ai reconstitué la clé que j\'utilisais quand j\'étais apprenti. Apparemment, elle est entièrement fonctionnelle en tant que clé. Mais pour ce qui est d\'ouvrir Karazhan, elle n\'est peut-être qu\'un vieux bout de métal.|n|nSans le consentement de Medivh, cette clé n\'a aucune valeur. Oui, bien sûr que je sais que Medivh est mort. Cela rend les choses plus difficiles, pas impossibles.|n|nIl existe en Azeroth un endroit appelé les Grottes du temps, gardé par le Vol de bronze. Trouvez le moyen d\'y entrer, voyagez dans le temps et allez voir Medivh pour qu\'il active la clé.', },
    {'Rendez-vous aux Grottes du temps et persuadez Medivh d\'accepter votre Clé de l\'apprenti réparée.', },
  },
  [10738] = {
    'Une distinction pour services rendus',
    {'Vous ne nous avez pas déçus, $N. Nous attendons encore beaucoup de vous, cependant.|n|nContinuez à servir l\'Œil pourpre et vous serez $Grécompensé:récompensée; comme il se doit.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Révéré:devenue Révérée; auprès de l\'Œil pourpre.', },
  },
  [10739] = {
    'Une distinction pour services rendus',
    {'Vous ne nous avez pas déçus, $N. Nous attendons encore beaucoup de vous, cependant.|n|nContinuez à servir l\'Œil pourpre et vous serez $Grécompensé:récompensée; comme il se doit.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Révéré:devenue Révérée; auprès de l\'Œil pourpre.', },
  },
  [10740] = {
    'Une distinction pour services rendus',
    {'Vous ne nous avez pas déçus, $N. Nous attendons encore beaucoup de vous, cependant.|n|nContinuez à servir l\'Œil pourpre et vous serez $Grécompensé:récompensée; comme il se doit.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Révéré:devenue Révérée; auprès de l\'Œil pourpre.', },
  },
  [10741] = {
    'Une distinction pour services rendus',
    {'Vous ne nous avez pas déçus, $N. Nous attendons encore beaucoup de vous, cependant.|n|nContinuez à servir l\'Œil pourpre et vous serez $Grécompensé:récompensée; comme il se doit.', },
    {'Apportez votre Chevalière pourpre à l\'archimage Leryda au défilé de Deuillevent après être $Gdevenu Révéré:devenue Révérée; auprès de l\'Œil pourpre.', },
  },
  [10742] = {
    'Cartes sur table',
    {'Voici ce qu\'il nous reste à faire. Nous allons attirer Goc hors de son repaire et le détruire. Une fois Goc mort, les ogres de Flèchelame ne menaceront plus les Mok\'Nathal. Rendez-vous à l\'autel de Goc à l\'extérieur du repaire de Gruul, puis soufflez dans mon cor. Je viendrai, et ensemble nous affronterons le fils de Gruul.', },
    nil,
  },
  [10743] = {
    '<txt>Héros des Mok\'Nathal',
    nil,
    nil,
  },
  [10744] = {
    'Des nouvelles de la victoire',
    {'Vous devez immédiatement informer Kurdran Marteau-Hardi de votre succès ! Ses hommes, sous les ordres du chef d\'escadrille Nuainn, ont combattu sans relâche pour assurer la sécurité du bastion des Marteaux-hardis et votre retour aura sûrement un effet positif sur leur moral. Maintenant que la menace de la Légion est écartée, Kurdran peut enfin tourner son attention vers les forces d\'Illidan. Notre position ici est loin d\'être sûre, mais nous avons remporté une grande victoire aujourd\'hui.', },
    {'Retournez au Bastion des Marteaux-Hardis et parlez à Kurdran Marteau-Hardi.', },
  },
  [10745] = {
    'Des nouvelles de la victoire',
    {'Vous devez apporter la nouvelle de notre réussite au suzerain Or\'barokh immédiatement ! Maintenant que nous avons écrasé la Légion et éliminé sa présence dans la vallée d\'Ombrelune, le suzerain peut consacrer son attention à nos autres ennemis.|n|nMême si la garde kor\'kronne ne l\'admettra jamais, elle sera heureuse de ne plus avoir à combattre sur deux fronts.', },
    {'Retournez au village d\'Ombrelune et parlez au suzerain Or\'barokh.', },
  },
  [10746] = {
    '[PÉRIMÉ) Karazhan: LAB - E - Anneau Exalté - Lanceur',
    {'Vos exploits dépassent mes espoirs les plus fous, $N.|n|nVous vous promenez dans et hors du temps avec autant d\'aise que tous les dragons de bronze que je connais. Votre destinée est celle d\'un pouvoir immense, et je suis plus qu\'heureuse de vous aider sur votre chemin.|n|nContinuez à servir la Balance des sables et je déchaînerai le plein potentiel de votre don.', },
    {'Apportez votre Bague d\'éternité à Soridormi aux Grottes du temps après être $Gdevenu Exalté:devenue Exaltée; auprès de la Balance des sables.', },
  },
  [10747] = {
    'Les dragonnets du culte du Ver',
    {'Il faut que j\'examine les dragonnets qu\'ils élèvent au Convent de l\'Aile noire.|n|nIls devraient être nombreux à voler à l\'intérieur de leurs cavernes, et vous trouverez aussi des œufs, qui écloront sûrement si vous vous approchez.|n|nS\'il vous plaît, $N, prenez le filet et capturez-en quelques vivants pour moi.|n|nVous les trouverez en traversant le pont Crâne-du-ver vers l\'ouest et en vous dirigeant vers le tunnel Crâne-du-ver. Suivez la route jusqu\'au bout, au-delà de Grishnath et du Bois aux corbeaux.', },
    nil,
  },
  [10748] = {
    'Maxnar doit mourir !',
    {'Ils ne nous ont pas laissé le choix, $N. Il est temps de mettre un terme à la menace que représente le Convent de l\'Aile noire en supprimant son chef, Maxnar le Cendregueule.|n|nJe ne sais pas si vous l\'avez aperçu quand vous y étiez, c\'est l\'un des draconiens, mi-homme, mi-dragon. Il est rudement coriace, ne le sous-estimez pas !|n|nFinissez-en avec lui rapidement, et avec un peu de chance vous aurez assuré la sécurité du Bosquet éternel et de la sylve Ruuan.', },
    nil,
  },
  [10749] = {
    'Le poison du baron Sablecrin',
    {'Voilà, apportez cela à votre maître. Je suis sûr que quelle qu\'en soit la raison, Rexxar en fera bon usage.|n|nOh, et n\'oubliez pas de lui rappeler qu\'il me doit une faveur.|n|nIl sait ce que je demande, et je suis certain que s\'il a l\'intention de le récupérer pour moi, je risque de vous revoir plus tôt que vous ne le penseriez.|n|nAllez, soyez $Gun gentil garçon:une gentille fille;, et donnez ceci à Rexxar.', },
    {'Livrez le Poison du baron Sablecrin à Rexxar, au bastion des Sire-tonnerre, dans les Tranchantes.', },
  },
  [10750] = {
    'La voie de la Conquête',
    {'Mes coursiers du vent sont revenus avec quelques nouvelles, $N ! Les elfes de sang de l\'Eclipsion sont en train de préparer un gros coup. Ils ont commencé à lever leur armée sur la voie de la Conquête, au sud-est d\'ici, près de la halte de l\'Éclipse.|n|nJe veux que vous alliez sur la voie de la Conquête pour évaluer la situation. Une fois que ce sera fait, utilisez ce lance-fusée pour faire un signal aux coursiers du vent. L\'un d\'entre eux descendra à votre rencontre. Dites-lui ce que vous aurez découvert et il vous donnera vos prochaines instructions.', },
    nil,
  },
  [10751] = {
    'Ouvrir la voie',
    {'Nous allons avoir besoin de plus de temps, $R. Je vais voler un peu plus en avant, avec quelques coursiers du vent. Avec un peu de chance, nous pourrons rassembler de nouvelles informations. J\'ai besoin que vous m\'ouvriez la voie et, plus important encore, que vous vous débrouilliez pour qu\'aucune flèche ne soit pointée vers nous !|n|nAppelez un coursier du vent avec le lance-fusée kor\'kron quand vous aurez diminué le nombre de nos adversaires.', },
    nil,
  },
  [10752] = {
    'En direction d\'Orneval',
    {'Récemment, Raene Mène-loup a traversé Auberdine, en arrivant de Darnassus, et est partie en direction d\'Orneval. Elle a parlé d\'une histoire avec les furbolgs. Je n\'ai pas eu l\'occasion de lui en demander plus, mais vous pourriez peut-être la trouver et lui proposer votre aide, $C. Prenez la route du sud en sortant d\'Auberdine. Quand vous aurez atteint Orneval, continuez sur le même chemin. Vous arriverez à Astranaar, où vous trouverez Raene Mène-loup.', },
    {'Parler à Raene Mène-loup à Astranaar.', },
  },
  [10753] = {
    'Tuer les bêtes sauvages',
    {'Les atrocités commises par la Légion ardente ne se comptent plus. À l\'heure où nous parlons, elle envoie ses forces contre les créatures de ces contrées. Incapables de se défendre contre sa puissance, elles tombent une par une. $N, aidez-moi à empêcher ces crimes contre la nature de détruire tout ce qu\'ils corrompent.|n|nAu-delà de la colline, à l\'est d\'ici, vous verrez la corruption se répandre depuis le goulet des Lames. Tuez les responsables de ce crime, les corrupteurs gangrenés, et autant de gangreliges que possible.', },
    nil,
  },
  [10754] = {
    'L\'entrée dans la citadelle',
    {'Ce moule fraîchement coulé devait servir à fabriquer une sorte de clé. D\'après l\'image gravée à son dos, il semble avoir un rapport avec la citadelle des Flammes infernales.|n|nPeut-être que cela pourrait intéresser Danath, le commandant de corps du bastion de l\'Honneur.', },
    {'Apportez le Moule à clé préparé au commandant de corps Danath au Bastion de l\'Honneur, dans la Péninsule des Flammes infernales.', },
  },
  [10755] = {
    'L\'entrée dans la citadelle',
    {'Ce moule fraîchement coulé devait servir à fabriquer une sorte de clé. D\'après l\'image gravée à son dos, il semble avoir un rapport avec la citadelle des Flammes infernales.|n|nPeut-être que cela pourrait intéresser Nazgrel, le chef des forces de la Horde à Thrallmar.', },
    {'Apportez le Moule à clé préparé à Nazgrel, à Thrallmar, dans la Péninsule des Flammes infernales.', },
  },
  [10756] = {
    'Le grand maître Rohok',
    {'Ce symbole sur l\'anneau de la clé... il est difficile à distinguer au fond du moule mais je le reconnais, c\'est bien celui de la Main brisée.|n|nIl y a de bonnes chances que cette clé vous permette d\'entrer dans les Salles brisées.|n|nAllez voir Rohok, notre forgeron. S\'il existe quelqu\'un capable de forger cette clé, c\'est lui.', },
    nil,
  },
  [10757] = {
    'La demande de Rohok',
    {'Les forgerons gangr\'orcs ne sont peut-être pas les plus talentueux du monde, mais leurs techniques de forge nécessitent quand même du métier. On ne peut utiliser que du gangrefer dans ce moule si nous voulons obtenir une clé utilisable - tout autre métal se briserait probablement.|n|nApportez-moi des barres de gangrefer, un peu de poussière arcanique et des granules de feu. Je vais essayer, mais je ne peux rien promettre.', },
    {'Apportez 4 Barres de gangrefer, 2 Poussières arcaniques et 4 Granules de feu à Rohok à Thrallmar dans la péninsule des Flammes infernales.', },
  },
  [10758] = {
    'Plus chaud que l\'enfer',
    {'Ça ne sert à rien, $N ! J\'ai beau ajouter du charbon dans le feu, ce n\'est pas assez chaud.|n|nJe ne connais qu\'une chose assez brûlante pour tremper cette clé, et c\'est l\'intérieur d\'un saccageur gangrené.|n|nJe n\'en ai jamais vu qu\'un se faire abattre. Je me souviens de ses entrailles fumantes qui crachaient du feu et de la vapeur lorsqu\'il est tombé. Prenez ce moule et plongez-le dans un saccageur gangrené abattu. Je vous conseille de vous faire assister par des amis si vous projetez d\'en détruire un.', },
    {'Détruisez un Saccageur gangrené dans la péninsule des Flammes infernales et plongez le Moule à clé inachevé dans ce qu\'il en reste. Apportez le Moule à clé carbonisé à Rohok à Thrallmar.', },
  },
  [10759] = {
    'Trouver le déserteur',
    {'J\'ai l\'impression que nous disposons de toutes les pièces, et pourtant je n\'arrive pas à les rassembler pour en faire une image révélatrice.|n|nJe pense que notre meilleure piste est d\'essayer de trouver ce déserteur. S\'il a laissé ses camarades au camp, il y a une chance que vous puissiez le persuader de nous aider à comprendre ce que mijotent les arakkoa du sombre Conclave.|n|nCommencez à le chercher le long de la route qui traverse les champs de magma au nord-ouest. Il me semble que c\'est un endroit où il a pu logiquement aller chercher un refuge.', },
    {'Trouvez Parshah dans les Champs de magma et parlez-lui.', },
  },
  [10760] = {
    'Les débris de Sketh\'lon',
    {'Les Débris sketh\'lon, juste à l\'est, sont un lieu étrange. Les péons sont convaincus qu\'il est maudit.|n|nIl y a peu d\'arbres ici, et les péons sont donc obligés de s\'aventurer dans les ruines arakkoa pour abattre du bois. Les esprits arakkoa attaquent les groupes de travailleurs, drainent leur vie et l\'utilisent pour alimenter leur détestable magie.|n|nNous devons découvrir quel est le moteur du sombre Conclave et l\'arrêter avant que son influence ne s\'étende. Fouillez les Débris sketh\'lon à la recherche d\'indices concernant leurs projets.', },
    {'Récupérez la Page 1 du journal du commandant de Sketh\'lon, la Page 2 du journal du commandant de Sketh\'lon et la Page 3 du journal du commandant de Sketh\'lon sur des arakkoa du sombre Conclave aux Débris sketh\'lon et apportez-les au sergent Kargrul au village d\'Ombrelune.', },
  },
  [10761] = {
    'Trouver le déserteur',
    {'Il n\'y a rien ici qui expliquerait pourquoi les esprits de ces arakkoa sont restés dans ce monde et pourquoi ils sont tellement assoiffés du sang des orcs.|n|nJe pense que notre meilleure piste est de trouver le déserteur mentionné dans le journal. S\'il a laissé ses camarades au camp, il y a une chance pour que vous puissiez le persuader de nous aider à comprendre ce que préparent les arakkoa du sombre Conclave.|n|nCommencez votre recherche sur la route, dans les Champs de magma, au sud-est.', },
    {'Trouvez Parshah dans les Champs de magma et parlez-lui.', },
  },
  [10762] = {
    'Le grand maître Dumphry',
    {'Ce symbole sur l\'anneau de la clé... il est difficile à distinguer au fond du moule mais je le reconnais, c\'est bien celui de la Main brisée.|n|nIl y a de bonnes chances que cette clé vous permette d\'entrer dans les Salles brisées.|n|nAllez voir Dumphry. C\'est un maître de son art. S\'il ne peut pas confectionner cette clé pour vous, personne ne le pourra.', },
    {'Apportez le Moule à clé préparé à Dumphry au bastion de l\'Honneur.', },
  },
  [10763] = {
    'La demande de Dumphry',
    {'Les gangr\'orcs sont peut-être des barbares complets, mais leurs techniques de forge ne sont pas aussi primitives qu\'on pourrait le croire. On ne peut utiliser que du gangrefer dans ce moule si nous voulons obtenir une clé utilisable - tout autre métal se briserait probablement.|n|nApportez-moi des barres de gangrefer, un peu de poussière arcanique et des granules de feu. Je vais essayer, mais je ne peux rien promettre.', },
    {'Apportez 4 Barres de gangrefer, 2 Poussières arcaniques et 4 Granules de feu à Dumphry au bastion de l\'Honneur dans la péninsule des Flammes infernales.', },
  },
  [10764] = {
    'Plus chaud que l\'enfer',
    {'Ça ne fonctionne pas, jeune $Ghomme:fille;. je ne peux pas le chauffer assez... les matériaux ne seront pas trempés correctement.|n|nVous savez, les saccageurs gangrenés qu\'utilise la Légion ardente sont alimentés par un noyau brûlant de gangrefeu - il brûle à une température bien plus élevée que le feu normal.|n|nSi vous pouviez réunir un groupe assez nombreux pour en abattre un, vous pourriez chauffer le moule à l\'intérieur d\'un saccageur gangrené. Faites attention, $C, ces saccageurs gangrenés tapent sacrément dur.', },
    {'Détruisez un Saccageur gangrené dans la péninsule des Flammes infernales et plongez le Moule à clé inachevé dans ce qu\'il en reste. Apportez le Moule à clé carbonisé à Dumphry au bastion de l\'Honneur.', },
  },
  [10765] = {
    'Le choc des mondes...',
    {'À l\'extrémité sud de la voie de la Conquête, près d\'une caravane stationnaire, j\'ai découvert ce qui ressemble fort à une rencontre entre un géant et un chancelier elfe de sang. Vous avez peut-être déjà remarqué les géants plus petits qui se trouvent aussi sur la route. Il y a quelque chose de louche qui se trame, grunt.|n|nJe veux que vous vous frayiez un chemin jusqu\'à cette rencontre, et que vous empêchiez que cette réunion parvienne à son terme. Récupérez ce que vous pourrez sur les lieux, puis appelez l\'un d\'entre nous avec le lance-fusée.', },
    nil,
  },
  [10766] = {
    'Le site d\'invasion Cataclysme',
    {'Maintenant que nous avons accès à la base de la Légion au site d\'invasion Cataclysme, nous devons imaginer un moyen de mettre fin à ses opérations. Le bastion des Marteaux-hardis ne sera pas en sécurité tant que les sbires de la Légion n\'auront pas été éliminés de la vallée d\'Ombrelune.|n|nJ\'ai envoyé un premier groupe d\'éclaireurs au site d\'invasion, pour vous aider à planifier la destruction des approvisionnements de la Légion. Retournez au bastion de la Légion et entrez dans le téléporteur surmonté de cristaux verts. Vous trouverez Plexi à votre point d\'arrivée.', },
    {'Présentez-vous à Plexi au Site d\'invasion Cataclysme.', },
  },
  [10767] = {
    'Le site d\'invasion Cataclysme',
    {'Maintenant que nous avons accès à la base de la Légion au site d\'invasion Cataclysme, nous devons imaginer un moyen de mettre fin à ses opérations. Le village d\'Ombrelune ne sera pas en sécurité tant que les sbires de la Légion n\'auront pas été éliminés de la vallée.|n|nJ\'ai envoyé un premier groupe d\'éclaireurs au site d\'invasion, pour vous aider à planifier la destruction des approvisionnements de la Légion. Retournez au bastion de la Légion et entrez dans le téléporteur surmonté de cristaux verts. Vous trouverez Nakansi à votre point d\'arrivée.', },
    {'Présentez-vous à Nakansi au Site d\'invasion Cataclysme.', },
  },
  [10768] = {
    'Les tabards des Illidari',
    {'Les coursiers du vent doivent rentrer au village d\'Ombrelune pour se préparer à la phase suivante de notre assaut. Ce qu\'il faudrait que vous me trouviez maintenant, ce sont les tabards que portent ces elfes de sang.|n|nQuand vous en aurez récupéré suffisamment, appelez un coursier du vent en utilisant le lance-fusée kor\'kron. Préparez-vous à faire un peu d\'espionnage, $R !', },
    nil,
  },
  [10769] = {
    'De la dissension dans les rangs...',
    {'Le chercheur Tiorus a été assez courtois pour préparer cette concoction pour l\'assaut final. Je vais simplement la verser sur le tabard que vous m\'avez fourni et l\'objet sera imprégné de l\'essence de cette vermine illidari.|n|nPrenez le tabard enchanté et rendez-vous aux Champs éclipsions, au sud-ouest de la Halte de l\'éclipse. Là-bas, utilisez le tabard pour vous transformer en agent d\'Illidan. Profitez alors de votre déguisement pour tuer les colosses affolés qui errent dans la région. Ils penseront qu\'il s\'agit d\'une attaque de l\'Eclipsion, et mettront fin à leur alliance !', },
    {'Tuez 5 Colosses affolés en portant le déguisement d\'un elfe de sang illidari, et retournez voir le suzerain Or\'barokh au village d\'Ombrelune dans la vallée d\'Ombrelune. Il voudra aussi que vous lui rendiez son Lance-fusée kor\'kron.', },
  },
  [10770] = {
    'Petites braises',
    {'Au nord-est d\'ici, sur le plateau au-dessus de nous, reposent les cendres calcinées de mon ancienne demeure. Un grand bois prospérait ici avant que la Légion ardente n\'envoie ses diablotins nous détruire par le feu. Il y a eu tant de morts que bien que des siècles se soient écoulés, mon vieux cœur fatigué crie toujours vengeance. Ils sont trop nombreux pour que nous reprenions jamais la terre, mais vous pourriez leur faire peur.|n|nVous accepteriez sûrement de m\'aider ?', },
    {'Boimoussu l\'Ancien veut que vous tuiez 8 Diablotins de brûlure avant de retourner le voir à la Sylve Ruuan.', },
  },
  [10771] = {
    'Tiré des cendres',
    {'Si vous suivez la route vers l\'est, montez par le côté de la montagne puis tournez vers le nord, vous arriverez dans le foyer que j\'ai perdu il y a bien longtemps.|n|nIl s\'y trouvait jadis un bois. Son nom a sombré dans l\'oubli. Dans un passé lointain, la Légion ardente a invoqué des diablotins de brûlure et d\'autres créatures des flammes. Ma patrie fut détruite et mon peuple dut fuir. À présent, il ne reste plus que moi.|n|nJ\'ai conservé des graines de racine-de-fer qui pourraient être semées dans de la terre volcanique fertile. Leur magie est puissante. Faites cela pour moi et je partagerai avec vous les trésors d\'un âge oublié.', },
    {'Boimoussu l\'Ancien veut que vous voyagiez jusqu\'à Skald pour y planter des Graines de racine-de-fer dans trois monticules différents de Terre volcanique fertile et que vous retourniez ensuite le voir dans la Sylve Ruuan.', },
  },
  [10772] = {
    'La voie de la Conquête',
    {'Mes chevaucheurs de griffons sont revenus avec quelques nouvelles ! Les elfes de sang de l\'Eclipsion sont en train de préparer un gros coup. Ils ont commencé à lever leur armée sur la voie de la conquête, à l\'est d\'ici, près de la halte de l\'éclipse.|n|nJe veux que vous alliez sur la voie de la conquête pour évaluer la situation. Une fois que ce sera fait, utilisez ce lance-fusée pour faire un signal aux chevaucheurs de griffons. L\'un d\'entre eux descendra à votre rencontre. Dites-lui ce que vous aurez découvert et il vous donnera vos prochaines instructions.', },
    nil,
  },
  [10773] = {
    'Ouvrir la voie',
    {'Nous allons avoir besoin de plus de temps, $R. Je vais voler un peu plus en avant, avec quelques chevaucheurs de griffons. Avec un peu de chance, nous pourrons rassembler de nouvelles informations. J\'ai besoin que vous m\'ouvriez la voie et, plus important encore, que vous vous débrouilliez pour qu\'aucune flèche ne soit pointée vers nous !|n|nAppelez un chevaucheur de griffon avec le lance-fusée marteau-hardi quand vous aurez diminué le nombre de nos adversaires.', },
    nil,
  },
  [10774] = {
    'Elfe de sang + Géant = ???',
    {'À l\'extrémité sud de la voie de la Conquête, près d\'une caravane à l\'arrêt, j\'ai surpris ce qui semble être une entrevue entre un géant et un chancelier elfe de sang. Qu\'est-ce que les géants fabriquent par ici ? Il y a quelque chose de louche là-dessous, grognard.|n|nJe veux que vous vous tailliez un chemin jusqu\'à ce point de rendez-vous et que vous vous mettiez fin à cette petite sauterie. Récupérez tout ce que vous pourrez sur place, puis appelez-nous avec le lance-fusée.', },
    nil,
  },
  [10775] = {
    'Les tabards des Illidari',
    nil,
    nil,
  },
  [10776] = {
    'De la dissension dans les rangs...',
    {'Gnomus a été assez courtois pour préparer cette concoction pour l\'assaut final. Je vais simplement la verser sur le tabard que vous m\'avez fourni et l\'objet sera imprégné de l\'essence de cette vermine illidari.|n|nPrenez le tabard enchanté et rendez-vous aux Champs éclipsions, au sud-ouest de la Halte de l\'éclipse. Là-bas, utilisez le tabard pour vous transformer en agent d\'Illidan. Profitez alors de votre déguisement pour tuer les colosses affolés qui errent dans la région. Ils penseront qu\'il s\'agit d\'une attaque de l\'Eclipsion, et mettront fin à leur alliance !', },
    {'Tuez 5 Colosses affolés en portant le déguisement d\'un agent d\'Illidan, et retournez voir le thane Yoregar au bastion des Marteaux-hardis dans la vallée d\'Ombrelune. Il voudra aussi que vous lui rendiez son Lance-fusée marteau-hardi.', },
  },
  [10777] = {
    'Le totem d\'Asghar',
    {'Ce que vous avez lu dans le journal du commandant est exact. Pendant que la Horde des orcs se regroupait sous le commandement de Gul\'dan, mon peuple voulut se défendre en lançant une attaque contre lui. Gul\'dan découvrit leurs intentions et lança un puissant sort qui détruisit nos camps et corrompit les esprits de mes frères.|n|nIl faut les arrêter avant qu\'ils ne libèrent un mal plus grand encore. Dans les Débris sketh\'lon au nord, trouvez Asghar et apportez-moi le totem qu\'il porte. Grâce à cet objet, nous pourrons commencer à contrecarrer les plans du sombre Conclave.', },
    {'Apportez le Totem de guerre de Sketh\'lon à Parshah dans les Champs de magma.', },
  },
  [10778] = {
    'Le bâtonnet de Lianthe',
    {'Le totem seul n\'est pas assez fort pour contrer la sinistre magie du sombre Conclave.|n|nNous pouvons l\'associer à d\'autres objets puissants pour former un bâton qui concentrera les énergies. Nous ne pouvons sauver mes frères des profondeurs de leur dépravation, mais nous pouvons les arrêter.|n|nL\'un des objets dont j\'aurai besoin pour ce bâton est le Bâtonnet de Lianthe, qui est entre les mains des elfes de sang de la Halte de l\'éclipse au sud-est. Il se trouve dans un pavillon sur le niveau supérieur des ruines et il sera lourdement gardé. Soyez $Gprudent:prudente;, $N.', },
    {'Procurez-vous la Clé de Lianthe sur un elfe de sang de la Halte de l\'éclipse, utilisez-la pour ouvrir le Coffre-fort de Lianthe et prenez-y le Bâtonnet de Lianthe. Apportez le bâtonnet à Parshah dans les Champs de magma.', },
  },
  [10779] = {
    'La voie du chasseur',
    {'Bonjour, jeune chasseur. Vous me semblez assez habile pour pouvoir vous occuper d\'une bête et l\'entraîner pour en faire votre compagnon. Allez voir la chasseresse Kella Arquenuit à QUELQUE PART. Elle vous mettra sur la bonne route pour que vous receviez votre propre familier.', },
    {'Parler à la chasseresse Kella Arquenuit QUELQUE PART.', },
  },
  [10780] = {
    'Les plumes de Sketh\'lon',
    {'Il ne manque plus qu\'un dernier élément pour terminer le bâton. Nous devons diriger sa puissance vers les esprits du sombre Conclave.|n|nNous y arriverons en rassemblant les plumes éparpillées sur le sol au camp Sketh\'lon, et en les incorporant au bâton. Le camp se trouve au sud, à l\'est du bastion des Marteaux-hardis.|n|nLa magie de Gul\'dan a totalement anéanti mes frères, n\'épargnant que leurs esprits, mais elle ne s\'est pas arrêtée là. Elle s\'est nourrie du sortilège que les arakkoa avaient préparé, pour forger une force sinistre qui a englouti les esprits.', },
    {'Rassemblez 8 Plumes de Sketh\'lon et apportez-les à Parshah dans les Champs de magma.', },
  },
  [10781] = {
    'La bataille du Guet cramoisi',
    {'Ils sont probablement en train de vous chercher sur la voie de la Conquête, à l\'heure où nous parlons. Vous devez vous enfuir, $R !|n|nLaissez-moi, j\'en ai fini… Ils… Je crois que je les entends arriver. C\'est maintenant ou jamais ! Partez ! Si vous préférez rester, il vous faudra combattre !|n|nSi vous combattez, et que d\'une façon ou d\'une autre vous parvenez à survivre, emportez ce que vous avez appris ici et livrez ces connaissances à A\'dal, à Shattrath.', },
    {'Combattez les forces d\'Illidan au Guet cramoisi et survivez !|n|nAllez voir A\'dal à Shattrath si vous avez réussi à vaincre.', },
  },
  [10782] = {
    'L\'imprégnation du bourdon',
    {'Le bâton est presque terminé !|n|nIl ne reste plus qu\'à imprégner le bourdon de la puissance qui émane des échos de Gul\'dan dans ce lieu maudit. À l\'est, près des Gangrefosses et au sud de la Forgemort, se trouve l\'Autel de la damnation.|n|nLà-bas, des fragments du passé de Gul\'dan sont piégés. Quand vous apporterez le bourdon inachevé du bâton près de l\'autel, ne vous étonnez pas si certaines des entités réagissent. Vous serez en train de porter un objet dangereux fortement lié au cataclysme.', },
    {'Voyagez jusqu\'à l\'Autel de la damnation et utilisez le Bourdon inachevé en vous tenant près de Gul\'dan. Quand le bourdon aura été imprégné d\'énergie, retournez voir Parshah dans les Champs de magma.', },
  },
  [10783] = {
    'Le baron Sablecrin',
    {'Voici mon plan. Nous allons empoisonner les ogres, puis détruire leur maître gronn.|n|nDurant mes voyages dans ces montagnes, j\'ai rencontré un homme nommé le baron Sablecrin. C\'est un maître des arts alchimiques, et vous pourrez peut-être le convaincre de nous aider.|n|nVous le trouverez au Cercle de sang, au bout du canyon qui se trouve au nord. Quel que soit le prix qu\'il demande, je vous laisse le choix de l\'accepter ou non.', },
    {'Parlez au Baron Sablecrin au Cercle de sang, dans les Tranchantes.', },
  },
  [10784] = {
    'Anéantir le camp Masse-sanglante',
    {'<Tor\'chunk s\'approche de vous pour pouvoir parler à voix basse.>|n|n$N, vous nous avez plus que fait honneur dans votre combat contre les ogres jusqu\'ici. Et tandis que j\'ai pleinement confiance en le plan que Rexxar a mis au point, j\'aimerais quand même vous demander d\'écraser les ogres du camp Masse-sanglante avant de partir.|n|nDe cette façon, nous serons doublement assurés de l\'issue du combat.|n|nPour y aller, descendez la rampe vers le nord en sortant de Sire-tonnerre. Ensuite, à la base de la rampe, traversez la Fin des dragons vers l\'ouest puis le Goulet bouillonnant et le canyon des Crocs-lames vers le nord.', },
    nil,
  },
  [10785] = {
    'C\'est un piège !',
    {'Il n\'y a pour moi source de fureur plus grande au monde que les fils de Gruul et leur père. Ils ont massacré mon peuple, mes enfants, et maintenant je veux connaître le goût de la vengeance !|n|nJ\'ai confectionné un piège à partir de feu de dragon, et si vous êtes assez $Gastucieux:astucieuse;, vous pourrez vous en servir pour tuer un gronn.|n|nApportez le piège à Rexxar sans tarder. Ma soif de vengeance doit être apaisée.', },
    {'Apportez le Piège de feu draconique à Rexxar au bastion des Sire-tonnerre dans les Tranchantes.', },
  },
  [10786] = {
    'Carnage à Roche\'mok',
    {'Je sais que Rexxar projette de vous envoyer à Roche\'mok. Il y a quelque chose que j\'aimerais que vous fassiez quand vous serez là-bas.|n|nNous devons profiter de toutes les occasions pour frapper les ogres de ces montagnes, ou ils nous envahiront et nous aurons versé notre sang et perdu des vies pour rien !|n|nRoche\'mok se trouve loin au nord-ouest. Partez vers le nord pour la sylve Ruuan, et depuis là-bas allez vers l\'ouest à travers le tunnel et au-delà du Bois aux corbeaux.|n|n$N, je veux que vous alliez tuer les ogres de Flèchelame à Roche\'mok. Massacrez-les !', },
    nil,
  },
  [10787] = {
    '<txt><nyi>Les dragons du Terme des dragons',
    nil,
    nil,
  },
  [10788] = {
    'Retourner voir Talionia',
    {'L\'une des démonistes qui vous forment, Talionia, de Lune-d\'Argent, vous réclame, $N. Il est sans doute temps pour vous d\'apprendre à invoquer et contrôler un démon plus puissant, je vous conseille donc d\'aller la voir immédiatement. Il me semble que Talionia se trouve au Sanctum, le petit nid douillet du maléfice, situé dans l\'Allée du meurtre.', },
    {'Parlez à Talionia à Lune-d\'Argent.', },
  },
  [10789] = {
    'Retourner voir Carendin Halgar',
    {'Ah, vous voilà donc, $N.|n|nCarendin Halgar a fait savoir qu\'il souhaitait que vous veniez le voir dans le quartier de la Magie de Fossoyeuse. La patience n\'est pas la plus grande de ses qualités, je ne tarderais pas à votre place.', },
    {'Parlez à Carendin Halgar à Fossoyeuse.', },
  },
  [10790] = {
    'Retourner voir Gan\'rul Œil-sanglant',
    {'Vous êtes bien loin de chez vous, $R. Il est sans doute temps que vous retourniez voir votre maître, Gan\'rul Œil-sanglant. Tous ceux qui suivent notre voie respectent son savoir, même ici.|n|nVous le trouverez dans la faille de l\'Ombre à Orgrimmar.', },
    {'Parler à Gan\'rul Oeil-sanglant à Orgrimmar.', },
  },
  [10791] = {
    'Accueillir l\'esprit du loup',
    {'J\'ai presque terminé les habits que je porterai durant la cérémonie. Pendant que je mets les touches finales, j\'aimerais que vous placiez cet encens près des bougies à côté de la pierre runique sur ma gauche.|n|nJe pense que cela nous aidera à attirer l\'attention de l\'esprit du loup, puisqu\'il date du temps des clans orcs. J\'imagine presque mes ancêtres utiliser cet encens lors d\'une cérémonie en hommage à l\'esprit du loup après une chasse réussie.|n|nUne fois que vous aurez mis l\'encens en place, je commencerai la cérémonie.', },
    {'Utilisez l\'Encens de cérémonie près des bougies dans la hutte de Malukaz et assistez à la cérémonie. Quand elle sera terminée, parlez à nouveau à Malukaz.', },
  },
  [10792] = {
    'Que Zeth\'Gor brûle !',
    {'Le clan de l\'Orbite-sanglante a trahi son noble héritage ! Nous autres, orcs, qui nous sommes battus et sommes morts pour nous délivrer de la souillure gangrenée de Mannoroth, nous observons nos ignobles cousins et nous ne voyons que faiblesse et abjection... et pour cela, ils doivent brûler !|n|nPénétrez dans Zeth\'Gor, leur bastion à l\'est, et brûlez leurs bâtiments. Tuez les péons pour leur prendre leurs torches, allumez-les au feu de leur forge, et lancez les torches enflammées sur leurs taudis, leur écurie et leur caserne. Brûlez-les tous avant de revenir me trouver !|n|nPour la Horde !', },
    {'Tuez les Péons de l\'Orbite sanglante pour prendre leurs torches, allumez celles-ci à la forge de Zeth\'Gor, puis jetez les torches enflammées sur les bâtiments de Zeth\'Gor.', },
  },
  [10793] = {
    'Le journal de Val\'zareq : Des présages de guerre',
    {'Ce journal contient le récit des activités récentes des armées d\'Illidan. Il explique aussi pourquoi Val\'zareq paradait autour de la voie de la Conquête. Ce dernier était personnellement responsable de la capture d\'un grand général des Sha\'tar.|n|nCe général est détenu à un poste appelé le Guet cramoisi, situé à l\'extrémité sud de la voie de la Conquête. Une faction mystérieuse, le Cachet cramoisi, est chargée de son incarcération. Si vous décidez d\'y mener une enquête, il serait plus sage d\'y aller avec quelques alliés.', },
    {'Trouvez Marcus Auralion, grand général des Sha\'tar, au Guet cramoisi.|n|nCherchez-le à l\'intérieur d\'une prison cristalline.', },
  },
  [10794] = {
    'Les voleurs de la Main brisée',
    {'$N, il existe dans ce monde des secrets que nous ne possédons pas encore. La Main brisée à Orgrimmar peut vous apprendre l\'un de ces secrets : leur méthode pour préparer des poisons mortels. Faites ce qu\'ils vous demandent et vous gagnerez leur confiance.|n|nPour vous rendre à Orgrimmar, prenez à Lune-d\'Argent le portail pour Fossoyeuse. Puis sortez de la ville et trouvez la tour proche où les zeppelins des gobelins prennent leurs passagers. À partir de là, volez jusqu\'à la ville d\'Orgrimmar, où vous trouverez Shenthul dans la Faille de l\'Ombre.', },
    {'Parlez à Shenthul à Orgrimmar.', },
  },
  [10795] = {
    'Un rendez-vous avec Dorgok',
    {'Bien, cela fait un moment que je vous vois et je voulais vous parler d\'une affaire de quelque importance.|n|nNous recevons des rapports disant que les ogres de la Masse-sanglante préparent une offensive contre Sylvanaar et la sylve Ruuan. Nous ignorons ce qui les pousse à agir ainsi, mais j\'ai bien l\'intention de tuer ce plan dans l\'œuf !|n|nC\'est du camp Masse-sanglante que devaient être lancées les attaques. Descendez la rampe vers le nord-ouest en sortant de la sylve Ruuan et vous le trouverez. Je veux que vous alliez tuer leur chef, Dorgok !', },
    nil,
  },
  [10796] = {
    'Anéantissez le camp Masse-sanglante !',
    {'J\'ai entendu que jusqu\'ici vous nous aviez plus que fait honneur dans vos combats contre les ogres. J\'aimerais maintenant que vous les affrontiez une fois encore. Je veux que vous écrasiez les ogres du camp Masse-sanglante !|n|nPour vous y rendre, descendez la rampe en direction du nord-ouest en sortant de la sylve Ruuan. Vous les trouverez en bas de la rampe.|n|nBonne chance, $C !', },
    nil,
  },
  [10797] = {
    'Une faveur des gronns',
    {'Un gage de la forme d\'une petite statuette tombe de la main sans vie de Dorgok. Elle ressemble de façon frappante à un gronn.|n|nVoilà qui intéresserait sûrement beaucoup le commandant Haephus Lamuraille au Bosquet éternel, en haut de la rampe à l\'est !', },
    {'Apportez la Faveur de Gorgrom au commandant Haephus Lamuraille au Bosquet éternel, dans les Tranchantes.', },
  },
  [10798] = {
    'Rendre visite au baron',
    {'Voilà une mauvaise nouvelle. Gorgrom le Mange-dragon se cache derrière les récents plans des Masse-sanglante contre Sylvanaar.|n|nPourquoi les manipuler, au lieu de simplement utiliser les Flèchelame, je l\'ignore. Mais si nous devons nous occuper d\'un gronn, nous allons avoir besoin d\'aide.|n|nJe connais un homme versé dans toutes sortes de magies exotiques. Il s\'agit du baron Sablecrin, vous le trouverez au Cercle de sang si vous descendez la rampe vers le nord-ouest puis traversez le canyon vers le sud-ouest.|n|nDemandez-lui de nous faire un piège pour le gronn.', },
    nil,
  },
  [10799] = {
    'Dans le Goulet bouillonnant',
    {'Très bien, je fabriquerai ce piège, mais je veux d\'abord quelque chose en échange.|n|nIl se trouve qu\'un gronn des environs possède un objet que je désire, mais vous ne pouvez pas l\'affronter, du moins pas encore.|n|nVous et moi allons donc préparer une poudre somnifère à partir du poison des perceurs de croûte de la région.|n|nVous les trouverez dans le goulet bouillonnant au sud-ouest. Apportez-moi un certain nombre de leurs glandes, et vite !', },
    nil,
  },
  [10800] = {
    'Bonne nuit, l\'horrible !',
    {'Je me suis encore surpassé. J\'ai préparé une poudre somnifère que vous pourrez utiliser sur Grulloc, le gronn dont je vous ai parlé qui garde ce que je veux.|n|nGrulloc demeure au Creux maudit, une zone à l\'extrémité est de la Fin des dragons de l\'autre côté du Cercle de sang.|n|nÀ votre place, je ne tarderais pas une fois que j\'aurais pris son sac. Les effets de la poudre ne dureront pas longtemps.', },
    nil,
  },
  [10801] = {
    'C\'est un piège !',
    {'Il n\'y a rien que je déteste plus au monde que les fils de Gruul et leur père ! Ils ont massacré mon peuple et mes enfants, et maintenant je veux connaître le goût de la vengeance !|n|nJ\'ai confectionné un piège à partir de feu de dragon, et si vous êtes assez $Gastucieux:astucieuse;, vous pourrez vous en servir pour tuer un gronn.|n|nJe suis sûr que vous pensez à un gronn en particulier ; peu m\'importe lequel vous tuerez, cela m\'est égal. Mais apportez le piège sans tarder à votre commandant Lamuraille.|n|nMa soif de vengeance doit être apaisée !', },
    {'Apportez le Piège de feu draconique au commandant Haephus Lamuraille au Bosquet éternel dans les Tranchantes.', },
  },
  [10802] = {
    'Gorgrom le Mange-dragon',
    {'Nous devons montrer aux ogres qu\'il ne faut pas nous traiter à la légère. Nous devons leur envoyer un message.|n|nVoyagez jusqu\'à Roche\'mok et tuez les ogres là-bas. Gardez bien leurs têtes.|n|nAllez ensuite à l\'autel de Gorgrom et placez-y le piège pour lui. Gorgrom apparaîtra, et vous devrez l\'attirer dans le piège. Quand il sera mort, placez vos totems macabres près de son cadavre, de sorte que les ogres puissent voir leur maître et leurs frères tombés, et connaissent le prix à payer par ceux qui cherchent à nous détruire.', },
    nil,
  },
  [10803] = {
    'Carnage à Roche\'mok',
    {'Je sais que nos plans prévoient que vous alliez à Roche\'mok. Il y a quelque chose que j\'aimerais que vous fassiez lorsque vous serez là-bas.|n|nNous devons saisir la moindre chance de frapper les ogres de ces montagnes, sinon ils nous submergeront, et nous aurons souffert et serons morts pour rien !|n|nRoche\'mok se trouve à l\'ouest. Voyagez vers le sud-ouest, traversez le pont et traversez le tunnel. Vous les trouverez sur le côté ouest du bois aux Corbeaux.|n|n$N, je veux que vous éliminiez les ogres de Flèchelame à Roche\'mok.', },
    nil,
  },
  [10804] = {
    'Un peu de gentillesse',
    {'Quelque chose les a effrayés, $R.|n|n<Mordenai désigne les drakes du Néant qui volent au-dessus de vous.>|n|nIls ne descendent même plus pour se nourrir. J\'en ai vu plusieurs tomber du ciel, morts d\'épuisement avant même que leur corps ne touche le sol.|n|nNous devons les sauver ! Les écorcheurs ongleroc que l\'on trouve près des cristaux sont leur proie naturelle. Tuez des écorcheurs et prenez leurs carcasses. Placez-en une dans le champ et restez complètement immobile. Tant que vous ne ferez pas de geste agressif, ils ne vous attaqueront pas.', },
    {'Mordenai, aux champs de l\'Aile-du-Néant, dans la vallée d\'Ombrelune, veut que vous nourrissiez 8 Drakes Aile-du-Néant adultes.', },
  },
  [10805] = {
    'Massacre au repaire de Gruul',
    {'Vous avez montré que vous étiez $Gplein:pleine; de ressources, et je pense que je vais vous employer à mes fins personnelles dans mon combat contre Gruul et ses fils.|n|nLe clan Flèchelame est le favori des gronns, et même si vous avez réduit leur nombre en d\'autres lieux, vous n\'avez pas encore affronté les plus forts d\'entre eux.|n|nGruul protège les abords de sa tanière avec les ogres les plus robustes, et ce sont eux que vous devez tuer. Dirigez-vous au nord en passant par le canyon des Crocs-lames, et vous trouverez au bout le repaire de Gruul.', },
    nil,
  },
  [10806] = {
    'Cartes sur table',
    {'Le moment est venu d\'affronter Goc, le maître des ogres du clan Flèchelame. Le moment est aussi venu pour moi de mettre la main à la pâte, pour voir la destruction des derniers gronns.|n|nPrenez ma chevalière. Quand vous serez $Gparvenu:parvenue; à l\'Autel de Goc, utilisez-la et je viendrai vous rejoindre.|n|nEnsemble, nous détruirons Goc.', },
    nil,
  },
  [10807] = {
    'Les roués cendrelangues',
    {'La tribu cendrelangue est crainte de tous les roués. Elle est constituée des individus les plus vicieux et les plus sanguinaires, triés sur le volet par Akama en personne. Ils sont aussi sauvages et dépourvus de pitié que n\'importe quel naga, démon ou elfe de sang de l\'armée d\'Illidan et ils ont été déployés en grand nombre aux ruines de Baa\'ri, au nord. Allez là-bas et réduisez leur nombre avant qu\'ils aient l\'occasion de lancer une attaque contre nous.', },
    {'Varen le Récupérateur veut que vous partiez pour les Ruines de Baa\'ri afin d\'y tuer 3 Dresseurs cendrelangues, 4 Guerriers cendrelangues et 6 Chamans cendrelangues.|n|nAccomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l\'Aldor.', },
  },
  [10808] = {
    'Contrecarrer le sombre Conclave',
    {'Les esprits du sombre Conclave essaient d\'invoquer une ancienne et puissante entité maléfique grâce à un rituel célébré aux puits de lave situés au sud du campement Sketh\'lon.|n|nLa magie de Gul\'dan s\'est mêlée à la leur, leur donnant le pouvoir nécessaire pour aider cette créature à se manifester dans notre monde ! Nous ne devons pas les laisser faire, $N. La mort et la destruction qu\'elle provoquerait sont inimaginables !|n|nEmportez le bâton jusqu\'au lieu de l\'invocation et utilisez sa magie pour arrêter le sombre Conclave une bonne fois pour toutes.', },
    {'Tuez les Ritualistes du sombre Conclave et utilisez le Bâton de Parshah pour mettre fin à leur rituel d\'invocation. Retournez ensuite voir Parshah dans les Champs de magma.', },
  },
  [10809] = {
    'On recherche : maître-worg Kruush',
    {'L\'affiche indique :|n|n« Le maître-worg Kruush mène les chevaucheurs de worg du clan de l\'Orbite-sanglante. Sa tête est mise à prix, car ses chevaucheurs lèvent un lourd tribut sur les convois de ravitaillement vers le poste de Brise-échine.|n|nLes éclaireurs ont signalé sa présence à Zeth\'Gor, et le héros qui sera capable de me rapporter la tête de ce scélérat recevra les remerciements de la Horde, ainsi qu\'une ample récompense.|n|n-Capitaine Rugissombre »', },
    {'Tuez le Maître-worg Kruush et apportez sa tête au Capitaine Rugissombre dans le Poste de Brise-échine.', },
  },
  [10810] = {
    'Le masque endommagé',
    {'En examinant le masque endommagé, vous entendez des sons étranges venant de l\'intérieur. Si le masque n\'était pas endommagé, on entendrait peut-être ces sons plus distinctement.|n|nO\'Mally Rossecoquin de la sylve Ruuan pourra peut-être vous aider à le réparer.', },
    nil,
  },
  [10811] = {
    'Trouvez Neltharaku',
    {'Leur protecteur sillonne les airs là-haut, $N. La gentillesse dont vous avez fait preuve à l\'égard de ses enfants aura peut-être ému son cœur. Allez chercher Neltharaku et obtenez son aide. Ensemble, nous parviendrons éventuellement à résoudre le problème des drakes de l\'Aile-du-Néant.|n|n<Mordenai pointe vers le ciel.>|n|nEnvolez-vous, mon $Gami:amie;...', },
    {'Partez à la recherche de Neltharaku, le protecteur du Vol de l\'Aile-du-Néant.', },
  },
  [10812] = {
    'Le masque mystère',
    {'OK, ça devrait marcher maintenant. Vous voulez savoir ce que c\'est ? Eh bien, c\'est un système de communication - il permet à ces crétins de communiquer entre eux. Vous savez bien, la Légion ardente ! Je vous conseille de donner ce masque au seigneur sauvage Antelarion. Il est là-bas, à faire les cent pas. Toujours en mouvement.|n|nNe traînez pas, ça fait longtemps qu\'il essaye de mettre la main sur un de ces appareils.', },
    nil,
  },
  [10813] = {
    'Les yeux de Grillok',
    {'$N, vous avez bravé le repaire des orcs de l\'Orbite-sanglante, la redoutée Zeth\'Gor, et vous avez survécu ! Vous aurez peut-être la force de m\'aider, car je cherche à plonger dans l\'esprit de son plus noir sorcier, Grillok !|n|nPrenez cet éclat. Utilisez-le pour ensorceler un œil de Grillok et le lier à vous. Ensuite revenez ici et approchez-vous de mon chaudron... il saura vous extraire l\'œil.|n|nAllez-y, $N, mais restez sur vos gardes. Un œil de Grillok vous trahira à nos ennemis si vous lui laissez la moindre occasion.', },
    {'Utilisez l\'Éclat de Zezzak pour capturer un Oeil de Grillok, puis approchez-vous du Chaudron de Zezzak pour l\'extraire. Une fois que ce sera fait, rendez son éclat à Zezzak.', },
  },
  [10814] = {
    'L\'histoire de Neltharaku',
    {'J\'ai des informations que vous trouverez certainement utiles. Je vous prie d\'écouter tout ce que j\'ai à vous dire, $R.', },
    {'Parlez à Neltharaku et écoutez son histoire.', },
  },
  [10815] = {
    'Le journal de Val\'zareq : Des présages de guerre',
    {'Ce journal contient le récit des activités récentes des armées d\'Illidan. Il explique aussi pourquoi Val\'zareq paradait autour de la voie de la Conquête. Ce dernier était personnellement responsable de la capture d\'un grand général des Sha\'tar.|n|nCe général est détenu à un poste appelé le Guet cramoisi, situé à l\'extrémité sud de la voie de la Conquête. Une faction mystérieuse, le Cachet cramoisi, est chargée de son incarcération. Si vous décidez d\'y mener une enquête, il serait plus sage d\'y aller avec quelques alliés.', },
    {'Trouvez Marcus Auralion, grand général des Sha\'tar, au Guet cramoisi.|n|nCherchez-le à l\'intérieur d\'une prison cristalline.', },
  },
  [10816] = {
    'La reconquête des terres sacrées',
    {'Vous vous êtes très bien $Gdébrouillé:débrouillée; contre les roués de Baa\'ri, $N. Voyons ce que vous valez contre l\'armée la plus crainte d\'Illidan.|n|nLes gangr\'orcs du clan d\'Ombrelune occupent la terrasse Ata\'mal, qui était autrefois un site sacré où les cristaux d\'Ata\'mal étaient utilisés dans des cérémonies spirituelles.|n|nNous avons des raisons de penser qu\'ils cachent un véritable cristal d\'Ata\'mal dans le voisinage, mais nos divinations n\'ont rien révélé. Néanmoins, les gangr\'orcs sont sur une terre sacrée draeneï et leur présence ne saurait être tolérée.', },
    {'Le redresseur de torts Aluumen veut que vous tuiez 8 Pourfendeurs ombrelunes, 8 Élus ombrelunes et 4 Tisseurs d\'ombre ombrelunes.|n|nAccomplir des quêtes pour l\'Aldor fera baisser votre réputation auprès des Clairvoyants.', },
  },
  [10817] = {
    'La grande vindicte',
    {'Vous vous êtes très bien $Gdébrouillé:débrouillée; contre les roués cendrelangues, $N. J\'ai un autre défi à vous proposer, si vous vous sentez à la hauteur.|n|nIl n\'y a pas si longtemps, le Sanctum des Étoiles a subi une terrible attaque des gangr\'orcs d\'Illidan.|n|nNous avons réussi à apprendre qu\'elle avait été lancée par les orcs ombrelunes qui occupent la terrasse Ata\'mal.|n|nMontrez-leur qu\'il ne faut pas prendre les Clairvoyants à la légère.', },
    {'Varen le Récupérateur veut que vous tuiez 8 Pourfendeurs ombrelunes, 8 Élus ombrelunes et 4 Tisseurs d\'ombre ombrelunes.|n|nAccomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de l\'Aldor.', },
  },
  [10818] = {
    'Le baron Sablecrin veut vous voir',
    {'$N, pendant que vous étiez $Gparti:partie; faire votre excellent travail de $C, le baron Sablecrin nous a envoyé son dragon favori avec un message.|n|nIl vous a demandé personnellement. D\'après ce que j\'ai compris, il désire que vous dirigiez son propre combat contre les gronns.|n|nJe suppose que vous êtes la personne la plus qualifiée en Outreterre pour l\'aider, mais si j\'étais vous, je contacterai d\'abord quelques amis et je leur demanderai de me rejoindre au Cercle de sang.', },
    nil,
  },
  [10819] = {
    'Le masque à gaz de gangrelige',
    {'J\'ai une mission très spéciale pour vous, $N. Je veux que vous infiltriez le camp de forge : Colère à l\'est d\'ici. Quand vous entrerez dans le camp, il faudra que vous portiez le masque à gaz de gangrelige, et vous devrez trouver le communicateur de la Légion. Une fois que vous aurez repéré le système de communication, parlez avec la personne qui sera au bout du fil, qui qu\'elle soit.|n|nSi tout fonctionne comme prévu, vous pourrez jouer un tour à ce démon ! Essayez de le convaincre que le camp Colère est en état d\'insurrection.|n|nBonne chance, $C.', },
    nil,
  },
  [10820] = {
    'Ton ennemi tu tromperas',
    {'Chaque seconde de silence vous rapproche de votre mort ! PARLEZ !|n|nQuoi ? Le camp s\'est révolté ? Ce n\'est pas possible ! Mes serviteurs n\'oseraient pas contester mon autorité.|n|nEh bien dans ce cas, ils paieront jusqu\'au dernier leur traîtrise, et chèrement. Réduisez-les tous au silence et finissez-en ! Faites-moi votre rapport lorsque vous aurez rempli mes ordres, ou je m\'occuperai de vous.', },
    nil,
  },
  [10821] = {
    'Vous êtes virée !',
    {'Vocifuneste n\'a rien fait pour arrêter la révolte ? Comment a-t-elle pu oser ! Cela fait quelque temps qu\'elle essaye de saper mon autorité. Mais cette fois sera la dernière. Invoquez-la et occupez-vous d\'elle personnellement.|n|nSes gardes de colère détiennent les clés qui permettent de l\'invoquer au camp de forge : Colère. Récupérez les cinq clés et activez les cinq obélisques de la Légion. Les obélisques n\'ont qu\'une durée limitée, faites donc en sorte qu\'elles soient toutes activées au même moment. N\'oubliez pas que les gardes de colère détiennent des clés en surnombre.', },
    nil,
  },
  [10822] = {
    'Une chevalière Solfurie',
    nil,
    nil,
  },
  [10823] = {
    'De nouvelles chevalières Solfurie',
    nil,
    nil,
  },
  [10824] = {
    'Les chevalières Solfurie',
    {'La survie des Clairvoyants repose sur un seul point crucial : ils doivent recruter plus que Kael\'thas. Tous les pèlerins de Quel\'Thalas qui rejoignent les rangs de ce dernier le rapprochent de la victoire. Le contraire est aussi vrai pour nous.|n|nNous allons bientôt manquer de recrues et nous allons arriver au point où ce sera le camp qui tuera le plus rapidement son adversaire qui gagnera. Prouvez votre valeur aux Clairvoyants en m\'apportant les chevalières Solfurie portées par les elfes de sang de haut rang qui travaillent pour Kael\'thas. Vous les trouverez à la halte de l\'Éclipse à l\'ouest, et dans les ruines de Karabor au nord-est.', },
    {'La Mage de bataille Vyara du Sanctum des Étoiles veut que vous lui apportiez 10 Chevalières Solfurie.|n|nAccomplir des quêtes pour les Clairvoyants fera baisser votre réputation auprès de la faction Aldor.', },
  },
  [10825] = {
    'La vérité toute nue',
    {'Un étrange orbe magique tombe des plumes de l\'arakkoa.|n|nBaignant dans une lueur violette sinistre, l\'orbe est animé d\'une pulsation silencieuse. Vous vous sentez mal à l\'aise en le tenant et vous vous hâtez de le ranger dans votre sac.|n|nPeut-être que le gardien des arbres Chawn de la sylve Ruuan, qui se trouve à l\'ouest, de l\'autre côté du pont Crâne-du-ver après avoir traversé le tunnel, souhaiterait l\'examiner ?', },
    nil,
  },
  [10826] = {
    'Les marques de Sargeras',
    {'Vous devez maintenant avoir une bonne idée de ce qui nous pousse à lutter contre la Légion et tous ceux qui les servent.|n|nSi vous voulez faire vos preuves auprès de l\'Aldor, rapportez-moi les insignes qu\'utilisent les agents hauts gradés de la Légion et leurs fidèles du Conseil des ombres. Dans la vallée d\'Ombrelune, vous trouverez une forte présence de la Légion loin à l\'ouest, au bastion de la Légion et à la Forgemort.', },
    {'Remettez 10 Marques de Sargeras au Messager Saronen, dans la Vallée d\'Ombrelune.|n|nAccomplir des quêtes pour l\'Aldor fera baisser votre réputation auprès des Clairvoyants.', },
  },
  [10827] = {
    'De nouvelles marques de Sargeras',
    nil,
    nil,
  },
  [10828] = {
    'Une marque de Sargeras',
    nil,
    nil,
  },
  [10829] = {
    'Arbrobole doit savoir',
    {'Comme c\'est troublant ! Les arakkoa sont responsables de la possession des anciens et des protecteurs par des esprits maléfiques !|n|nIl y a cependant un ancien qui n\'a certainement pas pu être affecté. Il se nomme Arbrobole, et vous devez immédiatement aller le voir si nous voulons sauver les arbres du Bois aux corbeaux !|n|nRetournez au Bois aux corbeaux. Vous le trouverez à l\'embranchement juste après Grishnath.', },
    nil,
  },
  [10830] = {
    'Exorciser les arbres',
    {'Les Grishna sont responsables de la possession des barbes-feuillues et des écorcepierres par des esprits kui-kui maléfiques.|n|nNous devons sauver les arbres, ou bientôt le Bois aux corbeaux sera perdu pour toujours !|n|nAssociez la magie d\'un orbe grishnath, qu\'on trouve partout à Grishnath, avec une plumule redoutable d\'un corbeau redoutable.|n|nUtilisez la plume d\'exorcisme que vous obtiendrez pour faire sortir l\'esprit kui-kui et le tuer aussi vite que possible. Les écorcepierres sont trop puissants pour ce rituel, mais si suffisamment de barbes-feuillues sont sauvés, eux aussi seront libérés.', },
    nil,
  },
  [10831] = {
    'Devenir un tailleur d\'étoffe lunaire',
    {'Je peux vous enseigner l\'art de la couture de l\'étoffe lunaire, si cela vous intéresse. Si vous vous spécialisez dans ce domaine, vous pourrez créer deux fois plus d\'étoffe lunaire primordiale et plusieurs patrons exclusifs vous seront disponibles. Pour cela, il suffit que vous passiez une épreuve simple.|n|nVotre tâche sera de créer un petit échantillon d\'étoffe lunaire primordiale au puits de lune du Refuge cénarien. Je vous fournirai tous les matériaux nécessaires. Quand vous aurez créé l\'échantillon, apportez-le-moi, que je puisse l\'examiner.', },
    {'Utilisez le Carré de tisse-néant imprégné en vous tenant près du puits de lune du Refuge cénarien pour créer un Échantillon d\'étoffe lunaire primordiale. Apportez l\'échantillon terminé à Nasmara Lunechant dans la Ville basse de Shattrath.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en couture.', },
  },
  [10832] = {
    'Devenir un tailleur de feu-sorcier',
    {'Je peux vous apprendre l\'art du tailleur du feu-sorcier si vous le souhaitez, mais soyez $Gprévenu:prévenue;, il s\'agit d\'une voie dangereuse.|n|nLa création de tisse-sort à Raz-de-Néant attire de puissantes âmes en peine du Néant. Je recherche un moyen de diminuer ces répercussions, mais il me faudra plus d\'essence d\'âme en peine du Néant pour mes travaux.|n|nEmportez cette balise à Raz-de-Néant et utilisez-la pour invoquer une âme en peine du Néant. Rapportez-moi son essence et j\'accepterai de vous former. En tant que tailleur de feu-sorcier, vous recevrez deux fois plus d\'étoffe et vous aurez accès à des patrons exclusifs.', },
    {'Apportez un échantillon d\'Essence d\'âme en peine du Néant à Gidge Tisse-sort dans la Ville basse de Shattrath.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en couture.', },
  },
  [10833] = {
    'Devenir un tailleur de tisse-ombre',
    {'Si vous devenez un spécialiste du tisse-ombre, vous produirez deux fois plus d\'étoffe d\'ombre qu\'un tailleur normal et plusieurs patrons exclusifs vous seront disponibles.|n|nBien sûr, n\'importe quel tailleur peut utiliser l\'autel des Ombres, mais l\'harmonisation d\'un tailleur de tisse-ombre avec l\'autel est plus profonde, lui donnant accès à des pouvoirs que peu sont en mesure de comprendre.|n|nEmportez ce cristal dans l\'est de la vallée d\'Ombrelune, et trouvez le défilé de l\'Aile-du-Néant qui conduit vers le sud depuis les champs de l\'Aile-du-Néant. Près de l\'extrémité de ce monde, vous verrez l\'autel des Ombres. Utilisez le cristal là-bas.', },
    {'Utilisez le Cristal des ombres profondes près de l\'autel des Ombres pour renforcer votre harmonisation avec l\'autel, puis retournez voir Andrion Sombrefileur dans la Ville basse de Shattrath.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en couture.', },
  },
  [10834] = {
    'Grillok « Sombrœil »',
    {'Grillok Sombrœil a misé une part de lui-même auprès des forces des ténèbres, et il a gagné en retour une grande magie. Son œil perdu, devenu le bijou d\'un démon, brûle au plus profond d\'un puits infernal... et le bandeau qui couvre cette trahison contient son propre secret ténébreux.|n|nApportez-moi le couvre-œil de Grillok, $N, et je vous récompenserai grandement pour votre service...', },
    {'Tuez Grillok Sombrœil et rapportez le Couvre-œil de Grillok à Zezzak au Poste de Brise-échine.', },
  },
  [10835] = {
    'L\'apothicaire Antonivitch',
    {'$N, j\'ai préparé un rapport préliminaire de mes découvertes en ce qui concerne les orcs de l\'Orbite-sanglante. Mon collègue de Thrallmar, l\'apothicaire Antonivitch, sera heureux d\'en prendre connaissance. Lui aussi étudie la phénoménologie des gangr\'orcs... dans l\'espoir d\'éviter qu\'une telle tragédie ne puisse se reproduire sur nos alliés orcs, bien entendu.|n|nApportez-lui ce rapport, et je vais poursuivre mes études avec le sang que vous m\'avez apporté. Si la fortune nous sourit, nous parviendrons à isoler la cause du malheur des gangr\'orcs.', },
    nil,
  },
  [10836] = {
    'Infiltrer la forteresse Gueule-de-dragon',
    {'Il me faut du temps pour établir un plan qui permette de sauver mes enfants et ma compagne. Vous m\'obtiendrez ce répit, $Gmortel:mortelle;.|n|nEnfoncez-vous dans la forteresse Gueule-de-dragon, située sur la bordure est des champs de l\'Aile-du-Néant, et massacrez tous les orcs Gueule-de-dragon que vous y trouverez. Le chaos et la confusion que vous déclencherez devraient avoir un retentissement important sur leurs projets.|n|nFaites attention, certains des miens sont hors d\'atteinte, leurs esprits trop corrompus par les Gueules-de-dragon. Pour eux, il ne reste que la mort. Vous avez mon autorisation de mettre fin à leur existence si nécessaire.', },
    {'Neltharaku, qui vole au-dessus des Champs de l\'Aile-du-Néant dans la Vallée d\'Ombrelune, veut que vous tuiez 15 Orcs Gueule-de-dragon.|n|nN\'importe quels orcs de la Forteresse Gueule-de-dragon feront l\'affaire.', },
  },
  [10837] = {
    'Vers l\'escarpement de l\'Aile-du-Néant !',
    {'Je pense que je peux imprégner des cristaux vignéants de ma propre essence. La puissance contenue dans ces cristaux imprégnés devrait être suffisante pour libérer les drakes réduits en esclavage.|n|nRendez-vous à l\'escarpement de l\'Aile-du-Néant, une île située non loin des saillies brisées de la vallée d\'Ombrelune, au sud-est. C\'est là que vous trouverez des cristaux vignéants. Revenez me voir quand vous aurez ramassé assez de cristaux pour remplir vos sacs.|n|nEt $N, prenez garde aux Gueules-de-dragon qui habitent désormais dans cette île.', },
    {'Neltharaku, qui vole au-dessus des champs de l\'Aile-du-Néant dans la vallée d\'Ombrelune, veut que vous ramassiez 12 cristaux vignéants à l\'escarpement de l\'Aile-du-Néant.', },
  },
  [10838] = {
    'Le scrutateur démonien',
    {'Le scrutateur démonien est maintenant prêt. Emportez-le derrière la citadelle, au bassin des Flammes infernales, et placez-le au sol. Il commencera alors à s\'harmoniser avec la citadelle des Flammes infernales. Une fois ceci fait, parlez au scrutateur et retranscrivez ce qu\'il vous dira. Apportez-moi ensuite cette transcription...|n|nAllez-y, $N, mais seulement quand vous serez $Gprêt:prête; pour l\'action. Nul doute que la citadelle détectera le scrutateur et enverra des gardiens pour le détruire !', },
    {'Utilisez le Scrutateur démonien dans le Bassin des Flammes infernales, attendez qu\'il soit harmonisé, puis faites un relevé.|n|nRapportez le Scrutateur démonien et le Relevé du scrutateur démonien à l\'Apothicaire Antonivitch à Thrallmar.', },
  },
  [10839] = {
    'Voile Skith : Sombrepierre de Terokk',
    {'Le Voile Skith se trouve au nord-ouest de la caravane et au sud de Shattrath dans un bosquet retiré de la forêt. Une rumeur dit que la colonie de Skettis a construit un autel où elle rend un culte sacrilège. Cette Sombrepierre de Terokk doit être purifiée si nous voulons qu\'un jour les arakkoa de Skith puissent être sauvés.|n|nPrenez ce bâtonnet de purification et jetez-le sur la Pierre. Il a été béni par A\'dal et sa pureté suffira peut-être à rendre la clarté à la Sombrepierre. Partez maintenant, et que la lumière vous éclaire.', },
    nil,
  },
  [10840] = {
    'Le tombeau des lumières',
    {'À l\'est, enfoui sous le sable carbonisé, se trouve le Tombeau des lumières, un lieu de repos perdu pour les morts. Avant que notre caravane ne subisse une embuscade, j\'étais en route vers le tombeau pour le purifier des esprits maléfiques.|n|nJ\'étais loin de penser qu\'il était déjà infesté par un autre type de mal. Encore maintenant, les éthériens pillent les corps à la recherche de babioles et de souvenirs offerts aux morts il y a des siècles.|n|nJe ne peux pas faire grand-chose tant que la caravane lutte pour sa survie.', },
    nil,
  },
  [10841] = {
    'Le messager vengeur',
    {'[PH] Allez au tombeau des lumières et activez le bidule.', },
    {'[PH] Activer le bidule.', },
  },
  [10842] = {
    'Âmes vengeresses',
    {'Le Tombeau des lumières a été corrompu par le Conseil des ombres et les morts draeneï sont devenus des esprits maudits, déboussolés et consumés par leur haine des vivants.|n|nAllez dans le tombeau à la recherche de ces malheureuses victimes. Donnez-leur le repos qu\'elles méritent.', },
    {'Le grand prêtre Orglum veut que vous vous rendiez au Tombeau des lumières et que vous vainquiez 5 Draeneï vengeurs.', },
  },
  [10843] = {
    'Depuis des temps immémoriaux…',
    {'Depuis des temps immémoriaux, nous combattons les ogres de Flèchelame.|n|nNous avons réussi à les repousser de sorte que leur position à l\'avant-poste Flèchelame est devenue précaire. Pour le trouver, repartez par où vous êtes $Gvenu:venue;, il est sur le bord sud-ouest de la Tranchecrête.|n|nProuvez-moi votre valeur en tuant leur chef, Gnosh Brognat.|n|nNous verrons de quel bois vous êtes $Gfait:faite; quand vous combattrez les ogres.', },
    nil,
  },
  [10844] = {
    'Le camp de forge : Colère',
    nil,
    nil,
  },
  [10845] = {
    'Tuer la mère des couvées',
    {'Mes chasseurs viennent de rentrer d\'une mission d\'observation à la Crête chantante. Il semble que le nombre des drakes du Néant, qui y infestent les cristaux, se soit grandement accru, et qu\'ils menacent de nous envahir.|n|nPuisque vous avez prouvé que vous étiez $Gun tueur compétent:une tueuse compétente;, voyons si vos talents de $C égalent ceux d\'un drake adulte.|n|nVous trouverez la Crête chantante en traversant la Saillie ailécaille vers le sud. Entrez et tuez la mère des couvées, Aile-de-peur.', },
    nil,
  },
  [10846] = {
    'Comprendre les Mok\'Nathal',
    {'<Leoroxx vous regarde dans les yeux avec une expression qui vous glace l\'âme.>|n|nVous êtes $Gvenu:venue; chez les Mok\'Nathal, mais vous ne nous comprenez pas. Vous ne comprenez pas notre lutte pour la survie.|n|nPour nous comprendre, vous devrez faire l\'expérience de cette lutte.|n|nAu sud demeurent les arakkoa vekh\'nir. Ils ont asservi un groupe d\'ogres dans les cavernes appelées la prétention de Trogma et c\'est là que se trouve Vekh, leur chef.|n|nTuez-le !', },
    nil,
  },
  [10847] = {
    'Les yeux de Skettis',
    {'Le malheur nous attend sur les falaises de Skettis.|n|nUn destin voilé par un mal indicible se prépare pour mon peuple, les arakkoa. Trop souvent nous avons abusé de la magie noire pour faire le mal. Grâce à A\'dal, j\'ai appris ce que signifiaient la Lumière et la rédemption.|n|nTerokk surveille ses colonies depuis Skettis par le moyen d\'orbes ayant subi de sombres enchantements. Volez ces Yeux au Voile Reskk et au Voile Shienor dans le nord de Terokkar. Permettez-moi de voir ce que Terokk voit. Permettez-moi de voir à travers les yeux de Skettis.', },
    nil,
  },
  [10848] = {
    'Voile Rhaze : Un mal sans vie',
    {'Le Voile Rhaze est une colonie particulièrement maléfique de Skettis.|n|nMalgré la destruction du village par le désastre d\'Auchindoun, l\'influence de Terokk y est restée dans des esprits malfaisants. Partez vers l\'ouest pour le Voile Rhaze et tuez ces horreurs meurtrières. Vous les trouverez à l\'ouest de la Tombe des ombres, à la frontière du désert des Ossements et de la forêt de Terokkar.|n|nCe sera le premier coup que nous porterons à Terokk et aux gardiens de Skettis.', },
    nil,
  },
  [10849] = {
    'À la recherche de Kirrik',
    {'D\'autres arakkoa ont rompu avec Terokk.|n|nKirrik a reconnu en lui un charlatan et non un prophète. La seule vision que Terokk ait jamais reçue était celle du malheur dont il est lui-même la source.|n|nC\'est Kirrik qui nous a courageusement conduits ici depuis Skettis. Après notre arrivée à Shattrath, Kirrik a parcouru les colonies à la recherche d\'autres.|n|nCette missive décrit ce qu\'ont vu les Yeux. Kirrik doit en être informé ! Suivez la route vers le sud en sortant de Shattrath jusqu\'au désert des Ossements et cherchez la caravane.', },
    nil,
  },
  [10850] = {
    'De l\'essence de Néant dans un moteur gangrefeu',
    nil,
    nil,
  },
  [10851] = {
    'Les totems de mon ennemi',
    {'Il y a la bonne manière d\'honorer ses ancêtres, mais il en existe également une mauvaise.|n|nLes ogres de Flèchelame portent des totems sur eux, mais ils ne les utilisent pas pour montrer leur respect. Au lieu de ça, ils désirent la manipulation et le pouvoir.|n|nNous devons voler leurs totems parce qu\'ils n\'en sont pas dignes ! Ensuite nous pourrons en faire un meilleur usage.|n|nAllez à l\'avant-poste Flèchelame à l\'ouest, juste au sud-ouest de la Tranchecrête. Tuez les mystiques et les écraseurs de Flèchelame, et prenez-leur leurs totems !', },
    nil,
  },
  [10852] = {
    'Les amis perdus',
    {'Nous nous sommes arrêtés ici parce que des gens sont venus pendant la nuit et ont fait beaucoup de bruit. C\'était effrayant. Je ne sais pas quand nous allons pouvoir repartir.|n|nEt certains de mes amis ont disparu. Je ne sais pas où ils sont. Je crois que ces vilains hommes-oiseaux les ont emmenés au nord-ouest. Ils sont sûrement enfermés dans des cages et tout ça. Si vous les trouviez, ce serait super. Je suis un peu inquiet pour eux.', },
    {'Ethan veut que vous trouviez 12 de ses amis disparus au Voile Skith et que vous reveniez ensuite le voir à la Caravane des réfugiés.', },
  },
  [10853] = {
    'L\'appel des esprits',
    {'Les esprits des drakes du Néant de la Crête chantante ont besoin d\'être libérés.|n|nCes drakes n\'ont pas toujours été des drakes du Néant. C\'étaient des drakes noirs.|n|nMais lors de la destruction de ce monde, une vague d\'énergie du Néant a tout balayé et l\'un des effets secondaires a été la transformation des œufs de drakes.|n|nIls sont tous des répliques corrompues de ce qu\'ils étaient. Nous devons les aider à trouver la paix.|n|nPour cela, tuez un drake près du totem d\'appel des esprits, puis prenez son esprit.', },
    nil,
  },
  [10854] = {
    'La force de Neltharaku',
    {'Prenez ce cristal vignéant enchanté et retournez dans la forteresse Gueule-de-dragon. Une fois que vous serez là-bas, trouvez les drakes asservis et invoquez la magie du cristal vignéant. Ma propre énergie en surgira et permettra aux drakes de briser les liens de leurs ravisseurs. Quand vous verrez un drake libre, aidez-le à vaincre son gardien ! Il sera très certainement affaibli par son emprisonnement.|n|nLibérez tous ceux que vous trouverez avant de revenir me voir, $N.', },
    {'Neltharaku, qui vole au-dessus des champs de l\'Aile-du-Néant dans la vallée d\'Ombrelune, veut que vous libériez 5 Drakes de l\'Aile-du-Néant asservis.', },
  },
  [10855] = {
    'Les saccageurs gangrenés ne passeront pas !',
    {'Ah oui, le saccageur gangrené ! Sans l\'ombre d\'un doute la plus terrible des créations mécaniques de la Légion. Trois de ces abominations sont braquées sur la Foudreflèche. Trois !|n|nHeureusement pour nous, ils ne sont pas encore actifs. Cela nous laisse une chance de les saboter plutôt que de nous lancer dans une attaque.|n|nRécupérez du gaz du Néant condensé sur les gan\'arg de la Base de forge : Oubli et remplissez-en le réservoir d\'un saccageur gangrené. J\'ai dans l\'idée que son moteur n\'appréciera pas.', },
    {'Récupérez 5 mesures de Gaz de Néant condensé auprès des Mekgénieurs gan\'arg de la Base de forge : Oubli, au nord-ouest de la Foudreflèche, et chargez-les dans un Saccageur gangrené inactif proche. Revenez voir le Traqueur-du-Néant Nauthis quand vous aurez terminé.', },
  },
  [10856] = {
    'La meilleure défense',
    {'De courageux actes de sabotage ne nous conduiront pas bien loin, $N. Si la base de forge Oubli sert de point d\'assemblage aux saccageurs gangrenés, la base de forge Géhenne sert de lieu de rassemblement pour leur armée, car c\'est là que la majorité des téléporteurs de la Légion sont situés.|n|nJe veux que vous alliez là-bas et que vous réduisiez un peu leur nombre. Ils doivent avoir un régiment entier de porte-courroux à l\'heure actuelle, et nous ne pouvons pas nous le permettre.', },
    {'Le Traqueur-du-Néant Nauthis veut que vous tuiez 12 Porte-courroux à la Base de forge Géhenne, au nord de la Foudreflèche.', },
  },
  [10857] = {
    'Téléportez-moi ça !',
    {'Même si tuer des démons est très drôle, cela ne nous aide pas beaucoup tant que la Légion pourra continuer à utiliser ses téléporteurs pour remplacer toutes les troupes que nous éliminons.|n|nMalheureusement, je n\'ai pas d\'explosifs assez puissants sous la main… mais les mo\'arg qui entretiennent les téléporteurs en ont.|n|nPrenez ce bâtonnet… J\'ai réglé ses harmoniques pour qu\'il interfère avec les fréquences cérébrales des mo\'arg. Retournez au camp de forge Géhenne et utilisez-le sur les mo\'arg que vous rencontrerez. Vous ne disposerez que de peu de temps, mais vous pourrez utiliser leurs charges d\'explosifs sur les téléporteurs les plus proches.', },
    {'Le Traqueur-du-Néant Nauthis veut que utilisiez le Bâtonnet d\'interférence mentale sur les mo\'arg du Camp de forge Géhenne, et utilisez leur capacité pour Faire exploser le téléporteur sur les trois téléporteurs du camp de forge.', },
  },
  [10858] = {
    nil,
    {'Demander encore votre assistance me couvre de honte, $N, mais vous êtes le seul espoir de mon vol. Sans ma compagne, la lignée de l\'Aile-du-Néant pourrait s\'éteindre complètement.|n|nFrayez-vous un chemin jusqu\'au sommet de la forteresse Gueule-de-dragon et trouvez Karynaku.|n|nNous volerons au-dessus de vous. Si une brèche apparaît dans leurs défenses, toute la puissance de l\'Aile-du-Néant fondra sur la forteresse pour vous aider.', },
    {'Trouvez Karynaku à la Forteresse Gueule-de-dragon.', },
  },
  [10859] = {
    'Réunir les orbes',
    {'Les éthériens razaani possèdent d\'étranges appareils qui émettent de petits orbes flottants de lumière rose. Ils me font penser à des âmes.|n|nIl ne faut pas les confondre avec les grandes boules jaunes qui s\'échappent des éthériens quand ils meurent, c\'est quelque chose de complètement différent.|n|nJ\'aimerais que vous partiez vers le nord pour le point d\'ancrage de Razaan et que vous y lâchiez des totems, qui attireront les orbes de lumière rose.|n|nRapportez-les-moi que je puisse déterminer de quoi il s\'agit exactement.', },
    nil,
  },
  [10860] = {
    'Délices de Mok\'Nathal',
    {'Vous avez faim, $R ? Le Grand esprit aide ceux qui s\'aident eux-mêmes. Si vous voulez gagner un repas, je vous conseille d\'écouter, parce que Braagor là-bas ne va rien vous donner gratuitement, et sûrement rien d\'aussi bon !|n|nLes raptors et les ailécailles de la Tranchecrête et de la Saillie ailécaille ont tout ce qu\'il faut pour deux des plus délicieux plats que vous aurez jamais l\'occasion de goûter. Apportez-moi des côtelettes de raptor et de la chair de serpent, et j\'en préparerai pour vous.|n|nJe pourrais même vous apprendre à les préparer vous-même, si vous faites vite.', },
    nil,
  },
  [10861] = {
    'Voile Lithic : Frappe préventive',
    {'Dans la maudite colonie au sud-ouest connue sous le nom de Voile Lithic, les serviteurs de Terokk tentent de souiller leurs frères oiseaux avant leur éclosion. Les sombres ensorceleurs de Lithic entourent les œufs d\'une ténébreuse malédiction. À leur naissance, les oisillons servent aveuglément Terokk.|n|nPartez pour le Voile Lithic et cassez les œufs prématurément, avant que la malédiction n\'ait pu les atteindre. Même si vous arrivez trop tard, vous pouvez éliminer ceux qui sont souillés.|n|nN\'oubliez pas que c\'est dans les ténèbres que la Lumière brille le plus.', },
    nil,
  },
  [10862] = {
    'Se rendre à la Horde',
    {'Ces lâches d\'arakkoa nous attaquent tous les jours. Ils prennent nos chasseurs en embuscade et s\'introduisent même parfois dans nos murs. Nous les tuons dès que nous en avons l\'occasion, mais leur magie est puissante et ils échappent souvent à nos groupes de guerre.|n|nJ\'ai appris que certains arakkoa se prétendent amis de la Horde. Ils vivent à Shattrath, au nord-ouest. Rilak le Racheté est leur chef. Cherchez-le dans la Ville basse, et quand vous l\'aurez trouvé, exigez sa reddition.', },
    nil,
  },
  [10863] = {
    'Les secrets des arakkoa',
    {'Ici à la frontière, nous devons affronter les arakkoa tous les jours. Ils nous attaquent selon leur bon plaisir, pillent nos lignes de ravitaillement et tuent nos éclaireurs.|n|nEt pourtant nous en savons très peu sur ces créatures énigmatiques. J\'ai appris qu\'au nord-ouest d\'ici à Shattrath se trouvaient des arakkoa qui ne sont pas hostiles, et qui accepteraient peut-être de partager les secrets de leur race.|n|nRilak le Racheté est leur chef. Il habite dans la partie nord de la ville basse.', },
    nil,
  },
  [10864] = {
    'Le fardeau des âmes',
    {'J\'ai ici un appareil, le scrutateur démonien, qui peut analyser la magie gangrenée. J\'aimerais que vous utilisiez le scrutateur, mais d\'abord... vous devez le calmer. Le scrutateur, voyez-vous, est un piège qui retient une créature d\'une intelligence formidable, et dont les besoins sont pour le moins... excentriques.|n|nPour apaiser le scrutateur, vous devez tuer des orcs. Très précisément, il doit s\'agir d\'orcs de la Main brisée. Le scrutateur réclame leurs âmes.|n|nRepassez me voir quand vous aurez fauché assez d\'âmes. Vous trouverez ces orcs au nord, et au sud, et tout autour... de la citadelle des Flammes infernales.', },
    {'Tuez 20 Orcs de la Main brisée, puis retournez voir l\'Apothicaire Antonivitch à Thrallmar.', },
  },
  [10865] = {
    'Informez Leoroxx !',
    {'Vite, vous devez informer Leoroxx de ce qui se passe au point d\'ancrage de Razaan !|n|nCes orbes sont composés d\'âmes, et certaines appartenaient à des Mok\'Nathal !', },
    nil,
  },
  [10866] = {
    'Zuluhed le Fourbu',
    {'Il se cache dans mes pensées, $Gmortel:mortelle;. Il attend que je cède... pour me plier à sa volonté.|n|nEt c\'est cela qui le perdra. Je vais l\'appeler. Je vais lui dire que je ferai ce qu\'il ordonnera. Quand il apparaîtra, tuez-le et prenez-lui la clé !|n|nMais sachez ceci : Zuluhed est un orc ancien, dépositaire de pouvoirs inconnus. Et Illidan l\'a certainement rendu encore plus puissant. En faisant ce que je vous demande, vous risquez votre vie pour moi. Êtes-vous $Gcertain:certaine; de vouloir faire ce sacrifice ?', },
    {'Tuez Zuluhed le Fourbu et récupérez la Clé de Zuluhed. Utilisez-la sur les Chaînes de Zuluhed pour libérer Karynaku.', },
  },
  [10867] = {
    'La seule réponse possible',
    {'Il ne peut y avoir qu\'une réponse à cette... cette, PROFANATION des âmes de nos ancêtres !|n|n$N, si vous voulez nous aider à remettre les âmes de nos honorés morts à la place qui leur appartient, retournez au point d\'ancrage de Razaan.|n|nRemontez là-haut et tuez les razaani jusqu\'à ce que leur chef, le prince-nexus Razaan, montre sa tête de lâche. Tuez-le et reprenez les âmes, puis donnez-les au mande-esprit Dohgar !', },
    nil,
  },
  [10868] = {
    'Le sentier de la guerre arakkoa',
    {'Les arakkoa nous ont à nouveau attaqués, de nuit cette fois, et en utilisant leur magie noire pour fuir avant que nous ne puissions lancer notre riposte. Ils se servent de cercles d\'invocation pour sauver leurs guerriers d\'une mort certaine mais ils ne pourront nous échapper si nous les attaquons chez eux. Le Voile Reskk et le Voile Shienor se trouvent au nord et au nord-est.|n|nTrouvez ces nids d\'arakkoa et tuez-en autant que vous le pourrez.', },
    {'La Conseillère Faila vous demande de tuer 14 Serrénites shienor et 6 Ensorceleurs shienor avant de revenir la voir au Fort des Brise-pierres.', },
  },
  [10869] = {
    'Restreindre la nuée',
    {'Les arakkoa nous ont à nouveau attaqués, cette fois de nuit et en utilisant leur magie noire pour fuir avant que nous ne puissions rassembler nos soldats. Le Voile Reskk et le Voile Shienor se trouvent au nord et au nord-ouest.|n|nTrouvez ces nids d\'arakkoa et tuez-en autant que vous le pourrez. Ils ne nous craignent peut-être pas, mais nous pouvons au moins réduire leur nombre.', },
    {'Le lieutenant Gravillemartel vous demande de tuer 14 Serrénites shienor et 6 Ensorceleurs shienor avant de revenir le voir au Bastion allérien.', },
  },
  [10870] = {
    'Allié du vol du Néant',
    {'Permettez-moi de vous ramener auprès de Mordenai. Je suis certaine qu\'il souhaite vous voir encore une fois.', },
    {'Permettez à Karynaku de vous ramener auprès de Mordenai dans les Champs de l\'Aile-du-Néant.', },
  },
  [10871] = {
    'Allié du vol du Néant',
    {'Permettez-moi de vous ramener auprès de Mordenai. Je suis certaine qu\'il souhaite vous voir encore une fois.', },
    {'Permettez à Karynaku de vous ramener auprès de Mordenai dans les Champs de l\'Aile-du-Néant.', },
  },
  [10872] = {
    'Zuluhed le Fourbu',
    {'Il se cache dans mes pensées, $Gmortel:mortelle;. Il attend que je cède... pour me plier à sa volonté.|n|nEt c\'est cela qui le perdra. Je vais l\'appeler. Je vais lui dire que je ferai ce qu\'il ordonnera. Quand il apparaîtra, tuez-le et prenez-lui la clé !|n|nMais sachez ceci : Zuluhed est un orc ancien, dépositaire de pouvoirs inconnus. Et Illidan l\'a certainement rendu encore plus puissant. En faisant ce que je vous demande, vous risquez votre vie pour moi. Êtes-vous $Gcertain:certaine; de vouloir faire ce sacrifice ?', },
    {'Tuez Zuluhed le Fourbu et récupérez la Clé de Zuluhed. Utilisez-la sur les Chaînes de Zuluhed pour libérer Karynaku.', },
  },
  [10873] = {
    'Pris dans la nuit',
    nil,
    nil,
  },
  [10874] = {
    'Voile Shalas : Feux de signal',
    {'Le perchoir de Terokk, Skettis, se dresse au-dessus du désert des Ossements à l\'est. À son pied se trouve le Voile Shalas, la plus terrible des colonies de Terokk. C\'est depuis le bastion du Voile Shalas que les sages de Terokk livrent leur guerre contre la Lumière.|n|nLes créatures malfaisantes de Shalas communiquent avec leur maître par un système complexe de feux de signal magiques. Partez vers l\'est, $R, et éteignez les feux. Une fois le Voile Shalas réduit au silence, nous pourrons commencer à préparer la chute de Skettis.|n|nMais chaque chose en son temps.', },
    nil,
  },
  [10875] = {
    'Se présenter à Nazgrel',
    {'$N, pendant votre expédition avec le scrutateur démonien, j\'ai fait connaître l\'histoire de vos exploits contre les gangr‘orcs. Nazgrel, notre illustre chef à Thrallmar, souhaite vous parler. Je pense qu\'il a une mission assez sanglante en tête pour vous.', },
    nil,
  },
  [10876] = {
    'Le pied de la citadelle',
    {'Le commandant de corps Gorax entraîne les capitaines de la Main brisée au pied de la citadelle des Flammes infernales, et fait d\'eux les combattants les plus endurcis qui soient. Vous devez le tuer, $N, car sa perte serait un coup terrible pour les gangr\'orcs.|n|nCe n\'est cependant pas la seule chose que vous devrez faire.|n|nPrenez cette bannière. Plantez-la sur le cadavre de Gorax. Le commandant de Gorax, la Main de Kargath, devra répondre à ce défi s\'il lui reste la moindre goutte de sang orc dans les veines !|n|nSa tête, la tête de la main de Kargath… C\'est ça que je veux.', },
    {'Tuez le Commandant de corps Gorax, placez le Défi de la Horde sur son cadavre, tuez la Main de Kargath, puis rapportez la Tête de la Main de Kargath à Nazgrel dans Thrallmar.', },
  },
  [10877] = {
    'La relique de l\'effroi',
    {'Il y a bien longtemps, une caravane partit pour Auchindoun avec pour mission la récupération d\'une Relique de l\'effroi dans les anciens tombeaux sous la nécropole. Ils purent s\'en échapper, mais la relique causa leur perte. La relique est maléfique et invoque le mal quand on la touche. Leur caravane fut détruite quelque part à l\'est.|n|nCe sombre artéfact est la clé d\'un terrible plan pour vaincre Teribus le Maudit, une créature qui vole au-dessus du désert des Ossements. Aidez-moi si tel est votre désir, mais votre vie et jusqu\'à votre âme seront en danger.', },
    {'Chênuin veut que vous partiez vers l\'est pour la Caravane abandonnée afin de récupérer la Relique de l\'effroi. Revenez voir Chênuin quand cette tâche sera achevée.', },
  },
  [10878] = {
    'Avant que l\'ombre…',
    {'Les sectateurs de la Cabale du Conseil des ombres ont attaqué notre caravane. Peu après, nous avons envoyé des éclaireurs à Shattrath pour réclamer de l\'aide. Les gardes pensent que nous sommes à l\'abri pour l\'instant, mais ils sous-estiment ces déments.|n|nJe n\'ai aucune envie qu\'un initié de la Cabale vienne me trancher la gorge au milieu de la nuit. Faites-nous une faveur : portez la guerre dans leur camp avant qu\'ils ne viennent nous achever.|n|nVous trouverez nos agresseurs au sud, près de l\'entrée nord d\'Auchindoun.', },
    nil,
  },
  [10879] = {
    'L\'offensive de Skettis',
    {'Skettis est en guerre contre nous ! Avez-vous rassemblé vos forces pour aider à la défense de Shattrath ?|n|nRepoussez les attaquants !', },
    nil,
  },
  [10880] = {
    'Les ordres de la Cabale',
    {'Ce message porte un sceau noir. Le langage vous semble familier, mais apparemment, il est codé.|n|nIl y aura peut-être quelqu\'un qui saura quoi en faire à la Caravane de réfugiés ?', },
    nil,
  },
  [10881] = {
    'La tombe des ombres',
    {'Bien des gens soupçonnent le Conseil des ombres d\'avoir provoqué l\'explosion qui a ravagé Auchindoun. On murmure qu\'ils y ont éveillé un mal immense...|n|nSi c\'est vrai, ce mal a dû se retourner contre eux. Et si j\'en crois ces ordres, une partie du Conseil des ombres est en train de fuir Auchindoun. Ils se servent de la tombe des ombres pour y conserver de puissants artéfacts récupérés à Auchindoun.|n|nTrois de ces objets sont sacrés, car ils ont appartenu aux grands patriarches Arunen, K\'alen et Atalor. Je vous demande de les récupérer.', },
    {'Rendez-vous dans la Tombe des ombres, à l\'ouest de la Caravane de réfugiés. Récupérez-y le Drapé d\'Arunen, le Marteau de K\'alen et le Parchemin d\'Atalor. Lorsque vous aurez terminé, retournez voir Mekeda à la Caravane de réfugiés.', },
  },
  [10882] = {
    'Messager funeste',
    {'<Vous remarquez une note discordante dans la « voix » d\'A\'dal.>|n|nLe prince Kael\'thas a mal choisi son gardien, et maintenant les entités que nous gardions enfermées à l\'intérieur de l\'Arcatraz sont en train de s\'échapper.|n|nL\'une d\'elles en particulier, un serviteur des Dieux très anciens connu sous le nom de messager Cieuriss cherche à réaliser le rêve de ses maîtres de conquérir tous les mondes de l\'univers.|n|n$N, vous ne devez pas le laisser s\'échapper. Retournez au donjon de la Tempête, pénétrez dans l\'Arcatraz et tuez le messager Cieuriss avant qu\'il ne soit trop tard !', },
    {'Vous avez été $Gchargé:chargée; d\'aller sur le satellite d\'Arcatraz du donjon de la Tempête et de tuer le Messager Cieuriss. Revenez voir A\'dal à la Terrasse de la Lumière de Shattrath quand ce sera fait.', },
  },
  [10883] = {
    'La clé de la Tempête',
    {'Vous avez prouvé que vous étiez capable de grands exploits, $N. Votre découverte de la Formule de damnation et de l\'implication de Kael\'thas a été d\'une importance capitale pour notre cause. Si Kael se servait de la formule, le peu qui reste de ce monde pourrait s\'écrouler.|n|nA\'dal est convaincu qu\'il faut arrêter Kael et cherche à présent des aventuriers prêts à subir des épreuves. À ceux qui auront prouvé leur force sera accordée la faveur des naaru.|n|n<Khadgar hoche la tête.>|n|nA\'dal attend...', },
    {'Parlez à A\'dal à Shattrath.', },
  },
  [10884] = {
    'L\'épreuve des naaru : Miséricorde',
    nil,
    {'A\'dal de Shattrath vous demande de prendre la Hache inutilisée du bourreau dans les Salles brisées de la citadelle des Flammes infernales.|n|nCette quête doit être accomplie en mode de difficulté du donjon Héroïque.', },
  },
  [10885] = {
    'L\'épreuve des naaru : Force',
    {'Vous devez réussir quatre épreuves avant d\'être $Gjugé:jugée; digne par les naaru.|n|nL\'épreuve de force se déroule en deux temps. Vous devez détruire le chef du Caveau de la vapeur de Glissecroc, le seigneur de guerre Kalithresh, et m\'apporter son trident. Tuez l\'être extraplanaire connu sous le nom de Marmon, dans le Labyrinthe des ombres d\'Auchindoun, et apportez-moi son essence.|n|nFaites cela et vous aurez réussi l\'épreuve de force.', },
    {'A\'dal de Shattrath vous demande de récupérer le Trident de Kalithresh et l\'Essence de Marmon.|n|nCette quête doit être accomplie en mode de difficulté du donjon Héroïque.', },
  },
  [10886] = {
    'L\'épreuve des naaru : Ténacité',
    {'Vous devez réussir quatre épreuves avant d\'être $Gjugé:jugée; digne par les naaru.|n|nLors de nos voyages, nous avons rencontré de nombreux êtres dangereux. Nous avons incarcéré certains d\'entre eux dans ce qu\'on appelle maintenant l\'Arcatraz du donjon de la Tempête.|n|nL\'un des prisonniers, cependant, a été victime des circonstances. Un clandestin qui se trouvait dans le mauvais vaisseau naaru au mauvais moment.|n|nPénétrez dans l\'Arcatraz et secourez ce gnome, Milhouse Tempête-de-mana. Assurez-vous de sa survie.', },
    {'A\'dal de Shattrath vous demande de sauver Milhouse Tempête-de-mana de l\'Arcatraz du donjon de la Tempête.|n|nCette quête doit être accomplie en mode de difficulté du donjon Héroïque.', },
  },
  [10887] = {
    'Sortir du tombeau',
    {'J\'apprécie votre aide, $N. J\'ai bien cru que j\'allais me faire tuer.|n|nAllons-nous-en vite. Les sectateurs ne vont pas tarder à nous poursuivre.', },
    nil,
  },
  [10888] = {
    'L\'épreuve des naaru : Magtheridon',
    {'Vous devez réussir quatre épreuves avant d\'être $Gjugé:jugée; digne par les naaru.|n|nIl ne reste plus qu\'un obstacle, $Gmortel:mortelle;. Rassemblez une armée et voyagez jusqu\'au repaire de Magtheridon, loin dans la citadelle des Flammes infernales. Frayez-vous un chemin jusqu\'au cœur de la chambre et détruisez ce vil corrupteur !', },
    {'A\'dal de Shattrath vous demande de tuer Magtheridon.', },
  },
  [10889] = {
    'Retour à Shattrath',
    {'Vos actes, quoique courageux, entraîneront sûrement de terribles représailles de la part de Terokk.|n|nPartez vite pour Shattrath. Prévenez Rilak !', },
    nil,
  },
  [10890] = {
    '[INUTILISÉ] <NYI>',
    nil,
    nil,
  },
  [10891] = {
    'L\'armure impériale en plaques',
    {'Il y a un nain à Gadgetzan qui s\'appelle Derotain Siroteboue, et qui pourra vous apprendre à fabriquer l\'armure impériale en plaques. Il vous suffit d\'aller dans le désert de Tanaris et de le trouver. Ça vous intéresse ?', },
    nil,
  },
  [10892] = {
    'L\'armure impériale en plaques',
    {'Il y a un nain à Gadgetzan qui s\'appelle Derotain Siroteboue, et qui pourra vous apprendre à fabriquer l\'armure impériale en plaques. Il vous suffit d\'aller dans le désert de Tanaris et de le trouver. Ça vous intéresse ?', },
    nil,
  },
  [10893] = {
    'Longue-queue est le pivot',
    {'Avec les sectateurs du Ver de l\'Aile noire qui se massent dans le tunnel, nous avons beaucoup de mal à garder la situation sous contrôle. Franchement, ils ont la supériorité numérique.|n|nEt même si nous parvenons à gérer ceux d\'entre eux qui s\'approchent trop près, le fait est que s\'ils attaquent pour de bon, nous serons submergés.|n|nLa situation exige que quelqu\'un se fraye un chemin jusqu\'à l\'autre bout du tunnel, et élimine leur chef, Draaca Longue-queue. Ça vous amuserait ?', },
    nil,
  },
  [10894] = {
    'Le guetteur du Crâne-du-ver',
    {'Hmm, je ne sais pas vraiment comment nous devrions agir à présent. Je ne suis pas un stratège militaire.|n|nLe guetteur Lunombrage saura quoi faire. Il dirige nos opérations défensives au tunnel Crâne-du-ver à l\'ouest au bout du pont Crâne-du-ver. Nous gardons une force stationnée là-bas au cas où les sectateurs tenteraient quelque chose de louche.|n|nS\'il vous plaît, apportez-lui la note sans tarder.', },
    {'Apportez la Note de rendez-vous au Guetteur Lunombrage à l\'entrée du tunnel Crâne-du-ver dans les Tranchantes.', },
  },
  [10895] = {
    'Que Zeth\'Gor brûle !',
    {'Il est temps de lancer une frappe aérienne sur Zeth\'Gor ! Nos chevaucheurs de griffons sont prêts à faire une sortie, $N. Mais ils ont besoin de quelqu\'un au sol pour diriger les tirs. Vous vous sentez de taille pour une mission discrète ?|n|nEmportez ces balises fumigènes à Zeth\'Gor, la forteresse de l\'Orbite-sanglante vers l\'ouest. Elle dispose de quatre tours de garde : une près de leur muraille nord, une près de la muraille sud, une proche de la forge, et la dernière nichée dans les collines. Placez une balise sous chacune des tours et nous arriverons pour les bombarder !', },
    {'Utilisez les Balises fumigènes sur chacune des tours de Zeth\'Gor, puis retournez voir le Chef d\'escadrille Dabir\'ee à la Halte de l\'expédition.', },
  },
  [10896] = {
    'Les protecteurs infestés',
    {'Les arbres de cette terre sont ravagés par la puissance qui a surgi d\'Auchindoun. La magie impure qui a été libérée a anéanti les terres pour en faire le désert que vous voyez ici. Les arbres qui ont survécu sont maintenant infestés par ces fichues mites des bois, qui s\'introduisent sous leur écorce et rongent leur chair.|n|nLes enragés des forêts pourrissants et les marche-racine infestés sont de véritables couveuses pour les mites. On les trouve à la lisière du bois, à l\'est. Détruisez ces créatures, puis tuez les mites qui s\'enfuiront de leur carcasse.', },
    {'Lakotae veut que vous tuiez 25 Mites des bois puis que vous reveniez le voir à la Caravane de réfugiés. On peut trouver les mites à l\'intérieur des corps des Enragés des forêts pourrissants et des Marche-racine infestés.', },
  },
  [10897] = {
    'Maître des potions',
    {'Comme vous le savez, les alchimistes ont recours aux propriétés des plantes pour fabriquer des potions qui soignent ou donnent de l\'énergie.|n|nJe connais suffisamment les plantes de l\'Outreterre pour apprendre aux alchimistes à en tirer le meilleur parti. Si vous souhaitez améliorer votre connaissance des potions, il ne me reste qu\'une tâche à vous confier.|n|nOn raconte que le Grand botaniste Freywenn du donjon de la Tempête a rédigé un guide botanique extrêmement complet. Rapportez ce guide avec quelques échantillons de votre travail, et je vous apprendrai ce que vous désirez savoir.', },
    {'Lauranna Thar\'well veut que vous vous rendiez dans la Botanica du donjon de la Tempête et que vous récupériez le Guide pratique du botaniste sur le Grand botaniste Freywenn. De plus, elle veut que vous lui rameniez 5 Potions de super-soins, 5 Potions de super-mana et 5 Potions de sommeil sans rêve majeures.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une seule spécialité d\'alchimie.', },
  },
  [10898] = {
    'Aile-du-ciel',
    {'Aile-du-ciel tourne autour de vous en battant des ailes.|n|nVous avez l\'impression qu\'il veut que vous le suiviez.', },
    {'Escortez Aile-du-ciel et allez voir Rilak le Racheté à Shattrath.', },
  },
  [10899] = {
    'Maître de la transmutation',
    {'Tous les alchimistes vous diront que la matière est malléable. Vous pouvez transformer une substance en une autre, mais rien ne se perd et rien ne se crée.|n|nUn véritable maître des transmutations apprend à contourner cette limitation… et je peux vous apprendre à atteindre ce niveau de maîtrise !|n|nEn tant que $Gcandidat:candidate; à la maîtrise de la transmutation, vous connaissez sans doute le pouvoir primordial : la combinaison de la représentation matérielle de toutes les forces primordiales. Apportez-moi la preuve de vos talents en matière de transmutation, et je partagerai mes connaissances avec vous.', },
    {'Zarevhi, de la Foudreflèche du Raz-de-Néant, veut que vous lui rameniez 4 Pouvoirs primordiaux.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une seule spécialité d\'alchimie.', },
  },
  [10900] = {
    'La marque de Vashj',
    nil,
    nil,
  },
  [10901] = {
    'Le casse-tête de Kar\'desh',
    {'Apportez-moi les chevalières élémentaires qu\'exige le casse-tête !|n|nLa chevalière terrestre est en la possession de Gruul le Tue-dragon. Vous pourrez le trouver au fond de son repaire, dans les Tranchantes.|n|nLa seconde chevalière est le cœur flamboyant d\'une créature appelée Plaie-de-nuit. Cette bête mythique réside, dit-on, dans les salles sacrées du prophète, Medivh.|n|nDépêchez-vous !', },
    {'Skar\'this l\'Hérétique, dans les Enclos aux esclaves héroïques du Réservoir de Glissecroc, veut que vous lui apportiez la Chevalière terrestre et la Chevalière flamboyante.', },
  },
  [10902] = {
    'Maître des élixirs',
    {'J\'ai consacré ma vie au perfectionnement de mes élixirs. Malgré mes succès, je n\'ai jamais pu créer d\'élixir de vie éternelle.|n|nJe pense connaître l\'ingrédient qui me manque. J\'ai entendu parler d\'un endroit appelé Grottes du temps en Azeroth où des intrus, connus sous le nom de seigneurs des failles et de gardiens des failles, entrent et sortent des voies temporelles.|n|nCes détemporalisations importunes créent des déchirures dans le temps lui-même, le tordant infiniment en essences cristallisées. Apportez-moi ces essences avec des échantillons de votre travail et je vous apprendrai tout ce que je sais.', },
    {'Partez pour les Grottes du temps dans le Noir Marécage et procurez-vous 10 Essences d\'infinité sur les Seigneurs des failles et Gardiens des failles. Apportez-les avec 5 Élixirs de défense majeure, 5 Élixirs de maîtrise et 5 Élixirs d\'agilité majeure à Lorokeem dans la Ville basse de Shattrath.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en alchimie.', },
  },
  [10903] = {
    'Retour au bastion de l\'Honneur',
    {'$N, pendant que vous étiez en mission à Zeth\'Gor, j\'ai reçu des nouvelles de mon officier supérieur, le colonel Jules. Il a été atteint par une corruption démoniaque alors qu\'il se battait près de l\'avant-poste Gol\'gaz, et son état est devenu très alarmant.|n|nVous avez accompli de tels exploits pour nous contre les gangr\'orcs. Vos qualités de $Gcombattant:combattante; ne sont plus à remettre en question... mais votre esprit est-il aussi fort ?|n|nJe vous en prie, retournez au bastion de l\'Honneur et parlez avec Klatu, dans l\'une des salles à l\'étage de l\'auberge du bastion.', },
    {'Parlez à Klatu, à l\'auberge du Bastion de l\'Honneur.', },
  },
  [10904] = {
    'La récolte des munitions gangrenées',
    {'Nous devons fermer l\'accès de la Légion ardente à la Porte de la mort, mais vous devrez d\'abord détruire leurs deux portails dimensionnels !|n|nLe problème, c\'est que nous ne pouvons même pas rayer ces choses. Vous allez donc devoir utiliser leurs propres armes contre eux.|n|nLes membres de la Force de mort, du Guet de mort, les supra-forgerons et les techniciens de la Forgemort portent les munitions des gangrecanons.|n|nNormalement, elles n\'ont pas d\'effet contre la Légion, mais si vous me donnez les boulets, je les imprégnerai de la colère déchaînée de la Nature !', },
    nil,
  },
  [10905] = {
    'Maître des potions',
    {'Mon savoir alchimique est très étendu. Cela implique toutefois qu\'il est de nature générale. Si vous désirez vous spécialiser, vous devrez trouver d\'autres maîtres qui se consacrent à des champs d\'études plus réduits.|n|nSi vous souhaitez vous spécialiser dans la création des potions, je vous conseille de rechercher l\'assistance de Lauranna Thar\'well de l\'Expédition cénarienne.|n|nSon érudition en matière de plantes vous permettra de rentabiliser au mieux vos matières premières. Partez à sa recherche dans le marécage de Zangar, et dites-lui bien que vous venez de ma part.', },
    {'Parlez à Lauranna Thar\'well au Refuge cénarien dans le Marécage de Zangar.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en alchimie.', },
  },
  [10906] = {
    'Maître des élixirs',
    {'Mon savoir alchimique est très étendu. Cela implique toutefois qu\'il est de nature générale. Si vous désirez vous spécialiser, vous devrez trouver d\'autres maîtres qui se consacrent à des champs d\'études plus réduits.|n|nSi vous souhaitez vous spécialiser dans la création des élixirs, je vous conseille de rechercher l\'assistance de l\'arakkoa connu sous le nom de Lorokeem.|n|nSa connaissance des élixirs est sans pareille, et pourtant il gaspille son talent à chercher un élixir de vie éternelle. Allez le trouver et voyez ce qu\'il peut vous apprendre.', },
    {'Parlez à Lorokeem dans la Ville basse de Shattrath.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en alchimie.', },
  },
  [10907] = {
    'Maître de la transmutation',
    {'Mon savoir alchimique est très étendu. Cela implique toutefois qu\'il est de nature générale. Si vous désirez vous spécialiser, vous devrez trouver d\'autres maîtres qui se consacrent à des champs d\'études plus réduits.|n|nSi vous souhaitez vous spécialiser dans la transmutation, je vous conseille de rechercher l\'assistance de l\'éthérien appelé Zarevhi. Il réside dans la Foudreflèche, au Raz-de-Néant.|n|nSa maîtrise de la transmutation est proprement... suffocante ! Voyez ce que vous pourrez apprendre auprès de lui, mais prenez garde : les éthériens sont durs en affaires.', },
    {'Parlez à Zarevhi à la Foudreflèche au Raz-de-Néant.|n|n*ATTENTION !* Vous ne pouvez choisir qu\'une spécialisation en alchimie.', },
  },
  [10908] = {
    'Parler à Rilak le Racheté',
    {'Vous avez l\'air $Gsurpris:surprise; de parler avec moi. Je ne vous en fais pas le reproche. Mon peuple, les arakkoa, mérite d\'être craint.|n|nParlez à Rilak le Racheté à Shattrath si vous désirez en savoir davantage. Il se trouve dans la partie nord de la Ville basse, avec les autres exilés de Skettis.|n|nEt, $N, nous nous reparlerons.', },
    nil,
  },
  [10909] = {
    'Les esprits gangrenés',
    {'Le colonel Jules a été maudit lors d\'une bataille près de l\'avant-poste de Gor\'gaz, un repaire de gangr\'orcs de la Main brisée. Mon maître Barada travaille sans relâche pour soigner ce pauvre humain, mais il a besoin d\'aide. L\'esprit tourmenté du colonel aspire à la paix, et j\'ai peur que le chemin de la paix passe dans son cas par la voie de la vengeance.|n|nEmportez cette relique d\'anachorète à l\'avant-poste de Gor\'gaz. Placez-la au sol près des orcs de la Main brisée et abattez-les. Cela libèrera leurs esprits gangrenés, que vous devrez ensuite détruire pour permettre le rétablissement de l\'esprit de Jules.', },
    {'Klatu au Bastion de l\'Honneur vous a demandé d\'utiliser la Relique d\'anachorète à l\'Avant-poste de Gor\'gaz, au sud-ouest du Bastion. Vous devrez ensuite tuer des Orcs de la Main brisée près de la relique, puis détruire les Esprits gangrenés libérés pour venger le Colonel Jules.', },
  },
  [10910] = {
    'La Porte de la mort',
    {'Il existe maintenant une menace encore plus grande venant de la Légion ardente. Au sud se trouve un portail connu sous le nom de Porte de la mort. Il s\'ouvre sur un monde terrifiant où la Légion élève ses divers molosses.|n|nPour aller là-bas, quittez le Bosquet éternel en montant sur la rampe à l\'est. Suivez le chemin du sud à travers le Goulet des lames, le point d\'ancrage de Razaan, la Tranchecrête et la Saillie ailécaille. Prenez ensuite la rampe qui descend vers le séjour de Vekhaar et accédez à la Porte de la mort par le tunnel, au sud de Mok\'Nathal.|n|nUne fois là-bas, utilisez ce signal druidique.', },
    nil,
  },
  [10911] = {
    'Feu à volonté !',
    {'Maintenant que ces munitions peuvent affecter la Légion ardente, il est temps que vous les utilisiez.|n|nIl existe deux portails dimensionnels, qui sont utilisés pour la téléportation et l\'amélioration des terreurs du vide. L\'un se trouve au sud et l\'autre au nord, mais ils sont tous deux à portée d\'un gangrecanon.|n|nFrayez-vous un chemin jusqu\'aux gangrecanons et utilisez les munitions naturalisées pour prendre le contrôle de chacun d\'entre eux et détruire les portails dimensionnels.|n|nQuand vous commencerez à bombarder les portails, soyez $Gprêt:prête; à tuer les défenseurs qui chercheront à neutraliser le canon !', },
    nil,
  },
  [10912] = {
    'Le maître-chien',
    {'Baelmon le Maître-chien doit mourir ! C\'est lui qui assure le rituel qui permet le fonctionnement du portail.|n|nLe portail de la Porte de la mort se trouve à l\'extrémité nord du canyon. Quand vous l\'aurez trouvé, vous aurez aussi trouvé Baelmon.|n|nVous allez avoir besoin d\'aide, alors prenez cette baguette. Quand vous affronterez le Maître-chien, utilisez-la et deux de mes amis viendront à votre aide.|n|nLorsque vous aurez vaincu Baelmon, retournez voir le seigneur sauvage Antelarion.|n|nEt $N, merci pour tout ce que vous avez fait pour nous ici.', },
    nil,
  },
  [10913] = {
    'Des funérailles inadéquates',
    {'Ne pouvons-nous rien faire pour arrêter la montée de la corruption ? Mes soldats combattent les Auchenaï depuis des jours, sans espoir d\'en venir à bout. Tous ceux qui tombent, qu\'ils soient auchenaï ou sha\'tar, sont arrachés au champ de bataille – leurs âmes sont conduites on ne sait où.|n|nC\'est insupportable ! Nous ne pouvons pas les enterrer correctement, mais ces monstres n\'auront pas leurs âmes ! Prenez cette torche. Rendez-vous sur le champ de bataille, juste à l\'est. Brûlez tous les corps ! Nous n\'alimenterons pas leurs rituels.', },
    {'Le commandant Ra\'vaj, du Camp de base shat\'ari dans le désert des Ossements de la forêt de Terokkar, veut que vous brûliez 8 Guerriers auchenaï tués et 8 Redresseurs de torts sha\'tar tués.', },
  },
  [10914] = {
    'Il nous faut un héros',
    {'Ce n\'est pas suffisant. Il nous faut un héros. Nos forces sont submergées, les Auchenaï sont de plus en plus nombreux.|n|n<Le commandant Ra\'vaj vous regarde.>|n|nSerez-vous $Gle héros:l\'héroïne; dont nous avons besoin ? Retournez sur le champ de bataille et attaquez les soldats. Occupez-les. Pendant ce temps, mes éclaireurs se faufileront derrières leurs lignes, et ils verront ce qu\'ils sont en train de créer.', },
    {'Le commandant Ra\'vaj, du Camp de base shat\'ari dans le désert des Ossements de la forêt de Terokkar, veut que vous tuiez 12 Initiés auchenaï et 5 Auspices-funestes auchenaï.', },
  },
  [10915] = {
    'L\'exarque déchu',
    {'Ils offrent les âmes qu\'ils dérobent à un cercueil qu\'ils ont sorti des cryptes des Auchenaï. Mes éclaireurs supposent qu\'il contient le premier exarque des cryptes. Ils cherchent à le ressusciter !|n|nVous devez vous frayer un passage dans la partie ouest d\'Auchindoun et nous débarrasser du contenu de ce cercueil avant qu\'ils ne lui aient donné assez d\'âmes. Si vous vous perdez, suivez les âmes qui marchent.|n|nDétruisez le contenu de ce cercueil !', },
    {'Le commandant Ra\'vaj, du Camp de base shat\'ari dans le désert des Ossements de la forêt de Terokkar, veut que vous détruisiez le contenu du Cercueil auchenaï.', },
  },
  [10916] = {
    'À la recherche de chapelets',
    {'L\'anachorète Barada projette d\'exorciser la corruption qui frappe le colonel Jules. Pour ce faire, il aura besoin d\'un assistant, et cet assistant devra y être correctement préparé...|n|nJ\'ai honte de devoir l\'admettre, mais mon chapelet a été perdu dans la cour du bastion de l\'Honneur. Je pense que le chien Fei Fei l\'a volé et enterré, mais j\'ignore où. Si vous pouviez le demander à sa maîtresse, l\'adjudante Tracy Fièrepuits, elle saura peut-être vous indiquer où Fei Fei cache le fruit de ses rapines.', },
    {'Retrouvez le Chapelet draeneï et rapportez-le à l\'Assistant Klatu dans le Bastion de l\'Honneur.', },
  },
  [10917] = {
    'La souffrance du paria',
    {'En tant que paria, je vis sous une sentence de mort des arakkoa loyaux à la cité de Skettis. Je ne peux quitter la protection de ces murs sous peine de perdre la vie, mais cela ne signifie pas que je ne peux pas me venger et les attaquer.|n|nJe possède quelques trésors que je suis prêt à partager, si vous voulez bien m\'aider à riposter contre mes prétendus assassins. Rapportez-moi des plumes des citoyens des divers Voiles de Terokkar comme preuve de leur défaite.', },
    {'Apportez 30 Plumes d\'arakkoa à Vekax dans la Ville basse de Shattrath.', },
  },
  [10918] = {
    'Plus de plumes',
    nil,
    nil,
  },
  [10919] = {
    'Les friandises de Fei Fei',
    nil,
    nil,
  },
  [10920] = {
    'Au nom des disparus',
    {'Lorsque les veuves croc-d\'effroi ont attaqué notre avant-poste, nous avons entendu la voix des naaru nous appeler au combat. Nous avons poursuivi les créatures dans la nuit. Nous avons trouvé certains de nos camarades morts dans l\'obscurité, et nous en avons entendu d\'autres lutter contre leurs ravisseurs.|n|nAu matin, nous sommes arrivés ici et nous avons combattu férocement, mais nous avons été vaincus. Le poison des croc-d\'effroi va bientôt emporter mes compagnons, et je ne survivrai pas longtemps. Avant de mourir, j\'aimerais être sûr que les veuves croc-d\'effroi ont été vaincues.', },
    {'Le redresseur de torts Haylen veut que vous tuiez 20 Veuves croc-d\'effroi, puis que vous reveniez le voir juste à l\'ouest de la Crête de Toile-néant.', },
  },
  [10921] = {
    nil,
    {'Vous avez tué nombre des veuves croc-d\'effroi, mais elles continuent de se reproduire et bientôt elles nous frapperont à nouveau. Loin dans la crête de Toile-néant se trouve le repaire de Terokkarantula, la mère des couvées de ces horribles créatures. Si nous voulons vivre en sécurité, elle doit mourir.', },
    {'Le redresseur de torts Haylen veut que vous alliez tuer Terokkarantula et que vous reveniez le voir à l\'ouest de la crête de Toile-néant.', },
  },
  [10922] = {
    'En fouillant dans les os',
    {'Escortez Leglas et son équipe et protégez-les pendant les fouilles. Si vous réussissez, retournez voir Nanowitz au Camp de base sha\'tari.', },
    {'Escortez Leglas et son équipe et protégez-les pendant les fouilles. Si vous réussissez, retournez voir Nanowitz au Camp de base sha\'tari.', },
  },
  [10923] = {
    'L\'approche du mal',
    {'Vous devez maintenant utiliser la relique de l\'effroi dans un ignoble rituel de nécromancie si vous désirez défier Teribus le Maudit. Au nord-est, au-delà d\'Auchindoun, se trouve le Monticule grouillant, un lieu où se rassemblent les nécromanciens.|n|nLes nécrorateurs et auspices-funestes auchenaï portent des crânes du destin dotés de puissants nécro-enchantements. Si vous réunissez suffisamment de crânes, vous pourrez associer leur puissance à celle de la relique de l\'effroi pour ordonner à Teribus de vous affronter.', },
    {'Chênuin veut que vous emportiez la Relique de l\'effroi au Monticule grouillant. Là-bas, tuez des nécrorateurs et des auspices-funestes auchenaï pour collecter 20 Crânes du destin. Trouvez ensuite le Cercle d\'invocation du Monticule grouillant et utilisez la Relique de l\'effroi pour invoquer et détruire Teribus le Maudit. Revenez voir Chênuin quand ce sera fait.', },
  },
  [10924] = {
    'La part du diabl-otin !',
    {'Le sang des poursuivants dimensionnels de cette région est un composant puissant et rare. C\'est l\'un des produits que je vends le mieux.|n|nNormalement, j\'emmène mon diablotin, Zeppit, avec moi pour le récolter. Le sang de poursuivant dimensionnel est tout simplement trop acide pour que vous ou moi puissions le manipuler sans risque. Mais cela ne gêne pas du tout Zeppit.|n|nSeulement, je suis de plus en plus accaparé par ma boutique, alors, si j\'envoie Zeppit vous accompagner, vous voulez bien m\'aider à récolter ce sang ? Zeppit a tendance à ne pas trop faire attention à ce qui l\'entoure, alors vous devrez être assez proche du poursuivant quand il mourra pour qu\'il puisse faire son travail.', },
    {'Sab\'aoth de la Cosmovrille veut 8 fioles de Sang de poursuivant dimensionnel.', },
  },
  [10925] = {
    'L\'approche du mal',
    nil,
    nil,
  },
  [10926] = {
    'Retour au camp de base sha\'tari',
    {'Nous ne pourrons pas rentrer seuls. Le poison des croc-d\'effroi est trop puissant. Vous devez retourner au camp de base sha\'tari pour nous. L\'éclaireur Navrin enverra un groupe de sauveteurs à notre recherche.', },
    nil,
  },
  [10927] = {
    'Tuer les rampantes',
    {'Le commandant Ombreciel veut que ce tunnel soit dégagé afin que nous puissions commercer avec le Havre boueux. Comme je ne dois pas quitter mon poste, je vous confie cette tâche. Nettoyez le tunnel et présentez-vous au commandant Ombreciel immédiatement !', },
    nil,
  },
  [10928] = {
    'Tuer les rampantes',
    {'Tor\'chunk Doublegriffes veut que ce tunnel soit dégagé afin que nous puissions commercer avec le poste du Rat des marais. Comme je ne dois pas quitter mon poste, je vous confie cette tâche. Nettoyez le tunnel et présentez-vous à Tor\'chunk Doublegriffes immédiatement !', },
    nil,
  },
  [10929] = {
    'Martelheurt',
    {'Ça vous dirait de continuer à travailler pour la Ligue des explorateurs ? Ces vers des os nous intriguent tous beaucoup.|n|nJ\'ai ici un tambour que vous pourrez utiliser dans le désert des Ossements. Tapez sur ce fichu truc, vous verrez bien ce que ça fait venir. Si c\'est un ver, tuez-le et rapportez-nous la carcasse, qu\'on puisse l\'étudier. Il va nous falloir pas mal de carcasses avant d\'avoir un échantillonnage valide.', },
    {'Nanowitz, du Camp de base sha\'tari du désert des Ossements, veut que vous lui rameniez 8 Carcasses de cribleurs des ossements adultes.', },
  },
  [10930] = {
    'Le gros ver des ossements',
    {'Nanowitz, du Camp de base sha\'tari du désert des Ossements, veut que vous trouviez des Organes d\'énorme ver des ossements.|n|nIl veut aussi qu\'on lui rapporte son Martelheurt.', },
    {'Nanowitz, du Camp de base sha\'tari du désert des Ossements, veut que vous trouviez des Organes d\'énorme ver des ossements.|n|nIl veut aussi qu\'on lui rapporte son Martelheurt.', },
  },
  [10931] = {
    'Retour à l\'Exodar',
    {'Votre maître, Caedmos de l\'Exodar, a demandé à vous voir. C\'est à propos de votre formation, mais je n\'en sais pas davantage.', },
    {'Parlez à Caedmos à l\'Exodar.', },
  },
  [10932] = {
    'Retour à l\'Exodar',
    {'Votre maître, Caedmos de l\'Exodar, a demandé à vous voir. C\'est à propos de votre formation, mais je n\'en sais pas davantage.', },
    {'Parlez à Caedmos à l\'Exodar.', },
  },
  [10933] = {
    'Retour à Lune-d\'Argent',
    {'Votre maître, Aldrae de Lune-d\'Argent, a demandé à vous voir. C\'est à propos de votre formation, mais je n\'en sais pas davantage.', },
    {'Parlez à Aldrae à Lune-d\'Argent.', },
  },
  [10934] = {
    'Retour à Lune-d\'Argent',
    {'Votre maître, Aldrae de Lune-d\'Argent, a demandé à vous voir. C\'est à propos de votre formation, mais je n\'en sais pas davantage.', },
    {'Parlez à Aldrae à Lune-d\'Argent.', },
  },
  [10935] = {
    'L\'exorcisme du colonel Jules',
    {'$N, il est temps de sauver le colonel Jules. Son état a encore empiré et Barada craint qu\'il ne soit perdu si nous ne le purifions pas de cette corruption.|n|nPrenez le chapelet que vous avez récupéré et allez voir l\'anachorète Barada pour entamer le rituel. Faites en sorte que rien n\'interrompe le rituel... et si tout se passe bien, le colonel Jules sera sauvé. Parlez à Jules une fois qu\'il sera sauf, puis revenez me voir.', },
    {'Parlez à l\'Anachorète Barada. Utilisez le chapelet pour l\'aider pendant le rituel, puis parlez au Colonel Jules quand il sera sauvé. Pour finir, retournez voir l\'Assistant Klatu.', },
  },
  [10936] = {
    'Trollemort vous cherche !',
    {'Pendant que nous étions occupés, un messager attendait dans l\'entrée. Je suppose qu\'il a fini par fatiguer, ou peut-être qu\'il a juste pris ses jambes à son cou en voyant Jules flotter à travers la pièce.|n|nQuoi qu\'il en soit, le commandant de corps Danath vous cherche. Je vous suggère de demander une audience dans la caserne aussi vite que possible !', },
    {'L\'Assistant Klatu vous a indiqué que le Commandant de corps Danath Trollemort vous cherchait. Allez lui parler à la caserne du Bastion de l\'Honneur dans la Péninsule des Flammes infernales.', },
  },
  [10937] = {
    'Détruisez le maître de manœuvre',
    {'Je reçois des rapports indiquant que les gangr\'orcs de la Main brisée devant la citadelle des Flammes infernales sont en train de préparer ce qui ressemble à une attaque massive. Nul doute qu\'ils ne sont pas heureux de vos succès contre tous les clans.|n|nRendez-vous à la base de la citadelle, là où s\'achève le sentier de la Gloire. Vous y trouverez les gangr\'orcs occupés à leurs préparatifs, mais vous pourrez les prendre au dépourvu.|n|nÉliminez celui qui est responsable de cette troupe. Tuez le maître de manœuvre Zurok !', },
    {'Le Commandant de corps Danath Trollemort vous a ordonné de tuer au plus vite le Maître de manœuvre Zurok. Retournez voir le commandant de corps au Bastion de l\'Honneur dans la Péninsule des Flammes infernales une fois que le maître de manœuvre sera mort.', },
  },
  [10938] = {
    'Suite de Bénédictions de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Bénédictions, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Bénédictions à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [10939] = {
    'Suite de Tempêtes de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Tempêtes, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Tempêtes à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [10940] = {
    'Suite de Furies de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Furies, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Furies à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [10941] = {
    'Suite de Déraison de Sombrelune',
    {'Maintenant que vous avez rassemblé toutes les cartes de la suite de Déraison, une neuvième carte apparaît mystérieusement, avec le même dos que les huit premières. Cette carte porte l\'inscription « Rapportez ces cartes à la foire de Sombrelune, pour recevoir une récompense. » Vous avez entendu parler de cette foire itinérante, qui s\'arrête en Mulgore et à Comté-de-l\'Or tous les mois.', },
    {'Rapporter la suite de Déraison à la foire de Sombrelune quand elle reviendra en ville.', },
  },
  [10942] = {
    'La Semaine des enfants',
    {'Une petite fille sera très contente de vous avoir comme $Gami:amie;, même si c\'est pour peu de temps...|n|nPrenez ce sifflet. Quand vous l\'utiliserez, vous pourrez appeler l\'enfant que vous avez accepté de parrainer. Le sifflet ne fonctionnera que pendant un temps limité, en fait, durant toute la Semaine des enfants.|n|nJe vous en prie, $N, utilisez le sifflet pour faire la connaissance de votre protégée ! Je suis sûre qu\'elle est très impatiente de vous rencontrer, et d\'avoir l\'occasion de s\'aventurer hors de la ville !', },
    {'Utiliser le Sifflet d\'orphelin elfe de sang pour parler à l\'enfant que vous surveillerez durant la Semaine des enfants.', },
  },
  [10943] = {
    'La Semaine des enfants',
    {'Une petite fille sera très contente de vous avoir comme $Gami:amie;, même si c\'est pour peu de temps...|n|nPrenez ce sifflet. Quand vous l\'utiliserez, vous pourrez appeler l\'enfant que vous avez accepté de parrainer. Le sifflet ne fonctionnera que pendant un temps limité, en fait, durant toute la Semaine des enfants.|n|nJe vous en prie, $N, utilisez le sifflet pour faire la connaissance de votre protégée ! Je suis sûre qu\'elle est très impatiente de vous rencontrer, et d\'avoir l\'occasion de s\'aventurer hors de la ville !', },
    {'Utiliser le Sifflet d\'orphelin draeneï pour parler à l\'enfant que vous surveillerez durant la Semaine des enfants.', },
  },
  [10944] = {
    'Un secret compromis',
    {'Merci encore, $N. Je reconnais votre nom. Akama vous a $Gmis:mise; dans la confidence de son plan, et je vais donc vous faire confiance à mon tour.|n|nLes nagas ont découvert que je m\'activais contre Illidan et ont tenté de me faire parler par la torture. Mais je ne leur ai pas lâché un mot. Akama lui-même m\'a enseigné la maîtrise de la douleur par la méditation.|n|nIllidan a demandé aux nagas de m\'amener à lui. Il aurait percé ma chair à jour jusqu\'aux secrets les plus profonds de mon âme.|n|nAkama doit être averti. Notre plan est menacé !', },
    {'Allez à la Cage de la gardienne dans la vallée d\'Ombrelune et parlez avec Akama.', },
  },
  [10945] = {
    'Hch\'uu et le peuple champignon',
    {'J\'avais une amie nommée Hch\'uu. Elle m\'a dit qu\'elle s\'est retrouvée à l\'orphelinat parce qu\'elle s\'était enfuie pour échapper à un méchant géant fongique, et qu\'elle s\'était perdue.|n|nOn s\'est beaucoup amusées jusqu\'à ce que sa famille vienne et la remmène l\'année dernière. Je crois qu\'elle a dit qu\'elle allait vivre dans un endroit appelé Sporeggar.|n|nJ\'aimerais bien lui rendre visite et aussi voir son village de champignons. La directrice de l\'orphelinat m\'a dit qu\'il se trouvait à l\'ouest du marécage de Zangar, entre le lac Ventespore et le lac des Furoles.|n|nOn peut y aller ? Dites, on peut y aller ?! S\'il vous plaît…', },
    {'Emmenez votre orpheline, Salandria, à Sporeggar dans le marécage de Zangar. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez. Puis aller parler à Hch\'uu.', },
  },
  [10946] = {
    'La ruse des Cendrelangues',
    {'Le sacrifice d\'Olum est un acte sublime. Moi-même, je ne lui aurais jamais demandé de donner sa vie. Mais il l\'a fait, maintenant.|n|nSi nous voulons faire croire à Illidan qu\'il est en sécurité, nous devons suivre ses ordres - pour l\'instant tout au moins.|n|nJe suis à la tête d\'une grande armée de Cendrelangues mais, hormis les ligemorts, personne n\'est digne de confiance.|n|nVous devez agir comme Illidan l\'exige. Prenez cette capuche, c\'est un objet magique. Vous paraîtrez être l\'un de mes hommes pour quiconque vous verra tuer le phénix de Kael, Al\'ar.', },
    {'Pénétrez dans le Donjon de la Tempête et tuez Al\'ar en portant la Capuche de Cendrelangue. Retournez voir Akama dans la Vallée d\'Ombrelune une fois que ce sera fait.', },
  },
  [10947] = {
    'Un artéfact du passé',
    {'Illidan se concentre désormais sur Kael\'thas, grâce à vous. Le moment est venu de passer à l\'action.|n|nJ\'ai eu la vision d\'un artéfact qui nous aidera dans notre combat final - le phylactère d\'une liche connue sous le nom de Froidhiver. Malheureusement, sa puissance a été perdue lors de la défaite de cette liche à la bataille du mont Hyjal.|n|nMais il existe peut-être un moyen de récupérer cet artéfact. La légende parle d\'un endroit en Azeroth gardé par des dragons de bronze... un endroit où le passé et le présent se rejoignent. C\'est là que vous trouverez ce que nous cherchons.', },
    {'Allez aux Grottes du temps en Tanaris, et rendez-vous à la Bataille du mont Hyjal. Quand vous y serez, triomphez de Rage Froidhiver et rapportez le Phylactère chronophasé à Akama dans la vallée d\'Ombrelune.', },
  },
  [10948] = {
    'L\'âme otage',
    {'Vous vous demandez peut-être pourquoi je me donne autant de mal pour dissimuler mes intentions. Pourquoi ne pas ouvertement prendre parti pour les naaru ?|n|nTout ce qui fait mon être, mon âme même, est prisonnier dans le Temple noir. Illidan n\'avait qu\'à souhaiter ma mort pour me tuer en un instant... jusqu\'à maintenant ! Ce phylactère va me permettre de reprendre le contrôle de mon âme.|n|nL\'heure est venue, $N. Je vais conduire Maiev et mes ligemorts aux portes d\'Illidan.|n|nAllez voir A\'dal et expliquez-lui notre plan. Si nous frappons ensemble, nous pourrons passer les protections d\'Illidan.', },
    {'Rendez-vous à Shattrath pour soumettre la requête d\'Akama à A\'dal.', },
  },
  [10949] = {
    'L\'entrée dans le Temple noir',
    {'<A\'dal vous montre une image d\'un naaru aux portes du Temple noir, combattant aux côtés de redresseurs de torts draeneï et de magistères elfes de sang. Vous comprenez immédiatement qu\'il s\'agit là de la diversion qu\'attend Akama.>', },
    {'Rendez-vous à l\'entrée du Temple noir dans la vallée d\'Ombrelune et allez parler à Xi\'ri.', },
  },
  [10950] = {
    'Auchindoun et le Cercle d\'observance',
    {'Un des prêtres qui vient nous voir des fois nous a raconté une histoire sur un endroit qui n\'est pas loin. Ça s\'appelle Auchindoun, et c\'est censé être très important pour les draeneï.|n|nIl disait que c\'est là que les corps des draeneï étaient emportés quand ils mouraient. Mais qu\'il y a longtemps, un truc méchant a tout fait exploser.|n|nJ\'aimerais bien voir le Cercle d\'observance, là-bas. La gouvernante de l\'orphelinat m\'a dit que c\'est au milieu du désert des Ossements, du côté sud de la forêt de Terokkar.|n|nS\'il vous plaît, $Gmonsieur:madame; $N, on peut y aller ?', },
    {'Emmenez votre orpheline, Dornaa, à la Pierre de rencontre du Cercle d\'observance, au centre d\'Auchindoun. Auchindoun est situé au centre du désert des Ossements de la forêt de Terokkar. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.', },
  },
  [10951] = {
    'Une visite à la Porte des ténèbres',
    {'Comment est-ce qu\'on peut aller voir tout plein d\'endroits intéressants et oublier la Porte des ténèbres ?!|n|nLes adultes essaient toujours de nous faire peur en nous racontant plein d\'histoires dessus, avec des démons et tout.|n|n<Salandria roule des yeux.>|n|nMais vous êtes là, donc ça ne va pas si mal se passer, hein ?|n|nJe veux voir ça de mes propres yeux. Vous vous souvenez où c\'est, à l\'est de la péninsule des Flammes infernales ?', },
    {'Emmenez votre orpheline, Salandria, en haut de l\'escalier du Destin, pour qu\'elle puisse passer devant la Porte des ténèbres dans la péninsule des Flammes infernales. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.', },
  },
  [10952] = {
    'Une visite à la Porte des ténèbres',
    {'Il y a un endroit qu\'il faut aller voir avant tous les autres, c\'est la Porte des ténèbres !|n|nLes gouvernantes de l\'orphelinat essaient toujours de nous faire peur en nous racontant des histoires et en disant que c\'est très dangereux, avec plein de démons et des gens comme vous qui traversent la porte.|n|n<Dornaa roule des yeux.>|n|nMais vous êtes là, et vous êtes $Ggentil:gentille;, donc ça ne va pas si mal se passer, hein ?|n|nJe veux voir ça de mes propres yeux. Vous vous souvenez où c\'est, à l\'est de la péninsule des Flammes infernales ?', },
    {'Emmenez votre orpheline, Dornaa, en haut de l\'escalier du Destin pour qu\'elle passe devant la Porte des ténèbres dans la péninsule des Flammes infernales. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.', },
  },
  [10953] = {
    'Une visite au Trône des éléments',
    {'Vous avez entendu parler du Trône des éléments ? On dit que c\'est un endroit de Nagrand où il y a des élémentaires très forts.|n|nUn jour, bientôt, je serai une grande mage, ou alors une démoniste. Il va falloir que j\'apprenne des trucs sur les forces des éléments !|n|nVous pensez qu\'on pourrait y aller ?|n|n<Salandria vous lance un regard rusé.>|n|nVous savez, ça serait très éducatif d\'aller là-bas. Il paraît que c\'est juste au nord de Garadar, de l\'autre côté du lac Chanteciel.', },
    {'Emmenez votre orpheline, Salandria, au Trône des éléments à Nagrand. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez. Ensuite, allez parler à l\'Élémentaliste Sharvak.', },
  },
  [10954] = {
    'Jheel est au point d\'ancrage Aeris !',
    {'Mon frère Jheel me manque. Il a quelques années de plus que moi, alors ils l\'ont laissé partir en apprentissage chez les éthériens à Nagrand.|n|nCe serait vraiment bien de pouvoir lui rendre visite. Il adore la géologie et tout ça, alors je parie qu\'il s\'amuse bien là-bas.|n|nLa directrice de l\'orphelinat m\'a dit qu\'il étudiait dans un endroit appelé le point d\'ancrage Aeris, à Nagrand. C\'est censé être sur la route, loin à l\'ouest de Telaar, et au nord-ouest de la grande montagne, Oshu\'gun.', },
    {'Emmenez votre orpheline, Dornaa, au Point d\'ancrage Aeris en Nagrand. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez. Ensuite, parlez avec Jheel.', },
  },
  [10955] = {
    'Morthis Murmedaile',
    {'Avant que tous les ordres druidiques ne se réunissent pour former le Cercle cénarien, les druides de la Serre avaient pour charge d\'enseigner aux jeunes druides prometteurs les secrets du vol. Depuis la dissolution de notre ordre, ses anciens membres dispensent leur savoir avec réserve.|n|nÀ ce jour, Morthis Murmedaile est encore à la recherche d\'un apprenti convenable. Peu de druides maîtrisent vraiment toutes les formes qui leur sont accessibles, mais vous semblez avoir le potentiel que Morthis exige de ses élèves. Allez le trouver au Refuge cénarien dans le marécage de Zangar.', },
    {'Allez parler à Morthis Murmedaile au Refuge cénarien dans le marécage de Zangar.', },
  },
  [10956] = {
    'Le Siège du naaru',
    {'Vous savez quelque chose sur les naaru ? C\'est les êtres angéliques qui aident les draeneï depuis vraiment très longtemps. J\'en ai vu un tas à Shattrath.|n|nIl paraît qu\'il y a un naaru, O\'ros, qui était avec l\'Exodar quand il est allé sur votre monde. J\'aimerais bien voir ça.|n|nVous pouvez m\'y emmener ? Je parie qu\'on pourrait aller là-bas très vite avec un des portails du temple de la Lune de Darnassus ! Quand on arrive là-bas, si on se perd, on pourra toujours regarder sur votre carte.', },
    {'Emmenez votre orpheline, Dornaa, voir O\'ros au pied du Siège du naaru dans l\'Exodar, sur l\'île de Brume-azur. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.|n|nRappelez-vous que vous pouvez utiliser votre carte à l\'intérieur de la ville.', },
  },
  [10957] = {
    'La rédemption du Cendrelangue',
    {'Quand Illidan a obtenu l\'allégeance des Roués, Akama était le plus sage d\'entre nous. Il savait que s\'opposer ouvertement au Traître provoquerait l\'extinction de notre race.|n|nIl a préféré comploter et intriguer pour arriver à ce moment ultime, dans le plus grand secret. Un échec serait catastrophique… non seulement pour Akama, non seulement pour les Roués, mais pour tout l\'Outreterre. Personne aussi proche d\'Illidan n\'a jamais été capable de lui délivrer un coup aussi terrible.|n|nAidez Akama à libérer son âme et il vous accordera l\'accès au sanctum d\'Illidan.', },
    {'Aidez Akama à reprendre le contrôle de son âme en vainquant l\'Ombre d\'Akama dans le Temple noir. Retournez voir le Voyant Kanai quand ce sera fait.', },
  },
  [10958] = {
    'À la recherche des Cendrelangues',
    {'<Alors que vous regardez Xi\'ri, votre concentration s\'intensifie et votre volonté s\'affirme. Votre mission ne s\'achève pas ici. Vous devez entrer dans le Temple noir et retrouver les fidèles d\'Akama.>|n|n<Beaucoup de choses dépendent de la réussite d\'Akama.>', },
    {'Trouvez les Ligemorts d\'Akama à l\'intérieur du Temple noir.', },
  },
  [10959] = {
    'La chute du Traître',
    {'Maintenant que les lieutenants d\'Illidan sont vaincus, Akama va pouvoir forcer les portes de son sanctum. Apprêtez-vous à entrer, vous et vos alliés, aussitôt que nous aurons terminé.|n|nNous ne savons toujours pas ce qui est advenu de Maiev, mais nous devons avancer sans elle.|n|nJ\'espère que votre troupe est à la hauteur. Illidan ne sera pas particulièrement heureux de voir Akama.', },
    {'Le voyant Kanai veut que vous vainquiez Illidan à l\'intérieur du Temple noir.', },
  },
  [10960] = {
    'Quand je serai grande…',
    {'Quand vous aviez mon âge, est-ce que vous saviez que vous vouliez être $Gun:une:c; $C quand vous seriez $Ggrand:grande; ?|n|nJe sais pas ce que j\'ai envie d\'être. Peut-être un mage ou un démoniste, comme je vous ai dit avant. Ou peut-être un paladin chevalier de sang ? Ouais, voilà, un chevalier de sang !|n|nOn m\'a dit que les vrais chevaliers de sang étaient entraînés à Lune-d\'Argent, sur votre monde. Vous pouvez m\'emmener là-bas ? J\'ai entendu que les maîtres des paladins vivent sur la place des Pérégrins, dans la ville.|n|nVous voulez pas m\'emmener là-bas, dites. Allez…', },
    {'Emmenez votre orpheline, Salandria, voir les maîtres des paladins sur la Place des Pérégrins, dans Lune-d\'Argent. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez. Ensuite, parlez avec Dame Liadrin, la matriarche des chevaliers de sang.|n|nRappelez-vous que vous pouvez utiliser votre carte à l\'intérieur de la ville, et parler aux gardes pour trouver les maîtres des paladins.', },
  },
  [10961] = {
    'La protection de l\'éveil',
    {'Il y a bien longtemps, les reliques utilisées pour apprendre aux néophytes la voie du corbeau des tempêtes furent confiées à un druide ancien.|n|nVous aurez besoin de ces reliques pour votre apprentissage, nous devons donc réveiller leur gardien.|n|nJe vais vous préparer une potion que vous pourrez utiliser pour faciliter le processus d\'éveil. La mixture nécessite des herbes communes ainsi que des fleurs des tourbières, qui poussent généralement au sommet des plus hauts champignons du marécage. Volez jusqu\'à leurs sommets pour les cueillir, mais faites très attention, elles sont fragiles et peuvent exploser violemment si on s\'y prend mal.', },
    {'Apportez 10 Fleurs des tourbières, 10 Lichens anciens et 10 Glauriers à Morthis Murmedaile, au Refuge cénarien.', },
  },
  [10962] = {
    'Il est temps de visiter les Grottes',
    {'Le vieux prêtre qui vient à l\'orphelinat nous a raconté des histoires sur les Grottes du temps. Il disait qu\'elles se trouvent au centre du temps, et qu\'elles sont très importantes pour que les choses restent droites.|n|nJe ne sais pas ce que ça veut dire, mais il disait aussi qu\'il y a des dragons là-bas qui aident à sauver le monde ! Je veux voir un dragon !|n|nVous pensez qu\'on pourrait y aller ? Il disait que l\'entrée est sur la bordure est d\'un grand désert appelé Tanaris.|n|nVous pourriez peut-être m\'acheter un souvenir quand on sera là-bas ?', },
    {'Emmenez votre orpheline, Dornaa, devant Zaladormu, le dragon qui se trouve sur l\'estrade au milieu des Grottes du temps. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.|n|nEnsuite, achetez-lui une Figurine de dragon auprès de l\'Intendant des Gardiens du temps, Alurmi, près du fond du tunnel d\'entrée.', },
  },
  [10963] = {
    'Il est temps de visiter les Grottes',
    {'Le vieux prêtre puant qui vient à l\'orphelinat nous a raconté des histoires sur les Grottes du temps. Il disait qu\'elles se trouvent au centre du temps, et qu\'elles sont très importantes pour que les choses restent droites.|n|nJe ne sais pas ce que ça veut dire, mais il disait aussi qu\'il y a des dragons là-bas qui aident à sauver le monde ! Je veux voir un dragon !|n|nJe pense qu\'on devrait y aller. Il disait que l\'entrée est sur la bordure est d\'un grand désert appelé Tanaris.|n|nVous pourrez m\'acheter un souvenir quand on sera là-bas !', },
    {'Emmenez votre orpheline, Salandria, devant Zaladormu, le dragon qui se trouve sur l\'estrade au milieu des Grottes du temps. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.|n|nEnsuite, achetez-lui une Figurine de dragon auprès de l\'Intendant des Gardiens du temps, Alurmi, près du fond du tunnel d\'entrée.', },
  },
  [10964] = {
    'Le réveil du dormeur',
    {'Emportez le gardien et allez à Reflet-de-Lune, au refuge des saisons de Malfurion. Vous trouverez Clintar Marcherêve dans le refuge le plus au sud, sous la protection des garderêves.|n|nAdministrez-lui la potion et veillez-le pendant son éveil. Tant que son esprit et son corps ne seront pas complètement réunis, il sera extrêmement vulnérable et il ne vous reconnaîtra probablement pas. Présentez-vous dès qu\'il aura repris conscience, $N. Il aura besoin de votre aide pour rassembler les reliques avant la cérémonie.', },
    {'Utilisez le Gardien de l\'éveil pour aider Clintar Marcherêve à sortir du Rêve d\'émeraude. Une fois qu\'il a repris connaissance, parlez-lui.', },
  },
  [10965] = {
    'Plus qu\'un simple rêve',
    {'<Vous transmettez à Clintar les instructions de Morthis. Il vous écoute en opinant, mais semble visiblement inquiet.>|n|nJe ne peux pas m\'extraire complètement du Rêve d\'émeraude pour vous aider, mais un fragment de mon esprit va vous guider dans votre recherche des reliques. Gardez-le avec soin, $R, car il est très fragile.|n|nLe Rêve d\'émeraude est devenu un endroit étrange et dangereux. Son emprise est forte, et je ne pourrai pas retrouver ma plénitude tant que le Rêve ne sera revenu à la normale. Ce que vous voyez autour de vous n\'est qu\'un écho de la réalité du rêve !', },
    {'Protégez l\'Esprit de Clintar Marcherêve pendant qu\'il recueille les reliques d\'Aviana, puis allez trouver la Garderêve Lurosa.', },
  },
  [10966] = {
    'De retour à l\'orphelinat',
    {'Mince alors ! Je crois que c\'est l\'heure de rentrer à l\'orphelinat de Shattrath.|n|nJe me suis tellement amusée. Vous êtes la personne la plus chouette de tout l\'univers, $N ! Vous êtes $Gmon grand frère:ma grande sœur; maintenant !|n|n<Les yeux de Dornaa commencent à se remplir de larmes.>|n|nVous allez tellement me manquer !!! Quand je serai grande, je veux être exactement comme vous !!!', },
    {'Ramenez votre protégée à l\'orphelinat de Shattrath, en rendant le Sifflet d\'orphelin draeneï à Miss Hérikorde, directrice de l\'orphelinat, dans la Ville basse.', },
  },
  [10967] = {
    'De retour à l\'orphelinat',
    {'Mince alors ! Je crois que c\'est l\'heure de rentrer à l\'orphelinat de Shattrath.|n|nJe me suis tellement amusée. Vous êtes la personne la plus chouette de tout l\'univers, $N ! Vous êtes $Gmon grand frère:ma grande sœur; maintenant !|n|n<Les yeux de Salandria commencent à se remplir de larmes.>|n|nVous allez tellement me manquer !!!', },
    {'Ramenez votre protégée à l\'orphelinat de Shattrath, en rendant le Sifflet d\'orphelin elfe de sang à Miss Hérikorde, directrice de l\'orphelinat, dans la Ville basse.', },
  },
  [10968] = {
    'En visite chez le long-voyant',
    {'Je ressens effectivement quelque chose de très particulier chez cette enfant.|n|nVous devriez l\'emmener en visite chez le long-voyant Nobundo, au sein de l\'Exodar. Je crois qu\'il attend votre arrivée.|n|nVous trouverez Nobundo sur la plus haute terrasse du Hall de cristal.', },
    {'Emmenez votre orpheline, Dornaa, rendre visite au Long-voyant Nobundo dans le Hall de Cristal à l\'intérieur de l\'Exodar, qui se trouve sur l\'Île de Brume-azur. N\'oubliez pas de l\'appeler si elle n\'est pas présente lorsque vous arrivez.|n|nRappelez-vous que vous pouvez consulter votre carte même à l\'intérieur de la ville.', },
  },
  [10969] = {
    'Rechercher Ameer',
    {'Il semblerait qu\'une force extérieure s\'intéresse aux pratiques commerciales du Consortium. Cinq négociants du Consortium ont été portés disparus dans les deux derniers jours. Nous avons des raisons de croire que l\'Ethereum est impliqué. Si vous souhaitez nous apporter votre aide, allez trouver le Commandant Ameer au poste de garde du Protectorat.|n|nLe poste se situe directement à l\'est d\'ici, sur la prochaine île.', },
    {'Trouvez le Commandant Ameer au Poste de garde du Protectorat.', },
  },
  [10970] = {
    'Une mission miséricordieuse',
    {'Nous avons récupéré cet orbe d\'emprisonnement lors de notre dernière mission de reconnaissance dans le territoire de l\'Ethereum. Nous ne l\'aurions jamais trouvé s\'il n\'avait pas émis un faible signal de détresse.|n|nNous pensons que l\'un des nôtres pourrait être enfermé dedans, mais nous n\'avons aucun moyen d\'ouvrir l\'orbe sans faire de mal à ce qu\'il contient, quoi que ce soit.|n|nNous avons une certitude au sujet de l\'Ethereum, c\'est qu\'à un moment donné n\'importe lequel de ses membres est susceptible d\'avoir sur lui une clé qui permette d\'ouvrir l\'orbe. Trouvez-en une et revenez me voir, afin que nous puissions percer les mystères de cette prison.', },
    {'Procurez-vous la Clé de la prison de l\'Ethereum récupérée pour le Commandant Ameer au Poste de garde du Protectorat.', },
  },
  [10971] = {
    'Secrets de l\'Ethereum',
    {'<Ameer vous montre une plaquette.>|n|nJ\'ai trouvé cette plaque d\'identité de prisonnier parmi les restes de l\'avant-garde. Je ne peux qu\'en déduire que tous leurs prisonniers sont marqués de cette manière.|n|nJe vais commencer à trier les plaques, dans l\'espoir de comprendre leur système pénal. Si, au cours de vos aventures, vous trouvez d\'autres clés de prison de l\'Ethereum, vous pourrez les utiliser pour ouvrir les cellules du Lieu de rassemblement de l\'Ethereum, directement au sud d\'ici. Rapportez-moi toutes les plaques d\'identité que vous recueillerez.', },
    {'Le Commandant Ameer, au Poste de garde du Protectorat au Raz-de-Néant, veut que vous lui apportiez une Plaque d\'identité de prisonnier de l\'Ethereum.', },
  },
  [10972] = {
    'Répertorier les prisonniers de l\'Ethereum',
    {'Il me faut plus de plaques d\'identité, $N. Pour l\'instant, j\'ai découvert qu\'il ne s\'agit pas seulement d\'un moyen de recenser les prisonniers, mais aussi d\'en indiquer la localisation !|n|nUne fois le code décrypté, nous pourrons déterminer exactement où nos alliés sont retenus et les libérer avec le minimum de réaction hostile.', },
    nil,
  },
  [10973] = {
    'Un millier de mondes',
    {'J\'ai percé le code ! Chaque plaque est divisée en plusieurs segments. Le côté face de la plaque est toujours le même, et dit : « Un millier de mondes… ». Je ne suis pas très sûr du sens de cette phrase, mais elle me semble insidieuse.|n|nDe l\'autre côté de la plaque, on trouve les statistiques vitales. La première série de runes indique l\'emplacement, et la seconde le type de prisonnier. De plus, il semblerait que les clés puissent être combinées pour former une clé spéciale qui donne accès à un autre type de prison. J\'ai donc besoin de plus de clés…', },
    {'Le Commandant Ameer, au Poste de garde du Protectorat au Raz-de-Néant, veut que vous lui apportiez 5 Clés de la prison de l\'Ethereum.', },
  },
  [10974] = {
    'Les chambres de stase de Bash\'ir',
    {'L\'Ethereum possède un camp appelé le point d\'ancrage de Bash\'ir, sur un plateau à l\'extrême-nord des Tranchantes. D\'après la tablette, il y a dans ce camp de plus grandes versions des prisons. Il faut aussi noter que l\'Ethereum décrit ces prisons comme des chambres de stase.|n|nLa tablette-clé ouvre l\'accès à une chambre bien particulière, du nom de chambre de stase alpha. Prenez la clé, et allez mener votre enquête.|n|nMon image attendra votre retour au point d\'ancrage de Bash\'ir. Venez m\'y parler.', },
    {'Utilisez la Tablette-clé de l\'Ethereum - Alpha pour ouvrir la Chambre de stase alpha au Point d\'ancrage de Bash\'ir dans les Tranchantes.|n|nRapportez les Indices de l\'alpha à l\'Image du commandant Ameer au Point d\'ancrage de Bash\'ir.', },
  },
  [10975] = {
    'La purge des chambres de Bash\'ir',
    nil,
    nil,
  },
  [10976] = {
    'La Marque du roi-nexus',
    {'Ce que je dois maintenant découvrir, c\'est ce que l\'Ethereum dissimule dans les Tombes-mana d\'Auchindoun.|n|nLors de vos batailles contre les bêtes des chambres de stase de Bash\'ir, vous tomberez peut-être sur un objet appelé la marque du roi-nexus. Si vous veniez à trouver cet objet, rapportez-le-moi sur-le-champ ! C\'est la dernière pièce qu\'il me manque pour forger une clé qui permettra d\'accéder à la chambre de stase située dans les Tombes-mana.', },
    {'L\'Image du commandant Ameer au Point d\'ancrage de Bash\'ir dans les Tranchantes vous demande de lui rapporter une Marque du roi-nexus.', },
  },
  [10977] = {
    'Les chambres de stase des Tombes-mana',
    {'La marque du roi-nexus que vous avez récupérée m\'a permis de forger une nouvelle clé pour les chambres de stase situées dans les Tombes-mana.|n|nD\'après les glyphes qui figurent sur la marque, il en existe deux : une près de l\'entrée, et une autre près du prince-nexus Shaffar. Cette clé que je vais vous confier vous donnera accès à la première.|n|nJe vous demande d\'aller aux Tombes-mana d\'Auchindoun et d\'ouvrir la chambre de stase des Tombes-mana.', },
    {'L\'Image du commandant Ameer au Point d\'ancrage de Bash\'ir dans les Tranchantes vous demande d\'utiliser la Clé de la chambre de stase des Tombes-mana dans les Tombes-mana d\'Auchindoun.|n|nCette quête ne peut être accomplie qu\'au niveau de difficulté Héroïque.', },
  },
  [10978] = {
    'Retourner voir Morthis Murmedaile',
    {'Maintenant que nous avons récupéré les reliques, vous devez vous dépêcher de partir d\'ici. Clintar a risqué sa vie et celle des garderêves pour vous aider, $N, mais il doit maintenant consacrer toute son énergie au combat contre la puissance qui a envahi le Rêve d\'émeraude.|n|nRapportez les reliques à Morthis Murmedaile, et expliquez-lui ce que vous avez vu ici. Il pourra peut-être nous aider à identifier la force qu\'affronte Clintar.', },
    {'Apportez les Reliques d\'Aviana à Morthis Murmedaile au Refuge cénarien dans le marécage de Zangar.', },
  },
  [10979] = {
    'En route pour le Bosquet éternel',
    {'Êtes-vous $Gsûr:sûre; d\'avoir bien aperçu un corbeau dans le refuge des saisons ?|n|nVoilà qui est troublant. Nous ne pouvons pas faire grand-chose pour aider Clintar et les garderêves directement, mais si nous pouvons en apprendre plus sur ce qui menace le Rêve d\'émeraude, nous pourrons peut-être y mettre un terme.|n|nNous recevons des rapports qui font état d\'une résurgence d\'un ancien culte arakkoa dans les Tranchantes. Il s\'agit du culte d\'un dieu corbeau. Rendez-vous au Bosquet éternel, et allez trouver Arthorn Chant-du-vent. Il existe peut-être un lien entre ce qui se passe là-bas et dans le Rêve d\'émeraude !', },
    {'Allez parler à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes.', },
  },
  [10980] = {
    'Le Livre du Corbeau',
    {'D\'après ce que vous me dites, les soupçons de Morthis semblent plausibles, mais nous avons besoin de certitudes.|n|nAu cours de ses recherches, Timeon a découvert des indices de l\'existence d\'un « livre du corbeau » qui aurait servi de recueil d\'écritures sacrées aux arakkoa.|n|nLes esprits arakkoa ne se révèleront pas à vos yeux. Emportez cette pierre sur les hauts pics de l\'ouest des Tranchantes, au sud du Bois aux corbeaux, procurez-vous un œil de raie de l\'éther, et combinez-les pour améliorer votre vue. Cherchez le fantôme que Timeon a identifié comme Sai\'kkal l\'Ancien.', },
    {'Utilisez un Œil de raie de l\'éther avec votre Pierre de prophète pour voir les fantômes du culte du corbeau. Cherchez l\'esprit de Sai\'kkal l\'Ancien dans la Cime du vortex et interrogez-le au sujet du livre du corbeau, puis retournez auprès d\'Arthorn Chant-du-vent.', },
  },
  [10981] = {
    'La chambre personnelle du prince-nexus Shaffar',
    nil,
    nil,
  },
  [10982] = {
    'L\'œil d\'Haramad',
    nil,
    nil,
  },
  [10983] = {
    'Mog\'dorg le Ratatiné',
    {'Mog\'dorg être sage ! Lui envoyer Grok à la ville, chercher l\'aide. Clan Masse-sanglante avoir besoin d\'aide.|n|nMog\'dorg dire, moi envoyer lui puissantes petites créatures. Lui dans Tranchantes, dans tour du Cercle de sang. Mog\'dorg être sage !', },
    {'Allez voir Mog\'dorg le Ratatiné au sommet de l\'une des tours qui se trouvent devant le Cercle de sang dans les Tranchantes.', },
  },
  [10984] = {
    'Parler avec l\'ogre',
    {'<La voix de V\'eru emplit votre esprit de son ton d\'une clarté cristalline.>|n|nIl y a un ogre dans la Ville basse, qui implore l\'aide des passants. Mais ils sont tous restés sourds à sa détresse.|n|nPensez-vous pouvoir l\'aider ?|n|nSon nom est Grok, et il est assis près des marchands, au sud-est.|n|nMerci, $N.', },
    {'Allez voir l\'Ogre, Grok, dans le quartier de la Ville basse de Shattrath.', },
  },
  [10985] = {
    'Une distraction pour Akama',
    {'<Xi\'ri émet une lumière scintillante tandis que les forces de l\'Aldor et des Clairvoyants qui l\'entourent mettent ses ordres à exécution. Son armée est prête à faire reculer les troupes d\'Illidan et à faire diversion pour Akama. Le naaru attend votre demande pour lancer l\'attaque.>', },
    {'Assurez-vous qu\'Akama et Maiev pénètrent bien dans le Temple noir de la Vallée d\'Ombrelune une fois que les forces de Xi\'ri auront fait diversion.', },
  },
  [10986] = {
    'Des yeux dans le ciel',
    {'Localiser les fragments du Livre du Corbeau, s\'ils ne sont pas détruits, sera bien difficile. Notre meilleur espoir est de faire appel à des yeux plus perçants que les vôtres.|n|nDans l\'ouest de Nagrand, sur la bordure est de la crête du Crépuscule, la gardienne Elaira étudie les diverses espèces d\'oiseaux de la faune locale. Allez la trouver, et voyez si elle peut vous aider à mettre à contribution l\'acuité visuelle des oiseaux.', },
    {'Allez parler à la Gardienne Elaira sur la Crête du Crépuscule, en Nagrand.', },
  },
  [10987] = {
    'La chasse à la crécerelle',
    {'Les crécerelles sauvages de Nagrand ont la vue la plus perçante de tous les oiseaux de proie de la région. Mais à cause de leur petite taille, elles ont été chassées de la plupart des zones par les grands venterocs.|n|nEn général, les crécerelles font leurs nids ici, sur la crête du Crépuscule. Si vous réussissez à en attraper une, je la dresserai à dénicher les fragments de votre tablette.|n|nMais ce ne sera pas facile. Les crécerelles sont très craintives, et s\'enfuiront à votre approche. je vous suggère d\'en bloquer une dans un coin, ou d\'approcher $Gcamouflé:camouflée; pour arriver à portée de lancer votre filet.', },
    {'Utilisez le Filet à crécerelles pour capturer une Crécerelle sauvage, et ramenez-la à la Gardienne Elaira sur la Crête du Crépuscule.', },
  },
  [10988] = {
    'Les pierres du Corbeau',
    {'J\'ai dressé votre crécerelle à répondre à un sifflement bien précis. Quand il en entendra le son, l\'oiseau vous rejoindra et vous guidera vers le fragment de tablette le plus proche. Arthorn nous a fait savoir que les fragments que vous cherchez sont enterrés dans la région de Skettis, au sud-est de la forêt de Terokkar, c\'est donc là que l\'oiseau vous attendra.|n|nQuand vous aurez trouvé toutes les pierres, rendez le sifflet à Arthorn et elle s\'occupera de libérer l\'oiseau dans de bonnes conditions.|n|nPassez le bonjour à Arthorn de ma part quand vous la verrez.', },
    {'Rassemblez 8 Pierres du Corbeau à Skettis et apportez-les à Arthorn Chant-du-vent au Bosquet éternel dans les Tranchantes.', },
  },
  [10989] = {
    'Mog\'dorg le Ratatiné',
    {'Mog\'dorg le Ratatiné vous attend au sommet d\'la tour. Il m\'a dit de rechercher $Gun:une:r; $R $C. C\'est vous, ça ! Vous devez aller le voir pour parler de choses importantes.|n|nAllez-y, mais dites rien à personne. C\'est un secret !', },
    nil,
  },
  [10990] = {
    'L\'essence de l\'aigle',
    {'Le Livre du Corbeau nous dit que ses fidèles avaient capturé et enchaîné les esprits de trois oiseaux rivaux dans de petits autels de pierre. Un gardien fut assigné à chaque autel, pour empêcher que les ennemis du Corbeau ne viennent délivrer les esprits.|n|nLe premier de ces autels est celui de l\'esprit de l\'Aigle. Il se trouve dans les collines au sud du lac Jorune et à l\'ouest du fort des Brise-pierres dans la forêt de Terokkar.|n|nLa tablette dit que l\'aigle s\'est battu avec bravoure, mais qu\'il a été submergé par le nombre de ses ennemis. L\'armure et l\'endurance de votre forme d\'ours conviennent bien à un tel combat.', },
    {'Terrassez le Gardien de l\'Aigle et emparez-vous de l\'Essence de l\'Aigle. Utilisez le Sifflet à crécerelle d\'Arthorn pour appeler la Crécerelle d\'Arthorn afin de transmettre la nouvelle de votre succès.|n|nSi vous perdez le Sifflet à crécerelle d\'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer.', },
  },
  [10991] = {
    'L\'essence de l\'épervier',
    {'<L\'oiseau parle avec la voix d\'Arthorn.>|n|nLe deuxième esprit enchaîné par les disciples du corbeau était l\'Épervier.|n|nIl a été vaincu et emprisonné près de Skettis, pour que les prêtres-corbeaux ne l\'oublient pas tant qu\'ils détiendraient le pouvoir.|n|nVous trouverez l\'autel de l\'épervier sur la rive du lac Ere\'Noru, au nord-ouest de Skettis.|n|nPour vaincre son gardien, vous devrez utiliser les forces de l\'épervier à votre avantage. Employez la vitesse et la grâce de votre forme de félin pour le battre avant qu\'il n\'atteigne le sommet de sa force !', },
    {'Terrassez le Gardien de l\'Épervier et emparez-vous de l\'Essence de l\'Épervier. Utilisez le Sifflet à crécerelle d\'Arthorn pour appeler la Crécerelle d\'Arthorn afin de transmettre la nouvelle de votre succès.|n|nSi vous perdez le Sifflet à crécerelle d\'Arthorn, retournez voir Arthorn Chant-du-vent au Bosquet éternel pour le faire remplacer.', },
  },
  [10992] = {
    'L\'essence du faucon',
    {'<La voix d\'Arthorn s\'adresse à vous.>Le dernier des esprits dont parle le Livre du Corbeau, qui est aussi le plus puissant, est celui du faucon. Il a été emprisonné loin de Skettis, dans un autel se trouvant sur une île isolée au sud-est d\'Auchindoun.|n|nJe pense que la description correspond à l\'île que nous appelons la halte Aile-du-chagrin.|n|nLa tablette dit que le gardien du faucon était quasiment invulnérable aux attaques des serres de l\'oiseau. Pour ce combat, renoncez aux attaques physiques au profit de la magie. Ne répétez pas l\'erreur du faucon.', },
    {'Terrassez le Gardien du Faucon et apportez l\'Essence du faucon à Arthorn Chant-du-vent au Bosquet éternel.', },
  },
  [10993] = {
    'Le retour au Refuge cénarien',
    {'Apportez les essences à Morthis Murmedaile, et exposez-lui nos découvertes sur le dieu corbeau.|n|nLui mieux que quiconque saura faire usage des essences et de ces informations pour débusquer Anzu. Hâtez-vous d\'y aller, nous ne savons pas combien de temps Clintar et les garderêves pourront tenir face aux assauts du corbeau !|n|n<Arthorn pose sa main sur votre bras avant que vous ne vous retourniez pour partir.>|n|nS\'il vous plaît, $N, dites à Morthis à quel point je vous ai $Gaidé:aidée;. Je crains que mon rôle dans l\'accomplissement de ces travaux ne lui échappe !', },
    {'Apportez le Colis d\'Arthorn à Morthis Murmedaile au Refuge cénarien.', },
  },
  [10994] = {
    'La chasse à la pierre de lune',
    {'Si l\'on combine les essences avec une gemme rare appelée pierre de lune de Furie-du-Sud, il sera possible d\'en déchaîner la puissance quand vous serez $Gprêt:prête; à défier Anzu.|n|nLe seul problème, c\'est qu\'on ne trouve ces gemmes que sur la rive du fleuve qui se trouve en Azshara, sur les falaises près de sa source.|n|nLe dernier groupe d\'elfes de la nuit qui est parti en chercher a connu un sort tragique. Leur bateau est toujours ancré dans le fleuve, près de l\'endroit où ils ont aperçu la pierre de lune. Gardez les yeux bien ouverts et approchez de ce site par la terre depuis Azshara.', },
    {'Apportez une Pierre de lune de Furie-du-Sud à Morthis Murmedaile au Refuge cénarien.', },
  },
  [10995] = {
    'Grulloc a deux crânes',
    {'À l\'est, tout au bout de la Fin des dragons, se trouve le Creux maudit. Grulloc, fils de Gruul, y élabore ses plans simplistes.|n|nOn raconte qu\'une de ses possessions lui a été dérobée par la ruse, était-ce votre œuvre ? Dommage qu\'il n\'ait pas été tué à cette occasion.|n|nSi nous voulons retrouver la liberté, je dois vous demander de vous emparer de son trésor le plus cher : un crâne de dragon datant de l\'époque où il avait le plaisir de voir son père décimer le Vol noir. Le seul moyen de lui prendre le crâne est de le terrasser.', },
    nil,
  },
  [10996] = {
    'Le coffre au trésor de Maggoc',
    {'Maggoc patrouille sur la Tranchecrête, un peu plus haut, au sud-est. Son père lui a confié la tâche de veiller sur la partie est de la chaîne de montagnes, et il adore terroriser toutes les créatures qui croisent son chemin.|n|nC\'est un fils de Gruul, il faut se débarrasser de lui si mon clan veut avoir une chance de survie. Et c\'est là que vous entrez en jeu.|n|nMaggoc a toujours sur lui un coffre à trésor. Prouvez-moi que vous l\'avez tué en me rapportant ce coffre. N\'hésitez pas à garder ce que vous y trouverez.', },
    nil,
  },
  [10997] = {
    'L\'étendard et la manière',
    {'Connaissez-vous bien Shattrath, $C ? Au-dessus de la ville, vers le nord-ouest, se trouve un endroit appelé la Barrière. Il n\'est accessible qu\'à dos de monture volante.|n|nSkori, l\'un des fils de Gruul, s\'y est exilé et a pris la tête des ogres gordunni qui y résident. Même s\'il est loin, nous ne pouvons pas nous permettre de le laisser en vie, ou il reviendra quand le dernier de ses frères aura été tué.|n|nIl faut que vous y alliez, $N. Rapportez-moi son étendard comme preuve de sa mort.', },
    nil,
  },
  [10998] = {
    'Le tome de sa voix',
    nil,
    nil,
  },
  [10999] = {
    'Faire mouche',
    {'Rapportez-moi 8 Dents de pierre.', },
    {'Rapportez-moi 8 Dents de pierre.', },
  },
  [11000] = {
    'Face au Broyeur-d\'âme',
    {'Le grimoire est la clé de la chute de Crânoc.|n|nLisez à haute voix le livre au refuge du Broyeur-d\'âme pour déclencher le rituel. Cela fera apparaître l\'objet appelé le Broyeur-d\'âme, et aussi les fantômes des victimes de Crânoc, qui tenteront de le détruire. Vous devez les en empêcher pendant suffisamment longtemps pour forcer Crânoc à venir complètement dans notre monde.|n|nVous trouverez le refuge en partant vers le nord par le canyon des Crocs-lames, de l\'autre côté du Cercle de sang. Il se trouve sur la droite, avant le repaire de Gruul.|n|nRevenez avec l\'âme de Crânoc.', },
    nil,
  },
  [11001] = {
    'Triompher du dieu corbeau',
    {'Nous devons nous occuper du dieu corbeau sans perdre de temps. Vous devez emporter la pierre de lune imprégnée d\'essence dans un lieu de grand pouvoir pour attirer le dieu hors de la sécurité relative du Rêve d\'émeraude.|n|nDescendez dans les salles des Sethekk et placez la pierre de lune dans la serre du corbeau. Vous la trouverez dans la chambre devant la salle du roi-serre.|n|nIl faut qu\'Anzu soit convaincu que ses serviteurs se sont rassemblés pour accueillir son retour en ce monde. Dès qu\'il se sera manifesté, ne lui faites pas de quartier !', },
    {'Tuez le Dieu corbeau et retournez voir Morthis Murmedaile au Refuge cénarien.|n|nCette quête doit être accomplie en mode de difficulté du donjon Héroïque.', },
  },
  [11002] = {
    'La chute de Magtheridon',
    {'L\'origine de l\'armée gangr\'orc de Hurlorage est vaincue. La manufacture a cessé sa sinistre production, au moins pour le moment. Il n\'en reste que ces quelques babioles et cette tête tranchée, un trophée digne d\'un héros de l\'Alliance.|n|nApportez la tête de Magtheridon à Danath Trollemort au bastion de l\'Honneur.', },
    {'Rapportez la Tête de Magtheridon au Commandant de corps Danath Trollemort au bastion de l\'Honneur dans la péninsule des Flammes infernales.', },
  },
  [11003] = {
    'La chute de Magtheridon',
    {'L\'origine de l\'armée gangr\'orc de Hurlorage est vaincue. La manufacture a cessé sa sinistre production, au moins pour le moment. Il n\'en reste que ces quelques babioles et cette tête tranchée, un trophée digne d\'un héros de la Horde.|n|nApportez la tête de Magtheridon à Nazgrel, à Thrallmar.', },
    {'Rapportez la Tête de Magtheridon à Nazgrel à Thrallmar dans la péninsule des Flammes infernales.', },
  },
  [11004] = {
    'Un monde d\'ombres',
    {'Le commandant Adaris de la Garde-ciel a été grièvement blessé durant une incursion à Skettis. Depuis, il ne reprend conscience que par intermittence.|n|nJ\'ai bien peur qu\'il ne délire sous l\'influence de la fièvre. Durant ses brefs moments de lucidité, il exige que je prépare un élixir à partir de la poussière ombreuse que possèdent les arakkoa. Il semble croire que cela lui permettra de voir « dans le monde des ombres » où vivent les véritables chefs des arakkoa.|n|nJe ne crois pas une seconde à toutes ces idioties, mais je crains qu\'il ne se repose pas tant que je n\'aurai pas obtenu cet élixir. Vous voulez bien m\'aider ?', },
    {'Séverin souhaite que vous vous aventuriez dans Skettis et que vous récupériez 6 Poussières ombreuses sur les arakkoa qui s\'y trouvent.', },
  },
  [11005] = {
    'Les secrets des prêtres de la Serre',
    {'Merci d\'avoir prêté attention à mes délires fiévreux. Depuis le début, nous avons cherché à identifier et détruire la chaîne de commandement de Skettis ; nous avons appris l\'existence de trois clercs, appelés les prêtres de la serre, mais nous ne les avions jamais vus de nos propres yeux. Nous savons à présent pourquoi.|n|nParlez à Séverin pour recevoir plus de l\'élixir qu\'il a découvert. Utilisez l\'élixir pour trouver et tuer les trois prêtres de la serre : Ishaal, Skizzik et Zellek. La rumeur dit qu\'ils résident au Voile Ala\'rak, près de la côte est du lac Noirvent.', },
    {'Procurez-vous un Élixir des ombres auprès de Séverin et utilisez-le pour trouver et tuer le Prêtre de la serre Ishaal, le Prêtre de la serre Skizzik et le Prêtre de la serre Zellek à Skettis. Retournez voir le commandant Adaris lorsque vous aurez accompli cette tâche.', },
  },
  [11006] = {
    'Plus de poussière ombreuse',
    nil,
    nil,
  },
  [11007] = {
    'Kael\'thas et la sphère verdoyante',
    {'L\'air résonne autour de vous, d\'un écho très doux. Les naaru ont perçu votre victoire. Voilà peut-être pourquoi vous vous êtes $Gsenti poussé:sentie poussée; à prendre cette sphère sur les restes encore agités de convulsions de Kael\'thas Haut-Soleil. Quels secrets peut-elle bien détenir ?|n|nPeut-être qu\'A\'dal, à Shattrath, comprendra ce dont il s\'agit.', },
    {'Apportez la Sphère verdoyante à A\'dal dans Shattrath.', },
  },
  [11008] = {
    'Un déluge de feu sur Skettis',
    {'Vous pensez que vous avez ce qu\'il faut pour entrer dans la Garde-ciel ? Voyons voir ce que vous valez dans les airs…|n|nLes arakkoa sont en train de créer une variété gigantesque de leurs familiers d\'attaque, et les utilisent contre nos éclaireurs. Je veux que vous emportiez ces détonateurs et que vous les utilisiez pour détruire les couvoirs qui se trouvent au-dessus des habitations des arakkoa. Évitez les kaliris monstrueux qui gardent les couvoirs. Ils vous feront tomber de votre monture avant même que vous sachiez ce qui vous a frappé.', },
    {'Cherchez les Œufs de kaliri monstrueux au sommet des habitations de Skettis, et utilisez les Détonateurs de la Garde-ciel pour les détruire. Revenez voir ensuite le Sergent Doryn de la Garde-ciel.', },
  },
  [11009] = {
    'Le paradis des ogres',
    {'Maintenant que vous nous avez délivrés du joug de nos opresseurs, nous pouvons commencer à travailler à la réunification des clans. Cela prendra du temps : les vieilles rancœurs sont difficiles à faire oublier.|n|nMais il y a plus urgent : vous devez vous rendre à Ogri\'la, dans le ciel, à l\'ouest. Vous devez la défendre, et nous défendre, des forces célestes desquelles les gronns nous protégeaient : éthériens, démons et, pire que tout, le Vol noir.|n|nQuand vous aurez trouvé le paradis des ogres, recherchez le conseil de Chu\'a\'lor. Il vous dira que faire.', },
    {'Mog\'dorg le Ratatiné vous demande d\'aller parler à Chu\'a\'lor à Ogri\'la dans les Tranchantes.', },
  },
  [11010] = {
    'Mission de bombardement',
    {'Z\'avez une monture volante, et après ? Vous pensez en avoir assez sous la tunique pour l\'utiliser correctement ?|n|nLes camps de forge : Courroux et Terreur, au nord et au sud d\'ici, sont une sacrée épine dans mon panard, et ils menacent la tranquillité d\'Ogri\'la. Avec tous leurs gangrecanons qui canardent la Garde-ciel dans tous les sens, on ne peut pas approcher pour nos opérations dans leurs forges.|n|nVous voulez faire vos preuves ? Prenez ce chargement de bombes et flinguez leurs stocks de munitions. Mais pensez à ne pas vous faire abattre, eh !', },
    nil,
  },
  [11011] = {
    'Une vigilance éternelle',
    {'Votre victoire sur Anzu, le dieu corbeau, est incontestablement un exploit remarquable. Je crains cependant qu\'il ne renonce pas à revenir en Outreterre.|n|nAussi longtemps qu\'il aura des fidèles ici, il recommencera. Gardez la pierre de lune imprégnée d\'essence, au cas où nous entendrions à nouveau parler d\'Anzu.', },
    {'Parlez à Morthis Murmedaile pour recevoir une Pierre de lune imprégnée d\'essence.', },
  },
  [11012] = {
    'Serment de sang de l\'Aile-du-Néant',
    nil,
    nil,
  },
  [11013] = {
    'Au service des Illidari',
    {'L\'escarpement de l\'Aile-du-Néant… Ce bastion qui fut un jour un sanctuaire pour l\'Aile-du-Néant est maintenant occupé par les Gueules-de-dragon. Mais si les orcs contrôlent l\'endroit, notre magie y reste puissante. Assez puissante pour dissimuler votre identité et vous permettre d\'infiltrer les rangs des Gueules-de-dragon.|n|nJe vous ai préparé une lettre à remettre à leur chef, le suzerain Mor\'ghor. Jetez-vous dans la gueule du loup, au campement de la Gueule-de-dragon. Là-bas vous attend votre nouvelle vie de gangr\'orc d\'Illidan Hurlorage.', },
    {'Rendez-vous à l\'Escarpement de l\'Aile-du-Néant et remettez la Lettre de service illidari au Suzerain Mor\'ghor au Campement des Gueules-de-dragon.', },
  },
  [11014] = {
    'Le sous-chef entre en scène',
    {'<Mor\'ghor chiffonne la lettre et la jette par terre.>|n|nD\'accord, grunt, commençons par le commencement. Si tu veux faire partie de ma belle armée Gueule-de-dragon, il va falloir travailler. Ici, à l\'escarpement, personne ne chôme. Trouve-toi un boulot et fais-le proprement, et alors je verrai si je peux te trouver quelque chose de plus intéressant plus tard.|n|nVa voir le sous-chef Varkule Souffle-de-dragon, au centre de la ville. Il verra ce que tu sais faire et te donnera du travail en fonction.|n|nAllez, dégage !', },
    {'Allez parler au Sous-chef Varkule Souffle-de-dragon au Campement des Gueules-de-dragon.', },
  },
  [11015] = {
    'Les cristaux de l\'Aile-du-Néant',
    {'$GUn bon:Une bonne; à rien ? Ça me va. Même une buse comme toi peut être mise à contribution dans le coin. Trouve-toi des créatures sur l\'escarpement et tue-les. Des fois, leurs carcasses porteront des cristaux du Néant. Ramasse-les et rapporte-les-moi. Je considérerai que tu as accompli ton travail de la journée.', },
    {'Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui rapportiez 30 Cristaux de l\'Aile-du-Néant.', },
  },
  [11016] = {
    'Des peaux d\'écorcheurs mine-néant',
    {'$GUn dépeceur:Une dépeceuse;, c\'est ça ? Tu vas trouver ton bonheur ici ! Cherche des écorcheurs autour des formations cristallines, abats-les et dépèce-les. Certains auront des peaux intéressantes. Apporte-les-moi.', },
    {'Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui rapportiez 35 Peaux d\'écorcheurs mine-néant.', },
  },
  [11017] = {
    'Du pollen de pruinéante',
    {'Alors comme ça on ramasse les petites fleurs ?! Ça me fait bien marrer. Malheureusement, nos mages et nos chamans ont besoin de tes services. Le pollen des buissons de pruinéante qui poussent sur l\'escarpement est apparemment spécial, et il sert à leurs machins magiques. Apporte-m\'en et je considèrerai que ton boulot de la journée est fait.', },
    {'Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui rapportiez 40 échantillons de Pollen de pruinéante.', },
  },
  [11018] = {
    'Du minerai de néanticite',
    {'$GUn mineur:Une mineuse; !|n|n<Varkule vous salue.>|n|nÇa, ça me parle ! C\'est comme ça que Varkule a commencé : comme mineur ! Il n\'y a rien qui vaille une bonne descente dans la saleté des mines, hein ?|n|nMaintenant, va me chercher des gisements de néanticite. Dépouille-les, et rapporte-moi le minerai.', },
    {'Le Sous-chef Varkule Souffle-de-dragon du Campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui rapportiez 40 échantillons de Minerai de néanticite.', },
  },
  [11019] = {
    'Un ami à l\'intérieur',
    nil,
    nil,
  },
  [11020] = {
    'Une mort lente',
    {'Les Gueules-de-dragon ont posté des péons sur presque tous les amas cristallins des environs. Les abattre directement attirerait beaucoup trop l\'attention sur vous, ce qui n\'est pas souhaitable, mais il y a un moyen de réduire leur nombre sans attirer le regard suspicieux de Mor\'ghor.|n|nAventurez-vous dans les étendues Sauvages de la vallée d\'Ombrelune, chassez-y les animaux corrompus et collectez-en les glandes gangrenées. Utilisez ces glandes non loin des péons pour empoisonner la viande de mouton que je vais vous donner. Une seule petite bouchée et ils tomberont mortellement malades !', },
    {'Yarzill le Mercenaire du Campement des Gueules-de-dragon de la Vallée d\'Ombrelune veut que vous utilisiez la Viande de mouton de Yarzill associée à des Gangreglandes pour empoisonner 12 Campements de péons Gueules-de-dragon.', },
  },
  [11021] = {
    'L\'almanach d\'Ishaal',
    {'Ce mystérieux tome se trouvait sur le cadavre du prêtre de la serre Ishaal. Il contient des symboles arcaniques et des cartes de corps célestes qui vous sont indéchiffrables.|n|nTout le texte est dans une langue que vous ne comprenez pas, sans doute une ancienne variante de la langue écrite des arakkoa. Vous devriez peut-être apporter tout cela au commandant de la Garde-ciel Adaris.', },
    {'Apportez l\'Almanach d\'Ishaal au Commandant de la Garde-ciel Adaris, au nord de Skettis.', },
  },
  [11022] = {
    'Parler à Mog\'dorg',
    {'$GRoi:Reine; $N ! Vous parler à Mog\'dorg Ratatiné avant de partir à Ogri\'la !', },
    {'Allez parler à Mog\'dorg le Ratatiné. Il se trouve au sommet de la tour située du côté est du Cercle de sang dans les Tranchantes.', },
  },
  [11023] = {
    'Bombardez-les encore !',
    {'On a encore des problèmes avec les canons antiaériens, $N.|n|nQu\'on se comprenne bien : vous avez fait du super boulot la dernière fois, mais ça change rien au fait que ces satanés démons ont l\'air de reconstituer leurs stocks de munitions plus vite qu\'on les descend. Et ça, ça veut dire qu\'on a un mal de chien à faire passer nos p\'tits gars, sans parler du danger que représentent les démons pour Ogri\'la.|n|nQu\'est-ce que vous en dites ? Vous voulez y retourner ?', },
    nil,
  },
  [11024] = {
    'Un allié dans la Ville basse',
    {'Vous trouverez un arakkoa du nom de Rilak dans la Ville basse… digne de confiance… Apportez-lui... le livre.|n|n<Adaris retombe inconscient en vous tendant le livre.>', },
    nil,
  },
  [11025] = {
    'Les cristaux',
    {'Lorsqu\'on les travaille correctement, les cristaux de ces montagnes revêtent des pouvoirs étranges. Par exemple, ils peuvent favoriser la clarté de l\'esprit, comme nous l\'avons vu à Ogri\'la.|n|nIls sont très recherchés par toutes les créatures des environs, qui les utilisent pour mener à bien leurs diaboliques desseins. La valeur des cristaux a même vu l\'apparition d\'une véritable économie.|n|nPour nous aider, vous devrez d\'abord en apprendre plus sur les éclats apogides. Apportez-m\'en. Comme je vous le disais, toutes les créatures des montagnes, ici et au nord-est, sont susceptibles d\'en posséder.', },
    {'Chu\'a\'lor vous a confié pour mission de collecter 5 Éclats apogides. Apportez-les-lui à Ogri\'la au sommet des Tranchantes.', },
  },
  [11026] = {
    'Bannissez les démons',
    {'Vous arrivez au bon moment, mon $Gami:amie; ! Nous avons besoin de votre soutien. En échange, vous recevrez quelque chose de très rare, qui nous aidera tous deux à la fin.|n|nNous ne sommes plus des ogres violents, mais les démons qui se trouvent non loin d\'ici menacent de nous envahir, nous et la Garde-ciel. Le problème, avec les démons, c\'est qu\'une fois que vous les avez tués, ils reviennent avec de nouveaux corps !|n|nMais si vous utilisez ce cristal pour invoquer un portail de bannissement, leur essence y sera aspirée et renvoyée là d\'où elle est venue !', },
    nil,
  },
  [11027] = {
    'Z\'avez la sombrerune ?',
    nil,
    nil,
  },
  [11028] = {
    'Compte à rebours avant anéantissement',
    {'Cet almanach prédit le retour de Terokk, le plus puissant et le plus terrible des rois de Skettis de l\'histoire des arakkoa.|n|nJ\'ai toujours cru que ce n\'était qu\'une légende, $N. Le retour des prêtres de la serre et votre découverte de ce recueil semblent indiquer que non.|n|nChaque jour, Terokk est plus près de retrouver toute sa force. Votre seule chance est de le forcer à revenir dans notre monde prématurément. Retournez à Skettis et parlez-en à Adaris. Espérons qu\'il aura la sagesse de faire ce qui est nécessaire.', },
    nil,
  },
  [11029] = {
    'Un déguisement miteux',
    {'Ouvrez le paquet, $N. C\'est un déguisement. Il n\'a pas l\'air très convaincant, hein ?|n|nJe les fais pour les contrebandiers éthériens qui cherchent des livres rares. Il y a un scribe arakkoa qui vit dans l\'île centrale de Skettis, le Repos de Terokk ; son nom est Sahaak. Il est vieux et presque aveugle.|n|nUtilisez le déguisement pour lui parler et recevoir le livre appelé Lignées antagonistes. Soyez $Gprudent:prudente;, $N. Le déguisement ne trompera pas les autres arakkoa.', },
    {'Utilisez le Déguisement arakkoa miteux pour obtenir les Lignées antagonistes de Sahaak, puis retournez auprès de Hazzik.', },
  },
  [11030] = {
    'Notre fils veut devenir patrouilleur de la Garde-ciel',
    {'$C, nous avons un problème : nous avons beaucoup de fils. Et depuis que la Garde-ciel s\'est installée à côté, ils ne parlent tous que de rejoindre ses rangs.|n|nNous sommes très fiers d\'eux, et nous voulons leur donner tous les avantages possibles pour appuyer leur candidature. Accepteriez-vous de vous rendre à la cristalforge gangrenée de l\'un des camps de forge au nord ou au sud, et de vous procurer un flacon magique pour nos fils ? Vous les repérerez facilement à leur fumée verte.|n|nNous pensons qu\'il faut dix éclats apogides pour les fabriquer. Nous vous aurions bien donné les éclats, mais nous n\'en avons plus en ce moment.', },
    nil,
  },
  [11031] = {
    'Quitter la voie de l\'archimage',
    nil,
    nil,
  },
  [11032] = {
    'Quitter la voie du protecteur',
    nil,
    nil,
  },
  [11033] = {
    'Quitter la voie de l\'assassin',
    nil,
    nil,
  },
  [11034] = {
    'Quitter la voie du guérisseur',
    nil,
    nil,
  },
  [11035] = {
    'Les cieux pas si cléments…',
    {'À l\'extrémité nord-est de cette île se trouve un embacardère utilisé pour le conditionnement et le transport des cristaux et autres reliques de l\'Aile-du-Néant. Les transporteurs Gueules-de-dragon les emportent vers la forteresse, tandis que les ascendants protègent l\'endroit de toute attaque.|n|nCela vous laisse une ouverture pour porter un coup aux Gueules-de-dragon : leur couloir aérien.|n|nEnvolez-vous jusqu\'aux îles dévastées du couloir aérien et tendez une embuscade aux transporteurs qui l\'empruntent. Récupérez les reliques qu\'ils nous ont volées !', },
    {'Yarzill le Mercenaire du Campement des Gueules-de-dragon de la Vallée d\'Ombrelune veut que vous récupériez 10 Reliques de l\'Aile-du-Néant.', },
  },
  [11036] = {
    'Marchandise extraordinaire !',
    {'Je suis le premier à reconnaître que je ne saisis pas exactement le sens de cette commande, mais les instructions du chef-de-fusée Karlingue étaient très précises : rien que les meilleurs fruits, conservés de manière à pouvoir survivre à un très long voyage et scellés pour les protéger des éléments.|n|nIl y avait d\'autres indications, apesanteur par-ci et basse pression par-là. Je ne vais pas faire semblant de comprendre, mais il paie bien, alors je vais la lui donner, sa supernourriture. Apportez-lui cette caisse dans la Zone 52. Après être $Gentré:entrée; dans Raz-de-Néant, continuez à suivre la route jusqu\'à ce que vous voyiez la ville.', },
    nil,
  },
  [11037] = {
    'Une vision étrange',
    {'J\'ai eu une vision pour le moins inhabituelle, $N, et je ne sais pas du tout comment l\'interpréter. J\'ai vu une flèche, une gigantesque flèche, jaillir vers le ciel en chevauchant une traînée de feu. Il s\'agit d\'un tour plutôt banal pour un mage talentueux, mais d\'une manière ou d\'une autre, je sais que la flèche que j\'ai vue n\'est pas une création magique.|n|nElle sera sans pareille, au-delà de tout ce que les habitants d\'Azeroth ont jamais construit. Vous devez trouver les gens qui travaillent à cette création, $N. Apportez-leur votre aide car, sans elle, leurs efforts pourraient encore échouer.', },
    {'Parlez au Chef-de-fusée Karlingue dans la Zone 52.', },
  },
  [11038] = {
    'Aider l\'exarque Orelis',
    {'Il n\'y a pas très longtemps, la grande prêtresse Ishanah a envoyé un petit groupe d\'anachorètes à Raz-de-Néant, sous le commandement de l\'exarque Orelis. Ils devaient enquêter au sujet des activités de Kael\'thas et ses serviteurs, mais nous n\'avons pas encore reçu de rapport concernant leurs découvertes.|n|nJe crains que notre présence dans cette région ne soit pas assez importante pour accomplir cette mission. Je suis certain que l\'exarque pourrait bénéficier de vos connaissances et de votre expérience. Accepteriez-vous de vous rendre dans la Zone 52 et de l\'aider ?', },
    {'Parlez à l\'Exarque Orelis dans la Zone 52.', },
  },
  [11039] = {
    'Se présenter au maître-espion Thalodien',
    {'Il y a quelque temps, Voren\'thal a envoyé une petite équipe à Raz-de-Néant pour enquêter sur les activités de Kael\'thas. Notre chef a la plus grande confiance en le maître-espion Thalodien et ses compagnons, et a décidé d\'honorer sa demande de renforts.|n|nLe rapport de Thalodien était bref, mais établissait clairement qu\'il avait découvert quelque chose de grande importance. Présentez-vous à lui dans la Zone 52 et aidez-le autant que vous le pourrez, $N.', },
    {'Présentez-vous au Maître-espion Thalodien dans la Zone 52.', },
  },
  [11040] = {
    'Des pièces détachées pour le chef-de-fusée',
    {'Vous pouvez compter sur les doigts d\'une main le nombre de fois où j\'ai collaboré avec un gobelin. Le plus souvent, on est en compétition avec eux, mais quand j\'ai reçu la requête du chef-de-fusée Karlingue, je n\'ai pas pu refuser.|n|nCette caisse est pleine de pièces détachées que je n\'utilise pas, mais elles pourront peut-être être utiles au projet du chef-de-fusée. Vous voulez bien les lui livrer si vous vous rendez à la Zone 52 ?|n|nQui sait, peut-être que quelques excellentes pièces de facture gnome empêcheront son invention d\'exploser !', },
    nil,
  },
  [11041] = {
    'Un travail à terminer…',
    {'Au nom de notre grand maître... Pour la gloire d\'Illidan !|n|nPar ordre du suzerain Mor\'ghor, le grand plateau de l\'Escarpement de l\'Aile-du-Néant doit être repris. Avec tous ces drakes de l\'Aile-du-Néant qui ont été capturés ou chassés de ces terres, les écorche-roc sont de plus en plus nombreux et menacent l\'exploitation du cristal.|n|nDétruisez-les tous, la mère de la tanière et son concubin, Arvoar.|n|nC\'est Mor\'ghor qui l\'ordonne !|n|n<On dirait que cet orc n\'a pas réussi à prendre le plateau. C\'est le moment de prouver votre valeur à Mor\'ghor !>', },
    {'Tuez 10 Écorcheurs Supremine et Barash la Mère de la tanière. Revenez voir le Suzerain Mor\'ghor au Campement des Gueules-de-dragon si vous réussissez.', },
  },
  [11042] = {
    'Une vision mystique',
    {'Une étrange vision me hante, $N. Je vois un nuage de fumée s\'élever sans fin vers le ciel, dans le sillon d\'un brasier géant qui s\'éloigne toujours plus vite. Ce n\'est ni un phénomène naturel, ni une création maléfique, ça je le sais.|n|nJ\'ignore à quoi cela ressemble, tout ce que je sais est qu\'il s\'agit du produit du labeur d\'un grand nombre de gens. Mais sans aide supplémentaire, il se peut que cette création ne voie jamais le jour.|n|nRendez-vous au Raz-de-Néant, $C. Trouvez les responsables de cette création, et offrez-leur votre aide.', },
    {'Parlez au Chef-de-fusée Karlingue dans la Zone 52.', },
  },
  [11043] = {
    'Le griffon de l\'avenir',
    {'J\'ai entendu dire que les nains Marteaux-hardis gardent un perchoir de griffons, dans leur forteresse au sud de la vallée d\'Ombrelune. Si vous allez là-bas, vous voulez bien dire un mot pour moi ? J\'ai quelques idées sur la façon d\'améliorer leurs griffons !|n|nPourquoi se contenter de leur mettre une armure, alors qu\'on pourrait leur installer un altimètre, un rétroviseur et une fusée ? Vous imaginez à quelle vitesse vous pourriez aller avec l\'un de ces bébés accrochés au dos de votre griffon ? Je vais l\'appeler le TurboGryphon 8000 !', },
    nil,
  },
  [11044] = {
    'Visions d\'anéantissement',
    {'Une vision cataclysmique trouble souvent mon repos : une pluie de feu verte s\'abat sur le sol et fauche les vaillants défenseurs d\'une imposante forteresse. Elle me hante depuis des semaines maintenant, et ce n\'est que récemment que j\'ai réussi à en comprendre la signification.|n|nLoin à l\'est, dans la vallée d\'Ombrelune, les nains Marteaux-hardis subissent les attaques incessantes de la Légion ardente et de nombreux autres ennemis. Ils combattent bravement mais, sans renfort, ils succomberont à leurs adversaires. Allez vous joindre à eux, $N. Aidez-les dans leur bataille.', },
    {'Parlez au Chef d\'escadrille Nuainn au Bastion des Marteaux-hardis.', },
  },
  [11045] = {
    'Zorus le Judicateur',
    {'L\'histoire de la vallée d\'Ombrelune est longue et troublée. Ils sont bien peu nombreux à l\'étudier, de peur de redonner vie aux indicibles atrocités qui ont eu lieu là-bas.|n|nMais tous ne sont pas si timorés. Zorus le Judicateur cherche à découvrir la vérité au sujet du passé des fantômes d\'Ombrelune. Une telle entreprise est éprouvante, et je suis sûr qu\'il accepterait de l\'aide avec plaisir.|n|nSi vos voyages vous mènent jusqu\'à Ombrelune, allez trouver Zorus au bastion des Marteaux-hardis, au centre de la partie sud de la vallée.', },
    {'Parlez à Zorus le Judicateur au Bastion des Marteaux-hardis.', },
  },
  [11046] = {
    'L\'apothicaire en chef Hildagard',
    {'L\'histoire de la vallée d\'Ombrelune est longue et troublée. Ils sont bien peu nombreux à l\'étudier, de peur de redonner vie aux indicibles atrocités qui ont eu lieu là-bas.|n|nMais ils ne sont pas tous si timorés. Les recherches de l\'apothicaire en chef Hildagard sont consacrées au passé des fantômes d\'Ombrelune. Une telle entreprise est éprouvante, et je suis sûr qu\'elle accepterait de l\'aide avec plaisir.|n|nSi vos voyages vous mènent par là, allez trouver Hildagard au village d\'Ombrelune, dans le nord-ouest de la vallée.', },
    {'Parlez à l\'Apothicaire en chef Hildagard au village d\'Ombrelune.', },
  },
  [11047] = {
    'La requête de l\'apprenti',
    {'En tant qu\'apprenti maître des coursiers du vent, l\'une de mes tâches est de prendre soin des bêtes quand elles ne volent pas. Le problème, c\'est que nous en avons si peu ici qu\'ils n\'ont que très peu de temps de repos.|n|nJe crains qu\'ils ne finissent par mourir de fatigue si nous n\'en recevons pas d\'autres. Il y a une grande étable au village d\'Ombrelune, dans l\'ouest de la vallée d\'Ombrelune. Dama Crin-sauvage y supervise l\'élevage et le dressage des coursiers du vent.|n|nAccepteriez-vous d\'aller lui parler de notre part et de l\'informer de notre situation ?', },
    nil,
  },
  [11048] = {
    'Le rapport de Kroghan',
    {'À l\'origine, mes ordres étaient de rester un peu à Garadar, puis de poursuivre ma route et de me présenter au garde de sang Gulmok au village d\'Ombrelune. Ce que j\'ai vu, pendant mon séjour ici, c\'est que Garadar aurait beaucoup à tirer d\'un contact avec la Horde établi sur le long terme.|n|nJe sais bien que Gulmok a besoin de tous les hommes disponibles, mais je sais aussi qu\'il comprendra que ma mission ici n\'est pas terminée. Rendez-vous au village d\'Ombrelune, dans le nord-ouest de la vallée d\'Ombrelune, et informez le garde de sang Gulmok du report de mon arrivée.', },
    {'Parlez au Garde de sang Gulmok au village d\'Ombrelune.', },
  },
  [11049] = {
    'La ruée vers les œufs de l\'Aile-du-Néant',
    {'Si vous deviez découvrir des œufs de l\'Aile-du-Néant lors de vos explorations, apportez-les-moi.|n|nSoyez $Gprévenu:prévenue;, il est rare d\'en trouver. Ne soyez pas $Gdéçu:déçue; si vous n\'en voyez pas. Ces Gueules-de-dragon ont méthodiquement collecté la plupart d\'entre eux et les ont expédiés vers une destination inconnue.|n|nOn peut trouver des œufs sur des créatures de l\'île, près des formations de cristal, dans les mines, ou même dans les filons de néanticite et les buissons de pruinéante.|n|nRestez $Gdiscret:discrète;. Il ne faut pas que Mor\'ghor soit au courant de vos activités.', },
    {'Yarzill le Mercenaire, du campement des Gueules-de-dragon dans la vallée d\'Ombrelune, veut que vous vous procuriez un Œuf de l\'Aile-du-Néant.', },
  },
  [11050] = {
    'Tous les œufs sont bons à prendre',
    nil,
    nil,
  },
  [11051] = {
    'Bannissez plus de démons',
    {'Si nous connaissons bien les démons, et c\'est le cas puisque nous les avons longuement étudiés, ils savent réparer très rapidement les dommages infligés à leur précieux transporteur.|n|nSi vous voulez tenter d\'obtenir une nouvelle sombrerune, reprenez notre cristal de bannissement et allez éliminer d\'autres démons. Vous voulez nous aider à amoindrir la menace que posent ces démons, n\'est-ce pas ?|n|nNous disons « tenter » car le procédé que nous utilisons donne des résultats mitigés. Vous pouvez obtenir une sombrerune, ou quelque chose de complètement différent.', },
    nil,
  },
  [11052] = {
    'La promesse d\'Akama',
    {'<Akama insère le cristal dans le médaillon qu\'il tient en main.>|n|nJe ne suis pas aussi fort maintenant qu\'autrefois, $N. Après toutes ces années à demeurer si près du mal... je ne sais pas si je saurai résister à un artéfact aussi puissant que celui-ci.|n|nPrenez ceci en guise de promesse que, le jour où vous vous retrouverez face à Illidan, je serai à vos côtés. Apportez-le au seul être à qui nous puissions confier un tel pouvoir. Donnez le médaillon à A\'dal, dans la cité de Shattrath.', },
    {'Apportez le Médaillon de Karabor à A\'dal, à Shattrath.', },
  },
  [11053] = {
    'Debout, surveillant !',
    {'C\'est rare qu\'un péon survive aussi longtemps. Encore plus rare qu\'un péon sorte du rang et reçoive une promotion.|n|n<Varkule applaudit.>|n|nLe suzerain veut vous voir, grunt. Vous allez prendre du galon, c\'est sûr.', },
    {'Parlez au Suzerain Mor\'ghor au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11054] = {
    'Être surveillant : savoir faire les bons choix',
    {'Le Surveillant-chef Tadboue du campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui apportiez 10 morceaux de Cuir granuleux et 1 Peau de Tyrantus durcie.', },
    {'Le Surveillant-chef Tadboue du campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui apportiez 10 morceaux de Cuir granuleux et 1 Peau de Tyrantus durcie.', },
  },
  [11055] = {
    'Le botterang : un traitement pour les péons bons à rien',
    {'C\'est votre botterang. Y en a beaucoup des comme ça, mais lui, c\'est le vôtre.|n|nEn tant que surveillant, vous devez vous en servir pour terroriser les péons insolents. Correctement manié, il instille l\'obéissance et garantit la subordination.|n|nRendez-vous dans les champs de cristal et punissez tous les péons que vous surprendrez à glander. Montrez-leur la puissance du botterang !', },
    {'Le Surveillant-chef Tadboue du campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous punissiez 20 Péons Gueules-de-dragon paresseux. Vous devrez aussi rapporter votre Botterang.', },
  },
  [11056] = {
    'Le marché d\'Hazzik',
    {'N\'attirez pas l\'attention sur notre conversation, elle ne plairait pas à Adaris.|n|nJ\'appartiens à la plus basse caste des arakkoa, $N. Sous le règne de Terokk, j\'aurais été sacrifié aux puissances des ténèbres par ses prêtres de la serre. Si ce que vous dites est vrai… si les prêtres de la serre cherchent à faire revenir Terokk... vous devez les en empêcher. Je me moque de ce que dit votre chef !|n|nJ\'ai quelque chose à vous offrir. Il y a un paquet dans mon ancienne maison, au Voile Shil\'ak supérieur. Rapportez-le-moi !', },
    {'Récupérez le Paquet d\'Hazzik dans sa demeure, à l\'est de Skettis, et remettez-le-lui.', },
  },
  [11057] = {
    'Des ennuis en contrebas',
    nil,
    nil,
  },
  [11058] = {
    'Une relique apogide',
    {'Il y a très longtemps, une secte d\'arakkoa aujourd\'hui éteinte, nommés les Apogides, vivait ici. Il subsiste encore des restes de leur civilisation. Nous les appelons des reliques apogides.|n|nL\'une des choses que nous savons à leur propos est que lorsqu\'elles sont correctement utilisées, elles accordent une sorte de bénédiction. Chaque relique présente une séquence de couleur qui, lorsque les cristaux sont pressés dans le bon ordre, permet d\'avancer dans une série de niveaux de plus en plus difficiles.|n|nUn éclat apogide est nécessaire pour alimenter la relique. Revenez quand vous vous serez $Gaccordé:accordée; à la vibration apogide.', },
    nil,
  },
  [11059] = {
    'Le gardien du monument',
    {'Vous avez compris comment utiliser les reliques pour une personne. Mais comme vous le voyez, il en existe de plus grandes, qui nous environnent.|n|nCes grands monuments apogides fonctionnent à peu près de la même façon, mais il faut 35 éclats apogides pour les alimenter.|n|nCe qui nous préoccupe le plus, ce sont les gardiens invoqués lors de leur utilisation. Ces structures de cristal se sont retournées contre leurs maîtres arakkoa, il y a bien longtemps, et mettent maintenant Ogri\'la en danger.|n|nNous vous demandons d\'en détruire un et de nous en apporter la preuve.', },
    nil,
  },
  [11060] = {
    'Une sombrerune cristalforgée',
    nil,
    nil,
  },
  [11061] = {
    'Le devoir d\'un père',
    {'L\'autre flacon magique ne peut être obtenu qu\'en un seul endroit : le point d\'ancrage de Bash\'ir. C\'est une base d\'éthériens, qui ne se montrent pas très amicaux envers les étrangers, donc il risque d\'être assez difficile à obtenir.|n|nVous me demandez où se trouve le point d\'ancrage de Bash\'ir ? Eh bien, enfourchez votre monture volante et dirigez-vous vers le nord-nord-est. Bien après le camp de forge Courroux, vous finirez par le découvrir. La cristalforge Bash\'ir elle-même se trouve dans l\'angle nord-est du campement.|n|nMerci de vous occuper de cela, $N. Cela signifie beaucoup pour nos fils !', },
    nil,
  },
  [11062] = {
    'L\'avant-poste de la Garde-ciel',
    {'$N, nous nous demandions si vous accepteriez de rendre visite à nos amis, au nord, à l\'avant-poste de la Garde-ciel ?|n|nLe commandant Keller de la Garde-ciel dirige des missions qui assurent notre protection mutuelle, et il m\'a demandé de lui envoyer toutes les personnes que nous sentirions prêtes à les aider.|n|nEt j\'ai pensé à vous !|n|nRendez-vous là-bas dès que vous le pourrez, et transmettez-lui nos salutations.', },
    nil,
  },
  [11063] = {
    'Mériter ses ailes…',
    nil,
    nil,
  },
  [11064] = {
    'Course Gueule-de-dragon : la ballade de Vieillot McVieux',
    {'Ne te laisse pas abuser par mes cheveux gris, grunt. Je reste un cavalier dix fois meilleur que toi ! Et ne va pas penser que le vieux singe n\'a plus aucun tour dans son sac.|n|nAlors, tout ce que tu as à faire, c\'est de me suivre et d\'essayer de ne pas te faire éjecter de ta monture. Si tu y arrives, le Vieillot admettra sa défaite.|n|nOn décolle dès que tu es prêt.', },
    {'Suivez Murg « Vieillot » Bourbegueule en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la Vallée d\'Ombrelune.', },
  },
  [11065] = {
    'Allez dompter quelques raies de l\'éther !',
    {'Vous voulez aider la Garde-ciel et Ogri\'la ?|n|nAttendez de m\'avoir écoutée avant de partir, $Gbeau gosse:fillette;. Nous avons besoin de montures de rechange ! Les bombardements et les missions au point d\'ancrage de Bash\'ir ont levé un lourd tribut.|n|nLes raies de l\'éther qui volent près de la cime du Vortex et de l\'éperon de Cristal, au nord-est, ont l\'air de parfaitement convenir. Ce n\'est même pas la peine de les ramener jusqu\'ici. Contentez-vous de les mater et de les attacher, et nous les récupérerons ensuite.|n|nVous pensez pouvoir en dompter quelques-unes ?', },
    nil,
  },
  [11066] = {
    'Allez dompter d\'autres raies de l\'éther !',
    {'Alors, j\'espère que vous vous sentez en forme pour nous aider à dompter quelques raies de l\'éther supplémentaires ! D\'après ce que je vois, vous maniez le lasso comme $Gun pro:une pro; ! Et c\'est pour une bonne cause, car non seulement nous avons besoin de nouvelles montures, mais cela nous aide à protéger Ogri\'la, ce que les ogres apprécient.|n|nN\'oubliez pas, les raies de l\'éther volent près de la cime du Vortex et de l\'éperon de Cristal, au nord-est.|n|nVous pensez pouvoir en dompter quelques autres ?', },
    nil,
  },
  [11067] = {
    'Course Gueule-de-dragon : Trope le Rote-crasse',
    {'Les Gueules-de-dragon sont bons, $N. Même une vieille créature maudite et usée comme moi a sa chance. Si tu veux prouver ta valeur aux Brise-ciel, il va falloir me battre.|n|nJe vais te larguer comme un drake dégage une puce de sa queue…|n|nOn décolle dès que tu es prêt.', },
    {'Suivez Trope le Rote-crasse en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11068] = {
    'Course Gueule-de-dragon : Corlok le Briscard',
    {'Tu me défies MOI ? Ne me fais pas rire !|n|nTu es sérieux ? Alors très bien ! Tout ce que tu as à faire, c\'est de ne pas mourir. Tu sais faire, ça, pas mourir, hein ? Même si je te balance des crânes et que je te vole tout autour sans que tu arrives à suivre ?|n|nDis-moi quand tu seras prêt, et on décolle.', },
    {'Suivez Corlok le Briscard en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11069] = {
    'Course Gueule-de-dragon : Chef d\'escadrille Ichman',
    {'Trois ans. Trois ans bloqué dans ce trou à rat. Trois ans passés comme prisonnier de guerre de ce satané clan Loup-de-givre. Assis enfermé dans leur tour, à les écouter rabâcher, gémir sans fin à propos du pont vers Dun Baldar. Que c\'est pas juste, et gna gna gna, et gna gna gna... La guerre n\'a rien de juste ! Qu\'ils aillent tous au diable !|n|nÀ la seconde où j\'ai été libéré, j\'ai quitté l\'endroit pour toujours et je suis venu ici commencer une nouvelle vie. Maintenant, Mulv et moi on est en lice pour le titre de champion. Si tu le veux, il va falloir me marcher dessus, microbe.|n|nOn y va dès que tu es prêt.', },
    {'Suivez le Chef d\'escadrille Ichman en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11070] = {
    'Course Gueule-de-dragon : Chef d\'escadrille Mulverick',
    {'Suivez le Chef d\'escadrille Mulverick en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
    {'Suivez le Chef d\'escadrille Mulverick en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11071] = {
    'Course Gueule-de-dragon : Capitaine Fracasse-ciel',
    {'Tu oses défier Fracasse-ciel ? Le monde qui t\'entoure sera précipité dans les ténèbres quand mes météores déchireront les cieux.|n|nTu n\'as aucune chance, soldat. Mais si tu désires mourir…|n|nJe vais satisfaire cette envie morbide, ne serait-ce que pour faire un exemple pour tous ceux qui rêveraient bêtement de commettre la même erreur.|n|nOn décolle dès que tu es prêt.', },
    {'Suivez le Capitaine Fracasse-ciel en tentant de rester sur votre monture volante. Si vous parvenez à le battre, informez Ja\'y Nosliw de votre victoire au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11072] = {
    'Lignées antagonistes',
    {'Ce livre contient une liste des descendants retenus prisonniers par les prêtres de la serre : Gezzarak la Chasseresse, Karrog le géant de cristal, l\'hérétique connu sous le nom d\'Akkarai le Hurle-sombre, et Vakkiz le Ragevent. Il faudra tous les abattre pour que Terokk puisse revenir en ce monde.|n|nVous aurez besoin de parchemins détenus par les arakkoa perdus dans le temps pour les faire apparaître aux cercles d\'invocation de Skettis. Apportez-moi un attribut de chacun d\'entre eux. Les êtres que vous allez affronter sont puissants : vous feriez bien d\'être $Gaccompagné:accompagnée;.', },
    {'Trouvez les Piles de crânes au milieu des cercles d\'invocation de Skettis. Invoquez et vainquez chacun des descendants des adversaires de Terokk en utilisant 10 Parchemins perdus dans le temps à la Pile de crâne. Retournez auprès de Hazzik au Raie\'odrome de Noirvent avec un gage de chacun d\'eux.', },
  },
  [11073] = {
    'La chute de Terokk',
    {'J\'ai fait semblant de ne pas voir ce que vous faisiez avec le prisonnier arakkoa, $N. On dirait que votre instinct ne vous a pas $Gtrompé:trompée; en vous poussant à coopérer avec lui.|n|nComprenez-moi… Vu ma situation, j\'aurais eu une mutinerie sur les bras si je vous avais $Gsoutenu:soutenue; dans vos efforts pour ramener Terokk en ce monde.|n|nEmportez les objets que vous a préparés Hazzik et passez à la prochaine étape du plan. Je vais ordonner à mes hommes de vous prêter main-forte quand le temps sera venu. Je vous conseille d\'amener vos propres troupes aussi. J\'ai bien peur que vous n\'ayez droit qu\'à une tentative.', },
    {'Emportez l\'Offrande perdue dans le temps préparée par Hazzik à la Pile de crânes qui se trouve au milieu de Skettis, puis invoquez et terrassez Terokk. Retournez voir le Commandant Adaris de la Garde-ciel quand vous aurez accompli votre mission.', },
  },
  [11074] = {
    'Les attributs des descendants',
    {'Ce livre contient une liste des descendants retenus prisonniers par les prêtres de la serre de Skettis : Gezzarak la Chasseresse, Karrog le géant de cristal, l\'hérétique connu sous le nom d\'Akkarai le Hurle-sombre, et Vekkaz le Ragevent. Il faudra tous les abattre pour que Terokk puisse revenir en ce monde.|n|nVous aurez besoin de parchemins détenus par les arakkoa perdus dans le temps pour les faire apparaître aux cercles d\'invocation de Skettis. Apportez-moi un attribut de chacun d\'entre eux. Les êtres que vous allez affronter sont puissants : vous feriez bien d\'être $Gaccompagné:accompagnée;.', },
    {'Rassemblez des Parchemins perdus dans le temps détenus par les arakkoa de Skettis, et emportez-les jusqu\'à une Pile de crânes au milieu d\'un cercle d\'invocation de Skettis. Invoquez et vainquez les descendants des adversaires de Terokk et rapportez les Serres d\'Akkarai, l\'Échine de Garrok, l\'Écaille de Vekkaz et les Griffes de Gezzarak à Hakkiz.', },
  },
  [11075] = {
    'Les mines de l\'Aile-du-Néant',
    {'On a besoin de votre aide aux mines de l\'Aile-du-Néant, surveillant $N.|n|nIl y a deux jours, nous y avons fait une découverte déplaisante qui a mis un terme à nos opérations. Un mineur qui travaillait dans les profondeurs a coincé sa pioche dans une formation cristalline inhabituelle… Malheureusement, celle-ci était attachée à un dragon du Néant qui n\'a pas apprécié. La bête s\'est réveillée et a exterminé tous nos ouvriers.|n|nPrésentez-vous à la Maîtresse des mines. Vous êtes attendu à l\'entrée des mines, au sud-ouest.', },
    {'Allez voir la Maîtresse des mines sur l\'Escarpement de l\'Aile-du-Néant.', },
  },
  [11076] = {
    'Ramasser les morceaux…',
    {'Une bonne partie de notre production est éparpillée dans les profondeurs. Des chariots pleins jonchent chaque centimètre carré de cette mine ! Nos problèmes actuels nous empêchent d\'y accéder.|n|nC\'est là que vous intervenez, $N. Votre tâche du jour sera de récupérer les cargaisons abandonnées par les mineurs et les ouvriers.|n|nRécupérez les cargaisons de Mine-néant et apportez-les à moi-même ou ma sœur.', },
    {'La Maîtresse des mines, des Mines de l\'escarpement de l\'Aile-du-Néant de la vallée d\'Ombrelune, veut que vous récupériez 15 caisses de Cargaison de Mine-néant.', },
  },
  [11077] = {
    'Les dragons sont les derniers de nos soucis',
    {'L\'éveil du dragon agite un tas d\'autres saletés qui vivent dans les mines. Deux variétés en particulier s\'avèrent être des épines dans le flanc des Gueules-de-dragon. Les écorcheurs mine-néant et les ravageurs mine-néant. Vous devez nous aider à les tuer. Tout ce que je vous demande, c\'est d\'intervenir une fois par jour.|n|nAllez, descendez et démolissez-en autant que vous le pouvez !', },
    {'Le Contremaître Gueule-de-dragon des Mines de l\'Aile-du-Néant de la vallée d\'Ombrelune veut que vous tuiez 15 Ecorcheurs mine-néant et 5 Ravageurs mine-néant.', },
  },
  [11078] = {
    'Pour régner sur les cieux',
    {'Pendant qu\'vous voliez dans l\'coin, vous avez dû r\'marquer les dragons là-haut. J\'suppose que vous n\'avez pas été victime d\'leur rage. Aidez-nous à y mettre fin, $N !|n|nClivenuit et Obsidia dominent ce plateau, tandis qu\'Insidion et Aile-furie règnent sur les cieux au-dessus de l\'autre plateau au nord-est. Ils ont chacun leur perchoir sur leur domaine respectif. J\'me demande si vous et vos amis ne voudriez pas aller là-bas, $Gmon gars:ma fille;, pour casser un œuf avec 35 éclats apogides et attirer l\'dragon.|n|nRapportez-moi des dents comme preuve.', },
    nil,
  },
  [11079] = {
    'Un gangrefouet pour Gahk',
    {'Gahk pense que être telligent, quequefois c\'est idiot. Gahk y veut pas penser. Y veut que $Gpetit:petite:r; $R, y crabouille les gros démons !|n|nY zont des chefs, et les chefs y zont des fouets pour taper sur les p\'tits démons. Vous apporte un fouet à Gahk !|n|nVous défie le chef démon dans les camps de forge au prisme en gangrecristal vert qui brûle. Vous utilise beaucoup d\'éclats apogides pour qu\'eux y viennent. Y s\'appellent Galvanoth, Braxxus, Zarcsin et Incinérateur mo\'arg.', },
    nil,
  },
  [11080] = {
    'Les émanations des reliques',
    {'Maintenant que vous avez senti les vibrations édifiantes des reliques apogides, il est temps que vous alliez plus loin dans votre compréhension de leur fonctionnement. Nous sommes très impatients de connaître les bénéfices que nous pourrons tirer de vos observations !|n|nEn progressant dans votre capacité à vous harmoniser aux reliques, vous obtiendrez un plus haut niveau de connaissances. Ce savoir prendra la forme d\'émanations sortant de la relique.|n|nRevenez nous voir quand vous aurez obtenu de telles émanations.', },
    nil,
  },
  [11081] = {
    'La grande révolte des Bourbesang',
    {'Ce document détaille la révolte prévue par les Roués bourbesang. Le dragon était censé faire diversion pendant leur fuite. Compte tenu du nombre de cadavres éparpillés dans la mine, on peut raisonnablement penser que les choses n\'ont pas tourné comme prévu.|n|nRemettez les plans d\'évasion à la Maîtresse des mines.', },
    {'Apportez les Plans d\'évasion bourbesang à la Maîtresse des mines.', },
  },
  [11082] = {
    'À la recherche de la vérité',
    {'Ces mineurs sont beaucoup trop bêtes pour avoir préparé un plan d\'évasion. Nous devons découvrir le coupable et le punir. Descendez dans les profondeurs de la mine, à la recherche des surveillants bourbesang. S\'ils n\'ont pas été submergés par les habitants de la mine, ils seront sûrement planqués.|n|nLorsque vous en tiendrez un, interrogez-le. Faites-lui avouer le nom du responsable de l\'évasion. Revenez me voir avec l\'identité de ce traître et la main du surveillant.', },
    {'Trouvez un Surveillant bourbesang et interrogez-le. Retournez voir la Maîtresse des mines avec les Informations des Bourbesang et la Main du surveillant.', },
  },
  [11083] = {
    'Affolés et perturbés',
    {'Ne vous préoccupez pas du dragon, $N. Nous avons des projets pour lui…|n|nIl y a une bande de Bourbesang affolés dans les profondeurs de la mine. Depuis que le dragon est libre, ils sont coupés de la sortie. Au bout de deux malheureux jours d\'isolation, ils ont perdu toute décence.|n|nIls se vautrent dans le désordre et le cannibalisme. C\'est le genre de comportement que nous ne pouvons pas tolérer ici. Trouvez-les. Tuez-les. Tous.', },
    {'Ronag l\'Esclavagiste, des Mines de l\'Aile-du-Néant dans la vallée d\'Ombrelune, vous demande de tuer le Contremaître bourbesang affolé et 5 Mineurs bourbesang affolés.', },
  },
  [11084] = {
    'Haut les cœurs, capitaine !',
    {'Eh bien... Toujours en vie, à ce que je vois. C\'est une bonne chose, parce que Mor\'ghor demande à vous voir dans sa tour sur-le-champ. Allez, on se dépêche !', },
    {'Parlez au Suzerain Mor\'ghor au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11085] = {
    'L\'évasion de Skettis',
    {'Salut, $N, et merci d\'être $Gvenu:venue; à mon secours.|n|nJ\'étais en mission de reconnaissance lorsque les oiseaux monstrueux des arakkoa m\'ont fait tomber de ma raie du Néant.|n|nFichons le camp d\'ici tant que nous le pouvons !', },
    {'Escorter le Prisonnier de la Garde-ciel à l\'abri, puis se présenter au Sergent Doryn de la Garde-ciel.', },
  },
  [11086] = {
    'Perturber la porte du Crépuscule',
    {'Une de vos responsabilités en tant que capitaine des Gueules-de-dragon est de nous débarrasser de la présence de la Légion ardente en Outreterre. Il est de votre devoir de réduire au silence ceux qui défient le seigneur Illidan !|n|nLes démons tentent bêtement de stabiliser la porte qui se trouve sur la crête du Crépuscule, à l\'ouest de Nagrand. Ils doivent payer pour leur traîtrise, et vous serez l\'orc chargé de percevoir le paiement.|n|nRendez-vous sur la crête du Crépuscule et anéantissez-en les habitants. Vous avez pour ordre de monter au moins une attaque par jour contre leurs fortifications.', },
    {'Le Suzerain Mor\'ghor du campement des Gueules-de-dragon dans la vallée d\'Ombrelune vous demande de tuer 20 Agents ombremort.', },
  },
  [11087] = {
    'MARQUE HYJAL',
    {'Illidan remplit sept fioles au Puits d\'éternité. Il en vida trois dans le lac au sommet du mont Hyjal, et un second Puits d\'éternité fut ainsi créé. Pendant des années, les autres fioles furent considérées comme perdues.|n|nAvec l\'ouverture de la Porte des ténèbres, nous avons appris qu\'il en donna une à chacun de ses lieutenants, Kael\'thas et Vashj. Récupérez ce qu\'il en reste, nous en aurons besoin comme catalyseur pour ouvrir un portail vers tout événement lié au mont Hyjal, récent ou ancien. L\'issue de la bataille du mont Hyjal doit être préservée.', },
    {'Soridormi aux Grottes du temps vous demande de récupérer le Reste de la fiole de Vashj auprès de Dame Vashj au réservoir de Glissecroc et le Reste de la fiole de Kael auprès de Kael\'thas Haut-Soleil au donjon de la Tempête.', },
  },
  [11088] = {
    'Oublier son entraînement',
    {'Filez-moi plein de feu-sorcier et vous oublierez tout.', },
    {'Apportez 10 échantillons d\'Étoffe du feu-sorcier à Jonathan Lecraft.', },
  },
  [11089] = {
    'Le canon à âmes de Reth\'hedron',
    nil,
    {'Le Seigneur illidari Balthas du campement des Gueules-de-dragon dans la vallée d\'Ombrelune veut que vous lui apportiez 2 Barres de gangracier, 1 Structure en adamantite, 1 Batterie en khorium et 1 Essence des arcanes sans défaut.', },
  },
  [11090] = {
    'Dominer le Dominateur',
    {'<Balthas vous montre un appareil d\'apparence surnaturelle.>|n|nVoici un canon à âme. Les effets en sont dévastateurs s\'il est harmonisé. Celui-ci est en phase avec mon sang, le même sang que celui qui coule dans les veines de mon frère, Reth\'hedron. Oui, et l\'erreur qu\'il a faite dans le choix de son allégeance lui coûtera la vie.|n|nPrenez le canon, et envolez-vous vers la crête du Crépuscule dans l\'ouest du Nagrand. Localisez Reth\'hedron, et ouvrez le feu ! Vous devez rester sur votre monture et à distance de tir pour que le canon fonctionne. Tenez bon, et il n\'aura pas d\'autre choix que la fuite !', },
    {'Le Seigneur illidari Balthas du campement des Gueules-de-dragon dans la vallée d\'Ombrelune vous a $Gchargé:chargée; d\'utiliser le Canon à âmes sur Reth\'hedron le Dominateur en Nagrand.|n|nVous devrez aussi rapporter le Canon à âmes.', },
  },
  [11091] = {
    'Remerciement spécial',
    {'Vos efforts à notre égard nous honorent. À présent, il y a quelqu\'un que nous aimerions que vous rencontriez.|n|nJho\'nass est notre intendant de confiance. Il garde un stock de marchandises dont nous ne proposons la vente qu\'aux amis les plus dévoués d\'Ogri\'la.|n|nVous êtes $Gl\'un:l\'une; de ces amis, $N.|n|nQuand vous en aurez le temps, allez lui parler. D\'après ce que nous savons, il a préparé un petit quelque chose en témoignage de notre reconnaissance.', },
    nil,
  },
  [11092] = {
    'Salut, commandant !',
    {'Capitaine $N !|n|n<Le sous-chef Varkule vous salue.>|n|nLe suzerain Mor\'ghor demande à vous voir immédiatement dans ses appartements !', },
    {'Parlez au Suzerain Mor\'ghor au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11093] = {
    'Raies du Néant affamées',
    {'Les raies du Néant se montrent d\'une loyauté et d\'une obéissance surprenantes une fois entraînées correctement. Malheureusement, la guerre contre Skettis ne leur fait pas du bien.|n|nOn fait des dizaines de sorties chaque jour, les pauvres bêtes n\'ont pas le temps de souffler. Et avec le rationnement de la nourriture, si ce ne sont pas ces satanés pigeons qui les tuent, ce sera la faim.|n|nSi vous voulez nous rendre service, emmenez l\'une de nos raies dans les bois, au sud. Elles n\'ont rien contre la viande de poursuivant dimensionnel si elle est bien fraîche.', },
    {'Utilisez la Cage de raie du Néant dans les bois qui se trouvent au sud du Raie\'odrome de Noirvent et tuez des Poursuivants dimensionnels près de la Raie du Néant affamée. Retournez voir le Dresseur Deesak de la Garde-ciel quand vous aurez terminé.', },
  },
  [11094] = {
    'Tuez-les tous !',
    {'Commandant $N, garde à vous ! Vous avez ordre d\'emmener un bataillon Brise-ciel mettre à sac l\'avant-poste des Clairvoyants qui se trouve au pied des champs de l\'Aile-du-Néant. Une fois le Sanctum des Étoiles détruit, nos lignes de communication vers la halte de l\'Éclipse et la halte Illidari seront réouvertes.|n|nExécution ! Utilisez ce lance-fusée pour lancer l\'attaque des Brise-ciel !', },
    {'Avertissez l\'Arcaniste Thelis du contenu de votre mission et apportez-lui le Lance-fusée gueule-de-dragon au Sanctum des Étoiles dans la vallée d\'Ombrelune.', },
  },
  [11095] = {
    'Le commandant Hobb',
    {'Les Gueules-de-dragon n\'osent nous attaquer que quand notre garde est baissée. Nous assaillir à un moment où nous les attendons, ce serait une défaite assurée pour eux.|n|nJe veux que vous les laissiez venir, $N.|n|n<Thelis hoche la tête.>|n|nOui… un piège. Reprenez le lance-fusée que vous avait donné leur chef, et apportez-le au commandant Hobb. Il monte la garde juste devant le bâtiment.', },
    {'Donnez le Lance-fusée gueule-de-dragon au Commandant Hobb au Sanctum des Étoiles dans la vallée d\'Ombrelune.', },
  },
  [11096] = {
    'La menace vient d\'en haut',
    {'Alors, vous voulez rejoindre la Garde-ciel ? Oui, je vois bien que vous pouvez voler… mais savez-vous vous battre ?|n|nLa Garde-ciel a juré de protéger Shattrath des dangers venus d\'en haut, qu\'ils soient proches ou lointains. Les ogres gordunni qui résident dans la Barrière, au nord, représentent une menace immédiate.|n|nLes forces terrestres de Shattrath ont du mal à les atteindre. C\'est là que nous intervenons. Voyez ce que vous pouvez faire pour les affaiblir.', },
    {'Tuez 20 Ogres gordunni de n\'importe quelle variété dans la Barrière, puis retournez voir Yuula à Shattrath.', },
  },
  [11097] = {
    'Le plus mortel des pièges',
    {'Aidez le Commandant Hobb et les Clairvoyants à défendre le Sanctum des Étoiles. Une fois que l\'ensemble des forces Gueule-de-dragon aura été vaincu, retournez voir le suzerain Mor\'ghor au Campement des Gueules-de-dragon avec les Médailles de Clairvoyant.', },
    {'Aidez le Commandant Hobb et les Clairvoyants à défendre le Sanctum des Étoiles. Une fois que l\'ensemble des forces Gueule-de-dragon aura été vaincu, retournez voir le suzerain Mor\'ghor au Campement des Gueules-de-dragon avec les Médailles de Clairvoyant.', },
  },
  [11098] = {
    'En route pour Skettis !',
    {'La Barrière n\'est que l\'un des fronts sur lesquels nous sommes déployés. Une menace moins immédiate, mais bien plus redoutable, nous guette au-delà des monts Skethyl. Il s\'agit de la cité arakkoa de Skettis.|n|nIl y a quelques mois, nos éclaireurs ont remarqué une forte augmentation de l\'activité des arakkoa qui y vivent. Peu après, ils ont lancé plusieurs attaques contre Shattrath. Depuis, nous avons placé des troupes près de leur ville.|n|nPrenez ces explosifs et remettez-les au sergent Doryn, au raie\'odrome de Noirvent, juste à l\'extérieur de Skettis. Dites-lui que vous êtes une nouvelle recrue.', },
    {'Apportez le Paquet d\'explosifs au Sergent Doryn de la Garde-ciel au Raie\'odrome de Noirvent à l\'extérieur de Skettis.', },
  },
  [11099] = {
    'Tuez-les tous !',
    {'Commandant $N, garde à vous ! Vous avez ordre d\'emmener un bataillon Brise-ciel mettre à sac l\'avant-poste de l\'Aldor qui se trouve au nord-ouest de notre cher Temple noir. Une fois l\'autel de Sha\'tar détruit, nos lignes de communication vers notre base de Glissentaille seront réouvertes.|n|nExécution ! Utilisez ce lance-fusée pour lancer l\'attaque des Brise-ciel !', },
    {'Avertissez l\'Anachorète Ceyla du contenu de votre mission et apportez-lui le Lance-fusée gueule-de-dragon à l\'Autel de Sha\'tar.', },
  },
  [11100] = {
    'Le commandant Arcus',
    {'Les Gueules-de-dragon n\'osent nous attaquer que quand notre garde est baissée. Nous assaillir à un moment où nous les attendons, ce serait une défaite assurée pour eux.|n|nJe veux que vous les laissiez venir, $N.|n|n<Ceyla hoche la tête.>|n|nOui… un piège. Reprenez le lance-fusée que vous avait donné leur chef, et apportez-le au commandant Arcus. Il monte la garde juste devant le bâtiment.', },
    {'Donnez le Lance-fusée gueule-de-dragon au Commandant Arcus à l\'Autel de Sha\'tar dans la vallée d\'Ombrelune.', },
  },
  [11101] = {
    'Le plus mortel des pièges',
    {'Prenez ces médailles de l\'Aldor. Mor\'ghor aura besoin d\'une preuve de « victoire » lorsque ce sera terminé. Il saura qu\'elles viennent de cadavres de soldats de l\'Aldor.|n|nMaintenant, il ne reste plus qu\'à tirer la fusée de signal pour alerter les écumeurs gueules-de-dragon. Nous les écraserons lorsque vous serez $Gprêt:prête;. Vous n\'avez qu\'à me donner le signal.', },
    {'Aidez le Commandant Arcus et l\'Aldor à défendre l\'Autel de Sha\'tar. Une fois que l\'ensemble des forces Gueule-de-dragon aura été vaincu, retournez voir le suzerain Mor\'ghor au Campement des Gueules-de-dragon avec les Médailles de l\'Aldor.', },
  },
  [11102] = {
    'Mission de bombardement',
    {'Vous pouvez vous promener en l\'air en forme de corbeau, et après ? Z\'avez déjà détruit quelque chose au sol en volant ? Ça vous tente ?|n|nLes camps de forge : Courroux et Terreur, au nord et au sud d\'ici, sont une sacrée épine dans mon panard, et ils menacent la tranquillité d\'Ogri\'la. Avec tous leurs gangrecanons qui canardent la Garde-ciel dans tous les sens, on ne peut pas passer pour faire notre travail.|n|nVous voulez faire vos preuves ? Prenez ce chargement de bombes et flinguez leurs stocks de munitions. Mais pensez à ne pas vous faire abattre, eh !', },
    nil,
  },
  [11103] = {
    'Quitter la voie du sage',
    nil,
    nil,
  },
  [11104] = {
    'Quitter la voie du guérisseur',
    nil,
    nil,
  },
  [11105] = {
    'Quitter la voie du champion',
    nil,
