  },
  [11106] = {
    'Quitter la voie du défenseur',
    nil,
    nil,
  },
  [11107] = {
    'À genoux devant le généralissime !',
    {'Parlez au Suzerain Mor\'ghor au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
    {'Parlez au Suzerain Mor\'ghor au Campement des Gueules-de-dragon dans la vallée d\'Ombrelune.', },
  },
  [11108] = {
    'Le seigneur Illidan Hurlorage',
    {'Venez, généralissime $N. Illidan en personne nous attend !', },
    {'Rencontrez Illidan Hurlorage. Si jamais vous survivez, allez trouver Barthamus dans la Ville-basse de Shattrath.', },
  },
  [11109] = {
    'Jorus le drake de l\'Aile-du-Néant cobalt',
    nil,
    nil,
  },
  [11110] = {
