  [13479] = {
    'La grande chasse aux œufs',
    {'La fête du Jardin des nobles, célébration de la vie et du printemps ! J\'espère que vous vous amusez bien à chasser les œufs, l\'$Gami:amie;, parce que j\'aurais bien besoin des services d\'une personne capable telle que vous.|n|nJe ne sais pas trop quel type de magie a été utilisé pour créer les œufs, et les druides n\'ont pas envie de m\'expliquer. Peut-être que vous pourriez ramasser quelques fragments de coquilles pour moi lors de votre chasse. Vous pouvez conserver le contenu des œufs : tout ce que je veux, c\'est un échantillon suffisant de leurs coquilles.', },
    {'Le Récolteur du printemps vous a demandé de lui ramener 20 Fragments de coquilles.', },
  },
  [13480] = {
    'La grande chasse aux œufs',
    {'La fête du Jardin des nobles, célébration de la vie et du printemps ! J\'espère que vous vous amusez bien à chasser les œufs, l\'$Gami:amie;, parce que j\'aurais bien besoin des services d\'une personne capable telle que vous.|n|nJe ne sais pas trop quel type de magie a été utilisé pour créer les œufs, et les druides n\'ont pas envie de m\'expliquer. Peut-être que vous pourriez ramasser quelques fragments de coquilles pour moi lors de votre chasse. Vous pouvez conserver le contenu des œufs : tout ce que je veux, c\'est un échantillon suffisant de leurs coquilles.', },
    {'Le Collecteur du printemps vous a demandé de lui ramener 20 Fragments de coquilles.', },
  },
  [13481] = {
    'Sortons de là !',
    {'La Lumière me sourit. Je n\'ai pas encore succombé à ce véritable cauchemar, mais le Fléau va me tuer et utiliser les différentes parties de mon corps dans cette « usine », si je n\'arrive pas à m\'échapper.|n|nJe n\'y arriverai pas seul, $C, mais avec votre aide, je peux peut-être survivre pour combattre à nouveau le Fléau.|n|nAcceptez-vous de m\'aider à m\'enfuir avant que ces bouchers du Fléau ne m\'achèvent ?', },
    {'Escortez le Père Kamaros jusqu\'à ce qu\'il soit en sécurité et présentez-vous au Frère Keltan, à bord du Marteau d\'Orgrim.', },
  },
  [13482] = {
    'Sortons de là',
    {'La Lumière me sourit. Je n\'ai pas encore succombé à ce véritable cauchemar, mais le Fléau va me tuer et utiliser les différentes parties de mon corps dans cette « usine », si je n\'arrive pas à m\'échapper.|n|nJe n\'y arriverai pas seul, mon enfant, mais avec votre aide, je peux peut-être survivre pour combattre à nouveau le Fléau.|n|nAcceptez-vous de m\'aider à m\'enfuir avant que ces bouchers du Fléau ne m\'achèvent ?', },
    {'Escortez le Père Kamaros jusqu\'à ce qu\'il soit en sécurité et présentez-vous à Absalan le Pieux, à bord du Brise-ciel.', },
  },
  [13483] = {
    'Récolteurs du printemps',
    {'Si vous cherchez à vous occuper, j\'ai entendu dire qu\'il y a, dans des campements près des capitales - Tranchecolline, Brill, Sabot-de-Sang et place de l\'Épervier - des mages qui recrutent des chasseurs d\'œufs pour les aider dans leurs recherches. Je ne connais pas tous les détails, mais je suis sûr qu\'ils vous renseigneront.', },
    {'Parlez à un Récolteur du printemps à Tranchecolline, à Brill, à Sabot-de-Sang ou à la Place de l\'Épervier.', },
  },
  [13484] = {
    'Collecteurs du printemps',
    {'Si vous cherchez à vous occuper, j\'ai entendu dire qu\'il y a, dans des campements près des capitales - Comté-de-l\'Or, Kharanos, Dolanaar et le Guet d\'Azur - des mages qui recrutent des chasseurs d\'œufs pour les aider dans leurs recherches. Je ne connais pas tous les détails, mais je suis sûr qu\'ils vous renseigneront.', },
    {'Parlez à un Collecteur du printemps à Comté-de-l\'Or, Kharanos, Dolanaar ou Guet d\'Azur.', },
  },
