  [13729] = {
    'Le défi du vaillant',
    {'Vous êtes presque $Gprêt:prête; à participer à la grande mêlée. Pour prouver que vous êtes digne de cet honneur, vous devez vaincre un champion de la Croisade d\'argent.|n|nAllez aux écuries qui se trouvent devant le pavillon, empoignez votre lance, et prenez une monture. Parlez à l\'écuyer Danny, à la lice des vaillants d\'Argent, à l\'extrémité ouest de l\'enceinte. Il appellera votre adversaire quand vous serez $Gprêt:prête;.|n|nUne fois le combat terminé, nous discuterons du résultat.', },
    {'Parlez à l\'Écuyer Danny pour invoquer votre adversaire. Quand vous aurez vaincu le Champion d\'argent, retournez voir le Nécrotraqueur Viscéri dans l\'Enceinte du tournoi d\'Argent.|n|nSi vous perdez votre lance, vous pouvez en prendre une autre dans n\'importe quel Râtelier de lances près des écuries, ou dans le Pavillon de Saccage-soleil.', },
  },
  [13730] = {
    'Jouer avec le gangrefeu',
    {'<Draaka se penche pour vous parler.>|n|nÉcoutez… Avant que vous ne disiez quoi que ce soit, je SAIS que nous ne devons pas interférer avec les énergies démoniaques…|n|nMais regardez autour de vous ! Nous sommes désespérés, $C.|n|nDe toute manière, nous allons probablement mourir ici. Nous ferions tout aussi bien de partir en beauté dans le feu de la gloire !|n|nAlors… vous acceptez ?|n|nPrenez cette boîte et allez au sud-est jusqu\'à la colline Gangrefeu. Utilisez-la près des plaques de gangrefeu et rapportez-la-moi quand vous l\'aurez remplie.|n|nOh, et il serait préférable de n\'en parler à personne…', },
    {'Draaka, à Bois-Brisé, vous demande de remplir la Boîte renforcée de 7 Gangrefeux de la Colline Gangrefeu.', },
  },
  [13731] = {
    'Le défi du vaillant',
    {'Vous êtes presque $Gprêt:prête; à participer à la grande mêlée. Pour prouver que vous êtes digne de cet honneur, vous devez vaincre un champion de la Croisade d\'argent.|n|nAllez aux écuries qui se trouvent devant le pavillon, empoignez votre lance, et prenez une monture. Parlez à l\'écuyer Danny, à la lice des vaillants d\'Argent, à l\'extrémité ouest de l\'enceinte. Il appellera votre adversaire quand vous serez $Gprêt:prête;.|n|nUne fois le combat terminé, nous discuterons du résultat.', },
    {'Parlez à l\'Écuyer Danny pour invoquer votre adversaire. Quand vous aurez vaincu le Champion d\'argent, retournez voir Eressea Chantelaube dans l\'Enceinte du tournoi d\'Argent.|n|nSi vous perdez votre lance, vous pouvez en prendre une autre dans n\'importe quel Râtelier de lances près des écuries, ou dans le Pavillon de Saccage-soleil.', },
  },
  [13732] = {
    'La naissance d\'un champion',
    {'Félicitations, $N. Vous avez maîtrisé de nombreux types de combats et remporté tous les défis que vous avez relevés. Il ne fait aucun doute que vous êtes $Gprêt:prête; à affronter les meilleurs guerriers qui se sont rassemblés pour le tournoi, les champions des capitales.|n|nLa justicière Mariel Cœur-vrai a demandé à vous parler, $N, pour vous inscrire officiellement à la grande mêlée.', },
    {'Parlez à la Justicière Mariel Cœur-vrai, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [13733] = {
    'La naissance d\'un champion',
    {'Félicitations, $N. Vous avez maîtrisé de nombreux types de combats et remporté tous les défis que vous avez relevés. Il ne fait aucun doute que vous êtes $Gprêt:prête; à affronter les meilleurs guerriers qui se sont rassemblés pour le tournoi, les champions des capitales.|n|nLa justicière Mariel Cœur-vrai a demandé à vous parler, $N, pour vous inscrire officiellement à la grande mêlée.', },
