  [13858] = {
    'Aux portes de l\'ennemi',
    {'Pendant que nous nous apprêtons à participer au tournoi, les forces de la Croisade d\'argent préparent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le côté sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les séides du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera très facilement.', },
    {'Anka Sabot-Griffu, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 15 Fantassins de la garde d\'os, 10 Eclaireurs de la garde d\'os et 3 Lieutenants de la garde d\'os.', },
  },
  [13859] = {
    'Aux portes de l\'ennemi',
    {'Pendant que nous nous apprêtons à participer au tournoi, les forces de la Croisade d\'argent préparent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le côté sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les séides du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera très facilement.', },
    {'Aneera Thuron, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 15 Fantassins de la garde d\'os, 10 Eclaireurs de la garde d\'os et 3 Lieutenants de la garde d\'os.', },
  },
  [13860] = {
    'Aux portes de l\'ennemi',
    {'Pendant que nous nous apprêtons à participer au tournoi, les forces de la Croisade d\'argent préparent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le côté sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les séides du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera très facilement.', },
    {'Le Dresseur Dretch, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 15 Fantassins de la garde d\'os, 10 Eclaireurs de la garde d\'os et 3 Lieutenants de la garde d\'os.', },
  },
  [13861] = {
    'La bataille devant la citadelle',
    {'Pendant que certains d\'entre nous organisent ce tournoi, nos frères préparent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le flanc sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les commandants du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera très facilement.', },
    {'Eadric le Pur, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 3 Commandants de la garde d\'os.', },
  },
  [13862] = {
    'La bataille devant la citadelle',
    {'Pendant que certains d\'entre nous organisent ce tournoi, nos frères préparent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le flanc sud de Corp\'rethar. Empoignez votre lance, et montez le destrier d\'Argent qui se trouve au campement. Puis allez détruire les commandants du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera très facilement.', },
    {'Eadric le Pur, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 3 Commandants de la garde d\'os.', },
  },
  [13863] = {
    'La bataille devant la citadelle',
    {'Alors que certains croisés s\'apprêtent à participer au tournoi, d\'autres lancent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le flanc sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les commandants du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera facilement.', },
    {'Crok Plaie-du-Fléau, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 3 Commandants de la garde d\'os.', },
  },
  [13864] = {
    'La bataille devant la citadelle',
    {'Alors que certains croisés s\'apprêtent à participer au tournoi, d\'autres lancent un assaut contre la forteresse de l\'ennemi, la citadelle de la Couronne de glace.|n|nDans la cour des Ossements, au sud-ouest de la Couronne de glace, quelques braves croisés ont installé un camp avancé sur le flanc sud de Corp\'rethar. Empoignez votre lance, et montez le destrier de campagne qui se trouve au campement. Puis allez détruire les commandants du roi-liche.|n|nNe craignez pas les nombreux fantassins de la garde d\'os, $N, car votre monture les piétinera facilement.', },
    {'Crok Plaie-du-Fléau, dans l\'enceinte du tournoi d\'Argent, veut que vous tuiez 3 Commandants de la garde d\'os.', },
  },
  [13865] = {
    'Un boulot salissant',
    {'Écoutez-moi bien, $C.|n|nLes elfes de la région sont commandés par trois chefs qui leur ordonnent de concentrer leurs efforts sur le camp de bûcherons. Les abattre sèmerait sûrement la panique et la confusion, assez longtemps, je l\'espère, pour que nous puissions mener à bien notre mission.|n|nPendant que vous y êtes, profitez-en pour tuer leurs éclaireurs, cela ne pourra que nous aider.', },
    {'Krokk vous a demandé de tuer Dorinar, Arminon, Endolar et 12 Éclaireurs d\'Orneval.|n|nSi vous perdez votre Poudre du signal secret, allez parler à Kadrak, à Bois-Brisé.', },
  },
  [13866] = {
    'Au Rempart !',
    {'Ces bois sont peut-être silencieux, mais nos ennemis se cachent derrière chaque tronc. J\'ai trouvé plus d\'un orc avec des flèches dans le dos, son arme encore dans son fourreau.|n|nLe terrain est traître par ici, derrière les lignes de front, mais nous aurions besoin de bras solides et d\'esprits affûtés là-bas au Rempart de Mor\'shan. Kadrak y prépare une offensive. Il préfère les actions aux paroles. Vous vous entendrez bien.|n|nVenez me parler quand vous serez $Gprêt:prête; et je vous y enverrai.', },
    {'Parlez à Kulg Crachetripes à la frontière entre Orneval et Azshara afin d\'être <transporté/transportée> vers le Rempart de Mor\'shan. Présentez-vous à Kadrak à votre arrivée.', },
  },
  [13867] = {
    'Réduction de la menace furbolg',
    {'Les furbolgs crins-de-chardon se trouvent juste au nord d\'Astranaar. Mes éclaireurs m\'ont signalé que leur nombre avait beaucoup augmenté au cours de ces derniers mois. S\'ils devenaient trop nombreux, ils pourraient trouver le courage d\'attaquer Astranaar !|n|nAllez au village des Crins-de-chardon et tuez autant de furbolgs que possible.|n|nJe resterai ici à Astranaar en attendant votre rapport. Qu\'Élune soit avec vous, $C.', },
    {'Tuez 15 Furbolgs au Village des Crins-de-chardon, en Orneval.', },
  },
  [13868] = {
    'Une influence corruptrice ?',
    {'Un petit charme roule au sol lorsque vous fouillez dans les affaires du furbolg mort devant vous. C\'est très certainement de l\'artisanat troll.|n|nEn touchant l\'objet en bois, un sentiment de malaise vous envahit. Vous sentez la corruption émaner de l\'amulette.|n|nVous l\'enveloppez dans un morceau de tissu puis la mettez dans votre besace. Vous décidez de la montrer à Raene Mèneloup la prochaine fois que vous passerez à Astranaar.', },
    {'Apportez le Charme troll à Raene Mèneloup à Astranaar, en Orneval.', },
  },
  [13869] = {
    'Le bois en émoi',
    nil,
    {'Récupérez 10 Bois de coupe chanteguerre.', },
  },
  [13870] = {
    'Le nec plus ultra',
    {'Eh bien, $C, ça ne pourrait pas mieux se passer.|n|nLes elfes peinent à se remettre de votre dernier passage. C\'est le moment de forcer l\'entrée du camp de bûcherons !|n|nFrayez-vous un chemin et allez parler au surveillant Gorthak. Il vous donnera des instructions sur la meilleure façon d\'escorter la diplomate et de la mettre à l\'abri.|n|nBonne chance !', },
    {'Krokk vous a demandé d\'entrer dans le Camp de bûcherons Chanteguerre, et d\'aller parler au Surveillant Gorthak.', },
  },
  [13871] = {
    nil,
    {'Ce n\'est pas comme si je n\'avais que ça à faire !|n|nIl faut que cet endroit reste opérationnel, et c\'est déjà assez difficile sans que je sois constamment harcelé par les elfes et les draeneï.|n|nEn prime, il y a maintenant une meurtrière qui rôde autour du camp et qui a tué une importante diplomate… pendant que je montais la garde !|n|nQui que ce soit, elle n\'a pas pu aller bien loin, $C. Fouillez le camp pour la retrouver puis vengez la diplomate !|n|nJe pourrai au moins apporter la tête de cette criminelle à Hurlenfer quand il me demandera des explications.', },
    {'Le Surveillant Gorthak vous demande de lui apporter la Tête de l\'assassin kaldorei.', },
  },
  [13872] = {
    'Sagesse worgen',
    {'L\'homme qui se trouve en face de moi se nomme Héphaïstos Pèlerin. C\'est un worgen.|n|nSa sœur et lui sont venus à Astranaar il n\'y a pas très longtemps, à la recherche d\'un asile. Selon le peu d\'informations que j\'ai pu glaner, il aimerait apporter son aide au Cercle terrestre pour faire face au bouleversement cataclysmique. Sa sœur est encore plus puissante. Elle s\'en est allée à l\'est aider les chamans à résoudre le problème du volcan.|n|nPeut-être qu\'Héphaïstos peut vous aider. Montrez-lui le charme et voyez ce qu\'il en pense.', },
    {'Apportez le Charme troll à Héphaïstos Pèlerin à Astranaar, en Orneval.', },
  },
  [13873] = {
    'La dernière volonté de Sheelah',
    {'Je… Je n\'arrive à croire qu\'elle soit morte. Tout s\'est passé si vite…|n|nJe crois que je dois vous remercier d\'avoir vengé ma maîtresse. Pour cela, vous avez ma gratitude et celle de Lune-d\'Argent.|n|nDans sa grande sagesse, ma maîtresse avait prédit ce dénouement. Elle avait préparé une missive à transmettre au cas où il lui arriverait malheur.|n|nNous étions censés rejoindre un groupe de gardes d\'Orgrimmar, au croisement, juste au nord d\'ici. Je vous en prie, $R, allez-y à notre place et veillez à ce que le message soit transmis.', },
    nil,
  },
  [13874] = {
    'Une vie pas si charmante',
    {'Les furbolgs convoitent ce qui ne leur appartient pas.|n|n<Héphaïstos retourne plusieurs fois le charme dans sa main puis le jette.>|n|nCes inscriptions possèdent un pouvoir qui corrompt lentement tous ceux qui ne sont pas trolls. D\'après ce que je sais, les furbolgs ont déjà été victimes de leur convoitise par le passé. Certains ne tirent jamais de leçon de leurs erreurs.|n|nIls doivent entasser la plupart des charmes au repaire des Crins-de-chardon, par-delà leur village, au nord.', },
    {'Rassemblez 8 Charmes trolls.', },
  },
  [13875] = {
    'La demande de Gurtar',
    {'J\'ai une requête un peu personnelle à vous adresser, $C.|n|nCela fait des lunes que je n\'ai pas vu Draaka, ma bien-aimée. Et il y en aura encore beaucoup d\'autres avant que nous ne soyons à nouveau réunis. Je crains que son amour pour moi ne se fane au fil du temps.|n|nCette tresse a une signification particulière pour nous deux, tout comme les sanguinettes épineuses, les fleurs qui poussent dans la région.|n|nJ\'aimerais que vous alliez cueillir ces fleurs et que vous les enrouliez autour de la tresse. Apportez ensuite ce cadeau à Draaka de ma part.', },
    {'Le Gardien Gurtar vous demande d\'apporter la Sanguinette tressée à Draaka, à Bois-Brisé.', },
  },
  [13876] = {
    'Perdus à jamais',
    {'Oui, je parle votre langue, $R.|n|nNous, les furbolgs, avons déjà été victimes de ce genre de corruption par le passé. Il n\'y a pas si longtemps, notre chef a volé l\'idole de Remulos. Cet objet démoniaque a ensorcelé toute notre tribu. Un druide appelé Broll Mantelours nous a finalement offert la rédemption.|n|nMais cette fois-ci, nous n\'avons rien volé. Les trolls de Zoram\'gar nous ont donné des charmes en gage d\'amitié. Une amitié empoisonnée, oui !|n|nLa folie s\'est emparée de notre chef, Dal Griffe-de-sang. Pénétrez dans le fort et rapportez-moi ces charmes.', },
    {'Procurez-vous l\'Assortiment de Griffe-de-sang.', },
  },
  [13877] = {
    'Autant en emporte la lave',
    {'<Le worgen vous dévisage avant de formuler sa demande.>|n|nLe volcan va engloutir la totalité d\'Orneval si nous n\'agissons pas rapidement. Je peux vous assurer que la cause de cette éruption n\'était pas naturelle.|n|nMa sœur, Sabina, une puissante chamane du Cercle terrestre, s\'en est allée à l\'est, à l\'extrémité du torrent de lave du Pic-Tonnerre. Elle tente d\'obtenir l\'aide des autres éléments pour affronter le seigneur du Feu à l\'origine de cette destruction.|n|n$N, allez la rejoindre et aidez-la du mieux de vos possibilités.', },
    {'Allez parler à Sabina Pèlerin, à l\'extrémité sud du torrent de lave de Pic-Tonnerre, en Orneval.', },
  },
  [13878] = {
    'À travers feu et flammes',
    {'Aidez-moi, $C ! Les hommes-cochons, ils sont venus mettre le feu aux écuries ! Au feu ! Au feu !|n|n<Dorak pousse des gémissements incohérents jusqu\'à ce que vous parveniez à le calmer.>|n|nLes loups sont encore attachés à l\'intérieur. Quelqu\'un doit sauver les pitits loups !', },
    {'Brisez les chaînes pour libérer les loups des écuries en feu.', },
  },
  [13879] = {
    'Le Pic-Tonnerre',
    {'Salutations, $C.|n|nJe vous félicite pour le succès de votre attaque sur Astranaar. Les elfes ne sont pas prêts d\'oublier l\'humiliation que vous leur avez fait subir.|n|nMais vous devez savoir qu\'ils ne sont pas les seuls obstacles qui empêchent la Horde de conquérir Orneval…|n|nÀ l\'est, un chaman du Cercle terrestre a besoin d\'aide pour résoudre un autre problème. Vous le trouverez au pied du volcan, le Pic-Tonnerre.', },
    {'Broyk vous demande de trouver Stikwad, au Pic-Tonnerre.', },
  },
  [13880] = {
    'Chaud devant !',
    {'<Le grand élémentaire de terre vous observe de toute sa hauteur.>|n|nNous devons interrompre le torrent de lave pour réussir. Je vais vous conférer une partie de mes pouvoirs. Utilisez-les pour combler les crevasses de lave !', },
    {'Utilisez le Don de la Terre pour combler 8 Crevasses de lave.', },
  },
  [13881] = {
    nil,
    {'Je m\'inquiète d\'abord pour les familles d\'ours des chardons qui vivent dans ce qui reste de ces bois. Juste au sud, au-delà du sanctuaire de l\'ours, une génération entière est tombée malade. Une vilaine maladie.|n|n$N, je ne sais pas de quoi ils souffrent au juste, mais ils se consument de l\'intérieur. Cela me brise le cœur qu\'une génération entière soit impossible à sauver, mais nous devons les tuer afin que la terre récupère leurs corps.|n|nDe plus, nous devons découvrir d\'où vient la maladie. Enquêtez au lac peu profond où ils boivent !', },
    {'Tuez 6 Ours des chardons consumés et examinez le lac auquel ils s\'abreuvent.', },
  },
  [13882] = {
    'Les graines de la vie',
    {'Quelque chose essaye de dévorer la vie de Sombrivage de l\'intérieur ! Je vais tenter d\'en apprendre davantage sur la… chose… que vous avez découverte dans le lac. Pendant ce temps, il faut que nous protégions la faune de nouveaux dégâts.|n|nPouvez-vous récupérer quelques matériaux pour moi ? J\'ai besoin de vie sous toutes ses formes. Parlez à Onu, ici dans le bosquet, pour récupérer une graine de la terre. Capturez l\'un des feux follets de Sombrivage qui flottent entre les arbres et vous aurez une graine du ciel. Enfin, vous trouverez une graine de la mer à l\'intérieur des coquillages le long de la côte, à l\'ouest.', },
    {'Récupérez une Graine de la terre, une Graine du ciel et une Graine de la mer.', },
  },
  [13883] = {
    'Mené en bateau',
    {'C\'est du sale boulot ! Il n\'y a pas d\'autre explication…|n|nCes navires ont dû être construits à la va-vite. Des pans entiers de blindage se détachent sans avoir subi le moindre choc !|n|nJe vais leur montrer comment on fait. Mais d\'abord, il faut que vous écumiez le fond des mers à la recherche de ces morceaux de ferraille.|n|nRapportez-les-moi, et je ferai le reste.', },
    {'Retrouvez 10 Morceaux de ferraille immergés.', },
  },
  [13884] = {
    'Ils ne feront pas long feu',
    {'Pour reprendre le contrôle de la région et mettre un terme à la destruction massive de la forêt, il faut d\'abord se débarrasser des sbires du seigneur Magmathar.|n|nLe torrent de lave, au nord, renforce les enragés de lave qui s\'y trouvent. $GSeul:Seule;, je crains que vous ne fassiez pas le poids face à eux.|n|nRevenez me parler quand vous serez $Gprêt:prête;, et j\'invoquerai un élémentaire pour vous aider.', },
    {'Tuez 10 Enragés de lave. Si vous avez besoin d\'un autre Surgisseur glacial, allez voir Arctanus.', },
  },
  [13885] = {
    'La défense de Sombrivage',
    {'Maintenant que nous savons que nos mesures préventives fonctionnent, nous devons couvrir autant de terrain que possible.|n|nJe me suis arrangée pour récupérer un hippogriffe, mais je ne suffirai pas à la tâche. Allez voir mon ami Orseus, près du maître de vol, juste devant le bosquet. Prévenez-le quand vous serez $Gprêt:prête;, je vous retrouverai là-bas. Nous sillonnerons Sombrivage depuis les airs, et nous protègerons autant d\'animaux que nous le pourrons !', },
    {'Parlez à Orseus à l\'extérieur du Bosquet des Anciens et montez sur un hippogriffe. Depuis les airs, protégez 8 Cerfs queue-blanche, 8 Vieux ours des chardons et 8 Matriarches ou Géniteurs traquelunes contre la consomption.', },
  },
  [13886] = {
    nil,
    {'Le temps est venu, $N. Lorsque vous serez $Gprêt:prête;, revenez me voir et j\'invoquerai un vortex tourbillonnant pour vous envoyer plus rapidement au sommet du Pic-Tonnerre.|n|nCanalisez le pouvoir du Cercle terrestre à travers l\'élémentaire pour vaincre le seigneur Magmathar et rétablir l\'équilibre.', },
    {'Utilisez les pouvoirs du Vortex tourbillonnant pour vaincre le Seigneur Magmathar.', },
  },
  [13887] = {
    'Des œufs de peau-de-venin',
    {'Maintenant que vous êtes insensible au poison de peau-de-venin, vous pouvez manier les animaux et leurs œufs. Les peau-de-venin, ils sont vicieux et doivent être entraînés dès l\'éclosion des œufs.|n|nSi vous souhaitez en chevaucher un, vous aurez besoin d\'un œuf non éclos. Il y a de nombreux nids de ravasaures éparpillés dans la Fondrière. Cherchez les œufs avec une coquille plus claire, ce sont les œufs des peau-de-venin.|n|nApportez-moi plusieurs de ces œufs et je vous autoriserai à en garder un. Vous pourrez ensuite élever le jeune ravasaure en suivant mes conseils.', },
    {'Apportez 4 Œufs de ravasaure peau-de-venin à Mor\'vek au sud-est de La Fondrière.', },
  },
  [13888] = {
    nil,
    {'Le temps est venu, $N. Lorsque vous serez $Gprêt:prête;, revenez me voir et j\'invoquerai un vortex tourbillonnant pour vous envoyer plus rapidement au sommet du Pic-Tonnerre.|n|nCanalisez le pouvoir du Cercle terrestre à travers l\'élémentaire pour vaincre le seigneur Magmathar et rétablir l\'équilibre.', },
    {'Utilisez les pouvoirs du Vortex tourbillonnant pour vaincre le Seigneur Magmathar.', },
  },
  [13889] = {
    'Il a faim… très faim !',
    {'Le jeune peau-de-venin vous regarde avec espoir, puis commence à dessiner dans la poussière.|n|nLes traits sont grossiers, mais vous reconnaissez la forme des dimeurtrodons, stégodons et pterreurdactyles. Lorsque le raptor termine son gribouillage, il lève les yeux vers vous, montre les dents et mime un mouvement de morsure.|n|nVotre jeune ravasaure peau-de-venin doit avoir envie de chair fraîche provenant de ces animaux. Trouvez et tuez n\'importe quel dimeurtrodon, stégodon ou pterreurdactyle dans le cratère d\'Un\'Goro et donnez sa viande à manger à votre jeune peau-de-venin affamé.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 15 morceaux de Viande de dinosaure fraîche.', },
  },
  [13890] = {
    'Jeter de l\'huile sur le feu',
    {'Ce n\'est pas une mince affaire, $R !|n|nD\'autres navires approchent, et sans la lumière du phare, ils seront perdus, ou pire ! Vous êtes donc $Gchargé:chargée; d\'entretenir le feu.|n|nRécupérez la graisse des hydres qui nagent dans ces eaux, puis transformez-la en huile grâce à la forge que voici.|n|nVous nous ferez gagner un temps précieux en jetant cette huile sur le feu du phare.', },
    {'Le Commandant Croc-sinistre, de Zoram\'gar, vous a demandé de verser de l\'Huile d\'hydre fouettebrume sur le feu du phare.', },
  },
  [13891] = {
    'Le Dévoreur de Sombrivage',
    {'Maintenant que les créatures de Sombrivage sont en sécurité, il est temps de nous intéresser à l\'artéfact que vous avez trouvé dans le lac. Je crois qu\'il est l\'œuvre d\'un séide d\'un Dieu très ancien. Nous allons combattre ces monstres en employant les énergies vitales de Sombrivage ! Rendez-vous sur la berge du lac peu profond qui se trouve au sud avec l\'arbrisseau portevie. Agitez-le au-dessus des eaux. Cela devrait suffire à neutraliser l\'artéfact.|n|nFaites quand même attention, $N. Il y a des chances qu\'il soit gardé par Élune sait quoi.', },
    {'Utilisez l\'Arbrisseau portevie sur la rive du lac peu profond, au sud du Bosquet des Anciens, afin de détruire l\'Artéfact dévoreur et son gardien.', },
  },
  [13892] = {
    'Ne laissez aucune trace',
    {'Au sud-ouest gît le corps d\'une créature apparentée aux Dieux très anciens que vénèrent les sectateurs du Marteau du crépuscule.|n|nIl a été vaincu avant notre temps, peut-être pas par les titans eux-mêmes, mais au moins par l\'une de leurs créations.|n|nL\'activité du culte a augmenté dans la région. Autrement dit, quelque chose de terrible se prépare.|n|nNous devons découvrir ce qu\'ils mijotent là-bas, et quelles sont leurs motivations. Prenez cette figurine, elle vous aidera à passer $Ginaperçu:inaperçue; pendant votre collecte d\'informations.', },
    {'Infiltrez-vous au Glaive du maître à l\'aide de la Figurine de panthère, et espionnez le Marteau du crépuscule.', },
  },
  [13893] = {
    'Soggoth et Kronn',
    {'Le Glaive du Maître a été le théâtre d\'une antique bataille, $N. Les titans ont envoyé vingt géants de pierre contre Soggoth.|n|nUn seul a survécu.|n|nLes tablettes disent que Kronn, le plus grand d\'entre eux, s\'est laissé prendre par les tentacules de Soggoth, juste assez longtemps pour que le monstre l\'approche de sa tête… à portée de son épée.|n|nHeureusement que ce truc est mort… nous n\'avons pas vingt géants de pierre pour l\'arrêter de nouveau.', },
    {'Retournez voir Larien au Bosquet des Anciens avec les informations que vous avez obtenues.', },
  },
  [13894] = {
    'Marquer les proies [PÉRIMÉ]',
    nil,
    nil,
  },
  [13895] = {
    'Les Anciens endormis',
    {'Nous n\'avons peut-être pas vingt géants de pierre à lancer sur l\'ennemi, mais nous autres géants de bois sommes aussi forts que n\'importe quel rocher.|n|nRegardez autour de vous, $R. Les miens dorment… mais lorsque le besoin s\'en fera sentir, ils entendront le cor du gardien.|n|nAllez voir Aros, le gardien du bosquet, au-delà du pont qui se trouve au nord-est.|n|nExpliquez-lui à quel point la situation est dramatique.', },
    {'Trouvez Aros au nord-est du Bosquet des Anciens, en Sombrivage.', },
  },
  [13896] = {
    'Connaissances déterrées',
    {'Écoutez, $N. Nous avons besoin d\'en savoir plus sur nos ennemis.|n|nAu sud-ouest, au-delà du Glaive du Maître, il y a un groupe de prospecteurs nains qui fouillent des ruines. Peut-être ont-ils découvert des informations susceptibles de nous aider ?', },
    {'Parlez à l\'Archéologue Groff aux Excavations de Songerrance.', },
  },
  [13897] = {
    'La bataille pour Sombrivage',
    {'Les anciens du bosquet sont venus nous prêter main-forte, $N. Je peux voir ce qu\'ils voient, en ce moment même.|n|nLe Marteau du crépuscule a été forcé de réaliser à la hâte son rituel. Il n\'a réussi à ramener à la vie qu\'une ombre du terrible Soggoth.|n|nDétruisez-la avant qu\'il ne soit trop tard, $N. Mon aide est requise ailleurs.|n|nRetournez voir les druides, au bosquet des Anciens, quand tout sera terminé. Ils vous diront quoi faire.', },
    {'Tuez l\'Avatar de Soggoth, au Glaive du Maître.', },
  },
  [13898] = {
    'Les marées se retournent contre nous',
    {'Nous ne pouvons pas laisser les nagas s\'en tirer comme ça, $N. Ils nous ont déclaré la guerre en tuant le gardien du bosquet.|n|nLeur antre se trouve dans une grotte, sur l\'île de Nazj\'vel, plus loin au sud-ouest.|n|nJe veux leur faire passer un message clair.', },
    {'Tuez 8 Myrmidons Sombrécailles.', },
  },
  [13899] = {
    'Le seigneur de guerre des Sombrécailles',
    {'Je prie pour qu\'Élune ait pitié des nagas, car ils ont l\'intention de s\'allier avec le Marteau du crépuscule.|n|nAventurez-vous dans leur repaire, sur l\'île de Nazj\'vel, et trouvez leur chef, le seigneur de guerre naga, connu sous le nom d\'Iréchine.|n|nLe cor des Anciens a encore une chance d\'être sauvé.', },
    {'Tuez le Seigneur de guerre Iréchine, à l\'intérieur de Nazj\'vel.', },
  },
  [13900] = {
    'L\'offrande à Azshara',
    {'Selon les dires du seigneur de guerre, le cor des Anciens a été offert à Azshara, au-dessus de Nazj\'vel.|n|nIl n\'est peut-être pas trop tard pour empêcher la relique antique d\'être détruite.', },
    {'Empêchez les Prêtresses Sombrécailles d\'offrir le Cor des Anciens à Azshara au-dessus de Nazj\'vel.', },
  },
  [13901] = {
    'Un désespoir intense',
    nil,
    {'Tuez 6 Prêtresses des marées de Brassenoire.', },
  },
  [13902] = {
    'Monter l\'offensive',
    {'Notre travail en Sombrivage n\'est pas encore terminé. Nous avons peut-être empêché la région d\'être pulvérisée, mais nos ennemis sont toujours très présents dans le secteur.|n|nJe veux que vous rejoigniez un groupe de druides, au bosquet des Anciens, plus loin au sud. Leur chef est un de mes vieux amis, Balren de la Griffe.|n|nDites-leur que l\'heure est venue d\'entrer en guerre contre nos ennemis. Je leur prêterai main-forte dès que la zone sera sécurisée.', },
    {'Allez parler à Balren de la Griffe, au Bosquet des Anciens, en Sombrivage.', },
  },
  [13903] = {
    'Larve Gorishi',
    {'Le jeune peau-de-venin vous regarde avec espoir, puis commence à dessiner dans la poussière.|n|nLes dessins du jeune ravasaure semblent représenter divers gros insectes, peut-être les silithides gorishi. Le raptor finit son gribouillage, puis le montre d\'un geste de son petit bras, fait claquer ses mâchoires et se lèche les babines.|n|nIl doit vouloir que vous vous rendiez dans la Balafre sinueuse, au centre de la région sud du cratère d\'Un\'Goro, et que vous récupériez de la viande de silithide. Lorsque vous aurez la viande, donnez-la à manger à votre jeune peau-de-venin affamé.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 10 morceaux de Viande de silithide.', },
  },
  [13904] = {
    'Pochés, brouillés ou crus ?',
    {'L\'estomac du jeune peau-de-venin gargouille, tandis qu\'il gesticule pour attirer votre attention. Il commence à gribouiller des dessins de silithides dans la poussière, puis ajoute des ovales au-dessous d\'eux. Le ravasaure vous regarde avec espoir en montrant les cercles.|n|nIl ne peut s\'agir que d\'œufs de silithides. Le Repaire nuisible, dans l\'ouest de Tanaris, près de la frontière du cratère d\'Un\'Goro, sera probablement l\'endroit idéal pour trouver les œufs qui font tant envie à votre peau-de-venin.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 12 Œufs de silithide.', },
  },
  [13905] = {
    'Des plumes de roc incendiaire',
    {'Le jeune ravasaure vous regarde pendant un moment, comme s\'il se demandait si vous comprendrez. Il dessine une paire de plumes dans la poussière et pointe de la griffe les liens sur ses coudes et ses genoux.|n|nIl n\'a pas l\'air d\'avoir faim, alors à quoi pourraient bien servir les plumes ?|n|nIl doit vouloir s\'en servir comme ornements comme ceux que vous avez vus sur d\'autres raptors. Les plus grandes plumes se trouvent sur les rocs incendiaires qui se rassemblent autour des os de grandes créatures dans l\'ouest de Tanaris, au nord-est de la vallée des Chardonniers.', },
    {'Votre Jeune peau-de-venin veut que vous rapportiez 5 pièces de Plumage de roc incendiaire.', },
  },
  [13906] = {
    'Ils grandissent tellement vite',
    {'Grâce à vos soins experts, votre jeune peau-de-venin grandira vite. Il perdra bientôt ses dents de lait, et elles seront remplacées par sa dentition d\'adulte. Gardez les dents qu\'il va perdre au cours de sa croissance, pour savoir quand il sera assez vieux pour être dressé et devenir votre monture.|n|nVotre peau-de-venin vous fera connaître ses besoins, soyez-y $Gattentif:attentive;. Lorsqu\'il aura perdu toutes ses dents de lait, revenez me voir avec votre peau-de-venin et le matériel dont j\'aurai besoin pour vous fabriquer une selle, je ferai le reste.', },
    {'Rapportez 20 Dents de lait de peau-de-venin, le Jeune peau-de-venin, 20 Étoffes runiques, 20 Cuirs robustes et 80 pièces d\'or à Mor\'vek au sud-est de La Fondrière, dans le Cratère d\'Un\'Goro.', },
  },
  [13907] = {
    'Nettoyer les ruines',
    {'Dès qu\'ils ont su pour le désastre, ces grosses barbes de Forgefer m\'ont envoyé ici pour jeter un œil aux fouilles de Songerrance. Regardez-moi ce bazar ! Des reliques inestimables emportées par la mer, des mois de fouilles réduits à néant en un clin d\'œil.|n|nQuand le raz-de-marée s\'est abattu sur le rivage, tous les camps murlocs ont été détruits. Une chance ? Tu parles, pas avec ma poisse. Les survivants se sont réfugiés dans les ruines, et ils font plus de dégâts que les éléments eux-mêmes n\'en feraient ! Ça vous dirait pas de traîner vos savates là-bas et de prendre les choses en main ?', },
    {'Tuez un total de 10 Oracles ou Réfugiés grisebrumes qui occupent les Excavations de Songerrance.', },
  },
  [13908] = {
    'Un harnachement spécial',
    {'Votre peau-de-venin, il est fort et en parfaite santé, et vous avez tissé de précieux liens. Vous pourrez le chevaucher dès que j\'aurai fabriqué sa selle et sa bride. Comme vous, il faut qu\'elles soient spécialement préparées pour supporter les toxines produites par le raptor.|n|nTout ce que vous avez à faire, c\'est de me rapporter du cuir robuste, de l\'étoffe runique et un peu d\'argent pour acheter les fournitures restantes, et je vous fabriquerai cette selle en un rien de temps.', },
    {'Rapportez 20 Cuirs robustes, 20 Étoffes runiques et 80 pièces d\'or à Mor\'vek dans la partie sud-est de la Fondrière dans le Cratère d\'Un\'Goro.', },
  },
  [13909] = {
    'Vous avez des débris ?',
    {'On va trouver un moyen, $N. Il nous faut juste un peu d\'ingéniosité naine. Réfléchis, Groffou, réfléchis !|n|nCes murlocs veulent juste un toit, c\'est ça ? Soyons constructifs. Et pas qu\'au sens figuré !|n|nToutes sortes de débris ont atterri sur le rivage pendant la catastrophe, et on doit pouvoir se servir des restes des taudis murlocs. Rassemblez tous les matériaux de construction que vous trouverez le long du rivage et qui pourraient convenir à un murloc. C\'est-à-dire à peu près tout et n\'importe quoi.', },
    {'Rassemblez 5 morceaux de Débris grisebrumes récupérables, le long du rivage et dans l\'eau près des Excavations de Songerrance.', },
  },
  [13910] = {
    'Un nouveau foyer',
    {'Peut-on le construire ? Oui, nous le pouvons ! À l\'ouest du site de fouille, j\'ai planté une bannière sur le rivage. Le sable est ferme et ce site est aussi bien qu\'un autre. Prenez mes outils et les pièces que vous avez récupérées, et construisez à ces pestes hargneuses un endroit différent où vivre.', },
    {'Construisez une cabane de murloc sur un site choisi par Groff, près du rivage.', },
  },
  [13911] = {
    'Les absences du Prospecteur',
    {'Vous êtes qui, déjà ? $N ? On se connaît ? Si c\'est la Ligue des explorateurs qui vous envoie, dites-leur que je ne partirai pas ! Pas sans ma trouvaille. Je l\'avais entre les mains. Puis, il y a eu les cris. Et l\'eau.|n|nÉcoutez voir, Trucmuche, j\'ai tout noté dans mon journal, le jour de la marée. Et je sais exactement où je l\'ai laissé ! Mon journal. Pas ma trouvaille. Aidez-moi à trouver l\'un pour retrouver l\'autre ! Ou l\'inverse ! Vous me suivez ? Suivez-moi !', },
    {'Escortez le Prospecteur Songerrance désorienté pour l\'aider à retrouver son journal. Allez parler à l\'Apprenti archéologue Ferd au site de fouilles quand vous aurez terminé.', },
  },
  [13912] = {
    'Secrets embourbés',
    {'Songerrance est peut-être une tête de linotte, mais c\'est un génie, un joyau dans un vieil écrin. Mais je n\'ai pas l\'intention de l\'abandonner. Regardez ce que j\'ai trouvé dans ses notes… ce n\'est pas là… non, ça, c\'est une liste de courses… Voilà ! Le passage où il essaie de dater le disque !|n|nNous pensons que cet artéfact légendaire est une sorte de roue contenant des informations codées. Nous étions en train de le déterrer soigneusement quand la catastrophe est survenue. Mais heureusement, il se trouve encore dans les ruines. Creusez et rapportez-le-moi !', },
    {'Trouvez un Disque ancien incrusté de boue dans les ruines voisines.', },
  },
  [13913] = {
    'Ils ont pris nos gnomes',
    nil,
    nil,
  },
  [13914] = {
    'Des plumes de roc incendiaire',
    {'Le jeune ravasaure vous regarde pendant un moment, comme s\'il se demandait si vous comprendrez. Il dessine une paire de plumes dans la poussière et pointe de la griffe les liens sur ses coudes et ses genoux.|n|nIl n\'a pas l\'air d\'avoir faim, alors à quoi pourraient bien servir les plumes ?|n|nIl doit vouloir s\'en servir comme ornements comme ceux que vous avez vus sur d\'autres raptors. Les plus grandes plumes se trouvent sur les rocs incendiaires qui se rassemblent autour des os de grandes créatures dans l\'ouest de Tanaris, au nord-est de la vallée des Chardonniers.', },
    {'Votre Jeune peau-de-venin veut que vous rapportiez 5 pièces de Plumage de roc incendiaire.', },
  },
  [13915] = {
    'Il a faim… très faim !',
    {'Le jeune peau-de-venin vous regarde avec espoir, puis commence à dessiner dans la poussière.|n|nLes traits sont grossiers, mais vous reconnaissez la forme des dimeurtrodons, stégodons et pterreurdactyles. Lorsque le raptor termine son gribouillage, il lève les yeux vers vous, montre les dents et mime un mouvement de morsure.|n|nVotre jeune ravasaure peau-de-venin doit avoir envie de chair fraîche provenant de ces animaux. Trouvez et tuez n\'importe quel dimeurtrodon, stégodon ou pterreurdactyle dans le cratère d\'Un\'Goro et donnez sa viande à manger à votre jeune peau-de-venin affamé.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 15 morceaux de Viande de dinosaure fraîche.', },
  },
  [13916] = {
    'Pochés, brouillés ou crus ?',
    {'L\'estomac du jeune peau-de-venin gargouille, tandis qu\'il gesticule pour attirer votre attention. Il commence à gribouiller des dessins de silithides dans la poussière, puis ajoute des ovales au-dessous d\'eux. Le ravasaure vous regarde avec espoir en montrant les cercles.|n|nIl ne peut s\'agir que d\'œufs de silithides. Le Repaire nuisible, dans l\'ouest de Tanaris, près de la frontière du cratère d\'Un\'Goro, sera probablement l\'endroit idéal pour trouver les œufs qui font tant envie à votre peau-de-venin.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 12 Œufs de silithide.', },
  },
  [13917] = {
    'Larve Gorishi',
    {'Le jeune peau-de-venin vous regarde avec espoir, puis commence à dessiner dans la poussière.|n|nLes dessins du jeune ravasaure semblent représenter divers gros insectes, peut-être les silithides gorishi. Le raptor finit son gribouillage, puis le montre d\'un geste de son petit bras, fait claquer ses mâchoires et se lèche les babines.|n|nIl doit vouloir que vous vous rendiez dans la Balafre sinueuse, au centre de la région sud du cratère d\'Un\'Goro, et que vous récupériez de la viande de silithide. Lorsque vous aurez la viande, donnez-la à manger à votre jeune peau-de-venin affamé.', },
    {'Votre Jeune peau-de-venin veut que vous le nourrissiez de 10 morceaux de Viande de silithide.', },
  },
  [13918] = {
    'Le terminal des titans',
    {'La découverte du disque nous permet désormais de comprendre l\'utilisation de nos premières trouvailles. Peu après mon arrivée, le prospecteur Songerrance a trouvé ce qu\'il pensait être un grille-pain préhistorique.|n|nJe pense que cette boîte dotée d\'une fente doit être une sorte de lecteur de données. Malheureusement, elle s\'est cassée, et la mer l\'a emportée avec le reste de notre camp de base quand la marée a déferlé sur le rivage !|n|nElle ne doit pas être bien loin, $N. Des morceaux doivent être enfouis dans le sable, aux alentours. Tenez, passez la plage au peigne fin avec mon fidèle détecteur d\'artéfacts enterrés.', },
    {'Passez la plage près des Excavations de Songerrance au Détecteur d\'artéfacts enterrés pour retrouver 5 morceaux du Mécanisme antique. Ensuite, assemblez-les pour former le Mécanisme antique pourvu d\'une fente.', },
  },
  [13919] = {
    'Un voyage au puits de lune',
    {'Ça n\'a pas marché.|n|n<Une expression de tristesse et de résignation se dessine sur le visage de Pelturas tandis qu\'il retire la larme de la soupe et la nettoie délicatement.>|n|nL\'éruption du Pic-Tonnerre a dû avoir un impact sur la pierre. Vous devez l\'emporter au puits de lune de pureté au sud-est, à proximité du volcan. Il est toujours intact, protégé par la puissance des déesses.|n|nLorsque vous y serez, vous purifierez la pierre dans les eaux sacrées d\'Élune. Je ne connais pas la suite des évènements. Je crains pour la vie de ma fille. Elle est entre vos mains désormais, $N.', },
    {'Prenez la Larme d\'Élune et allez la purifier dans les eaux du Puits de lune de pureté, en Orneval.', },
  },
  [13920] = {
    'Avant de partir...',
    {'Il faut à tout prix envoyer $Gun:une:c; $C au guet de Hurlenfer, et quelqu\'un de compétent, $N. Mais avant que vous n\'y alliez, il reste encore un problème à régler, ici.|n|nNous avons perdu une bonne partie de nos denrées périssables en mer à cause des attaques répétées de l\'Alliance. Nous devons stocker suffisamment de nourriture pour mener à bien notre campagne sur Orneval.|n|nVous trouverez de nombreux animaux sauvages juste à l\'est d\'ici. Rapportez-moi la meilleure viande que vous trouverez pour sustenter nos troupes !', },
    {'Rapportez 5 Steaks de venaison au Commandant Croc-sinistre, à Zoram\'gar.', },
  },
  [13921] = {
    'Celui qui cherchait le pardon',
    {'<Une voix envahit votre esprit. Elle provient du puits de lune et vous apaise.>|n|nVous souhaitez guérir un enfant, mais sachez que toute chose a un prix. La tour de Raynebois se dresse à l\'est. Celui qui a succombé à la corruption se tient devant cette tour, près de mon puits de lune.|n|nAvrus Malmurmure cherche le pardon et la rédemption, $N. L\'aiderez-vous à obtenir ce qu\'il désire pour atteindre votre objectif ?', },
    {'Allez parler à Avrus Malmurmure, à la Tour de Raynebois.', },
  },
  [13922] = {
    'Satyre à sa fin',
    {'Il y a quelque temps de cela, les membres de mon ancien clan, les Gangremusc du défilé de la Nuit, ont pillé le lac Tombeciel, et volé les uniques pierres de lune de la région.|n|nLes propriétés curatives de ces pierres sont réputées et pourraient certainement être utilisées pour guérir l\'enfant malade d\'Astranaar.|n|nPour vous rendre au défilé de la Nuit, vous devez emprunter la route à l\'est, qui mène au nord. Il existe de nombreux chemins dans les collines qui vous permettront de vous y rendre, sur le côté est : c\'est là que vous trouverez mes frères irrécupérables. Ils auront ce que vous cherchez.', },
    {'Récupérez 5 Pierres de lune tombées.', },
  },
  [13923] = {
    'En route pour le Guet de Hurlenfer',
    {'Nous combattrons ensemble jusqu\'au bout, $R !|n|nLe Guet de Hurlenfer est l\'une des zones les plus sensibles d\'Orneval. Vous devriez retirer beaucoup d\'expérience de cette mission… enfin, si vous survivez.|n|nQuand vous serez $Gprêt:prête;, allez parler à Andruk. Il vous conduira directement à votre poste.|n|nUne fois sur place, cherchez le capitaine Goggath. Il vous donnera des instructions.|n|nTerrassez nos ennemis ! Pour la Horde !', },
    {'Allez parler au Capitaine Goggath, au Guet de Hurlenfer.', },
  },
  [13924] = {
    'Tout est bien qui finit bien',
    nil,
    nil,
  },
  [13925] = {
    'Une once de prévention',
    {'Avez-vous déjà entendu parler des Très anciens, $N ? Onu et moi pensons que l\'artéfact que vous avez trouvé dans le lac ne peut que leur appartenir. Son pouvoir corrompt Sombrivage et des horreurs, disparues depuis longtemps, refont surface. Vous et moi ne faisons pas le poids face à la situation, mais, pour l\'instant, ma principale préoccupation est de protéger la faune.|n|nTenez, voici l\'arbrisseau qui renferme l\'essence vitale que vous m\'avez rapportée. Je pense qu\'il peut protéger la faune locale. Testez-le sur un ours, un cerf, ou un traquelune non corrompus, et revenez m\'informer du résultat !', },
    {'Testez l\'Arbrisseau portevie sur un Vieil ours des chardons sain, un Cerf blanche-queue sain, une Matriarche ou un Géniteur traquelune sain.', },
  },
  [13926] = {
    'Thann, le petit orphelin oracle',
    {'Cela fait bien longtemps que les orphelins attendent l\'occasion de rencontrer des amis comme vous, $N. C\'est merveilleux que vous ayez accepté de vous occuper de l\'un d\'entre eux.|n|nPrenez ce sifflet. Grâce à lui, vous pourrez appeler l\'orphelin que vous avez choisi de parrainer. Cela ne durera pas très longtemps… Pas plus que la Semaine des enfants, en fait.|n|nJe vous en prie, $N, appelez votre orphelin. Il sera très heureux de vous rencontrer et de découvrir les paysages du Norfendre avec vous.', },
    {'Parlez à la Directrice de l\'orphelinat Aria, puis utilisez le Sifflet d\'orphelin oracle pour appeler l\'enfant que vous protégerez durant la Semaine des enfants.', },
  },
  [13927] = {
    'Kekek, le petit orphelin varleu',
    {'Cela fait bien longtemps que les orphelins attendent l\'occasion de rencontrer des amis comme vous, $N. C\'est merveilleux que vous ayez accepté de vous occuper de l\'un d\'entre eux.|n|nPrenez ce sifflet. Grâce à lui, vous pourrez appeler l\'orphelin que vous avez choisi de parrainer. Cela ne durera pas très longtemps… Pas plus que la Semaine des enfants, en fait.|n|nJe vous en prie, $N, appelez votre orphelin. Il sera très heureux de vous rencontrer et de découvrir les paysages du Norfendre avec vous.', },
    {'Parlez à la Directrice de l\'orphelinat Aria, puis utilisez le Sifflet d\'orphelin varleu pour appeler l\'enfant que vous protégerez durant la Semaine des enfants.', },
  },
  [13928] = {
    'Les âmes des sœurs',
    {'Le gardien Ordanus nous a chargées, mes sentinelles et moi, de rester ici et de protéger la tour. Jusqu\'ici, nous avons réussi à repousser les assaillants de la Horde. Mais ils nous contournent à présent, et se dirigent vers la retraite, au nord.|n|nLe gardien a envoyé ses dryades pour protéger l\'arbre, mais elles ne semblent pas faire le poids face à l\'avant-garde des orcs chanteguerre.|n|nVous devez y aller et récupérer autant de corps de sœurs rieuses que possible. Apportez-les à Halannia, à l\'intérieur de l\'arbre, à la retraite. Elle saura quoi faire.', },
    {'Retrouvez 10 Cadavres de sœurs rieuses.', },
  },
  [13929] = {
    'Le plus grand arbre du monde !',
    {'Il y a une grande guerre, avant, et nous quitte le village. Nous souvient que Soo-pape dit à nous plein de choses sur le plus grand arbre du monde !|n|nSoo-pape appelle lui Grisegueule… Soo-pape dit qu\'il est au milieu des Grisettes. Non, vous attend, ce n\'est pas quoi Soo-pape dit, Soo-pape dit Grisonnes. Maintenant, nous souvient ! L\'arbre est grand, grand, et il est au milieu des Grisonnes. Pas possible de louper lui !|n|nVous emmène nous là-bas, d\'ac ? Nous voit dans l\'arbre géant ? Soo-pape dit que des gros hommes-ours vit dans l\'arbre aussi. Peut-être que nous voit eux ?', },
    {'Emmenez votre orphelin, Thann, visiter Grisegueule. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous entrez dans le tronc du grand arbre.', },
  },
  [13930] = {
    'La demeure des hommes-ours',
    {'Grand chaman Rakjak dit toujours des histoires de puissants guerriers, même si eux très loin. Quelquefois, il dit des histoires sur des hommes-ours géants, avec de grandes batailles pour un arbre-ville.|n|nPeut-être que vous emmène Kekek là, pour voir l\'arbre, voir la bataille ! Le grand chaman Rakjak dit à Kekek que la ville-arbre géant Grisegueule est au milieu des Grisonnes.|n|nMoi voit jamais ville avant que moi rencontre dame des orphelins, mais cette ville n\'a pas de guerriers, juste des hommes en robe violette. Kekek veut voir de vrais guerriers qui se battent pour une vraie ville.', },
    {'Emmenez votre orphelin, Kekek, visiter Grisegueule. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous entrez dans le tronc du grand arbre.', },
  },
  [13931] = {
    'Une nouvelle année, un nouveau souvenir',
    {'Non seulement nous fournissons de la bière à tout le monde, mais nous avons aussi des bocks à offrir ! De jolis bocks commémoratifs que nous nous sommes procurés de façon entièrement légale ! Voilà un bon pour l\'un d\'entre eux.|n|nAllez voir Blix, vers le fond du campement de la fête des Brasseurs. Il est un peu bizarre, surtout depuis qu\'il porte sans arrêt ces drôles de lunettes. Il s\'occupera de changer votre bon, ou de toute autre transaction liée à la fête des Brasseurs.', },
    {'Échangez le Bon pour un bock de la fête des Brasseurs à Blix Réparouage à l\'arrière du campement de la fête des Brasseurs.', },
  },
  [13932] = {
    'Une nouvelle année, un nouveau souvenir',
    {'La fête des Brasseurs, ce n\'est pas que des courses de béliers, c\'est aussi boire de bons coups ! Quand vous aurez un moment, apportez ce bon-cadeau à Belbi Coupecircuit. Elle est presque au fond du campement de la fête des Brasseurs. Si vous n\'arrivez pas à la voir, ne vous inquiétez pas, c\'est elle qui vous verra.|n|nDe toute façon, allez lui remettre ce bon-cadeau pour avoir votre bock de la fête des Brasseurs. Elle sera aussi très heureuse de gérer toutes les autres transactions de la fête des Brasseurs.', },
    {'Échangez le bon-cadeau à Belbi Coupecircuit dans le campement de la fête des Brasseurs.', },
  },
  [13933] = {
    'Le sanctuaire draconique bronze',
    {'Des fois, le haut-oracle Soo-pape dit des histoires sur un sanctuaire des dragons machins, pas comme la grande pierre à Pluie, mais différent. Soo-pape il dit que nous on peut voir comment nous est dans beaucoup d\'années.|n|nOn va là-bas ? Nous souvient que le sanctuaire des dragons machins de bronze est dans un endroit avec des dragons désolés. Soo-pape il dit que la grande pierre à Pluie lui montre le sanctuaire au nord-est du temple du ver qui se repose et au nord-ouest d\'un endroit avec les peaux-sèches qui gardent l\'hiver. Nous y va ?', },
    {'Emmenez votre orphelin, Thann, visiter le Sanctuaire draconique bronze. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13934] = {
    'Le sanctuaire draconique bronze',
    {'Quand Kekek est un jeune chien, il entend parfois les anciens parler du sanctuaire au loin. Des fois, les sages dit que les choses-dragons bronze là-bas sait tout sur l\'avenir.|n|nKekek vous dit qu\'il est grand guerrier plus tard. Maintenant, nous va voir. Le sanctuaire des choses-dragons bronze est quelque part dans la Désolation des dragons, au nord-est du temple des choses-dragons qui a le nom Repos du ver, et au nord-ouest de la ville des hommes qui a le nom Garde-Hiver.|n|nNous va là-bas, et nous voit l\'avenir. Nous prouve que la dame des sans-parents a tort sur Kekek. Kekek est un guerrier quand il est grand. Pas une brute !', },
    {'Emmenez votre orphelin, Kekek, visiter le Sanctuaire draconique bronze. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13935] = {
    'Défendez l\'arbre !',
    {'Nous utilisons le pouvoir du cœur de la forêt pour empêcher la Horde de détruire l\'arbre, mais son pouvoir n\'est pas sans limite. Nous devons nous en servir pour attaquer cette racaille !|n|nShadumbra, le grand félin de la forêt, rôde tout près d\'ici. C\'est en elle que nous devons puiser notre inspiration. Vous deviendrez l\'ombre de Shadumbra. Vous serez $Gimprégné:imprégnée; de l\'essence de la panthère et vous tuerez tous ceux qui osent s\'attaquer à la puissante Orneval !', },
    {'Allez voir Halannia pour invoquer l\'Ombre de Shadumbra et utilisez son pouvoir pour détruire un total de 50 ennemis chanteguerres, à la Retraite de Raynebois.', },
  },
  [13936] = {
    'Gluon englué',
    {'Des retards, encore des retards et toujours des retards ! Je ne m\'en sors pas !|n|nOn m\'avait dit que ce gobelin avait du talent, qu\'il aurait plein de gadgets qui forceraient l\'ennemi à se soumettre. Jusqu\'à présent, je n\'ai entendu que de belles paroles. S\'il revient les mains vides, je le jette du haut de la falaise !|n|nAllez lui parler, $C. Dites-lui que ma patience atteint ses limites !', },
    {'Le Capitaine Goggath vous demande de parler à Gluon, au Guet de Hurlenfer.', },
  },
  [13937] = {
    'Une balade à la Miraclerie',
    {'Nous a le temps de s\'arrêter encore ? Nous entend que Dalaran a un magasin de joujoux mais nous va jamais, encore. La dame des sans-parents dit que trop de sans-parents remplit le magasin. Peut-être que nous peut aller là-bas, juste tous les deux...|n|nNous peut avoir un petit zeppelin en papier ? Nous pense qu\'il y en a à la Miraclerie à Dalaran. Nous veut toujours jouer avec un. Peut-être vous peut en lancer un à nous.', },
    {'Achetez un Petit zeppelin en papier à la Miraclerie et lancez-le à votre orphelin, Thann.', },
  },
  [13938] = {
    'Une visite de la Miraclerie',
    {'Vous emmène Kekek ailleurs ? La dame des sans-parents, elle dit qu\'il y a un magasin de jouets à Dalaran, la Miraclerie. Mais Kekek le voit jamais. Elle dit que si un sans-parent y va, tous les sans-parents y va. Mais vous peut peut-être emmener Kekek ?|n|nKekek voit d\'autres enfants jouer avec petit zeppelin en papier. Kekek sait que zeppelin vient de la Miraclerie. Peut-être vous peut en prendre un et le lancer à Kekek ?', },
    {'Achetez un Petit zeppelin en papier à La Miraclerie et lancez-le à votre orphelin, Kekek.', },
  },
  [13939] = {
    'Les petits bonshommes en gangremousse',
    nil,
    {'Collectez 6 Gangremousses.', },
  },
  [13940] = {
    'La fin du rêve',
    {'Tenez bon, $N. Le réveil est toujours un peu difficile pour les esprits et les corps qui n\'y sont pas préparés.', },
    {'Allez parler à Malfurion, dans l\'Œil du Vortex, en Sombrivage.', },
  },
  [13941] = {
    'La vile ennemie',
    {'Githyiss la Vile était connue pour posséder un venin plus violent que celui des autres Tissebois. Dirania Brillargent, au pied d\'Aldrassil, pourra certainement fabriquer un antidote très puissant à partir de la glande à venin congestionnée de Githyiss. Elle pourrait même vous offrir une récompense…', },
    {'Apportez la Glande à venin congestionnée à Dirania Brillargent au pied d\'Aldrassil.', },
  },
  [13942] = {
    'Je vais l\'exploser, façon puzzle !',
    nil,
    nil,
  },
  [13943] = {
    'Trêve de plaisanterie !',
    {'Nos troupes ne sont pas encore prêtes à attaquer Astranaar, $C. Les elfes savent que nous allons passer à l\'offensive et ne se contentent pas de rester assis à nous attendre. Ils ont établi un camp au pied de cette falaise, duquel ils lancent des attaques assez gênantes à la lumière de la lune.|n|nAvant qu\'ils ne soient stimulés par ces embuscades, je veux que vous leur montriez de quel bois se chauffe la Horde ! Revenez au rapport quand vous les aurez calmés.', },
    {'Le Capitaine Goggath vous a demandé de tuer 10 Tirailleurs d\'Astranaar et 3 Officiers d\'Astranaar.', },
  },
  [13944] = {
    'Petit, mais costaud !',
    {'<Gluon gesticule frénétiquement. Vous remarquez que ses gants sont anormalement grands.>|n|nJ\'ai réussi ! Ça devrait même plaire à Goggath !|n|nIl faudrait juste pouvoir le tester sur quelque chose pour prouver son efficacité… ahh : le chariot !|n|nÇa fait des jours que le patron nous a demandé de dégager cette poubelle rouillée. Utilisez mes explosifs pour vous en débarrasser, puis voyez ce que le capitaine dira !', },
    {'Utilisez l\'Explosif improvisé de Gluon sur le Chariot cassé, au Guet de Hurlenfer.', },
  },
  [13945] = {
    'Danger à domicile',
    {'L\'agression des Pins-tordus restreint nos choix. Personne parmi nous n\'a envie de se retourner, armes à la main, contre les furbolgs. Ils ont été nos amis, mais je redoute qu\'ils ne s\'intéressent bientôt à Dolanaar.|n|nLes furbolgs du creux de Ban\'ethil et du refuge des saisons de Ban\'ethil sont ma principale source d\'inquiétude. J\'ai besoin que vous partiez vers l\'ouest, que vous entriez dans le refuge des saisons, et que vous tuiez tous les Pins-tordus que vous pourrez. Nous n\'aurons sans doute pas beaucoup d\'autres occasions de limiter leur nombre, alors faites vite.', },
    {'Tuez 20 Furbolgs pins-tordus à l\'intérieur et aux alentours du Refuge des saisons de Ban\'ethil.', },
  },
  [13946] = {
    'Les représailles de la nature',
    {'Vous êtes $Gprêt:prête; à réparer vos erreurs. C\'est une bonne chose, et cela me donne une haute idée de votre caractère.|n|nJ\'ai une autre tâche pour vous. J\'ai récolté quelques graines d\'iracine. Elles ressemblent à des gangrenoix, mais en plus puissantes. La nature réagit souvent mal aux démons, et ces iracines représentent une forme de représailles concentrées.|n|nAllez à Gangreroche, au nord. Vous y trouverez des grellides qui n\'ont plus aucun espoir de rédemption. Servez-vous des racines pour les chasser, avant qu\'ils ne deviennent une menace plus sérieuse.', },
    {'Utilisez des Graines d\'iracine pour tuer 12 Grellides à l\'intérieur de Gangreroche.', },
  },
  [13947] = {
    nil,
    {'Alors, Gluon est finalement venu à bout de ces explosifs, hein ?|n|nÇa ne pouvait pas mieux tomber. En ce moment même, les elfes d\'Astranaar se préparent à lancer une violente attaque sur notre camp.|n|nFaites-leur goûter notre nouvelle arme en la lançant du ciel ! Tous les elfes de la nuit ressentiront la destruction d\'Astranaar comme un coup de poignard !|n|nAllez parler à Thraka quand vous serez $Gprêt:prête; à lancer l\'assaut.|n|nVisez juste, $C.', },
    {'Le Capitaine Goggath vous a demandé d\'utiliser les Explosifs improvisés de Gluon pour tuer 20 Sentinelles d\'Astranaar et détruire 10 Lanceurs d\'Astranaar.', },
  },
  [13948] = {
    'Améliorer la surveillance',
    {'Les sectateurs semblent exhumer les restes d\'une créature connue sous le nom de Soggoth le Rampant.|n|nLeurs supérieurs, sur les poutres au-dessus, ont peut-être davantage d\'informations.', },
    {'Infiltrez-vous au Glaive du maître à l\'aide de la Figurine de panthère, et espionnez les chefs du Marteau du crépuscule, sur la plateforme située au-dessus.', },
  },
  [13949] = {
    'Rétablir la caravane pour la Croisée',
    nil,
    {'Parlez à Halga Œil-sanglant au Poste de Guet-Lointain pour escorter la prochaine caravane de la Croisée jusqu\'à la Ferme de Grol\'dom.', },
  },
  [13950] = {
    'Des camarades de jeu !',
    {'C\'est triste d\'être sans-parent. Nous sent seul. Des fois, nous veut aller ailleurs, rencontrer de nouveaux amis.|n|nPeut-être que vous peut emmener nous dans un endroit avec d\'autres enfants ? Nous entend parler d\'un endroit qui a nom retraite des Ailerons-d\'hiver, dans la grande toundra Boréenne. Nous pense que c\'est loin au nord-ouest, près des côtes de l\'île de Frimarra.|n|nLa dame des sans-parents dit que quelqu\'un courageux sauve plein de bébés là-bas, une fois. Nous pense qu\'eux aussi se sent seuls. Nous pense qu\'ils a besoin d\'amis. Vous emmène nous là-bas ?', },
    {'Emmenez votre orphelin, Thann, visiter la Retraite des Ailerons-d\'hiver. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13951] = {
    'Des camarades de jeu !',
    {'Kekek pense qu\'il y a pas assez de chiots avec la dame des sans-parents. Nous peut aller voir des chiots ?|n|nKekek connaît une tribu qui vit dans la Désolation des dragons, à la clairière de Tombeneige. Vous connaît ? La clairière de Tombeneige est au nord de la ville des hommes-morses, Port-Moa\'ki, et au sud du sanctuaire draconique rubis.|n|n<Kekek se renfrogne lorsqu\'il évoque les roharts.>|n|nVous emmène Kekek là-bas, dans les villages. Peut-être que nous rencontre des nouveaux varleus, pour leur montrer que les Frénécœurs est féroces !', },
    {'Emmenez votre orphelin, Kekek, visiter la Clairière de Tombeneige. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13952] = {
    'Les morts reconnaissants',
    {'C\'est bien agréable de pouvoir rendre visite à sa famille et à ses amis. Mais je crois que j\'ai peut-être un peu exagéré… J\'ai déjà mangé tout ce qu\'ils avaient préparé pour moi ! |n|nPourrais-je vous demander un peu plus de ce délicieux pain des morts ? Je vous en serais très reconnaissant…|n|nJe crois que Chapman, là-bas, en vend la recette.', },
    {'Récupérez un peu de Pain des morts et donnez-le à l\'Esprit d\'humain joyeux dans le cimetière de Hurlevent.|n|nUtilisez un Chrysanthème orange pour voir l\'esprit, qui sinon restera invisible.', },
  },
  [13953] = {
    'Des nagas parmi nous',
    {'Cette créature semble s\'être fendu le crâne en affrontant Aros. Elle ressemble à la description des nagas qu\'on vous a donnée.|n|nOn raconte que malgré leur monstrueuse apparence, les nagas sont des elfes de la nuit déformés par la magie des arcanes de la reine Azshara.|n|nOn dirait bien qu\'ils ont décidé de vous empêcher de récupérer le cor des Anciens.', },
    {'Retournez voir Balren de la Griffe au Bosquet des Anciens, en Sombrivage.', },
  },
  [13954] = {
    'La reine dragon',
    {'Une des histoires du haut-oracle Soo-pape dit que les Tout-puissants fait tous les dragons et aussi la reine dragon. Nous veut la voir ! Vous veut bien emmener nous au sommet du temple du Repos du ver ? Nous rappelle que Soo-pape dit que la chose-temple est au milieu de la Désolation des dragons.|n|nNous veut vraiment rencontrer la reine dragon. Elle doit être très grande et très belle. Peut-être elle peut aider nous à trouver de nouveaux parents.|n|nVous emmène nous ?', },
    {'Emmenez votre orphelin, Thann, rendre visite à Alexstrasza la Lieuse-de-vie, au sommet du Temple du Repos du ver. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13955] = {
    'La reine dragon',
    {'Kekek aime toujours dragons. Kekek veut toujours être dragon, mais dame des sans-parents dit non. Mais elle dit que peut-être vous emmène Kekek voir reine dragon.|n|nKekek pense que dame des sans-parents a bonne idée pour une fois. Vous emmène Kekek au temple du Repos du ver, au milieu de Désolation des dragons ? Kekek vole jusqu\'au sommet pour rencontrer reine dragon. Elle doit être vraiment grande, pour être reine de tous les dragons. Kekek est impatient de voir elle !', },
    {'Emmenez votre orphelin, Kekek, rendre visite à Alexstrasza la Lieuse-de-vie, au sommet du Temple du Repos du ver. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13956] = {
    'La rencontre avec un Tout-puissant',
    {'Le haut-oracle Soo-pape dit toujours à nous comment les Tout-puissants construit les sanctuaires et comment nous leur donne du qui-brille, mais lui voit jamais les Tout-puissants... personne voit jamais les Tout-puissants. Mais vous sait peut-être comment en trouver un ?|n|nSoo-pape dit à nous que les Tout-puissants fabrique un portail et le place au centre de la zone sud de Sholazar. Soo-pape dit pas où il mène, mais peut-être qu\'il mène à un Tout-puissant ! Vous emmène nous à travers le portail et nous le découvre, $N !', },
    {'Emmenez votre orphelin, Thann, visiter l\'Etymidian à la terrasse du Façonneur. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13957] = {
    'Le puissant Hemet Nesingwary',
    {'Vous sait qui Kekek veut toujours rencontrer ? Hemet Nesingwary.|n|nPeut-être que vous emmène Kekek pour voir lui ? Ancien Harkek dit plein de choses à nous sur lui. Il vient à Sholazar pour chasser grandes créatures partout ! Même anciens Frénécœur respectent Hemet Nesingwary, car lui est grand chasseur.|n|nAncien Harkek dit à Kekek que camp de base de Nesingwary est au milieu côté ouest de Sholazar, à côté rivière qui s\'appelle courant de la Brèche. Nous va visiter et apprendre comment chasser comme Hemet ?', },
    {'Emmenez votre orphelin, Kekek, rendre visite à Hemet Nesingwary, au Camp de base de Nesingwary. N\'oubliez pas de l\'appeler s\'il n\'est pas présent lorsque vous arrivez là-bas.', },
  },
  [13958] = {
    'La situation est critique !',
    {'Nos ennemis sont sur les dents. La victoire est proche !|n|nMais l\'heure n\'est pas encore à la fête, $C. Il reste beaucoup à faire avant que la Horde ne puisse revendiquer Orneval.|n|nUn conflit a éclaté à la retraite de Raynebois, à l\'est. Les rapports indiquent que la Horde compte de nombreux blessés.|n|nPrenez les fournitures médicales que voici et apportez-les à Thagg. Dites-lui que notre attaque sur Astranaar est une réussite. Cela pourrait remonter le moral des troupes.', },
    nil,
  },
  [13959] = {
    'De retour à l\'orphelinat',
    {'Nous passe nos meilleurs moments avec vous, $N. Nous veut que vous est $Gmon papa:ma maman; maintenant, mais vous doit ramener nous à Aria, la dame des sans-parents à Dalaran.|n|nPeut-être que vous peut venir voir nous une autre fois ? Nous a beaucoup aimé voir les bébés aileron-d\'hiver et la reine dragon. Personne va croire nous quand nous raconte que nous rencontre un Tout-puissant !|n|nVous manque à nous, après, $N. Nous promet d\'envoyer à vous une lettre bientôt, d\'ac ?', },
    {'Ramenez votre protégé à l\'orphelinat de Dalaran, en rendant le Sifflet d\'orphelin oracle à la Directrice de l\'orphelinat Aria à Dalaran.', },
  },
  [13960] = {
    'De retour à l\'orphelinat',
    {'Vous sait quoi ? Vous est pas si mal, en fait, $N. Vous emmène Kekek dans plein d\'endroits rigolos. Kekek rencontre plein de nouveaux amis et fait plein de choses qu\'aucun chiot fait.|n|nVous et Hemet Nesingwary et les chiots de la clairière de Tombeneige sont tous les meilleurs amis de Kekek. Peut-être qu\'un jour vous rapporte à Kekek le livre sur les vertes collines ? Kekek promet d\'écrire à vous, des fois, pour dire à vous comment ça va. Et peut-être que Kekek sera gentil avec les enfants grosses-langues, parfois.|n|nKekek doit retourner avec la dame des sans-parents Aria, maintenant, dans la ville violette des hommes.', },
    {'Ramenez votre protégé à l\'orphelinat de Dalaran, en rendant le Sifflet d\'orphelin varleu à la Directrice de l\'orphelinat Aria à Dalaran.', },
  },
  [13961] = {
    'Tirer les vers du nez',
    {'Notre instinct est de courir sus à nos agresseurs, mais la sagesse nous dicte une autre voie. Nous devrions interroger l\'un de ces envahisseurs hurans afin d\'apprendre tout ce que nous pourrons. Prenez ce filet, $N, et allez m\'attraper un de ces pillards hurans qui attaquent notre ferme à l\'ouest. Assommez-moi un de ces bestiaux et livrez-le-moi.', },
    {'Utilisez le Filet de Grol\'dom pour capturer un Pillard tranchecrin et le ramener à Togrik, à la Ferme de Grol\'dom.', },
  },
  [13962] = {
    nil,
    {'Les trousses de triage nous aident à tenir pour les combats, cependant nous sommes dans une impasse.|n|nLes dryades meurent assez facilement, mais leur chef les ramène rapidement à la vie ! Nous devons affronter un flot incessant de cette vermine !|n|nLe gardien Ordanus se cache dans cet arbre biscornu. Nous avons tenté d\'y accéder, mais en vain. Peut-être pourriez-vous essayer de vous frayer un chemin pendant que nous nous chargeons de ces dryades… ?|n|nCe devrait être un jeu d\'enfant pour quelqu\'un qui a conquis Astranaar. N\'est-ce pas ?', },
    {'Thagg, de la Retraite de Raynebois, vous a demandé de tuer le Gardien Ordanus.', },
  },
  [13963] = {
    'Coûte que coûte',
    {'Je pense qu\'il reviendra à lui si on lui verse de l\'eau froide sur la tête. Que va-t-il nous dire, à votre avis ?|n|nJe vais l\'enfermer dans notre enclos à bestiaux là-bas derrière moi. Je ne pense pas qu\'il restera conscient longtemps. Tâchez d\'apprendre le maximum de choses sur les raisons qui poussent les hurans à attaquer nos fermes ! Je vous laisse le choix de la méthode d\'interrogation.', },
    {'Interrogez le Prisonnier tranchecrin. S\'il n\'est pas là ou s\'il est inconscient, adressez-vous à Togrik qui le ranimera.', },
  },
  [13964] = {
    'En route pour la flèche',
    {'Nous avons perdu le refuge de Vent-d\'Argent ! Tout ce que je sais, c\'est que la Horde a attaqué par surprise et est parvenue d\'une façon ou d\'une autre à retourner les élémentaires gardiens du lac Mystral contre nous.|n|nLes survivants se sont repliés sur la flèche de Chimétoile. $N, ils ont besoin de votre aide.|n|nPartez vers le sud-sud-est. Vous trouverez la flèche à l\'entrée de la Perce des Serres, qui conduit aux Serres-Rocheuses. Vous y rencontrerez la sentinelle Vélène Heurtétoile, elle prépare une contre-offensive.', },
    {'Parlez à la Sentinelle Vélène Heurtétoile à la Flèche de Chimétoile.', },
  },
  [13965] = {
    'L\'infortune des Edune',
    {'$N, si vous avez un moment, j\'aimerais vous demander votre aide pour une affaire fort simple.|n|nJe n\'ai pas reçu de nouvelles de mes amis, les Edune, depuis quelque temps. Je me demandais si vous ne pourriez pas faire un crochet vers l\'ouest pour aller les voir ?|n|nJe vous remercie. Leur maison se trouve sur un petit terrain, juste à l\'ouest du sanctuaire d\'Aessina.', },
    {'Allez parler à Benjari Edune, à la Maison d\'Edune.', },
  },
  [13966] = {
    'Un cadeau pour le Voile d\'hiver',
    nil,
    nil,
  },
  [13967] = {
    'Prendre du poil de la bête',
    {'Au sud, les furbolgs sont plus nombreux que nous ne le pensions. Ils sont aussi bien plus agressifs.|n|nNous sommes occupés à traquer les elfes et à récolter le bois dont nous avons besoin, il n\'y a plus que vous pour m\'aider à résoudre le problème des furbolgs.|n|nJe dois faire des recherches, ici. En attendant, j\'aimerais que vous ayez une approche plus… directe. Rapportez-moi les oreilles des furbolgs qui sont dans le coin pour prouver à Tarkan que l\'on se charge de l\'affaire.', },
    {'Senani Cœur-de-tonnerre, de la Retraite de Vent-d\'Argent, vous a demandé de rassembler 15 Oreilles de furbolgs sur les Totémiques vile-sylve et les Ursas vile-sylve.', },
  },
  [13968] = {
    'L\'assassinat de Raclhure',
    {'Dans le sillage du chaos qui règne au sud, cette brute de « Raclhure » semble avoir rallié tous les réfugiés tranchecrins sous sa bannière. Sous son commandement, ils sont devenus de vulgaires brigands. On ne négocie pas avec ces gens-là. Raclhure doit être éliminé.|n|nÀ en croire notre prisonnier, vous le trouverez au sud-est d\'ici, dans un endroit appelé la colline des Épines. Cherchez près des promontoires d\'où on a une vue dégagée sur la route. Tuez-le, $N, et la menace immédiate devrait disparaître.', },
    {'Éliminez Raclhure, le chef des Tranchecrins.', },
  },
  [13969] = {
    'Le kodo manquant de Grol\'dom',
    {'$GCher ami:Chère amie;, si vous voyagez vers le sud en direction de la colline des Épines, je me demandais si vous ne pourriez pas localiser un des kodos que nous avons perdus ? Toutes les caravanes n\'arrivent pas au-delà du poste de Guet-Lointain. Ces brutes de Tranchecrins ont attaqué un animal de bât hier matin. Il n\'est peut-être plus en vie, mais au cas où il le serait, nous ne pouvons pas nous permettre de perdre davantage de bêtes.', },
    {'Trouvez un Kodo de Grol\'dom égaré dans la Colline des Épines, dans les Tarides du Nord.', },
  },
  [13970] = {
    'Services aux animaux',
    {'Les kodos sont des créatures résistantes. Avec de la nourriture, ce gros pépère va peut-être revenir à lui.|n|nLes Tranchecrins ont volé quantité de céréales aux caravanes précédentes. Vous pouvez ramasser du grain dans les différents camps des environs.', },
    {'Ramassez 5 Sacs de grain volé dans les camps des Tranchecrins, sur la Colline des Épines.', },
  },
  [13971] = {
    'Le retour du kodo',
    {'L\'énorme bête se redresse lentement sur ses pattes en faisant tomber de la terre des Tarides de ses membres revivifiés. Guidée par son instinct, elle se met en route d\'un pas lourd vers la ferme de Grol\'dom.|n|nVous voudrez probablement vérifier auprès de Kranal Fiss que le kodo est bien arrivé chez lui.', },
    {'Parlez à Kranal Fiss à la Ferme de Grol\'dom pour vous assurer que son kodo perdu est bien arrivé.', },
  },
  [13972] = {
    'De nouveau parmi les humains',
    {'Enfin ! La potion de Krennan aura au moins fonctionné sur l\'un de vous autres worgens.|n|nVous devriez être capable de garder le dessus la plupart du temps, mais contrôlez vos émotions.|n|nLe maire Arsmtead voudra probablement vous parler. Gilnéas est attaquée et nous avons vraiment besoin que tout combattant apte prenne les armes.', },
    {'Parlez à Gwen Armstead à Triste-bourg.', },
  },
  [13973] = {
    'La milice de Grol\'dom',
    {'Ils sont venus de nulle part, $C ! Des hurans à perte de vue. Tant de piquants, de groins et de dents. Nous nous sommes repliés sur la ferme mais il en venait toujours plus.|n|nNos meilleurs défenseurs sont tombés au combat, et nous n\'avons aucune nouvelle du fermier Ralton. J\'ai besoin que vous partiez à l\'offensive pour moi ! Tenez ces porcs en respect pendant que je défends les blessés en attendant l\'arrivée des secours.', },
    {'Tuez 6 Pillards tranchecrins.', },
  },
  [13974] = {
    'Le petit paquet de Gluon',
    {'Waouh !|n|nMatez-moi un peu ça ! C\'est révolutionnaire ! La technologie des explosifs, qui est d\'ailleurs la plus intéressante, va faire un bond en avant grâce à cette découverte !|n|nTous les gobelins du sud du Norfendre vont être verts de jalousie !|n|nCroyez-le ou non, j\'ai amélioré la formule pour la rendre encore plus efficace !|n|nTenez. Apportez-en un échantillon au refuge de Vent-d\'Argent, au sud-est. Mon cousin, Flouz, saura peut-être comment l\'utiliser pour aider la Horde à s\'emparer des lieux.', },
    nil,
  },
  [13975] = {
    'Mener la caravane pour la Croisée',
    nil,
    nil,
  },
  [13976] = {
    'Trois amis de la forêt',
    {'Ça vous dirait d\'aller faire un tour dans le sud ? Je n\'ai pas eu de nouvelles de trois de mes amis depuis longtemps. Je n\'ose pas abandonner ma famille à cause de ces étranges tentacules qui surgissent du sol, au nord, et à cause de toute cette activité démoniaque.|n|nBolyun a établi son camp au sud-ouest de la forêt, juste au nord-ouest de ce maudit sanctuaire de Scarfeu. Alenndaar et Harlown l\'y ont rejoint. Ils devraient être en sécurité, mais on ne sait jamais.|n|nMerci, $N.', },
    {'Allez voir Bolyun au Camp de Bolyun, en Orneval.', },
  },
  [13977] = {
    'Production de masse',
    nil,
    {'Flouz vous a demandé d\'apporter la Poudre bang-bang de Gluon à Laguigne, à la Bidouillerie.', },
  },
  [13978] = {
    'Des rôdeurs dans la brume',
    {'Nous avons construit des murs et des portails pour nous protéger de nos ennemis, et pourtant ils sont à nos portes.|n|nLa milice a été obligée de se déplacer pour rejoindre le plus gros de ses troupes, ce qui a laissé la ville sans défenses.|n|nMais plus grandes craintes se sont réalisées et Triste-bourg est envahie par les orcs.|n|nIls sont soit en train d\'attendre leurs ordres d\'attaque, soit en train d\'informer d\'autres troupes de nos déplacements. Quoi qu\'il en soit, nous devons nous occuper d\'eux.|n|nVous êtes peut-être $Gun enragé:une enragée;, mais vous êtes toujours $Gun Gilnéen:une Gilnéenne;. Repoussez l\'ennemi et regagnez votre humanité, $N.', },
    {'Gwen Armstead, à Triste-bourg, vous demande de tuer 8 Éclaireurs orcs.', },
  },
  [13979] = {
    'Le cerveau gobelin',
    {'Si ces fichus bombardements lancés depuis les machines gobelines cessaient, nous pourrions lancer une contre-offensive pour reprendre le refuge de Vent-d\'Argent !|n|nD\'après mon expérience, les gobelins sont soit paresseux et improductifs, soit trop productifs et finissent par se tuer avec leurs propres explosifs. Malheureusement pour nous, ils sont formés par l\'explosif boumgénieur en chef Sploseur.|n|nDirigez-vous vers la Bidouillerie, à l\'ouest du refuge, et ne revenez que lorsque vous aurez la tête du boumgénieur en chef !', },
    {'Procurez-vous la Tête de Sploseur.', },
  },
  [13980] = {
    'À l\'assaut de l\'invisible',
    {'Ils ne sont pas loin, $C. Et ils nous encerclent.|n|nMes hommes commencent à mourir les uns après les autres. Ce sont des attaques elfes, il n\'y a aucun doute possible.|n|nOn dirait que votre raid sur Astranaar les a bien décidés à mettre un terme à notre avancée. Allez, un dernier effort pour échapper à la défaite !|n|nPrenez ces lunettes. Grâce à elles, vous pourrez voir même le plus sournois des elfes. Surveillez mes arrières le temps que je termine d\'armer vos explosifs.', },
    {'Laguigne, à la Bidouillerie, vous a demandé de tuer 12 Assassins d\'Orneval.', },
  },
  [13981] = {
    'Ça va péter !',
    {'De toute évidence, c\'est le plus gros explosif que vous ayez jamais vu. Mais qu\'est-ce que les gobelins comptaient bombarder avec un tel engin ?|n|nÀ vos yeux, la bombe paraît presque terminée. Les gobelins semblent avoir soigné son élaboration : on dirait qu\'elle résiste à toutes les attaques. Et elle est trop grosse pour que vous puissiez la déplacer.|n|nVous feriez mieux d\'aller informer la chasseresse Jalin de l\'existence de cette bombe, à la flèche de Chimétoile, au sud-ouest.', },
    {'Informez la Chasseresse Jalin de l\'existence de la Bombe, à la Flèche de Chimétoile en Orneval.', },
  },
  [13982] = {
    'Les liens du cœur',
    {'Faites attention, $N. Kaliva est toujours dans les parages et quand elle nous a capturés, elle a clairement mentionné votre nom.|n|nSeul son cœur peut nous libérer de ces chaînes, mais je pense qu\'elle vous a tendu un piège !', },
    {'Procurez-vous le Cœur de Kaliva pour Bolyun, au Camp de Bolyun.', },
  },
  [13983] = {
    'Creuser sa propre tombe',
    {'Quand cette bombe sera terminée, on devra l\'apporter à Saurboz.|n|nEt par « on », j\'entends « vous ».|n|nAvec tous ces ennemis qui rôdent dans les parages, je vais devoir créer quelque chose d\'exceptionnel si vous voulez avoir une chance de réussir.|n|nJe peux bricoler l\'un de ces déchiqueteurs détraqués, mais il va me falloir quelques pièces détachées. Vous devriez pouvoir en trouver facilement dans les bois, à l\'ouest.|n|nRassemblez-en quelques-unes le temps que je termine de travailler sur la bombe.', },
    {'Le Contremaître Laguigne vous a demandé de rassembler 3 Rouages en bronze, 3 Plaques de cuivre, et 5 Écrous d\'assemblage.', },
  },
  [13984] = {
    'Sur les traces de nos moindres mouvements',
    {'Le groupe d\'éclaireurs orcs utilise des loups pisteurs. Il y a de fortes chances que leur chef soit lui-même un éleveur de loups.|n|nApportez-moi les colliers portés par ces loups et nous mettrons l\'un de nos limiers sur leurs traces.', },
    {'Gwen Armstead, à Triste-bourg, vous a demandé de lui rapporter 3 Colliers à clou de loup.', },
  },
  [13985] = {
    'Nettoyer le sanctuaire',
    {'Il faut mettre un terme à l\'invasion maléfique de la Légion ardente !|n|nVous avez vaincu l\'un de leurs démons les plus puissants, $N, mais ils sont encore nombreux dans les bois, à l\'est du sanctuaire de Scarfeu.|n|nEn tant qu\'$Gami:amie; de la forêt, accepteriez-vous d\'aller abattre ces infâmes créatures ? Vous devrez ensuite aller prévenir Grand-baobab, le grand ancien de guerre du sanctuaire d\'Aessina, au nord-est.', },
    {'Tuez 12 démons au Sanctuaire de Scarfeu.', },
  },
  [13986] = {
    'Une collègue blessée',
    {'La bataille fait rage ici, $C, comme vous avez dû le constater. Nous tenons bon, mais tout le monde n\'en est pas sorti indemne.|n|nUne guerrière de notre groupe, Aponi Crin-brillant, est tombée malade suite à une blessure au bras qui s\'est infectée. Elle a été rapatriée aux Pitons-du-Tonnerre pour être remise sur pied. On dirait qu\'elle a oublié son bouclier au front dans la confusion du départ. Est-ce que vous pourriez le lui rapporter, et lui transmettre tous nos vœux de rétablissement ? Son sourire nous manque, ici.|n|nVous la trouverez sur la cime des Anciens, aux Pitons-du-Tonnerre.', },
    {'Apportez le Bouclier tribal endommagé à Aponi Crin-Brillant sur la Cime des Anciens, aux Pitons-du-Tonnerre.', },
  },
  [13987] = {
    'La bataille finale',
    {'$N, il faut absolument que vous m\'aidiez ! Je ne pourrai pas repousser indéfiniment l\'assaut démoniaque. Si je cède, Astranaar sera leur prochaine cible !|n|nJe vous en supplie, aidez-moi !', },
    {'Tuez 30 Envahisseurs démoniaques.', },
  },
  [13988] = {
    'Un problème croissant',
    {'Un foisonnement de vie sur des terres incultes… Mon compagnon Jerrik m\'a décrit des évènements similaires qui sont arrivés ailleurs dans les Tarides. Je dois m\'en rendre compte par moi-même, mais je ne peux pas abandonner mon poste.|n|nTenez, $N, je vous prête mes « yeux ». Mon compagnon aigle me sert depuis que je suis né. Accompagnez-le jusqu\'au sommet de Tête-tonnerre, où Jerrik vous attend, et nous examinerons le phénomène.|n|nPour arriver au sommet, suivez la route à l\'est de la Croisée et tournez au sud quand vous atteindrez une grosse pierre couverte de peintures.', },
    {'Apportez les Yeux de Tonga au Sommet de Tête-tonnerre, au sud-ouest de Cabestan.', },
  },
  [13989] = {
    'Roi des Vile-sylve',
    {'Je n\'éprouve pas beaucoup de sympathie pour votre espèce, $R. Mais je veux sauver les furbolgs.|n|nEmportez cette bannière un peu au nord-est, dans le village des Pattes-vertes, et placez-la sur le tertre de leur totem. Ils considéreront cela comme une agression et essaieront de la détruire. Contenez leurs assauts jusqu\'à ce que leur chef, Murgut, apparaisse pour sauver l\'honneur de sa tribu, puis tuez ce traître !|n|nÉconomisez vos forces, mon $Gami:amie;, car le combat promet d\'être long.', },
    {'Placez la Bannière dent-rouge sur le Tertre du totem Vile-sylve. Ne laissez pas les furbolgs détruire la bannière avant que leur chef n\'arrive. Tuez le Chef Murgut.', },
  },
  [13990] = {
    'Promo Upper Deck - Monture poulet',
    nil,
    nil,
  },
  [13991] = {
    'La paie dérobée',
    {'Eh bien, $N. J\'admets que vous avez votre place dans ma Horde bien-aimée. Vous m\'avez montré votre force, votre habileté, votre sens de l\'initiative... Même Thork a récemment mentionné votre nom, et pourtant ni lui ni moi ne nous laissons facilement impressionner. Beau travail.|n|nIl est temps à présent que vous fassiez votre part du travail. La paie des gardes de la Croisée pour la semaine a disparu. Gazrog à Cabestan mène l\'enquête. Allez lui parler !|n|nIl suffit de suivre la route à l\'est d\'ici vers la côte.', },
    {'Parlez à Gazrog près de l\'entrée de Cabestan.', },
  },
  [13992] = {
    'Une petite diversion',
    {'J\'ai été envoyé ici en reconnaissance pour observer l\'activité centaure. J\'ai surveillé leurs moindres mouvements pendant des jours ! Il est temps pour moi de partir discrètement, mais ils ont cerné cette oasis.|n|nVous avez l\'air d\'une personne dangereuse. Pouvez-vous faire beaucoup de bruit pour moi ? Provoquez-les ! Tuez-les au hasard. Pendant qu\'ils seront à votre recherche, je me glisserai hors d\'ici pour rapporter mes informations à Regthar Seuil-de-mort.', },
    {'Tuez 8 Centaures kolkars.', },
  },
  [13993] = {
    'Vous êtes la bombe !',
    {'Très bien, $N. Vous êtes fin $Gprêt:prête;.|n|nJ\'ai programmé l\'itinéraire jusqu\'aux Serres-Rocheuses, vous n\'aurez qu\'à vous soucier de protéger la bombe.|n|nVous pouvez utiliser les lames de scie pour abattre vos ennemis à distance, ou faire sauter un fusible pour tuer ceux qui s\'approchent de trop près. |n|nVous ne pouvez réparer la bombe qu\'UNE seule fois si elle est gravement endommagée. Choisissez le bon moment !|n|nVenez me voir quand vous serez $Gprêt:prête;.|n|nBonne chance !', },
    {'Le Contremaître Laguigne vous a demandé d\'utiliser le Déchiqueteur reconverti pour vous rendre aux Montagnes des Serres-Rocheuses puis d\'aller voir Saurboz.', },
  },
  [13994] = {
    '(PÉRIMÉ)',
    {'Écoutez, $N. Vous devez faire ce que l\'inquisiteur vous a demandé.|n|nIl affirme que la Horde attaque Gilnéas. Si c\'est vrai, alors quelqu\'un doit en informer le clan Cœur-de-loup avant qu\'il ne soit trop tard.|n|nSans compter que Balvus Cœur-de-loup m\'écorcherait vivant s\'il découvrait que je vous ai $Glaissé:laissée; moisir sur les réserves de Grisetête.', },
    {'Parlez à l\'Inquisiteur Blackwell à Triste-bourg.', },
  },
  [13995] = {
    'Le roi de la montagne des centaures',
    {'Nous avons été envoyés ici pour observer les déplacements des centaures kolkars, mais au bout d\'une semaine à observer ces saletés d\'animaux galoper partout autour de cette oasis, ça me démange vraiment d\'aller leur faire goûter ma hache. Qu\'en dites-vous, $C ? Vous voulez faire quelques ravages avec moi ?|n|nVoyons un peu si nous pouvons attirer l\'attention de leur guerrier le plus puissant, Kurak.', },
    {'Veillez à ce que Gorgal Balafre-furieuse reste en vie alors qu\'il se bat contre les centaures et aidez-le à tuer Kurak.', },
  },
  [13996] = {
    'Pouvez-vous prendre cette quête pendant que je suis en combat ?',
    {'Votre mission, si vous arrivez à lire ceci alors que je suis en combat, consiste à tuer cinq de ces maudits kobolds qui me maintiennent tout le temps en combat.|n|nRien que le fait de pouvoir lire ceci est une grande VICTOIRE ! Dan est génial, pas vrai ?!!', },
    {'ELM Cible d\'hébétement sur l\'Île des Concepteurs vous a demandé de tuer 5 ELM attaquants pour Dan et la Grande justice !', },
  },
  [13997] = {
    'Si vous lisez ceci pendant que je suis en train de combattre...',
    {'Dan est le programmeur le plus génial du monde... du monde de Warcraft !|n|nCe n\'était bizarre que vous ne soyez pas capable de discuter avec moi pendant que je me battais ? C\'est fini, mon ami, car Dan a largement amélioré l\'un de mes flags de créature !|n|nFêtez cela avec moi en dégommant ces immondes créatures qui viennent sans arrêt me combattre.', },
    {'ELM Cible d\'hébétement veut que vous tuiez 5 ELM attaquants pour Dan et la Grande Justice !', },
  },
  [13998] = {
    'Les champignons, une valeur sûre',
    {'J\'ai mis en culture ces spores étranges que vous avez trouvées avec un mélange raffiné de... composants... que j\'affectionne particulièrement. Je suis impatient de voir comment mes spores améliorées réagiront aux eaux des oasis de la Croisée.|n|nL\'oasis Stagnante au sud-est devrait nous offrir un site exempt de toute contamination pour notre expérience. Il vous suffit de planter cette culture dans le sol humide n\'importe où autour de l\'oasis et de noter les résultats pour moi.|n|nN\'oubliez surtout pas de vous couvrir la bouche, $C.|n|n<Helbrim vous décoche un sourire désarmant.>', },
    {'Plantez une Culture fongique près de l\'Oasis Stagnante et observez les résultats.', },
  },
  [13999] = {
    'Trafic de champis',
    {'Imaginez un peu le potentiel, $N ! Des vecteurs fongiques à croissance rapide pour toutes sortes de toxines. Mes camarades de Fossoyeuse voudront en être informés.|n|nVoici mes notes et quelques échantillons supplémentaires. Si nous faisons vite, nous pourrons profiter du prochain bateau pour les royaumes de l\'Est. Prenez la route à l\'est d\'ici et suivez-la jusqu\'à la ville gobeline de Cabestan. Cherchez la Taverne de la quille brisée vers le côté sud de la ville et apportez-les à mon associée Sashya à l\'intérieur.', },
    {'Apportez les Recherches de Helbrim à Sashya à Cabestan, dans les Tarides du Nord.', },
  },
  [14000] = {
    'Chasser ou être chassé',
    {'Cela devrait suffire pour pister la personne en charge de leurs bêtes.|n|nApportez ces colliers au veneur Russell. Je lui ai demandé de nous garder l\'un de ces plus fins limiers pour accomplir cette tâche.', },
    {'Apportez les Colliers à clou de loup au Veneur Russell à Triste-bourg.', },
  },
  [14001] = {
    'Les capsules de sauvetage gobelines',
    {'$N, je suis navré, je croyais que vous étiez $Gmort:morte; !|n|nC\'est juste incroyable. Notre navire s\'est retrouvé au milieu d\'une bataille entre l\'Alliance et la Horde !|n|nNos frères et sœurs ont besoin d\'être secourus.|n|n<Il montre toutes les capsules de sauvetage autour de vous.>|n|nJe crois que je vais encore un peu rester assis pour reprendre mon souffle. Pourriez-vous les rejoindre à la nage et les aider à sortir des capsules ? Prenez mes palmes thermohydratiques, vous irez plus vite.|n|nDites à Chipie que je viendrai bientôt.', },
    {'Portez secours à 6 Survivants gobelins.', },
  },
  [14002] = {
    'Un boulot pour un limier',
    {'Regardez les colliers près de ces cages à l\'arrière. Montrez-en un à n\'importe lequel de mes limiers -- ils savent quoi faire.|n|nUne fois qu\'ils auront trouvé ce que vous cherchez, préparez-vous à vous battre. Revenez faire votre rapport au maire quand vous aurez terminé.', },
    nil,
  },
  [14003] = {
    'La réparation du samophlange',
    {'Zut, ce n\'était pas prévu, ça. Je pense que je l\'ai cassé.|n|nMais pas de panique. Rendez-moi service : apportez ça à Brakk, dans le camp. Il retapera ce bibelot en deux temps, trois mouvements !', },
    {'Apportez le Samophlange cassé à Brak Rouspétuyère, dans le campement.', },
  },
  [14004] = {
    'Retour au samophlangeur',
    {'Eh bien, ça n\'a pas marché. L\'intégrité structurelle du samophlange est à son plus-bas historique. Je pourrais ajouter plus de cadrans et peut-être un levier ou deux pour arranger ça, mais… ce serait peut-être pire que mieux.|n|nMais regardez ce que j\'ai découvert en bloquant la soupape de sûreté et en faisant sauter le couvercle du carter de différentiel : le poinçon personnel du « Chef Cuivroncteur ».|n|nRapportez ceci à Krachevalve et dites-lui de trouver ce génie de Cuivroncteur. Quand vous en aurez terminé ici, vous n\'aurez qu\'à me parler et je vous expédierai grâce au téléporteur de Brak.', },
    {'Rapportez les Débris du samophlange rafistolé à Krachevalve, à l\'Avant-poste de Potuyère. Parlez à Wenikee pour qu\'elle vous y téléporte directement.', },
  },
  [14005] = {
    'La vengeance d\'Élune',
    {'Teldrassil se nettoie de la corruption qui a perverti sa croissance pendant ces années. Une tumeur maligne s\'est formée près de la lisière, au sud. Nous avons l\'occasion de l\'attaquer et de faire disparaître la source de gangremousse qui a perverti les Pins-tordus, les sylvains et tout le reste.|n|nGrâce à l\'eau que vous avez récoltée dans les puits de lune et grâce à la puissance retrouvée de Teldrassil, je vais vous accorder de grands pouvoirs pour un court moment. Mettez un terme à cette corruption, $N.', },
    {'Utilisez les pouvoirs qui vous ont été accordés par Tarindrella pour vous frayer un chemin jusqu\'au Cœur de la corruption et détruisez-le.', },
  },
  [14006] = {
    'Lire le manuel',
    {'À l\'époque où j\'étais dans l\'Union des bricoleurs, le chef Cuivroncteur était le meilleur ingénieur que nous avions. Il est parti pour la KapitalRisk peu avant que je quitte l\'union et il a emmené ses meilleures technologies avec lui. Il gardait bien ses secrets et n\'en divulguait que de petits fragments à ses collaborateurs les plus fidèles.|n|nSi c\'est lui qui a construit le samophlange, il doit probablement en détenir le manuel. La dernière fois que j\'en ai entendu parler, il travaillait tout près d\'ici, à l\'entrée de la mine des Pierriers au nord-est. Qu\'il vous donne le manuel, ensuite vous rassemblerez les pages auprès de ses collaborateurs.', },
    {'Reconstituez le Manuel du samophlange.', },
  },
  [14007] = {
    'Le tir assuré',
    nil,
    nil,
  },
  [14008] = {
    'Projectiles des Arcanes',
    nil,
    nil,
  },
  [14009] = {
    'Soins rapides',
    nil,
    nil,
  },
  [14010] = {
    'Eviscération',
    nil,
    nil,
  },
  [14011] = {
    'La frappe primordiale',
    nil,
    nil,
  },
  [14012] = {
    'Immoler',
    nil,
    nil,
  },
  [14014] = {
    'Rapportez-nous nos affaires !',
    {'Nos bombes et nos outils ! Ces singes sournois, à l\'est, les ont tous volés au beau milieu de la nuit !|n|nPouvez-vous y aller et nous rapporter nos affaires, $N ? Sans ces outils, nous n\'avons aucun moyen de quitter cette île !', },
    {'Récupérez 8 Caisses d\'outils.', },
  },
  [14015] = {
    'Une cartographie inachevée',
    {'<Vous ouvez le parchemin, qui dévoile une carte extrêmement précise de Gilnéas, à une exception près. Il manque toute la zone entre la côte et les falaises derrière Triste-bourg.|n|nDes flèches ont également été dessinées. Elles semblent représenter les déplacements de la Horde en Gilnéas. Le maire Armstead trouvera probablement ces informations très intéressantes.', },
    {'Apportez la Carte trempée au Maire Armstead à Triste-bourg.', },
  },
  [14016] = {
    'La malédiction du Chevalier noir',
    {'Je voulais enlever les restes du Chevalier noir de l\'enceinte du tournoi après votre victoire, mais le confesseur d\'argent Paletress a insisté pour qu\'il reçoive un enterrement décent. Depuis, une sombre présence se fait sentir dans le cimetière et les gens ont peur de rendre visite à leurs disparus.|n|nVoulez-vous bien vous rendre au cimetière, tout à l\'est de l\'enceinte du tournoi, et tenter de découvrir ce qui s\'y passe ?', },
    {'La croisée Rhydalla, dans l\'Enceinte du tournoi d\'Argent, vous demande d\'enquêter sur la Tombe du Chevalier noir.', },
  },
  [14017] = {
    'Le destin du Chevalier noir',
    {'Vous dites que les sectateurs ont emporté son corps ? Je ne vois qu\'un endroit où ils ont pu aller, le Guet du nécrorateur, le camp qui se trouve sur la crête, à l\'ouest de l\'enceinte du tournoi.|n|nQuoi qu\'ils fassent, les sectateurs doivent être arrêtés. J\'ai entendu une rumeur, et je crains qu\'elle ne soit vraie… Il paraît que l\'abominable docteur Kohler est parmi eux, à pratiquer son art. Cherchez une hauteur ou un autel qui surplombe le camp des sectateurs, et fouillez-le à la recherche d\'une preuve de ses plans. Ralentissez ses travaux par tous les moyens possibles.', },
    {'Emparez-vous des Ordres du docteur Kohler au Guet du nécrorateur, puis retournez voir la Croisée Rhydalla dans l\'Enceinte du Tournoi d\'argent.', },
  },
  [14018] = {
    'Celui qui cherchait le pardon',
    {'Vous avez entendu la voix de la déesse au puits de lune, $N. Le remède pour sauver Relara se trouve à l\'est, près de la tour de Raynebois. Vous trouverez là-bas celui qui a succombé à la corruption.|n|nAvrus Malmurmure cherche le pardon et la rédemption. C\'est à vous de l\'aider et par là même, je l\'espère, vous aiderez mon enfant.', },
    {'Allez parler à Avrus Malmurmure, à la Tour de Raynebois.', },
  },
  [14019] = {
    'Arrêtez leurs singeries',
    {'Nous avons un sérieux problème avec les singes dans la jungle, à l\'est. Ils ont volé tous nos explosifs, et maintenant ils s\'amusent à les lancer.|n|nIls nous visent même, parfois !|n|nJ\'ai demandé à Bulle Briquet de mettre un peu de nitro dans ces bananes. Aucun singe ne peut résister à un régime de bananes !|n|nTout ce que vous avez à faire, c\'est d\'aller par là et de les nourrir.', },
    {'Nourrissez 10 Singes lanceurs de bombes en leur lançant des Bananes au nitro-potassium.', },
  },
  [14020] = {
    'La Malédiction',
    {'La Malédiction nous a touchés par surprise. Tout allait bien un jour, et le lendemain des villages entiers étaient infestés de worgens hurlants.|n|nSur les ordres du seigneur Grisetête, nous avons trimé jour et nuit pour découvrir un remède... Sans succès, malheureusement.|n|nMais nous avons trouvé ce qui s\'en rapproche le plus. L\'essence distillée de mandragore noire nous permet d\'estomper la plupart des effets de la Malédiction.|n|nMalheureusement, j\'ai perdu mes réserves lors de l\'attaque des orcs. Rapportez-moi autant de mandragore noire que possible, pour que je puisse en distiller l\'essence.', },
    {'Krennan Aranas, à Triste-bourg, vous demande de lui rapporter 8 Mandragores noires.', },
  },
  [14021] = {
    'Troubles mineurs',
    {'Des singes mineurs dotés d\'intelligence !|n|nIl y en a partout à l\'intérieur de la caverne, avec… des pioches ! Il y a là quelque chose de pas naturel, et je suis sûr que c\'est à cause de cette kaja\'mite !|n|nAucun de mes mineurs n\'est sorti. Je n\'en ai presque plus ! Vous voyez dans quelle situation je me trouve, $N.|n|n<Le contremaître baisse la voix.>|n|nCes gars sont loin d\'être aussi bons que mon vieux groupe de trolls de la jungle. Ah, c\'était le bon temps.|n|nPeut-être que vous pourriez escorter mon dernier mineur dans la caverne et faire en sorte que les singes ne s\'approchent pas de lui ? Il nous faut cette kaja\'mite !', },
    {'Escortez le Mineur effrayé à travers la Caverne de kaja\'mite.', },
  },
  [14022] = {
    'Les Bienfaits du pèlerin',
    {'Vous ne voulez pas célébrer les Bienfaits du pèlerin avec nous, $N ? C\'est le moment où chacun d\'entre nous repense au chemin parcouru et à sa bonne fortune. Nous partageons un excellent repas avec nos amis, en nous racontant des histoires.|n|nVous pouvez participer aux excellents banquets des Bienfaits du pèlerin près de toutes les grandes villes, en vous asseyant à une table des Bienfaits et en servant les mets que vous y trouverez.|n|nSi vous voulez apprendre les recettes traditionnelles de cette fête, allez voir Gregory Tabor. Vous le trouverez juste devant les portes de Hurlevent.', },
    {'Parlez à Gregory Tabor, qui se tient devant les portes de Hurlevent.', },
  },
  [14023] = {
    'La farce au pain épicé',
    {'Notre farce au pain épicé est la pierre angulaire de la table des Bienfaits du pèlerin. Cette recette a toujours été très populaire à Hurlevent et elle a maintenant trouvé place dans le livre de cuisine des Bienfaits.|n|nSi vous êtes déjà $Gcuisinier:cuisinière;, allez voir un vendeur des Bienfaits du pèlerin pour vous procurer un exemplaire du livre de cuisine et tous les ingrédients locaux dont vous aurez besoin pour préparer les plats de la fête. Et si vous n\'êtes pas encore $Gcuisinier:cuisinière;, c\'est le moment idéal pour vous y mettre !|n|nUne fois que vous aurez préparé la farce, apportez-la à Jasper Moore près des tables.', },
    {'Préparez 5 portions de Farce au pain épicé puis apportez-les à Jasper Moore au festin qui se déroule à l\'extérieur des portes de Hurlevent.', },
  },
  [14024] = {
    'La tarte à la citrouille',
    {'Cette farce au pain épicé sent délicieusement bon, mais aucun festin des Bienfaits du pèlerin ne saurait se passer de tarte à la citrouille. C\'est l\'un de nos plats favoris, à Hurlevent, car il utilise les citrouilles mûres d\'Elwynn qui ne poussent qu\'ici.|n|nSi vous ne savez pas encore confectionner ce plat, vous trouverez une recette dans votre livre de cuisine des Bienfaits.|n|nVous voudriez bien nous préparer quelques parts de tarte, et les apporter à Edward Winslow, devant Forgefer ? Il doit en manquer, à l\'heure qu\'il est.', },
    {'Confectionnez 5 parts de Tarte à la citrouille et apportez-les à Edward Winslow, au festin qui se tient devant Forgefer.', },
  },
  [14025] = {
    'Direction la ligne de front',
    nil,
    nil,
  },
  [14026] = {
    'Tout a commencé par un gros boum',
    nil,
    nil,
  },
  [14027] = {
    'Face à face',
    {'Mes hommes ont très certainement besoin d\'aide, $N. Nous faisons tout notre possible pour repousser les orcs, mais cela ne suffit pas.|n|nTuez autant de peaux vertes que possible pour faire pencher la balance en notre faveur. Voyons si la férocité pour laquelle votre clan est connu est aussi efficace contre les orcs que contre notre bétail.', },
    {'Le Lieutenant Wright vous a demandé de tuer 10 Envahisseurs orcs.', },
  },
  [14028] = {
    'La sauce aux canneberges',
    {'Si vous n\'avez pas encore essayé la sauce aux canneberges, vous allez vous faire plaisir. Elle est confectionnée à partir des canneberges piquantes des Paluns. Allez en acheter une poignée à la vendeuse des Bienfaits du pèlerin, si vous voulez essayer cette recette.|n|nElle devrait se trouver dans votre livre de cuisine des Bienfaits.|n|nEt si vous en avez le temps, vous pourriez peut-être en apporter à Jasper Moore, devant Hurlevent ? Je lui ai promis de lui en fournir en échange de la tarte que vous venez d\'apporter.', },
    {'Préparez 5 portions de Sauce aux canneberges et apportez-les à Jasper Moore, au festin qui se tient devant Hurlevent.', },
  },
  [14029] = {
    'Briser le siège',
    nil,
    nil,
  },
  [14030] = {
    'Ils sont affamés à Darnassus',
    {'Merci d\'avoir apporté la sauce aux canneberges. Il y a tellement de cuisine à faire que j\'ai à peine le temps de penser à autre chose. Et en plus de mes responsabilités ici, Isaac Allerton à Darnassus est presque à court de tout. J\'imagine que vous seriez $Gprêt:prête; à l\'aider en préparant en vitesse un peu de farce au pain épicé et de tarte à la citrouille ? Le marchand devrait avoir tous les ingrédients dont vous aurez besoin.|n|nVous pourrez sans doute le trouver près des tables de festin près de l\'entrée de Darnassus, juste au-delà de la terrasse des Guerriers.', },
    {'Apportez 5 portions de Farce au pain épicé et 5 Tartes à la citrouille à Isaac Allerton près de l\'entrée de Darnassus.', },
  },
  [14031] = {
    'Immortaliser l\'inconnu',
    {'Salut, $N, il y a d\'étranges peintures rupestres et d\'autres reliques dans la grotte.|n|nPensez-vous que vous pourriez utiliser le clic-clac-flash de la SCK intégré à votre ceinture pour prendre des photos des endroits indiqués ? Ah, profitez-en pour prendre également une photo de l\'autel qui se trouve au fond de la grotte.|n|nJe parie que ces informations intéresseront Chipie.', },
    {'À l\'aide de votre Clic-clac-flash de la SCK, prenez des photos des trois peintures rupestres et de l\'autel pygmée là où vous voyez des appareils photos.', },
  },
  [14032] = {
    'Le nettoyage du camp des kobolds (test de programmation)',
    {'Votre premier travail est de faire un peu de nettoyage, $N. Un clan de kobolds a envahi les bois, au nord. Allez là-bas et attaquez ces vermines. Affaiblissez-les assez, pour qu\'un jour nous puissions les repousser hors de Comté-du-Nord.', },
    {'Tuez 6 Vermines kobolds, puis revenez voir le Maréchal McBride.', },
  },
  [14033] = {
    'Les patates douces confites',
    {'Puisque vous êtes là, vous devriez faire provision de patates douces de Teldrassil. Elles servent à confectionner les meilleures patates douces confites que vous ayez jamais goûtées.|n|nSi vous ne me croyez pas, regardez la recette dans votre livre de cuisine des Bienfaits, et essayez-la. Et s\'il vous en reste un peu, vous pouvez les partager avec Gregory Tabor, au festin qui se tient devant Hurlevent. C\'est l\'un de ses plats favoris, mais à l\'entendre, tout ce que l\'on sert est son plat favori !', },
    {'Confectionnez 5 portions de Patates douces confites et apportez-les à Gregory Tabor, juste devant les portes de Hurlevent.', },
  },
  [14034] = {
    'Racketter Foote',
    {'Toutes ces nouvelles frictions entre l\'Alliance et la Horde allaient mener à des bénéfices exceptionnels, jusqu\'à ce que le contre-amiral Hartley débarque dans MON port et commence à me mettre des bâtons dans les roues. Il recherche et saisit les vaisseaux portant les couleurs de la Horde dans le but de les priver de l\'usage d\'un port neutre.|n|nJe ne vais pas laisser un gros balourd d\'humain tailler dans mes profits ! Allez me chercher les plans de son vaisseau amiral. L\'ingénieur en chef de Hartley est en train de se saouler à la Taverne de la quille brisée juste en haut de la colline...', },
    {'Prenez les Plans du navire à l\'Ingénieur en chef Foote à la Taverne de la quille brisée, à Cabestan.', },
  },
  [14035] = {
    'La dinde rôtie',
    {'Un festin des Bienfaits du pèlerin requiert toujours un magnifique plat de résistance, et je ne parle pas d\'une corne d\'abondance décorative. Non, le grand moment du repas est une magnifique dinde rôtie.|n|nVous trouverez une bonne recette pour la préparer dans votre livre de cuisine des Bienfaits. Pourquoi n\'iriez-vous pas chasser quelques dindes sauvages, pour les rôtir ? Il y a plein de dindes qui se promènent dans la forêt d\'Elwynn, vous devriez en trouver sans difficulté.|n|nQuand vous aurez fini de les rôtir, vous voudrez bien les apporter à Isaac Allerton, près des portes de Darnassus ?', },
    {'Préparez 5 Dindes rôties et apportez-les à Isaac Allerton, près des portes de Darnassus.', },
  },
  [14036] = {
    'Les Bienfaits du pèlerin',
    {'Vous êtes ici pour célébrer les Bienfaits du pèlerin avec nous ? C\'était autrefois le moment où chacun d\'entre nous repensait au chemin parcouru et à sa bonne fortune, tout en partageant un excellent repas avec ses amis. Beaucoup de gens commémorent encore cet évènement.|n|nVous pouvez participer aux banquets des Bienfaits du pèlerin près de toutes les grandes villes, en vous asseyant à une table des Bienfaits et en servant les mets que vous y trouverez.|n|nSi vous voulez apprendre les recettes traditionnelles de cette fête, allez trouver Miles Standish. Vous le trouverez dans la cour au-dessus de Fossoyeuse.', },
    {'Parlez à Miles Standish dans la cour au-dessus de Fossoyeuse.', },
  },
  [14037] = {
    'La farce au pain épicé',
    {'Notre farce au pain épicé est la pierre angulaire de la table des Bienfaits du pèlerin. La recette remonte aux jours meilleurs de Lordaeron et elle a maintenant pris place dans le repas traditionnel.|n|nSi vous êtes déjà $Gcuisinier:cuisinière;, allez voir un vendeur des Bienfaits du pèlerin pour vous procurer un exemplaire du livre de cuisine des Bienfaits et tous les ingrédients locaux dont vous aurez besoin pour préparer les plats de la fête. Et si vous n\'êtes pas encore $Gcuisinier:cuisinière;, c\'est le moment idéal pour vous y mettre !|n|nUne fois que vous aurez préparé la farce, apportez-la à William Mullins près des tables.', },
    {'Préparez 5 portions de Farce au pain épicé puis apportez-les à William Mullins au festin à l\'intérieur de la cour au-dessus de Fossoyeuse.', },
  },
  [14038] = {
    'Une mine attachante',
    nil,
    {'Plantez une Mine-ventouse à l\'endroit le moins épais de la coque du Bellipotent.', },
  },
  [14039] = {
    'Le foyer des Kaldorei',
    {'C\'est un grand honneur que de vous avoir $Grencontré:rencontrée;. Vous êtes le témoignage vivant de la noblesse de votre race.|n|nAllez, et accomplissez cette dernière tâche. Apportez cette eau à Tyrande Murmevent à Darnassus.', },
    {'Remettez le Récipient rempli à Tyrande Murmevent à Darnassus.', },
  },
  [14040] = {
    'La tarte à la citrouille',
    {'Cette farce au pain épicé que vous avez préparée est fantastique, mais aucun festin des Bienfaits du pèlerin ne saurait se passer de tarte à la citrouille. C\'est aussi un plat traditionnel local, car il utilise les citrouilles mûres de Tirisfal qui ne poussent qu\'ici.|n|nSi vous ne savez pas encore confectionner ce plat, vous trouverez une recette dans votre livre de cuisine des Bienfaits.|n|nVous voudriez bien nous préparer quelques parts de tarte, et les apporter à Francis Eaton, devant Orgrimmar ? Il doit en manquer, à l\'heure qu\'il est.', },
    {'Confectionnez 5 parts de Tarte à la citrouille et apportez-les à Francis Eaton, au festin qui se tient devant Orgrimmar.', },
  },
  [14041] = {
    'La sauce aux canneberges',
    {'Vous avez goûté à la sauce aux canneberges ? Elle est faite à partir de canneberges piquantes de la Furie-du-Sud. Allez en acheter une poignée à la vendeuse des Bienfaits du pèlerin, si vous voulez essayer cette recette.|n|nElle devrait se trouver dans votre livre de cuisine des Bienfaits.|n|nEt si vous en avez le temps, vous pourriez peut-être en apporter à Dokin Plaine-lointaine, qui se trouve au pied de l\'ascenseur du côté ouest des Pitons-du-Tonnerre.', },
    {'Préparez 5 portions de Sauce aux canneberges et apportez-les à Dokin Plaine-lointaine, au pied de l\'ascenseur du côté ouest des Pitons-du-Tonnerre.', },
  },
  [14042] = {
    'Munitions à gogo',
    {'Hartley a dû décharger toutes ses munitions sur la plage. Faisons-lui une surprise, $N !|n|nFilez le long de la côte pour trouver ses dépôts de munitions. Faites-les sauter et comme ça, il se retrouvera échoué, à terre et sans armes pendant les réparations du Bellipotent.|n|nAllez-y et je vous retrouverai ici même, à Cabestan.', },
    {'Détruisez 5 Réserves de munitions de Theramore le long de la côte.', },
  },
  [14043] = {
    'Les patates douces confites',
    {'Puisque vous êtes là, vous devriez faire provision de patates douces de Mulgore. Elles servent à confectionner les patates douces confites, l\'un de mes plats favoris du repas des Bienfaits du Pèlerin.|n|nSi vous ne me croyez pas, regardez la recette dans votre livre de cuisine des Bienfaits, et essayez-la. Et si vous retournez à Orgrimmar, apportez-en à Francis Eaton, au festin qui se tient devant la ville. J\'essaie toujours de l\'approvisionner suffisamment, mais tout part si vite, là-bas.', },
    {'Confectionnez 5 portions de Patates douces confites et apportez-les à Francis Eaton, juste devant Orgrimmar.', },
  },
  [14044] = {
    'On creuse sa tombe avec ses dents',
    {'Merci d\'avoir amené les patates douces confites. Il y a encore tant de plats à préparer, j\'arrive à peine à garder le rythme ! Et par-dessus le marché, Miles vient de m\'envoyer un mot pour me prévenir qu\'il était sur le point de tomber à court de farce et de sauce aux canneberges. Si ça ne vous dérange pas trop, pourriez-vous en préparer un peu ? La vendeuse devrait avoir tous les ingrédients nécessaires.|n|nQuant à Miles, vous le trouverez près des tables du festin, dans les ruines au-dessus de Fossoyeuse.', },
    {'Apportez 5 portions de Farce au pain épicé et 5 portions de Sauce aux canneberges à Miles Standish, près de l\'entrée de Fossoyeuse.', },
  },
  [14045] = {
    'Trouver le baron de Longrivage',
    {'Ce sale flibustier de baron de Longrivage était la terreur de ces eaux avant que l\'Alliance ne démolisse sa flotte et n\'embastille les survivants. Est-ce que je suis content pour autant ? Est-ce que j\'ai l\'air d\'avoir de la joie au cœur, $N ?|n|nNon ! Avant d\'être capturé, Longrivage a détourné quelques-uns de mes meilleurs chargements. La rumeur dit qu\'il a enterré son butin avant de se faire serrer. Je veux récupérer ces marchandises ! Trouvez Longrivage dans le camp de l\'Alliance, juste au sud d\'ici et faites-lui cracher l\'emplacement de MON trésor.', },
    {'Parlez au Baron de Longrivage, le célèbre pirate, après l\'avoir trouvé dans les Tarides du Nord.', },
  },
  [14046] = {
    'Les exigences du baron',
    {'Ch\'suis mûr pour la potence, matelot, ça c\'est sûr. Ce trésor, il ne me sert à rien pour le moment…|n|nÀ moins que je l\'utilise pour me sauver la mise… Je vais faire un marché avec vous, $R. Libérez-moi de ces fers et je vous dirai où mon magot est enfoui.|n|nOh, vous pouvez me croire sur parole, $Gl\'ami:chérie;. J\'étais un vrai baron, dans le temps, vous savez.', },
    {'Si vous lui faites confiance, parlez au Baron de Longrivage pour le libérer de ses menottes.', },
  },
  [14047] = {
    'La dinde rôtie',
    {'Un festin des Bienfaits du pèlerin requiert toujours un magnifique plat de résistance, et pour nous, c\'est une dinde rôtie. Il n\'y a rien de mieux pour couronner le repas.|n|nVous trouverez une bonne recette pour la préparer dans votre livre de cuisine des Bienfaits. Pourquoi n\'iriez-vous pas chasser quelques dindes sauvages, pour les rôtir ? Il y a plein de dindes qui se promènent dans les clairières de Tirisfal, vous devriez en trouver sans difficulté.|n|nQuand vous aurez fini de les rôtir, vous voudrez bien les apporter à Francis Eaton, devant Orgrimmar ?', },
    {'Préparez 5 Dindes rôties et apportez-les à Francis Eaton, près des portes d\'Orgrimmar.', },
  },
  [14048] = {
    'Il n\'y aura jamais assez de dinde',
    {'Je n\'ai pas arrêté de faire la cuisine depuis le début de la fête, et je n\'arrive pas à satisfaire toute la demande. Vous ne voudriez pas m\'aider à préparer l\'un de ces plats ?|n|nOn a du mal à trouver des dindes, par ici, et si vous pouviez me rapporter quelques dindes rôties, ça me rendrait un fier service. Si vous voulez les préparer vous-même, vous pouvez les chasser n\'importe où dans la forêt d\'Elwynn. Vous devriez pouvoir acheter tout ce dont vous aurez besoin à n\'importe quel vendeur des Bienfaits du pèlerin.', },
    {'Apportez 20 Dindes rôties à Caitrin Bouilloire-de-fer, devant Forgefer.', },
  },
  [14049] = {
    'Une drôle de carte',
    {'Voilà le marché, marin d\'eau douce : Pour protéger ma carte au trésor, je l\'ai tatouée sur le crâne de mon second.|n|nBien sûr, il est mort à l\'heure qu\'il est, ainsi que la plupart de mon équipage. L\'Alliance ne connaît même pas sa chance : la tête de mon second est pendue à un arbre à l\'entrée de ce camp.|n|nAttrapez cette tête et apportez-la à Gazleu, à Cabestan.', },
    {'Procurez-vous la Tête tatouée exposée à l\'entrée de la base de l\'Alliance.', },
  },
  [14050] = {
    'La fortune de Gazleu',
    {'Sabordelipopette, vous aviez raison ! Il y a une carte tatouée sur ce crâne.|n|nCe maudit Baron. Il a enterré mon trésor juste sous mon nez. Ou plutôt au-dessus de ma tête. La carte indique un endroit sur les hauteurs qui surplombent Cabestan, au sud.|n|nSuivez la route à l\'ouest en sortant de la ville, montez en haut de la colline, dirigez-vous vers le sud, puis reprenez la direction de la côte et cherchez un arbre énorme qui surplombe la baie. Cherchez mon trésor, et je le partagerai avec vous !', },
    {'Gazleu veut que vous déterriez son trésor en haut des falaises qui surplombent Cabestan.', },
  },
  [14051] = {
    'N\'oubliez pas la farce !',
    {'Approvisionner sans cesse ces tables est une tâche écrasante ! Il faut que je prépare la sauce aux canneberges, tout en surveillant du coin de l\'œil les patates douces et faisant attention à ce que les tartes ne brûlent pas.|n|nJe pense que tout est prêt… Non, attendez, j\'ai oublié quelque chose : la farce ! Oh non. Je ne vais pas avoir le temps de préparer une nouvelle fournée de farce ! Vous ne voudriez pas m\'aider ? Cela ne devrait pas vous prendre trop longtemps d\'acheter ou de confectionner un peu de farce, et vous pouvez trouver tous les ingrédients ici même.', },
    {'Apportez 20 portions de Farce au pain épicé à Caitrin Bouilloire-de-fer, au festin qui se trouve devant Forgefer.', },
  },
  [14052] = {
    'Fomenter avec Tony',
    {'Cette histoire de pirates freine vraiment mon commerce. Le cap\'taine Garvey attaque tout ce qui bouge, même les navires dont les armateurs m\'ont acheté l\'assurance « tous risques » bidon. Il faut mettre ces pirates au pas, et vite !|n|nJ\'ai l\'homme qu\'il nous faut pour ça : un des hommes de Garvey avec qui je suis en cheville. Il m\'a proposé d\'organiser une petite mutinerie dans l\'équipage. Une fois que ces gars travailleront pour nous, ce sera du gâteau, vous saisissez ?|n|nParlez à mon contact sur l\'île de la Dispute, au sud. Il s\'appelle Tony Deux-Défenses.', },
    {'Parlez à Tony Deux-Défenses sur l\'Île de la Dispute, dans les Tarides du Nord.', },
  },
  [14053] = {
    'On est encore à court de sauce ?',
    {'Mon époux, Jasper, devait préparer une nouvelle marmite de sauce aux canneberges, mais il est trop occupé à s\'assurer qu\'il reste assez de patates douces confites pour tous les invités. Vous voulez bien nous aider ? Si vous savez cuisiner, vous pourrez trouver les canneberges des Paluns nécessaires auprès de la vendeuse des Bienfaits du pèlerin installée devant Forgefer.|n|nSi vous n\'avez pas envie de vous mettre aux fourneaux, vous pouvez toujours demander à quelqu\'un d\'autre de préparer la sauce.', },
    {'Apportez 20 portions de Sauce aux canneberges à Ellen Moore, au festin qui se tient devant Hurlevent.', },
  },
  [14054] = {
    'C\'est du gâteau',
    {'Isaac se donne beaucoup de mal pour enseigner aux participants la tradition du festin des Bienfaits et comment préparer les plats à partir des ingrédients que l\'on trouve à cette époque de l\'année. J\'essaye d\'approvisionner les tables avec un maximum de plats, mais nous commençons à manquer de la recette favorite d\'Isaac, la tarte à la citrouille.|n|nVous voulez bien aller nous en chercher ? Si vous voulez préparer les tartes vous-même, il faudra que vous achetiez des citrouilles mûres d\'Elwynn à la vendeuse des Bienfaits du pèlerin installée devant Hurlevent.', },
    {'Apportez 20 Tartes à la citrouille à Mary Allerton, au festin qui se tient près des portes de Darnassus.', },
  },
  [14055] = {
    'Si vous avez la patate...',
    {'Ma femme Ellen m\'a recruté pour l\'aider à approvisionner les tables, mais elle n\'arrive pas à se décider. J\'ai d\'abord fait des tartes à la citrouille, mais elle a changé d\'avis et elle veut maintenant des patates douces confites.|n|nBon, j\'ai déjà commencé les tartes, alors vous pourriez peut-être m\'aider à récupérer ces patates douces ? Elle aura une belle surprise si nous pouvons préparer tout ce qu\'elle a demandé.|n|nSi vous souhaitez cuisiner vous-même les patates douces, vous pouvez acheter les ingrédients à la vendeuse des Bienfaits du pèlerin installée à Darnassus. Merci, $N.', },
    {'Apportez 20 Patates douces confites à Jasper Moore, au festin qui se tient devant Hurlevent.', },
  },
  [14056] = {
    'Glomp trône dessus',
    {'Quoi ? C\'est Tournoupette tout craché, de vouloir une mutinerie au rabais.|n|nPas grave, mec, on peut le faire. Tout d\'abord, il nous faut le blé. Le cap\'taine Garvey, il aime bien accumuler le butin au fur et à mesure des pillages. C\'est de l\'argent que je peux utiliser pour payer mes mutins triés sur le volet, tu vois ?|n|nLa trésorerie, elle est juste en dehors de cette caserne, et pour accéder au trésor, vous devrez d\'abord vous occuper du « trésorier » du cap\'taine Garvey, tu saisis ? Seulement, Glomp, l\'est pas du genre à se laisser bousculer. J\'ai essayé de le bousculer, une fois. Pas bougé d\'un cheveu, le gars.', },
    {'Tuez Glomp et volez-lui son Butin.', },
  },
  [14057] = {
    'Des flingues. Il nous faut des flingues.',
    {'Alors, une bonne mutinerie, elle doit avoir une vraie puissance de feu, vous voyez ? Le cap\'taine Garvey, il s\'est gardé les meilleures armes : toute une cargaison de gros fusils à silex nains. Il les planque près de lui, dans le bâtiment de l\'autre côté de l\'île. Dégottez-moi six de ces fusils et je les distribuerai à mes futurs officiers…', },
    {'Rassemblez 6 Carabines lourdes naines.', },
  },
  [14058] = {
    'Si vous avez la patate...',
    {'Roberta Carter m\'a recruté pour l\'aider à préparer l\'un des plats du festin, les patates douces confites. Normalement, je me serais fait un plaisir de les cuisiner, mais j\'ai promis à l\'hôtesse de l\'aider à surveiller les tables.|n|nJ\'apprécierais beaucoup votre aide, si vous vouliez bien m\'apporter ces patates douces confites. Roberta ne me le pardonnerait jamais si je lui faisais faux bond.|n|nSi vous souhaitez confectionner vous-même les patates douces, vous pouvez acheter les ingrédients à la marchande des Bienfaits du pèlerin installée aux Pitons-du-Tonnerre. Merci, $N.', },
    {'Apportez 20 Patates douces confites à William Mullins, au festin qui se tient au-dessus de Fossoyeuse.', },
  },
  [14059] = {
    'On est encore à court de sauce ?',
    {'J\'aimerais bien savoir pourquoi on se retrouve toujours aussi rapidement à court de sauce aux canneberges. Des fois, je me demande s\'ils ne s\'en servent pas pour nourrir les abominations quand j\'ai le dos tourné. Vous voudriez bien m\'aider à en préparer une nouvelle fournée ? Si vous savez cuisiner, vous pourrez trouver les canneberges de la Furie-du-Sud nécessaires auprès de la vendeuse des Bienfaits du pèlerin installée devant Orgrimmar.|n|nSi vous n\'avez pas envie de vous mettre aux fourneaux, vous pouvez toujours demander à quelqu\'un d\'autre de préparer la sauce.', },
    {'Apportez 20 portions de Sauce aux canneberges à Roberta Carter, au festin qui se tient au-dessus de Fossoyeuse.', },
  },
  [14060] = {
    'C\'est du gâteau',
    {'Dokin et Laha se donnent beaucoup de mal pour apprendre aux participants la tradition du festin des Bienfaits, et comment préparer les plats à partir des ingrédients que l\'on trouve à cette époque de l\'année. J\'essaye d\'approvisionner les tables avec un maximum de plats, mais nous commençons à manquer de tarte à la citrouille.|n|nVous voulez bien aller nous en chercher ? Si vous voulez préparer les tartes vous-même, il faudra que vous achetiez des citrouilles mûres de Tirisfal à la vendeuse des Bienfaits du pèlerin installée devant Fossoyeuse.', },
    {'Apportez 20 Tartes à la citrouille à Mahara Blé-Doré, au festin qui se tient devant les Pitons-du-Tonnerre.', },
  },
  [14061] = {
    'Il n\'y aura jamais assez de dinde',
    {'Je n\'ai pas arrêté de faire la cuisine depuis le début de la fête, et je n\'arrive pas à satisfaire toute la demande. Vous ne voudriez pas m\'aider à préparer l\'un de ces plats ?|n|nOn a du mal à trouver des dindes, par ici, et si vous pouviez me rapporter quelques dindes rôties, ça me rendrait un fier service. Si vous voulez les préparer vous-même, vous pouvez les chasser n\'importe où dans les clairières de Tirisfal. Vous devriez pouvoir acheter tout ce dont vous aurez besoin à n\'importe quel vendeur des Bienfaits du pèlerin.', },
    {'Apportez 20 Dindes rôties à Ondani Grand-moulin, devant Orgrimmar.', },
  },
  [14062] = {
    'N\'oubliez pas la farce !',
    {'Approvisionner sans cesse ces tables est une tâche écrasante ! Il faut que je prépare la sauce aux canneberges, tout en surveillant du coin de l\'œil les patates douces et faisant attention à ce que les tartes ne brûlent pas.|n|nJe pense que tout est prêt… Non, attendez, j\'ai oublié quelque chose : la farce ! Oh non. Je ne vais pas avoir le temps de préparer une nouvelle fournée de farce ! Vous ne voudriez pas m\'aider ? Cela ne devrait pas vous prendre trop longtemps d\'acheter ou de confectionner un peu de farce, et vous pouvez trouver tous les ingrédients ici même.', },
    {'Apportez 20 portions de Farce au pain épicé à Ondani Grand-moulin, devant Orgrimmar.', },
  },
  [14063] = {
    'La mutinerie, camarade !',
    {'On arrive à ma partie préférée de la mutinerie : le massacre ! Chez les pirates, on se fiche de savoir qui commande. La vraie question, c\'est qui contrôle les bateaux. La Dague de la vierge, l\'ancien navire amiral de Garvey, est à l\'ancre à la pointe est de cette île. Il y a laissé son plus fidèle officier pour monter la garde : Alicia Cuthbert. Quand on l\'aura neutralisée, le navire sera à nous, et la mer avec, mec.|n|nJe vais faire embarquer mes hommes dans des canots. Je veux que vous montiez à bord de la Dague et que vous sonniez de cette corne sur le pont. Ce sera notre signal pour l\'abordage général. Ha-haarh !', },
    {'Soufflez dans le Cor de signal pirate pour donner l\'ordre à Tony Deux-Défenses et son équipage d\'aborder la Dague de la vierge. Aidez-le à tuer Alicia Cuthbert qui se trouve sur le pont inférieur.', },
  },
  [14064] = {
    'Partager un festin des Bienfaits',
    {'Vous n\'avez pas célébré la fête des Bienfaits du pèlerin comme il faut si vous ne vous êtes pas rempli la panse à une table des Bienfaits.|n|nJe vous en prie, asseyez-vous, et goûtez à tout ! Vous pouvez passer de chaise en chaise, ou demander aux autres personnes de la table de vous passer un peu de leur nourriture.|n|nQuand vous aurez assez mangé de chaque plat, vous serez $Gimprégné:imprégnée; de l\'Esprit du partage.', },
    {'Mangez cinq fois de chacun des plats présentés sur la Table des Bienfaits, jusqu\'à ce que vous gagniez l\'amélioration Esprit du partage.', },
  },
  [14065] = {
    'Partager un festin des Bienfaits',
    {'Vous n\'avez pas célébré la fête des Bienfaits du pèlerin comme il faut si vous ne vous êtes pas rempli la panse à une table des Bienfaits.|n|nJe vous en prie, asseyez-vous, et goûtez à tout ! Vous pouvez passer de chaise en chaise, ou demander aux autres personnes de la table de vous passer un peu de leur nourriture.|n|nQuand vous aurez assez mangé de chaque plat, vous serez $Gimprégné:imprégnée; de l\'Esprit du partage.', },
    {'Mangez cinq fois de chacun des plats présentés sur la Table des Bienfaits, jusqu\'à ce que vous gagniez l\'amélioration Esprit du partage.', },
  },
  [14066] = {
    'Enquête sur les débris',
    {'Il y a peu, une cargaison d\'argent a été volée en chemin entre ici et la Croisée. Cet argent était destiné à payer les gardes, et nous voulons le récupérer.|n|nJe vais interroger les gens par ici à la recherche d\'indices, mais je veux que vous alliez enquêter sur la scène du crime. Partez vers l\'ouest à la recherche d\'un chariot de caravane accidenté juste au nord de la route entre ici et la Croisée. Découvrez qui a pris notre argent, et récupérez-le !', },
    {'Trouvez la caravane accidentée sur la route entre Cabestan et la Croisée et fouillez les environs à la recherche d\'indices.', },
  },
  [14067] = {
    'L\'argent volé',
    {'Il apparaît clairement que ces raptors sont les seuls responsables du vol de l\'argent de la Horde.|n|nL\'heure est venue de donner une bonne leçon à ces sales bêtes.', },
    {'Tuez 8 Ravageurs et 4 Faucheurs solécailles et localisez l\'Argent volé.', },
  },
  [14068] = {
    'La prive au piève',
    {'Piéver des raptors, fa peut f\'avérer danvereux, mais v\'ai confu de nouveaux pièves pour réduire les rifques.|n|nPovez le piève fur le fol et il pouffera un cri de raptor, fe qui devrait les attirer vufqu\'au piève.|n|nQuand un raptor marfe fur un piève à raptor, fa le rétréfit fur-le-famp pour qu\'il foit moins danvereux. F\'est fuper fafile ! Ve ferais bien tout fa moi-même, mais ve fuis tombé fur le roi Griffe-aférée, réfemment.', },
    {'Utilisez le Piève à raptor de Kala\'ma pour capturer 5 Raptors rétréfis.', },
  },
  [14069] = {
    'L\'aide n\'est plus ce qu\'elle était',
    {'J\'ai échoué ! J\'ai fait tout mon possible pour remplir les quotas de production de Kaja\'Cola, mais vous savez comment sont les esclaves trolls, de nos jours. Difficile de trouver une assistance efficace !|n|nVotre façon toute personnelle de régler les problèmes serait très utile. Une décharge de votre gadgetoceinture gobeline devrait faire l\'affaire. Si nous arrivons à corriger quelques trolls défiants, les autres suivront sans broncher.|n|nNous devons poursuivre la production de Kaja\'Cola ou c\'est nous tous qui subirons le courroux du prince marchand !', },
    {'Corriger le comportement de 8 Trolls défiants.', },
  },
  [14070] = {
    'Faites-le vous-même',
    {'Nous devons envoyer un message à plusieurs mauvais payeurs. Bien sûr, cette racaille se cache dans Trimeville. Je sais que vous détestez devoir aller dans ces taudis, boss, mais que pouvons-nous faire ?|n|n<Chipie feuillette rapidement ses papiers.>|n|nJ\'ai là tous les noms.|n|nPuis-je vous suggérer une petite « visite personnelle » ? Un ou deux coups bien placés enverraient également un message à vos autres débiteurs ET à vos concurrents.|n|nIl ne faut pas prendre $N à la légère !', },
    {'Rossez Bruno Lignifuge, Frankie Glissécrou, Jack le Marteau et Savon Magee.', },
  },
  [14071] = {
    'Rouler avec mes potes',
    {'$N, j\'ai entendu dire que vous organisez une fête d\'entreprise qui éclipsera toutes les autres ! Mes études indiquent que si vous êtes $Gvu:vue; en train de vous amuser à cette fête, votre quotient promotionnel grimpera en flèche et atteindra des sommets !|n|nEn gardant ces données en tête, puis-je vous suggérer d\'aller faire un tour avec la voiture de sport de votre entreprise et de passer prendre vos amis en ville ?|n|nOh et n\'oubliez pas ce que j\'ai fait pour vous quand tout ça aura porté ses fruits et que vous serez $Gle nouveau prince marchand:la nouvelle princesse marchande;, d\'accord ?', },
    {'Faites une virée en Voiture de sport et ramassez vos amis Crack, Gobeur et Izzy.', },
  },
  [14072] = {
    'Verog passe à la trappe',
    {'Regthar Seuil-de-mort m\'a envoyée ici pour épier les activités des centaures, mais leur chef est difficile à identifier. J\'ai appris qu\'il s\'appelle « Verog le Derviche », mais j\'ignore toujours où il se trouve.|n|nPouvez-vous m\'aider à creuser un peu la question ? Je sais que les centaures ont l\'intelligence d\'une huître, mais leurs camps sont souvent jonchés de renseignements importants sur leurs activités. Fouillez les tentes des centaures tout autour de l\'oasis Stagnante et rapportez-moi des informations.', },
    {'Retrouvez 4 pages d\'Informations des centaures autour de l\'Oasis Stagnante.', },
  },
  [14073] = {
    'Des renforts pour Seuil-de-mort',
    {'$N ! Votre réputation s\'étend au sein de la Horde. J\'ai eu vent de rapports en provenance des bassins Oubliés et de l\'oasis Stagnante disant que vous avez été un vrai fléau pour nos ennemis centaures. Très beau travail.|n|nRegthar Seuil-de-mort est en charge de nos opérations contre les centaures dans toutes les Tarides du Nord. Il pourrait avoir besoin d\'$Gun courageux:une courageuse:c; $C comme vous pour renforcer ses troupes. Présentez-vous à lui à son avant-poste au bord de la route à l\'ouest d\'ici et apportez-lui toute l\'aide qu\'il vous demandera.', },
    {'Présentez-vous à Regthar Seuil-de-mort à son avant-poste à l\'ouest de la Croisée, dans les Tarides du Nord.', },
  },
  [14074] = {
    'Comment retomber sur ses pattes…',
    {'La Croisade d\'argent a envoyé un vaisseau rapide chargé de viande de haut-trotteur et d\'autres provisions pour nous autres qui vivons dans l\'enceinte du tournoi, mais il n\'est pas arrivé. D\'après les éclaireurs, il aurait été attaqué par les Kvaldirs, des pillards vrykuls qui sillonnent les mers.|n|nIls ont tué l\'équipage et emporté la cargaison sur une île, l\'accostage de Hrothgar. Si vous allez vers le nord, vous la verrez, noyée dans la brume. Voulez-vous nous aider à retrouver les vivres volés ? Sans ces pattes de haut-trotteur, il n\'y aura bientôt plus rien à manger.', },
    {'Récupérer 10 Pilons de haut-trotteur volés pour Narasi Aubeneige, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14075] = {
    'Des problèmes dans les mines',
    {'On a encore des problèmes dans la Kaja\'mine, boss. Les vers des tunnels sont de retour et ils sont littéralement en train de grignoter les marges de la Société Commerciale du Kajaro !|n|nNous avons dû suspendre l\'extraction de kaja\'mite, ce qui a un impact négatif sur la production de Kaja\'Cola!|n|nJ\'ai tenté de faire appel à la société d\'extermination, mais le patron s\'est enfui après sa dernière paye.|n|nVous pensez que vous pourriez entrer dans les trois mines et vous en charger ? J\'vous aurais bien $Gaidé:aidée;, mais je n\'ai pas encore eu l\'occasion d\'assister au séminaire de formation de combattant du cartel.', },
    {'Exterminez 6 Vers tunneliers.', },
  },
  [14076] = {
    'Le petit-déjeuner des champions',
    {'Maintenant que le colisée est achevé, la Croisade d\'argent nous a demandé de l\'aider à s\'occuper des créatures que les champions combattront.|n|nLes jormungars géants ont un régime fort étrange, ils grandissent et deviennent forts en mangeant les œufs de leurs congénères. Les meilleurs œufs viennent des jormungars des profondeurs.|n|nPrenez ce tambour et allez au Pied-mont, au centre des pics Foudroyés. Jouez-en près des monticules de neige que vous verrez là-bas. Faites sortir les jormungars des profondeurs, tuez-les et récupérez leurs cocons d\'œufs.', },
    {'Procurez-vous 4 Cocons d\'œufs de jormungar et remettez-les à Savinia Chanterite dans l\'Enceinte du tournoi d\'argent.', },
  },
  [14077] = {
    'La miséricorde de la Lumière',
    {'J\'ai écouté le discours du confesseur Paletress, et je vous avoue que ses paroles m\'ont donné matière à réflexion. Combattre auprès des croisés ne suffit pas ; nous devons faire nôtre leur mission.|n|nAu large de la côte, au nord, se trouve l\'accostage de Hrothgar. Les kvaldirs y ont envahi un ancien camp rohart et ont massacré les villageois. Prenez ce livre et récitez les sacrements pour les morts en vous tenant près des cadavres des villageois. Leurs esprits pourront alors s\'échapper des brumes étouffant l\'île, et connaître le repos.', },
    {'Utilisez le Livre de prière du confesseur pour célébrer les derniers sacrements sur 8 Villageois tualiq morts, puis retournez voir Narasi Aubeneige dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14078] = {
    'Enfermés !',
    {'Que faites-vous encore là, $Gcitoyen:citoyenne; ? Vous n\'avez pas entendu ? La ville est en état d\'alerte.|n|nAllez voir le lieutenant Walden, il vous donnera les consignes d\'évacuation.', },
    {'Trouvez le Lieutenant Walden à l\'extrémité nord-ouest de la Place des Marchands.', },
  },
  [14079] = {
    'Un cavalier débutant dans la forêt d\'Elwynn',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Randal Hunter.|n|nRandal vit dans la forêt d\'Elwynn, au camp de bûcherons du Val d\'Est, le long de la route qui part à l\'est depuis Hurlevent.', },
    {'Rapportez ce fascicule à Randal Hunter au Camp de bûcherons du Val d\'Est dans la Forêt d\'Elwynn.', },
  },
  [14080] = {
    'Arrêter les agresseurs',
    {'Les kvaldirs, de terribles pillards vrykuls, ont interrompu nos livraisons et ont assassiné les roharts qui habitaient l\'île située au nord. Ils ont rebaptisé les lieux l\'accostage de Hrothgar. Si on les laisse s\'installer là-bas, il ne fait aucun doute que nous serons leur prochaine cible.|n|nLes forces de la croisade sont déjà terriblement occupées à combattre le Fléau, et nous devons défendre l\'enceinte du tournoi. Volez vers le nord depuis l\'enceinte, jusqu\'à ce que vous atteigniez l\'île et attaquez les kvaldirs avant qu\'ils ne détruisent autre chose.', },
    {'Narasi Aubeneige, de l\'Enceinte du tournoi d\'Argent, veut que vous tuiez 10 Kvaldirs.', },
  },
  [14081] = {
    'Un cavalier débutant au bois des Chants éternels',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Perascamin.|n|nPerascamin vit à l\'écurie de Thuron, au sud-est de la porte du Berger lorsque vous sortez de Lune-d\'Argent.', },
    {'Rapportez ce fascicule à Perascamin à l\'Écurie de Thuron, à Lune-d\'Argent.', },
  },
  [14082] = {
    'Un cavalier débutant à l\'Exodar',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Aalun.|n|nAalun se trouve près de l\'entrée de l\'Exodar, sur l\'île de Brume-azur.', },
    {'Rapportez ce fascicule à Aalun à l\'extérieur de l\'Exodar, sur l\'Île de Brume-azur.', },
  },
  [14083] = {
    'Un cavalier débutant en Dun Morogh',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Ultham Corne-de-fer|n|nUltham se trouve à la ferme des Distillambre, en Dun Morogh, sur la route à l\'est de Forgefer.', },
    {'Rapportez ce fascicule à Ultham Corne-de-fer à la ferme des Distillambre en Dun Morogh.', },
  },
  [14084] = {
    'Un cavalier débutant en Dun Morogh',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Binjy Siffleplume.|n|nBinjy se trouve au dépôt de Grillacier, au nord-est de Kharanos en Dun Morogh.', },
    {'Rapportez ce fascicule à Binjy Siffleplume au Dépôt de Grillacier en Dun Morogh.', },
  },
  [14085] = {
    'Un cavalier débutant à Darnassus',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Jartsam.|n|nJartsam vit dans l\'Enclave cénarienne, à Darnassus.', },
    {'Rapportez ce fascicule à Jartsam, dans l\'Enclave cénarienne de Darnassus.', },
  },
  [14086] = {
    'Un cavalier débutant à Orgrimmar',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Kildar.|n|nKildar vit dans la vallée de l\'Honneur, à Orgrimmar.', },
    {'Rapportez ce fascicule à Kildar, dans la Vallée de l\'Honneur d\'Orgrimmar.', },
  },
  [14087] = {
    'Un cavalier débutant à Mulgore',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Kar Chante-l\'orage.|n|nKar vit à Sabot-de-Sang, en Mulgore.', },
    {'Rapportez ce fascicule à Kar Chante-l\'Orage, à Sabot-de-Sang en Mulgore.', },
  },
  [14088] = {
    'Un cavalier débutant en Durotar',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Xar\'Ti.|n|nXar\'Ti vit à Sen\'jin, dans le sud de Durotar.', },
    {'Rapportez ce fascicule à Xar\'Ti, à Sen\'jin au sud de Durotar.', },
  },
  [14089] = {
    'Un cavalier débutant dans les clairières de Tirisfal',
    {'Ce fascicule est une publicité pour un maître d\'équitation et un marchand de montures, envoyée par Velma Warnam.|n|nVelma se trouve à Brill, dans les clairières de Tirisfal.', },
    {'Rapportez ce fascicule à Velma Warnam à Brill dans les Clairières de Tirisfal.', },
  },
  [14090] = {
    'Gormok veut ses frigbolds !',
    {'Deux de mes hommes sont déjà morts en tentant d\'enfermer ce magnataure, Gormok l\'Empaleur, mais la bête écume de rage. Elle hurle pendant des heures en réclamant son frigbold préféré.|n|nSi la Croisade d\'argent n\'avait pas décidé d\'utiliser ce monstre dans le colisée, je l\'aurais abattu de mes propres mains ! Il est peut-être temps de lui ramener ses joujoux. Prenez ce filet et rendez-vous à Plaie-de-Garm, au sud-est des pics Foudroyés. C\'est juste au nord-est du K3. Capturez quelques frigbolds, et priez la Lumière pour que vous ayez trouvé le bon.', },
    {'Servez-vous du Filet lesté pour capturer 8 Suivants Brûleglace, et remettez-les à Savinia Chanterite, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14091] = {
    'Quelque chose ne va pas',
    {'Le lieutenant semble avoir succombé à de graves blessures. Le prince voudra probablement l\'apprendre.|n|nVous entendez des bruits de combat venant du marché.', },
    {'Retournez voir le Prince Liam Grisetête sur la Place des Marchands.', },
  },
  [14092] = {
    'Le petit-déjeuner des champions',
    {'Maintenant que le colisée est achevé, la Croisade d\'argent nous a demandé de l\'aider à s\'occuper des créatures que les champions combattront.|n|nLes jormungars géants ont un régime fort étrange, ils grandissent et deviennent forts en mangeant les œufs de leurs congénères. Les meilleurs œufs viennent des jormungars des profondeurs.|n|nPrenez ce tambour et allez au Pied-mont, au centre des pics Foudroyés. Jouez-en près des monticules de neige que vous verrez là-bas. Le son fera sortir les jormungars des profondeurs. Tuez-les, récupérez leurs cocons d\'œufs et retournez dans l\'enceinte du tournoi.', },
    {'Procurez-vous 4 Cocons d\'œufs de jormungar et remettez-les à Tylos Coursaurore dans l\'Enceinte du tournoi d\'argent.', },
  },
  [14093] = {
    'Une pagaille monstrueuse',
    {'Des worgens ! Mon père m\'avait prévenu que les créations de l\'archimage Arugal étaient devenues incontrôlables.|n|nMais d\'où viennent-ils ?|n|nJe suppose que cela n\'a aucune espèce d\'importance. Aidez-nous à nous débarrasser d\'eux. Nous autres Gilnéens leur montrerons de quoi nous sommes capables !', },
    {'Le Prince Liam Grisetête vous demande de tuer 6 Worgens déchaînés.', },
  },
  [14094] = {
    'Préserver le ravitaillement',
    {'Écoutez, $N. Nous ne pouvons pas les laisser détruire notre ravitaillement.|n|nGilnéas étant coupé du reste du monde, nous ne passerons pas l\'hiver si nous perdons encore des provisions.|n|nAidez-moi à sauver ce que vous pouvez.', },
    {'Récupérez 4 Caisses de fournitures.', },
  },
  [14095] = {
    'L\'identification des restes',
    {'Une dent de kraken entière est une trouvaille exceptionnelle. Le croisé Aubargent voudra certainement la voir.', },
    {'Apportez la Dent de kraken au Croisé Aubargent comme preuve de votre victoire.', },
  },
  [14096] = {
    'Oh bravo, Kul !!!',
    {'Le croisé Kul s\'est encore fourré dans les ennuis, mais cette fois, il n\'est plus le seul en cause. Quand il a vu que les sectateurs montaient un camp au Guet du nécrorateur, à l\'ouest de l\'enceinte du tournoi, Kul a rassemblé quelques aspirants pour les attaquer.|n|nSans le soutien de renforts, Kul et son groupe ont été facilement capturés. Je suis absolument certaine que le culte sacrifiera ses prisonniers, à moins que nous n\'allions les secourir. N\'importe lequel de ces sectateurs est susceptible d\'avoir les clés des cages noires. Trouvez les clés et libérez Kul et les aspirants captifs.', },
    {'Sauvez Kul le Téméraire et 4 Aspirants captifs du Guet du nécrorateur. Lorsque ce sera fait, retournez voir Narasi Aubeneige, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14097] = {
    'Faites-moi partir ce marchand !',
    nil,
    nil,
  },
  [14098] = {
    'L\'évacuation de la place des Marchands',
    {'Les civils ne sont plus en sécurité. Pas même chez eux.|n|nNous faisons tout notre possible pour empêcher les worgens d\'entrer, mais ils sont trop nombreux.|n|nAidez-nous à évacuer les foyers des civils. L\'armée de mon père est basée dans le quartier de la prison et sera plus à même de protéger les citoyens.', },
    {'Évacuez 3 Maisons de civils.', },
  },
  [14099] = {
    'Des ordres royaux',
    {'Il est temps pour vous de partir, $N. Allez dans le secteur Militaire avec les autres civils.|n|nPrésentez-vous auprès de Gwen Armstead lorsque vous aurez traversé le pont au sud-est... Vérifiez que tout le monde va bien.|n|nJe vais rester ici avec les gardes et couvrir la fuite des civils. C\'est un ordre !', },
    {'Parlez à Gwen Armstead dans le Secteur Militaire, au sud-est.', },
  },
  [14100] = {
    'La relique du Cercle terrestre',
    {'Vous avez fait de gros progrès, $N. Maintenant que vous maîtrisez les quatre éléments de base, vous devez apprendre à les équilibrer. Il y a un avantage à cela : avec le temps, vous n\'aurez plus besoin que d\'une seule relique au lieu de vos quatre totems.|n|nPour perfectionner votre maîtrise des éléments, allez parler à Gotura Quatre-vents, dans la vallée de la Sagesse d\'Orgrimmar.', },
    {'Apportez vos quatre totems à Gotura Quatre-vents à Orgrimmar.', },
  },
  [14101] = {
    'Le drottinn Hrothgar',
    {'Les Kvaldirs, des vrykuls des mers qui pillent les navires et les villages côtiers, se sont emparés d\'une île rohart, au nord du détroit. Leur chef, le drottinn Hrothgar, est un pillard chevronné, qui cherche à contrôler ces mers.|n|nTant qu\'il sera au pouvoir, nos transports de troupes et de matériel seront en danger. Nous risquons de nous retrouver échoués ici, à la merci du roi-liche.|n|nNous nous sommes emparés de ce cor kvaldir. Si vous le faites résonner dans le cercle de statues roharts au nord-est de l\'accostage de Hrothgar, le chef kvaldir considérera cet appel comme un défi.', },
    {'Le Haut croisé Adélard, dans l\'Enceinte du tournoi d\'Argent, veut que vous vainquiez le Drottinn Hrothgar.', },
  },
  [14102] = {
    'Le mandebrume Yngvar',
    {'Les kvaldirs sont retournés sur les côtes du Norfendre et si on ne les surveille pas, ils vont bloquer l\'arrivée de notre approvisionnement et de nos renforts. L\'un d\'entre eux, appelé le mandebrume Yngvar, s\'est installé dans une grotte, sur le flanc ouest de l\'accostage de Hrothgar. C\'est depuis cet endroit qu\'il manipule les brumes pour cacher les kvaldirs et les créatures marines qu\'ils commandent.|n|nPrenez ce charme et voyagez vers le détroit au nord de l\'enceinte du tournoi, jusqu\'à l\'accostage de Hrothgar. Trouvez la grotte du mandebrume et utilisez le charme pour le révéler.', },
    {'Le Haut croisé Adélard, dans l\'Enceinte du tournoi d\'Argent, veut que vous tuiez le Mandebrume Yngvar.', },
  },
  [14103] = {
    'La poudre de titane',
    nil,
    nil,
  },
  [14104] = {
    'Ornolf le Balafré',
    {'Ornolf le Balafré est un terrible pillard, célèbre chez ses frères kvaldirs pour ses captures de navires. Depuis la Furie de Bor, ce pirate et son équipage attaquent nos vaisseaux et volent nos marchandises.|n|nOrnolf et ses hommes ont participé au massacre des habitants d\'une île rohart, au nord. Ils l\'ont renommée l\'accostage de Hrothgar. Son navire est à l\'ancre à la pointe orientale du port de l\'île. Prenez cette bannière capturée et déployez-la sur son vaisseau pour le provoquer. Il viendra sans nul doute vous attaquer.', },
    {'Le Haut croisé Adélard, dans l\'Enceinte du tournoi d\'Argent, veut que vous tuiez Ornolf le Balafré.', },
  },
  [14105] = {
    'Le nécrorateur Kharos',
    {'Le Culte des damnés redouble d\'efforts pour nous anéantir. Ses membres s\'enhardissent. Leurs forces se rassemblent au Guet du nécrorateur, sur la crête, à l\'ouest de l\'enceinte du tournoi.|n|nL\'impitoyable nécrorateur Kharos a ordonné à ses hommes de fortifier leurs positions, et se prépare à déchaîner contre nous toute la puissance du culte.|n|nMes hommes préparent la défense en compagnie des vaillants, mais je veux que ce soient des champions comme vous, $N, qui dirigent notre contre-attaque. Trouvez le nécrorateur Kharos et tuez-le.', },
    {'Le Haut croisé Adélard, dans l\'Enceinte du tournoi d\'Argent, veut que vous tuiez le Nécrorateur Kharos.', },
  },
  [14106] = {
    'Quête de test de Na Kada',
    nil,
    nil,
  },
  [14107] = {
    'Le destin des défunts',
    {'La Croisade d\'argent est pour ainsi dire la première organisation qui ose défier le roi-liche. Notre ennemi retourne les esprits des morts contre nous.|n|nCes esprits errent dans la vallée des héros défunts, au sud-ouest de l\'enceinte, entre Aldur\'thar et le rempart Mur-de-fer. La zone est constellée de cristaux d\'âme abandonnés, utilisés par le Fléau pour contrôler les esprits. Collectez ces cristaux, et utilisez-les avec cette relique bénie par la Lumière, pour accorder la paix aux esprits. Ils ont bien mérité leur repos.', },
    {'Le Croisé Aubargent veut que vous apportiez la paix à 6 Esprits de héros défunts.', },
  },
  [14108] = {
    'Sus au kraken !',
    {'Les Saccage-soleil et le Concordat argenté ont envoyé des vaisseaux vers le nord pour attaquer les kvaldirs, à l\'accostage de Hrothgar. Malheureusement, ils ont été interceptés et capturés par un navire kvaldir. Comme si ce n\'était pas suffisant, les kvaldirs ont trouvé le moyen d\'appeler le terrible kraken qui vit dans les profondeurs de la mer Boréale. Si nous voulons que nos marins survivent, ce kraken doit être chassé et le rituel d\'invocation des kvaldirs doit être… interrompu.|n|n$GCroisé:Croisée;, prenez ces lances et un hippogriffe d\'Argent vous conduira à la bataille.', },
    {'Le Croisé Aubargent veut que vous chevauchiez un Hippogriffe d\'Argent, que vous lanciez 8 Lances enflammées sur le Kraken de la mer Boréale, et que vous abattiez 6 Mande-fonds kvaldirs.|n|nVous trouverez des Hippogriffes d\'Argent devant la tente de la Croisade d\'argent, dans l\'Enceinte du tournoi d\'argent.', },
  },
  [14109] = {
    'Un nouveau vous',
    {'Une nouvelle tenue ? Sans blague ! Votre fête fait couler beaucoup d\'encre. Tous les gobelins un tant soit peu célèbres de l\'île seront présents.|n|nEh bien, bon shopping. La rue de la Fauche est très connue pour les offres qu\'on y trouve !', },
    {'Achetez un Bling-bling rutilant à Diastème Dent-d\'argent, une Nouvelle tenue branchée auprès de Szabo et des Lunettes de soleil cool chez Missa Labinocle, dans la Rue de la Fauche.', },
  },
  [14110] = {
    'Un nouveau vous',
    {'Une nouvelle tenue ? Sans blague ! Votre fête fait couler beaucoup d\'encre. Tous les gobelins un tant soit peu célèbres de l\'île seront présents.|n|nEh bien, bon shopping. La rue de la Fauche est très connue pour les offres qu\'on y trouve !', },
    {'Achetez un Bling-bling rutilant à Diastème Dent-d\'argent, une Nouvelle tenue branchée auprès de Szabo et des Lunettes de soleil cool chez Missa Labinocle, dans la Rue de la Fauche.', },
  },
  [14111] = {
    'La relique du Cercle terrestre',
    {'Vous avez fait de gros progrès, $N. Maintenant que vous maîtrisez les quatre éléments de base, vous devez apprendre à les équilibrer. Il y a un avantage à cela – avec le temps, vous n\'aurez plus besoin que d\'une seule relique au lieu de vos quatre totems.|n|nAllez parler au long-voyant Eanuu, près de la Grande forge de Forgefer. Il vous aidera à perfectionner votre maîtrise des éléments.', },
    {'Apportez vos quatre totems au Long-voyant Eannu à Forgefer.', },
  },
  [14112] = {
    'Ça mange quoi, un yéti, d\'abord ?',
    {'Les croisés ont capturé un yéti qu\'ils appellent Glace-hurlante. Il doit participer aux combats du colisée et on nous a demandé de l\'aide pour son entraînement et son entretien.|n|nLes croisés n\'ont pas eu l\'air d\'apprécier mon idée de le nourrir de quelques Saccage-soleil inutiles. La bête semble apprécier la viande de requin, donc j\'aimerais que vous voliez jusqu\'à la Lame argentée, qui est ancrée dans le détroit, vers le nord. Prenez des appâts frais dans l\'un des seaux sur le bateau, et jetez-les à la mer pour attirer les requins.', },
    {'Savinia Chanterite, dans l\'Enceinte du tournoi d\'Argent, veut que vous lui apportiez 3 morceaux de Chair de requin de la mer Boréale.', },
  },
  [14113] = {
    'Membre d\'honneur',
    {'Waouh, bébé ! Tout le monde est là ! On se fiche de ce stupide dragon !|n|nLa fête bat son plein autour de la piscine. On dirait qu\'ils s\'amusent tous comme des fous. Et toi, tu vas être tellement $Gélégant:élégante; !|n|nPourquoi ne vas-tu pas près de la piscine pour divertir tes invités ? Je te rejoins dans un tout petit instant... Il faut juste que je me glisse dans une robe encore plus magnifique !', },
    {'Revêtez votre Tenue de fête sensationnelle (Lunettes de soleil cool, Nouvelle tenue branchée et Bling-bling rutilant), puis dirigez-vous vers la fête à la piscine du Quartier général de la SCK et divertissez 10 Bambocheurs de Kezan.', },
  },
  [14114] = {
    'Un nouveau vous (suivi d\'évènement)',
    nil,
    nil,
  },
  [14115] = {
    'Les trouble-fête pirates',
    nil,
    {'Tuez 12 Trouble-fête pirates pour sauver votre carrière.', },
  },
  [14116] = {
    'Un invité indésirable',
    {'Pendant que vous vous occupiez des pirates, j\'ai aperçu le prince marchand se faufiler à l\'étage. Il est sur le balcon en haut des marches.|n|n$N, je crois que c\'est lui qui a envoyé les pirates.|n|n<Chipie a un mouvement de recul.>|n|nVous devriez y aller au plus vite ! Je ne le ferais pas attendre, si j\'étais vous.', },
    {'Parlez au Prince marchand Gallywix à l\'étage du bâtiment principal du Quartier général de la SCK, sur Kezan.', },
  },
  [14117] = {
    'Les yeux d\'Orneval',
    {'Nos ennemis sont partout, $C, jusque sur le pas de notre porte. Les elfes de la nuit ont renforcé la halte de Talrendis dans l\'intention de mettre un terme à notre avancée en Orneval. En ce moment même, leurs éclaireurs patrouillent dans les collines à proximité, relevant toutes les allées et venues qui passent par ces portes.|n|nIl faut supprimer ces yeux d\'Orneval.|n|nAllez-y. Vos proies rôdent tout autour de ces portes, surtout à l\'est. Massacrez les éclaireurs qui nous espionnent !', },
    {'Tuez 8 Éclaireurs de Talrendis.', },
  },
  [14118] = {
    'Une livraison de venaison',
    {'Au fur et à mesure que nous épuisons les ressources de cette terre pour nos machines de guerre, nous privons les animaux de la région de leur habitat naturel. S\'ils doivent mourir, ce serait dommage de gaspiller leur viande alors qu\'Orgrimmar est pleine de ventres affamés.|n|nAllez tuer les cerfs sabot-de-mousse qui subsistent dans la région et récupérez leur viande pour nos péons et nos grunts.', },
    {'Récupérez 15 Tranches de venaison sur des Cerfs sabot-de-mousse affaiblis.', },
  },
  [14120] = {
    'Mille milliards de radis ?!',
    {'Vous êtes $Gun jeune gobelin:une jeune gobeline; très $Gambitieux:ambitieuse;, $N. Peut-être même un peu trop pour votre propre bien. J\'ai l\'impression de me revoir à votre âge.|n|nJe vais vous faire une offre. Vous avez peut-être remarqué que le mont Kajaro est en train d\'exploser à cause de votre dragon. Tous les habitants de Kezan vont mourir !|n|nMais si vous me rapportez mille milliards de radis avant que mon voilier ne quitte l\'île, je m\'assurerai que vous soyez $Gl\'un des heureux élus:l\'une des heureuses élues; à s\'échapper.|n|nSi vous voulez vivre, vous feriez bien de trouver rapidement une solution pour me rapporter mon flouze !', },
    {'Parlez à Chipie Serrelavis au Quartier général de la SCK, sur Kezan.', },
  },
  [14121] = {
    'Robin des bois moderne',
    nil,
    {'Utilisez votre Voiture de sport pour renverser 12 Pillards embauchés et récolter 12 Butins volés par la même occasion.', },
  },
  [14122] = {
    'Le casse du jour',
    {'Tous vos actifs ont été gelés et la Banque Centrale de Kezan a fermé ses portes !|n|nVous avez besoin d\'un sacré paquet de flouze, boss. Je crois bien que vous allez devoir voler votre propre argent à la banque ! Les différents outils de votre gadgetoceinture gobeline devraient suffire à ouvrir le coffre.|n|nEspérons seulement que vous avez économisé suffisamment pour le cas où vous auriez chaud aux fesses, comme je vous l\'avais conseillé. Vous l\'avez peut-être remarqué mais... le coup de chaleur risque de durer un bon moment !!!', },
    {'Faites sauter le coffre de la Banque Centrale de Kezan pour récupérer vos Biens personnels.', },
  },
  [14123] = {
    'On entre et on ressort',
    {'Il n\'y a qu\'un moyen d\'obtenir mille milliards de radis : les voler aux riches !|n|nCet abject prince marchand a volé de nombreux objets d\'art et antiquités. Il est temps de les lui reprendre et de les distribuer aux nécessiteux... à commencer par nous !|n|nHobart a laissé une coiffe sur laquelle il travaillait. C\'est un déguisement qui vous fera passer pour l\'un des malabars de Gallywix. Tout ce que vous devez faire, c\'est rentrer dans sa villa, à l\'ouest, et vous « procurer » ce qui nous intéresse.|n|nUn conseil, faites attention à ses cochons, ils sont capables de renifler les intrus malgré leur déguisement !', },
    {'Obtenez l\'Épervier de Maldy, La Gobeline Lisa et la Bombe ultime.', },
  },
  [14124] = {
    'L\'extraction de la kaja\'mite',
    {'$G Monsieur: Madame, il nous faut des tonnes de moolah pour payer le prince du commerce et descendre de Kezan! Eh bien, il y en a des tonnes qui n\'attendent que la descente dans la Kaja\'mine!|n|nT, ce sont les derniers gisements connus de kaja\'mite. C\'est la matière première qui a fait de nous les génies et les alchimistes que nous sommes aujourd\'hui. Si cela ne vaut pas un bazillion de macarons, je ne sais pas ce que c\'est!|n|nTake quelques-unes de mes kablooey bombes et fait sauter les dépôts. Ensuite, prenez les morceaux.|n|nJessez-vous aux trolls rebelles!', },
    {'Collectez 12 Morceaux de kaja\'mite.', },
  },
  [14125] = {
    nil,
    {'Nous y sommes presque, mais nous n\'avons pas encore assez de radis. J\'ai donc élaboré un plan : nous allons nous servir de la police d\'assurance du quartier général !|n|nJe me suis permis de ranger les feux d\'artifice qui restaient de votre petite fête dans le bâtiment. Tout ce que vous avez à faire, c\'est d\'entrer et de saboter quelques installations.|n|nJe pense notamment au générateur défectueux, au poêle qui fuit et au lit inflammable. Ensuite, ressortez et utilisez le panneau de commandes pour envoyer le gazbot.|n|nC\'est un plan infaillible !', },
    {'Surchargez le Générateur défectueux, activez le Poêle qui fuit, laissez tomber un cigare sur le Lit inflammable et utilisez le Gazbot pour mettre le feu au Quartier général de la SCK !', },
  },
  [14126] = {
    'Les économies de toute une vie',
    {'Nous avons tout le flouze dont nous avons besoin. Il n\'y a plus qu\'une chose à faire, boss. Allez sur le bateau du prince marchand. Il va bientôt lever l\'ancre !|n|nNous avons intérêt à nous dépêcher. Montez, je prends le volant.', },
    {'Cédez vos Économies d\'une vie au Prince marchand Gallywix sur le Voilier du prince marchand, sur Kezan.', },
  },
  [14127] = {
    'Le retour des Bien-nés ?',
    {'Le cachet de cire qui scellait ces ordres semble avoir été récemment brisé. L\'écriture du texte est soignée mais vous ne savez pas lire la langue des elfes de la nuit. Cependant, une petite carte dessinée à la main indique les ruines à proximité. En dessous de la carte, des runes sont inscrites dans une langue complètement différente, avec une encre aux reflets métalliques.|n|nCette importante découverte intéressera certainement Ag\'tor.', },
    {'Apportez les Ordres de l\'éclaireur à Ag\'tor Poing-de-sang, à la Porte d\'Azshara.', },
  },
  [14128] = {
    'Le retour des Bien-nés ?',
    {'Nos alliés elfes de sang font des recherches sur le site de fouilles des ruines indiquées sur la carte depuis quelque temps, et peuvent probablement comprendre ce texte mystérieux. Cherchez une elfe de sang nommée Malynéa Saccagecieux. Elle dirige ses recherches depuis la station d\'Orgrimmar du fusorail, juste au nord d\'ici. Cet endroit fait partie du nouveau système de transport gobelin qui sillonne cette terre. Dépêchez-vous !', },
    {'Apportez les Ordres de l\'éclaireur à Malynéa Saccagecieux, à la Station d\'Orgrimmar du fusorail.', },
  },
  [14129] = {
    'Déchiqueteur emballé !',
    nil,
    nil,
  },
  [14130] = {
    'Un ami haut en couleur',
    {'Mes frères et moi sommes pourchassés.|n|nNotre père vient d\'être tué et le Vol draconique noir veut expulser tous ceux de notre espèce encore en vie. Je suis ici pour trouver Azuregos et le conduire en sécurité, si seulement il voulait bien se laisser faire.|n|nAzuregos a peu d\'amis, et ceux qu\'il a sont un peu… spéciaux. Le seul que je connaisse est un murloc du nom d\'Ergll. Vous devriez le trouver sur la côte, au nord-est d\'ici.|n|nFaites votre possible pour trouver Azuregos et envoyez-le-moi.|n|nJe vous en prie, hâtez-vous.', },
    {'Trouvez Ergll sur la côte des Ruines d\'Arkkoran.', },
  },
  [14131] = {
    'Un petit remontant',
    {'Azuregos… Azuregos. Azy ? Le dragon ? Bien sûr, qu\'on est amis ! Y m\'a appris à parler. Y disait qu\'il aimait ma teinte… Il a un truc avec les couleurs, hein ?|n|nMe rappelle pas où il est allé. Mmhh… y me faudrait quelque chose pour me rafraîchir la mémoire !|n|nJe plante du kaphay partout sur la plage. Ça aime le sable, ça. Plutôt bizarre.|n|nVous pourriez aller en récupérer un peu ?', },
    {'Récupérez 10 Fèves de kaphay sur les kaphayers dans les Ruines d\'Arkkoran.', },
  },
  [14132] = {
    'C\'est vraiment mal élevé !',
    {'Je partagerais bien avec eux, s\'ils me le demandaient. Mais ils vont juste faire clic-clac sur mon kaphay ! Y sont vraiment mal élevés ! Vous devriez leur donner une bonne leçon.|n|nStupides makrinnis.', },
    {'Tuez 10 Makrinnis dans les Ruines d\'Arkkoran.', },
  },
  [14133] = {
    'Le véritable chemin pour toucher un mage…',
    {'Maintenant que vous avez terminé de rendre service à Ergll, il est temps qu\'il vous donne des informations concernant Azuregos. Parlez-lui et voyez s\'il peut vous donner des pistes sur l\'endroit où Azuregos pourrait se trouver.', },
    {'Interrogez Ergll à propose d\'Azuregos.', },
  },
  [14134] = {
    'Il faut bûcher',
    {'Maintenant que vous maîtrisez cette machine, je vous propose d\'aller récupérer le bois que j\'étais censé amasser. Sinon, ces orcs vont ME transformer en catapulte !|n|nLe bois fraîchement coupé doit être empilé partout autour d\'ici. Utilisez le déchiqueteur pour récupérer tout le bois que vous pouvez.', },
    {'Utilisez le Déchiqueteur reprogrammé pour récupérer 6 piles de Bois d\'Azshara. Si vous perdez votre déchiqueteur, vous pouvez en attaquer un autre et le reprogrammer.', },
  },
  [14135] = {
    'Une coupe sombre',
    {'Attendez une seconde, je vais brancher les commandes de votre scie circulaire.|n|nDes tireurs elfes de la nuit de Talrendis sont embusqués dans les arbres et tirent au hasard sur mes ouvriers. Je veux que vous vous débarrassiez de ces snipers… en abattant d\'abord les arbres. Cherchez des arbrisseaux d\'Azshara, à l\'est des portes principales. Votre déchiqueteur saura quoi faire. Allez bûcher !', },
    {'Utilisez la scie circulaire du déchiqueteur pour abattre des Arbrisseaux d\'Azshara, et tuez 9 Snipers de Talrendis dès que vous les apercevez.', },
  },
  [14136] = {
    'Secours en mer',
    {'Les kvaldirs ont établi leur camp sur l\'Accostage de Hrothgar, une petite île au nord. Nous avons envoyé le capitaine Aerthas Faucon-de-feu dans cette zone, mais ses troupes sont tombées sur un raid de kvaldirs qui venait attaquer le tournoi d\'Argent ! Le Faucon-de-feu est maintenant la cible des kvaldirs, en grande supériorité numérique. Rendez-vous là-bas, et montrez-leur ce qu\'il en coûte de s\'attaquer aux Saccage-soleil.|n|nLe Faucon-de-feu se trouve entre l\'Accostage de Hrothgar, au nord, et l\'enceinte du tournoi d\'Argent, dans la partie ouest du trajet du Saccageur des mers.', },
    {'Girana Premier-sang, de l\'Enceinte du tournoi d\'Argent, veut que vous tuiez 8 Berserkers kvaldirs et 3 Harponneurs kvaldirs à bord du Faucon-de-feu.', },
  },
  [14137] = {
    'Formation de classe (suivi d\'évènement)',
    nil,
    nil,
  },
  [14138] = {
    'La main à la pâte',
    {'Le contremaître Mèchumide vous cherche partout à cause des problèmes que nous avons dans la Kaja\'mine. Il a parlé de « trolls défiants ».|n|nLa kaja\'mite que nos trolls minent est primordiale dans la fabrication du Kaja\'Cola. Cette boisson gazeuse nous rapporte une fortune, et c\'est grâce à ça que vous serez bientôt $Gpromu prince marchand:promue princesse marchande; !|n|nMais tout d\'abord, nous devons faire en sorte que la production reprenne. Vous trouverez le contremaître à l\'est. Tenez, donnez-lui ceci pour le motiver.', },
    {'Apportez l\'Encouragement de Chipie au Contremaître Mèchumide au Quartier général de la SCK, sur Kezan.', },
  },
  [14139] = {
    'Fin de phase 1 (suivi d\'évènement)',
    nil,
    nil,
  },
  [14140] = {
    'Arrêter les agresseurs',
    {'Les kvaldirs, de terribles pillards vrykuls, ont interrompu nos livraisons et ont assassiné les roharts qui habitaient l\'île située au nord. Ils ont rebaptisé les lieux l\'accostage de Hrothgar. Si on les laisse s\'installer là-bas, il ne fait aucun doute que nous serons leur prochaine cible.|n|nLes forces de la croisade sont déjà terriblement occupées à combattre le Fléau, et nous devons défendre l\'enceinte du tournoi. Volez vers le nord depuis l\'enceinte, jusqu\'à ce que vous atteigniez l\'île et attaquez les kvaldirs avant qu\'ils ne détruisent autre chose.', },
    {'Girana Premier-sang, de l\'Enceinte du tournoi d\'Argent, veut que vous tuiez 10 Kvaldirs.', },
  },
  [14141] = {
    'Gormok veut ses frigbolds !',
    {'Deux de mes hommes sont déjà morts en tentant d\'enfermer ce magnataure, Gormok l\'Empaleur, mais la bête écume de rage. Elle hurle pendant des heures en réclamant son frigbold préféré.|n|nSi la Croisade d\'argent n\'avait pas décidé d\'utiliser ce monstre dans le colisée, je l\'aurais abattu de mes propres mains ! Il est peut-être temps de lui ramener ses joujoux. Prenez ce filet et rendez-vous à Plaie-de-Garm, au sud-est des pics Foudroyés. C\'est juste au nord-est du K3. Capturez quelques frigbolds, et priez la Lumière pour que vous ayez trouvé le bon.', },
    {'Servez-vous du Filet lesté pour capturer 8 Suivants Brûleglace, et remettez-les à Tylos Coursaurore, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14142] = {
    'Oh bravo, Kul !!!',
    {'Le croisé Kul a encore trouvé moyen de se mettre dans les ennuis, mais cette fois, il n\'est plus le seul en cause. Lorsqu\'il a vu que les sectateurs installaient leur camp au Guet du nécrorateur, à l\'ouest de l\'enceinte du tournoi, Kul a rassemblé les aspirants pour monter une attaque.|n|nBien entendu, ils se sont fait capturer. Maintenant, Kul moisit dans une cage, sur la plateforme du camp. Je suis sûre que les sectateurs sacrifieront les prisonniers si nous n\'allons pas les sauver. N\'importe lequel d\'entre eux est susceptible d\'avoir les clés des cages noires. Trouvez les clés et libérez Kul et les aspirants captifs.', },
    {'Sauvez Kul le Téméraire et 4 Aspirants captifs du Guet du nécrorateur. Lorsque ce sera fait, retournez voir Girana Premier-sang dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14143] = {
    'Comment retomber sur ses pattes…',
    {'La Croisade d\'argent a envoyé un vaisseau rapide chargé de viande de haut-trotteur et d\'autres provisions pour nous autres qui vivons dans l\'enceinte du tournoi, mais il n\'est pas arrivé. D\'après les éclaireurs, il aurait été attaqué par les Kvaldirs, des pillards vrykuls qui sillonnent les mers.|n|nIls ont tué l\'équipage et emporté la cargaison sur une île, l\'accostage de Hrothgar. Si vous allez vers le nord, vous la verrez, noyée dans la brume. Voulez-vous nous aider à retrouver les vivres volés ? Sans ces pattes de haut-trotteur, il n\'y aura bientôt plus rien à manger.', },
    {'Récupérer 10 Pilons de haut-trotteur volés pour Girana Premier-sang, dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14144] = {
    'La miséricorde de la Lumière',
    {'J\'ai écouté le discours du confesseur Paletress, et je vous avoue que ses paroles m\'ont fait réfléchir. Nous combattons aux côtés des croisés, mais nous avons également beaucoup à apprendre d\'eux.|n|nAu large de la côte, au nord, se trouve l\'accostage de Hrothgar, où un village de roharts a été envahi et ses habitants massacrés. Prenez ce livre et récitez les sacrements pour les morts en vous tenant près des cadavres des villageois. Leurs esprits pourront alors s\'échapper des brumes étouffant l\'île, et connaître le repos.', },
    {'Utilisez le Livre de prière du confesseur pour célébrer les derniers sacrements sur 8 Villageois tualiq morts, puis retournez voir Girana Premier-sang dans l\'Enceinte du tournoi d\'Argent.', },
  },
  [14145] = {
    'Ça mange quoi, un yéti, d\'abord ?',
    {'Les croisés ont capturé un yéti qu\'ils appellent Glace-hurlante. Il doit participer aux combats du colisée et on nous a demandé de l\'aide pour son entraînement et son entretien.|n|nLes croisés n\'ont pas eu l\'air d\'apprécier mon idée de le nourrir des membres du Concordat argenté. La bête préfère la viande de requin, donc j\'aimerais que vous voliez jusqu\'à l\'Aube cramoisie, qui est ancrée dans le détroit, vers le nord. Prenez des appâts frais dans l\'un des seaux sur le bateau, et jetez-les à la mer pour attirer les requins.', },
    {'Tylos Coursaurore, dans l\'Enceinte du tournoi d\'Argent, veut que vous lui apportiez 3 morceaux de Chair de requin de la mer Boréale.', },
  },
  [14146] = {
    'Défendez les portes !',
    {'Bon sang, mais que se passe-t-il ?|n|n<Des cris, des hurlements et le chaos du combat envahissent la radio.>|n|n$N ! Revenez ici immédiatement. Retournez près des portes, vite ! Nous sommes attaqués !|n|nAidez-nous à repousser les envahisseurs. Je suis en train d\'armer votre lance-grenades !!', },
    {'Le Capitaine d\'ouvrage Grailletout veut que vous retourniez sans tarder à la Porte d\'Azshara pour massacrer 20 Écumeurs Elfes de la nuit.', },
  },
  [14151] = {
    'Le rubis cardinal',
    {'On raconte que le rubis cardinal est la gemme la plus précieuse de tout le Norfendre. Il brille comme une rose de cristal au soleil.|n|nAvant que je vous enseigne cette recette, je vais vous demander d\'effectuer cinq transmutations de gemmes épiques pour préparer votre esprit. Vous pouvez faire celles que vous préférez, vous pouvez même effectuer la même transmutation plusieurs fois.|n|nRevenez me voir lorsque vous serez vraiment $Gprêt:prête;.', },
    {'Linzy Noirboulon, à Dalaran, veut que vous effectuiez 5 transmutations de gemmes épiques grâce à vos compétences d\'alchimiste. Les transmutations acceptées sont les suivantes : Amétrine, Œil de Zul, Pierre d\'effroi, Ambre du roi et Zircon majestueux.', },
  },
  [14152] = {
    'Secours en mer',
    {'$GChampion:Championne;, le capitaine du Hautevague et son navire ont été envoyés au nord pour mettre un terme aux agissements des kvaldirs à l\'Accostage de Hrothgar. Malheureusement, ils ont été interceptés par un raid de kvaldirs qui venait attaquer le tournoi d\'Argent. Leurs adversaires sont en très nette supériorité numérique, et ils prennent peu à peu le contrôle du navire.|n|nIl faut que vous vous rendiez au nord, jusqu\'au Hautevague, dans les eaux de Hrothgar, entre l\'enceinte du tournoi d\'Argent et l\'Accostage de Hrothgar. Aidez l\'équipage à repousser leur attaque ! Vous devriez voir le vaisseau à l\'est du passage.', },
    {'Partez pour la Mer Boréale et tuez 8 Berserkers kvaldirs et 3 Harponneurs kvaldirs parmi les assaillants du Hautevague.', },
  },
  [14153] = {
    'Membre d\'honneur',
    {'Eh ben, bébé ! Tout le gratin est là ! On se fiche de ce stupide dragon !|n|nLa fête bat son plein autour de la piscine. On dirait qu\'ils s\'amusent tous comme des fous. Tu vas être tellement $Gélégant:élégante; !|n|nPourquoi ne vas-tu pas près de la piscine pour divertir tes invités ? Je te rejoins dans un instant... Il faut juste que je me mette quelque chose sur le dos !', },
    {'Revêtez votre Tenue de fête sensationnelle (Lunettes de soleil cool, Nouvelle tenue branchée et Bling-bling rutilant), puis dirigez-vous vers la fête à la piscine du Quartier général de la SCK et divertissez 10 Bambocheurs de Kezan.', },
  },
  [14154] = {
    'Pas passé loin',
    nil,
    {'Repoussez les worgens au sommet de la prison de Gilnéas pendant 2 minutes.', },
  },
  [14155] = {
    nil,
    {'Le déchiqueteur tient le coup ? Je pense pouvoir réactiver vos réserves d\'énergie d\'urgence, ça rechargera vos batteries si vous êtes $Gtouché:touchée;.|n|nÉcoutez, ces elfes de la nuit tirent leur puissance d\'un ancien de la guerre, enraciné juste à l\'ouest des portes. C\'est un arbre gigantesque. Vous savez ce qu\'il vous reste à faire ! Dégommez-le !|n|nVous êtes $Gfait:faite; pour ça !', },
    nil,
  },
  [14156] = {
    'Un infiltré',
    {'Si le roi veut sauver le seigneur Crowley et sa bande de traître, alors nous obéirons à ses ordres.|n|nC\'est aussi bien... Un de mes hommes avait pour mission d\'infiltrer le groupe de Crowley en prison et j\'aimerais vraiment savoir s\'il a survécu à l\'incident.|n|nContactez Sean Dempsey discrètement... vous ne voulez certainement pas le démasquer devant les hommes de Crowley. Ils pourraient se révéler bien plus dangereux pour Dempsey que les worgens.', },
    {'Trouvez Sean Dempsey sur le toit de la prison de Gilnéas.', },
  },
  [14157] = {
    'D\'anciennes rancœurs',
    {'Le seigneur Darius Crowley a porté bien des noms : rebelle, traître, terroriste.|n|nAvant la guerre civile, je l\'appelais… mon ami.|n|nJe ne lui en ai jamais voulu d\'avoir mené une insurrection contre moi. Ses terres et son peuple étaient séparés de Gilnéas par un mur de dix mètres de haut… mais nous n\'avions pas d\'autre choix.|n|nNéanmoins… Crowley est exactement l\'homme qu\'il nous faut aujourd\'hui.|n|nEntrez dans la prison de Gardepierre et demandez au capitaine Broderick où se cache Crowley. J\'aurais bien envoyé mes hommes, mais les vieilles rancœurs sont tenaces.', },
    {'Parlez au Capitaine Broderick dans la Prison de Gardepierre, à Gilnéas.', },
  },
  [14158] = {
    'Fin de phase 6 (suivi d\'évènement)',
    nil,
    nil,
  },
  [14159] = {
    'L\'arsenal du seigneur séditieux',
    {'L\'arsenal dont parlait Crowley se trouve dans la cave d\'un bâtiment à l\'ouest.|n|nIl est assez pénible de savoir que mes ennemis ont réussi à cacher des armes en ville, mais aujourd\'hui, cet armement sauvera peut-être les habitants de Gilnéas.|n|nTrouvez Josiah Avery et réquisitionnez l\'artillerie rebelle. Nous ferons bon usage de ces armes.', },
    {'Parlez à Josiah Avery dans le Secteur Militaire, à Gilnéas.', },
  },
  [14160] = {
    'Commission de mérite',
    {'Le délicat parchemin liste un grand nombre d\'accomplissements, réalisés par $N, dans la plus pure tradition de la joaillerie.|n|nPrésentez cette commission à Timothy Jones, à Dalaran, pour recevoir votre récompense.', },
    {'Présentez la Commission de mérite à Timothy Jones, à Dalaran.', },
  },
  [14161] = {
    'Un parfum de basilic',
    {'Nous avons déplacé l\'ensemble de cette montagne pour pouvoir exploiter les minerais qui se trouvent en dessous. Mais c\'était sans compter les basilics souterrains qui sont maintenant, euh… terrains. Vous avez l\'air débrouillard ! Allez donc tuer quelques-uns de ces monstres et je piocherai dans notre cagnotte pour vous récompenser.', },
    {'Tuez 10 Basilics grispierre dans la Mine à ciel ouvert du Puy-du-Pied.', },
  },
  [14162] = {
    'Présentez-vous à Horzak',
    {'Grâce à vous, la coupe du bois a repris. Mais j\'ai entendu dire que notre quota de pierre était insuffisant. Si seulement on pouvait déplacer des montagnes et rassembler quelques rochers…|n|nEh bien, ce n\'est pas mon problème, mais ça pourrait peut-être devenir le vôtre. Présentez-vous à Horzak Zigrignote un peu plus loin, à la station d\'Orgrimmar du fusorail. Voyez si vous pouvez l\'aider à réorganiser ses opérations. Vous n\'avez qu\'à suivre la route au nord-est. Vous le trouverez dans la tour du fusorail.', },
    {'Trouvez Horzak Zigrignote à la Station d\'Orgrimmar du fusorail, en Azshara.', },
  },
  [14163] = {
    'Appel aux armes : île des Conquérants',
    {'La victoire est de plus en plus proche, mais il apparaît de plus en plus évident que nos armées devront affronter la Horde avant de s\'attaquer au roi-liche.|n|nLa garde d\'élite connue sous le nom de kor\'krons a été déployée pour nous empêcher d\'avancer sur l\'île des Conquérants. L\'île est d\'une importance stratégique vitale, $N. Il faut que nous gagnions la bataille !', },
    {'Gagnez sur l\'Île des Conquérants, puis présentez-vous à un Général de brigade de l\'Alliance, à Joug-d\'hiver, à Dalaran, à Shattrath ou dans l\'une des capitales de l\'Alliance.', },
  },
  [14164] = {
    'Appel aux armes : île des Conquérants',
    {'La victoire au Norfendre sera bientôt nôtre… Mais il nous faut absolument une tête de pont dans la Couronne des glaces, pour transporter et ravitailler nos troupes.|n|nL\'île des Conquérants est un site idéal : facilement défendable et riche en ressources. L\'Alliance est arrivée à la même conclusion que nous, et a envoyé la Septième légion pour en arracher le contrôle à nos forces.|n|nAllez combattre, $N, et assurez-vous que la Horde l\'emporte ! Quel qu\'en soit le prix !', },
    {'Gagnez sur l\'Île des Conquérants, puis présentez-vous à un Porteguerre de la Horde, à Joug-d\'hiver, à Dalaran, à Shattrath ou dans l\'une des capitales de la Horde.', },
  },
  [14165] = {
    'Froid comme la pierre',
    {'Mes ouvriers n\'arrêtent pas de se plaindre. Quand ce n\'est pas le travail qui est éreintant, les heures qui semblent interminables, ou la paie qui est mauvaise, c\'est la faute des basilics qui les changent en pierre. Il y a toujours quelque chose !|n|nMais je pourrais peut-être me faire de l\'argent avec ces ouvriers pétrifiés. Et si ces gars étaient faits d\'une pierre de très bonne qualité ? Mes geignards d\'employés me rapporteraient peut-être plus en tant que matériaux de construction de luxe qu\'en tant que main d\'œuvre ! Allez chercher un mineur pétrifié et ramenez-le-moi.', },
    {'Allez chercher un Mineur du Puy-du-Pied pétrifié dans la Mine à ciel ouvert du Puy-du-Pied, et ramenez-le à Horzak Zigrignote, à la Station d\'Orgrimmar du fusorail.', },
  },
  [14166] = {
    'Les morts reconnaissants',
    {'C\'est bien agréable de pouvoir rendre visite à sa famille et à ses amis. Mais je crois que j\'ai peut-être un peu exagéré… J\'ai déjà mangé tout ce qu\'ils avaient préparé pour moi ! |n|nPourrais-je vous demander un peu plus de ce délicieux pain des morts ? Je vous en serais très reconnaissant…|n|nJe crois que Chapman, là-bas, en vend la recette.', },
    {'Récupérez un peu de Pain des morts, et donnez-le à l\'Esprit de Dalaran joyeux dans le cimetière de Dalaran.|n|nUtilisez un Chrysanthème orange pour voir l\'esprit, qui sinon restera invisible.', },
  },
  [14167] = {
    'Les morts reconnaissants',
