  [28775] = {
    'La figurine de serpent cassée',
    nil,
    {'Réparez la figurine cassée en utilisant votre compétence et les matériaux appropriés.', },
  },
  [28776] = {
    'La figurine de terrestre cassée',
    nil,
    {'Réparez la figurine cassée en utilisant votre compétence et les matériaux appropriés.', },
  },
  [28777] = {
    'La figurine de chouette cassée',
    nil,
    {'Réparez la figurine cassée en utilisant votre compétence et les matériaux appropriés.', },
  },
  [28778] = {
    'La figurine de sanglier cassée',
    nil,
    {'Réparez la figurine cassée en utilisant votre compétence et les matériaux appropriés.', },
  },
  [28779] = {
    'Bien loin de chez soi',
    {'Je pense que j\'ai réussi à échapper à mes ravisseurs parce que, franchement, il n\'y a nulle part où aller.|n|nSur ces plateformes, ils finiront par me trouver, tôt ou tard. À moins que…|n|nOn dit que le cœur d\'un noble élémentaire donne à celui qui le tient les caractéristiques de son élément. Dans le cas de l\'air, ça pourrait m\'aider à descendre.|n|nSi vous m\'amenez le cœur du grand vizir Ertan, je pourrais m\'en servir pour me poser en douceur sur la côte d\'Uldum.', },
    {'Procurez-vous le Cœur du grand vizir Erthan.', },
  },
  [28780] = {
    'Rejoignez la bataille !',
    nil,
    {'Présentez-vous au Sergent Willem derrière l\'Abbaye de Comté-du-Nord, dans la Forêt d\'Elwynn.', },
  },
  [28781] = {
    'Des objectifs fortuits',
    {'Nous faisions partie d\'une opération clandestine créée par le prince Nadun de Ramkahen. Nous avons perdu une grande partie de notre unité au cours d\'une embuscade et maintenant, nous sommes dans l\'impossibilité de terminer notre mission.|n|nSi ça vous intéresse, je peux m\'arranger pour vous obtenir une belle récompense.|n|nNous avions l\'ordre de détruire toute cible à portée et nous permettant de déstabiliser l\'infrastructure militaire de l\'ennemi.|n|nNous avons repéré le général Husam et deux de ses capitaines un peu plus loin. Tuez-les pour nous, vous feriez une grande faveur à Ramkahen.', },
    {'Tuez le général Husam et 2 Capitaines liés par le serment.', },
  },
  [28782] = {
    'Un oiseau de légende',
    {'La légende locale parle d\'une puissante chouette qui plane autour des sommets montagneux, telle une faucheuse ailée. Au début, les gens l\'ont appelée Aile de mort.|n|nRapidement, ils apprirent que ce nom était déjà pris. Ils ont donc trouvé un sobriquet évoquant la même idée d\'horreur et de terreur :|n|nBelzhibou.|n|nBelzhibou se trouve au sommet de la montagne au sud-ouest de notre fosse de fumage. Faites taire ce rapace de malheur… pour que nous puissions le manger !', },
    {'Éliminez Belzhibou.', },
  },
  [28783] = {
    'La source de leur puissance',
    {'Nous avons réussi à faire une reconnaissance poussée avant que notre équipe ne tombe dans une embuscade.|n|nNous avons découvert que c\'est l\'envoyé d\'Aile de mort, Siamat, qui fournit aux Neferset leur toute nouvelle puissance.|n|nIls affirment qu\'il leur a rendu leur grandeur d\'autrefois, mais il s\'est passé autre chose. Leur âme même a été corrompue.|n|nÉtant l\'un des quatre vents, Siamat est incroyablement puissant. Mais ce procédé a énormément puisé dans cette puissance.|n|nFrappez maintenant, tant qu\'il est encore possible pour vous de le tuer et de mettre un terme à cette folie.', },
    {'Tuez Siamat.', },
  },
  [28784] = {
