  [28790] = {
    'Un appel personnel',
    {'<Une sensation inhabituelle vous envahit, s\'imposant à votre esprit par des pensées et des images.>|n|nÉcoutez mes paroles, $N.|n|nNotre monde est plongé dans une crise terrible.|n|nJe fais appel à vous et vous implore de nous apporter votre aide en cette heure désespérée.|n|nJe m\'appelle Krogar.|n|nRetrouvez-moi immédiatement, et votre destinée vous sera révélée.|n|nJe vous attends au nord de la Herse, à Orgrimmar.', },
    {'Le Long-voyant Krogar veut vous rencontrer, à Orgrimmar.', },
  },
  [28791] = {
    'Ils ont envoyé des assassins',
    {'Avez-vous déjà vu un gobelin, $N ? Ce sont d\'affreux petits monstres à la peau verte qui n\'aiment que deux choses : l\'or et eux-mêmes.|n|nLes orcs rochenoires ont recruté des assassins gobelins pour tuer nos soldats. Si on regarde vers le champ là-bas, au nord, on arrive à peine à distinguer leurs silhouettes, en train de se faufiler dans l\'herbe.|n|nIl faut que vous alliez là-bas et que vous tuiez tous les gobelins que vous croiserez. On doit leur faire comprendre que personne ne touche à l\'Alliance !', },
    {'Tuez 8 Assassins gobelins.', },
  },
  [28792] = {
    'Ils ont envoyé des assassins',
    {'Avez-vous déjà vu un gobelin, $N ? Ce sont d\'affreux petits monstres à la peau verte qui n\'aiment que deux choses : l\'or et eux-mêmes.|n|nLes orcs rochenoires ont recruté des assassins gobelins pour tuer nos soldats. Si on regarde vers le champ là-bas, au nord, on arrive à peine à distinguer leurs silhouettes, en train de se faufiler dans l\'herbe.|n|nIl faut que vous alliez là-bas et que vous tuiez tous les gobelins que vous croiserez. On doit leur faire comprendre que personne ne touche à l\'Alliance !', },
