  [28934] = {
    'Détrôner la Royale',
    {'Ce grand livre est plein de noms de lieux, et j\'ai besoin de vous pour enquêter et agir. Il est temps de mettre le holà à toute cette histoire.|n|nTenez, prenez cette mention : on dirait que c\'est à Uldum, juste à l\'est de la tombe de Khartut, près de l\'entrée venant de Tanaris. Allez-y et défoncez-les.|n|nEt si vous voyez quelque chose d\'assez gros et d\'assez dangereux pour mériter d\'être éparpillé façon puzzle, lancez-lui cette bombe.', },
    {'Tuez 5 Laquais de La Royale et utilisez la Bombe en khorium de Tordboulon pour endommager un Chariot de produits chimiques à l\'est de la Tombe de Khartut, dans Uldum, puis retournez voir l\'Inspecteur Latenaille Tordboulon à Hurlevent.', },
  },
  [28935] = {
    'Détrôner la Royale',
    {'Ce grand livre est plein de noms de lieux, et j\'ai besoin de vous pour enquêter et agir. Il est temps de mettre le holà à toute cette histoire.|n|nTenez, prenez cette mention : on dirait que c\'est à Uldum, juste à l\'est de la tombe de Khartut, près de l\'entrée venant de Tanaris. Allez-y et défoncez-les.|n|nEt si vous voyez quelque chose d\'assez gros et d\'assez dangereux pour mériter d\'être éparpillé façon puzzle, lancez-lui cette bombe.', },
    {'Tuez 5 Laquais de La Royale et utilisez la Bombe en khorium de Tordboulon pour endommager un Chariot de produits chimiques à l\'est de la Tombe de Khartut, dans Uldum, puis retournez voir l\'Inspecteur Lapince Tordboulon à Orgrimmar.', },
  },
  [28936] = {
    'Le dilemme de la diva',
    nil,
    {'Tuez 6 Nagas.', },
  },
  [28937] = {
    nil,
    {'Des monstres ! C\'étaient des monstres, que je vous dis !|n|nNotre navire a jeté l\'ancre juste au sud de Stromgarde, et la côte ici est infestée d\'étranges créatures.|n|nJ\'ai juste aperçu leur sale tronche et entendu des gargouillements bizarres, et je suis parti sans demander mon reste. Vous devriez vraiment aller aider mes camarades de bord, $N!', },
    {'Parlez à Dame Gurga à la Crique de Faldir.', },
  },
  [28938] = {
    'Sauvez les enfants',
    nil,
    {'Sauvez 6 Bébés murlocs.', },
  },
  [28939] = {
